import { element, button } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import { describeStoryWeekday } from '../../time/story-time.js';
import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';

const WEEKDAY_HEADERS = ['日', '一', '二', '三', '四', '五', '六'] as const;

const pad2 = (value: number) => String(value).padStart(2, '0');
/** 组装节日状态键：YYYY-MM-DD（month 为 0 起）。 */
const dateKey = (year: number, month: number, day: number) => `${year}-${pad2(month + 1)}-${pad2(day)}`;

/** 日历应用：以剧情时间为“今天”的月历视图，可标记节日/事件。 */
export function createCalendarApp(): PhoneAppDefinition {
  /** 相对剧情当前月份的偏移（翻月用）。 */
  let monthOffset = 0;
  /** 选中的日期键；null 表示跟随剧情今天。 */
  let selectedKey: string | null = null;

  const render = (context: PhoneViewContext): HTMLElement => {
    const page = element('div', { className: 'phone-page phone-calendar' });
    const storyNow = new Date(context.state.worldClock.now);
    const viewBase = new Date(storyNow.getFullYear(), storyNow.getMonth() + monthOffset, 1);
    const todayKey = dateKey(storyNow.getFullYear(), storyNow.getMonth(), storyNow.getDate());
    const festivals = context.state.calendarFestivals ?? {};
    const activeKey = selectedKey ?? todayKey;

    const header = element('div', { className: 'phone-calendar-header' });
    const prev = button('', 'phone-icon-button phone-calendar-nav', () => {
      monthOffset -= 1;
      context.navigate('calendar');
    });
    prev.append(renderPhoneIcon('back'));
    prev.setAttribute('aria-label', '上一个月');
    const next = button('', 'phone-icon-button phone-calendar-nav phone-calendar-nav-next', () => {
      monthOffset += 1;
      context.navigate('calendar');
    });
    next.append(renderPhoneIcon('chevron'));
    next.setAttribute('aria-label', '下一个月');
    const title = element('strong', {
      className: 'phone-calendar-title',
      text: `${viewBase.getFullYear()}年${viewBase.getMonth() + 1}月`,
    });
    header.append(prev, title, next);
    page.append(header);

    if (monthOffset !== 0 || selectedKey) {
      const backToday = button('回到今天', 'phone-button phone-button-secondary phone-button-compact phone-calendar-today-btn', () => {
        monthOffset = 0;
        selectedKey = null;
        context.navigate('calendar');
      });
      page.append(backToday);
    }

    const grid = element('div', { className: 'phone-calendar-grid' });
    for (const label of WEEKDAY_HEADERS) {
      grid.append(element('span', { className: 'phone-calendar-weekday', text: label }));
    }

    const firstWeekday = viewBase.getDay();
    const daysInMonth = new Date(viewBase.getFullYear(), viewBase.getMonth() + 1, 0).getDate();
    for (let blank = 0; blank < firstWeekday; blank += 1) {
      grid.append(element('span', { className: 'phone-calendar-day is-empty' }));
    }
    for (let day = 1; day <= daysInMonth; day += 1) {
      const key = dateKey(viewBase.getFullYear(), viewBase.getMonth(), day);
      // 点击日期切换选中：底部节日区随之切换到该日期。
      const cell = button(String(day), 'phone-calendar-day', () => {
        selectedKey = key;
        context.navigate('calendar');
      });
      if (key === todayKey) {
        cell.classList.add('is-today');
        cell.title = '剧情今天';
      }
      if (key === activeKey) cell.classList.add('is-selected');
      const festival = festivals[key];
      if (festival) {
        cell.classList.add('has-festival');
        cell.append(element('span', { className: 'phone-calendar-day-dot' }));
        cell.title = cell.title ? `${cell.title} · ${festival.name}` : festival.name;
      }
      cell.setAttribute('aria-label', `${viewBase.getMonth() + 1}月${day}日${festival ? `（${festival.name}）` : ''}`);
      grid.append(cell);
    }
    page.append(grid);

    page.append(renderFestivalCard(context, activeKey, activeKey === todayKey));

    const footer = element('div', { className: 'phone-calendar-footer' });
    footer.append(
      element('strong', {
        text: `${storyNow.getFullYear()}年${storyNow.getMonth() + 1}月${storyNow.getDate()}日 ${describeStoryWeekday(context.state.worldClock.now, context.state.scopeId)}`,
      }),
      element('span', { text: `剧情时间 ${pad2(storyNow.getHours())}:${pad2(storyNow.getMinutes())} · 在首页双击时钟可调整` }),
    );
    page.append(footer);
    return page;
  };

  return {
    id: 'calendar',
    label: '日历',
    icon: '📅',
    navigation: [],
    render,
  };
}

/** 选中日期的触发事件/节日卡片：查看、标记、编辑、删除。 */
function renderFestivalCard(context: PhoneViewContext, key: string, isToday: boolean): HTMLElement {
  const festival = (context.state.calendarFestivals ?? {})[key];
  const [, month, day] = key.split('-').map(Number);
  const card = element('section', { className: 'phone-calendar-festival' });

  const head = element('div', { className: 'phone-calendar-festival-head' });
  head.append(element('strong', {
    text: `${month}月${day}日${isToday ? '（今天）' : ''} · 触发事件/节日`,
  }));
  const actions = element('div', { className: 'phone-calendar-festival-actions' });

  const openEditor = async () => {
    const existing = (context.state.calendarFestivals ?? {})[key];
    const result = await context.showModal(existing ? '编辑节日/事件' : '标记节日/事件', [
      {
        name: 'name',
        label: '节日/事件名称',
        required: true,
        value: existing?.name ?? '',
        placeholder: '例如：中元节 / 学园祭 / 结婚纪念日',
      },
      {
        name: 'description',
        label: '大致内容（习俗、活动、对角色的意义等）',
        type: 'textarea',
        value: existing?.description ?? '',
        placeholder: '剧情到达这一天时，角色们会知道这些内容',
      },
    ]);
    if (!result?.name?.trim()) return;
    try {
      await context.commands.upsertCalendarFestival(key, result.name, result.description ?? '');
      context.showNotice('已保存节日/事件', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
  };

  actions.append(button(festival ? '编辑' : '标记节日/事件', 'phone-button phone-button-secondary phone-button-compact', () => {
    void openEditor();
  }));
  if (festival) {
    actions.append(button('删除', 'phone-button phone-button-danger-ghost phone-button-compact', async () => {
      if (!window.confirm(`确定删除「${festival.name}」吗？`)) return;
      try {
        await context.commands.removeCalendarFestival(key);
        context.showNotice('已删除该节日/事件', 'info');
      } catch (error) {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      }
    }));
  }
  head.append(actions);
  card.append(head);

  if (festival) {
    card.append(element('strong', { className: 'phone-calendar-festival-name', text: festival.name }));
    if (festival.description) {
      card.append(element('p', { className: 'phone-calendar-festival-desc', text: festival.description }));
    }
  } else {
    card.append(element('p', {
      className: 'phone-calendar-festival-empty',
      text: '这一天还没有标记节日或事件。',
    }));
  }
  card.append(element('span', {
    className: 'phone-calendar-festival-note',
    text: '剧情时间到达当天时，角色们会知道这个节日/事件及其内容。',
  }));
  return card;
}
