interface FencedBlock {
  readonly language: string;
  readonly body: string;
  readonly start: number;
  readonly end: number;
}

/** 只取原始回复中完整的 SQL 围栏；正文标签外的 SQL 和字符串字面量均保持原样。 */
export function extractStorySqlBlocks(raw: string): readonly string[] {
  const text = raw.replace(/\r\n?/g, '\n');
  const blocks: FencedBlock[] = [];
  let open: { marker: string; language: string; start: number; bodyStart: number } | null = null;
  let offset = 0;
  for (const line of text.split('\n')) {
    const fence = /^[ \t]*(`{3,}|~{3,})(.*)$/.exec(line);
    if (!open && fence) {
      open = { marker: fence[1]!, language: fence[2]!.trim().toLowerCase(), start: offset, bodyStart: offset + line.length + 1 };
    } else if (open && fence && !fence[2]!.trim()
      && fence[1]![0] === open.marker[0] && fence[1]!.length >= open.marker.length) {
      blocks.push({ ...open, body: text.slice(open.bodyStart, offset), end: offset + line.length });
      open = null;
    }
    offset += line.length + 1;
  }

  // 隐藏区只在围栏外识别，避免把 SQL 字符串中的 <think> 等普通数据当作标签。
  let outside = '';
  let cursor = 0;
  for (const block of blocks) {
    outside += text.slice(cursor, block.start) + ' '.repeat(block.end - block.start);
    cursor = block.end;
  }
  outside += text.slice(cursor);
  const hiddenPatterns = [
    /<(think|thinking|analysis|reasoning|reflection|scratchpad|chain[-_ ]?of[-_ ]?thought|story_context|image[_ -]?prompt)\b[^>]*>[\s\S]*?(?:<\/\1\s*>|$)/gi,
    /<details\b[^>]*class\s*=\s*["'][^"']*(?:narrative-phone-log|reasoning|thinking|thought|analysis)[^"']*["'][^>]*>[\s\S]*?(?:<\/details\s*>|$)/gi,
    /<details\b[^>]*>\s*<summary\b[^>]*>[^\n]{0,200}(?:思考|推理|reasoning|thought|analysis)[^\n]{0,200}<\/summary>[\s\S]*?(?:<\/details\s*>|$)/gi,
    /<!--[\s\S]*?(?:-->|$)/g,
  ];
  const hidden = hiddenPatterns.flatMap((pattern) => [...outside.matchAll(pattern)]
    .map((match) => ({ start: match.index, end: match.index + match[0].length })));
  return blocks
    .filter((block) => /^(?:sql|sqlite|sqlite3)$/.test(block.language)
      && !hidden.some((range) => block.start >= range.start && block.start < range.end))
    .map((block) => block.body);
}

/** 卡内协议使用显示表名；只把写入目标的精确名称映射到当前聊天已注册的物理表。 */
export function resolveStorySqlTableName(
  sql: string,
  sheets: readonly { readonly name: string; readonly physicalName: string }[],
): string {
  const target = /^(\s*(?:INSERT\s+(?:OR\s+\w+\s+)?INTO|UPDATE(?:\s+OR\s+\w+)?|DELETE\s+FROM)\s+)("(?:[^"]|"")+"|`(?:[^`]|``)+`|\[[^\]]+\]|[^\s().;]+)(?=\s|\(|$)/i.exec(sql);
  if (!target) return sql;
  const identifier = target[2]!;
  const unquoted = identifier.startsWith('"') ? identifier.slice(1, -1).replace(/""/g, '"')
    : identifier.startsWith('`') ? identifier.slice(1, -1).replace(/``/g, '`')
      : identifier.startsWith('[') ? identifier.slice(1, -1) : identifier;
  const fold = (name: string): string => name.replace(/[A-Z]/g, (char) => char.toLowerCase());
  const name = fold(unquoted);
  const physical = sheets.find((sheet) => fold(sheet.physicalName) === name);
  const matches = physical ? [physical] : sheets.filter((sheet) => fold(sheet.name) === name);
  // 未注册或重名的目标留给 SQL 闸门报告，绝不按名称前缀猜表。
  if (matches.length !== 1) return sql;
  return target[1] + matches[0]!.physicalName + sql.slice(target[0].length);
}

export interface StorySqlBatch {
  readonly scopeId: string;
  readonly presetId?: string;
  readonly floor: number;
  readonly blocks: readonly string[];
}

/** 消息收到、生成结束与楼层回撤共用一条队列，避免重复 INSERT 或回撤后又落下旧写入。 */
export class StorySqlExecutionQueue {
  #chain: Promise<unknown> = Promise.resolve();
  readonly #completed = new Map<string, Map<string, Map<number, string>>>();

  has(scopeId: string, floor: number, presetId = ''): boolean {
    return this.#completed.get(scopeId)?.get(presetId)?.has(floor) ?? false;
  }

  consume(
    batch: StorySqlBatch,
    callbacks: {
      readonly isCurrent: () => boolean;
      readonly apply: () => Promise<boolean>;
      readonly revert: () => Promise<void>;
    },
  ): Promise<boolean> {
    return this.#serialize(async () => {
      if (batch.blocks.length === 0 || !callbacks.isCurrent()) return false;
      const signature = JSON.stringify(batch.blocks);
      const presetId = batch.presetId ?? '';
      const previous = this.#completed.get(batch.scopeId)?.get(presetId)?.get(batch.floor);
      if (previous === signature) return true;
      if (previous !== undefined) {
        // 续写可能在同一层追加 SQL：先回撤该层，再执行完整的新版本。
        await callbacks.revert();
        this.#forgetFromFloor(batch.scopeId, batch.floor);
        if (!callbacks.isCurrent()) return false;
      }
      if (!await callbacks.apply()) return false;
      const presets = this.#completed.get(batch.scopeId) ?? new Map<string, Map<number, string>>();
      const floors = presets.get(presetId) ?? new Map<number, string>();
      floors.set(batch.floor, signature);
      presets.set(presetId, floors);
      this.#completed.set(batch.scopeId, presets);
      return true;
    });
  }

  invalidateFromFloor(scopeId: string, floor: number, revert: () => Promise<void>): Promise<void> {
    return this.#serialize(async () => {
      await revert();
      this.#forgetFromFloor(scopeId, floor);
    });
  }

  #forgetFromFloor(scopeId: string, fromFloor: number): void {
    const presets = this.#completed.get(scopeId);
    if (!presets) return;
    // 楼层回撤覆盖本聊天全部预设的表，因此同时清理它们的去重标记。
    for (const [presetId, floors] of presets) {
      for (const floor of floors.keys()) if (floor >= fromFloor) floors.delete(floor);
      if (floors.size === 0) presets.delete(presetId);
    }
    if (presets.size === 0) this.#completed.delete(scopeId);
  }

  #serialize<T>(operation: () => Promise<T>): Promise<T> {
    const pending = this.#chain.then(operation, operation);
    this.#chain = pending.catch(() => undefined);
    return pending;
  }
}
