/**
 * 记忆向量的本地缓存（IndexedDB）。
 * 键为「作用域|向量模型|记忆条目 id」，换模型后旧向量自动失效（键不同）。
 * 向量不进入手机状态，避免撑大 JSON 序列化与数据库镜像。
 */

const DB_NAME = 'narrative_phone_memory_vectors';
const DB_VERSION = 1;
const STORE_NAME = 'vectors';
const MAX_ENTRIES = 4_000;

interface StoredVectorRecord {
  readonly key: string;
  readonly scopeId: string;
  readonly vector: readonly number[];
  readonly savedAt: number;
}

let dbPromise: Promise<IDBDatabase> | null = null;

function openDatabase(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'key' });
        store.createIndex('savedAt', 'savedAt');
        store.createIndex('scopeId', 'scopeId');
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => {
      dbPromise = null;
      reject(request.error ?? new Error('无法打开记忆向量缓存。'));
    };
  });
  return dbPromise;
}

function requestAsPromise<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('记忆向量缓存操作失败。'));
  });
}

export function vectorCacheKey(scopeId: string, model: string, itemId: string): string {
  return `${scopeId}|${model}|${itemId}`;
}

/** 批量读取缓存向量；返回 key → vector（未命中的键不在结果里）。 */
export async function loadVectors(keys: readonly string[]): Promise<ReadonlyMap<string, readonly number[]>> {
  const found = new Map<string, readonly number[]>();
  if (keys.length === 0) return found;
  try {
    const db = await openDatabase();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const store = tx.objectStore(STORE_NAME);
    await Promise.all(keys.map(async (key) => {
      const record = await requestAsPromise<StoredVectorRecord | undefined>(
        store.get(key) as IDBRequest<StoredVectorRecord | undefined>,
      );
      if (record?.vector?.length) found.set(key, record.vector);
    }));
  } catch {
    // 缓存不可用时按全部未命中处理。
  }
  return found;
}

/** 批量写入向量缓存。 */
export async function saveVectors(
  scopeId: string,
  entries: readonly { readonly key: string; readonly vector: readonly number[] }[],
): Promise<void> {
  if (entries.length === 0) return;
  try {
    const db = await openDatabase();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const store = tx.objectStore(STORE_NAME);
    for (const entry of entries) {
      store.put({ key: entry.key, scopeId, vector: entry.vector, savedAt: Date.now() } satisfies StoredVectorRecord);
    }
    await new Promise<void>((resolve, reject) => {
      tx.oncomplete = () => resolve();
      tx.onerror = () => reject(tx.error ?? new Error('写入记忆向量缓存失败。'));
    });
    void pruneOldEntries();
  } catch {
    // 写缓存失败时下次重新向量化即可。
  }
}

/** 清空某个作用域的全部向量（重建索引用）。 */
export async function clearScopeVectors(scopeId: string): Promise<void> {
  try {
    const db = await openDatabase();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const index = tx.objectStore(STORE_NAME).index('scopeId');
    await new Promise<void>((resolve) => {
      const cursorRequest = index.openCursor(IDBKeyRange.only(scopeId));
      cursorRequest.onsuccess = () => {
        const cursor = cursorRequest.result;
        if (!cursor) {
          resolve();
          return;
        }
        cursor.delete();
        cursor.continue();
      };
      cursorRequest.onerror = () => resolve();
    });
  } catch {
    // 清理失败可忽略。
  }
}

async function pruneOldEntries(): Promise<void> {
  try {
    const db = await openDatabase();
    const countTx = db.transaction(STORE_NAME, 'readonly');
    const total = await requestAsPromise(countTx.objectStore(STORE_NAME).count());
    if (total <= MAX_ENTRIES) return;
    const removeCount = total - MAX_ENTRIES;
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const index = tx.objectStore(STORE_NAME).index('savedAt');
    let removed = 0;
    await new Promise<void>((resolve) => {
      const cursorRequest = index.openCursor();
      cursorRequest.onsuccess = () => {
        const cursor = cursorRequest.result;
        if (!cursor || removed >= removeCount) {
          resolve();
          return;
        }
        cursor.delete();
        removed += 1;
        cursor.continue();
      };
      cursorRequest.onerror = () => resolve();
    });
  } catch {
    // 清理失败可忽略。
  }
}
