/**
 * 生成图片仅存储在浏览器 IndexedDB 中，并按聊天作用域与提示词隔离。
 * 旧版未分作用域的 IndexedDB 记录只用于兼容读取。
 */

const DB_NAME = 'narrative_phone_images';
const DB_VERSION = 3;
const ALBUM_STORE = 'album';
const STORE_NAME = 'scoped-images';
const LEGACY_STORE_NAME = 'images';
const MAX_ENTRIES = 300;

interface StoredImageRecord {
  readonly key: string;
  readonly scopeId: string;
  readonly prompt: string;
  readonly blob: Blob;
  readonly savedAt: number;
}

interface LegacyStoredImageRecord {
  readonly prompt: string;
  readonly blob?: Blob;
  readonly savedAt: number;
}

let dbPromise: Promise<IDBDatabase> | null = null;

function openDatabase(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(STORE_NAME)) {
        const store = db.createObjectStore(STORE_NAME, { keyPath: 'key' });
        store.createIndex('savedAt', 'savedAt');
        store.createIndex('scopeId', 'scopeId');
      }
      if (!db.objectStoreNames.contains(ALBUM_STORE)) {
        const album = db.createObjectStore(ALBUM_STORE, { keyPath: 'key' });
        album.createIndex('scopeId', 'scopeId');
        const old = request.transaction!.objectStore(STORE_NAME).openCursor();
        old.onsuccess = () => {
          const cursor = old.result;
          if (!cursor) return;
          album.put({ ...cursor.value, key: `legacy:${cursor.key}` });
          cursor.continue();
        };
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => {
      dbPromise = null;
      reject(request.error ?? new Error('无法打开图片存储数据库。'));
    };
  });
  return dbPromise;
}

function requestAsPromise<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('图片存储操作失败。'));
  });
}

function imageKey(scopeId: string, prompt: string): string {
  return `${scopeId}|${prompt}`;
}

/** 保存生成结果到浏览器 IndexedDB，并返回当前页面可展示的本地对象地址。 */
export async function persistGeneratedImage(scopeId: string, prompt: string, src: string): Promise<string> {
  const blob = await readImageBlob(src);
  const record: StoredImageRecord = {
    key: imageKey(scopeId, prompt),
    scopeId,
    prompt,
    blob,
    savedAt: Date.now(),
  };
  const db = await openDatabase();
  const tx = db.transaction([STORE_NAME, ALBUM_STORE], 'readwrite');
  tx.objectStore(STORE_NAME).put(record);
  tx.objectStore(ALBUM_STORE).add({ ...record, key: crypto.randomUUID() });
  await transactionSettled(tx);
  void pruneOldEntries();
  return URL.createObjectURL(blob);
}

/** 优先读取当前聊天作用域的本地图片，再兼容旧版未分作用域缓存。 */
export async function loadGeneratedImage(scopeId: string, prompt: string): Promise<string | null> {
  try {
    const db = await openDatabase();
    const tx = db.transaction(STORE_NAME, 'readonly');
    const record = await requestAsPromise<StoredImageRecord | undefined>(
      tx.objectStore(STORE_NAME).get(imageKey(scopeId, prompt)) as IDBRequest<StoredImageRecord | undefined>,
    );
    if (record) return imageSource(record);
  } catch {
    // 继续尝试旧版本地缓存。
  }

  return loadLegacyImage(prompt);
}

export async function listAlbumImages(scopeId: string): Promise<readonly StoredImageRecord[]> {
  const db = await openDatabase();
  const tx = db.transaction(ALBUM_STORE, 'readonly');
  const records = await requestAsPromise<StoredImageRecord[]>(tx.objectStore(ALBUM_STORE).index('scopeId').getAll(scopeId));
  return records.sort((a, b) => b.savedAt - a.savedAt);
}

export async function deleteAlbumImage(scopeId: string, key: string): Promise<void> {
  const db = await openDatabase();
  const tx = db.transaction(ALBUM_STORE, 'readwrite');
  const settled = transactionSettled(tx);
  const request = tx.objectStore(ALBUM_STORE).get(key);
  request.onsuccess = () => {
    if (request.result?.scopeId === scopeId) tx.objectStore(ALBUM_STORE).delete(key);
  };
  await settled;
}

/** 清空某个作用域的全部生成图片缓存（数据清理用）。 */
export async function clearScopeImages(scopeId: string): Promise<void> {
  const album = await listAlbumImages(scopeId);
  await Promise.all(album.map((image) => deleteAlbumImage(scopeId, image.key)));
  try {
    const db = await openDatabase();
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const index = tx.objectStore(STORE_NAME).index('scopeId');
    await new Promise<void>((resolve) => {
      const cursorRequest = index.openCursor(IDBKeyRange.only(scopeId));
      cursorRequest.onsuccess = () => {
        const cursor = cursorRequest.result;
        if (!cursor) {
          resolve();
          return;
        }
        cursor.delete();
        cursor.continue();
      };
      cursorRequest.onerror = () => resolve();
    });
  } catch {
    // 缓存清理失败不影响事实数据。
  }
}

async function readImageBlob(src: string): Promise<Blob> {
  const response = await fetch(src, /^https?:\/\//i.test(src) ? { mode: 'cors' } : undefined);
  if (!response.ok) throw new Error(`读取生成图片失败 (HTTP ${response.status})`);
  const blob = await response.blob();
  if (blob.size === 0) throw new Error('生成图片内容为空。');
  if (blob.type && !blob.type.startsWith('image/')) throw new Error(`生成结果不是图片（${blob.type}）。`);
  return blob;
}

async function loadLegacyImage(prompt: string): Promise<string | null> {
  try {
    const db = await openDatabase();
    if (!db.objectStoreNames.contains(LEGACY_STORE_NAME)) return null;
    const tx = db.transaction(LEGACY_STORE_NAME, 'readonly');
    const record = await requestAsPromise<LegacyStoredImageRecord | undefined>(
      tx.objectStore(LEGACY_STORE_NAME).get(prompt) as IDBRequest<LegacyStoredImageRecord | undefined>,
    );
    return record ? imageSource(record) : null;
  } catch {
    return null;
  }
}

function imageSource(record: { readonly blob?: Blob }): string | null {
  return record.blob ? URL.createObjectURL(record.blob) : null;
}

function transactionSettled(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error('图片存储事务失败。'));
    transaction.onabort = () => reject(transaction.error ?? new Error('图片存储事务已取消。'));
  });
}

async function pruneOldEntries(): Promise<void> {
  try {
    const db = await openDatabase();
    const countTx = db.transaction(STORE_NAME, 'readonly');
    const total = await requestAsPromise(countTx.objectStore(STORE_NAME).count());
    if (total <= MAX_ENTRIES) return;
    const removeCount = total - MAX_ENTRIES;
    const tx = db.transaction(STORE_NAME, 'readwrite');
    const index = tx.objectStore(STORE_NAME).index('savedAt');
    let removed = 0;
    await new Promise<void>((resolve) => {
      const cursorRequest = index.openCursor();
      cursorRequest.onsuccess = () => {
        const cursor = cursorRequest.result;
        if (!cursor || removed >= removeCount) {
          resolve();
          return;
        }
        cursor.delete();
        removed += 1;
        cursor.continue();
      };
      cursorRequest.onerror = () => resolve();
    });
  } catch {
    // 缓存清理失败不影响事实数据。
  }
}
