export const DEFAULT_NOTICE_DURATION_MS = 5_000;

export interface NoticeTimerHost<Handle> {
  readonly setTimeout: (callback: () => void, delay: number) => Handle;
  readonly clearTimeout: (handle: Handle) => void;
}

export interface NoticeTimer {
  readonly clear: () => void;
  readonly schedule: (callback: () => void, durationMs?: number) => void;
}

export function normalizeNoticeDuration(
  durationMs: number | undefined,
  fallback = DEFAULT_NOTICE_DURATION_MS,
): number {
  const safeFallback = Number.isFinite(fallback) && fallback > 0 ? fallback : DEFAULT_NOTICE_DURATION_MS;
  return typeof durationMs === 'number' && Number.isFinite(durationMs) && durationMs > 0
    ? durationMs
    : safeFallback;
}

export interface NoticeElement {
  textContent: string | null;
  readonly dataset: DOMStringMap;
  readonly classList: Pick<DOMTokenList, 'add' | 'remove'>;
}

export function showAutoDismissNotice(
  element: NoticeElement,
  timer: NoticeTimer,
  message: string,
  kind: string,
  durationMs?: number,
): void {
  element.textContent = message;
  element.dataset.kind = kind;
  element.classList.add('is-visible');
  timer.schedule(() => element.classList.remove('is-visible'), durationMs);
}

export function hideAutoDismissNotice(element: NoticeElement, timer: NoticeTimer): void {
  timer.clear();
  element.classList.remove('is-visible');
}

export function createNoticeTimer<Handle>(
  host: NoticeTimerHost<Handle>,
  fallbackDurationMs = DEFAULT_NOTICE_DURATION_MS,
): NoticeTimer {
  let handle: Handle | null = null;

  const clear = (): void => {
    if (handle === null) return;
    host.clearTimeout(handle);
    handle = null;
  };

  const schedule = (callback: () => void, durationMs?: number): void => {
    clear();
    handle = host.setTimeout(() => {
      handle = null;
      callback();
    }, normalizeNoticeDuration(durationMs, fallbackDurationMs));
  };

  return { clear, schedule };
}