import type { ExtensionModuleHostApi } from '../extensions/public-api.js';
import type { DatabaseTablesSnapshot, DatabaseWriteResult } from '../storage/database-api.js';
import type { DataCenterAccess } from './data-center-access.js';
import type { SheetContent, SqliteMemoryEngine } from './memory-engine.js';
import { resolveStorySqlTableName } from './story-sql.js';

interface Options {
  readonly access: DataCenterAccess;
  readonly engine: () => SqliteMemoryEngine;
  readonly scopeId: () => string;
  readonly afterWrite: () => void;
}

function message(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/** 保留扩展 API 的调用形状，所有数据来自内部数据中心，不访问外部数据库插件。 */
export function createDataCenterDatabaseApi(options: Options): ExtensionModuleHostApi['database'] {
  let writes: Promise<unknown> = Promise.resolve();

  const context = () => ({
    assertCurrent: options.access.require(),
    engine: options.engine(),
    scopeId: options.scopeId(),
  });
  type Context = ReturnType<typeof context>;

  const readTable = async (run: Context, tableName: string): Promise<SheetContent> => {
    const sheets = await run.engine.listSheets(run.scopeId);
    run.assertCurrent();
    const exact = sheets.find((sheet) => sheet.id === tableName || sheet.physicalName === tableName);
    const matches = exact ? [exact] : sheets.filter((sheet) => sheet.name === tableName);
    if (matches.length !== 1) throw new Error(matches.length > 1 ? '存在同名表，请使用表 ID。' : '数据中心中未找到该表。');
    const content = await run.engine.readSheet(run.scopeId, matches[0]!.id, 10_000);
    run.assertCurrent();
    if (!content) throw new Error('数据中心表格读取失败。');
    return content;
  };

  const valuesFor = (table: SheetContent, data: Readonly<Record<string, string>>): Readonly<Record<string, string>> => {
    const values: Record<string, string> = {};
    for (const [key, value] of Object.entries(data)) {
      const matches = table.columns.includes(key)
        ? [key]
        : table.columns.filter((_, index) => table.labels[index] === key);
      if (matches.length !== 1) throw new Error(`列「${key}」不存在或名称重复，请使用列名。`);
      values[matches[0]!] = String(value);
    }
    if (Object.keys(values).length === 0) throw new Error('请至少提供一个字段。');
    return values;
  };

  const rowIdFor = (table: SheetContent, rowIndex: number): number => {
    if (!Number.isInteger(rowIndex) || rowIndex < 1) throw new Error('数据行号从 1 开始。');
    const row = table.rows[rowIndex - 1];
    if (!row) throw new Error('数据行不存在。');
    return row.rowId;
  };

  const mutate = (task: (run: Context) => Promise<DatabaseWriteResult & { readonly rowIndex?: number }>) => {
    try {
      const run = context();
      const pending = writes.then(async () => {
        run.assertCurrent();
        const result = await task(run);
        run.assertCurrent();
        if (result.ok) options.afterWrite();
        return result;
      }).catch((error: unknown) => ({ ok: false, message: message(error) }));
      writes = pending;
      return pending;
    } catch (error) {
      return Promise.resolve({ ok: false, message: message(error) });
    }
  };

  const tables = async (): Promise<DatabaseTablesSnapshot> => {
    try {
      const run = context();
      const sheets = await run.engine.listSheets(run.scopeId);
      run.assertCurrent();
      if (run.engine.availability.kind !== 'ready') throw new Error('数据中心数据库尚未就绪。');
      const contents = await Promise.all(sheets.map((sheet) => run.engine.readSheet(run.scopeId, sheet.id, 10_000)));
      run.assertCurrent();
      return {
        available: true,
        reason: `已读取数据中心的 ${sheets.length} 张表。`,
        tables: contents.filter((table): table is SheetContent => table !== null).map((table) => ({
          sheetKey: table.sheet.id,
          name: table.sheet.name,
          headers: table.labels,
          rows: table.rows.map((row) => row.values),
        })),
      };
    } catch (error) {
      return { available: false, reason: message(error), tables: [] };
    }
  };

  return {
    tables,
    query: async (request) => {
      try {
        if (request.kind === 'tables') {
          const snapshot = await tables();
          return snapshot.available ? { tables: snapshot.tables.map((table) => table.name) } : { error: snapshot.reason };
        }
        const run = context();
        const limit = Number.isFinite(request.limit) ? Math.max(1, Math.min(1_000, Math.trunc(request.limit!))) : 100;
        if (request.kind === 'table') {
          const table = await readTable(run, request.tableName?.trim() ?? '');
          return {
            columns: table.columns,
            rows: table.rows.slice(0, limit).map((row) => Object.fromEntries(table.columns.map((column, index) => [column, row.values[index] ?? '']))),
          };
        }
        const sheets = await run.engine.listSheets(run.scopeId);
        run.assertCurrent();
        const sql = resolveStorySqlTableName(request.sql ?? '', sheets);
        const result = await run.engine.queryUserSql(run.scopeId, sql, limit);
        run.assertCurrent();
        return { columns: [...new Set(result.rows.flatMap((row) => Object.keys(row)))], rows: result.rows };
      } catch (error) {
        return { error: message(error) };
      }
    },
    updateRow: (tableName, rowIndex, data) => mutate(async (run) => {
      const table = await readTable(run, tableName);
      const changed = await run.engine.updateSheetRow(run.scopeId, table.sheet.id, rowIdFor(table, rowIndex), valuesFor(table, data));
      return { ok: changed > 0, message: changed > 0 ? '已保存到数据中心。' : '数据行已发生变化，请刷新后重试。' };
    }),
    insertRow: (tableName, data) => mutate(async (run) => {
      const table = await readTable(run, tableName);
      await run.engine.insertSheetRow(run.scopeId, table.sheet.id, valuesFor(table, data));
      return { ok: true, message: '已在数据中心新增一行。', rowIndex: table.rows.length + 1 };
    }),
    deleteRow: (tableName, rowIndex) => mutate(async (run) => {
      const table = await readTable(run, tableName);
      const changed = await run.engine.deleteSheetRow(run.scopeId, table.sheet.id, rowIdFor(table, rowIndex));
      return { ok: changed > 0, message: changed > 0 ? '已从数据中心删除该行。' : '数据行已发生变化，请刷新后重试。' };
    }),
  };
}
