import type {
  ConditionArrayNode,
  ConditionBinaryNode,
  ConditionBinaryOperator,
  ConditionCallNode,
  ConditionFunctionName,
  ConditionLiteralNode,
  ConditionNode,
  ConditionPathNode,
  ConditionPathSegment,
  ConditionSource,
  ConditionUnaryNode,
  ConditionLimits,
} from './types.js';
import { DEFAULT_CONDITION_LIMITS } from './types.js';

export class ConditionParseError extends Error {
  readonly code = 'parse' as const;

  constructor(message: string, readonly offset: number) {
    super(`${message}（位置 ${offset}）`);
    this.name = 'ConditionParseError';
  }
}

type TokenKind = 'number' | 'string' | 'identifier' | 'operator' | 'punctuation' | 'eof';

interface Token {
  readonly kind: TokenKind;
  readonly value: string;
  readonly offset: number;
}

const FUNCTION_NAMES = new Set<ConditionFunctionName>([
  'exists',
  'empty',
  'length',
  'contains',
  'startsWith',
  'endsWith',
]);
const BINARY_WORDS = new Set(['and', 'or', 'in']);

export function parseCondition(
  source: ConditionSource,
  limits: ConditionLimits = DEFAULT_CONDITION_LIMITS,
): ConditionNode {
  if (typeof source !== 'string') return source;
  const maxSourceLength = limits.maxSourceLength ?? DEFAULT_CONDITION_LIMITS.maxSourceLength;
  if (source.length > maxSourceLength) throw new ConditionParseError('条件表达式过长', maxSourceLength);
  const parser = new ConditionParser(tokenize(source, limits.maxTokens ?? DEFAULT_CONDITION_LIMITS.maxTokens));
  return parser.parse();
}

export function tryParseCondition(
  source: ConditionSource,
  limits: ConditionLimits = DEFAULT_CONDITION_LIMITS,
): { readonly node?: ConditionNode; readonly error?: ConditionParseError } {
  try {
    return { node: parseCondition(source, limits) };
  } catch (error) {
    return { error: error instanceof ConditionParseError ? error : new ConditionParseError('条件表达式无效', 0) };
  }
}

function tokenize(source: string, maxTokens: number): readonly Token[] {
  const tokens: Token[] = [];
  const tokenLimit = Math.max(1, Math.floor(maxTokens));
  const pushToken = (token: Token): void => {
    if (tokens.length >= tokenLimit) throw new ConditionParseError('条件表达式 token 数超过限制', token.offset);
    tokens.push(token);
  };
  let index = 0;
  while (index < source.length) {
    const char = source[index] ?? '';
    if (/\s/u.test(char)) {
      index += 1;
      continue;
    }
    if (char === '"' || char === "'") {
      const start = index;
      const quote = char;
      index += 1;
      let value = '';
      let closed = false;
      while (index < source.length) {
        const current = source[index] ?? '';
        if (current === '\\') {
          const escaped = source[index + 1];
          if (escaped === undefined) break;
          value += decodeEscape(escaped);
          index += 2;
          continue;
        }
        if (current === quote) {
          index += 1;
          closed = true;
          break;
        }
        value += current;
        index += 1;
      }
      if (!closed) throw new ConditionParseError('字符串缺少结束引号', start);
      pushToken({ kind: 'string', value, offset: start });
      continue;
    }
    if (/[0-9]/u.test(char) || (char === '-' && /[0-9]/u.test(source[index + 1] ?? ''))) {
      const start = index;
      index += 1;
      while (/[0-9.eE+-]/u.test(source[index] ?? '')) index += 1;
      const value = source.slice(start, index);
      if (!Number.isFinite(Number(value)) || !/^[-+]?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?$/u.test(value)) {
        throw new ConditionParseError('数字字面量无效', start);
      }
      pushToken({ kind: 'number', value, offset: start });
      continue;
    }
    const two = source.slice(index, index + 2);
    const three = source.slice(index, index + 3);
    if (three === '===' || three === '!==') {
      pushToken({ kind: 'operator', value: three === '===' ? '==' : '!=', offset: index });
      index += 3;
      continue;
    }
    if (['&&', '||', '==', '!=', '>=', '<='].includes(two)) {
      pushToken({ kind: 'operator', value: two, offset: index });
      index += 2;
      continue;
    }
    if (['!', '>', '<'].includes(char)) {
      pushToken({ kind: 'operator', value: char, offset: index });
      index += 1;
      continue;
    }
    if ('().[],'.includes(char)) {
      pushToken({ kind: 'punctuation', value: char, offset: index });
      index += 1;
      continue;
    }
    const start = index;
    while (index < source.length && !/[\s().[\],!<>=&|]/u.test(source[index] ?? '')) index += 1;
    if (index === start) throw new ConditionParseError(`无法识别字符“${char}”`, index);
    pushToken({ kind: 'identifier', value: source.slice(start, index), offset: start });
  }
  pushToken({ kind: 'eof', value: '', offset: source.length });
  return tokens;
}

class ConditionParser {
  #index = 0;

  constructor(private readonly tokens: readonly Token[]) {}

  parse(): ConditionNode {
    const node = this.parseOr();
    const token = this.current();
    if (token.kind !== 'eof') throw new ConditionParseError(`多余内容“${token.value}”`, token.offset);
    return node;
  }

  private parseOr(): ConditionNode {
    let left = this.parseAnd();
    while (this.matchWord('or') || this.matchOperator('||')) left = this.binary('or', left, this.parseAnd());
    return left;
  }

  private parseAnd(): ConditionNode {
    let left = this.parseComparison();
    while (this.matchWord('and') || this.matchOperator('&&')) left = this.binary('and', left, this.parseComparison());
    return left;
  }

  private parseComparison(): ConditionNode {
    let left = this.parseUnary();
    while (true) {
      const operator = this.readComparisonOperator();
      if (!operator) return left;
      left = this.binary(operator, left, this.parseUnary());
    }
  }

  private parseUnary(): ConditionNode {
    if (this.matchOperator('!') || this.matchWord('not')) {
      const node: ConditionUnaryNode = { kind: 'unary', operator: 'not', operand: this.parseUnary() };
      return node;
    }
    return this.parsePrimary();
  }

  private parsePrimary(): ConditionNode {
    const token = this.current();
    if (this.matchPunctuation('(')) {
      const node = this.parseOr();
      this.expectPunctuation(')');
      return node;
    }
    if (this.matchPunctuation('[')) {
      const items: ConditionNode[] = [];
      if (!this.matchPunctuation(']')) {
        do items.push(this.parseOr()); while (this.matchPunctuation(','));
        this.expectPunctuation(']');
      }
      const node: ConditionArrayNode = { kind: 'array', items };
      return node;
    }
    if (token.kind === 'number') {
      this.advance();
      const node: ConditionLiteralNode = { kind: 'literal', value: Number(token.value) };
      return node;
    }
    if (token.kind === 'string') {
      this.advance();
      const node: ConditionLiteralNode = { kind: 'literal', value: token.value };
      return node;
    }
    if (token.kind !== 'identifier') throw new ConditionParseError('需要条件值', token.offset);
    this.advance();
    if (token.value === 'true' || token.value === 'false' || token.value === 'null') {
      const value = token.value === 'null' ? null : token.value === 'true';
      const node: ConditionLiteralNode = { kind: 'literal', value };
      return node;
    }
    if (FUNCTION_NAMES.has(token.value as ConditionFunctionName) && this.matchPunctuation('(')) {
      const args: ConditionNode[] = [];
      if (!this.matchPunctuation(')')) {
        do args.push(this.parseOr()); while (this.matchPunctuation(','));
        this.expectPunctuation(')');
      }
      const node: ConditionCallNode = { kind: 'call', name: token.value as ConditionFunctionName, arguments: args };
      return node;
    }
    return this.parsePath(token.value, token.offset);
  }

  private parsePath(root: string, offset: number): ConditionPathNode {
    const segments: ConditionPathSegment[] = [root];
    while (true) {
      if (this.matchPunctuation('.')) {
        const token = this.current();
        if (token.kind !== 'identifier') throw new ConditionParseError('点号后需要属性名', token.offset);
        this.advance();
        segments.push(token.value);
        continue;
      }
      if (this.matchPunctuation('[')) {
        const token = this.current();
        if (token.kind !== 'number' && token.kind !== 'string' && token.kind !== 'identifier') {
          throw new ConditionParseError('方括号内需要属性名或索引', token.offset);
        }
        this.advance();
        const segment: ConditionPathSegment = token.kind === 'number' ? Number(token.value) : token.value;
        segments.push(segment);
        this.expectPunctuation(']');
        continue;
      }
      break;
    }
    const node: ConditionPathNode = { kind: 'path', segments };
    if (segments.length === 0) throw new ConditionParseError('路径为空', offset);
    return node;
  }

  private readComparisonOperator(): ConditionBinaryOperator | null {
    const token = this.current();
    if (token.kind === 'operator') {
      this.advance();
      const map: Record<string, ConditionBinaryOperator> = {
        '==': 'eq', '!=': 'ne', '>': 'gt', '>=': 'gte', '<': 'lt', '<=': 'lte',
      };
      const operator = map[token.value];
      if (operator) return operator;
      throw new ConditionParseError(`不支持的运算符“${token.value}”`, token.offset);
    }
    if (token.kind === 'identifier' && (token.value === 'in' || token.value === 'contains')) {
      this.advance();
      return token.value as ConditionBinaryOperator;
    }
    return null;
  }

  private binary(operator: ConditionBinaryOperator, left: ConditionNode, right: ConditionNode): ConditionBinaryNode {
    return { kind: 'binary', operator, left, right };
  }

  private current(): Token {
    return this.tokens[this.#index] ?? { kind: 'eof', value: '', offset: 0 };
  }

  private advance(): void {
    this.#index += 1;
  }

  private matchOperator(value: string): boolean {
    if (this.current().kind === 'operator' && this.current().value === value) {
      this.advance();
      return true;
    }
    return false;
  }

  private matchWord(value: string): boolean {
    if (this.current().kind === 'identifier' && this.current().value === value) {
      this.advance();
      return true;
    }
    return false;
  }

  private matchPunctuation(value: string): boolean {
    if (this.current().kind === 'punctuation' && this.current().value === value) {
      this.advance();
      return true;
    }
    return false;
  }

  private expectPunctuation(value: string): void {
    if (!this.matchPunctuation(value)) throw new ConditionParseError(`需要“${value}”`, this.current().offset);
  }
}

function decodeEscape(value: string): string {
  const escapes: Record<string, string> = { n: '\n', r: '\r', t: '\t', '\\': '\\', '"': '"', "'": "'" };
  return escapes[value] ?? value;
}