/**
 * NovelAI 请求闸门：本地串行 + 失败重试策略。
 *
 * NovelAI 自 2024-03 起取消了并发生图能力，同一账号同一时刻只允许一张图在生成，
 * 第二个同时发出的请求会被直接拒绝（429；经酒馆代理后会变成 500）。
 * 页面上可以同时存在多个「点击生成图片」按钮，用户先后点击就会并发发请求，
 * 所以在客户端这一层强制串行，并对限流类失败做退避重试。
 */

/** 退避重试的等待时间；数组长度即额外重试次数。 */
export const NOVELAI_RETRY_DELAYS_MS: readonly number[] = [3_000, 8_000];

/** 一次请求尝试的结果：成功值，或带可重试标记的失败原因。 */
export type NovelAiAttempt<T> =
  | { readonly ok: true; readonly value: T }
  | {
    readonly ok: false;
    readonly message: string;
    readonly retryable: boolean;
    /** 指定本次失败的等待时长（毫秒）；未提供时按退避表等待。 */
    readonly retryAfterMs?: number;
  };

export interface NovelAiRetryableError extends Error {
  readonly retryable: boolean;
}

/** 限流 / 并发冲突 / 网关错误按可重试处理；鉴权、额度、路径错误重试无意义。 */
export function isRetryableNovelAiStatus(status: number): boolean {
  return status === 408 || status === 429 || status >= 500;
}

let tail: Promise<unknown> = Promise.resolve();

/**
 * 把 NovelAI 请求排成单条队列：无论前一个请求成功还是失败，都在它结束后才开始下一个。
 * 队列只保证互斥，不吞掉任何结果，调用方仍然拿到自己那次操作的 Promise。
 */
export function runNovelAiExclusive<T>(operation: () => Promise<T>): Promise<T> {
  const result = tail.then(operation, operation);
  tail = result.then(ignore, ignore);
  return result;
}

/** 按退避表重试可恢复的失败；重试耗尽或失败不可恢复时抛出最后一次的原因。 */
export async function withNovelAiRetry<T>(
  attempt: () => Promise<NovelAiAttempt<T>>,
  delaysMs: readonly number[] = NOVELAI_RETRY_DELAYS_MS,
): Promise<T> {
  let lastMessage = 'NovelAI 请求失败。';
  for (let round = 0; round <= delaysMs.length; round += 1) {
    let result: NovelAiAttempt<T>;
    try {
      result = await attempt();
    } catch (error) {
      if (!isRetryableError(error)) throw error;
      result = { ok: false, retryable: true, message: error.message };
    }
    if (result.ok) return result.value;
    lastMessage = result.message;
    const hasNextRound = round < delaysMs.length;
    if (!result.retryable || !hasNextRound) break;
    await sleep(result.retryAfterMs ?? delaysMs[round] ?? 0);
  }
  throw new Error(lastMessage);
}

function isRetryableError(error: unknown): error is NovelAiRetryableError {
  return error instanceof Error
    && (error as Partial<NovelAiRetryableError>).retryable === true;
}

function ignore(): void {
  // 队列只关心「上一个请求已结束」，成败由调用方各自处理。
}

function sleep(milliseconds: number): Promise<void> {
  if (milliseconds <= 0) return Promise.resolve();
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}