import { phoneLogger } from '../core/logger.js';
import { generateWithApiProxy } from '../generation/api-client.js';
import { CancellableRun, isCancelledError } from '../generation/cancellable-run.js';
import type { FanficSettings, OpenAiCompatibleApiConfig } from '../integration/sillytavern-bridge.js';
import type { FanficNarrativeState } from './model.js';
import { buildNarrativePatchPrompt, parseNarrativePatch, type NarrativePatch } from './patch-protocol.js';
import { structuredTemperature, structuredTokenBudget } from './structured-request.js';

export interface NarrativeFloor {
  readonly floor: number;
  readonly name: string;
  readonly role: 'user' | 'ai';
  readonly text: string;
}

export interface NarrativePipelineDeps {
  readonly settings: () => {
    readonly fanfic: FanficSettings;
    readonly fallbackApi: OpenAiCompatibleApiConfig;
  };
  readonly narrative: () => FanficNarrativeState;
  readonly characterNames: () => readonly string[];
  readonly readFloorsSince: (afterFloor: number) => readonly NarrativeFloor[];
  readonly latestFloorIndex: () => number;
  readonly advance: (floor: number, patch: NarrativePatch) => Promise<void>;
  readonly reportTask?: (message: string | null) => void;
  readonly reportTaskResult?: (message: string, kind: 'error' | 'success' | 'cancelled') => void;
}

export interface NarrativePipelineResult {
  readonly ok: boolean;
  readonly message: string;
}

/** 单次跟踪最多读取的正文字符数：足够覆盖新增楼层，又不至于让请求过大。 */
const TRANSCRIPT_CHAR_LIMIT = 12_000;
/**
 * 状态补丁的输出预算区间：补丁有场景、在场、秘密、悬念等八个字段，
 * 预算太小会写到一半被截断，只能报「格式无效」。
 */
const PATCH_TOKEN_RANGE = { min: 3_000, max: 16_000 } as const;
/** 失败后的真实时间冷却，避免连续报错刷屏与浪费额度。 */
const FAILURE_COOLDOWN_MS = 90_000;

/**
 * 剧情状态跟踪管线：AI 回复后把新增正文压缩成"仍然成立的事实"，写入聊天级 AU 状态。
 * 任何失败都保留上一版状态并进入冷却，不阻断正文生成。
 */
export class NarrativePipeline {
  readonly #deps: NarrativePipelineDeps;
  readonly #run = new CancellableRun();
  #running = false;
  #cooldownUntil = 0;

  constructor(deps: NarrativePipelineDeps) {
    this.#deps = deps;
  }

  get isRunning(): boolean {
    return this.#running;
  }

  /** 用户在提示卡片上点「终止」时调用。 */
  cancel(): boolean {
    return this.#run.cancel();
  }

  /** 楼层被编辑、删除或滑动后调用：解除冷却，让下一次跟踪立即重算。 */
  resetCooldown(): void {
    this.#cooldownUntil = 0;
  }

  /** 自动跟踪：达到设定的 AI 回复数量才调用 API。 */
  async maybeTrack(): Promise<void> {
    const { fanfic } = this.#deps.settings();
    if (!fanfic.enabled || !fanfic.autoTrack || this.#running) return;
    if (Date.now() < this.#cooldownUntil) return;
    const narrative = this.#deps.narrative();
    const floors = this.#deps.readFloorsSince(narrative.lastFloor);
    const aiFloors = floors.filter((floor) => floor.role === 'ai' && floor.text.trim());
    if (aiFloors.length < Math.max(1, fanfic.trackEveryAiMessages)) return;
    const result = await this.track();
    if (!result.ok) {
      // 提示已由 track 内部落终态，这里只留排查用日志。
      phoneLogger.warn('同人剧情状态自动跟踪未完成', { message: result.message });
    }
  }

  /** 手动或自动触发一次状态跟踪。 */
  async track(): Promise<NarrativePipelineResult> {
    const { fanfic } = this.#deps.settings();
    if (!fanfic.enabled) return { ok: false, message: '请先启用同人剧情模式。' };
    if (this.#running) return { ok: false, message: '剧情状态正在更新中，请稍候。' };
    const api = this.#resolveApi();
    if (!api.model.trim()) {
      return { ok: false, message: '请先为同人剧情或记忆整理配置 API 模型，才能自动跟踪剧情状态。' };
    }
    const narrative = this.#deps.narrative();
    const floors = this.#deps.readFloorsSince(narrative.lastFloor);
    const usable = floors.filter((floor) => floor.text.trim());
    if (usable.length === 0) return { ok: false, message: '没有新增正文需要跟踪。' };

    this.#running = true;
    this.#deps.reportTask?.('墨韵手机：正在更新同人剧情状态.....');
    const signal = this.#run.begin();
    try {
      const prompt = buildNarrativePatchPrompt({
        transcript: buildTranscript(usable),
        narrative,
        characterNames: this.#deps.characterNames(),
      });
      const raw = await generateWithApiProxy(api, {
        system: prompt.system,
        user: prompt.user,
        temperature: structuredTemperature(api),
        maxTokens: structuredTokenBudget(api, PATCH_TOKEN_RANGE),
        signal,
        validateResponse: (response) => parseNarrativePatch(response) !== null,
        invalidResponseMessage: '剧情状态跟踪返回的格式无效。',
        onRetry: ({ attempt, retryCount, error }) => {
          this.#deps.reportTaskResult?.(
            `墨韵手机：剧情状态更新失败，正在重试 ${attempt}/${retryCount}：${describeError(error)}`,
            'error',
          );
        },
      });
      const patch = parseNarrativePatch(raw);
      if (!patch) throw new Error('剧情状态跟踪返回的格式无效。');
      const floor = Math.max(narrative.lastFloor, usable.at(-1)?.floor ?? this.#deps.latestFloorIndex());
      await this.#deps.advance(floor, patch);
      this.#cooldownUntil = 0;
      const message = `剧情状态已更新到第 ${floor} 楼。`;
      this.#deps.reportTaskResult?.(`墨韵手机：${message}`, 'success');
      return { ok: true, message };
    } catch (error) {
      if (isCancelledError(error)) {
        this.#deps.reportTaskResult?.('墨韵手机：剧情跟踪已终止。', 'cancelled');
        return { ok: false, message: '剧情状态更新已终止。' };
      }
      this.#cooldownUntil = Date.now() + FAILURE_COOLDOWN_MS;
      const message = `剧情状态更新失败：${describeError(error)}`;
      this.#deps.reportTaskResult?.(`墨韵手机：${message}`, 'error');
      return { ok: false, message };
    } finally {
      this.#running = false;
      this.#run.end();
    }
  }

  #resolveApi(): OpenAiCompatibleApiConfig {
    const { fanfic, fallbackApi } = this.#deps.settings();
    return fanfic.api.model.trim() ? fanfic.api : fallbackApi;
  }
}

/** 新增正文拼接：保留楼层号与说话人，超长时从头部截断（最近内容优先）。 */
function buildTranscript(floors: readonly NarrativeFloor[]): string {
  const text = floors
    .map((floor) => `第${floor.floor}楼（${floor.name}/${floor.role === 'ai' ? 'AI' : '用户'}）：\n${floor.text.trim()}`)
    .join('\n\n');
  return text.length > TRANSCRIPT_CHAR_LIMIT ? text.slice(-TRANSCRIPT_CHAR_LIMIT) : text;
}

function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}