export const APP_ID_LABELS: Readonly<Record<AppId, string>> = Object.freeze({
  wechat: '微信',
  forum: '论坛',
  anonymous: '匿名交友',
  twitter: '推特',
});

/** 解析应用显示名称：个性化自定义名称优先，留空则回落到出厂名称。 */
export function appLabelOf(
  appId: AppId,
  customLabels: Readonly<Record<string, string>> = {},
): string {
  const custom = customLabels[appId]?.trim();
  return custom || APP_ID_LABELS[appId];
}

