/**
 * 正文首行当标题：去掉 Markdown 标题符号，并且只在整行被方括号包住时才脱壳，
 * 这样「【求助】谁见过闪光鲤鱼王」这类前缀写法能原样保留。
 * 解析落库与界面展示共用同一条规则，避免两边算出不同标题。
 */
export function derivePostTitle(content: string): string {
  const firstLine = content.split(/\r?\n/, 1)[0]?.trim() ?? '';
  const withoutHeading = firstLine.replace(/^#+\s*/, '').trim();
  const wrapped = /^【(.+)】$/.exec(withoutHeading) ?? /^\[(.+)\]$/.exec(withoutHeading);
  return (wrapped?.[1] ?? withoutHeading).trim();
}

