export type MemorySource = 'memory' | 'summary' | 'phone';
export type MemoryDisplayType = 'memory' | 'summary' | 'phone';

export const MEMORY_SOURCE_LABELS: Readonly<Record<MemorySource, string>> = Object.freeze({
  phone: '手机',
  memory: '记忆',
  summary: '总结',
});

function isMemorySource(value: unknown): value is MemorySource {
  return value === 'memory' || value === 'summary' || value === 'phone';
}

export function memorySourceOf(item: Pick<MemoryItem, 'kind' | 'source' | 'displayType'>): MemorySource {
  if (isMemorySource(item.source)) return item.source;
  if (isMemorySource(item.displayType)) return item.displayType;
  return item.kind === 'consolidation' ? 'summary' : 'memory';
}

export function memoryLabelOf(item: Pick<MemoryItem, 'seq' | 'kind' | 'source' | 'displayType'>): string {
  return `${MEMORY_SOURCE_LABELS[memorySourceOf(item)]}#${item.seq}`;
}

/** 解析 `记忆#12` / `总结#3` / `手机#5` 形式的引用标签；未知前缀按正文记忆处理。 */
export function parseMemoryLabel(label: string): { readonly source: MemorySource; readonly seq: number } | null {
  const match = /^\s*(手机|记忆|总结)?\s*#?\s*(\d{1,10})\s*$/u.exec(label);
  if (!match) return null;
  const seq = Number(match[2]);
  if (!Number.isInteger(seq)) return null;
  const prefix = match[1];
  const source: MemorySource = prefix === '手机' ? 'phone' : prefix === '总结' ? 'summary' : 'memory';
  return { source, seq };
}

/** 按来源筛选记忆库条目（保持原有编号顺序）。 */
export function selectMemoryItemsBySource(
  items: readonly MemoryItem[],
  source: MemorySource,
): readonly MemoryItem[] {
  return items.filter((item) => memorySourceOf(item) === source);
}

/** 手机内容总结（按覆盖时间升序）；旧 `PhoneSummary` 已在版本层迁移为该来源。 */
export function selectPhoneSummaryItems(state: PhoneState): readonly MemoryItem[] {
  return selectMemoryItemsBySource(state.memoryItems ?? [], 'phone')
    .slice()
    .sort((left, right) => memoryCoveredUntil(left) - memoryCoveredUntil(right));
}

/** 手机总结覆盖到的剧情时刻；正文记忆没有覆盖时刻时回退到创建时间。 */
export function memoryCoveredUntil(item: MemoryItem): number {
  return typeof item.coveredUntil === 'number' && Number.isFinite(item.coveredUntil)
    ? item.coveredUntil
    : item.createdAt;
}

/** 把手机来源记忆投影成旧 `PhoneSummary` 形状，供外部模块 API 与设置界面继续读取。 */
export function projectPhoneSummaries(state: PhoneState): readonly PhoneSummary[] {
  return selectPhoneSummaryItems(state).map((item) => ({
    id: item.id,
    scopeId: item.scopeId,
    content: item.content,
    coveredUntil: memoryCoveredUntil(item),
    sourceCount: item.sourceCount ?? 0,
    createdAt: item.createdAt,
  }));
}

/**
 * 记忆库条目：正文楼层摘要、合并总结或手机内容总结。
 * source/displayType 为 v2 字段，缺失时由旧 kind 投影，保证旧状态和旧备份可读。
 */
export interface MemoryItem {
  readonly id: string;
  readonly scopeId: string;
  /** 记忆编号（本聊天内递增，显示标签由 source 决定）。 */
  readonly seq: number;
  readonly kind: 'summary' | 'consolidation';
  /** 来源语义：正文楼层、合并总结或手机内容。旧数据缺失时按 kind 推导。 */
  readonly source?: MemorySource;
  /** UI 和外部 API 使用的稳定显示分类；旧数据缺失时按 source 推导。 */
  readonly displayType?: MemoryDisplayType;
  readonly content: string;
  /** 摘要覆盖的正文楼层范围；手机来源可为 0，因为它不代表正文楼层。 */
  readonly floorFrom: number;
  readonly floorTo: number;
  /** 已并入某份总结的摘要标记为 archived（仍可查看与检索）。 */
  readonly archived: boolean;
  /** kind = consolidation 时：并入的摘要编号列表。 */
  readonly sourceSeqs?: readonly number[];
  /** source = phone 时：总结覆盖到的剧情时刻。 */
  readonly coveredUntil?: number;
  /** source = phone 时：被总结的手机记录条数。 */
  readonly sourceCount?: number;
  readonly createdAt: number;
}

/** 时间线事件：剧情里某个时间点发生了什么。 */
export interface TimelineEvent {
  readonly id: string;
  readonly scopeId: string;
  readonly seq: number;
  /** 剧情内时间标签（如「8月12日 下午」）。 */
  readonly timeLabel: string;
  readonly text: string;
  /** 事件来源楼层。 */
  readonly floor: number;
  readonly createdAt: number;
}

/** 同一来源楼层只展示一条记录；重复事件合并其时间与剧情描述。 */
export function normalizeTimelineEvents(events: readonly TimelineEvent[]): readonly TimelineEvent[] {
  const byFloor = new Map<number, TimelineEvent>();
  let changed = false;
  for (const event of events) {
    const existing = byFloor.get(event.floor);
    if (!existing) {
      byFloor.set(event.floor, event);
      continue;
    }
    changed = true;
    const text = mergeTimelineText(existing.text, event.text);
    const timeLabel = mergeTimelineTime(existing.timeLabel, event.timeLabel);
    byFloor.set(event.floor, { ...existing, text, timeLabel });
  }
  if (!changed) return events;
  return [...byFloor.values()].sort((left, right) => left.seq - right.seq);
}

function mergeTimelineText(left: string, right: string): string {
  const first = left.trim();
  const second = right.trim();
  if (!second || first.includes(second)) return first;
  if (!first || second.includes(first)) return second;
  return `${first}；${second}`;
}

function mergeTimelineTime(left: string, right: string): string {
  const first = left.trim();
  const second = right.trim();
  if (!second || first === second || first.includes(second)) return first;
  if (!first) return second.slice(0, 60);
  return `${first} / ${second}`.slice(0, 60);
}

