  readonly interactions: Readonly<Record<string, Interaction>>;
  readonly outbox: Readonly<Record<string, OutboxItem>>;
  readonly batches: Readonly<Record<string, GenerationBatch>>;
  readonly appliedActionIds: readonly string[];
  readonly summaries: readonly PhoneSummary[];
  readonly pxxProducts: readonly PxxProduct[];
