  /** 日记本条目（按日期升序）。 */
  readonly diaryEntries: readonly DiaryEntry[];
  /** 日记已覆盖到的剧情时间点（0 = 尚未建立基线）。 */
  readonly diaryCoveredUntil: number;
  /** 记忆库条目（按记忆编号升序）。 */
  readonly memoryItems: readonly MemoryItem[];
  /** 记忆编号发号器（已用到的最大编号）。 */
  readonly memorySeq: number;
  /** 记忆库已整理到的正文楼层号（-1 = 尚未建立基线）。 */
  readonly memoryLastFloor: number;
