import type { PhoneEvent } from '../domain/events.js';
import { createInitialPhoneState, type PhoneState } from '../domain/model.js';
import { reducePhoneEvents } from '../domain/reducer.js';
import {
  StorageConflictError,
  type StorageBackend,
  type StorageListener,
  type UnsubscribeStorage,
} from './storage-port.js';

export const INDEXEDDB_DATABASE_NAME = 'narrative-phone';
export const INDEXEDDB_STATE_STORE = 'scope-state';
const DATABASE_NAME = INDEXEDDB_DATABASE_NAME;
const DATABASE_VERSION = 1;
const STATE_STORE = INDEXEDDB_STATE_STORE;

interface PersistedScopeState {
  readonly scopeId: string;
  readonly state: PhoneState;
}

function requestResult<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('IndexedDB request failed'));
  });
}

function transactionSettled(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onabort = () => reject(transaction.error ?? new Error('IndexedDB transaction aborted'));
    transaction.onerror = () => reject(transaction.error ?? new Error('IndexedDB transaction failed'));
  });
}

export class IndexedDbStorage implements StorageBackend {
  readonly kind = 'indexeddb' as const;
  readonly #listeners = new Map<string, Set<StorageListener>>();
  #databasePromise: Promise<IDBDatabase> | null = null;

  async isAvailable(): Promise<boolean> {
    if (typeof indexedDB === 'undefined') return false;
    try {
      await this.#open();
      return true;
    } catch {
      return false;
    }
  }

  async load(scopeId: string): Promise<PhoneState | null> {
    const database = await this.#open();
    const transaction = database.transaction(STATE_STORE, 'readonly');
    const record = await requestResult<PersistedScopeState | undefined>(
      transaction.objectStore(STATE_STORE).get(scopeId),
    );
    await transactionSettled(transaction);
    return record?.state ? structuredClone(record.state) : null;
  }

  async commit(
    scopeId: string,
    expectedRevision: number,
    events: readonly PhoneEvent[],
  ): Promise<PhoneState> {
    if (events.length === 0) {
      const current = await this.load(scopeId);
      return current ?? createInitialPhoneState(scopeId);
    }

    const database = await this.#open();
    const transaction = database.transaction(STATE_STORE, 'readwrite');
    const store = transaction.objectStore(STATE_STORE);
    const persisted = await requestResult<PersistedScopeState | undefined>(store.get(scopeId));
    const initialTime = events[0]?.occurredAt ?? Date.now();
    const current = persisted?.state ?? createInitialPhoneState(scopeId, initialTime);

    if (current.revision !== expectedRevision) {
      transaction.abort();
      throw new StorageConflictError(scopeId, expectedRevision, current.revision);
    }

    const next = reducePhoneEvents(current, events);
    store.put({ scopeId, state: next } satisfies PersistedScopeState);
    await transactionSettled(transaction);
    this.#notify(scopeId, next);
    return structuredClone(next);
  }

  async replace(scopeId: string, state: PhoneState): Promise<void> {
    if (state.scopeId !== scopeId) throw new Error('Cannot replace a different phone scope');
    const database = await this.#open();
    const transaction = database.transaction(STATE_STORE, 'readwrite');
    transaction.objectStore(STATE_STORE).put({ scopeId, state } satisfies PersistedScopeState);
    await transactionSettled(transaction);
    this.#notify(scopeId, state);
  }

  async listScopes(): Promise<readonly string[]> {
    const database = await this.#open();
    const transaction = database.transaction(STATE_STORE, 'readonly');
    const keys = await requestResult<IDBValidKey[]>(transaction.objectStore(STATE_STORE).getAllKeys());
    await transactionSettled(transaction);
    return keys.map(String);
  }

  async deleteScope(scopeId: string): Promise<void> {
    const database = await this.#open();
    const transaction = database.transaction(STATE_STORE, 'readwrite');
    transaction.objectStore(STATE_STORE).delete(scopeId);
    await transactionSettled(transaction);
    this.#listeners.delete(scopeId);
  }

  subscribe(scopeId: string, listener: StorageListener): UnsubscribeStorage {
    const listeners = this.#listeners.get(scopeId) ?? new Set<StorageListener>();
    listeners.add(listener);
    this.#listeners.set(scopeId, listeners);
    return () => {
      listeners.delete(listener);
      if (listeners.size === 0) this.#listeners.delete(scopeId);
    };
  }

  dispose(): void {
    this.#listeners.clear();
    if (!this.#databasePromise) return;
    void this.#databasePromise.then((database) => database.close()).catch(() => undefined);
    this.#databasePromise = null;
  }

  #notify(scopeId: string, state: PhoneState): void {
    for (const listener of this.#listeners.get(scopeId) ?? []) {
      listener(structuredClone(state));
    }
  }

  #open(): Promise<IDBDatabase> {
    if (this.#databasePromise) return this.#databasePromise;
    if (typeof indexedDB === 'undefined') {
      return Promise.reject(new Error('IndexedDB is unavailable'));
    }

    this.#databasePromise = new Promise((resolve, reject) => {
      const request = indexedDB.open(DATABASE_NAME, DATABASE_VERSION);
      request.onupgradeneeded = () => {
        const database = request.result;
        if (!database.objectStoreNames.contains(STATE_STORE)) {
          database.createObjectStore(STATE_STORE, { keyPath: 'scopeId' });
        }
      };
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error ?? new Error('Failed to open IndexedDB'));
      request.onblocked = () => reject(new Error('IndexedDB upgrade is blocked'));
    });

    return this.#databasePromise;
  }
}