import type { CharacterLock } from './model.js';

/** 别名 → 角色锁；出现歧义的别名会被剔除，宁可不认也不串人。 */
export interface CharacterIndex {
  readonly byId: ReadonlyMap<string, CharacterLock>;
  readonly byAlias: ReadonlyMap<string, CharacterLock>;
  readonly ambiguous: readonly string[];
}

/** 稳定角色 ID：同一名字在多次重建、导入与备份之间保持一致。 */
export function canonCharacterId(name: string): string {
  const key = normalizeName(name);
  return key ? `canon:${key}` : '';
}

export function normalizeName(value: string): string {
  return value
    .toLocaleLowerCase()
    .replace(/[\s\u3000]+/g, '')
    .replace(/[·・.,，。!！?？:：;；'"“”‘’()（）\[\]【】\-—_/\\]+/g, '');
}

export function buildCharacterIndex(characters: readonly CharacterLock[]): CharacterIndex {
  const byId = new Map<string, CharacterLock>();
  const owners = new Map<string, Set<string>>();
  for (const character of characters) {
    if (!character.id) continue;
    byId.set(character.id, character);
    for (const alias of [character.name, ...character.aliases]) {
      const key = normalizeName(alias);
      if (!key) continue;
      const set = owners.get(key) ?? new Set<string>();
      set.add(character.id);
      owners.set(key, set);
    }
  }
  const byAlias = new Map<string, CharacterLock>();
  const ambiguous: string[] = [];
  for (const [alias, ids] of owners) {
    if (ids.size > 1) {
      ambiguous.push(alias);
      continue;
    }
    const character = byId.get([...ids][0] ?? '');
    if (character) byAlias.set(alias, character);
  }
  return { byId, byAlias, ambiguous };
}

/** 按 ID、精确别名、再按包含关系解析角色；无法唯一确定时返回 null。 */
export function resolveCharacterLock(index: CharacterIndex, name: string): CharacterLock | null {
  const raw = name.trim();
  if (!raw) return null;
  const direct = index.byId.get(raw);
  if (direct) return direct;
  const key = normalizeName(raw);
  if (!key) return null;
  const exact = index.byAlias.get(key);
  if (exact) return exact;
  const contained = [...index.byAlias.entries()].filter(([alias]) => (
    alias.length >= 2 && (key.includes(alias) || alias.includes(key))
  ));
  const unique = new Set(contained.map(([, character]) => character.id));
  return unique.size === 1 ? contained[0]?.[1] ?? null : null;
}

/** 从任意文本里找出提到的角色，按首次出现顺序去重。 */
export function detectMentionedCharacters(
  index: CharacterIndex,
  text: string,
): readonly CharacterLock[] {
  const found = new Map<string, CharacterLock>();
  const haystack = normalizeName(text);
  if (!haystack) return [];
  for (const [alias, character] of index.byAlias) {
    if (alias.length < 2 || found.has(character.id)) continue;
    if (haystack.includes(alias)) found.set(character.id, character);
  }
  return [...found.values()];
}

/**
 * 合并重建结果：用户手工修正过的角色锁不被自动覆盖，
 * 其余字段以新解析结果为准，但保留已积累的别名与来源。
 */
export function mergeCharacterLocks(
  existing: readonly CharacterLock[],
  incoming: readonly CharacterLock[],
): readonly CharacterLock[] {
  const merged = new Map(existing.map((character) => [character.id, character]));
  for (const candidate of incoming) {
    if (!candidate.id) continue;
    const current = merged.get(candidate.id);
    if (!current) {
      merged.set(candidate.id, candidate);
      continue;
    }
    if (current.manual) {
      merged.set(candidate.id, {
        ...current,
        aliases: uniqueTexts([...current.aliases, ...candidate.aliases]),
        sourceIds: uniqueTexts([...current.sourceIds, ...candidate.sourceIds]),
      });
      continue;
    }
    merged.set(candidate.id, {
      ...candidate,
      aliases: uniqueTexts([...current.aliases, ...candidate.aliases]),
      sourceIds: uniqueTexts([...current.sourceIds, ...candidate.sourceIds]),
    });
  }
  return [...merged.values()];
}

export function uniqueTexts(values: readonly string[], limit = 40): readonly string[] {
  const seen = new Set<string>();
  const unique: string[] = [];
  for (const value of values) {
    const text = value.trim();
    if (!text || seen.has(text)) continue;
    seen.add(text);
    unique.push(text);
    if (unique.length >= limit) break;
  }
  return unique;
}