/**
 * 扫描当前角色卡与绑定世界书里的 MVU 资产。
 *
 * 只读操作，是「MVU 转换数据」面板的入口：先让用户看清认出了什么，再决定要不要转换。
 * 两个关键点：
 * - 读**全部**世界书条目而不是生效条目——InitVar 在卡里通常是关闭状态；
 * - 一并读卡内的酒馆助手脚本——MVU Zod 卡的变量结构写在 `registerMvuSchema(z.object({...}))` 里，
 *   世界书 InitVar 只是种子，光看世界书会把这类卡判成「没有变量」。
 */

import {
  getCharacterCardSnapshot,
  getCurrentCharacterData,
  getSillyTavernContext,
  loadWorldBookSnapshot,
  type SillyTavernContextShape,
} from './sillytavern-bridge.js';
import { collectMvuAssets, type MvuSourceEntry, type MvuSourceScript } from '../mvu/card-source.js';
import type { MvuCardSource } from '../mvu/types.js';

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

/** 卡里可能把脚本挂在 `tavern_helper.scripts` 或 `TavernHelper_scripts`，两种都读。 */
function readCardScripts(context: SillyTavernContextShape): readonly MvuSourceScript[] {
  const card = getCurrentCharacterData(context);
  const data = isRecord(card) && isRecord(card.data) ? card.data : (isRecord(card) ? card : {});
  const extensions = isRecord(data.extensions) ? data.extensions : {};
  const helper = isRecord(extensions.tavern_helper) ? extensions.tavern_helper : {};
  const lists = [helper.scripts, extensions.TavernHelper_scripts].filter((list): list is unknown[] => Array.isArray(list));
  return lists.flat().flatMap((script): readonly MvuSourceScript[] => {
    if (!isRecord(script)) return [];
    const content = text(script.content);
    return content.trim()
      ? [{ name: text(script.name), content, enabled: script.enabled !== false }]
      : [];
  });
}

export async function scanMvuCardSource(): Promise<MvuCardSource> {
  const context = getSillyTavernContext();
  const card = getCharacterCardSnapshot(context);
  const worldBook = await loadWorldBookSnapshot(context, { sourceMode: 'bound' });
  const entries: readonly MvuSourceEntry[] = worldBook.entries.map((entry) => ({
    id: entry.id,
    name: entry.name,
    content: entry.content,
    enabled: entry.enabled,
    book: entry.book ?? '',
    ...(entry.activation ? { activation: entry.activation } : {}),
  }));
  return collectMvuAssets({
    cardName: card.name,
    books: worldBook.books.length > 0 ? worldBook.books : worldBook.names,
    entries,
    scripts: readCardScripts(context),
  });
}
