export type ConditionPrimitive = string | number | boolean | null;

export type ConditionValue =
  | ConditionPrimitive
  | readonly ConditionValue[]
  | { readonly [key: string]: ConditionValue };

export type ConditionPathSegment = string | number;

export interface ConditionLiteralNode {
  readonly kind: 'literal';
  readonly value: ConditionValue;
}

export interface ConditionPathNode {
  readonly kind: 'path';
  readonly segments: readonly ConditionPathSegment[];
}

export interface ConditionArrayNode {
  readonly kind: 'array';
  readonly items: readonly ConditionNode[];
}

export type ConditionUnaryOperator = 'not';

export interface ConditionUnaryNode {
  readonly kind: 'unary';
  readonly operator: ConditionUnaryOperator;
  readonly operand: ConditionNode;
}

export type ConditionBinaryOperator =
  | 'and'
  | 'or'
  | 'eq'
  | 'ne'
  | 'gt'
  | 'gte'
  | 'lt'
  | 'lte'
  | 'contains'
  | 'in';

export interface ConditionBinaryNode {
  readonly kind: 'binary';
  readonly operator: ConditionBinaryOperator;
  readonly left: ConditionNode;
  readonly right: ConditionNode;
}

export type ConditionFunctionName =
  | 'exists'
  | 'empty'
  | 'length'
  | 'contains'
  | 'startsWith'
  | 'endsWith';

export interface ConditionCallNode {
  readonly kind: 'call';
  readonly name: ConditionFunctionName;
  readonly arguments: readonly ConditionNode[];
}

export type ConditionNode =
  | ConditionLiteralNode
  | ConditionPathNode
  | ConditionArrayNode
  | ConditionUnaryNode
  | ConditionBinaryNode
  | ConditionCallNode;

export type ConditionSource = string | ConditionNode;

export interface ConditionSnapshot {
  readonly scopeId: string;
  readonly revision: string;
  readonly data: ConditionValue;
}

export interface ConditionRule {
  readonly id: string;
  readonly condition: ConditionSource;
  readonly onError?: 'deny' | 'allow';
}

export interface ConditionEvaluation {
  readonly ok: boolean;
  readonly value: ConditionValue;
  readonly error?: ConditionError;
  readonly steps: number;
}

export type ConditionErrorCode =
  | 'parse'
  | 'invalid-path'
  | 'invalid-operation'
  | 'step-limit'
  | 'depth-limit'
  | 'node-limit'
  | 'invalid-value';

export interface ConditionError {
  readonly code: ConditionErrorCode;
  readonly message: string;
  readonly offset?: number;
}

export interface ConditionLimits {
  readonly maxSourceLength?: number;
  readonly maxDepth?: number;
  readonly maxSteps?: number;
  readonly maxArrayLength?: number;
  readonly maxStringLength?: number;
  readonly maxTokens?: number;
  readonly maxNodes?: number;
}

export const DEFAULT_CONDITION_LIMITS: Required<ConditionLimits> = {
  maxSourceLength: 2_000,
  maxDepth: 32,
  maxSteps: 2_000,
  maxArrayLength: 64,
  maxStringLength: 4_000,
  maxTokens: 512,
  maxNodes: 256,
};

export function isConditionRecord(value: unknown): value is { readonly [key: string]: unknown } {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function isConditionValue(
  value: unknown,
  depth = 0,
  limits: ConditionLimits = DEFAULT_CONDITION_LIMITS,
  seen = new WeakSet<object>(),
): value is ConditionValue {
  const maxDepth = limits.maxDepth ?? DEFAULT_CONDITION_LIMITS.maxDepth;
  const maxStringLength = limits.maxStringLength ?? DEFAULT_CONDITION_LIMITS.maxStringLength;
  if (depth > maxDepth) return false;
  if (value === null || typeof value === 'boolean') return true;
  if (typeof value === 'string') return value.length <= maxStringLength;
  if (typeof value === 'number') return Number.isFinite(value);
  if (typeof value !== 'object' || seen.has(value)) return false;
  seen.add(value);
  if (Array.isArray(value)) {
    const valid = value.length <= (limits.maxArrayLength ?? DEFAULT_CONDITION_LIMITS.maxArrayLength)
      && value.every((item) => isConditionValue(item, depth + 1, limits, seen));
    seen.delete(value);
    return valid;
  }
  const valid = Object.keys(value).every((key) => (
    isSafePropertyKey(key) && isConditionValue((value as Record<string, unknown>)[key], depth + 1, limits, seen)
  ));
  seen.delete(value);
  return valid;
}

export function isSafePropertyKey(key: string): boolean {
  return key !== '__proto__' && key !== 'prototype' && key !== 'constructor';
}