import type { ApiProfile, OpenAiCompatibleApiConfig, VectorEndpointConfig } from '../integration/sillytavern-bridge.js';
import { button, element } from '../ui/dom.js';

/** 功能应用共用的设置行控件（标题 + 控件的两列卡片行）。 */

export interface SettingsApiProfileRowsOptions {
  /**
   * 是否在选择器下方显示「当前：模型 X · 端点」摘要。
   * 已经有独立数据面板的功能（如向量库）可以关掉，避免同一信息出现两遍。
   */
  readonly showCurrent?: boolean;
}

/**
 * 「使用配置」选择行 + 当前摘要：从 API 配置库中为某个功能挑选配置。
 * 配置库为空时显示指引文案。
 */
export function settingsApiProfileRows(
  profiles: readonly ApiProfile[],
  current: OpenAiCompatibleApiConfig | VectorEndpointConfig,
  onSelect: (profile: ApiProfile) => void,
  options: SettingsApiProfileRowsOptions = {},
): readonly HTMLElement[] {
  if (profiles.length === 0) {
    return [element('p', {
      className: 'phone-settings-hint',
      text: '配置库还是空的：到 设置 → API 配置 的「API 配置库」里填写并保存配置，然后回到这里选择。',
    })];
  }
  const knownProfile = profiles.find((profile) => profile.name === current.profileName);
  const hasManualConfig = Boolean(current.model || current.baseUrl);
  const optionList: (readonly [string, string])[] = [
    ['', '— 选择已保存的配置 —'],
    ...(!knownProfile && hasManualConfig ? [['__current__', '当前配置（未关联配置库）'] as const] : []),
    ...profiles.map((profile) => [profile.name, `${profile.name}（${profile.model || '未填模型'}）`] as const),
  ];
  const rows: HTMLElement[] = [
    settingsSelectRow('使用配置', optionList, knownProfile ? knownProfile.name : (hasManualConfig ? '__current__' : ''), (value) => {
      const profile = profiles.find((item) => item.name === value);
      if (profile) onSelect(profile);
    }),
  ];
  if (options.showCurrent === false) return rows;
  rows.push(element('p', {
    className: 'phone-settings-hint',
    text: hasManualConfig
      ? `当前：模型 ${current.model || '未填写'} · ${current.baseUrl || '官方地址'}`
      : '尚未选择配置。',
  }));
  return rows;
}

export interface SettingsSegmentedOption<T extends string> {
  readonly value: T;
  readonly label: string;
}

/**
 * 滑动分段选择：在两三个互斥选项之间滑动切换，选中项由滑块指示。
 *
 * 用于「二选一」的模式开关（例如召回方式）：比两个复选框更能表达互斥，
 * 也比下拉框更容易在手机窄屏上一眼看清当前选择。
 */
export function settingsSegmentedRow<T extends string>(
  label: string,
  options: readonly SettingsSegmentedOption<T>[],
  value: T,
  onChange: (value: T) => void,
): HTMLElement {
  const row = element('div', { className: 'phone-setting-control phone-segmented-control' });
  row.append(element('span', { className: 'phone-control-label', text: label }));
  const group = element('div', {
    className: 'phone-segmented',
    attributes: { role: 'radiogroup', 'aria-label': label },
  });
  const activeIndex = Math.max(0, options.findIndex((option) => option.value === value));
  const thumb = element('span', { className: 'phone-segmented-thumb', attributes: { 'aria-hidden': 'true' } });
  thumb.style.width = `calc((100% - 4px) / ${options.length})`;
  thumb.style.transform = `translateX(calc(${activeIndex} * 100%))`;
  group.append(thumb);
  options.forEach((option, index) => {
    const active = index === activeIndex;
    const item = button(option.label, `phone-segmented-item${active ? ' is-active' : ''}`, () => {
      if (option.value !== value) onChange(option.value);
    });
    item.setAttribute('role', 'radio');
    item.setAttribute('aria-checked', String(active));
    group.append(item);
  });
  row.append(group);
  return row;
}

export function settingsToggleRow(
  title: string,
  hint: string,
  checked: boolean,
  onChange: (checked: boolean) => void,
): HTMLElement {
  const row = element('label', { className: 'phone-checkbox-control' });
  const input = element('input', { attributes: { type: 'checkbox' } });
  input.checked = checked;
  input.addEventListener('change', () => onChange(input.checked));
  const copy = element('span');
  copy.append(element('strong', { text: title }), element('small', { text: hint }));
  row.append(input, copy);
  return row;
}

export function settingsTextRow(
  label: string,
  value: string,
  placeholder: string,
  onChange: (value: string) => void,
  secret = false,
): HTMLElement {
  const row = element('label', { className: 'phone-setting-control' });
  row.append(element('span', { className: 'phone-control-label', text: label }));
  const input = element('input', {
    className: 'phone-input',
    attributes: { type: secret ? 'password' : 'text', placeholder, autocomplete: 'off', spellcheck: 'false' },
  });
  input.value = value;
  input.addEventListener('change', () => onChange(input.value.trim()));
  row.append(input);
  return row;
}

export function settingsSelectRow(
  label: string,
  options: readonly (readonly [string, string])[],
  value: string,
  onChange: (value: string) => void,
): HTMLElement {
  const row = element('label', { className: 'phone-setting-control' });
  row.append(element('span', { className: 'phone-control-label', text: label }));
  const select = element('select', { className: 'phone-select' });
  for (const [optionValue, optionLabel] of options) {
    const option = element('option', { text: optionLabel, attributes: { value: optionValue } });
    option.selected = optionValue === value;
    select.append(option);
  }
  select.addEventListener('change', () => onChange(select.value));
  row.append(select);
  return row;
}

export function settingsNumberRow(
  label: string,
  value: number | null,
  min: number,
  max: number,
  step: number,
  onChange: (value: number | null) => void,
): HTMLElement {
  const row = element('label', { className: 'phone-setting-control' });
  row.append(element('span', { className: 'phone-control-label', text: label }));
  const input = element('input', {
    className: 'phone-number-input',
    attributes: { type: 'number', min: String(min), max: String(max), step: String(step), inputmode: 'decimal' },
  });
  input.value = value === null ? '' : String(value);
  input.addEventListener('change', () => {
    const raw = input.value.trim();
    if (!raw) {
      onChange(null);
      return;
    }
    const next = Number(raw);
    if (Number.isFinite(next)) onChange(Math.min(max, Math.max(min, next)));
  });
  row.append(input);
  return row;
}
