import { logOperationFailure } from '../core/diagnostics.js';

export interface AutoCardUpdaterApi {
  exportTableAsJson?: () => unknown | Promise<unknown>;
}

/** 外部数据库只用于桌面查看；不暴露 SQL 或写入能力。 */
export interface DatabaseApiInspection {
  readonly pluginDetected: boolean;
  readonly available: boolean;
  readonly reason: string;
}

export interface DatabaseTableSnapshot {
  readonly sheetKey: string;
  readonly name: string;
  readonly headers: readonly string[];
  readonly rows: readonly (readonly string[])[];
}

export interface DatabaseWriteResult {
  readonly ok: boolean;
  readonly message: string;
}

export interface DatabaseTablesSnapshot {
  readonly available: boolean;
  readonly reason: string;
  readonly tables: readonly DatabaseTableSnapshot[];
}

declare global {
  interface Window {
    AutoCardUpdaterAPI?: AutoCardUpdaterApi;
  }
}

function getDatabaseApi(): AutoCardUpdaterApi | null {
  return collectAccessibleWindows()
    .map((target) => target.AutoCardUpdaterAPI)
    .find((candidate): candidate is AutoCardUpdaterApi => Boolean(candidate && typeof candidate === 'object'))
    ?? null;
}

export function inspectDatabaseApi(): DatabaseApiInspection {
  const api = getDatabaseApi();
  const available = typeof api?.exportTableAsJson === 'function';
  return {
    pluginDetected: api !== null,
    available,
    reason: available
      ? '已连接外部数据库，仅查看当前表格内容。'
      : api ? '数据库读取接口尚未就绪。' : '未检测到外部数据库插件。',
  };
}

/**
 * 读取数据库当前聊天的全部表格数据。
 * 使用 exportTableAsJson，这是原生模式与 SQLite 模式都保证提供的通用读取接口。
 */
export async function getDatabaseTablesSnapshot(): Promise<DatabaseTablesSnapshot> {
  const api = getDatabaseApi();
  if (!api) {
    return { available: false, reason: '未找到数据库 API；请确认数据库插件已安装并启用。', tables: [] };
  }
  if (typeof api.exportTableAsJson !== 'function') {
    return { available: false, reason: '数据库 API 缺少 exportTableAsJson，可能仍在初始化。', tables: [] };
  }
  try {
    const raw = await Promise.resolve(api.exportTableAsJson());
    const tables = parseDatabaseTables(raw);
    return {
      available: true,
      reason: tables.length > 0 ? `已读取 ${tables.length} 张表。` : '数据库已连接，当前聊天暂无表格数据。',
      tables,
    };
  } catch (error) {
    logOperationFailure({ stage: '数据库表格读取', reason: describeDatabaseError(error), error });
    return { available: false, reason: `读取表格数据失败：${describeDatabaseError(error)}`, tables: [] };
  }
}

/** 将 exportTableAsJson 的返回结构解析为统一的表格快照。 */
export function parseDatabaseTables(raw: unknown): readonly DatabaseTableSnapshot[] {
  const record = asResultRecord(raw) as Record<string, unknown> | null;
  if (!record) return [];
  const tables: Array<DatabaseTableSnapshot & { readonly orderNo: number }> = [];
  for (const [sheetKey, value] of Object.entries(record)) {
    if (sheetKey === 'mate') continue;
    const sheet = asResultRecord(value) as Record<string, unknown> | null;
    if (!sheet) continue;
    const name = String(sheet.name ?? '').trim();
    const content = Array.isArray(sheet.content) ? sheet.content : null;
    if (!name || !content) continue;
    const grid = content.map((row) => (Array.isArray(row) ? row.map(formatSnapshotCell) : []));
    const headers = grid[0] ?? [];
    const orderNo = Number(sheet.orderNo);
    tables.push({
      sheetKey,
      name,
      headers,
      rows: grid.slice(1),
      orderNo: Number.isFinite(orderNo) ? orderNo : Number.MAX_SAFE_INTEGER,
    });
  }
  tables.sort((left, right) => left.orderNo - right.orderNo || left.name.localeCompare(right.name));
  return tables.map(({ sheetKey, name, headers, rows }) => ({ sheetKey, name, headers, rows }));
}

export function describeDatabaseError(error: unknown): string {
  const message = error instanceof Error ? error.message : String(error ?? '').trim();
  return message || '数据库操作失败。';
}

function collectAccessibleWindows(): readonly Window[] {
  if (typeof window === 'undefined') return [];
  const targets: Window[] = [];
  const pending: Window[] = [];
  const visited = new Set<Window>();

  const add = (candidate: Window | null | undefined): void => {
    try {
      if (!candidate || visited.has(candidate)) return;
      visited.add(candidate);
      targets.push(candidate);
      pending.push(candidate);
    } catch {
      // Cross-origin windows are intentionally ignored.
    }
  };

  add(window);
  for (let index = 0; index < pending.length; index += 1) {
    const target = pending[index];
    if (!target) continue;
    try {
      add(target.parent);
      add(target.top);
      for (let frameIndex = 0; frameIndex < target.frames.length; frameIndex += 1) {
        add(target.frames[frameIndex]);
      }
    } catch {
      // A cross-origin frame must not prevent discovery in accessible windows.
    }
  }
  return targets;
}

function formatSnapshotCell(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  try {
    return JSON.stringify(value);
  } catch {
    return String(value);
  }
}

function asResultRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}
