import type { SqliteMemoryStore, SheetRecord } from './memory-store.js';
import { ROW_ID_ALIAS } from './memory-store.js';
import type { DbStatement } from './protocol.js';
import { createSheetDdl, hashText, physicalTableName, prepareSheetRegistration, sheetColumnLabels, sheetColumnNames } from './sheet-dsl.js';
import { PRESET_SHEET_ID_PREFIX, presetSheetId, type SheetPresetBundle, type SheetPresetEntry, type SheetPresetImport } from './sheet-preset.js';
import { LEGACY_PRESET_ID, presetScopeFingerprint, presetScopeKey, sheetBackupPrefix, sheetIsActive, type PresetScopeState } from './preset-state.js';
import { dropSheetStatements, insertSheetRowsStatements, registerSheetStatements, writeSheetMetaStatement } from './sheet-transaction.js';

export interface PresetMaterializeOptions {
  readonly assertCurrent?: () => void;
  readonly presetId?: string;
  readonly knownPresets?: readonly SheetPresetBundle[];
  /** 保留旧调用方参数；未选中的实例现在归档保留。 */
  readonly prunePresetSheets?: boolean;
  readonly restoreDeleted?: boolean;
}

const sourceKey = (entry: SheetPresetEntry): string => entry.sourceKey || entry.name;
const sameColumns = (left: readonly string[], right: readonly string[]): boolean => left.length === right.length && left.every((item, i) => item === right[i]);

/** 静态规划、单事务提交；任何一张表失败，全部表及其归属保持原状。 */
export async function materializePreset(store: SqliteMemoryStore, scopeId: string, preset: SheetPresetImport, options: PresetMaterializeOptions) {
  options.assertCurrent?.();
  const presetId = options.presetId ?? 'default-import';
  const existing = await store.listSheets(scopeId, true);
  const previous = await store.readPresetState(scopeId);
  const owners = { ...previous.owners };
  const keys = { ...previous.keys };
  const definitions = { ...previous.definitions };
  const deleted = { ...previous.deleted };
  const hidden = new Set(previous.hidden);
  const statements: DbStatement[] = [];
  const skipped: string[] = [], rebuilt: string[] = [], pruned: string[] = [], updated: string[] = [];
  let createdSheets = 0, insertedRows = 0;
  const known = options.knownPresets ?? [{ id: presetId, name: presetId, sheets: preset.sheets }];

  for (const sheet of existing) {
    if (!sheet.id.startsWith(PRESET_SHEET_ID_PREFIX) || owners[sheet.id]) continue;
    const candidates = known.flatMap((bundle) => bundle.sheets.filter((entry) => entry.name === sheet.name
      && sameColumns(sheetColumnNames(sheet.ddl), entry.columns)).map((entry) => ({ bundle, entry })));
    const unique = candidates.length === 1 ? candidates[0] : undefined;
    owners[sheet.id] = unique?.bundle.id ?? LEGACY_PRESET_ID;
    keys[sheet.id] = unique ? sourceKey(unique.entry) : sheet.name;
  }
  if (options.knownPresets) {
    const knownIds = new Set([...known.map((bundle) => bundle.id), presetId, LEGACY_PRESET_ID]);
    for (const [id, owner] of Object.entries(owners)) if (!knownIds.has(owner)) owners[id] = LEGACY_PRESET_ID;
  }
  if (options.restoreDeleted) delete deleted[presetId];
  const tombstones = new Set(deleted[presetId] ?? []);
  const wanted = new Set(preset.sheets.map(sourceKey));
  for (const sheet of existing) {
    if (owners[sheet.id] !== presetId || presetId === LEGACY_PRESET_ID) continue;
    if (!wanted.has(keys[sheet.id] ?? sheet.name)) {
      hidden.add(sheet.id);
      pruned.push(sheet.name);
    }
  }

  for (const [index, entry] of preset.sheets.entries()) {
    const key = sourceKey(entry);
    if (tombstones.has(key)) { skipped.push(entry.name); continue; }
    const current = existing.find((sheet) => owners[sheet.id] === presetId && keys[sheet.id] === key);
    const id = current?.id ?? presetSheetId(scopeId, entry, presetId);
    owners[id] = presetId;
    keys[id] = key;
    hidden.delete(id);
    const fingerprint = hashText(JSON.stringify(entry));
    if (current && definitions[id] === fingerprint) { skipped.push(entry.name); continue; }
    const physicalName = current?.physicalName ?? physicalTableName(entry.name, id);
    const sheet = prepareSheetRegistration({ ...entry, id, scopeId, physicalName, orderNo: index,
      ddl: createSheetDdl(physicalName, entry.columns.map((name) => ({ name, type: 'TEXT' as const }))),
    });
    definitions[id] = fingerprint;
    if (!current) {
      statements.push(...registerSheetStatements(sheet), ...insertSheetRowsStatements(sheet, entry.columns, entry.rows, entry.rowIds));
      createdSheets += 1;
      insertedRows += entry.rows.length;
      continue;
    }
    const oldColumns = sheetColumnNames(current.ddl);
    if (sameColumns(oldColumns, entry.columns)) {
      statements.push(...registerSheetStatements(sheet).slice(1));
      updated.push(entry.name);
      skipped.push(entry.name);
      continue;
    }
    const oldRows = await store.readAllSheetRows(current);
    const rowIds = oldRows.map((row) => Number(row[ROW_ID_ALIAS]));
    const backup = { sheet: current, columns: oldColumns, rows: oldRows.map((row) => oldColumns.map((column) => String(row[column] ?? ''))), rowIds };
    statements.push(writeSheetMetaStatement(`${sheetBackupPrefix(scopeId)}${id}:${hashText(JSON.stringify(backup))}`, { ...backup, capturedAt: Date.now() }));
    const oldLabels = sheetColumnLabels(current.rowTemplate);
    const used = new Set<string>();
    const columnMap = entry.columns.map((column, i) => {
      if (oldColumns.includes(column)) { used.add(column); return column; }
      const label = entry.labels[i];
      const matches = oldColumns.filter((old) => !used.has(old) && oldLabels.get(old) === label);
      const match = label && matches.length === 1 ? matches[0] : undefined;
      if (match) used.add(match);
      return match;
    });
    const rows = oldRows.map((row) => entry.columns.map((_, i) => {
      const old = columnMap[i];
      return old ? String(row[old] ?? '') : (entry.rows.length === 1 ? entry.rows[0]?.[i] ?? '' : '');
    }));
    statements.push(...await store.planSnapshotColumns(current, entry.columns, columnMap, entry.rows.length === 1 ? entry.rows[0] : []));
    statements.push(...dropSheetStatements(current), ...registerSheetStatements(sheet), ...insertSheetRowsStatements(sheet, entry.columns, rows, rowIds));
    rebuilt.push(entry.name);
  }

  const state: PresetScopeState = { ...previous, activeId: presetId, owners, keys, definitions, deleted, hidden: [...hidden], updatedAt: Date.now() };
  const changed = presetScopeFingerprint(previous) !== presetScopeFingerprint(state);
  if (changed) statements.push(writeSheetMetaStatement(presetScopeKey(scopeId), state));
  // 清掉非活动实例的派生索引，防止它们占用检索候选名额。
  for (const id of Object.keys(owners)) if (!sheetIsActive(id, state)) statements.push({
    sql: 'DELETE FROM mem_doc WHERE scope_id = ? AND sheet_id = ?', params: [scopeId, id],
  });
  options.assertCurrent?.();
  await store.commitSheetPlan(statements);
  return { format: preset.format, createdSheets, insertedRows, skipped, rebuilt, pruned, updated, issues: preset.issues, changed: changed || statements.length > 0 };
}

export async function deletePresetSheet(store: SqliteMemoryStore, sheet: SheetRecord): Promise<void> {
  const state = await store.readPresetState(sheet.scopeId);
  const owner = state.owners[sheet.id];
  const key = state.keys[sheet.id] ?? sheet.name;
  const next: PresetScopeState = { ...state, updatedAt: Date.now(),
    deleted: owner ? { ...state.deleted, [owner]: [...new Set([...(state.deleted[owner] ?? []), key])] } : state.deleted,
  };
  await store.commitSheetPlan([...dropSheetStatements(sheet), writeSheetMetaStatement(presetScopeKey(sheet.scopeId), next)]);
}
