import type { PhoneViewContext } from '../app-types.js';
import type { PhonePost } from '../../domain/model.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import {
  renderAvatar,
  renderRichContent,
  richContextOf,
} from '../shared-view.js';
import { buildForumIndex, type ForumFloor, type ForumThreadView } from './projection.js';
import { forumAvatarProfile, forumIdentity, forumTime, renderThreadStats } from './shared.js';
import {
  forumDraft,
  forumReplyTarget,
  forumView,
  setForumDraft,
  setForumReplyTarget,
} from './view-state.js';

/** 吸底回复条的控制器：楼层里的「回复」按钮只改目标与焦点，不重建整页。 */
interface ForumComposer {
  readonly element: HTMLElement;
  readonly aimAt: (target: ForumFloor | null) => void;
}

export function renderForumDetail(context: PhoneViewContext, thread: PhonePost): HTMLElement {
  const index = buildForumIndex(context.state);
  const view = index.threads.find((item) => item.thread.id === thread.id);
  const page = element('div', { className: 'phone-page phone-forum-detail' });
  if (!view) return page;

  const composer = createComposer(context, view);
  page.append(renderArticle(context, view));
  page.append(renderFloorSection(context, view, composer));
  page.append(composer.element);
  return page;
}

function renderArticle(context: PhoneViewContext, view: ForumThreadView): HTMLElement {
  const article = element('article', { className: 'phone-forum-article' });
  const breadcrumb = element('div', { className: 'phone-forum-breadcrumb' });
  breadcrumb.append(
    element('span', { text: context.appTitle('论坛') }),
    element('span', { text: '›' }),
    element('strong', { text: view.board }),
  );
  article.append(breadcrumb);

  const titleRow = element('div', { className: 'phone-forum-detail-title-row' });
  if (view.pinned) titleRow.append(element('span', { className: 'phone-forum-flag is-pinned', text: '置顶' }));
  if (view.hot) titleRow.append(element('span', { className: 'phone-forum-flag is-hot', text: '热' }));
  titleRow.append(element('h1', { className: 'phone-forum-detail-title', text: view.title }));
  article.append(titleRow);

  const author = element('div', { className: 'phone-forum-detail-author' });
  const authorCopy = element('span', { className: 'phone-forum-author-copy' });
  authorCopy.append(
    element('strong', { text: forumIdentity(context, view.thread.profileId) }),
    element('small', { text: `${forumTime(view.thread.createdAt, view.thread.timeLabel)} · 1 楼（楼主）` }),
  );
  author.append(
    renderAvatar(forumAvatarProfile(context.state.profiles[view.thread.profileId]), 'phone-avatar phone-forum-avatar'),
    authorCopy,
  );
  author.append(renderForumDelete(context, view.thread.id, view.thread.content, '主题', () => {
    forumView.detailPostId = null;
    context.navigate(forumView.returnRoute);
  }));
  article.append(author);

  article.append(renderRichContent(view.thread.content, richContextOf(context), {
    className: 'phone-forum-detail-content',
    block: true,
  }));

  const tags = view.thread.tags ?? [];
  if (tags.length > 0) {
    const tagRow = element('div', { className: 'phone-forum-tag-row' });
    for (const tag of tags) tagRow.append(element('span', { className: 'phone-forum-topic-tag', text: tag }));
    article.append(tagRow);
  }

  const footer = element('div', { className: 'phone-forum-detail-stats' });
  footer.append(renderLikeButton(context, view), renderThreadStats(view, { showHeat: true }));
  article.append(footer);
  return article;
}

function renderLikeButton(context: PhoneViewContext, view: ForumThreadView): HTMLElement {
  const liked = Object.values(context.state.interactions).some((interaction) => interaction.appId === 'forum'
    && interaction.type === 'like'
    && interaction.actorProfileId === 'profile:self'
    && interaction.targetId === view.thread.id);
  const like = button('', `phone-forum-like-button${liked ? ' is-active' : ''}`, async () => {
    like.disabled = true;
    try {
      await context.commands.createUserInteraction('forum', 'like', view.thread.id);
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      like.disabled = false;
    }
  });
  like.disabled = liked;
  like.title = liked ? '你已经赞过这个主题' : '给这个主题点赞';
  like.setAttribute('aria-label', like.title);
  like.append(
    renderPhoneIcon('heart', 'phone-svg-icon phone-forum-like-icon'),
    element('span', { text: liked ? '已赞' : '点赞' }),
  );
  return like;
}

function renderFloorSection(
  context: PhoneViewContext,
  view: ForumThreadView,
  composer: ForumComposer,
): HTMLElement {
  const section = element('section', { className: 'phone-forum-comments' });
  const header = element('div', { className: 'phone-forum-comments-header' });
  header.append(
    element('h2', { text: `全部回复 ${view.replyCount}` }),
    element('span', { text: view.replyCount > 0 ? '按楼层顺序排列' : '等待第一条回复' }),
  );
  section.append(header);
  if (view.replyCount === 0) {
    section.append(element('div', { className: 'phone-forum-comments-empty', text: '还没有人回复，来抢 2 楼。' }));
    return section;
  }
  const list = element('div', { className: 'phone-forum-comment-list' });
  for (const floor of view.floors) appendFloor(context, list, floor, composer);
  section.append(list);
  return section;
}

/** 楼层树按 depth 缩进渲染：父楼在前，子楼紧随其后。 */
function appendFloor(
  context: PhoneViewContext,
  list: HTMLElement,
  floor: ForumFloor,
  composer: ForumComposer,
): void {
  list.append(renderFloor(context, floor, composer));
  for (const child of floor.children) appendFloor(context, list, child, composer);
}

function renderFloor(context: PhoneViewContext, floor: ForumFloor, composer: ForumComposer): HTMLElement {
  const card = element('article', { className: `phone-forum-comment is-depth-${floor.depth}` });
  const head = element('header', { className: 'phone-forum-comment-head' });
  const author = element('div', { className: 'phone-forum-comment-author' });
  const authorCopy = element('span', { className: 'phone-forum-author-copy' });
  authorCopy.append(
    element('strong', { text: forumIdentity(context, floor.profileId) }),
    element('small', { text: forumTime(floor.createdAt, floor.timeLabel) }),
  );
  author.append(
    renderAvatar(forumAvatarProfile(context.state.profiles[floor.profileId]), 'phone-avatar phone-forum-comment-avatar'),
    authorCopy,
  );
  const marks = element('span', { className: 'phone-forum-comment-marks' });
  if (floor.hot) marks.append(element('span', { className: 'phone-forum-flag is-hot', text: '热评' }));
  marks.append(element('span', { className: 'phone-forum-floor', text: `${floor.floor} 楼` }));
  head.append(author, marks);
  card.append(head);

  if (floor.parentProfileId) {
    card.append(element('div', {
      className: 'phone-forum-replying-to',
      text: `回复 @${forumIdentity(context, floor.parentProfileId)}`,
    }));
  }
  card.append(renderRichContent(floor.content, richContextOf(context), {
    className: 'phone-forum-comment-content',
    block: true,
  }));

  const footer = element('footer', { className: 'phone-forum-comment-footer' });
  footer.append(renderForumDelete(context, floor.id, floor.content, floor.entityType === 'post' ? '回复' : '评论', () => {
    context.navigate('forumPost');
  }));
  // 只有真实帖子楼层能当回复目标：互动评论没有独立帖子 id，挂不上楼中楼。
  if (floor.post) {
    footer.append(button('回复', 'phone-button phone-button-ghost', () => composer.aimAt(floor)));
  }
  card.append(footer);
  return card;
}

function renderForumDelete(
  context: PhoneViewContext,
  itemId: string,
  content: string,
  label: '主题' | '回复' | '评论',
  onDeleted: () => void,
): HTMLButtonElement {
  const remove = button('', 'phone-icon-button phone-post-delete phone-forum-delete-any', async () => {
    const confirmed = await context.showConfirm({
      title: `删除这条${label}？`,
      message: label === '主题'
        ? '主题、全部楼层、楼中楼、点赞和待生成任务都会一并删除，且不可撤销。'
        : `${label}及挂在它下面的楼中楼会一并删除，且不可撤销。`,
      detail: content.replace(/\s+/g, ' ').trim().slice(0, 180),
      confirmLabel: `删除${label}`,
      danger: true,
    });
    if (!confirmed) return;
    remove.disabled = true;
    try {
      await context.commands.deleteForumItem(itemId);
      onDeleted();
      context.showNotice(`${label}已删除`, 'success');
    } catch (error) {
      remove.disabled = false;
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
  });
  remove.append(renderPhoneIcon('trash'));
  remove.title = `删除${label}`;
  remove.setAttribute('aria-label', remove.title);
  return remove;
}

function createComposer(context: PhoneViewContext, view: ForumThreadView): ForumComposer {
  const threadId = view.thread.id;
  const composer = element('form', { className: 'phone-forum-reply-composer' });
  const input = element('textarea', {
    className: 'phone-forum-reply-input',
    attributes: { rows: '3', maxlength: '1200', placeholder: '写下你的回复……' },
  });
  input.value = forumDraft(threadId);
  input.addEventListener('input', () => setForumDraft(threadId, input.value));

  const hint = element('span', { className: 'phone-forum-reply-target', text: '回复主题' });
  const cancel = button('取消指定回复', 'phone-button phone-button-ghost phone-forum-reply-cancel', () => aimAt(null));
  const top = element('div', { className: 'phone-forum-reply-composer-top' });
  top.append(hint, cancel);

  const submit = button('', 'phone-forum-reply-send');
  submit.title = '发布回复';
  submit.setAttribute('aria-label', submit.title);
  submit.append(renderPhoneIcon('send', 'phone-svg-icon phone-forum-reply-send-icon'));
  const send = async () => {
    const content = input.value.trim();
    if (!content) return;
    input.disabled = true;
    submit.disabled = true;
    try {
      await context.commands.createUserPost('forum', 'forum-reply', content, {
        parentId: forumReplyTarget(threadId) ?? threadId,
        ...(view.thread.board ? { board: view.thread.board } : {}),
      });
      setForumDraft(threadId, '');
      setForumReplyTarget(threadId, null);
      input.value = '';
      context.showNotice('回复已发布，正在等待后续回应', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      input.disabled = false;
      submit.disabled = false;
    }
  };
  composer.addEventListener('submit', (event) => {
    event.preventDefault();
    void send();
  });
  submit.addEventListener('click', () => void send());
  // 发送键压在输入框右下角：长楼层里手指不用离开输入区就能发出去。
  const field = element('div', { className: 'phone-forum-reply-field' });
  field.append(input, submit);
  composer.append(top, field);

  const aimAt = (target: ForumFloor | null): void => {
    setForumReplyTarget(threadId, target?.post?.id ?? null);
    hint.textContent = target
      ? `回复 ${target.floor} 楼 · @${forumIdentity(context, target.profileId)}`
      : '回复主题';
    cancel.hidden = target === null;
    composer.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
    input.focus();
  };

  // 重新进入详情时恢复上次选定的楼层，草稿与回复目标保持一致。
  const restored = forumReplyTarget(threadId);
  const restoredFloor = restored ? findFloor(view.floors, restored) : null;
  if (restoredFloor) {
    hint.textContent = `回复 ${restoredFloor.floor} 楼 · @${forumIdentity(context, restoredFloor.profileId)}`;
    cancel.hidden = false;
  } else {
    if (restored) setForumReplyTarget(threadId, null);
    cancel.hidden = true;
  }

  return { element: composer, aimAt };
}

function findFloor(floors: readonly ForumFloor[], postId: string): ForumFloor | null {
  for (const floor of floors) {
    if (floor.post?.id === postId) return floor;
    const nested = findFloor(floor.children, postId);
    if (nested) return nested;
  }
  return null;
}