/**
 * 酒馆正文请求提示词日志。
 *
 * 只收录宿主原生的正文生成请求（普通回复、续写、重生成、滑动），
 * 手机插件自身的静默请求（Generate 类型 quiet）、扮演补全（impersonate）
 * 与仅用于算 token 的 dryRun 都会被拒绝，因此这里看到的结构等同于
 * 酒馆真正发给模型的那一份提示词。
 *
 * 日志只驻留内存：提示词体积大且含角色卡与世界书正文，不写入聊天存储。
 */

/** chat = OpenAI 兼容的 messages 数组；text = 文本补全拼好的单段提示词。 */
export type TavernPromptChannel = 'chat' | 'text';

export interface TavernPromptSegment {
  /** 在最终请求里的顺序，从 1 开始，便于与酒馆提示词管理器对照。 */
  readonly index: number;
  readonly role: string;
  /** 消息携带的说话人名（酒馆按角色卡/用户名填充），无则为空串。 */
  readonly name: string;
  readonly content: string;
  readonly chars: number;
  readonly truncated: boolean;
}

export interface TavernPromptLogEntry {
  readonly id: number;
  readonly timestamp: number;
  readonly channel: TavernPromptChannel;
  /** 宿主原始生成类型，空串表示普通正文回复。 */
  readonly generationType: string;
  readonly chatId: string;
  readonly segments: readonly TavernPromptSegment[];
  readonly totalChars: number;
  readonly truncated: boolean;
}

export interface TavernPromptCapture {
  readonly channel: TavernPromptChannel;
  readonly generationType: unknown;
  readonly dryRun: unknown;
  /** chat 通道传 messages 数组，text 通道传拼接后的提示词字符串。 */
  readonly payload: unknown;
  readonly chatId?: string;
}

const CAPACITY = 20;
const SEGMENT_LIMIT = 400;
const SEGMENT_CHAR_LIMIT = 40_000;
const ENTRY_CHAR_LIMIT = 240_000;

/** 非正文请求：静默生成（手机插件走的通道）与扮演补全都不属于正文提示词。 */
const NON_STORY_GENERATION_TYPES: readonly string[] = Object.freeze(['quiet', 'impersonate']);

const GENERATION_TYPE_LABELS: Readonly<Record<string, string>> = Object.freeze({
  '': '正文回复',
  normal: '正文回复',
  continue: '续写',
  regenerate: '重新生成',
  swipe: '滑动重生成',
  ask_command: '/ask 指令',
});

const CHANNEL_LABELS: Readonly<Record<TavernPromptChannel, string>> = Object.freeze({
  chat: '对话补全（messages）',
  text: '文本补全（单段提示词）',
});

export function normalizeGenerationType(value: unknown): string {
  return String(value ?? '').trim().toLowerCase();
}

export function isStoryGenerationType(value: unknown): boolean {
  return !NON_STORY_GENERATION_TYPES.includes(normalizeGenerationType(value));
}

export function describeGenerationType(generationType: string): string {
  return GENERATION_TYPE_LABELS[generationType] ?? generationType;
}

export function describeChannel(channel: TavernPromptChannel): string {
  return CHANNEL_LABELS[channel];
}

/** 多模态消息的 content 可能是分片数组；这里只取其中的文本部分。 */
function flattenContent(content: unknown): string {
  if (typeof content === 'string') return content;
  if (typeof content === 'number' || typeof content === 'boolean') return String(content);
  if (!Array.isArray(content)) return '';
  return content
    .map((part) => {
      if (typeof part === 'string') return part;
      if (!part || typeof part !== 'object') return '';
      const record = part as Record<string, unknown>;
      if (typeof record.text === 'string') return record.text;
      return typeof record.type === 'string' ? `[${record.type}]` : '';
    })
    .filter(Boolean)
    .join('\n');
}

function readSegments(capture: TavernPromptCapture): readonly TavernPromptSegment[] {
  if (capture.channel === 'text') {
    const prompt = typeof capture.payload === 'string' ? capture.payload : '';
    return prompt.trim() ? [rawSegment(1, 'prompt', '', prompt)] : [];
  }
  if (!Array.isArray(capture.payload)) return [];
  const segments: TavernPromptSegment[] = [];
  for (const message of capture.payload.slice(0, SEGMENT_LIMIT)) {
    if (!message || typeof message !== 'object') continue;
    const record = message as Record<string, unknown>;
    const content = flattenContent(record.content);
    const role = String(record.role ?? '').trim() || 'unknown';
    const name = String(record.name ?? '').trim();
    if (!content && !name) continue;
    segments.push(rawSegment(segments.length + 1, role, name, content));
  }
  return segments;
}

function rawSegment(index: number, role: string, name: string, content: string): TavernPromptSegment {
  const truncated = content.length > SEGMENT_CHAR_LIMIT;
  return {
    index,
    role,
    name,
    content: truncated ? content.slice(0, SEGMENT_CHAR_LIMIT) : content,
    chars: content.length,
    truncated,
  };
}

/** 超出单条预算时从尾部丢弃剩余段落，保证内存占用有上界。 */
function withinEntryBudget(
  segments: readonly TavernPromptSegment[],
): { readonly segments: readonly TavernPromptSegment[]; readonly truncated: boolean } {
  const kept: TavernPromptSegment[] = [];
  let used = 0;
  for (const segment of segments) {
    if (used + segment.content.length > ENTRY_CHAR_LIMIT) {
      return { segments: kept, truncated: true };
    }
    used += segment.content.length;
    kept.push(segment);
  }
  return { segments: kept, truncated: segments.some((segment) => segment.truncated) };
}

/**
 * 把宿主事件载荷整理成一条日志；不符合“正文请求”条件时返回 null。
 * 纯函数：不读全局状态、不写日志缓冲，便于单测覆盖过滤规则。
 */
export function buildTavernPromptEntry(
  capture: TavernPromptCapture,
  id: number,
  timestamp: number,
): TavernPromptLogEntry | null {
  if (capture.dryRun === true) return null;
  const generationType = normalizeGenerationType(capture.generationType);
  if (!isStoryGenerationType(generationType)) return null;
  const budgeted = withinEntryBudget(readSegments(capture));
  if (budgeted.segments.length === 0) return null;
  return {
    id,
    timestamp,
    channel: capture.channel,
    generationType,
    chatId: String(capture.chatId ?? ''),
    segments: budgeted.segments,
    totalChars: budgeted.segments.reduce((sum, segment) => sum + segment.chars, 0),
    truncated: budgeted.truncated,
  };
}

/** 导出/复制用的纯文本视图：与界面展示的分段结构一致。 */
export function formatTavernPromptEntryText(entry: TavernPromptLogEntry): string {
  const head = [
    `时间：${new Date(entry.timestamp).toLocaleString()}`,
    `请求类型：${describeGenerationType(entry.generationType)}`,
    `提示词通道：${describeChannel(entry.channel)}`,
    `段数：${entry.segments.length} · 总字符：${entry.totalChars}${entry.truncated ? '（已截断）' : ''}`,
    entry.chatId ? `聊天：${entry.chatId}` : '',
  ].filter(Boolean).join('\n');
  const body = entry.segments
    .map((segment) => [
      `── #${segment.index} ${segment.role}${segment.name ? ` · ${segment.name}` : ''} · ${segment.chars} 字符${segment.truncated ? '（已截断）' : ''} ──`,
      segment.content,
    ].join('\n'))
    .join('\n\n');
  return `${head}\n\n${body}\n`;
}

let nextId = 1;
let enabled = false;
const entries: TavernPromptLogEntry[] = [];

/**
 * 提示词日志缓冲：默认关闭，只有设置里启用后才记录；
 * 关闭时立即清空，避免界面显示上一次会话遗留的旧请求。
 */
export const tavernPromptLog = {
  setEnabled(value: boolean): void {
    if (enabled === value) return;
    enabled = value;
    if (!value) entries.length = 0;
  },
  isEnabled(): boolean {
    return enabled;
  },
  /** 记录一条正文请求；未启用或不符合过滤条件时返回 null。 */
  record(capture: TavernPromptCapture): TavernPromptLogEntry | null {
    if (!enabled) return null;
    const entry = buildTavernPromptEntry(capture, nextId, Date.now());
    if (!entry) return null;
    nextId += 1;
    entries.push(entry);
    if (entries.length > CAPACITY) entries.splice(0, entries.length - CAPACITY);
    return entry;
  },
  /** 按时间倒序返回，最新的请求排在最前面。 */
  entries(): readonly TavernPromptLogEntry[] {
    return [...entries].reverse();
  },
  find(id: number): TavernPromptLogEntry | null {
    return entries.find((entry) => entry.id === id) ?? null;
  },
  clear(): void {
    entries.length = 0;
  },
};
