/** 剧情时间戳 → 本地日期键（YYYY-MM-DD），与日历应用的节日键一致。 */
function formatDateKey(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/** 已配置生图素体的角色列表：@备注名（素体预览）。 */
function appearanceRoster(state: PhoneState): readonly string[] {
  return Object.values(state.profiles)
    .filter((profile) => (profile.appearancePrompt ?? '').trim().length > 0)
    .map((profile) => {
      const preview = (profile.appearancePrompt ?? '').trim().slice(0, 60);
      return `@${profile.displayName}（${preview}）`;
    });
}

/**
 * 生图指令：NovelAI 供应商输出 v4 多角色结构化格式（吸收 NAI4 世界书的提示词方法论），
 * 其他供应商输出简单的单串 Danbooru 标签格式。
 * 自定义标签与自定义绘图提示词从标记注册表读取，与识别侧共用同一数据源。
 */
function imageGenerationRules(imageProvider: string, roster: readonly string[] = []): readonly string[] {
  const marker = getCustomImageMarker();
  const markerSyntax = marker ? `image###...### 或 ${marker.start}...${marker.end}` : 'image###...###';
  const customPrompt = getCustomImagePrompt();
  const customRule = customPrompt ? [`自定义绘图要求（优先遵守）：${customPrompt}`] : [];
  const common = `角色想发照片时（聊天消息、朋友圈、论坛、推特动态都可以），在 content 中插入一个 ${markerSyntax} 标记，`
    + '标记前后可以写普通文字；每条内容最多一个标记；'
    + '照片内容必须是该角色此刻真实会拍到的画面（自拍、合照、食物、风景、宠物、屋内一角…），与剧情和当前时间地点一致；不要输出其他图片格式或链接。';
  const rosterRule = roster.length > 0
    ? ['以下角色已锁定生图素体（固定外貌）：' + roster.join('、') + '。'
      + '照片里出现这些角色时，在其提示词开头写 @备注名（原样保留中文名），系统会自动替换为该角色的完整素体 tag；'
      + '@引用之后只能追加服装、表情、动作、姿势等临时状态，严禁自行描写或更改这些角色的发色、瞳色、发型、体型等基础外貌。'
      + '未列出的角色才需要你自己写外貌 tag，且同一角色的外貌描写必须与之前的照片保持一致。']
    : [];
  if (imageProvider !== 'novelai') {
    return [common
      + '标记内为英文逗号分隔的 Danbooru 风格标签（人物特征、服装、动作、场景、光线、构图、氛围），'
      + '例如 image###1girl, brown hair, casual clothes, selfie, cafe interior, warm lighting, smile###。',
    ...rosterRule,
    ...customRule];
  }
  return [
    common,
    ...rosterRule,
    ...customRule,
    '生图标记内部使用 NAI 多角色结构化格式（英文 Danbooru 标签，标签间用英文逗号，段落间用英文分号）：'
      + 'image###Scene Composition:场景构图;Character 1 Prompt:角色1描述|centers:c3;Character 1 UC:角色1排除的负面tag;Character 2 Prompt:角色2描述|centers:d3;###。'
      + 'Scene Composition 按顺序写：人数构成（1girl / 2girls,1boy / 1milf…）、地点（cafe interior, bedroom, street…）、'
      + '时间与光照（morning / night, warm lighting, backlighting…）、镜头视角（selfie, upper body, from above, looking_at_viewer…）。'
      + 'Character N Prompt 按顺序写：发色发型、瞳色、体型、服装饰品、表情、姿势动作细节；照片里有几个人就写几个 Character，最多 4 个。',
    'NAI 生图细则：两人有肢体接触时，主动方写 {source#动作}、被动方写 {target#动作}（如 {source#hug} / {target#hug}），成对出现；'
      + 'centers 是九宫格位置（列 a~e × 行 1~5，c3 居中、b3 偏左、d3 偏右），双人常用 b3/d3，避免 a1、e5 等边缘位置，单人可省略；'
      + 'Character UC 用于排除该角色不该有的元素（可省略）；画面涉及裸露时在 Scene Composition 开头加 nsfw。'
      + '示例：image###Scene Composition:2girls,cafe interior,afternoon,warm lighting,upper body;'
      + 'Character 1 Prompt:long brown hair,brown eyes,casual hoodie,smile,peace sign,{source#hug}|centers:b3;'
      + 'Character 2 Prompt:short black hair,glasses,school uniform,embarrassed,{target#hug}|centers:d3;###',
  ];
}

function selectConversationHistory(
  state: PhoneState,
  conversationId: string,
  limit: number,
  summarizedUntil = 0,
  excludedMessageIds: ReadonlySet<string> = new Set(),
): readonly PhoneMessage[] {
  return state.messageOrder
    .slice()
    .reverse()
    .flatMap((id) => {
      const message = state.messages[id];
      if (!message || message.conversationId !== conversationId || excludedMessageIds.has(id)) return [];
      // 幕后指令不属于聊天记录，也不该被后续轮次反复执行。
      if (message.kind === 'directive') return [];
      // 已被总结覆盖的旧消息不再逐条注入（总结内容会以 phoneSummary 注入）。
      if (message.createdAt <= summarizedUntil) return [];
      return [message];
    })
    .reverse()
    .slice(-limit);
}

function referencedPostOf(state: PhoneState, post: PhonePost): PhonePost | undefined {
  const referenceId = post.parentId ?? post.targetId;
  return referenceId ? state.posts[referenceId] : undefined;
}

function formatPost(post: PhonePost, state: PhoneState, selfProfileId: string): Record<string, unknown> {
  const profile = state.profiles[post.profileId];
  const publicApp = post.appId === 'forum' || post.appId === 'twitter' ? post.appId : null;
  const publicName = profile && publicApp ? publicNameFor(profile, publicApp) : '匿名用户';
  return {
    id: post.id,
    appId: post.appId,
    kind: post.kind,
    ...(publicApp
      ? {
          authorName: publicName,
          isUserPost: post.profileId === selfProfileId,
        }
      : { actorProfileId: post.profileId }),
    ...(post.title ? { title: post.title } : {}),
    content: post.content,
    createdAt: formatWorldTime(post.createdAt),
    ...(post.parentId ? { parentId: post.parentId } : {}),
    ...(post.targetId ? { targetId: post.targetId } : {}),
  };
}

function formatMessage(message: PhoneMessage, state: PhoneState, selfProfileId: string): Record<string, unknown> {
  return {
    id: message.id,
    profileId: message.profileId,
    speaker: speakerNameOf(state, message.profileId),
    ...(message.profileId === selfProfileId ? { isUser: true } : {}),
    direction: message.direction,
    content: message.content,
    createdAt: formatWorldTime(message.createdAt),
    ...(message.kind ? { kind: message.kind } : {}),
    ...(message.metadata ? { metadata: message.metadata } : {}),
    ...(message.claimStatus ? { claimStatus: message.claimStatus } : {}),
  };
}