import { sheetSchemaLine, type SheetDefinition } from './sheet-dsl.js';

/**
 * 装配 recall pack 需要的表信息：`id` 与 `tokenBudget` 用于给固定记忆按表分配预算，
 * `rowTemplate` 用于在表结构行里带出中文列标签。
 */
export type RecallSchemaEntry = Pick<SheetDefinition, 'id' | 'name' | 'purpose' | 'ddl' | 'tokenBudget'>
  & { readonly rowTemplate?: string };

export interface RecallCandidate {
  readonly id: number | string;
  readonly text: string;
  readonly tokens?: number;
  readonly importance?: number;
  readonly pinned?: boolean | number;
  readonly updatedAt?: number;
  readonly ftsScore?: number;
  readonly ftsRank?: number;
  readonly vectorScore?: number;
  /** 来源表；固定记忆按表分预算时用它对齐 `tokenBudget`。 */
  readonly sheetId?: string;
}

export interface RecallPackInput {
  readonly schema: readonly RecallSchemaEntry[];
  readonly always: readonly RecallCandidate[];
  readonly recall: readonly RecallCandidate[];
  /** 召回段的 token 预算；表结构与固定记忆不吃这份预算。 */
  readonly totalTokenBudget: number;
  /**
   * 表结构 + 固定记忆的上限。省略表示不限量——这两段是「模型必须知道的当前状态」，
   * 被预算悄悄截掉的话，表还在库里、数据也在写，模型却看不见，等于整套表白建。
   * 只有调用方明确要限量时才传，此时才按各表的 `tokenBudget` 分配。
   */
  readonly fixedTokenBudget?: number;
  readonly now?: number;
  readonly tokenCounter?: (text: string) => number;
}

export interface RecallPack {
  readonly text: string;
  readonly schema: readonly string[];
  readonly always: readonly RecallCandidate[];
  readonly recall: readonly RecallCandidate[];
  readonly usedTokens: number;
  readonly truncated: boolean;
  /** 因为限量而没能进表结构段的表名；不限量时为空。 */
  readonly omittedSheets: readonly string[];
}

const SCHEMA_LABEL = '可用记忆表：';
const ALWAYS_LABEL = '固定记忆：';
const RECALL_LABEL = '召回记忆：';

/**
 * 表结构段的预算占比上限。
 * 表结构只说明"能查到什么"，真正有用的是数据行；不设上限时，表一多就会把固定记忆与召回记忆
 * 全部挤成空段，注入块退化成一份表名清单。
 */
const SCHEMA_BUDGET_RATIO = 0.35;
const SCHEMA_BUDGET_FLOOR = 64;
const MIN_SHEET_BUDGET = 16;

interface Section {
  readonly lines: readonly string[];
  readonly used: number;
  readonly truncated: boolean;
  readonly omitted: readonly string[];
}

function roughTokenCount(text: string): number {
  let ascii = 0;
  let other = 0;
  for (const char of text) {
    if (/\s|[\x00-\x7f]/.test(char)) ascii += 1;
    else other += 1;
  }
  return Math.max(1, Math.ceil(ascii / 4) + other);
}

function clamp(value: number, min = 0, max = 1): number {
  return Math.min(max, Math.max(min, Number.isFinite(value) ? value : min));
}

function scoreCandidate(candidate: RecallCandidate, now: number, rank: number): number {
  const fts = candidate.ftsRank === undefined
    ? (candidate.ftsScore === undefined ? 0 : clamp(1 / (1 + Math.abs(candidate.ftsScore))))
    : 1 / (1 + Math.max(0, candidate.ftsRank));
  const vector = clamp(candidate.vectorScore ?? 0, -1, 1) * 0.5 + 0.5;
  const importance = clamp(candidate.importance ?? 0);
  const pinned = candidate.pinned === true || candidate.pinned === 1 ? 1 : 0;
  const ageDays = candidate.updatedAt === undefined ? 365 : Math.max(0, (now - candidate.updatedAt) / 86_400_000);
  const recency = 1 / (1 + ageDays / 30);
  const rankPrior = 1 / (1 + rank);
  return fts * 0.38 + vector * 0.25 + importance * 0.15 + pinned * 0.14 + recency * 0.06 + rankPrior * 0.02;
}

function candidateText(candidate: RecallCandidate): string {
  return `- ${candidate.text.trim()}`;
}

function candidateTokens(candidate: RecallCandidate, tokenCounter: (text: string) => number): number {
  return Math.max(1, candidate.tokens ?? tokenCounter(candidateText(candidate)));
}

/** 段落用量含段标题：标题不计入会让预算统计系统性偏低。 */
function takeSection<T extends RecallCandidate>(
  label: string,
  candidates: readonly T[],
  budget: number,
  tokenCounter: (text: string) => number,
  perItemCap?: (candidate: T, tokens: number) => boolean,
): { readonly selected: readonly T[]; readonly used: number; readonly truncated: boolean } {
  const labelTokens = tokenCounter(label);
  if (candidates.length === 0) return { selected: [], used: 0, truncated: false };
  if (labelTokens >= budget) return { selected: [], used: 0, truncated: true };
  let used = labelTokens;
  let truncated = false;
  const selected: T[] = [];
  for (const candidate of candidates) {
    const tokens = candidateTokens(candidate, tokenCounter);
    if (used + tokens > budget || (perItemCap && !perItemCap(candidate, tokens))) {
      truncated = true;
      continue;
    }
    selected.push(candidate);
    used += tokens;
  }
  return selected.length === 0
    ? { selected, used: 0, truncated: true }
    : { selected, used, truncated };
}

function schemaBudgetOf(totalBudget: number): number {
  return Math.min(totalBudget, Math.max(SCHEMA_BUDGET_FLOOR, Math.trunc(totalBudget * SCHEMA_BUDGET_RATIO)));
}

/** 表结构段按行截断：装不下的表宁可不列，也不让它吃掉数据行的预算。 */
function takeSchemaSection(
  schema: readonly RecallSchemaEntry[],
  budget: number,
  tokenCounter: (text: string) => number,
): Section {
  if (schema.length === 0) return { lines: [], used: 0, truncated: false, omitted: [] };
  const labelTokens = tokenCounter(SCHEMA_LABEL);
  if (labelTokens >= budget) return { lines: [], used: 0, truncated: true, omitted: schema.map((sheet) => sheet.name) };
  let used = labelTokens;
  let truncated = false;
  const lines: string[] = [];
  const omitted: string[] = [];
  for (const sheet of schema) {
    const line = `- ${sheetSchemaLine(sheet)}`;
    const tokens = tokenCounter(line);
    if (used + tokens > budget) {
      truncated = true;
      omitted.push(sheet.name);
      continue;
    }
    lines.push(line);
    used += tokens;
  }
  return lines.length === 0
    ? { lines: [], used: 0, truncated: true, omitted: schema.map((sheet) => sheet.name) }
    : { lines, used, truncated, omitted };
}

/**
 * 固定记忆按表分配预算：`sheet.tokenBudget` 在这里生效，
 * 否则一张行数很多的 `always` 表会把整段预算吃光，其余表与召回记忆全部落空。
 */
function alwaysCapGuard(
  schema: readonly RecallSchemaEntry[],
): (candidate: RecallCandidate, tokens: number) => boolean {
  const caps = new Map(schema.map((sheet) => [sheet.id, Math.max(MIN_SHEET_BUDGET, Math.trunc(sheet.tokenBudget))]));
  const spent = new Map<string, number>();
  return (candidate, tokens) => {
    const key = candidate.sheetId ?? '';
    const cap = caps.get(key);
    if (cap === undefined) return true;
    const used = spent.get(key) ?? 0;
    if (used + tokens > cap) return false;
    spent.set(key, used + tokens);
    return true;
  };
}

function renderSection(label: string, lines: readonly string[]): string {
  return lines.length > 0 ? `\n${label}\n${lines.join('\n')}` : '';
}

export function buildRecallPack(input: RecallPackInput): RecallPack {
  const tokenCounter = input.tokenCounter ?? roughTokenCount;
  const recallBudget = Math.max(32, Math.trunc(input.totalTokenBudget));
  // 不传就是不限量：表结构与固定记忆是「模型必须看见的当前状态」，宁可长也不能悄悄少。
  const fixedBudget = input.fixedTokenBudget === undefined
    ? Number.POSITIVE_INFINITY
    : Math.max(64, Math.trunc(input.fixedTokenBudget));
  const limited = Number.isFinite(fixedBudget);
  const now = input.now ?? Date.now();

  const schemaSection = takeSchemaSection(input.schema, limited ? schemaBudgetOf(fixedBudget) : fixedBudget, tokenCounter);
  const afterSchema = limited ? Math.max(0, fixedBudget - schemaSection.used) : fixedBudget;

  const alwaysResult = takeSection(
    ALWAYS_LABEL,
    input.always,
    afterSchema,
    tokenCounter,
    // 按表分配只在明确限量时才做：不限量时每张 always 表都要完整注入。
    limited ? alwaysCapGuard(input.schema) : undefined,
  );

  const selectedAlwaysIds = new Set(alwaysResult.selected.map((candidate) => candidate.id));
  const scored = input.recall
    .filter((candidate) => !selectedAlwaysIds.has(candidate.id))
    .map((candidate, index) => ({ candidate, score: scoreCandidate(candidate, now, index) }))
    .sort((left, right) => right.score - left.score || String(left.candidate.id).localeCompare(String(right.candidate.id)));
  const recallResult = takeSection(RECALL_LABEL, scored.map((item) => item.candidate), recallBudget, tokenCounter);

  const text = [
    schemaSection.lines.length > 0 ? `${SCHEMA_LABEL}\n${schemaSection.lines.join('\n')}` : '',
    renderSection(ALWAYS_LABEL, alwaysResult.selected.map(candidateText)),
    renderSection(RECALL_LABEL, recallResult.selected.map(candidateText)),
  ].join('').trim();

  return {
    text,
    schema: schemaSection.lines,
    always: alwaysResult.selected,
    recall: recallResult.selected,
    usedTokens: schemaSection.used + alwaysResult.used + recallResult.used,
    truncated: schemaSection.truncated || alwaysResult.truncated || recallResult.truncated,
    omittedSheets: schemaSection.omitted,
  };
}