import {
  EXTENSION_MODULE_ID_PATTERN,
  EXTENSION_MODULE_MAX_ICON_BYTES,
  EXTENSION_MODULE_MAX_SOURCE_BYTES,
  EXTENSION_MODULE_PROTOCOL_VERSION,
  type ExtensionModuleBundle,
  type ExtensionModuleDefinition,
  type ExtensionModuleFactory,
  type ExtensionModuleManifest,
  type ExtensionModulePermission,
} from './module-contract.js';

const PERMISSIONS = new Set<ExtensionModulePermission>([
  'generation',
  'image',
  'worldBook',
  'phone.read',
  'wechat.read',
  'wechat.write',
  'calendar.read',
  'calendar.write',
  'pxx.read',
  'pxx.write',
  'memory.read',
  'memory.write',
  'vector.read',
  'vector.write',
  'variables.read',
  'variables.write',
  'database.read',
  'database.write',
  'floorTriggers',
  'moduleStorage',
]);

export interface ModuleValidationOptions {
  readonly sourceBytes?: number;
  readonly iconBytes?: number;
}

export function validateExtensionModuleManifest(
  value: unknown,
  options: ModuleValidationOptions = {},
): ExtensionModuleManifest {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('模块 manifest 必须是 JSON 对象。');
  const raw = value as Record<string, unknown>;
  const protocolVersion = Number(raw.protocolVersion);
  if (protocolVersion !== EXTENSION_MODULE_PROTOCOL_VERSION) {
    throw new Error(`模块协议版本不兼容：需要 ${EXTENSION_MODULE_PROTOCOL_VERSION}。`);
  }
  const id = String(raw.id ?? '').trim();
  if (!EXTENSION_MODULE_ID_PATTERN.test(id)) throw new Error('模块 id 只能使用小写字母、数字、点、下划线和短横线。');
  const name = String(raw.name ?? '').trim();
  if (!name || name.length > 40) throw new Error('模块名称不能为空且不能超过 40 个字符。');
  const version = String(raw.version ?? '').trim();
  if (!version || version.length > 32) throw new Error('模块版本不能为空且不能超过 32 个字符。');
  const author = String(raw.author ?? '').trim();
  if (!author || author.length > 80) throw new Error('模块作者不能为空且不能超过 80 个字符。');
  const entry = String(raw.entry ?? '').trim();
  const isJavaScriptEntry = entry !== 'self'
    && !entry.includes('/')
    && (entry.endsWith('.js') || entry.endsWith('.mjs'));
  if (!entry || (entry !== 'self' && !isJavaScriptEntry)) {
    throw new Error('模块 entry 必须填写 self，或填写当前单文件的 .js/.mjs 文件名。');
  }
  if (options.sourceBytes !== undefined && options.sourceBytes > EXTENSION_MODULE_MAX_SOURCE_BYTES) {
    throw new Error(`模块代码不能超过 ${EXTENSION_MODULE_MAX_SOURCE_BYTES} 字节。`);
  }
  const icon = raw.icon === undefined ? undefined : String(raw.icon);
  const iconBytes = icon ? new TextEncoder().encode(icon).byteLength : 0;
  if (iconBytes > EXTENSION_MODULE_MAX_ICON_BYTES || (options.iconBytes !== undefined && options.iconBytes > EXTENSION_MODULE_MAX_ICON_BYTES)) {
    throw new Error(`模块图标不能超过 ${EXTENSION_MODULE_MAX_ICON_BYTES} 字节。`);
  }
  if (icon && !isAllowedIcon(icon)) throw new Error('模块图标必须是 data:image/* 或 https 图片地址。');
  const permissions = normalizePermissions(raw.permissions);
  const description = raw.description === undefined ? undefined : String(raw.description).trim().slice(0, 400);
  return {
    protocolVersion,
    id,
    name,
    version,
    author,
    ...(description ? { description } : {}),
    ...(icon ? { icon } : {}),
    entry,
    ...(permissions.length > 0 ? { permissions } : {}),
    ...(isRecord(raw.api) ? { api: normalizeApiBinding(raw.api) } : {}),
    ...(isRecord(raw.generationContext) ? {
      generationContext: { includeStorage: raw.generationContext.includeStorage === true },
    } : {}),
  };
}

export async function readModuleFile(sourceFile: File): Promise<ExtensionModuleBundle> {
  if (!/\.(?:m?js)$/i.test(sourceFile.name)) throw new Error('请选择一个 .js 或 .mjs 模块文件。');
  const source = await sourceFile.text();
  const sourceBytes = new TextEncoder().encode(source).byteLength;
  if (sourceBytes > EXTENSION_MODULE_MAX_SOURCE_BYTES) {
    throw new Error(`模块代码不能超过 ${EXTENSION_MODULE_MAX_SOURCE_BYTES} 字节。`);
  }
  const imported = await importModuleSource(source);
  const manifestValue = imported.manifest
    ?? (isRecord(imported.default) ? imported.default.manifest : undefined);
  const manifest = validateExtensionModuleManifest(manifestValue, { sourceBytes });
  const factory = resolveFactory(imported);
  if (!factory) throw new Error('模块文件必须默认导出工厂函数，或导出 createModule 函数。');
  return { manifest, source, factory };
}

export async function loadModuleDefinition(
  bundle: ExtensionModuleBundle,
): Promise<ExtensionModuleFactory> {
  if (bundle.factory) return bundle.factory;
  return resolveFactory(await importModuleSource(bundle.source))
    ?? (() => { throw new Error('module.js 必须默认导出工厂函数，或导出 createModule 函数。'); })();
}

async function importModuleSource(source: string): Promise<Record<string, unknown>> {
  const url = URL.createObjectURL(new Blob([source], { type: 'text/javascript' }));
  try {
    return await import(/* @vite-ignore */ url) as Record<string, unknown>;
  } finally {
    URL.revokeObjectURL(url);
  }
}

function resolveFactory(imported: Record<string, unknown>): ExtensionModuleFactory | null {
  const factory = imported.default ?? imported.createModule;
  return typeof factory === 'function' ? factory as ExtensionModuleFactory : null;
}

export function validateModuleDefinition(
  manifest: ExtensionModuleManifest,
  value: unknown,
): ExtensionModuleDefinition {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('模块工厂必须返回定义对象。');
  const definition = value as Partial<ExtensionModuleDefinition>;
  if (definition.manifest?.id !== manifest.id) throw new Error('模块定义 manifest 与导入 manifest 的 id 不一致。');
  if (typeof definition.render !== 'function') throw new Error('模块定义缺少 render 函数。');
  const autoParse = validateAutoParseDefinition(definition.autoParse);
  return {
    manifest,
    render: definition.render,
    ...(autoParse ? { autoParse } : {}),
    ...(typeof definition.dispose === 'function' ? { dispose: definition.dispose } : {}),
  };
}

function validateAutoParseDefinition(value: unknown): ExtensionModuleDefinition['autoParse'] | undefined {
  if (value === undefined) return undefined;
  if (!isRecord(value)) throw new Error('模块 autoParse 必须是对象。');
  const description = String(value.description ?? '').trim().slice(0, 500);
  if (!description) throw new Error('模块 autoParse.description 不能为空。');
  if (!isRecord(value.schema)) throw new Error('模块 autoParse.schema 必须是 JSON Schema 对象。');
  const schemaText = JSON.stringify(value.schema);
  if (schemaText.length > 20_000) throw new Error('模块 autoParse.schema 不能超过 20KB。');
  if (typeof value.apply !== 'function') throw new Error('模块 autoParse.apply 必须是函数。');
  return {
    description,
    ...(typeof value.prompt === 'string' && value.prompt.trim() ? { prompt: value.prompt.trim() } : {}),
    schema: structuredClone(value.schema),
    ...(typeof value.parse === 'function' ? { parse: value.parse as (data: unknown) => unknown } : {}),
    ...(typeof value.validate === 'function' ? { validate: value.validate as (data: unknown) => boolean } : {}),
    apply: value.apply as NonNullable<ExtensionModuleDefinition['autoParse']>['apply'],
  };
}

function normalizePermissions(value: unknown): readonly ExtensionModulePermission[] {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.map((item) => String(item).trim()))]
    .filter((item): item is ExtensionModulePermission => PERMISSIONS.has(item as ExtensionModulePermission));
}

function normalizeApiBinding(value: Record<string, unknown>): ExtensionModuleManifest['api'] {
  const mode = value.mode === 'profile' || value.mode === 'custom' ? value.mode : 'shared';
  const profileName = String(value.profileName ?? '').trim().slice(0, 40);
  return {
    mode,
    ...(profileName ? { profileName } : {}),
    ...(isRecord(value.config) ? { config: value.config as ExtensionModuleManifest['api'] extends { config?: infer C } ? C : never } : {}),
  };
}

function isAllowedIcon(value: string): boolean {
  return value.startsWith('data:image/') || /^https:\/\/[^\s]+$/i.test(value);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value));
}