import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import { createConditionContext } from '../../conditions/context.js';
import { evaluateCondition, toConditionBoolean } from '../../conditions/evaluator.js';
import {
  CONDITION_RULE_LIMITS,
  evaluateConditionRule,
  normalizeConditionRule,
  type ConditionRule,
  type ConditionRuleTarget,
} from '../../conditions/rules.js';
import type { ConditionSnapshot } from '../../conditions/types.js';
import {
  createConditionSnapshotTree,
  filterConditionSnapshotTree,
  type ConditionSnapshotNode,
  type ConditionSnapshotTree,
} from '../../conditions/snapshot-view.js';
import {
  compileVisualCondition,
  createVisualConditionClause,
  readConditionEditorSource,
  type VisualConditionClause,
  type VisualConditionGroup,
  type VisualConditionOperator,
  type VisualConditionValueKind,
} from '../../conditions/visual-builder.js';
import { createId } from '../../domain/ids.js';
import { readVariables } from '../../integration/variables-bridge.js';
import { button, clear, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';

const TARGET_LABELS: Readonly<Record<ConditionRuleTarget, string>> = {
  prompt: '提示词片段',
  action: '生成动作',
  app: '应用范围',
  injection: '正文注入',
};

const TARGET_DESCRIPTIONS: Readonly<Record<ConditionRuleTarget, string>> = {
  prompt: '成立时追加系统提示词',
  action: '不成立时丢弃对应动作',
  app: '不成立时停用对应应用动作',
  injection: '不成立时跳过正文注入',
};

const TARGET_ICONS: Readonly<Record<ConditionRuleTarget, 'message' | 'send' | 'home' | 'edit'>> = {
  prompt: 'message',
  action: 'send',
  app: 'home',
  injection: 'edit',
};

const TARGET_OPTIONS: readonly (readonly [string, string])[] = [
  ['prompt', '提示词片段'],
  ['action', '生成动作'],
  ['app', '应用范围'],
  ['injection', '正文注入'],
];

const OPERATOR_OPTIONS: readonly (readonly [VisualConditionOperator, string])[] = [
  ['eq', '等于'],
  ['ne', '不等于'],
  ['gt', '大于'],
  ['gte', '大于或等于'],
  ['lt', '小于'],
  ['lte', '小于或等于'],
  ['contains', '包含'],
  ['in', '属于列表'],
  ['exists', '存在'],
  ['empty', '为空'],
];

const VALUE_KIND_OPTIONS: readonly (readonly [VisualConditionValueKind, string])[] = [
  ['string', '文字'],
  ['number', '数字'],
  ['boolean', '布尔值'],
  ['list', '列表'],
  ['path', '另一个路径'],
];

const SNAPSHOT_ROOT_LABELS: Readonly<Record<string, string>> = {
  state: '运行状态',
  variables: '变量',
  time: '剧情时间',
  apps: '应用状态',
  worldBook: '世界书',
  modules: '拓展数据',
};

const MAX_TEXT_PREVIEW = 180;
let draftExpression = '';

type RuleFilter = ConditionRuleTarget | 'all';
type RuleDisplayState = 'pass' | 'deny' | 'error' | 'off' | 'unknown';
interface ClauseDraft {
  path: string;
  operator: VisualConditionOperator;
  value: string;
  valueKind: VisualConditionValueKind;
}

export function createConditionsApp(): PhoneAppDefinition {
  return {
    id: 'conditions',
    label: '条件',
    icon: 'conditions',
    navigation: [],
    render: renderConditionsApp,
  };
}

function renderConditionsApp(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-conditions-page' });
  let snapshot: ConditionSnapshot | null = null;
  let snapshotTree: ConditionSnapshotTree | null = null;
  let pathFilter = '';
  let ruleFilter: RuleFilter = 'all';

  const heading = element('header', { className: 'phone-conditions-heading' });
  const overview = element('section', { className: 'phone-cond-overview' });
  const impact = element('section', { className: 'phone-cond-impact-section' });
  const editor = element('section', { className: 'phone-cond-editor', attributes: { hidden: 'true' } });
  const rulesSection = element('section', { className: 'phone-cond-section' });
  const tester = element('section', { className: 'phone-cond-section phone-cond-tester' });
  const snapshotSection = element('section', { className: 'phone-cond-section phone-cond-snapshot' });
  const statusLine = element('p', { className: 'phone-cond-status', text: '正在读取当前运行快照…' });
  const ruleList = element('div', { className: 'phone-cond-rule-list' });
  const snapshotBody = element('div', { className: 'phone-cond-snapshot-body' });
  const snapshotSearch = element('input', { className: 'phone-input phone-cond-search', attributes: { type: 'search', placeholder: '搜索路径或字段' } });
  snapshotSearch.addEventListener('input', () => {
    pathFilter = snapshotSearch.value.trim();
    renderSnapshot();
  });

  heading.append(
    element('span', { className: 'phone-kicker', text: 'AUTOMATION CONTROL' }),
    element('h2', { className: 'phone-section-title', text: '条件门控' }),
    element('p', { className: 'phone-settings-hint', text: '用条件决定哪些提示词、动作和应用可以参与当前一轮生成。先看结果，再按需展开细节。' }),
  );
  page.append(heading, overview, impact, editor, rulesSection, tester, snapshotSection);

  const rules = (): readonly ConditionRule[] => context.conditions.settings.rules;
  const saveRules = (next: readonly ConditionRule[]) => context.conditions.updateSettings({ rules: next });

  const statusMeta = (rule: ConditionRule): { state: RuleDisplayState; label: string; detail: string } => {
    if (!rule.enabled) return { state: 'off', label: '已停用', detail: '规则不会参与本轮判定' };
    if (!snapshot) return { state: 'unknown', label: '待检测', detail: '快照尚未就绪' };
    const result = evaluateConditionRule(rule, snapshot);
    return { state: result.state, label: result.state === 'pass' ? '成立' : result.state === 'deny' ? '不成立' : '求值失败', detail: result.detail };
  };

  const renderOverview = (): void => {
    clear(overview);
    const current = rules();
    const enabled = context.conditions.settings.enabled;
    const active = current.filter((rule) => rule.enabled);
    const states = active.map(statusMeta);
    const pass = states.filter((item) => item.state === 'pass').length;
    const deny = states.filter((item) => item.state === 'deny').length;
    const error = states.filter((item) => item.state === 'error').length;
    const hero = element('div', { className: `phone-cond-overview-card${enabled ? '' : ' is-disabled'}` });
    const heroCopy = element('div', { className: 'phone-cond-overview-copy' });
    heroCopy.append(
      element('span', { className: 'phone-cond-overview-eyebrow', text: enabled ? 'LIVE GATE' : 'GATE PAUSED' }),
      element('strong', { text: enabled ? '条件门控正在工作' : '条件门控已暂停' }),
      element('small', { text: enabled ? '启用中的规则会在生成链路中实时判定。' : '规则保留但不会影响提示词、动作或正文注入。' }),
    );
    const toggle = button(enabled ? '已启用' : '已停用', `phone-cond-toggle ${enabled ? 'is-on' : 'is-off'}`, async () => {
      await context.conditions.updateSettings({ enabled: !enabled });
      context.showNotice(!enabled ? '条件门控已启用。' : '条件门控已暂停。', 'success');
    });
    toggle.setAttribute('aria-pressed', String(enabled));
    hero.append(heroCopy, toggle);
    const metrics = element('div', { className: 'phone-cond-overview-metrics' });
    metrics.append(
      metricCard('规则', String(current.length), `${active.length} 条启用`, 'neutral'),
      metricCard('成立', String(pass), '当前会放行', 'pass'),
      metricCard('拦截', String(deny), '当前会拒绝', 'deny'),
      metricCard('异常', String(error), '需要检查表达式', 'error'),
    );
    overview.append(hero, metrics);
  };

  const metricCard = (label: string, value: string, hint: string, state: string): HTMLElement => {
    const card = element('div', { className: `phone-cond-metric is-${state}` });
    card.append(element('small', { text: label }), element('strong', { text: value }), element('span', { text: hint }));
    return card;
  };

  const renderImpact = (): void => {
    clear(impact);
    const title = element('div', { className: 'phone-cond-section-heading' });
    title.append(
      element('div', { className: 'phone-cond-section-title-copy' },),
    );
    const titleCopy = title.querySelector('.phone-cond-section-title-copy')!;
    titleCopy.append(element('span', { className: 'phone-cond-label', text: '规则作用范围' }), element('h3', { text: '你正在控制什么？' }));
    title.append(element('small', { text: '点击一类范围，只查看相关规则' }));
    impact.append(title);
    const grid = element('div', { className: 'phone-cond-impact-grid' });
    const targets: readonly (ConditionRuleTarget | 'all')[] = ['all', 'prompt', 'action', 'app', 'injection'];
    for (const target of targets) {
      const scoped = target === 'all' ? rules() : rules().filter((rule) => rule.target === target);
      const enabled = scoped.filter((rule) => rule.enabled).length;
      const states = scoped.filter((rule) => rule.enabled).map(statusMeta);
      const passes = states.filter((item) => item.state === 'pass').length;
      const blocked = states.filter((item) => item.state === 'deny').length;
      const label = target === 'all' ? '全部规则' : TARGET_LABELS[target];
      const card = button('', `phone-cond-impact-card${ruleFilter === target ? ' is-selected' : ''}`, () => {
        ruleFilter = target;
        renderImpact();
        renderRules();
      });
      card.setAttribute('aria-pressed', String(ruleFilter === target));
      const icon = element('span', { className: `phone-cond-impact-icon is-${target}` });
      if (target === 'all') icon.append(renderPhoneIcon('conditions', 'phone-svg-icon'));
      else icon.append(renderPhoneIcon(TARGET_ICONS[target], 'phone-svg-icon'));
      const copy = element('span', { className: 'phone-cond-impact-copy' });
      copy.append(element('strong', { text: label }), element('small', { text: target === 'all' ? '所有控制点' : TARGET_DESCRIPTIONS[target] }));
      const count = element('span', { className: 'phone-cond-impact-count' });
      count.append(element('b', { text: String(scoped.length) }), element('small', { text: `${enabled} 启用` }));
      const footer = element('span', { className: 'phone-cond-impact-footer' });
      footer.append(element('span', { className: 'is-pass', text: `${passes} 成立` }), element('span', { className: 'is-deny', text: `${blocked} 拦截` }));
      card.append(icon, copy, count, footer);
      grid.append(card);
    }
    impact.append(grid);
  };

  const renderRules = (): void => {
    clear(rulesSection);
    const current = ruleFilter === 'all' ? rules() : rules().filter((rule) => rule.target === ruleFilter);
    const headingRow = element('div', { className: 'phone-cond-section-heading' });
    const copy = element('div', { className: 'phone-cond-section-title-copy' });
    copy.append(element('span', { className: 'phone-cond-label', text: '规则库' }), element('h3', { text: ruleFilter === 'all' ? '门控规则' : TARGET_LABELS[ruleFilter] }));
    headingRow.append(copy, element('span', { className: 'phone-cond-count-label', text: `${current.length} 条` }));
    const actions = element('div', { className: 'phone-cond-section-actions' });
    actions.append(
      button('新增规则', 'phone-button phone-button-primary phone-button-compact', () => openRuleEditor()),
      button('从测试台保存', 'phone-button phone-button-secondary phone-button-compact', () => openRuleEditor(undefined, draftExpression)),
    );
    rulesSection.append(headingRow, actions, ruleList);
    clear(ruleList);
    if (current.length === 0) {
      const empty = element('div', { className: 'phone-cond-empty' });
      empty.append(renderPhoneIcon('conditions', 'phone-cond-empty-icon'), element('strong', { text: ruleFilter === 'all' ? '还没有门控规则' : '这个作用范围还没有规则' }), element('span', { text: '从新增规则开始，或在测试台写好条件后保存。' }));
      ruleList.append(empty);
      return;
    }
    for (const rule of current) ruleList.append(renderRuleCard(rule));
  };

  const renderRuleCard = (rule: ConditionRule): HTMLElement => {
    const meta = statusMeta(rule);
    const card = element('article', { className: `phone-cond-rule-card is-${meta.state}` });
    const top = element('div', { className: 'phone-cond-rule-top' });
    const target = element('span', { className: `phone-cond-target is-${rule.target}` });
    target.append(renderPhoneIcon(TARGET_ICONS[rule.target], 'phone-svg-icon'), element('span', { text: TARGET_LABELS[rule.target] }));
    const state = element('span', { className: `phone-cond-status-pill is-${meta.state}`, text: meta.label });
    const name = element('div', { className: 'phone-cond-rule-name' });
    name.append(element('strong', { text: rule.name }), target);
    top.append(name, state);
    const condition = element('div', { className: 'phone-cond-rule-condition' });
    condition.append(element('code', { text: rule.condition.length > MAX_TEXT_PREVIEW ? `${rule.condition.slice(0, MAX_TEXT_PREVIEW)}…` : rule.condition }), element('small', { text: meta.detail }));
    const controls = element('div', { className: 'phone-cond-rule-controls' });
    const toggle = button(rule.enabled ? '停用' : '启用', 'phone-button phone-button-secondary phone-button-compact', async () => {
      await saveRules(rules().map((item) => item.id === rule.id ? { ...item, enabled: !item.enabled } : item));
    });
    controls.append(toggle, button('编辑', 'phone-button phone-button-secondary phone-button-compact', () => openRuleEditor(rule)));
    const more = element('details', { className: 'phone-cond-rule-more' });
    const summary = element('summary', { text: '查看详情' });
    const details = element('div', { className: 'phone-cond-rule-details' });
    details.append(
      detailLine('控制说明', TARGET_DESCRIPTIONS[rule.target]),
      detailLine(rule.target === 'action' || rule.target === 'app' ? '目标标识' : '失败策略', rule.target === 'action' || rule.target === 'app' ? rule.selector || '全部' : rule.onError === 'allow' ? '出错时放行' : '出错时拒绝'),
    );
    if (rule.target === 'prompt') details.append(detailLine('追加片段', rule.text));
    details.append(detailLine('完整表达式', rule.condition, true));
    details.append(button('载入测试台', 'phone-button phone-button-secondary phone-button-compact', () => {
      draftExpression = rule.condition;
      renderTester();
      tester.scrollIntoView({ behavior: 'smooth', block: 'center' });
    }));
    details.append(button('删除规则', 'phone-button phone-button-danger-ghost phone-button-compact', async () => {
      const confirmed = await context.showConfirm({
        title: '删除条件规则',
        message: '删除后该规则将不再参与门控，且无法恢复。',
        detail: `${rule.name}\n${rule.condition}`,
        confirmLabel: '删除',
        danger: true,
      });
      if (!confirmed) return;
      await saveRules(rules().filter((item) => item.id !== rule.id));
      context.showNotice('规则已删除。', 'success');
    }));
    more.append(summary, details);
    card.append(top, condition, controls, more);
    return card;
  };

  const detailLine = (label: string, value: string, code = false): HTMLElement => {
    const row = element('div', { className: 'phone-cond-detail-line' });
    row.append(element('small', { text: label }), element(code ? 'code' : 'span', { text: value.length > 500 ? `${value.slice(0, 500)}…` : value }));
    return row;
  };

  const renderTester = (): void => {
    clear(tester);
    const headingRow = element('div', { className: 'phone-cond-section-heading' });
    const copy = element('div', { className: 'phone-cond-section-title-copy' });
    copy.append(element('span', { className: 'phone-cond-label', text: 'SAFE PLAYGROUND' }), element('h3', { text: '条件测试台' }));
    headingRow.append(copy, element('small', { text: '只读求值，不会写入变量或触发动作' }));
    const body = element('div', { className: 'phone-cond-tester-body' });
    const expressionInput = element('textarea', { className: 'phone-textarea phone-cond-input', attributes: { rows: '3', placeholder: '例如：variables.好感度 >= 60 and apps.wechat.enabled == true' } });
    expressionInput.value = draftExpression;
    expressionInput.addEventListener('input', () => { draftExpression = expressionInput.value; });
    const quick = element('div', { className: 'phone-cond-quick-row' });
    quick.append(element('span', { text: '快速插入' }));
    for (const path of ['variables', 'time', 'apps', 'worldBook', 'state']) {
      quick.append(button(path, 'phone-cond-token', () => {
        const next = expressionInput.value.trimEnd();
        expressionInput.value = next ? `${next} ${path}.` : `${path}.`;
        draftExpression = expressionInput.value;
        expressionInput.focus();
      }));
    }
    const result = element('div', { className: 'phone-cond-test-result is-idle' });
    result.append(renderPhoneIcon('conditions', 'phone-svg-icon'), element('span', { text: '输入表达式后运行测试。' }));
    const actions = element('div', { className: 'phone-cond-tester-actions' });
    actions.append(
      button('运行测试', 'phone-button phone-button-primary phone-button-compact', () => {
        const source = expressionInput.value.trim();
        if (!snapshot) {
          setTestResult(result, 'error', '当前快照还未准备好，请先刷新快照。');
          return;
        }
        if (!source) {
          setTestResult(result, 'error', '请先输入条件表达式。');
          return;
        }
        const evaluated = evaluateCondition(source, snapshot);
        if (!evaluated.ok) {
          setTestResult(result, 'error', `表达式无法求值：${evaluated.error?.message ?? '未知错误'}`);
          return;
        }
        const passed = toConditionBoolean(evaluated.value);
        setTestResult(result, passed ? 'pass' : 'deny', `${passed ? '成立，条件会放行' : '不成立，条件会拦截'} · 返回 ${formatValue(evaluated.value)} · 求值 ${evaluated.steps} 步`);
      }),
      button('保存为规则', 'phone-button phone-button-secondary phone-button-compact', () => openRuleEditor(undefined, expressionInput.value)),
      button('清空', 'phone-button phone-button-secondary phone-button-compact', () => {
        expressionInput.value = '';
        draftExpression = '';
        setTestResult(result, 'idle', '输入表达式后运行测试。');
      }),
    );
    body.append(expressionInput, quick, result, actions);
    tester.append(headingRow, body);
  };

  const setTestResult = (result: HTMLElement, state: 'idle' | 'pass' | 'deny' | 'error', text: string): void => {
    result.className = `phone-cond-test-result is-${state}`;
    clear(result);
    const icon = state === 'pass' ? 'check' : state === 'deny' ? 'close' : state === 'error' ? 'alert' : 'conditions';
    result.append(renderPhoneIcon(icon as Parameters<typeof renderPhoneIcon>[0], 'phone-svg-icon'), element('span', { text }));
  };

  const renderSnapshot = (): void => {
    clear(snapshotSection);
    const headingRow = element('div', { className: 'phone-cond-section-heading phone-cond-snapshot-heading' });
    const copy = element('div', { className: 'phone-cond-section-title-copy' });
    copy.append(element('span', { className: 'phone-cond-label', text: 'READ-ONLY CONTEXT' }), element('h3', { text: '当前条件快照' }));
    const snapshotActions = element('div', { className: 'phone-cond-snapshot-actions' });
    snapshotActions.append(snapshotSearch, button('刷新', 'phone-button phone-button-secondary phone-button-compact', () => load()));
    headingRow.append(copy, snapshotActions);
    const hint = element('p', { className: 'phone-cond-snapshot-hint', text: snapshotTree ? `${snapshotTree.totalNodes} 个节点 · ${snapshotTree.totalValues} 个值 · 点击叶节点可插入路径` : '快照尚未就绪' });
    snapshotSection.append(headingRow, hint, snapshotBody);
    clear(snapshotBody);
    if (!snapshotTree) {
      snapshotBody.append(element('div', { className: 'phone-cond-loading', text: '正在整理状态、变量和应用摘要…' }));
      return;
    }
    const filtered = filterConditionSnapshotTree(snapshotTree, pathFilter);
    if (filtered.children.length === 0) {
      snapshotBody.append(element('div', { className: 'phone-cond-empty', text: '没有匹配的路径。' }));
      return;
    }
    const grid = element('div', { className: 'phone-cond-snapshot-grid' });
    for (const node of filtered.children) grid.append(renderSnapshotNode(node, 0));
    snapshotBody.append(grid);
  };

  const renderSnapshotNode = (node: ConditionSnapshotNode, depth: number): HTMLElement => {
    if (!node.expandable) {
      const leaf = button('', 'phone-cond-snapshot-leaf', () => insertPath(node.path));
      leaf.title = '点击插入测试台';
      leaf.append(element('code', { text: node.path }), element('span', { text: node.preview }));
      return leaf;
    }
    const disclosure = element('details', { className: `phone-cond-snapshot-node is-${node.kind}` });
    disclosure.open = Boolean(pathFilter);
    const summary = element('summary');
    const label = SNAPSHOT_ROOT_LABELS[node.key] ?? node.key;
    summary.append(element('strong', { text: label }), element('span', { className: 'phone-cond-snapshot-preview', text: node.preview }), element('b', { text: String(node.count) }));
    const children = element('div', { className: 'phone-cond-snapshot-children' });
    for (const child of node.children) children.append(renderSnapshotNode(child, depth + 1));
    disclosure.append(summary, children);
    return disclosure;
  };

  const insertPath = (path: string): void => {
    const next = draftExpression.trimEnd();
    draftExpression = next ? `${next} ${path}` : path;
    renderTester();
    tester.scrollIntoView({ behavior: 'smooth', block: 'center' });
  };

  const openRuleEditor = (existing?: ConditionRule, presetCondition = ''): void => {
    clear(editor);
    editor.hidden = false;
    const source = existing?.condition ?? presetCondition.trim();
    const editorSource = readConditionEditorSource(source);
    let mode: 'visual' | 'advanced' = editorSource.mode;
    let join: 'and' | 'or' = 'and';
    let clauses: ClauseDraft[] = [];
    if (editorSource.mode === 'visual') {
      const flat = flattenVisualSource(editorSource.node);
      if (flat) {
        join = flat.join;
        clauses = flat.clauses.map((clause) => ({ ...clause }));
      } else {
        mode = 'advanced';
      }
    }
    if (clauses.length === 0) clauses = [{ ...createVisualConditionClause() }];
    const panel = element('div', { className: 'phone-cond-editor-panel' });
    const title = element('div', { className: 'phone-cond-editor-title' });
    title.append(element('span', { className: 'phone-cond-label', text: existing ? 'EDIT RULE' : 'NEW RULE' }), element('h3', { text: existing ? '编辑门控规则' : '创建门控规则' }), element('small', { text: mode === 'visual' ? '可视化模式：按行拼出条件' : '高级模式：保留原始 DSL' }));
    const close = button('关闭', 'phone-button phone-button-secondary phone-button-compact', () => { editor.hidden = true; });
    title.append(close);
    const form = element('form', { className: 'phone-cond-editor-form' });
    const basicGrid = element('div', { className: 'phone-cond-editor-grid' });
    const nameInput = fieldInput('规则名称', existing?.name ?? '', '例如：好感度达到阈值');
    const targetSelect = fieldSelect('作用范围', TARGET_OPTIONS, existing?.target ?? 'prompt');
    const selectorInput = fieldInput('目标标识', existing?.selector ?? '*', '动作类型 / 应用 id / *');
    const textInput = fieldTextarea('成立时追加内容', existing?.text ?? '', '只对“提示词片段”生效');
    basicGrid.append(nameInput.row, targetSelect.row, selectorInput.row, textInput.row);
    const visualPanel = element('div', { className: 'phone-cond-visual-editor' });
    const modeSelect = fieldSelect('条件编辑方式', [['visual', '可视化条件'], ['advanced', '高级表达式']], mode);
    const joinSelect = fieldSelect('条件之间', [['and', '全部满足（AND）'], ['or', '任一满足（OR）']], join);
    const clauseRows = element('div', { className: 'phone-cond-clause-list' });
    const advancedInput = element('textarea', { className: 'phone-textarea phone-cond-advanced-input', attributes: { rows: '5', placeholder: '例如：variables.好感度 >= 60 and apps.wechat.enabled == true' } });
    advancedInput.value = source;
    const addClause = button('添加条件', 'phone-button phone-button-secondary phone-button-compact', () => {
      clauses.push({ ...createVisualConditionClause() });
      renderClauses();
    });
    const strategySelect = fieldSelect('表达式求值失败时', [['deny', '拒绝（安全默认）'], ['allow', '放行（谨慎使用）']], existing?.onError ?? 'deny');
    const preview = element('div', { className: 'phone-cond-editor-preview' });
    const footer = element('div', { className: 'phone-cond-editor-footer' });
    const cancel = button('取消', 'phone-button phone-button-secondary phone-button-compact', () => { editor.hidden = true; });
    const save = button(existing ? '保存修改' : '创建规则', 'phone-button phone-button-primary phone-button-compact', async () => {
      let condition = advancedInput.value.trim();
      if (mode === 'visual') {
        const node: VisualConditionGroup = {
          kind: 'group',
          join,
          items: clauses.map((clause) => ({ kind: 'clause', ...clause })),
        };
        try {
          condition = compileVisualCondition(node);
        } catch (error) {
          context.showNotice(error instanceof Error ? error.message : String(error), 'error');
          return;
        }
      }
      const draft = normalizeConditionRule({
        id: existing?.id ?? createId(),
        name: nameInput.control.value,
        target: targetSelect.control.value,
        selector: selectorInput.control.value,
        text: textInput.control.value,
        condition,
        onError: strategySelect.control.value,
        enabled: existing?.enabled ?? true,
      }, existing?.id ?? createId());
      if (!draft) {
        context.showNotice('请补全规则名称、条件；提示词片段还需要填写追加内容。', 'error');
        return;
      }
      const parsed = snapshot ? evaluateCondition(draft.condition, snapshot) : null;
      if (parsed && !parsed.ok && parsed.error?.code === 'parse') {
        context.showNotice(`表达式无法解析：${parsed.error.message}`, 'error');
        return;
      }
      const next = existing ? rules().map((item) => item.id === existing.id ? draft : item) : [...rules(), draft];
      if (next.length > CONDITION_RULE_LIMITS.maxRules) {
        context.showNotice(`规则数量不能超过 ${CONDITION_RULE_LIMITS.maxRules} 条。`, 'error');
        return;
      }
      await saveRules(next);
      editor.hidden = true;
      context.showNotice(existing ? '规则已更新。' : '规则已创建。', 'success');
    });
    footer.append(cancel, save);

    const syncVisibility = (): void => {
      const isVisual = mode === 'visual';
      visualPanel.classList.toggle('is-advanced', !isVisual);
      joinSelect.row.hidden = !isVisual;
      clauseRows.hidden = !isVisual;
      addClause.hidden = !isVisual;
      advancedInput.hidden = isVisual;
      advancedInput.value = isVisual && !advancedInput.value.trim() ? compileClauses() : advancedInput.value;
      selectorInput.row.hidden = targetSelect.control.value !== 'action' && targetSelect.control.value !== 'app';
      textInput.row.hidden = targetSelect.control.value !== 'prompt';
      renderPreview();
    };
    const compileClauses = (): string => {
      try {
        return compileVisualCondition({ kind: 'group', join, items: clauses.map((clause) => ({ kind: 'clause', ...clause })) });
      } catch {
        return '等待补全条件…';
      }
    };
    const renderPreview = (): void => {
      clear(preview);
      preview.append(element('small', { text: '将保存为' }), element('code', { text: mode === 'visual' ? compileClauses() : advancedInput.value.trim() || '未填写表达式' }));
    };
    const renderClauses = (): void => {
      clear(clauseRows);
      clauses.forEach((clause, index) => {
        const row = element('div', { className: 'phone-cond-clause-row' });
        const path = element('input', { className: 'phone-input phone-cond-clause-path', attributes: { placeholder: 'variables.好感度' } });
        path.value = clause.path;
        path.addEventListener('input', () => { clause.path = path.value; renderPreview(); });
        const operator = element('select', { className: 'phone-select phone-cond-clause-operator' });
        appendOptions(operator, OPERATOR_OPTIONS, clause.operator);
        const valueKind = element('select', { className: 'phone-select phone-cond-clause-kind' });
        appendOptions(valueKind, VALUE_KIND_OPTIONS, clause.valueKind);
        const value = element('input', { className: 'phone-input phone-cond-clause-value', attributes: { placeholder: '60、true 或文字' } });
        value.value = clause.value;
        const remove = button('删除', 'phone-button phone-button-danger-ghost phone-button-compact', () => {
          if (clauses.length === 1) return;
          clauses.splice(index, 1);
          renderClauses();
        });
        const updateValueVisibility = (): void => {
          clause.operator = operator.value as VisualConditionOperator;
          clause.valueKind = valueKind.value as VisualConditionValueKind;
          value.hidden = clause.operator === 'exists' || clause.operator === 'empty';
          valueKind.hidden = value.hidden;
          if (clause.operator === 'in') {
            clause.valueKind = 'list';
            valueKind.value = 'list';
            valueKind.hidden = true;
          }
          renderPreview();
        };
        operator.addEventListener('change', updateValueVisibility);
        valueKind.addEventListener('change', updateValueVisibility);
        value.addEventListener('input', () => { clause.value = value.value; renderPreview(); });
        row.append(path, operator, valueKind, value, remove);
        clauseRows.append(row);
        updateValueVisibility();
      });
    };
    modeSelect.control.addEventListener('change', () => {
      const requested = modeSelect.control.value as 'visual' | 'advanced';
      if (requested === 'visual') {
        const parsed = readConditionEditorSource(advancedInput.value);
        if (parsed.mode !== 'visual') {
          modeSelect.control.value = 'advanced';
          context.showNotice('这条表达式包含高级语法，已保留高级模式，未修改原文。', 'info');
          return;
        }
        const flat = flattenVisualSource(parsed.node);
        if (!flat) {
          modeSelect.control.value = 'advanced';
          context.showNotice('这条表达式无法安全转换为可视化条件，已保留原文。', 'info');
          return;
        }
        join = flat.join;
        clauses = flat.clauses.map((clause) => ({ ...clause }));
      } else {
        advancedInput.value = compileClauses();
      }
      mode = requested;
      title.querySelector('small')!.textContent = mode === 'visual' ? '可视化模式：按行拼出条件' : '高级模式：保留原始 DSL';
      renderClauses();
      syncVisibility();
    });
    joinSelect.control.addEventListener('change', () => { join = joinSelect.control.value as 'and' | 'or'; renderPreview(); });
    targetSelect.control.addEventListener('change', syncVisibility);
    advancedInput.addEventListener('input', renderPreview);
    renderClauses();
    form.append(basicGrid, visualPanel, strategySelect.row, preview, footer);
    visualPanel.append(modeSelect.row, joinSelect.row, clauseRows, addClause, advancedInput);
    panel.append(title, form);
    editor.append(panel);
    syncVisibility();
    editor.scrollIntoView({ behavior: 'smooth', block: 'start' });
  };

  const fieldInput = (label: string, value: string, placeholder: string): FieldControl<HTMLInputElement> => {
    const row = element('label', { className: 'phone-cond-field' });
    row.append(element('span', { text: label }));
    const control = element('input', { className: 'phone-input', attributes: { type: 'text', placeholder } });
    control.value = value;
    row.append(control);
    return { row, control };
  };

  const fieldTextarea = (label: string, value: string, placeholder: string): FieldControl<HTMLTextAreaElement> => {
    const row = element('label', { className: 'phone-cond-field phone-cond-field-wide' });
    row.append(element('span', { text: label }));
    const control = element('textarea', { className: 'phone-textarea', attributes: { rows: '3', placeholder } });
    control.value = value;
    row.append(control);
    return { row, control };
  };

  const fieldSelect = <T extends string>(label: string, options: readonly (readonly [T, string])[], value: string): FieldControl<HTMLSelectElement> => {
    const row = element('label', { className: 'phone-cond-field' });
    row.append(element('span', { text: label }));
    const control = element('select', { className: 'phone-select' });
    appendOptions(control, options, value);
    row.append(control);
    return { row, control };
  };

  const appendOptions = <T extends string>(select: HTMLSelectElement, options: readonly (readonly [T, string])[], selected: string): void => {
    for (const [value, label] of options) {
      const option = element('option', { text: label, attributes: { value } });
      option.selected = value === selected;
      select.append(option);
    }
  };

  const renderInitial = (): void => {
    renderOverview();
    renderImpact();
    renderRules();
    renderTester();
    renderSnapshot();
  };

  const load = async (): Promise<void> => {
    try {
      const variables = await readVariables('message', null);
      const appAccess = Object.fromEntries(context.conditions.disabledAppIds.map((appId) => [appId, false]));
      snapshot = createConditionContext({
        state: context.state,
        variables,
        worldBook: context.conditions.worldBook,
        appAccess,
        now: context.state.worldClock.now,
      }).snapshot;
      snapshotTree = createConditionSnapshotTree(snapshot);
      const floor = variables.messageId === null ? '' : ` · 第 ${variables.messageId} 楼`;
      statusLine.textContent = variables.available
        ? `快照就绪 · ${variables.source}${floor}`
        : `变量来源不可用：${variables.reason || '仍可使用手机状态、时间和应用路径'}`;
      renderOverview();
      renderImpact();
      renderRules();
      renderSnapshot();
    } catch (error) {
      statusLine.textContent = `快照读取失败：${error instanceof Error ? error.message : String(error)}`;
      renderSnapshot();
    }
  };

  page.insertBefore(statusLine, overview);
  renderInitial();
  void load();
  return page;
}

interface FieldControl<T extends HTMLElement> {
  readonly row: HTMLElement;
  readonly control: T;
}

function flattenVisualSource(node: import('../../conditions/visual-builder.js').VisualConditionNode): { readonly join: 'and' | 'or'; readonly clauses: readonly VisualConditionClause[] } | null {
  if (node.kind === 'clause') return { join: 'and', clauses: [node] };
  if (node.kind === 'not') return null;
  const clauses: VisualConditionClause[] = [];
  for (const item of node.items) {
    if (item.kind !== 'clause') return null;
    clauses.push(item);
  }
  return clauses.length > 0 ? { join: node.join, clauses } : null;
}

function formatValue(value: unknown): string {
  if (typeof value === 'string') return `“${value.length > 80 ? `${value.slice(0, 79)}…` : value}”`;
  try {
    const serialized = JSON.stringify(value);
    return serialized.length > 120 ? `${serialized.slice(0, 119)}…` : serialized;
  } catch {
    return String(value);
  }
}