import type { PhoneEvent } from '../domain/events.js';
import { createInitialPhoneState, ensurePhoneStateShape, type PhoneState } from '../domain/model.js';
import { logPhoneEvents } from '../core/event-logging.js';
import { AdaptiveStorage } from './adaptive-storage.js';
import type { UnsubscribeStorage } from './storage-port.js';

export type PhoneStateListener = (state: PhoneState) => void;

export class PhoneStore {
  readonly #storage: AdaptiveStorage;
  readonly #listeners = new Set<PhoneStateListener>();
  #state: PhoneState | null = null;
  #scopeId: string | null = null;
  #storageSubscription: UnsubscribeStorage | null = null;
  #queue: Promise<void> = Promise.resolve();
  /** 已经广播过的修订号：同一次提交既走存储回调又走 dispatch，只应刷新界面一次。 */
  #notifiedRevision = -1;

  constructor(storage: AdaptiveStorage) {
    this.#storage = storage;
  }

  /**
   * 当前状态快照。
   *
   * 状态是纯数据且全链路只读（reducer 每次提交都产出新对象），因此这里直接返回内部引用。
   * 早期版本每次读取都 structuredClone 一整份状态，消息攒到几百条后，任何一次
   * 「读一下时间/读一下会话」都要深拷贝整个手机状态，是发消息卡顿的主要来源。
   */
  get state(): PhoneState {
    if (!this.#state) throw new Error('PhoneStore has not been opened');
    return this.#state;
  }

  get scopeId(): string {
    if (!this.#scopeId) throw new Error('PhoneStore has not been opened');
    return this.#scopeId;
  }

  async open(scopeId: string, initialNow = Date.now()): Promise<PhoneState> {
    if (this.#scopeId === scopeId && this.#state) return this.state;
    this.#storageSubscription?.();
    this.#storageSubscription = null;

    const persisted = await this.#storage.load(scopeId);
    const state = persisted ? ensurePhoneStateShape(persisted) : createInitialPhoneState(scopeId, initialNow);
    if (!persisted || state !== persisted) await this.#storage.replace(scopeId, state);

    this.#scopeId = scopeId;
    this.#state = state;
    this.#notifiedRevision = -1;
    this.#storageSubscription = this.#storage.subscribe(scopeId, (next) => {
      if (this.#scopeId !== scopeId || !this.#state || next.revision <= this.#state.revision) return;
      this.#state = next;
      this.#notify();
    });
    this.#notify();
    return this.state;
  }

  async refresh(): Promise<PhoneState> {
    if (!this.#scopeId) throw new Error('PhoneStore has not been opened');
    const next = await this.#storage.load(this.#scopeId);
    if (!next) return this.state;
    const normalized = ensurePhoneStateShape(next);
    if (normalized !== next) await this.#storage.replace(this.#scopeId, normalized);
    this.#state = normalized;
    this.#notify({ force: true });
    return this.state;
  }

  dispatch(events: readonly PhoneEvent[]): Promise<PhoneState> {
    return this.#enqueue(async () => {
      if (!this.#state || !this.#scopeId) throw new Error('PhoneStore has not been opened');
      if (events.length === 0) return this.state;
      for (const event of events) {
        if (event.scopeId !== this.#scopeId) {
          throw new Error(`Event scope mismatch: ${event.scopeId} !== ${this.#scopeId}`);
        }
      }
      const next = await this.#storage.commit(this.#scopeId, this.#state.revision, events);
      this.#state = next;
      logPhoneEvents(events);
      this.#notify();
      return this.state;
    });
  }

  subscribe(listener: PhoneStateListener): () => void {
    this.#listeners.add(listener);
    if (this.#state) listener(this.state);
    return () => this.#listeners.delete(listener);
  }

  close(): void {
    this.#storageSubscription?.();
    this.#storageSubscription = null;
    this.#scopeId = null;
    this.#state = null;
    this.#notifiedRevision = -1;
    this.#listeners.clear();
  }

  #enqueue<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.#queue.then(operation, operation);
    this.#queue = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }

  #notify(options: { readonly force?: boolean } = {}): void {
    if (!this.#state) return;
    // 一次提交会同时触发存储订阅回调和 dispatch 的收尾；修订号相同就是同一份状态，只广播一次。
    if (!options.force && this.#state.revision === this.#notifiedRevision) return;
    this.#notifiedRevision = this.#state.revision;
    const snapshot = this.#state;
    for (const listener of this.#listeners) listener(snapshot);
  }
}