/**
 * 结构化 JSON 请求的公共参数。
 *
 * 原著抽取与剧情状态跟踪都要求模型输出完整闭合的 JSON：
 * - 输出预算太小，JSON 会写到一半被切断，上层只能报「格式无效」并白重试；
 * - 温度太高，模型会加解说、改键名、编造字段。
 * 因此这两个环节不直接沿用创作用的参数，而是按下限抬高预算、按上限收敛温度。
 */

export interface StructuredBudgetRange {
  readonly min: number;
  readonly max: number;
}

/** 未指定温度时结构化环节使用的低温默认值。 */
const DEFAULT_STRUCTURED_TEMPERATURE = 0.2;

/** 输出预算：用户配置更大就沿用，否则抬到下限，最后按上限收口。 */
export function structuredTokenBudget(
  api: { readonly maxTokens: number | null },
  range: StructuredBudgetRange,
): number {
  const configured = Number(api.maxTokens);
  const budget = Number.isFinite(configured) && configured > 0
    ? Math.max(configured, range.min)
    : range.min;
  return Math.min(budget, range.max);
}

/** 温度：抽取不是创作，用户把温度调到很高时按上限收敛，保证 JSON 结构稳定。 */
export function structuredTemperature(
  api: { readonly temperature: number | null },
  ceiling = 0.6,
): number {
  // null 表示「跟随全局设置」，结构化环节按低温默认值处理，而不是当成 0。
  if (api.temperature === null || api.temperature === undefined) return DEFAULT_STRUCTURED_TEMPERATURE;
  const configured = Number(api.temperature);
  return Number.isFinite(configured) && configured >= 0
    ? Math.min(configured, ceiling)
    : DEFAULT_STRUCTURED_TEMPERATURE;
}
