/** 手机发送与生成共用的时间规则；缺省值保持原有节奏。 */
export interface TimeAdvanceSettings {
  readonly enabled: boolean;
  readonly sendBaseMinutes: number;
  readonly sendCharsPerMinute: number;
  readonly sendAttachmentMinutes: number;
  readonly sendMaxMinutes: number;
  readonly useModelDelay: boolean;
  readonly modelDelayMaxMinutes: number;
  readonly firstReplyMinSeconds: number;
  readonly firstReplyMaxSeconds: number;
  readonly burstMinSeconds: number;
  readonly burstMaxSeconds: number;
  readonly batchMaxMinutes: number;
}

export const DEFAULT_TIME_ADVANCE: TimeAdvanceSettings = Object.freeze({
  enabled: true,
  sendBaseMinutes: 1,
  sendCharsPerMinute: 180,
  sendAttachmentMinutes: 2,
  sendMaxMinutes: 60,
  useModelDelay: true,
  modelDelayMaxMinutes: 45,
  firstReplyMinSeconds: 30,
  firstReplyMaxSeconds: 480,
  burstMinSeconds: 30,
  burstMaxSeconds: 90,
  batchMaxMinutes: 120,
});

export type TimeAdvanceNumberKey = Exclude<keyof TimeAdvanceSettings, 'enabled' | 'useModelDelay'>;
export const TIME_ADVANCE_LIMITS: Readonly<Record<TimeAdvanceNumberKey, readonly [number, number]>> = {
  sendBaseMinutes: [0, 1440], sendCharsPerMinute: [1, 100000], sendAttachmentMinutes: [0, 1440], sendMaxMinutes: [0, 1440],
  modelDelayMaxMinutes: [0, 1440], firstReplyMinSeconds: [0, 86400], firstReplyMaxSeconds: [0, 86400],
  burstMinSeconds: [0, 86400], burstMaxSeconds: [0, 86400], batchMaxMinutes: [0, 1440],
};

export function normalizeTimeAdvanceSettings(value: unknown): TimeAdvanceSettings {
  const raw = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
  const numbers = {} as Record<TimeAdvanceNumberKey, number>;
  for (const key of Object.keys(TIME_ADVANCE_LIMITS) as TimeAdvanceNumberKey[]) {
    const value = raw[key];
    const parsed = typeof value === 'number' || (typeof value === 'string' && value.trim()) ? Number(value) : Number.NaN;
    const [min, max] = TIME_ADVANCE_LIMITS[key];
    numbers[key] = Number.isFinite(parsed) ? Math.min(max, Math.max(min, parsed)) : DEFAULT_TIME_ADVANCE[key];
  }
  numbers.sendCharsPerMinute = Math.round(numbers.sendCharsPerMinute);
  numbers.firstReplyMaxSeconds = Math.max(numbers.firstReplyMinSeconds, numbers.firstReplyMaxSeconds);
  numbers.burstMaxSeconds = Math.max(numbers.burstMinSeconds, numbers.burstMaxSeconds);
  return { ...numbers, enabled: raw.enabled !== false, useModelDelay: raw.useModelDelay !== false };
}

/** 关闭自动推进后，只有用户在时钟编辑器中明确要求同步时才读取绑定时间。 */
export function shouldSyncBoundClock(settings: TimeAdvanceSettings, reason: string): boolean {
  return settings.enabled || reason === 'manual-config';
}
