export interface AbortableSingleFlight<T> {
  readonly run: (task: (signal: AbortSignal) => Promise<T>) => Promise<T>;
  readonly cancel: () => void;
  readonly isRunning: () => boolean;
}

/**
 * 同一职责在任意时刻只允许一个异步任务运行；重复调用直接失败，取消信号由任务自行处理。
 */
export function createAbortableSingleFlight<T>(busyMessage: string): AbortableSingleFlight<T> {
  let active: { readonly controller: AbortController; readonly promise: Promise<T> } | null = null;

  const run = (task: (signal: AbortSignal) => Promise<T>): Promise<T> => {
    if (active) return Promise.reject(new Error(busyMessage));
    const controller = new AbortController();
    const promise = Promise.resolve().then(() => task(controller.signal));
    active = { controller, promise };
    return promise.finally(() => {
      if (active?.promise === promise) active = null;
    });
  };

  return {
    run,
    cancel: () => active?.controller.abort(),
    isRunning: () => active !== null,
  };
}