import { createImageMarkerPattern } from './image-marker.js';

export {
  contentHasImageMarker,
  replaceImageMarkers,
  splitContentWithImageMarkers,
} from './image-marker.js';
export type { ContentSegment } from './image-marker.js';

/**
 * 手机富内容中的生图标记统一由 image-marker 模块注册和识别。
 * 内置格式：image###英文提示词###；兼容旧格式 [[生图:英文提示词]]。
 */
const HIDDEN_DETAILS_PATTERN = /<details\b[^>]*class\s*=\s*["'][^"']*(?:narrative-phone-log|reasoning|thinking|thought|analysis)[^"']*["'][^>]*>[\s\S]*?<\/details\s*>/gi;
const STORY_CONTEXT_PATTERN = /(?:以上是用户的本轮输入，[^\n]*(?:\r?\n\s*)?)?<story_context\b[^>]*>[\s\S]*?<\/story_context\s*>/gi;
const THOUGHT_DETAILS_PATTERN = /<details\b[^>]*>\s*<summary\b[^>]*>[\s\S]{0,200}?(?:思考|推理|reasoning|thought|analysis)[\s\S]{0,200}?<\/summary>[\s\S]*?<\/details\s*>/gi;
const HIDDEN_TAG_PATTERN = /<(?:think|thinking|analysis|reasoning|reflection|scratchpad|chain[-_ ]?of[-_ ]?thought|image[_ -]?prompt)\b[^>]*>[\s\S]*?<\/(?:think|thinking|analysis|reasoning|reflection|scratchpad|chain[-_ ]?of[-_ ]?thought|image[_ -]?prompt)\s*>/gi;
const UNCLOSED_HIDDEN_TAG_PATTERN = /<(?:think|thinking|analysis|reasoning|reflection|scratchpad|image[_ -]?prompt)\b[^>]*>[\s\S]*$/gi;
const LABELED_CODE_BLOCK_PATTERN = /```(?:thinking|think|analysis|reasoning|image[_ -]?prompt|drawing[_ -]?prompt)[^\n]*\n[\s\S]*?```/gi;
const BRACKETED_HIDDEN_BLOCK_PATTERN = /\[(?:think(?:ing)?|analysis|reasoning|image[_ -]?prompt)\][\s\S]*?\[\/(?:think(?:ing)?|analysis|reasoning|image[_ -]?prompt)\]/gi;
const THOUGHT_SECTION_PATTERN = /(?:^|\n)\s*(?:思考过程|推理过程|思维过程|analysis|reasoning|thought process)\s*[:：]?\s*\n[\s\S]*?(?=\n\s*(?:正文|最终答案|回答|剧情)\s*[:：]?\s*\n|$)/gi;
const IMAGE_PROMPT_PARAGRAPH_PATTERN = /(?:^|\n)\s*(?:【|\[)(?:生图|绘图|图片)提示词(?:】|\])[^\n]*(?:\n(?!\s*\n)[^\n]*){0,8}/gi;
const PROMPT_LINE_PATTERN = /^[ \t]*(?:[#>*-]+[ \t]*)?(?:【|\[)?(?:生图提示词|绘图提示词|图片提示词|image[ _-]?prompt|drawing[ _-]?prompt|positive[ _-]?prompt|negative[ _-]?prompt|scene[ _-]?composition|character[ \t]*\d+[ \t]*(?:prompt|uc))(?:】|\])?[ \t]*[:：|]?[ \t]*.*$/gim;
const STORY_HEADING_PATTERN = /^[ \t]*(?:正文|最终答案|回答|剧情)[ \t]*[:：][ \t]*$/gim;
const STORY_CONTENT_TAG_PATTERN = /<(?:content|story|maintext|\u6b63\u6587|\u5267\u60c5)[^>]*>([\s\S]*?)<\/(?:content|story|maintext|\u6b63\u6587|\u5267\u60c5)>/gi;
const PROVIDER_ERROR_ENVELOPE_PATTERN = /^[▷▶>\s`"'(\[]*(?:json\s*)?(?:\{\s*["']?(?:error|errors)["']?\s*[:：]|(?:api|http|provider|model|generation|request)[ _-]?(?:error|failed|failure)\s*[:：]|(?:请求|生成|接口|模型|服务)(?:失败|错误)\s*[:：]|(?:请求|生成)(?:已)?被拒绝(?:[。.!！]|$))/i;
const PROVIDER_FILTER_PATTERN = /(?:\bcontent[_ -]?filter(?:ed|ing)?\b|\bsafety[_ -]?(?:filter|policy)\b|内容审核(?:未通过|拦截)|安全策略(?:拦截|拒绝))/i;
const REFUSAL_VERB_PATTERN = /(?:无法|不能|不会|拒绝|不便|can(?:not|'t)|unable|won't|refus(?:e|al)|declin(?:e|ed))/i;
const POLICY_REASON_PATTERN = /(?:违反|违规|违法|政策|规定|法律法规|安全准则|未成年|淫秽|色情|危害|敏感内容|公序良俗|policy|safety|guideline|minor|underage|sexual|harmful|illegal|prohibited)/i;
const APOLOGY_PATTERN = /(?:(?:非常|十分|很)?抱歉|对不起|很遗憾|sorry|regret)/i;
const REQUEST_CONTEXT_PATTERN = /(?:为你|为您|你(?:的)?请求|您的请求|(?:该|这个|此)(?:请求|要求)|相关(?:服务|内容)|您?提供的内容|所述内容|提供(?:相关)?(?:服务|内容)|满足.{0,20}请求|(?:that|this|your|the) request|such content|with (?:that|this))/i;
const CHINESE_APOLOGETIC_REFUSAL_PATTERN = /^(?:[▷▶>\s`"'(\[])*(?:(?:非常|十分|很)?抱歉|对不起|很遗憾)[，,:：。.!！\s]*(?:我|本模型|本助手|作为\s*(?:一个)?(?:AI|人工智能|语言模型|助手))?.{0,60}(?:无法|不能|不会|拒绝|不便).{0,100}(?:提供|生成|协助|帮助|继续|回答|处理|满足)/i;
const ENGLISH_REFUSAL_PATTERN = /(?:\bi(?:['’]m| am)\s+sorry.{0,120}\b(?:can(?:not|'t)|unable|won't)\b|\bi\s+(?:can(?:not|'t)|am unable|won't|must refuse|have to refuse)\s+(?:to\s+)?(?:assist|help|provide|generate|comply|fulfill|answer|continue))/i;
const EXPLICIT_ASSISTANT_PATTERN = /(?:作为\s*(?:一个)?(?:AI|人工智能|语言模型|助手)|我是\s*(?:一个)?(?:AI|人工智能|语言模型|助手)|本(?:AI|模型|助手)|as an?\s+(?:ai|artificial intelligence|language model|assistant))/i;

/**
 * 提取可以被当作剧情正文的文本。
 * 思考链、插件注入块、生图提示词和纯展示标签会被移除，但正常段落结构会保留。
 */
/** Extract tagged story content before removing other non-story blocks. */
function extractTaggedStoryText(raw: string): string {
  STORY_CONTENT_TAG_PATTERN.lastIndex = 0;
  const parts = [...raw.matchAll(STORY_CONTENT_TAG_PATTERN)].map((match) => match[1] ?? '').filter(Boolean);
  STORY_CONTENT_TAG_PATTERN.lastIndex = 0;
  return parts.length > 0 ? parts.join('\n\n') : raw;
}

/**
 * 中和宿主模板定界符。
 *
 * 注入到提示词里的文本会被酒馆的模板引擎再渲染一次：数据里残留的 EJS 片段
 * （`<%= _cos %>`、`<%_ if (_preg) _%>` 之类）会被当成代码执行，作用域里没有那些
 * 局部变量就抛 `not defined` 并中断整轮生成。模板源码对模型没有信息价值，
 * 因此整段换成占位说明。`{{...}}` 宏由宿主负责替换且不会报错，保持原样。
 */
export function neutralizeHostTemplates(raw: string): string {
  return raw
    .replace(/<%[-=_]?[\s\S]*?[-_]?%>/g, '（动态值）')
    // 落单的定界符也要断开，避免与后续文本拼成新的可执行片段。
    .replace(/<%/g, '‹')
    .replace(/%>/g, '›')
    .replace(/（动态值）(?:\s*（动态值）)+/g, '（动态值）');
}

export function sanitizeStoryText(raw: string, charLimit = Number.POSITIVE_INFINITY): string {
  let text = extractTaggedStoryText(raw);
  text = text.replace(/\r\n?/g, '\n').replace(/\u0000/g, '');
  for (let pass = 0; pass < 3; pass += 1) {
    const previous = text;
    text = text
      .replace(STORY_CONTEXT_PATTERN, ' ')
      .replace(HIDDEN_DETAILS_PATTERN, ' ')
      .replace(THOUGHT_DETAILS_PATTERN, ' ')
      .replace(HIDDEN_TAG_PATTERN, ' ')
      .replace(LABELED_CODE_BLOCK_PATTERN, ' ')
      .replace(BRACKETED_HIDDEN_BLOCK_PATTERN, ' ');
    if (text === previous) break;
  }
  text = text
    .replace(UNCLOSED_HIDDEN_TAG_PATTERN, ' ')
    .replace(THOUGHT_SECTION_PATTERN, ' ')
    .replace(IMAGE_PROMPT_PARAGRAPH_PATTERN, ' ')
    .replace(createImageMarkerPattern(), '')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/!\[[^\]]*\]\([^\n)]*\)/g, '')
    .replace(PROMPT_LINE_PATTERN, '')
    .replace(STORY_HEADING_PATTERN, '')
    .replace(/<[^>]{1,500}>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&amp;/gi, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
  return Number.isFinite(charLimit) ? text.slice(0, Math.max(0, charLimit)) : text;
}

/**
 * 仅识别足以自动删除历史数据的高置信拒绝/供应商错误。
 * 普通剧情里的“拒绝、违规、无法帮助”等叙述不会单凭关键词命中。
 */
export function isHighConfidenceModelRefusal(raw: string): boolean {
  const text = normalizeRefusalDetectionText(raw);
  if (!text) return false;

  if (PROVIDER_ERROR_ENVELOPE_PATTERN.test(text)) return true;
  if (PROVIDER_FILTER_PATTERN.test(text) && (REFUSAL_VERB_PATTERN.test(text) || POLICY_REASON_PATTERN.test(text))) {
    return true;
  }
  if (CHINESE_APOLOGETIC_REFUSAL_PATTERN.test(text) && (REQUEST_CONTEXT_PATTERN.test(text) || POLICY_REASON_PATTERN.test(text))) {
    return true;
  }
  if (ENGLISH_REFUSAL_PATTERN.test(text)) return true;
  return EXPLICIT_ASSISTANT_PATTERN.test(text)
    && REFUSAL_VERB_PATTERN.test(text)
    && (REQUEST_CONTEXT_PATTERN.test(text) || POLICY_REASON_PATTERN.test(text));
}

/** 识别模型把安全拒绝或接口错误正文当作正常生成结果返回的情况。 */
export function isLikelyModelRefusal(raw: string): boolean {
  const text = normalizeRefusalDetectionText(raw);
  if (!text) return false;
  if (isHighConfidenceModelRefusal(text)) return true;

  const startsAsRefusal = /^(?:[▷▶>\s`"'(\[])*(?:(?:非常|十分|很)?抱歉|对不起|很遗憾|sorry|i\s+(?:can(?:not|'t)|am unable|won't))/i.test(text);
  return startsAsRefusal
    && REFUSAL_VERB_PATTERN.test(text)
    && (APOLOGY_PATTERN.test(text) || REQUEST_CONTEXT_PATTERN.test(text))
    && (REQUEST_CONTEXT_PATTERN.test(text) || POLICY_REASON_PATTERN.test(text));
}

function normalizeRefusalDetectionText(raw: string): string {
  return sanitizeStoryText(raw).replace(/\s+/g, ' ').trim().slice(0, 3_000);
}

/** 清理并校验需要直接写入业务状态的模型文本。 */
export function requireUsableGeneratedText(raw: string, label: string): string {
  if (isLikelyModelRefusal(raw)) {
    throw new Error(`${label}被模型拒绝，结果未写入；请调整模型、提示内容或上游安全设置后重试。`);
  }
  const text = sanitizeStoryText(raw);
  if (!text) throw new Error(`${label}没有返回可用正文，结果未写入。`);
  if (isLikelyModelRefusal(text)) {
    throw new Error(`${label}被模型拒绝，结果未写入；请调整模型、提示内容或上游安全设置后重试。`);
  }
  return text;
}