type HostResourceModule = Record<string, unknown>;
type HostModuleLoader = (path: string) => Promise<HostResourceModule>;

/** 使用宿主刷新入口，以保留当前角色身份和世界书选中状态。 */
export async function refreshConvertedResources(
  load: HostModuleLoader = (path) => import(/* @vite-ignore */ path),
): Promise<readonly string[]> {
  const issues: string[] = [];
  for (const [path, method, label] of [
    ['/scripts/world-info.js', 'updateWorldInfoList', '世界书'],
    ['/script.js', 'getCharacters', '角色卡'],
  ] as const) {
    try {
      const module = await load(path);
      const refresh = module[method];
      if (typeof refresh !== 'function') throw new Error('宿主刷新接口不可用');
      await refresh();
    } catch {
      issues.push(`${label}已创建，但列表刷新失败；请手动刷新列表，不要重复转换。`);
    }
  }
  return issues;
}