/**
 * 手机内开发者指南与仓库示例共用的模块模板源码。
 *
 * 模板正文只使用字符串拼接，不使用反引号与 ${}，因此可以原样下载成 .js 直接导入。
 */

export interface ExtensionModuleTemplate {
  readonly id: string;
  readonly title: string;
  readonly filename: string;
  readonly summary: string;
  readonly source: string;
}

const HELLO_WORLD = `export const manifest = {
  protocolVersion: 1,
  id: 'hello-phone',
  name: '你好手机',
  version: '1.0.0',
  author: '你的名字',
  description: '最小可运行模块：读取当前手机状态。',
  entry: 'self',
};

export default function createModule(api) {
  const root = document.createElement('section');
  const title = document.createElement('strong');
  const output = document.createElement('p');
  const refresh = document.createElement('button');
  title.textContent = '你好，' + api.module.manifest.name;
  refresh.type = 'button';
  refresh.className = 'phone-button phone-button-primary';
  refresh.textContent = '读取当前状态';
  refresh.addEventListener('click', () => {
    const state = api.state.snapshot();
    output.textContent = '作用域 ' + api.state.scopeId
      + ' · 联系人 ' + Object.keys(state.profiles).length
      + ' · 会话 ' + Object.keys(state.conversations).length
      + ' · 剧情时间 ' + api.time.format();
  });
  root.append(title, refresh, output);
  return { manifest, render: () => root };
}
`;

const WECHAT_AVATAR = `export const manifest = {
  protocolVersion: 1,
  id: 'wechat-avatar-kit',
  name: '微信头像助手',
  version: '1.0.0',
  author: '你的名字',
  description: '读取微信联系人，逐个查看与设置微信头像。',
  entry: 'self',
};

export default function createModule(api) {
  const root = document.createElement('section');
  const list = document.createElement('div');
  const notice = document.createElement('p');

  function draw() {
    list.replaceChildren();
    for (const profile of api.wechat.profiles()) {
      const row = document.createElement('div');
      const avatar = document.createElement('img');
      const name = document.createElement('span');
      const pick = document.createElement('button');
      avatar.width = 36;
      avatar.height = 36;
      avatar.alt = '';
      avatar.src = api.wechat.getAvatar(profile.id) || '';
      name.textContent = profile.displayName;
      pick.type = 'button';
      pick.className = 'phone-button phone-button-secondary';
      pick.textContent = '设置头像';
      pick.addEventListener('click', async () => {
        const values = await api.modal('设置微信头像', [
          { name: 'url', label: '头像地址（https 或 data:image/*，留空清除）' },
        ]);
        if (!values) return;
        try {
          await api.wechat.setAvatar(profile.id, values.url);
          notice.textContent = '已更新 ' + profile.displayName + ' 的微信头像。';
          draw();
        } catch (error) {
          notice.textContent = '设置失败：' + (error instanceof Error ? error.message : String(error));
        }
      });
      row.append(avatar, name, pick);
      list.append(row);
    }
  }

  draw();
  root.append(list, notice);
  return { manifest, render: () => root };
}
`;

const REPLY_ASSISTANT = `export const manifest = {
  protocolVersion: 1,
  id: 'reply-assistant',
  name: '回复助手',
  version: '1.0.0',
  author: '你的名字',
  description: '按最近若干条微信消息生成回复草稿，确认后再发送。',
  entry: 'self',
  api: { mode: 'shared' },
};

export default function createModule(api) {
  const root = document.createElement('section');
  const picker = document.createElement('select');
  const draft = document.createElement('textarea');
  const generate = document.createElement('button');
  const send = document.createElement('button');
  const notice = document.createElement('p');

  for (const conversation of api.wechat.conversations()) {
    const option = document.createElement('option');
    option.value = conversation.id;
    option.textContent = conversation.title;
    picker.append(option);
  }
  generate.type = 'button';
  generate.className = 'phone-button phone-button-primary';
  generate.textContent = '生成草稿';
  send.type = 'button';
  send.className = 'phone-button phone-button-secondary';
  send.textContent = '发送到会话';

  generate.addEventListener('click', async () => {
    notice.textContent = '正在生成…';
    try {
      const messages = api.wechat.messages(picker.value, 20).map((message) => ({
        role: message.direction === 'outgoing' ? 'user' : 'assistant',
        content: message.content,
      }));
      draft.value = await api.generation.reply({ messages, waitFor: 20 });
      notice.textContent = '草稿已生成，可编辑后发送。';
    } catch (error) {
      notice.textContent = '生成失败：' + (error instanceof Error ? error.message : String(error));
    }
  });

  send.addEventListener('click', async () => {
    try {
      await api.wechat.send(picker.value, draft.value.trim());
      draft.value = '';
      notice.textContent = '已发送，并加入统一回复队列。';
    } catch (error) {
      notice.textContent = '发送失败：' + (error instanceof Error ? error.message : String(error));
    }
  });

  root.append(picker, generate, draft, send, notice);
  return { manifest, render: () => root };
}
`;

const AUTO_PARSE_TRACKER = `export const manifest = {
  protocolVersion: 1,
  id: 'delivery-tracker',
  name: '快递追踪',
  version: '1.0.0',
  author: '你的名字',
  description: '正文出现快递状态时自动记录，并注入模型上下文。',
  entry: 'self',
  generationContext: { includeStorage: true },
};

const SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['courier', 'status'],
  properties: {
    courier: { type: 'string', minLength: 1, maxLength: 40 },
    status: { type: 'string', minLength: 1, maxLength: 80 },
    note: { type: 'string', maxLength: 200 },
  },
};

export default function createModule(api) {
  const root = document.createElement('section');
  const list = document.createElement('ul');

  async function draw() {
    const records = (await api.storage.get('records')) || [];
    list.replaceChildren();
    for (const record of records) {
      const item = document.createElement('li');
      item.textContent = record.courier + ' · ' + record.status
        + (record.note ? ' · ' + record.note : '');
      list.append(item);
    }
  }

  void draw();
  root.append(list);

  return {
    manifest,
    render: () => root,
    autoParse: {
      description: '正文明确写出快递公司和最新状态时提取一条记录。',
      prompt: '只提取正文已经发生的快递状态变化，不要预测后续配送。',
      schema: SCHEMA,
      validate: (value) => typeof value.status === 'string' && value.status.length > 0,
      apply: async (value, context) => {
        const records = (await api.storage.get('records')) || [];
        const floor = context.sourceFloors.length > 0
          ? context.sourceFloors[context.sourceFloors.length - 1]
          : 0;
        await api.storage.set('records', records.concat([{
          courier: value.courier,
          status: value.status,
          note: value.note || '',
          floor,
        }]));
        api.notify('已记录一条快递状态。', 'success');
        await draw();
      },
    },
  };
}
`;

