export function isPhoneAppEnabled(disabledAppIds: readonly string[], appId: string): boolean {
  return !disabledAppIds.includes(appId);
}

export interface PhoneNavigationItem {
  readonly route: PhoneRoute;
  readonly label: string;
  readonly icon: string;
}

export interface PhoneDatabaseViewContext {
  readonly storage: AdaptiveStorageStatus;
  /** 数据库插件当前能力快照（模式、接口可用性）。 */
  readonly inspect: () => DatabaseApiInspection;
  /** 通过 exportTableAsJson 读取当前聊天全部表格数据（原生与 SQLite 模式通用）。 */
  readonly snapshotTables: () => Promise<DatabaseTablesSnapshot>;
  readonly refresh: () => Promise<void>;
}

/** 新建自定义记忆表的表单输入；列名限制与 DDL 校验由 db 层负责。 */
export interface LocalSheetDraft {
  readonly name: string;
  readonly purpose: string;
  readonly columns: readonly string[];
  readonly policy: SheetPolicy;
  readonly rowTemplate: string;
  readonly tokenBudget: number;
  /** 注入条件（IF 语法的表达式部分）；空串表示无条件。 */
  readonly injectCondition: string;
  /** 填表规则；随表结构进填表提示词，空串表示没有额外规则。 */
  readonly fillGuide: string;
}

export interface LocalSqlOutcome {
  readonly ok: boolean;
  readonly message: string;
  readonly columns: readonly string[];
  readonly rows: readonly Readonly<Record<string, unknown>>[];
}

export interface LocalActionResult {
  readonly ok: boolean;
  readonly message: string;
}

/** 数据中心应用的上下文：手机插件自有的本地 SQLite 记忆库，所有调用经运行时代理到 Worker。 */
export interface PhoneDataCenterContext {
  readonly settings: DataCenterSettings;
  readonly apiProfiles: readonly ApiProfile[];
  readonly updateSettings: (patch: DataCenterSettingsPatch) => Promise<void>;
  readonly inspect: () => Promise<SqlitePanelStatus>;
  readonly createSheet: (draft: LocalSheetDraft) => Promise<LocalActionResult>;
  /** 导入表格预设：本扩展自有格式或 SP 的 chatSheets 模板；name 用作预设包名称。 */
  readonly importPreset: (raw: string, name?: string) => Promise<LocalActionResult>;
  readonly importCurrentSqCard?: () => Promise<LocalActionResult>;
  /** 从预设库移除一份导入的预设；内置默认表格不可删除，已建好的表不受影响。 */
  readonly deletePreset: (bundleId: string) => Promise<LocalActionResult>;
  /** 读取一张表的内容用于可视化网格。 */
  readonly readSheet: (sheetId: string) => Promise<SheetContent | null>;
  readonly insertRow: (sheetId: string, values: Readonly<Record<string, string>>) => Promise<LocalActionResult>;
  readonly updateRow: (
    sheetId: string,
    rowId: number,
    values: Readonly<Record<string, string>>,
  ) => Promise<LocalActionResult>;
  readonly deleteRow: (sheetId: string, rowId: number) => Promise<LocalActionResult>;
  readonly dropSheet: (sheetId: string) => Promise<LocalActionResult>;
  /** 表结构编辑：元数据与列的增删改。 */
  readonly updateSheet: (sheetId: string, patch: SheetMetaPatch) => Promise<LocalActionResult>;
  readonly addColumn: (sheetId: string, column: string, label?: string) => Promise<LocalActionResult>;
  readonly renameColumn: (sheetId: string, from: string, to: string) => Promise<LocalActionResult>;
  readonly dropColumn: (sheetId: string, column: string) => Promise<LocalActionResult>;
  /** 立即让填表模型处理尚未记录的楼层。 */
  readonly recordNow: () => Promise<LocalActionResult>;
  /** 执行过闸 SQL（只允许 SELECT/INSERT/UPDATE/DELETE 且只能命中已注册表）。 */
  readonly runSql: (sql: string) => Promise<LocalSqlOutcome>;
  readonly refreshProjections: () => Promise<LocalActionResult>;
  readonly exportDatabase: () => Promise<LocalActionResult>;
}

/** 运行时提供的数据中心操作；设置快照与写回由外壳按当前 runtimeInfo 注入。 */
export type PhoneDataCenterActions = Omit<PhoneDataCenterContext, 'settings' | 'apiProfiles' | 'updateSettings'>;

/** 日记本应用的视图上下文：设置、可选的已保存 API 配置与手动补写。 */
export interface PhoneDiaryViewContext {
  /** 当前日记设置快照。 */
  readonly settings: DiarySettings;
  /** API 配置库（在 设置 → API 配置 中维护）。 */
  readonly apiProfiles: readonly ApiProfile[];
  readonly updateSettings: (patch: DiarySettingsPatch) => Promise<void>;
  /** 立即补写日记：覆盖上次记录点到当前剧情时刻。 */
  readonly generateNow: () => Promise<{ readonly ok: boolean; readonly message: string }>;
}

/** 记忆库应用的视图上下文。 */
export interface PhoneMemoryViewContext {
  readonly settings: MemorySettings;
  /** API 配置库（在 设置 → API 配置 中维护）。 */
  readonly apiProfiles: readonly ApiProfile[];
  /** 当前酒馆预设中可用于记忆注入的提示词槽位。 */
  readonly presetPromptSlots: PresetPromptSlotSnapshot;
  readonly refreshPresetPromptSlots: () => Promise<void>;
  readonly updateSettings: (patch: MemorySettingsPatch) => Promise<void>;
  /** 手动整理未摘要的楼层（含不满一批的零头）。 */
  readonly memorizeNow: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 编辑已有记忆正文。 */
  readonly updateItemContent: (itemId: string, content: string) => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 按原楼层范围重新生成一份摘要。 */
  readonly regenerateItem: (itemId: string) => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 手动把未归档摘要合并成总结。 */
  readonly consolidateNow: () => Promise<{ readonly ok: boolean; readonly message: string }>;
}

/** 向量库应用的视图上下文。 */
export interface PhoneVectorViewContext {
  readonly settings: VectorSettings;
  /** 向量库应用是否被个性化停用；停用后向量召回同样跑不起来。 */
  readonly appDisabled: boolean;
  /** API 配置库（在设置中维护）。 */
  readonly apiProfiles: readonly ApiProfile[];
  readonly updateSettings: (patch: VectorSettingsPatch) => Promise<void>;
  /** 手动检索测试。 */
  readonly test: (query: string) => Promise<readonly MemorySearchHit[]>;
  /** 清空并重建向量索引。 */
  readonly rebuildIndex: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 只补齐未索引的记忆，保留已有向量。 */
  readonly ensureIndex: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 索引数据面板（总覆盖率、分组覆盖率、向量维度与生效模型）。 */
  readonly indexStatus: () => Promise<VectorIndexStats>;
}

/** 同人剧情应用的视图上下文：原著库、人物锁、AU 状态与召回诊断。 */
export interface FanficImportSummary {
  readonly id: string;
  readonly name: string;
  readonly charCount: number;
}

export interface FanficCardSummary {
  readonly available: boolean;
  readonly name: string;
  readonly fieldCount: number;
  readonly charCount: number;
}

/** 同人剧情面板的只读快照：由运行时提供，界面不直接访问原著库存储。 */
export interface FanficPanelSnapshot {
  readonly stats: {
    readonly documents: number;
    readonly chunks: number;
    readonly analyzed: number;
    readonly characters: number;
    readonly facts: number;
    readonly worldRules: number;
  };
  readonly card: FanficCardSummary;
  readonly imports: readonly FanficImportSummary[];
  readonly characters: readonly CharacterLock[];
  /** 最近一次编译的召回诊断；仅展示给用户，不进入提示词。 */
  readonly diagnostics: FanficContextDiagnostics | null;
  readonly busy: boolean;
}

export interface PhoneFanficViewContext extends FanficPanelSnapshot {
  readonly settings: FanficSettings;
  readonly apiProfiles: readonly ApiProfile[];
  readonly narrative: FanficNarrativeState;
  readonly updateSettings: (patch: FanficSettingsPatch) => Promise<void>;
  readonly importText: (name: string, text: string) => Promise<FanficActionResult>;
  readonly removeDocument: (documentId: string) => Promise<FanficActionResult>;
  /** reset=true 重建原著库（保留手工修正的人物锁），否则继续解析未处理片段。 */
  readonly analyze: (reset: boolean) => Promise<FanficActionResult>;
  readonly clearLibrary: () => Promise<FanficActionResult>;
  readonly updateCharacter: (character: CharacterLock) => Promise<FanficActionResult>;
  readonly trackNow: () => Promise<FanficActionResult>;
  readonly clearNarrative: () => Promise<FanficActionResult>;
}

export interface FanficActionResult {
  readonly ok: boolean;
  readonly message: string;
}

/** 条件应用的视图上下文：规则设置、只读世界书快照与停用应用列表（构建条件快照用）。 */
export interface PhoneConditionsViewContext {
  readonly settings: ConditionRulesSettings;
  readonly worldBook: WorldBookSnapshot;
  readonly disabledAppIds: readonly string[];
  readonly updateSettings: (patch: Partial<ConditionRulesSettings>) => Promise<void>;
}

export interface PhoneForumViewContext {
  readonly settings: ForumSettings;
  readonly updateSettings: (patch: ForumSettingsPatch) => Promise<void>;
}

export interface ContactAutoMatchRequest {
  readonly platform: 'wechat' | 'twitter';
  readonly targetName?: string;
}

export interface ContactAutoMatchContact {
  readonly conversationId: string;
  readonly profileId: string;
  readonly displayName: string;
  readonly boundCharacter: string;
}

export interface ContactAutoMatchResult {
  /** 本轮新建或补全的联系人。 */
  readonly contacts: readonly ContactAutoMatchContact[];
  /** 因为已经匹配过或资料冲突而跳过的角色说明。 */
  readonly skipped: readonly string[];
  /** 本轮用满了单次上限，世界书里可能还有角色没匹配。 */
  readonly hasMore: boolean;
}

export interface PhoneViewContext {
  readonly state: PhoneState;
  readonly commands: PhoneCommands;
  readonly generation: GenerationService;
  readonly database: PhoneDatabaseViewContext;
  readonly dataCenter: PhoneDataCenterContext;
  readonly diary: PhoneDiaryViewContext;
  readonly memoryBank: PhoneMemoryViewContext;
  readonly vector: PhoneVectorViewContext;
  readonly fanfic: PhoneFanficViewContext;
  readonly conditions: PhoneConditionsViewContext;
  readonly forum: PhoneForumViewContext;
  readonly route: PhoneRoute;
  readonly selectedConversationId: string | null;
  /** 当前应用的运行时显示名称（个性化里改过名就用自定义名）；不影响应用内导航项名称。 */
  readonly appTitle: (defaultLabel: string) => string;
  readonly navigate: (route: PhoneRoute) => void;
  readonly openConversation: (conversationId: string) => void;
  /** 使用设置中的生图供应商生成图片，返回可用于 img src 的地址。 */
  readonly generateImage: (prompt: string) => Promise<string>;
  /** 根据角色资料与剧情上下文生成并校验头像提示词。 */
  readonly generateAvatarPrompt: (request: AvatarPromptRequest) => Promise<AvatarPromptResult>;
  /** 从当前激活世界书匹配并补全微信或推特联系人。 */
  readonly autoMatchContact: (request: ContactAutoMatchRequest) => Promise<ContactAutoMatchResult>;
  /** 调用 AI 生成一批贴合世界书与剧情的 PXX 商品（不含已有商品名）。 */
  readonly generatePxxProducts: (existingNames: readonly string[]) => Promise<readonly PxxProductDraft[]>;
  /** 根据用户公开互动形成的兴趣信号刷新论坛或 X 推荐内容；论坛可用 board 限定只自转单个板块。 */
  readonly generateAmbientPosts: (
    platform: 'forum' | 'twitter',
    options?: { readonly board?: string },
  ) => Promise<number>;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
  readonly showModal: (title: string, fields: readonly ModalField[]) => Promise<Record<string, string> | null>;
  /** 不可逆操作（删除消息、回撤生成内容、删帖）前的确认弹窗。 */
  readonly showConfirm: (request: ConfirmRequest) => Promise<boolean>;
  readonly showContactPicker: (title: string, contacts: readonly ContactOption[], options?: { readonly min?: number; readonly max?: number }) => Promise<readonly string[] | null>;
  readonly getProgress: () => GenerationProgress;
}

export interface PhoneAppDefinition {
  readonly id: PhoneAppId;
  readonly label: string;
  readonly icon: string;
  readonly navigation: readonly PhoneNavigationItem[];
  readonly render: (context: PhoneViewContext) => HTMLElement;
  /** 应用内子页面的返回目标（如推文详情返回来源列表）；返回 null 走默认返回逻辑。 */
  readonly backRoute?: (route: PhoneRoute) => PhoneRoute | null;
}
