import { phoneLogger } from './logger.js';

const RAW_EXCERPT_LIMIT = 4_000;

/** 截取原始文本：保留头尾并标出省略量，方便判断是被截断还是格式本身不对。 */
export function excerpt(value: unknown, limit = RAW_EXCERPT_LIMIT): string {
  const text = typeof value === 'string' ? value : safeStringify(value);
  if (text.length <= limit) return text;
  const head = text.slice(0, Math.floor(limit * 0.7));
  const tail = text.slice(-Math.floor(limit * 0.25));
  return `${head}\n…（省略 ${text.length - head.length - tail.length} 字）…\n${tail}`;
}

export function describeError(error: unknown): string {
  const value = error instanceof Error ? `${error.name}: ${error.message}` : typeof error === 'string' ? error : safeStringify(error);
  return redactText(value);
}

export interface ModelFailureReport {
  /** 出问题的环节，例如「统一回复」「正文自动解析」「记忆整理」。 */
  readonly stage: string;
  readonly reason: string;
  /** 模型原始输出：排查「格式不对」时最关键的信息。 */
  readonly raw?: string;
  /** 请求侧摘要（模型、长度、参数），不包含密钥。 */
  readonly request?: Readonly<Record<string, unknown>>;
  readonly issues?: readonly string[];
  readonly error?: unknown;
}

/** 模型输出相关的失败：把原始输出、请求摘要与逐条 issue 一起写进日志。 */
export function logModelFailure(report: ModelFailureReport): void {
  phoneLogger.error(`${report.stage}失败：${report.reason}`, {
    ...(report.issues && report.issues.length > 0 ? { issues: report.issues.slice(0, 20).map(redactText) } : {}),
    ...(report.request ? { request: redactRecord(report.request) } : {}),
    ...(report.error !== undefined ? { error: describeError(report.error) } : {}),
    ...(report.raw !== undefined
      ? { rawLength: report.raw.length, raw: redactText(excerpt(report.raw)) }
      : {}),
  });
}

export interface HttpFailureReport {
  readonly stage: string;
  readonly url: string;
  readonly status?: number;
  readonly statusText?: string;
  /** 响应体原文或已解析对象。 */
  readonly body?: unknown;
  readonly request?: Readonly<Record<string, unknown>>;
  readonly error?: unknown;
}

/** 接口请求失败：记录状态码、去掉查询串的地址与响应体原文。 */
export function logHttpFailure(report: HttpFailureReport): void {
  const status = report.status === undefined
    ? '网络错误'
    : `HTTP ${report.status}${report.statusText ? ` ${report.statusText}` : ''}`;
  phoneLogger.error(`${report.stage}请求失败（${status}）`, {
    url: redactUrl(report.url),
    ...(report.request ? { request: redactRecord(report.request) } : {}),
    ...(report.error !== undefined ? { error: describeError(report.error) } : {}),
    ...(report.body !== undefined ? { body: redactText(excerpt(report.body)) } : {}),
  });
}

/** 查询串可能带 token，日志里只保留路径。 */
function redactUrl(url: string): string {
  const index = url.indexOf('?');
  return redactText(index >= 0 ? `${url.slice(0, index)}?…` : url);
}

function redactRecord(record: Readonly<Record<string, unknown>>): Readonly<Record<string, unknown>> {
  return Object.fromEntries(Object.entries(record).map(([key, value]) => [key, redactDiagnosticValue(key, value)]));
}

function redactDiagnosticValue(key: string, value: unknown): unknown {
  if (/token|api.?key|authorization|secret|password/i.test(key)) return '[已脱敏]';
  if (typeof value === 'string') return redactText(value);
  if (Array.isArray(value)) return value.map((item) => redactDiagnosticValue('', item));
  if (value && typeof value === 'object') return redactRecord(value as Readonly<Record<string, unknown>>);
  return value;
}

function redactText(value: string): string {
  return value
    .replace(/\bBearer\s+[A-Za-z0-9._~+/=-]+/gi, 'Bearer [已脱敏]')
    .replace(/\b(?:pst|sk)-[A-Za-z0-9._-]{6,}/gi, '[已脱敏]')
    .replace(/([?&](?:token|key|api[_-]?key|authorization)=)[^&#\s]+/gi, '$1…');
}

export interface OperationFailureReport {
  /** 出问题的环节，例如「数据库写入」「世界书投影」「状态持久化」。 */
  readonly stage: string;
  readonly reason: string;
  /** 操作上下文：表名、行号、作用域等定位信息。 */
  readonly context?: Readonly<Record<string, unknown>>;
  readonly error?: unknown;
}

/** 非模型、非 HTTP 的操作失败：数据库写入、存储持久化、世界书投影等。 */
export function logOperationFailure(report: OperationFailureReport): void {
  phoneLogger.error(`${report.stage}失败：${report.reason}`, {
    ...(report.context ? { context: redactRecord(report.context) } : {}),
    ...(report.error !== undefined ? { error: describeError(report.error) } : {}),
    ...(report.error instanceof Error && report.error.stack
      ? { stack: redactText(report.error.stack).slice(0, 2_000) }
      : {}),
  });
}

function safeStringify(value: unknown): string {
  if (value === undefined) return 'undefined';
  try {
    return JSON.stringify(value) ?? String(value);
  } catch {
    return String(value);
  }
}