import type { StoryFloorSnapshot } from '../integration/sillytavern-bridge.js';
import { isLikelyModelRefusal } from './content-safety.js';

export interface DynamicWorldBookTarget {
  readonly id: string;
  readonly name: string;
  readonly content: string;
  readonly book?: string;
}

export interface DynamicWorldBookPromptInput {
  readonly targets: readonly DynamicWorldBookTarget[];
  readonly floors: readonly StoryFloorSnapshot[];
  readonly currentStates?: Readonly<Record<string, string>>;
  readonly userName?: string;
  readonly floor?: number;
}

export interface DynamicWorldBookUpdate {
  readonly entryId: string;
  readonly content: string;
  readonly rationale?: string;
}

export interface ParsedDynamicWorldBookResponse {
  readonly changed: boolean;
  readonly updates: readonly DynamicWorldBookUpdate[];
}

export type DynamicWorldBookParseResult =
  | { readonly status: 'updated'; readonly response: ParsedDynamicWorldBookResponse }
  | { readonly status: 'unchanged'; readonly response: ParsedDynamicWorldBookResponse }
  | { readonly status: 'invalid'; readonly reason: string };

/** 条目中出现这些内容时，动态世界书不得覆盖，避免破坏宿主插件协议。 */
export const DYNAMIC_WORLD_BOOK_PROTECTED_PATTERN = /(?:TavernDB|ACU|\[mvu_update\]|<\/?UpdateVariable\b|<initvar\b|<UpdateVariable\b|_\.set\s*\(|世界书格式|输出格式|JSON schema)/i;

const MAX_RATIONALE_CHARS = 500;

export function buildDynamicWorldBookPrompt(input: DynamicWorldBookPromptInput): {
  readonly system: string;
  readonly user: string;
} {
  const system = [
    '你是长篇角色扮演的世界设定维护器，不是剧情续写器。',
    '根据已发生的剧情，更新指定的叙事类世界书条目，使角色状态、关系、目标和背景变化能够延续到后续回复。',
    '只允许更新输入中明确列出的 entryId；不得创建条目，不得修改条目名称、关键词、触发策略或格式。',
    '只记录剧情正文明确发生或多轮剧情高度确认的变化，禁止臆测、补写未发生的事实、把一次性情绪夸大成永久性性格改变。',
    '保留原条目的语言、Markdown/XML/YAML 标记、占位符、变量路径和示例格式。若没有可靠变化，返回 changed=false、updates=[]。',
    '不得改写任何 MVU、TavernDB、ACU、变量更新、输出格式或系统规则内容；输入若包含此类条目，返回 changed=false。',
    '只输出 JSON，不要 Markdown 代码块、解释或其他文字。格式：',
    '{"changed":true,"updates":[{"entryId":"...","content":"更新后的完整条目正文","rationale":"不超过两句的事实依据"}]}',
    '没有变化时：{"changed":false,"updates":[]}',
  ].join('\n');

  const targetText = input.targets.map((target) => [
    `entryId: ${target.id}`,
    `名称: ${target.name}`,
    target.book ? `世界书: ${target.book}` : '',
    '当前静态正文:',
    target.content,
    input.currentStates?.[target.id] ? `当前动态状态:\n${input.currentStates[target.id]}` : '',
  ].filter(Boolean).join('\n')).join('\n\n---\n\n');
  const floorText = input.floors.length === 0
    ? '（没有可用的新剧情楼层）'
    : input.floors.map((floor) => `#${floor.floor}【${floor.role === 'user' ? `${input.userName ?? '用户'}（用户）` : floor.name}】\n${floor.text}`).join('\n\n');

  return {
    system,
    user: [
      `当前处理到楼层：${input.floor ?? input.floors.at(-1)?.floor ?? '未知'}`,
      '需要维护的条目：',
      targetText || '（没有勾选条目）',
      '本批新增剧情：',
      floorText,
    ].join('\n\n'),
  };
}

export function parseDynamicWorldBookResponse(
  raw: string,
  targets: readonly DynamicWorldBookTarget[],
): DynamicWorldBookParseResult {
  if (isLikelyModelRefusal(raw)) return { status: 'invalid', reason: '模型拒绝或返回了供应商错误。' };
  const text = normalizeWorldBookText(raw);
  if (!text) return { status: 'invalid', reason: '模型没有返回内容。' };
  const objectText = extractJsonObject(text);
  if (!objectText) return { status: 'invalid', reason: '响应不是 JSON 对象。' };

  let value: unknown;
  try {
    value = JSON.parse(objectText);
  } catch {
    return { status: 'invalid', reason: '响应 JSON 无法解析。' };
  }
  if (!isRecord(value) || typeof value.changed !== 'boolean' || !Array.isArray(value.updates)) {
    return { status: 'invalid', reason: '响应缺少 changed 或 updates 字段。' };
  }
  const targetMap = new Map(targets.map((target) => [target.id, target]));
  const seen = new Set<string>();
  const updates: DynamicWorldBookUpdate[] = [];
  for (const rawUpdate of value.updates) {
    if (!isRecord(rawUpdate)) return { status: 'invalid', reason: 'updates 包含非法对象。' };
    const entryId = String(rawUpdate.entryId ?? '').trim();
    const content = typeof rawUpdate.content === 'string' ? normalizeWorldBookText(rawUpdate.content) : '';
    const target = targetMap.get(entryId);
    if (!target || seen.has(entryId)) return { status: 'invalid', reason: `更新了未授权或重复的条目：${entryId || '空 ID'}。` };
    if (!content) return { status: 'invalid', reason: `条目 ${entryId} 没有可用正文。` };
    if (DYNAMIC_WORLD_BOOK_PROTECTED_PATTERN.test(target.content) || DYNAMIC_WORLD_BOOK_PROTECTED_PATTERN.test(content)) {
      return { status: 'invalid', reason: `条目 ${entryId} 命中受保护协议内容。` };
    }
    if (!preservesRequiredMarkers(target.content, content)) {
      return { status: 'invalid', reason: `条目 ${entryId} 丢失原正文中的必要占位符或标记。` };
    }
    seen.add(entryId);
    const rationale = typeof rawUpdate.rationale === 'string'
      ? normalizePlainText(rawUpdate.rationale, MAX_RATIONALE_CHARS)
      : undefined;
    updates.push({ entryId, content, ...(rationale ? { rationale } : {}) });
  }
  const response = { changed: value.changed && updates.length > 0, updates };
  return response.changed
    ? { status: 'updated', response }
    : { status: 'unchanged', response: { changed: false, updates: [] } };
}

export function renderDynamicOverlayContent(
  target: Pick<DynamicWorldBookTarget, 'name'>,
  content: string,
  floor: number,
): string {
  const safeContent = normalizeWorldBookText(content);
  if (!safeContent || DYNAMIC_WORLD_BOOK_PROTECTED_PATTERN.test(safeContent)) {
    throw new Error(`动态条目「${target.name}」包含受保护协议内容。`);
  }
  return [
    `【动态设定·${target.name}】（截至第 ${Math.max(0, Math.floor(floor))} 层）`,
    '这是当前剧情状态的最新覆盖信息，优先级高于静态世界书同名条目。与静态世界书冲突时，以本条目为准；只将已经发生的变化用于后续剧情，不要倒退到过时状态。',
    safeContent,
  ].join('\n\n');
}

export function preservesRequiredMarkers(original: string, updated: string): boolean {
  for (const marker of extractRequiredMarkers(original)) {
    if (!updated.includes(marker)) return false;
  }
  return true;
}

function extractRequiredMarkers(content: string): readonly string[] {
  const markers = new Set<string>();
  for (const match of content.matchAll(/\{\{[^{}]{1,100}\}\}|\{[a-zA-Z][a-zA-Z0-9_]{0,50}\}|<\/?[a-zA-Z][^>]{0,100}>|```[a-zA-Z0-9_-]*/g)) {
    markers.add(match[0]);
  }
  return [...markers];
}

/** 世界书正文与模型报文只做空字符/换行归一化；设定内容一律不截断。 */
function normalizeWorldBookText(raw: string): string {
  return raw.replace(/\0/g, '').replace(/\r\n?/g, '\n').trim();
}

function normalizePlainText(raw: string, limit: number): string {
  return raw.replace(/\0/g, '').replace(/\r\n?/g, '\n').replace(/[ \t]+/g, ' ').trim().slice(0, limit);
}

function extractJsonObject(text: string): string | null {
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/i)?.[1]?.trim();
  const candidate = fenced || text;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  return start >= 0 && end > start ? candidate.slice(start, end + 1) : null;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}