/**
 * 剧情时间解析：把变量或用户输入中的日期/时间文本转换成时间戳。
 * 支持常见格式：2026-08-13、2026/8/13、2026年8月13日、8月13日（补当前年）、
 * 14:30、14:30:00、14点30分、下午2点30分 等。
 */

export interface VariableLeaf {
  readonly path: string;
  readonly preview: string;
}

const WEEKDAY_STORAGE_PREFIX = 'narrative-phone:weekday-override:';

/** 解析日期文本，返回 {year, month, day}；解析失败返回 null。 */
export function parseStoryDate(text: string, fallback: Date): { year: number; month: number; day: number } | null {
  const cleaned = text.trim();
  if (!cleaned) return null;

  // 2026-08-13 / 2026/8/13 / 2026.8.13
  let match = /(\d{4})\s*[-/.]\s*(\d{1,2})\s*[-/.]\s*(\d{1,2})/.exec(cleaned);
  if (match) return buildDateParts(Number(match[1]), Number(match[2]), Number(match[3]));

  // 2026年8月13日
  match = /(\d{4})\s*年\s*(\d{1,2})\s*月\s*(\d{1,2})\s*[日号]?/.exec(cleaned);
  if (match) return buildDateParts(Number(match[1]), Number(match[2]), Number(match[3]));

  // 8月13日（年份取当前剧情年）
  match = /(\d{1,2})\s*月\s*(\d{1,2})\s*[日号]?/.exec(cleaned);
  if (match) return buildDateParts(fallback.getFullYear(), Number(match[1]), Number(match[2]));

  // 08-13 / 8/13（年份取当前剧情年）
  match = /^(\d{1,2})\s*[-/.]\s*(\d{1,2})$/.exec(cleaned);
  if (match) return buildDateParts(fallback.getFullYear(), Number(match[1]), Number(match[2]));

  return null;
}

/** 解析时间文本，返回 {hour, minute}；解析失败返回 null。 */
export function parseStoryTime(text: string): { hour: number; minute: number } | null {
  const cleaned = text.trim();
  if (!cleaned) return null;

  const periodMatch = /(凌晨|清晨|早上|上午|中午|下午|傍晚|晚上|深夜|夜晚)/.exec(cleaned);
  const period = periodMatch?.[1] ?? null;

  // 14:30 / 14:30:00 / 14：30
  let match = /(\d{1,2})\s*[:：]\s*(\d{1,2})(?:\s*[:：]\s*\d{1,2})?/.exec(cleaned);
  let hour: number | null = null;
  let minute = 0;
  if (match) {
    hour = Number(match[1]);
    minute = Number(match[2]);
  } else {
    // 14点30分 / 14时 / 下午2点
    match = /(\d{1,2})\s*[点时](?:\s*(\d{1,2})\s*分?)?/.exec(cleaned);
    if (match) {
      hour = Number(match[1]);
      minute = match[2] ? Number(match[2]) : 0;
    }
  }
  if (hour === null || !Number.isFinite(hour) || !Number.isFinite(minute)) return null;
  if (hour > 23 || minute > 59) return null;

  if (period && hour <= 12) {
    if ((period === '下午' || period === '傍晚' || period === '晚上' || period === '夜晚') && hour < 12) hour += 12;
    if (period === '中午' && hour < 11) hour += 12;
    if (period === '深夜' && hour >= 10 && hour < 12) hour += 12;
    if (period === '凌晨' && hour === 12) hour = 0;
  }
  return { hour: Math.min(23, hour), minute: Math.min(59, minute) };
}

/**
 * 组合日期与时间文本得到时间戳。
 * - 只有日期：时间沿用 fallback 的时分。
 * - 只有时间：日期沿用 fallback 的年月日。
 * - 都没有解析出来：返回 null。
 */
export function parseStoryDateTime(dateText: string, timeText: string, fallbackTimestamp: number): number | null {
  const fallback = new Date(fallbackTimestamp);
  const dateParts = parseStoryDate(dateText, fallback) ?? parseStoryDate(timeText, fallback);
  const timeParts = parseStoryTime(timeText) ?? parseStoryTime(dateText);
  if (!dateParts && !timeParts) return null;
  const year = dateParts?.year ?? fallback.getFullYear();
  const month = (dateParts?.month ?? fallback.getMonth() + 1) - 1;
  const day = dateParts?.day ?? fallback.getDate();
  const hour = timeParts?.hour ?? fallback.getHours();
  const minute = timeParts?.minute ?? fallback.getMinutes();
  const result = new Date(year, month, day, hour, minute, 0, 0).getTime();
  return Number.isFinite(result) ? result : null;
}

function buildDateParts(year: number, month: number, day: number): { year: number; month: number; day: number } | null {
  if (!Number.isFinite(year) || !Number.isFinite(month) || !Number.isFinite(day)) return null;
  if (year < 1900 || year > 9999 || month < 1 || month > 12 || day < 1 || day > 31) return null;
  return { year, month, day };
}

/** 按点分路径读取嵌套变量值（支持数组下标）。 */
export function resolveVariablePath(source: unknown, path: string): unknown {
  if (!path) return undefined;
  let current: unknown = source;
  for (const segment of path.split('.')) {
    if (current === null || current === undefined) return undefined;
    if (Array.isArray(current)) {
      const index = Number(segment);
      if (!Number.isInteger(index)) return undefined;
      current = current[index];
      continue;
    }
    if (typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

/** 把变量对象拍平成叶子路径列表（只保留字符串/数字叶子），用于绑定选择 UI。 */
export function flattenVariableLeaves(source: unknown, limit = 400): readonly VariableLeaf[] {
  const leaves: VariableLeaf[] = [];
  const walk = (value: unknown, path: string, depth: number): void => {
    if (leaves.length >= limit || depth > 8) return;
    if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') {
      if (path) {
        leaves.push({ path, preview: String(value).slice(0, 40) });
      }
      return;
    }
    if (Array.isArray(value)) {
      value.forEach((item, index) => walk(item, path ? `${path}.${index}` : String(index), depth + 1));
      return;
    }
    if (value && typeof value === 'object') {
      for (const [key, item] of Object.entries(value)) {
        walk(item, path ? `${path}.${key}` : key, depth + 1);
      }
    }
  };
  walk(source, '', 0);
  return leaves;
}

/** 星期显示覆盖（按聊天 scope 存 localStorage，null = 跟随日期计算）。 */
export function getWeekdayOverride(scopeId: string): number | null {
  try {
    const raw = window.localStorage.getItem(`${WEEKDAY_STORAGE_PREFIX}${scopeId}`);
    if (raw === null) return null;
    const value = Number(raw);
    return Number.isInteger(value) && value >= 0 && value <= 6 ? value : null;
  } catch {
    return null;
  }
}

export function setWeekdayOverride(scopeId: string, weekday: number | null): void {
  try {
    const key = `${WEEKDAY_STORAGE_PREFIX}${scopeId}`;
    if (weekday === null) window.localStorage.removeItem(key);
    else window.localStorage.setItem(key, String(weekday));
  } catch {
    // localStorage 不可用时静默忽略。
  }
}

export const WEEKDAY_LABELS = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'] as const;

/** 时钟配置弹窗使用的日期文本（YYYY-MM-DD）。 */
export function formatClockConfigDate(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

/** 时钟配置弹窗使用的时间文本（HH:mm）。 */
export function formatClockConfigTime(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

/** 剧情日期的星期文本（考虑覆盖设置）。 */
export function describeStoryWeekday(timestamp: number, scopeId: string): string {
  const override = getWeekdayOverride(scopeId);
  const index = override ?? new Date(timestamp).getDay();
  return WEEKDAY_LABELS[index] ?? WEEKDAY_LABELS[0];
}
