import type { Profile } from '../../domain/model.js';
import type { PhoneViewContext } from '../app-types.js';
import { button, element } from '../../ui/dom.js';
import { formatTime, renderAvatar } from '../shared-view.js';
import { resolvePublicIdentity } from '../identity.js';
import type { ForumThreadView } from './projection.js';

/** 论坛里所有人都以公开身份出现（匿名昵称优先于真实姓名）。 */
export function forumIdentity(context: PhoneViewContext, profileId: string): string {
  return resolvePublicIdentity(
    context.state.profiles[profileId],
    'forum',
    'profile:self',
    context.state.profiles['profile:self']?.displayName ?? '',
  ).name;
}

export function forumAvatarProfile(profile: Profile | undefined): Profile | undefined {
  if (!profile?.forumAvatarUrl) return profile;
  return { ...profile, avatarUrl: profile.forumAvatarUrl };
}

/** 时间优先显示卡里写的相对时间（「5分钟前」），没有才用剧情时钟。 */
export function forumTime(createdAt: number, timeLabel?: string): string {
  return timeLabel?.trim() || formatTime(createdAt);
}

export function formatForumCount(value: number): string {
  if (value >= 10_000) return `${(value / 10_000).toFixed(value % 10_000 === 0 ? 0 : 1)}万`;
  return String(value);
}

/** 一个计数格：数字在上、名称在下，没有数据的计数不渲染。 */
function renderStat(label: string, value: number, title: string): HTMLElement {
  const stat = element('span', { className: 'phone-forum-stat' });
  stat.title = title;
  stat.append(
    element('strong', { text: formatForumCount(value) }),
    element('small', { text: label }),
  );
  return stat;
}

/** 主题行右侧的公开计数：卡里给了什么就显示什么，没有的不补。 */
export function renderThreadStats(view: ForumThreadView, options: { readonly showHeat?: boolean } = {}): HTMLElement {
  const stats = element('span', { className: 'phone-forum-thread-stats' });
  if (options.showHeat) {
    stats.append(renderStat(
      view.heatEstimated ? '热度*' : '热度',
      view.heat,
      view.heatEstimated ? '卡里没有公开计数，热度由回复数与新鲜度推算' : '按卡里的浏览、点赞与评论数折算',
    ));
  }
  const views = view.metrics.views;
  if (views !== undefined) stats.append(renderStat('浏览', views, '正文里给出的浏览数'));
  stats.append(renderStat('回复', view.metrics.comments ?? view.replyCount, '楼层与评论总数'));
  const likes = view.metrics.likes ?? view.likes;
  if (likes > 0) stats.append(renderStat('赞', likes, '点赞数'));
  return stats;
}

/** 板块、置顶、加精、标签这类元信息统一走一行胶囊。 */
export function renderThreadMeta(context: PhoneViewContext, view: ForumThreadView): HTMLElement {
  const meta = element('span', { className: 'phone-forum-thread-meta' });
  if (view.pinned) meta.append(element('span', { className: 'phone-forum-flag is-pinned', text: '置顶' }));
  if (view.hot) meta.append(element('span', { className: 'phone-forum-flag is-hot', text: '热' }));
  meta.append(element('span', { className: 'phone-forum-board-tag', text: view.board }));
  for (const tag of view.thread.tags?.slice(0, 2) ?? []) {
    meta.append(element('span', { className: 'phone-forum-topic-tag', text: tag }));
  }
  meta.append(element('span', {
    className: 'phone-forum-thread-byline',
    text: `${forumIdentity(context, view.thread.profileId)} · ${forumTime(view.thread.createdAt, view.thread.timeLabel)}`,
  }));
  return meta;
}

/**
 * 主题列表行。名次徽标只在热榜出现，其他列表显示楼主头像，
 * 避免「行首数字到底是排名还是热度」这种含混。
 */
export function renderThreadRow(
  context: PhoneViewContext,
  view: ForumThreadView,
  options: { readonly rank?: number; readonly onOpen: () => void },
): HTMLElement {
  const row = button('', 'phone-forum-thread-row', options.onOpen);
  row.setAttribute('aria-label', `打开主题：${view.title}`);
  if (options.rank !== undefined) {
    const rank = element('span', { className: 'phone-forum-thread-rank', text: String(options.rank) });
    rank.title = `热度第 ${options.rank} 名`;
    row.append(rank);
  } else {
    row.append(renderAvatar(forumAvatarProfile(context.state.profiles[view.thread.profileId]), 'phone-avatar phone-forum-row-avatar'));
  }
  const copy = element('span', { className: 'phone-forum-thread-copy' });
  copy.append(
    element('strong', { className: 'phone-forum-thread-title', text: view.title }),
    renderThreadMeta(context, view),
  );
  row.append(copy, renderThreadStats(view, { showHeat: options.rank !== undefined }));
  return row;
}

export function renderForumEmpty(title: string, detail: string): HTMLElement {
  const empty = element('div', { className: 'phone-empty phone-forum-empty' });
  empty.append(element('strong', { text: title }), element('span', { text: detail }));
  return empty;
}

/** 分区标题：左侧标题，右侧是说明文案，需要时再挂一组操作按钮。 */
export function renderSectionHead(title: string, hint: string, actions: readonly HTMLElement[] = []): HTMLElement {
  const head = element('div', { className: 'phone-forum-section-head' });
  head.append(element('h3', { text: title }), element('span', { text: hint }));
  if (actions.length > 0) {
    const actionRow = element('div', { className: 'phone-forum-section-actions' });
    actionRow.append(...actions);
    head.append(actionRow);
  }
  return head;
}