import { phoneLogger } from '../core/logger.js';
import { quoteIdentifier } from '../db/sheet-dsl.js';
import { parseSheetRuleFields } from '../db/sheet-rules.js';
import type { DbStatement } from '../db/protocol.js';
import { getSillyTavernEventChannel } from './sillytavern-bridge.js';
import { sqRecord, type SqCompatibility, type SqTableBinding } from '../sq/template.js';
import type { MvuSheetView } from '../mvu/projection.js';

export interface SqSheetView extends MvuSheetView { readonly physicalName: string; readonly policy?: string; readonly fillGuide?: string }
export interface SqBridgePort {
  readonly isActive: () => boolean;
  readonly contextKey: () => string;
  readonly metadata: () => SqCompatibility | undefined;
  readonly captureAccess: () => () => boolean;
  readonly readViews: () => Promise<readonly SqSheetView[]>;
  readonly initialize: (template: unknown, isCurrent: () => boolean) => Promise<void>;
  readonly write: (statement: DbStatement, isCurrent: () => boolean) => Promise<{ changes: number; rowId?: number }>;
  readonly host?: Record<string, unknown>;
}

const cellText = (value: unknown): string => value === null || value === undefined ? '' : typeof value === 'object' ? JSON.stringify(value) : String(value);
function typedCell(value: string, type: string): unknown {
  if ((type === 'INTEGER' || type === 'REAL') && value !== '' && Number.isFinite(Number(value))) return Number(value);
  return value;
}

/** 保留外部表键、中文表头和真实 rowid，供原卡同步读取。 */
export function exportSqTables(metadata: SqCompatibility, views: readonly SqSheetView[]): Record<string, unknown> {
  const result: Record<string, unknown> = { mate: metadata.mate };
  for (const [orderNo, table] of metadata.tables.entries()) {
    const view = views.find((item) => item.name === table.name);
    if (!view) continue;
    const rules = view.fillGuide === undefined ? null : parseSheetRuleFields(view.fillGuide);
    const sourceData = rules ? { ...table.sourceData, initNode: rules.initialize, insertNode: rules.insert, updateNode: rules.update, deleteNode: rules.delete } : table.sourceData;
    result[table.key] = { uid: table.uid, name: table.name, orderNo, sourceData,
      exportConfig: table.exportConfig, updateConfig: table.updateConfig,
      content: [['row_id', ...table.columns.map((column) => column.label)], ...view.rows.map((row) => [row.rowId,
        ...table.columns.map((column) => typedCell(row.values[view.columns.indexOf(column.column)] ?? '', column.type))])] };
  }
  return result;
}

/** 同一列接受原 DDL 名、中文标签和内部列名；歧义及未知列直接报告。 */
export function resolveSqValues(table: SqTableBinding, view: SqSheetView, input: unknown, rowId?: number): Record<string, string> {
  const raw = Array.isArray(input) ? Object.fromEntries(input.map((value, index) => [table.columns[index]?.label ?? String(index), value])) : sqRecord(input);
  const values: Record<string, string> = {};
  for (const [key, value] of Object.entries(raw)) {
    if (key === 'row_id' || key === 'rowid') {
      if (value !== null && value !== undefined && value !== '' && rowId !== undefined && Number(value) !== rowId) throw new Error('数据中的行号与写入目标不同。');
      continue;
    }
    const candidates = table.columns.filter((column) => [column.column, column.sourceName, column.label].includes(key));
    if (candidates.length !== 1 || !view.columns.includes(candidates[0]!.column)) throw new Error(`表「${table.name}」中没有唯一可写列「${key}」。`);
    values[candidates[0]!.column] = cellText(value);
  }
  return values;
}

function defaultHost(): Record<string, unknown> {
  try { if (globalThis.window?.parent?.SillyTavern) return globalThis.window.parent as unknown as Record<string, unknown>; } catch { /* 同源限制 */ }
  return globalThis as unknown as Record<string, unknown>;
}

export function createSqDataBridge(port: SqBridgePort) {
  const host = port.host ?? defaultHost();
  let installed = false, identity = '', lastError = '';
  let lifecycle = 0;
  let lastSyncedAt: number | null = null;
  let views: readonly SqSheetView[] = [];
  let snapshot: Record<string, unknown> = {};
  let foreign: unknown;
  let descriptor: PropertyDescriptor | undefined;
  let chain: Promise<unknown> = Promise.resolve();
  const listeners = new Set<(tables: Record<string, unknown>) => unknown>();
  const key = (): string => JSON.stringify([port.contextKey(), port.metadata()]);
  const syncIdentity = (): void => {
    const next = key();
    if (next === identity) return;
    identity = next; snapshot = {}; views = []; lastSyncedAt = null; lastError = '';
  };
  const serial = <T>(task: (isCurrent: () => boolean) => Promise<T>): Promise<T> => {
    syncIdentity();
    const identityAtStart = identity, lifetimeAtStart = lifecycle, access = port.captureAccess();
    const isCurrent = (): boolean => port.isActive() && access() && lifecycle === lifetimeAtStart && key() === identityAtStart;
    const run = chain.then(async () => {
      if (!isCurrent()) throw new Error('SQ 数据接口已切换，请在当前预设重试。');
      try { return await task(isCurrent); } catch (error) {
        if (isCurrent()) lastError = error instanceof Error ? error.message : String(error);
        throw error;
      }
    });
    chain = run.catch(() => undefined);
    return run;
  };
  const refreshNow = async (isCurrent: () => boolean): Promise<void> => {
    const metadata = port.metadata();
    if (!metadata || !isCurrent()) return;
    const current = await port.readViews();
    if (!isCurrent()) return;
    views = current;
    snapshot = exportSqTables(metadata, views);
    lastSyncedAt = Date.now();
    lastError = '';
    for (const listener of listeners) { try { listener(structuredClone(snapshot)); } catch (error) { phoneLogger.warn('SQ 刷新监听器异常', error); } }
    try { getSillyTavernEventChannel()?.emit('moyun_sq_tables_updated', structuredClone(snapshot)); } catch { /* 宿主事件通道可选 */ }
  };
  const locate = (name: unknown): { table: SqTableBinding; view: SqSheetView } => {
    const identifier = String(name);
    const candidates = port.metadata()?.tables.filter((table) => [table.key, table.uid, table.name, table.sqlName].includes(identifier)) ?? [];
    const table = candidates.length === 1 ? candidates[0] : undefined;
    const view = table && views.find((view) => view.name === table.name);
    if (!table || !view) throw new Error(`SQ 表「${identifier}」未就绪或已删除。`);
    return { table, view };
  };
  const mutate = (kind: 'insert' | 'update' | 'delete', name: unknown, selector: unknown, value?: unknown) => serial(async (isCurrent) => {
    await refreshNow(isCurrent);
    if (!isCurrent()) throw new Error('SQ 操作已失效。');
    const { table, view } = locate(name);
    const requested = kind === 'insert' ? sqRecord(value).row_id ?? sqRecord(value).rowid : selector;
    const rowId = requested === null || requested === undefined || requested === '' ? undefined : Number(requested);
    if (rowId !== undefined && (!Number.isSafeInteger(rowId) || rowId <= 0)) throw new Error('SQ 行号必须是正整数。');
    if (kind !== 'insert' && (rowId === undefined || !view.rows.some((row) => row.rowId === rowId))) throw new Error(`表「${table.name}」没有 row_id=${String(selector)} 的记录。`);
    const values = kind === 'delete' ? {} : resolveSqValues(table, view, value, rowId);
    if (kind === 'insert' && !Object.keys(values).length) for (const column of view.columns) values[column] = '';
    if (kind === 'update' && !Object.keys(values).length) return { success: true, changes: 0, rowId };
    const columns = Object.keys(values), physical = quoteIdentifier(view.physicalName);
    let statement: DbStatement;
    if (kind === 'delete') statement = { sql: `DELETE FROM ${physical} WHERE rowid = ?`, params: [rowId!] };
    else if (kind === 'update') statement = { sql: `UPDATE ${physical} SET ${columns.map((column) => `${quoteIdentifier(column)} = ?`).join(', ')} WHERE rowid = ?`, params: [...columns.map((column) => values[column]!), rowId!] };
    else {
      const names = [...(rowId === undefined ? [] : ['rowid']), ...columns];
      statement = { sql: `INSERT INTO ${physical}(${names.map(quoteIdentifier).join(', ')}) VALUES (${names.map(() => '?').join(', ')})`,
        params: [...(rowId === undefined ? [] : [rowId]), ...columns.map((column) => values[column]!)] };
    }
    const result = await port.write(statement, isCurrent);
    try { await refreshNow(isCurrent); } catch (error) {
      if (isCurrent()) lastError = error instanceof Error ? error.message : String(error);
      phoneLogger.warn('SQ 数据已写入，但读取缓存刷新失败', error);
    }
    return { success: true, changes: result.changes, rowId: kind === 'insert' ? result.rowId : rowId };
  });
  const api = {
    __moyunSqBridge: true,
    exportTableAsJson: (): Record<string, unknown> => { syncIdentity(); return port.isActive() ? structuredClone(snapshot) : {}; },
    initGameSession: (_variables: unknown = {}, options: unknown = {}) => serial(async (isCurrent) => {
      const opts = sqRecord(options);
      if (opts.loadPreset === true) throw new Error('SQ 数据桥使用当前数据中心预设；请在数据中心选择要使用的预设。');
      await port.initialize(opts.templateData, isCurrent);
      await refreshNow(isCurrent);
      return { success: true, tables: views.length };
    }),
    insertRow: (table: unknown, data: unknown) => mutate('insert', table, undefined, data),
    updateRow: (table: unknown, rowId: unknown, data: unknown) => mutate('update', table, rowId, data),
    deleteRow: (table: unknown, rowId: unknown) => mutate('delete', table, rowId),
    getAllVariables: (): Record<string, unknown> => {
      syncIdentity();
      if (!port.isActive()) return {};
      const result: Record<string, unknown> = {};
      for (const table of port.metadata()?.tables ?? []) {
        const data = sqRecord(snapshot[table.key]), content = Array.isArray(data.content) ? data.content as unknown[][] : [];
        const rows = content.slice(1).map((row) => Object.fromEntries((content[0] ?? []).map((label, index) => [String(label), row[index]])));
        result[table.key] = rows; result[table.name] = rows;
      }
      return result;
    },
    registerTableUpdateCallback: (callback: (tables: Record<string, unknown>) => unknown) => { if (typeof callback === 'function') listeners.add(callback); return () => listeners.delete(callback); },
    unregisterTableUpdateCallback: (callback: (tables: Record<string, unknown>) => unknown) => listeners.delete(callback),
  };
  return {
    api,
    refresh: () => port.isActive() ? serial(refreshNow) : Promise.resolve(),
    install: (): void => {
      syncIdentity();
      if (installed && host.AutoCardUpdaterAPI === api) return;
      lifecycle += 1;
      descriptor = Object.getOwnPropertyDescriptor(host, 'AutoCardUpdaterAPI');
      foreign = host.AutoCardUpdaterAPI;
      Object.defineProperty(host, 'AutoCardUpdaterAPI', { configurable: true, get: () => api, set: (value) => { if (value !== api) foreign = value; } });
      installed = true;
      try { getSillyTavernEventChannel()?.emit('global_AutoCardUpdaterAPI_initialized'); } catch { /* 宿主事件通道可选 */ }
    },
    uninstall: (): void => {
      lifecycle += 1;
      snapshot = {}; views = []; identity = ''; lastSyncedAt = null; lastError = ''; listeners.clear();
      if (!installed) return;
      if (host.AutoCardUpdaterAPI === api) {
        delete host.AutoCardUpdaterAPI;
        if (descriptor) Object.defineProperty(host, 'AutoCardUpdaterAPI', { ...descriptor, ...('value' in descriptor ? { value: foreign } : {}) });
        else if (foreign !== undefined) host.AutoCardUpdaterAPI = foreign;
      }
      installed = false;
    },
    status: () => ({ installed: installed && host.AutoCardUpdaterAPI === api, tables: views.length, lastSyncedAt, lastError, replacedForeignApi: !!foreign }),
  };
}
