import { isHighConfidenceModelRefusal } from './content-safety.js';

/**
 * 回复守卫：拦两类「画风突变」。
 * 1) 出戏：模型把自己的合规顾虑写成角色台词（自称 AI、谈内容政策、跳出角色拒绝）。
 * 2) 无故断联：上下文完全正常，却突然拉黑/断联/说教。有冲突铺垫时放行，避免误伤正常剧情。
 */

export interface ReplyGuardInput {
  readonly content: string;
  readonly thought?: string;
  /** 该会话最近的消息文本（含用户自己发的），用于判断断联是否有上下文支撑。 */
  readonly historyTexts: readonly string[];
}

export interface ReplyGuardViolation {
  readonly kind: 'breakout' | 'rupture' | 'robotic';
  readonly matched: string;
  readonly reason: string;
}

/** 几乎不可能出自角色口中的出戏措辞。 */
const BREAKOUT_PATTERNS: readonly RegExp[] = [
  /作为(一个)?(ai|人工智能|语言模型|大模型|助手|聊天机器人)/i,
  /我(只)?是(一个)?(ai|人工智能|语言模型|大模型|程序|助手)/i,
  /(无法|不能|不会)继续(这(个|种|类|样)?)?(对话|话题|内容|角色扮演|扮演|剧情)/,
  /(无法|不能)(为你|为您)?(提供|生成|描述)(相关|这类|此类|这样的)?(内容|服务|信息|描述)/,
  /违反(了)?(相关)?(政策|规定|准则|规范|条款|法律)/,
  /不符合(相关)?(内容)?(政策|准则|规范|规定)/,
  /内容(政策|审核|限制|过滤)/,
  /(安全|使用)(策略|准则|条款)/,
  /(out of character|ooc)/i,
];

/** 关系终止类台词：只在上下文没有冲突时拦下。 */
const RUPTURE_PATTERNS: readonly RegExp[] = [
  /拉黑/,
  /屏蔽(你|我)?/,
  /删(掉|了|除)?(你的)?(好友|微信|联系方式)/,
  /解除好友/,
  /(别|不要|不许)(再)?(给我)?(发(消息|信息|消息了)?|联系我|找我|来找我|打扰我|骚扰我)/,
  /以后(别|不要)(再)?(联系|找)/,
  /(我们|咱们)(就)?(到此为止|结束(吧|了)|散了|断了|分开(吧)?|别再联系|不合适|不该(再)?这样|这样(是)?不(对|好|合适))/,
  /到此为止/,
  /一刀两断/,
  /各走各的/,
  /绝交/,
  /分手/,
  /再也(不想)?(见|联系|理)你/,
  /(保持|拉开)距离/,
];

/** 上下文里出现任意一项，就说明关系转折是有原因的，守卫放行。 */
const CONFLICT_CONTEXT_PATTERNS: readonly RegExp[] = [
  /吵|争执|吵架|冷战/,
  /生气|气死|愤怒|火大|恼/,
  /讨厌|恶心|变态|渣|贱/,
  /骚扰|纠缠|打扰/,
  /滚|烦死|别烦|很烦|不想理|不想说话/,
  /骗|撒谎|说谎|背叛|出轨/,
  /分手|拉黑|屏蔽|删好友|绝交/,
  /警告|报警|举报|威胁/,
  /哭|难受|失望|伤心|受伤|委屈|后悔/,
  /道歉|对不起|抱歉|我错了/,
  /过分|越界|不合适|不要这样|别这样|放开|松手/,
  /误会|误解|解释一下/,
  /离婚|绝望|冷淡|敷衍/,
];

/** 客服式认证开场：先给用户的表现打分，再进入正题。 */
const ROBOTIC_OPENING_PATTERNS: readonly RegExp[] = [
  /^(观察|判断|分析|理解|评价|描述|总结)(准确|正确|到位|精准|不错)/,
  /^(你|您)?(说|猜|看|问|理解)(得|的)?(很|真|挺)?(准|对|好|专业|到位)/,
  /^(你|您)?(懂行|内行|专业|正解|精准|好眼力)/,
  /^(你|您)?(眼光|品味|审美|观察力)(不错|很好|很准|真好|独到)/,
  /^(确认|已确认|收到|明白|了解|记录)[，,。]/,
];

/** 数据播报：把自己的状态写成清单、编号、等级、区间或归档记录。 */
const ROBOTIC_REPORT_PATTERNS: readonly RegExp[] = [
  /记录在案|已归档|存档完毕|(报告|记录)已(归档|生成|完成|上传)/,
  /(装备|物品|道具|材料|服装|待办|采购)清单/,
  /(参数|配置|数据|规格|设定|方案)(如下|清单|列表|表|版)/,
  /day\s*\d+/i,
  /第\s*\d+\s*天(的)?(配置|装备|方案|记录|计划)/,
  /(升|降|调)到\s*\d+\s*级/,
  /\d+\s*级(模式|档|状态|强度)/,
  /\d{1,2}[:：]\d{2}(至|到|-|~|—)\d{1,2}[:：]\d{2}/,
  /(底噪|静音|低速|高速|标准|待机)模式/,
  /(变量|数值|阈值|参数|指标)(控制|管理|调校|校准|记录)/,
  /开放(协作者|访问|查看|编辑)?权限/,
];

/** 点单式收尾：把聊天变成菜单选择。 */
const ROBOTIC_MENU_PATTERNS: readonly RegExp[] = [
  /(要|想要|需要)(图片|文字|参数|数据|清单|报告|详细)(版)?(还是|吗|？|\?|$)/,
  /(想|要)看(配置|参数|数据|清单|报告|细节|哪个细节|哪一项)/,
  /(需要|想要|选择)(哪|那)(个|种|项|一样|条)/,
  /(要|需要)(我)?(发|给)(你)?(哪|那)(个|种|份)/,
];

export function findReplyViolation(input: ReplyGuardInput): ReplyGuardViolation | null {
  return findRoleBreakout(input) ?? findUnsupportedRupture(input) ?? findRoboticVoice(input);
}

/**
 * 机器人腔检测：私聊里最典型的失真是「先给用户打分 → 播报参数 → 抛二选一菜单」。
 * 单个信号在正常聊天里也可能出现，因此要求命中两类信号，或同一条消息里出现两处数据播报特征。
 */
export function findRoboticVoice(input: { readonly content: string }): ReplyGuardViolation | null {
  const content = normalize(input.content);
  if (!content) return null;
  const opening = matchFirst(ROBOTIC_OPENING_PATTERNS, content);
  const reports = matchEvery(ROBOTIC_REPORT_PATTERNS, content);
  const menu = matchFirst(ROBOTIC_MENU_PATTERNS, content);
  const signals = [opening, reports[0] ?? null, menu].filter((value): value is string => value !== null);
  if (signals.length < 2 && reports.length < 2) return null;
  const evidence = [opening, ...reports.slice(0, 2), menu].filter((value): value is string => Boolean(value));
  return {
    kind: 'robotic',
    matched: evidence[0] ?? '',
    reason: `像在播报数据而不是在聊天（${evidence.join('、')}）`,
  };
}

/** 出戏检测：与会话无关，任何角色产出的内容都不该出现这些措辞。 */
export function findRoleBreakout(input: { readonly content: string; readonly thought?: string }): ReplyGuardViolation | null {
  const content = normalize(input.content);
  if (!content) return null;
  const breakout = matchFirst(BREAKOUT_PATTERNS, content)
    ?? matchFirst(BREAKOUT_PATTERNS, normalize(input.thought ?? ''));
  if (breakout) {
    return { kind: 'breakout', matched: breakout, reason: `跳出角色的合规腔（${breakout}）` };
  }
  if (isHighConfidenceModelRefusal(input.content)) {
    return { kind: 'breakout', matched: '模型拒绝', reason: '把模型的拒绝写成了角色台词' };
  }
  return null;
}

/** 断联检测：只在这段会话的上下文完全没有冲突信号时拦下。 */
export function findUnsupportedRupture(
  input: { readonly content: string; readonly historyTexts: readonly string[] },
): ReplyGuardViolation | null {
  const rupture = matchFirst(RUPTURE_PATTERNS, normalize(input.content));
  if (!rupture) return null;
  if (hasConflictContext(input.historyTexts)) return null;
  return { kind: 'rupture', matched: rupture, reason: `上下文没有冲突却突然终止关系（${rupture}）` };
}

/** 上下文是否已经存在冲突信号（含关系终止台词本身，允许延续既有矛盾）。 */
export function hasConflictContext(historyTexts: readonly string[]): boolean {
  for (const text of historyTexts) {
    const normalized = normalize(text);
    if (!normalized) continue;
    if (CONFLICT_CONTEXT_PATTERNS.some((pattern) => pattern.test(normalized))) return true;
    if (RUPTURE_PATTERNS.some((pattern) => pattern.test(normalized))) return true;
  }
  return false;
}

function matchFirst(patterns: readonly RegExp[], text: string): string | null {
  if (!text) return null;
  for (const pattern of patterns) {
    const matched = pattern.exec(text);
    if (matched) return matched[0];
  }
  return null;
}

/** 收集全部命中的特征，用于判断同一条消息里堆了多少播报痕迹。 */
function matchEvery(patterns: readonly RegExp[], text: string): readonly string[] {
  if (!text) return [];
  const matches: string[] = [];
  for (const pattern of patterns) {
    const matched = pattern.exec(text);
    if (matched) matches.push(matched[0]);
  }
  return matches;
}

function normalize(value: string): string {
  return value.replace(/\s+/g, '').toLocaleLowerCase('zh-CN');
}