import type { PhoneState } from '../domain/model.js';

export interface BatchRevertResult {
  readonly state: PhoneState;
  readonly batchId: string;
  readonly removedMessages: number;
  readonly removedPosts: number;
  readonly removedInteractions: number;
  readonly removedConversations: number;
  readonly removedOutboxItems: number;
}

/** 找到最近一次已完成/部分完成的生成批次。 */
export function findLatestRevertibleBatchId(state: PhoneState): string | null {
  const candidates = Object.values(state.batches)
    .filter((batch) => batch.status === 'completed' || batch.status === 'partial')
    .sort((left, right) => (right.completedAt ?? right.createdAt) - (left.completedAt ?? left.createdAt));
  return candidates[0]?.id ?? null;
}

/**
 * 完整撤销一个生成批次：
 * - 删除批次生成的 AI 消息、动态与互动；
 * - 删除该批次消费的用户消息/帖子及 outbox，不再重新排队；
 * - 匿名会话若因此没有消息，则级联删除会话、匹配互动与临时档案；
 * - 清理不再被引用的路人档案与批次记录。
 * 纯函数：不修改传入状态。
 */
export function revertBatchFromState(state: PhoneState, batchId: string): BatchRevertResult | null {
  const batch = state.batches[batchId];
  if (!batch) return null;
  const actionPrefix = `action:${batchId}:`;

  const batchOutboxIds = new Set(batch.outboxIds);
  const consumedOutbox = Object.values(state.outbox).filter(
    (item) => batchOutboxIds.has(item.id) || item.batchId === batchId,
  );
  const consumedMessageIds = new Set(
    consumedOutbox.filter((item) => item.entityType === 'message').map((item) => item.entityId),
  );
  const consumedPostIds = new Set(
    consumedOutbox.filter((item) => item.entityType === 'post').map((item) => item.entityId),
  );

  const removedMessageIds = new Set<string>(consumedMessageIds);
  for (const [id, message] of Object.entries(state.messages)) {
    if (message.batchId === batchId || message.actionId?.startsWith(actionPrefix)) removedMessageIds.add(id);
  }

  const removedPostIds = new Set<string>(consumedPostIds);
  for (const [id, post] of Object.entries(state.posts)) {
    if (post.actionId?.startsWith(actionPrefix)) removedPostIds.add(id);
  }

  const messages = Object.fromEntries(
    Object.entries(state.messages).filter(([id]) => !removedMessageIds.has(id)),
  );
  const posts = Object.fromEntries(
    Object.entries(state.posts).filter(([id]) => !removedPostIds.has(id)),
  );

  let removedInteractions = 0;
  let interactions = Object.fromEntries(
    Object.entries(state.interactions).filter(([, interaction]) => {
      const remove = interaction.actionId?.startsWith(actionPrefix)
        || removedPostIds.has(interaction.targetId)
        || removedMessageIds.has(interaction.targetId);
      if (remove) removedInteractions += 1;
      return !remove;
    }),
  );

  const affectedAnonymousConversationIds = new Set(
    consumedOutbox
      .filter((item) => item.appId === 'anonymous' && item.conversationId)
      .map((item) => item.conversationId as string),
  );
  const emptyAnonymousConversationIds = new Set(
    [...affectedAnonymousConversationIds].filter((conversationId) =>
      !Object.values(messages).some((message) => message.conversationId === conversationId)),
  );
  const removedUnreadByConversation = new Map<string, number>();
  for (const messageId of removedMessageIds) {
    const message = state.messages[messageId];
    if (message?.direction !== 'incoming') continue;
    removedUnreadByConversation.set(
      message.conversationId,
      (removedUnreadByConversation.get(message.conversationId) ?? 0) + 1,
    );
  }
  const conversations = Object.fromEntries(
    Object.entries(state.conversations)
      .filter(([conversationId]) => !emptyAnonymousConversationIds.has(conversationId))
      .map(([conversationId, conversation]) => [
        conversationId,
        {
          ...conversation,
          unreadCount: Math.max(0, conversation.unreadCount - (removedUnreadByConversation.get(conversationId) ?? 0)),
        },
      ]),
  );
  if (emptyAnonymousConversationIds.size > 0) {
    interactions = Object.fromEntries(
      Object.entries(interactions).filter(([, interaction]) => {
        const remove = emptyAnonymousConversationIds.has(interaction.targetId);
        if (remove) removedInteractions += 1;
        return !remove;
      }),
    );
  }

  const outbox = Object.fromEntries(
    Object.entries(state.outbox).filter(([id, item]) => !batchOutboxIds.has(id) && item.batchId !== batchId),
  );

  // 清理本轮后不再被消息、动态、互动或会话引用的路人/匿名临时档案。
  const profiles = Object.fromEntries(
    Object.entries(state.profiles).filter(([profileId]) => {
      const temporary = isTemporaryProfileId(profileId, 'ambient-profile')
        || isTemporaryProfileId(profileId, 'anonymous-profile');
      if (!temporary) return true;
      return Object.values(messages).some((message) => message.profileId === profileId)
        || Object.values(posts).some((post) => post.profileId === profileId)
        || Object.values(interactions).some((interaction) => interaction.actorProfileId === profileId || interaction.targetId === profileId)
        || Object.values(conversations).some((conversation) => conversation.participantIds.includes(profileId));
    }),
  );

  const batches = Object.fromEntries(
    Object.entries(state.batches).filter(([id]) => id !== batchId),
  );

  // 撤销本轮时把剧情时钟回退到批次开始前，避免时间残留推进。
  const revertedClock = batch.createdAt > 0 && state.worldClock.now > batch.createdAt
    ? {
        ...state.worldClock,
        now: batch.createdAt,
        source: 'user' as const,
        reason: `batch-revert:${batchId}`,
      }
    : state.worldClock;

  const next: PhoneState = {
    ...state,
    revision: state.revision + 1,
    profiles,
    conversations,
    messages,
    messageOrder: state.messageOrder.filter((id) => !removedMessageIds.has(id)),
    posts,
    postOrder: state.postOrder.filter((id) => !removedPostIds.has(id)),
    interactions,
    outbox,
    batches,
    appliedActionIds: state.appliedActionIds.filter((actionId) => !actionId.startsWith(actionPrefix)),
    worldClock: revertedClock,
  };

  return {
    state: next,
    batchId,
    removedMessages: removedMessageIds.size,
    removedPosts: removedPostIds.size,
    removedInteractions,
    removedConversations: emptyAnonymousConversationIds.size,
    removedOutboxItems: consumedOutbox.length,
  };
}

function isTemporaryProfileId(profileId: string, prefix: 'ambient-profile' | 'anonymous-profile'): boolean {
  return profileId.startsWith(`${prefix}:`) || profileId.includes(`:${prefix}:`);
}
