import { normalizeName } from './identity.js';
import type { CharacterLock, FanficSecret } from './model.js';

export interface FanficConsistencyInput {
  /** 说话人的稳定角色 ID 与名字；解析不到角色锁时跳过全部检查。 */
  readonly speakerName: string;
  readonly content: string;
  readonly character: CharacterLock | null;
  readonly secrets: readonly FanficSecret[];
}

export interface FanficConsistencyViolation {
  readonly kind: 'voice' | 'knowledge';
  readonly matched: string;
  readonly reason: string;
}

/** 判定“引用了秘密原文”所需的连续字符长度：短于此长度的重合视为巧合。 */
const SECRET_QUOTE_LENGTH = 6;

/**
 * 同人一致性检查：只拦两类可判定的硬冲突，避免误伤正常剧情。
 * 1) 说出人物锁里标注“绝不会说”的表达。
 * 2) 复述了自己并不知情的秘密。
 */
export function findFanficViolation(
  input: FanficConsistencyInput,
): FanficConsistencyViolation | null {
  return findForbiddenVoice(input) ?? findSecretLeak(input);
}

function findForbiddenVoice(input: FanficConsistencyInput): FanficConsistencyViolation | null {
  const forbidden = input.character?.voice.forbidden ?? [];
  if (forbidden.length === 0) return null;
  const content = normalizeName(input.content);
  if (!content) return null;
  for (const phrase of forbidden) {
    const key = normalizeName(phrase);
    // 过短的禁用项（一两个字）无法可靠判定，跳过而不是制造误报。
    if (key.length < 3 || !content.includes(key)) continue;
    return {
      kind: 'voice',
      matched: phrase,
      reason: `${input.character?.name ?? input.speakerName} 说出了人物锁标注绝不会说的表达（${phrase}）`,
    };
  }
  return null;
}

function findSecretLeak(input: FanficConsistencyInput): FanficConsistencyViolation | null {
  if (input.secrets.length === 0) return null;
  const speakerKey = normalizeName(input.speakerName);
  const characterKey = normalizeName(input.character?.name ?? '');
  const content = normalizeName(input.content);
  if (!content) return null;
  for (const secret of input.secrets) {
    if (knowsSecret(secret, [speakerKey, characterKey, ...(input.character?.aliases ?? []).map(normalizeName)])) continue;
    const quoted = findSharedRun(content, normalizeName(secret.text), SECRET_QUOTE_LENGTH);
    if (!quoted) continue;
    return {
      kind: 'knowledge',
      matched: quoted,
      reason: `${input.character?.name ?? input.speakerName} 复述了自己并不知情的信息（${secret.text.slice(0, 40)}）`,
    };
  }
  return null;
}

function knowsSecret(secret: FanficSecret, speakerKeys: readonly string[]): boolean {
  const keys = speakerKeys.filter(Boolean);
  if (keys.length === 0) return true;
  return secret.knownBy.some((name) => {
    const known = normalizeName(name);
    return known.length > 0 && keys.some((key) => key === known || key.includes(known) || known.includes(key));
  });
}

/** 找出两段文本共享的最长连续片段（达到阈值即返回），用于判断是否在复述原文。 */
export function findSharedRun(haystack: string, needle: string, minLength: number): string | null {
  if (haystack.length < minLength || needle.length < minLength) return null;
  for (let length = Math.min(needle.length, 24); length >= minLength; length -= 1) {
    for (let start = 0; start + length <= needle.length; start += 1) {
      const candidate = needle.slice(start, start + length);
      if (haystack.includes(candidate)) return candidate;
    }
  }
  return null;
}