import type { AppId, Profile } from '../domain/model.js';

export interface PublicIdentity {
  readonly name: string;
  readonly handle?: string;
  readonly anonymous: boolean;
}

/**
 * 公开平台只暴露平台身份，不把微信联系人备注或内部角色档案当作实名证明。
 * 只有 User 自己沿用真实名字；其他档案使用应用别名或通用匿名名。
 */
export function resolvePublicIdentity(
  profile: Profile | undefined,
  appId: Extract<AppId, 'forum' | 'twitter' | 'wechat'>,
  selfProfileId: string,
  selfName: string,
): PublicIdentity {
  if (!profile) return { name: '匿名网友', anonymous: true };
  if (profile.id === selfProfileId || profile.displayName === selfName) {
    return {
      name: appId === 'twitter'
        ? profile.twitterName?.trim() || profile.displayName
        : appId === 'forum'
          ? profile.forumName?.trim() || profile.aliases.forum?.trim() || profile.displayName
          : profile.displayName,
      ...(appId === 'twitter' ? { handle: profile.aliases.twitter } : {}),
      anonymous: false,
    };
  }

  if (appId === 'twitter') {
    const name = profile.twitterName?.trim() || profile.aliases.twitter?.replace(/^@/, '').trim() || '匿名网友';
    return { name, handle: profile.aliases.twitter, anonymous: true };
  }

  const alias = appId === 'forum'
    ? profile.forumName?.trim() || profile.aliases.forum?.trim()
    : profile.aliases[appId]?.trim();
  return { name: alias || '匿名网友', anonymous: true };
}