/**
 * 手机操作文案注册表：把「操作名 + 进行中 / 成功 / 失败」三态文案集中声明在一处。
 *
 * 标题一律渲染为「墨韵手机 {操作名}」，副文案由这里给出默认值；
 * 具体调用点只提供操作 id 与真实结果，不再自己拼字符串。
 */

export interface OperationCopy {
  /** 操作名，渲染为标题「墨韵手机 {name}」。 */
  readonly name: string;
  /** 进行中文案。 */
  readonly pending: string;
  /** 结果没有自带文案时的成功兜底。 */
  readonly success: string;
  /** 失败文案前缀，最终形态为「{fail}：{原因}」。 */
  readonly fail: string;
  /**
   * 瞬时操作：不显示进行中卡片，只在结束时给出终态提示。
   * 用于毫秒级的本地读写，避免卡片一闪而过。
   */
  readonly instant?: boolean;
  /** 终态提示的显示时长；不填则由任务层按成功/失败取默认值。 */
  readonly successMs?: number;
  /**
   * 由业务自己驱动三态（或纯界面数据加载），不参与入口自动包裹。
   * 例如手机内容生成的进度是流式的，由生成进度订阅独占那张卡片。
   */
  readonly manual?: boolean;
}

type CopyInput = Omit<OperationCopy, 'success' | 'fail'> & {
  readonly success?: string;
  readonly fail?: string;
};

/** 补齐成功/失败兜底文案，让注册表只写必要信息。 */
function copy(input: CopyInput): OperationCopy {
  return {
    ...input,
    success: input.success ?? `${input.name}完成`,
    fail: input.fail ?? `${input.name}失败`,
  };
}

