export type ShellOperationId = keyof typeof SHELL_OPERATIONS;
export type RuntimeOperationId = keyof typeof RUNTIME_OPERATIONS;
export type PhoneOperationId = ShellOperationId | RuntimeOperationId;

const ALL_OPERATIONS: Readonly<Record<string, OperationCopy>> = {
  ...SHELL_OPERATIONS,
  ...RUNTIME_OPERATIONS,
};

/** 未登记的 id 退化为「以 id 当操作名」，保证新功能接入时也不会丢提示。 */
export function operationCopy(id: string): OperationCopy {
  return ALL_OPERATIONS[id] ?? copy({ name: id, pending: '正在处理…' });
}

/** 统一标题：墨韵手机 {操作名}。 */
export function operationTitle(id: string): string {
  return `墨韵手机 ${operationCopy(id).name}`;
}
