import { canonCharacterId, uniqueTexts } from './identity.js';
import {
  isRecord,
  parseJsonValue,
  pickValue,
  readFlexibleRecordList,
  readFlexibleTextList,
  readText,
  unwrapJsonPayload,
} from './json.js';
import type {
  CanonChunk,
  CanonConfidence,
  CanonFact,
  CanonFactKind,
  CanonRelationship,
  CharacterLock,
  VoiceFingerprint,
} from './model.js';

export interface CanonExtraction {
  readonly characters: readonly CharacterLock[];
  readonly facts: readonly CanonFact[];
  readonly worldRules: readonly string[];
}

const FACT_KINDS: readonly CanonFactKind[] = ['trait', 'value', 'relationship', 'event', 'rule', 'knowledge', 'voice'];
const CONFIDENCES: readonly CanonConfidence[] = ['high', 'medium', 'low'];

/** 键名别名表：模型会在英文、下划线与中文键名之间摇摆，全部接住而不是判为格式错误。 */
const CHARACTER_KEYS = ['characters', 'characterLocks', 'character_locks', 'character', '人物', '人物锁', '角色'];
const FACT_KEYS = ['facts', 'canonFacts', 'canon_facts', 'fact', '事实', '原著事实'];
const WORLD_RULE_KEYS = ['worldRules', 'world_rules', 'worldrules', 'world_rule', 'rules', '世界规则', '规则'];
const CHARACTER_ITEM_KEYS = [
  'name', 'aliases', 'core', 'values', 'knowledge', 'voice', 'relationships', 'signatureLines',
  'signature_lines', 'alias', 'personality', '姓名', '别名', '性格',
];
const NAME_KEYS = ['name', 'character', 'characterName', 'character_name', '姓名', '名字', '角色', '角色名'];
const ALIAS_KEYS = ['aliases', 'alias', 'nicknames', 'nickname', 'otherNames', 'other_names', '别名', '称号', '小名'];
const CORE_KEYS = ['core', 'personality', 'persona', 'traits', 'summary', '核心', '性格', '人格'];
const VALUE_KEYS = ['values', 'value', 'beliefs', 'bottomLines', 'bottom_lines', 'principles', '价值观', '底线'];
const KNOWLEDGE_KEYS = ['knowledge', 'knows', 'awareness', 'information', '认知', '知识', '认知边界'];
const VOICE_KEYS = ['voice', 'speech', 'tone', 'voiceFingerprint', 'voice_fingerprint', '语感', '说话方式'];
const RELATIONSHIP_KEYS = ['relationships', 'relationship', 'relations', 'relation', '关系', '人物关系'];
const SIGNATURE_KEYS = ['signatureLines', 'signature_lines', 'quotes', 'lines', 'signature', '台词', '经典台词'];
const FACT_TEXT_KEYS = ['text', 'content', 'fact', 'description', 'detail', 'summary', '内容', '事实', '描述'];
const FACT_KIND_KEYS = ['kind', 'type', 'category', '类型', '类别'];
const FACT_CHARACTER_KEYS = ['characters', 'character', 'people', 'names', 'who', '人物', '角色'];
const CONFIDENCE_KEYS = ['confidence', 'certainty', 'reliability', '可信度', '置信度'];
const CHUNK_KEYS = ['chunkId', 'chunk_id', 'chunk', 'source', 'sourceId', '片段', '片段编号'];

/** 中文枚举值映射：模型经常直接写中文，不该因此丢掉整条事实。 */
const FACT_KIND_ALIASES: ReadonlyMap<string, CanonFactKind> = new Map([
  ['性格', 'trait'], ['特质', 'trait'], ['特征', 'trait'],
  ['价值观', 'value'], ['底线', 'value'],
  ['关系', 'relationship'], ['人物关系', 'relationship'],
  ['事件', 'event'], ['剧情', 'event'], ['经历', 'event'],
  ['规则', 'rule'], ['设定', 'rule'], ['世界规则', 'rule'],
  ['知识', 'knowledge'], ['认知', 'knowledge'], ['信息', 'knowledge'],
  ['语感', 'voice'], ['台词', 'voice'], ['说话方式', 'voice'],
]);
const CONFIDENCE_ALIASES: ReadonlyMap<string, CanonConfidence> = new Map([
  ['高', 'high'], ['很高', 'high'], ['确定', 'high'], ['明确', 'high'],
  ['中', 'medium'], ['中等', 'medium'], ['一般', 'medium'],
  ['低', 'low'], ['很低', 'low'], ['推测', 'low'], ['不确定', 'low'],
]);

export function buildCanonExtractionPrompt(
  chunks: readonly CanonChunk[],
  knownNames: readonly string[],
): { readonly system: string; readonly user: string } {
  return {
    system: [
      '你是同人剧情引擎的原著解析器，不是聊天助手。',
      '从给定的原著资料片段中提取可以长期复用的人物设定与世界规则，只输出 JSON。',
      '直接以 { 开头、以 } 结尾输出；不要写代码围栏、注释或任何解释文字。',
      '字段：characters（数组）、facts（数组）、worldRules（字符串数组）。',
      'characters[] 字段：name、aliases、core、values、knowledge、voice{register,habits,forbidden}、relationships[{target,summary}]、signatureLines。',
      'aliases、core、values、knowledge、signatureLines、voice.habits、voice.forbidden 必须是字符串数组；只有一条也要写成数组，没有内容就写 []。',
      'core 写核心人格与行为倾向；values 写价值观、底线与绝不会做的事；knowledge 写该角色在原著中知道与不知道的关键信息边界。',
      'voice.register 概括语体（如冷硬短句、书面文言、少年口语）；voice.habits 写标点、口癖、称呼习惯；voice.forbidden 写这个角色绝不会说的表达。',
      'signatureLines 只能摘录资料中真实出现过的短句，最多 4 条，每条不超过 40 字，不要自行创作。',
      'facts[] 字段：kind（trait/value/relationship/event/rule/knowledge/voice）、text、characters（涉及角色名数组）、confidence（high/medium/low）。',
      'facts 只记录资料里明确写出的内容；推断内容必须标 low，且不得写成既定事实。',
      'worldRules 写世界观硬规则（力量体系、禁忌、社会结构等），与具体角色无关。',
      '严禁编造资料中不存在的人物、关系或事件；资料信息不足时留空数组。',
      '每条内容都要短：单条不超过 80 字，characters 最多 12 个人物，facts 最多 20 条；宁可少写也必须把 JSON 完整闭合。',
    ].join('\n'),
    user: [
      knownNames.length > 0 ? `已知角色（同名请沿用该写法）：${knownNames.slice(0, 40).join('、')}` : '暂无已知角色。',
      '原著资料片段：',
      chunks.map((chunk) => `【片段 ${chunk.id}${chunk.heading ? ` · ${chunk.heading}` : ''}】\n${chunk.text}`).join('\n\n'),
    ].join('\n\n'),
  };
}

/** 解析原著抽取结果；结构非法返回 null，由调用方决定重试或跳过该批。 */
export function parseCanonExtraction(
  raw: string,
  chunks: readonly CanonChunk[],
  now: number,
): CanonExtraction | null {
  const parsed = parseJsonValue(raw);
  if (!parsed) return null;
  const value = isRecord(parsed)
    ? unwrapJsonPayload(parsed, [...CHARACTER_KEYS, ...FACT_KEYS, ...WORLD_RULE_KEYS])
    : classifyCanonList(parsed);
  const primaryChunk = chunks[0];
  const chunkIds = uniqueTexts(chunks.map((chunk) => chunk.id));
  const characters = readFlexibleRecordList(pickValue(value, CHARACTER_KEYS), 24, {
    keyField: 'name',
    keyValueKey: 'core',
    textKey: 'name',
    itemKeys: CHARACTER_ITEM_KEYS,
  })
    .map((record) => toCharacterLock(record, chunkIds, now))
    .filter((character): character is CharacterLock => character !== null);
  const facts = readFlexibleRecordList(pickValue(value, FACT_KEYS), 60, { textKey: 'text' })
    .map((record, index) => toCanonFact(record, chunks, primaryChunk, index))
    .filter((fact): fact is CanonFact => fact !== null);
  const worldRules = readFlexibleTextList(pickValue(value, WORLD_RULE_KEYS), 20, 300);
  if (characters.length === 0 && facts.length === 0 && worldRules.length === 0) return null;
  return { characters, facts, worldRules };
}

/**
 * 顶层只给了一个数组时的归类：模型省掉外层对象是常见偷懒。
 * 带名字的对象数组算人物，带正文/类型的算事实，纯字符串数组算世界规则。
 */
function classifyCanonList(items: readonly unknown[]): Record<string, unknown> {
  const records = items.filter(isRecord);
  if (records.some((record) => pickValue(record, NAME_KEYS) !== undefined)) return { characters: items };
  if (records.some((record) => (
    pickValue(record, FACT_TEXT_KEYS) !== undefined || pickValue(record, FACT_KIND_KEYS) !== undefined
  ))) {
    return { facts: items };
  }
  return { worldRules: items };
}

function toCharacterLock(
  record: Record<string, unknown>,
  chunkIds: readonly string[],
  now: number,
): CharacterLock | null {
  const name = readText(pickValue(record, NAME_KEYS), 60);
  const id = canonCharacterId(name);
  if (!id) return null;
  return {
    id,
    name,
    aliases: readFlexibleTextList(pickValue(record, ALIAS_KEYS), 12, 60),
    core: readFlexibleTextList(pickValue(record, CORE_KEYS), 10, 200),
    values: readFlexibleTextList(pickValue(record, VALUE_KEYS), 10, 200),
    knowledge: readFlexibleTextList(pickValue(record, KNOWLEDGE_KEYS), 10, 200),
    voice: toVoiceFingerprint(pickValue(record, VOICE_KEYS)),
    relationships: toRelationships(pickValue(record, RELATIONSHIP_KEYS)),
    signatureLines: readFlexibleTextList(pickValue(record, SIGNATURE_KEYS), 4, 40),
    sourceIds: chunkIds,
    manual: false,
    updatedAt: now,
  };
}

/** voice 可能是对象、单个字符串（语体）或习惯数组，三种形态都接住。 */
function toVoiceFingerprint(value: unknown): VoiceFingerprint {
  if (typeof value === 'string') {
    return { register: readText(value, 120), habits: [], forbidden: [] };
  }
  if (Array.isArray(value)) {
    return { register: '', habits: readFlexibleTextList(value, 8, 120), forbidden: [] };
  }
  const record = isRecord(value) ? value : {};
  return {
    register: readText(pickValue(record, ['register', 'tone', 'style', 'voice', '语体', '语气']), 120),
    habits: readFlexibleTextList(pickValue(record, ['habits', 'habit', 'tics', 'quirks', '习惯', '口癖']), 8, 120),
    forbidden: readFlexibleTextList(
      pickValue(record, ['forbidden', 'avoid', 'never', 'taboo', '禁忌', '绝不会说']),
      8,
      120,
    ),
  };
}

/** 关系可能写成对象、`{"燕清":"同门师妹"}` 字典，或 `燕清：同门师妹` 字符串。 */
function toRelationships(value: unknown): readonly CanonRelationship[] {
  return readFlexibleRecordList(value, 12, {
    keyField: 'target',
    keyValueKey: 'summary',
    textKey: 'summary',
    itemKeys: ['target', 'targetName', 'target_name', 'summary', 'to', '对象', '关系'],
  }).flatMap((record) => {
    const rawTarget = readText(pickValue(record, ['target', 'targetName', 'target_name', 'to', 'name', '对象', '角色']), 60);
    const rawSummary = readText(pickValue(record, ['summary', 'relation', 'description', 'text', '关系', '说明']), 200);
    const { target, summary } = rawTarget && rawSummary
      ? { target: rawTarget, summary: rawSummary }
      : splitRelationshipText(rawSummary || rawTarget);
    const targetId = canonCharacterId(target);
    return targetId && summary ? [{ targetId, targetName: target, summary }] : [];
  });
}

function splitRelationshipText(text: string): { readonly target: string; readonly summary: string } {
  const match = /^([^：:\-—|]{1,20})\s*[：:\-—|]\s*(.+)$/.exec(text.trim());
  return match
    ? { target: readText(match[1], 60), summary: readText(match[2], 200) }
    : { target: '', summary: '' };
}

function toCanonFact(
  record: Record<string, unknown>,
  chunks: readonly CanonChunk[],
  primaryChunk: CanonChunk | undefined,
  index: number,
): CanonFact | null {
  const text = readText(pickValue(record, FACT_TEXT_KEYS), 400);
  if (!text || !primaryChunk) return null;
  const referenced = readText(pickValue(record, CHUNK_KEYS), 120);
  const chunk = chunks.find((candidate) => candidate.id === referenced) ?? primaryChunk;
  const kind = readEnum(pickValue(record, FACT_KIND_KEYS), FACT_KINDS, FACT_KIND_ALIASES, 'event');
  const confidence = readEnum(pickValue(record, CONFIDENCE_KEYS), CONFIDENCES, CONFIDENCE_ALIASES, 'medium');
  const characterIds = readFlexibleTextList(pickValue(record, FACT_CHARACTER_KEYS), 8, 60)
    .map((name) => canonCharacterId(name))
    .filter(Boolean);
  return {
    id: `${chunk.id}:f${index}`,
    kind,
    text,
    characterIds: uniqueTexts(characterIds, 8),
    chunkId: chunk.id,
    documentId: chunk.documentId,
    confidence,
  };
}

function readEnum<T extends string>(
  value: unknown,
  allowed: readonly T[],
  aliases: ReadonlyMap<string, T>,
  fallback: T,
): T {
  const text = readText(value, 40).toLowerCase();
  return allowed.find((candidate) => candidate === text)
    ?? aliases.get(readText(value, 40))
    ?? fallback;
}

/** 未启用解析 API，或解析失败时的确定性兜底：至少让角色卡本体成为人物锁。 */
export function fallbackCharacterLock(
  name: string,
  description: string,
  chunkIds: readonly string[],
  now: number,
): CharacterLock | null {
  const id = canonCharacterId(name);
  if (!id) return null;
  const lines = description.split(/\n+/).map((line) => line.trim()).filter(Boolean);
  return {
    id,
    name: name.trim(),
    aliases: [],
    core: uniqueTexts(lines, 8).map((line) => line.slice(0, 200)),
    values: [],
    knowledge: [],
    voice: { register: '', habits: [], forbidden: [] },
    relationships: [],
    signatureLines: [],
    sourceIds: uniqueTexts(chunkIds),
    manual: false,
    updatedAt: now,
  };
}
