import { buildCharacterIndex, detectMentionedCharacters, resolveCharacterLock } from './identity.js';
import { FANFIC_STATE_VERSION, type CanonChunk, type CanonFact, type CanonLibrary, type CharacterLock, type FanficNarrativeState } from './model.js';
import { hasFanficNarrativeContent } from './narrative.js';
import { rankCanonChunks, rankCanonFacts } from './retrieval.js';

export interface FanficContextBudget {
  readonly characterLimit: number;
  readonly factLimit: number;
  readonly excerptLimit: number;
  /** 原著部分的字符预算；剧情状态始终注入，不参与裁剪。 */
  readonly charLimit: number;
}

export interface FanficContextRequest {
  readonly query: string;
  /** 本轮明确在场或参与会话的角色名（正文说话人、手机会话成员）。 */
  readonly participantNames: readonly string[];
  readonly narrative: FanficNarrativeState;
  readonly library: CanonLibrary | null;
  readonly budget: FanficContextBudget;
}

export interface FanficContextDiagnostics {
  readonly participantNames: readonly string[];
  readonly matchedCharacterNames: readonly string[];
  readonly unresolvedNames: readonly string[];
  readonly ambiguousAliases: readonly string[];
  readonly factCount: number;
  readonly droppedFactCount: number;
  readonly excerptCount: number;
  readonly charCount: number;
}

export interface FanficTurnContext {
  readonly version: number;
  readonly title: string;
  readonly characters: readonly CharacterLock[];
  readonly facts: readonly CanonFact[];
  readonly excerpts: readonly CanonChunk[];
  readonly narrative: FanficNarrativeState;
  readonly diagnostics: FanficContextDiagnostics;
}

export const DEFAULT_FANFIC_BUDGET: FanficContextBudget = Object.freeze({
  characterLimit: 6,
  factLimit: 12,
  excerptLimit: 2,
  charLimit: 6_000,
});

/**
 * 编译本轮同人上下文：正文与手机共用同一份结果，保证两条链路看到同样的人物锁、
 * 原著事实与 AU 状态。原著部分按预算裁剪；剧情状态是强约束，不参与裁剪。
 */
export function compileFanficContext(request: FanficContextRequest): FanficTurnContext {
  const library = request.library;
  const index = buildCharacterIndex(library?.characters ?? []);
  const resolved = new Map<string, CharacterLock>();
  const unresolved: string[] = [];
  for (const name of request.participantNames) {
    const character = resolveCharacterLock(index, name);
    if (character) resolved.set(character.id, character);
    else if (name.trim()) unresolved.push(name.trim());
  }
  // 在场角色优先，其次是本轮文本里提到的角色，避免把整本原著人物表塞进提示词。
  for (const character of detectMentionedCharacters(index, request.query)) {
    if (resolved.size >= request.budget.characterLimit) break;
    resolved.set(character.id, character);
  }
  const characters = [...resolved.values()].slice(0, Math.max(0, request.budget.characterLimit));
  const characterIds = characters.map((character) => character.id);

  const ranked = rankCanonFacts(library?.facts ?? [], {
    query: request.query,
    characterIds,
    limit: request.budget.factLimit,
  }).map((scored) => scored.fact);
  const excerpts = rankCanonChunks(library?.chunks ?? [], request.query, request.budget.excerptLimit);
  const trimmed = trimByBudget(characters, ranked, excerpts, request.budget.charLimit);

  return {
    version: FANFIC_STATE_VERSION,
    title: library?.title ?? '',
    characters,
    facts: trimmed.facts,
    excerpts: trimmed.excerpts,
    narrative: request.narrative,
    diagnostics: {
      participantNames: request.participantNames.filter((name) => name.trim()),
      matchedCharacterNames: characters.map((character) => character.name),
      unresolvedNames: unresolved,
      ambiguousAliases: index.ambiguous,
      factCount: trimmed.facts.length,
      droppedFactCount: ranked.length - trimmed.facts.length,
      excerptCount: trimmed.excerpts.length,
      charCount: trimmed.charCount,
    },
  };
}

/** 预算不足时先丢原文摘录，再从相关度最低的事实开始丢；人物锁始终保留。 */
function trimByBudget(
  characters: readonly CharacterLock[],
  facts: readonly CanonFact[],
  excerpts: readonly CanonChunk[],
  charLimit: number,
): { readonly facts: readonly CanonFact[]; readonly excerpts: readonly CanonChunk[]; readonly charCount: number } {
  const limit = Math.max(500, Math.floor(charLimit));
  const characterCost = characters.reduce((total, character) => total + characterCostOf(character), 0);
  let used = characterCost;
  const keptFacts: CanonFact[] = [];
  for (const fact of facts) {
    const cost = fact.text.length + 24;
    if (used + cost > limit) break;
    used += cost;
    keptFacts.push(fact);
  }
  const keptExcerpts: CanonChunk[] = [];
  for (const chunk of excerpts) {
    const cost = chunk.text.length + chunk.heading.length + 24;
    if (used + cost > limit) break;
    used += cost;
    keptExcerpts.push(chunk);
  }
  return { facts: keptFacts, excerpts: keptExcerpts, charCount: used };
}

function characterCostOf(character: CharacterLock): number {
  const texts = [
    character.name,
    ...character.aliases,
    ...character.core,
    ...character.values,
    ...character.knowledge,
    character.voice.register,
    ...character.voice.habits,
    ...character.voice.forbidden,
    ...character.relationships.map((relationship) => `${relationship.targetName}${relationship.summary}`),
    ...character.signatureLines,
  ];
  return texts.reduce((total, text) => total + text.length + 2, 0);
}

/** 上下文是否值得注入：既没有原著约束也没有剧情事实时应当跳过。 */
export function hasFanficContextContent(context: FanficTurnContext): boolean {
  return context.characters.length > 0
    || context.facts.length > 0
    || context.excerpts.length > 0
    || hasFanficNarrativeContent(context.narrative);
}