import { hashText } from '../db/sheet-dsl.js';
const record = (value: unknown): Record<string, unknown> => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};

/** 转换卡携带来源标识；改名、自动追加序号或重新导入均不会改变绑定关系。 */
export function mvuCardIdentity(card: unknown): string {
  const root = record(card);
  const data = Object.keys(record(root.data)).length ? record(root.data) : root;
  const marker = record(record(data.extensions).moyun_data);
  if (typeof marker.sourceIdentity === 'string' && marker.sourceIdentity) return marker.sourceIdentity;
  return `mvu-card-${hashText(JSON.stringify(['name', 'creator', 'character_version', 'description', 'personality', 'scenario', 'first_mes'].map((key) => data[key] ?? root[key] ?? '')))}`;
}

export function mvuPresetMatchesCard(bundle: { readonly sourceIdentity?: string; readonly sourceCard?: string }, card: unknown): boolean {
  if (bundle.sourceIdentity) return bundle.sourceIdentity === mvuCardIdentity(card);
  const root = record(card), data = record(root.data);
  const name = String(data.name ?? root.name ?? '').trim();
  if (!bundle.sourceCard) return false;
  if (bundle.sourceCard === name) return true;
  const prefix = `${bundle.sourceCard}（墨韵数据）`;
  if (!name.startsWith(prefix) || !/^\d*$/.test(name.slice(prefix.length))) return false;
  const book = record(data.character_book ?? root.character_book);
  const entries = Array.isArray(book.entries) ? book.entries : [];
  return entries.some((entry) => record(entry).comment === '【墨韵数据·填表协议】')
    || String(record(data.extensions ?? root.extensions).world ?? '').includes('（墨韵数据）');
}
