import type { GenerationConditionContext } from '../conditions/generation.js';
import { createConditionSnapshot } from '../conditions/evaluator.js';
import { logModelFailure } from '../core/diagnostics.js';
import type { PhoneEvent } from '../domain/events.js';
import { createPhoneEvent } from '../domain/events.js';
import { createId, type IdFactory } from '../domain/ids.js';
import { memoryCoveredUntil, selectPhoneSummaryItems, type AppId, type PhoneState } from '../domain/model.js';
import { PhoneStore } from '../storage/phone-store.js';
import { analyzeGenerationCoverage, buildActionEvents } from './action-executor.js';
import type { TimeAdvanceSettings } from '../time/time-advance.js';
import { createGenerationPlan, planOutboxIds, splitGenerationPlan, type GenerationPlan } from './batch-planner.js';
import {
  SillyTavernGenerationPort,
  isConfiguredApiReady,
  type GenerationPort,
  type GenerationProviderPreference,
  type GenerationRunInfo,
} from './generation-port.js';
import type { OpenAiCompatibleApiConfig, StoryFloorSnapshot } from '../integration/sillytavern-bridge.js';
import type { CharacterLock, FanficSecret } from '../fanfic/model.js';
import type { ApiRetryProgress } from './api-client.js';
import { buildGenerationRetrievalQuery, type RetrievedStoryContext } from './retrieval-context.js';
import { compileGenerationPrompt, type CompiledGenerationPrompt } from './prompt-compiler.js';
import { validateGenerationResponse } from './action-validator.js';
import { GENERATION_MAX_ACTIONS } from './schema.js';
import type {
  ValidatedGenerationAction,
  ValidatedVariableUpdate,
  ValidationIssue,
  ValidationResult,
} from './schema.js';

export interface GenerationWorldBookContext {
  readonly entryCount: number;
  readonly names: readonly string[];
  readonly excerpt: string;
}

export interface GenerationModuleContext {
  readonly moduleId: string;
  readonly name: string;
  readonly data: Readonly<Record<string, unknown>>;
}

/** 应用开关：论坛/推特/匿名交友是否允许自主生成内容（由用户的应用停用列表决定）。 */
export interface GenerationAppAccess {
  readonly forum: boolean;
  readonly twitter: boolean;
  readonly anonymous: boolean;
}

/** 同人剧情上下文提供者：由运行时用同一份编译逻辑生成，正文与手机共享结果。 */
export interface FanficGenerationContext {
  /** 注入提示词的结构化载荷。 */
  readonly payload: Readonly<Record<string, unknown>>;
  /** 按名字解析人物锁，供动作校验判断语感与认知边界。 */
  readonly resolveCharacter: (name: string) => CharacterLock | null;
  readonly secrets: readonly FanficSecret[];
}

export type FanficContextProvider = (input: {
  readonly query: string;
  readonly participantNames: readonly string[];
}) => FanficGenerationContext | null;

export interface GenerationServiceOptions {
  readonly timeAdvanceProvider?: () => TimeAdvanceSettings;
  readonly selfProfileId: string;
  readonly idFactory?: IdFactory;
  readonly generationPort?: GenerationPort;
  readonly preferTavernHelper?: boolean;
  readonly providerPreference?: GenerationProviderPreference;
  readonly primaryApi?: OpenAiCompatibleApiConfig;
  readonly secondaryApi?: OpenAiCompatibleApiConfig;
  readonly allowTavernFallback?: boolean;
  readonly autonomousPostBudget?: number;
  readonly temperature?: number;
  readonly maxTokens?: number;
  readonly jailbreakPrompt?: string;
  readonly worldBookProvider?: () => GenerationWorldBookContext | null;
  readonly appAccessProvider?: () => GenerationAppAccess | null;
  /** 提供当前聊天作用域内启用模块的公开数据，供其他应用核对模块产生的事实。 */
  readonly moduleDataProvider?: () => readonly GenerationModuleContext[] | null;
  /** 是否启用世界自转：关闭时禁止本轮生成独立论坛/Twitter动态。 */
  readonly worldRotationEnabledProvider?: () => boolean;
  readonly imageGenerationEnabledProvider?: () => boolean;
  /** 生图供应商类型（novelai 时输出 NAI 多角色结构化提示词指导）。 */
  readonly imageProviderKindProvider?: () => string;
  /** 提供当前楼层的 stat_data 变量快照（已折叠 MVU 二元组），用于让模型判断需要更新的变量。 */
  readonly floorVariablesProvider?: () => Promise<Readonly<Record<string, unknown>> | null>;
  /** 提供正文最新楼层，作为手机互动的剧情背景。 */
  readonly recentStoryProvider?: () => readonly StoryFloorSnapshot[] | null;
  /** 生成前从记忆库检索相关记忆；查询和计划都来自同一份冻结批次快照。 */
  readonly retrievedMemoriesProvider?: (
    query: string,
    plan: GenerationPlan,
  ) => Promise<readonly RetrievedStoryContext[] | null>;
  readonly summaryInjectCount?: number;
  /** 提供本轮同人剧情上下文（人物锁、AU 状态、原著事实）。 */
  readonly fanficContextProvider?: FanficContextProvider;
  /** 每次请求最多处理的会话数（0 = 不分片，所有会话打包进一次请求）。 */
  readonly conversationShardSize?: number;
  /** 当前批次冻结的纯条件上下文；条件失败时只影响门控，不执行任何副作用。 */
  readonly conditionContextProvider?: () => GenerationConditionContext | null;
  readonly disabledAppIds?: readonly string[];
}

export interface GenerationProgress {
  readonly phase: 'idle' | 'planning' | 'generating' | 'committing' | 'completed' | 'failed';
  readonly batchId?: string;
  readonly message: string;
}

export interface BatchRunResult {
  readonly batchId: string;
  readonly completedOutboxIds: readonly string[];
  readonly queuedOutboxIds: readonly string[];
  readonly unansweredOutboxIds: readonly string[];
  readonly issues: readonly string[];
  /** 模型请求更新的变量（已通过结构校验，待运行时应用到楼层）。 */
  readonly variableUpdates: readonly { readonly path: string; readonly value: string | number | boolean | null }[];
  /** 本轮使用的冻结条件上下文：注入等后续阶段复用同一份只读快照，避免判定漂移。 */
  readonly conditionContext: GenerationConditionContext;
}

/** 一次分片生成所需的公共上下文（整轮只解析一次，各分片复用）。 */
interface ShardRunContext {
  readonly controller: AbortController;
  readonly shardCount: number;
  readonly worldBook: GenerationWorldBookContext | null;
  readonly appAccess: GenerationAppAccess | null;
  readonly moduleData: readonly GenerationModuleContext[] | null;
  readonly floorVariables: Readonly<Record<string, unknown>> | null;
  readonly retrievedMemories: readonly RetrievedStoryContext[] | null;
  readonly conditionContext: GenerationConditionContext | null;
  /** 同人剧情上下文：与正文生成同源的人物锁、AU 状态与原著事实。 */
  readonly fanficContext: FanficGenerationContext | null;
}

interface ShardOutcome {
  readonly usable: boolean;
  readonly actions: readonly ValidatedGenerationAction[];
  readonly variableUpdates: readonly ValidatedVariableUpdate[];
  readonly issues: readonly string[];
  readonly failure?: string;
}

/** 分片动作序号步长：保证不同分片、以及分片内补生的 actionId 不相撞。 */
const SHARD_ACTION_STRIDE = 100;
const REPAIR_ACTION_OFFSET = 50;
/** 模型没吐出可解析 JSON 时的总尝试次数（含首次）。 */
const JSON_ATTEMPT_LIMIT = 3;
const JSON_ATTEMPT_STRIDE = 10;

export class GenerationService {
  readonly #timeAdvanceProvider: (() => TimeAdvanceSettings) | undefined;
  readonly #store: PhoneStore;
  readonly #selfProfileId: string;
  readonly #idFactory: IdFactory;
  readonly #generationPort: GenerationPort;
  #autonomousPostBudget: number;
  #temperature: number;
  #maxTokens: number;
  #jailbreakPrompt: string;
  #primaryApi: OpenAiCompatibleApiConfig | null;
  #secondaryApi: OpenAiCompatibleApiConfig | null;
  #worldBookProvider: (() => GenerationWorldBookContext | null) | null;
  #appAccessProvider: (() => GenerationAppAccess | null) | null;
  #moduleDataProvider: (() => readonly GenerationModuleContext[] | null) | null;
  #worldRotationEnabledProvider: (() => boolean) | null;
  #imageGenerationEnabledProvider: (() => boolean) | null;
  #imageProviderKindProvider: (() => string) | null;
  #floorVariablesProvider: (() => Promise<Readonly<Record<string, unknown>> | null>) | null;
  #recentStoryProvider: (() => readonly StoryFloorSnapshot[] | null) | null;
  #retrievedMemoriesProvider: ((
    query: string,
    plan: GenerationPlan,
  ) => Promise<readonly RetrievedStoryContext[] | null>) | null;
  #summaryInjectCount: number;
  #fanficContextProvider: FanficContextProvider | null;
  #conversationShardSize: number;
  #conditionContextProvider: (() => GenerationConditionContext | null) | null;
  #disabledAppIds: readonly string[];
  readonly #progressListeners = new Set<(progress: GenerationProgress) => void>();
  #active: { readonly batchId: string; readonly controller: AbortController } | null = null;

  constructor(store: PhoneStore, options: GenerationServiceOptions) {
    this.#timeAdvanceProvider = options.timeAdvanceProvider;
    this.#store = store;
    this.#selfProfileId = options.selfProfileId;
    this.#idFactory = options.idFactory ?? createId;
    this.#generationPort = options.generationPort ?? new SillyTavernGenerationPort({
      preferTavernHelper: options.preferTavernHelper,
      providerPreference: options.providerPreference,
      primaryApi: options.primaryApi,
      secondaryApi: options.secondaryApi,
      allowTavernFallback: options.allowTavernFallback,
    });
    this.#autonomousPostBudget = options.autonomousPostBudget ?? 3;
    this.#temperature = normalizeTemperature(options.temperature);
    this.#maxTokens = normalizeMaxTokens(options.maxTokens);
    this.#jailbreakPrompt = normalizeJailbreakPrompt(options.jailbreakPrompt);
    this.#primaryApi = options.primaryApi ?? null;
    this.#secondaryApi = options.secondaryApi ?? null;
    this.#worldBookProvider = options.worldBookProvider ?? null;
    this.#appAccessProvider = options.appAccessProvider ?? null;
    this.#moduleDataProvider = options.moduleDataProvider ?? null;
    this.#worldRotationEnabledProvider = options.worldRotationEnabledProvider ?? null;
    this.#imageGenerationEnabledProvider = options.imageGenerationEnabledProvider ?? null;
    this.#imageProviderKindProvider = options.imageProviderKindProvider ?? null;
    this.#floorVariablesProvider = options.floorVariablesProvider ?? null;
    this.#recentStoryProvider = options.recentStoryProvider ?? null;
    this.#retrievedMemoriesProvider = options.retrievedMemoriesProvider ?? null;
    this.#summaryInjectCount = normalizeSummaryInjectCount(options.summaryInjectCount);
    this.#fanficContextProvider = options.fanficContextProvider ?? null;
    this.#conversationShardSize = normalizeShardSize(options.conversationShardSize);
    this.#conditionContextProvider = options.conditionContextProvider ?? null;
    this.#disabledAppIds = [...new Set(options.disabledAppIds ?? [])];
  }

  get isRunning(): boolean {
    return this.#active !== null;
  }

  get lastRun(): GenerationRunInfo | null {
    return this.#generationPort.getLastRun?.() ?? null;
  }

  updateConfiguration(options: {
    readonly providerPreference?: GenerationProviderPreference;
    readonly primaryApi?: OpenAiCompatibleApiConfig;
    readonly secondaryApi?: OpenAiCompatibleApiConfig;
    readonly allowTavernFallback?: boolean;
    readonly autonomousPostBudget?: number;
    readonly temperature?: number;
    readonly maxTokens?: number;
    readonly jailbreakPrompt?: string;
    readonly worldBookProvider?: (() => GenerationWorldBookContext | null) | null;
    readonly appAccessProvider?: (() => GenerationAppAccess | null) | null;
    readonly moduleDataProvider?: (() => readonly GenerationModuleContext[] | null) | null;
    readonly worldRotationEnabledProvider?: (() => boolean) | null;
    readonly imageGenerationEnabledProvider?: (() => boolean) | null;
    readonly imageProviderKindProvider?: (() => string) | null;
    readonly floorVariablesProvider?: (() => Promise<Readonly<Record<string, unknown>> | null>) | null;
    readonly recentStoryProvider?: (() => readonly StoryFloorSnapshot[] | null) | null;
    readonly retrievedMemoriesProvider?: ((
      query: string,
      plan: GenerationPlan,
    ) => Promise<readonly RetrievedStoryContext[] | null>) | null;
    readonly conditionContextProvider?: (() => GenerationConditionContext | null) | null;
    readonly fanficContextProvider?: FanficContextProvider | null;
    readonly summaryInjectCount?: number;
    readonly conversationShardSize?: number;
    readonly disabledAppIds?: readonly string[];
  }): void {
    if (options.providerPreference !== undefined) {
      this.#generationPort.setProviderPreference?.(options.providerPreference);
    }
    if (
      options.primaryApi !== undefined
      || options.secondaryApi !== undefined
      || options.allowTavernFallback !== undefined
    ) {
      this.#generationPort.setApiConfigs?.({
        ...(options.primaryApi !== undefined ? { primaryApi: options.primaryApi } : {}),
        ...(options.secondaryApi !== undefined ? { secondaryApi: options.secondaryApi } : {}),
        ...(options.allowTavernFallback !== undefined ? { allowTavernFallback: options.allowTavernFallback } : {}),
      });
    }
    if (options.autonomousPostBudget !== undefined) {
      this.#autonomousPostBudget = Math.min(8, Math.max(0, Math.round(options.autonomousPostBudget)));
    }
    if (options.temperature !== undefined) this.#temperature = normalizeTemperature(options.temperature);
    if (options.maxTokens !== undefined) this.#maxTokens = normalizeMaxTokens(options.maxTokens);
    if (options.jailbreakPrompt !== undefined) this.#jailbreakPrompt = normalizeJailbreakPrompt(options.jailbreakPrompt);
    if (options.primaryApi !== undefined) this.#primaryApi = options.primaryApi;
    if (options.secondaryApi !== undefined) this.#secondaryApi = options.secondaryApi;
    if (options.worldBookProvider !== undefined) this.#worldBookProvider = options.worldBookProvider;
    if (options.appAccessProvider !== undefined) this.#appAccessProvider = options.appAccessProvider;
    if (options.moduleDataProvider !== undefined) this.#moduleDataProvider = options.moduleDataProvider;
    if (options.worldRotationEnabledProvider !== undefined) {
      this.#worldRotationEnabledProvider = options.worldRotationEnabledProvider;
    }
    if (options.imageGenerationEnabledProvider !== undefined) {
      this.#imageGenerationEnabledProvider = options.imageGenerationEnabledProvider;
    }
    if (options.imageProviderKindProvider !== undefined) {
      this.#imageProviderKindProvider = options.imageProviderKindProvider;
    }
    if (options.floorVariablesProvider !== undefined) this.#floorVariablesProvider = options.floorVariablesProvider;
    if (options.recentStoryProvider !== undefined) this.#recentStoryProvider = options.recentStoryProvider;
    if (options.retrievedMemoriesProvider !== undefined) this.#retrievedMemoriesProvider = options.retrievedMemoriesProvider;
    if (options.conditionContextProvider !== undefined) this.#conditionContextProvider = options.conditionContextProvider;
    if (options.fanficContextProvider !== undefined) this.#fanficContextProvider = options.fanficContextProvider;
    if (options.summaryInjectCount !== undefined) {
      this.#summaryInjectCount = normalizeSummaryInjectCount(options.summaryInjectCount);
    }
    if (options.conversationShardSize !== undefined) {
      this.#conversationShardSize = normalizeShardSize(options.conversationShardSize);
    }
    if (options.disabledAppIds !== undefined) this.#disabledAppIds = [...new Set(options.disabledAppIds)];
  }

  subscribe(listener: (progress: GenerationProgress) => void): () => void {
    this.#progressListeners.add(listener);
    listener({ phase: 'idle', message: '待生成' });
    return () => this.#progressListeners.delete(listener);
  }

  async run(): Promise<BatchRunResult | null> {
    if (this.#active) return null;
    this.#emit({ phase: 'planning', message: '整理待发送消息' });
    const state = this.#store.state;
    const plan = createGenerationPlan(state, this.#idFactory, state.worldClock.now, this.#disabledAppIds);
    if (!plan) {
      this.#emit({ phase: 'idle', message: '没有待生成消息' });
      return null;
    }

    const controller = new AbortController();
    this.#active = { batchId: plan.batch.id, controller };
    this.#emit({ phase: 'planning', batchId: plan.batch.id, message: '冻结本轮消息快照' });
    await this.#store.dispatch([
      createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'batch.started',
          occurredAt: state.worldClock.now,
          payload: { batch: plan.batch },
        },
        this.#idFactory,
      ),
    ]);

    try {
      this.#emit({ phase: 'generating', batchId: plan.batch.id, message: '正在生成联系人回复与动态' });
      const shards = this.#splitPlan(plan);
      const context: ShardRunContext = {
        controller,
        shardCount: shards.length,
        worldBook: this.#worldBookProvider?.() ?? null,
        appAccess: this.#appAccessProvider?.() ?? null,
        moduleData: this.#moduleDataProvider?.() ?? null,
        floorVariables: await this.#resolveFloorVariables(),
        retrievedMemories: await this.#resolveRetrievedMemories(plan),
        fanficContext: this.#resolveFanficContext(plan),
        conditionContext: this.#resolveConditionContext(),
      };

      const collected: ValidatedGenerationAction[] = [];
      let variableUpdates: readonly ValidatedVariableUpdate[] = [];
      const issues: string[] = [];
      const failures: string[] = [];
      const retryOutboxIds = new Set<string>();
      for (const [shardIndex, shard] of shards.entries()) {
        if (controller.signal.aborted) throw new DOMException('生成已取消', 'AbortError');
        if (shards.length > 1) {
          this.#emit({
            phase: 'generating',
            batchId: plan.batch.id,
            message: `正在生成第 ${shardIndex + 1}/${shards.length} 组会话`,
          });
        }
        const outcome = await this.#runShard(shard, shardIndex, context);
        collected.push(...outcome.actions);
        variableUpdates = mergeVariableUpdates(variableUpdates, outcome.variableUpdates);
        issues.push(...outcome.issues);
        if (!outcome.usable) {
          if (outcome.failure) failures.push(outcome.failure);
          // 这一片没拿到任何可用结果：相关消息保持待生成，用户可以再次点击生成。
          for (const outboxId of planOutboxIds(shard)) retryOutboxIds.add(outboxId);
        }
      }
      if (failures.length === shards.length) {
        throw new Error(failures.join('；') || '模型回复无法解析');
      }
      if (retryOutboxIds.size > 0) {
        issues.push(`${retryOutboxIds.size} 条待处理内容未获得可解析回复，已恢复为待生成，可再次点击生成`);
      }

      const actions = deduplicateActions(collected);
      const finalCoverage = analyzeGenerationCoverage(plan, actions);
      const unresolved = finalCoverage.unansweredOutboxIds.filter((id) => !retryOutboxIds.has(id));
      if (unresolved.length > 0) {
        issues.push(`未生成有效回复，已结束本次处理：${unresolved.join('、')}`);
      }
      this.#emit({ phase: 'committing', batchId: plan.batch.id, message: '写入手机事件' });
      const execution = buildActionEvents(
        this.#store.state,
        plan,
        actions,
        this.#idFactory,
        {
          timeAdvance: this.#timeAdvanceProvider?.(),
          ...(issues.length > 0 ? { validationError: issues.slice(0, 5).join('; ') } : {}),
          ...(retryOutboxIds.size > 0 ? { retryOutboxIds } : {}),
        },
      );
      await this.#store.dispatch(execution.events);
      const result: BatchRunResult = {
        batchId: plan.batch.id,
        completedOutboxIds: execution.completedOutboxIds,
        queuedOutboxIds: execution.queuedOutboxIds,
        unansweredOutboxIds: execution.unansweredOutboxIds,
        issues,
        variableUpdates,
        conditionContext: context.conditionContext
          ?? { snapshot: createConditionSnapshot(plan.scopeId, plan.batch.id, {}) },
      };
      this.#emit({ phase: 'completed', batchId: plan.batch.id, message: this.#resultMessage(result) });
      return result;
    } catch (error) {
      const message = error instanceof DOMException && error.name === 'AbortError'
        ? '生成已取消'
        : error instanceof Error
          ? error.message
          : String(error);
      try {
        await this.#store.dispatch([
          createPhoneEvent(
            {
              scopeId: this.#store.scopeId,
              type: 'batch.failed',
              occurredAt: this.#store.state.worldClock.now,
              payload: { batchId: plan.batch.id, failedAt: Date.now(), error: message },
            },
            this.#idFactory,
          ),
        ]);
      } catch (failureError) {
        console.error('[墨韵手机] 回收失败批次时出错', failureError);
      }
      this.#emit({ phase: 'failed', batchId: plan.batch.id, message });
      throw error;
    } finally {
      this.#active = null;
    }
  }

  cancel(): void {
    if (!this.#active) return;
    this.#generationPort.stop(this.#active.batchId);
    this.#active.controller.abort();
  }

  #emit(progress: GenerationProgress): void {
    for (const listener of this.#progressListeners) listener(progress);
  }

  #emitRetryProgress(batchId: string, progress: ApiRetryProgress, label: string): void {
    this.#emit({
      phase: 'generating',
      batchId,
      message: `${label}失败，${progress.delayMs / 1000} 秒后重试 ${progress.attempt}/${progress.retryCount}`,
    });
  }

  /** 会话数超过分片上限时拆成多次请求；0 表示不分片。 */
  #splitPlan(plan: GenerationPlan): readonly GenerationPlan[] {
    return this.#conversationShardSize > 0
      ? splitGenerationPlan(plan, this.#conversationShardSize)
      : [plan];
  }

  /**
   * 生成单个分片：编译提示词 → 请求 → 校验 → 必要时补生一次。
   * 分片之间通过 allowedConversationIds 完全隔离，跨分片的回复会被校验层拒绝。
   * 模型没吐出可解析 JSON 时会带着更强硬的格式要求重问，仍失败才把该分片判为失败。
   */
  async #runShard(
    shard: GenerationPlan,
    shardIndex: number,
    context: ShardRunContext,
  ): Promise<ShardOutcome> {
    const label = context.shardCount > 1 ? `第 ${shardIndex + 1} 组` : '';
    const prompt = this.#compilePromptWithinBudget(shard, context);
    const offset = shardIndex * SHARD_ACTION_STRIDE;
    const issues: string[] = [];
    let validation: ValidationResult | null = null;
    for (let attempt = 1; attempt <= JSON_ATTEMPT_LIMIT; attempt += 1) {
      if (attempt > 1) {
        this.#emit({
          phase: 'generating',
          batchId: shard.batch.id,
          message: `${label}回复不是 JSON，正在重试 ${attempt - 1}/${JSON_ATTEMPT_LIMIT - 1}`,
        });
      }
      const attemptPrompt = attempt > 1 ? buildJsonRetryPrompt(prompt) : prompt;
      const raw = await this.#generationPort.generate({
        generationId: shard.batch.id,
        system: attemptPrompt.system,
        user: attemptPrompt.user,
        temperature: this.#temperature,
        maxTokens: this.#maxTokens,
        signal: context.controller.signal,
        onRetry: (progress) => this.#emitRetryProgress(shard.batch.id, progress, `${label}生成`),
      });
      validation = validateGenerationResponse(
        raw,
        this.#validationContext(shard, context, offset + (attempt - 1) * JSON_ATTEMPT_STRIDE),
      );
      if (validation.issues.length > 0) {
        // 「不是完整 JSON / 已恢复 N 个动作」必须能追到模型原文，否则无法判断是截断还是格式错。
        logModelFailure({
          stage: `统一回复${label ? `（${label}）` : ''}`,
          reason: validation.issues[0]?.reason ?? '模型输出存在问题',
          raw,
          issues: validation.issues.map((issue) => `#${issue.index} ${issue.reason}`),
          request: {
            batchId: shard.batch.id,
            attempt,
            conversations: shard.conversations.length,
            queuedPosts: shard.queuedPosts.length,
            maxTokens: this.#maxTokens,
            promptLength: attemptPrompt.system.length + attemptPrompt.user.length,
          },
        });
      }
      if (!isUnusableGenerationResponse(validation)) break;
      issues.push(...formatIssues(validation.issues, attempt > 1 ? `${label}重试${attempt - 1}` : label));
    }
    if (!validation || isUnusableGenerationResponse(validation)) {
      return {
        usable: false,
        actions: [],
        variableUpdates: [],
        issues,
        failure: validation?.issues.map((issue) => issue.reason).join('；') || '模型回复无法解析',
      };
    }

    let actions = [...validation.actions];
    let variableUpdates: readonly ValidatedVariableUpdate[] = validation.variableUpdates;
    issues.push(...formatIssues(validation.issues, label));
    const coverage = analyzeGenerationCoverage(shard, actions);
    if (coverage.unansweredOutboxIds.length > 0) {
      this.#emit({
        phase: 'generating',
        batchId: shard.batch.id,
        message: `${label}正在补全遗漏的回复`,
      });
      const repairPrompt = buildRepairPrompt(prompt, coverage);
      const repairRaw = await this.#generationPort.generate({
        generationId: shard.batch.id,
        system: repairPrompt.system,
        user: repairPrompt.user,
        temperature: this.#temperature,
        maxTokens: this.#maxTokens,
        signal: context.controller.signal,
        onRetry: (progress) => this.#emitRetryProgress(shard.batch.id, progress, `${label}补全回复`),
      });
      const repairValidation = validateGenerationResponse(
        repairRaw,
        this.#validationContext(shard, context, offset + REPAIR_ACTION_OFFSET),
      );
      issues.push(...formatIssues(repairValidation.issues, `${label}补生`));
      if (!isUnusableGenerationResponse(repairValidation)) {
        actions = deduplicateActions([...actions, ...selectRepairActions(repairValidation.actions, coverage)]);
        variableUpdates = mergeVariableUpdates(variableUpdates, repairValidation.variableUpdates);
      }
    }
    return { usable: true, actions, variableUpdates, issues };
  }

  #validationContext(shard: GenerationPlan, context: ShardRunContext, actionIndexOffset: number) {
    const autonomousBlocked = this.#worldRotationEnabledProvider?.() === false
      || shard.allowAutonomous === false;
    return {
      batchId: shard.batch.id,
      state: this.#store.state,
      selfProfileId: this.#selfProfileId,
      allowedConversationIds: new Set(shard.conversations.map(({ conversation }) => conversation.id)),
      maxActions: shardActionBudget(shard),
      actionIndexOffset,
      ...(autonomousBlocked
        ? { allowedAutonomousApps: new Set<AppId>() }
        : context.appAccess
          ? { allowedAutonomousApps: buildAllowedAutonomousApps(context.appAccess) }
          : {}),
      ...(this.#disabledAppIds.length > 0 ? { disabledAppIds: new Set(this.#disabledAppIds) } : {}),
      ...(context.conditionContext ? { conditionContext: context.conditionContext } : {}),
      ...(context.fanficContext
        ? {
            fanficGuard: {
              resolveCharacter: context.fanficContext.resolveCharacter,
              secrets: context.fanficContext.secrets,
            },
          }
        : {}),
    };
  }

  #resolveConditionContext(): GenerationConditionContext | null {
    if (!this.#conditionContextProvider) return null;
    try {
      const context = this.#conditionContextProvider();
      return context ? { ...context, snapshot: { ...context.snapshot } } : null;
    } catch {
      return null;
    }
  }

  /**
   * 在 API 配置的上下文上限内编译提示词。
   * 超出预算时收缩历史条数和正文楼层，但始终保留完整世界书摘录。
   */
  async #resolveFloorVariables(): Promise<Readonly<Record<string, unknown>> | null> {
    try {
      return await this.#floorVariablesProvider?.() ?? null;
    } catch {
      return null;
    }
  }

  /** 使用冻结的生成计划构造查询；检索失败不阻塞生成。 */
  async #resolveRetrievedMemories(plan: GenerationPlan): Promise<readonly RetrievedStoryContext[] | null> {
    try {
      if (!this.#retrievedMemoriesProvider) return null;
      const query = buildGenerationRetrievalQuery(plan, this.#safeRecentStory() ?? []);
      return query ? await this.#retrievedMemoriesProvider(query, plan) : null;
    } catch {
      return null;
    }
  }

  /** 同人上下文与正文共用一份编译逻辑；参与者取自本轮会话成员，失败不阻塞生成。 */
  #resolveFanficContext(plan: GenerationPlan): FanficGenerationContext | null {
    try {
      if (!this.#fanficContextProvider) return null;
      const participantNames = [...new Set(plan.conversations.flatMap(({ participants }) => participants
        .filter((profile) => profile.id !== this.#selfProfileId)
        .map((profile) => profile.boundCharacter?.trim() || profile.displayName)))];
      const query = buildGenerationRetrievalQuery(plan, this.#safeRecentStory() ?? []);
      return this.#fanficContextProvider({ query, participantNames });
    } catch {
      return null;
    }
  }

  #compilePromptWithinBudget(
    plan: GenerationPlan,
    context: Pick<
      ShardRunContext,
      'worldBook' | 'appAccess' | 'moduleData' | 'floorVariables' | 'retrievedMemories' | 'conditionContext' | 'fanficContext'
    >,
  ): CompiledGenerationPrompt {
    const { worldBook, appAccess, moduleData, floorVariables, retrievedMemories, conditionContext, fanficContext } = context;
    const autonomousPostBudget = this.#worldRotationEnabledProvider?.() === false
      ? 0
      : this.#autonomousPostBudget;
    const imageGeneration = this.#imageGenerationEnabledProvider?.() === true;
    const imageProvider = imageGeneration ? this.#imageProviderKindProvider?.() ?? '' : '';
    const recentStory = this.#safeRecentStory();
    const summaries = selectPhoneSummaryItems(this.#store.state);
    const phoneSummaries = this.#disabledAppIds.some((id) => ['wechat', 'forum', 'anonymous', 'twitter'].includes(id))
      ? []
      : summaries.slice(-this.#summaryInjectCount).map((summary) => summary.content);
    const summarizedUntil = summaries.length > 0 ? memoryCoveredUntil(summaries[summaries.length - 1]!) : 0;
    const compileWith = (
      historyLimit: number,
      book: GenerationWorldBookContext | null,
      story: readonly StoryFloorSnapshot[] | null = recentStory,
    ): CompiledGenerationPrompt => {
      const compiled = compileGenerationPrompt(plan, this.#store.state, {
        selfProfileId: this.#selfProfileId,
        autonomousPostBudget,
        historyLimit,
        imageGeneration,
        imageProvider,
        summarizedUntil,
        ...(phoneSummaries.length > 0 ? { phoneSummaries } : {}),
        ...(story && story.length > 0 ? { recentStory: story } : {}),
        ...(floorVariables ? { variables: floorVariables } : {}),
        ...(retrievedMemories && retrievedMemories.length > 0 ? { retrievedMemories } : {}),
        ...(fanficContext ? { fanficContext: fanficContext.payload } : {}),
        ...(appAccess ? { appAccess } : {}),
        ...(this.#disabledAppIds.length > 0 ? { disabledAppIds: this.#disabledAppIds } : {}),
        ...(moduleData && moduleData.length > 0 ? { moduleData } : {}),
        ...(book ? { worldBook: book } : {}),
        ...(conditionContext ? { conditionContext } : {}),
      });
      return { ...compiled, system: prependPrompt(this.#jailbreakPrompt, compiled.system) };
    };

    let prompt = compileWith(16, worldBook);
    const contextBudget = this.#contextTokenBudget();
    if (!contextBudget) return prompt;

    const outputReserve = this.#activeApiConfig()?.maxTokens ?? this.#maxTokens;
    const inputBudget = Math.max(1_024, contextBudget - outputReserve);
    if (estimatePromptTokens(prompt) <= inputBudget) return prompt;

    for (const historyLimit of [8, 4]) {
      prompt = compileWith(historyLimit, worldBook);
      if (estimatePromptTokens(prompt) <= inputBudget) return prompt;
    }

    const shortStory = recentStory && recentStory.length > 5 ? recentStory.slice(-5) : recentStory;
    prompt = compileWith(4, worldBook, shortStory);
    return prompt;
  }

  #safeRecentStory(): readonly StoryFloorSnapshot[] | null {
    try {
      return this.#recentStoryProvider?.() ?? null;
    } catch {
      return null;
    }
  }

  /**
   * 单次自由生成（总结 / PXX 商品等辅助任务），不走批次流程。
   * 返回模型原始文本。
   */
  async generateFreeform(
    tag: string,
    system: string,
    user: string,
    maxTokens?: number,
    signal?: AbortSignal,
    temperature?: number,
    onRetry?: (progress: ApiRetryProgress) => void | Promise<void>,
  ): Promise<string> {
    const raw = await this.#generationPort.generate({
      generationId: `${tag}:${Date.now().toString(36)}`,
      // 不在此处截断：世界书等设定必须完整送达，长度控制由各调用方对自己的可变内容负责。
      system: prependPrompt(this.#jailbreakPrompt, system),
      user,
      temperature: temperature ?? this.#temperature,
      maxTokens: maxTokens ?? this.#maxTokens,
      signal,
      ...(onRetry ? { onRetry } : {}),
    });
    const text = raw.trim();
    if (!text) throw new Error('模型返回为空');
    return text;
  }

  #activeApiConfig(): OpenAiCompatibleApiConfig | null {
    return [this.#primaryApi, this.#secondaryApi]
      .find((config): config is OpenAiCompatibleApiConfig => Boolean(config && isConfiguredApiReady(config)))
      ?? null;
  }

  #contextTokenBudget(): number | null {
    return this.#activeApiConfig()?.maxContextTokens ?? null;
  }

  #resultMessage(result: BatchRunResult): string {
    const completed = result.completedOutboxIds.length;
    const queued = result.queuedOutboxIds.length;
    if (queued > 0) return `已处理 ${completed} 条，${queued} 条生成失败已恢复为待生成`;
    const unanswered = result.unansweredOutboxIds.length;
    if (unanswered > 0) return `本轮已处理 ${completed} 条，${unanswered} 条未获得有效回复`;
    return `本轮已完成 ${completed} 条会话`;
  }
}

function isUnusableGenerationResponse(validation: ValidationResult): boolean {
  return validation.actions.length === 0 && validation.issues.some((issue) =>
    issue.reason.includes('没有返回 JSON')
    || issue.reason.includes('actions 必须是数组'));
}

function buildRepairPrompt(
  prompt: CompiledGenerationPrompt,
  coverage: ReturnType<typeof analyzeGenerationCoverage>,
): CompiledGenerationPrompt {
  const payload = JSON.parse(prompt.user) as Record<string, unknown>;
  const protocol = payload.protocol && typeof payload.protocol === 'object' && !Array.isArray(payload.protocol)
    ? payload.protocol as Record<string, unknown>
    : {};
  const rules = Array.isArray(protocol.rules) ? protocol.rules : [];
  return {
    system: prompt.system,
    user: JSON.stringify({
      ...payload,
      task: '上一份结果遗漏了必需目标。只补全 repairTargets 中的回复，不要重复已经完成的目标，也不要创建额外自主动态。',
      protocol: {
        ...protocol,
        rules: [
          ...rules,
          '这是唯一一次补生：每个 repairTargets.conversationIds 必须输出 message.reply。',
          '每个 repairTargets.postIds 必须输出一个直接引用该 id 的回复、评论、点赞或转发动作。',
          '上一份结果里有回复因为身份错乱被丢弃：每条回复只能由该会话 speakers 里的角色本人发出，'
            + 'thought 以「我是<自己的名字>」开头，content 不得自称或署名别人。',
          '也不要让角色无故终止关系（拉黑、别再联系我、我们不合适、分手、绝交）或说出跳出角色的合规腔'
            + '（自称 AI、谈内容政策、「我不能继续」），这类回复同样会被丢弃。',
        ],
      },
      repairTargets: {
        conversationIds: coverage.missingConversationIds,
        postIds: coverage.missingPostIds,
      },
    }, null, 2),
  };
}

/** 格式重问：保留全部上下文，只把「必须是纯 JSON」的要求顶到最前面。 */
function buildJsonRetryPrompt(prompt: CompiledGenerationPrompt): CompiledGenerationPrompt {
  const payload = JSON.parse(prompt.user) as Record<string, unknown>;
  const protocol = payload.protocol && typeof payload.protocol === 'object' && !Array.isArray(payload.protocol)
    ? payload.protocol as Record<string, unknown>
    : {};
  const rules = Array.isArray(protocol.rules) ? protocol.rules : [];
  return {
    system: prompt.system,
    user: JSON.stringify({
      ...payload,
      task: `${String(payload.task ?? '')}（上一次的回复无法解析，这次必须只输出 JSON）`,
      protocol: {
        ...protocol,
        rules: [
          '上一次回复不是可解析的 JSON。这次的整个回复必须以 { 开头、以 } 结尾：'
            + '不要 markdown 代码块、不要解释、不要思考过程、不要在 JSON 前后写任何文字。',
          '如果内容较多，就减少动作数量，也要保证 JSON 完整闭合，不要写到一半被截断。',
          ...rules,
        ],
      },
    }, null, 2),
  };
}

/** 校验问题格式化：多分片时带上分片标签，便于定位是哪一组会话出的问题。 */
function formatIssues(issues: readonly ValidationIssue[], prefix: string): string[] {
  return issues.map((issue) => `${prefix ? `${prefix} ` : ''}${issue.index}: ${issue.reason}`);
}

/** 分片动作上限：按本片会话数给预算，避免会话多时后面的会话被整体截断。 */
function shardActionBudget(shard: GenerationPlan): number {
  // 角色多、待处理内容多时动作自然更多；预算跟着会话与动态数量走，不再卡在固定小值上。
  return Math.min(GENERATION_MAX_ACTIONS, 24 + shard.conversations.length * 8 + shard.queuedPosts.length * 4);
}

function selectRepairActions(
  actions: readonly ValidatedGenerationAction[],
  coverage: ReturnType<typeof analyzeGenerationCoverage>,
): readonly ValidatedGenerationAction[] {
  const conversations = new Set(coverage.missingConversationIds);
  const posts = new Set(coverage.missingPostIds);
  return actions.filter((action) => {
    if ((action.type === 'message.reply' || action.type === 'message.claim') && action.conversationId) {
      return conversations.has(action.conversationId);
    }
    const referencedPostId = action.parentId ?? action.targetId;
    return Boolean(referencedPostId && posts.has(referencedPostId));
  });
}

function deduplicateActions(actions: readonly ValidatedGenerationAction[]): ValidatedGenerationAction[] {
  const unique = new Map<string, ValidatedGenerationAction>();
  for (const action of actions) unique.set(action.actionId, action);
  return [...unique.values()];
}

function mergeVariableUpdates(
  initial: readonly ValidatedVariableUpdate[],
  repair: readonly ValidatedVariableUpdate[],
): ValidatedVariableUpdate[] {
  const merged = new Map<string, ValidatedVariableUpdate>();
  for (const update of [...initial, ...repair]) merged.set(update.path, update);
  return [...merged.values()];
}

function buildAllowedAutonomousApps(access: GenerationAppAccess): ReadonlySet<'wechat' | 'forum' | 'anonymous' | 'twitter'> {
  const allowed = new Set<'wechat' | 'forum' | 'anonymous' | 'twitter'>(['wechat']);
  if (access.forum) allowed.add('forum');
  if (access.twitter) allowed.add('twitter');
  if (access.anonymous) allowed.add('anonymous');
  return allowed;
}

/** 粗略估算 token 数：ASCII 约 3.5 字符/token，其余字符（如中日韩）按 1 字符/token 保守计。 */
export function estimateTokenCount(text: string): number {
  let ascii = 0;
  let other = 0;
  for (let index = 0; index < text.length; index += 1) {
    if (text.charCodeAt(index) <= 0x7f) ascii += 1;
    else other += 1;
  }
  return Math.ceil(ascii / 3.5) + other;
}

function estimatePromptTokens(prompt: CompiledGenerationPrompt): number {
  return estimateTokenCount(prompt.system) + estimateTokenCount(prompt.user);
}

function normalizeSummaryInjectCount(value: number | undefined): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.min(10, Math.max(1, Math.round(numeric))) : 3;
}

/** 分片大小：0 表示不分片；其余夹到 1~12。 */
function normalizeShardSize(value: number | undefined): number {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return 4;
  const rounded = Math.round(numeric);
  return rounded <= 0 ? 0 : Math.min(12, rounded);
}

function normalizeTemperature(value: number | undefined): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.round(Math.min(2, Math.max(0, numeric)) * 100) / 100 : 0.8;
}

function normalizeJailbreakPrompt(value: string | undefined): string {
  return String(value ?? '').trim();
}

function prependPrompt(prefix: string, prompt: string): string {
  return prefix ? `${prefix}\n\n${prompt}` : prompt;
}

function normalizeMaxTokens(value: number | undefined): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.min(8192, Math.max(128, Math.round(numeric))) : 1200;
}
