export interface ScopeIdentityContext {
  readonly chatId?: string;
  readonly characterId?: string | number;
  readonly chatMetadata?: Readonly<Record<string, unknown>>;
  readonly chat?: object;
}

const anonymousChatScopes = new WeakMap<object, string>();
let anonymousChatScopeSequence = 0;

export const ANONYMOUS_CHAT_SCOPE_PREFIX = 'chat:anonymous-';
export const DEFAULT_SESSION_SCOPE_ID = 'session:default';

/**
 * 瞬态作用域：酒馆尚未给出 chatId 时的占位（匿名聊天序号、默认会话）。
 * 每次页面加载序号都从 1 重新计数，这些 id 不能标识任何一个真实聊天，
 * 因此按聊天隔离的持久化数据（数据中心表格、自动记录）不应落到这里。
 */
export function isTransientScopeId(scopeId: string): boolean {
  return scopeId.startsWith(ANONYMOUS_CHAT_SCOPE_PREFIX) || scopeId === DEFAULT_SESSION_SCOPE_ID;
}

export function resolveScopeId(context: ScopeIdentityContext): string | null {
  const chatId = String(context.chatId ?? '').trim();
  if (chatId) return `chat:${chatId}`;

  const metadata = context.chatMetadata;
  const metadataId = metadata && typeof metadata === 'object'
    ? String(metadata.id ?? metadata.chatId ?? metadata.chat_id ?? '').trim()
    : '';
  if (metadataId) return `chat:${metadataId}`;

  if (context.chat && typeof context.chat === 'object') {
    let anonymousScope = anonymousChatScopes.get(context.chat);
    if (!anonymousScope) {
      anonymousScope = `${ANONYMOUS_CHAT_SCOPE_PREFIX}${++anonymousChatScopeSequence}`;
      anonymousChatScopes.set(context.chat, anonymousScope);
    }
    return anonymousScope;
  }

  const characterId = String(context.characterId ?? '').trim();
  return characterId ? `character:${characterId}` : null;
}