import {
  createSheetDdl,
  hashText,
  type SheetPolicy,
  type SheetRegistrationInput,
} from './sheet-dsl.js';
import { normalizePresetScopeState, presetScopeFingerprint, type PresetScopeState } from './preset-state.js';

/**
 * 表格归档：数据中心表结构与行数据的可携带副本。
 *
 * 存在的理由：SQLite 库只落在浏览器本地（OPFS 或 IndexedDB 快照），换浏览器、换设备、
 * 清理站点数据都会丢。归档把「表定义 + 行文本」提成纯 JSON，由调用方写进 SillyTavern
 * 聊天元数据，从而跟随服务端聊天文件走，与 `narrative_phone_state` 的持久化语义一致。
 *
 * 只归档事实数据：`mem_doc` 召回投影、`mem_fts` 索引与 `op_log` 审计都能从行数据重建，不入档。
 */
export const SHEET_ARCHIVE_VERSION = 1;

/** 单元格分隔符用不可见控制字符，避免与正文内容碰撞导致指纹误判。 */
const CELL_SEPARATOR = '\u001f';
const ROW_SEPARATOR = '\u001e';
const SHEET_SEPARATOR = '\u001d';

export interface SheetArchiveEntry {
  readonly rowIds?: readonly number[];
  readonly id: string;
  readonly name: string;
  readonly purpose: string;
  /**
   * 物理表名随档保存而不是按 `name + id` 重算：表改名后物理名不变，
   * 重算会在新设备上得到另一个名字，导致同一张表被当成两张。
   */
  readonly physicalName: string;
  readonly policy: SheetPolicy;
  readonly rowTemplate: string;
  readonly tokenBudget: number;
  readonly orderNo: number;
  readonly updatedAt: number;
  /** 注入条件（IF 语法的表达式部分）；空串表示无条件。 */
  readonly injectCondition: string;
  /** 这张表的填表规则；空串表示没有额外规则。 */
  readonly fillGuide: string;
  readonly columns: readonly string[];
  readonly rows: readonly (readonly string[])[];
}

export interface SheetArchive {
  readonly presetState?: PresetScopeState;
  /** 结构迁移前像；键相对当前聊天的备份前缀。 */
  readonly migrationBackups?: Readonly<Record<string, string>>;
  readonly version: number;
  readonly scopeId: string;
  readonly updatedAt: number;
  readonly sheets: readonly SheetArchiveEntry[];
}

/** 归档输入：注册元数据 + 列顺序 + 按列顺序对齐的行文本。 */
export interface SheetArchiveSource {
  readonly rowIds?: readonly number[];
  readonly sheet: Omit<SheetArchiveEntry, 'columns' | 'rows'>;
  readonly columns: readonly string[];
  readonly rows: readonly (readonly string[])[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function sheetPolicy(value: unknown): SheetPolicy {
  return value === 'always' || value === 'manual' ? value : 'recall';
}

function textCells(value: unknown): readonly string[] {
  return Array.isArray(value) ? value.map((cell) => (typeof cell === 'string' ? cell : String(cell ?? ''))) : [];
}

function archiveEntry(value: unknown): readonly SheetArchiveEntry[] {
  if (!isRecord(value)) return [];
  const id = typeof value.id === 'string' ? value.id : '';
  const physicalName = typeof value.physicalName === 'string' ? value.physicalName : '';
  const columns = textCells(value.columns);
  if (!id || !physicalName || columns.length === 0) return [];
  return [{
    id,
    name: typeof value.name === 'string' ? value.name : id,
    purpose: typeof value.purpose === 'string' ? value.purpose : '',
    physicalName,
    policy: sheetPolicy(value.policy),
    rowTemplate: typeof value.rowTemplate === 'string' ? value.rowTemplate : '',
    tokenBudget: Number.isFinite(value.tokenBudget) ? Number(value.tokenBudget) : 256,
    orderNo: Number.isFinite(value.orderNo) ? Number(value.orderNo) : 0,
    updatedAt: Number.isFinite(value.updatedAt) ? Number(value.updatedAt) : 0,
    injectCondition: typeof value.injectCondition === 'string' ? value.injectCondition : '',
    fillGuide: typeof value.fillGuide === 'string' ? value.fillGuide : '',
    columns,
    rows: Array.isArray(value.rows) ? value.rows.map(textCells) : [],
    ...(Array.isArray(value.rowIds) && value.rowIds.length === (Array.isArray(value.rows) ? value.rows.length : 0)
      && value.rowIds.every((id) => Number.isSafeInteger(id) && Number(id) > 0)
      && new Set(value.rowIds).size === value.rowIds.length ? { rowIds: value.rowIds as number[] } : {}),
  }];
}

/**
 * 宽松解析：归档来自聊天文件，可能被手工编辑或由旧版本写入。
 * 缺少 id/物理名/列的条目直接丢弃，其余字段按默认值补齐，绝不因为一条坏数据放弃整份归档。
 */
export function parseSheetArchive(value: unknown): SheetArchive | null {
  if (!isRecord(value) || typeof value.scopeId !== 'string' || !value.scopeId) return null;
  if (!Array.isArray(value.sheets)) return null;
  return {
    version: Number.isFinite(value.version) ? Number(value.version) : SHEET_ARCHIVE_VERSION,
    scopeId: value.scopeId,
    updatedAt: Number.isFinite(value.updatedAt) ? Number(value.updatedAt) : 0,
    sheets: value.sheets.flatMap(archiveEntry),
    ...(isRecord(value.presetState) ? { presetState: normalizePresetScopeState(value.presetState) } : {}),
    ...(isRecord(value.migrationBackups) ? { migrationBackups: Object.fromEntries(Object.entries(value.migrationBackups)
      .filter((entry): entry is [string, string] => typeof entry[1] === 'string')) } : {}),
  };
}

export function captureSheetArchive(
  scopeId: string,
  sources: readonly SheetArchiveSource[],
  now = Date.now(),
  extra: Pick<SheetArchive, 'presetState' | 'migrationBackups'> = {},
): SheetArchive {
  return {
    version: SHEET_ARCHIVE_VERSION,
    scopeId,
    updatedAt: now,
    sheets: sources.map((source) => ({ ...source.sheet, columns: source.columns, rows: source.rows,
      ...(source.rowIds ? { rowIds: source.rowIds } : {}),
    })),
    ...extra,
  };
}

/**
 * 内容指纹：判断「本地是否有未上传的改动」与「远端归档是否带来新内容」的唯一依据。
 *
 * 刻意不含 `updatedAt`：时间戳每次写入都会变，纳入指纹会让每一次读取都被误判成有改动，
 * 从而在两个浏览器之间来回覆盖。`orderNo` 反过来必须纳入，它是用户可见的表排序。
 */
export function sheetArchiveFingerprint(archive: Pick<SheetArchive, 'sheets' | 'presetState' | 'migrationBackups'>): string {
  const canonical = [...archive.sheets]
    .sort((left, right) => left.id.localeCompare(right.id))
    .map((sheet) => [
      sheet.id,
      sheet.name,
      sheet.purpose,
      sheet.physicalName,
      sheet.policy,
      sheet.rowTemplate,
      String(sheet.tokenBudget),
      String(sheet.orderNo),
      sheet.injectCondition,
      sheet.fillGuide,
      sheet.columns.join(CELL_SEPARATOR),
      sheet.rows.map((row) => row.join(CELL_SEPARATOR)).join(ROW_SEPARATOR),
      ...(sheet.rowIds ? [JSON.stringify(sheet.rowIds)] : []),
    ].join(ROW_SEPARATOR))
    .join(SHEET_SEPARATOR);
  const state = archive.presetState ? presetScopeFingerprint(archive.presetState) : '';
  const backups = archive.migrationBackups && Object.keys(archive.migrationBackups).length
    ? JSON.stringify(Object.entries(archive.migrationBackups).sort(([a], [b]) => a.localeCompare(b))) : '';
  return hashText(canonical + (state || backups ? JSON.stringify([state, backups]) : ''));
}

export const EMPTY_SHEET_ARCHIVE_FINGERPRINT = sheetArchiveFingerprint({ sheets: [] });

export type SheetArchiveSyncDecision =
  | { readonly kind: 'noop'; readonly reason: string }
  | { readonly kind: 'adopt-remote'; readonly reason: string }
  | { readonly kind: 'push-local'; readonly reason: string };

function latestUpdatedAt(archive: SheetArchive): number {
  return archive.sheets.reduce((latest, sheet) => Math.max(latest, sheet.updatedAt), archive.presetState?.updatedAt ?? 0);
}

export function sheetArchiveHasContent(archive: SheetArchive): boolean {
  return archive.sheets.length > 0 || !!archive.presetState || Object.keys(archive.migrationBackups ?? {}).length > 0;
}

/**
 * 本地库与聊天文件归档的同步决策。
 *
 * `archivedFingerprint` 是本地库记下的「上次成功归档时的内容」，它把三种局面区分开：
 * 本地干净（可以安全采用远端）、本地领先（应该覆盖远端）、本浏览器从未归档过（首次接触，
 * 既可能是老用户第一次升级到归档版本，也可能是换了新浏览器）。
 *
 * 首次接触时不能用 dirty 判据：新浏览器的本地永远"脏"，照 dirty 处理会把空库推上去、
 * 清空别的设备写好的数据。因此首次接触改按「本地有没有表」和 `updatedAt` 新旧来判。
 */
export function decideSheetArchiveSync(input: {
  readonly local: SheetArchive;
  readonly remote: SheetArchive | null;
  readonly archivedFingerprint: string | null;
}): SheetArchiveSyncDecision {
  const localFingerprint = sheetArchiveFingerprint(input.local);
  const remoteFingerprint = input.remote ? sheetArchiveFingerprint(input.remote) : null;
  if (remoteFingerprint === localFingerprint) return { kind: 'noop', reason: '本地与聊天文件的表格内容一致。' };

  if (!input.remote) {
    if (!sheetArchiveHasContent(input.local)) return { kind: 'noop', reason: '本地与聊天文件都没有表格。' };
    return { kind: 'push-local', reason: '聊天文件里还没有表格归档，上传本地表格。' };
  }

  if (input.archivedFingerprint !== null) {
    return input.archivedFingerprint === localFingerprint
      ? { kind: 'adopt-remote', reason: '本地改动都已归档，聊天文件里有更新的表格内容。' }
      : { kind: 'push-local', reason: '本地存在尚未归档的表格改动，先上传本地。' };
  }

  if (!sheetArchiveHasContent(input.local)) {
    return { kind: 'adopt-remote', reason: '本浏览器还没有表格，从聊天文件恢复。' };
  }
  return input.remote.updatedAt > latestUpdatedAt(input.local)
    ? { kind: 'adopt-remote', reason: '聊天文件里的归档比本地表格更新，以聊天文件为准。' }
    : { kind: 'push-local', reason: '本地表格比聊天文件里的归档更新，上传本地。' };
}

/** 归档条目 → 建表输入：DDL 由列顺序经 `sheet-dsl` 重新生成，与本地新建表走同一条校验路径。 */
export function archiveEntryToRegistration(scopeId: string, entry: SheetArchiveEntry): SheetRegistrationInput {
  return {
    id: entry.id,
    scopeId,
    name: entry.name,
    purpose: entry.purpose || entry.name,
    physicalName: entry.physicalName,
    ddl: createSheetDdl(entry.physicalName, entry.columns.map((name) => ({ name, type: 'TEXT' as const }))),
    policy: entry.policy,
    rowTemplate: entry.rowTemplate || entry.columns.map((name) => `${name}={{${name}}}`).join('；'),
    tokenBudget: entry.tokenBudget,
    orderNo: entry.orderNo,
    injectCondition: entry.injectCondition,
    fillGuide: entry.fillGuide,
  };
}
