/**
 * InitVar 用的 YAML 子集解析。
 *
 * 为什么自己写：真实 MVU 卡的 InitVar 一半是 JSON、一半是 YAML（用户本机 20 多张卡里两种都有），
 * 而这个扩展的运行环境里不保证有 YAML 库——`window.YAML` 只在装了酒馆助手时存在，
 * 测试环境更是完全没有。两套解析器会漂移，因此统一走这一份。
 *
 * 支持范围按 InitVar 的实际写法收敛：
 * - 缩进嵌套映射、`key: value`、引号字符串、数字/布尔/null 推断；
 * - 行内流式集合 `[a, b]` / `{a: 1}`（MVU 的 `[值, 描述]` 二元组就走这里）；
 * - `- item` 块序列（标量与紧凑映射）；
 * - `#` 注释、`|` / `>` 块标量。
 * 不支持锚点、别名、多文档、复杂键——遇到就当普通字符串，不猜。
 */

export type YamlValue = string | number | boolean | null | readonly YamlValue[] | { readonly [key: string]: YamlValue };

interface YamlLine {
  readonly indent: number;
  readonly text: string;
}

/** 去掉行尾注释：引号内的 `#` 必须原样保留。 */
function stripComment(line: string): string {
  let quote: '"' | '\'' | null = null;
  for (let index = 0; index < line.length; index += 1) {
    const char = line[index];
    if (quote) {
      if (char === '\\' && quote === '"') index += 1;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'') {
      quote = char;
      continue;
    }
    if (char === '#' && (index === 0 || /\s/.test(line[index - 1] ?? ' '))) return line.slice(0, index);
  }
  return line;
}

function toLines(source: string): readonly YamlLine[] {
  return source.replace(/\r\n?/g, '\n').split('\n').flatMap((raw): readonly YamlLine[] => {
    const withoutComment = stripComment(raw);
    if (!withoutComment.trim()) return [];
    if (/^\s*---\s*$/.test(withoutComment) || /^\s*\.\.\.\s*$/.test(withoutComment)) return [];
    const indent = withoutComment.length - withoutComment.trimStart().length;
    return [{ indent, text: withoutComment.trim() }];
  });
}

/** 在流式集合与引号之外找第一个分隔符。 */
function findTopLevel(text: string, predicate: (char: string, index: number) => boolean): number {
  let quote: '"' | '\'' | null = null;
  let depth = 0;
  for (let index = 0; index < text.length; index += 1) {
    const char = text[index] ?? '';
    if (quote) {
      if (char === '\\' && quote === '"') index += 1;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'') {
      quote = char;
      continue;
    }
    if (char === '[' || char === '{') depth += 1;
    else if (char === ']' || char === '}') depth -= 1;
    else if (depth === 0 && predicate(char, index)) return index;
  }
  return -1;
}

function unquote(text: string): string | null {
  if (text.length >= 2 && text.startsWith('\'') && text.endsWith('\'')) {
    return text.slice(1, -1).replaceAll('\'\'', '\'');
  }
  if (text.length >= 2 && text.startsWith('"') && text.endsWith('"')) {
    try {
      return JSON.parse(text) as string;
    } catch {
      return text.slice(1, -1);
    }
  }
  return null;
}

/** 拆分流式集合的顶层逗号项。 */
function splitFlowItems(body: string): readonly string[] {
  const items: string[] = [];
  let start = 0;
  let quote: '"' | '\'' | null = null;
  let depth = 0;
  for (let index = 0; index < body.length; index += 1) {
    const char = body[index] ?? '';
    if (quote) {
      if (char === '\\' && quote === '"') index += 1;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'') {
      quote = char;
      continue;
    }
    if (char === '[' || char === '{') depth += 1;
    else if (char === ']' || char === '}') depth -= 1;
    else if (char === ',' && depth === 0) {
      items.push(body.slice(start, index).trim());
      start = index + 1;
    }
  }
  const tail = body.slice(start).trim();
  if (tail) items.push(tail);
  return items;
}

function parseScalar(raw: string): YamlValue {
  const text = raw.trim();
  if (!text) return null;
  const unquoted = unquote(text);
  if (unquoted !== null) return unquoted;
  if (text === '{}') return {};

  if (text.startsWith('[') && text.endsWith(']')) {
    return splitFlowItems(text.slice(1, -1)).map((item) => parseScalar(item));
  }
  if (text.startsWith('{') && text.endsWith('}')) {
    const record: Record<string, YamlValue> = {};
    let parsedAny = false;
    for (const item of splitFlowItems(text.slice(1, -1))) {
      const colon = findTopLevel(item, (char) => char === ':');
      if (colon < 0) continue;
      const key = (unquote(item.slice(0, colon).trim()) ?? item.slice(0, colon).trim());
      if (!key) continue;
      record[key] = parseScalar(item.slice(colon + 1));
      parsedAny = true;
    }
    // `{{user}}` 这类模板占位符不是流式映射，解析不出键值就按原文保留。
    return parsedAny ? record : text;
  }

  const lower = text.toLowerCase();
  if (lower === 'true' || lower === 'yes') return true;
  if (lower === 'false' || lower === 'no') return false;
  if (lower === 'null' || text === '~') return null;
  if (/^[-+]?\d+$/.test(text)) return Number.parseInt(text, 10);
  if (/^[-+]?\d*\.\d+(?:[eE][-+]?\d+)?$/.test(text)) return Number.parseFloat(text);
  return text;
}

interface Cursor {
  index: number;
}

function blockScalar(lines: readonly YamlLine[], cursor: Cursor, indent: number, fold: boolean): string {
  const collected: string[] = [];
  while (cursor.index < lines.length) {
    const line = lines[cursor.index]!;
    if (line.indent <= indent) break;
    collected.push(line.text);
    cursor.index += 1;
  }
  return collected.join(fold ? ' ' : '\n');
}

function parseBlock(lines: readonly YamlLine[], cursor: Cursor, indent: number): YamlValue {
  const first = lines[cursor.index];
  if (!first || first.indent < indent) return null;
  return first.text.startsWith('- ') || first.text === '-'
    ? parseSequence(lines, cursor, first.indent)
    : parseMapping(lines, cursor, first.indent);
}

function parseSequence(lines: readonly YamlLine[], cursor: Cursor, indent: number): readonly YamlValue[] {
  const items: YamlValue[] = [];
  while (cursor.index < lines.length) {
    const line = lines[cursor.index]!;
    if (line.indent !== indent || !(line.text === '-' || line.text.startsWith('- '))) break;
    const rest = line.text === '-' ? '' : line.text.slice(2).trim();
    cursor.index += 1;
    if (!rest) {
      items.push(parseBlock(lines, cursor, indent + 1));
      continue;
    }
    const colon = findTopLevel(rest, (char) => char === ':');
    const looksLikeMap = colon > 0 && !rest.startsWith('[') && !rest.startsWith('{');
    if (!looksLikeMap) {
      items.push(parseScalar(rest));
      continue;
    }
    // `- key: value` 紧凑映射：把这一行当成子映射的第一条，再吃掉后面更深缩进的行。
    const inline: YamlLine[] = [{ indent: indent + 2, text: rest }];
    while (cursor.index < lines.length && lines[cursor.index]!.indent > indent) {
      inline.push({ indent: indent + 2, text: lines[cursor.index]!.text });
      cursor.index += 1;
    }
    const innerCursor: Cursor = { index: 0 };
    items.push(parseMapping(inline, innerCursor, indent + 2));
  }
  return items;
}

function parseMapping(lines: readonly YamlLine[], cursor: Cursor, indent: number): YamlValue {
  const record: Record<string, YamlValue> = {};
  while (cursor.index < lines.length) {
    const line = lines[cursor.index]!;
    if (line.indent < indent) break;
    if (line.indent > indent) {
      // 缩进异常（卡片手写常见）：跳过这一行，不因为一处对不齐放弃整份变量。
      cursor.index += 1;
      continue;
    }
    if (line.text === '-' || line.text.startsWith('- ')) break;
    const colon = findTopLevel(line.text, (char) => char === ':');
    if (colon < 0) {
      cursor.index += 1;
      continue;
    }
    const rawKey = line.text.slice(0, colon).trim();
    const key = unquote(rawKey) ?? rawKey;
    const rest = line.text.slice(colon + 1).trim();
    cursor.index += 1;
    if (!key) continue;
    if (rest === '|' || rest === '|-' || rest === '|+' || rest === '>' || rest === '>-' || rest === '>+') {
      record[key] = blockScalar(lines, cursor, indent, rest.startsWith('>'));
      continue;
    }
    if (rest) {
      record[key] = parseScalar(rest);
      continue;
    }
    const next = lines[cursor.index];
    record[key] = next && next.indent > indent ? parseBlock(lines, cursor, next.indent) : null;
  }
  return record;
}

/** 解析 YAML 子集；顶层是映射或序列，解析不出内容时返回 null。 */
export function parseYamlLite(source: string): YamlValue {
  const lines = toLines(source);
  if (lines.length === 0) return null;
  const cursor: Cursor = { index: 0 };
  return parseBlock(lines, cursor, lines[0]!.indent);
}
