import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import { SELF_PROFILE_ID } from '../../domain/commands.js';
import { APP_ID_LABELS, type Conversation, type MessageKind, type PhoneMessage, type PhonePost, type Profile } from '../../domain/model.js';
import { replaceImageMarkers } from '../../generation/image-client.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon, type PhoneIconName } from '../../ui/phone-icon.js';
import { appendMessageBody, createChatExtPanel, describeContactMatchResult, describeMessagePreview, formatTime, latestMessagesByConversation, pickImageAsDataUrl, renderAvatar, renderDirectiveCard, renderMediaMessageCard, renderMessageRollback, renderPostCard, renderQueuedMessageDelete, renderRichContent, richContextOf, scrollToLatestMessage, selectRecentMessages, sendDirectiveMessage, sendMediaMessage } from '../shared-view.js';
import { createProfileAvatarGenerator } from '../profile-avatar-generator.js';

export function createWechatApp(): PhoneAppDefinition {
  let contactDeleteMode = false;
  const selectedContactIds = new Set<string>();
  const enterContactDeleteMode = (context: PhoneViewContext): void => {
    contactDeleteMode = true;
    selectedContactIds.clear();
    context.navigate('wechatContacts');
  };
  const exitContactDeleteMode = (context: PhoneViewContext): void => {
    contactDeleteMode = false;
    selectedContactIds.clear();
    context.navigate('wechatContacts');
  };

  return {
    id: 'wechat',
    label: APP_ID_LABELS.wechat,
    icon: '微信',
    navigation: [
      { route: 'wechat', label: '消息', icon: 'chat' },
      { route: 'wechatContacts', label: '通讯录', icon: 'contacts' },
      { route: 'wechatDiscover', label: '发现', icon: 'discover' },
      { route: 'wechatMe', label: '我', icon: 'me' },
    ],
    render(context) {
      if (context.selectedConversationId) {
        const conversation = context.state.conversations[context.selectedConversationId];
        if (conversation?.appId === 'wechat') return renderConversation(context, conversation);
      }
      if (context.route === 'wechatContacts') {
        return renderContactPage(context, {
          deleteMode: contactDeleteMode,
          selectedContactIds,
          onEnterDeleteMode: () => enterContactDeleteMode(context),
          onExitDeleteMode: () => exitContactDeleteMode(context),
        });
      }
      if (context.route === 'wechatDiscover') return renderDiscoverPage(context);
      if (context.route === 'wechatMoments') return renderMoments(context);
      if (context.route === 'wechatMe') return renderMePage(context);
      return renderConversationList(context);
    },
  };
}

function renderConversationList(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-wechat-page phone-wechat-chats' });
  const conversations = Object.values(context.state.conversations)
    .filter((conversation) => conversation.appId === 'wechat')
    .sort((a, b) => b.updatedAt - a.updatedAt);
  const list = element('div', { className: 'phone-list phone-wechat-list' });
  const latestByConversation = latestMessagesByConversation(context.state);
  for (const conversation of conversations) {
    const latest = latestByConversation.get(conversation.id);
    const peerId = conversation.participantIds.find((id) => id !== SELF_PROFILE_ID);
    const item = button('', 'phone-wechat-list-item phone-searchable-item', () => {
      context.openConversation(conversation.id);
      if (conversation.unreadCount > 0) void context.commands.markConversationRead(conversation.id);
    });
    const body = element('span', { className: 'phone-wechat-item-body' });
    const titleLine = element('span', { className: 'phone-wechat-item-line' });
    titleLine.append(
      element('strong', { className: 'phone-wechat-item-title', text: conversation.title }),
      element('time', { className: 'phone-wechat-item-time', text: formatListTime(conversation.updatedAt, context.state.worldClock.now) }),
    );
    const previewLine = element('span', { className: 'phone-wechat-item-line phone-wechat-preview-line' });
    previewLine.append(element('span', {
      className: 'phone-wechat-item-preview',
      text: latest ? replaceImageMarkers(describeMessagePreview(latest, '开始聊天')) : '开始聊天',
    }));
    if (conversation.muted) previewLine.append(element('span', { className: 'phone-wechat-muted-mark', text: '免打扰' }));
    body.append(titleLine, previewLine);
    const avatar = renderAvatar(context.state.profiles[peerId ?? ''], 'phone-avatar phone-wechat-avatar');
    if (conversation.unreadCount > 0) {
      const avatarWrap = element('span', { className: 'phone-avatar-wrap' });
      avatarWrap.append(avatar, element('span', { className: 'phone-badge', text: String(conversation.unreadCount) }));
      item.append(avatarWrap, body);
    } else {
      item.append(avatar, body);
    }
    list.append(item);
  }

  const search = renderSearchField('搜索聊天', list);
  const actions = element('div', { className: 'phone-wechat-inline-actions' });
  actions.append(
    iconAction('发起群聊', 'group', () => createGroupConversation(context)),
    iconAction('添加联系人', 'friend', () => addContact(context)),
  );
  page.append(search, actions);
  if (conversations.length === 0) {
    page.append(renderWechatEmpty('还没有聊天', '从通讯录添加联系人，或发起一个群聊。'));
  } else {
    page.append(list);
  }
  return page;
}

interface ContactPageOptions {
  readonly deleteMode: boolean;
  readonly selectedContactIds: Set<string>;
  readonly onEnterDeleteMode: () => void;
  readonly onExitDeleteMode: () => void;
}

function renderContactPage(context: PhoneViewContext, options: ContactPageOptions): HTMLElement {
  const page = element('div', { className: 'phone-page phone-wechat-page phone-wechat-contacts' });
  const shortcutList = element('div', { className: 'phone-wechat-shortcuts' });
  const autoMatch = shortcutRow(
    '自动匹配',
    '从当前绑定的世界书补全联系人资料',
    'autoMatch',
    () => autoMatchWechatContact(context, autoMatch),
    'blue',
  );
  shortcutList.append(
    shortcutRow('新的朋友', '添加联系人', 'friend', () => addContact(context), 'green'),
    autoMatch,
    shortcutRow('群聊', '选择联系人发起群聊', 'group', () => createGroupConversation(context), 'green'),
  );

  const profiles = Object.values(context.state.profiles)
    .filter((profile) => profile.id !== SELF_PROFILE_ID && isWechatContact(context, profile))
    .sort((a, b) => a.displayName.localeCompare(b.displayName, 'zh-CN'));
  const list = element('div', { className: 'phone-list phone-wechat-contact-list' });
  const selectedCount = element('span', { className: 'phone-wechat-delete-count' });
  const deleteSelected = button('', 'phone-wechat-delete-action', async () => {
    if (!options.deleteMode) {
      options.onEnterDeleteMode();
      return;
    }
    if (options.selectedContactIds.size === 0) {
      context.showNotice('请先选择要删除的联系人', 'info');
      return;
    }
    const names = profiles
      .filter((profile) => options.selectedContactIds.has(profile.id))
      .map((profile) => profile.displayName)
      .join('、');
    if (!window.confirm(`确定删除联系人「${names}」吗？相关微信会话和消息也会一并删除。`)) return;
    deleteSelected.disabled = true;
    try {
      const count = await context.commands.deleteWechatContacts([...options.selectedContactIds]);
      options.onExitDeleteMode();
      context.showNotice(`已删除 ${count} 位联系人`, 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      deleteSelected.disabled = false;
    }
  });
  deleteSelected.append(renderPhoneIcon('trash'), element('span', { text: '删除联系人' }), selectedCount);
  const updateDeleteToolbar = () => {
    selectedCount.textContent = options.selectedContactIds.size > 0 ? `已选 ${options.selectedContactIds.size}` : '';
    deleteSelected.classList.toggle('has-selection', options.selectedContactIds.size > 0);
  };
  updateDeleteToolbar();
  for (const profile of profiles) {
    const conversation = findWechatConversation(context, profile);
    const item = button('', 'phone-wechat-contact-item phone-searchable-item', () => {
      if (options.deleteMode) {
        toggleContactSelection(profile.id, item, mark, options.selectedContactIds, updateDeleteToolbar);
        return;
      }
      if (conversation) context.openConversation(conversation.id);
      else context.showNotice('该联系人还没有微信会话', 'info');
    });
    const mark = element('span', { className: 'phone-wechat-contact-check', attributes: { 'aria-hidden': 'true' } });
    const main = element('span', { className: 'phone-wechat-contact-main' });
    main.append(
      element('strong', { text: profile.displayName }),
      element('small', { text: profile.boundCharacter ? `绑定：${profile.boundCharacter}` : (profile.aliases.wechat ?? '微信联系人') }),
    );
    const avatar = renderAvatar(profile, 'phone-avatar phone-wechat-avatar phone-avatar-clickable');
    avatar.title = options.deleteMode ? '选择联系人' : '查看资料';
    avatar.addEventListener('click', (event) => {
      event.stopPropagation();
      if (options.deleteMode) {
        toggleContactSelection(profile.id, item, mark, options.selectedContactIds, updateDeleteToolbar);
      } else {
        openProfileEditor(context, profile.id);
      }
    });
    if (options.deleteMode) item.append(mark, avatar, main);
    else item.append(avatar, main);
    item.classList.toggle('is-selected', options.selectedContactIds.has(profile.id));
    updateContactSelectionMark(item, mark, options.selectedContactIds.has(profile.id));
    list.append(item);
  }

  const modeActions = element('div', { className: 'phone-wechat-delete-toolbar' });
  if (options.deleteMode) {
    const cancel = button('取消', 'phone-button phone-button-secondary phone-button-compact', options.onExitDeleteMode);
    modeActions.append(element('span', { className: 'phone-wechat-delete-hint', text: '点击联系人进行多选' }), cancel, deleteSelected);
  } else {
    modeActions.append(deleteSelected);
  }

  page.append(renderSearchField('搜索联系人', list), shortcutList, modeActions);
  if (profiles.length === 0) {
    page.append(renderWechatEmpty('通讯录为空', '点击“新的朋友”添加第一位联系人。'));
  } else {
    page.append(element('div', { className: 'phone-wechat-section-label', text: '联系人' }), list);
  }
  return page;
}

function toggleContactSelection(
  profileId: string,
  item: HTMLElement,
  mark: HTMLElement,
  selectedContactIds: Set<string>,
  updateToolbar: () => void,
): void {
  if (selectedContactIds.has(profileId)) selectedContactIds.delete(profileId);
  else selectedContactIds.add(profileId);
  const selected = selectedContactIds.has(profileId);
  item.classList.toggle('is-selected', selected);
  updateContactSelectionMark(item, mark, selected);
  updateToolbar();
}

function updateContactSelectionMark(item: HTMLElement, mark: HTMLElement, selected: boolean): void {
  mark.textContent = selected ? '✓' : '';
}

function renderDiscoverPage(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-wechat-page phone-wechat-discover' });
  const momentCount = Object.values(context.state.posts).filter((post) => post.kind === 'moment').length;
  const social = element('div', { className: 'phone-wechat-menu-group' });
  social.append(shortcutRow(
    '朋友圈',
    momentCount > 0 ? `${momentCount} 条动态` : '分享和查看好友生活',
    'moments',
    () => context.navigate('wechatMoments'),
    'blue',
  ));
  const utilities = element('div', { className: 'phone-wechat-menu-group' });
  utilities.append(
    shortcutRow('扫一扫', '识别二维码或条码', 'scan', () => context.showNotice('扫一扫功能暂未开放', 'info'), 'blue'),
    shortcutRow('看一看', '浏览当前世界的公开动态', 'discover', () => context.showNotice('公开动态会在论坛和推特中显示', 'info'), 'orange'),
  );
  page.append(social, utilities);
  return page;
}

function renderMePage(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-wechat-page phone-wechat-me' });
  const self = context.state.profiles[SELF_PROFILE_ID];
  const profile = element('section', { className: 'phone-wechat-profile-card' });
  const profileCopy = element('div', { className: 'phone-wechat-profile-copy' });
  profileCopy.append(
    element('h2', { text: self?.displayName ?? '微信用户' }),
    element('p', { text: `微信号：${self?.aliases.wechat ?? '尚未设置'}` }),
  );
  profile.append(
    renderAvatar(self, 'phone-avatar phone-wechat-profile-avatar'),
    profileCopy,
    renderPhoneIcon('chevron'),
  );

  const personal = element('div', { className: 'phone-wechat-menu-group' });
  personal.append(shortcutRow('朋友圈', '查看我发布的动态', 'moments', () => context.navigate('wechatMoments'), 'blue'));
  const system = element('div', { className: 'phone-wechat-menu-group' });
  system.append(shortcutRow('设置', '连接、生成与数据管理', 'settings', () => context.navigate('settings'), 'gray'));
  page.append(profile, personal, system);
  return page;
}

function renderConversation(context: PhoneViewContext, conversation: Conversation): HTMLElement {
  if (conversation.unreadCount > 0) void context.commands.markConversationRead(conversation.id);
  const page = element('div', { className: `phone-chat phone-wechat-chat${conversation.kind === 'group' ? ' has-header' : ''}` });
  const messages = selectRecentMessages(context.state, conversation.id, 120);
  const list = element('div', { className: 'phone-message-list phone-wechat-message-list' });

  // 联系人自定义的聊天背景图。
  if (conversation.kind === 'direct') {
    const peerId = conversation.participantIds.find((id) => id !== SELF_PROFILE_ID);
    const peer = peerId ? context.state.profiles[peerId] : undefined;
    if (peer?.chatBackgroundUrl) {
      list.style.backgroundImage = `url("${peer.chatBackgroundUrl}")`;
      list.style.backgroundSize = 'cover';
      list.style.backgroundPosition = 'center';
      list.classList.add('has-custom-background');
    }
  }
  if (conversation.kind === 'group') {
    list.append(element('div', { className: 'phone-chat-system-note', text: `${conversation.participantIds.length} 位成员` }));
  }
  if (messages.length === 0) {
    list.append(renderWechatEmpty('还没有消息', '发送第一条消息，之后可以统一生成回复。'));
  } else {
    for (const message of messages.slice(-120)) list.append(renderMessage(context, message, conversation));
  }

  const composerWrap = element('div', { className: 'phone-chat-composer-wrap phone-wechat-composer-wrap' });
  const composer = element('form', { className: 'phone-composer phone-wechat-composer' });
  const input = element('input', {
    className: 'phone-input phone-wechat-input',
    attributes: { type: 'text', placeholder: '发消息', maxlength: '1200', autocomplete: 'off' },
  });
  const { panel, toggle } = createChatExtPanel(context, [
    { label: '图片', handler: () => sendMediaMessage(context, conversation.id, 'image') },
    { label: '视频', handler: () => sendMediaMessage(context, conversation.id, 'video') },
    { label: '位置', handler: () => sendLocationMessage(context, conversation) },
    { label: '红包', handler: () => sendRedPacketMessage(context, conversation) },
    { label: '礼物', handler: () => sendGiftMessage(context, conversation) },
    { label: '转账', handler: () => sendTransferMessage(context, conversation) },
    { label: '强行介入', handler: () => sendDirectiveMessage(context, conversation.id) },
  ]);
  const send = button('发送', 'phone-button phone-button-primary phone-wechat-send');
  const submit = async () => {
    const content = input.value.trim();
    if (!content) return;
    input.disabled = true;
    send.disabled = true;
    try {
      await context.commands.queueMessage(conversation.id, content);
      input.value = '';
      context.showNotice('消息已发送，等待统一生成回复', 'success');
    } finally {
      input.disabled = false;
      send.disabled = false;
      input.focus();
    }
  };
  composer.addEventListener('submit', (event) => {
    event.preventDefault();
    void submit().catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });
  send.addEventListener('click', () => {
    void submit().catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });
  composer.append(input, toggle, send);
  composerWrap.append(composer, panel);
  if (conversation.kind === 'group') page.append(renderWechatGroupHeader(context, conversation));
  page.append(list, composerWrap);
  scrollToLatestMessage(list);
  return page;
}

function renderWechatGroupHeader(context: PhoneViewContext, conversation: Conversation): HTMLElement {
  const header = element('header', { className: 'phone-wechat-group-header' });
  const copy = element('span', { className: 'phone-wechat-group-copy' });
  copy.append(
    element('strong', { text: conversation.title }),
    element('small', { text: `${conversation.participantIds.length} 位成员` }),
  );
  const actions = element('span', { className: 'phone-wechat-group-actions' });
  const add = button('', 'phone-icon-button phone-wechat-group-action', async () => {
    const contacts = Object.values(context.state.profiles)
      .filter((profile) => profile.id !== SELF_PROFILE_ID
        && !conversation.participantIds.includes(profile.id)
        && isWechatContact(context, profile))
      .sort((left, right) => left.displayName.localeCompare(right.displayName, 'zh-CN'))
      .map((profile) => ({
        id: profile.id,
        name: profile.displayName,
        detail: profile.aliases.wechat ?? '微信联系人',
      }));
    if (contacts.length === 0) {
      context.showNotice('没有可添加的新成员', 'info');
      return;
    }
    const selected = await context.showContactPicker('添加群成员', contacts, { min: 1 });
    if (!selected?.length) return;
    add.disabled = true;
    try {
      await context.commands.addConversationParticipants(conversation.id, selected);
      context.showNotice(`已添加 ${selected.length} 位群成员`, 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      add.disabled = false;
    }
  });
  add.append(renderPhoneIcon('friend'));
  add.setAttribute('aria-label', '添加群成员');
  add.title = '添加群成员';

  const remove = button('', 'phone-icon-button phone-wechat-group-action is-danger', async () => {
    if (!window.confirm(`确定删除群聊「${conversation.title}」吗？所有聊天记录也会一并删除。`)) return;
    remove.disabled = true;
    try {
      await context.commands.deleteConversation(conversation.id);
      context.navigate('wechat');
      context.showNotice('群聊已删除', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      remove.disabled = false;
    }
  });
  remove.append(renderPhoneIcon('trash'));
  remove.setAttribute('aria-label', '删除群聊');
  remove.title = '删除群聊';
  actions.append(add, remove);
  header.append(renderPhoneIcon('group'), copy, actions);
  return header;
}

function renderMessage(context: PhoneViewContext, message: PhoneMessage, conversation: Conversation): HTMLElement {
  const outgoing = message.direction === 'outgoing';
  const row = element('div', { className: `phone-message-row ${outgoing ? 'is-outgoing' : 'is-incoming'}` });
  const stack = element('div', { className: 'phone-message-stack' });
  const senderName = !outgoing && conversation.kind === 'group'
    ? context.state.profiles[message.profileId]?.displayName ?? '群成员'
    : undefined;
  appendMessageBody(stack, renderMessageBody(context, message), senderName ? { senderName } : {});
  stack.append(
    element('span', { className: 'phone-message-meta', text: `${formatTime(message.createdAt)} · ${statusLabel(message.status)}` }),
  );
  const profile = context.state.profiles[outgoing ? SELF_PROFILE_ID : message.profileId];
  const avatar = renderAvatar(profile, 'phone-avatar phone-chat-avatar phone-wechat-avatar phone-avatar-clickable');
  if (profile) {
    avatar.title = '查看资料';
    avatar.addEventListener('click', (event) => {
      event.stopPropagation();
      openProfileEditor(context, profile.id);
    });
  }
  // 未回复的用户消息给「删除」，已生成过内容的给「回滚重生成」。
  const control = renderQueuedMessageDelete(context, message) ?? renderMessageRollback(context, message);
  if (outgoing) {
    if (control) row.append(control);
    row.append(stack, avatar);
  } else {
    row.append(avatar, stack);
    if (control) row.append(control);
  }
  return row;
}

/** 联系人资料页：备注名、绑定角色、头像与聊天背景图均可编辑上传。 */
function openProfileEditor(context: PhoneViewContext, profileId: string): void {
  const profile = context.state.profiles[profileId];
  if (!profile) return;
  const host = document.getElementById('narrative-phone-host');
  const shellRoot = host?.shadowRoot?.querySelector<HTMLElement>('.phone-shell');
  if (!shellRoot) return;

  let avatarUrl = profile.avatarUrl ?? '';
  let backgroundUrl = profile.chatBackgroundUrl ?? '';

  const backdrop = element('div', { className: 'phone-modal-backdrop' });
  const dialog = element('div', { className: 'phone-modal phone-profile-editor', attributes: { role: 'dialog', 'aria-modal': 'true' } });
  dialog.append(element('h2', { className: 'phone-modal-title', text: '联系人资料' }));

  const avatarRow = element('div', { className: 'phone-profile-avatar-row' });
  const avatarPreview = element('button', { className: 'phone-profile-avatar', attributes: { type: 'button', title: '点击更换头像' } });
  const refreshAvatarPreview = () => {
    avatarPreview.replaceChildren();
    if (avatarUrl) {
      avatarPreview.append(element('img', { attributes: { src: avatarUrl, alt: '头像' } }));
    } else {
      avatarPreview.append(element('span', { text: profile.displayName.slice(0, 1).toUpperCase() }));
    }
  };
  refreshAvatarPreview();
  avatarPreview.addEventListener('click', () => {
    void pickImageAsDataUrl(256).then((dataUrl) => {
      if (!dataUrl) return;
      avatarUrl = dataUrl;
      refreshAvatarPreview();
    });
  });
  avatarRow.append(avatarPreview);
  dialog.append(avatarRow);

  const backgroundField = element('div', { className: 'phone-modal-field' });
  backgroundField.append(element('span', { text: '聊天背景图' }));
  const backgroundPreview = element('button', { className: 'phone-profile-background', attributes: { type: 'button', title: '点击更换聊天背景' } });
  const refreshBackgroundPreview = () => {
    backgroundPreview.style.backgroundImage = backgroundUrl ? `url("${backgroundUrl}")` : '';
    backgroundPreview.textContent = backgroundUrl ? '' : '点击上传背景图';
  };
  refreshBackgroundPreview();
  backgroundPreview.addEventListener('click', () => {
    void pickImageAsDataUrl(1024).then((dataUrl) => {
      if (!dataUrl) return;
      backgroundUrl = dataUrl;
      refreshBackgroundPreview();
    });
  });
  const clearBackground = button('清除背景', 'phone-button phone-button-secondary phone-button-compact', () => {
    backgroundUrl = '';
    refreshBackgroundPreview();
  });
  backgroundField.append(backgroundPreview, clearBackground);
  dialog.append(backgroundField);

  const nameField = element('label', { className: 'phone-modal-field' });
  nameField.append(element('span', { text: '备注名' }));
  const nameInput = element('input', { className: 'phone-modal-input', attributes: { maxlength: '40' } });
  nameInput.value = profile.displayName;
  nameField.append(nameInput);
  dialog.append(nameField);

  const boundField = element('label', { className: 'phone-modal-field' });
  boundField.append(element('span', { text: '实际绑定角色（世界书/角色卡中的正式名字）' }));
  const boundInput = element('input', { className: 'phone-modal-input', attributes: { maxlength: '80', placeholder: '留空表示与备注名相同' } });
  boundInput.value = profile.boundCharacter ?? '';
  boundField.append(boundInput);
  dialog.append(boundField);

  // 生图一致性：素体提示词 + 角色参考图。
  const appearanceField = element('label', { className: 'phone-modal-field' });
  appearanceField.append(element('span', { text: '生图素体提示词（固定外貌 tag：发色、瞳色、发型、体型等，英文逗号分隔）' }));
  const appearanceInput = element('textarea', {
    className: 'phone-modal-input phone-modal-textarea',
    attributes: { rows: '3', maxlength: '1000', placeholder: '例如：long silver hair, blue eyes, slender, small breasts, mole under eye' },
  });
  appearanceInput.value = profile.appearancePrompt ?? '';
  appearanceField.append(
    appearanceInput,
    element('small', { className: 'phone-settings-hint', text: '配置后 AI 生图会用 @备注名 引用并自动替换，任何场景下该角色的基础外貌保持一致。' }),
  );
  dialog.append(appearanceField);

  const avatarGenerator = createProfileAvatarGenerator({
    context,
    profile,
    avatarField: 'avatarUrl',
    appearanceInput,
    getDraft: () => ({
      displayName: nameInput.value,
      boundCharacter: boundInput.value,
      appearancePrompt: appearanceInput.value,
    }),
    onAvatarApplied: (url) => {
      avatarUrl = url;
      refreshAvatarPreview();
    },
  });
  avatarRow.append(avatarGenerator.control);

  let imageRefUrl = profile.imageRefUrl ?? '';
  const refField = element('div', { className: 'phone-modal-field' });
  refField.append(element('span', { text: '角色参考图（NAI v4 系专用，锁定角色长相；每张生成额外消耗 5 Anlas）' }));
  const refPreview = element('button', { className: 'phone-profile-background', attributes: { type: 'button', title: '点击上传角色参考图' } });
  const refreshRefPreview = () => {
    refPreview.style.backgroundImage = imageRefUrl ? `url("${imageRefUrl}")` : '';
    refPreview.textContent = imageRefUrl ? '' : '点击上传参考图';
  };
  refreshRefPreview();
  refPreview.addEventListener('click', () => {
    void pickImageAsDataUrl(1536).then((dataUrl) => {
      if (!dataUrl) return;
      imageRefUrl = dataUrl;
      refreshRefPreview();
    });
  });
  const refActions = element('div', { className: 'phone-inline-group' });
  const clearRef = button('移除参考图', 'phone-button phone-button-secondary phone-button-compact', () => {
    imageRefUrl = '';
    refreshRefPreview();
  });
  const strengthLabel = element('span', { className: 'phone-settings-hint', text: '参考强度' });
  const strengthInput = element('input', {
    className: 'phone-modal-input phone-profile-strength',
    attributes: { type: 'number', min: '0.1', max: '1', step: '0.05' },
  });
  strengthInput.value = String(profile.imageRefStrength ?? 0.75);
  refActions.append(clearRef, strengthLabel, strengthInput);
  refField.append(refPreview, refActions);
  dialog.append(refField);

  const actions = element('div', { className: 'phone-modal-actions' });
  const cancel = button('取消', 'phone-button phone-button-secondary', () => backdrop.remove());
  const save = button('保存', 'phone-button phone-button-primary', async () => {
    save.disabled = true;
    try {
      const strength = Number(strengthInput.value);
      await context.commands.updateProfile(profile.id, {
        displayName: nameInput.value,
        boundCharacter: boundInput.value,
        avatarUrl,
        chatBackgroundUrl: backgroundUrl,
        appearancePrompt: appearanceInput.value,
        avatarPrompt: avatarGenerator.promptInput.value,
        imageRefUrl,
        ...(Number.isFinite(strength) ? { imageRefStrength: strength } : {}),
      });
      backdrop.remove();
      context.showNotice('联系人资料已保存。', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      save.disabled = false;
    }
  });
  actions.append(cancel, save);
  dialog.append(actions);
  backdrop.append(dialog);
  backdrop.addEventListener('pointerdown', (event) => {
    if (event.target === backdrop) backdrop.remove();
  });
  shellRoot.append(backdrop);
}

function renderMoments(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-moments-page' });
  const self = context.state.profiles[SELF_PROFILE_ID];
  const cover = element('section', { className: 'phone-moments-cover' });
  const publishTrigger = button('', 'phone-moments-camera', () => {
    composer.hidden = false;
    input.focus();
  });
  publishTrigger.setAttribute('aria-label', '发布朋友圈');
  publishTrigger.append(renderPhoneIcon('camera'));
  const identity = element('div', { className: 'phone-moments-identity' });
  identity.append(
    element('strong', { text: self?.displayName ?? '微信用户' }),
    renderAvatar(self, 'phone-avatar phone-moments-self-avatar'),
  );
  cover.append(publishTrigger, identity);

  const composer = element('div', { className: 'phone-post-card phone-moments-composer' });
  composer.hidden = true;
  const input = element('textarea', {
    className: 'phone-textarea',
    attributes: { placeholder: '这一刻的想法……', maxlength: '1200' },
  });
  const composerActions = element('div', { className: 'phone-composer-footer' });
  const cancel = button('取消', 'phone-button phone-button-secondary', () => {
    input.value = '';
    composer.hidden = true;
  });
  const publish = button('发表', 'phone-button phone-button-primary', async () => {
    const content = input.value.trim();
    if (!content) return;
    await context.commands.createUserPost('wechat', 'moment', content);
    input.value = '';
    composer.hidden = true;
    context.showNotice('朋友圈已发布', 'success');
  });
  composerActions.append(cancel, publish);
  composer.append(input, composerActions);

  const posts = selectPosts(context, 'moment');
  const feed = element('div', { className: 'phone-feed phone-moments-feed' });
  for (const post of posts) {
    feed.append(renderPostCard(context.state, post, {
      rich: richContextOf(context),
      onLike: () => interactWithPost(context, post, 'like'),
      onComment: () => commentOnPost(context, post),
    }));
  }
  if (posts.length === 0) feed.append(renderWechatEmpty('朋友圈还没有动态', '点击右上角相机发布第一条动态。'));
  page.append(cover, composer, feed);
  return page;
}

function renderSearchField(placeholder: string, list: HTMLElement): HTMLElement {
  const field = element('label', { className: 'phone-wechat-search' });
  const input = element('input', {
    className: 'phone-wechat-search-input',
    attributes: { type: 'search', placeholder, autocomplete: 'off' },
  });
  input.addEventListener('input', () => {
    const keyword = input.value.trim().toLocaleLowerCase('zh-CN');
    for (const item of list.querySelectorAll<HTMLElement>('.phone-searchable-item')) {
      item.hidden = Boolean(keyword) && !item.textContent?.toLocaleLowerCase('zh-CN').includes(keyword);
    }
  });
  field.append(renderPhoneIcon('search'), input);
  return field;
}

function iconAction(label: string, icon: PhoneIconName, action: () => void | Promise<void>): HTMLButtonElement {
  const control = button('', 'phone-wechat-inline-action', action);
  control.append(renderPhoneIcon(icon), element('span', { text: label }));
  return control;
}

function shortcutRow(
  title: string,
  detail: string,
  icon: PhoneIconName,
  action: () => void | Promise<void>,
  color: 'green' | 'blue' | 'orange' | 'gray',
): HTMLButtonElement {
  const row = button('', 'phone-wechat-menu-row', action);
  const iconBox = element('span', { className: `phone-wechat-menu-icon is-${color}` });
  iconBox.append(renderPhoneIcon(icon));
  const copy = element('span', { className: 'phone-wechat-menu-copy' });
  copy.append(element('strong', { text: title }), element('small', { text: detail }));
  row.append(iconBox, copy, renderPhoneIcon('chevron'));
  return row;
}

function renderWechatEmpty(title: string, detail: string): HTMLElement {
  const empty = element('div', { className: 'phone-empty phone-wechat-empty' });
  empty.append(renderPhoneIcon('chat'), element('strong', { text: title }), element('span', { text: detail }));
  return empty;
}

async function autoMatchWechatContact(context: PhoneViewContext, trigger: HTMLButtonElement): Promise<void> {
  trigger.disabled = true;
  context.showNotice('正在从当前世界书批量匹配微信联系人…', 'info');
  try {
    const result = await context.autoMatchContact({ platform: 'wechat' });
    context.showNotice(
      describeContactMatchResult(result, '微信联系人'),
      result.contacts.length > 0 ? 'success' : 'info',
    );
    const single = result.contacts.length === 1 ? result.contacts[0] : undefined;
    if (single) context.openConversation(single.conversationId);
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  } finally {
    trigger.disabled = false;
  }
}

async function addContact(context: PhoneViewContext): Promise<void> {
  const name = (await context.showModal('添加联系人', [{ name: 'name', label: '联系人名称', required: true }]))?.name;
  if (!name?.trim()) return;
  try {
    const { profile } = await context.commands.addContact({ displayName: name });
    context.showNotice(`已添加 ${profile.displayName}`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

async function createGroupConversation(context: PhoneViewContext): Promise<void> {
  const contacts = Object.values(context.state.profiles)
    .filter((profile) => profile.id !== SELF_PROFILE_ID && isWechatContact(context, profile))
    .sort((a, b) => a.displayName.localeCompare(b.displayName, 'zh-CN'))
    .map((profile) => ({
      id: profile.id,
      name: profile.displayName,
      detail: profile.aliases.wechat ?? '微信联系人',
    }));
  if (contacts.length === 0) {
    context.showNotice('还没有可邀请的联系人', 'error');
    return;
  }
  const selected = await context.showContactPicker('发起群聊', contacts, { min: 1 });
  if (!selected?.length) return;
  const profiles = selected.flatMap((id) => {
    const profile = context.state.profiles[id];
    return profile ? [profile] : [];
  });
  if (profiles.length === 0) {
    context.showNotice('没有匹配到联系人', 'error');
    return;
  }
  try {
    const conversation = await context.commands.createConversation({
      appId: 'wechat',
      kind: 'group',
      title: profiles.map((profile) => profile.displayName).join('、').slice(0, 60),
      participantIds: [SELF_PROFILE_ID, ...profiles.map((profile) => profile.id)],
    });
    context.openConversation(conversation.id);
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

function findWechatConversation(context: PhoneViewContext, profile: Profile): Conversation | undefined {
  return Object.values(context.state.conversations).find(
    (conversation) => conversation.appId === 'wechat'
      && conversation.kind === 'direct'
      && conversation.participantIds.includes(profile.id),
  );
}

/**
 * 微信通讯录只显示微信联系人：
 * 推特私信、匿名交友创建的档案（只有对应应用的别名）不会出现在这里。
 */
function isWechatContact(context: PhoneViewContext, profile: Profile): boolean {
  if (profile.aliases.wechat) return true;
  return Object.values(context.state.conversations).some(
    (conversation) => conversation.appId === 'wechat' && conversation.participantIds.includes(profile.id),
  );
}

function selectPosts(context: PhoneViewContext, kind: PhonePost['kind']): readonly PhonePost[] {
  return [...context.state.postOrder].reverse().flatMap((id) => {
    const post = context.state.posts[id];
    return post?.kind === kind ? [post] : [];
  });
}

async function interactWithPost(
  context: PhoneViewContext,
  post: PhonePost,
  type: 'like' | 'comment',
  content = '',
): Promise<void> {
  try {
    await context.commands.createUserInteraction('wechat', type, post.id, content);
    context.showNotice(type === 'like' ? '已赞' : '评论已发布', 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

async function commentOnPost(context: PhoneViewContext, post: PhonePost): Promise<void> {
  const content = (await context.showModal('评论朋友圈', [{ name: 'content', label: '评论内容', type: 'textarea', required: true }]))?.content;
  if (!content?.trim()) return;
  await interactWithPost(context, post, 'comment', content);
}

function statusLabel(status: PhoneMessage['status']): string {
  switch (status) {
    case 'queued': return '等待回复';
    case 'processing': return '生成中';
    case 'failed': return '发送失败';
    case 'sent': return '已送达';
  }
}

async function queueSpecialMessage(
  context: PhoneViewContext,
  conversationId: string,
  kind: MessageKind,
  content: string,
  metadata: Readonly<Record<string, string>>,
): Promise<void> {
  await context.commands.queueMessage(conversationId, content, { kind, metadata });
  context.showNotice('消息已发送，等待统一生成回复', 'success');
}

async function sendLocationMessage(context: PhoneViewContext, conversation: Conversation): Promise<void> {
  const values = await context.showModal('发送位置', [{ name: 'location', label: '位置名称', required: true }]);
  if (!values?.location?.trim()) return;
  const location = values.location.trim();
  await queueSpecialMessage(context, conversation.id, 'location', `[位置] ${location}`, { location });
}

async function sendRedPacketMessage(context: PhoneViewContext, conversation: Conversation): Promise<void> {
  const values = await context.showModal('发红包', [
    { name: 'amount', label: '金额（元）', type: 'number', required: true },
    { name: 'blessing', label: '祝福语', required: true },
  ]);
  if (!values?.amount?.trim() || !values.blessing?.trim()) return;
  const amount = values.amount.trim();
  const blessing = values.blessing.trim();
  await queueSpecialMessage(context, conversation.id, 'red_packet', `[红包] ${blessing}`, { amount, blessing });
}

async function sendGiftMessage(context: PhoneViewContext, conversation: Conversation): Promise<void> {
  const values = await context.showModal('送礼物', [
    { name: 'gift', label: '礼物名称', required: true },
    { name: 'note', label: '附言', type: 'textarea' },
  ]);
  if (!values?.gift?.trim()) return;
  const gift = values.gift.trim();
  const note = values.note?.trim() ?? '';
  await queueSpecialMessage(context, conversation.id, 'gift', `[礼物] ${gift}`, { gift, ...(note ? { note } : {}) });
}

async function sendTransferMessage(context: PhoneViewContext, conversation: Conversation): Promise<void> {
  const values = await context.showModal('转账', [
    { name: 'amount', label: '金额（元）', type: 'number', required: true },
    { name: 'note', label: '备注', type: 'textarea' },
  ]);
  if (!values?.amount?.trim()) return;
  const amount = values.amount.trim();
  const note = values.note?.trim() ?? '';
  await queueSpecialMessage(context, conversation.id, 'transfer', `[转账] ¥${amount}`, { amount, ...(note ? { note } : {}) });
}

function renderMessageBody(context: PhoneViewContext, message: PhoneMessage): HTMLElement {
  const kind = message.kind ?? 'text';
  // 认不出的类型（旧数据或写坏的类型）一律按文字渲染：空卡片没有卡面视觉，会变成一块看不见的区域。
  return (kind === 'text' ? undefined : renderMessageCard(message, kind))
    ?? renderRichContent(message.content, richContextOf(context));
}

/** 红包/转账/礼物：左图标 + 右侧文案的横排头部。 */
function financeCardHead(icon: string, primary: HTMLElement, secondary?: HTMLElement): HTMLElement {
  const head = element('div', { className: 'phone-msg-finance-head' });
  head.append(element('span', { className: 'phone-msg-finance-icon', text: icon }));
  const copy = element('span', { className: 'phone-msg-finance-copy' });
  copy.append(primary);
  if (secondary) copy.append(secondary);
  head.append(copy);
  return head;
}

/** 卡片底部品牌行：左侧品牌名 + 右侧领取状态。 */
function financeCardBrand(brand: string, status?: string): HTMLElement {
  const row = element('div', { className: 'phone-msg-finance-brand' });
  row.append(element('span', { text: brand }));
  if (status) row.append(element('span', { className: 'phone-msg-finance-status', text: status }));
  return row;
}

function claimText(message: PhoneMessage, claimed: string, declined: string): string | undefined {
  if (!message.claimStatus || message.claimStatus === 'none') return undefined;
  return message.claimStatus === 'claimed' ? claimed : declined;
}

function renderMessageCard(message: PhoneMessage, kind: MessageKind): HTMLElement | undefined {
  if (kind === 'image' || kind === 'video') return renderMediaMessageCard(message, kind);
  if (kind === 'directive') return renderDirectiveCard(message);
  const card = element('div', { className: `phone-msg-card phone-msg-card-${kind.replace(/_/g, '-')}` });
  const meta = message.metadata ?? {};
  const claimed = message.claimStatus && message.claimStatus !== 'none';
  switch (kind) {
    case 'location': {
      const map = element('span', { className: 'phone-msg-map' });
      map.append(element('span', { className: 'phone-msg-map-pin', text: '📍' }));
      const body = element('div', { className: 'phone-msg-map-body' });
      body.append(
        element('strong', { className: 'phone-msg-map-name', text: meta.location ?? message.content.replace(/^\[位置\]\s*/, '') }),
        element('span', { className: 'phone-msg-map-label', text: '位置' }),
      );
      card.append(map, body);
      break;
    }
    case 'red_packet': {
      if (claimed) card.classList.add('is-claimed');
      card.append(
        financeCardHead(
          '🧧',
          element('strong', { className: 'phone-msg-finance-title', text: meta.blessing ?? '恭喜发财，大吉大利' }),
          meta.amount ? element('span', { className: 'phone-msg-finance-sub', text: `¥${meta.amount}` }) : undefined,
        ),
        financeCardBrand('微信红包', claimText(message, '已领取', '已婉拒')),
      );
      break;
    }
    case 'gift': {
      if (claimed) card.classList.add('is-claimed');
      card.append(
        financeCardHead(
          '🎁',
          element('strong', { className: 'phone-msg-finance-title', text: meta.gift ?? message.content.replace(/^\[礼物\]\s*/, '') }),
          meta.note ? element('span', { className: 'phone-msg-finance-sub', text: meta.note }) : undefined,
        ),
        financeCardBrand('礼物', claimText(message, '已收下', '已婉拒')),
      );
      break;
    }
    case 'transfer': {
      if (claimed) card.classList.add('is-claimed');
      card.append(
        financeCardHead(
          '⇄',
          element('strong', { className: 'phone-msg-finance-amount', text: meta.amount ? `¥${meta.amount}` : message.content }),
          meta.note || !claimed
            ? element('span', { className: 'phone-msg-finance-sub', text: meta.note || '请收款' })
            : undefined,
        ),
        financeCardBrand('微信转账', claimText(message, '已收款', '已退回')),
      );
      break;
    }
    default:
      // 没有对应卡面的类型不硬造空卡片，交回上层按文字渲染。
      return undefined;
  }
  return card;
}

function formatListTime(timestamp: number, now: number): string {
  const date = new Date(timestamp);
  const current = new Date(now);
  if (date.toDateString() === current.toDateString()) {
    return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
  }
  return `${date.getMonth() + 1}/${date.getDate()}`;
}