import { commandTargetValue, type MvuCommand } from './commands.js';
import { formatCellValue, joinMvuPath, mappingDynamic, parseCellValue, resolveVariableTarget, splitMvuPath } from './mapping.js';
import type { MvuMapping, MvuMappingEntry } from './types.js';
import type { MvuSheetView, MvuSheetWrite, MvuWritePlan } from './projection.js';

const isRecord = (value: unknown): value is Record<string, unknown> => !!value && typeof value === 'object' && !Array.isArray(value);
const samePath = (a: readonly string[], b: readonly string[]): boolean => a.length === b.length && a.every((key, i) => key === b[i]);
const list = (value: unknown): unknown[] => Array.isArray(value) ? [...value] : typeof value === 'string' ? value.split('、').filter(Boolean) : [];

function applyValue(current: unknown, command: MvuCommand): unknown {
  const value = commandTargetValue(command);
  if (command.kind === 'set') return value;
  if (command.kind === 'add') return typeof value === 'boolean' ? !current : (Number(current) || 0) + (Number(value) || 0);
  if (command.kind === 'insert') {
    const items = list(current);
    items.splice(typeof command.index === 'number' ? Math.max(0, command.index) : items.length, 0, value);
    return items;
  }
  if (command.kind === 'delete') {
    if (command.index !== undefined) { const items = list(current); items.splice(Number(command.index), 1); return items; }
    if (Array.isArray(current)) return command.args.length ? current.filter((item) => JSON.stringify(item) !== JSON.stringify(value)) : [];
    return command.args.length ? list(current).filter((item) => item !== value) : '';
  }
  return current;
}

function editJson(current: unknown, path: readonly string[], command: MvuCommand): unknown {
  if (!path.length) return applyValue(current, command);
  const root: Record<string, unknown> | unknown[] = isRecord(current) || Array.isArray(current) ? structuredClone(current) : /^\d+$/.test(path[0] ?? '') ? [] : {};
  let target = root as Record<string, unknown>;
  for (let i = 0; i < path.length - 1; i += 1) {
    const key = path[i]!;
    if (!isRecord(target[key]) && !Array.isArray(target[key])) target[key] = /^\d+$/.test(path[i + 1] ?? '') ? [] : {};
    target = target[key] as Record<string, unknown>;
  }
  const key = path.at(-1)!;
  if (command.kind === 'delete' && command.args.length === 0 && command.index === undefined) {
    if (Array.isArray(target)) target.splice(Number(key), 1); else delete target[key];
  } else target[key] = applyValue(target[key], command);
  return root;
}

function cell(value: unknown, entry: MvuMappingEntry): string {
  if (value === null && entry.nullable) return 'null';
  if (entry.valueType === 'number' && value !== '') {
    let numeric = Number(value);
    if (!Number.isFinite(numeric)) throw new Error('数字字段需要有限数值。');
    numeric = Math.max(entry.constraints?.minimum ?? -Infinity, Math.min(entry.constraints?.maximum ?? Infinity, numeric));
    value = entry.constraints?.integer ? Math.round(numeric) : numeric;
  }
  if (entry.constraints?.enumValues?.length && !entry.constraints.enumValues.some((item) => item === value)) throw new Error('字段值不在 schema 的枚举选项内。');
  return formatCellValue(value, entry.valueType);
}

/** 在内存副本上按命令顺序编辑，再生成最小行差异；支持空字典、JSON 子路径与成员删除。 */
export function planCommandWrites(mapping: MvuMapping, source: readonly MvuSheetView[], commands: readonly MvuCommand[]): MvuWritePlan {
  const views = source.map((view) => ({ ...view, columns: [...view.columns], rows: view.rows.map((row) => ({ rowId: row.rowId, values: [...row.values] })) }));
  const skipped: { path: string; reason: string }[] = [];
  const included = new Map<number, Set<string>>();
  let nextId = -1;
  let budget = 20_000;
  const templates = mapping.entries.filter((entry) => !!mappingDynamic(entry));
  const protectsRows = (sheet: string): boolean => mapping.entries.some((entry) => entry.sheet === sheet && entry.readOnly);

  const ensureRow = (entry: MvuMappingEntry, keyValue: string) => {
    const view = views.find((item) => item.name === entry.sheet);
    if (!view) throw new Error(`表「${entry.sheet}」不存在或未物化。`);
    const keyIndex = view.columns.indexOf(entry.keyColumn);
    let row = entry.keyColumn ? view.rows.find((item) => item.values[keyIndex] === keyValue) : view.rows[0];
    if (!row) {
      const values = view.columns.map(() => '');
      const columns = new Set<string>();
      for (const candidate of mapping.entries.filter((item) => item.sheet === entry.sheet && item.defaultValue !== undefined
        && (!item.keyColumn || item.dynamic || item.keyValue === keyValue))) {
        const index = view.columns.indexOf(candidate.column);
        if (index >= 0) { values[index] = candidate.defaultValue!; columns.add(candidate.column); }
      }
      if (entry.keyColumn) {
        if (keyIndex < 0) throw new Error('成员定位列已经被删除。');
        values[keyIndex] = keyValue;
        columns.add(entry.keyColumn);
      }
      row = { rowId: nextId--, values };
      included.set(row.rowId, columns);
      view.rows.push(row);
    }
    return { view, row };
  };

  const process = (command: MvuCommand, depth = 0): void => {
    if (--budget <= 0 || depth > 24) { skipped.push({ path: command.path, reason: '写入结构超过处理预算。' }); return; }
    const path = splitMvuPath(command.path);
    if (!path.length) { skipped.push({ path: command.path, reason: '变量路径格式无效。' }); return; }
    if (command.kind === 'move') { skipped.push({ path: command.path, reason: '请用 set 和 delete 表达对象移动。' }); return; }
    const target = resolveVariableTarget(mapping, command.path);

    const scalarMemberDelete = target && mappingDynamic(target.entry)?.field.length === 0
      && !target.jsonPath?.length && command.kind === 'delete' && !command.args.length && command.index === undefined;
    if (scalarMemberDelete) {
      const view = views.find((item) => item.name === target.entry.sheet);
      if (!view || protectsRows(target.entry.sheet)) { skipped.push({ path: command.path, reason: '成员不存在或包含只读字段。' }); return; }
      const keyIndex = view.columns.indexOf(target.entry.keyColumn);
      view.rows = view.rows.filter((row) => row.values[keyIndex] !== target.keyValue);
      return;
    }
    if (!target) {
      const template = templates.find((entry) => {
        const dynamic = mappingDynamic(entry)!;
        return samePath(path, dynamic.prefix) || samePath(path.slice(0, -1), dynamic.prefix);
      });
      if (template) {
        const dynamic = mappingDynamic(template)!;
        const isCollection = samePath(path, dynamic.prefix);
        const view = views.find((item) => item.name === template.sheet);
        if (!view) { skipped.push({ path: command.path, reason: `表「${template.sheet}」不存在。` }); return; }
        const keyIndex = view.columns.indexOf(template.keyColumn);
        const key = isCollection ? undefined : path.at(-1);
        if (command.kind === 'delete') {
          if (protectsRows(template.sheet)) { skipped.push({ path: command.path, reason: '成员含有只读变量。' }); return; }
          const wanted = key ?? (command.args.length ? String(commandTargetValue(command)) : undefined);
          view.rows = view.rows.filter((row) => wanted !== undefined && row.values[keyIndex] !== wanted);
          return;
        }
        if (command.kind === 'insert' && isCollection && command.args.length >= 2) {
          process({ ...command, kind: 'set', path: joinMvuPath([...path, String(command.args[0])]), args: [command.args[1]] }, depth + 1);
          return;
        }
        const value = commandTargetValue(command);
        if (command.kind === 'set' && isRecord(value)) {
          if (isCollection) {
            if (protectsRows(template.sheet) && view.rows.some((row) => !Object.hasOwn(value, row.values[keyIndex] ?? ''))) {
              skipped.push({ path: command.path, reason: '待移除成员含有只读变量。' }); return;
            }
            view.rows = view.rows.filter((row) => Object.hasOwn(value, row.values[keyIndex] ?? ''));
          } else if (Object.keys(value).length === 0) ensureRow(template, key!);
          for (const [child, childValue] of Object.entries(value)) process({ ...command, path: joinMvuPath([...path, child]), args: [childValue] }, depth + 1);
          return;
        }
      }
      const value = commandTargetValue(command);
      if (command.kind === 'set' && isRecord(value) && Object.keys(value).length) {
        for (const [key, child] of Object.entries(value)) process({ ...command, path: joinMvuPath([...path, key]), args: [child] }, depth + 1);
        return;
      }
      skipped.push({ path: command.path, reason: '没有对应的表格映射，未写入。' });
      return;
    }
    if (target.entry.readOnly) {
      const view = views.find((item) => item.name === target.entry.sheet);
      const row = view?.rows.find((item) => !target.entry.keyColumn || item.values[view.columns.indexOf(target.entry.keyColumn)] === target.keyValue);
      const raw = row?.values[view!.columns.indexOf(target.entry.column)] ?? target.entry.defaultValue ?? '';
      if (command.kind === 'set' && JSON.stringify(parseCellValue(raw, target.entry.valueType, target.entry.nullable)) === JSON.stringify(commandTargetValue(command))) return;
      skipped.push({ path: command.path, reason: '这是原卡中的只读变量。' }); return;
    }
    try {
      const { view, row } = ensureRow(target.entry, target.keyValue);
      const index = view.columns.indexOf(target.entry.column);
      if (index < 0) throw new Error(`列 ${target.entry.column} 已被删除。`);
      const raw = row.values[index] ?? target.entry.defaultValue ?? '';
      const current = parseCellValue(raw, target.entry.valueType, target.entry.nullable);
      const value = target.entry.valueType === 'json' || target.jsonPath?.length
        ? editJson(current, target.jsonPath ?? [], command) : applyValue(current, command);
      row.values[index] = cell(value, target.entry);
      included.get(row.rowId)?.add(target.entry.column);
    } catch (error) { skipped.push({ path: command.path, reason: error instanceof Error ? error.message : String(error) }); }
  };
  // 一个对象命令里任一字段验证失败，撤销该命令的所有中间编辑，避免留下默认空行或半个对象。
  for (const command of commands) {
    const beforeRows = views.map((view) => view.rows.map((row) => ({ rowId: row.rowId, values: [...row.values] })));
    const beforeIncluded = new Map([...included].map(([id, columns]) => [id, new Set(columns)]));
    const beforeSkipped = skipped.length;
    process(command);
    if (skipped.length > beforeSkipped) {
      views.forEach((view, index) => { view.rows = beforeRows[index]!; });
      included.clear();
      for (const [id, columns] of beforeIncluded) included.set(id, columns);
    }
  }

  const writes: MvuSheetWrite[] = [];
  for (const view of views) {
    const before = source.find((item) => item.id === view.id)!;
    for (const old of before.rows) if (!view.rows.some((row) => row.rowId === old.rowId)) writes.push({ kind: 'delete', sheetId: view.id, rowId: old.rowId });
    for (const row of view.rows) {
      const old = before.rows.find((item) => item.rowId === row.rowId);
      const columns = view.columns.filter((column, i) => old ? old.values[i] !== row.values[i] : included.get(row.rowId)?.has(column));
      if (!columns.length) continue;
      const values = Object.fromEntries(columns.map((column) => [column, row.values[view.columns.indexOf(column)] ?? '']));
      writes.push(old ? { kind: 'update', sheetId: view.id, rowId: row.rowId, values } : { kind: 'insert', sheetId: view.id, values });
    }
  }
  return { writes, skipped };
}
