import { pickImageAsDataUrl } from '../apps/shared-view.js';
import {
  EMPTY_THEME_COLORS,
  type PhoneExtensionSettings,
  type PhoneSettingsPatch,
  type PhoneTheme,
  type ThemeColorOverrides,
  type ThemeColorPreset,
} from '../integration/sillytavern-bridge.js';
import { button, element, type ModalField } from './dom.js';
import { beginPhoneTask } from './phone-task.js';
import { renderPhoneIcon, type PhoneIconName } from './phone-icon.js';
import { numberField, selectField } from './settings-panel.js';

/** 图标编辑列表中的一个应用条目（含首页上的「设置」「个性化」入口）。 */
export interface PersonalizeAppEntry {
  readonly id: string;
  readonly label: string;
  readonly icon: PhoneIconName;
  readonly canDisable?: boolean;
}

export interface PersonalizePanelContext {
  readonly settings: PhoneExtensionSettings;
  readonly apps: readonly PersonalizeAppEntry[];
  readonly disabledAppIds: readonly string[];
  readonly onChange: (patch: PhoneSettingsPatch) => void | Promise<void>;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
  readonly showModal: (title: string, fields: readonly ModalField[]) => Promise<Record<string, string> | null>;
}

function reportPersonalizationSaveError(error: unknown): void {
  beginPhoneTask('personalizeSave').fail(error);
}

/** 个性化应用：桌面布局、窗口尺寸、字号字体、主题配色、壁纸与自定义应用图标。 */
export function renderPersonalizePanel(context: PersonalizePanelContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-settings phone-personalize' });
  page.append(
    section('外观', '个性化', renderAppearanceCard(context)),
    section('主题配色', '个性化', renderThemeColorsCard(context)),
    section('手机壁纸', '个性化', renderWallpaperCard(context)),
    section('应用管理', '个性化', renderAppIconsCard(context)),
  );
  return page;
}

function section(title: string, kicker: string, content: HTMLElement): HTMLElement {
  const box = element('section', { className: 'phone-settings-section' });
  const heading = element('div', { className: 'phone-settings-heading' });
  heading.append(
    element('span', { className: 'phone-kicker', text: kicker }),
    element('h2', { className: 'phone-settings-title', text: title }),
  );
  box.append(heading, content);
  return box;
}

function patchPersonalization(
  context: PersonalizePanelContext,
  partial: Partial<PhoneExtensionSettings['personalization']>,
): void | Promise<void> {
  return context.onChange({ personalization: partial });
}

function renderAppearanceCard(context: PersonalizePanelContext): HTMLElement {
  const card = element('div', { className: 'phone-settings-card' });
  const config = context.settings.personalization;
  const patch = (partial: Partial<PhoneExtensionSettings['personalization']>) => patchPersonalization(context, partial);

  card.append(
    element('h3', { className: 'phone-subsection-title', text: '桌面布局' }),
    selectField(
      '首页应用每行数量',
      [['3', '3 个'], ['4', '4 个（默认）'], ['5', '5 个'], ['6', '6 个']],
      String(config.appColumns),
      (value) => patch({ appColumns: Number(value) }),
    ),
    element('h3', { className: 'phone-subsection-title', text: '手机尺寸' }),
    element('p', { className: 'phone-settings-hint', text: '填 0 使用默认尺寸；移动端全屏布局下不生效。' }),
    numberField('窗口宽度（px，0 = 默认）', config.shellWidth, 0, 900, 10, (value) => patch({ shellWidth: value })),
    numberField('窗口高度（px，0 = 默认）', config.shellHeight, 0, 1_200, 10, (value) => patch({ shellHeight: value })),
    element('h3', { className: 'phone-subsection-title', text: '字体与字号' }),
    numberField('字号缩放（%）', config.fontScale, 80, 140, 5, (value) => patch({ fontScale: value })),
    selectField(
      '字体选择',
      [
        ['', '系统默认'],
        ["'Microsoft YaHei', 'PingFang SC', sans-serif", '黑体系（雅黑/苹方）'],
        ["'SimSun', 'Songti SC', serif", '宋体系'],
        ["'KaiTi', 'Kaiti SC', serif", '楷体系'],
        ["'SimHei', sans-serif", '黑体'],
        ["Consolas, 'Courier New', monospace", '等宽字体'],
      ],
      config.fontFamily,
      (value) => patch({ fontFamily: value }),
    ),
  );
  return card;
}

