  dark: {
    accent: '#64a9ff',
    accentDark: '#8fc2ff',
    canvas: '#0d1118',
    surface: '#181d26',
    textPrimary: '#f4f7fb',
    textSecondary: '#b9c2d0',
  },
  glass: {
    accent: '#8ce7ff',
    accentDark: '#c5f5ff',
    canvas: '#101a2d',
    surface: '#b9d8ef',
    textPrimary: '#f5fbff',
    textSecondary: '#c3d7e8',
  },
