/** 主题配色：按当前主题分别定制主/副色等槽位，支持内置配色与保存个人预设。 */
function renderThemeColorsCard(context: PersonalizePanelContext): HTMLElement {
  const card = element('div', { className: 'phone-settings-card' });
  const config = context.settings.personalization;
  const theme = context.settings.uiTheme;
  const colors = theme === 'dark'
    ? config.themeColorsDark
    : theme === 'glass'
      ? config.themeColorsGlass
      : config.themeColorsLight;
  const defaults = THEME_DEFAULT_COLORS[theme];
  const patchColors = (partial: Partial<ThemeColorOverrides>) => patchPersonalization(
    context,
    theme === 'dark'
      ? { themeColorsDark: { ...colors, ...partial } }
      : theme === 'glass'
        ? { themeColorsGlass: { ...colors, ...partial } }
        : { themeColorsLight: { ...colors, ...partial } },
  );

  card.append(
    element('h3', { className: 'phone-subsection-title', text: '一键套用主题' }),
    element('p', { className: 'phone-settings-hint', text: '选择手机界面的显示模式；切换后会自动套用该模式对应的配色。' }),
    renderThemeModeChips(context),
    element('p', {
      className: 'phone-settings-hint',
      text: `正在编辑「${themeLabel(theme)}」主题的配色。`
        + '修改立即生效；「跟随主题」表示使用默认配色。',
    }),
  );

  for (const slot of THEME_COLOR_SLOTS) {
    card.append(colorField(
      slot.label,
      slot.hint,
      colors[slot.key],
      defaults[slot.key],
      (value) => patchColors({ [slot.key]: value } as Partial<ThemeColorOverrides>),
    ));
  }

  const customizedCount = Object.values(colors).filter(Boolean).length;
  const actions = element('div', { className: 'phone-settings-inline-actions' });
  if (customizedCount > 0) {
    actions.append(button('恢复本主题默认配色', 'phone-button phone-button-secondary', async () => {
      await patchColors({ ...EMPTY_THEME_COLORS });
      context.showNotice(`已恢复${themeLabel(theme)}主题默认配色。`, 'info');
    }));
    card.append(actions);
  }

  card.append(
    element('h3', { className: 'phone-subsection-title', text: '内置配色' }),
    element('p', { className: 'phone-settings-hint', text: '一键套用（同时应用到白天、黑夜与玻璃主题）。' }),
    renderBuiltinPresetChips(context),
    element('h3', { className: 'phone-subsection-title', text: '我的主题' }),
    renderThemePresetManager(context),
  );
  return card;
}

function themeLabel(theme: PhoneTheme): string {
  return theme === 'dark' ? '黑夜' : theme === 'glass' ? '玻璃' : '白天';
}

function renderThemeModeChips(context: PersonalizePanelContext): HTMLElement {
  const chips = element('div', { className: 'phone-theme-preset-chips phone-theme-mode-chips' });
  const options: readonly { readonly value: PhoneTheme; readonly label: string; readonly icon: PhoneIconName }[] = [
    { value: 'light', label: '白天主题', icon: 'sun' },
    { value: 'dark', label: '黑夜主题', icon: 'moon' },
    { value: 'glass', label: '玻璃主题', icon: 'palette' },
  ];
  for (const option of options) {
    const active = context.settings.uiTheme === option.value;
    const chip = button(
      option.label,
      `phone-theme-chip phone-theme-mode-chip${active ? ' is-active' : ''}`,
      async () => {
        if (active) return;
        await Promise.resolve(context.onChange({ uiTheme: option.value }));
        context.showNotice(`已切换到${option.label}。`, 'success');
      },
    );
    chip.prepend(renderPhoneIcon(option.icon, 'phone-theme-mode-icon'));
    chip.setAttribute('aria-pressed', String(active));
    chips.append(chip);
  }
  return chips;
}

function renderBuiltinPresetChips(context: PersonalizePanelContext): HTMLElement {
  const chips = element('div', { className: 'phone-theme-preset-chips' });
  const reset = button('默认', 'phone-theme-chip', async () => {
    await patchPersonalization(context, {
      themeColorsLight: { ...EMPTY_THEME_COLORS },
      themeColorsDark: { ...EMPTY_THEME_COLORS },
      themeColorsGlass: { ...EMPTY_THEME_COLORS },
    });
    context.showNotice('已恢复默认配色。', 'info');
  });
  reset.prepend(themeChipDot('#1473e6', '#64a9ff'));
  chips.append(reset);
  for (const preset of BUILTIN_THEME_PRESETS) {
    const chip = button(preset.name, 'phone-theme-chip', async () => {
      await patchPersonalization(context, {
        themeColorsLight: { ...preset.light },
        themeColorsDark: { ...preset.dark },
        themeColorsGlass: { ...(preset.glass ?? EMPTY_THEME_COLORS) },
      });
      context.showNotice(`已套用「${preset.name}」配色。`, 'success');
    });
    chip.prepend(themeChipDot(preset.light.accent, preset.dark.accent, preset.glass?.accent));
    chips.append(chip);
  }
  return chips;
}

/** 三色圆点：左半白天主色、中间黑夜主色、右半玻璃主色。 */
function themeChipDot(lightColor: string, darkColor: string, glassColor = ''): HTMLElement {
  const dot = element('span', { className: 'phone-theme-chip-dot' });
  dot.style.background = glassColor
    ? `linear-gradient(90deg, ${lightColor || '#1473e6'} 33%, ${darkColor || '#64a9ff'} 33% 66%, ${glassColor} 66%)`
    : `linear-gradient(90deg, ${lightColor || '#1473e6'} 50%, ${darkColor || '#64a9ff'} 50%)`;
  return dot;
}

/** 个人主题预设：保存当前白天、黑夜与玻璃配色为命名预设，可套用或删除。 */
function renderThemePresetManager(context: PersonalizePanelContext): HTMLElement {
  const box = element('div', { className: 'phone-setting-control phone-setting-control-stack' });
  const config = context.settings.personalization;
  const presets = config.themePresets;

  const row = element('div', { className: 'phone-inline-group' });
  const select = element('select', { className: 'phone-select phone-preset-select' });
  select.append(element('option', {
    text: presets.length > 0 ? '— 选择主题以套用 —' : '（还没有保存的主题）',
    attributes: { value: '' },
  }));
  for (const preset of presets) {
    select.append(element('option', { text: preset.name, attributes: { value: preset.name } }));
  }
  select.addEventListener('change', () => {
    const preset = presets.find((item) => item.name === select.value);
    if (!preset) return;
    void Promise.resolve()
      .then(() => patchPersonalization(context, {
        themeColorsLight: { ...preset.light },
        themeColorsDark: { ...preset.dark },
        themeColorsGlass: { ...(preset.glass ?? EMPTY_THEME_COLORS) },
      }))
      .then(() => context.showNotice(`已套用主题「${preset.name}」。`, 'success'))
      .catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });

  const save = button('保存当前', 'phone-button phone-button-secondary phone-button-compact', async () => {
    const values = await context.showModal('保存主题预设', [
      { name: 'name', label: '主题名称', required: true, placeholder: '例如：奶油紫' },
    ]);
    const name = values?.name?.trim().slice(0, 30);
    if (!name) return;
    const others = config.themePresets.filter((item) => item.name !== name);
    await patchPersonalization(context, {
      themePresets: [
        ...others,
        {
          name,
          light: { ...config.themeColorsLight },
          dark: { ...config.themeColorsDark },
          glass: { ...config.themeColorsGlass },
        },
      ],
    });
    context.showNotice(`主题「${name}」已保存。`, 'success');
  });
  const remove = button('删除所选', 'phone-button phone-button-danger phone-button-compact', async () => {
    const name = select.value;
    if (!name) {
      context.showNotice('请先在下拉框中选择要删除的主题。', 'info');
      return;
    }
    await patchPersonalization(context, {
      themePresets: config.themePresets.filter((item) => item.name !== name),
    });
    context.showNotice(`主题「${name}」已删除。`, 'info');
  });
  row.append(select, save, remove);
  box.append(row, element('small', {
    className: 'phone-settings-hint',
    text: '「保存当前」会把白天、黑夜与玻璃三套配色一起存成主题；最多保存 12 个。',
  }));
  return box;
}

/** 颜色槽位行：取色器 + 状态说明 + 恢复默认。 */
function colorField(
  label: string,
  hint: string,
  value: string,
  fallback: string,
  onChange: (value: string) => void | Promise<void>,
): HTMLElement {
  const row = element('div', { className: 'phone-setting-control phone-color-control' });
  const copy = element('span', { className: 'phone-color-copy' });
  copy.append(
    element('span', { className: 'phone-control-label', text: label }),
    element('small', { className: 'phone-color-hint', text: hint }),
  );
  const group = element('span', { className: 'phone-color-group' });
  const input = element('input', { className: 'phone-color-input', attributes: { type: 'color' } });
  input.value = value || fallback;
  input.addEventListener('change', () => {
    void Promise.resolve()
      .then(() => onChange(input.value))
      .catch(reportPersonalizationSaveError);
  });
  group.append(input, element('small', { className: 'phone-color-status', text: value ? value : '跟随主题' }));
  if (value) {
    group.append(button('默认', 'phone-button phone-button-secondary phone-button-compact', () => {
      void Promise.resolve()
        .then(() => onChange(''))
        .catch(reportPersonalizationSaveError);
    }));
  }
  row.append(copy, group);
  return row;
}

function renderWallpaperCard(context: PersonalizePanelContext): HTMLElement {
  const card = element('div', { className: 'phone-settings-card' });
  const config = context.settings.personalization;
  const patch = (partial: Partial<PhoneExtensionSettings['personalization']>) => patchPersonalization(context, partial);

  card.append(element('p', { className: 'phone-settings-hint', text: '壁纸显示在手机首页背景上，图片会压缩后保存到扩展设置中。' }));
  if (config.wallpaper) {
    card.append(element('img', {
      className: 'phone-wallpaper-preview',
      attributes: { alt: '当前壁纸预览', src: config.wallpaper },
    }));
  }

  const actions = element('div', { className: 'phone-settings-inline-actions' });
  const upload = button(config.wallpaper ? '更换壁纸' : '上传壁纸', 'phone-button phone-button-primary', async () => {
    upload.disabled = true;
    try {
      const dataUrl = await pickImageAsDataUrl(1_000);
      if (dataUrl) {
        await patch({ wallpaper: dataUrl });
        context.showNotice('壁纸已更新。', 'success');
      }
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      upload.disabled = false;
    }
  });
  actions.append(upload);
  if (config.wallpaper) {
    actions.append(button('清除壁纸', 'phone-button phone-button-secondary', () => {
      void patch({ wallpaper: '' });
      context.showNotice('已恢复默认背景。', 'info');
    }));
  }
  card.append(actions);
  return card;
}

/** 应用图标：每个应用一行，支持上传自定义图标与恢复默认。 */
function renderAppIconsCard(context: PersonalizePanelContext): HTMLElement {
  const card = element('div', { className: 'phone-settings-card' });
  const appLabels = context.settings.personalization.appLabels;
  const appIcons = context.settings.personalization.appIcons;
  card.append(element('p', {
    className: 'phone-settings-hint',
    text: '编辑应用可一次保存名称和启停状态；图标支持上传、替换或恢复默认。设置保存后首页会立即刷新。',
  }));

  const list = element('div', { className: 'phone-icon-edit-list' });
  for (const app of context.apps) {
    list.append(renderAppIconRow(
      context,
      app,
      appLabels[app.id] ?? app.label,
      appIcons,
      context.disabledAppIds.includes(app.id),
    ));
  }
  card.append(list);

  if (Object.keys(appIcons).length > 0) {
    const actions = element('div', { className: 'phone-settings-inline-actions' });
    actions.append(button('全部恢复默认图标', 'phone-button phone-button-secondary', async () => {
      await patchPersonalization(context, { appIcons: {} });
      context.showNotice('已恢复全部默认图标。', 'info');
    }));
    card.append(actions);
  }
  return card;
}

function renderAppIconRow(
  context: PersonalizePanelContext,
  app: PersonalizeAppEntry,
  label: string,
  appIcons: Readonly<Record<string, string>>,
  disabled: boolean,
): HTMLElement {
  const custom = appIcons[app.id] ?? '';
  const row = element('div', { className: `phone-icon-edit-row phone-app-tile-${app.id}${disabled ? ' is-disabled' : ''}` });
  const iconBox = element('span', { className: `phone-app-icon-box phone-icon-edit-preview${custom ? ' has-custom-icon' : ''}` });
  if (custom) {
    iconBox.append(element('img', {
      className: 'phone-app-icon-img',
      attributes: { alt: `${label}自定义图标`, src: custom },
    }));
  } else {
    iconBox.append(renderPhoneIcon(app.icon, 'phone-app-icon-svg'));
  }

  const copy = element('span', { className: 'phone-icon-edit-copy' });
  const states = [
    disabled ? '已停用' : '已启用',
    label === app.label ? '默认名称' : '自定义名称',
    custom ? '自定义图标' : '默认图标',
  ];
  copy.append(
    element('strong', { text: label }),
    element('small', { text: states.join(' · ') }),
  );

  const actions = element('span', { className: 'phone-icon-edit-actions' });
  actions.append(button('编辑', 'phone-button phone-button-primary phone-button-compact', async () => {
    const fields: ModalField[] = [
      { name: 'name', label: '应用名称', value: label, required: true, placeholder: app.label },
      ...(app.canDisable === false ? [] : [{
        name: 'status',
        label: '应用状态',
        type: 'select' as const,
        value: disabled ? 'disabled' : 'enabled',
        options: [['enabled', '启用'], ['disabled', '停用']] as const,
      }]),
      {
        name: 'iconAction',
        label: '应用图标',
        type: 'select',
        value: 'keep',
        options: [
          ['keep', custom ? '保留当前图标' : '使用默认图标'],
          ['upload', custom ? '上传并替换图标' : '上传自定义图标'],
          ['default', '恢复默认图标'],
        ],
      },
      {
        name: 'iconUpload',
        label: '当前图标',
        type: 'image',
        value: custom,
        visibleWhen: (values) => values.iconAction === 'upload',
        imagePreview: {
          alt: `${label}图标预览`,
          hint: custom ? '点击图标替换自定义图标' : '点击图标上传自定义图标',
          renderFallback: () => renderPhoneIcon(app.icon, 'phone-modal-default-icon'),
          onPick: () => pickImageAsDataUrl(256),
        },
      },
    ];
    const values = await context.showModal(`编辑「${label}」`, fields);
    if (!values) return;
    const nextLabel = values.name?.trim().slice(0, 40);
    if (!nextLabel) {
      context.showNotice('应用名称不能为空。', 'error');
      return;
    }

    const nextLabels = { ...context.settings.personalization.appLabels };
    if (nextLabel === app.label) delete nextLabels[app.id];
    else nextLabels[app.id] = nextLabel;
    const nextDisabled = app.canDisable === false
      ? context.disabledAppIds
      : values.status === 'disabled'
        ? [...new Set([...context.disabledAppIds, app.id])]
        : context.disabledAppIds.filter((id) => id !== app.id);
    const nextIcons = { ...appIcons };
    if (values.iconAction === 'default') delete nextIcons[app.id];
    if (values.iconAction === 'upload') {
      if (!values.iconUpload) {
        context.showNotice('请点击当前图标上传自定义图标。', 'error');
        return;
      }
      nextIcons[app.id] = values.iconUpload;
    }

    await patchPersonalization(context, {
      appLabels: nextLabels,
      appIcons: nextIcons,
      disabledAppIds: nextDisabled,
    });
    context.showNotice(`「${nextLabel}」设置已保存。`, 'success');
  }));

  row.append(iconBox, copy, actions);
  return row;
}
