/**
 * 「MVU 转换数据」面板。
 *
 * 流程是三段式：扫描（只读）→ 选项 → 二次确认后执行。
 * 写宿主角色库与世界书是不可逆动作，因此执行按钮必须点两次，第二次才真的写。
 */

import type { MvuBridgeStatus } from '../integration/mvu-data-bridge.js';
import {
  DEFAULT_MVU_CONVERT_OPTIONS,
  describeConversion,
  type MvuConvertOptions,
  type MvuConvertReport,
  type MvuScanReport,
} from '../mvu/convert.js';
import type { MvuBridgeSettings } from '../integration/sillytavern-bridge.js';
import { button, element } from './dom.js';

export interface MvuPanelActions {
  readonly scan: () => Promise<MvuScanReport>;
  readonly convert: (options: MvuConvertOptions) => Promise<MvuConvertReport>;
  readonly bridgeStatus: () => MvuBridgeStatus;
  readonly project: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 当前聊天与角色卡的标识：变化后面板丢弃上一张卡的扫描与转换结果。 */
  readonly scopeKey: () => string;
}

export interface MvuPanelContext {
  readonly bridge: MvuBridgeSettings;
  readonly activePresetName: string;
  readonly mvu: MvuPanelActions;
  readonly onBridgeChange: (patch: Partial<MvuBridgeSettings>) => void | Promise<void>;
  /** 重绘本页（扫描、转换完成后刷新视图）。 */
  readonly refresh: () => void;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

const ASSET_LABELS: Readonly<Record<string, string>> = Object.freeze({
  schema: '变量结构脚本',
  initVar: '初始变量',
  updateRules: '更新规则',
  outputFormat: '输出格式',
  variableList: '变量列表',
});

const SHAPE_LABELS: Readonly<Record<string, string>> = Object.freeze({
  wide: '单行宽表',
  entity: '多行实体表',
  keyValue: '键值表',
  global: '全局标记表',
});

/** 面板内的一次性状态：扫描结果与勾选项不写进设置，离开页面或换聊天即重置。 */
let report: MvuScanReport | null = null;
let options: MvuConvertOptions = DEFAULT_MVU_CONVERT_OPTIONS;
let lastReport: MvuConvertReport | null = null;
let confirming = false;
let busy = false;
/** 上次渲染所属的聊天与角色卡；换卡换聊天后旧结果必须作废。 */
let renderedScopeKey = '';

function toggleRow(
  label: string,
  hint: string,
  checked: boolean,
  onChange: (next: boolean) => void,
): HTMLElement {
  const row = element('label', { className: 'phone-setting-control phone-setting-toggle' });
  const input = element('input', { attributes: { type: 'checkbox' } });
  input.checked = checked;
  input.addEventListener('change', () => onChange(input.checked));
  const copy = element('span', { className: 'phone-setting-copy' });
  copy.append(element('span', { className: 'phone-control-label', text: label }));
  if (hint) copy.append(element('small', { className: 'phone-settings-hint', text: hint }));
  row.append(input, copy);
  return row;
}

function statusLine(label: string, value: string): HTMLElement {
  const row = element('div', { className: 'phone-db-record-card' });
  row.append(element('span', { text: label }), element('strong', { text: value }));
  return row;
}

function renderScanSection(context: MvuPanelContext): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  section.append(element('h3', { className: 'phone-subsection-title', text: '扫描结果' }));

  const scan = button(report ? '重新扫描' : '扫描当前角色卡', 'phone-button phone-button-secondary', async () => {
    scan.disabled = true;
    try {
      report = await context.mvu.scan();
      confirming = false;
      lastReport = null;
      context.refresh();
    } catch (error) {
      context.showNotice(`扫描失败：${error instanceof Error ? error.message : String(error)}`, 'error');
    } finally {
      scan.disabled = false;
    }
  });

  if (!report) {
    section.append(
      element('p', {
        className: 'phone-settings-hint',
        text: '扫描当前角色卡与它绑定的世界书，找出 MVU 的初始变量、更新规则与输出格式条目。只读操作，不会改动任何内容。',
      }),
      scan,
    );
    return section;
  }

  section.append(element('p', {
    className: 'phone-settings-hint',
    text: `角色卡：${report.cardName || '（未命名）'}｜世界书：${report.books.length > 0 ? report.books.join('、') : '（未绑定）'}`,
  }));

  if (report.assets.length === 0) {
    section.append(element('p', {
      className: 'phone-settings-hint',
      text: '没有识别到 MVU 变量资产。如果这张卡确实用 MVU，请确认初始变量条目在绑定的世界书里（条目关闭也能识别）。',
    }));
  } else {
    const list = element('div', { className: 'phone-db-cards' });
    for (const asset of report.assets) {
      list.append(statusLine(
        `${ASSET_LABELS[asset.kind] ?? asset.kind}｜${asset.name}`,
        `${asset.chars} 字${asset.enabled ? '' : '（已关闭）'}${asset.detectedBy === 'shape' ? '（按正文形状识别）' : ''}`,
      ));
    }
    section.append(list);
  }

  if (report.error) {
    section.append(element('p', { className: 'phone-settings-hint', text: `无法生成表结构：${report.error}` }));
  }

  const outcome = report.outcome;
  if (outcome) {
    section.append(
      element('p', { className: 'phone-settings-hint', text: `转换预览：${describeConversion(outcome)}` }),
    );
    if (outcome.usedAssets.length > 0) {
      section.append(element('p', {
        className: 'phone-settings-hint',
        text: `建表依据：${outcome.usedAssets.join(' + ')}`,
      }));
    }
    const preview = element('div', { className: 'phone-db-cards' });
    for (const sheet of outcome.preview) {
      preview.append(statusLine(
        `${sheet.name}（${SHAPE_LABELS[sheet.shape] ?? sheet.shape}）`,
        `${sheet.columns} 列 / ${sheet.rows} 行${sheet.hasGuide ? ' · 带填表规则' : ''}`,
      ));
    }
    section.append(preview);
  }

  if (report.issues.length > 0) {
    const issues = element('div', { className: 'phone-db-cards' });
    for (const issue of report.issues) {
      issues.append(element('p', { className: 'phone-settings-hint', text: `· ${issue}` }));
    }
    section.append(element('h3', { className: 'phone-subsection-title', text: '降级说明' }), issues);
  }

  section.append(scan);
  return section;
}

function renderOptionsSection(context: MvuPanelContext): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  const outcome = report?.outcome ?? null;
  section.append(element('h3', { className: 'phone-subsection-title', text: '转换选项' }));

  const update = (patch: Partial<MvuConvertOptions>): void => {
    options = { ...options, ...patch };
    confirming = false;
    context.refresh();
  };

  section.append(
    toggleRow(
      '合并进当前预设',
      `不勾选就新建独立预设包「<卡名>（墨韵数据）」；勾选则并入当前预设「${context.activePresetName || '未选择'}」`
        + '（内置默认表格会先复制成库里的一份新预设，不会被改动）。',
      options.mergeIntoActive,
      (mergeIntoActive) => update({ mergeIntoActive }),
    ),
    toggleRow(
      '写出（墨韵数据）角色卡与世界书',
      '新建一张卡与一本世界书，名字统一加「（墨韵数据）」后缀；重名自动加序号。原卡与原世界书全程只读。',
      options.writeCard,
      (writeCard) => update({ writeCard }),
    ),
    toggleRow(
      '开启数据桥接管',
      '前端状态栏、EJS 与旧脚本的 MVU 读写改走数据中心：表内容投影回 stat_data，_.set 之类的写入翻译成表格写入。',
      options.enableBridge,
      (enableBridge) => update({ enableBridge }),
    ),
    toggleRow(
      '允许正文模型直接输出 SQL',
      '新卡的填表协议会要求模型在回复末尾输出 ```sql（支持 IF <条件> THEN <SQL>），由扩展直接执行，省掉填表模型的额外调用。',
      options.allowStorySql,
      (allowStorySql) => update({ allowStorySql }),
    ),
  );

  const actions = element('div', { className: 'phone-settings-actions' });
  const run = button(
    confirming ? '确认转换（会新建卡与世界书）' : '开始转换',
    confirming ? 'phone-button phone-button-danger' : 'phone-button phone-button-primary',
    async () => {
      if (!outcome) {
        context.showNotice('请先扫描出可用的 MVU 变量。', 'info');
        return;
      }
      if (!confirming) {
        confirming = true;
        context.refresh();
        return;
      }
      busy = true;
      run.disabled = true;
      try {
        lastReport = await context.mvu.convert(options);
        confirming = false;
        context.showNotice(lastReport.message, lastReport.ok ? 'success' : 'error');
        context.refresh();
      } finally {
        busy = false;
        run.disabled = false;
      }
    },
  );
  run.disabled = !outcome || busy;
  actions.append(run);
  if (confirming) {
    actions.append(button('取消', 'phone-button phone-button-secondary', () => {
      confirming = false;
      context.refresh();
    }));
  }
  section.append(actions);

  if (confirming) {
    section.append(element('p', {
      className: 'phone-settings-hint',
      text: options.writeCard
        ? '再点一次就会：建表并写入初始数据、把预设设为当前使用、新建带（墨韵数据）后缀的角色卡与世界书。原卡不会被修改。'
        : '再点一次就会：建表并写入初始数据、把预设设为当前使用。不会新建角色卡与世界书。',
    }));
  }
  return section;
}

function renderReportSection(): HTMLElement | null {
  if (!lastReport) return null;
  const section = element('section', { className: 'phone-database-status' });
  section.append(
    element('h3', { className: 'phone-subsection-title', text: '转换报告' }),
    statusLine('预设包', `${lastReport.presetName}（${lastReport.sheets} 张表）`),
    statusLine('本聊天新建', `${lastReport.createdSheets} 张表 / ${lastReport.insertedRows} 行`),
    statusLine('入表变量', `${lastReport.mappedPaths} 个`),
    statusLine('新角色卡', lastReport.cardName || '（未写出）'),
    statusLine('新世界书', lastReport.bookNames.length > 0 ? lastReport.bookNames.join('、') : '（未写出）'),
  );
  if (lastReport.issues.length > 0) {
    for (const issue of lastReport.issues) {
      section.append(element('p', { className: 'phone-settings-hint', text: `· ${issue}` }));
    }
  }
  return section;
}

function renderBridgeSection(context: MvuPanelContext): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  const status = context.mvu.bridgeStatus();
  const updateBridge = (patch: Partial<MvuBridgeSettings>): void => {
    void Promise.resolve().then(() => context.onBridgeChange(patch)).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
  };
  section.append(element('h3', { className: 'phone-subsection-title', text: '数据桥' }));

  const modeRow = element('label', { className: 'phone-db-field' });
  modeRow.append(element('span', { className: 'phone-control-label', text: '接管模式' }));
  const select = element('select', { className: 'phone-select' });
  for (const [value, label] of [
    ['auto', '自动（有变量映射就接管）'],
    ['takeover', '强制接管（即使装了 MVU 框架）'],
    ['off', '关闭（保持 MVU 原样）'],
  ] as const) {
    const option = element('option', { text: label, attributes: { value } });
    option.selected = context.bridge.mode === value;
    select.append(option);
  }
  select.addEventListener('change', () => {
    const next = select.value;
    updateBridge({ mode: next === 'takeover' || next === 'off' ? next : 'auto' });
  });
  modeRow.append(select);

  const project = button('立即投影一次', 'phone-button phone-button-secondary', async () => {
    project.disabled = true;
    try {
      const outcome = await context.mvu.project();
      context.showNotice(outcome.message, outcome.ok ? 'success' : 'error');
      context.refresh();
    } finally {
      project.disabled = false;
    }
  });
  project.disabled = context.bridge.mode === 'off';
  const actions = element('div', { className: 'phone-settings-actions' });
  if (status.installed) {
    const cancel = button('取消接管', 'phone-button phone-button-secondary', async () => {
      cancel.disabled = true;
      project.disabled = true;
      try {
        await context.onBridgeChange({ mode: 'off' });
        context.showNotice('已取消数据桥接管。', 'success');
        context.refresh();
      } finally {
        cancel.disabled = false;
        project.disabled = !context.mvu.bridgeStatus().installed;
      }
    });
    actions.append(cancel);
  }
  actions.append(project);

  section.append(
    modeRow,
    toggleRow(
      '投影回楼层变量',
      '把表内容写回最新楼层的 stat_data，前端状态栏与 EJS 模板不用改代码就能读到数据中心的数据。',
      context.bridge.projectToVariables,
      (projectToVariables) => updateBridge({ projectToVariables }),
    ),
    toggleRow(
      '执行正文里的 SQL 代码块',
      '正文模型按填表协议输出 ```sql 时直接执行（支持 IF 语法），不需要再调用填表模型。',
      context.bridge.acceptStoryTableSql,
      (acceptStoryTableSql) => updateBridge({ acceptStoryTableSql }),
    ),
    statusLine('门面状态', status.installed ? '已接管 window.Mvu' : '未接管'),
    statusLine('已投影变量', `${status.mappedPaths} 个${status.missingPaths > 0 ? `（${status.missingPaths} 个在表里读不到）` : ''}`),
    statusLine('上次投影', status.lastProjectedAt ? new Date(status.lastProjectedAt).toLocaleString('zh-CN') : '尚未投影'),
    actions,
  );
  if (status.replacedForeignMvu) {
    section.append(element('p', {
      className: 'phone-settings-hint',
      text: '检测到已安装的 MVU 变量框架，已被接管；关闭接管模式后会自动还原。',
    }));
  }
  if (status.lastSkipped.length > 0) {
    section.append(element('h3', { className: 'phone-subsection-title', text: '未翻译的写入' }));
    for (const item of status.lastSkipped.slice(0, 8)) {
      section.append(element('p', { className: 'phone-settings-hint', text: `· ${item.path}：${item.reason}` }));
    }
  }
  section.append(element('p', {
    className: 'phone-settings-hint',
    text: '表内容只在填表模型跑过（或正文 SQL 执行）之后才变，投影随之更新；'
      + '接管后建议把数据中心的「每多少条 AI 回复记录一次」设为 1，否则状态栏会比正文慢一轮。'
      + '另外：在数据中心里重命名转换出来的表会断开变量映射，重命名后请重新转换一次。',
  }));
  return section;
}

export function renderMvuConvertPanel(context: MvuPanelContext): HTMLElement {
  // 换聊天或换角色卡后，上一张卡的扫描结果与转换报告不能继续显示。
  const scopeKey = context.mvu.scopeKey();
  if (scopeKey !== renderedScopeKey) {
    resetMvuConvertPanel();
    renderedScopeKey = scopeKey;
  }
  const page = element('div', { className: 'phone-settings-card' });
  page.append(renderScanSection(context), renderOptionsSection(context));
  const reportSection = renderReportSection();
  if (reportSection) page.append(reportSection);
  page.append(renderBridgeSection(context));
  return page;
}

/** 离开设置页时清掉一次性状态，下次进来重新扫描。 */
export function resetMvuConvertPanel(): void {
  report = null;
  options = DEFAULT_MVU_CONVERT_OPTIONS;
  lastReport = null;
  confirming = false;
  busy = false;
}
