import { listMvuLeafPaths } from './init-var.js';
import { splitMvuPath } from './mapping.js';
import type { MvuMapping, MvuTree } from './types.js';

/** JSON 单元格覆盖其子路径，动态模板覆盖当前成员及未来成员。分母始终来自源结构。 */
export function mvuMappingCoverage(tree: MvuTree, mapping: MvuMapping): { declared: number; covered: number; missing: readonly string[] } {
  const paths = [...new Set(listMvuLeafPaths(tree))];
  const missing = paths.filter((path) => {
    const source = splitMvuPath(path);
    return !mapping.entries.some((entry) => {
      const target = entry.dynamic ? [...entry.dynamic.prefix, '*', ...entry.dynamic.field] : splitMvuPath(entry.path);
      return target.length <= source.length && (target.length === source.length || entry.valueType === 'json')
        && target.every((key, index) => key === '*' || key === source[index]);
    });
  });
  return { declared: paths.length, covered: paths.length - missing.length, missing };
}
