/**
 * 同人剧情引擎的领域模型。
 *
 * 分成两层且互不写入：
 * - 原著库（CanonLibrary）：稳定、可跨聊天复用，来自角色卡、世界书与导入资料。
 * - 剧情状态（FanficNarrativeState）：当前聊天里已经发生的 AU 事实，随楼层推进与回滚。
 *
 * 生成层只消费本文件定义的结构，不直接读取宿主字段。
 */

export const FANFIC_STATE_VERSION = 1;
export const CANON_LIBRARY_VERSION = 1;
/** 保留的楼层检查点数量：楼层被编辑、删除或滑动时用于回滚剧情状态。 */
export const FANFIC_CHECKPOINT_LIMIT = 16;

export type CanonSourceKind = 'card' | 'worldbook' | 'import';
export type CanonFactKind = 'trait' | 'value' | 'relationship' | 'event' | 'rule' | 'knowledge' | 'voice';
export type CanonConfidence = 'high' | 'medium' | 'low';

export interface CanonDocument {
  readonly id: string;
  readonly kind: CanonSourceKind;
  readonly name: string;
  readonly charCount: number;
  readonly updatedAt: number;
}

/** 原著资料分块：检索与引用的最小单位，保留来源以便用户追溯。 */
export interface CanonChunk {
  readonly id: string;
  readonly documentId: string;
  readonly index: number;
  readonly heading: string;
  readonly text: string;
}

export interface CanonFact {
  readonly id: string;
  readonly kind: CanonFactKind;
  readonly text: string;
  /** 涉及的稳定角色 ID；世界规则可为空。 */
  readonly characterIds: readonly string[];
  readonly chunkId: string;
  readonly documentId: string;
  readonly confidence: CanonConfidence;
}

/** 说话指纹：还原原著语感的最小约束集合。 */
export interface VoiceFingerprint {
  readonly register: string;
  readonly habits: readonly string[];
  readonly forbidden: readonly string[];
}

export interface CanonRelationship {
  readonly targetId: string;
  readonly targetName: string;
  readonly summary: string;
}

/** 人物锁：AU 剧情可以改命运，但这些约束保持原著一致。 */
export interface CharacterLock {
  readonly id: string;
  readonly name: string;
  readonly aliases: readonly string[];
  readonly core: readonly string[];
  readonly values: readonly string[];
  readonly knowledge: readonly string[];
  readonly voice: VoiceFingerprint;
  readonly relationships: readonly CanonRelationship[];
  readonly signatureLines: readonly string[];
  readonly sourceIds: readonly string[];
  /** 用户手工修正过：自动重建不覆盖该角色锁。 */
  readonly manual: boolean;
  readonly updatedAt: number;
}

export interface CanonLibrary {
  readonly version: number;
  /** 来源指纹：角色卡与导入资料未变化时可直接复用已建立的原著库。 */
  readonly fingerprint: string;
  readonly title: string;
  readonly documents: readonly CanonDocument[];
  readonly chunks: readonly CanonChunk[];
  readonly facts: readonly CanonFact[];
  readonly characters: readonly CharacterLock[];
  readonly worldRules: readonly string[];
  /** 已解析过的分块 ID：长篇原著可以分多次继续解析而不重复消耗 API。 */
  readonly analyzedChunkIds: readonly string[];
  readonly builtAt: number;
}

export interface FanficScene {
  readonly place: string;
  readonly time: string;
  readonly situation: string;
  readonly floor: number;
}

/** 进入本轮时仍然成立的人物状态。 */
export interface FanficPresence {
  readonly characterId: string;
  readonly name: string;
  readonly present: boolean;
  readonly posture: string;
  readonly holding: string;
  readonly mood: string;
}

export interface FanficRelationshipShift {
  readonly characterId: string;
  readonly targetId: string;
  readonly summary: string;
  readonly floor: number;
}

/** 秘密与知情名单：角色认知边界的事实源，避免全知发言。 */
export interface FanficSecret {
  readonly id: string;
  readonly text: string;
  readonly knownBy: readonly string[];
  readonly floor: number;
}

export interface FanficThread {
  readonly id: string;
  readonly kind: 'promise' | 'open';
  readonly text: string;
  readonly owners: readonly string[];
  readonly floor: number;
  readonly resolved: boolean;
}

/** 与原著明确不同的既定事实：AU 剧情优先，用于压制原著同位事件。 */
export interface FanficDivergence {
  readonly id: string;
  readonly canonText: string;
  readonly storyText: string;
  readonly floor: number;
}

/** 可整体快照与回滚的剧情事实集合。 */
export interface FanficNarrativeCore {
  readonly scene: FanficScene;
  readonly presence: readonly FanficPresence[];
  readonly relationshipShifts: readonly FanficRelationshipShift[];
  readonly secrets: readonly FanficSecret[];
  readonly threads: readonly FanficThread[];
  readonly divergences: readonly FanficDivergence[];
}

export interface FanficCheckpoint {
  readonly floor: number;
  readonly core: FanficNarrativeCore;
}

export interface FanficNarrativeState extends FanficNarrativeCore {
  readonly version: number;
  readonly lastFloor: number;
  readonly revision: number;
  readonly checkpoints: readonly FanficCheckpoint[];
}