import type { PhoneEvent } from '../domain/events.js';
import type { PhoneState } from '../domain/model.js';

export type StorageBackendKind = 'tavern' | 'indexeddb';
export type StorageListener = (state: PhoneState) => void;
export type UnsubscribeStorage = () => void;

export interface StorageBackend {
  readonly kind: StorageBackendKind;
  isAvailable(): Promise<boolean>;
  load(scopeId: string): Promise<PhoneState | null>;
  commit(scopeId: string, expectedRevision: number, events: readonly PhoneEvent[]): Promise<PhoneState>;
  replace(scopeId: string, state: PhoneState): Promise<void>;
  listScopes(): Promise<readonly string[]>;
  deleteScope(scopeId: string): Promise<void>;
  subscribe?(scopeId: string, listener: StorageListener): UnsubscribeStorage;
  /** 等待后端内部合并的写入落盘（实现了延迟写入的后端才需要提供）。 */
  flush?(): Promise<void>;
  dispose(): void;
}

export class StorageConflictError extends Error {
  constructor(
    readonly scopeId: string,
    readonly expectedRevision: number,
    readonly actualRevision: number,
  ) {
    super(
      `Storage revision conflict for ${scopeId}: expected ${expectedRevision}, actual ${actualRevision}`,
    );
    this.name = 'StorageConflictError';
  }
}

export interface StorageSelection {
  readonly backend: StorageBackend;
  readonly reason: 'database-available' | 'indexeddb-fallback' | 'user-selection';
}