/**
 * 按应用/功能清除手机数据。
 *
 * 这里只声明「有哪些可清除的数据桶」以及「清掉某个桶之后的状态长什么样」，
 * 全部是纯函数：不碰存储、不碰界面。落盘、清浏览器缓存与刷新界面由运行时负责。
 */

import { createEmptyFanficNarrative } from '../fanfic/narrative.js';
import type { AppId, PhoneState } from './model.js';

/** 状态之外的派生存储；由运行时按标记清理。 */
export type PhoneDataSideEffect = 'dataCenter' | 'images' | 'vectors';

export type PhoneDataBucketId =
  | 'wechat'
  | 'forum'
  | 'anonymous'
  | 'twitter'
  | 'profiles'
  | 'memory'
  | 'summaries'
  | 'diary'
  | 'calendar'
  | 'timeline'
  | 'dynamicWorldBook'
  | 'fanfic'
  | 'pxx'
  | 'queue'
  | 'dataCenter'
  | 'images'
  | 'vectors';

export interface PhoneDataBucket {
  readonly id: PhoneDataBucketId;
  readonly label: string;
  readonly hint: string;
  /** 当前条目数，供界面显示；外部存储桶无法同步统计时返回 -1。 */
  readonly countOf: (state: PhoneState) => number;
  /** 清除该桶后的状态；纯外部存储桶原样返回。 */
  readonly purge: (state: PhoneState) => PhoneState;
  readonly sideEffect?: PhoneDataSideEffect;
}

/** 统计数无法从状态得出的外部存储桶。 */
const UNKNOWN_COUNT = -1;

function withoutApp<T extends { readonly appId: AppId }>(
  entries: Readonly<Record<string, T>>,
  appId: AppId,
): Readonly<Record<string, T>> {
  return Object.fromEntries(Object.entries(entries).filter(([, entry]) => entry.appId !== appId));
}

function countApp(state: PhoneState, appId: AppId): number {
  const of = (entries: Readonly<Record<string, { readonly appId: AppId }>>): number =>
    Object.values(entries).filter((entry) => entry.appId === appId).length;
  return of(state.conversations) + of(state.messages) + of(state.posts);
}

/** 清掉某个应用的全部产物：会话、消息、动态、互动与待发队列一起走，顺序数组同步收缩。 */
function purgeApp(state: PhoneState, appId: AppId): PhoneState {
  const messages = withoutApp(state.messages, appId);
  const posts = withoutApp(state.posts, appId);
  return {
    ...state,
    conversations: withoutApp(state.conversations, appId),
    messages,
    messageOrder: state.messageOrder.filter((id) => id in messages),
    posts,
    postOrder: state.postOrder.filter((id) => id in posts),
    interactions: withoutApp(state.interactions, appId),
    outbox: withoutApp(state.outbox, appId),
    ...(appId === 'forum' ? { forumBoards: {} } : {}),
  };
}

function appBucket(id: AppId, label: string, hint: string): PhoneDataBucket {
  return {
    id,
    label,
    hint,
    countOf: (state) => countApp(state, id),
    purge: (state) => purgeApp(state, id),
  };
}

/** 可清除的数据桶。顺序即界面顺序：先按应用，再按功能，最后是浏览器侧缓存。 */
export const PHONE_DATA_BUCKETS: readonly PhoneDataBucket[] = Object.freeze([
  appBucket('wechat', '微信', '会话、聊天记录、朋友圈动态与相关待发队列'),
  appBucket('forum', '论坛', '板块、主题、回复与相关待发队列'),
  appBucket('twitter', '推特 / X', '推文、回复、转发、私信与相关待发队列'),
  appBucket('anonymous', '匿名交友', '匿名会话与聊天记录'),
  {
    id: 'profiles',
    label: '联系人资料',
    hint: '通讯录里的角色资料、头像、别名与生图参考（会话记录不受影响）',
    countOf: (state) => Object.keys(state.profiles).length,
    purge: (state) => ({ ...state, profiles: {} }),
  },
  {
    id: 'memory',
    label: '记忆库',
    hint: '记忆条目、合并总结与整理进度基线',
    countOf: (state) => state.memoryItems.length,
    purge: (state) => ({ ...state, memoryItems: [], memorySeq: 0, memoryLastFloor: -1 }),
  },
  {
    id: 'summaries',
    label: '手机内容总结',
    hint: '按手机记录生成的「手机#N」总结',
    countOf: (state) => state.summaries.length,
    purge: (state) => ({ ...state, summaries: [] }),
  },
  {
    id: 'diary',
    label: '日记本',
    hint: '日记条目与已覆盖的剧情时间基线',
    countOf: (state) => state.diaryEntries.length,
    purge: (state) => ({ ...state, diaryEntries: [], diaryCoveredUntil: 0 }),
  },
  {
    id: 'calendar',
    label: '日历',
    hint: '自定义节日与日期事件',
    countOf: (state) => Object.keys(state.calendarFestivals).length,
    purge: (state) => ({ ...state, calendarFestivals: {} }),
  },
  {
    id: 'timeline',
    label: '时间线',
    hint: '按楼层记录的剧情事件',
    countOf: (state) => state.timelineEvents.length,
    purge: (state) => ({ ...state, timelineEvents: [], timelineSeq: 0 }),
  },
  {
    id: 'dynamicWorldBook',
    label: '动态世界书状态',
    hint: '本聊天的动态条目与叠加层（角色卡原始世界书只读，不受影响）',
    countOf: (state) => state.dynamicWorldBook.entries.length,
    purge: (state) => ({
      ...state,
      dynamicWorldBook: { lastFloor: -1, entries: [], revision: state.dynamicWorldBook.revision + 1 },
    }),
  },
  {
    id: 'fanfic',
    label: '同人剧情状态',
    hint: '本聊天成立的 AU 事实与剧情跟踪进度',
    countOf: (state) => {
      const narrative = state.fanficNarrative;
      return narrative.presence.length
        + narrative.relationshipShifts.length
        + narrative.secrets.length
        + narrative.threads.length
        + narrative.divergences.length;
    },
    purge: (state) => ({ ...state, fanficNarrative: createEmptyFanficNarrative() }),
  },
  {
    id: 'pxx',
    label: '商城商品',
    hint: '拼夕夕生成的商品列表',
    countOf: (state) => state.pxxProducts.length,
    purge: (state) => ({ ...state, pxxProducts: [] }),
  },
  {
    id: 'queue',
    label: '待处理队列与生成批次',
    hint: '尚未发出的待处理项、生成批次记录与已应用动作指纹',
    countOf: (state) => Object.keys(state.outbox).length + Object.keys(state.batches).length,
    purge: (state) => ({ ...state, outbox: {}, batches: {}, appliedActionIds: [] }),
  },
  {
    id: 'dataCenter',
    label: '数据中心表格',
    hint: '本地 SQLite 里的表结构、行数据与跟随聊天的归档',
    countOf: () => UNKNOWN_COUNT,
    purge: (state) => state,
    sideEffect: 'dataCenter',
  },
  {
    id: 'images',
    label: '生成图片缓存',
    hint: '浏览器里缓存的生图结果（消息中的生图标记会需要重新生成）',
    countOf: () => UNKNOWN_COUNT,
    purge: (state) => state,
    sideEffect: 'images',
  },
  {
    id: 'vectors',
    label: '向量索引缓存',
    hint: '记忆向量缓存（清除后按需重新向量化）',
    countOf: () => UNKNOWN_COUNT,
    purge: (state) => state,
    sideEffect: 'vectors',
  },
]);

export interface PhoneDataBucketSummary {
  readonly id: PhoneDataBucketId;
  readonly label: string;
  readonly hint: string;
  /** -1 表示条目数只存在于浏览器侧存储，无法从手机状态统计。 */
  readonly count: number;
}

export function summarizePhoneData(state: PhoneState): readonly PhoneDataBucketSummary[] {
  return PHONE_DATA_BUCKETS.map((bucket) => ({
    id: bucket.id,
    label: bucket.label,
    hint: bucket.hint,
    count: bucket.countOf(state),
  }));
}

export interface PhoneDataPurgeResult {
  readonly state: PhoneState;
  /** 实际参与清除的桶（未识别的 id 会被忽略）。 */
  readonly buckets: readonly PhoneDataBucket[];
  /** 需要运行时额外清理的浏览器侧存储。 */
  readonly sideEffects: readonly PhoneDataSideEffect[];
  /** 状态里被清掉的条目总数；外部存储不计入。 */
  readonly removedCount: number;
}

/**
 * 依次套用被选中的桶。修订号加一，让存储层与界面把它当成一次正常提交。
 * 作用域、schema 版本与剧情时间永不参与清除：它们是这份数据的身份，不是内容。
 */
export function purgePhoneData(
  state: PhoneState,
  bucketIds: readonly string[],
): PhoneDataPurgeResult {
  const selected = PHONE_DATA_BUCKETS.filter((bucket) => bucketIds.includes(bucket.id));
  const removedCount = selected.reduce((sum, bucket) => {
    const count = bucket.countOf(state);
    return sum + (count > 0 ? count : 0);
  }, 0);
  const purged = selected.reduce((current, bucket) => bucket.purge(current), state);
  return {
    state: purged === state ? state : { ...purged, revision: state.revision + 1 },
    buckets: selected,
    sideEffects: [...new Set(selected.flatMap((bucket) => (bucket.sideEffect ? [bucket.sideEffect] : [])))],
    removedCount,
  };
}
