const ICON_ASSET_DIRECTORY = new URL('./图标/', import.meta.url);

/** 所有图标共用的基类：蒙版着色规则挂在它上面，具体尺寸仍由调用方传入的 className 决定。 */
const ICON_BASE_CLASS = 'phone-icon';

/**
 * 图标资源是透明底的白色单色 PNG。直接当 img 渲染时颜色被写死成白色，
 * 浅色主题下白图标压在白卡上就看不见，而且样式表里所有 `color` 规则都对图片无效。
 * 因此这里改成「图片当蒙版、由 `currentColor` 上色」的 span：
 * 图标颜色自动跟随所在容器的文字色，浅色/黑夜/玻璃三套主题与彩色图标底都不需要各写一遍。
 */
export function renderPhoneIcon(name: PhoneIconName, className = 'phone-svg-icon'): HTMLSpanElement {
  const icon = document.createElement('span');
  icon.className = className ? `${ICON_BASE_CLASS} ${className}` : ICON_BASE_CLASS;
  icon.style.setProperty('--phone-icon-src', `url("${new URL(ICON_ASSET_FILES[name], ICON_ASSET_DIRECTORY).href}")`);
  icon.setAttribute('aria-hidden', 'true');
  return icon;
}