/** 规则继续随 fillGuide 保存、归档和注入；编辑器把操作规则展开为独立字段。 */
export interface SheetRuleFields {
  readonly general: string;
  readonly initialize: string;
  readonly insert: string;
  readonly update: string;
  readonly delete: string;
}

export const SHEET_RULE_SECTIONS = [
  { key: 'initialize', label: '初始化规则', hint: '首次建表或开局时，哪些内容需要建立初始记录。' },
  { key: 'insert', label: '新增规则', hint: '什么情况下新增记录，以及需要填写哪些字段。' },
  { key: 'update', label: '更新规则', hint: '什么情况下修改记录，以及如何定位原有行。' },
  { key: 'delete', label: '删除规则', hint: '什么情况下移除记录，以及需要保留哪些历史信息。' },
] as const;

/** 同时识别编辑器的段落标题与旧 SQ 导入生成的“初始化规则：”格式。 */
export function parseSheetRuleFields(guide: string): SheetRuleFields {
  const text = guide.replace(/\r\n?/g, '\n');
  const headers = [...text.matchAll(/^(?:【(初始化规则|新增规则|更新规则|删除规则)】[ \t]*|((?:初始化|新增|更新|删除)规则)[ \t]*[：:][ \t]*)(.*)$/gm)];
  const result = { general: text.slice(0, headers[0]?.index ?? text.length).trim(), initialize: '', insert: '', update: '', delete: '' };
  for (const [index, header] of headers.entries()) {
    const section = SHEET_RULE_SECTIONS.find((item) => item.label === (header[1] ?? header[2]));
    if (!section) continue;
    const followingLines = text.slice(header.index! + header[0].length, headers[index + 1]?.index ?? text.length).replace(/^\n/, '');
    const content = [header[3], followingLines].filter(Boolean).join('\n').trim();
    result[section.key] = [result[section.key], content].filter(Boolean).join('\n\n');
  }
  return result;
}

export function composeSheetRuleFields(fields: SheetRuleFields): string {
  return [fields.general.trim(), ...SHEET_RULE_SECTIONS.flatMap(({ key, label }) =>
    fields[key].trim() ? [`【${label}】\n${fields[key].trim()}`] : [])].filter(Boolean).join('\n\n');
}
