import type { Profile } from '../domain/model.js';
import { parseAvatarPromptResponse } from './avatar-prompt.js';

export type ContactMatchPlatform = 'wechat' | 'twitter';

/** 单轮批量匹配上限：再多会把输出撑爆，导致 JSON 被截断。 */
export const CONTACT_MATCH_BATCH_LIMIT = 8;

export interface ContactMatchWorldBookEntry {
  readonly name: string;
  readonly content: string;
}

export interface ContactMatchPromptOptions {
  readonly platform: ContactMatchPlatform;
  readonly targetName?: string;
  readonly worldBookEntries: readonly ContactMatchWorldBookEntry[];
  readonly existingProfiles: readonly Pick<Profile, 'displayName' | 'boundCharacter' | 'twitterName' | 'aliases'>[];
  readonly recentStory?: readonly string[];
  /** 本轮最多匹配几位联系人；指定 targetName 时固定为 1。 */
  readonly limit?: number;
}

export interface ContactMatchDraft {
  readonly platform: ContactMatchPlatform;
  readonly boundCharacter: string;
  readonly displayName: string;
  readonly wechatAlias: string;
  readonly twitterName: string;
  readonly twitterHandle: string;
  readonly bio: string;
  readonly personality: string;
  readonly appearancePrompt: string;
  readonly avatarPrompt: string;
  readonly sourceEntryName?: string;
}

const AVATAR_SCHEMA = {
  subject: '1girl | 1boy | 1woman | 1man | 1person',
  age: 'English tags',
  hairColor: 'English tags',
  hairStyle: 'English tags',
  eyeColor: 'English tags',
  skin: 'English tags',
  face: 'English tags',
  expression: 'English tags',
  build: 'English tags',
  clothing: 'English tags',
  extraTags: ['English tag'],
} as const;

const CONTACT_SCHEMA = {
  boundCharacter: '世界书中的正式角色名',
  displayName: '手机通讯录通用显示名；微信时作为备注名',
  wechatAlias: '微信昵称或备注名',
  twitterName: '推特显示昵称',
  twitterHandle: '@english_handle',
  bio: '80-200字角色简介，概括身份与背景',
  personality: '80-300字性格、口癖和交流风格',
  sourceEntryName: '主要依据的世界书条目名',
  avatar: AVATAR_SCHEMA,
} as const;

/** 批量模式下压缩简介长度：一次要写多位角色，太长会被输出上限截断。 */
const BATCH_CONTACT_SCHEMA = {
  ...CONTACT_SCHEMA,
  bio: '60-120字角色简介，概括身份与背景',
  personality: '60-160字性格、口癖和交流风格',
} as const;

export function buildContactMatchPrompt(
  options: ContactMatchPromptOptions,
): { readonly system: string; readonly user: string } {
  const platformLabel = options.platform === 'twitter' ? '推特私信' : '微信消息';
  const targetName = options.targetName?.trim() ?? '';
  const limit = targetName ? 1 : Math.min(12, Math.max(1, Math.round(options.limit ?? CONTACT_MATCH_BATCH_LIMIT)));
  const excludedCharacters = excludedCharactersOf(options.existingProfiles);
  return {
    system: [
      `你是${platformLabel}联系人资料批量匹配器。`,
      '只能依据给定世界书条目识别真实存在的角色，禁止创造世界书中不存在的人物。',
      targetName
        ? `本次只处理用户指定的角色或称呼「${targetName}」：即使它已经是联系人，也要返回完整资料用于补全。`
        : `一次找出世界书里所有适合成为${platformLabel}联系人、且尚未匹配过的角色，最多 ${limit} 位，按在剧情中的重要程度排序。`,
      ...(targetName
        ? []
        : ['excludedCharacters 与 existingContacts 里出现过的角色一律跳过，绝对不能重复返回；'
          + '如果确实没有新角色可匹配，就返回 {"contacts": []}。']),
      '同一个角色只能出现一次；不同角色不得共用昵称或账号名。',
      '资料必须符合角色的明确设定与世界书条目。昵称、账号和简介只能做合理的平台化表达，不得创造世界书中不存在的角色、关系、经历或外貌。',
      'twitterHandle 必须是 1-30 位英文字母、数字或下划线组成的账号名，可带 @；不得使用中文、空格或标点。',
      'avatar 中所有字段都必须填写简短明确的英文标签；未知外貌应基于设定保守推断，禁止 unknown、N/A。',
      '只输出一个 JSON 对象 {"contacts": [...]}，不要 Markdown、解释或代码围栏。',
    ].join('\n'),
    user: JSON.stringify({
      task: targetName
        ? `匹配并生成「${targetName}」的${platformLabel}联系人资料。`
        : `一次性匹配并生成最多 ${limit} 位尚未存在的${platformLabel}联系人资料。`,
      platform: options.platform,
      requestedCharacter: targetName,
      maxContacts: limit,
      outputSchema: { contacts: [targetName ? CONTACT_SCHEMA : BATCH_CONTACT_SCHEMA] },
      ...(targetName ? {} : { excludedCharacters }),
      existingContacts: options.existingProfiles.map((profile) => ({
        displayName: profile.displayName,
        boundCharacter: profile.boundCharacter ?? '',
        twitterName: profile.twitterName ?? '',
        aliases: profile.aliases,
      })),
      worldBookEntries: options.worldBookEntries,
      recentStory: (options.recentStory ?? []).slice(-8),
    }),
  };
}

/** 已经存在的角色名清单：模型只需要看名字就知道要跳过谁。 */
function excludedCharactersOf(
  profiles: readonly Pick<Profile, 'displayName' | 'boundCharacter' | 'twitterName' | 'aliases'>[],
): readonly string[] {
  const names = new Set<string>();
  for (const profile of profiles) {
    const name = (profile.boundCharacter ?? '').trim() || profile.displayName.trim();
    if (name) names.add(name);
  }
  return [...names].slice(0, 80);
}

/** 批量解析：跳过个别无效条目，只要还有一位可用就不报错；模型返回空数组时返回空列表。 */
export function parseContactMatchResponses(
  raw: string,
  platform: ContactMatchPlatform,
): readonly ContactMatchDraft[] {
  const entries = extractContactEntries(raw);
  const drafts: ContactMatchDraft[] = [];
  const seen = new Set<string>();
  for (const entry of entries) {
    let draft: ContactMatchDraft;
    try {
      draft = toContactMatchDraft(entry, platform);
    } catch {
      continue;
    }
    const key = draft.boundCharacter.toLocaleLowerCase('zh-CN');
    if (seen.has(key)) continue;
    seen.add(key);
    drafts.push(draft);
  }
  // 全部条目都不合格时，抛出第一条的具体原因（例如缺少推特号），便于用户排查。
  if (drafts.length === 0 && entries.length > 0) toContactMatchDraft(entries[0] as Record<string, unknown>, platform);
  return drafts;
}

/** 单条解析：用于指定角色的补全场景。 */
export function parseContactMatchResponse(raw: string, platform: ContactMatchPlatform): ContactMatchDraft {
  const entries = extractContactEntries(raw);
  const first = entries[0];
  if (!first) throw new Error('自动匹配结果里没有联系人资料。');
  return toContactMatchDraft(first, platform);
}

function toContactMatchDraft(record: Record<string, unknown>, platform: ContactMatchPlatform): ContactMatchDraft {
  const boundCharacter = requiredText(record.boundCharacter, '绑定角色', 80);
  const displayName = requiredText(record.displayName, '联系人昵称', 40);
  const wechatAlias = cleanText(record.wechatAlias, 40) || displayName;
  const twitterName = cleanText(record.twitterName, 40) || displayName;
  const twitterHandle = normalizeTwitterHandle(record.twitterHandle);
  if (platform === 'twitter' && !twitterHandle) throw new Error('自动匹配结果缺少有效的推特号。');
  const bio = requiredText(record.bio, '角色简介', 300);
  const personality = requiredText(record.personality, '角色性格', 500);
  if (!record.avatar || typeof record.avatar !== 'object' || Array.isArray(record.avatar)) {
    throw new Error('自动匹配结果缺少头像提示词资料。');
  }
  const avatar = parseAvatarPromptResponse(JSON.stringify(record.avatar));
  const sourceEntryName = cleanText(record.sourceEntryName, 120);
  return {
    platform,
    boundCharacter,
    displayName,
    wechatAlias,
    twitterName,
    twitterHandle,
    bio,
    personality,
    appearancePrompt: avatar.appearancePrompt,
    avatarPrompt: avatar.prompt,
    ...(sourceEntryName ? { sourceEntryName } : {}),
  };
}

/**
 * 取出所有联系人条目：支持 {contacts:[…]}、裸数组、单个对象三种形态；
 * 整体 JSON 解析失败（例如输出被截断）时退化为扫描花括号，尽量保住已经写完的条目。
 */
function extractContactEntries(raw: string): readonly Record<string, unknown>[] {
  const cleaned = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const parsed = tryParseJson(cleaned);
  if (Array.isArray(parsed)) return parsed.filter(isRecord);
  if (isRecord(parsed)) {
    if (Array.isArray(parsed.contacts)) return parsed.contacts.filter(isRecord);
    if (typeof parsed.boundCharacter === 'string') return [parsed];
    const list = Object.values(parsed).find(
      (value): value is unknown[] => Array.isArray(value) && value.some((item) => isRecord(item) && 'boundCharacter' in item),
    );
    if (list) return list.filter(isRecord);
  }
  const scanned = scanContactObjects(cleaned);
  if (scanned.length > 0) return scanned;
  throw new Error('模型没有返回联系人匹配 JSON。');
}

/** 扫描文本中所有闭合的花括号对象，保留带 boundCharacter 的那些（可从截断输出中救回条目）。 */
function scanContactObjects(text: string): readonly Record<string, unknown>[] {
  const found: Record<string, unknown>[] = [];
  const starts: number[] = [];
  let inString = false;
  let escaped = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') inString = true;
    else if (character === '{') starts.push(index);
    else if (character === '}') {
      const start = starts.pop();
      if (start === undefined) continue;
      const value = tryParseJson(text.slice(start, index + 1));
      if (isRecord(value) && typeof value.boundCharacter === 'string') found.push(value);
    }
  }
  return found;
}

function tryParseJson(text: string): unknown {
  const objectStart = text.indexOf('{');
  const arrayStart = text.indexOf('[');
  const start = objectStart < 0 ? arrayStart : arrayStart < 0 ? objectStart : Math.min(objectStart, arrayStart);
  const end = Math.max(text.lastIndexOf('}'), text.lastIndexOf(']'));
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(text.slice(start, end + 1));
  } catch {
    return null;
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function requiredText(value: unknown, label: string, maxLength: number): string {
  const text = cleanText(value, maxLength);
  if (!text) throw new Error(`自动匹配结果缺少${label}。`);
  return text;
}

function cleanText(value: unknown, maxLength: number): string {
  return String(value ?? '').replace(/\u0000/g, '').trim().slice(0, maxLength);
}

function normalizeTwitterHandle(value: unknown): string {
  const handle = String(value ?? '')
    .trim()
    .replace(/^@+/, '')
    .replace(/[^A-Za-z0-9_]/g, '')
    .slice(0, 30);
  return handle ? `@${handle}` : '';
}