import type { ForumDiscussionDraft } from '../domain/commands.js';
import { derivePostTitle, type PhonePost, type PhoneState } from '../domain/model.js';
import type { ForumActivityLevel, ForumSettings } from '../integration/forum-settings.js';
import { formatWorldTime } from '../time/world-clock.js';
import { replaceImageMarkers } from './content-safety.js';
import { identityNamesOf, normalizeIdentityName, publicNameFor } from './identity.js';

export const FORUM_DISCUSSION_PROTOCOL_VERSION = 1;
export const FORUM_DISCUSSION_MAX_ACTIONS = 120;

export interface ForumDiscussionPrompt {
  readonly system: string;
  readonly user: string;
  readonly expectedThreadCount: number;
  readonly allowedParentPostIds: readonly string[];
  readonly existingParentRoots: Readonly<Record<string, string>>;
  readonly existingParentDepths: Readonly<Record<string, number>>;
  readonly continuationThreadIds: readonly string[];
  readonly existingContents: readonly string[];
  readonly blockedAuthorNames: readonly string[];
  readonly requireNestedReply: boolean;
  /** 板块自转：本批次只允许写入这个板块，解析时会强制归位。 */
  readonly requiredBoard?: string;
}

export interface ForumDiscussionPromptOptions {
  readonly state: PhoneState;
  readonly settings: ForumSettings;
  readonly selfProfileId: string;
  readonly worldBookExcerpt?: string | null;
  readonly worldBookNames?: readonly string[];
  /** 只自转单个板块时传入板块名；留空表示全站自转。 */
  readonly board?: string | null;
}

interface ExistingDiscussion {
  readonly id: string;
  readonly title: string;
  readonly board: string;
  readonly authorName: string;
  readonly content: string;
  readonly replies: readonly {
    readonly id: string;
    readonly parentId: string;
    readonly authorName: string;
    readonly content: string;
    readonly depth: number;
  }[];
}

interface ParsedActionRecord {
  readonly key: string;
  readonly kind: 'thread' | 'reply';
  readonly authorName: string;
  readonly content: string;
  readonly title?: string;
  readonly board?: string;
  readonly tags?: readonly string[];
  readonly parentKey?: string;
  readonly parentPostId?: string;
}

const FORUM_MAX_THREAD_CHARS = 3_400;
const FORUM_MAX_REPLY_CHARS = 1_200;
/** 帖子没写板块时的归属，与界面上的默认板块保持一致。 */
const FORUM_DEFAULT_BOARD_NAME = '综合讨论';
const ACTIVITY_GUIDANCE: Readonly<Record<ForumActivityLevel, string>> = {
  quiet: '安静：话题节奏舒缓，回复克制，允许观点停留，不制造突发热点。',
  balanced: '均衡：日常话题与有来有回的讨论并存，热度分布自然。',
  lively: '活跃：多位网友快速接话，观点差异明显，但不靠重复刷屏制造热闹。',
  bustling: '沸腾：社区正在集中讨论多个公共事件，回复密集且会分叉成楼中楼。',
};

export function buildForumDiscussionPrompt(options: ForumDiscussionPromptOptions): ForumDiscussionPrompt {
  const boards = collectBoards(options.state, options.board);
  const scopedBoard = options.board?.trim() ? boards[0]?.name ?? options.board.trim() : '';
  const discussions = collectExistingDiscussions(
    options.state,
    options.selfProfileId,
    options.settings.contextThreadCount,
    scopedBoard,
  );
  const continuationCount = options.settings.autonomousMode && options.settings.repliesPerThread > 0
    ? Math.min(options.settings.continuationThreadCount, discussions.length)
    : 0;
  const continuationThreadIds = discussions.slice(0, continuationCount).map((discussion) => discussion.id);
  const requestedReplies = options.settings.autonomousMode ? options.settings.repliesPerThread : 0;
  const requireNestedReply = options.settings.autonomousMode
    && options.settings.maxReplyDepth >= 2
    && requestedReplies >= 2;
  const existingParentRoots: Record<string, string> = {};
  const existingParentDepths: Record<string, number> = {};
  for (const discussion of discussions) {
    existingParentRoots[discussion.id] = discussion.id;
    existingParentDepths[discussion.id] = 0;
    for (const reply of discussion.replies) {
      existingParentRoots[reply.id] = discussion.id;
      existingParentDepths[reply.id] = reply.depth;
    }
  }
  const allowedParentPostIds = Object.keys(existingParentRoots);
  const blockedAuthorNames = selfIdentityNames(options.state, options.selfProfileId);
  const boardGuidance = boards
    .filter((board) => board.guidance)
    .map((board) => `${board.name}：${board.guidance ?? ''}`);
  const actionShape = {
    key: 't1 或 r1（批次内唯一）',
    type: 'thread 或 reply',
    authorName: '论坛公开昵称',
    title: '仅 thread 必填',
    board: scopedBoard ? `仅 thread 必填，且必须是「${scopedBoard}」` : '仅 thread 必填',
    tags: ['可选标签'],
    content: '正文',
    parentKey: 'reply 引用同批次 key 时填写',
    parentPostId: 'reply 续聊已有内容时填写',
  };
  const system = [
    '你是论坛世界自转引擎，只输出严格 JSON，不输出 markdown、解释或额外文字。',
    '世界书摘录是最高优先级事实约束：论坛主题、作者资格、时代、语言、板块与互动方式都必须服从世界书。通用论坛习惯只能在世界书没有规定时作为兜底。',
    '世界书没有写论坛这类公共讨论区时不要拒绝生成、也不要返回空批次：按世界书给出的世界观、时代、地域、人群与正在发生的事，推断这个世界里公共讨论区的形态、常驻人群与话题；完全没有可推断线索时才使用与论坛相符的中性内容。',
    '本批次是公开论坛里的 NPC/路人自主活动，不回应、不提及、不影射用户，也不引用私聊、通讯录、用户经历或内部 profile id。',
    ...(scopedBoard
      ? [`本批次是「${scopedBoard}」板块自转：所有 thread 的 board 必须是「${scopedBoard}」，不得新建其他板块，也不得续聊其他板块的内容。`]
      : []),
    ...(boardGuidance.length > 0
      ? [`板块说明是该板块的硬约束，写在这个板块里的主题与回复，其题材、语气和取材都要服从它；与通用论坛习惯冲突时以板块说明为准：\n${boardGuidance.map((line) => `- ${line}`).join('\n')}`]
      : []),
    options.settings.autonomousMode
      ? '开启自娱自乐：NPC/路人要围绕彼此的公开内容发帖、接话、争论、补充和楼中楼交流；不要等待用户参与。世界书允许多人参与时，同一主题使用多个有辨识度的公开昵称。'
      : '未开启自娱自乐：只生成独立主题，不生成 reply。',
    '每个 action 都必须有批次内唯一 key。reply 必须且只能提供 parentKey 或 parentPostId：parentKey 引用同批次 action，parentPostId 只能取请求给出的 allowedParentPostIds。',
    '禁止复制已有内容；不要为了凑数量套用近义标题。每个作者的语气、立场和关注点应有区别。',
    `返回格式：${JSON.stringify({ version: FORUM_DISCUSSION_PROTOCOL_VERSION, actions: [actionShape] })}`,
  ].join('\n');
  const user = JSON.stringify({
    task: {
      newThreadCount: options.settings.refreshThreadCount,
      selfPlayEnabled: options.settings.autonomousMode,
      activity: options.settings.activityLevel,
      activityGuidance: ACTIVITY_GUIDANCE[options.settings.activityLevel],
      recommendedRepliesPerNewThread: options.settings.autonomousMode ? requestedReplies : 0,
      continuationThreadIds,
      requireAtLeastOneNestedReply: requireNestedReply,
      ...(scopedBoard ? { onlyBoard: scopedBoard } : {}),
    },
    limits: {
      threadTargetChars: options.settings.threadTargetLength,
      replyTargetChars: options.settings.replyTargetLength,
      threadMaxChars: FORUM_MAX_THREAD_CHARS,
      replyMaxChars: FORUM_MAX_REPLY_CHARS,
      repliesPerThread: options.settings.repliesPerThread,
      maxReplyDepth: options.settings.maxReplyDepth,
      maxTagsPerThread: options.settings.maxTagsPerThread,
      maxActions: FORUM_DISCUSSION_MAX_ACTIONS,
    },
    currentTime: formatWorldTime(options.state.worldClock.now),
    boards,
    allowedParentPostIds,
    recentPublicDiscussions: discussions,
    currentWorldBookEntries: options.worldBookNames ?? [],
    ...(options.worldBookExcerpt?.trim() ? { settingExcerpt: options.worldBookExcerpt.trim() } : {}),
  }, null, 2);
  return {
    system,
    user,
    expectedThreadCount: options.settings.refreshThreadCount,
    allowedParentPostIds,
    existingParentRoots,
    existingParentDepths,
    continuationThreadIds,
    existingContents: Object.values(options.state.posts)
      .filter((post) => post.appId === 'forum')
      .map((post) => post.content),
    blockedAuthorNames,
    requireNestedReply,
    ...(scopedBoard ? { requiredBoard: scopedBoard } : {}),
  };
}

export function parseForumDiscussionBatch(
  raw: string,
  settings: ForumSettings,
  prompt: Pick<ForumDiscussionPrompt,
    | 'expectedThreadCount'
    | 'allowedParentPostIds'
    | 'existingParentRoots'
    | 'existingParentDepths'
    | 'continuationThreadIds'
    | 'existingContents'
    | 'blockedAuthorNames'
    | 'requireNestedReply'
    | 'requiredBoard'>,
): readonly ForumDiscussionDraft[] {
  const parsed = parseJsonObject(raw);
  if (parsed.version !== FORUM_DISCUSSION_PROTOCOL_VERSION) {
    throw new Error(`论坛讨论协议版本应为 ${FORUM_DISCUSSION_PROTOCOL_VERSION}`);
  }
  if (!Array.isArray(parsed.actions)) throw new Error('论坛讨论 actions 必须是数组');
  if (parsed.actions.length === 0 || parsed.actions.length > FORUM_DISCUSSION_MAX_ACTIONS) {
    throw new Error(`论坛讨论 actions 应为 1-${FORUM_DISCUSSION_MAX_ACTIONS} 条`);
  }

  const blockedNames = new Set(prompt.blockedAuthorNames.map(normalizeIdentityName).filter(Boolean));
  const knownContents = new Set(prompt.existingContents.map(normalizeForComparison).filter(Boolean));
  const allowedParents = new Set(prompt.allowedParentPostIds);
  const records = parsed.actions.map((value, index) => parseAction(
    value,
    index,
    settings,
    blockedNames,
    knownContents,
    allowedParents,
  ));
  const byKey = new Map<string, ParsedActionRecord>();
  for (const record of records) {
    if (byKey.has(record.key)) throw new Error(`论坛讨论存在重复 key：${record.key}`);
    byKey.set(record.key, record);
  }

  const depthCache = new Map<string, number>();
  const rootCache = new Map<string, string>();
  const visiting = new Set<string>();
  const resolvePosition = (record: ParsedActionRecord): { readonly depth: number; readonly root: string } => {
    const cachedDepth = depthCache.get(record.key);
    const cachedRoot = rootCache.get(record.key);
    if (cachedDepth !== undefined && cachedRoot) return { depth: cachedDepth, root: cachedRoot };
    if (visiting.has(record.key)) throw new Error(`论坛讨论存在循环引用：${record.key}`);
    visiting.add(record.key);
    let depth = 0;
    let root = record.key;
    if (record.kind === 'reply' && record.parentKey) {
      const parent = byKey.get(record.parentKey);
      if (!parent) throw new Error(`论坛回复 ${record.key} 引用了不存在的 parentKey`);
      const parentPosition = resolvePosition(parent);
      depth = parentPosition.depth + 1;
      root = parentPosition.root;
    } else if (record.kind === 'reply' && record.parentPostId) {
      const parentDepth = prompt.existingParentDepths[record.parentPostId];
      const parentRoot = prompt.existingParentRoots[record.parentPostId];
      if (parentDepth === undefined || !parentRoot) throw new Error(`论坛回复 ${record.key} 的历史父级无效`);
      depth = parentDepth + 1;
      root = parentRoot;
    }
    visiting.delete(record.key);
    if (depth > settings.maxReplyDepth) {
      throw new Error(`论坛回复 ${record.key} 超过最大楼中楼层级 ${settings.maxReplyDepth}`);
    }
    depthCache.set(record.key, depth);
    rootCache.set(record.key, root);
    return { depth, root };
  };

  const replyCounts = new Map<string, number>();
  let nestedReplyCount = 0;
  let threadCount = 0;
  for (const record of records) {
    const position = resolvePosition(record);
    if (record.kind === 'thread') {
      threadCount += 1;
      continue;
    }
    if (position.depth >= 2) nestedReplyCount += 1;
    replyCounts.set(position.root, (replyCounts.get(position.root) ?? 0) + 1);
  }
  if (threadCount !== prompt.expectedThreadCount) {
    throw new Error(`AI 必须返回恰好 ${prompt.expectedThreadCount} 个新主题，实际为 ${threadCount} 个`);
  }
  if (!settings.autonomousMode && records.some((record) => record.kind === 'reply')) {
    throw new Error('自娱自乐关闭时不得生成论坛回复');
  }
  if (settings.autonomousMode) {
    if (settings.repliesPerThread > 0) {
      const emptyThread = records.find((record) => record.kind === 'thread' && (replyCounts.get(record.key) ?? 0) === 0);
      if (emptyThread) throw new Error(`自娱自乐主题 ${emptyThread.key} 没有 NPC 回复`);
    }
    if (prompt.requireNestedReply && nestedReplyCount === 0) throw new Error('本批次缺少楼中楼 NPC 对话');
    if (prompt.continuationThreadIds.length > 0) {
      const missingContinuations = prompt.continuationThreadIds.filter((threadId) => (replyCounts.get(threadId) ?? 0) === 0);
      if (missingContinuations.length > 0) {
        throw new Error(`本批次没有续聊已有 NPC 主题（未续聊全部指定的已有 NPC 主题）：${missingContinuations.join('、')}`);
      }
    }
  }
  for (const [root, count] of replyCounts) {
    if (count > settings.repliesPerThread) {
      throw new Error(`主题 ${root} 的新增回复 ${count} 条，超过上限 ${settings.repliesPerThread}`);
    }
  }

  return records.map((record): ForumDiscussionDraft => ({
    key: record.key,
    kind: record.kind,
    authorName: record.authorName,
    content: record.content,
    ...(record.title ? { title: record.title } : {}),
    ...(boardOf(record, prompt.requiredBoard) ? { board: boardOf(record, prompt.requiredBoard) } : {}),
    ...(record.tags && record.tags.length > 0 ? { tags: record.tags } : {}),
    ...(record.parentKey ? { parentKey: record.parentKey } : {}),
    ...(record.parentPostId ? { parentPostId: record.parentPostId } : {}),
  }));
}

/** 板块自转按作用域归位：AI 写错板块名也不会把内容漏到别的板块。 */
function boardOf(record: ParsedActionRecord, requiredBoard?: string): string {
  return requiredBoard?.trim() || record.board || '';
}

function parseAction(
  value: unknown,
  index: number,
  settings: ForumSettings,
  blockedNames: ReadonlySet<string>,
  knownContents: Set<string>,
  allowedParents: ReadonlySet<string>,
): ParsedActionRecord {
  if (!value || typeof value !== 'object' || Array.isArray(value)) {
    throw new Error(`论坛讨论第 ${index + 1} 条 action 不是对象`);
  }
  const record = value as Record<string, unknown>;
  const key = cleanSingleLine(record.key, 80);
  const kind = record.type === 'thread' ? 'thread' : record.type === 'reply' ? 'reply' : null;
  const authorName = cleanSingleLine(record.authorName, 40);
  if (!key || !kind || !authorName) throw new Error(`论坛讨论第 ${index + 1} 条缺少 key、type 或 authorName`);
  if (blockedNames.has(normalizeIdentityName(authorName))) throw new Error(`论坛讨论第 ${index + 1} 条使用了用户身份`);

  const content = cleanContent(record.content);
  const maximum = kind === 'thread' ? FORUM_MAX_THREAD_CHARS : FORUM_MAX_REPLY_CHARS;
  if (!content || content.length > maximum) {
    throw new Error(`论坛讨论第 ${index + 1} 条正文应为 1-${maximum} 字`);
  }
  const contentKey = normalizeForComparison(content);
  if (!contentKey || knownContents.has(contentKey)) throw new Error(`论坛讨论第 ${index + 1} 条与已有内容重复`);
  knownContents.add(contentKey);

  const title = cleanSingleLine(record.title, 80);
  const board = cleanSingleLine(record.board, 40);
  const tags = normalizeTags(record.tags, settings.maxTagsPerThread);
  const parentKey = cleanSingleLine(record.parentKey, 80);
  const parentPostId = cleanSingleLine(record.parentPostId, 200);
  if (kind === 'thread') {
    if (!title || !board) throw new Error(`论坛主题 ${key} 缺少 title 或 board`);
    if (parentKey || parentPostId) throw new Error(`论坛主题 ${key} 不得指定父级`);
  } else {
    if (Boolean(parentKey) === Boolean(parentPostId)) throw new Error(`论坛回复 ${key} 必须且只能指定一种父级`);
    if (parentPostId && !allowedParents.has(parentPostId)) throw new Error(`论坛回复 ${key} 引用了未授权的历史内容`);
  }
  return {
    key,
    kind,
    authorName,
    content,
    ...(title && kind === 'thread' ? { title } : {}),
    ...(board ? { board } : {}),
    ...(tags.length > 0 ? { tags } : {}),
    ...(parentKey ? { parentKey } : {}),
    ...(parentPostId ? { parentPostId } : {}),
  };
}

function collectExistingDiscussions(
  state: PhoneState,
  selfProfileId: string,
  limit: number,
  board = '',
): readonly ExistingDiscussion[] {
  const scopeKey = boardKeyOf(board);
  const threads = state.postOrder
    .slice()
    .reverse()
    .flatMap((id) => {
      const post = state.posts[id];
      if (post?.appId !== 'forum' || post.kind !== 'forum-thread' || post.profileId === selfProfileId) return [];
      return !scopeKey || boardKeyOf(post.board ?? '') === scopeKey ? [post] : [];
    })
    .slice(0, Math.max(0, limit));
  return threads.map((thread) => {
    const replies = state.postOrder.flatMap((id) => {
      const post = state.posts[id];
      if (post?.appId !== 'forum' || post.kind !== 'forum-reply' || post.profileId === selfProfileId) return [];
      const ancestry = forumAncestry(state, post);
      if (ancestry.rootId !== thread.id) return [];
      return [{
        id: post.id,
        parentId: post.parentId ?? post.targetId ?? thread.id,
        authorName: publicForumName(state, post.profileId),
        content: cleanExcerpt(post.content, 500),
        depth: ancestry.depth,
      }];
    }).slice(-10);
    return {
      id: thread.id,
      title: thread.title?.trim() || derivePostTitle(thread.content) || '未命名主题',
      board: thread.board?.trim() || FORUM_DEFAULT_BOARD_NAME,
      authorName: publicForumName(state, thread.profileId),
      content: cleanExcerpt(thread.content, 800),
      replies,
    };
  });
}

function forumAncestry(state: PhoneState, post: PhonePost): { readonly rootId: string | null; readonly depth: number } {
  let current: PhonePost | undefined = post;
  let depth = 0;
  const visited = new Set<string>();
  while (current && !visited.has(current.id) && depth <= 20) {
    visited.add(current.id);
    if (current.kind === 'forum-thread') return { rootId: current.id, depth };
    const parentId: string | undefined = current.parentId ?? current.targetId;
    if (!parentId) return { rootId: null, depth };
    current = state.posts[parentId];
    depth += 1;
  }
  return { rootId: null, depth };
}

interface PromptBoard {
  readonly name: string;
  /** 板块说明；有说明时它就是该板块生成内容的硬约束。 */
  readonly guidance?: string;
  readonly source: 'custom' | 'content' | 'default';
}

/** 传入 scope 时只返回该板块，让板块自转的提示词里没有别的板块可选。 */
function collectBoards(state: PhoneState, scope?: string | null): readonly PromptBoard[] {
  const boards = new Map<string, PromptBoard>();
  for (const board of Object.values(state.forumBoards)) {
    boards.set(boardKeyOf(board.name), {
      name: board.name,
      ...(board.description.trim() ? { guidance: board.description.trim() } : {}),
      source: 'custom',
    });
  }
  for (const post of Object.values(state.posts)) {
    const name = post.appId === 'forum' ? post.board?.trim() : '';
    if (!name || boards.has(boardKeyOf(name))) continue;
    boards.set(boardKeyOf(name), { name, source: 'content' });
  }
  const scopeKey = boardKeyOf(scope ?? '');
  if (scopeKey) {
    const scoped = boards.get(scopeKey);
    return [scoped ?? { name: (scope ?? '').trim(), source: 'content' }];
  }
  if (boards.size === 0) boards.set(boardKeyOf(FORUM_DEFAULT_BOARD_NAME), { name: FORUM_DEFAULT_BOARD_NAME, source: 'default' });
  return [...boards.values()];
}

function boardKeyOf(name: string): string {
  return name.trim().toLocaleLowerCase('zh-CN');
}

function selfIdentityNames(state: PhoneState, selfProfileId: string): readonly string[] {
  const profile = state.profiles[selfProfileId];
  return profile ? identityNamesOf(profile) : [];
}

function publicForumName(state: PhoneState, profileId: string): string {
  const profile = state.profiles[profileId];
  return profile ? publicNameFor(profile, 'forum') : '匿名网友';
}

function parseJsonObject(raw: string): Record<string, unknown> {
  const trimmed = String(raw ?? '').trim();
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/iu.exec(trimmed);
  const candidate = fenced?.[1] ?? trimmed;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('AI 返回的论坛讨论格式无效');
  try {
    const value = JSON.parse(candidate.slice(start, end + 1)) as unknown;
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error();
    return value as Record<string, unknown>;
  } catch {
    throw new Error('AI 返回的论坛讨论不是有效 JSON');
  }
}

function cleanSingleLine(value: unknown, maximum: number): string {
  return typeof value === 'string'
    ? value.replace(/\u0000/g, '').replace(/\s+/g, ' ').trim().slice(0, maximum)
    : '';
}

function cleanContent(value: unknown): string {
  if (typeof value !== 'string') return '';
  return replaceImageMarkers(value, '')
    .replace(/\u0000/g, '')
    .replace(/[\t ]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function cleanExcerpt(value: string, maximum: number): string {
  return cleanContent(value).slice(0, maximum);
}

function normalizeTags(value: unknown, maximum: number): readonly string[] {
  if (!Array.isArray(value)) return [];
  const tags = new Map<string, string>();
  for (const raw of value) {
    const tag = cleanSingleLine(raw, 24).replace(/^#+/u, '');
    if (!tag) continue;
    tags.set(tag.toLocaleLowerCase('zh-CN'), `#${tag}`);
    if (tags.size >= maximum) break;
  }
  return [...tags.values()];
}

function normalizeForComparison(value: string): string {
  return cleanContent(value).toLocaleLowerCase('zh-CN').replace(/[^\p{L}\p{N}]+/gu, '').slice(0, 800);
}