import { logHttpFailure, logModelFailure } from '../core/diagnostics.js';
import { phoneLogger } from '../core/logger.js';
import {
  getSillyTavernRequestHeaders,
  type OpenAiCompatibleApiConfig,
} from '../integration/sillytavern-bridge.js';

export interface ApiModelOption {
  readonly id: string;
  readonly label: string;
}

export interface ApiRetryProgress {
  readonly attempt: number;
  readonly retryCount: number;
  readonly delayMs: number;
  readonly error: unknown;
}

export interface ApiCompletionRequest {
  readonly system: string;
  readonly user: string;
  readonly temperature: number;
  readonly maxTokens: number;
  readonly signal?: AbortSignal;
  /**
   * 单次请求的空闲超时：流式按「多久没有收到新数据」计时，非流式按整次请求计时。
   * 空闲超时只中止当前尝试并按可重试错误上报，不会取消整轮重试。
   */
  readonly idleTimeoutMs?: number;
  readonly validateResponse?: (response: string) => boolean;
  readonly invalidResponseMessage?: string;
  readonly onRetry?: (progress: ApiRetryProgress) => void | Promise<void>;
}

type ProxySource = 'openai' | 'custom';

interface ProxyErrorPayload {
  readonly error?: unknown;
  readonly message?: unknown;
}

interface CompletionPayload extends ProxyErrorPayload {
  readonly choices?: readonly {
    readonly message?: { readonly content?: unknown };
    readonly text?: unknown;
  }[];
}

function extractTextContent(value: unknown): string {
  if (typeof value === 'string') return value;
  if (!Array.isArray(value)) return '';
  return value.map((part) => {
    if (typeof part === 'string') return part;
    if (!part || typeof part !== 'object') return '';
    const record = part as Record<string, unknown>;
    return extractTextContent(record.text ?? record.content);
  }).join('');
}

function extractChoiceText(choice: {
  readonly message?: { readonly content?: unknown };
  readonly text?: unknown;
} | undefined): string {
  return extractTextContent(choice?.message?.content ?? choice?.text).trim();
}

const OFFICIAL_OPENAI_BASE_URL = 'https://api.openai.com/v1';
const MODELS_FETCH_TIMEOUT_MS = 20_000;

/**
 * 规范化 Base URL：
 * - 去掉末尾斜杠与 /chat/completions 后缀；
 * - 纯域名（无路径）时自动补 /v1；
 * - 为空时使用官方 OpenAI 地址。
 */
export function normalizeApiBaseUrl(baseUrl: string): string {
  let normalized = baseUrl.trim().replace(/\/+$/, '');
  if (!normalized) return '';
  normalized = normalized.replace(/\/chat\/completions$/i, '').replace(/\/+$/, '');
  try {
    const url = new URL(normalized);
    const path = url.pathname.replace(/\/+$/, '');
    if (!path) return `${normalized}/v1`;
  } catch {
    // 保留用户输入，交由后端报错提示。
  }
  return normalized;
}

export function resolveApiBaseUrl(config: OpenAiCompatibleApiConfig): string {
  return normalizeApiBaseUrl(config.baseUrl) || OFFICIAL_OPENAI_BASE_URL;
}

export function parseApiModels(payload: unknown): readonly ApiModelOption[] {
  const record = asRecord(payload);
  const candidates = Array.isArray(payload)
    ? payload
    : Array.isArray(record?.data)
      ? record.data
      : Array.isArray(record?.models)
        ? record.models
        : [];
  const modelIds = candidates
    .map((candidate) => {
      if (typeof candidate === 'string') return candidate.trim();
      const item = asRecord(candidate);
      const id = String(item?.id ?? item?.name ?? item?.model ?? '').trim();
      return id.startsWith('models/') ? id.slice('models/'.length) : id;
    })
    .filter(Boolean);
  return [...new Set(modelIds)].sort((left, right) => left.localeCompare(right)).map((id) => ({ id, label: id }));
}

/**
 * 拉取模型列表。依次尝试：
 * 1. 酒馆后端代理（openai 源，reverse_proxy + proxy_password）；
 * 2. 酒馆后端代理（custom 源，custom_url + Authorization 头）；
 * 3. 浏览器直连 GET {baseUrl}/models。
 */
export async function fetchApiModels(config: OpenAiCompatibleApiConfig): Promise<readonly ApiModelOption[]> {
  const failures: string[] = [];
  for (const source of ['openai', 'custom'] as const) {
    try {
      const payload = await postToProxy('/api/backends/chat-completions/status', {
        ...createProxyConfigPayload(config, source),
      }, AbortSignal.timeout(MODELS_FETCH_TIMEOUT_MS));
      const models = parseApiModels(payload);
      if (models.length > 0) return models;
      failures.push(`${source} 路线返回了空模型列表`);
    } catch (error) {
      failures.push(`${source} 路线：${describeError(error)}`);
    }
  }

  try {
    const models = await fetchModelsDirectly(config);
    if (models.length > 0) return models;
    failures.push('浏览器直连返回了空模型列表');
  } catch (error) {
    failures.push(`浏览器直连：${describeError(error)}`);
  }
  throw new Error(`模型列表获取失败。${failures.join('；')}`);
}

export async function testApiConnection(config: OpenAiCompatibleApiConfig): Promise<readonly ApiModelOption[]> {
  const models = await fetchApiModels(config);
  if (models.length === 0) throw new Error('接口可访问，但未返回可选模型。');
  return models;
}

/** API 重试等待固定为 5 秒，避免不同请求的退避节奏不一致。 */
function retryDelayMs(_attempt: number): number {
  return 5_000;
}

/**
 * 识别值得自动重试的瞬时上游错误：
 * - 5xx / 429（通道繁忙、网关超时、限流）；
 * - new-api 类中转站在模型长思考时返回的「思考中…」/ get_channel_failed；
 * - 明确的过载与限流文案。
 */
export function isTransientUpstreamError(error: unknown): boolean {
  const status = (error as { status?: unknown } | null)?.status;
  if (typeof status === 'number' && [429, 500, 502, 503, 504].includes(status)) return true;
  const message = error instanceof Error ? error.message : String(error ?? '');
  return /status\s+(429|50[0234])|思考中|get_channel_failed|Service Unavailable|Bad Gateway|Gateway Time-?out|overloaded|rate.?limit|too many requests/i.test(message);
}

function isAbortError(error: unknown): boolean {
  return error instanceof DOMException
    ? error.name === 'AbortError'
    : error instanceof Error && error.name === 'AbortError';
}

function waitBeforeRetry(ms: number, signal?: AbortSignal): Promise<void> {
  return new Promise((resolve, reject) => {
    if (signal?.aborted) {
      reject(new DOMException('Aborted', 'AbortError'));
      return;
    }
    const onAbort = () => {
      window.clearTimeout(timer);
      reject(new DOMException('Aborted', 'AbortError'));
    };
    const timer = window.setTimeout(() => {
      signal?.removeEventListener('abort', onAbort);
      resolve();
    }, ms);
    signal?.addEventListener('abort', onAbort, { once: true });
  });
}

/**
 * 通过酒馆后端代理执行补全。
 * - 先走 openai 源（reverse_proxy），遇到路由类失败时自动降级 custom 源；
 * - 任意 API 请求或响应校验失败均按配置自动重试；中止信号不会重试；
 * - 调用方可通过 onRetry 把当前错误与重试进度显示给用户。
 */
export async function generateWithApiProxy(
  config: OpenAiCompatibleApiConfig,
  request: ApiCompletionRequest,
): Promise<string> {
  if (!config.model.trim()) throw new Error('请先选择或填写模型。');

  const retryCount = Math.min(10, Math.max(0, Math.round(config.retryCount ?? 3)));
  let lastError: unknown = null;
  for (let attempt = 0; attempt <= retryCount; attempt += 1) {
    if (attempt > 0) {
      const delayMs = retryDelayMs(attempt);
      phoneLogger.warn(`API 请求失败，${delayMs / 1000}s 后重试 ${attempt}/${retryCount}`, {
        error: lastError instanceof Error ? lastError.message.slice(0, 200) : String(lastError).slice(0, 200),
      });
      await request.onRetry?.({ attempt, retryCount, delayMs, error: lastError });
      await waitBeforeRetry(delayMs, request.signal);
    }
    for (const source of ['openai', 'custom'] as const) {
      try {
        const response = await generateViaSource(config, request, source);
        if (request.validateResponse && !request.validateResponse(response)) {
          // 「格式无效」最难排查：把模型这次真正返回的原文一起记进日志。
          logModelFailure({
            stage: 'API 返回格式校验',
            reason: request.invalidResponseMessage ?? 'API 返回内容格式无效。',
            raw: response,
            request: describeApiRequest(config, request, source),
          });
          throw new Error(request.invalidResponseMessage ?? 'API 返回内容格式无效。');
        }
        return response;
      } catch (error) {
        lastError = error;
        if (request.signal?.aborted || isAbortError(error)) throw error;
        if (isRouteFallbackError(error)) continue;
        break;
      }
    }
  }
  logModelFailure({
    stage: '配置 API 生成',
    reason: describeError(lastError),
    request: describeApiRequest(config, request),
    error: lastError,
  });
  throw lastError instanceof Error ? lastError : new Error(String(lastError ?? '配置 API 请求失败'));
}

async function generateViaSource(
  config: OpenAiCompatibleApiConfig,
  request: ApiCompletionRequest,
  source: ProxySource,
): Promise<string> {
  const useStream = config.stream !== false;
  const tokenField = config.maxTokenField === 'max_completion_tokens'
    ? { max_completion_tokens: request.maxTokens }
    : { max_tokens: request.maxTokens };
  const body = {
    ...createProxyConfigPayload(config, source),
    model: config.model.trim(),
    messages: [
      { role: 'system', content: request.system },
      { role: 'user', content: request.user },
    ],
    temperature: request.temperature,
    top_p: config.topP ?? 1,
    frequency_penalty: config.frequencyPenalty ?? 0,
    presence_penalty: config.presencePenalty ?? 0,
    stream: useStream,
    ...tokenField,
  };
  const deadline = createRequestDeadline(request);
  try {
    if (useStream) return await generateStreaming(body, deadline, request.validateResponse);
    const payload = await postToProxy('/api/backends/chat-completions/generate', body, deadline.signal) as CompletionPayload;
    const text = extractChoiceText(payload.choices?.[0]);
    if (!text) throw new Error('配置 API 返回空内容。');
    return text;
  } catch (error) {
    // 空闲超时只是本次尝试没等到数据，翻译成普通错误后仍可按配置重试。
    if (deadline.cancelledByCaller() || !deadline.idleExpired()) throw error;
    throw new Error(`配置 API 在 ${Math.round((request.idleTimeoutMs ?? 0) / 1000)}s 内没有返回新内容。`);
  } finally {
    deadline.dispose();
  }
}

/**
 * 单次请求的中止边界：把「调用方取消」与「空闲超时」分开，
 * 让上层能区分用户主动停止和值得重试的静默通道。
 */
interface RequestDeadline {
  readonly signal?: AbortSignal;
  /** 收到新数据时重置空闲计时。 */
  readonly touch: () => void;
  readonly cancelledByCaller: () => boolean;
  readonly idleExpired: () => boolean;
  readonly dispose: () => void;
}

function createRequestDeadline(request: ApiCompletionRequest): RequestDeadline {
  const callerSignal = request.signal;
  const idleTimeoutMs = request.idleTimeoutMs;
  const cancelledByCaller = () => callerSignal?.aborted === true;
  if (!idleTimeoutMs || !Number.isFinite(idleTimeoutMs) || idleTimeoutMs <= 0) {
    return {
      ...(callerSignal ? { signal: callerSignal } : {}),
      touch: () => undefined,
      cancelledByCaller,
      idleExpired: () => false,
      dispose: () => undefined,
    };
  }

  const controller = new AbortController();
  let expired = false;
  let timer: number | null = null;
  const clear = () => {
    if (timer !== null) window.clearTimeout(timer);
    timer = null;
  };
  const arm = () => {
    clear();
    timer = window.setTimeout(() => {
      expired = true;
      controller.abort();
    }, idleTimeoutMs);
  };
  const onCallerAbort = () => {
    clear();
    controller.abort();
  };
  if (cancelledByCaller()) controller.abort();
  else {
    callerSignal?.addEventListener('abort', onCallerAbort, { once: true });
    arm();
  }
  return {
    signal: controller.signal,
    touch: arm,
    cancelledByCaller,
    idleExpired: () => expired,
    dispose: () => {
      clear();
      callerSignal?.removeEventListener('abort', onCallerAbort);
    },
  };
}

interface StreamDeltaPayload {
  readonly choices?: readonly {
    readonly delta?: { readonly content?: unknown };
    readonly message?: { readonly content?: unknown };
    readonly text?: unknown;
  }[];
}

/**
 * 流式补全：解析 SSE（data: 行）中的增量内容并拼接为完整文本。
 * 部分代理对 stream 请求仍返回普通 JSON，此时按非流式解析兜底。
 *
 * 收到 [DONE] 即视为本次输出结束，不再等待连接关闭；
 * 若连接在内容到齐之后异常中断（BodyStreamBuffer was aborted 等），
 * 已收到的完整内容仍然算成功，只有真正没拿到内容时才报错。
 */
async function generateStreaming(
  body: Record<string, unknown>,
  deadline: RequestDeadline,
  validateResponse?: (response: string) => boolean,
): Promise<string> {
  const response = await fetch('/api/backends/chat-completions/generate', {
    method: 'POST',
    headers: getSillyTavernRequestHeaders(),
    credentials: 'include',
    cache: 'no-cache',
    ...(deadline.signal ? { signal: deadline.signal } : {}),
    body: JSON.stringify(body),
  });
  if (!response.ok) {
    const payload = await readPayload(response);
    const error = new Error(readProxyError(payload, `请求失败 (HTTP ${response.status})`));
    (error as Error & { status?: number }).status = response.status;
    throw error;
  }

  if (!response.body) throw new Error('流式响应没有可读的数据流。');
  // 注意：酒馆后端转发流式响应时可能不带 content-type，
  // 因此不依赖响应头判断，直接按 SSE 逐行解析，最后对非 SSE 内容做 JSON 兜底。
  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffer = '';
  let rawText = '';
  let text = '';
  let streamError = '';
  let completed = false;
  const consumeLine = (line: string): void => {
    if (completed) return;
    const trimmed = line.trim();
    if (!trimmed.startsWith('data:')) return;
    const data = trimmed.slice(5).trim();
    if (!data) return;
    if (data === '[DONE]') {
      completed = true;
      return;
    }
    try {
      const chunk = JSON.parse(data) as StreamDeltaPayload & ProxyErrorPayload;
      if (chunk.error) {
        streamError = readProxyError(chunk, '流式输出中断');
        return;
      }
      const choice = chunk.choices?.[0];
      const delta = extractTextContent(choice?.delta?.content ?? choice?.message?.content ?? choice?.text);
      if (delta) text += delta;
    } catch {
      // 忽略无法解析的心跳/注释行。
    }
  };
  let readFailure: unknown = null;
  try {
    while (!completed) {
      const { done, value } = await reader.read();
      if (done) break;
      deadline.touch();
      const piece = decoder.decode(value, { stream: true });
      rawText += piece;
      buffer += piece;
      let newlineIndex = buffer.indexOf('\n');
      while (newlineIndex >= 0) {
        consumeLine(buffer.slice(0, newlineIndex));
        buffer = buffer.slice(newlineIndex + 1);
        newlineIndex = buffer.indexOf('\n');
      }
    }
  } catch (error) {
    readFailure = error;
  } finally {
    await reader.cancel().catch(() => undefined);
  }
  const tail = decoder.decode();
  rawText += tail;
  buffer += tail;
  if (buffer.trim()) consumeLine(buffer);

  let result = text.trim();
  if (!result) {
    // 非 SSE 兜底：部分代理对 stream 请求仍返回普通 JSON。
    try {
      const payload = JSON.parse(rawText) as CompletionPayload;
      if (hasProxyError(payload)) throw new Error(readProxyError(payload, '配置 API 请求失败'));
      const content = extractChoiceText(payload.choices?.[0]);
      if (content) result = content;
    } catch (error) {
      if (error instanceof Error && error.message !== 'Unexpected token' && !(error instanceof SyntaxError)) throw error;
    }
  }
  if (readFailure) {
    if (deadline.cancelledByCaller()) throw readFailure;
    // 内部空闲超时或未发送 [DONE] 的中断都不能直接接受已有片段；
    // 只有调用方提供的完整性校验通过时，才兼容“内容已到齐但代理未正常收尾”的情况。
    const complete = Boolean(validateResponse && (() => {
      try {
        return validateResponse(result);
      } catch {
        return false;
      }
    })());
    if (deadline.idleExpired() || !result || !complete) {
      throw asRetryableStreamFailure(readFailure);
    }
    phoneLogger.warn('流式连接提前中断，已采用通过校验的完整内容', {
      error: readFailure instanceof Error ? readFailure.message.slice(0, 200) : String(readFailure).slice(0, 200),
      length: result.length,
    });
  }
  if (streamError) throw new Error(streamError);
  if (!result) throw new Error('配置 API 流式输出为空内容。');
  return result;
}

function asRetryableStreamFailure(error: unknown): Error {
  return new Error(`流式连接中断：${error instanceof Error ? error.message : String(error ?? '未知原因')}`);
}

export function createProxyConfigPayload(
  config: OpenAiCompatibleApiConfig,
  source: ProxySource = 'openai',
): Record<string, unknown> {
  const normalizedBaseUrl = normalizeApiBaseUrl(config.baseUrl);
  const apiKey = config.apiKey.trim();
  if (source === 'custom') {
    return {
      chat_completion_source: 'custom',
      custom_url: normalizedBaseUrl || OFFICIAL_OPENAI_BASE_URL,
      ...(apiKey
        ? {
            custom_include_headers: JSON.stringify({
              Authorization: apiKey.startsWith('Bearer ') ? apiKey : `Bearer ${apiKey}`,
            }),
          }
        : {}),
    };
  }
  // Base URL 与 Key 都为空时不传 reverse_proxy，让酒馆后端使用已保存的 OpenAI 密钥。
  if (!normalizedBaseUrl && !apiKey) {
    return { chat_completion_source: 'openai' };
  }
  return {
    chat_completion_source: 'openai',
    reverse_proxy: normalizedBaseUrl || OFFICIAL_OPENAI_BASE_URL,
    proxy_password: apiKey,
  };
}

async function postToProxy(
  endpoint: string,
  body: Record<string, unknown>,
  signal?: AbortSignal,
): Promise<unknown> {
  const response = await fetch(endpoint, {
    method: 'POST',
    headers: getSillyTavernRequestHeaders(),
    credentials: 'include',
    cache: 'no-cache',
    ...(signal ? { signal } : {}),
    body: JSON.stringify(body),
  });
  const payload = await readPayload(response);
  if (!response.ok || hasProxyError(payload)) {
    const error = new Error(readProxyError(payload, `请求失败 (HTTP ${response.status})`));
    (error as Error & { status?: number }).status = response.status;
    logHttpFailure({
      stage: '酒馆代理补全',
      url: endpoint,
      status: response.status,
      statusText: response.statusText,
      body: payload,
    });
    throw error;
  }
  return payload;
}

async function fetchModelsDirectly(config: OpenAiCompatibleApiConfig): Promise<readonly ApiModelOption[]> {
  const baseUrl = resolveApiBaseUrl(config);
  const apiKey = config.apiKey.trim();
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (apiKey) headers.Authorization = apiKey.startsWith('Bearer ') ? apiKey : `Bearer ${apiKey}`;
  const response = await fetch(`${baseUrl}/models`, {
    method: 'GET',
    headers,
    signal: AbortSignal.timeout(MODELS_FETCH_TIMEOUT_MS),
  });
  const payload = await readPayload(response);
  if (!response.ok || hasProxyError(payload)) {
    logHttpFailure({
      stage: '模型列表获取',
      url: `${baseUrl}/models`,
      status: response.status,
      statusText: response.statusText,
      body: payload,
    });
    throw new Error(readProxyError(payload, `HTTP ${response.status}`));
  }
  return parseApiModels(payload);
}

function isRouteFallbackError(error: unknown): boolean {
  const status = (error as { status?: unknown } | null)?.status;
  return typeof status === 'number' && [400, 404, 405, 415, 422].includes(status);
}

function describeError(error: unknown): string {
  if (error instanceof DOMException && (error.name === 'TimeoutError' || error.name === 'AbortError')) {
    return '请求超时';
  }
  return error instanceof Error ? error.message : String(error ?? '未知错误');
}

/** 请求摘要：模型、通道与长度信息，用于日志定位；不包含密钥。 */
function describeApiRequest(
  config: OpenAiCompatibleApiConfig,
  request: ApiCompletionRequest,
  source?: ProxySource,
): Readonly<Record<string, unknown>> {
  return {
    baseUrl: config.baseUrl,
    model: config.model,
    stream: config.stream !== false,
    ...(source ? { source } : {}),
    temperature: request.temperature,
    // 键名避开 token 字样：输出预算不是密钥，被脱敏后无法排查「被截断」类故障。
    outputBudget: request.maxTokens,
    systemLength: request.system.length,
    userLength: request.user.length,
  };
}

async function readPayload(response: Response): Promise<unknown> {
  const text = await response.text();
  if (!text.trim()) return {};
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return { message: text.slice(0, 800) };
  }
}

function hasProxyError(payload: unknown): boolean {
  const record = asRecord(payload);
  return Boolean(record?.error);
}

function readProxyError(payload: unknown, fallback: string): string {
  const record = asRecord(payload);
  const error = record?.error;
  if (typeof error === 'string' && error.trim()) return error.trim();
  const nested = asRecord(error);
  const nestedMessage = String(nested?.message ?? '').trim();
  if (nestedMessage) return nestedMessage;
  const message = String(record?.message ?? '').trim();
  return message || fallback;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}
