/**
 * 表格 ↔ `stat_data` 的双向投影（纯函数）。
 *
 * 正向：表内容按映射拼成 `stat_data`，供前端状态栏、EJS 与 `{{getvar}}` 继续按老路子读。
 * 反向：旧脚本的 `_.set` 系命令按映射翻译成表格写入。
 *
 * 运行时的 `stat_data` 存纯值（描述只存在于世界书 InitVar 里），因此正向投影不还原二元组。
 */

import { parseCellValue, assignByPath, assignBySegments, mappingDynamic, resolveVariableTarget, type MvuMappingTarget } from './mapping.js';

import type { MvuMapping, MvuMappingEntry } from './types.js';

/** 表内容的最小形状：与 `SheetContent` 结构兼容，但不依赖数据库层。 */
export interface MvuSheetView {
  readonly id: string;
  readonly name: string;
  readonly columns: readonly string[];
  readonly rows: readonly { readonly rowId: number; readonly values: readonly string[] }[];
}

export interface MvuProjectionResult {
  readonly projectedPaths?: number;
  readonly statData: Record<string, unknown>;
  /** 映射里有、但表里读不到的路径（表被删或行被清空）。 */
  readonly missing: readonly string[];
}

export type MvuSheetWrite =
  | { readonly kind: 'delete'; readonly sheetId: string; readonly rowId: number }
  | { readonly kind: 'update'; readonly sheetId: string; readonly rowId: number; readonly values: Record<string, string> }
  | { readonly kind: 'insert'; readonly sheetId: string; readonly values: Record<string, string> };

export interface MvuWritePlan {
  readonly writes: readonly MvuSheetWrite[];
  /** 映射里找不到、或命令语义无法翻译的路径；调用方负责上报，不静默丢。 */
  readonly skipped: readonly { readonly path: string; readonly reason: string }[];
}

function viewByName(views: readonly MvuSheetView[], name: string): MvuSheetView | null {
  return views.find((view) => view.name === name) ?? null;
}

function findRow(
  view: MvuSheetView,
  entry: Pick<MvuMappingEntry, 'keyColumn' | 'keyValue'>,
  keyValue = entry.keyValue,
): { readonly rowId: number; readonly values: readonly string[] } | null {
  if (!entry.keyColumn) return view.rows[0] ?? null;
  const keyIndex = view.columns.indexOf(entry.keyColumn);
  if (keyIndex < 0) return null;
  return view.rows.find((row) => (row.values[keyIndex] ?? '') === keyValue) ?? null;
}

/** 表内容 → `stat_data`。读不到的路径记进 `missing`，不写占位值。 */
export function projectStatData(mapping: MvuMapping, views: readonly MvuSheetView[]): MvuProjectionResult {
  const statData: Record<string, unknown> = {};
  const missing: string[] = [];
  let projectedPaths = 0;
  const dynamicGroups = new Set<string>();
  for (const entry of mapping.entries) {
    const view = viewByName(views, entry.sheet);
    const dynamic = mappingDynamic(entry);
    if (dynamic && view) {
      const signature = JSON.stringify([entry.sheet, entry.column, dynamic]);
      if (!dynamicGroups.has(signature)) {
        dynamicGroups.add(signature);
        const keyIndex = view.columns.indexOf(entry.keyColumn);
        const columnIndex = view.columns.indexOf(entry.column);
        if (keyIndex < 0 || columnIndex < 0) { missing.push(entry.path); continue; }
        if (keyIndex >= 0 && columnIndex >= 0) {
          if (view.rows.length === 0 && dynamic.prefix.length) assignBySegments(statData, dynamic.prefix, {});
          for (const row of view.rows) {
            const key = row.values[keyIndex];
            if (!key) continue;
            assignBySegments(statData, [...dynamic.prefix, key, ...dynamic.field],
              parseCellValue(row.values[columnIndex] ?? entry.defaultValue ?? '', entry.valueType, entry.nullable));
            projectedPaths += 1;
          }
        }
      }
      if (entry.dynamic || view.rows.some((row) => row.values[view.columns.indexOf(entry.keyColumn)] === entry.keyValue)) continue;
    }
    if (entry.dynamic && view) continue;
    const row = view ? findRow(view, entry) : null;
    const columnIndex = view ? view.columns.indexOf(entry.column) : -1;
    if (!view || !row || columnIndex < 0) {
      if (view && !row && (entry.optional || dynamic)) continue;
      missing.push(entry.path);
      continue;
    }
    assignByPath(statData, entry.path, parseCellValue(row.values[columnIndex] ?? '', entry.valueType, entry.nullable));
    projectedPaths += 1;
  }
  return { statData, missing, projectedPaths };
}

/**
 * 未收录路径的动态解析：实体表里新增对象时，路径只有行键那一段不同。
 * 例如映射里有 `角色.络络.好感度`，脚本写 `角色.新人.好感度`，
 * 那就复用同一张表同一列，行键换成「新人」。
 */
export function resolveMappingTarget(
  mapping: MvuMapping,
  path: string,
): MvuMappingTarget | null {
  return resolveVariableTarget(mapping, path);
}


export { planCommandWrites } from './write-plan.js';
