import {
  isRecord,
  parseJsonObject,
  pickValue,
  readBoolean,
  readFlexibleRecordList,
  readFlexibleTextList,
  readText,
  unwrapJsonPayload,
} from './json.js';
import type { FanficNarrativeState } from './model.js';

export interface NarrativeScenePatch {
  readonly place: string;
  readonly time: string;
  readonly situation: string;
}

export interface NarrativePresencePatch {
  readonly name: string;
  readonly present: boolean;
  readonly posture: string;
  readonly holding: string;
  readonly mood: string;
}

export interface NarrativeShiftPatch {
  readonly from: string;
  readonly to: string;
  readonly summary: string;
}

export interface NarrativeSecretPatch {
  readonly text: string;
  readonly knownBy: readonly string[];
}

export interface NarrativeThreadPatch {
  readonly text: string;
  readonly owners: readonly string[];
}

export interface NarrativeDivergencePatch {
  readonly canon: string;
  readonly story: string;
}

/** 生成后状态补丁：只允许更新剧情事实，不能触及原著库。 */
export interface NarrativePatch {
  readonly scene: NarrativeScenePatch | null;
  readonly presence: readonly NarrativePresencePatch[];
  readonly shifts: readonly NarrativeShiftPatch[];
  readonly secrets: readonly NarrativeSecretPatch[];
  readonly promises: readonly NarrativeThreadPatch[];
  readonly openThreads: readonly NarrativeThreadPatch[];
  readonly resolved: readonly string[];
  readonly divergences: readonly NarrativeDivergencePatch[];
}

export interface NarrativePatchPromptInput {
  /** 本次新增的正文（含说话人与楼层号）。 */
  readonly transcript: string;
  readonly narrative: FanficNarrativeState;
  readonly characterNames: readonly string[];
}

export function buildNarrativePatchPrompt(
  input: NarrativePatchPromptInput,
): { readonly system: string; readonly user: string } {
  return {
    system: [
      '你是同人剧情状态跟踪器，不是聊天助手。只输出 JSON，不要解释。',
      '任务：读取新增正文，更新"进入下一轮时仍然成立"的剧情状态。',
      '字段：scene{place,time,situation}、presence[]、relationshipShifts[]、secrets[]、promises[]、openThreads[]、resolved[]、divergences[]。',
      'scene 写正文结束时所在的地点、剧情内时间与正在发生的场景。',
      'presence[] 为每个出场人物给出 name、present（正文结束时是否仍在场）、posture（最后的动作与位置）、holding（手中物品）、mood（情绪）。',
      'relationshipShifts[] 只记录本次正文中真实发生变化的关系，字段 from、to、summary。没有变化就给空数组。',
      'secrets[] 记录本次出现的秘密或未公开信息，knownBy 只填明确知道该信息的人物名。',
      'promises[] 记录新出现的约定或承诺；openThreads[] 记录新出现、尚未解决的悬念。',
      'resolved[] 填写本次正文中已经兑现或解决的约定/悬念原文，用于关闭旧条目。',
      'divergences[] 只在本次正文明确改写了原著既定事件时填写，canon 写原著版本，story 写本作版本。',
      '严禁写入推测、心理旁白或尚未发生的计划；没有内容的字段给空数组或空字符串。',
    ].join('\n'),
    user: [
      input.characterNames.length > 0 ? `已知人物：${input.characterNames.slice(0, 30).join('、')}` : '暂无已知人物名册。',
      `上一轮状态：\n${describeNarrative(input.narrative)}`,
      `新增正文：\n${input.transcript}`,
    ].join('\n\n'),
  };
}

function describeNarrative(narrative: FanficNarrativeState): string {
  const scene = narrative.scene;
  const rows = [
    `场景：${[scene.place, scene.time, scene.situation].filter(Boolean).join(' / ') || '（未知）'}`,
    `人物：${narrative.presence.map((presence) => `${presence.name}${presence.present ? '' : '(不在场)'}`).join('、') || '（无）'}`,
    `未完成约定：${narrative.threads.filter((thread) => thread.kind === 'promise' && !thread.resolved).map((thread) => thread.text).join('；') || '（无）'}`,
    `待解决伏笔：${narrative.threads.filter((thread) => thread.kind === 'open' && !thread.resolved).map((thread) => thread.text).join('；') || '（无）'}`,
    `秘密：${narrative.secrets.map((secret) => secret.text).join('；') || '（无）'}`,
  ];
  return rows.join('\n');
}

export function parseNarrativePatch(raw: string): NarrativePatch | null {
  const parsed = parseJsonObject(raw);
  if (!parsed) return null;
  const value = unwrapJsonPayload(parsed, [
    'scene', 'presence', 'relationshipShifts', 'secrets', 'promises', 'openThreads', 'resolved', 'divergences',
  ]);
  const scene = readScene(pickValue(value, ['scene', '场景']));
  const patch: NarrativePatch = {
    scene: scene && (scene.place || scene.time || scene.situation) ? scene : null,
    presence: readFlexibleRecordList(pickValue(value, ['presence', 'characters', '人物', '在场人物']), 16, {
      textKey: 'name',
      itemKeys: ['name', 'present', 'posture', 'holding', 'mood', '姓名'],
      keyField: 'name',
      keyValueKey: 'posture',
    }).flatMap((record) => {
      const name = readText(pickValue(record, ['name', 'character', '姓名', '角色']), 60);
      const present = pickValue(record, ['present', 'inScene', '在场']);
      return name
        ? [{
            name,
            present: present === undefined ? true : readBoolean(present),
            posture: readText(pickValue(record, ['posture', 'action', 'position', '动作', '位置']), 200),
            holding: readText(pickValue(record, ['holding', 'items', 'holds', '手持', '物品']), 120),
            mood: readText(pickValue(record, ['mood', 'emotion', 'feeling', '情绪']), 120),
          }]
        : [];
    }),
    shifts: readFlexibleRecordList(
      pickValue(value, ['relationshipShifts', 'relationship_shifts', 'shifts', '关系变化']),
      12,
      { textKey: 'summary' },
    ).flatMap((record) => {
      const summary = readText(pickValue(record, ['summary', 'change', 'description', '说明', '变化']), 300);
      return summary
        ? [{
            from: readText(pickValue(record, ['from', 'source', 'a', '主体']), 60),
            to: readText(pickValue(record, ['to', 'target', 'b', '对象']), 60),
            summary,
          }]
        : [];
    }),
    secrets: readFlexibleRecordList(pickValue(value, ['secrets', '秘密']), 12, { textKey: 'text' })
      .flatMap((record) => {
        const text = readText(pickValue(record, ['text', 'secret', 'content', '内容', '秘密']), 300);
        return text
          ? [{ text, knownBy: readFlexibleTextList(pickValue(record, ['knownBy', 'known_by', 'who', '知情人']), 12, 60) }]
          : [];
      }),
    promises: readThreads(pickValue(value, ['promises', 'promise', '约定', '承诺'])),
    openThreads: readThreads(pickValue(value, ['openThreads', 'open_threads', 'threads', '伏笔', '悬念'])),
    resolved: readFlexibleTextList(pickValue(value, ['resolved', 'closed', '已解决']), 12, 300),
    divergences: readFlexibleRecordList(pickValue(value, ['divergences', 'divergence', '差异', '改写']), 8)
      .flatMap((record) => {
        const canon = readText(pickValue(record, ['canon', 'original', '原著']), 300);
        const story = readText(pickValue(record, ['story', 'current', 'au', '本作']), 300);
        return canon && story ? [{ canon, story }] : [];
      }),
  };
  return isEmptyPatch(patch) ? null : patch;
}

/** scene 可能被写成对象或一句话；一句话时按「正在发生的场景」收下。 */
function readScene(value: unknown): NarrativeScenePatch | null {
  if (typeof value === 'string') {
    const situation = readText(value, 400);
    return situation ? { place: '', time: '', situation } : null;
  }
  if (!isRecord(value)) return null;
  return {
    place: readText(pickValue(value, ['place', 'location', '地点']), 120),
    time: readText(pickValue(value, ['time', 'clock', '时间']), 120),
    situation: readText(pickValue(value, ['situation', 'summary', 'description', '场景', '情况']), 400),
  };
}

function readThreads(value: unknown): readonly NarrativeThreadPatch[] {
  return readFlexibleRecordList(value, 12, { textKey: 'text' }).flatMap((record) => {
    const text = readText(pickValue(record, ['text', 'content', 'thread', 'promise', '内容']), 300);
    return text
      ? [{ text, owners: readFlexibleTextList(pickValue(record, ['owners', 'owner', 'who', '当事人']), 8, 60) }]
      : [];
  });
}

export function isEmptyPatch(patch: NarrativePatch): boolean {
  return patch.scene === null
    && patch.presence.length === 0
    && patch.shifts.length === 0
    && patch.secrets.length === 0
    && patch.promises.length === 0
    && patch.openThreads.length === 0
    && patch.resolved.length === 0
    && patch.divergences.length === 0;
}