import {
  derivePostTitle,
  type ForumBoard,
  type PhonePost,
  type PhonePostMetrics,
  type PhoneState,
} from '../../domain/model.js';

/** 卡里没写板块时的归属，界面上作为一个正常板块展示。 */
export const FORUM_DEFAULT_BOARD = '综合讨论';
/** 楼中楼最多缩进三级，再深的层级并到第三级，避免窄屏里挤成一条线。 */
const MAX_FLOOR_DEPTH = 2;

export type ForumSort = 'latest' | 'heat' | 'replies';

export interface ForumFloor {
  /** 帖子 id 或互动 id，仅用于渲染 key 与删除。 */
  readonly id: string;
  readonly entityType: 'post' | 'interaction';
  readonly profileId: string;
  readonly content: string;
  readonly createdAt: number;
  /** 正文里给出的相对时间文案（如「3分钟前」）。 */
  readonly timeLabel?: string;
  /** 楼层号：主楼下为 `2`、`3`，楼中楼为 `2-1`。 */
  readonly floor: string;
  readonly depth: number;
  readonly hot: boolean;
  /** 回复的上一层作者，用于「回复 @某人」。 */
  readonly parentProfileId?: string;
  /** 由帖子产生的楼层才有，互动评论没有；用于删除未回复的用户内容。 */
  readonly post?: PhonePost;
  readonly children: readonly ForumFloor[];
}

export interface ForumThreadView {
  readonly thread: PhonePost;
  readonly board: string;
  readonly title: string;
  readonly replyCount: number;
  readonly likes: number;
  readonly pinned: boolean;
  readonly hot: boolean;
  /** 排序与热榜用的热度；卡里给了公开计数时按计数折算。 */
  readonly heat: number;
  /** 热度是插件推算的（卡里没给任何公开计数）。 */
  readonly heatEstimated: boolean;
  readonly metrics: PhonePostMetrics;
  readonly floors: readonly ForumFloor[];
}

export interface ForumBoardView {
  readonly name: string;
  /** 登记过的板块记录；NPC/世界书写出的内容板块没有记录，首次编辑时才登记。 */
  readonly record?: ForumBoard;
  /** 板块说明：决定该板块后续生成的内容取向，只有登记过的板块才有。 */
  readonly description: string;
  readonly threadCount: number;
  readonly replyCount: number;
  /** 已登记或确实有帖子写着这个板块名；「综合讨论」兜底名不能改也不能删。 */
  readonly manageable: boolean;
}

export interface ForumIndexView {
  readonly threads: readonly ForumThreadView[];
  readonly boards: readonly ForumBoardView[];
  readonly totalReplies: number;
}

interface BoardAccumulator {
  readonly name: string;
  readonly record?: ForumBoard;
  threadCount: number;
  replyCount: number;
  /** 名字来自登记记录或帖子里真的写了，而不是缺省归属推出来的。 */
  explicit: boolean;
}

interface RawFloor {
  readonly id: string;
  readonly entityType: 'post' | 'interaction';
  readonly profileId: string;
  readonly content: string;
  readonly createdAt: number;
  readonly timeLabel?: string;
  readonly hot: boolean;
  readonly post?: PhonePost;
}

/**
 * 论坛列表与详情共用的一次性投影。
 * 主题、楼层、点赞都在同一轮遍历里归位，列表页不再为每个主题重扫全表。
 */
export function buildForumIndex(state: PhoneState): ForumIndexView {
  const threads: PhonePost[] = [];
  const floorsByParent = new Map<string, RawFloor[]>();
  for (const id of state.postOrder) {
    const post = state.posts[id];
    if (post?.appId !== 'forum') continue;
    if (post.kind === 'forum-thread') {
      threads.push(post);
      continue;
    }
    if (post.kind !== 'forum-reply') continue;
    const parentId = post.parentId ?? post.targetId;
    if (!parentId) continue;
    appendFloor(floorsByParent, parentId, {
      id: post.id,
      entityType: 'post',
      profileId: post.profileId,
      content: post.content,
      createdAt: post.createdAt,
      ...(post.timeLabel ? { timeLabel: post.timeLabel } : {}),
      hot: post.hot === true,
      post,
    });
  }

  const likesByTarget = new Map<string, number>();
  for (const interaction of Object.values(state.interactions)) {
    if (interaction.appId !== 'forum') continue;
    if (interaction.type === 'like') {
      likesByTarget.set(interaction.targetId, (likesByTarget.get(interaction.targetId) ?? 0) + 1);
      continue;
    }
    if (interaction.type !== 'comment' || !interaction.content?.trim()) continue;
    appendFloor(floorsByParent, interaction.targetId, {
      id: interaction.id,
      entityType: 'interaction',
      profileId: interaction.actorProfileId,
      content: interaction.content,
      createdAt: interaction.createdAt,
      hot: false,
    });
  }

  const boards = new Map<string, BoardAccumulator>();
  for (const record of Object.values(state.forumBoards)) {
    boards.set(forumBoardKey(record.name), { name: record.name, record, threadCount: 0, replyCount: 0, explicit: true });
  }
  const views = threads.map((thread) => {
    const board = forumBoardOf(thread);
    const accumulator = boards.get(forumBoardKey(board)) ?? { name: board, threadCount: 0, replyCount: 0, explicit: false };
    boards.set(forumBoardKey(board), accumulator);
    accumulator.threadCount += 1;
    if (thread.board?.trim()) accumulator.explicit = true;
    const stats = { count: 0, likes: likesByTarget.get(thread.id) ?? 0 };
    const floors = buildFloors(thread.id, null, 0, floorsByParent, likesByTarget, new Set([thread.id]), stats);
    accumulator.replyCount += stats.count;
    const heat = resolveHeat(thread, stats.count, stats.likes, state.worldClock.now);
    return {
      thread,
      board,
      title: forumTitleOf(thread),
      replyCount: stats.count,
      likes: stats.likes,
      pinned: thread.pinned === true,
      hot: thread.hot === true,
      heat: heat.value,
      heatEstimated: heat.estimated,
      metrics: thread.metrics ?? {},
      floors,
    } satisfies ForumThreadView;
  });

  return {
    threads: views,
    boards: [...boards.values()].map((accumulator) => ({
      name: accumulator.name,
      ...(accumulator.record ? { record: accumulator.record } : {}),
      description: accumulator.record?.description.trim() ?? '',
      threadCount: accumulator.threadCount,
      replyCount: accumulator.replyCount,
      manageable: accumulator.explicit,
    })),
    totalReplies: views.reduce((total, view) => total + view.replyCount, 0),
  };
}

export function forumBoardKey(name: string): string {
  return name.trim().toLocaleLowerCase('zh-CN');
}

export function sortForumThreads(
  threads: readonly ForumThreadView[],
  sort: ForumSort,
): readonly ForumThreadView[] {
  const ordered = [...threads];
  if (sort === 'heat') ordered.sort((left, right) => right.heat - left.heat || right.thread.createdAt - left.thread.createdAt);
  else if (sort === 'replies') ordered.sort((left, right) => right.replyCount - left.replyCount || right.thread.createdAt - left.thread.createdAt);
  else ordered.sort((left, right) => right.thread.createdAt - left.thread.createdAt);
  return ordered;
}

/** 置顶主题永远排在最前，其余保持传入顺序。 */
export function pinnedFirst(threads: readonly ForumThreadView[]): readonly ForumThreadView[] {
  return [...threads].sort((left, right) => Number(right.pinned) - Number(left.pinned));
}

export function forumBoardOf(thread: PhonePost): string {
  return thread.board?.trim() || FORUM_DEFAULT_BOARD;
}

/** 标题优先用卡里给的，其次用正文首行，避免列表里出现「未命名主题」。 */
export function forumTitleOf(post: PhonePost): string {
  const explicit = post.title?.trim();
  if (explicit) return truncateTitle(explicit);
  return truncateTitle(derivePostTitle(post.content) || '未命名主题');
}

function truncateTitle(value: string): string {
  return value.length > 42 ? `${value.slice(0, 42)}…` : value;
}

function appendFloor(floors: Map<string, RawFloor[]>, parentId: string, floor: RawFloor): void {
  const bucket = floors.get(parentId);
  if (bucket) bucket.push(floor);
  else floors.set(parentId, [floor]);
}

function buildFloors(
  parentId: string,
  parentFloorLabel: string | null,
  depth: number,
  floorsByParent: ReadonlyMap<string, readonly RawFloor[]>,
  likesByTarget: ReadonlyMap<string, number>,
  visited: Set<string>,
  stats: { count: number; likes: number },
  parentProfileId?: string,
): readonly ForumFloor[] {
  const bucket = [...(floorsByParent.get(parentId) ?? [])]
    .sort((left, right) => left.createdAt - right.createdAt || left.id.localeCompare(right.id));
  const nodes: ForumFloor[] = [];
  for (const raw of bucket) {
    if (visited.has(raw.id)) continue;
    visited.add(raw.id);
    stats.count += 1;
    stats.likes += likesByTarget.get(raw.id) ?? 0;
    const floorLabel = parentFloorLabel === null
      ? String(nodes.length + 2)
      : `${parentFloorLabel}-${nodes.length + 1}`;
    nodes.push({
      id: raw.id,
      entityType: raw.entityType,
      profileId: raw.profileId,
      content: raw.content,
      createdAt: raw.createdAt,
      ...(raw.timeLabel ? { timeLabel: raw.timeLabel } : {}),
      floor: floorLabel,
      depth: Math.min(MAX_FLOOR_DEPTH, depth),
      hot: raw.hot,
      ...(parentProfileId ? { parentProfileId } : {}),
      ...(raw.post ? { post: raw.post } : {}),
      children: buildFloors(
        raw.id,
        floorLabel,
        depth + 1,
        floorsByParent,
        likesByTarget,
        visited,
        stats,
        raw.profileId,
      ),
    });
  }
  return nodes;
}

/**
 * 热度只用于排序与热榜名次。卡里写了浏览/点赞/评论就按这些公开计数折算，
 * 只有一个计数都没有时才用「回复数 + 点赞 + 新鲜度」推算，并标记为估算。
 */
function resolveHeat(
  thread: PhonePost,
  replyCount: number,
  likes: number,
  now: number,
): { readonly value: number; readonly estimated: boolean } {
  const metrics = thread.metrics;
  const hasCardMetrics = metrics !== undefined
    && (metrics.views !== undefined || metrics.likes !== undefined || metrics.comments !== undefined);
  if (hasCardMetrics) {
    const value = (metrics?.views ?? 0)
      + (metrics?.likes ?? likes) * 3
      + (metrics?.comments ?? replyCount) * 10;
    return { value: Math.max(1, Math.round(value)), estimated: false };
  }
  const ageHours = Math.max(0, (now - thread.createdAt) / 3_600_000);
  const freshness = Math.max(0, Math.round(24 - Math.min(24, ageHours)));
  return { value: Math.max(1, 10 + replyCount * 10 + likes * 3 + freshness), estimated: true };
}