import { button, element } from './dom.js';

const previews = new WeakMap<HTMLElement, () => void>();

export function closeImagePreview(shell: HTMLElement): void {
  previews.get(shell)?.();
}

export function showImagePreview(origin: HTMLElement, src: string): void {
  const shell = origin.closest<HTMLElement>('.phone-shell');
  if (!shell) return;
  closeImagePreview(shell);
  const previous = shell.getRootNode() instanceof ShadowRoot
    ? (shell.getRootNode() as ShadowRoot).activeElement : document.activeElement;
  const overlay = element('div', { attributes: { role: 'dialog', 'aria-modal': 'true', 'aria-label': '图片预览' } });
  overlay.style.cssText = 'position:absolute;inset:0;z-index:10000;background:rgba(0,0,0,.94);display:flex;align-items:center;justify-content:center;overflow:hidden;border-radius:inherit;';
  const image = element('img', { attributes: { src, alt: '图片预览' } });
  image.style.cssText = 'max-width:100%;max-height:100%;object-fit:contain;';
  const close = (): void => {
    overlay.remove();
    previews.delete(shell);
    if (previous instanceof HTMLElement && previous.isConnected) previous.focus();
  };
  const dismiss = button('×', 'phone-image-preview-close', close);
  dismiss.setAttribute('aria-label', '关闭图片预览');
  dismiss.style.cssText = 'position:absolute;right:12px;top:12px;width:40px;height:40px;border:0;border-radius:50%;background:#333;color:#fff;font-size:28px;cursor:pointer;';
  overlay.addEventListener('click', (event) => event.stopPropagation());
  overlay.addEventListener('pointerdown', (event) => event.stopPropagation());
  overlay.addEventListener('keydown', (event) => {
    if (event.key === 'Escape') { event.preventDefault(); event.stopPropagation(); close(); }
    if (event.key === 'Tab') { event.preventDefault(); dismiss.focus(); }
  });
  overlay.append(image, dismiss);
  previews.set(shell, close);
  shell.append(overlay);
  dismiss.focus();
}