import type { AppId, ConversationKind, MessageKind, PhonePostMetrics, PostKind } from '../domain/model.js';

export type ParsedSpeakerRole = 'self' | 'other';
export type ParsedPhoneItemKind = 'message' | 'post' | 'interaction';

export interface ParsedPhoneAttachment {
  readonly kind: 'image' | 'video' | 'audio' | 'sticker' | 'transfer' | 'music';
  readonly value: string;
}

/** 与领域层同构：解析出来的计数原样落库，不做换算。 */
export type ParsedPhoneMetrics = PhonePostMetrics;

export interface ParsedPhoneItem {
  readonly appId: AppId;
  readonly itemKind: ParsedPhoneItemKind;
  readonly conversationKind: ConversationKind;
  readonly conversationKey: string;
  readonly speakerRole: ParsedSpeakerRole;
  readonly speakerName: string;
  readonly accountName?: string;
  readonly content: string;
  readonly title?: string;
  readonly postKind?: PostKind;
  /** 卡内提供的帖子/动态 ID，用于在同一解析批次内关联评论。 */
  readonly sourceEntityId?: string;
  /** 卡内提供的目标帖子/动态 ID。 */
  readonly targetEntityId?: string;
  /** 卡内提供的父级 ID（楼中楼回复的上一层）。 */
  readonly parentEntityId?: string;
  /** 论坛板块 / 频道名。 */
  readonly board?: string;
  readonly tags?: readonly string[];
  readonly pinned?: boolean;
  readonly hot?: boolean;
  readonly timeLabel?: string;
  readonly messageKind?: MessageKind;
  readonly attachments?: readonly ParsedPhoneAttachment[];
  readonly metrics?: ParsedPhoneMetrics;
  readonly sourceAdapterId: string;
  readonly sourceStart: number;
  readonly sourceEnd: number;
}

export function normalizeParsedContent(value: string): string {
  return value
    .replace(/\r\n?/g, '\n')
    .replace(/<br\s*\/?\s*>/gi, '\n')
    .replace(/\u0000/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

export function normalizeIdentity(value: string): string {
  return value.toLocaleLowerCase('zh-CN').replace(/^@+/, '').replace(/[^\p{L}\p{N}]+/gu, '');
}

export function isSelfSpeaker(value: string, userNames: readonly string[]): boolean {
  const normalized = normalizeIdentity(value);
  if (!normalized) return false;
  const generic = ['user', '用户', '玩家', '我', 'tuser', '你的名字', '{{user}}', '<user>'];
  return [...userNames, ...generic].some((name) => normalizeIdentity(name) === normalized);
}

export function parseInlineAttachments(content: string): {
  readonly content: string;
  readonly messageKind?: MessageKind;
  readonly attachments: readonly ParsedPhoneAttachment[];
} {
  const attachments: ParsedPhoneAttachment[] = [];
  let messageKind: MessageKind | undefined;
  const text = content.replace(/\[(bqb|zz|yy|music|img)-([^\]]+)]/gi, (_match, rawKind: string, rawValue: string) => {
    const kind = rawKind.toLocaleLowerCase('zh-CN');
    const value = rawValue.trim();
    if (kind === 'bqb') attachments.push({ kind: 'sticker', value });
    else if (kind === 'zz') {
      attachments.push({ kind: 'transfer', value });
      messageKind = 'transfer';
    } else if (kind === 'yy') attachments.push({ kind: 'audio', value });
    else if (kind === 'music') attachments.push({ kind: 'music', value });
    else {
      attachments.push({ kind: 'image', value });
      messageKind = 'image';
    }
    return `[${kind}-${value}]`;
  });
  return {
    content: normalizeParsedContent(text),
    ...(messageKind ? { messageKind } : {}),
    attachments,
  };
}

export function normalizeFingerprintText(value: string): string {
  return normalizeParsedContent(value)
    .normalize('NFKC')
    .toLocaleLowerCase('zh-CN')
    .replace(/[“”‘’]/g, '"')
    .replace(/[，。！？；：、]/g, (character) => ({
      '，': ',',
      '。': '.',
      '！': '!',
      '？': '?',
      '；': ';',
      '：': ':',
      '、': ',',
    })[character] ?? character)
    .replace(/\s+/g, ' ')
    .trim();
}

export function hashFingerprint(value: string): string {
  let hash = 2_166_136_261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16_777_619);
  }
  return (hash >>> 0).toString(36);
}

export function parsedItemFingerprint(item: ParsedPhoneItem): string {
  return [
    item.appId,
    item.itemKind,
    item.conversationKind,
    normalizeIdentity(item.conversationKey),
    item.speakerRole,
    normalizeIdentity(item.speakerName),
    normalizeFingerprintText(item.title ?? ''),
    normalizeFingerprintText(item.content),
  ].join('|');
}