import { memoryLabelOf, memorySourceOf, type MemoryItem, type MemorySource } from '../domain/model.js';
import type { StoryFloorSnapshot } from '../integration/sillytavern-bridge.js';
import type { GenerationPlan } from './batch-planner.js';

export interface RetrievedStoryContext {
  readonly id: string;
  readonly source: 'memory' | 'timeline';
  readonly content: string;
}

const DEFAULT_QUERY_LIMIT = 2_000;
/** 单条记忆注入提示词时的字符上限，避免一条长总结挤掉其他上下文。 */
const MEMORY_CONTENT_LIMIT = 1_600;

/**
 * 从已冻结的生成计划构造检索查询，避免批次开始后发件箱状态变化导致本轮内容丢失。
 * 查询同时保留会话对象、用户待处理内容与最新正文，以便记忆按当前剧情检索。
 */
export function buildGenerationRetrievalQuery(
  plan: GenerationPlan,
  recentStory: readonly StoryFloorSnapshot[] = [],
  charLimit = DEFAULT_QUERY_LIMIT,
): string {
  const sections = [
    ...plan.conversations.flatMap(({ conversation, participants, messages }) => {
      const participantNames = participants.map((profile) => profile.boundCharacter || profile.displayName).join('、');
      return [
        `【${conversation.title || conversation.appId}；参与者：${participantNames || '未知'}】`,
        ...messages.map((message) => `用户消息：${message.content.trim()}`),
      ];
    }),
    ...plan.queuedPosts.map(({ post }) => `【${post.appId}待处理动态】${post.content.trim()}`),
    ...recentStory.map((floor) => `【正文#${floor.floor} ${floor.name}】${floor.text.trim()}`),
  ].filter((section) => section.trim().length > 0);

  const limit = Math.max(200, Math.round(charLimit));
  return sections.join('\n').slice(-limit).trim();
}

export interface StoryMemoryContextBudget {
  /** 注入的正文记忆条数上限。 */
  readonly memoryLimit: number;
  /** 注入的总结（含手机总结）条数上限。 */
  readonly summaryLimit: number;
}

/**
 * 向量召回不可用时的确定性上下文：按来源分别取最新的正文记忆与总结，
 * 每条都带稳定的来源编号标签，让「已进入记忆库的楼层」仍然出现在生成上下文里。
 */
export function selectStoryMemoryContext(
  memoryItems: readonly MemoryItem[],
  scopeId: string,
  budget: StoryMemoryContextBudget,
): readonly RetrievedStoryContext[] {
  const memoryLimit = Math.max(0, Math.floor(budget.memoryLimit));
  const summaryLimit = Math.max(0, Math.floor(budget.summaryLimit));
  if (memoryLimit === 0 && summaryLimit === 0) return [];
  const usable = memoryItems.filter((item) => (
    item.scopeId === scopeId && !item.archived && item.content.trim().length > 0
  ));
  const bySource = (source: MemorySource, limit: number): readonly MemoryItem[] => (
    limit === 0 ? [] : usable.filter((item) => memorySourceOf(item) === source).slice(-limit)
  );
  // 总结预算在合并总结与手机总结之间分配：手机总结至少保留一条，其余给合并总结。
  const phoneShare = summaryLimit === 0 ? 0 : Math.max(1, Math.floor(summaryLimit / 2));
  const selected = [
    ...bySource('summary', summaryLimit - phoneShare),
    ...bySource('phone', phoneShare),
    ...bySource('memory', memoryLimit),
  ];
  return selected.map((item) => ({
    id: memoryLabelOf(item),
    source: 'memory' as const,
    content: item.content.trim().slice(0, MEMORY_CONTENT_LIMIT),
  }));
}

/** 合并向量召回与确定性补充：召回结果优先，缺口用最新记录补齐并按标签去重。 */
export function mergeStoryMemoryContext(
  retrieved: readonly RetrievedStoryContext[] | null,
  fallback: readonly RetrievedStoryContext[],
  limit: number,
): readonly RetrievedStoryContext[] {
  const merged: RetrievedStoryContext[] = [];
  const seen = new Set<string>();
  for (const entry of [...(retrieved ?? []), ...fallback]) {
    if (seen.has(entry.id) || !entry.content.trim()) continue;
    seen.add(entry.id);
    merged.push(entry);
    if (merged.length >= Math.max(1, Math.floor(limit))) break;
  }
  return merged;
}