import type { FanficActionResult, PhoneViewContext } from '../app-types.js';
import { button, element } from '../../ui/dom.js';

/** 同人剧情应用内的异步动作按钮：执行期间禁用并回显结果，成功后刷新页面。 */
export function fanficActionButton(
  context: PhoneViewContext,
  options: {
    readonly label: string;
    readonly title: string;
    readonly className?: string;
    readonly disabled?: boolean;
    readonly run: () => Promise<FanficActionResult>;
  },
): HTMLButtonElement {
  const trigger = button(
    options.label,
    options.className ?? 'phone-button phone-button-secondary phone-button-compact',
    async () => {
      trigger.disabled = true;
      trigger.textContent = '处理中…';
      try {
        const result = await options.run();
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) context.navigate('fanfic');
      } catch (error) {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      } finally {
        trigger.disabled = Boolean(options.disabled);
        trigger.textContent = options.label;
      }
    },
  );
  trigger.title = options.title;
  if (options.disabled) trigger.disabled = true;
  return trigger;
}

/** 状态行：左侧名称、右侧数值，值为空时显示占位。 */
export function fanficStatRow(label: string, value: string, ok = true): HTMLElement {
  const row = element('div', { className: `phone-fanfic-stat${ok ? '' : ' is-warn'}` });
  row.append(
    element('span', { className: 'phone-fanfic-stat-label', text: label }),
    element('strong', { className: 'phone-fanfic-stat-value', text: value || '—' }),
  );
  return row;
}

/** 折叠块：标题 + 明细列表，列表为空时不渲染。 */
export function fanficDetailBlock(title: string, lines: readonly string[]): HTMLElement | null {
  const usable = lines.map((line) => line.trim()).filter(Boolean);
  if (usable.length === 0) return null;
  const block = element('details', { className: 'phone-fanfic-block' });
  const summary = element('summary', { className: 'phone-fanfic-block-summary' });
  summary.append(
    element('strong', { text: title }),
    element('small', { text: `${usable.length} 条` }),
  );
  const body = element('div', { className: 'phone-fanfic-block-body' });
  for (const line of usable) body.append(element('p', { className: 'phone-fanfic-line', text: line }));
  block.append(summary, body);
  return block;
}