import type { PhoneState } from '../domain/model.js';
import {
  readVariables,
  type VariableScope,
  type VariablesSnapshot,
} from '../integration/variables-bridge.js';
import { createConditionSnapshot } from './evaluator.js';
import type { GenerationConditionContext } from './generation.js';
import type { ConditionLimits, ConditionValue } from './types.js';

export interface ConditionWorldBookSource {
  readonly available?: boolean;
  readonly books?: readonly string[];
  readonly names?: readonly string[];
  readonly excerpt?: string;
  readonly entries?: readonly { readonly name: string; readonly content?: string; readonly enabled?: boolean }[];
}

export interface ConditionContextOptions {
  readonly state?: PhoneState | null;
  readonly variables?: VariablesSnapshot | Readonly<Record<string, unknown>> | null;
  readonly variableScope?: VariableScope;
  readonly messageId?: number | null;
  readonly worldBook?: ConditionWorldBookSource | null;
  readonly appAccess?: Readonly<Record<string, boolean>> | null;
  readonly modules?: readonly { readonly id: string; readonly data: unknown }[];
  readonly now?: number | Date;
  readonly extra?: Readonly<Record<string, unknown>>;
  readonly limits?: ConditionLimits;
  readonly revision?: string | number;
  readonly scopeId?: string;
}

export function createConditionContext(options: ConditionContextOptions = {}): GenerationConditionContext {
  const state = options.state ?? null;
  const now = resolveTime(options.now, state?.worldClock.now ?? Date.now());
  const scopeId = options.scopeId ?? state?.scopeId ?? 'condition-scope';
  const revision = options.revision ?? state?.revision ?? now;
  const variables = variableData(options.variables);
  const worldBook = buildWorldBookData(options.worldBook);
  const data = {
    state: state ? {
      scopeId: state.scopeId,
      revision: state.revision,
      messageCount: state.messageOrder.length,
      postCount: state.postOrder.length,
      pendingCount: Object.values(state.outbox).filter((item) => item.status === 'queued').length,
    } : null,
    variables,
    time: timeData(now),
    apps: buildAppData(state, options.appAccess),
    worldBook,
    modules: Object.fromEntries((options.modules ?? []).map((module) => [module.id, module.data])),
    ...(options.extra ?? {}),
  } satisfies Record<string, unknown>;
  return {
    snapshot: createConditionSnapshot(scopeId, revision, data, options.limits),
  };
}

export async function readConditionContext(options: Omit<ConditionContextOptions, 'variables'> = {}): Promise<GenerationConditionContext> {
  const variables = await readVariables(options.variableScope ?? 'message', options.messageId ?? null);
  return createConditionContext({ ...options, variables });
}

export function buildConditionData(
  options: ConditionContextOptions = {},
): ConditionValue {
  return createConditionContext(options).snapshot.data;
}

function variableData(
  variables: ConditionContextOptions['variables'],
): Readonly<Record<string, unknown>> {
  if (!variables) return {};
  if ('data' in variables && variables.data && typeof variables.data === 'object') {
    return variables.data as Readonly<Record<string, unknown>>;
  }
  return variables as Readonly<Record<string, unknown>>;
}

function resolveTime(now: number | Date | undefined, fallback: number): number {
  const value = now instanceof Date ? now.getTime() : now ?? fallback;
  return Number.isFinite(value) ? value : fallback;
}

function timeData(now: number): Record<string, ConditionValue> {
  const date = new Date(now);
  return {
    now,
    iso: date.toISOString(),
    date: date.toISOString().slice(0, 10),
    hour: date.getHours(),
    minute: date.getMinutes(),
    weekday: date.getDay(),
  };
}

function buildWorldBookData(source: ConditionWorldBookSource | null | undefined): Record<string, ConditionValue> {
  const entries = (source?.entries ?? []).slice(0, 128).map((entry) => ({
    name: entry.name,
    content: entry.content ?? '',
    enabled: entry.enabled !== false,
  }));
  return {
    available: source?.available === true,
    books: [...(source?.books ?? [])].slice(0, 32),
    names: [...(source?.names ?? entries.map((entry) => entry.name))].slice(0, 128),
    entryCount: entries.length || source?.names?.length || 0,
    excerpt: source?.excerpt ?? '',
    entries,
  };
}

function buildAppData(
  state: PhoneState | null,
  access: Readonly<Record<string, boolean>> | null | undefined,
): Record<string, ConditionValue> {
  const appIds = new Set<string>(['wechat', 'forum', 'twitter', 'anonymous', 'calendar', 'diary', 'variables', 'memory', 'vector']);
  for (const key of Object.keys(access ?? {})) appIds.add(key);
  const result: Record<string, ConditionValue> = {};
  for (const appId of appIds) {
    const conversations = state
      ? Object.values(state.conversations).filter((conversation) => conversation.appId === appId)
      : [];
    const posts = state
      ? Object.values(state.posts).filter((post) => post.appId === appId)
      : [];
    const messages = state
      ? Object.values(state.messages).filter((message) => message.appId === appId)
      : [];
    result[appId] = {
      enabled: access?.[appId] !== false,
      conversationCount: conversations.length,
      postCount: posts.length,
      messageCount: messages.length,
      unreadCount: conversations.reduce((sum, item) => sum + item.unreadCount, 0),
    };
  }
  return result;
}