import { evaluateConditionGate, isActionAllowed } from '../conditions/generation.js';
import { logModelFailure } from '../core/diagnostics.js';
import type { GenerationConditionContext } from '../conditions/generation.js';
import type { ConditionSource } from '../conditions/types.js';
import { SELF_PROFILE_ID } from '../domain/commands.js';
import type { PhoneEvent } from '../domain/events.js';
import { createId, createScopedId, type IdFactory } from '../domain/ids.js';
import type {
  AppId,
  Conversation,
  PhoneMessage,
  PhonePost,
  PhoneState,
  Profile,
} from '../domain/model.js';
import { PhoneStore } from '../storage/phone-store.js';

import {
  AUTO_PARSE_ACTION_KINDS,
  AUTO_PARSE_MAX_ACTIONS,
  AUTO_PARSE_MAX_EXTENSION_ACTIONS,
  AUTO_PARSE_MAX_CONTENT_LENGTH,
  AUTO_PARSE_MAX_NAME_LENGTH,
  AUTO_PARSE_PROTOCOL_VERSION,
  AUTO_PARSE_RECENT_CONTENT_LIMIT,
} from './auto-parse-schema.js';
import type { AutoParseActionKind } from './auto-parse-schema.js';

export { AUTO_PARSE_RESPONSE_SCHEMA, buildAutoParseResponseSchema } from './auto-parse-schema.js';

export interface AutoParseAction {
  readonly kind: AutoParseActionKind;
  /** 正文中的角色正式名称；若正文只给出账号昵称，也可与 accountName 相同。 */
  readonly actorName: string;
  /** 微信昵称、推特昵称或推特号。 */
  readonly accountName?: string;
  /** 正文明确给出昵称与正式角色名的对应关系时填写。 */
  readonly boundCharacter?: string;
  readonly content: string;
}

export interface AutoParseExtensionProtocol {
  readonly moduleId: string;
  readonly name: string;
  readonly description: string;
  /** 扩展自身的正文格式与生成规则，原样注入自动解析提示词。 */
  readonly prompt?: string;
  /** 条件不满足时不向模型暴露该扩展的正文协议，并在应用阶段再次校验。 */
  readonly condition?: ConditionSource;
  readonly schema: Readonly<Record<string, unknown>>;
  /** 扩展自己的格式解析/归一化逻辑。 */
  readonly parse?: (value: unknown) => unknown;
  readonly validate?: (value: unknown) => boolean;
  readonly apply: (value: unknown, context: {
    readonly sourceFloors: readonly number[];
    readonly sourceText: string;
  }) => void | Promise<void>;
}

export interface AutoParseExtensionAction {
  readonly moduleId: string;
  readonly data: unknown;
}

export interface AutoParseResult {
  readonly actions: readonly AutoParseAction[];
  readonly extensionActions: readonly AutoParseExtensionAction[];
  readonly issues: readonly string[];
}

export interface AutoParseExecutionResult {
  readonly importedCount: number;
  readonly createdProfileCount: number;
  readonly createdConversationCount: number;
  readonly extensionImportedCount: number;
  readonly issues: readonly string[];
}

export interface AutoParseServiceOptions {
  readonly generate: (system: string, user: string) => Promise<string>;
  readonly extensionProtocols?: () => readonly AutoParseExtensionProtocol[];
  readonly conditionContextProvider?: () => GenerationConditionContext | null;
  readonly idFactory?: IdFactory;
}

/** 编译与解析共用的作用域参数；userNames 只在解析阶段用于判定私信收信人。 */
export interface AutoParseOptions {
  readonly disabledAppIds?: readonly string[];
  readonly extensionProtocols?: readonly AutoParseExtensionProtocol[];
  readonly userNames?: readonly string[];
}

const ACTION_KINDS = new Set<AutoParseActionKind>(AUTO_PARSE_ACTION_KINDS);

/** 私信只能落在「用户 ↔ 角色」的会话里，因此必须逐条确认收信人是用户本人。 */
const DIRECT_MESSAGE_KINDS = new Set<AutoParseActionKind>([
  'wechat.message',
  'twitter.message',
  'anonymous.message',
]);

/** 与人格名无关的通用用户代称。 */
const GENERIC_USER_NAMES = ['user', '用户', '玩家'] as const;

const AUTO_PARSE_SYSTEM_PROMPT = `你是“墨韵手机正文解析器”。你的唯一任务是从一批已经完成的 AI 正文中提取明确发生的手机行为，并返回严格 JSON。

只提取以下六类：
- wechat.message：非用户角色通过微信发给用户本人的私信
- wechat.moment：非用户角色已经发布的微信朋友圈
- twitter.message：非用户角色通过 Twitter/X 私信发给用户本人的消息
- twitter.post：非用户角色已经发布的 Twitter/X 动态
- forum.thread：非用户角色已经发布的论坛主题
- anonymous.message：匿名身份发给用户本人的匿名消息

私信三类（wechat.message / twitter.message / anonymous.message）只记录用户本人收到的内容，提取前必须先判定收信人并写入 recipient：
- 收信人是用户本人时 recipient 填 "user"。
- 收信人是其他角色时（亲友、同事、助理、第三方，或不包含用户的群聊），recipient 必须填那个收信角色的名字；这类记录会被忽略，绝不能改写成发给用户。
- 正文描述两个非用户角色之间互发消息、互相回复、或某角色替别人转达时，一律不要提取私信。
- 无法确定收信人是谁时 recipient 填 "unknown" 并不要提取该条。
- 朋友圈、Twitter 动态、论坛主题是公开广播，不需要 recipient。

先对每段手机相关叙述执行“新增行为/复述内容”判定，再决定是否提取：
- 新增行为：当前 aiMessage 的时间线上，角色在本段实际完成了输入、发送、回复或发布，并能确定本次新发出的内容。
- 复述内容：正文为了衔接剧情而回顾、引用、展示或概括此前已经存在的消息/帖子；它没有在当前叙事时点再次发送。
- “看见/读到/收到/想起/回忆/屏幕上显示/对方刚才说过/此前发过/已经回复过”等语境中的文字，默认都是历史内容或引用，不是本次新发送。
- user/用户发来的文字即使被角色阅读、引用或逐字展示，也绝不能改判为该角色的新消息。
- 同一段同时包含历史消息与新回复时，只提取明确的新回复。例如：“她拿起手机，看到了 user 回复的‘A’，想了想，给 user 回复了‘B’过去”只能提取 B，不能提取 A。
- 角色回想或复述自己先前发出的内容也不要再次提取。例如：“她想起自己刚才发过‘C’”不能输出 C。
- recentRecordedPhoneContent 是已经落库的手机内容，只用于判断复述。若正文只是再次叙述其中相同或近似的发送者与内容，不要重复输出；只有正文明确说明角色在当前时点“再次发送/重发”，且动作确实完成时，才可视为新增行为。
- aiMessage 含多个楼层时按楼层顺序判断；后一个楼层对前一个楼层行为的回顾只算复述，同一手机行为最多提取一次。
- 无法确定某段是在本次新发送还是仅复述时，保守地不提取，不得猜测。

规则：
1. 只提取正文中明确已经发生且包含实际内容的新增行为；计划、猜测、愿望、假设、转述、复述、引用、教程示例和被否定的行为不要提取。
2. 不得补写正文没有提供的消息或动态内容，不得把普通对话误判成手机消息；不得把角色看到的历史内容与随后新发出的内容拼接为一条消息。
3. 不提取 user/用户本人作为发送者的行为，也不得把 user 消息归到阅读它的角色名下；更不得把发给其他角色的私信改写成发给用户的私信。
4. actorName 优先写角色正式名称；accountName 写正文中的微信昵称、推特昵称或 @handle。
5. 只有正文明确说明昵称对应某正式角色时才填写 boundCharacter；不要猜测身份。
6. 没有可提取内容时 actions 返回空数组。
7. 只返回 JSON，不要 Markdown，不要解释。

以上“新增行为/复述内容”判定同样适用于 extensionActions。扩展应用的正文格式必须通过 extensionActions 返回，moduleId 必须来自 extensionApps；data 必须符合该扩展提供的 schema。没有在当前叙事时点明确新发生的扩展行为时不要输出 extensionActions。

输出格式：
{"version":1,"actions":[{"kind":"wechat.message|wechat.moment|twitter.message|twitter.post|forum.thread|anonymous.message","actorName":"角色名","accountName":"可选账号昵称","boundCharacter":"可选正式角色名","recipient":"私信收信人：user 或收信角色名","content":"正文中的实际新增内容"}],"extensionActions":[{"moduleId":"扩展 id","data":{}}]}`;

export function compileAutoParsePrompt(
  aiMessage: string,
  state: PhoneState,
  options: AutoParseOptions = {},
): { readonly system: string; readonly user: string } {
  const disabled = new Set(options.disabledAppIds ?? []);
  const extensionProtocols = options.extensionProtocols ?? [];
  const supportedKinds = [
    ...(!disabled.has('wechat') ? ['wechat.message', 'wechat.moment'] : []),
    ...(!disabled.has('twitter') ? ['twitter.message', 'twitter.post'] : []),
    ...(!disabled.has('forum') ? ['forum.thread'] : []),
    ...(!disabled.has('anonymous') ? ['anonymous.message'] : []),
  ];
  const contacts = Object.values(state.profiles)
    .filter((profile) => profile.id !== SELF_PROFILE_ID)
    .slice(0, 120)
    .map((profile) => ({
      displayName: profile.displayName,
      boundCharacter: profile.boundCharacter ?? '',
      wechat: profile.aliases.wechat ?? '',
      twitter: profile.aliases.twitter ?? '',
      twitterName: profile.twitterName ?? '',
    }));
  const recentRecordedPhoneContent = buildRecentRecordedPhoneContent(state);
  const extensionInstructions = extensionProtocols
    .map(({ moduleId, name, description, prompt, schema }) => [
      `扩展应用 ${name}（moduleId: ${moduleId}）`,
      `用途：${description}`,
      ...(prompt ? [`扩展自己的格式与生成规则：\n${prompt}`] : []),
      `extensionActions.data JSON Schema：\n${JSON.stringify(schema)}`,
    ].join('\n'))
    .join('\n\n');
  return {
    system: extensionInstructions
      ? `${AUTO_PARSE_SYSTEM_PROMPT}\n\n以下扩展格式规则由扩展应用自身声明，必须逐项遵守，不得用内置手机动作格式代替：\n\n${extensionInstructions}`
      : AUTO_PARSE_SYSTEM_PROMPT,
    user: JSON.stringify({
      task: '解析 aiMessage 中已经发生的手机行为；aiMessage 可能包含多层 AI 正文，existingContacts 只用于身份对齐，recentRecordedPhoneContent 只用于判定正文中的手机内容是新增行为还是对既有内容的复述。私信只能提取 userNames 里的人收到的内容。',
      supportedKinds,
      userNames: options.userNames ?? collectUserNames(state),
      existingContacts: contacts,
      recentRecordedPhoneContent,
      extensionApps: extensionProtocols.map(({ moduleId, name, description, prompt, schema }) => ({
        moduleId,
        name,
        description,
        ...(prompt ? { prompt } : {}),
        schema,
      })),
      aiMessage,
    }, null, 2),
  };
}

/** 用户本人的全部可识别称呼：人格名、绑定角色名、各应用账号名与通用代称。 */
export function collectUserNames(state: PhoneState): readonly string[] {
  const self = state.profiles[SELF_PROFILE_ID];
  const names = [
    self?.displayName ?? '',
    self?.boundCharacter ?? '',
    self?.twitterName ?? '',
    ...Object.values(self?.aliases ?? {}),
    ...GENERIC_USER_NAMES,
  ];
  return [...new Set(names.map((name) => String(name ?? '').trim()).filter(Boolean))];
}

function buildRecentRecordedPhoneContent(state: PhoneState): readonly Record<string, string>[] {
  const profiles = state.profiles;
  const messages = Object.values(state.messages).map((message) => ({
    createdAt: message.createdAt,
    app: message.appId,
    type: 'message',
    sender: message.direction === 'outgoing'
      ? (profiles[SELF_PROFILE_ID]?.displayName ?? '用户')
      : (profiles[message.profileId]?.boundCharacter ?? profiles[message.profileId]?.displayName ?? '未知角色'),
    direction: message.direction,
    content: message.content,
  }));
  const posts = Object.values(state.posts).map((post) => ({
    createdAt: post.createdAt,
    app: post.appId,
    type: post.kind,
    sender: profiles[post.profileId]?.boundCharacter ?? profiles[post.profileId]?.displayName ?? '未知角色',
    direction: 'published',
    content: post.title ? `${post.title}\n${post.content}` : post.content,
  }));
  return [...messages, ...posts]
    .sort((left, right) => right.createdAt - left.createdAt)
    .slice(0, AUTO_PARSE_RECENT_CONTENT_LIMIT)
    .map(({ createdAt: _createdAt, ...record }) => record);
}

export function parseAutoParseResponse(
  raw: string,
  options: AutoParseOptions = {},
): AutoParseResult {
  const parsed = parseJsonObject(raw);
  if (!parsed) return { actions: [], extensionActions: [], issues: ['模型没有返回 JSON 对象'] };
  if (parsed.version !== AUTO_PARSE_PROTOCOL_VERSION) return { actions: [], extensionActions: [], issues: ['自动解析协议版本不匹配'] };
  if (!Array.isArray(parsed.actions)) return { actions: [], extensionActions: [], issues: ['actions 必须是数组'] };

  const disabled = new Set(options.disabledAppIds ?? []);
  const extensionProtocols = options.extensionProtocols ?? [];
  const userNames = options.userNames ?? GENERIC_USER_NAMES;
  const actions: AutoParseAction[] = [];
  const issues: string[] = [];
  for (const [index, value] of parsed.actions.slice(0, AUTO_PARSE_MAX_ACTIONS).entries()) {
    const action = validateAction(value, disabled, userNames);
    if (typeof action === 'string') issues.push(`${index}: ${action}`);
    else actions.push(action);
  }
  if (parsed.actions.length > AUTO_PARSE_MAX_ACTIONS) issues.push(`动作超过 ${AUTO_PARSE_MAX_ACTIONS} 条，其余已忽略`);

  const protocols = new Map(extensionProtocols.map((protocol) => [protocol.moduleId, protocol]));
  const extensionActions: AutoParseExtensionAction[] = [];
  if (parsed.extensionActions !== undefined && !Array.isArray(parsed.extensionActions)) {
    issues.push('extensionActions 必须是数组，已忽略');
  } else if (Array.isArray(parsed.extensionActions)) {
    for (const [index, value] of parsed.extensionActions.slice(0, AUTO_PARSE_MAX_EXTENSION_ACTIONS).entries()) {
      const action = validateExtensionAction(value, protocols);
      if (typeof action === 'string') issues.push(`扩展 ${index}: ${action}`);
      else extensionActions.push(action);
    }
    if (parsed.extensionActions.length > AUTO_PARSE_MAX_EXTENSION_ACTIONS) issues.push(`扩展动作超过 ${AUTO_PARSE_MAX_EXTENSION_ACTIONS} 条，其余已忽略`);
  }
  return { actions, extensionActions, issues };
}

export async function applyAutoParseExtensionActions(
  actions: readonly AutoParseExtensionAction[],
  protocols: readonly AutoParseExtensionProtocol[],
  context: {
    readonly sourceFloors: readonly number[];
    readonly sourceText: string;
    /** 应用前重新读取的纯条件快照；缺失时拒绝带条件的扩展动作。 */
    readonly conditionContext?: GenerationConditionContext | null;
  },
): Promise<{ readonly importedCount: number; readonly issues: readonly string[] }> {
  const protocolMap = new Map(protocols.map((protocol) => [protocol.moduleId, protocol]));
  const issues: string[] = [];
  let importedCount = 0;
  for (const action of actions) {
    const protocol = protocolMap.get(action.moduleId);
    if (!protocol) continue;
    if (protocol.condition !== undefined) {
      if (!context.conditionContext || !evaluateConditionGate(protocol.condition, context.conditionContext)) {
        issues.push(`${protocol.name} 未通过应用阶段条件门控，已忽略`);
        continue;
      }
    }
    try {
      await protocol.apply(action.data, context);
      importedCount += 1;
    } catch (error) {
      issues.push(`${protocol.name} 写入失败：${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return { importedCount, issues };
}

export class AutoParseService {
  readonly #store: PhoneStore;
  readonly #generate: AutoParseServiceOptions['generate'];
  readonly #extensionProtocols: NonNullable<AutoParseServiceOptions['extensionProtocols']>;
  readonly #conditionContextProvider: (() => GenerationConditionContext | null) | null;
  readonly #idFactory: IdFactory;
  #running = false;

  constructor(store: PhoneStore, options: AutoParseServiceOptions) {
    this.#store = store;
    this.#generate = options.generate;
    this.#extensionProtocols = options.extensionProtocols ?? (() => []);
    this.#conditionContextProvider = options.conditionContextProvider ?? null;
    this.#idFactory = options.idFactory ?? createId;
  }

  get isRunning(): boolean {
    return this.#running;
  }

  async parseAndImport(
    aiMessage: string,
    sourceFloors: readonly number[],
    disabledAppIds: readonly string[] = [],
  ): Promise<AutoParseExecutionResult> {
    const text = aiMessage.trim();
    if (!text || sourceFloors.length === 0 || this.#running) return emptyExecutionResult();
    const extensionProtocols = this.#extensionProtocols();
    const conditionContext = this.#resolveConditionContext();
    if (this.#conditionContextProvider && !conditionContext) return emptyExecutionResult();
    const activeExtensionProtocols = conditionContext
      ? extensionProtocols.filter((protocol) => protocol.condition === undefined || evaluateConditionGate(protocol.condition, conditionContext))
      : extensionProtocols;
    const allSupportedAppsDisabled = ['wechat', 'twitter', 'forum', 'anonymous']
      .every((appId) => disabledAppIds.includes(appId));
    if (allSupportedAppsDisabled && activeExtensionProtocols.length === 0) return emptyExecutionResult();

    this.#running = true;
    try {
      const prompt = compileAutoParsePrompt(text, this.#store.state, { disabledAppIds, extensionProtocols: activeExtensionProtocols });
      const raw = await this.#generate(prompt.system, prompt.user);
      const parsed = parseAutoParseResponse(raw, {
        disabledAppIds,
        extensionProtocols: activeExtensionProtocols,
      });
      if (parsed.issues.length > 0 || (parsed.actions.length === 0 && parsed.extensionActions.length === 0)) {
        // 正文解析失败最常见的原因是模型没按协议输出，把原文留在日志里才能定位。
        logModelFailure({
          stage: '正文自动解析',
          reason: parsed.issues[0] ?? '模型没有提取到任何手机行为',
          raw,
          issues: parsed.issues,
          request: {
            sourceFloors,
            sourceLength: text.length,
            extensionProtocols: activeExtensionProtocols.map((protocol) => protocol.moduleId),
          },
        });
      }
      const allowedActions = conditionContext
        ? parsed.actions.filter((action) => isActionAllowed(action.kind, conditionContext))
        : parsed.actions;
      const sourceFloor = sourceFloors.at(-1) as number;
      const execution = buildAutoParseEvents(
        this.#store.state,
        allowedActions,
        sourceFloor,
        this.#idFactory,
      );
      if (execution.events.length > 0) await this.#store.dispatch(execution.events);
      const extensionExecution = await applyAutoParseExtensionActions(
        parsed.extensionActions,
        activeExtensionProtocols,
        { sourceFloors, sourceText: text, conditionContext: this.#resolveConditionContext() },
      );
      return {
        importedCount: execution.importedCount,
        createdProfileCount: execution.createdProfileCount,
        createdConversationCount: execution.createdConversationCount,
        extensionImportedCount: extensionExecution.importedCount,
        issues: [...parsed.issues, ...extensionExecution.issues],
      };
    } finally {
      this.#running = false;
    }
  }

  #resolveConditionContext(): GenerationConditionContext | null {
    if (!this.#conditionContextProvider) return null;
    try {
      const context = this.#conditionContextProvider();
      return context ? { ...context, snapshot: { ...context.snapshot } } : null;
    } catch {
      return null;
    }
  }
}

export function buildAutoParseEvents(
  initialState: PhoneState,
  actions: readonly AutoParseAction[],
  sourceFloor: number,
  idFactory: IdFactory,
): {
  readonly events: readonly PhoneEvent[];
  readonly importedCount: number;
  readonly createdProfileCount: number;
  readonly createdConversationCount: number;
} {
  const events: PhoneEvent[] = [];
  const profiles = new Map(Object.values(initialState.profiles).map((profile) => [profile.id, profile]));
  const conversations = new Map(Object.values(initialState.conversations).map((conversation) => [conversation.id, conversation]));
  const knownActionIds = new Set(initialState.appliedActionIds);
  const actionOccurrences = new Map<string, number>();
  let importedCount = 0;
  let createdProfileCount = 0;
  let createdConversationCount = 0;

  actions.forEach((action, index) => {
    const appId = appIdForKind(action.kind);
    const fingerprint = actionFingerprint(action);
    const occurrence = actionOccurrences.get(fingerprint) ?? 0;
    actionOccurrences.set(fingerprint, occurrence + 1);
    const actionId = buildActionId(action, occurrence);
    if (knownActionIds.has(actionId)) return;

    const resolved = resolveOrCreateProfile(initialState, profiles, action, appId, idFactory);
    if (resolved.event) {
      events.push(resolved.event);
      if (resolved.created) createdProfileCount += 1;
    }
    profiles.set(resolved.profile.id, resolved.profile);

    const createdAt = initialState.worldClock.now + index * 1_000;
    if (action.kind === 'wechat.message' || action.kind === 'twitter.message' || action.kind === 'anonymous.message') {
      const conversationResult = resolveOrCreateConversation(
        initialState,
        conversations,
        resolved.profile,
        appId,
        createdAt,
        idFactory,
      );
      if (conversationResult.event) {
        events.push(conversationResult.event);
        createdConversationCount += 1;
      }
      conversations.set(conversationResult.conversation.id, conversationResult.conversation);
      const message: PhoneMessage = {
        id: createScopedId(initialState.scopeId, 'auto-message', idFactory),
        scopeId: initialState.scopeId,
        appId,
        conversationId: conversationResult.conversation.id,
        profileId: resolved.profile.id,
        direction: 'incoming',
        content: action.content,
        metadata: { source: 'story-auto-parse', sourceFloor: String(sourceFloor) },
        status: 'sent',
        createdAt,
        actionId,
      };
      events.push(createEvent(initialState.scopeId, 'message.received', createdAt, { message }, idFactory, actionId));
    } else {
      const post: PhonePost = {
        id: createScopedId(initialState.scopeId, 'auto-post', idFactory),
        scopeId: initialState.scopeId,
        appId,
        kind: action.kind === 'wechat.moment'
          ? 'moment'
          : action.kind === 'forum.thread'
            ? 'forum-thread'
            : 'twitter-post',
        profileId: resolved.profile.id,
        content: action.content,
        createdAt,
        actionId,
      };
      events.push(createEvent(initialState.scopeId, 'post.created', createdAt, { post }, idFactory, actionId));
    }
    knownActionIds.add(actionId);
    importedCount += 1;
  });

  return { events, importedCount, createdProfileCount, createdConversationCount };
}

function resolveOrCreateProfile(
  state: PhoneState,
  profiles: ReadonlyMap<string, Profile>,
  action: AutoParseAction,
  appId: AppId,
  idFactory: IdFactory,
): { readonly profile: Profile; readonly event: PhoneEvent | null; readonly created: boolean } {
  const existing = findMatchingProfile(profiles.values(), action, appId);
  const accountName = cleanAccountName(action.accountName ?? '', appId);
  if (existing) {
    const aliases = { ...existing.aliases };
    const alias = accountName || aliases[appId] || existing.displayName;
    const actorName = cleanName(action.actorName);
    const inferredBoundCharacter = cleanName(action.boundCharacter ?? '')
      || (accountName && normalizeIdentity(accountName) !== normalizeIdentity(actorName) ? actorName : '');
    const boundCharacter = existing.boundCharacter || inferredBoundCharacter;
    const changed = aliases[appId] !== alias || (!existing.boundCharacter && Boolean(boundCharacter));
    if (!changed) return { profile: existing, event: null, created: false };
    aliases[appId] = alias;
    const profile: Profile = {
      ...existing,
      aliases,
      ...(boundCharacter ? { boundCharacter } : {}),
      updatedAt: state.worldClock.now,
    };
    return {
      profile,
      event: createEvent(state.scopeId, 'profile.upserted', state.worldClock.now, { profile }, idFactory),
      created: false,
    };
  }

  const actorName = cleanName(action.actorName);
  const explicitBoundCharacter = cleanName(action.boundCharacter ?? '');
  const displayName = (accountName || actorName).slice(0, 40);
  const inferredBoundCharacter = explicitBoundCharacter
    || (accountName && normalizeIdentity(accountName) !== normalizeIdentity(actorName) ? actorName : '');
  const profile: Profile = {
    id: createScopedId(state.scopeId, `auto-${appId}-profile`, idFactory),
    scopeId: state.scopeId,
    displayName,
    ...(inferredBoundCharacter ? { boundCharacter: inferredBoundCharacter.slice(0, 80) } : {}),
    aliases: { [appId]: accountName || displayName },
    replyDelay: { minimumMinutes: 2, maximumMinutes: 25 },
    activeHours: { startHour: 7, endHour: 23 },
    createdAt: state.worldClock.now,
    updatedAt: state.worldClock.now,
  };
  return {
    profile,
    event: createEvent(state.scopeId, 'profile.upserted', state.worldClock.now, { profile }, idFactory),
    created: true,
  };
}

function findMatchingProfile(
  profiles: Iterable<Profile>,
  action: AutoParseAction,
  appId: AppId,
): Profile | null {
  const candidates = [action.boundCharacter, action.actorName, action.accountName]
    .map((value) => normalizeIdentity(value ?? ''))
    .filter(Boolean);
  if (candidates.length === 0) return null;
  let aliasMatch: Profile | null = null;
  for (const profile of profiles) {
    if (profile.id === SELF_PROFILE_ID) continue;
    const formalNames = [profile.boundCharacter, profile.displayName, profile.twitterName]
      .map((value) => normalizeIdentity(value ?? ''))
      .filter(Boolean);
    if (candidates.some((candidate) => formalNames.includes(candidate))) return profile;
    const alias = normalizeIdentity(profile.aliases[appId] ?? '');
    if (alias && candidates.includes(alias)) aliasMatch = profile;
  }
  return aliasMatch;
}

function resolveOrCreateConversation(
  state: PhoneState,
  conversations: ReadonlyMap<string, Conversation>,
  profile: Profile,
  appId: AppId,
  createdAt: number,
  idFactory: IdFactory,
): { readonly conversation: Conversation; readonly event: PhoneEvent | null } {
  const existing = [...conversations.values()].find((conversation) =>
    conversation.appId === appId
    && conversation.kind === (appId === 'anonymous' ? 'anonymous' : 'direct')
    && conversation.participantIds.includes(SELF_PROFILE_ID)
    && conversation.participantIds.includes(profile.id));
  if (existing) return { conversation: existing, event: null };

  const alias = profile.aliases[appId] ?? profile.displayName;
  const conversation: Conversation = {
    id: createScopedId(state.scopeId, `auto-${appId}-conversation`, idFactory),
    scopeId: state.scopeId,
    appId,
    kind: appId === 'anonymous' ? 'anonymous' : 'direct',
    title: appId === 'twitter' && alias !== profile.displayName
      ? `${profile.twitterName ?? profile.displayName} ${alias}`.slice(0, 80)
      : alias.slice(0, 80),
    participantIds: [SELF_PROFILE_ID, profile.id],
    unreadCount: 0,
    muted: false,
    createdAt,
    updatedAt: createdAt,
  };
  return {
    conversation,
    event: createEvent(state.scopeId, 'conversation.upserted', createdAt, { conversation }, idFactory),
  };
}

function validateExtensionAction(
  value: unknown,
  protocols: ReadonlyMap<string, AutoParseExtensionProtocol>,
): AutoParseExtensionAction | string {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return '动作必须是对象';
  const record = value as Record<string, unknown>;
  const moduleId = String(record.moduleId ?? '').trim();
  const protocol = protocols.get(moduleId);
  if (!protocol) return '模块不存在、未启用或未声明自动解析协议';
  if (!('data' in record)) return '缺少 data';
  if (!matchesJsonSchema(record.data, protocol.schema)) return `data 不符合 ${protocol.name} 的 schema`;
  try {
    const parsedData = protocol.parse ? protocol.parse(record.data) : record.data;
    if (parsedData === undefined) return `${protocol.name} 的格式解析器未返回数据`;
    if (protocol.validate && !protocol.validate(parsedData)) return `data 未通过 ${protocol.name} 的自定义校验`;
    return { moduleId, data: structuredClone(parsedData) };
  } catch (error) {
    return `${protocol.name} 格式解析失败：${error instanceof Error ? error.message : String(error)}`;
  }
}

function matchesJsonSchema(value: unknown, schema: Readonly<Record<string, unknown>>): boolean {
  if ('const' in schema && !Object.is(value, schema.const)) return false;
  if (Array.isArray(schema.enum) && !schema.enum.some((item) => JSON.stringify(item) === JSON.stringify(value))) return false;
  const types = Array.isArray(schema.type) ? schema.type : [schema.type].filter(Boolean);
  if (types.length > 0 && !types.some((type) => matchesJsonType(value, String(type)))) return false;
  if (value === null) return true;

  if (typeof value === 'string') {
    if (Number.isFinite(Number(schema.minLength)) && value.length < Number(schema.minLength)) return false;
    if (Number.isFinite(Number(schema.maxLength)) && value.length > Number(schema.maxLength)) return false;
    if (typeof schema.pattern === 'string') {
      try {
        if (!new RegExp(schema.pattern).test(value)) return false;
      } catch {
        return false;
      }
    }
  }
  if (typeof value === 'number') {
    if (Number.isFinite(Number(schema.minimum)) && value < Number(schema.minimum)) return false;
    if (Number.isFinite(Number(schema.maximum)) && value > Number(schema.maximum)) return false;
  }
  if (Array.isArray(value)) {
    if (Number.isFinite(Number(schema.minItems)) && value.length < Number(schema.minItems)) return false;
    if (Number.isFinite(Number(schema.maxItems)) && value.length > Number(schema.maxItems)) return false;
    if (schema.items && typeof schema.items === 'object' && !Array.isArray(schema.items)) {
      if (!value.every((item) => matchesJsonSchema(item, schema.items as Readonly<Record<string, unknown>>))) return false;
    }
  }
  if (value && typeof value === 'object' && !Array.isArray(value)) {
    const record = value as Record<string, unknown>;
    const required = Array.isArray(schema.required) ? schema.required.map(String) : [];
    if (required.some((key) => !(key in record))) return false;
    const properties = schema.properties && typeof schema.properties === 'object' && !Array.isArray(schema.properties)
      ? schema.properties as Record<string, unknown>
      : {};
    if (schema.additionalProperties === false && Object.keys(record).some((key) => !(key in properties))) return false;
    for (const [key, propertySchema] of Object.entries(properties)) {
      if (!(key in record)) continue;
      if (!propertySchema || typeof propertySchema !== 'object' || Array.isArray(propertySchema)) return false;
      if (!matchesJsonSchema(record[key], propertySchema as Readonly<Record<string, unknown>>)) return false;
    }
  }
  return true;
}

function matchesJsonType(value: unknown, type: string): boolean {
  if (type === 'null') return value === null;
  if (type === 'array') return Array.isArray(value);
  if (type === 'object') return Boolean(value && typeof value === 'object' && !Array.isArray(value));
  if (type === 'integer') return typeof value === 'number' && Number.isInteger(value);
  return typeof value === type;
}

function validateAction(
  value: unknown,
  disabled: ReadonlySet<string>,
  userNames: readonly string[],
): AutoParseAction | string {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return '动作必须是对象';
  const record = value as Record<string, unknown>;
  const kind = String(record.kind ?? '') as AutoParseActionKind;
  if (!ACTION_KINDS.has(kind)) return '动作类型不受支持';
  const appId = appIdForKind(kind);
  if (disabled.has(appId)) return '目标应用已停用';
  const actorName = cleanName(record.actorName);
  if (!actorName) return '角色名称为空或过长';
  if (isUserIdentity(actorName, userNames)) return '不能导入用户本人作为发送者';
  const recipientIssue = checkDirectMessageRecipient(kind, record, userNames);
  if (recipientIssue) return recipientIssue;
  const content = cleanContent(record.content);
  if (!content) return '内容为空或过长';
  const accountName = cleanName(record.accountName);
  const boundCharacter = cleanName(record.boundCharacter);
  return {
    kind,
    actorName,
    ...(accountName ? { accountName } : {}),
    ...(boundCharacter ? { boundCharacter } : {}),
    content,
  };
}

/**
 * 私信最终写进「用户 ↔ 角色」的会话，收信人必须是用户本人。
 * 模型标注了其他角色（两个非用户角色互发、发给第三方）或标注不明时直接丢弃本条。
 */
function checkDirectMessageRecipient(
  kind: AutoParseActionKind,
  record: Record<string, unknown>,
  userNames: readonly string[],
): string | null {
  if (!DIRECT_MESSAGE_KINDS.has(kind)) return null;
  const recipient = cleanName(record.recipient ?? record.targetName ?? record.receiver);
  if (!recipient || isUserIdentity(recipient, userNames)) return null;
  if (normalizeIdentity(recipient) === 'unknown') return '私信收信人无法确认，已忽略';
  return `私信收信人是「${recipient}」而不是用户本人，已忽略`;
}

function appIdForKind(kind: AutoParseActionKind): AppId {
  if (kind.startsWith('wechat.')) return 'wechat';
  if (kind.startsWith('twitter.')) return 'twitter';
  if (kind.startsWith('forum.')) return 'forum';
  return 'anonymous';
}

function cleanName(value: unknown): string {
  if (typeof value !== 'string') return '';
  const result = value.replace(/\u0000/g, '').trim().slice(0, 80);
  return result.length <= 80 ? result : '';
}

function cleanAccountName(value: string, appId: AppId): string {
  const name = cleanName(value).slice(0, 40);
  if (!name || appId !== 'twitter' || name.startsWith('@')) return name;
  return `@${name.replace(/^@+/, '')}`;
}

function cleanContent(value: unknown): string {
  if (typeof value !== 'string') return '';
  const result = value.replace(/\u0000/g, '').trim();
  return result.length > 0 && result.length <= AUTO_PARSE_MAX_CONTENT_LENGTH ? result : '';
}

function normalizeIdentity(value: string): string {
  return value.toLocaleLowerCase('zh-CN').replace(/^@+/, '').replace(/[^\p{L}\p{N}]+/gu, '');
}

function isUserIdentity(value: string, userNames: readonly string[] = GENERIC_USER_NAMES): boolean {
  const normalized = normalizeIdentity(value);
  if (!normalized) return false;
  return userNames.some((name) => normalizeIdentity(name) === normalized);
}

function parseJsonObject(raw: string): Record<string, unknown> | null {
  const trimmed = String(raw ?? '').trim();
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/i.exec(trimmed);
  const candidate = fenced?.[1] ?? trimmed;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    const value = JSON.parse(candidate.slice(start, end + 1));
    return value && typeof value === 'object' && !Array.isArray(value)
      ? value as Record<string, unknown>
      : null;
  } catch {
    return null;
  }
}

function actionFingerprint(action: AutoParseAction): string {
  return [
    action.kind,
    normalizeIdentity(action.actorName),
    normalizeIdentity(action.accountName ?? ''),
    normalizeIdentity(action.boundCharacter ?? ''),
    action.content.normalize('NFKC').replace(/\s+/g, ' ').trim().toLocaleLowerCase('zh-CN'),
  ].join('|');
}

function buildActionId(action: AutoParseAction, occurrence: number): string {
  const source = `${actionFingerprint(action)}|${occurrence}`;
  let hash = 2_166_136_261;
  for (const character of source) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16_777_619);
  }
  return `auto-parse:${(hash >>> 0).toString(36)}`;
}

function createEvent<TType extends PhoneEvent['type']>(
  scopeId: string,
  type: TType,
  occurredAt: number,
  payload: Extract<PhoneEvent, { readonly type: TType }>['payload'],
  idFactory: IdFactory,
  actionId?: string,
): Extract<PhoneEvent, { readonly type: TType }> {
  return {
    id: createScopedId(scopeId, 'auto-parse-event', idFactory),
    scopeId,
    type,
    occurredAt,
    payload,
    ...(actionId ? { actionId } : {}),
  } as Extract<PhoneEvent, { readonly type: TType }>;
}

function emptyExecutionResult(): AutoParseExecutionResult {
  return {
    importedCount: 0,
    createdProfileCount: 0,
    createdConversationCount: 0,
    extensionImportedCount: 0,
    issues: [],
  };
}