import { memoryLabelOf, type MemoryItem } from '../domain/model.js';
import { measureFloorChars, type StoryFloorSnapshot } from '../integration/sillytavern-bridge.js';
import { formatWorldTime } from '../time/world-clock.js';
import {
  isLikelyModelRefusal,
  requireUsableGeneratedText,
  sanitizeStoryText,
} from './content-safety.js';

/** 一次摘要任务：一批楼层（含穿插的用户楼层），以最后一个 AI 楼层收尾。 */
export interface MemoryFloorBatch {
  readonly floors: readonly StoryFloorSnapshot[];
  readonly floorFrom: number;
  readonly floorTo: number;
}

export interface MemoryBatchSelectionOptions {
  readonly includeRemainder?: boolean;
  readonly deferLatestAi?: boolean;
  /** 正文截断值：批次正文不足该字数时不收口，继续与后续楼层累积（0 = 不限制）。 */
  readonly minChars?: number;
}

/**
 * 把未整理的楼层按「每 X 条 AI 回复一份摘要」分批。
 * 自动模式可排除最新 AI 楼层，等下一条 AI 回复出现后再整理。
 * 正文字数不足截断值的批次不收口，留给下一轮与新楼层合并，避免为几十字的短楼层调用模型。
 */
export function selectMemoryBatches(
  floors: readonly StoryFloorSnapshot[],
  everyAiMessages: number,
  options: boolean | MemoryBatchSelectionOptions = false,
): readonly MemoryFloorBatch[] {
  const includeRemainder = typeof options === 'boolean' ? options : options.includeRemainder === true;
  const deferLatestAi = typeof options === 'object' && options.deferLatestAi === true;
  const minChars = typeof options === 'object' ? Math.max(0, Math.trunc(options.minChars ?? 0)) : 0;
  const latestAiIndex = deferLatestAi ? findLatestAiIndex(floors) : -1;
  const eligibleFloors = latestAiIndex >= 0 ? floors.slice(0, latestAiIndex) : floors;
  const interval = Math.max(1, Math.round(everyAiMessages));
  const batches: MemoryFloorBatch[] = [];
  let current: StoryFloorSnapshot[] = [];
  let aiCount = 0;
  for (const floor of eligibleFloors) {
    current.push(floor);
    if (floor.role !== 'ai') continue;
    aiCount += 1;
    if (aiCount < interval || measureFloorChars(current) < minChars) continue;
    batches.push(buildBatch(current));
    current = [];
    aiCount = 0;
  }
  if (includeRemainder && current.some((floor) => floor.role === 'ai')) {
    batches.push(buildBatch(current));
  }
  return batches;
}

function findLatestAiIndex(floors: readonly StoryFloorSnapshot[]): number {
  for (let index = floors.length - 1; index >= 0; index -= 1) {
    if (floors[index]?.role === 'ai') return index;
  }
  return -1;
}

function buildBatch(floors: readonly StoryFloorSnapshot[]): MemoryFloorBatch {
  const first = floors[0]!;
  const last = floors[floors.length - 1]!;
  return { floors, floorFrom: first.floor, floorTo: last.floor };
}

export interface MemoryPrompt {
  readonly system: string;
  readonly user: string;
}

/**
 * 受控模板替换：只识别白名单变量，其余 `{{...}}` 原样保留。
 * 模板只替换系统提示词，数据始终以用户消息传入，避免自定义内容影响解析协议。
 */
export function applyPromptTemplate(
  template: string,
  variables: Readonly<Record<string, string>>,
): string {
  return template.replace(/\{\{\s*([A-Za-z][A-Za-z0-9_]*)\s*\}\}/g, (match, name: string) => {
    const value = variables[name];
    return value === undefined ? match : value;
  });
}

/** 楼层记忆提示词：可读、不丢细节，同时提取时间线事件。 */
export function buildFloorMemoryPrompt(input: {
  readonly userName: string;
  readonly floors: readonly StoryFloorSnapshot[];
  readonly extractTimeline: boolean;
  readonly currentTime?: number;
  /** 自定义系统提示词模板；留空使用默认提示词。 */
  readonly template?: string;
}): MemoryPrompt {
  const defaultSystem = [
    '你是剧情档案员，负责把一段角色扮演正文整理成结构化记忆。',
    '输入中可能包含模型思考链、插件日志、生图提示词或安全拒绝文本；这些都不是剧情正文，必须忽略。',
    '如果输入没有可识别的剧情正文，summary 必须为空字符串，events 必须为空数组；不要把拒绝说明、错误对象或提示词改写成剧情。',
    '要求：',
    '- summary：把这段正文梳理成一份可读、连贯且不丢细节的摘要。必须保留：出场人物与称呼、地点场景、关键对话要点、行动与结果、'
      + '获得或失去的物品/金钱/能力、达成的约定与承诺、人物关系与情绪的变化、明确提到的时间。禁止评价与臆测，禁止流水账式逐句复述。',
    ...(input.extractTimeline
      ? ['- events：只提取 1 条时间线事件；用 2~4 句连贯文字概括本批正文的大致剧情，必须写清背景、关键人物、主要行动、结果或关系变化。'
        + 'time 用正文里的剧情时间（如「8月12日 下午」）；正文没写时间就用空字符串。没有可记录的剧情时给空数组。']
      : []),
    '只输出一个 JSON 对象，不要 Markdown 代码块或其他文字：',
    input.extractTimeline
      ? '{"summary":"...","events":[{"time":"...","text":"背景、行动、结果与变化..."}]}'
      : '{"summary":"..."}',
  ].join('\n');

  const currentTimeLine = formatWorldTime(input.currentTime ?? Date.now());
  const floorLines = input.floors
    .map((floor) => {
      const phoneLine = floor.phoneText?.trim() ? `\n[手机互动记录]\n${floor.phoneText.trim()}` : '';
      return `#${floor.floor}【${floor.role === 'user' ? `${input.userName}（用户）` : floor.name}】${floor.text}${phoneLine}`;
    })
    .join('\n\n');
  const user = `需要整理的正文楼层：\n\n${floorLines}`;
  const template = input.template?.trim();
  if (!template) return { system: defaultSystem, user };
  const outputFormat = input.extractTimeline
    ? '{"summary":"...","events":[{"time":"...","text":"..."}]}'
    : '{"summary":"..."}';
  const system = [
    applyPromptTemplate(template, {
      user: input.userName,
      time: currentTimeLine,
      floors: floorLines,
      floorRange: describeFloorRange(input.floors),
      format: outputFormat,
    }),
    // 解析协议由插件负责，自定义提示词不能改掉输出格式。
    `无论上面如何要求，只输出一个 JSON 对象：${outputFormat}`,
  ].join('\n\n');
  return { system, user };
}

function describeFloorRange(floors: readonly StoryFloorSnapshot[]): string {
  const first = floors[0];
  const last = floors[floors.length - 1];
  return first && last ? `${first.floor}-${last.floor}` : '';
}

export interface ParsedFloorMemory {
  readonly summary: string;
  readonly events: readonly { readonly time: string; readonly text: string }[];
  readonly rejected: boolean;
}

/** 解析摘要响应：拒绝/错误响应直接视为空结果，避免污染记忆库；普通纯文本仍兼容为摘要。 */
export function parseFloorMemoryResponse(raw: string): ParsedFloorMemory {
  const rejected = isLikelyModelRefusal(raw);
  const empty: ParsedFloorMemory = { summary: '', events: [], rejected };
  const fallbackText = sanitizeStoryText(raw);
  if (!fallbackText || rejected) return empty;

  const start = fallbackText.indexOf('{');
  const end = fallbackText.lastIndexOf('}');
  if (start < 0 || end <= start) return { summary: fallbackText, events: [], rejected: false };
  try {
    const parsed = JSON.parse(fallbackText.slice(start, end + 1)) as {
      summary?: unknown;
      events?: unknown;
    };
    const summary = typeof parsed.summary === 'string' ? sanitizeStoryText(parsed.summary) : '';
    if (!summary || isLikelyModelRefusal(summary)) return { summary: '', events: [], rejected: true };
    const events = Array.isArray(parsed.events)
      ? parsed.events
        .map((entry) => {
          const record = entry as Record<string, unknown> | null;
          const text = sanitizeStoryText(String(record?.text ?? ''), 900);
          return {
            time: sanitizeStoryText(String(record?.time ?? ''), 60),
            text,
          };
        })
        .filter((entry) => entry.text.length > 0 && !isLikelyModelRefusal(entry.text))
        .slice(0, 4)
      : [];
    return { summary, events, rejected: false };
  } catch {
    return { summary: fallbackText, events: [], rejected: false };
  }
}

/** 只统计清洗后的正文，协议包装和空白不计入最低长度。 */
export function requireUsableMemoryText(raw: string, label: string): string {
  const content = requireUsableGeneratedText(raw, label);
  const length = Array.from(content.replace(/<[^>]*>/g, '').replace(/\s/g, '')).length;
  if (length < 100) throw new Error(`${label}不足 100 字（${length} 字），视为拒答。`);
  return content;
}

/** API 响应校验器：拒绝、空摘要与短摘要进入请求层的有限重试。 */
export function isUsableFloorMemoryResponse(raw: string): boolean {
  const parsed = parseFloorMemoryResponse(raw);
  if (parsed.rejected) return false;
  try {
    requireUsableMemoryText(parsed.summary, '记忆摘要');
    return true;
  } catch {
    return false;
  }
}

/** 把一批摘要事件合并为一条可读时间线，避免同一批正文被拆成多个相同楼层卡片。 */
export function mergeTimelineEvent(
  summary: string,
  events: readonly { readonly time: string; readonly text: string }[],
): { readonly time: string; readonly text: string } | null {
  const cleanedSummary = sanitizeStoryText(summary, 900);
  const uniqueEvents: string[] = [];
  const seen = new Set<string>();
  for (const event of events) {
    const text = sanitizeStoryText(event.text, 900);
    const key = text.replace(/[\s，。！？、；：,.!?;:]+/g, '').toLowerCase();
    if (!text || isLikelyModelRefusal(text) || seen.has(key)) continue;
    seen.add(key);
    uniqueEvents.push(text);
  }
  const time = events.map((event) => sanitizeStoryText(event.time, 60)).find(Boolean) ?? '';
  const eventText = uniqueEvents.join('；');
  const text = cleanedSummary.length > eventText.length
    ? cleanedSummary
    : eventText || cleanedSummary;
  if (!text || isLikelyModelRefusal(text)) return null;
  return { time, text };
}

/** 总结提示词：把多份记忆合并成一份总结，保留关键事实。 */
export function buildConsolidationPrompt(items: readonly MemoryItem[], template?: string): MemoryPrompt {
  const defaultSystem = [
    '你是剧情档案员，请把多份剧情记忆合并成一份总结。',
    '- 按时间顺序组织；保留关键事件、人物关系变化、重要约定、获得/失去的东西、未解决的伏笔。',
    '- 相同事件去重，次要细节可压缩，但不得遗漏影响后续剧情的事实。',
    '- 只输出总结正文纯文本，不要标题、编号列表符号或 Markdown。',
  ].join('\n');
  const memories = items
    .map((item) => `【${memoryLabelOf(item)}（楼层 ${item.floorFrom}-${item.floorTo}）】\n${item.content}`)
    .join('\n\n');
  const custom = template?.trim();
  const system = custom
    ? [
        applyPromptTemplate(custom, { memories, count: String(items.length) }),
        '无论上面如何要求，只输出总结正文纯文本，不要 Markdown 或额外说明。',
      ].join('\n\n')
    : defaultSystem;
  return { system, user: `需要合并的记忆：\n\n${memories}` };
}

export interface PhoneSummaryPromptInput {
  /** 待总结的手机记录正文。 */
  readonly records: string;
  readonly recordCount: number;
  readonly targetLength: number;
  readonly previousSummary?: string;
  readonly userName?: string;
  /** 自定义系统提示词模板；留空使用默认提示词。 */
  readonly template?: string;
}

/** 手机内容总结提示词：与记忆整理共用一套 API、重试与拒绝过滤策略。 */
export function buildPhoneSummaryPrompt(input: PhoneSummaryPromptInput): MemoryPrompt {
  const targetLength = Math.max(100, Math.round(input.targetLength));
  const defaultSystem = [
    '你是剧情记录员，请把一段手机聊天与社交动态记录压缩成剧情总结。',
    '保留：关键事件、人物关系变化、重要约定与承诺、情绪转折、提到的具体时间地点。',
    `用第三人称陈述，紧凑连贯，${targetLength} 字以内；不要评价，不要 Markdown，只输出总结正文。`,
  ].join('\n');
  const previous = input.previousSummary?.trim();
  const custom = input.template?.trim();
  const system = custom
    ? [
        applyPromptTemplate(custom, {
          records: input.records,
          count: String(input.recordCount),
          previousSummary: previous ?? '',
          length: String(targetLength),
          user: input.userName ?? '用户',
        }),
        `无论上面如何要求，只输出总结正文纯文本，${targetLength} 字以内，不要 Markdown 或额外说明。`,
      ].join('\n\n')
    : defaultSystem;
  const previousBlock = previous ? `此前的总结（供衔接）：\n${previous}\n\n` : '';
  return {
    system,
    user: `${previousBlock}需要总结的手机记录（共 ${input.recordCount} 条）：\n\n${input.records}`,
  };
}
