import { parseCondition, ConditionParseError } from './parser.js';
import type {
  ConditionBinaryOperator,
  ConditionError,
  ConditionEvaluation,
  ConditionFunctionName,
  ConditionLimits,
  ConditionNode,
  ConditionSnapshot,
  ConditionSource,
  ConditionValue,
} from './types.js';
import {
  DEFAULT_CONDITION_LIMITS,
  isConditionRecord,
  isSafePropertyKey,
} from './types.js';

interface EvaluationState {
  readonly snapshot: ConditionSnapshot;
  readonly limits: Required<ConditionLimits>;
  steps: number;
  depth: number;
}

const MISSING = Symbol('condition-missing');
type ResolvedValue = ConditionValue | typeof MISSING;

export function createConditionSnapshot(
  scopeId: string,
  revision: string | number,
  data: unknown,
  limits: ConditionLimits = DEFAULT_CONDITION_LIMITS,
): ConditionSnapshot {
  return {
    scopeId,
    revision: String(revision),
    data: sanitizeValue(data, 0, normalizeLimits(limits)),
  };
}

export function evaluateCondition(
  source: ConditionSource,
  snapshot: ConditionSnapshot,
  limits: ConditionLimits = DEFAULT_CONDITION_LIMITS,
): ConditionEvaluation {
  const normalizedLimits = normalizeLimits(limits);
  if (typeof source === 'string' && source.length > normalizedLimits.maxSourceLength) {
    return failure({ code: 'parse', message: '条件表达式过长' }, 0);
  }
  const state: EvaluationState = { snapshot, limits: normalizedLimits, steps: 0, depth: 0 };
  try {
    const node = parseCondition(source, normalizedLimits);
    validateConditionNode(node, normalizedLimits);
    const value = evaluateNode(node, state);
    return { ok: true, value, steps: state.steps };
  } catch (error) {
    return failure(toConditionError(error), state.steps);
  }
}

export function evaluateConditionBoolean(
  source: ConditionSource,
  snapshot: ConditionSnapshot,
  limits: ConditionLimits = DEFAULT_CONDITION_LIMITS,
): ConditionEvaluation {
  const result = evaluateCondition(source, snapshot, limits);
  if (!result.ok) return result;
  return { ...result, value: toConditionBoolean(result.value) };
}

export function readConditionPath(
  snapshot: ConditionSnapshot,
  path: readonly (string | number)[],
): ConditionValue | undefined {
  const value = resolvePath(snapshot.data, path);
  return value === MISSING ? undefined : value;
}

export function toConditionBoolean(value: ConditionValue): boolean {
  if (value === null || value === false) return false;
  if (typeof value === 'number') return value !== 0 && Number.isFinite(value);
  if (typeof value === 'string') return value.length > 0;
  return true;
}

function validateConditionNode(
  node: unknown,
  limits: Required<ConditionLimits>,
  depth = 0,
  counter = { value: 0 },
): asserts node is ConditionNode {
  counter.value += 1;
  if (counter.value > limits.maxNodes) throw conditionError('node-limit', '条件 AST 节点超过限制');
  if (depth > limits.maxDepth) throw conditionError('depth-limit', '条件 AST 嵌套深度超过限制');
  if (!isConditionRecord(node)) throw conditionError('invalid-value', '条件 AST 节点无效');

  const kind = node.kind;
  if (kind === 'literal') {
    if (!isBoundedConditionValue(node.value, 0, limits)) throw conditionError('invalid-value', '条件字面量无效');
    return;
  }
  if (kind === 'path') {
    if (!Array.isArray(node.segments) || node.segments.length === 0) {
      throw conditionError('invalid-path', '条件路径为空');
    }
    for (const segment of node.segments) {
      if (typeof segment === 'string') {
        if (!segment || !isSafePropertyKey(segment) || segment.length > limits.maxStringLength) {
          throw conditionError('invalid-path', '条件路径包含不安全属性');
        }
      } else if (!Number.isInteger(segment) || segment < 0) {
        throw conditionError('invalid-path', '条件路径索引无效');
      }
    }
    return;
  }
  if (kind === 'array') {
    if (!Array.isArray(node.items) || node.items.length > limits.maxArrayLength) {
      throw conditionError('invalid-value', '条件数组无效或超过限制');
    }
    for (const item of node.items) validateConditionNode(item, limits, depth + 1, counter);
    return;
  }
  if (kind === 'unary') {
    if (node.operator !== 'not') throw conditionError('invalid-operation', '条件一元运算符无效');
    validateConditionNode(node.operand, limits, depth + 1, counter);
    return;
  }
  if (kind === 'binary') {
    if (!isBinaryOperator(node.operator)) throw conditionError('invalid-operation', '条件二元运算符无效');
    validateConditionNode(node.left, limits, depth + 1, counter);
    validateConditionNode(node.right, limits, depth + 1, counter);
    return;
  }
  if (kind === 'call') {
    if (!isConditionFunctionName(node.name) || !Array.isArray(node.arguments)
      || node.arguments.length > limits.maxArrayLength) {
      throw conditionError('invalid-operation', '条件函数调用无效');
    }
    for (const argument of node.arguments) validateConditionNode(argument, limits, depth + 1, counter);
    return;
  }
  throw conditionError('invalid-value', '条件 AST 节点类型不受支持');
}

function isBinaryOperator(value: unknown): value is ConditionBinaryOperator {
  return typeof value === 'string'
    && ['and', 'or', 'eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'contains', 'in'].includes(value);
}

function isConditionFunctionName(value: unknown): value is ConditionFunctionName {
  return typeof value === 'string'
    && ['exists', 'empty', 'length', 'contains', 'startsWith', 'endsWith'].includes(value);
}

function isBoundedConditionValue(
  value: unknown,
  depth: number,
  limits: Required<ConditionLimits>,
  seen = new WeakSet<object>(),
): value is ConditionValue {
  if (value === null || typeof value === 'boolean') return true;
  if (typeof value === 'string') return value.length <= limits.maxStringLength;
  if (typeof value === 'number') return Number.isFinite(value);
  if (typeof value !== 'object' || seen.has(value)) return false;
  if (depth > limits.maxDepth) return false;
  seen.add(value);
  if (Array.isArray(value)) {
    const valid = value.length <= limits.maxArrayLength
      && value.every((item) => isBoundedConditionValue(item, depth + 1, limits, seen));
    seen.delete(value);
    return valid;
  }
  const valid = Object.keys(value).every((key) => (
    isSafePropertyKey(key)
    && isBoundedConditionValue((value as Record<string, unknown>)[key], depth + 1, limits, seen)
  ));
  seen.delete(value);
  return valid;
}

function evaluateNode(node: ConditionNode, state: EvaluationState): ConditionValue {
  tick(state);
  enter(state);
  try {
    switch (node.kind) {
      case 'literal':
        return node.value;
      case 'path': {
        const value = resolvePath(state.snapshot.data, node.segments);
        return value === MISSING ? null : value;
      }
      case 'array':
        return node.items.map((item) => evaluateNode(item, state));
      case 'unary':
        return !toConditionBoolean(evaluateNode(node.operand, state));
      case 'call':
        return evaluateCallNode(node, state);
      case 'binary':
        return evaluateBinary(node.operator, node.left, node.right, state);
    }
  } finally {
    leave(state);
  }
}

function evaluateBinary(
  operator: ConditionBinaryOperator,
  leftNode: ConditionNode,
  rightNode: ConditionNode,
  state: EvaluationState,
): ConditionValue {
  if (operator === 'and') {
    const left = evaluateNode(leftNode, state);
    return toConditionBoolean(left) ? toConditionBoolean(evaluateNode(rightNode, state)) : false;
  }
  if (operator === 'or') {
    const left = evaluateNode(leftNode, state);
    return toConditionBoolean(left) ? true : toConditionBoolean(evaluateNode(rightNode, state));
  }
  const left = evaluateNode(leftNode, state);
  const right = evaluateNode(rightNode, state);
  switch (operator) {
    case 'eq': return deepEqual(left, right);
    case 'ne': return !deepEqual(left, right);
    case 'gt': return compare(left, right, (a, b) => a > b);
    case 'gte': return compare(left, right, (a, b) => a >= b);
    case 'lt': return compare(left, right, (a, b) => a < b);
    case 'lte': return compare(left, right, (a, b) => a <= b);
    case 'contains': return contains(left, right);
    case 'in': return contains(right, left);
  }
}

function evaluateCallNode(node: Extract<ConditionNode, { kind: 'call' }>, state: EvaluationState): ConditionValue {
  if (node.name === 'exists' && node.arguments.length === 1 && node.arguments[0]?.kind === 'path') {
    return resolvePath(state.snapshot.data, node.arguments[0].segments) !== MISSING;
  }
  return evaluateCall(node.name, node.arguments.map((argument) => evaluateNode(argument, state)), state);
}

function evaluateCall(
  name: ConditionFunctionName,
  args: readonly ConditionValue[],
  state: EvaluationState,
): ConditionValue {
  switch (name) {
    case 'exists':
      if (args.length !== 1) throw invalidOperation('exists 只接受一个参数');
      return args[0] !== null;
    case 'empty':
      if (args.length !== 1) throw invalidOperation('empty 只接受一个参数');
      return isEmpty(args[0] ?? null);
    case 'length': {
      if (args.length !== 1) throw invalidOperation('length 只接受一个参数');
      const value = args[0];
      if (typeof value === 'string' || Array.isArray(value)) return value.length;
      if (isConditionRecord(value)) return Object.keys(value).length;
      return 0;
    }
    case 'contains':
      if (args.length !== 2) throw invalidOperation('contains 需要两个参数');
      return contains(args[0] ?? null, args[1] ?? null);
    case 'startsWith':
    case 'endsWith': {
      if (args.length !== 2 || typeof args[0] !== 'string' || typeof args[1] !== 'string') {
        throw invalidOperation(`${name} 需要两个字符串参数`);
      }
      return name === 'startsWith' ? args[0].startsWith(args[1]) : args[0].endsWith(args[1]);
    }
  }
}

function resolvePath(root: ConditionValue, path: readonly (string | number)[]): ResolvedValue {
  let current: ResolvedValue = root;
  for (const segment of path) {
    if (typeof segment === 'string' && !isSafePropertyKey(segment)) return MISSING;
    if (Array.isArray(current)) {
      if (typeof segment !== 'number' || !Number.isInteger(segment) || segment < 0) return MISSING;
      current = current[segment] ?? MISSING;
      continue;
    }
    if (!isConditionRecord(current)) return MISSING;
    const key = String(segment);
    current = Object.prototype.hasOwnProperty.call(current, key) ? current[key] ?? null : MISSING;
  }
  return current;
}

function contains(container: ConditionValue, needle: ConditionValue): boolean {
  if (typeof container === 'string' && typeof needle === 'string') return container.includes(needle);
  if (Array.isArray(container)) return container.some((item) => deepEqual(item, needle));
  if (isConditionRecord(container) && typeof needle === 'string') return Object.prototype.hasOwnProperty.call(container, needle);
  return false;
}

function compare(
  left: ConditionValue,
  right: ConditionValue,
  comparator: (left: number | string, right: number | string) => boolean,
): boolean {
  if (typeof left === 'number' && typeof right === 'number') return comparator(left, right);
  if (typeof left === 'string' && typeof right === 'string') return comparator(left, right);
  throw invalidOperation('比较运算要求两侧都是数字或字符串');
}

function deepEqual(left: ConditionValue, right: ConditionValue): boolean {
  if (left === right) return true;
  if (typeof left !== typeof right || left === null || right === null) return false;
  if (Array.isArray(left) && Array.isArray(right)) {
    return left.length === right.length && left.every((value, index) => deepEqual(value, right[index] ?? null));
  }
  if (isConditionRecord(left) && isConditionRecord(right)) {
    const leftKeys = Object.keys(left);
    const rightKeys = Object.keys(right);
    return leftKeys.length === rightKeys.length
      && leftKeys.every((key) => Object.prototype.hasOwnProperty.call(right, key) && deepEqual(left[key] ?? null, right[key] ?? null));
  }
  return false;
}

function isEmpty(value: ConditionValue): boolean {
  if (value === null) return true;
  if (typeof value === 'string' || Array.isArray(value)) return value.length === 0;
  if (isConditionRecord(value)) return Object.keys(value).length === 0;
  return false;
}

function sanitizeValue(
  value: unknown,
  depth: number,
  limits: Required<ConditionLimits>,
  seen = new WeakSet<object>(),
): ConditionValue {
  if (value === null || typeof value === 'string' || typeof value === 'boolean') {
    return typeof value === 'string' ? value.slice(0, limits.maxStringLength) : value;
  }
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value !== 'object' || seen.has(value)) return null;
  if (depth >= limits.maxDepth) return null;
  seen.add(value);
  if (Array.isArray(value)) {
    const result = value.slice(0, limits.maxArrayLength)
      .map((item) => sanitizeValue(item, depth + 1, limits, seen));
    seen.delete(value);
    return result;
  }
  const record: Record<string, ConditionValue> = {};
  for (const [key, item] of Object.entries(value)) {
    if (isSafePropertyKey(key)) record[key] = sanitizeValue(item, depth + 1, limits, seen);
  }
  seen.delete(value);
  return record;
}

function normalizeLimits(limits: ConditionLimits): Required<ConditionLimits> {
  return {
    maxSourceLength: clampInteger(limits.maxSourceLength, DEFAULT_CONDITION_LIMITS.maxSourceLength, 100, 10_000),
    maxDepth: clampInteger(limits.maxDepth, DEFAULT_CONDITION_LIMITS.maxDepth, 4, 64),
    maxSteps: clampInteger(limits.maxSteps, DEFAULT_CONDITION_LIMITS.maxSteps, 100, 20_000),
    maxArrayLength: clampInteger(limits.maxArrayLength, DEFAULT_CONDITION_LIMITS.maxArrayLength, 1, 256),
    maxStringLength: clampInteger(limits.maxStringLength, DEFAULT_CONDITION_LIMITS.maxStringLength, 32, 20_000),
    maxTokens: clampInteger(limits.maxTokens, DEFAULT_CONDITION_LIMITS.maxTokens, 16, 4_096),
    maxNodes: clampInteger(limits.maxNodes, DEFAULT_CONDITION_LIMITS.maxNodes, 16, 2_048),
  };
}

function clampInteger(value: number | undefined, fallback: number, min: number, max: number): number {
  return Number.isInteger(value) ? Math.min(max, Math.max(min, value as number)) : fallback;
}

function tick(state: EvaluationState): void {
  state.steps += 1;
  if (state.steps > state.limits.maxSteps) throw conditionError('step-limit', '条件求值超过步数限制');
}

function enter(state: EvaluationState): void {
  state.depth += 1;
  if (state.depth > state.limits.maxDepth) throw conditionError('depth-limit', '条件求值超过嵌套深度限制');
}

function leave(state: EvaluationState): void {
  state.depth -= 1;
}

function invalidOperation(message: string): Error {
  return conditionError('invalid-operation', message);
}

function conditionError(code: ConditionError['code'], message: string): Error & { readonly conditionError: ConditionError } {
  const error = new Error(message) as Error & { readonly conditionError: ConditionError };
  Object.defineProperty(error, 'conditionError', { value: { code, message }, enumerable: false });
  return error;
}

function toConditionError(error: unknown): ConditionError {
  if (error instanceof ConditionParseError) return { code: 'parse', message: error.message, offset: error.offset };
  if (typeof error === 'object' && error !== null && 'conditionError' in error) {
    const conditionError = (error as { conditionError: ConditionError }).conditionError;
    return conditionError;
  }
  return { code: 'invalid-value', message: error instanceof Error ? error.message : '条件求值失败' };
}

function failure(error: ConditionError, steps: number): ConditionEvaluation {
  return { ok: false, value: false, error, steps };
}