import { loadModuleDefinition, readModuleFile, validateExtensionModuleManifest, validateModuleDefinition } from './module-loader.js';
import type {
  ExtensionModuleBundle,
  ExtensionModuleDefinition,
  ExtensionModuleFactory,
  ExtensionModuleHostApi,
  ExtensionModuleManifest,
  ExtensionModuleRecord,
} from './module-contract.js';

export interface ModuleHostApiFactory {
  readonly create: (record: ExtensionModuleRecord) => ExtensionModuleHostApi;
}

export interface ModuleRegistrySnapshot {
  readonly records: readonly ExtensionModuleRecord[];
  readonly definitions: ReadonlyMap<string, ExtensionModuleDefinition>;
}

export class ExtensionModuleRegistry {
  readonly #records = new Map<string, ExtensionModuleRecord>();
  readonly #definitions = new Map<string, ExtensionModuleDefinition>();
  readonly #factories = new Map<string, ExtensionModuleFactory>();
  readonly #host: ModuleHostApiFactory;

  constructor(records: readonly ExtensionModuleRecord[], host: ModuleHostApiFactory) {
    this.#host = host;
    for (const record of records) this.#records.set(record.manifest.id, normalizeRecord(record));
  }

  get snapshot(): ModuleRegistrySnapshot {
    return {
      records: [...this.#records.values()].map((record) => structuredClone(record)),
      definitions: new Map(this.#definitions),
    };
  }

  get records(): readonly ExtensionModuleRecord[] {
    return [...this.#records.values()].map((record) => structuredClone(record));
  }

  async loadAll(): Promise<void> {
    for (const record of this.#records.values()) {
      if (!record.enabled) continue;
      try {
        await this.#loadRecord(record);
      } catch (error) {
        console.warn(`[墨韵手机] 动态模块 ${record.manifest.id} 加载失败`, error);
        this.#records.set(record.manifest.id, { ...record, enabled: false });
      }
    }
  }

  async reloadAll(): Promise<void> {
    for (const definition of this.#definitions.values()) await definition.dispose?.();
    this.#definitions.clear();
    await this.loadAll();
  }

  async install(bundle: ExtensionModuleBundle): Promise<ExtensionModuleRecord> {
    const manifest = validateExtensionModuleManifest(bundle.manifest, {
      sourceBytes: new TextEncoder().encode(bundle.source).byteLength,
    });
    if (this.#records.has(manifest.id)) throw new Error(`模块「${manifest.name}」已经安装。`);
    const record: ExtensionModuleRecord = {
      manifest,
      source: bundle.source,
      importedAt: Date.now(),
      enabled: true,
      settings: {},
    };
    this.#records.set(manifest.id, record);
    try {
      await this.#loadRecord(record, bundle.factory);
    } catch (error) {
      this.#records.delete(manifest.id);
      throw error;
    }
    return structuredClone(record);
  }

  async installFile(sourceFile: File): Promise<ExtensionModuleRecord> {
    return this.install(await readModuleFile(sourceFile));
  }

  async remove(moduleId: string): Promise<void> {
    const record = this.#records.get(moduleId);
    if (!record) return;
    await this.#definitions.get(moduleId)?.dispose?.();
    this.#definitions.delete(moduleId);
    this.#factories.delete(moduleId);
    this.#records.delete(moduleId);
  }

  async setEnabled(moduleId: string, enabled: boolean): Promise<void> {
    const record = this.#records.get(moduleId);
    if (!record) throw new Error('模块不存在。');
    if (record.enabled === enabled) return;
    if (!enabled) {
      await this.#definitions.get(moduleId)?.dispose?.();
      this.#definitions.delete(moduleId);
      this.#factories.delete(moduleId);
    }
    const next = { ...record, enabled };
    this.#records.set(moduleId, next);
    if (enabled) await this.#loadRecord(next);
  }

  async updateSettings(moduleId: string, patch: Readonly<Record<string, unknown>>): Promise<void> {
    const record = this.#records.get(moduleId);
    if (!record) throw new Error('模块不存在。');
    const settings = { ...record.settings, ...structuredClone(patch) };
    if (JSON.stringify(settings).length > 64_000) throw new Error('模块设置不能超过 64KB。');
    this.#records.set(moduleId, { ...record, settings });
  }

  getDefinition(moduleId: string): ExtensionModuleDefinition | null {
    return this.#definitions.get(moduleId) ?? null;
  }

  async dispose(): Promise<void> {
    for (const definition of this.#definitions.values()) await definition.dispose?.();
    this.#definitions.clear();
    this.#factories.clear();
  }

  async #loadRecord(record: ExtensionModuleRecord, factory?: ExtensionModuleFactory): Promise<void> {
    const resolvedFactory = factory
      ?? this.#factories.get(record.manifest.id)
      ?? await loadModuleDefinition({ manifest: record.manifest, source: record.source });
    this.#factories.set(record.manifest.id, resolvedFactory);
    const hostApi = this.#host.create(record);
    const value = callFactory(resolvedFactory, hostApi);
    const definition = validateModuleDefinition(record.manifest, value);
    this.#definitions.set(record.manifest.id, definition);
  }
}

function callFactory(factory: ExtensionModuleFactory, api: ExtensionModuleHostApi): unknown {
  return factory(api);
}

function normalizeRecord(record: ExtensionModuleRecord): ExtensionModuleRecord {
  return {
    manifest: validateExtensionModuleManifest(record.manifest),
    source: record.source,
    importedAt: Number.isFinite(record.importedAt) ? record.importedAt : Date.now(),
    enabled: record.enabled !== false,
    settings: record.settings && typeof record.settings === 'object' ? structuredClone(record.settings) : {},
  };
}