import type { StoryFloorSnapshot, OpenAiCompatibleApiConfig } from '../integration/sillytavern-bridge.js';
import { generateWithApiProxy, type ApiRetryProgress } from './api-client.js';

export const STORY_CONTEXT_OPEN = '<story_context>';
export const STORY_CONTEXT_CLOSE = '</story_context>';
export const STORY_CONTEXT_GUIDANCE = '以上是用户的本轮输入，请以用户输入作为本轮剧情发展的直接驱动力，并结合下方提供的角色状态、人物动作、场景、时间、剧情重点及相关记忆，自然续写本轮剧情。创作时须保持人物性格、关系、行为与前文连续一致，通过具体的动作、神态、语言、感官、环境和情绪变化推进情节，使叙事生动、细腻且富有画面感；不要复述、解释或暴露下方的结构化信息。';

export interface StoryAnalysis {
  readonly characterInfo: string;
  readonly characterActions: string;
  readonly sceneInfo: string;
  readonly time: string;
  readonly plotFocus: string;
  readonly memoryIds: readonly number[];
  readonly summaryIds: readonly number[];
}

/** 可供剧情分析器选择的当前聊天记忆；归档条目不会进入目录。 */
export interface StoryMemoryCandidate {
  readonly seq: number;
  readonly kind: 'summary' | 'consolidation';
  readonly floorFrom: number;
  readonly floorTo: number;
  readonly content: string;
}

export interface StoryContextAnalysisResult {
  readonly analysis: StoryAnalysis;
  readonly formatted: string;
}

/** 单次记忆召回请求允许的最长静默时间（无新数据）；自动重试各自独立计时。 */
const ANALYSIS_IDLE_TIMEOUT_MS = 45_000;
const ID_LIMIT = 32;
const MEMORY_CANDIDATE_LIMIT = 32;
const SELECTED_MEMORY_LIMIT = 10;

/**
 * 未配置上下文上限时不截断提示词；配置了就按配置换算出可用字符数。
 * 这里只保留用户显式声明的边界，不再额外设死天花板。
 */
function resolveStoryAnalysisPromptLimit(config: OpenAiCompatibleApiConfig): number {
  const configured = config.maxContextTokens;
  if (!Number.isFinite(configured) || configured === null || configured <= 0) return Number.POSITIVE_INFINITY;
  const outputBudget = Math.max(512, config.maxTokens ?? 2_000);
  return Math.max(8_000, (configured - outputBudget - 512) * 4);
}

/** 超出用户声明的上下文预算时，优先保留本轮用户消息，其余从历史头部裁掉。 */
function boundStoryAnalysisPrompt(rawUserPrompt: string, maxPromptChars: number): string {
  if (!Number.isFinite(maxPromptChars) || rawUserPrompt.length <= maxPromptChars) return rawUserPrompt;
  const currentIndex = rawUserPrompt.lastIndexOf('本轮用户消息：');
  if (currentIndex < 0) return rawUserPrompt.slice(-maxPromptChars);
  const currentSection = rawUserPrompt.slice(currentIndex).trim();
  const historySection = rawUserPrompt.slice(0, currentIndex).trim();
  const availableHistoryChars = Math.max(0, maxPromptChars - currentSection.length - 2);
  return `${historySection.slice(-availableHistoryChars)}\n\n${currentSection}`;
}

export function buildStoryAnalysisPrompt(
  floors: readonly StoryFloorSnapshot[],
  currentMessage: string,
  memoryCandidates: readonly StoryMemoryCandidate[] = [],
): { readonly system: string; readonly user: string } {
  const transcript = floors.slice(-10).map((floor) =>
    `正文#${floor.floor}【${floor.name}/${floor.role}】\n${floor.text}`,
  ).join('\n\n');
  const rankedCandidates = rankStoryMemoryCandidates(
    memoryCandidates,
    `${transcript}\n${currentMessage}`,
  );
  const memoryCatalog = rankedCandidates.map((candidate) => {
    const kind = candidate.kind === 'consolidation' ? '合并总结' : '记忆摘要';
    return `记忆#${candidate.seq}【${kind}；来源楼层${candidate.floorFrom}-${candidate.floorTo}】\n${candidate.content}`;
  }).join('\n\n');
  return {
    system: [
      '你是记忆库剧情分析器，不是聊天助手。',
      '分析最近十个酒馆正文楼层和本轮用户输入，提取下一轮生成真正需要的剧情上下文。',
      '只输出 JSON，不要 Markdown 代码围栏、解释或拒答。',
      'JSON 字段必须是 characterInfo、characterActions、sceneInfo、time、plotFocus、memoryIds、summaryIds。',
      'characterInfo 必须基于最近剧情动态更新每名在场角色的当前身份、状态、关系和刚发生的新变化，不得机械复用上一轮已经过时的描述。',
      'characterActions 单独描述每名在场人物在上个场景结束时的最后动作、姿势、所处位置及手中物品，也就是进入本轮时仍然成立的当前动作，例如“张凡坐在沙发上，手拿一本书；燕儿站在茶几旁”。不要写计划、心理或尚未发生的动作。',
      'sceneInfo 描述地点、环境和正在发生的场景；必须与 characterActions 的人物位置和姿势一致。',
      'time 给出剧情内时间或时间推进；plotFocus 概括本轮剧情重点和应保持的连续性。',
      '记忆摘要与合并总结合计不超过 10 条时，必须把目录中的全部编号分别写入 memoryIds 和 summaryIds，不得因相关性较低而省略。',
      '候选总数超过 10 条时，才根据本轮人物、物品、地点、约定和未解决剧情进行重排序，最终合计选择最符合剧情的 10 条，不多不少。',
      'memoryIds 只填写“记忆摘要”的编号；summaryIds 只填写“合并总结”的编号，两个数组的数量合计按上述规则处理。',
      '严禁输出候选目录中不存在的编号，不要把聊天楼层号当成记忆或总结编号。',
    ].join('\n'),
    user: [
      `最近十个正文楼层：\n${transcript || '（无历史正文）'}`,
      `当前可用记忆目录（仅可从这里选择编号）：\n${memoryCatalog || '（当前没有可用记忆）'}`,
      `本轮用户消息：\n${currentMessage.trim()}`,
    ].join('\n\n'),
  };
}

export interface StoryContextAnalysisOptions {
  readonly signal?: AbortSignal;
  readonly memoryCandidates?: readonly StoryMemoryCandidate[];
  readonly onRetry?: (progress: ApiRetryProgress) => void | Promise<void>;
}

export async function analyzeStoryContext(
  config: OpenAiCompatibleApiConfig,
  floors: readonly StoryFloorSnapshot[],
  currentMessage: string,
  options: StoryContextAnalysisOptions = {},
): Promise<StoryContextAnalysisResult | null> {
  if (!config.model.trim() || !currentMessage.trim()) return null;
  const memoryCandidates = options.memoryCandidates ?? [];
  const prompt = buildStoryAnalysisPrompt(floors.slice(-10), currentMessage, memoryCandidates);
  const boundedUserPrompt = boundStoryAnalysisPrompt(prompt.user, resolveStoryAnalysisPromptLimit(config));
  const raw = await generateWithApiProxy(config, {
    system: prompt.system,
    user: boundedUserPrompt,
    temperature: config.temperature ?? 1,
    maxTokens: Math.min(config.maxTokens ?? 2_000, 2_000),
    // 只约束单次请求的静默时长，长思考与自动重试都不会被整轮超时砍断。
    idleTimeoutMs: ANALYSIS_IDLE_TIMEOUT_MS,
    ...(options.signal ? { signal: options.signal } : {}),
    validateResponse: (response) => parseStoryAnalysis(response) !== null,
    invalidResponseMessage: '记忆召回 API 返回的剧情分析格式无效。',
    ...(options.onRetry ? { onRetry: options.onRetry } : {}),
  });
  const parsed = parseStoryAnalysis(raw);
  if (!parsed) throw new Error('记忆召回 API 返回的剧情分析格式无效。');
  const query = [...floors.slice(-10).map((floor) => floor.text), currentMessage].join('\n');
  const analysis = constrainStoryAnalysis(parsed, memoryCandidates, query);
  return { analysis, formatted: formatStoryContext(analysis) };
}

export function parseStoryAnalysis(raw: string): StoryAnalysis | null {
  const candidate = extractJsonObject(raw);
  if (!candidate) return null;
  try {
    const value: unknown = JSON.parse(candidate);
    if (!isRecord(value)) return null;
    const characterInfo = readText(value.characterInfo);
    const characterActions = readText(value.characterActions);
    const sceneInfo = readText(value.sceneInfo);
    const time = readText(value.time);
    const plotFocus = readText(value.plotFocus);
    if (!characterInfo && !characterActions && !sceneInfo && !time && !plotFocus) return null;
    return {
      characterInfo,
      characterActions,
      sceneInfo,
      time,
      plotFocus,
      memoryIds: readIds(value.memoryIds),
      summaryIds: readIds(value.summaryIds),
    };
  } catch {
    return null;
  }
}

export function constrainStoryAnalysis(
  analysis: StoryAnalysis,
  candidates: readonly StoryMemoryCandidate[],
  query: string,
): StoryAnalysis {
  const ranked = rankStoryMemoryCandidates(candidates, query);
  if (ranked.length <= SELECTED_MEMORY_LIMIT) {
    return withSelectedStoryMemories(analysis, ranked);
  }

  const selectedMemoryIds = new Set(analysis.memoryIds);
  const selectedSummaryIds = new Set(analysis.summaryIds);
  const preferred = ranked.filter((candidate) => (
    candidate.kind === 'summary'
      ? selectedMemoryIds.has(candidate.seq)
      : selectedSummaryIds.has(candidate.seq)
  ));
  const preferredSeqs = new Set(preferred.map((candidate) => candidate.seq));
  const selected = [
    ...preferred,
    ...ranked.filter((candidate) => !preferredSeqs.has(candidate.seq)),
  ].slice(0, SELECTED_MEMORY_LIMIT);
  return withSelectedStoryMemories(analysis, selected);
}

function withSelectedStoryMemories(
  analysis: StoryAnalysis,
  selected: readonly StoryMemoryCandidate[],
): StoryAnalysis {
  return {
    ...analysis,
    memoryIds: selected.filter((candidate) => candidate.kind === 'summary').map((candidate) => candidate.seq),
    summaryIds: selected.filter((candidate) => candidate.kind === 'consolidation').map((candidate) => candidate.seq),
  };
}

export function rankStoryMemoryCandidates(
  candidates: readonly StoryMemoryCandidate[],
  query: string,
): readonly StoryMemoryCandidate[] {
  const unique = new Map<number, StoryMemoryCandidate>();
  for (const candidate of candidates) {
    if (!Number.isInteger(candidate.seq) || candidate.seq < 0 || !candidate.content.trim()) continue;
    if (!unique.has(candidate.seq)) unique.set(candidate.seq, candidate);
  }
  const queryGrams = createMatchGrams(query);
  return [...unique.values()]
    .sort((left, right) => {
      const scoreDifference = scoreMemoryCandidate(right, queryGrams) - scoreMemoryCandidate(left, queryGrams);
      if (scoreDifference !== 0) return scoreDifference;
      if (right.floorTo !== left.floorTo) return right.floorTo - left.floorTo;
      return right.seq - left.seq;
    })
    .slice(0, MEMORY_CANDIDATE_LIMIT);
}

function scoreMemoryCandidate(candidate: StoryMemoryCandidate, queryGrams: ReadonlySet<string>): number {
  if (queryGrams.size === 0) return 0;
  let score = 0;
  for (const gram of createMatchGrams(candidate.content)) {
    if (!queryGrams.has(gram)) continue;
    score += gram.length >= 3 ? 2 : 1;
  }
  return score;
}

function createMatchGrams(value: string): ReadonlySet<string> {
  const compact = value
    .toLocaleLowerCase()
    .replace(/<[^>]{0,500}>/g, ' ')
    .replace(/[^\p{L}\p{N}]+/gu, '');
  const grams = new Set<string>();
  for (const size of [2, 3]) {
    for (let index = 0; index <= compact.length - size; index += 1) {
      grams.add(compact.slice(index, index + size));
    }
  }
  return grams;
}

export function formatStoryContext(analysis: StoryAnalysis): string {
  return [
    '【角色信息】', analysis.characterInfo || '无新增角色信息',
    '【人物动作】', analysis.characterActions || '未明确人物当前动作',
    '【场景信息】', analysis.sceneInfo || '无新增场景信息',
    '【时间】', analysis.time || '未明确',
    '【剧情重点】', analysis.plotFocus || '保持当前剧情连续性',
    '【本轮需要的记忆编号】', formatIds(analysis.memoryIds),
    '【本轮需要的总结编号】', formatIds(analysis.summaryIds),
  ].join('\n');
}

export function injectStoryContext(original: string, formatted: string): string {
  const withoutPrevious = removeStoryContext(original);
  return `${withoutPrevious.trimEnd()}\n\n${STORY_CONTEXT_GUIDANCE}\n${STORY_CONTEXT_OPEN}\n${formatted.trim()}\n${STORY_CONTEXT_CLOSE}`.trim();
}

export function removeStoryContext(content: string): string {
  return content.replace(
    new RegExp(`(?:${escapeRegExp(STORY_CONTEXT_GUIDANCE)}\\s*)?${escapeRegExp(STORY_CONTEXT_OPEN)}[\\s\\S]*?${escapeRegExp(STORY_CONTEXT_CLOSE)}`, 'gi'),
    '',
  ).trimEnd();
}

export function extractStoryContext(content: string): StoryAnalysis | null {
  const match = content.match(new RegExp(`${escapeRegExp(STORY_CONTEXT_OPEN)}([\\s\\S]*?)${escapeRegExp(STORY_CONTEXT_CLOSE)}`, 'i'));
  if (!match?.[1]) return null;
  return {
    characterInfo: readLabeledField(match[1], '角色信息'),
    characterActions: readLabeledField(match[1], '人物动作'),
    sceneInfo: readLabeledField(match[1], '场景信息'),
    time: readLabeledField(match[1], '时间'),
    plotFocus: readLabeledField(match[1], '剧情重点'),
    memoryIds: readLabeledIds(match[1], '本轮需要的记忆编号'),
    summaryIds: readLabeledIds(match[1], '本轮需要的总结编号'),
  };
}

function extractJsonObject(raw: string): string | null {
  const text = raw.replace(/```(?:json)?/gi, '').replace(/```/g, '').trim();
  const start = text.indexOf('{');
  if (start < 0) return null;

  let depth = 0;
  let quoted = false;
  let escaped = false;
  for (let index = start; index < text.length; index += 1) {
    const character = text[index]!;
    if (quoted) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') quoted = false;
      continue;
    }
    if (character === '"') {
      quoted = true;
      continue;
    }
    if (character === '{') depth += 1;
    else if (character === '}') {
      depth -= 1;
      if (depth === 0) return text.slice(start, index + 1);
    }
  }
  return null;
}

function readText(value: unknown): string {
  return typeof value === 'string'
    ? value.replace(/<[^>]{1,500}>/g, ' ').replace(/\s+/g, ' ').trim()
    : '';
}

function readIds(value: unknown): readonly number[] {
  if (!Array.isArray(value)) return [];
  return [...new Set(value.flatMap((item) => {
    const text = typeof item === 'string' ? item.trim() : '';
    const number = typeof item === 'number' ? item : Number(text.replace(/^#/, ''));
    return Number.isInteger(number) && number >= 0 && number <= 2_000_000_000 ? [number] : [];
  }))].slice(0, ID_LIMIT);
}

function readLabeledField(content: string, label: string): string {
  const match = content.match(new RegExp(`【${escapeRegExp(label)}】\\s*([\\s\\S]*?)(?=\\n【|$)`, 'i'));
  return readText(match?.[1] ?? '');
}

function readLabeledIds(content: string, label: string): readonly number[] {
  const match = content.match(new RegExp(`【${escapeRegExp(label)}】\\s*([^\\n]*)`, 'i'));
  return readIds((match?.[1] ?? '').split(/[、,，#\\s]+/).filter(Boolean));
}

function formatIds(ids: readonly number[]): string {
  return ids.length > 0 ? ids.map((id) => `#${id}`).join('、') : '无';
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\\]\\]/g, '\\$&');
}
