import type { CanonExtraction } from './canon-extractor.js';
import { mergeCharacterLocks, uniqueTexts } from './identity.js';
import { CANON_LIBRARY_VERSION, type CanonFact, type CanonLibrary } from './model.js';
import type { CanonSourceBundle } from './source-normalizer.js';

/** 事实与世界规则的累计上限：长篇原著分多次解析后仍能持续积累，检索层再按预算裁剪。 */
const FACT_LIMIT = 3_000;
const WORLD_RULE_LIMIT = 200;
/** 已解析分块 ID 的累计上限：与分块上限同量级，避免长篇原著被反复重解析。 */
const ANALYZED_CHUNK_LIMIT = 50_000;

export function createEmptyCanonLibrary(bundle: CanonSourceBundle, now: number): CanonLibrary {
  return {
    version: CANON_LIBRARY_VERSION,
    fingerprint: bundle.fingerprint,
    title: bundle.title,
    documents: bundle.documents,
    chunks: bundle.chunks,
    facts: [],
    characters: [],
    worldRules: [],
    analyzedChunkIds: [],
    builtAt: now,
  };
}

/**
 * 合并一批解析结果：人物锁按稳定 ID 合并（手工修正过的不被覆盖），
 * 事实与世界规则去重累积，并记录已解析的分块以支持继续解析长篇原著。
 */
export function mergeCanonExtractions(
  library: CanonLibrary,
  extractions: readonly CanonExtraction[],
  analyzedChunkIds: readonly string[],
  now: number,
): CanonLibrary {
  const characters = extractions.reduce(
    (current, extraction) => mergeCharacterLocks(current, extraction.characters),
    library.characters,
  );
  const facts = dedupeFacts([...library.facts, ...extractions.flatMap((extraction) => extraction.facts)]);
  const worldRules = uniqueTexts(
    [...library.worldRules, ...extractions.flatMap((extraction) => extraction.worldRules)],
    WORLD_RULE_LIMIT,
  );
  return {
    ...library,
    version: CANON_LIBRARY_VERSION,
    characters,
    facts,
    worldRules,
    analyzedChunkIds: uniqueTexts([...library.analyzedChunkIds, ...analyzedChunkIds], ANALYZED_CHUNK_LIMIT),
    builtAt: now,
  };
}

/** 同一条事实可能在多个片段里重复出现；按正文去重并保留可信度更高的那条。 */
export function dedupeFacts(facts: readonly CanonFact[]): readonly CanonFact[] {
  const order = { high: 3, medium: 2, low: 1 } as const;
  const byText = new Map<string, CanonFact>();
  for (const fact of facts) {
    const key = fact.text.replace(/\s+/g, '');
    if (!key) continue;
    const current = byText.get(key);
    if (!current || order[fact.confidence] > order[current.confidence]) byText.set(key, fact);
  }
  return [...byText.values()].slice(-FACT_LIMIT);
}

/** 尚未解析的分块：角色卡与世界书优先，导入资料按文档顺序继续。 */
export function pendingChunks(library: CanonLibrary): readonly CanonLibrary['chunks'][number][] {
  const analyzed = new Set(library.analyzedChunkIds);
  const priority = new Map(library.documents.map((document, index) => [
    document.id,
    document.kind === 'card' ? -2 : document.kind === 'worldbook' ? -1 : index,
  ]));
  return library.chunks
    .filter((chunk) => !analyzed.has(chunk.id))
    .slice()
    .sort((left, right) => (
      (priority.get(left.documentId) ?? 0) - (priority.get(right.documentId) ?? 0)
      || left.index - right.index
    ));
}

/** 把待解析分块按字符预算打包成请求批次。 */
export function batchChunks(
  chunks: readonly CanonLibrary['chunks'][number][],
  charsPerBatch: number,
  maxBatches: number,
): readonly (readonly CanonLibrary['chunks'][number][])[] {
  const batches: CanonLibrary['chunks'][number][][] = [];
  let current: CanonLibrary['chunks'][number][] = [];
  let used = 0;
  for (const chunk of chunks) {
    if (current.length > 0 && used + chunk.text.length > charsPerBatch) {
      batches.push(current);
      if (batches.length >= maxBatches) return batches;
      current = [];
      used = 0;
    }
    current.push(chunk);
    used += chunk.text.length;
  }
  if (current.length > 0 && batches.length < maxBatches) batches.push(current);
  return batches;
}

export function canonLibraryStats(library: CanonLibrary | null): {
  readonly documents: number;
  readonly chunks: number;
  readonly analyzed: number;
  readonly characters: number;
  readonly facts: number;
  readonly worldRules: number;
} {
  return {
    documents: library?.documents.length ?? 0,
    chunks: library?.chunks.length ?? 0,
    analyzed: library?.analyzedChunkIds.length ?? 0,
    characters: library?.characters.length ?? 0,
    facts: library?.facts.length ?? 0,
    worldRules: library?.worldRules.length ?? 0,
  };
}