import type { ExtensionModuleRecord } from '../extensions/module-contract.js';
import { EXTENSION_MODULE_TEMPLATES } from '../extensions/module-templates.js';
import { button, element } from './dom.js';
import { renderPhoneIcon } from './phone-icon.js';

export interface ExtensionModulesPanelContext {
  readonly modules: readonly ExtensionModuleRecord[];
  readonly onImport: (sourceFile: File) => Promise<void>;
  readonly onToggle: (moduleId: string, enabled: boolean) => Promise<void>;
  readonly onRemove: (moduleId: string) => Promise<void>;
  readonly openDeveloperGuide: () => void;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

export function renderExtensionModulesPanel(context: ExtensionModulesPanelContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-extension-modules' });
  const header = element('header', { className: 'phone-extension-modules-header' });
  header.append(
    element('span', { className: 'phone-kicker', text: 'EXTENSIONS' }),
    element('h2', { className: 'phone-section-title', text: '拓展应用' }),
    element('p', { className: 'phone-settings-hint', text: '模块按可信代码运行，可访问完整手机 Host API。模块代码会在当前页面执行，请只导入你信任的来源。' }),
  );
  const actions = element('div', { className: 'phone-extension-modules-actions' });
  actions.append(
    button('导入模块', 'phone-button phone-button-primary', () => {
      void chooseModuleFile(context);
    }),
    button('开发者指南', 'phone-button phone-button-secondary', context.openDeveloperGuide),
    button('下载最小模板', 'phone-button phone-button-secondary', () => {
      const template = EXTENSION_MODULE_TEMPLATES[0];
      if (!template) return;
      downloadTextFile(template.filename, template.source);
      context.showNotice(`已下载「${template.title}」模板。`, 'success');
    }),
  );
  header.append(actions);
  page.append(header);

  const list = element('div', { className: 'phone-extension-module-list' });
  if (context.modules.length === 0) {
    list.classList.add('phone-empty', 'phone-extension-empty');
    list.append(
      renderPhoneIcon('extensions', 'phone-extension-empty-icon'),
      element('strong', { text: '还没有拓展应用' }),
      element('span', { text: '选择单个 .js 文件即可导入；manifest 和应用代码必须打包在同一个文件内。' }),
    );
  } else {
    for (const record of context.modules) list.append(renderModuleCard(context, record));
  }
  page.append(list);
  return page;
}

async function chooseModuleFile(context: ExtensionModulesPanelContext): Promise<void> {
  const sourceFile = await chooseFile('.js,.mjs,text/javascript', '请选择模块 .js 文件');
  if (!sourceFile) return;
  try {
    await context.onImport(sourceFile);
    context.showNotice('模块导入成功。', 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

function chooseFile(accept: string, title: string): Promise<File | null> {
  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = accept;
    input.title = title;
    input.addEventListener('change', () => resolve(input.files?.[0] ?? null), { once: true });
    input.click();
  });
}

function renderModuleCard(context: ExtensionModulesPanelContext, record: ExtensionModuleRecord): HTMLElement {
  const manifest = record.manifest;
  const card = element('article', { className: `phone-extension-module-card${record.enabled ? '' : ' is-disabled'}` });
  const icon = element('span', { className: 'phone-extension-module-icon' });
  if (manifest.icon) icon.append(element('img', { attributes: { src: manifest.icon, alt: '' } }));
  else icon.append(renderPhoneIcon('extensions'));
  const copy = element('div', { className: 'phone-extension-module-copy' });
  copy.append(
    element('strong', { text: manifest.name }),
    element('small', { text: `${manifest.author} · v${manifest.version}` }),
  );
  if (manifest.description) copy.append(element('p', { text: manifest.description }));
  copy.append(element('small', {
    className: 'phone-extension-module-permissions',
    text: manifest.permissions?.length
      ? `可信模块 · 旧权限声明（仅兼容，不限制能力）：${manifest.permissions.join('、')}`
      : '可信模块 · 可访问完整 Host API',
  }));
  card.append(icon, copy, renderModuleActions(context, record));
  return card;
}

function renderModuleActions(context: ExtensionModulesPanelContext, record: ExtensionModuleRecord): HTMLElement {
  const manifest = record.manifest;
  const actions = element('div', { className: 'phone-extension-module-actions' });
  const toggle = button(record.enabled ? '停用' : '启用', 'phone-button phone-button-secondary phone-button-compact', async () => {
    toggle.disabled = true;
    try {
      await context.onToggle(manifest.id, !record.enabled);
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      toggle.disabled = false;
    }
  });
  const remove = button('删除', 'phone-button phone-button-danger phone-button-compact', async () => {
    if (!window.confirm(`确定删除「${manifest.name}」吗？模块设置和模块数据也会被清理。`)) return;
    remove.disabled = true;
    try {
      await context.onRemove(manifest.id);
      context.showNotice(`已删除「${manifest.name}」。`, 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      remove.disabled = false;
    }
  });
  actions.append(toggle, remove);
  return actions;
}

function downloadTextFile(filename: string, text: string): void {
  const blob = new Blob([text], { type: 'text/javascript;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}
