export type PresetPromptRole = 'system' | 'user' | 'assistant';

export interface PresetPromptSlot {
  readonly id: string;
  readonly name: string;
  readonly enabled: boolean;
  readonly role: PresetPromptRole;
  readonly index: number;
  readonly position: 'relative' | 'in_chat';
  readonly depth: number | null;
  readonly contentLength: number;
}

export interface PresetPromptSlotSnapshot {
  readonly available: boolean;
  readonly presetName: string;
  readonly slots: readonly PresetPromptSlot[];
  readonly reason: string;
}

export interface PresetPromptSlotOptions {
  readonly targetId: string;
  readonly roleOverride: '' | PresetPromptRole;
}

interface TavernPresetPrompt {
  id?: unknown;
  name?: unknown;
  enabled?: unknown;
  role?: unknown;
  content?: unknown;
  position?: unknown;
  [key: string]: unknown;
}

interface TavernPreset {
  prompts?: unknown;
  prompts_unused?: unknown;
  [key: string]: unknown;
}

interface TavernHelperPresetApi {
  getLoadedPresetName?: () => unknown;
  getPreset?: (presetName: string) => unknown;
  updatePresetWith?: (
    presetName: string,
    updater: (preset: TavernPreset) => TavernPreset | Promise<TavernPreset>,
    options?: { readonly render?: 'debounced' | 'immediate' | 'none' },
  ) => Promise<unknown>;
}

interface SlotLease {
  readonly presetName: string;
  readonly targetId: string;
  readonly original: TavernPresetPrompt;
}

const SYSTEM_PROMPT_IDS = new Set([
  'main',
  'nsfw',
  'jailbreak',
  'enhanceDefinitions',
  'worldInfoBefore',
  'personaDescription',
  'charDescription',
  'charPersonality',
  'scenario',
  'worldInfoAfter',
  'dialogueExamples',
  'chatHistory',
]);

/** 全局已占用的槽位（预设名 + 提示词 ID）；避免两个会话同时租用同一条目导致原像丢失。 */
const leasedSlots = new Set<string>();

const slotKey = (presetName: string, targetId: string): string => `${presetName}\u0000${targetId}`;

/**
 * 管理一个临时预设提示词槽。每次占用前保存完整原像，生成结束或切换上下文时恢复。
 * 该会话不负责内容生产，只处理酒馆助手的预设读写边界。
 */
export class PresetPromptSlotSession {
  #lease: SlotLease | null = null;

  inspect(): PresetPromptSlotSnapshot {
    const helper = getTavernHelper();
    if (!helper?.getPreset) {
      return unavailableSnapshot('未检测到酒馆助手的预设读取 API。');
    }

    try {
      const presetName = loadedPresetName(helper);
      const preset = asPreset(helper.getPreset('in_use'));
      if (!preset) return unavailableSnapshot('当前预设数据不可用。', presetName);
      const prompts = promptList(preset);
      return {
        available: true,
        presetName,
        slots: prompts.flatMap((prompt, index) => {
          const slot = toPromptSlot(prompt, index);
          return slot ? [slot] : [];
        }),
        reason: '',
      };
    } catch (error) {
      return unavailableSnapshot(describeError(error));
    }
  }

  async set(content: string, options: PresetPromptSlotOptions): Promise<boolean> {
    if (!content.trim()) return this.restore();
    const targetId = options.targetId.trim();
    if (!targetId) throw new Error('未选择用于注入的预设提示词槽位。');

    const helper = requireWritableHelper();
    const presetName = loadedPresetName(helper);
    if (this.#lease && (this.#lease.presetName !== presetName || this.#lease.targetId !== targetId)) {
      await this.restore();
    }
    const key = slotKey(presetName, targetId);
    if (!this.#lease && leasedSlots.has(key)) {
      throw new Error(`提示词“${targetId}”已被另一处注入占用，请为两处注入选择不同的槽位。`);
    }

    let capturedOriginal: TavernPresetPrompt | null = null;
    await helper.updatePresetWith?.('in_use', (preset) => {
      const prompts = promptList(preset);
      const target = prompts.find((prompt) => String(prompt.id ?? '') === targetId);
      if (!target) throw new Error(`当前预设里找不到 ID 为“${targetId}”的提示词。`);
      if (!isEligiblePrompt(target)) throw new Error(`提示词“${targetId}”是系统占位条目，不能作为注入槽。`);

      if (!this.#lease) capturedOriginal = clonePrompt(target);
      target.enabled = true;
      if (options.roleOverride) target.role = options.roleOverride;
      target.content = content;
      return preset;
    }, { render: 'none' });

    if (!this.#lease) {
      if (!capturedOriginal) throw new Error('无法保存目标提示词的原始状态。');
      this.#lease = { presetName, targetId, original: capturedOriginal };
      leasedSlots.add(key);
    }
    return true;
  }

  async restore(): Promise<boolean> {
    const lease = this.#lease;
    if (!lease) return true;
    const helper = getTavernHelper();
    if (!helper?.updatePresetWith) {
      this.#releaseLease();
      return false;
    }

    try {
      const currentPresetName = loadedPresetName(helper);
      if (currentPresetName !== lease.presetName) {
        this.#releaseLease();
        return false;
      }
      await helper.updatePresetWith('in_use', (preset) => {
        const prompts = promptList(preset);
        const target = prompts.find((prompt) => String(prompt.id ?? '') === lease.targetId);
        if (!target) throw new Error(`恢复失败：当前预设里找不到 ID 为“${lease.targetId}”的提示词。`);
        replacePrompt(target, lease.original);
        return preset;
      }, { render: 'none' });
      this.#releaseLease();
      return true;
    } catch {
      return false;
    }
  }

  abandon(): void {
    this.#releaseLease();
  }

  #releaseLease(): void {
    if (this.#lease) leasedSlots.delete(slotKey(this.#lease.presetName, this.#lease.targetId));
    this.#lease = null;
  }
}

function getTavernHelper(): TavernHelperPresetApi | null {
  try {
    const parent = window.parent as unknown as Record<string, unknown>;
    const helper = parent?.TavernHelper ?? (window as unknown as Record<string, unknown>).TavernHelper;
    return helper && typeof helper === 'object' ? helper as TavernHelperPresetApi : null;
  } catch {
    const helper = (window as unknown as Record<string, unknown>).TavernHelper;
    return helper && typeof helper === 'object' ? helper as TavernHelperPresetApi : null;
  }
}

function requireWritableHelper(): Required<Pick<TavernHelperPresetApi, 'getPreset' | 'updatePresetWith'>> & TavernHelperPresetApi {
  const helper = getTavernHelper();
  if (!helper?.getPreset || !helper.updatePresetWith) {
    throw new Error('酒馆助手预设 API 不可用，无法使用指定预设槽位注入。');
  }
  return helper as Required<Pick<TavernHelperPresetApi, 'getPreset' | 'updatePresetWith'>> & TavernHelperPresetApi;
}

function loadedPresetName(helper: TavernHelperPresetApi): string {
  try {
    return String(helper.getLoadedPresetName?.() ?? '当前预设').trim() || '当前预设';
  } catch {
    return '当前预设';
  }
}

function asPreset(value: unknown): TavernPreset | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as TavernPreset : null;
}

function promptList(preset: TavernPreset): TavernPresetPrompt[] {
  return Array.isArray(preset.prompts) ? preset.prompts as TavernPresetPrompt[] : [];
}

function toPromptSlot(prompt: TavernPresetPrompt, index: number): PresetPromptSlot | null {
  if (!isEligiblePrompt(prompt)) return null;
  const id = String(prompt.id ?? '').trim();
  if (!id) return null;
  const position = prompt.position && typeof prompt.position === 'object' && !Array.isArray(prompt.position)
    ? prompt.position as Record<string, unknown>
    : {};
  const positionType = position.type === 'in_chat' ? 'in_chat' : 'relative';
  const depth = positionType === 'in_chat' && Number.isFinite(Number(position.depth))
    ? Math.max(0, Math.round(Number(position.depth)))
    : null;
  return {
    id,
    name: String(prompt.name ?? '').trim() || id,
    enabled: prompt.enabled !== false,
    role: normalizeRole(prompt.role),
    index,
    position: positionType,
    depth,
    contentLength: typeof prompt.content === 'string' ? prompt.content.length : 0,
  };
}

function isEligiblePrompt(prompt: TavernPresetPrompt): boolean {
  const id = String(prompt.id ?? '').trim();
  return Boolean(id) && !SYSTEM_PROMPT_IDS.has(id) && typeof prompt.content === 'string';
}

function normalizeRole(value: unknown): PresetPromptRole {
  return value === 'user' || value === 'assistant' ? value : 'system';
}

function clonePrompt(prompt: TavernPresetPrompt): TavernPresetPrompt {
  return typeof structuredClone === 'function'
    ? structuredClone(prompt)
    : JSON.parse(JSON.stringify(prompt)) as TavernPresetPrompt;
}

function replacePrompt(target: TavernPresetPrompt, original: TavernPresetPrompt): void {
  for (const key of Object.keys(target)) delete target[key];
  Object.assign(target, clonePrompt(original));
}

function unavailableSnapshot(reason: string, presetName = ''): PresetPromptSlotSnapshot {
  return { available: false, presetName, slots: [], reason };
}

function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? '未知错误');
}