import type { ActiveHours, Profile, WorldClock } from '../domain/model.js';
import { DEFAULT_TIME_ADVANCE, type TimeAdvanceSettings } from './time-advance.js';

export interface ClockAnchors {
  readonly databaseNow?: number | null;
  readonly chatNow?: number | null;
  readonly systemNow?: number | null;
}

export interface UserActionDurationInput {
  readonly contentLength: number;
  readonly hasAttachment?: boolean;
  readonly baseMinutes?: number;
}

export interface ReplyScheduleInput {
  readonly clock: WorldClock;
  readonly profile: Profile;
  readonly seed: string;
}

export interface ScheduledReply {
  readonly at: number;
  readonly delayMinutes: number;
  readonly shiftedToActiveHours: boolean;
}

function finiteTimestamp(value: number | null | undefined): number | null {
  if (value === null || value === undefined) return null;
  const number = Number(value);
  return Number.isFinite(number) && number > 0 ? number : null;
}

export function resolveInitialClock(anchors: ClockAnchors): WorldClock {
  const databaseNow = finiteTimestamp(anchors.databaseNow);
  const chatNow = finiteTimestamp(anchors.chatNow);
  const systemNow = finiteTimestamp(anchors.systemNow) ?? Date.now();
  const now = databaseNow ?? chatNow ?? systemNow;
  const source = databaseNow ? 'database' : chatNow ? 'chat' : 'system';
  return {
    scopeId: '',
    now,
    source,
    reason: `initial-${source}-anchor`,
  };
}

export function calculateUserActionMinutes(input: UserActionDurationInput, rules: TimeAdvanceSettings = DEFAULT_TIME_ADVANCE): number {
  if (!rules.enabled) return 0;
  const base = Math.max(0, input.baseMinutes ?? rules.sendBaseMinutes);
  const contentMinutes = Math.ceil(Math.max(0, input.contentLength) / rules.sendCharsPerMinute);
  const attachmentMinutes = input.hasAttachment ? rules.sendAttachmentMinutes : 0;
  return Math.min(rules.sendMaxMinutes, base + contentMinutes + attachmentMinutes);
}

export function advanceClock(
  clock: WorldClock,
  minutes: number,
  reason: string,
  source: WorldClock['source'] = 'user',
): WorldClock {
  const safeMinutes = Number.isFinite(minutes) ? Math.max(0, minutes) : 0;
  return {
    ...clock,
    now: clock.now + safeMinutes * 60_000,
    source,
    reason,
  };
}

export function scheduleReply({ clock, profile, seed }: ReplyScheduleInput): ScheduledReply {
  const minimum = Math.max(0, Math.round(profile.replyDelay.minimumMinutes));
  const maximum = Math.max(minimum, Math.round(profile.replyDelay.maximumMinutes));
  const offset = deterministicInteger(seed, maximum - minimum + 1);
  const delayMinutes = minimum + offset;
  const candidate = clock.now + delayMinutes * 60_000;
  const active = normalizeActiveHours(profile.activeHours);
  const shifted = moveIntoActiveHours(candidate, active);
  return {
    at: shifted.at,
    delayMinutes: Math.round((shifted.at - clock.now) / 60_000),
    shiftedToActiveHours: shifted.shifted,
  };
}

export function advanceTo(clock: WorldClock, timestamp: number, reason: string): WorldClock {
  return {
    ...clock,
    now: Math.max(clock.now, finiteTimestamp(timestamp) ?? clock.now),
    source: 'generation',
    reason,
  };
}

export function formatWorldTime(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  const today = `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
  return `${today} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

export function sameWorldDay(first: number, second: number): boolean {
  const a = new Date(first);
  const b = new Date(second);
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function normalizeActiveHours(hours: ActiveHours): ActiveHours {
  return {
    startHour: Math.min(23, Math.max(0, Math.round(hours.startHour))),
    endHour: Math.min(23, Math.max(0, Math.round(hours.endHour))),
  };
}

function moveIntoActiveHours(timestamp: number, hours: ActiveHours): { at: number; shifted: boolean } {
  const date = new Date(timestamp);
  const hour = date.getHours();
  const overnight = hours.endHour < hours.startHour;
  const active = overnight ? hour >= hours.startHour || hour <= hours.endHour : hour >= hours.startHour && hour <= hours.endHour;
  if (active) return { at: timestamp, shifted: false };

  const target = new Date(timestamp);
  if (overnight && hour > hours.endHour && hour < hours.startHour) {
    target.setHours(hours.startHour, 0, 0, 0);
  } else if (!overnight && hour < hours.startHour) {
    target.setHours(hours.startHour, 0, 0, 0);
  } else {
    target.setDate(target.getDate() + 1);
    target.setHours(hours.startHour, 0, 0, 0);
  }
  return { at: target.getTime(), shifted: true };
}

function deterministicInteger(seed: string, range: number): number {
  if (range <= 1) return 0;
  let hash = 2166136261;
  for (const character of seed) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) % range;
}
