import { getSillyTavernContext, type SillyTavernContextShape } from './sillytavern-bridge.js';
import { flattenMvuTuples, isMvuTupleLeaf } from '../mvu/mvu-tuple.js';

export type VariableScope = 'chat' | 'message';

export interface VariablesSnapshot {
  readonly available: boolean;
  readonly reason: string;
  readonly scope: VariableScope;
  /** message 作用域时为楼层号；chat 作用域为 null。 */
  readonly messageId: number | null;
  readonly lastMessageId: number | null;
  readonly source: 'mvu' | 'tavernHelper' | 'context' | 'none';
  readonly data: Readonly<Record<string, unknown>>;
}

export interface VariableWriteResult {
  readonly ok: boolean;
  readonly message: string;
}

interface MvuApi {
  getMvuData?: (options: { type: string; message_id?: number }) => unknown;
  setMvuVariable?: (mvuData: unknown, path: string, value: unknown, options?: Record<string, unknown>) => unknown | Promise<unknown>;
  replaceMvuData?: (mvuData: unknown, options: { type: string; message_id?: number }) => unknown | Promise<unknown>;
}

interface VariablesHelperApi {
  getVariables?: (options: { type: string; message_id?: number }) => unknown;
  updateVariablesWith?: (
    updater: (variables: Record<string, unknown>) => Record<string, unknown>,
    options: { type: string; message_id?: number },
  ) => unknown | Promise<unknown>;
  getLastMessageId?: () => number;
}

function getHostRecord(): Record<string, unknown> {
  try {
    const parent = window.parent as unknown as Record<string, unknown>;
    if (parent && (parent.SillyTavern || parent.TavernHelper || parent.Mvu)) return parent;
  } catch {
    // Cross-origin parents are ignored.
  }
  return window as unknown as Record<string, unknown>;
}

function getMvu(): MvuApi | null {
  const host = getHostRecord();
  const mvu = host.Mvu as (MvuApi & { readonly __narrativePhoneBridge?: boolean }) | undefined;
  // 我们自己装的兼容门面也长成 MVU 的样子；把它当真 MVU 用会绕回自己，读到刚投影出去的数据。
  if (mvu?.__narrativePhoneBridge === true) return null;
  return mvu && typeof mvu.getMvuData === 'function' ? mvu : null;
}

function getVariablesHelper(): VariablesHelperApi | null {
  const host = getHostRecord();
  const helper = host.TavernHelper as VariablesHelperApi | undefined;
  return helper && typeof helper === 'object' ? helper : null;
}

export function getLastMessageIdSafe(context: SillyTavernContextShape = getSillyTavernContext()): number | null {
  const helper = getVariablesHelper();
  if (helper && typeof helper.getLastMessageId === 'function') {
    try {
      const id = Number(helper.getLastMessageId());
      if (Number.isInteger(id) && id >= 0) return id;
    } catch {
      // 继续走上下文推断。
    }
  }
  const chat = Array.isArray(context.chat) ? context.chat : [];
  return chat.length > 0 ? chat.length - 1 : null;
}

/** 读取聊天变量或指定楼层的变量（含 stat_data）。 */
export async function readVariables(
  scope: VariableScope,
  messageId: number | null = null,
): Promise<VariablesSnapshot> {
  const context = getSillyTavernContext();
  const lastMessageId = getLastMessageIdSafe(context);
  const resolvedMessageId = scope === 'message'
    ? (messageId ?? lastMessageId)
    : null;

  if (scope === 'message' && resolvedMessageId === null) {
    return emptySnapshot(scope, null, lastMessageId, 'none', '当前聊天没有任何楼层。');
  }

  if (scope === 'message') {
    const mvu = getMvu();
    if (mvu) {
      try {
        const mvuData = mvu.getMvuData?.({ type: 'message', message_id: resolvedMessageId ?? 0 });
        const record = asRecord(mvuData);
        if (record && hasKeys(asRecord(record.stat_data))) {
          return {
            available: true,
            reason: `已通过 MVU 读取第 ${resolvedMessageId} 楼变量。`,
            scope,
            messageId: resolvedMessageId,
            lastMessageId,
            source: 'mvu',
            data: { stat_data: record.stat_data },
          };
        }
      } catch {
        // MVU 读取失败时降级到通用接口。
      }
    }
  }

  const helper = getVariablesHelper();
  if (helper && typeof helper.getVariables === 'function') {
    try {
      const raw = helper.getVariables(
        scope === 'message'
          ? { type: 'message', message_id: resolvedMessageId ?? 0 }
          : { type: 'chat' },
      );
      const record = asRecord(raw) ?? {};
      return {
        available: true,
        reason: hasKeys(record)
          ? (scope === 'message' ? `已读取第 ${resolvedMessageId} 楼变量。` : '已读取聊天变量。')
          : (scope === 'message' ? `第 ${resolvedMessageId} 楼没有变量数据。` : '当前聊天没有变量数据。'),
        scope,
        messageId: resolvedMessageId,
        lastMessageId,
        source: 'tavernHelper',
        data: record,
      };
    } catch {
      // 继续走直接上下文。
    }
  }

  const direct = readVariablesFromContext(context, scope, resolvedMessageId);
  if (direct) {
    return {
      available: true,
      reason: hasKeys(direct)
        ? (scope === 'message' ? `已读取第 ${resolvedMessageId} 楼变量。` : '已读取聊天变量。')
        : '暂无变量数据。',
      scope,
      messageId: resolvedMessageId,
      lastMessageId,
      source: 'context',
      data: direct,
    };
  }
  return emptySnapshot(
    scope,
    resolvedMessageId,
    lastMessageId,
    'none',
    scope === 'message'
      ? `第 ${resolvedMessageId} 楼没有变量数据（需要 MVU 或酒馆助手写入过变量）。`
      : '当前聊天没有变量数据。',
  );
}

/**
 * 按路径写入变量值。楼层的 stat_data 优先走 MVU 以保持 display_data 一致。
 * mvuDescription 为 MVU 二元组叶子 [值, 描述] 的描述部分；提供时其它写入通道会保留该描述。
 */
export async function writeVariableByPath(
  scope: VariableScope,
  messageId: number | null,
  path: readonly string[],
  value: unknown,
  mvuDescription?: string,
  assertAccess?: () => void,
): Promise<VariableWriteResult> {
  assertAccess?.();
  if (path.length === 0) return { ok: false, message: '变量路径为空。' };

  if (scope === 'message' && messageId !== null && path[0] === 'stat_data' && path.length > 1) {
    const mvu = getMvu();
    if (mvu && typeof mvu.setMvuVariable === 'function' && typeof mvu.replaceMvuData === 'function') {
      try {
        const mvuData = mvu.getMvuData?.({ type: 'message', message_id: messageId });
        const record = asRecord(mvuData);
        if (record) {
          const mvuPath = path.slice(1).join('.');
          await Promise.resolve(mvu.setMvuVariable(mvuData, mvuPath, value, { reason: '手机变量管理器修改' }));
          assertAccess?.();
          if (mvuDescription) {
            // setMvuVariable 可能丢失二元组描述；发现丢失时补写完整二元组。
            const statData = asRecord(record.stat_data);
            const updated = statData ? getNestedValue(statData, path.slice(1)) : undefined;
            if (!isMvuTupleLeaf(updated) || updated[1] !== mvuDescription) {
              if (statData) setNestedValue(statData, path.slice(1), [value, mvuDescription]);
            }
          }
          await Promise.resolve(mvu.replaceMvuData(mvuData, { type: 'message', message_id: messageId }));
          return { ok: true, message: '已通过 MVU 保存变量。' };
        }
      } catch {
        // 降级到通用接口。
      }
    }
  }

  const finalValue = mvuDescription ? [value, mvuDescription] : value;
  assertAccess?.();
  const helper = getVariablesHelper();
  if (helper && typeof helper.updateVariablesWith === 'function') {
    try {
      await Promise.resolve(helper.updateVariablesWith(
        (variables) => {
          assertAccess?.();
          setNestedValue(variables, path, finalValue);
          return variables;
        },
        scope === 'message' ? { type: 'message', message_id: messageId ?? 0 } : { type: 'chat' },
      ));
      return { ok: true, message: '变量已保存。' };
    } catch (error) {
      return { ok: false, message: `保存变量失败：${formatError(error)}` };
    }
  }

  return writeVariablesToContext(scope, messageId, (variables) => {
    assertAccess?.();
    setNestedValue(variables, path, finalValue);
  });
}

/** 按路径删除变量。 */
export async function deleteVariableByPath(
  scope: VariableScope,
  messageId: number | null,
  path: readonly string[],
): Promise<VariableWriteResult> {
  if (path.length === 0) return { ok: false, message: '变量路径为空。' };

  const helper = getVariablesHelper();
  if (helper && typeof helper.updateVariablesWith === 'function') {
    try {
      await Promise.resolve(helper.updateVariablesWith(
        (variables) => {
          deleteNestedValue(variables, path);
          return variables;
        },
        scope === 'message' ? { type: 'message', message_id: messageId ?? 0 } : { type: 'chat' },
      ));
      return { ok: true, message: '变量已删除。' };
    } catch (error) {
      return { ok: false, message: `删除变量失败：${formatError(error)}` };
    }
  }
  return writeVariablesToContext(scope, messageId, (variables) => {
    deleteNestedValue(variables, path);
  });
}

/** 用一个完整对象替换整个作用域的变量（JSON 编辑）。 */
export async function replaceVariablesData(
  scope: VariableScope,
  messageId: number | null,
  data: Record<string, unknown>,
): Promise<VariableWriteResult> {
  const helper = getVariablesHelper();
  if (helper && typeof helper.updateVariablesWith === 'function') {
    try {
      await Promise.resolve(helper.updateVariablesWith(
        (variables) => {
          for (const key of Object.keys(variables)) delete variables[key];
          Object.assign(variables, data);
          return variables;
        },
        scope === 'message' ? { type: 'message', message_id: messageId ?? 0 } : { type: 'chat' },
      ));
      return { ok: true, message: '变量已整体替换。' };
    } catch (error) {
      return { ok: false, message: `替换变量失败：${formatError(error)}` };
    }
  }
  return writeVariablesToContext(scope, messageId, (variables) => {
    for (const key of Object.keys(variables)) delete variables[key];
    Object.assign(variables, data);
  });
}

/** MVU 叶子值约定：[值, 描述] 二元组。判定与折叠逻辑在 `src/mvu/mvu-tuple.ts`，两侧共用一份。 */
export { flattenMvuTuples, isMvuTupleLeaf } from '../mvu/mvu-tuple.js';

/**
 * 生成用于提示词的变量快照（折叠二元组）；
 * 超出字符预算时按顶层键顺序截取，保证 JSON 尺寸可控。
 */
export function compactVariablesForPrompt(
  data: Readonly<Record<string, unknown>>,
  charBudget = 6_000,
): Record<string, unknown> | null {
  const flattened = flattenMvuTuples(data) as Record<string, unknown>;
  const entries = Object.entries(flattened);
  if (entries.length === 0) return null;
  if (JSON.stringify(flattened).length <= charBudget) return flattened;

  const partial: Record<string, unknown> = {};
  let used = 2;
  for (const [key, value] of entries) {
    const chunk = JSON.stringify({ [key]: value }).length;
    if (used + chunk > charBudget) continue;
    partial[key] = value;
    used += chunk;
  }
  return Object.keys(partial).length > 0 ? partial : null;
}

export interface VariableUpdateRequest {
  /** 相对 stat_data 的路径，用 . 分隔（例如 世界.时间）。 */
  readonly path: string;
  readonly value: string | number | boolean | null;
}

export interface VariableUpdatesResult {
  readonly applied: number;
  readonly skipped: readonly string[];
  readonly messageId: number | null;
}

/**
 * 把 AI 决定的变量更新写入最新楼层的 stat_data。
 * 只允许更新已存在的变量路径，避免模型凭空创建变量；MVU 二元组的描述会保留。
 */
export async function applyVariableUpdates(
  updates: readonly VariableUpdateRequest[],
): Promise<VariableUpdatesResult> {
  if (updates.length === 0) return { applied: 0, skipped: [], messageId: null };
  const snapshot = await readVariables('message', null);
  if (!snapshot.available) {
    return { applied: 0, skipped: updates.map((update) => update.path), messageId: snapshot.messageId };
  }

  let applied = 0;
  const skipped: string[] = [];
  for (const update of updates) {
    const parts = update.path.split('.').map((part) => part.trim()).filter(Boolean);
    if (parts.length === 0) {
      skipped.push(update.path);
      continue;
    }
    const fullPath = parts[0] === 'stat_data' ? parts : ['stat_data', ...parts];
    const existing = getNestedValue(snapshot.data as Record<string, unknown>, fullPath);
    if (existing === undefined) {
      skipped.push(update.path);
      continue;
    }
    const description = isMvuTupleLeaf(existing) && typeof existing[1] === 'string' ? existing[1] : undefined;
    const result = await writeVariableByPath('message', snapshot.messageId, fullPath, update.value, description);
    if (result.ok) applied += 1;
    else skipped.push(update.path);
  }
  return { applied, skipped, messageId: snapshot.messageId };
}

function readVariablesFromContext(
  context: SillyTavernContextShape,
  scope: VariableScope,
  messageId: number | null,
): Record<string, unknown> | null {
  if (scope === 'chat') {
    const metadata = context.chatMetadata as Record<string, unknown> | undefined;
    const variables = asRecord(metadata?.variables);
    return variables ? structuredClone(variables) : {};
  }
  const chat = Array.isArray(context.chat) ? context.chat : [];
  const message = messageId !== null ? chat[messageId] : undefined;
  if (!message) return null;
  const variables = resolveMessageVariables(message);
  return variables ? structuredClone(variables) : null;
}

function resolveMessageVariables(message: Record<string, unknown>): Record<string, unknown> | null {
  const variables = message.variables;
  if (!variables || typeof variables !== 'object') return null;
  const swipeId = Number(message.swipe_id ?? 0);
  if (Array.isArray(variables)) {
    return asRecord(variables[Number.isInteger(swipeId) ? swipeId : 0]) ?? asRecord(variables[0]);
  }
  const record = variables as Record<string, unknown>;
  const bySwipe = asRecord(record[String(Number.isInteger(swipeId) ? swipeId : 0)]);
  return bySwipe ?? record;
}

async function writeVariablesToContext(
  scope: VariableScope,
  messageId: number | null,
  mutate: (variables: Record<string, unknown>) => void,
): Promise<VariableWriteResult> {
  const context = getSillyTavernContext();
  try {
    if (scope === 'chat') {
      const metadata = context.chatMetadata as Record<string, unknown> | undefined;
      if (!metadata) return { ok: false, message: '无法访问聊天元数据。' };
      const variables = asRecord(metadata.variables) ?? {};
      metadata.variables = variables;
      mutate(variables);
      saveContext(context);
      return { ok: true, message: '变量已保存（直接写入聊天元数据）。' };
    }
    const chat = Array.isArray(context.chat) ? context.chat : [];
    const message = messageId !== null ? chat[messageId] as Record<string, unknown> | undefined : undefined;
    if (!message) return { ok: false, message: `找不到第 ${messageId} 楼消息。` };
    const container = resolveWritableMessageVariables(message);
    mutate(container);
    saveContext(context);
    return { ok: true, message: '变量已保存（直接写入楼层数据）。' };
  } catch (error) {
    return { ok: false, message: `保存变量失败：${formatError(error)}` };
  }
}

function resolveWritableMessageVariables(message: Record<string, unknown>): Record<string, unknown> {
  const swipeId = Number(message.swipe_id ?? 0);
  const index = Number.isInteger(swipeId) && swipeId >= 0 ? swipeId : 0;
  const variables = message.variables;
  if (Array.isArray(variables)) {
    const existing = asRecord(variables[index]);
    if (existing) return existing;
    const created: Record<string, unknown> = {};
    (variables as unknown[])[index] = created;
    return created;
  }
  const record = asRecord(variables);
  if (record) {
    const bySwipe = asRecord(record[String(index)]);
    if (bySwipe) return bySwipe;
    return record;
  }
  const created: Record<string, unknown> = {};
  message.variables = created;
  return created;
}

function saveContext(context: SillyTavernContextShape): void {
  const anyContext = context as Record<string, unknown>;
  const saveMetadata = anyContext.saveMetadataDebounced ?? anyContext.saveMetadata;
  if (typeof saveMetadata === 'function') {
    (saveMetadata as () => void).call(context);
  }
  const saveChat = anyContext.saveChatDebounced ?? anyContext.saveChat;
  if (typeof saveChat === 'function') {
    (saveChat as () => void).call(context);
  }
}

function emptySnapshot(
  scope: VariableScope,
  messageId: number | null,
  lastMessageId: number | null,
  source: VariablesSnapshot['source'],
  reason: string,
): VariablesSnapshot {
  return { available: false, reason, scope, messageId, lastMessageId, source, data: {} };
}

function getNestedValue(target: Record<string, unknown>, path: readonly string[]): unknown {
  let current: unknown = target;
  for (const key of path) {
    if (!current || typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

function setNestedValue(target: Record<string, unknown>, path: readonly string[], value: unknown): void {
  let current: Record<string, unknown> = target;
  for (let index = 0; index < path.length - 1; index += 1) {
    const key = path[index]!;
    const next = current[key];
    if (!next || typeof next !== 'object') {
      const created: Record<string, unknown> = {};
      current[key] = created;
      current = created;
    } else {
      current = next as Record<string, unknown>;
    }
  }
  const lastKey = path[path.length - 1]!;
  if (Array.isArray(current)) {
    const numeric = Number(lastKey);
    if (Number.isInteger(numeric) && numeric >= 0) {
      (current as unknown[])[numeric] = value;
      return;
    }
  }
  current[lastKey] = value;
}

function deleteNestedValue(target: Record<string, unknown>, path: readonly string[]): void {
  let current: unknown = target;
  for (let index = 0; index < path.length - 1; index += 1) {
    if (!current || typeof current !== 'object') return;
    current = (current as Record<string, unknown>)[path[index]!];
  }
  if (!current || typeof current !== 'object') return;
  const lastKey = path[path.length - 1]!;
  if (Array.isArray(current)) {
    const numeric = Number(lastKey);
    if (Number.isInteger(numeric) && numeric >= 0) current.splice(numeric, 1);
    return;
  }
  delete (current as Record<string, unknown>)[lastKey];
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : null;
}

function hasKeys(record: Record<string, unknown> | null): boolean {
  return Boolean(record && Object.keys(record).length > 0);
}

function formatError(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? '未知错误');
}
