import type { PhoneViewContext } from '../app-types.js';
import type { CharacterLock } from '../../fanfic/model.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import { fanficDetailBlock } from './shared.js';

/** 人物锁列表：预览原著约束，并允许人工修正（修正后不再被自动解析覆盖）。 */
export function renderFanficCharacters(context: PhoneViewContext): HTMLElement {
  const fanfic = context.fanfic;
  const view = element('div', { className: 'phone-fanfic-section' });
  view.append(element('p', {
    className: 'phone-settings-hint',
    text: '人物锁约束的是"这个人是谁"：核心人格、价值观底线、认知边界与说话方式。剧情可以改变命运与关系，但这些约束保持原著一致。',
  }));

  if (fanfic.characters.length === 0) {
    const empty = element('div', { className: 'phone-empty' });
    empty.append(
      renderPhoneIcon('worldBook'),
      element('strong', { text: '还没有人物锁' }),
      element('span', { text: '到「来源」页导入原著资料或直接解析角色卡，即可建立人物锁。' }),
    );
    view.append(empty);
    return view;
  }

  const list = element('div', { className: 'phone-fanfic-list' });
  for (const character of fanfic.characters) list.append(renderCharacterCard(context, character));
  view.append(list);
  return view;
}

function renderCharacterCard(context: PhoneViewContext, character: CharacterLock): HTMLElement {
  const card = element('article', { className: `phone-fanfic-character${character.manual ? ' is-manual' : ''}` });
  const head = element('div', { className: 'phone-fanfic-character-head' });
  head.append(
    element('strong', { text: character.name }),
    element('small', {
      text: character.aliases.length > 0 ? `又称：${character.aliases.join('、')}` : '无别名',
    }),
  );
  if (character.manual) head.append(element('span', { className: 'phone-fanfic-tag', text: '已手工修正' }));
  const edit = button('', 'phone-icon-button phone-fanfic-row-action', () => {
    void openCharacterEditor(context, character);
  });
  edit.append(renderPhoneIcon('edit', 'phone-svg-icon'));
  edit.setAttribute('aria-label', `编辑${character.name}的人物锁`);
  edit.title = '手工修正后自动解析不会再覆盖';
  head.append(edit);
  card.append(head);

  for (const block of [
    fanficDetailBlock('核心人格', character.core),
    fanficDetailBlock('价值观与底线', character.values),
    fanficDetailBlock('认知边界', character.knowledge),
    fanficDetailBlock('说话指纹', [
      character.voice.register ? `语体：${character.voice.register}` : '',
      ...character.voice.habits.map((habit) => `习惯：${habit}`),
      ...character.voice.forbidden.map((phrase) => `绝不会说：${phrase}`),
    ]),
    fanficDetailBlock('关系基线', character.relationships.map((relationship) => (
      `${relationship.targetName}：${relationship.summary}`
    ))),
    fanficDetailBlock('原著台词参考', character.signatureLines),
  ]) {
    if (block) card.append(block);
  }
  return card;
}

/** 人物锁编辑：每行一条，保存后标记为手工修正。 */
async function openCharacterEditor(context: PhoneViewContext, character: CharacterLock): Promise<void> {
  const values = await context.showModal(`编辑「${character.name}」人物锁`, [
    { name: 'aliases', label: '别名（每行一个）', type: 'textarea', value: character.aliases.join('\n') },
    { name: 'core', label: '核心人格（每行一条）', type: 'textarea', value: character.core.join('\n') },
    { name: 'values', label: '价值观与底线（每行一条）', type: 'textarea', value: character.values.join('\n') },
    { name: 'knowledge', label: '认知边界（每行一条）', type: 'textarea', value: character.knowledge.join('\n') },
    { name: 'register', label: '语体', value: character.voice.register },
    { name: 'habits', label: '说话习惯（每行一条）', type: 'textarea', value: character.voice.habits.join('\n') },
    { name: 'forbidden', label: '绝不会说（每行一条，会被系统拦截）', type: 'textarea', value: character.voice.forbidden.join('\n') },
    { name: 'signatureLines', label: '原著台词参考（每行一条）', type: 'textarea', value: character.signatureLines.join('\n') },
  ]);
  if (!values) return;
  const next: CharacterLock = {
    ...character,
    aliases: splitLines(values.aliases),
    core: splitLines(values.core),
    values: splitLines(values.values),
    knowledge: splitLines(values.knowledge),
    voice: {
      register: (values.register ?? '').trim(),
      habits: splitLines(values.habits),
      forbidden: splitLines(values.forbidden),
    },
    signatureLines: splitLines(values.signatureLines),
    manual: true,
  };
  const result = await context.fanfic.updateCharacter(next);
  context.showNotice(result.message, result.ok ? 'success' : 'error');
  if (result.ok) context.navigate('fanfic');
}

function splitLines(value: string | undefined): readonly string[] {
  return (value ?? '')
    .split(/\n+/)
    .map((line) => line.trim())
    .filter(Boolean)
    .slice(0, 20);
}