/**
 * 转换产物的落地：带「（墨韵数据）」后缀的新世界书与新角色卡。
 *
 * 三条硬规则：
 * - 只新建，不覆盖：原卡与原世界书一个字节都不动，重名就在后缀后面加序号；
 * - 世界书按原始条目结构改写（走 `/api/worldinfo/get` 拿到的原始字段），保住 position/order/keys 这些设置，
 *   只删掉 MVU 的变量条目、补上一条数据中心的填表协议；
 * - 卡片通过 `/api/characters/import` 以 JSON 形式导入，绑定新书。
 */

import { refreshConvertedResources } from '../integration/resource-refresh.js';
import { withStorySqlDisplayRegexes } from '../integration/story-sql-display.js';
import { logHttpFailure } from '../core/diagnostics.js';
import {
  getCurrentCharacterData,
  getSillyTavernContext,
  getSillyTavernRequestHeaders,
  type SillyTavernContextShape,
} from '../integration/sillytavern-bridge.js';
import { hasMvuCommandMarkers, matchesMvuEntryName, classifyMvuEntry } from './card-source.js';
import { looksLikeMvuSchemaScript } from './zod-schema.js';
import { sanitizeRuleText } from './rules-to-prompt.js';
import type { SheetPresetEntry } from '../db/sheet-preset.js';

export const MOYUN_DATA_SUFFIX = '（墨韵数据）';
export const MOYUN_PROTOCOL_ENTRY_NAME = '【墨韵数据·填表协议】';

export interface CardWriteOptions {
  readonly sourceIdentity?: string;
  readonly presetId?: string;
  /** 原世界书名；空数组表示这张卡没绑世界书，此时只写卡。 */
  readonly bookNames: readonly string[];
  readonly sheets: readonly SheetPresetEntry[];
  readonly sharedGuide: string;
  /** 是否允许正文模型直接输出 IF/SQL（决定协议条目怎么写）。 */
  readonly allowStorySql: boolean;
}

export interface CardWriteResult {
  readonly ok: boolean;
  readonly message: string;
  readonly bookName: string;
  readonly cardName: string;
  readonly removedEntries: readonly string[];
  readonly issues: readonly string[];
}

type RawEntry = Record<string, unknown>;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

/** 加后缀；重名时在后缀后面补序号，永不覆盖已有资源。 */
export function uniqueSuffixedName(base: string, taken: readonly string[], suffix = MOYUN_DATA_SUFFIX): string {
  const trimmed = base.trim() || '未命名';
  const candidate = `${trimmed}${suffix}`;
  if (!taken.includes(candidate)) return candidate;
  for (let index = 2; index < 100; index += 1) {
    const numbered = `${trimmed}${suffix}${index}`;
    if (!taken.includes(numbered)) return numbered;
  }
  return `${trimmed}${suffix}${Date.now().toString(36)}`;
}

/** 一张表在协议里的说明行：列名后跟中文标签，模型照这个写 SQL。 */
function describeSheetForProtocol(sheet: SheetPresetEntry): string {
  const columns = sheet.columns.map((column, index) => `${column}=${sheet.labels[index] ?? column}`).join('，');
  return `- ${sheet.name}（${columns}）：${sheet.purpose}`;
}

/**
 * 填表协议条目正文。这是「把卡转换成 IF 语法支持的格式」的落点：
 * 原来的 `<UpdateVariable>` + `_.set` 协议被换成数据中心的 SQL / IF 语法。
 */
export function buildProtocolEntryContent(options: CardWriteOptions): string {
  const lines = [
    '<墨韵数据·填表协议>',
    '本卡的变量已迁移到墨韵手机「数据中心」的表格，不再使用 MVU 变量框架。',
    '禁止再输出 <UpdateVariable> 段落、<JSONPatch> 块与 `_.set(...)` 命令：没有任何程序会读它们。',
    '',
    '当前的数据表：',
    ...options.sheets.map(describeSheetForProtocol),
    '',
  ];
  if (options.allowStorySql) {
    lines.push(
      '需要改动数据时，在回复末尾输出一个 ```sql 代码块（不需要时就不要输出）：',
      '- 只允许 INSERT / UPDATE / DELETE，表名用上面列出的表名，UPDATE/DELETE 必须带 WHERE。',
      '- 要按现有数据判断时写成 `IF <条件> THEN <SQL>`，一条语句只能有一个 IF，没有 ELSE。',
      '- 条件里读表用 `sheets.<表名>`：`.count` 行数、`.first` / `.last` 首尾行、`.rows[n]` 指定行，行下面接列名或中文标签。',
      '- 例：`IF sheets.角色状态.rows[0].好感度 < 100 THEN UPDATE 角色状态 SET fav = \'62\' WHERE rowid = 1`。',
      '- 写坏的 IF 会被整条丢弃，写不出条件就直接给普通语句。',
    );
  } else {
    lines.push('数据由数据中心的填表模型自动记录，正文里不需要输出任何变量更新语句。');
  }
  if (options.sharedGuide.trim()) {
    lines.push('', '通用状态法则（从原卡的更新规则整理而来）：', options.sharedGuide.trim());
  }
  lines.push('</墨韵数据·填表协议>');
  return lines.join('\n');
}

/**
 * 原始条目 → 是不是要从新书里删掉的 MVU 变量条目。
 *
 * 这里刻意比扫描时更严格：只认标题命名与 `_.set` / `<UpdateVariable>` 这类命令特征。
 * 扫描阶段的「正文形状兜底」会把任何带三个以上叶子的 JSON 当成变量，
 * 用它来决定删条目会误删用户手写的 JSON 设定条目。
 */
export function isRemovableMvuEntry(entry: RawEntry): boolean {
  const name = text(entry.comment) || text(entry.name);
  const content = text(entry.content);
  return matchesMvuEntryName(name) || hasMvuCommandMarkers(content);
}

function nextUid(entries: readonly RawEntry[]): number {
  return entries.reduce((max, entry) => Math.max(max, Number(entry.uid ?? 0) + 1), 0);
}

/** 用原书的一条条目当模板造协议条目：position/role 这些字段沿用原书的常驻条目风格。 */
export function buildProtocolRawEntry(entries: readonly RawEntry[], content: string): RawEntry {
  const uid = nextUid(entries);
  return {
    uid,
    displayIndex: uid,
    key: [],
    keysecondary: [],
    comment: MOYUN_PROTOCOL_ENTRY_NAME,
    content,
    constant: true,
    vectorized: false,
    selective: true,
    selectiveLogic: 0,
    addMemo: true,
    order: 100,
    position: 0,
    disable: false,
    excludeRecursion: true,
    preventRecursion: true,
    delayUntilRecursion: false,
    probability: 100,
    useProbability: true,
    depth: 4,
    group: '',
    groupOverride: false,
    groupWeight: 100,
    scanDepth: null,
    caseSensitive: null,
    matchWholeWords: null,
    useGroupScoring: null,
    automationId: '',
    role: 0,
    sticky: 0,
    cooldown: 0,
    delay: 0,
  };
}

/** 更新规则沿用原条目的开关、关键词和 EJS 条件，只替换旧输出协议。 */
function rewriteUpdateRule(entry: RawEntry): RawEntry | null {
  const name = text(entry.comment) || text(entry.name);
  const source = text(entry.content);
  if (classifyMvuEntry({ name, content: source }) !== 'updateRules') return null;
  const blocks: string[] = [];
  const held = source.replace(/<%[\s\S]*?%>/g, (block) => `MOYUN_EJS_${blocks.push(block) - 1}_END`);
  const content = sanitizeRuleText(held).replace(/MOYUN_EJS_(\d+)_END/g, (_match, index: string) => blocks[Number(index)] ?? '');
  return { ...entry, content: `${source.includes('@@preprocessing') ? '@@preprocessing\n' : ''}${content}\n以上状态变化写入墨韵数据表，遵循填表协议。` };
}

/** 过滤 MVU 初始化和协议条目；规则保留原条目的触发设置。 */
export function rewriteBookEntries(
  entries: Readonly<Record<string, RawEntry>>,
  protocolContent: string,
): { readonly entries: Record<string, RawEntry>; readonly removed: readonly string[] } {
  const kept: RawEntry[] = [];
  const removed: string[] = [];
  for (const entry of Object.values(entries)) {
    if (!isRecord(entry)) continue;
    const rule = rewriteUpdateRule(entry);
    if (rule) { kept.push(rule); continue; }
    if (isRemovableMvuEntry(entry)) {
      removed.push(text(entry.comment) || text(entry.name) || `uid ${String(entry.uid ?? '?')}`);
      continue;
    }
    kept.push(entry);
  }
  const next = [...kept, buildProtocolRawEntry(kept, protocolContent)];
  return {
    entries: Object.fromEntries(next.map((entry, index) => [String(entry.uid ?? index), entry])),
    removed,
  };
}

async function fetchRawBook(bookName: string, context: SillyTavernContextShape): Promise<Record<string, RawEntry>> {
  const response = await fetch('/api/worldinfo/get', {
    method: 'POST',
    headers: getSillyTavernRequestHeaders(context),
    credentials: 'include',
    body: JSON.stringify({ name: bookName }),
  });
  if (!response.ok) {
    logHttpFailure({
      stage: 'MVU 转换读取世界书',
      url: '/api/worldinfo/get',
      status: response.status,
      statusText: response.statusText,
      body: await response.text().catch(() => ''),
      request: { bookName },
    });
    throw new Error(`读取世界书「${bookName}」失败：HTTP ${response.status}`);
  }
  const payload = await response.json() as { entries?: Record<string, RawEntry> };
  return payload.entries ?? {};
}

async function writeRawBook(
  bookName: string,
  entries: Record<string, RawEntry>,
  context: SillyTavernContextShape,
): Promise<void> {
  const response = await fetch('/api/worldinfo/edit', {
    method: 'POST',
    headers: getSillyTavernRequestHeaders(context),
    credentials: 'include',
    body: JSON.stringify({ name: bookName, data: { entries } }),
  });
  if (!response.ok) {
    logHttpFailure({
      stage: 'MVU 转换写入世界书',
      url: '/api/worldinfo/edit',
      status: response.status,
      statusText: response.statusText,
      body: await response.text().catch(() => ''),
      request: { bookName, entryCount: Object.keys(entries).length },
    });
    throw new Error(`写入世界书「${bookName}」失败：HTTP ${response.status}`);
  }
}

function helperBookNames(): readonly string[] {
  try {
    const host = (globalThis.window?.parent ?? globalThis) as unknown as Record<string, unknown>;
    const helper = host.TavernHelper as { getWorldbookNames?: () => readonly string[] } | undefined;
    return helper?.getWorldbookNames?.() ?? [];
  } catch {
    return [];
  }
}

function existingCardNames(context: SillyTavernContextShape): readonly string[] {
  const characters = Array.isArray(context.characters) ? context.characters : [];
  return characters.flatMap((character) => {
    const record = isRecord(character) ? character : null;
    const name = record ? text(record.name) : '';
    return name ? [name] : [];
  });
}

/** 名字或正文表明这是 MVU 变量系统的脚本（结构注册、值守卫、框架加载）。 */
function isMvuScript(entry: Record<string, unknown>): boolean {
  const name = text(entry.name);
  const content = text(entry.content);
  return /mvu|变量结构|变量守卫|变量值守卫|schema/i.test(name)
    || looksLikeMvuSchemaScript(content)
    || /registerMvuSchema|VARIABLE_UPDATE_ENDED/.test(content);
}

/**
 * 关掉卡内的 MVU 脚本。
 * 变量已经搬进数据中心，`registerMvuSchema` 与值守卫会继续按老框架读写 `stat_data`，
 * 两套系统同时跑必然打架；这里只是把脚本停用（保留内容），用户想回退随时能开回来。
 */
function disableMvuScripts(extensions: Record<string, unknown>): { readonly disabled: readonly string[] } {
  const helper = isRecord(extensions.tavern_helper) ? { ...extensions.tavern_helper } : null;
  const scripts = helper && Array.isArray(helper.scripts) ? helper.scripts : null;
  if (!helper || !scripts) return { disabled: [] };
  const disabled: string[] = [];
  helper.scripts = scripts.map((script) => {
    if (!isRecord(script) || !isMvuScript(script)) return script;
    if (script.enabled === false) return script;
    disabled.push(text(script.name) || '未命名脚本');
    return { ...script, enabled: false };
  });
  extensions.tavern_helper = helper;
  return { disabled };
}

/** 角色卡 → 可导入的 V2 JSON；只改名字、世界书绑定、内嵌世界书条目与 MVU 脚本开关。 */
export function buildConvertedCardJson(
  source: unknown,
  cardName: string,
  bookName: string,
  protocolContent: string,
  options: { readonly allowStorySql?: boolean; readonly sourceIdentity?: string; readonly presetId?: string } = {},
): { readonly json: Record<string, unknown>; readonly issues: readonly string[] } {
  const issues: string[] = [];
  const record = isRecord(source) ? source : {};
  const data = isRecord(record.data) ? { ...record.data } : {};
  const legacy = (key: string): string => text(data[key]) || text(record[key]);
  const extensions = isRecord(data.extensions) ? { ...data.extensions } : {};
  extensions.world = bookName;
  if (options.allowStorySql) extensions.regex_scripts = withStorySqlDisplayRegexes(extensions.regex_scripts);
  if (options.sourceIdentity) extensions.moyun_data = { sourceIdentity: options.sourceIdentity, presetId: options.presetId, sourceName: legacy('name') };
  const scripts = disableMvuScripts(extensions);
  if (scripts.disabled.length > 0) {
    issues.push(`新卡里已停用 MVU 脚本：${scripts.disabled.slice(0, 6).join('、')}（变量改由数据中心维护）。`);
  }

  const characterBook = isRecord(data.character_book) ? { ...data.character_book } : null;
  if (characterBook) {
    const bookEntries = Array.isArray(characterBook.entries) ? characterBook.entries : [];
    const kept = bookEntries.flatMap((entry) => {
      if (!isRecord(entry)) return [];
      const rule = rewriteUpdateRule(entry);
      return rule ? [rule] : !isRemovableMvuEntry(entry) ? [entry] : [];
    });
    characterBook.name = bookName;
    characterBook.entries = [...kept, {
      keys: [],
      secondary_keys: [],
      comment: MOYUN_PROTOCOL_ENTRY_NAME,
      content: protocolContent,
      constant: true,
      selective: true,
      insertion_order: 100,
      enabled: true,
      position: 'before_char',
      extensions: { position: 0, depth: 4, prevent_recursion: true, exclude_recursion: true },
    }];
    if (bookEntries.length !== kept.length) {
      issues.push(`卡内嵌世界书里移除了 ${bookEntries.length - kept.length} 条 MVU 变量条目。`);
    }
  }

  const nextData: Record<string, unknown> = {
    ...data,
    name: cardName,
    description: legacy('description'),
    personality: legacy('personality'),
    scenario: legacy('scenario'),
    first_mes: legacy('first_mes'),
    mes_example: legacy('mes_example'),
    extensions,
    ...(characterBook ? { character_book: characterBook } : {}),
  };

  return {
    json: {
      spec: 'chara_card_v2',
      spec_version: '2.0',
      name: cardName,
      description: nextData.description,
      personality: nextData.personality,
      scenario: nextData.scenario,
      first_mes: nextData.first_mes,
      mes_example: nextData.mes_example,
      data: nextData,
    },
    issues,
  };
}

async function importCard(cardName: string, json: Record<string, unknown>, context: SillyTavernContextShape): Promise<void> {
  const headers = { ...getSillyTavernRequestHeaders(context) } as Record<string, string>;
  delete headers['Content-Type'];
  const form = new FormData();
  form.append('avatar', new File([JSON.stringify(json)], `${cardName}.json`, { type: 'application/json' }));
  form.append('file_type', 'json');
  const response = await fetch('/api/characters/import', {
    method: 'POST',
    headers,
    credentials: 'include',
    body: form,
    cache: 'no-cache',
  });
  const payload = response.ok ? await response.json().catch(() => null) as { error?: boolean } | null : null;
  if (!response.ok || payload?.error === true) {
    logHttpFailure({
      stage: 'MVU 转换导入角色卡',
      url: '/api/characters/import',
      status: response.status,
      statusText: response.statusText,
      body: JSON.stringify(payload ?? {}),
      request: { cardName },
    });
    throw new Error(`导入角色卡「${cardName}」失败：HTTP ${response.status}`);
  }
}

/**
 * 写出转换后的世界书与角色卡。
 * 世界书按原书逐一改写（一本原书对应一本新书），卡片绑定第一本新书。
 */
export async function writeConvertedCard(options: CardWriteOptions): Promise<CardWriteResult> {
  const context = getSillyTavernContext();
  const issues: string[] = [];
  const removed: string[] = [];
  const protocolContent = buildProtocolEntryContent(options);
  const takenBooks = [...helperBookNames()];
  const newBookNames: string[] = [];

  for (const bookName of options.bookNames) {
    const raw = await fetchRawBook(bookName, context);
    const rewritten = rewriteBookEntries(raw, protocolContent);
    const nextName = uniqueSuffixedName(bookName, takenBooks);
    await writeRawBook(nextName, rewritten.entries, context);
    takenBooks.push(nextName);
    newBookNames.push(nextName);
    removed.push(...rewritten.removed);
  }

  const source = getCurrentCharacterData(context);
  const sourceName = text(isRecord(source) ? source.name : '') || '未命名角色';
  const cardName = uniqueSuffixedName(sourceName, existingCardNames(context));
  const bookName = newBookNames[0] ?? '';
  const card = buildConvertedCardJson(source, cardName, bookName, protocolContent, options);
  issues.push(...card.issues);
  await importCard(cardName, card.json, context);
  issues.push(...await refreshConvertedResources());

  return {
    ok: true,
    message: bookName
      ? `已新建角色卡「${cardName}」与世界书「${newBookNames.join('、')}」。`
      : `已新建角色卡「${cardName}」（原卡没有绑定世界书，因此只写了卡）。`,
    bookName,
    cardName,
    removedEntries: [...new Set(removed)],
    issues,
  };
}
