import type { CanonChunk, CanonFact } from './model.js';

export interface CanonRetrievalRequest {
  /** 本轮查询文本：最近正文、用户输入与待处理手机内容的拼接。 */
  readonly query: string;
  /** 在场或被提到的角色；命中的事实会显著加权。 */
  readonly characterIds: readonly string[];
  readonly limit: number;
}

export interface ScoredCanonFact {
  readonly fact: CanonFact;
  readonly score: number;
}

const CONFIDENCE_WEIGHT = Object.freeze({ high: 3, medium: 1, low: -2 });
/** 人物锁相关的事实类型优先注入，剧情事件次之。 */
const KIND_WEIGHT = Object.freeze({
  trait: 4, value: 4, voice: 4, knowledge: 3, relationship: 2, rule: 2, event: 1,
});
/**
 * 逐条计算 gram 相关度的成本与原著体量成正比：整本长篇会有上千个分块、上千条事实，
 * 每轮生成都全量计算会卡住界面。超过这些数量时先用原生正则粗筛出候选，再精算分数。
 */
const MAX_SCORED_CHUNKS = 300;
const MAX_SCORED_FACTS = 400;
const MAX_PREFILTER_GRAMS = 32;

/**
 * 原著事实召回：角色命中 + 词法相关度 + 事实类型 + 可信度的确定性打分。
 * 不依赖向量服务，向量可用时由调用方在此结果之上再做重排。
 */
export function rankCanonFacts(
  facts: readonly CanonFact[],
  request: CanonRetrievalRequest,
): readonly ScoredCanonFact[] {
  const queryGrams = createMatchGrams(request.query);
  const characters = new Set(request.characterIds.filter(Boolean));
  const limit = Math.max(0, Math.floor(request.limit));
  if (limit === 0) return [];
  return narrowFacts(facts, request.query, characters)
    .map((fact) => ({ fact, score: scoreFact(fact, queryGrams, characters) }))
    .filter((scored) => scored.score > 0)
    .sort((left, right) => (
      right.score - left.score || left.fact.id.localeCompare(right.fact.id)
    ))
    .slice(0, limit);
}

function scoreFact(
  fact: CanonFact,
  queryGrams: ReadonlySet<string>,
  characters: ReadonlySet<string>,
): number {
  const mentioned = fact.characterIds.some((id) => characters.has(id));
  const characterScore = mentioned ? 8 : (fact.characterIds.length === 0 ? 1 : 0);
  // 与在场角色完全无关、又没有词法命中的事实不进入上下文，避免注入无关原著段落。
  const lexicalScore = overlapScore(fact.text, queryGrams);
  if (characterScore === 0 && lexicalScore === 0) return 0;
  const base = characterScore + lexicalScore + KIND_WEIGHT[fact.kind] + CONFIDENCE_WEIGHT[fact.confidence];
  return Math.max(0, base);
}

/** 原著原文召回：人物锁不够用时补充可引用的具体段落。 */
export function rankCanonChunks(
  chunks: readonly CanonChunk[],
  query: string,
  limit: number,
): readonly CanonChunk[] {
  const queryGrams = createMatchGrams(query);
  const bounded = Math.max(0, Math.floor(limit));
  if (bounded === 0 || queryGrams.size === 0) return [];
  return narrowChunks(chunks, query)
    .map((chunk) => ({ chunk, score: overlapScore(`${chunk.heading}\n${chunk.text}`, queryGrams) }))
    .filter((scored) => scored.score > 0)
    .sort((left, right) => right.score - left.score || left.chunk.id.localeCompare(right.chunk.id))
    .slice(0, bounded)
    .map((scored) => scored.chunk);
}

/**
 * 事实粗筛：只在事实条数超过上限时启用，保证中小规模原著库的结果与逐条精算完全一致。
 * 在场角色相关的事实优先保留（它们不依赖词法命中也会得分），其次是命中查询探针的，
 * 最后用无角色标注的通用事实补齐候选池。
 */
function narrowFacts(
  facts: readonly CanonFact[],
  query: string,
  characters: ReadonlySet<string>,
): readonly CanonFact[] {
  if (facts.length <= MAX_SCORED_FACTS) return facts;
  const probes = createPrefilterProbes(query);
  const related: CanonFact[] = [];
  const matched: { readonly fact: CanonFact; readonly hits: number }[] = [];
  const generic: CanonFact[] = [];
  for (const fact of facts) {
    if (fact.characterIds.some((id) => characters.has(id))) {
      related.push(fact);
      continue;
    }
    const hits = probeHits(fact.text, probes);
    if (hits > 0) {
      matched.push({ fact, hits });
      continue;
    }
    if (fact.characterIds.length === 0) generic.push(fact);
  }
  const ordered = [
    ...related,
    ...matched
      .slice()
      .sort((left, right) => right.hits - left.hits || left.fact.id.localeCompare(right.fact.id))
      .map((entry) => entry.fact),
    ...generic,
  ];
  return ordered.slice(0, MAX_SCORED_FACTS);
}

/** 原文粗筛：整本长篇会有上千个分块，先用探针挑出最可能命中的若干块再精算。 */
function narrowChunks(chunks: readonly CanonChunk[], query: string): readonly CanonChunk[] {
  if (chunks.length <= MAX_SCORED_CHUNKS) return chunks;
  const probes = createPrefilterProbes(query);
  if (probes.length === 0) return chunks.slice(0, MAX_SCORED_CHUNKS);
  return chunks
    .map((chunk) => ({ chunk, hits: probeHits(`${chunk.heading}\n${chunk.text}`, probes) }))
    .filter((entry) => entry.hits > 0)
    .sort((left, right) => right.hits - left.hits || left.chunk.id.localeCompare(right.chunk.id))
    .slice(0, MAX_SCORED_CHUNKS)
    .map((entry) => entry.chunk);
}

/**
 * 粗筛探针：从查询里等距取若干 3-gram。
 * 用原生子串搜索代替「为每个候选构建 gram 集合」，是大原著库下唯一能扛住的做法。
 */
function createPrefilterProbes(query: string): readonly string[] {
  const compact = compactText(query);
  if (compact.length < 3) return [];
  const step = Math.max(1, Math.ceil((compact.length - 2) / MAX_PREFILTER_GRAMS));
  const probes = new Set<string>();
  for (let index = 0; index + 3 <= compact.length && probes.size < MAX_PREFILTER_GRAMS; index += step) {
    probes.add(compact.slice(index, index + 3));
  }
  return [...probes];
}

function probeHits(text: string, probes: readonly string[]): number {
  if (probes.length === 0) return 0;
  const compact = compactText(text);
  let hits = 0;
  for (const probe of probes) {
    if (compact.includes(probe)) hits += 1;
  }
  return hits;
}

export function overlapScore(text: string, queryGrams: ReadonlySet<string>): number {
  if (queryGrams.size === 0) return 0;
  let score = 0;
  for (const gram of createMatchGrams(text)) {
    if (!queryGrams.has(gram)) continue;
    score += gram.length >= 3 ? 2 : 1;
  }
  // 长段落天然命中更多 gram，用对数压缩长度优势。
  return score === 0 ? 0 : Math.round(score / Math.log2(Math.max(4, text.length)) * 10) / 10;
}

export function createMatchGrams(value: string): ReadonlySet<string> {
  const compact = compactText(value);
  const grams = new Set<string>();
  for (const size of [2, 3]) {
    for (let index = 0; index <= compact.length - size; index += 1) {
      grams.add(compact.slice(index, index + size));
    }
  }
  return grams;
}

/** 归一化：去标签、去标点与空白，只留字母数字与汉字，供 gram 与探针共用。 */
function compactText(value: string): string {
  return value
    .toLocaleLowerCase()
    .replace(/<[^>]{0,500}>/g, ' ')
    .replace(/[^\p{L}\p{N}]+/gu, '');
}