import type { PhoneViewContext } from './app-types.js';
import type { Profile } from '../domain/model.js';
import {
  isAvatarPromptComplete,
  type AvatarPromptDraft,
} from '../generation/avatar-prompt.js';
import { button, element } from '../ui/dom.js';
import { resizeImageSourceAsDataUrl } from './shared-view.js';

export interface ProfileAvatarGeneratorOptions {
  readonly context: PhoneViewContext;
  readonly profile: Profile;
  readonly avatarField: 'avatarUrl' | 'twitterAvatarUrl';
  readonly appearanceInput: HTMLTextAreaElement;
  readonly getDraft: () => AvatarPromptDraft;
  readonly onAvatarApplied: (url: string) => void;
}

export interface ProfileAvatarGeneratorView {
  readonly control: HTMLElement;
  readonly promptInput: HTMLTextAreaElement;
}

/** 创建资料页共用的头像提示词/生图状态机。 */
export function createProfileAvatarGenerator(options: ProfileAvatarGeneratorOptions): ProfileAvatarGeneratorView {
  const { context, profile } = options;
  const control = element('div', { className: 'phone-profile-avatar-generator' });
  const promptInput = element('textarea', {
    className: 'phone-modal-input phone-profile-avatar-prompt',
    attributes: {
      rows: '3',
      maxlength: '1600',
      placeholder: '先生成角色头像提示词；标签完整后即可生成图片',
      'aria-label': '角色头像提示词',
    },
  });
  promptInput.value = profile.avatarPrompt ?? '';
  const status = element('small', { className: 'phone-settings-hint phone-profile-avatar-status' });
  const action = button('', 'phone-button phone-button-primary phone-profile-avatar-action');
  let busy = false;

  const refreshState = () => {
    const ready = isAvatarPromptComplete(promptInput.value);
    action.textContent = ready ? '生成图片' : '生成提示词';
    action.dataset.mode = ready ? 'image' : 'prompt';
    status.textContent = ready ? '标签完整，可以生成头像图片' : '需要完整的角色外貌与头像构图标签';
  };

  const run = async () => {
    if (busy) return;
    busy = true;
    action.disabled = true;
    const ready = isAvatarPromptComplete(promptInput.value);
    action.textContent = ready ? '图片生成中…' : '提示词生成中…';
    status.textContent = ready ? '正在调用生图供应商' : '正在调用模型整理角色外貌';
    try {
      if (!ready) {
        const result = await context.generateAvatarPrompt({
          profileId: profile.id,
          draft: options.getDraft(),
        });
        promptInput.value = result.prompt;
        options.appearanceInput.value = result.appearancePrompt;
        await context.commands.updateProfile(profile.id, {
          appearancePrompt: result.appearancePrompt,
          avatarPrompt: result.prompt,
        });
        context.showNotice('头像提示词已生成，标签检测完整。', 'success');
      } else {
        const prompt = promptInput.value.trim();
        const source = await context.generateImage(prompt);
        const avatarUrl = await resizeImageSourceAsDataUrl(source, 512);
        await context.commands.updateProfile(profile.id, {
          avatarPrompt: prompt,
          [options.avatarField]: avatarUrl,
        });
        options.onAvatarApplied(avatarUrl);
        context.showNotice('头像已生成并自动应用。', 'success');
      }
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      status.textContent = '生成失败，请检查模型或生图配置后重试';
    } finally {
      busy = false;
      action.disabled = false;
      refreshState();
    }
  };

  promptInput.addEventListener('input', refreshState);
  action.addEventListener('click', () => { void run(); });
  refreshState();
  control.append(action, status, promptInput);
  return { control, promptInput };
}