/**
 * MVU 更新规则里的机械约束 → 数据中心 IF 语法门控。
 *
 * 只编译能靠字面判定的五类约束（只读、不可逆布尔、单调上涨、取值区间、增长递减），
 * 其余一律原文保留成自然语言规则。编译出来的条件都过 `validateSheetCondition`，
 * 语法不过就退回自然语言——宁可少一条门控，也不能往表里写进解析不了的条件。
 */

import { validateSheetCondition } from '../db/sheet-condition.js';

export type MvuConstraintKind = 'readonly' | 'irreversibleBoolean' | 'monotonicUp' | 'range' | 'decay';

export interface MvuConstraint {
  readonly kind: MvuConstraintKind;
  /** 字段的中文标签（就是 MVU 里的叶子键）。 */
  readonly field: string;
  /** 区间等附加信息；没有就是空串。 */
  readonly detail: string;
}

export interface CompiledConstraints {
  readonly constraints: readonly MvuConstraint[];
  /** 直接写进填表规则的提示行。 */
  readonly lines: readonly string[];
  readonly issues: readonly string[];
}

const READONLY_PATTERN = /只读|不得自行修改|不可修改|禁止修改|不允许修改|AI\s*不得/;
const IRREVERSIBLE_PATTERN = /不可逆/;
const MONOTONIC_PATTERN = /只能上涨|只增不减|不能下降|只能增加|单调递增|只增/;
const DECAY_PATTERN = /递减/;
const RANGE_PATTERN = /(?:number|数值|整数)?\s*[（(]?\s*(\d{1,4})\s*[-~－—]\s*(\d{1,5})\s*[)）]?/;
const BOOLEAN_PATTERN = /boolean|布尔|true|false/i;

/** 单行表用 `.first` 定位，多行表用 `rows[0]` 做示例。 */
export function conditionPathFor(sheetName: string, field: string, multiRow: boolean): string {
  return `sheets.${sheetName}.${multiRow ? 'rows[0]' : 'first'}.${field}`;
}

function safeCondition(condition: string): string {
  return validateSheetCondition(condition) === null ? condition : '';
}

/** 从一段字段规则原文里识别约束。 */
export function detectConstraints(field: string, body: string): readonly MvuConstraint[] {
  const constraints: MvuConstraint[] = [];
  if (READONLY_PATTERN.test(body)) constraints.push({ kind: 'readonly', field, detail: '' });
  if (IRREVERSIBLE_PATTERN.test(body) && BOOLEAN_PATTERN.test(body)) {
    constraints.push({ kind: 'irreversibleBoolean', field, detail: '' });
  }
  if (MONOTONIC_PATTERN.test(body)) constraints.push({ kind: 'monotonicUp', field, detail: '' });
  const range = RANGE_PATTERN.exec(body);
  if (range && range[1] && range[2]) {
    constraints.push({ kind: 'range', field, detail: `${range[1]}-${range[2]}` });
  }
  if (DECAY_PATTERN.test(body)) constraints.push({ kind: 'decay', field, detail: '' });
  return constraints;
}

/**
 * 约束 → 提示行。
 * `multiRow` 决定条件示例用 `rows[0]` 还是 `.first`；实体表里模型需要自己换成对应对象所在行。
 */
export function compileConstraintLines(
  sheetName: string,
  constraints: readonly MvuConstraint[],
  multiRow: boolean,
): CompiledConstraints {
  const issues: string[] = [];
  const lines: string[] = [];

  const readonlyFields = constraints.filter((item) => item.kind === 'readonly').map((item) => item.field);
  if (readonlyFields.length > 0) {
    lines.push(`只读字段（任何情况下都不要写入）：${[...new Set(readonlyFields)].join('、')}。`);
  }

  for (const constraint of constraints) {
    if (constraint.kind === 'readonly') continue;
    const path = conditionPathFor(sheetName, constraint.field, multiRow);
    const rowHint = multiRow ? '（把 rows[0] 换成该对象所在行）' : '';
    if (constraint.kind === 'irreversibleBoolean') {
      const condition = safeCondition(`${path} != 'true'`);
      if (!condition) {
        issues.push(`${sheetName}·${constraint.field}：不可逆约束无法编译成条件，已按自然语言保留。`);
        lines.push(`「${constraint.field}」不可逆：只允许从 false 改成 true，不得改回。`);
        continue;
      }
      lines.push(`「${constraint.field}」不可逆：只允许 false→true，写成 \`IF ${condition} THEN UPDATE ...\`${rowHint}。`);
      continue;
    }
    if (constraint.kind === 'monotonicUp') {
      const condition = safeCondition(`${path} < 100`);
      lines.push(condition
        ? `「${constraint.field}」只能上涨：先比大小再写，写成 \`IF ${path} < <新值> THEN UPDATE ...\`${rowHint}。`
        : `「${constraint.field}」只能上涨，不得下降。`);
      continue;
    }
    if (constraint.kind === 'range') {
      lines.push(`「${constraint.field}」取值范围 ${constraint.detail}，超出请裁剪到边界。`);
      continue;
    }
    lines.push(`「${constraint.field}」增长有递减规则，按原文的分段系数执行，不要线性加减。`);
  }

  return { constraints, lines: [...new Set(lines)], issues };
}