import type { PhoneRoute, PhoneViewContext } from '../app-types.js';
import type { PhonePost } from '../../domain/model.js';
import { button, element, type ModalField } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import {
  buildForumIndex,
  FORUM_DEFAULT_BOARD,
  pinnedFirst,
  sortForumThreads,
  type ForumBoardView,
  type ForumFloor,
  type ForumIndexView,
  type ForumSort,
  type ForumThreadView,
} from './projection.js';
import {
  forumAvatarProfile,
  forumIdentity,
  forumTime,
  renderForumEmpty,
  renderSectionHead,
  renderThreadRow,
} from './shared.js';
import { renderAvatar } from '../shared-view.js';
import { forumView } from './view-state.js';

const SORT_LABELS: Readonly<Record<ForumSort, string>> = {
  latest: '最新',
  heat: '热度',
  replies: '回复',
};

const ACTIVITY_LABELS = {
  quiet: '安静',
  balanced: '均衡',
  lively: '活跃',
  bustling: '沸腾',
} as const;

const HOME_LATEST_LIMIT = 5;
const HOME_HOT_LIMIT = 3;
const HOT_RANK_LIMIT = 12;

export function openForumThread(context: PhoneViewContext, thread: PhonePost): void {
  forumView.detailPostId = thread.id;
  if (context.route !== 'forumPost') {
    forumView.returnRoute = context.route.startsWith('forum') ? context.route : 'forum';
  }
  context.navigate('forumPost');
}

export function renderForumHome(context: PhoneViewContext): HTMLElement {
  const index = buildForumIndex(context.state);
  const page = element('div', { className: 'phone-page phone-forum-page phone-forum-home' });
  page.append(renderForumHeader(
    context.appTitle('论坛'),
    `${index.boards.length} 个板块 · ${index.threads.length} 个主题 · ${index.totalReplies} 条回复`,
    [createRefreshButton(context)],
  ));
  page.append(renderForumPulse(context, index));
  page.append(
    renderSectionHead('板块区', '点板块直接进入', [
      button('新建板块', 'phone-button phone-button-secondary phone-forum-section-action', () => createBoard(context)),
    ]),
    renderBoardDirectory(context, index),
  );

  if (index.threads.length === 0) {
    // 一个板块都没有时，板块区里的空态已经把下一步说清楚了，不再叠第二张空卡片。
    if (index.boards.length > 0) {
      page.append(renderForumEmpty('论坛暂时没有主题', '使用“论坛自转”生成第一批 NPC 主题，或进入板块发布。'));
    }
    return page;
  }

  const pinned = index.threads.filter((view) => view.pinned);
  const rest = index.threads.filter((view) => !view.pinned);
  const hot = sortForumThreads(rest, 'heat').slice(0, HOME_HOT_LIMIT);
  const latest = sortForumThreads(rest, 'latest').slice(0, HOME_LATEST_LIMIT);
  if (pinned.length > 0) {
    page.append(renderSectionHead('公告与置顶', `${pinned.length} 条`), renderThreadList(context, pinned));
  }
  if (hot.length > 0) {
    page.append(renderSectionHead('正在发酵', '首页只保留 3 个焦点'), renderThreadList(context, hot));
  }
  page.append(renderSectionHead('刚刚发生', `最近 ${latest.length} 个主题`), renderThreadList(context, latest));
  page.append(renderHomeShortcuts(context));
  return page;
}

export function renderForumBoard(context: PhoneViewContext): HTMLElement {
  const index = buildForumIndex(context.state);
  const selectedBoard = resolveSelectedBoard(index);
  forumView.board = selectedBoard;
  const page = element('div', { className: 'phone-page phone-forum-page phone-forum-board-page' });
  page.append(renderForumHeader(
    selectedBoard ?? '板块广场',
    selectedBoard ? '板块内浏览、排序、发布与板块自转' : '还没有板块，先回首页的板块区新建一个',
    selectedBoard
      ? [
        button('发布主题', 'phone-button phone-button-primary phone-forum-compose', () => composeThread(context, index)),
        createBoardRefreshButton(context, selectedBoard),
      ]
      : [],
  ));
  if (!selectedBoard) {
    page.append(renderForumEmpty('还没有可浏览的板块', '回到首页板块区新建板块，或让论坛自转先写出内容板块。'));
    return page;
  }

  const scoped = index.threads.filter((view) => view.board === selectedBoard);
  page.append(renderSortChips(context));
  if (scoped.length === 0) {
    page.append(renderForumEmpty('这个板块还没有主题', '可在当前板块发布第一个主题，或用“板块自转”只生成这个板块的内容。'));
    return page;
  }
  page.append(
    renderSectionHead('板块主题', `${scoped.length} 条 · ${SORT_LABELS[forumView.sort]}排序`),
    renderThreadList(context, pinnedFirst(sortForumThreads(scoped, forumView.sort))),
  );
  return page;
}

/** 板块页只展示单个板块：沿用上次选择，选择失效时退回第一个板块，保证底部导航直接可用。 */
function resolveSelectedBoard(index: ForumIndexView): string | null {
  const current = forumView.board;
  if (current && index.boards.some((board) => board.name === current)) return current;
  return index.boards[0]?.name ?? null;
}

export function renderForumHot(context: PhoneViewContext): HTMLElement {
  const index = buildForumIndex(context.state);
  const page = element('div', { className: 'phone-page phone-forum-page phone-forum-hot-page' });
  const estimated = index.threads.some((view) => view.heatEstimated);
  page.append(renderForumHeader(
    '社区热榜',
    estimated ? '带 * 的热度由公开回复与新鲜度推算' : '按正文公开浏览、点赞与评论计数排名',
  ));
  if (index.threads.length === 0) {
    page.append(renderForumEmpty('还没有可以排名的主题', '论坛有内容后，这里才会形成榜单与实时讨论流。'));
    return page;
  }

  const ranking = element('div', { className: 'phone-forum-list phone-forum-ranking' });
  sortForumThreads(index.threads, 'heat').slice(0, HOT_RANK_LIMIT).forEach((view, position) => {
    ranking.append(renderThreadRow(context, view, {
      rank: position + 1,
      onOpen: () => openForumThread(context, view.thread),
    }));
  });
  page.append(renderSectionHead('热度排名', `TOP ${Math.min(HOT_RANK_LIMIT, index.threads.length)}`), ranking);

  const activity = collectForumActivity(index).slice(0, 10);
  page.append(renderSectionHead('实时讨论流', activity.length > 0 ? `${activity.length} 条最近回复` : '暂无楼层活动'));
  if (activity.length > 0) page.append(renderActivityStream(context, activity));
  return page;
}

export function renderForumMe(context: PhoneViewContext): HTMLElement {
  const index = buildForumIndex(context.state);
  const selfId = 'profile:self';
  const mine = sortForumThreads(index.threads.filter((view) => view.thread.profileId === selfId), 'latest');
  const joined = sortForumThreads(index.threads.filter((view) => view.thread.profileId !== selfId
    && view.floors.some((floor) => containsSelfFloor(floor, selfId))), 'latest');
  const page = element('div', { className: 'phone-page phone-forum-page phone-forum-me-page' });
  page.append(renderForumHeader('我的论坛', '公开身份、论坛参数与个人讨论记录集中管理'));
  page.append(renderIdentityCard(context));
  page.append(renderForumSettings(context));

  if (mine.length === 0 && joined.length === 0) {
    page.append(renderForumEmpty('你还没有论坛足迹', '发布主题或参与讨论后，记录会出现在这里。'));
    return page;
  }
  if (mine.length > 0) {
    page.append(renderSectionHead('我发布的', `${mine.length} 个主题`), renderThreadList(context, mine));
  }
  if (joined.length > 0) {
    page.append(renderSectionHead('我参与的', `${joined.length} 个讨论`), renderThreadList(context, joined));
  }
  return page;
}

function renderForumHeader(title: string, subtitle: string, actions: readonly HTMLElement[] = []): HTMLElement {
  const header = element('header', { className: 'phone-forum-header' });
  const heading = element('div', { className: 'phone-forum-heading' });
  heading.append(
    element('span', { className: 'phone-forum-kicker', text: 'FORUM' }),
    element('h2', { text: title }),
    element('p', { text: subtitle }),
  );
  header.append(heading);
  if (actions.length > 0) {
    const actionRow = element('div', { className: 'phone-forum-header-actions' });
    actionRow.append(...actions);
    header.append(actionRow);
  }
  return header;
}

/** 首页只留主题、楼层与近一天回复三个计数；运行参数在“我的”里查看和调整。 */
function renderForumPulse(context: PhoneViewContext, index: ForumIndexView): HTMLElement {
  const recentReplies = collectForumActivity(index).filter((item) => (
    context.state.worldClock.now - item.floor.createdAt <= 86_400_000
  )).length;
  const card = element('section', { className: 'phone-forum-pulse' });
  const stats = element('div', { className: 'phone-forum-pulse-stats' });
  stats.append(
    pulseStat(String(index.threads.length), '主题'),
    pulseStat(String(index.totalReplies), '楼层'),
    pulseStat(String(recentReplies), '近一天'),
  );
  card.append(stats);
  return card;
}

function pulseStat(value: string, label: string): HTMLElement {
  const stat = element('span');
  stat.append(element('strong', { text: value }), element('small', { text: label }));
  return stat;
}

function renderHomeShortcuts(context: PhoneViewContext): HTMLElement {
  const shortcuts = element('div', { className: 'phone-forum-shortcuts' });
  shortcuts.append(
    shortcut('进入板块', '按板块浏览与发布', 'forum', () => context.navigate('forumBoard')),
    shortcut('查看热榜', '排名与实时回复流', 'summary', () => context.navigate('forumHot')),
    shortcut('论坛管理', '身份、参数与我的内容', 'settings', () => context.navigate('forumMe')),
  );
  return shortcuts;
}

function shortcut(
  title: string,
  detail: string,
  icon: Parameters<typeof renderPhoneIcon>[0],
  onOpen: () => void,
): HTMLElement {
  const item = button('', 'phone-forum-shortcut', onOpen);
  const iconBox = element('span', { className: 'phone-forum-shortcut-icon' });
  iconBox.append(renderPhoneIcon(icon));
  const copy = element('span');
  copy.append(element('strong', { text: title }), element('small', { text: detail }));
  item.append(iconBox, copy, renderPhoneIcon('chevron'));
  return item;
}

/** 板块区：点卡片进入板块，右下角是编辑与删除。缺省归属的「综合讨论」不是真实板块，不给管理入口。 */
function renderBoardDirectory(context: PhoneViewContext, index: ForumIndexView): HTMLElement {
  const section = element('section', { className: 'phone-forum-board-directory' });
  const grid = element('div', { className: 'phone-forum-board-grid' });
  for (const board of index.boards) {
    const card = element('article', { className: 'phone-forum-board-card' });
    const open = button('', 'phone-forum-board-open', () => {
      forumView.board = board.name;
      context.navigate('forumBoard');
    });
    const copy = element('span', { className: 'phone-forum-board-copy' });
    copy.append(
      element('strong', { text: board.name }),
      element('small', { text: board.description || `${board.threadCount} 个主题 · ${board.replyCount} 条回复` }),
    );
    open.append(copy, element('span', { className: 'phone-forum-board-count', text: String(board.threadCount) }));
    card.append(open);
    if (board.manageable) card.append(renderBoardActions(context, board));
    grid.append(card);
  }
  if (index.boards.length === 0) {
    grid.append(renderForumEmpty('还没有板块', '创建自定义板块后即可发布主题。'));
  }
  section.append(grid);
  return section;
}

function renderBoardActions(context: PhoneViewContext, board: ForumBoardView): HTMLElement {
  const actions = element('div', { className: 'phone-forum-board-actions' });
  const edit = button('', 'phone-icon-button', () => editBoard(context, board));
  edit.append(renderPhoneIcon('edit'));
  edit.title = `编辑板块 ${board.name}`;
  edit.setAttribute('aria-label', edit.title);
  const remove = button('', 'phone-icon-button phone-forum-danger-action', () => deleteBoard(context, board));
  remove.append(renderPhoneIcon('trash'));
  remove.title = `删除板块 ${board.name}`;
  remove.setAttribute('aria-label', remove.title);
  actions.append(edit, remove);
  return actions;
}

function renderSortChips(context: PhoneViewContext): HTMLElement {
  const row = element('div', { className: 'phone-forum-sort-chips' });
  for (const sort of Object.keys(SORT_LABELS) as readonly ForumSort[]) {
    const chip = button(SORT_LABELS[sort], `phone-forum-sort-chip${forumView.sort === sort ? ' is-active' : ''}`, () => {
      forumView.sort = sort;
      context.navigate('forumBoard');
    });
    chip.setAttribute('aria-pressed', String(forumView.sort === sort));
    row.append(chip);
  }
  return row;
}

function renderThreadList(context: PhoneViewContext, threads: readonly ForumThreadView[]): HTMLElement {
  const list = element('div', { className: 'phone-forum-list' });
  for (const view of threads) {
    list.append(renderThreadRow(context, view, { onOpen: () => openForumThread(context, view.thread) }));
  }
  return list;
}

interface ForumActivityItem {
  readonly thread: ForumThreadView;
  readonly floor: ForumFloor;
}

function collectForumActivity(index: ForumIndexView): readonly ForumActivityItem[] {
  const items: ForumActivityItem[] = [];
  const append = (thread: ForumThreadView, floor: ForumFloor): void => {
    items.push({ thread, floor });
    for (const child of floor.children) append(thread, child);
  };
  for (const thread of index.threads) {
    for (const floor of thread.floors) append(thread, floor);
  }
  return items.sort((left, right) => right.floor.createdAt - left.floor.createdAt);
}

function renderActivityStream(context: PhoneViewContext, items: readonly ForumActivityItem[]): HTMLElement {
  const stream = element('div', { className: 'phone-forum-activity-stream' });
  for (const item of items) {
    const row = button('', 'phone-forum-activity-row', () => openForumThread(context, item.thread.thread));
    row.append(renderAvatar(
      forumAvatarProfile(context.state.profiles[item.floor.profileId]),
      'phone-avatar phone-forum-activity-avatar',
    ));
    const copy = element('span', { className: 'phone-forum-activity-copy' });
    copy.append(
      element('strong', { text: `${forumIdentity(context, item.floor.profileId)} 回复了「${item.thread.title}」` }),
      element('span', { text: excerpt(item.floor.content, 76) }),
      element('small', { text: `${forumTime(item.floor.createdAt, item.floor.timeLabel)} · ${item.floor.floor} 楼` }),
    );
    row.append(copy);
    stream.append(row);
  }
  return stream;
}

function renderIdentityCard(context: PhoneViewContext): HTMLElement {
  const profile = context.state.profiles['profile:self'];
  const card = element('section', { className: 'phone-forum-profile-card' });
  card.append(renderAvatar(forumAvatarProfile(profile), 'phone-avatar phone-forum-profile-avatar'));
  const copy = element('div', { className: 'phone-forum-profile-copy' });
  copy.append(
    element('span', { className: 'phone-forum-pulse-label', text: '公开论坛身份' }),
    element('strong', { text: forumIdentity(context, 'profile:self') }),
    element('p', { text: profile?.forumBio?.trim() || '尚未填写论坛简介。' }),
  );
  const edit = button('编辑身份', 'phone-button phone-button-secondary', () => editForumIdentity(context));
  card.append(copy, edit);
  return card;
}

function renderForumSettings(context: PhoneViewContext): HTMLElement {
  const settings = context.forum.settings;
  const form = element('form', { className: 'phone-forum-settings-card' });
  const head = element('div', { className: 'phone-forum-settings-head' });
  head.append(
    element('div', { className: 'phone-forum-settings-copy' }),
    element('span', { className: 'phone-forum-settings-status', text: `${ACTIVITY_LABELS[settings.activityLevel]} · ${settings.autonomousMode ? '自娱自乐开启' : '仅独立主题'}` }),
  );
  const headCopy = head.firstElementChild as HTMLElement;
  headCopy.append(element('strong', { text: '论坛运行参数' }), element('small', { text: '控制下一次刷新，不改动已有帖子。' }));

  const activity = element('select', { className: 'phone-forum-setting-input' });
  for (const [value, label] of Object.entries(ACTIVITY_LABELS)) {
    const option = element('option', { text: label, attributes: { value } });
    option.selected = value === settings.activityLevel;
    activity.append(option);
  }
  const autonomous = element('input', { attributes: { type: 'checkbox' } });
  autonomous.checked = settings.autonomousMode;
  const refreshCount = numberInput(settings.refreshThreadCount, 1, 6);
  const replies = numberInput(settings.repliesPerThread, 0, 6);
  const continuations = numberInput(settings.continuationThreadCount, 0, 8);
  const depth = numberInput(settings.maxReplyDepth, 1, 6);
  const threadLength = numberInput(settings.threadTargetLength, 80, 1_200, 20);
  const replyLength = numberInput(settings.replyTargetLength, 20, 1_200, 20);
  const maxTokens = numberInput(settings.generationMaxTokens, 800, 8_192, 100);
  const contextThreads = numberInput(settings.contextThreadCount, 0, 40);
  const maxTags = numberInput(settings.maxTagsPerThread, 1, 8);

  const controls = element('div', { className: 'phone-forum-settings-grid' });
  controls.append(
    settingRow('活跃程度', '影响讨论密度与语气', activity),
    settingRow('自娱自乐', '允许 NPC 互相回复和续聊旧帖', autonomous),
    settingRow('每次新主题', '刷新时严格生成的主题数', refreshCount),
    settingRow('每主题回复', '0 表示不要求 NPC 回复', replies),
    settingRow('续聊旧主题', '每轮最多选择多少旧讨论', continuations),
    settingRow('楼中楼深度', '限制 NPC 回复嵌套', depth),
    settingRow('主题目标字数', 'AI 生成目标，不是最低字数', threadLength),
    settingRow('回复目标字数', 'AI 生成目标，不是最低字数', replyLength),
    settingRow('输出 Token', '论坛刷新专用预算', maxTokens),
    settingRow('上下文主题', '提供给 AI 的最近主题数', contextThreads),
    settingRow('主题标签数', '用户发帖和 AI 输出上限', maxTags),
  );
  const save = button('保存论坛设置', 'phone-button phone-button-primary phone-forum-settings-save');
  save.addEventListener('click', async () => {
    save.disabled = true;
    try {
      await context.forum.updateSettings({
        autonomousMode: autonomous.checked,
        activityLevel: activity.value as keyof typeof ACTIVITY_LABELS,
        refreshThreadCount: refreshCount.valueAsNumber,
        repliesPerThread: replies.valueAsNumber,
        continuationThreadCount: continuations.valueAsNumber,
        maxReplyDepth: depth.valueAsNumber,
        threadTargetLength: threadLength.valueAsNumber,
        replyTargetLength: replyLength.valueAsNumber,
        generationMaxTokens: maxTokens.valueAsNumber,
        contextThreadCount: contextThreads.valueAsNumber,
        maxTagsPerThread: maxTags.valueAsNumber,
      });
      context.showNotice('论坛设置已保存', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      save.disabled = false;
    }
  });
  form.append(head, controls, save);
  return form;
}

function settingRow(label: string, hint: string, control: HTMLElement): HTMLElement {
  const row = element('label', { className: 'phone-forum-setting-row' });
  const copy = element('span');
  copy.append(element('strong', { text: label }), element('small', { text: hint }));
  row.append(copy, control);
  return row;
}

function numberInput(value: number, minimum: number, maximum: number, step = 1): HTMLInputElement {
  const input = element('input', {
    className: 'phone-forum-setting-input',
    attributes: {
      type: 'number',
      value: String(value),
      min: String(minimum),
      max: String(maximum),
      step: String(step),
    },
  });
  return input;
}

function createRefreshButton(context: PhoneViewContext): HTMLButtonElement {
  const label = context.forum.settings.autonomousMode ? '论坛自转' : '刷新主题';
  const refresh = button(label, 'phone-button phone-button-primary phone-forum-refresh-button');
  refresh.prepend(renderPhoneIcon('refresh'));
  refresh.title = context.forum.settings.autonomousMode
    ? '生成 NPC 主题、互相回复、楼中楼及旧帖续聊'
    : '仅生成一批独立论坛主题';
  refresh.addEventListener('click', () => refreshForum(context, refresh));
  return refresh;
}

/** 板块自转：同一套自转参数，但只写入当前板块，不产出其他板块的内容。 */
function createBoardRefreshButton(context: PhoneViewContext, board: string): HTMLButtonElement {
  const refresh = button('板块自转', 'phone-button phone-button-primary phone-forum-refresh-button');
  refresh.prepend(renderPhoneIcon('refresh'));
  refresh.title = `只在「${board}」板块内生成主题与回复`;
  refresh.addEventListener('click', () => refreshForum(context, refresh, board));
  return refresh;
}

async function refreshForum(
  context: PhoneViewContext,
  trigger: HTMLButtonElement,
  board?: string,
): Promise<void> {
  trigger.disabled = true;
  trigger.classList.add('is-loading');
  try {
    const count = await context.generateAmbientPosts('forum', board ? { board } : undefined);
    context.showNotice(board ? `「${board}」已写入 ${count} 条新内容` : `论坛已写入 ${count} 条新内容`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  } finally {
    trigger.disabled = false;
    trigger.classList.remove('is-loading');
  }
}

async function composeThread(context: PhoneViewContext, index: ForumIndexView): Promise<void> {
  const boards = index.boards.length > 0 ? index.boards.map((board) => board.name) : [FORUM_DEFAULT_BOARD];
  const fields: readonly ModalField[] = [
    { name: 'title', label: '主题标题', required: true, placeholder: '用一句话概括主题' },
    {
      name: 'board',
      label: '发布板块',
      type: 'select',
      value: forumView.board ?? boards[0] ?? FORUM_DEFAULT_BOARD,
      options: boards.map((board) => [board, board] as const),
    },
    { name: 'tags', label: `标签（最多 ${context.forum.settings.maxTagsPerThread} 个）`, placeholder: '#日常 #吐槽' },
    { name: 'content', label: '完整内容', type: 'textarea', required: true, placeholder: '详细说说发生了什么……' },
  ];
  const values = await context.showModal('发布论坛主题', fields);
  const title = values?.title?.trim();
  const content = values?.content?.trim();
  if (!title || !content) return;
  try {
    const tags = values?.tags?.trim()
      ? values.tags.split(/[\s,，、]+/u).filter(Boolean).slice(0, context.forum.settings.maxTagsPerThread)
      : [];
    const thread = await context.commands.createUserPost('forum', 'forum-thread', content, {
      title,
      ...(values?.board ? { board: values.board } : {}),
      ...(tags.length > 0 ? { tags } : {}),
    });
    openForumThread(context, thread);
    context.showNotice(`主题已发布到「${values?.board ?? FORUM_DEFAULT_BOARD}」`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

async function createBoard(context: PhoneViewContext): Promise<void> {
  const values = await context.showModal('创建自定义板块', [
    { name: 'name', label: '板块名称', required: true, placeholder: '例如：旅行见闻' },
    {
      name: 'description',
      label: '板块说明（决定该板块之后生成的内容）',
      type: 'textarea',
      placeholder: '例如：偏日常，只聊通勤、吃饭和邻里琐事；留空则沿用社区默认风格',
    },
  ]);
  if (!values?.name?.trim()) return;
  try {
    const board = await context.commands.createForumBoard(values.name, values.description ?? '', 30);
    forumView.board = board.name;
    context.navigate('forumBoard');
    context.showNotice(`已创建板块「${board.name}」`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

async function editBoard(context: PhoneViewContext, board: ForumBoardView): Promise<void> {
  const values = await context.showModal(`编辑板块 · ${board.name}`, [
    { name: 'name', label: '板块名称', required: true, value: board.name },
    {
      name: 'description',
      label: '板块说明（决定该板块之后生成的内容）',
      type: 'textarea',
      value: board.description,
      placeholder: '例如：偏日常，只聊通勤、吃饭和邻里琐事；留空则沿用社区默认风格',
    },
  ]);
  if (!values?.name?.trim()) return;
  try {
    const updated = await context.commands.updateForumBoardByName(board.name, {
      name: values.name,
      description: values.description ?? '',
    });
    if (forumView.board === board.name) forumView.board = updated.name;
    context.showNotice(`板块已更新为「${updated.name}」`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

async function deleteBoard(context: PhoneViewContext, board: ForumBoardView): Promise<void> {
  const confirmed = await context.showConfirm({
    title: `删除板块「${board.name}」？`,
    message: '板块会从板块区移除，原有主题不会删除，而是回到“综合讨论”。此操作不可撤销。',
    confirmLabel: '删除板块',
    danger: true,
  });
  if (!confirmed) return;
  try {
    await context.commands.deleteForumBoardByName(board.name);
    if (forumView.board === board.name) forumView.board = null;
    context.navigate('forum');
    context.showNotice(`板块「${board.name}」已删除`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

async function editForumIdentity(context: PhoneViewContext): Promise<void> {
  const profile = context.state.profiles['profile:self'];
  if (!profile) {
    context.showNotice('用户资料尚未建立', 'error');
    return;
  }
  const values = await context.showModal('编辑论坛公开身份', [
    { name: 'name', label: '论坛昵称', required: true, value: profile.forumName ?? profile.aliases.forum ?? profile.displayName },
    { name: 'bio', label: '论坛简介', type: 'textarea', value: profile.forumBio ?? '', placeholder: '只在论坛资料卡展示' },
    { name: 'avatarUrl', label: '论坛头像地址', value: profile.forumAvatarUrl ?? '', placeholder: '留空则沿用通用头像' },
  ]);
  if (!values?.name?.trim()) return;
  try {
    await context.commands.updateOwnForumIdentity({
      name: values.name,
      bio: values.bio ?? '',
      avatarUrl: values.avatarUrl ?? '',
    });
    context.showNotice('论坛公开身份已保存，历史帖子会同步显示新身份', 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

function containsSelfFloor(floor: ForumFloor, selfId: string): boolean {
  return floor.profileId === selfId || floor.children.some((child) => containsSelfFloor(child, selfId));
}

function excerpt(value: string, maximum: number): string {
  const normalized = value.replace(/\s+/g, ' ').trim();
  return normalized.length > maximum ? `${normalized.slice(0, maximum)}…` : normalized;
}

export function forumBackRoute(route: PhoneRoute): PhoneRoute | null {
  if (route === 'forumPost') return forumView.returnRoute;
  if (route === 'forumBoard' || route === 'forumHot' || route === 'forumMe') return 'forum';
  return null;
}