/**
 * 可取消的单次运行：把 AbortController 的生命周期收在一处。
 *
 * 管线只需要 begin / end / cancel 三个动作，不必各自维护控制器与中止判定；
 * 界面侧拿到 cancel 就能在「进行中」提示上提供终止入口。
 */

export class CancellableRun {
  #controller: AbortController | null = null;

  get active(): boolean {
    return this.#controller !== null;
  }

  /** 开始一次运行并取得信号；上一次未收尾的运行会被中止。 */
  begin(): AbortSignal {
    this.#controller?.abort();
    this.#controller = new AbortController();
    return this.#controller.signal;
  }

  /** 正常收尾：清掉控制器，之后的 cancel 不再有副作用。 */
  end(): void {
    this.#controller = null;
  }

  /** 用户主动终止；返回是否真的中止了一次进行中的运行。 */
  cancel(): boolean {
    if (!this.#controller) return false;
    this.#controller.abort();
    this.#controller = null;
    return true;
  }
}

/** 判断错误是否来自主动取消（AbortController 或上层的取消约定）。 */
export function isCancelledError(error: unknown): boolean {
  if (error instanceof DOMException && error.name === 'AbortError') return true;
  if (error instanceof Error) {
    return error.name === 'AbortError' || /aborted|取消/u.test(error.message);
  }
  return false;
}