/**
 * 应用显示名称的作用域规则。
 *
 * 个性化里的自定义名称属于「应用级」：只影响桌面图标、通知列表和应用页面顶部标题。
 * 应用内导航项（主页/搜索/通知/私信/我）永远使用导航项自身的名称，
 * 否则给「推特」改名会把所有导航项都变成同一个名字。
 */
export interface AppLabelSource {
  readonly id: string;
  readonly label: string;
  readonly navigation: readonly { readonly label: string }[];
}

export interface AppDisplayLabels {
  /** 桌面图标下方的名称。 */
  readonly desktop: string;
  /** 应用页面顶部标题。 */
  readonly pageTitle: string;
  /** 底部导航项名称（顺序与 navigation 一致）。 */
  readonly navigation: readonly string[];
}

export function resolveAppLabel(
  appLabels: Readonly<Record<string, string>>,
  appId: string,
  fallback: string,
): string {
  const custom = appLabels[appId];
  return custom && custom.trim() ? custom : fallback;
}

export function resolveAppDisplayLabels(
  appLabels: Readonly<Record<string, string>>,
  app: AppLabelSource,
): AppDisplayLabels {
  const custom = resolveAppLabel(appLabels, app.id, app.label);
  return {
    desktop: custom,
    pageTitle: custom,
    navigation: app.navigation.map((item) => item.label),
  };
}