import {
  describeChannel,
  describeGenerationType,
  formatTavernPromptEntryText,
  tavernPromptLog,
  type TavernPromptLogEntry,
  type TavernPromptSegment,
} from '../integration/tavern-prompt-log.js';
import { button, downloadJsonFile, downloadTextFile, element } from './dom.js';
import { renderPhoneIcon } from './phone-icon.js';

export interface TavernPromptLogViewContext {
  readonly enabled: boolean;
  /** 请求重绘当前设置页（列表刷新与列表/详情切换共用）。 */
  readonly refresh: () => void;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

/** 当前展开的请求；设置页重绘不丢失选择，与 API 配置编辑器的草稿同一套做法。 */
let openedEntryId: number | null = null;
/** 列表↔详情切换标记：外壳会还原上一次滚动位置，切换视图时必须回到顶部。 */
let viewSwitched = false;

const ROLE_LABELS: Readonly<Record<string, string>> = Object.freeze({
  system: '系统',
  user: '用户',
  assistant: '模型',
  tool: '工具',
  prompt: '完整提示词',
  unknown: '未标注',
});

function fileStamp(timestamp: number): string {
  return new Date(timestamp).toISOString().slice(0, 19).replace(/[T:]/g, '-');
}

function clockText(timestamp: number): string {
  const time = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${pad(time.getHours())}:${pad(time.getMinutes())}:${pad(time.getSeconds())}`;
}

async function copyToClipboard(text: string): Promise<void> {
  if (!navigator.clipboard?.writeText) throw new Error('当前浏览器不允许直接写入剪贴板，请改用导出。');
  await navigator.clipboard.writeText(text);
}

/** 切换列表/详情后把设置页滚回顶部；结构不符合预期时静默跳过，不影响渲染。 */
function settleViewSwitch(node: HTMLElement): HTMLElement {
  if (!viewSwitched) return node;
  viewSwitched = false;
  requestAnimationFrame(() => {
    node.closest('.phone-page')?.parentElement?.scrollTo({ top: 0 });
  });
  return node;
}

function switchView(entryId: number | null, context: TavernPromptLogViewContext): void {
  openedEntryId = entryId;
  viewSwitched = true;
  context.refresh();
}

/**
 * 酒馆提示词日志视图：未启用时只给出说明，启用后展示请求列表，
 * 点开某条请求则显示该次发送的完整提示词分段结构。
 */
export function renderTavernPromptLogView(context: TavernPromptLogViewContext): HTMLElement {
  if (!context.enabled) {
    openedEntryId = null;
    return element('p', {
      className: 'phone-settings-hint',
      text: '未启用，不记录也不显示任何提示词。开启上面的开关后，之后每一次酒馆正文请求都会留下一条快照。',
    });
  }
  const opened = openedEntryId === null ? null : tavernPromptLog.find(openedEntryId);
  if (openedEntryId !== null && !opened) openedEntryId = null;
  return settleViewSwitch(opened ? renderEntryDetail(opened, context) : renderEntryList(context));
}

function renderEntryList(context: TavernPromptLogViewContext): HTMLElement {
  const wrap = element('div', { className: 'phone-prompt-log' });
  const entries = tavernPromptLog.entries();

  const toolbar = element('div', { className: 'phone-settings-inline-actions phone-logs-toolbar' });
  toolbar.append(
    button('刷新', 'phone-button phone-button-secondary phone-button-compact', () => context.refresh()),
    button('导出全部（JSON）', 'phone-button phone-button-secondary phone-button-compact', () => {
      if (entries.length === 0) {
        context.showNotice('当前没有可导出的请求。', 'info');
        return;
      }
      downloadJsonFile(`酒馆提示词日志-${fileStamp(Date.now())}.json`, entries);
      context.showNotice(`已导出 ${entries.length} 条请求。`, 'success');
    }),
    button('清空', 'phone-button phone-button-danger phone-button-compact', () => {
      tavernPromptLog.clear();
      openedEntryId = null;
      context.refresh();
    }),
  );
  wrap.append(toolbar);

  wrap.append(element('p', {
    className: 'phone-settings-hint',
    text: entries.length > 0
      ? `共 ${entries.length} 条请求（只保留最近若干次，仅存内存，刷新页面即清空）。单击任意一条查看该次发送的完整提示词结构。`
      : '还没有记录到正文请求。在酒馆里正常发送一条消息或点重生成，这里就会出现对应的快照。',
  }));

  if (entries.length === 0) return wrap;

  const list = element('div', { className: 'phone-logs-list phone-prompt-log-list' });
  for (const entry of entries) {
    list.append(renderEntryRow(entry, context));
  }
  wrap.append(list);
  return wrap;
}

function renderEntryRow(entry: TavernPromptLogEntry, context: TavernPromptLogViewContext): HTMLElement {
  const row = button('', 'phone-log-row phone-prompt-log-row', () => switchView(entry.id, context));
  const copy = element('span', { className: 'phone-prompt-log-row-copy' });
  const head = element('span', { className: 'phone-prompt-log-row-head' });
  head.append(
    element('span', { className: 'phone-log-time', text: clockText(entry.timestamp) }),
    element('span', { className: 'phone-prompt-log-tag', text: describeGenerationType(entry.generationType) }),
    element('span', {
      className: 'phone-prompt-log-tag is-channel',
      text: entry.channel === 'chat' ? 'messages' : '单段',
    }),
  );
  copy.append(head, element('small', {
    className: 'phone-prompt-log-row-meta',
    text: `${entry.segments.length} 段 · ${entry.totalChars.toLocaleString()} 字符${entry.truncated ? ' · 已截断' : ''}`,
  }));
  row.append(copy, renderPhoneIcon('chevron'));
  return row;
}

function renderEntryDetail(entry: TavernPromptLogEntry, context: TavernPromptLogViewContext): HTMLElement {
  const wrap = element('div', { className: 'phone-prompt-log' });

  const toolbar = element('div', { className: 'phone-settings-inline-actions phone-logs-toolbar' });
  toolbar.append(
    button('← 返回请求列表', 'phone-button phone-button-secondary phone-button-compact', () => switchView(null, context)),
    button('复制全文', 'phone-button phone-button-secondary phone-button-compact', async () => {
      await copyToClipboard(formatTavernPromptEntryText(entry));
      context.showNotice('已复制该次请求的完整提示词。', 'success');
    }),
    button('导出文本', 'phone-button phone-button-secondary phone-button-compact', () => {
      downloadTextFile(`酒馆提示词-${fileStamp(entry.timestamp)}.txt`, formatTavernPromptEntryText(entry));
      context.showNotice('已导出为文本文件。', 'success');
    }),
    button('导出 JSON', 'phone-button phone-button-secondary phone-button-compact', () => {
      downloadJsonFile(`酒馆提示词-${fileStamp(entry.timestamp)}.json`, entry);
      context.showNotice('已导出为 JSON 文件。', 'success');
    }),
  );
  wrap.append(toolbar, renderEntryMeta(entry));

  const body = element('div', { className: 'phone-prompt-segments' });
  for (const segment of entry.segments) {
    body.append(renderSegment(segment));
  }
  wrap.append(body);
  return wrap;
}

function renderEntryMeta(entry: TavernPromptLogEntry): HTMLElement {
  const card = element('div', { className: 'phone-settings-card phone-prompt-log-meta' });
  const line = (label: string, value: string) => {
    const row = element('div', { className: 'phone-detail-line' });
    row.append(element('span', { text: label }), element('strong', { text: value }));
    return row;
  };
  card.append(
    line('发送时间', new Date(entry.timestamp).toLocaleString()),
    line('请求类型', describeGenerationType(entry.generationType)),
    line('提示词通道', describeChannel(entry.channel)),
    line('分段数量', `${entry.segments.length} 段`),
    line('总字符数', entry.totalChars.toLocaleString()),
  );
  if (entry.chatId) card.append(line('所属聊天', entry.chatId));
  if (entry.truncated) {
    card.append(element('p', {
      className: 'phone-settings-hint',
      text: '这条请求超出了单条留存预算，界面里的正文已被截断；上面的字符数仍是截断前的真实长度。',
    }));
  }
  return card;
}

function renderSegment(segment: TavernPromptSegment): HTMLElement {
  // 角色名来自宿主，做一次白名单收敛后才拼进 class，避免异常值污染选择器。
  const roleClass = segment.role.toLowerCase().replace(/[^a-z0-9-]/g, '') || 'unknown';
  const box = element('div', { className: `phone-prompt-segment phone-prompt-role-${roleClass}` });
  const head = element('div', { className: 'phone-prompt-segment-head' });
  head.append(
    element('span', { className: 'phone-prompt-segment-index', text: `#${segment.index}` }),
    element('span', { className: 'phone-prompt-segment-role', text: ROLE_LABELS[segment.role] ?? segment.role }),
    element('code', { className: 'phone-prompt-segment-raw', text: segment.role }),
  );
  if (segment.name) {
    head.append(element('span', { className: 'phone-prompt-segment-name', text: segment.name }));
  }
  head.append(element('small', {
    className: 'phone-prompt-segment-size',
    text: `${segment.chars.toLocaleString()} 字符${segment.truncated ? ' · 已截断' : ''}`,
  }));
  box.append(head, element('pre', {
    className: 'phone-prompt-segment-body',
    text: segment.content || '（空内容）',
  }));
  return box;
}
