/**
 * MVU 新版更新协议：`<UpdateVariable>` 里的 `<JSONPatch>` 增量与 `<initvar>` 全量。
 *
 * 老卡输出 `_.set('路径', 旧, 新)`，MVU Zod 之后的卡改成了 RFC 6902 风格的 JSON Patch：
 *
 * ```text
 * <UpdateVariable>
 * <Analysis>…</Analysis>
 * <JSONPatch>
 * [ { "op": "replace", "path": "/世界/当前地点", "value": "卧室" },
 *   { "op": "delta",   "path": "/女性角色/络络/好感度", "value": 3 },
 *   { "op": "insert",  "path": "/后宫/保护名单/-", "value": "络络" },
 *   { "op": "remove",  "path": "/女性角色/旧人" } ]
 * </JSONPatch>
 * </UpdateVariable>
 * ```
 *
 * 这一层只把它们翻译成统一的 `MvuCommand`，路径与语义的落地由映射层负责。
 * 解析刻意宽容：模型输出常带尾逗号、注释或半截数组，一条坏 patch 不该让整批更新失效，
 * 因此整体解析失败时退回「逐个顶层 `{...}` 块解析」。
 */

import { parseInitVarTree, mvuNodeValue, relaxJson } from './init-var.js';
import { flattenLeafPaths, joinMvuPath, splitMvuPath } from './mapping.js';
import type { MvuCommand, MvuCommandKind } from './commands.js';

const PATCH_BLOCK_PATTERN = /<\s*JSONPatch\s*>([\s\S]*?)<\s*\/\s*JSONPatch\s*>/gi;
const UPDATE_BLOCK_PATTERN = /<\s*UpdateVariable\s*>([\s\S]*?)<\s*\/\s*UpdateVariable\s*>/gi;
const INIT_VAR_BLOCK_PATTERN = /<\s*initvar\s*>([\s\S]*?)<\s*\/\s*initvar\s*>/gi;
const ANALYSIS_BLOCK_PATTERN = /<\s*Analysis\s*>[\s\S]*?<\s*\/\s*Analysis\s*>/gi;

function matchAll(text: string, pattern: RegExp): readonly string[] {
  const found: string[] = [];
  pattern.lastIndex = 0;
  let match = pattern.exec(text);
  while (match) {
    const body = (match[1] ?? '').trim();
    if (body) found.push(body);
    match = pattern.exec(text);
  }
  return found;
}

/** 从 `[` 开始截出配对的 `]`，引号内的括号不计。 */
function sliceArray(text: string, start: number): string {
  let depth = 0;
  let quote: '"' | '\'' | null = null;
  for (let index = start; index < text.length; index += 1) {
    const char = text[index] ?? '';
    if (quote) {
      if (char === '\\') index += 1;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'') {
      quote = char;
      continue;
    }
    if (char === '[' || char === '{') depth += 1;
    else if (char === ']' || char === '}') {
      depth -= 1;
      if (depth === 0) return text.slice(start, index + 1);
    }
  }
  return text.slice(start);
}

/** 取出所有可能装着 patch 数组的载荷：优先 `<JSONPatch>`，否则退到 `<UpdateVariable>` 里的裸数组。 */
export function extractPatchPayloads(text: string): readonly string[] {
  const blocks = matchAll(text, PATCH_BLOCK_PATTERN);
  if (blocks.length > 0) return blocks;
  return matchAll(text, UPDATE_BLOCK_PATTERN).flatMap((block): readonly string[] => {
    const body = block.replace(ANALYSIS_BLOCK_PATTERN, '');
    const start = body.indexOf('[');
    return start < 0 ? [] : [sliceArray(body, start)];
  });
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

/** 逐个顶层 `{...}` 块解析：整体 JSON 坏掉时至少救回能读的那几条。 */
function parseLoosely(payload: string): readonly Record<string, unknown>[] {
  const records: Record<string, unknown>[] = [];
  for (let index = 0; index < payload.length; index += 1) {
    if (payload[index] !== '{') continue;
    const block = sliceArray(payload, index);
    index += block.length - 1;
    try {
      const record = asRecord(JSON.parse(relaxJson(block)) as unknown);
      if (record) records.push(record);
    } catch {
      // 这一条读不出来就跳过，不影响其他 patch。
    }
  }
  return records;
}

/** patch 载荷 → 操作对象数组。 */
export function parsePatchOperations(payload: string): readonly Record<string, unknown>[] {
  for (const candidate of [payload, relaxJson(payload)]) {
    try {
      const parsed = JSON.parse(candidate) as unknown;
      if (Array.isArray(parsed)) return parsed.flatMap((item) => (asRecord(item) ? [asRecord(item)!] : []));
      const single = asRecord(parsed);
      if (single) return [single];
    } catch {
      // 继续试下一种写法。
    }
  }
  return parseLoosely(payload);
}

/** JSON Pointer → MVU 的点分路径；`~1`/`~0` 按 RFC 6901 反转义。 */
export function pointerToPath(pointer: string): string {
  return joinMvuPath(pointer
    .replace(/^#/, '')
    .split('/')
    .map((segment) => segment.replaceAll('~1', '/').replaceAll('~0', '~').trim())
    .filter(Boolean)
    );
}

const LIST_TAIL_PATTERN = /^(?:-|\d+)$/;

interface Translated {
  readonly kind: MvuCommandKind;
  readonly path: string;
}

/**
 * op → MVU 命令语义。
 * `path` 末段是 `-` 或数字时指的是列表元素，这时 `insert`/`add` 表示往列表里追加，
 * 命令路径退回列表本身——表格里列表存成一格文本，追加就是往这一格里加一项。
 */
function translateOp(op: string, pointer: string): Translated | null {
  const segments = splitMvuPath(pointerToPath(pointer));
  const tail = segments.at(-1) ?? '';
  const listTail = LIST_TAIL_PATTERN.test(tail);
  const listPath = joinMvuPath(segments.slice(0, -1));
  const path = joinMvuPath(segments);
  const normalized = op.trim().toLowerCase();
  if (!path && !listPath) return null;
  if (normalized === 'delta' || normalized === 'increment' || normalized === 'inc') {
    return { kind: 'add', path };
  }
  if (normalized === 'insert' || normalized === 'push' || normalized === 'append') {
    return listTail ? { kind: 'insert', path: listPath } : { kind: 'set', path };
  }
  if (normalized === 'add') {
    return listTail ? { kind: 'insert', path: listPath } : { kind: 'set', path };
  }
  if (normalized === 'remove' || normalized === 'delete') {
    return listTail ? { kind: 'delete', path: listPath } : { kind: 'delete', path };
  }
  if (normalized === 'move' || normalized === 'copy') return { kind: 'move', path };
  if (normalized === 'replace' || normalized === 'set' || normalized === 'assign') return { kind: 'set', path };
  return null;
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

/** `<JSONPatch>` → MVU 命令。认不出 op 或路径为空的条目会被跳过。 */
export function parseJsonPatchCommands(source: string): readonly MvuCommand[] {
  return extractPatchPayloads(source).flatMap((payload) => parsePatchOperations(payload).flatMap((operation): readonly MvuCommand[] => {
    const pointer = text(operation.path) || text(operation.p);
    const translated = translateOp(text(operation.op) || text(operation.operation), pointer);
    if (!translated || !translated.path) return [];
    const hasValue = 'value' in operation;
    return [{
      kind: translated.kind,
      path: translated.path,
      args: hasValue ? [operation.value] : [],
      ...(translated.path !== pointerToPath(pointer) && /\d+$/.test(pointer.split('/').at(-1) ?? '')
        ? { index: Number(pointer.split('/').at(-1)) } : {}),
      reason: text(operation.reason) || text(operation.note) || text(operation.comment),
      raw: JSON.stringify(operation),
    }];
  }));
}

/**
 * `<initvar>` 全量块 → 逐路径 set 命令。
 * 开局消息用它覆写初值（不同开局分歧就靠这个），不认的话第 0 楼的差异会整段丢掉。
 */
export function parseInitVarBlockCommands(source: string): readonly MvuCommand[] {
  return matchAll(source, INIT_VAR_BLOCK_PATTERN).flatMap((block): readonly MvuCommand[] => {
    let value: unknown;
    try { value = mvuNodeValue(parseInitVarTree(block).tree); } catch { return []; }
    return [...flattenLeafPaths(value)].map(([path, value]) => ({
      kind: 'set' as const,
      path,
      args: [value],
      reason: '开局 initvar 覆写',
      raw: `${path}=${JSON.stringify(value ?? null)}`,
    }));
  });
}

/** 这段文本里有没有新版协议的载荷。 */
export function hasNewProtocolPayload(source: string): boolean {
  return extractPatchPayloads(source).length > 0 || INIT_VAR_BLOCK_PATTERN.test(source);
}
