/**
 * InitVar 条目 → 变量树。
 *
 * 真实卡里的 InitVar 有三种写法，用户本机的卡都出现过：
 * - JSON：叶子是 `[值, 描述]` 二元组，正文常被 ```json 围栏或 `<initvar>` 标签包着，还带行尾注释与尾逗号；
 * - YAML：缩进映射，叶子多为裸标量（MVU Zod 卡的写法）；
 * - 两者混排：外层 YAML、个别值写成行内流式集合。
 * 因此先按「去壳后第一个非空字符是不是 `{`」分流，再各走各的解析；两条路都失败就明确报错，不猜内容。
 *
 * 叶子怎么读取决于**整份文档**的方言（见 `detectLeafDialect`）：把 Zod 卡的两项名单
 * 读成「值 + 描述」会直接丢一半数据，所以方言判定必须在解析入口做一次，再往下传。
 */

import { detectLeafDialect, readMvuLeaf, type MvuLeafDialect, type MvuLeafValue } from './mvu-tuple.js';
import { parseYamlLite } from './yaml-lite.js';
import type { MvuGroupNode, MvuLeafNode, MvuNode, MvuTree, MvuTreeEntry, MvuValueType } from './types.js';

export interface MvuTreeParseResult {
  readonly tree: MvuTree;
  readonly issues: readonly string[];
  readonly format: 'json' | 'yaml';
  readonly dialect: MvuLeafDialect;
}

const EMPTY_GROUP: MvuGroupNode = Object.freeze({ kind: 'group', entries: [] });

/** 去掉围栏与标签包裹，留下裸正文。 */
export function stripInitVarWrappers(raw: string): string {
  return raw
    .replace(/```[a-zA-Z]*\s*/g, '')
    .replace(/```/g, '')
    .replace(/<\/?(?:initvar|InitVar|init_var|variables?|mvu)[^>]*>/gi, '')
    .trim();
}

/**
 * 截出最外层的 `{...}`。要求去壳后的第一个字符就是 `{`：
 * YAML 正文里 `'{{user}}'` 这类占位符也含花括号，按「找第一个 `{`」会截出一段废话。
 */
export function extractInitVarJson(raw: string): string {
  const body = stripInitVarWrappers(raw);
  if (!body.startsWith('{')) return '';
  const end = body.lastIndexOf('}');
  return end > 0 ? body.slice(0, end + 1) : '';
}

/** 按字符扫描去注释与尾逗号：字符串字面量里的 `//` 与 `,` 必须原样保留。 */
export function relaxJson(source: string): string {
  let output = '';
  let quote: '"' | '\'' | null = null;
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index] ?? '';
    if (quote) {
      output += char;
      if (char === '\\') {
        output += source[index + 1] ?? '';
        index += 1;
        continue;
      }
      if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'') {
      quote = char;
      output += char;
      continue;
    }
    if (char === '/' && source[index + 1] === '/') {
      while (index < source.length && source[index] !== '\n') index += 1;
      output += '\n';
      continue;
    }
    if (char === '/' && source[index + 1] === '*') {
      const close = source.indexOf('*/', index + 2);
      index = close < 0 ? source.length : close + 1;
      continue;
    }
    output += char;
  }
  return output.replace(/,(\s*[}\]])/g, '$1');
}

/** EJS/lodash 模板定界符：出现在键或值里都说明这是展示层构件。 */
const TEMPLATE_MARK_PATTERN = /<%|%>/;
/** 卡作者留的元数据键，不是变量字段。 */
const META_LEAF_KEYS: ReadonlySet<string> = new Set(['schema', '$schema', '$meta']);

/**
 * 这个叶子是否真的承载数据。
 *
 * MVU 卡在实践里有两类写法：一类是干净的「分组 + 标量」，另一类把状态栏的渲染
 * 构件也塞进 `stat_data`——EJS 模板片段与真数据混在一起。模板不是字段：拿去建表
 * 只会得到空列，注入提示词时还会被宿主引擎当代码执行并抛 `not defined`。
 *
 * 判据刻意只留两条最确定的（键或值含模板定界符、键是元数据），不猜「像占位的值」：
 * 诸如 `value`、`none` 这类字符串在别的卡里可能就是真实数据，宁可放过也不误删。
 */
function leafCarriesData(key: string, value: unknown): boolean {
  const name = key.trim();
  if (!name || TEMPLATE_MARK_PATTERN.test(name)) return false;
  if (META_LEAF_KEYS.has(name.toLowerCase())) return false;
  const text = Array.isArray(value)
    ? value.map((item) => (item === null ? '' : String(item))).join(' ')
    : (value === null || value === undefined ? '' : String(value));
  return !TEMPLATE_MARK_PATTERN.test(text);
}

/** 叶子值 → 单元格还原类型。列表与结构值分开，投影回 `stat_data` 时才不会变形。 */
export function valueTypeOfLeafValue(value: MvuLeafValue): MvuValueType {
  if (Array.isArray(value)) return 'list';
  if (typeof value === 'number') return 'number';
  if (typeof value === 'boolean') return 'boolean';
  return 'string';
}

/** MVU 命名修饰符：`_` 只读、`$` 对 AI 隐藏；分组上的修饰符向下继承。 */
export interface MvuKeyFlags {
  readonly readOnly: boolean;
  readonly hidden: boolean;
}

export const OPEN_KEY_FLAGS: MvuKeyFlags = Object.freeze({ readOnly: false, hidden: false });

export function keyFlagsOf(key: string, inherited: MvuKeyFlags = OPEN_KEY_FLAGS): MvuKeyFlags {
  const name = key.trim();
  return {
    readOnly: inherited.readOnly || name.startsWith('_'),
    hidden: inherited.hidden || name.startsWith('$'),
  };
}

export function makeLeaf(
  value: MvuLeafValue,
  desc: string,
  flags: MvuKeyFlags = OPEN_KEY_FLAGS,
  valueType: MvuValueType = valueTypeOfLeafValue(value),
): MvuLeafNode {
  return { kind: 'leaf', value, desc, valueType, readOnly: flags.readOnly, hidden: flags.hidden };
}

interface ParseContext {
  readonly dialect: MvuLeafDialect;
  readonly issues: string[];
}

/**
 * 结构值（对象数组、混合数组）转成 `json` 叶子。
 * 这类值在真实卡里是历史记录、分区清单这种整体读写的数据：拆成子表没人看得懂，
 * 丢掉又会让变量在投影回 `stat_data` 后缺字段，所以整值存 JSON 文本，投影时原样解析回来。
 */
function toJsonLeaf(value: unknown, flags: MvuKeyFlags): MvuLeafNode {
  return makeLeaf(JSON.stringify(value), '', flags, 'json');
}

function toNode(value: unknown, path: string, flags: MvuKeyFlags, context: ParseContext): MvuNode | null {
  const leaf = readMvuLeaf(value, context.dialect);
  if (leaf) {
    const key = path.split('.').at(-1) ?? '';
    if (!leafCarriesData(key, leaf.value)) {
      context.issues.push(`${path}：值是展示模板或类型占位，已跳过，不作为数据列。`);
      return null;
    }
    return makeLeaf(leaf.value, leaf.desc, flags);
  }
  if (Array.isArray(value)) return toJsonLeaf(value, flags);
  if (!value || typeof value !== 'object') {
    context.issues.push(`${path}：无法识别的值类型，已跳过。`);
    return null;
  }
  const entries = Object.entries(value as Record<string, unknown>).flatMap(([key, child]): readonly MvuTreeEntry[] => {
    const childPath = path ? `${path}.${key}` : key;
    const node = toNode(child, childPath, keyFlagsOf(key, flags), context);
    return node ? [{ key, node }] : [];
  });
  return { kind: 'group', entries };
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

/** `{"stat_data": {...}}` 这种整包导出：真正的变量在 `stat_data` 下面。 */
function unwrapStatData(value: unknown): unknown {
  const record = asRecord(value);
  const inner = record ? asRecord(record.stat_data) : null;
  return inner && Object.keys(record ?? {}).length <= 4 ? inner : value;
}

/**
 * 解析 InitVar 正文为原始对象。JSON 优先，其次 YAML 子集；两条路都不成时返回 null。
 * 只做结构解析，不判断是不是 MVU 变量——那是 `looksLikeMvuVariableTree` 与 `card-source` 的职责。
 */
export function parseInitVarPayload(raw: string): { readonly value: unknown; readonly format: 'json' | 'yaml' } | null {
  const json = extractInitVarJson(raw);
  if (json) {
    try {
      return { value: unwrapStatData(JSON.parse(relaxJson(json)) as unknown), format: 'json' };
    } catch {
      // JSON 路失败时继续试 YAML：YAML 是 JSON 的超集，仍有可能读出来。
    }
  }
  const body = stripInitVarWrappers(raw);
  if (!body) return null;
  const parsed = parseYamlLite(body);
  return parsed && typeof parsed === 'object' && !Array.isArray(parsed)
    ? { value: unwrapStatData(parsed), format: 'yaml' }
    : null;
}

/** 解析 InitVar 正文。无法解析时抛错——静默返回空树会让用户以为卡里没有变量。 */
export function parseInitVarTree(raw: string): MvuTreeParseResult {
  const payload = parseInitVarPayload(raw);
  if (!payload) throw new Error('InitVar 条目既不是可解析的 JSON，也不是可识别的 YAML 映射。');
  const dialect = detectLeafDialect(payload.value);
  const context: ParseContext = { dialect, issues: [] };
  const node = toNode(payload.value, '', OPEN_KEY_FLAGS, context);
  if (!node || node.kind !== 'group') throw new Error('InitVar 条目的顶层必须是对象。');
  // 空树等于「没读出变量」：静默返回会让后续流程建出零张表，用户只会看到功能失灵。
  if (node.entries.length === 0) throw new Error('InitVar 条目里没有读到任何变量。');
  return { tree: node, issues: context.issues, format: payload.format, dialect };
}

/** 键名看起来像变量字段，而不是散文标题或列表项。 */
export function keyLooksLikeField(key: string): boolean {
  const name = key.trim();
  if (!name || name.length > 32) return false;
  if (/\s/.test(name)) return false;
  if (/^[-*•>#+=\d]/.test(name)) return false;
  if (/[。，、！？；：""''（）()【】\[\]{}…"'`|\\/]/.test(name)) return false;
  if (/https?:|--/.test(name)) return false;
  return true;
}

function countTreeLeaves(node: MvuNode): number {
  return node.kind === 'leaf' ? 1 : node.entries.reduce((total, entry) => total + countTreeLeaves(entry.node), 0);
}

/** 顶层里像「字段」的键占比够高才可能是变量树；散文条目的键会大面积落榜。 */
function fieldishRatio(keys: readonly string[]): number {
  if (keys.length === 0) return 0;
  return keys.filter((key) => keyLooksLikeField(key)).length / keys.length;
}

const FIELDISH_FLOOR = 0.8;
const MIN_GROUPS = 2;
const MIN_LEAVES = 4;

/**
 * 这份正文是不是 MVU 变量树。
 *
 * 只靠「能解析成对象」远远不够：`parseYamlLite` 对任何带冒号的散文都能读出映射，
 * 于是人设、生图规范、表情包链接表全会被当成变量条目，再按「叶子最多」挑主表时
 * 真正的变量条目就被挤掉了。这里的判据是结构性的：顶层键要像字段名，
 * 且要么自带 `_schemaVersion` 这类 MVU 标志，要么有多个分组与足够的叶子。
 */
export function looksLikeMvuVariableTree(value: unknown): boolean {
  const record = asRecord(unwrapStatData(value));
  if (!record) return false;
  const keys = Object.keys(record);
  if (keys.length === 0 || fieldishRatio(keys) < FIELDISH_FLOOR) return false;
  if (keys.some((key) => /^[_$]?schemaVersion$/i.test(key.trim()))) return true;
  const dialect = detectLeafDialect(record);
  const groups = keys.filter((key) => asRecord(record[key]) !== null).length;
  if (groups < MIN_GROUPS) return false;
  const context: ParseContext = { dialect, issues: [] };
  const node = toNode(record, '', OPEN_KEY_FLAGS, context);
  return node !== null && node.kind === 'group' && countTreeLeaves(node) >= MIN_LEAVES;
}

/** 读取树上某条路径的节点；路径不存在时返回 null。 */
export function findMvuNode(tree: MvuTree, path: readonly string[]): MvuNode | null {
  let current: MvuNode = tree;
  for (const key of path) {
    if (current.kind !== 'group') return null;
    const next: MvuTreeEntry | undefined = current.entries.find((entry) => entry.key === key);
    if (!next) return null;
    current = next.node;
  }
  return current;
}

/** 变量树里的全部叶子路径，按声明顺序。 */
export function listMvuLeafPaths(tree: MvuTree): readonly string[] {
  const paths: string[] = [];
  const part = (key: string): string => /[.\[\]"']/.test(key) ? `[${JSON.stringify(key)}]` : key;
  const walk = (node: MvuNode, prefix: string): void => {
    if (node.kind === 'leaf') {
      paths.push(prefix);
      return;
    }
    for (const entry of node.entries) {
      const key = part(entry.key);
      walk(entry.node, prefix ? `${prefix}${key.startsWith('[') ? '' : '.'}${key}` : key);
    }
    if (node.record && node.template) walk(node.template, `${prefix}.*`);
    else if (prefix && node.entries.length === 0) paths.push(prefix);
  };
  walk(tree, '');
  return paths;
}

/**
 * 合并两棵变量树：`base` 提供结构（Zod schema 的字段、类型、只读性），`overlay` 提供数据（InitVar 的实例与初值）。
 *
 * MVU Zod 卡的字段定义在角色脚本里，世界书 InitVar 常被作者关掉只当种子，
 * 两边都只有一半信息；只取一边都会漏字段或漏角色，因此按键归并：
 * 同名叶子取 overlay 的值、base 的类型与只读性；overlay 独有的键（record 的动态成员）整枝收下。
 */
export function mergeMvuTrees(base: MvuTree, overlay: MvuTree): MvuTree {
  return mergeGroups(base, overlay);
}

function mergeGroups(base: MvuGroupNode, overlay: MvuGroupNode): MvuGroupNode {
  const overlayByKey = new Map(overlay.entries.map((entry) => [entry.key, entry.node]));
  const merged: MvuTreeEntry[] = base.entries.map((entry) => {
    const other = overlayByKey.get(entry.key);
    overlayByKey.delete(entry.key);
    return other ? { key: entry.key, node: mergeNodes(entry.node, other) } : entry;
  });
  for (const [key, node] of overlayByKey) merged.push({ key, node });
  const template = base.template ?? overlay.template;
  return {
    ...base,
    kind: 'group',
    entries: merged,
    ...(overlay.entries.length ? { present: true } : {}),
    ...(base.record || overlay.record ? { record: true } : {}),
    ...(template ? { template } : {}),
  };
}

function mergeNodes(base: MvuNode, overlay: MvuNode): MvuNode {
  if (base.kind === 'group' && overlay.kind === 'group') return mergeGroups(base, overlay);
  if (base.kind === 'leaf' && overlay.kind === 'leaf') {
    let value = overlay.value;
    if (value === null && !base.nullable) value = base.value;
    if (base.valueType === 'number' && value !== null) {
      const numeric = value === '' ? NaN : Number(value);
      value = Number.isFinite(numeric) ? numeric : base.value;
      if (typeof value === 'number') {
        value = Math.min(base.constraints?.maximum ?? Infinity, Math.max(base.constraints?.minimum ?? -Infinity, value));
        if (base.constraints?.integer) value = Math.round(value);
      }
    }
    if (base.valueType === 'boolean' && typeof value === 'string') value = !['false', '0', '否', '关闭', ''].includes(value.trim().toLowerCase());
    if (base.valueType === 'string' && value !== null) value = String(value);
    if (base.valueType === 'json') {
      if (overlay.valueType !== 'json') value = JSON.stringify(value);
    }
    if (base.constraints?.enumValues?.length && !base.constraints.enumValues.includes(value as never)) value = base.value;
    return {
      ...base,
      value,
      desc: base.desc || overlay.desc,
      valueType: base.valueType,
      readOnly: base.readOnly || overlay.readOnly,
      hidden: base.hidden || overlay.hidden,
    };
  }
  if (base.kind === 'leaf' && base.valueType === 'json') return { ...base, value: JSON.stringify(mvuNodeValue(overlay)) };
  if (base.kind === 'group' && overlay.kind === 'leaf') {
    if (typeof overlay.value === 'string' && overlay.value.trim().startsWith('{')) {
      try {
        const parsed = toNode(JSON.parse(overlay.value), '', OPEN_KEY_FLAGS, { dialect: 'plain', issues: [] });
        if (parsed?.kind === 'group') return mergeGroups(base, parsed);
      } catch { /* 不把文本猜成对象；继续保留 schema 默认结构。 */ }
    }
    return base;
  }
  return base;
}

/** 树中的真实初值；记录模板只提供结构，不凭模板制造成员。 */
export function mvuNodeValue(node: MvuNode): unknown {
  if (node.kind === 'group') return Object.fromEntries(node.entries.map((entry) => [entry.key, mvuNodeValue(entry.node)]));
  if (node.valueType === 'json' && typeof node.value === 'string') {
    try { return JSON.parse(node.value); } catch { return node.value; }
  }
  return node.value;
}

/**
 * `record` 分组按模板补齐成员字段。
 * Zod 的 `z.record(...)` 只声明了成员长什么样，成员本身来自 InitVar；
 * 补齐之后同一张实体表里每个成员的列都对得上，不会出现「有的角色少两列」。
 */
export function expandRecordMembers(tree: MvuTree): MvuTree {
  const expand = (node: MvuNode): MvuNode => {
    if (node.kind === 'leaf') return node;
    const entries = node.entries.map((entry) => ({ key: entry.key, node: expand(entry.node) }));
    const template = node.template;
    if (!node.record || !template) return { ...node, entries };
    return {
      ...node,
      entries: entries.map((member) => ({
        key: member.key,
        node: expand(mergeNodes(template, member.node)),
      })),
    };
  };
  const expanded = expand(tree);
  return expanded.kind === 'group' ? expanded : tree;
}

export { EMPTY_GROUP as EMPTY_MVU_GROUP };
