export type IdFactory = () => string;

let fallbackCounter = 0;

export const createId: IdFactory = () => {
  if (typeof globalThis.crypto?.randomUUID === 'function') {
    return globalThis.crypto.randomUUID();
  }
  fallbackCounter += 1;
  return `phone-${Date.now().toString(36)}-${fallbackCounter.toString(36)}`;
};

export function createScopedId(scopeId: string, prefix: string, idFactory: IdFactory = createId): string {
  const safeScope = scopeId.replace(/[^a-zA-Z0-9_-]/g, '_').slice(0, 48) || 'default';
  return `${prefix}:${safeScope}:${idFactory()}`;
}