/**
 * 一次遍历得出每个会话的最后一条消息。
 * 会话列表原来对每个会话都要倒扫一遍整张消息表（还带两次数组拷贝），消息攒多以后开列表明显发卡。
 */
export function latestMessagesByConversation(
  state: Pick<PhoneState, 'messageOrder' | 'messages'>,
): ReadonlyMap<string, PhoneMessage> {
  const latest = new Map<string, PhoneMessage>();
  for (const id of state.messageOrder) {
    const message = state.messages[id];
    if (message) latest.set(message.conversationId, message);
  }
  return latest;
}

/**
 * 会话内最近 limit 条消息（按时间正序）。
 * 从尾部倒扫并在取够后立即停下，不再为了取最后 120 条而遍历整张消息表。
 */
export function selectRecentMessages(
  state: Pick<PhoneState, 'messageOrder' | 'messages'>,
  conversationId: string,
  limit: number,
): readonly PhoneMessage[] {
  const picked: PhoneMessage[] = [];
  for (let index = state.messageOrder.length - 1; index >= 0 && picked.length < limit; index -= 1) {
    const id = state.messageOrder[index];
    const message = id ? state.messages[id] : undefined;
    if (message?.conversationId === conversationId) picked.push(message);
  }
  return picked.reverse();
}

/** 删除/回撤这类不可逆操作共用的宿主能力；未接入确认弹窗时退化为直接执行。 */
interface DestructiveActionContext {
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
  readonly showConfirm?: (request: ConfirmRequest) => Promise<boolean>;
}

/**
 * 破坏性操作按钮：点击后先弹确认弹窗，确认才执行；取消则恢复可点击。
 * 删除消息、回撤生成内容、删帖都走这一条路径，确保交互一致。
 */
function destructiveButton(
  context: DestructiveActionContext,
  options: {
    readonly className: string;
    readonly label: string;
    readonly icon: 'trash' | 'refresh';
    readonly iconClassName: string;
    readonly confirm: ConfirmRequest;
    readonly run: () => Promise<void>;
  },
): HTMLButtonElement {
  const trigger = button('', options.className, async () => {
    trigger.disabled = true;
    try {
      const approved = context.showConfirm ? await context.showConfirm(options.confirm) : true;
      if (!approved) {
        trigger.disabled = false;
        return;
      }
      await options.run();
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      trigger.disabled = false;
    }
  });
  trigger.title = options.label;
  trigger.setAttribute('aria-label', options.label);
  trigger.append(renderPhoneIcon(options.icon, options.iconClassName));
  return trigger;
}

/** 确认弹窗里回显被操作的内容，隐藏生图标记并截断过长正文。 */
function confirmDetail(text: string, limit = 120): string {
  const compact = replaceImageMarkers(text).replace(/\s+/g, ' ').trim();
  if (!compact) return '';
  return compact.length > limit ? `${compact.slice(0, limit)}…` : compact;
}

/**
 * 等待回复阶段的用户消息删除按钮：仅对自己发送且尚未生成回复（queued）
 * 的消息返回按钮，其余情况返回 null。确认后从聊天记录中删除该消息。
 */
export function renderQueuedMessageDelete(
  context: DestructiveActionContext & {
    readonly commands: { deleteQueuedMessage(messageId: string): Promise<void> };
  },
  message: PhoneMessage,
): HTMLElement | null {
  if (message.direction !== 'outgoing' || message.status !== 'queued') return null;
  const detail = confirmDetail(describeMessagePreview(message, ''));
  return destructiveButton(context, {
    className: 'phone-msg-delete',
    label: '删除这条未回复的消息',
    icon: 'trash',
    iconClassName: 'phone-svg-icon phone-msg-delete-icon',
    confirm: {
      title: '删除这条消息？',
      message: '这条消息还在等待生成回复，删除后不会再提交给模型，且无法恢复。',
      ...(detail ? { detail } : {}),
      confirmLabel: '删除',
    },
    run: async () => {
      await context.commands.deleteQueuedMessage(message.id);
      context.showNotice('已删除该条消息', 'info');
    },
  });
}

/**
 * 已生成内容的回滚按钮：
 * - 用户消息：删掉它之后的全部内容，让它回到「待生成」，可以重新 roll；
 * - 角色消息：连自己一起删除；若上方的用户消息因此没有回复，也会回到「待生成」。
 */
export function renderMessageRollback(
  context: DestructiveActionContext & {
    readonly state: PhoneState;
    readonly commands: { rollbackMessage(messageId: string): Promise<MessageRollbackPlan> };
  },
  message: PhoneMessage,
): HTMLButtonElement | null {
  if (message.direction === 'system') return null;
  const plan = planMessageRollback(context.state, message.id);
  if (!plan || (plan.removedMessageIds.length === 0 && !plan.requeueMessageId)) return null;
  const fromUser = message.direction === 'outgoing';
  const label = fromUser ? '删除这条之后的回复，重新等待生成' : '删除这条及其之后的内容';
  const detail = confirmDetail(describeMessagePreview(message, ''));
  return destructiveButton(context, {
    className: 'phone-msg-delete phone-msg-rollback',
    label,
    icon: fromUser ? 'refresh' : 'trash',
    iconClassName: 'phone-svg-icon phone-msg-delete-icon',
    confirm: {
      title: fromUser ? '回撤到这条消息？' : '删除这条及之后的内容？',
      message: describeRollbackPlan(plan, fromUser),
      ...(detail ? { detail } : {}),
      confirmLabel: fromUser ? '回撤' : '删除',
    },
    run: async () => {
      const applied = await context.commands.rollbackMessage(message.id);
      context.showNotice(describeRollback(applied), 'info');
    },
  });
}

/** 回撤前的后果说明：会删掉几条、这条消息是否回到待生成。 */
function describeRollbackPlan(plan: MessageRollbackPlan, fromUser: boolean): string {
  const removed = plan.removedMessageIds.length;
  const scope = fromUser
    ? removed > 0 ? `将删除这条消息之后的 ${removed} 条内容` : '这条消息之后没有其他内容'
    : `将删除这条消息及其之后的 ${removed} 条内容`;
  const requeue = plan.requeueMessageId ? '，并让最后一条用户消息回到待生成，可重新生成回复' : '';
  return `${scope}${requeue}。删除的内容无法恢复。`;
}

function describeRollback(plan: MessageRollbackPlan): string {
  const removed = plan.removedMessageIds.length;
  if (plan.requeueMessageId) {
    return removed > 0
      ? `已删除 ${removed} 条后续内容，这条消息回到待生成，可再次点击生成`
      : '这条消息已回到待生成';
  }
  return `已删除 ${removed} 条内容`;
}

/** 论坛与推特中仅对当前仍可删除的用户帖子/回复显示删除按钮。 */
export function renderUnansweredPostDelete(
  context: DestructiveActionContext & {
    readonly state: PhoneState;
    readonly commands: { deleteUnansweredUserPost(postId: string): Promise<void> };
  },
  post: PhonePost,
  onDeleted?: () => void,
): HTMLButtonElement | null {
  if (!canDeleteUnansweredUserPost(context.state, post.id)) return null;
  const isThread = post.kind === 'forum-thread' || post.kind === 'twitter-post';
  const noun = isThread ? (post.appId === 'twitter' ? '动态' : '帖子') : '回复';
  const detail = confirmDetail(post.title ? `${post.title} ${post.content}` : post.content);
  return destructiveButton(context, {
    className: 'phone-post-delete',
    label: '删除这条尚未收到回复的内容',
    icon: 'trash',
    iconClassName: 'phone-svg-icon phone-post-delete-icon',
    confirm: {
      title: `删除这条${noun}？`,
      message: `这条${noun}还没有收到任何回复或评论，删除后无法恢复。`,
      ...(detail ? { detail } : {}),
      confirmLabel: '删除',
    },
    run: async () => {
      await context.commands.deleteUnansweredUserPost(post.id);
      context.showNotice(isThread ? `${noun}已删除` : '回复已删除', 'info');
      onDeleted?.();
    },
  });
}

export interface RichContentContext {
  readonly scopeId: string;
  readonly generateImage: (prompt: string) => Promise<string>;
  readonly notify: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

/** 从视图上下文构造富文本渲染所需的能力。 */
export function richContextOf(context: {
  readonly state: Pick<PhoneState, 'scopeId'>;
  readonly generateImage: (prompt: string) => Promise<string>;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}): RichContentContext {
  return { scopeId: context.state.scopeId, generateImage: context.generateImage, notify: context.showNotice };
}

/** 已生成图片的内存缓存（作用域 + 提示词 → 图片地址）。 */
const generatedImageCache = new Map<string, string>();
/** 正在生成的图片任务；视图重绘后，新按钮继续复用同一任务和加载态。 */
const pendingImageGenerations = new Map<string, Promise<string>>();
/** 正在恢复的图片，避免同屏多个相同标记并发查询。 */
const pendingRestores = new Map<string, Promise<string | null>>();

function generatedImageKey(scopeId: string, prompt: string): string {
  return `${scopeId}|${prompt}`;
}

/** 从当前浏览器的 IndexedDB 恢复已生成图片。 */
function restoreGeneratedImage(scopeId: string, prompt: string): Promise<string | null> {
  const key = generatedImageKey(scopeId, prompt);
  const cached = generatedImageCache.get(key);
  if (cached) return Promise.resolve(cached);
  let pending = pendingRestores.get(key);
  if (!pending) {
    pending = loadGeneratedImage(scopeId, prompt).then((src) => {
      if (src) generatedImageCache.set(key, src);
      pendingRestores.delete(key);
      return src;
    });
    pendingRestores.set(key, pending);
  }
  return pending;
}

/**
 * 渲染消息/动态内容：识别 [[生图:提示词]] 标记，把提示词隐藏为
 * “点击生成图片”卡片；点击后调用生图供应商并就地显示图片。
 */
export function renderRichContent(
  content: string,
  rich: RichContentContext | null,
  options: { readonly className?: string; readonly block?: boolean } = {},
): HTMLElement {
  const wrap = element(options.block ? 'div' : 'span', {
    className: `phone-rich-content${options.className ? ` ${options.className}` : ''}`,
  });
  for (const segment of splitContentWithImageMarkers(content)) {
    if (segment.kind === 'text') {
      if (segment.value.trim()) wrap.append(element('span', { text: segment.value }));
      continue;
    }
    wrap.append(renderImageSegment(segment.value, rich));
  }
  return wrap;
}

function getOrCreateImageGeneration(
  rich: RichContentContext,
  prompt: string,
): Promise<string> {
  const key = generatedImageKey(rich.scopeId, prompt);
  const active = pendingImageGenerations.get(key);
  if (active) return active;

  const task = (async () => {
    try {
      const src = await rich.generateImage(prompt);
      generatedImageCache.set(key, src);
      try {
        const localSrc = await persistGeneratedImage(rich.scopeId, prompt, src);
        generatedImageCache.set(key, localSrc);
        return localSrc;
      } catch (error) {
        rich.notify(
          `图片已生成，但未能保存到浏览器本地：${error instanceof Error ? error.message : String(error)}`,
          'error',
        );
        return src;
      }
    } catch (error) {
      rich.notify(
        `图片生成失败：${error instanceof Error ? error.message : String(error)}`,
        'error',
      );
      throw error;
    } finally {
      pendingImageGenerations.delete(key);
    }
  })();
  pendingImageGenerations.set(key, task);
  return task;
}

function renderImageSegment(prompt: string, rich: RichContentContext | null): HTMLElement {
  const scopeId = rich?.scopeId ?? '';
  const cacheKey = scopeId ? generatedImageKey(scopeId, prompt) : '';
  const cached = cacheKey ? generatedImageCache.get(cacheKey) : undefined;
  if (cached) return renderGeneratedImage(cached);

  const holder = element('span', { className: 'phone-genimage-holder' });
  const label = element('span', { text: '点击生成图片' });
  const observeGeneration = (task: Promise<string>): void => {
    trigger.disabled = true;
    trigger.classList.add('is-loading');
    trigger.setAttribute('aria-busy', 'true');
    label.textContent = '生成中…';
    void task.then(
      (src) => holder.replaceChildren(buildGeneratedImage(src)),
      () => {
        trigger.disabled = false;
        trigger.classList.remove('is-loading');
        trigger.removeAttribute('aria-busy');
        label.textContent = '点击生成图片';
      },
    );
  };
  const trigger = button('', 'phone-genimage-button', () => {
    if (!rich) return;
    observeGeneration(getOrCreateImageGeneration(rich, prompt));
  });
  trigger.append(element('span', { className: 'phone-genimage-icon', text: '🖼' }), label);
  holder.append(trigger);

  const active = cacheKey ? pendingImageGenerations.get(cacheKey) : undefined;
  if (active) observeGeneration(active);

  if (scopeId) {
    void restoreGeneratedImage(scopeId, prompt).then((src) => {
      if (src && !trigger.disabled) holder.replaceChildren(buildGeneratedImage(src));
    });
  }
  return holder;
}

function buildGeneratedImage(src: string): HTMLElement {
  const image = element('img', {
    className: 'phone-genimage',
    attributes: { src, alt: '生成的图片', loading: 'lazy' },
  });
  image.addEventListener('click', (event) => {
    event.preventDefault();
    event.stopPropagation();
    showImagePreview(image, src);
  });
  return image;
}

function renderGeneratedImage(src: string): HTMLElement {
  const holder = element('span', { className: 'phone-genimage-holder' });
  holder.append(buildGeneratedImage(src));
  return holder;
}

export function renderAvatar(profile: Profile | undefined, className = 'phone-avatar'): HTMLElement {
  const avatar = element('span', { className, text: profile?.displayName.slice(0, 1).toUpperCase() ?? '?' });
  if (profile?.avatarUrl) {
    const image = element('img', {
      attributes: { src: profile.avatarUrl, alt: profile.displayName, loading: 'lazy', referrerpolicy: 'no-referrer' },
    });
    image.addEventListener('error', () => image.remove(), { once: true });
    avatar.replaceChildren(image);
  }
  return avatar;
}

/** 图片/视频消息卡片：缩略图占位 + 用户写的文字描述。微信与推特私信共用。 */
export function renderMediaMessageCard(message: PhoneMessage, kind: 'image' | 'video'): HTMLElement {
  const card = element('div', { className: `phone-msg-card phone-msg-card-${kind}` });
  const thumb = element('span', { className: `phone-msg-thumb phone-msg-thumb-${kind}` });
  thumb.append(kind === 'image'
    ? element('span', { className: 'phone-msg-thumb-icon', text: '🖼' })
    : element('span', { className: 'phone-msg-thumb-play', text: '▶' }));
  const caption = message.metadata?.description
    ?? message.content.replace(kind === 'image' ? /^\[图片\]\s*/ : /^\[视频\]\s*/, '');
  card.append(thumb);
  if (caption) card.append(element('p', { className: 'phone-msg-card-caption', text: caption }));
  return card;
}

/** 强行介入卡片：写给模型的幕后指令，角色看不到，界面上明确标出来。 */
export function renderDirectiveCard(message: PhoneMessage): HTMLElement {
  const card = element('div', { className: 'phone-msg-card phone-msg-card-directive' });
  card.append(
    element('span', { className: 'phone-msg-directive-label', text: '强行介入 · 仅 AI 可见' }),
    element('p', { className: 'phone-msg-card-caption', text: message.metadata?.directive ?? message.content }),
  );
  return card;
}

/** 卡片类消息主体（图片、视频、位置、红包、礼物、转账、强行介入）自带完整卡面视觉。 */
export function isMessageCardBody(body: HTMLElement): boolean {
  return body.classList.contains('phone-msg-card');
}

/**
 * 把消息主体挂进堆叠层：文字进气泡，卡片直接贴在堆叠层上。
 *
 * 卡片本身就是一张完整的卡（底色、圆角、阴影齐全），再套一层聊天气泡，
 * 气泡底色就会从卡片四周露出来，看起来像两个气泡叠在一起；
 * 而且各主题给气泡上色的选择器权重都比「气泡里装了卡片就透明」这类结构规则高，
 * 光靠样式覆盖压不住，所以这里从结构上就不给卡片套气泡。
 * 微信、推特私信、匿名聊天共用这一条挂载路径，任何一处新增消息类型都不会再踩同一个坑。
 */
export function appendMessageBody(
  stack: HTMLElement,
  body: HTMLElement,
  options: { readonly senderName?: string } = {},
): void {
  const sender = options.senderName
    ? element('div', { className: 'phone-message-sender', text: options.senderName })
    : undefined;
  if (isMessageCardBody(body)) {
    // 堆叠层收缩到卡片宽度并按消息方向贴边，避免留下一段"看不见但占位"的空气泡。
    stack.classList.add('has-card');
    if (sender) stack.append(sender);
    stack.append(body);
    return;
  }
  const bubble = element('div', { className: 'phone-message-bubble' });
  if (sender) bubble.append(sender);
  bubble.append(body);
  stack.append(bubble);
}

/** 会话列表预览：强行介入不是聊天内容，单独标注，避免看起来像自己发的话。 */
export function describeMessagePreview(message: PhoneMessage | undefined, fallback: string): string {
  if (!message) return fallback;
  if (message.kind === 'directive') return `强行介入：${message.metadata?.directive ?? message.content}`;
  return message.content;
}

export interface ChatExtAction {
  readonly label: string;
  readonly handler: () => void | Promise<void>;
}

interface ChatComposeContext {
  readonly commands: {
    queueMessage(
      conversationId: string,
      content: string,
      options?: { readonly kind?: MessageKind; readonly metadata?: Readonly<Record<string, string>> },
    ): Promise<unknown>;
  };
  readonly showModal: (title: string, fields: readonly ModalField[]) => Promise<Record<string, string> | null>;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

/**
 * 微信式「+」扩展面板：返回折叠面板与开关按钮，选中任一动作后自动收起。
 * 微信与推特私信共用同一套交互与样式。
 */
export function createChatExtPanel(
  context: { readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void },
  actions: readonly ChatExtAction[],
): { readonly panel: HTMLElement; readonly toggle: HTMLButtonElement } {
  const panel = element('div', { className: 'phone-chat-ext-panel', attributes: { hidden: '' } });
  const grid = element('div', { className: 'phone-chat-ext-grid' });
  for (const action of actions) {
    grid.append(button(action.label, 'phone-chat-ext-action', () => {
      panel.hidden = true;
      void Promise.resolve(action.handler()).catch((error: unknown) => {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      });
    }));
  }
  panel.append(grid);
  const toggle = button('', 'phone-chat-plus', () => { panel.hidden = !panel.hidden; });
  toggle.setAttribute('aria-label', '更多');
  toggle.title = '更多';
  toggle.append(element('span', { text: '+' }));
  return { panel, toggle };
}

/** 发送图片/视频：画面内容由用户用文字描述。 */
export async function sendMediaMessage(
  context: ChatComposeContext,
  conversationId: string,
  kind: 'image' | 'video',
): Promise<void> {
  const label = kind === 'image' ? '图片' : '视频';
  const values = await context.showModal(`发送${label}`, [
    { name: 'description', label: `${label}描述`, type: 'textarea', required: true },
  ]);
  const description = values?.description?.trim();
  if (!description) return;
  await context.commands.queueMessage(conversationId, `[${label}] ${description}`, {
    kind,
    metadata: { description },
  });
  context.showNotice(`${label}已发送，等待统一生成回复`, 'success');
}

/**
 * 强行介入：把一条只给模型看的指令挂到本会话，下一轮生成必须照此执行。
 * 相当于在消息末尾用括号写给 AI 的话，但不会出现在聊天内容与正文摘要里。
 */
export async function sendDirectiveMessage(
  context: ChatComposeContext,
  conversationId: string,
): Promise<void> {
  const values = await context.showModal('强行介入', [{
    name: 'directive',
    label: '给 AI 的指令（角色看不到这段话）',
    type: 'textarea',
    required: true,
    placeholder: '例如：他最终接受了我的提议，但嘴上还要别扭一下',
  }]);
  const directive = values?.directive?.trim();
  if (!directive) return;
  await context.commands.queueMessage(conversationId, directive, {
    kind: 'directive',
    metadata: { directive },
  });
  context.showNotice('已记录强行介入，下轮生成会照此执行', 'success');
}

export function renderPostCard(
  state: PhoneState,
  post: PhonePost,
  options: {
    readonly replyLabel?: string;
    readonly rich?: RichContentContext;
    readonly onReply?: (post: PhonePost) => void | Promise<void>;
    readonly onLike?: (post: PhonePost) => void | Promise<void>;
    readonly onComment?: (post: PhonePost) => void | Promise<void>;
  } = {},
): HTMLElement {
  const card = element('article', { className: `phone-post-card phone-post-card-${post.appId}` });
  const profile = state.profiles[post.profileId];
  const self = state.profiles[SELF_PROFILE_ID];
  const identity = resolvePublicIdentity(profile, post.appId === 'twitter' ? 'twitter' : post.appId === 'forum' ? 'forum' : 'wechat', SELF_PROFILE_ID, self?.displayName ?? '');
  const head = element('header', { className: 'phone-post-head' });
  const identityBlock = element('div', { className: 'phone-list-main' });
  identityBlock.append(
    element('div', { className: 'phone-post-author', text: identity.name }),
    element('div', { className: 'phone-post-time', text: formatTime(post.createdAt) }),
  );
  if (identity.anonymous) identityBlock.append(element('small', { className: 'phone-post-anonymous', text: '匿名' }));
  head.append(renderAvatar(profile), identityBlock);
  const content = renderRichContent(post.content, options.rich ?? null, { className: 'phone-post-content', block: true });
  card.append(head, content);

  const interactions = Object.values(state.interactions).filter((item) => item.targetId === post.id);
  if (interactions.length > 0) card.append(renderInteractions(state, interactions));
  const hasSelfLike = interactions.some((item) => item.type === 'like' && item.actorProfileId === SELF_PROFILE_ID);
  if (options.onReply || options.onLike || options.onComment) {
    const actions = element('div', { className: 'phone-post-actions' });
    if (options.onLike) {
      actions.append(button(hasSelfLike ? '已赞' : '赞', 'phone-button phone-button-ghost', () => options.onLike?.(post)));
    }
    if (options.onComment) {
      actions.append(button('评论', 'phone-button phone-button-ghost', () => options.onComment?.(post)));
    }
    if (options.onReply) {
      actions.append(button(options.replyLabel ?? '回复', 'phone-button phone-button-ghost', () => options.onReply?.(post)));
    }
    card.append(actions);
  }
  return card;
}

function renderInteractions(state: PhoneState, interactions: readonly Interaction[]): HTMLElement {
  const list = element('div', { className: 'phone-list-preview' });
  const self = state.profiles[SELF_PROFILE_ID];
  const publicName = (interaction: Interaction): string => {
    const profile = state.profiles[interaction.actorProfileId];
    const app = interaction.appId === 'twitter' ? 'twitter' : interaction.appId === 'forum' ? 'forum' : 'wechat';
    return resolvePublicIdentity(profile, app, SELF_PROFILE_ID, self?.displayName ?? '').name;
  };
  const likes = interactions.filter((item) => item.type === 'like');
  if (likes.length > 0) {
    const names = likes.map(publicName);
    list.append(element('div', { text: `赞 · ${names.join('、')}` }));
  }
  for (const interaction of interactions.filter((item) => item.type === 'comment')) {
    list.append(element('div', { text: `${publicName(interaction)}：${interaction.content ?? ''}` }));
  }
  return list;
}

/** 将任意图片地址压缩为适合资料头像存储的 dataURL；跨域图片无法读取时保留原地址。 */
export function resizeImageSourceAsDataUrl(source: string, maxDimension = 512): Promise<string> {
  return new Promise((resolve) => {
    if (!source) {
      resolve(source);
      return;
    }
    const image = new Image();
    if (!source.startsWith('data:')) image.crossOrigin = 'anonymous';
    image.onload = () => {
      const scale = Math.min(1, maxDimension / Math.max(image.width, image.height, 1));
      if (scale >= 1 && source.length <= 750_000) {
        resolve(source);
        return;
      }
      const canvas = document.createElement('canvas');
      canvas.width = Math.max(1, Math.round(image.width * scale));
      canvas.height = Math.max(1, Math.round(image.height * scale));
      const context = canvas.getContext('2d');
      if (!context) {
        resolve(source);
        return;
      }
      try {
        context.drawImage(image, 0, 0, canvas.width, canvas.height);
        resolve(canvas.toDataURL('image/jpeg', 0.85));
      } catch {
        resolve(source);
      }
    };
    image.onerror = () => resolve(source);
    image.src = source;
  });
}

/**
 * 打开文件选择器读取一张图片并压缩为 dataURL（最长边不超过 maxDimension）。
 * 取消选择时返回 null。
 */
export function pickImageAsDataUrl(maxDimension = 512): Promise<string | null> {
  return new Promise((resolve) => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.addEventListener('change', () => {
      const file = input.files?.[0];
      if (!file) {
        resolve(null);
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        const source = String(reader.result ?? '');
        if (!source) {
          resolve(null);
          return;
        }
        void resizeImageSourceAsDataUrl(source, maxDimension).then(resolve);
      };
      reader.onerror = () => {
        beginPhoneTask('imagePick').fail(reader.error?.message || '无法读取图片文件。');
        resolve(null);
      };
      reader.readAsDataURL(file);
    }, { once: true });
    input.click();
  });
}

/**
 * 进入聊天/发送消息后滚动到最新消息。
 * - 列表自身可滚动时直接置底；
 * - 同时用 scrollIntoView 兜底（滚动发生在外层容器时也能定位）；
 * - 连续两帧 + 延迟补偿，覆盖图片/字体加载导致的高度变化。
 */
export function scrollToLatestMessage(list: HTMLElement): void {
  const scroll = () => {
    const last = list.lastElementChild as HTMLElement | null;
    last?.scrollIntoView?.({ block: 'end', inline: 'nearest' });
    // scrollIntoView 之后再置底，保证滚到含底部内边距的绝对底部。
    list.scrollTop = list.scrollHeight;
  };
  requestAnimationFrame(() => {
    scroll();
    requestAnimationFrame(scroll);
  });
  window.setTimeout(scroll, 120);
  window.setTimeout(scroll, 360);
}

export function formatTime(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}

/** 批量匹配结果的提示文案：匹配到谁、跳过了谁、是否还有剩余。 */
export function describeContactMatchResult(result: ContactAutoMatchResult, label: string): string {
  if (result.contacts.length === 0) {
    return result.skipped.length > 0
      ? `没有新的${label}可匹配（${result.skipped.slice(0, 5).join('、')}）`
      : `世界书里没有找到可以匹配的${label}。`;
  }
  const names = result.contacts
    .map((contact) => `${contact.displayName}（${contact.boundCharacter}）`)
    .join('、');
  const parts = [`已匹配 ${result.contacts.length} 位${label}：${names}`];
  if (result.skipped.length > 0) {
    parts.push(`跳过 ${result.skipped.length} 位（${result.skipped.slice(0, 3).join('、')}）`);
  }
  if (result.hasMore) parts.push('如仍有角色未匹配，可再次点击自动匹配');
  return parts.join('；');
}