import {
  generateWithApiProxy,
  type ApiRetryProgress,
} from './api-client.js';
import type { OpenAiCompatibleApiConfig } from '../integration/sillytavern-bridge.js';

export interface GenerationRequest {
  readonly generationId: string;
  readonly system: string;
  readonly user: string;
  readonly temperature?: number;
  readonly maxTokens?: number;
  readonly signal?: AbortSignal;
  readonly onRetry?: (progress: ApiRetryProgress) => void | Promise<void>;
}

export type GenerationProviderPreference = 'auto' | 'quietPrompt' | 'tavernHelper';
export type GenerationRunProvider = 'configuredApi' | 'quietPrompt' | 'tavernHelper' | 'tavernFallback' | 'none';

export interface GenerationRunInfo {
  readonly provider: GenerationRunProvider;
  readonly status: 'idle' | 'running' | 'succeeded' | 'failed';
  readonly model?: string;
  readonly message: string;
}

export interface GenerationPort {
  generate(request: GenerationRequest): Promise<string>;
  stop(generationId: string): void;
  setProviderPreference?(preference: GenerationProviderPreference): void;
  setApiConfigs?(configs: {
    readonly primaryApi?: OpenAiCompatibleApiConfig;
    readonly secondaryApi?: OpenAiCompatibleApiConfig;
    readonly allowTavernFallback?: boolean;
  }): void;
  getLastRun?(): GenerationRunInfo;
}

export interface GenerationCapabilities {
  readonly preference: GenerationProviderPreference;
  readonly quietPromptAvailable: boolean;
  readonly tavernHelperAvailable: boolean;
  readonly configuredApiAvailable: boolean;
  readonly configuredApiRequested: boolean;
  readonly configuredModel: string;
  readonly allowTavernFallback: boolean;
  readonly selectedProvider: 'configuredApi' | 'quietPrompt' | 'tavernHelper' | 'unavailable';
  readonly selectedLabel: string;
}

export interface GenerationPortOptions {
  readonly preferTavernHelper?: boolean;
  readonly providerPreference?: GenerationProviderPreference;
  readonly primaryApi?: OpenAiCompatibleApiConfig;
  readonly secondaryApi?: OpenAiCompatibleApiConfig;
  readonly allowTavernFallback?: boolean;
}

interface TavernHelperApi {
  generateRaw?: (config: Record<string, unknown>) => Promise<string>;
  stopGenerationById?: (generationId: string) => void;
}

type QuietPromptGenerator = (
  quietPrompt: string,
  quietToLoud?: boolean,
  skipWIAN?: boolean,
  quietImage?: string | null,
  quietName?: string | null,
  responseLength?: number | null,
) => Promise<string>;

interface SillyTavernContext {
  generateQuietPrompt?: QuietPromptGenerator;
}

interface SillyTavernApi {
  getContext?: () => SillyTavernContext;
}

declare global {
  interface Window {
    TavernHelper?: TavernHelperApi;
    SillyTavern?: SillyTavernApi;
  }
}

function getHostWindow(): Window {
  try {
    return window.parent && window.parent !== window ? window.parent : window;
  } catch {
    return window;
  }
}

function getTavernHelper(): TavernHelperApi | null {
  const host = getHostWindow();
  return host.TavernHelper ?? window.TavernHelper ?? null;
}

function getSillyTavernContext(): SillyTavernContext | null {
  const host = getHostWindow();
  return host.SillyTavern?.getContext?.() ?? window.SillyTavern?.getContext?.() ?? null;
}

export function isConfiguredApiReady(config: OpenAiCompatibleApiConfig | undefined): boolean {
  return Boolean(config?.enabled && config.model.trim());
}

export function detectGenerationCapabilities(
  preference: GenerationProviderPreference = 'auto',
  apiConfigs?: {
    readonly primaryApi?: OpenAiCompatibleApiConfig;
    readonly secondaryApi?: OpenAiCompatibleApiConfig;
    readonly allowTavernFallback?: boolean;
  },
): GenerationCapabilities {
  const helper = getTavernHelper();
  const context = getSillyTavernContext();
  const quietPromptAvailable = typeof context?.generateQuietPrompt === 'function';
  const tavernHelperAvailable = typeof helper?.generateRaw === 'function';
  const configuredApiRequested = Boolean(apiConfigs?.primaryApi?.enabled || apiConfigs?.secondaryApi?.enabled);
  const configuredApi = [apiConfigs?.primaryApi, apiConfigs?.secondaryApi].find(isConfiguredApiReady);
  const configuredApiAvailable = Boolean(configuredApi);

  const selectedProvider = configuredApiRequested
    ? 'configuredApi'
    : selectTavernProvider(preference, quietPromptAvailable, tavernHelperAvailable);
  const selectedLabel = selectedProvider === 'configuredApi'
    ? configuredApiAvailable
      ? `配置 API · ${configuredApi?.model ?? ''}`
      : '配置 API（缺少模型，请先拉取并选择）'
    : selectedProvider === 'quietPrompt'
      ? '酒馆静默生成'
      : selectedProvider === 'tavernHelper'
        ? '酒馆助手生成'
        : '未检测到可用的回复引擎';

  return {
    preference,
    quietPromptAvailable,
    tavernHelperAvailable,
    configuredApiAvailable,
    configuredApiRequested,
    configuredModel: configuredApi?.model ?? '',
    allowTavernFallback: apiConfigs?.allowTavernFallback === true,
    selectedProvider,
    selectedLabel,
  };
}

export class SillyTavernGenerationPort implements GenerationPort {
  #providerPreference: GenerationProviderPreference;
  #primaryApi: OpenAiCompatibleApiConfig;
  #secondaryApi: OpenAiCompatibleApiConfig;
  #allowTavernFallback: boolean;
  #lastRun: GenerationRunInfo = {
    provider: 'none',
    status: 'idle',
    message: '尚未开始生成。',
  };

  constructor(options: GenerationPortOptions = {}) {
    this.#providerPreference = options.providerPreference ?? (options.preferTavernHelper ? 'tavernHelper' : 'auto');
    this.#primaryApi = options.primaryApi ?? emptyApiConfig();
    this.#secondaryApi = options.secondaryApi ?? emptyApiConfig();
    this.#allowTavernFallback = options.allowTavernFallback === true;
  }

  get capabilities(): GenerationCapabilities {
    return detectGenerationCapabilities(this.#providerPreference, {
      primaryApi: this.#primaryApi,
      secondaryApi: this.#secondaryApi,
      allowTavernFallback: this.#allowTavernFallback,
    });
  }

  getLastRun(): GenerationRunInfo {
    return this.#lastRun;
  }

  setProviderPreference(preference: GenerationProviderPreference): void {
    this.#providerPreference = preference;
  }

  setApiConfigs(configs: {
    readonly primaryApi?: OpenAiCompatibleApiConfig;
    readonly secondaryApi?: OpenAiCompatibleApiConfig;
    readonly allowTavernFallback?: boolean;
  }): void {
    if (configs.primaryApi) this.#primaryApi = configs.primaryApi;
    if (configs.secondaryApi) this.#secondaryApi = configs.secondaryApi;
    if (configs.allowTavernFallback !== undefined) this.#allowTavernFallback = configs.allowTavernFallback;
  }

  async generate(request: GenerationRequest): Promise<string> {
    if (request.signal?.aborted) throw abortError();
    const enabledApis = [this.#primaryApi, this.#secondaryApi].filter((config) => config.enabled);
    if (enabledApis.length === 0) return this.#generateWithTavern(request, false);

    const readyApis = enabledApis.filter(isConfiguredApiReady);
    if (readyApis.length === 0) {
      return this.#handleConfiguredApiFailure(
        request,
        new Error('已启用配置 API，但尚未填写模型；请在设置中拉取并选择模型。'),
      );
    }

    let lastError: unknown = null;
    for (const [index, config] of readyApis.entries()) {
      const label = index === 0 ? '主配置 API' : '副配置 API';
      this.#lastRun = {
        provider: 'configuredApi',
        status: 'running',
        model: config.model,
        message: `正在使用${label} · ${config.model}。`,
      };
      try {
        const text = await raceAbort(
          generateWithApiProxy(config, {
            system: request.system,
            user: request.user,
            // API 配置里的采样参数优先；未设置时跟随「生成设置」的全局值。
            temperature: config.temperature ?? request.temperature ?? 0.8,
            maxTokens: config.maxTokens ?? request.maxTokens ?? 1200,
            signal: request.signal,
            ...(request.onRetry ? { onRetry: request.onRetry } : {}),
          }),
          request.signal,
          () => this.stop(request.generationId),
        );
        this.#lastRun = {
          provider: 'configuredApi',
          status: 'succeeded',
          model: config.model,
          message: `${label}已完成 · ${config.model}。`,
        };
        return text;
      } catch (error) {
        lastError = error;
        if (request.signal?.aborted) throw error;
      }
    }

    return this.#handleConfiguredApiFailure(request, lastError);
  }

  stop(generationId: string): void {
    const helper = getTavernHelper();
    try {
      helper?.stopGenerationById?.(generationId);
    } catch (error) {
      console.warn('[墨韵手机] 停止静默生成失败', error);
    }
  }

  async #handleConfiguredApiFailure(request: GenerationRequest, error: unknown): Promise<string> {
    const message = redactApiError(error, [this.#primaryApi, this.#secondaryApi]);
    if (!this.#allowTavernFallback) {
      this.#lastRun = {
        provider: 'configuredApi',
        status: 'failed',
        message: `配置 API 失败，未启用酒馆回退：${message}`,
      };
      throw new Error(`配置 API 生成失败：${message}。已禁用酒馆回退。`);
    }
    try {
      return await this.#generateWithTavern(request, true);
    } catch (fallbackError) {
      const fallbackMessage = redactApiError(fallbackError, [this.#primaryApi, this.#secondaryApi]);
      this.#lastRun = {
        provider: 'tavernFallback',
        status: 'failed',
        message: `配置 API 失败：${message}；酒馆回退失败：${fallbackMessage}`,
      };
      throw new Error(`配置 API 失败：${message}；酒馆回退也失败：${fallbackMessage}`);
    }
  }

  async #generateWithTavern(request: GenerationRequest, fallbackFromConfiguredApi: boolean): Promise<string> {
    const helper = getTavernHelper();
    const context = getSillyTavernContext();
    const useHelper = this.#shouldUseTavernHelper(helper, context);
    const provider: GenerationRunProvider = fallbackFromConfiguredApi
      ? 'tavernFallback'
      : useHelper
        ? 'tavernHelper'
        : 'quietPrompt';
    this.#lastRun = {
      provider,
      status: 'running',
      message: fallbackFromConfiguredApi ? '配置 API 失败，正在回退酒馆生成。' : '正在使用酒馆生成。',
    };
    const task = useHelper
      ? this.#generateWithHelper(helper as TavernHelperApi, request)
      : this.#generateQuietly(context, request);
    const text = await raceAbort(task, request.signal, () => this.stop(request.generationId));
    this.#lastRun = {
      provider,
      status: 'succeeded',
      message: fallbackFromConfiguredApi ? '已通过酒馆回退通道完成生成。' : '已通过酒馆生成完成。',
    };
    return text;
  }

  #shouldUseTavernHelper(
    helper: TavernHelperApi | null,
    context: SillyTavernContext | null,
  ): boolean {
    if (this.#providerPreference === 'tavernHelper') return Boolean(helper?.generateRaw);
    if (this.#providerPreference === 'quietPrompt') return !context?.generateQuietPrompt && Boolean(helper?.generateRaw);
    return !context?.generateQuietPrompt && Boolean(helper?.generateRaw);
  }

  async #generateWithHelper(helper: TavernHelperApi, request: GenerationRequest): Promise<string> {
    if (!helper.generateRaw) throw new Error('酒馆助手生成接口不可用。');
    return helper.generateRaw({
      generation_id: request.generationId,
      should_silence: true,
      should_stream: false,
      max_chat_history: 0,
      ...(request.temperature === undefined ? {} : { temperature: request.temperature }),
      ...(request.maxTokens === undefined ? {} : { max_tokens: request.maxTokens }),
      user_input: request.user,
      ordered_prompts: [
        { role: 'system', content: request.system },
        'world_info_before',
        'char_description',
        'char_personality',
        'scenario',
        'world_info_after',
        'user_input',
      ],
    });
  }

  async #generateQuietly(
    context: SillyTavernContext | null,
    request: GenerationRequest,
  ): Promise<string> {
    if (!context?.generateQuietPrompt) {
      throw new Error('未检测到酒馆静默生成或酒馆助手生成接口。');
    }
    return context.generateQuietPrompt(
      `${request.system}\n\n${request.user}`,
      false,
      false,
      null,
      null,
      request.maxTokens,
    );
  }
}

function selectTavernProvider(
  preference: GenerationProviderPreference,
  quietPromptAvailable: boolean,
  tavernHelperAvailable: boolean,
): GenerationCapabilities['selectedProvider'] {
  if (preference === 'tavernHelper') {
    return tavernHelperAvailable ? 'tavernHelper' : quietPromptAvailable ? 'quietPrompt' : 'unavailable';
  }
  if (preference === 'quietPrompt') {
    return quietPromptAvailable ? 'quietPrompt' : tavernHelperAvailable ? 'tavernHelper' : 'unavailable';
  }
  return quietPromptAvailable ? 'quietPrompt' : tavernHelperAvailable ? 'tavernHelper' : 'unavailable';
}

function emptyApiConfig(): OpenAiCompatibleApiConfig {
  return {
    enabled: false,
    baseUrl: '',
    apiKey: '',
    model: '',
    temperature: null,
    maxTokens: null,
    maxContextTokens: null,
    stream: true,
    maxTokenField: 'max_tokens',
    topP: 1,
    frequencyPenalty: 0,
    presencePenalty: 0,
  };
}

function redactApiError(error: unknown, configs: readonly OpenAiCompatibleApiConfig[]): string {
  let message = error instanceof Error ? error.message : String(error ?? '未知错误');
  for (const config of configs) {
    if (config.apiKey.trim()) message = message.replaceAll(config.apiKey.trim(), '[已隐藏]');
  }
  return message.replace(/\s+/g, ' ').trim().slice(0, 500) || '未知错误';
}

function raceAbort<T>(task: Promise<T>, signal: AbortSignal | undefined, onAbort: () => void): Promise<T> {
  if (!signal) return task;
  return new Promise((resolve, reject) => {
    const handleAbort = () => {
      onAbort();
      reject(abortError());
    };
    signal.addEventListener('abort', handleAbort, { once: true });
    task.then(
      (value) => {
        signal.removeEventListener('abort', handleAbort);
        resolve(value);
      },
      (error: unknown) => {
        signal.removeEventListener('abort', handleAbort);
        reject(error);
      },
    );
  });
}

function abortError(): DOMException {
  return new DOMException('生成已取消', 'AbortError');
}