import type { AppId, PostKind } from '../domain/model.js';

export const GENERATION_PROTOCOL_VERSION = 1;
export const GENERATION_MAX_ACTIONS = 120;
export const GENERATION_MAX_VARIABLE_UPDATES = 200;
export const GENERATION_MAX_ACTOR_NAME_LENGTH = 24;
export const GENERATION_MAX_THOUGHT_LENGTH = 400;
export const GENERATION_MAX_COMMON_CONTENT_LENGTH = 500;
export const GENERATION_MAX_LONG_CONTENT_LENGTH = 1_200;
export const GENERATION_MAX_TITLE_LENGTH = 80;
export const GENERATION_MAX_VARIABLE_PATH_LENGTH = 200;
export const GENERATION_MAX_DELAY_MINUTES = 45;

export const GENERATION_ACTION_TYPES = [
  'message.reply',
  'moment.create',
  'forum.thread.create',
  'forum.ambient.create',
  'forum.reply.create',
  'twitter.post.create',
  'twitter.ambient.create',
  'twitter.reply.create',
  'twitter.repost.create',
  'interaction.like',
  'interaction.comment',
  'message.claim',
] as const;
export const GENERATION_LONG_CONTENT_ACTION_TYPES = [
  'forum.thread.create',
  'forum.ambient.create',
  'forum.reply.create',
] as const;
export const GENERATION_COMMON_CONTENT_ACTION_TYPES = GENERATION_ACTION_TYPES.filter(
  (type) => !GENERATION_LONG_CONTENT_ACTION_TYPES.includes(type as typeof GENERATION_LONG_CONTENT_ACTION_TYPES[number]),
);
export const GENERATION_RESPONSE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['version', 'batchId', 'actions'],
  properties: {
    version: { const: GENERATION_PROTOCOL_VERSION },
    batchId: { type: 'string' },
    actions: {
      type: 'array',
      maxItems: GENERATION_MAX_ACTIONS,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['type'],
        description: '除 message.claim 外，动作必须提供 content；常规动作需要 actorProfileId，论坛/推特路人动作可改用 actorName。具体必填字段见 meta.protocols().',
        properties: {
          type: {
            enum: GENERATION_ACTION_TYPES,
          },
          conversationId: { type: 'string' },
          actorProfileId: { type: 'string' },
          actorName: {
            type: 'string',
            minLength: 1,
            maxLength: GENERATION_MAX_ACTOR_NAME_LENGTH,
            description: '论坛/推特匿名路人昵称；独立动态和公开互动使用，不能映射为真实姓名',
          },
          thought: {
            type: 'string',
            maxLength: GENERATION_MAX_THOUGHT_LENGTH,
            description: '内部思考（不展示给用户）：角色此刻在哪/在做什么/心情与关系温度/这轮想达成什么/用什么说话指纹；content 必须与之一致',
          },
          content: { type: 'string', minLength: 1, maxLength: GENERATION_MAX_LONG_CONTENT_LENGTH },
          title: {
            type: 'string',
            minLength: 1,
            maxLength: GENERATION_MAX_TITLE_LENGTH,
            description: 'forum.thread.create 的主题标题；其他动作省略',
          },
          targetId: { type: 'string' },
          parentId: { type: 'string' },
          claimStatus: { type: 'string', enum: ['claimed', 'declined'] },
          delayMinutes: { type: 'number', minimum: 0, maximum: GENERATION_MAX_DELAY_MINUTES },
        },
      },
    },
    variableUpdates: {
      type: 'array',
      maxItems: GENERATION_MAX_VARIABLE_UPDATES,
      description: '需要随剧情推进更新的已有变量（相对 stat_data 的点分路径）',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['path', 'value'],
        properties: {
          path: { type: 'string', minLength: 1, maxLength: GENERATION_MAX_VARIABLE_PATH_LENGTH },
          value: { type: ['string', 'number', 'boolean', 'null'] },
        },
      },
    },
  },
} as const;

export type GenerationActionType = typeof GENERATION_ACTION_TYPES[number];

export interface ValidatedGenerationAction {
  readonly actionId: string;
  readonly type: GenerationActionType;
  readonly appId: AppId;
  /** 常规动作为已有档案 id；推特路人互动为空字符串并携带 actorName。 */
  readonly actorProfileId: string;
  /** 推特路人网友昵称（仅当 actorProfileId 为空时使用）。 */
  readonly actorName?: string;
  /** 角色内部思考（状态/位置/动作/想法），仅用于提升回复质量，不展示给用户。 */
  readonly thought?: string;
  readonly content: string;
  readonly title?: string;
  readonly conversationId?: string;
  readonly targetId?: string;
  readonly parentId?: string;
  readonly delayMinutes?: number;
  readonly postKind?: PostKind;
  readonly claimStatus?: 'claimed' | 'declined';
}

export interface ValidationIssue {
  readonly index: number;
  readonly reason: string;
}

export interface ValidatedVariableUpdate {
  readonly path: string;
  readonly value: string | number | boolean | null;
}

export interface ValidationResult {
  readonly actions: readonly ValidatedGenerationAction[];
  readonly issues: readonly ValidationIssue[];
  readonly variableUpdates: readonly ValidatedVariableUpdate[];
}