import { canonCharacterId, normalizeName } from './identity.js';
import type {
  FanficDivergence,
  FanficNarrativeCore,
  FanficNarrativeState,
  FanficPresence,
  FanficRelationshipShift,
  FanficSecret,
  FanficThread,
} from './model.js';
import { advanceFanficNarrative } from './narrative.js';
import type { NarrativePatch, NarrativeThreadPatch } from './patch-protocol.js';
import { hashText } from './source-normalizer.js';

const SHIFT_LIMIT = 24;
const SECRET_LIMIT = 32;
const THREAD_LIMIT = 32;
const DIVERGENCE_LIMIT = 16;

/**
 * 把状态补丁应用到剧情状态：场景与人物状态整体替换（它们描述"此刻"），
 * 关系变化、秘密、约定、伏笔与原著分歧按去重累积，兑现的条目被标记为已解决。
 */
export function applyNarrativePatch(
  state: FanficNarrativeState,
  patch: NarrativePatch,
  floor: number,
): FanficNarrativeState {
  const core: FanficNarrativeCore = {
    scene: patch.scene
      ? { place: patch.scene.place, time: patch.scene.time, situation: patch.scene.situation, floor }
      : state.scene,
    presence: patch.presence.length > 0 ? mapPresence(patch) : state.presence,
    relationshipShifts: mergeShifts(state.relationshipShifts, patch, floor),
    secrets: mergeSecrets(state.secrets, patch, floor),
    threads: mergeThreads(state.threads, patch, floor),
    divergences: mergeDivergences(state.divergences, patch, floor),
  };
  return advanceFanficNarrative(state, floor, core);
}

function mapPresence(patch: NarrativePatch): readonly FanficPresence[] {
  const seen = new Set<string>();
  const presence: FanficPresence[] = [];
  for (const entry of patch.presence) {
    const characterId = canonCharacterId(entry.name);
    if (!characterId || seen.has(characterId)) continue;
    seen.add(characterId);
    presence.push({
      characterId,
      name: entry.name,
      present: entry.present,
      posture: entry.posture,
      holding: entry.holding,
      mood: entry.mood,
    });
  }
  return presence;
}

function mergeShifts(
  existing: readonly FanficRelationshipShift[],
  patch: NarrativePatch,
  floor: number,
): readonly FanficRelationshipShift[] {
  const known = new Set(existing.map((shift) => normalizeName(shift.summary)));
  const added = patch.shifts.flatMap((shift) => {
    const key = normalizeName(shift.summary);
    if (!key || known.has(key)) return [];
    known.add(key);
    return [{
      characterId: canonCharacterId(shift.from),
      targetId: canonCharacterId(shift.to),
      summary: shift.summary,
      floor,
    }];
  });
  return [...existing, ...added].slice(-SHIFT_LIMIT);
}

function mergeSecrets(
  existing: readonly FanficSecret[],
  patch: NarrativePatch,
  floor: number,
): readonly FanficSecret[] {
  const merged = existing.map((secret) => ({ ...secret }));
  for (const entry of patch.secrets) {
    const key = normalizeName(entry.text);
    if (!key) continue;
    const index = merged.findIndex((secret) => normalizeName(secret.text) === key);
    if (index >= 0) {
      const current = merged[index]!;
      merged[index] = { ...current, knownBy: unionNames(current.knownBy, entry.knownBy) };
      continue;
    }
    merged.push({ id: `secret:${floor}:${hashText(key)}`, text: entry.text, knownBy: entry.knownBy, floor });
  }
  return merged.slice(-SECRET_LIMIT);
}

function mergeThreads(
  existing: readonly FanficThread[],
  patch: NarrativePatch,
  floor: number,
): readonly FanficThread[] {
  const resolvedKeys = patch.resolved.map((text) => normalizeName(text)).filter(Boolean);
  const marked = existing.map((thread) => {
    if (thread.resolved) return thread;
    const key = normalizeName(thread.text);
    const hit = resolvedKeys.some((resolved) => key.includes(resolved) || resolved.includes(key));
    return hit ? { ...thread, resolved: true } : thread;
  });
  const known = new Set(marked.map((thread) => normalizeName(thread.text)));
  const append = (entries: readonly NarrativeThreadPatch[], kind: FanficThread['kind']): readonly FanficThread[] =>
    entries.flatMap((entry) => {
      const key = normalizeName(entry.text);
      if (!key || known.has(key)) return [];
      known.add(key);
      return [{ id: `${kind}:${floor}:${hashText(key)}`, kind, text: entry.text, owners: entry.owners, floor, resolved: false }];
    });
  return [
    ...marked,
    ...append(patch.promises, 'promise'),
    ...append(patch.openThreads, 'open'),
  ].slice(-THREAD_LIMIT);
}

function mergeDivergences(
  existing: readonly FanficDivergence[],
  patch: NarrativePatch,
  floor: number,
): readonly FanficDivergence[] {
  const known = new Set(existing.map((divergence) => normalizeName(`${divergence.canonText}${divergence.storyText}`)));
  const added = patch.divergences.flatMap((divergence) => {
    const key = normalizeName(`${divergence.canon}${divergence.story}`);
    if (!key || known.has(key)) return [];
    known.add(key);
    return [{ id: `diverge:${floor}:${hashText(key)}`, canonText: divergence.canon, storyText: divergence.story, floor }];
  });
  return [...existing, ...added].slice(-DIVERGENCE_LIMIT);
}

function unionNames(current: readonly string[], incoming: readonly string[]): readonly string[] {
  const seen = new Map<string, string>();
  for (const name of [...current, ...incoming]) {
    const key = normalizeName(name);
    if (!key || seen.has(key)) continue;
    seen.set(key, name);
  }
  return [...seen.values()].slice(0, 16);
}