import type { PhoneViewContext } from '../app-types.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import { fanficActionButton, fanficDetailBlock, fanficStatRow } from './shared.js';

/** 本作已发生：当前场景、人物状态、关系变化、秘密、约定与原著分歧，以及本轮召回诊断。 */
export function renderFanficNarrative(context: PhoneViewContext): HTMLElement {
  const fanfic = context.fanfic;
  const narrative = fanfic.narrative;
  const view = element('div', { className: 'phone-fanfic-section' });
  const scene = narrative.scene;
  const hasContent = Boolean(scene.place || scene.situation) || narrative.presence.length > 0;

  view.append(element('p', {
    className: 'phone-settings-hint',
    text: '这里记录"进入下一轮时仍然成立"的事实。它优先于原著：与原著冲突时以这里为准，正文楼层被编辑或删除时会自动回滚。',
  }));
  view.append(
    fanficStatRow('已跟踪到', narrative.lastFloor >= 0 ? `第 ${narrative.lastFloor} 楼` : '尚未建立', narrative.lastFloor >= 0),
    fanficStatRow('当前场景', [scene.place, scene.time, scene.situation].filter(Boolean).join(' / '), hasContent),
    fanficStatRow('回滚检查点', `${narrative.checkpoints.length} 个`, narrative.checkpoints.length > 0),
  );

  if (!hasContent) {
    const empty = element('div', { className: 'phone-empty' });
    empty.append(
      renderPhoneIcon('memory'),
      element('strong', { text: '还没有剧情状态' }),
      element('span', { text: 'AI 回复后会自动跟踪；也可以现在点「立即更新」用已有正文建立状态。' }),
    );
    view.append(empty);
  }

  for (const block of [
    fanficDetailBlock('人物当前状态', narrative.presence.map((presence) => {
      const details = [presence.posture, presence.holding, presence.mood].filter(Boolean).join('，');
      const prefix = presence.present ? presence.name : `${presence.name}（不在场）`;
      return details ? `${prefix}：${details}` : prefix;
    })),
    fanficDetailBlock('关系变化', narrative.relationshipShifts.map((shift) => `第${shift.floor}楼：${shift.summary}`)),
    fanficDetailBlock('秘密与知情人', narrative.secrets.map((secret) => (
      `${secret.text}（知情：${secret.knownBy.length > 0 ? secret.knownBy.join('、') : '无人'}）`
    ))),
    fanficDetailBlock('未完成的约定', narrative.threads
      .filter((thread) => thread.kind === 'promise' && !thread.resolved)
      .map((thread) => thread.text)),
    fanficDetailBlock('待解决的伏笔', narrative.threads
      .filter((thread) => thread.kind === 'open' && !thread.resolved)
      .map((thread) => thread.text)),
    fanficDetailBlock('已兑现/已解决', narrative.threads
      .filter((thread) => thread.resolved)
      .map((thread) => thread.text)),
    fanficDetailBlock('与原著的分歧', narrative.divergences.map((divergence) => (
      `原著「${divergence.canonText}」→ 本作「${divergence.storyText}」`
    ))),
  ]) {
    if (block) view.append(block);
  }

  const diagnostics = fanfic.diagnostics;
  if (diagnostics) {
    const block = element('details', { className: 'phone-fanfic-block' });
    const summary = element('summary', { className: 'phone-fanfic-block-summary' });
    summary.append(
      element('strong', { text: '本轮召回诊断' }),
      element('small', { text: `${diagnostics.factCount} 条原著事实` }),
    );
    const body = element('div', { className: 'phone-fanfic-block-body' });
    body.append(
      fanficStatRow('在场人物', diagnostics.matchedCharacterNames.join('、')),
      fanficStatRow('未匹配到人物锁', diagnostics.unresolvedNames.join('、'), diagnostics.unresolvedNames.length === 0),
      fanficStatRow('歧义别名', diagnostics.ambiguousAliases.join('、'), diagnostics.ambiguousAliases.length === 0),
      fanficStatRow('注入事实/被裁剪', `${diagnostics.factCount} / ${diagnostics.droppedFactCount}`),
      fanficStatRow('原著片段', String(diagnostics.excerptCount)),
      fanficStatRow('原著部分字符', String(diagnostics.charCount)),
    );
    body.append(element('p', {
      className: 'phone-settings-hint',
      text: '诊断只展示给你，不会进入提示词。未匹配到人物锁说明该名字在原著资料里找不到唯一对应角色。',
    }));
    block.append(summary, body);
    view.append(block);
  }

  const actions = element('div', { className: 'phone-fanfic-actions' });
  actions.append(fanficActionButton(context, {
    label: '立即更新剧情状态',
    title: '读取新增正文并重新整理"仍然成立的事实"',
    className: 'phone-button phone-button-primary phone-button-compact',
    run: () => fanfic.trackNow(),
  }));
  actions.append(button('清空剧情状态', 'phone-button phone-button-danger-ghost phone-button-compact', async () => {
    const approved = await context.showConfirm({
      title: '清空本作剧情状态？',
      message: '会删除当前场景、人物状态、秘密、约定与原著分歧记录（原著库与人物锁不受影响）。',
      confirmLabel: '清空',
    });
    if (!approved) return;
    const result = await fanfic.clearNarrative();
    context.showNotice(result.message, result.ok ? 'success' : 'error');
    if (result.ok) context.navigate('fanfic');
  }));
  view.append(actions);
  return view;
}