import { evaluateInjectionGate } from '../conditions/generation.js';
import type { ConditionSnapshot, ConditionSource } from '../conditions/types.js';
import { SELF_PROFILE_ID } from '../domain/commands.js';
import { appLabelOf, type AppId, type PhoneState } from '../domain/model.js';
import { replaceImageMarkers } from '../generation/image-client.js';
import { shouldPreserveImageMarkers } from '../generation/image-marker.js';
import { getSillyTavernContext } from './sillytavern-bridge.js';

/** 注入正文时把生图标记替换为占位，避免提示词泄露进剧情；智绘姬模式保留原标记供其渲染按钮。 */
const sanitizeInjectedContent = (content: string): string => (
  shouldPreserveImageMarkers() ? content : replaceImageMarkers(content)
);

export interface BatchInjectionSummary {
  readonly text: string;
  readonly count: number;
}

/** 一个批次的互动正文（不含任何承载格式）：按应用与会话分组，分隔方式由各载体自行决定。 */
export interface BatchInteractionDigest {
  readonly sections: readonly string[];
  readonly count: number;
}

export const PHONE_INTERACTION_PROMPT_OPEN_TAG = '<手机互动消息>';
export const PHONE_INTERACTION_PROMPT_CLOSE_TAG = '</手机互动消息>';

/** 楼层折叠块内各分组之间只留空行。 */
const LOG_SECTION_GAP = '\n\n';

/** 预设槽位提示词的模块说明与分隔线：说明与各分组之间用 --- 断开，降低分组串读的概率。 */
const PRESET_SLOT_DIVIDER = '---';
const PRESET_SLOT_SECTION_GAP = `\n\n${PRESET_SLOT_DIVIDER}\n\n\n`;
const PRESET_SLOT_BRIEF: readonly string[] = [
  '手机互动模块',
  '下方内容为正文外{{user}}和角色手机互动历史，是已发生事实，可在正文中体现，如果空则无互动。',
];

export interface InjectionResult {
  readonly ok: boolean;
  readonly message: string;
}

const LOG_CSS_CLASS = 'narrative-phone-log';

export type BatchInjectionVisibility = 'visible' | 'hidden';

/** 互动正文的渲染与门控参数；载体差异只体现在各自的扩展字段上。 */
export interface InjectionRenderOptions {
  /** 个性化里的自定义应用名称；缺省回落到出厂名称。 */
  readonly appLabels?: Readonly<Record<string, string>>;
  readonly condition?: ConditionInjectionOptions;
}

export interface BatchInjectionOptions extends InjectionRenderOptions {
  /** 隐藏模式仍写入楼层，只是不在正文界面展开。 */
  readonly visibility?: BatchInjectionVisibility;
}

export interface ConditionInjectionOptions {
  readonly conditionSnapshot: ConditionSnapshot;
  /** 兼容宿主侧的未知扩展值；仅接受 AST、字符串或 { condition } 规则。 */
  readonly gate?: unknown;
}

function injectionAllowed(options?: ConditionInjectionOptions): boolean {
  if (!options) return true;
  const gate = options.gate;
  if (gate === undefined) return true;
  if (typeof gate === 'string' || isConditionNode(gate) || isConditionGate(gate)) {
    return evaluateInjectionGate(options.conditionSnapshot, gate);
  }
  return false;
}

function isConditionNode(value: unknown): value is Exclude<ConditionSource, string> {
  return typeof value === 'object' && value !== null && 'kind' in value;
}

function isConditionGate(value: unknown): value is { readonly condition: ConditionSource; readonly onError?: 'deny' | 'allow' } {
  return typeof value === 'object' && value !== null && 'condition' in value;
}

/**
 * 汇总一个生成批次中的全部互动（用户发出的消息/动态 + 角色回复/动态/互动），
 * 按应用与会话分组，输出与承载格式无关的互动正文。
 */
export function buildBatchInteractionDigest(
  state: PhoneState,
  batchId: string,
  appLabels: Readonly<Record<string, string>> = {},
): BatchInteractionDigest | null {
  const outboxItems = Object.values(state.outbox).filter((item) => item.batchId === batchId);
  const outgoingMessageIds = new Set(
    outboxItems.filter((item) => item.entityType === 'message').map((item) => item.entityId),
  );
  const userPostIds = new Set(
    outboxItems.filter((item) => item.entityType === 'post').map((item) => item.entityId),
  );
  const actionPrefix = `action:${batchId}:`;

  const messages = Object.values(state.messages)
    .filter((message) => message.batchId === batchId || outgoingMessageIds.has(message.id))
    .sort((left, right) => left.createdAt - right.createdAt);
  const posts = Object.values(state.posts)
    .filter((post) => userPostIds.has(post.id) || post.actionId?.startsWith(actionPrefix))
    .sort((left, right) => left.createdAt - right.createdAt);
  const interactions = Object.values(state.interactions)
    .filter((interaction) => interaction.actionId?.startsWith(actionPrefix))
    .sort((left, right) => left.createdAt - right.createdAt);

  const sections: string[] = [];
  let count = 0;
  const nameOf = (profileId: string): string => state.profiles[profileId]?.displayName
    ?? (profileId === SELF_PROFILE_ID ? '用户' : '未知');

  // 会话消息：按会话独立分组。
  const byConversation = new Map<string, typeof messages>();
  for (const message of messages) {
    const list = byConversation.get(message.conversationId) ?? [];
    byConversation.set(message.conversationId, [...list, message]);
  }
  for (const [conversationId, conversationMessages] of byConversation) {
    const conversation = state.conversations[conversationId];
    if (!conversation || conversationMessages.length === 0) continue;
    const lines = conversationMessages.map(
      (message) => `[${formatInjectionTime(message.createdAt)}] ${nameOf(message.profileId)}：${sanitizeInjectedContent(message.content)}`,
    );
    count += lines.length;
    sections.push(`【${appLabelOf(conversation.appId, appLabels)} · ${conversation.title}】\n${lines.join('\n')}`);
  }

  // 动态与互动：按应用独立分组。
  const appIds: readonly AppId[] = ['wechat', 'forum', 'anonymous', 'twitter'];
  for (const appId of appIds) {
    const lines: string[] = [];
    for (const post of posts.filter((item) => item.appId === appId)) {
      const verb = post.kind.includes('reply') ? '回复动态' : post.kind.includes('repost') ? '转发动态' : '发布动态';
      lines.push(`[${formatInjectionTime(post.createdAt)}] ${nameOf(post.profileId)} ${verb}：${sanitizeInjectedContent(post.content)}`);
    }
    for (const interaction of interactions.filter((item) => item.appId === appId)) {
      const target = state.posts[interaction.targetId];
      const verb = interaction.type === 'like' ? '点赞' : '评论';
      const detail = interaction.type === 'like'
        ? `（${truncate(target?.content ?? '', 24)}）`
        : `：${interaction.content ?? ''}`;
      lines.push(`[${formatInjectionTime(interaction.createdAt)}] ${nameOf(interaction.actorProfileId)} ${verb}${detail}`);
    }
    if (lines.length === 0) continue;
    count += lines.length;
    sections.push(`【${appLabelOf(appId, appLabels)} · 动态】\n${lines.join('\n')}`);
  }

  if (count === 0 || sections.length === 0) return null;
  return { sections, count };
}

/** 楼层载体：把互动正文包成可折叠的日志块，写入 AI/User 楼层底部。 */
export function buildBatchInjection(
  state: PhoneState,
  batchId: string,
  options: BatchInjectionOptions = {},
): BatchInjectionSummary | null {
  if (!injectionAllowed(options.condition)) return null;
  const digest = buildBatchInteractionDigest(state, batchId, options.appLabels);
  if (!digest) return null;
  const hiddenAttribute = options.visibility === 'hidden' ? ' hidden' : '';
  const text = [
    `<details class="${LOG_CSS_CLASS}" data-batch="${batchId}"${hiddenAttribute}>`,
    `<summary>📱 手机互动记录（${digest.count} 条）</summary>`,
    '',
    digest.sections.join(LOG_SECTION_GAP),
    '',
    '</details>',
  ].join('\n');
  return { text, count: digest.count };
}

/** 预设槽位载体：把互动正文包成带模块说明的「手机互动消息」提示词。 */
export function buildPresetSlotInjection(
  state: PhoneState,
  batchId: string,
  options: InjectionRenderOptions = {},
): BatchInjectionSummary | null {
  if (!injectionAllowed(options.condition)) return null;
  const digest = buildBatchInteractionDigest(state, batchId, options.appLabels);
  if (!digest) return null;
  return { text: formatPresetSlotInjection(digest.sections), count: digest.count };
}

export function formatPresetSlotInjection(sections: readonly string[]): string {
  return [
    PHONE_INTERACTION_PROMPT_OPEN_TAG,
    '',
    ...PRESET_SLOT_BRIEF,
    '',
    PRESET_SLOT_DIVIDER,
    '',
    `内容：${sections.join(PRESET_SLOT_SECTION_GAP)}`,
    PHONE_INTERACTION_PROMPT_CLOSE_TAG,
  ].join('\n');
}

export type InjectionAnchor = 'latestAi' | 'currentUser';

/**
 * 把互动记录写入指定锚点楼层。
 * latestAi 保持旧模式语义；currentUser 用当前聊天最后一条 User 楼层。
 */
export async function injectIntoLatestAiMessage(
  injection: BatchInjectionSummary,
  batchId: string,
  anchor: InjectionAnchor = 'latestAi',
  conditionOptions?: ConditionInjectionOptions,
): Promise<InjectionResult> {
  if (!injectionAllowed(conditionOptions)) {
    return { ok: false, message: '本轮互动未通过条件门控，未注入正文。' };
  }
  const context = getSillyTavernContext();
  const chat = Array.isArray(context.chat) ? context.chat : [];
  let targetIndex = -1;
  for (let index = chat.length - 1; index >= 0; index -= 1) {
    const message = chat[index] as Record<string, unknown> | undefined;
    if (!message) continue;
    if (anchor === 'currentUser') {
      if (message.is_user === true) {
        targetIndex = index;
        break;
      }
      continue;
    }
    if (message.is_user === true || message.is_system === true) continue;
    targetIndex = index;
    break;
  }
  if (targetIndex < 0) {
    return {
      ok: false,
      message: anchor === 'currentUser' ? '当前聊天没有可注入的 User 楼层。' : '当前聊天没有可注入的 AI 楼层。',
    };
  }
  const message = chat[targetIndex] as Record<string, unknown>;
  const current = String(message.mes ?? '');
  const withoutOldBlock = current
    .replace(buildBlockPattern(batchId), '')
    .replace(/\n{3,}$/g, '\n');
  const next = `${withoutOldBlock.replace(/\s+$/, '')}\n\n${injection.text}`;

  const helper = getTavernHelperRecord();
  const setChatMessages = helper?.setChatMessages;
  if (typeof setChatMessages === 'function') {
    try {
      await Promise.resolve((setChatMessages as (
        updates: readonly Record<string, unknown>[],
        options?: Record<string, unknown>,
      ) => unknown).call(helper, [{ message_id: targetIndex, message: next }], { refresh: 'affected' }));
      return { ok: true, message: `已把 ${injection.count} 条互动注入第 ${targetIndex} 楼。` };
    } catch {
      // 降级为直接修改。
    }
  }

  message.mes = next;
  const contextRecord = context as unknown as Record<string, unknown>;
  const save = contextRecord.saveChatDebounced ?? contextRecord.saveChat;
  if (typeof save === 'function') (save as () => void).call(context);
  return { ok: true, message: `已把 ${injection.count} 条互动写入第 ${targetIndex} 楼（刷新聊天后可见）。` };
}

/** 从正文中删除某个批次注入的互动记录折叠块（撤销本轮内容时使用）。 */
export async function removeInjectedBatchLog(batchId: string): Promise<InjectionResult> {
  const context = getSillyTavernContext();
  const chat = Array.isArray(context.chat) ? context.chat : [];
  const pattern = buildBlockPattern(batchId);
  const updates: { readonly message_id: number; readonly message: string }[] = [];

  for (let index = 0; index < chat.length; index += 1) {
    const message = chat[index] as Record<string, unknown> | undefined;
    if (!message) continue;
    const current = String(message.mes ?? '');
    pattern.lastIndex = 0;
    if (!pattern.test(current)) continue;
    pattern.lastIndex = 0;
    const next = current.replace(pattern, '').replace(/\s+$/, '');
    updates.push({ message_id: index, message: next });
  }
  if (updates.length === 0) {
    return { ok: true, message: '正文中没有本轮的互动记录。' };
  }

  const helper = getTavernHelperRecord();
  const setChatMessages = helper?.setChatMessages;
  if (typeof setChatMessages === 'function') {
    try {
      await Promise.resolve((setChatMessages as (
        items: readonly Record<string, unknown>[],
        options?: Record<string, unknown>,
      ) => unknown).call(helper, updates, { refresh: 'affected' }));
      return { ok: true, message: '已删除正文中的互动记录。' };
    } catch {
      // 降级为直接修改。
    }
  }
  for (const update of updates) {
    const message = chat[update.message_id] as Record<string, unknown> | undefined;
    if (message) message.mes = update.message;
  }
  const contextRecord = context as unknown as Record<string, unknown>;
  const save = contextRecord.saveChatDebounced ?? contextRecord.saveChat;
  if (typeof save === 'function') (save as () => void).call(context);
  return { ok: true, message: '已删除正文中的互动记录（刷新聊天后可见）。' };
}

function buildBlockPattern(batchId: string): RegExp {
  const escaped = batchId.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(
    `\\n{0,2}<details class="${LOG_CSS_CLASS}" data-batch="${escaped}"(?: hidden)?>[\\s\\S]*?<\\/details>`,
    'g',
  );
}

function getTavernHelperRecord(): Record<string, unknown> | null {
  try {
    const parent = window.parent as unknown as Record<string, unknown> | undefined;
    const helper = parent?.TavernHelper ?? (window as unknown as Record<string, unknown>).TavernHelper;
    return helper && typeof helper === 'object' ? helper as Record<string, unknown> : null;
  } catch {
    return (window as unknown as { TavernHelper?: Record<string, unknown> }).TavernHelper ?? null;
  }
}

function truncate(text: string, limit: number): string {
  return text.length > limit ? `${text.slice(0, limit)}…` : text;
}

/** 剧情时间戳：MM-DD HH:MM。 */
function formatInjectionTime(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}
