import { hashText, isUsableColumnName } from './sheet-dsl.js';
import { validateSheetCondition } from './sheet-condition.js';
import type { SheetPolicy } from './sheet-dsl.js';
import type { MvuAsset, MvuMapping } from '../mvu/types.js';
import { normalizeMvuMapping } from '../mvu/mapping.js';
import { normalizeRuleSources } from '../mvu/rule-activation.js';
import { extractSqCardTemplate, normalizeSqCompatibility, sqBinding, sqFillGuide, sqRecord, type SqCompatibility, type SqTableBinding } from '../sq/template.js';
import { mvuCardIdentity } from '../mvu/card-identity.js';

/** 导入路径上的条件容错：语法错就丢掉条件并记进 issues，不因此跳过整张表。 */
function safeInjectCondition(value: unknown, sheetName: string, issues: string[]): string {
  const source = typeof value === 'string' ? value.trim().slice(0, 2_000) : '';
  if (!source) return '';
  const error = validateSheetCondition(source);
  if (!error) return source;
  issues.push(`${sheetName}：注入条件无法解析（${error}），已按无条件导入。`);
  return '';
}

/** 一张待导入的表：列名一律 ASCII（来自 DDL），中文标签走 `labels` 并渲染进行模板。 */
export interface SheetPresetEntry {
  readonly rowIds?: readonly number[];
  /** 来源模板中的稳定键；表改名后仍可定位原实例。 */
  readonly sourceKey?: string;
  readonly name: string;
  readonly purpose: string;
  readonly columns: readonly string[];
  readonly labels: readonly string[];
  readonly policy: SheetPolicy;
  readonly rowTemplate: string;
  readonly tokenBudget: number;
  readonly orderNo: number;
  /** 注入条件（IF 语法的表达式部分）；空串表示无条件。 */
  readonly injectCondition: string;
  /** 这张表的填表规则（MVU 更新规则转换后落在这里）；空串表示没有额外规则。 */
  readonly fillGuide: string;
  /** 预设自带的初始数据行，按 `columns` 顺序对齐。 */
  readonly rows: readonly (readonly string[])[];
}

export type SheetPresetFormat = 'narrative-phone' | 'sp-chat-sheets';

/**
 * 一份可整体启用的表格预设包。预设包是全局资产（跟随扩展设置），
 * 用户在数据中心里选择当前使用哪一份；被选中的那一份才会物化到各个聊天。
 */
export interface SheetPresetBundle {
  readonly sq?: SqCompatibility;
  readonly ruleSources?: readonly MvuAsset[];
  readonly sourceIdentity?: string;
  readonly id: string;
  readonly name: string;
  readonly sheets: readonly SheetPresetEntry[];
  /** MVU 转换产出的变量映射；只有从 MVU 卡转换来的预设包才有。 */
  readonly mvuMapping?: MvuMapping;
  /**
   * 转换来源的角色卡名。
   * 预设库是全局的，但 MVU 映射只对产出它的那张卡成立：换卡后必须凭这个字段
   * 拒绝接管数据桥，否则会把别的卡的表结构投影进当前聊天的 stat_data。
   */
  readonly sourceCard?: string;
  /** 跨表共享的填表规则（MVU 里那些没法归属到单张表的通用法则）。 */
  readonly sharedGuide?: string;
}


export interface SheetPresetImport {
  readonly sq?: SqCompatibility;
  readonly sourceIdentity?: string;
  readonly sourceCard?: string;
  readonly format: SheetPresetFormat;
  readonly sheets: readonly SheetPresetEntry[];
  /** 解析过程中的降级说明；不阻断导入，但必须让用户看到。 */
  readonly issues: readonly string[];
}

const PURPOSE_LIMIT = 160;

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

function text(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  return '';
}

/** 说明文字压成一句：模型只需要知道这张表存来干什么。 */
function condensePurpose(note: string, fallback: string): string {
  const firstLine = note.split(/\r?\n/).map((line) => line.trim()).find((line) => line && !line.startsWith('-')) ?? '';
  const condensed = firstLine.replace(/^【[^】]*】/, '').trim() || fallback;
  return condensed.length > PURPOSE_LIMIT ? `${condensed.slice(0, PURPOSE_LIMIT - 1)}…` : condensed;
}

/** 从 SP 的 DDL 里取出列名（跳过 `row_id`，它由我们自己的 rowid 承担）。 */
function parseDdlColumns(ddl: string): readonly string[] {
  const body = ddl.slice(ddl.indexOf('(') + 1);
  const columns: string[] = [];
  for (const line of body.split(/\r?\n/)) {
    const match = /^\s*([A-Za-z_][A-Za-z0-9_]*)\s+(TEXT|INTEGER|REAL|BLOB)\b/i.exec(line);
    const name = match?.[1];
    if (!name || name.toLowerCase() === 'row_id' || columns.includes(name)) continue;
    columns.push(name);
  }
  return columns;
}

/**
 * 把外部 DDL 的列名收敛成可直接用于未加引号 DDL 的形式。
 * SP 模板里存在 `action` 这类 SQLite 保留字列名，重命名即可；中文语义由标签承担，物理名只是载体。
 */
function normalizeColumnName(
  raw: string,
  taken: readonly string[],
  sheetName: string,
  issues: string[],
): string | null {
  const base = raw.trim();
  if (!base) return null;
  for (const candidate of [base, `${base}_col`, `col${taken.length + 1}`]) {
    if (!isUsableColumnName(candidate) || taken.includes(candidate)) continue;
    if (candidate !== base) {
      issues.push(`${sheetName}：列名「${base}」是 SQLite 保留字或与已有列冲突，已改用「${candidate}」。`);
    }
    return candidate;
  }
  return null;
}

/** 中文标签写进行模板，让召回文本自带列语义；列名本身保持 ASCII。 */
export function buildRowTemplate(columns: readonly string[], labels: readonly string[]): string {
  return columns
    .map((column, index) => `${labels[index]?.trim() || column}={{${column}}}`)
    .join('；');
}

function fallbackColumnNames(count: number): readonly string[] {
  return Array.from({ length: count }, (_, index) => `col${index + 1}`);
}

/** SP 的 `exportConfig.entryType`：常驻条目对应每轮注入，关键词条目对应按需召回。 */
function inferPolicy(exportConfig: unknown): SheetPolicy {
  if (isRecord(exportConfig) && exportConfig.enabled === false) return 'manual';
  return isRecord(exportConfig) && exportConfig.entryType === 'constant' ? 'always' : 'recall';
}

function parseSpSheet(
  key: string,
  raw: unknown,
  issues: string[],
  bindings: SqTableBinding[],
): SheetPresetEntry | null {
  if (!isRecord(raw)) return null;
  const name = text(raw.name).trim();
  if (!name) {
    issues.push(`${key}：缺少表名，已跳过。`);
    return null;
  }
  const source = isRecord(raw.sourceData) ? raw.sourceData : {};
  const grid = Array.isArray(raw.content) ? raw.content : [];
  const header = Array.isArray(grid[0]) ? grid[0].map(text) : [];
  // SP 的表头与 DDL 都以行号列开头，映射到我们的模型时一并去掉。
  const labels = header.slice(1);
  const ddlColumns = parseDdlColumns(text(source.ddl));
  const rawColumns = ddlColumns.length > 0 ? ddlColumns : fallbackColumnNames(labels.length);
  if (ddlColumns.length === 0) issues.push(`${name}：DDL 无法解析列名，已用 col1..colN 兜底。`);
  if (rawColumns.length === 0) {
    issues.push(`${name}：没有可导入的列，已跳过。`);
    return null;
  }
  if (labels.length > 0 && labels.length !== rawColumns.length) {
    issues.push(`${name}：表头 ${labels.length} 列与 DDL ${rawColumns.length} 列不一致，已为缺失的一侧补齐列名或标签。`);
  }

  const width = Math.max(rawColumns.length, labels.length);
  const columns: string[] = [];
  const usedLabels: string[] = [];
  const sourceIndexes: number[] = [];
  for (let index = 0; index < width; index += 1) {
    const column = normalizeColumnName(rawColumns[index] ?? `col${index + 1}`, columns, name, issues);
    if (!column) {
      issues.push(`${name}：第 ${index + 1} 列无法转成合法列名，已跳过该列。`);
      continue;
    }
    columns.push(column);
    usedLabels.push((labels[index] ?? '').trim() || column);
    sourceIndexes.push(index);
  }
  if (columns.length === 0) {
    issues.push(`${name}：没有可导入的列，已跳过。`);
    return null;
  }

  const policy = inferPolicy(raw.exportConfig);
  const orderNo = Number(raw.orderNo);
  const rowIds: number[] = [];
  const rows = grid.slice(1).flatMap((row): readonly (readonly string[])[] => {
    if (!Array.isArray(row)) return [];
    const values = row.slice(1).map(text);
    const mapped = sourceIndexes.map((index) => values[index] ?? '');
    const rawId = Number(row[0]);
    const id = Number.isSafeInteger(rawId) && rawId > 0 ? rawId : (Math.max(0, ...rowIds) + 1);
    if (rowIds.includes(id)) throw new Error(`${name}：存在重复的 row_id=${id}，请先修正来源数据。`);
    rowIds.push(id);
    return [mapped];
  });

  if (columns.length > 64) throw new Error(`${name}：共有 ${columns.length} 列，超过当前表结构支持的 64 列。`);
  bindings.push(sqBinding(key, raw, columns, usedLabels, sourceIndexes.map((index) => rawColumns[index] ?? `col${index + 1}`)));

  return {
    sourceKey: key,
    rowIds,
    name,
    purpose: condensePurpose(text(source.note), `${name}（自 SP 表格预设导入）`),
    columns,
    labels: usedLabels,
    policy,
    rowTemplate: buildRowTemplate(columns, usedLabels),
    tokenBudget: policy === 'always' ? 512 : 256,
    orderNo: Number.isFinite(orderNo) ? Math.trunc(orderNo) : 0,
    injectCondition: '',
    fillGuide: sqFillGuide(source),
    rows,
  };
}

function parsePhoneSheet(raw: unknown, index: number, issues: string[]): SheetPresetEntry | null {
  if (!isRecord(raw)) return null;
  const name = text(raw.name).trim();
  if (!name) {
    issues.push(`第 ${index + 1} 张表缺少表名，已跳过。`);
    return null;
  }
  const rawColumns = Array.isArray(raw.columns) ? raw.columns : [];
  const columns: string[] = [];
  const labels: string[] = [];
  for (const column of rawColumns) {
    const columnName = isRecord(column) ? text(column.name).trim() : text(column).trim();
    if (!isUsableColumnName(columnName) || columns.includes(columnName)) {
      if (columnName) issues.push(`${name}：列名「${columnName}」非法或重复，已跳过该列。`);
      continue;
    }
    columns.push(columnName);
    labels.push(isRecord(column) ? text(column.label).trim() || columnName : columnName);
  }
  if (columns.length === 0) {
    issues.push(`${name}：没有合法列，已跳过。`);
    return null;
  }
  const policy: SheetPolicy = raw.policy === 'always' || raw.policy === 'manual' ? raw.policy : 'recall';
  const budget = Number(raw.tokenBudget);
  const rows = (Array.isArray(raw.rows) ? raw.rows : []).flatMap((row): readonly (readonly string[])[] => {
    if (Array.isArray(row)) return [columns.map((_, position) => text(row[position]))];
    if (isRecord(row)) return [columns.map((column) => text(row[column]))];
    return [];
  });
  return {
    name,
    purpose: condensePurpose(text(raw.purpose), name),
    columns,
    labels,
    policy,
    rowTemplate: text(raw.rowTemplate).trim() || buildRowTemplate(columns, labels),
    tokenBudget: Number.isFinite(budget) ? Math.min(8_192, Math.max(16, Math.trunc(budget))) : 256,
    orderNo: index,
    injectCondition: safeInjectCondition(raw.injectCondition, name, issues),
    fillGuide: text(raw.fillGuide).trim(),
    rows: rows.filter((row) => row.some((value) => value.trim())),
  };
}

/**
 * 解析表格预设。支持两种来源：
 * - 本扩展自有格式：`{ format: 'narrative-phone-sheets', sheets: [...] }`
 * - SP·数据库（TavernDB）导出的 `chatSheets` 模板：`{ mate: { type: 'chatSheets' }, sheet_xxx: {...} }`
 * 解析是纯函数，不触碰数据库；无法识别的结构直接抛错，降级点写进 `issues`。
 */
export function parseSheetPreset(raw: unknown): SheetPresetImport {
  if (!isRecord(raw)) throw new Error('表格预设必须是 JSON 对象。');
  const issues: string[] = [];
  const embedded = extractSqCardTemplate(raw);
  if (embedded) return { ...parseSheetPreset(embedded.template), sourceCard: embedded.cardName, sourceIdentity: mvuCardIdentity(raw) };

  const mate = isRecord(raw.mate) ? raw.mate : null;
  if (mate?.type === 'chatSheets' || Object.keys(raw).some((key) => key.startsWith('sheet_'))) {
    const bindings: SqTableBinding[] = [];
    const sheets = Object.entries(raw)
      .filter(([key]) => key.startsWith('sheet_'))
      .flatMap(([key, value]) => {
        const sheet = parseSpSheet(key, value, issues, bindings);
        return sheet ? [sheet] : [];
      })
      .sort((left, right) => left.orderNo - right.orderNo || left.name.localeCompare(right.name, 'zh-CN'));
    if (sheets.length === 0) throw new Error('SP 表格预设里没有可导入的表。');
    return { format: 'sp-chat-sheets', sheets, issues, sq: { version: 1, mate: sqRecord(raw.mate), tables: bindings } };
  }

  const rawSheets = Array.isArray(raw.sheets) ? raw.sheets : null;
  if (!rawSheets) throw new Error('无法识别的表格预设格式：缺少 sheets 或 SP 的 sheet_* 结构。');
  const sheets = rawSheets.flatMap((value, index) => {
    const sheet = parsePhoneSheet(value, index, issues);
    return sheet ? [sheet] : [];
  });
  if (sheets.length === 0) throw new Error('表格预设里没有可导入的表。');
  return { format: 'narrative-phone', sheets, issues };
}

/** 预设物化出来的表 id 前缀；界面手工建的表用 `sheet-` 前缀，两者据此区分。 */
export const PRESET_SHEET_ID_PREFIX = 'preset-';

/** 预设条目的稳定 id：同一份预设重复导入会命中同一张表而不是不断新建。 */
export function presetSheetId(scopeId: string, entry: Pick<SheetPresetEntry, 'name' | 'sourceKey'>, presetId?: string): string {
  return `${PRESET_SHEET_ID_PREFIX}${hashText(presetId === undefined
    ? `${scopeId}|${entry.name}` : JSON.stringify([scopeId, presetId, entry.sourceKey || entry.name]))}`;
}

/**
 * 规范化预设自带的初始行。
 *
 * `keep` 是保留下来的列在原始列表里的下标：列被过滤（列名非法或重名）时，
 * 行数据必须按原下标取值，否则标签与单元格会整排错位。
 *
 * 空行只从第二行起过滤：单行宽表的初值可能整行都是空串（例如 `道具.待使用: ''`），
 * 那一行是变量的落脚点，丢掉它整张表就没有行，投影与写入都会因为「定位不到行」而
 * 静默失联；而手写预设里多余的空白行仍然会被清掉。
 */
function normalizeRows(value: unknown, keep: readonly number[], keepEmpty = false): readonly (readonly string[])[] {
  if (!Array.isArray(value)) return [];
  return value
    .flatMap((row, index): readonly (readonly string[])[] => {
      if (!Array.isArray(row)) return [];
      const values = keep.map((column) => text(row[column]));
      return keepEmpty || index === 0 || values.some((cell) => cell.trim()) ? [values] : [];
    });
}

/** 挑出列名合法且不重名的列；结构容量由建表阶段完整校验，保存时保留原定义。 */
function keptColumnIndexes(rawColumns: readonly string[]): readonly number[] {
  const keep: number[] = [];
  const seen = new Set<string>();
  for (const [index, column] of rawColumns.entries()) {
    if (!isUsableColumnName(column) || seen.has(column)) continue;
    seen.add(column);
    keep.push(index);
  }
  return keep;
}

/**
 * 规范化持久化的表格预设。预设是全局资产（跟随扩展设置），每个聊天首次使用时再物化成自己的表，
 * 因此这里只校验结构，不涉及任何 scope。
 *
 * 默认保留所有表；自动截断会造成转换映射仍在、对应表定义却已经丢失。
 */
export function normalizeSheetPresetEntries(value: unknown, limit = Number.POSITIVE_INFINITY): readonly SheetPresetEntry[] {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  const entries: SheetPresetEntry[] = [];
  for (const item of value) {
    if (!isRecord(item)) continue;
    const name = text(item.name).trim();
    const rawColumns = Array.isArray(item.columns) ? item.columns.map(text) : [];
    const keep = keptColumnIndexes(rawColumns);
    const columns = keep.map((index) => rawColumns[index] ?? '');
    if (!name || columns.length === 0 || seen.has(name)) continue;
    seen.add(name);
    const rawLabels = Array.isArray(item.labels) ? item.labels.map(text) : [];
    // 标签按原始下标取：列被过滤时不能顺位平移，否则整排标签对错列。
    const labels = keep.map((index, position) => rawLabels[index]?.trim() || columns[position] || '');
    const policy: SheetPolicy = item.policy === 'always' || item.policy === 'manual' ? item.policy : 'recall';
    const budget = Number(item.tokenBudget);
    const order = Number(item.orderNo);
    const condition = text(item.injectCondition).trim().slice(0, 2_000);
    entries.push({
      ...(Array.isArray(item.rowIds) && item.rowIds.length === (Array.isArray(item.rows) ? item.rows.length : 0)
        && item.rowIds.every((id) => Number.isSafeInteger(id) && id > 0) ? { rowIds: item.rowIds as number[] } : {}),
      ...(typeof item.sourceKey === 'string' && item.sourceKey ? { sourceKey: item.sourceKey } : {}),
      name,
      purpose: text(item.purpose).trim().slice(0, PURPOSE_LIMIT) || name,
      columns,
      labels,
      policy,
      rowTemplate: text(item.rowTemplate).trim() || buildRowTemplate(columns, labels),
      tokenBudget: Number.isFinite(budget) ? Math.min(8_192, Math.max(16, Math.trunc(budget))) : 256,
      orderNo: Number.isFinite(order) ? Math.trunc(order) : entries.length,
      // 存进设置的条件必须能解析，否则物化建表时会整张表失败。
      injectCondition: validateSheetCondition(condition) === null ? condition : '',
      fillGuide: text(item.fillGuide).trim(),
      rows: normalizeRows(item.rows, keep, Array.isArray(item.rowIds)),
    });
    if (entries.length >= limit) break;
  }
  return entries;
}

/** 合并预设：同名以新导入的为准，其余保持原有顺序。 */
export function mergeSheetPresets(
  current: readonly SheetPresetEntry[],
  incoming: readonly SheetPresetEntry[],
): readonly SheetPresetEntry[] {
  const merged = new Map(current.map((entry) => [entry.name, entry]));
  for (const entry of incoming) merged.set(entry.name, entry);
  return normalizeSheetPresetEntries([...merged.values()]);
}

/** 预设包 id 按名字派生：重复导入同名预设命中同一份，不会越导越多。 */
export function presetBundleId(name: string): string {
  return `bundle-${hashText(name.trim().toLowerCase())}`;
}

export function normalizeSheetPresetBundles(value: unknown, limit = Number.POSITIVE_INFINITY): readonly SheetPresetBundle[] {
  if (!Array.isArray(value)) return [];
  const bundles: SheetPresetBundle[] = [];
  const seen = new Set<string>();
  for (const item of value) {
    if (!isRecord(item)) continue;
    const name = text(item.name).trim();
    const sheets = normalizeSheetPresetEntries(item.sheets);
    if (!name || sheets.length === 0) continue;
    const id = text(item.id).trim() || presetBundleId(name);
    if (seen.has(id)) continue;
    seen.add(id);
    const mvuMapping = normalizeMvuMapping(item.mvuMapping);
    const sharedGuide = text(item.sharedGuide).trim();
    const sourceCard = text(item.sourceCard).trim();
    const sq = normalizeSqCompatibility(item.sq);
    bundles.push({
      ...(sq ? { sq } : {}),
      ...(Array.isArray(item.ruleSources) ? { ruleSources: normalizeRuleSources(item.ruleSources) } : {}),
      ...(typeof item.sourceIdentity === 'string' ? { sourceIdentity: item.sourceIdentity } : {}),
      id,
      name,
      sheets,
      ...(mvuMapping ? { mvuMapping } : {}),
      ...(sharedGuide ? { sharedGuide } : {}),
      ...(sourceCard ? { sourceCard } : {}),
    });
    if (bundles.length >= limit) break;
  }
  return bundles;
}

export function selectPresetBundle(
  bundles: readonly SheetPresetBundle[],
  id: string,
): SheetPresetBundle | null {
  return bundles.find((bundle) => bundle.id === id) ?? null;
}

/**
 * 写入一份完整预设定义；同名更新替换旧定义，聊天数据由物化器保留和迁移。
 */
export function upsertPresetBundle(
  library: readonly SheetPresetBundle[],
  name: string,
  sheets: readonly SheetPresetEntry[],
  extra: {
    readonly sq?: SqCompatibility;
    readonly ruleSources?: readonly MvuAsset[];
    readonly sourceIdentity?: string;
    readonly mvuMapping?: MvuMapping;
    readonly sharedGuide?: string;
    readonly sourceCard?: string;
  } = {},
): { readonly library: readonly SheetPresetBundle[]; readonly bundle: SheetPresetBundle } {
  const trimmed = name.trim() || '未命名预设';
  const id = presetBundleId(trimmed);
  const existing = selectPresetBundle(library, id);
  const mvuMapping = extra.mvuMapping;
  const sharedGuide = (extra.sharedGuide ?? existing?.sharedGuide ?? '').trim();
  const sourceCard = (extra.sourceCard ?? existing?.sourceCard ?? '').trim();
  const bundle: SheetPresetBundle = {
    ...(extra.sq ? { sq: extra.sq } : {}),
    ...(extra.ruleSources ? { ruleSources: extra.ruleSources } : {}),
    ...(extra.sourceIdentity ? { sourceIdentity: extra.sourceIdentity } : {}),
    id,
    name: trimmed,
    sheets: normalizeSheetPresetEntries(sheets),
    ...(mvuMapping ? { mvuMapping } : {}),
    ...(sharedGuide ? { sharedGuide } : {}),
    ...(sourceCard ? { sourceCard } : {}),
  };
  const next = existing
    ? library.map((item) => (item.id === id ? bundle : item))
    : [...library, bundle];
  return { library: next, bundle };
}

export function removePresetBundle(
  library: readonly SheetPresetBundle[],
  id: string,
): readonly SheetPresetBundle[] {
  return library.filter((bundle) => bundle.id !== id);
}
