import type { PhoneAppDefinition } from '../app-types.js';
import { APP_ID_LABELS } from '../../domain/model.js';
import { renderForumDetail } from './detail-view.js';
import {
  forumBackRoute,
  renderForumBoard,
  renderForumHome,
  renderForumHot,
  renderForumMe,
} from './list-view.js';
import { forumView } from './view-state.js';

/**
 * 论坛应用：首页（置顶/热门/最新）、板块、热榜、我的四个列表页 + 主题详情。
 * 列表与详情共用 `buildForumIndex` 的一次性投影，界面层只负责渲染。
 */
export function createForumApp(): PhoneAppDefinition {
  return {
    id: 'forum',
    label: APP_ID_LABELS.forum,
    icon: '论',
    navigation: [
      { route: 'forum', label: '首页', icon: 'home' },
      { route: 'forumBoard', label: '板块', icon: 'forum' },
      { route: 'forumHot', label: '热榜', icon: 'summary' },
      { route: 'forumMe', label: '我的', icon: 'me' },
    ],
    backRoute: forumBackRoute,
    render(context) {
      if (context.route === 'forumPost') {
        const thread = forumView.detailPostId ? context.state.posts[forumView.detailPostId] : undefined;
        if (thread?.appId === 'forum' && thread.kind === 'forum-thread') return renderForumDetail(context, thread);
        return renderForumHome(context);
      }
      if (context.route === 'forumBoard') return renderForumBoard(context);
      if (context.route === 'forumHot') return renderForumHot(context);
      if (context.route === 'forumMe') return renderForumMe(context);
      return renderForumHome(context);
    },
  };
}