import {
  INDEXEDDB_DATABASE_NAME,
  INDEXEDDB_STATE_STORE,
  IndexedDbStorage,
} from './indexeddb-storage.js';
import { phoneStatesEqual } from './state-equality.js';
import { phoneLogger } from '../core/logger.js';
import { SELF_PROFILE_ID } from '../domain/commands.js';
import type { PhoneEvent } from '../domain/events.js';
import type { PhoneState } from '../domain/model.js';
import { TavernStorage, type TavernStorageContextProvider } from './tavern-storage.js';
import type {
  StorageBackend,
  StorageBackendKind,
  StorageListener,
  UnsubscribeStorage,
} from './storage-port.js';

/** 手机状态以酒馆聊天元数据为事实源，IndexedDB 仅作恢复缓存。 */
export type StoragePreference = 'auto' | 'tavern' | 'indexeddb';
export type StorageResolution =
  | 'tavern'
  | 'migrated-local'
  | 'indexeddb-fallback'
  | 'migration-conflict'
  | 'user-selection';

export interface StorageMigrationDiagnostic {
  readonly state: 'not-needed' | 'migrated' | 'conflict' | 'fallback';
  readonly reason: string;
}

export interface AdaptiveStorageStatus {
  readonly scopeId: string;
  readonly preference: StoragePreference;
  readonly selectedKind: StorageBackendKind | null;
  readonly resolution: StorageResolution | null;
  readonly migration: StorageMigrationDiagnostic;
  readonly tavernAvailable: boolean;
  readonly tavernReason: string;
  readonly indexedDbAvailable: boolean;
  readonly indexedDbDatabaseName: string;
  readonly indexedDbStoreName: string;
}

interface ScopeDiagnostic {
  readonly resolution: StorageResolution;
  readonly migration: StorageMigrationDiagnostic;
}

const NO_MIGRATION: StorageMigrationDiagnostic = Object.freeze({
  state: 'not-needed',
  reason: '当前事实源不需要迁移。',
});

/**
 * 存储架构（v3）：
 *
 * 1. TavernStorage：聊天元数据是业务状态的持久事实源，跟随酒馆服务端聊天文件。
 * 2. IndexedDB：本机恢复缓存及酒馆暂不可用时的临时降级，不参与覆盖已有酒馆数据。
 */
export class AdaptiveStorage {
  readonly #tavern: StorageBackend;
  readonly #indexedDb: StorageBackend;
  readonly #selected = new Map<string, StorageBackendKind>();
  readonly #selecting = new Map<string, Promise<StorageBackend>>();
  readonly #diagnostics = new Map<string, ScopeDiagnostic>();
  readonly #cachePending = new Map<string, PhoneState>();
  readonly #cacheInFlight = new Map<string, Promise<void>>();
  readonly #tavernPending = new Map<string, PhoneState>();
  readonly #tavernInFlight = new Map<string, Promise<void>>();
  #tavernAvailable = false;
  #cacheFailureLogged = false;
  #preference: StoragePreference;

  constructor(options: {
    readonly tavern?: StorageBackend | TavernStorageContextProvider;
    readonly indexedDb?: StorageBackend;
    readonly preference?: StoragePreference;
  } = {}) {
    this.#tavern = typeof options.tavern === 'function'
      ? new TavernStorage(options.tavern)
      : options.tavern ?? new TavernStorage();
    this.#indexedDb = options.indexedDb ?? new IndexedDbStorage();
    this.#preference = options.preference ?? 'auto';
  }

  async isAvailable(): Promise<boolean> {
    const [tavern, indexedDb] = await Promise.all([
      this.#probeTavern(),
      this.#indexedDb.isAvailable().catch(() => false),
    ]);
    return tavern.available || indexedDb;
  }

  async refreshAvailability(scopeId: string): Promise<void> {
    this.#selected.delete(scopeId);
    this.#diagnostics.delete(scopeId);
    try {
      await this.backendFor(scopeId);
    } catch (error) {
      this.#diagnostics.set(scopeId, {
        resolution: 'indexeddb-fallback',
        migration: {
          state: 'fallback',
          reason: error instanceof Error ? error.message : String(error),
        },
      });
    }
  }

  async backendFor(scopeId: string): Promise<StorageBackend> {
    const selectedKind = this.#selected.get(scopeId);
    if (selectedKind) return this.#backend(selectedKind);

    const pending = this.#selecting.get(scopeId);
    if (pending) return pending;

    const selection = this.#selectBackend(scopeId);
    this.#selecting.set(scopeId, selection);
    try {
      return await selection;
    } finally {
      if (this.#selecting.get(scopeId) === selection) this.#selecting.delete(scopeId);
    }
  }

  async load(scopeId: string): Promise<PhoneState | null> {
    return (await this.backendFor(scopeId)).load(scopeId);
  }

  async commit(
    scopeId: string,
    expectedRevision: number,
    events: readonly PhoneEvent[],
  ): Promise<PhoneState> {
    const backend = await this.backendFor(scopeId);
    const next = await backend.commit(scopeId, expectedRevision, events);
    if (backend.kind === 'tavern') {
      this.#cacheState(scopeId, next);
    } else if (backend.kind === 'indexeddb') {
      this.#pushTavern(scopeId, next);
    }
    return next;
  }

  async replace(scopeId: string, state: PhoneState): Promise<void> {
    const backend = await this.backendFor(scopeId);
    await backend.replace(scopeId, state);
    if (backend.kind === 'tavern') {
      this.#cacheState(scopeId, state);
    } else if (backend.kind === 'indexeddb') {
      this.#pushTavern(scopeId, state);
    }
  }

  async listScopes(): Promise<readonly string[]> {
    const scopes = new Set<string>();
    for (const backend of [this.#tavern, this.#indexedDb]) {
      try {
        for (const scope of await backend.listScopes()) scopes.add(scope);
      } catch {
        // 任选持久后端不可用时继续读取其他后端。
      }
    }
    return [...scopes].sort();
  }

  async deleteScope(scopeId: string): Promise<void> {
    const backend = await this.backendFor(scopeId);
    await backend.deleteScope(scopeId);
    if (backend.kind === 'tavern') {
      await this.#indexedDb.deleteScope(scopeId).catch(() => undefined);
    }
    this.#selected.delete(scopeId);
    this.#diagnostics.delete(scopeId);
  }

  subscribe(scopeId: string, listener: StorageListener): UnsubscribeStorage {
    const subscriptions: UnsubscribeStorage[] = [];
    for (const backend of [this.#tavern, this.#indexedDb]) {
      try {
        subscriptions.push(
          backend.subscribe?.(scopeId, (state) => {
            if (this.#selected.get(scopeId) === backend.kind) listener(state);
          }) ?? (() => undefined),
        );
      } catch {
        // 辅助后端监听是 best effort。
      }
    }
    return () => subscriptions.forEach((unsubscribe) => unsubscribe());
  }

  /** 等待恢复缓存队列与酒馆延迟写盘全部完成。 */
  async flush(scopeId: string): Promise<void> {
    const pending = [
      this.#tavern.flush?.(),
      this.#cacheInFlight.get(scopeId),
      this.#tavernInFlight.get(scopeId),
    ].filter(
      (promise): promise is Promise<void> => Boolean(promise),
    );
    if (pending.length > 0) await Promise.all(pending);
  }

  setPreference(preference: StoragePreference): void {
    if (this.#selected.size > 0 && preference !== this.#preference) {
      throw new Error('存储后端已打开；修改首选项需要重新加载扩展。');
    }
    this.#preference = preference;
  }

  selectedKind(scopeId: string): StorageBackendKind | null {
    return this.#selected.get(scopeId) ?? null;
  }

  async statusFor(scopeId: string): Promise<AdaptiveStorageStatus> {
    const [tavernProbe, indexedDbAvailable] = await Promise.all([
      this.#probeTavern(),
      this.#indexedDb.isAvailable().catch(() => false),
    ]);
    const diagnostic = this.#diagnostics.get(scopeId);
    return {
      scopeId,
      preference: this.#preference,
      selectedKind: this.selectedKind(scopeId),
      resolution: diagnostic?.resolution ?? null,
      migration: diagnostic?.migration ?? NO_MIGRATION,
      tavernAvailable: tavernProbe.available,
      tavernReason: tavernProbe.reason,
      indexedDbAvailable,
      indexedDbDatabaseName: INDEXEDDB_DATABASE_NAME,
      indexedDbStoreName: INDEXEDDB_STATE_STORE,
    };
  }

  dispose(): void {
    this.#tavern.dispose();
    this.#indexedDb.dispose();
    this.#selected.clear();
    this.#selecting.clear();
    this.#diagnostics.clear();
  }

  async #selectBackend(scopeId: string): Promise<StorageBackend> {
    const [tavernProbe, indexedDbAvailable] = await Promise.all([
      this.#probeTavern(),
      this.#indexedDb.isAvailable().catch(() => false),
    ]);
    this.#tavernAvailable = tavernProbe.available;
    if (scopeId.startsWith('session:')) {
      if (indexedDbAvailable) {
        return this.#select(scopeId, 'indexeddb', 'indexeddb-fallback', {
          state: 'fallback',
          reason: '当前没有打开的酒馆聊天，临时使用浏览器本地缓存。',
        });
      }
      throw new Error('当前没有打开聊天，且浏览器本地缓存不可用。');
    }

    if (tavernProbe.available) {
      const migration = await this.#reconcileTavernAndLocal(scopeId);
      if (migration.backend === 'tavern') {
        return this.#select(scopeId, 'tavern', migration.resolution, migration.diagnostic);
      }
      return this.#select(scopeId, 'indexeddb', 'indexeddb-fallback', migration.diagnostic);
    }

    if (indexedDbAvailable) {
      return this.#select(scopeId, 'indexeddb', 'indexeddb-fallback', {
        state: 'fallback',
        reason: `酒馆聊天持久化暂不可用，临时使用浏览器本地缓存：${tavernProbe.reason}`,
      });
    }

    throw new Error(`酒馆聊天持久化和浏览器本地缓存均不可用：${tavernProbe.reason}`);
  }

  async #reconcileTavernAndLocal(scopeId: string): Promise<{
    readonly backend: 'tavern' | 'indexeddb';
    readonly resolution: StorageResolution;
    readonly diagnostic: StorageMigrationDiagnostic;
  }> {
    const [tavernState, localState] = await Promise.all([
      this.#tavern.load(scopeId).catch((error: unknown) => {
        phoneLogger.warn('读取酒馆聊天状态失败', error);
        return null;
      }),
      this.#indexedDb.load(scopeId).catch(() => null),
    ]);

    if (!tavernState && !localState) {
      return {
        backend: 'tavern',
        resolution: 'tavern',
        diagnostic: { state: 'not-needed', reason: '手机状态将持久保存在酒馆聊天元数据。' },
      };
    }

    if (!tavernState && localState) {
      try {
        await this.#tavern.replace(scopeId, localState);
        const persisted = await this.#tavern.load(scopeId);
        if (!persisted || !phoneStatesEqual(localState, persisted)) {
          throw new Error('迁移后校验不一致');
        }
        return {
          backend: 'tavern',
          resolution: 'migrated-local',
          diagnostic: {
            state: 'migrated',
            reason: '已把旧版浏览器本地状态迁移到酒馆聊天元数据，今后不再依赖浏览器数据库。',
          },
        };
      } catch (error) {
        phoneLogger.warn('浏览器状态迁移到酒馆失败，暂保留本地缓存', error);
        return {
          backend: 'indexeddb',
          resolution: 'indexeddb-fallback',
          diagnostic: {
            state: 'fallback',
            reason: `迁移到酒馆失败，暂时保留浏览器本地状态：${formatError(error)}`,
          },
        };
      }
    }

    if (!tavernState) throw new Error('酒馆状态选择流程异常');

    if (!localState || phoneStatesEqual(tavernState, localState)) {
      this.#cacheState(scopeId, tavernState);
      return {
        backend: 'tavern',
        resolution: 'tavern',
        diagnostic: {
          state: 'not-needed',
          reason: '手机状态已从酒馆聊天元数据恢复；浏览器仅保留恢复缓存。',
        },
      };
    }

    if (localState.revision > tavernState.revision) {
      try {
        await this.#tavern.replace(scopeId, localState);
        const persisted = await this.#tavern.load(scopeId);
        if (!persisted || !phoneStatesEqual(localState, persisted)) throw new Error('较新本地状态迁移后校验失败');
        return {
          backend: 'tavern',
          resolution: 'migrated-local',
          diagnostic: {
            state: 'migrated',
            reason: '检测到本地缓存修订号更新，已安全回写酒馆聊天元数据。',
          },
        };
      } catch (error) {
        return {
          backend: 'indexeddb',
          resolution: 'indexeddb-fallback',
          diagnostic: {
            state: 'fallback',
            reason: `较新本地状态无法回写酒馆，暂保留本地状态：${formatError(error)}`,
          },
        };
      }
    }

    // 酒馆状态同修订号冲突时，保留本地副本并以服务端状态为事实源，避免静默反复覆盖。
    const reason = localState && localState.revision === tavernState.revision
      ? '酒馆与旧浏览器缓存修订号相同但内容不同，已保留酒馆状态并停止用本地缓存覆盖它。'
      : '酒馆聊天状态更新，已用酒馆状态覆盖旧浏览器缓存。';
    this.#cacheState(scopeId, tavernState);
    return {
      backend: 'tavern',
      resolution: localState && localState.revision === tavernState.revision ? 'migration-conflict' : 'tavern',
      diagnostic: {
        state: localState && localState.revision === tavernState.revision ? 'conflict' : 'not-needed',
        reason,
      },
    };
  }

  #cacheState(scopeId: string, state: PhoneState): void {
    this.#cachePending.set(scopeId, state);
    if (this.#cacheInFlight.has(scopeId)) return;
    const run = (async () => {
      while (this.#cachePending.has(scopeId)) {
        const next = this.#cachePending.get(scopeId);
        this.#cachePending.delete(scopeId);
        if (!next) break;
        try {
          await this.#indexedDb.replace(scopeId, next);
          this.#cacheFailureLogged = false;
        } catch (error) {
          if (!this.#cacheFailureLogged) {
            this.#cacheFailureLogged = true;
            phoneLogger.warn('写入浏览器恢复缓存失败（酒馆主数据不受影响）', error);
          }
        }
      }
      this.#cacheInFlight.delete(scopeId);
    })();
    this.#cacheInFlight.set(scopeId, run);
  }

  #pushTavern(scopeId: string, state: PhoneState): void {
    this.#tavernPending.set(scopeId, state);
    if (this.#tavernInFlight.has(scopeId)) return;
    const run = (async () => {
      const probe = await this.#probeTavern();
      if (!probe.available) return;
      while (this.#tavernPending.has(scopeId)) {
        const next = this.#tavernPending.get(scopeId);
        if (!next) break;
        try {
          await this.#tavern.replace(scopeId, next);
          if (this.#tavernPending.get(scopeId) === next) this.#tavernPending.delete(scopeId);
          this.#selected.set(scopeId, 'tavern');
          this.#diagnostics.set(scopeId, {
            resolution: 'migrated-local',
            migration: {
              state: 'migrated',
              reason: '酒馆持久化恢复后，已把浏览器临时状态回写酒馆聊天元数据。',
            },
          });
          this.#cacheState(scopeId, next);
        } catch (error) {
          this.#tavernAvailable = false;
          phoneLogger.warn('恢复酒馆主存储失败，继续使用浏览器缓存', error);
          break;
        }
      }
    })().finally(() => {
      this.#tavernInFlight.delete(scopeId);
    });
    this.#tavernInFlight.set(scopeId, run);
  }

  async #probeTavern(): Promise<{ readonly available: boolean; readonly reason: string }> {
    const available = await this.#tavern.isAvailable().catch(() => false);
    this.#tavernAvailable = available;
    return {
      available,
      reason: available ? '酒馆聊天元数据保存接口已验证可用。' : '当前聊天没有可用的酒馆元数据保存接口。',
    };
  }

  #select(
    scopeId: string,
    kind: StorageBackendKind,
    resolution: StorageResolution,
    migration: StorageMigrationDiagnostic,
  ): StorageBackend {
    this.#selected.set(scopeId, kind);
    this.#diagnostics.set(scopeId, { resolution, migration });
    return this.#backend(kind);
  }

  #backend(kind: StorageBackendKind): StorageBackend {
    return kind === 'tavern' ? this.#tavern : this.#indexedDb;
  }
}

function formatError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * 判断一份手机状态是否真正没有业务数据。
 * 记忆、时间线、日记、日历和总结本身都是事实数据，不能被忽略。
 */
export function isEssentiallyEmptyPhoneState(state: PhoneState): boolean {
  const profileIds = Object.keys(state.profiles);
  const onlySelfProfile = profileIds.length === 0
    || (profileIds.length === 1 && profileIds[0] === SELF_PROFILE_ID);
  return onlySelfProfile
    && Object.keys(state.conversations).length === 0
    && Object.keys(state.messages).length === 0
    && Object.keys(state.posts).length === 0
    && Object.keys(state.interactions).length === 0
    && Object.keys(state.outbox).length === 0
    && Object.keys(state.batches).length === 0
    && state.messageOrder.length === 0
    && state.postOrder.length === 0
    && state.appliedActionIds.length === 0
    && state.summaries.length === 0
    && state.pxxProducts.length === 0
    && Object.keys(state.calendarFestivals).length === 0
    && state.diaryEntries.length === 0
    && state.diaryCoveredUntil === 0
    && state.memoryItems.length === 0
    && state.memorySeq === 0
    && state.memoryLastFloor === -1
    && state.timelineEvents.length === 0
    && state.timelineSeq === 0;
}
