import { logOperationFailure } from '../core/diagnostics.js';
import {
  getSillyTavernEventChannel,
  type SillyTavernEventChannel,
} from '../integration/sillytavern-bridge.js';

/** 智绘姬/前端助手约定的跨扩展生图事件。 */
export const ZHIHUIJI_REQUEST_EVENT = 'generate-image-request';
export const ZHIHUIJI_RESPONSE_EVENT = 'generate-image-response';
export const ZHIHUIJI_READY_EVENT = ZHIHUIJI_RESPONSE_EVENT;

const DEFAULT_TIMEOUT_MS = 180_000;

export interface ZhihuijiImageRequest {
  readonly id: string;
  readonly prompt: string;
  readonly width: null;
  readonly height: null;
}

export interface ZhihuijiImageResponse {
  readonly id?: unknown;
  readonly success?: unknown;
  readonly imageData?: unknown;
  readonly error?: unknown;
  readonly prompt?: unknown;
  readonly change?: unknown;
}

/** 供测试或其他宿主适配器注入的智慧姬事件端口。 */
export interface ZhihuijiPort {
  readonly getEventChannel: () => SillyTavernEventChannel | null;
}

export interface ZhihuijiAvailability {
  readonly available: boolean;
  readonly reason: string;
  /** 事件协议不暴露 DOM 按钮数量，这两个字段只为旧设置数据结构保留。 */
  readonly triggerCount: 0;
  readonly pendingCount: 0;
  readonly source?: SillyTavernEventChannel['source'];
}

export interface ZhihuijiRequestOptions {
  readonly port?: ZhihuijiPort;
  readonly timeoutMs?: number;
}

/** 检查宿主是否提供完整的请求—响应事件通道；这不是一次生图测试。 */
export function inspectZhihuiji(
  port: ZhihuijiPort = createDomZhihuijiPort(),
): ZhihuijiAvailability {
  const channel = port.getEventChannel();
  if (!channel) {
    return {
      available: false,
      reason: '未检测到智绘姬事件通道：需要前端助手或提供 eventSource.on、emit、removeListener 的宿主。',
      triggerCount: 0,
      pendingCount: 0,
    };
  }
  return {
    available: true,
    reason: `智绘姬事件通道可用（${channel.source}），尚未进行真实生图验证；请通过实际生图请求验证。`,
    triggerCount: 0,
    pendingCount: 0,
    source: channel.source,
  };
}

/**
 * 按接入文档执行一次完整的事件请求生命周期。
 * 先注册带唯一 ID 的响应监听，再发出请求；响应、异常和超时都会移除监听。
 */
export async function requestZhihuijiImage(
  prompt: string,
  options: ZhihuijiRequestOptions = {},
): Promise<string> {
  const cleanPrompt = prompt.trim();
  if (!cleanPrompt) throw new Error('智绘姬生图提示词为空。');
  const port = options.port ?? createDomZhihuijiPort();
  const channel = port.getEventChannel();
  if (!channel) {
    const availability = inspectZhihuiji(port);
    logOperationFailure({ stage: '智绘姬生图', reason: '事件通道不可用', context: { promptLength: cleanPrompt.length } });
    throw new Error(`智绘姬无法接收这次生图请求：${availability.reason}`);
  }

  const timeoutMs = Math.max(1_000, options.timeoutMs ?? DEFAULT_TIMEOUT_MS);
  const requestId = createRequestId();
  const request: ZhihuijiImageRequest = {
    id: requestId,
    prompt: cleanPrompt,
    width: null,
    height: null,
  };

  return await new Promise<string>((resolve, reject) => {
    let settled = false;
    let listening = false;
    let timer: ReturnType<typeof setTimeout> | undefined;

    const cleanup = (): void => {
      if (timer !== undefined) clearTimeout(timer);
      if (!listening) return;
      listening = false;
      try {
        channel.removeListener(ZHIHUIJI_RESPONSE_EVENT, responseHandler);
      } catch (error) {
        logOperationFailure({ stage: '智绘姬生图', reason: '移除响应监听失败', error });
      }
    };
    const finish = (result: string): void => {
      if (settled) return;
      settled = true;
      cleanup();
      resolve(result);
    };
    const fail = (error: unknown, reason: string): void => {
      if (settled) return;
      settled = true;
      cleanup();
      logOperationFailure({
        stage: '智绘姬生图',
        reason,
        context: { requestId, promptLength: cleanPrompt.length },
        ...(error === undefined ? {} : { error }),
      });
      reject(error instanceof Error ? error : new Error(String(error)));
    };
    const responseHandler = (payload: unknown): void => {
      const response = readResponse(payload);
      if (!response || response.id !== requestId) return;
      if (response.success === true) {
        const imageData = readImageData(response.imageData);
        if (imageData) {
          finish(imageData);
        } else {
          fail(new Error('智绘姬响应成功但没有返回 imageData。'), '响应缺少图片数据');
        }
        return;
      }
      fail(new Error(readResponseError(response.error)), '智绘姬响应报告生成失败');
    };

    try {
      channel.on(ZHIHUIJI_RESPONSE_EVENT, responseHandler);
      listening = true;
      timer = setTimeout(() => {
        const seconds = Math.round(timeoutMs / 1000);
        fail(new Error(`智绘姬在 ${seconds} 秒内没有返回图片；请检查智绘姬扩展和其后端日志。`), '等待响应超时');
      }, timeoutMs);
      const emitted = channel.emit(ZHIHUIJI_REQUEST_EVENT, request);
      void Promise.resolve(emitted).catch((error: unknown) => {
        fail(error, '发送生图请求失败');
      });
    } catch (error) {
      fail(error, '注册或发送生图请求失败');
    }
  });
}

/** 解析协议允许的 imageData，兼容裸 base64 与 data URL/远程地址。 */
export function readImageData(value: unknown): string | null {
  if (typeof value !== 'string') return null;
  const compact = value.trim();
  if (!compact) return null;
  if (/^(?:data:image\/|https?:\/\/)/i.test(compact)) return compact;
  if (/^[A-Za-z0-9+/]+={0,2}$/.test(compact.replace(/\s+/g, ''))) {
    return `data:image/png;base64,${compact.replace(/\s+/g, '')}`;
  }
  return compact;
}

function readResponse(value: unknown): ZhihuijiImageResponse | null {
  return value && typeof value === 'object' ? value as ZhihuijiImageResponse : null;
}

function readResponseError(value: unknown): string {
  if (typeof value === 'string' && value.trim()) return value.trim();
  if (value && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    const message = record.message ?? record.error ?? record.detail;
    if (typeof message === 'string' && message.trim()) return message.trim();
  }
  return '智绘姬未提供具体错误信息。';
}

function createRequestId(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') {
    return `sjichajian-${crypto.randomUUID()}`;
  }
  return `sjichajian-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

/** 集中从当前酒馆/父窗口读取事件总线，不访问图片按钮或聊天 DOM。 */
export function createDomZhihuijiPort(): ZhihuijiPort {
  return { getEventChannel: getSillyTavernEventChannel };
}