import { SELF_PROFILE_ID } from '../domain/commands.js';
import type { PhoneEvent } from '../domain/events.js';
import { createId, createScopedId, type IdFactory } from '../domain/ids.js';
import { derivePostTitle, type Conversation, type PhoneMessage, type PhonePost, type PhoneState, type Profile } from '../domain/model.js';
import {
  hashFingerprint,
  normalizeFingerprintText,
  normalizeIdentity,
  parsedItemFingerprint,
  type ParsedPhoneItem,
} from './normalize.js';

export interface ParsedReconcileResult {
  readonly events: readonly PhoneEvent[];
  readonly importedCount: number;
  readonly createdProfileCount: number;
  readonly createdConversationCount: number;
  readonly issues: readonly string[];
}

export function reconcileParsedPhoneItems(
  initialState: PhoneState,
  inputItems: readonly ParsedPhoneItem[],
  sourceFloor: number,
  idFactory: IdFactory = createId,
): ParsedReconcileResult {
  const events: PhoneEvent[] = [];
  const issues: string[] = [];
  const profiles = new Map(Object.values(initialState.profiles).map((profile) => [profile.id, profile]));
  const conversations = new Map(Object.values(initialState.conversations).map((conversation) => [conversation.id, conversation]));
  const posts = new Map(Object.values(initialState.posts).map((post) => [post.id, post]));
  const externalPosts = new Map<string, PhonePost>();
  for (const post of posts.values()) {
    if (post.actionId?.startsWith('parsed-entity:')) externalPosts.set(post.actionId.slice('parsed-entity:'.length), post);
    else if (post.externalId) externalPosts.set(`${post.appId}:${normalizeIdentity(post.externalId)}`, post);
  }
  const knownActionIds = new Set(initialState.appliedActionIds);
  const knownFingerprints = collectExistingFingerprints(initialState);
  const knownOutgoingFingerprints = collectOutgoingFingerprints(initialState);
  /** 本次导入中每个会话/板块最近一条主帖，用于给同段正文里的评论找目标。 */
  const passPostsByConversation = new Map<string, PhonePost>();
  const occurrence = new Map<string, number>();
  let importedCount = 0;
  let createdProfileCount = 0;
  let createdConversationCount = 0;

  inputItems.forEach((item, index) => {
    const baseFingerprint = parsedItemFingerprint(item);
    const ordinal = occurrence.get(baseFingerprint) ?? 0;
    occurrence.set(baseFingerprint, ordinal + 1);
    if (item.speakerRole === 'self' && knownOutgoingFingerprints.has(outgoingItemFingerprint(item))) return;
    const actionId = item.sourceEntityId
      ? `parsed-entity:${item.appId}:${normalizeIdentity(item.sourceEntityId)}`
      : `parsed:${hashFingerprint(`${baseFingerprint}|${ordinal}`)}`;
    const exactFingerprint = `${baseFingerprint}|${ordinal}`;
    if (knownActionIds.has(actionId) || knownFingerprints.has(exactFingerprint)) return;

    const actor = item.speakerRole === 'self'
      ? profiles.get(SELF_PROFILE_ID) ?? null
      : resolveOrCreateProfile(initialState, profiles, item, idFactory);
    if (!actor) {
      issues.push(`${item.sourceAdapterId}: 用户资料不存在，无法导入用户侧内容`);
      return;
    }
    if (item.speakerRole === 'other' && !profiles.has(actor.id)) {
      profiles.set(actor.id, actor);
      events.push(createEvent(initialState, 'profile.upserted', initialState.worldClock.now, { profile: actor }, idFactory));
      createdProfileCount += 1;
    }

    const createdAt = resolveItemTimestamp(initialState.worldClock.now, item.timeLabel, index);
    if (item.itemKind === 'message') {
      const resolved = resolveOrCreateConversation(initialState, conversations, item, actor, createdAt, idFactory);
      if (resolved.event) {
        events.push(resolved.event);
        createdConversationCount += resolved.created ? 1 : 0;
      }
      conversations.set(resolved.conversation.id, resolved.conversation);
      const message: PhoneMessage = {
        id: createScopedId(initialState.scopeId, 'parsed-message', idFactory),
        scopeId: initialState.scopeId,
        appId: item.appId,
        conversationId: resolved.conversation.id,
        profileId: actor.id,
        direction: item.speakerRole === 'self' ? 'outgoing' : 'incoming',
        content: item.content,
        ...(item.messageKind ? { kind: item.messageKind } : {}),
        metadata: {
          source: 'story-structured-parse',
          sourceFloor: String(sourceFloor),
          sourceAdapter: item.sourceAdapterId,
          conversationKey: item.conversationKey,
          ...(item.timeLabel ? { sourceTime: item.timeLabel } : {}),
        },
        status: 'sent',
        createdAt,
        actionId,
      };
      events.push(createEvent(initialState, 'message.received', createdAt, { message }, idFactory, actionId));
    } else if (item.itemKind === 'post') {
      const postResult = createParsedPost(initialState, item, actor, posts, externalPosts, createdAt, actionId, idFactory);
      events.push(postResult.event);
      posts.set(postResult.post.id, postResult.post);
      if (item.sourceEntityId) externalPosts.set(`${item.appId}:${normalizeIdentity(item.sourceEntityId)}`, postResult.post);
      if (postResult.post.kind !== 'forum-reply') passPostsByConversation.set(conversationPassKey(item), postResult.post);
    } else {
      // 同一段正文里的评论优先挂到刚导入的那条动态上，卡里没写 ID 时也不会丢。
      const target = findExternalPost(externalPosts, item.appId, item.targetEntityId ?? item.parentEntityId)
        ?? passPostsByConversation.get(conversationPassKey(item))
        ?? findConversationPost(posts.values(), item);
      if (!target) {
        issues.push(`${item.sourceAdapterId}: 评论目标不存在，已忽略「${item.content.slice(0, 40)}」`);
        return;
      }
      const interaction = {
        id: createScopedId(initialState.scopeId, 'parsed-interaction', idFactory),
        scopeId: initialState.scopeId,
        appId: item.appId,
        type: 'comment' as const,
        actorProfileId: actor.id,
        targetId: target.id,
        content: item.content,
        createdAt,
        actionId,
      };
      events.push(createEvent(initialState, 'interaction.created', createdAt, { interaction }, idFactory, actionId));
    }
    knownActionIds.add(actionId);
    knownFingerprints.add(exactFingerprint);
    if (item.speakerRole === 'self') knownOutgoingFingerprints.add(outgoingItemFingerprint(item));
    importedCount += 1;
  });

  return { events, importedCount, createdProfileCount, createdConversationCount, issues };
}

function resolveOrCreateProfile(
  state: PhoneState,
  profiles: ReadonlyMap<string, Profile>,
  item: ParsedPhoneItem,
  idFactory: IdFactory,
): Profile {
  const candidates = [item.speakerName, item.accountName].map((value) => normalizeIdentity(value ?? '')).filter(Boolean);
  for (const profile of profiles.values()) {
    if (profile.id === SELF_PROFILE_ID) continue;
    const names = [profile.displayName, profile.boundCharacter, profile.twitterName, ...Object.values(profile.aliases)]
      .map((value) => normalizeIdentity(value ?? ''))
      .filter(Boolean);
    if (candidates.some((candidate) => names.includes(candidate))) return profile;
  }
  const displayName = (item.accountName || item.speakerName).slice(0, 40);
  return {
    id: createScopedId(state.scopeId, `parsed-${item.appId}-profile`, idFactory),
    scopeId: state.scopeId,
    displayName,
    ...(item.accountName && normalizeIdentity(item.accountName) !== normalizeIdentity(item.speakerName)
      ? { boundCharacter: item.speakerName.slice(0, 80) }
      : {}),
    aliases: { [item.appId]: item.accountName || displayName },
    replyDelay: { minimumMinutes: 2, maximumMinutes: 25 },
    activeHours: { startHour: 7, endHour: 23 },
    createdAt: state.worldClock.now,
    updatedAt: state.worldClock.now,
  };
}

function resolveOrCreateConversation(
  state: PhoneState,
  conversations: ReadonlyMap<string, Conversation>,
  item: ParsedPhoneItem,
  actor: Profile,
  createdAt: number,
  idFactory: IdFactory,
): { readonly conversation: Conversation; readonly event: PhoneEvent | null; readonly created: boolean } {
  const title = displayConversationTitle(item.conversationKey, actor.displayName);
  const existing = [...conversations.values()].find((conversation) => {
    if (conversation.appId !== item.appId || conversation.kind !== item.conversationKind) return false;
    if (item.conversationKind === 'group') return normalizeIdentity(conversation.title) === normalizeIdentity(title);
    return conversation.participantIds.includes(SELF_PROFILE_ID) && conversation.participantIds.includes(actor.id);
  });
  if (existing) {
    if (existing.participantIds.includes(actor.id)) return { conversation: existing, event: null, created: false };
    const conversation = { ...existing, participantIds: [...existing.participantIds, actor.id], updatedAt: createdAt };
    return {
      conversation,
      event: createEvent(state, 'conversation.upserted', createdAt, { conversation }, idFactory),
      created: false,
    };
  }
  const conversation: Conversation = {
    id: createScopedId(state.scopeId, `parsed-${item.appId}-conversation`, idFactory),
    scopeId: state.scopeId,
    appId: item.appId,
    kind: item.conversationKind,
    title,
    participantIds: [...new Set([SELF_PROFILE_ID, actor.id])],
    unreadCount: 0,
    muted: false,
    createdAt,
    updatedAt: createdAt,
  };
  return {
    conversation,
    event: createEvent(state, 'conversation.upserted', createdAt, { conversation }, idFactory),
    created: true,
  };
}

function createParsedPost(
  state: PhoneState,
  item: ParsedPhoneItem,
  actor: Profile,
  posts: ReadonlyMap<string, PhonePost>,
  externalPosts: ReadonlyMap<string, PhonePost>,
  createdAt: number,
  actionId: string,
  idFactory: IdFactory,
): { readonly post: PhonePost; readonly event: PhoneEvent } {
  let kind = item.postKind ?? (item.appId === 'forum' ? 'forum-thread' : item.appId === 'twitter' ? 'twitter-post' : 'moment');
  const board = parsedItemBoard(item);
  let parentId: string | undefined;
  let targetId: string | undefined;
  if (kind === 'forum-reply') {
    // 卡内 ID 是最可靠的挂载依据；没有 ID 才退回板块与标题匹配。
    const root = findExternalPost(externalPosts, item.appId, item.parentEntityId ?? item.targetEntityId)
      ?? findConversationPost(posts.values(), item);
    if (root) {
      parentId = root.id;
      targetId = root.id;
    } else {
      kind = 'forum-thread';
    }
  } else if (kind === 'twitter-reply' && item.targetEntityId) {
    const root = findExternalPost(externalPosts, item.appId, item.targetEntityId);
    if (root) targetId = root.id;
  }
  const title = item.title?.trim() || (kind === 'forum-thread' ? deriveThreadTitle(item.content, board) : '');
  const parentExternalId = item.parentEntityId ?? item.targetEntityId;
  const post: PhonePost = {
    id: createScopedId(state.scopeId, 'parsed-post', idFactory),
    scopeId: state.scopeId,
    appId: item.appId,
    kind,
    profileId: actor.id,
    ...(title ? { title } : {}),
    content: item.content,
    createdAt,
    ...(parentId ? { parentId } : {}),
    ...(targetId ? { targetId } : {}),
    ...(board ? { board } : {}),
    ...(item.tags && item.tags.length > 0 ? { tags: item.tags } : {}),
    ...(item.pinned ? { pinned: true } : {}),
    ...(item.hot ? { hot: true } : {}),
    ...(item.metrics && Object.values(item.metrics).some((value) => value !== undefined) ? { metrics: item.metrics } : {}),
    ...(item.timeLabel ? { timeLabel: item.timeLabel } : {}),
    ...(item.sourceEntityId ? { externalId: item.sourceEntityId } : {}),
    ...(kind !== 'forum-thread' && parentExternalId ? { parentExternalId } : {}),
    actionId,
  };
  return { post, event: createEvent(state, 'post.created', createdAt, { post }, idFactory, actionId) };
}

/** 板块优先取卡里明确写的分区；论坛容器没写时退回 conversationKey 里的频道名。 */
function parsedItemBoard(item: ParsedPhoneItem): string {
  const explicit = item.board?.trim();
  if (explicit) return explicit.slice(0, 80);
  return item.appId === 'forum' ? displayConversationTitle(item.conversationKey, '') : '';
}

/** 卡里没给标题时用正文首行当标题，规则与界面展示保持一致。 */
function deriveThreadTitle(content: string, board: string): string {
  return (derivePostTitle(content) || board || '论坛主题').slice(0, 80);
}

function findExternalPost(
  externalPosts: ReadonlyMap<string, PhonePost>,
  appId: PhonePost['appId'],
  externalId: string | undefined,
): PhonePost | null {
  if (!externalId?.trim()) return null;
  return externalPosts.get(`${appId}:${normalizeIdentity(externalId)}`) ?? null;
}

function conversationPassKey(item: ParsedPhoneItem): string {
  return `${item.appId}:${normalizeIdentity(item.conversationKey)}`;
}

function findConversationPost(posts: Iterable<PhonePost>, item: ParsedPhoneItem): PhonePost | null {
  const board = normalizeIdentity(parsedItemBoard(item));
  const title = normalizeIdentity(displayConversationTitle(item.conversationKey, ''));
  if (!board && !title) return null;
  return [...posts].reverse().find((post) => post.appId === item.appId
    && post.kind === 'forum-thread'
    && ((board !== '' && normalizeIdentity(post.board ?? '') === board)
      || (title !== '' && normalizeIdentity(post.title ?? '') === title))) ?? null;
}

function collectExistingFingerprints(state: PhoneState): Set<string> {
  const result = new Set<string>();
  const messageOccurrences = new Map<string, number>();
  for (const id of state.messageOrder) {
    const message = state.messages[id];
    if (!message) continue;
    const conversation = state.conversations[message.conversationId];
    const profile = state.profiles[message.profileId];
    const base = [
      message.appId,
      'message',
      conversation?.kind ?? 'direct',
      normalizeIdentity(message.metadata?.conversationKey ?? conversation?.title ?? ''),
      message.direction === 'outgoing' ? 'self' : 'other',
      normalizeIdentity(profile?.displayName ?? ''),
      '',
      normalizeFingerprintText(message.content),
    ].join('|');
    const ordinal = messageOccurrences.get(base) ?? 0;
    messageOccurrences.set(base, ordinal + 1);
    result.add(`${base}|${ordinal}`);
  }
  return result;
}

function collectOutgoingFingerprints(state: PhoneState): Set<string> {
  const result = new Set<string>();
  for (const message of Object.values(state.messages)) {
    if (message.direction !== 'outgoing') continue;
    result.add(`${message.appId}|${normalizeFingerprintText(message.content)}`);
  }
  return result;
}

function outgoingItemFingerprint(item: ParsedPhoneItem): string {
  return `${item.appId}|${normalizeFingerprintText(item.content)}`;
}

function displayConversationTitle(key: string, fallback: string): string {
  const cleaned = key.replace(/^(?:wechat|twitter|anonymous|forum|qq(?::(?:direct|group))?|qq-space):/i, '').trim();
  return (cleaned || fallback || '新会话').slice(0, 80);
}

function resolveItemTimestamp(now: number, timeLabel: string | undefined, index: number): number {
  const match = /(?:^|\s)(\d{1,2}):(\d{2})(?:\s|$)/.exec(timeLabel ?? '');
  if (!match) return now + index * 1_000;
  const hours = Number(match[1]);
  const minutes = Number(match[2]);
  if (hours > 23 || minutes > 59) return now + index * 1_000;
  const date = new Date(now);
  date.setHours(hours, minutes, index, 0);
  return date.getTime();
}

function createEvent<TType extends PhoneEvent['type']>(
  state: PhoneState,
  type: TType,
  occurredAt: number,
  payload: Extract<PhoneEvent, { readonly type: TType }>['payload'],
  idFactory: IdFactory,
  actionId?: string,
): Extract<PhoneEvent, { readonly type: TType }> {
  return {
    id: createScopedId(state.scopeId, 'parsed-event', idFactory),
    scopeId: state.scopeId,
    type,
    occurredAt,
    payload,
    ...(actionId ? { actionId } : {}),
  } as Extract<PhoneEvent, { readonly type: TType }>;
}