/**
 * MVU 更新命令解析。
 *
 * 两代协议：老卡与旧脚本写 `_.set('路径', 旧值, 新值); // 理由`，
 * MVU Zod 之后的卡改成 `<UpdateVariable><JSONPatch>[…]</JSONPatch></UpdateVariable>`。
 * 数据桥要把两者都翻译成表格写入，因此先把命令解析成结构化形式。
 * 只解析，不判断路径存不存在——那是映射层的职责。
 */

import { parseInitVarBlockCommands, parseJsonPatchCommands } from './json-patch.js';

export type MvuCommandKind = 'set' | 'add' | 'insert' | 'delete' | 'move';

export interface MvuCommand {
  readonly index?: number;
  readonly kind: MvuCommandKind;
  readonly path: string;
  /** 命令参数（已解析字面量），不含路径。 */
  readonly args: readonly unknown[];
  readonly reason: string;
  readonly raw: string;
}

const COMMAND_PATTERN = /_\.\s*(set|add|insert|delete|move)\s*\(/gi;

/** 在引号与括号之外找配对的右括号。 */
function findCallEnd(text: string, start: number): number {
  let depth = 0;
  let quote: '"' | '\'' | '`' | null = null;
  for (let index = start; index < text.length; index += 1) {
    const char = text[index] ?? '';
    if (quote) {
      if (char === '\\') index += 1;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'' || char === '`') {
      quote = char;
      continue;
    }
    if (char === '(' || char === '[' || char === '{') depth += 1;
    else if (char === ')' || char === ']' || char === '}') {
      depth -= 1;
      if (depth === 0) return index;
    }
  }
  return -1;
}

function splitArguments(body: string): readonly string[] {
  const args: string[] = [];
  let start = 0;
  let depth = 0;
  let quote: '"' | '\'' | '`' | null = null;
  for (let index = 0; index < body.length; index += 1) {
    const char = body[index] ?? '';
    if (quote) {
      if (char === '\\') index += 1;
      else if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'' || char === '`') {
      quote = char;
      continue;
    }
    if (char === '(' || char === '[' || char === '{') depth += 1;
    else if (char === ')' || char === ']' || char === '}') depth -= 1;
    else if (char === ',' && depth === 0) {
      args.push(body.slice(start, index).trim());
      start = index + 1;
    }
  }
  const tail = body.slice(start).trim();
  if (tail) args.push(tail);
  return args;
}

/** 解析单个字面量：字符串、数字、布尔、null、数组、对象；认不出来按原文字符串返回。 */
export function parseCommandLiteral(raw: string): unknown {
  const text = raw.trim();
  if (!text) return '';
  const quote = text[0];
  if ((quote === '\'' || quote === '"' || quote === '`') && text.endsWith(quote) && text.length >= 2) {
    if (quote === '"') { try { return JSON.parse(text); } catch { /* 宽松的旧命令继续走下方解析。 */ } }
    const inner = text.slice(1, -1);
    return quote === '"' ? unescapeDouble(inner) : inner.replaceAll('\\\'', '\'');
  }
  if (text === 'true') return true;
  if (text === 'false') return false;
  if (text === 'null' || text === 'undefined') return null;
  if (/^[-+]?\d+(?:\.\d+)?$/.test(text)) return Number(text);
  if ((text.startsWith('[') && text.endsWith(']')) || (text.startsWith('{') && text.endsWith('}'))) {
    try {
      try { return JSON.parse(text) as unknown; } catch { return JSON.parse(text.replaceAll('\'', '"')) as unknown; }
    } catch {
      return text;
    }
  }
  return text;
}

function unescapeDouble(inner: string): string {
  return inner.replace(/\\(.)/g, (_match, char: string) => {
    if (char === 'n') return '\n';
    if (char === 't') return '\t';
    return char;
  });
}

function readReason(text: string, from: number): string {
  const line = text.slice(from, text.indexOf('\n', from) < 0 ? text.length : text.indexOf('\n', from));
  const comment = /\/\/\s*(.*)$/.exec(line);
  return (comment?.[1] ?? '').trim().slice(0, 200);
}

/** 从一段文本里提取老协议的 `_.set` 系命令，按出现顺序。 */
export function parseLegacyMvuCommands(text: string): readonly MvuCommand[] {
  const commands: MvuCommand[] = [];
  COMMAND_PATTERN.lastIndex = 0;
  let match = COMMAND_PATTERN.exec(text);
  while (match) {
    const kind = match[1]?.toLowerCase() as MvuCommandKind;
    const open = match.index + match[0].length - 1;
    const close = findCallEnd(text, open);
    if (close < 0) break;
    const args = splitArguments(text.slice(open + 1, close));
    const path = String(parseCommandLiteral(args[0] ?? '')).trim();
    if (path) {
      commands.push({
        kind,
        path,
        args: args.slice(1).map((item) => parseCommandLiteral(item)),
        reason: readReason(text, close + 1),
        raw: text.slice(match.index, close + 1),
      });
    }
    COMMAND_PATTERN.lastIndex = close + 1;
    match = COMMAND_PATTERN.exec(text);
  }
  return commands;
}

/**
 * 从一段文本里提取全部 MVU 更新命令。
 *
 * 两代协议都收：老卡写 `_.set(...)`，MVU Zod 之后的卡写 `<JSONPatch>`；
 * `<initvar>` 全量块排在最前，因为它是开局覆写，后面的增量要盖在它之上。
 */
export function parseMvuCommands(text: string): readonly MvuCommand[] {
  return [
    ...parseInitVarBlockCommands(text),
    ...parseLegacyMvuCommands(text),
    ...parseJsonPatchCommands(text),
  ];
}

/**
 * 命令的目标值。
 * `set` 支持两种写法：`(path, 新值)` 与 `(path, 旧值, 新值)`，后者取最后一个参数。
 */
export function commandTargetValue(command: MvuCommand): unknown {
  if (command.kind === 'set') return command.args[command.args.length - 1];
  return command.args[command.args.length - 1];
}
