import {
  FANFIC_CHECKPOINT_LIMIT,
  FANFIC_STATE_VERSION,
  type FanficCheckpoint,
  type FanficNarrativeCore,
  type FanficNarrativeState,
  type FanficScene,
} from './model.js';

const EMPTY_SCENE: FanficScene = Object.freeze({ place: '', time: '', situation: '', floor: -1 });

export function createEmptyFanficNarrative(): FanficNarrativeState {
  return {
    version: FANFIC_STATE_VERSION,
    lastFloor: -1,
    revision: 0,
    scene: EMPTY_SCENE,
    presence: [],
    relationshipShifts: [],
    secrets: [],
    threads: [],
    divergences: [],
    checkpoints: [],
  };
}

/** 兼容旧持久化状态与外部备份：缺字段补空，不抛错，不静默丢弃已知字段。 */
export function normalizeFanficNarrative(raw: unknown): FanficNarrativeState {
  const empty = createEmptyFanficNarrative();
  if (!isRecord(raw)) return empty;
  const scene = isRecord(raw.scene) ? raw.scene : {};
  return {
    version: FANFIC_STATE_VERSION,
    lastFloor: asFloor(raw.lastFloor, -1),
    revision: Math.max(0, asFloor(raw.revision, 0)),
    scene: {
      place: asText(scene.place),
      time: asText(scene.time),
      situation: asText(scene.situation),
      floor: asFloor(scene.floor, -1),
    },
    presence: asArray(raw.presence),
    relationshipShifts: asArray(raw.relationshipShifts),
    secrets: asArray(raw.secrets),
    threads: asArray(raw.threads),
    divergences: asArray(raw.divergences),
    checkpoints: asArray(raw.checkpoints),
  };
}

export function narrativeCoreOf(state: FanficNarrativeState): FanficNarrativeCore {
  return {
    scene: state.scene,
    presence: state.presence,
    relationshipShifts: state.relationshipShifts,
    secrets: state.secrets,
    threads: state.threads,
    divergences: state.divergences,
  };
}

/** 是否已有任何可注入的剧情事实；空状态不应该占用提示词预算。 */
export function hasFanficNarrativeContent(state: FanficNarrativeState): boolean {
  return Boolean(state.scene.place || state.scene.situation)
    || state.presence.length > 0
    || state.relationshipShifts.length > 0
    || state.secrets.length > 0
    || state.threads.length > 0
    || state.divergences.length > 0;
}

/**
 * 写入新一层剧情事实：先把上一层的核心快照存成检查点，再替换为新核心。
 * 检查点让编辑、删除、滑动楼层时能恢复到该楼层之前的状态，而不是清空全部进度。
 */
export function advanceFanficNarrative(
  state: FanficNarrativeState,
  floor: number,
  core: FanficNarrativeCore,
): FanficNarrativeState {
  const nextFloor = asFloor(floor, state.lastFloor);
  const checkpoints = hasFanficNarrativeContent(state)
    ? [...state.checkpoints, { floor: state.lastFloor, core: narrativeCoreOf(state) }].slice(-FANFIC_CHECKPOINT_LIMIT)
    : state.checkpoints;
  return {
    ...state,
    ...core,
    version: FANFIC_STATE_VERSION,
    lastFloor: Math.max(nextFloor, state.lastFloor),
    revision: state.revision + 1,
    checkpoints,
  };
}

/**
 * 楼层从 fromFloor 起失效：恢复到最近一个早于该楼层的检查点，
 * 并丢掉所有产生于 fromFloor 及之后的条目，避免保留被删掉的剧情事实。
 */
export function rollbackFanficNarrative(
  state: FanficNarrativeState,
  fromFloor: number,
): FanficNarrativeState {
  const boundary = Math.max(0, asFloor(fromFloor, 0));
  if (state.lastFloor < boundary && state.scene.floor < boundary) return state;
  const usable = state.checkpoints.filter((checkpoint) => checkpoint.floor < boundary);
  const restored = usable.at(-1)?.core ?? createEmptyFanficNarrative();
  const core = pruneNarrativeCore(restored, boundary);
  return {
    ...state,
    ...core,
    version: FANFIC_STATE_VERSION,
    lastFloor: Math.min(state.lastFloor, boundary - 1),
    revision: state.revision + 1,
    checkpoints: usable,
  };
}

function pruneNarrativeCore(core: FanficNarrativeCore, boundary: number): FanficNarrativeCore {
  const before = <T extends { readonly floor: number }>(items: readonly T[]): readonly T[] =>
    items.filter((item) => asFloor(item.floor, 0) < boundary);
  return {
    scene: core.scene.floor < boundary ? core.scene : EMPTY_SCENE,
    presence: core.scene.floor < boundary ? core.presence : [],
    relationshipShifts: before(core.relationshipShifts),
    secrets: before(core.secrets),
    threads: before(core.threads),
    divergences: before(core.divergences),
  };
}

export function fanficCheckpointFloors(state: FanficNarrativeState): readonly number[] {
  return state.checkpoints.map((checkpoint: FanficCheckpoint) => checkpoint.floor);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function asArray<T>(value: unknown): readonly T[] {
  return Array.isArray(value) ? value as T[] : [];
}

function asText(value: unknown): string {
  return typeof value === 'string' ? value.trim() : '';
}

function asFloor(value: unknown, fallback: number): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.floor(numeric) : fallback;
}