/**
 * 手机操作任务：把「进行中 → 成功 / 失败」这条生命周期收成一个句柄。
 *
 * 调用方只声明操作 id 与真实结果，标题（墨韵手机 {操作名}）、三态文案、
 * 显示时长与卡片复用都由这里统一决定，避免每个功能各自拼字符串、各自漏提示。
 */

import {
  pushStackNotice,
  type NoticeAction,
  type NoticeHandle,
  type NoticeKind,
} from './notice-stack.js';
import { operationCopy, operationTitle, SHELL_OPERATIONS, type ShellOperationId } from './phone-operations.js';

const SUCCESS_MS = 3_200;
const ERROR_MS = 8_000;
const WARN_MS = 6_000;

/** 结果对象的通用形状：项目里大量操作返回 { ok, message }。 */
export interface TaskOutcome {
  readonly ok: boolean;
  readonly message?: string;
}

export interface PhoneTaskOptions {
  /** 覆盖进行中文案。 */
  readonly detail?: string;
  /** 行内动作按钮，例如生成中的「终止」。 */
  readonly action?: NoticeAction | null;
  /**
   * 并发区分后缀：同一操作同时跑多次时传入不同值，卡片才会各自独立。
   * 默认同一操作复用一张卡片，重复触发不会刷屏。
   */
  readonly variant?: string;
}

export interface PhoneTaskHandle {
  /** 更新进行中文案（例如「正在解析 3/8…」）。 */
  readonly progress: (detail: string) => void;
  /** 重试提示：保持同一张卡片，转为警告色。 */
  readonly retry: (info: { readonly attempt: number; readonly retryCount: number; readonly error: unknown }) => void;
  readonly succeed: (detail?: string) => void;
  readonly fail: (reason: unknown) => void;
  /** 按 { ok, message } 自动落成功或失败。 */
  readonly settle: (outcome: TaskOutcome) => void;
  /** 用户主动取消：中性收尾，不算失败。 */
  readonly cancel: (detail?: string) => void;
  /** 静默收起（无终态提示）。 */
  readonly dismiss: () => void;
}

export function describeTaskReason(reason: unknown): string {
  if (reason instanceof Error) return reason.message || reason.name;
  if (typeof reason === 'string') return reason || '未知错误';
  return String(reason ?? '未知错误');
}

function noticeKey(id: string, variant?: string): string {
  return variant ? `phone-task:${id}:${variant}` : `phone-task:${id}`;
}

function terminalMs(kind: NoticeKind, id: string): number {
  if (kind === 'error') return ERROR_MS;
  if (kind === 'warn') return WARN_MS;
  return operationCopy(id).successMs ?? SUCCESS_MS;
}

/**
 * 开启一个操作任务。瞬时操作不显示进行中卡片，等终态再出现；
 * 其余操作立刻显示常驻的进行中卡片，终态时原地变色，不闪断。
 */
export function beginPhoneTask(id: string, options: PhoneTaskOptions = {}): PhoneTaskHandle {
  const spec = operationCopy(id);
  const key = noticeKey(id, options.variant);
  const title = operationTitle(id);
  let notice: NoticeHandle | null = null;

  const show = (kind: NoticeKind, detail: string, action?: NoticeAction | null): void => {
    const next = {
      title,
      detail,
      kind,
      durationMs: kind === 'pending' ? 0 : terminalMs(kind, id),
      action: action ?? null,
      key,
    };
    if (notice?.isAlive()) notice.update(next);
    else notice = pushStackNotice(next);
  };

  if (!spec.instant) show('pending', options.detail ?? spec.pending, options.action);

  return {
    progress: (detail) => show('pending', detail, options.action),
    retry: ({ attempt, retryCount, error }) => show(
      'warn',
      `${spec.fail}，正在重试 ${attempt}/${retryCount}：${describeTaskReason(error)}`,
      options.action,
    ),
    succeed: (detail) => show('success', detail?.trim() || spec.success),
    fail: (reason) => show('error', `${spec.fail}：${describeTaskReason(reason)}`),
    settle: (outcome) => {
      const message = outcome.message?.trim() ?? '';
      if (outcome.ok) show('success', message || spec.success);
      else show('error', message || spec.fail);
    },
    cancel: (detail) => show('info', detail?.trim() || `${spec.name}已取消`),
    dismiss: () => notice?.dismiss(),
  };
}

/** { ok, message } 形状的结果对象判定：用于自动落成功/失败态。 */
function isTaskOutcome(value: unknown): value is TaskOutcome {
  return typeof value === 'object'
    && value !== null
    && typeof (value as { ok?: unknown }).ok === 'boolean';
}

/**
 * 用任务提示包裹一次异步操作：进入即提示进行中，正常返回落成功，抛错落失败。
 *
 * 这是「每个功能都有三态提示」的落点——功能只需要被它包一层，
 * 不必在自己的实现里散落通知调用。返回 { ok, message } 的操作会沿用其真实文案。
 */
export async function runPhoneTask<T>(
  id: string,
  run: (task: PhoneTaskHandle) => Promise<T> | T,
  options: PhoneTaskOptions = {},
): Promise<T> {
  const task = beginPhoneTask(id, options);
  try {
    const result = await run(task);
    if (isTaskOutcome(result)) task.settle(result);
    else task.succeed();
    return result;
  } catch (error) {
    task.fail(error);
    throw error;
  }
}

type AnyCallback = (...args: readonly never[]) => unknown;

/** 同步与异步回调统一收口：Promise 走 then/catch，同步值立即落终态。 */
function attachTaskNotice(id: ShellOperationId, callback: AnyCallback): AnyCallback {
  return (...args) => {
    const task = beginPhoneTask(id);
    try {
      const result = callback(...args);
      if (result instanceof Promise) {
        return result.then(
          (value: unknown) => {
            if (isTaskOutcome(value)) task.settle(value);
            else task.succeed();
            return value;
          },
          (error: unknown) => {
            task.fail(error);
            throw error;
          },
        );
      }
      if (isTaskOutcome(result)) task.settle(result);
      else task.succeed();
      return result;
    } catch (error) {
      task.fail(error);
      throw error;
    }
  };
}

/**
 * 给操作入口集合套上统一的三态提示。
 *
 * 键名命中 SHELL_OPERATIONS 且未标记 manual 的回调会被包裹，签名与返回值保持原样；
 * 这样「每个功能都有提示」由入口层一次性保证，而不是散落在每个功能实现里。
 */
export function withOperationNotices<T extends object>(options: T): T {
  const source = options as unknown as Record<string, unknown>;
  const wrapped: Record<string, unknown> = { ...source };
  for (const [key, value] of Object.entries(source)) {
    if (typeof value !== 'function') continue;
    const spec = SHELL_OPERATIONS[key as ShellOperationId] as { readonly manual?: boolean } | undefined;
    if (!spec || spec.manual === true) continue;
    wrapped[key] = attachTaskNotice(key as ShellOperationId, value as AnyCallback);
  }
  return wrapped as T;
}