/** SQ / ACU 的原始定义只作为数据保存，角色脚本与模板中的代码均不执行。 */
export interface SqColumnBinding {
  readonly column: string;
  readonly sourceName: string;
  readonly label: string;
  readonly type: string;
}
export interface SqTableBinding {
  readonly key: string;
  readonly uid: string;
  readonly name: string;
  readonly sqlName: string;
  readonly columns: readonly SqColumnBinding[];
  readonly sourceData: Readonly<Record<string, unknown>>;
  readonly exportConfig: Readonly<Record<string, unknown>>;
  readonly updateConfig: Readonly<Record<string, unknown>>;
}
export interface SqCompatibility {
  readonly version: 1;
  readonly mate: Readonly<Record<string, unknown>>;
  readonly tables: readonly SqTableBinding[];
}

export const sqRecord = (value: unknown): Record<string, unknown> => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};

export function extractSqCardTemplate(value: unknown): { template: Record<string, unknown>; cardName: string } | null {
  const root = sqRecord(value), data = sqRecord(root.data);
  const book = sqRecord(data.character_book ?? root.character_book);
  const entries = Array.isArray(book.entries) ? book.entries : Object.values(sqRecord(book.entries));
  for (const raw of entries) {
    const entry = sqRecord(raw);
    const keys = [entry.comment, entry.name, ...[entry.keys, entry.key].flatMap((key) => Array.isArray(key) ? key : [key])];
    if (!keys.some((key) => String(key ?? '').trim() === '__ACU_TEMPLATE_DATA__')) continue;
    const content = String(entry.content ?? '').trim();
    let template: Record<string, unknown>;
    try {
      const json = content.startsWith('{') ? content : new TextDecoder('utf-8', { fatal: true }).decode(Uint8Array.from(atob(content.replace(/\s/g, '')), (char) => char.charCodeAt(0)));
      template = sqRecord(JSON.parse(json));
    } catch { throw new Error('SQ 角色卡的 __ACU_TEMPLATE_DATA__ 不是有效的 UTF-8 JSON / Base64 模板。'); }
    if (sqRecord(template.mate).type !== 'chatSheets' && !Object.keys(template).some((key) => key.startsWith('sheet_'))) {
      throw new Error('SQ 角色卡模板缺少 chatSheets 表定义。');
    }
    return { template, cardName: String(data.name ?? root.name ?? '') };
  }
  return null;
}

export function normalizeSqCompatibility(value: unknown): SqCompatibility | undefined {
  const raw = sqRecord(value);
  if (raw.version !== 1 || !Array.isArray(raw.tables)) return undefined;
  const tables = raw.tables.flatMap((value): SqTableBinding[] => {
    const table = sqRecord(value);
    if (typeof table.key !== 'string' || typeof table.name !== 'string' || !Array.isArray(table.columns)) return [];
    const columns = table.columns.flatMap((value): SqColumnBinding[] => {
      const column = sqRecord(value);
      return typeof column.column === 'string' ? [{ column: column.column, sourceName: String(column.sourceName ?? column.column), label: String(column.label ?? column.column), type: String(column.type ?? 'TEXT') }] : [];
    });
    return [{ key: table.key, uid: String(table.uid ?? table.key), name: table.name, sqlName: String(table.sqlName ?? table.name), columns,
      sourceData: sqRecord(table.sourceData), exportConfig: sqRecord(table.exportConfig), updateConfig: sqRecord(table.updateConfig) }];
  });
  return { version: 1, mate: sqRecord(raw.mate), tables };
}

export function sqBinding(key: string, raw: Record<string, unknown>, columns: readonly string[], labels: readonly string[], sourceNames: readonly string[]): SqTableBinding {
  const sourceData = sqRecord(raw.sourceData), ddl = String(sourceData.ddl ?? '');
  return { key, uid: String(raw.uid ?? key), name: String(raw.name),
    sqlName: /CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?["`\[]?([^\s("`\]]+)/i.exec(ddl)?.[1] ?? String(raw.name),
    columns: columns.map((column, index) => ({ column, sourceName: sourceNames[index] ?? column, label: labels[index] ?? column,
      type: new RegExp(`\\b${(sourceNames[index] ?? column).replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s+(TEXT|INTEGER|REAL|BLOB)\\b`, 'i').exec(ddl)?.[1]?.toUpperCase() ?? 'TEXT' })),
    sourceData, exportConfig: sqRecord(raw.exportConfig), updateConfig: sqRecord(raw.updateConfig) };
}

export function sqFillGuide(source: Readonly<Record<string, unknown>>): string {
  const labels: Record<string, string> = { note: '原表说明', initNode: '初始化规则', insertNode: '新增规则', updateNode: '更新规则', deleteNode: '删除规则' };
  return ['外部 SQL 中 row_id 对应本表 rowid；实际写入使用当前表结构给出的物理表名与列名。',
    ...Object.entries(labels).flatMap(([key, label]) => typeof source[key] === 'string' && source[key] ? [`${label}：\n${source[key]}`] : [])].join('\n\n');
}
