import { evaluateConditionBoolean } from '../conditions/evaluator.js';
import { tryParseCondition } from '../conditions/parser.js';
import { isConditionRecord, type ConditionSnapshot, type ConditionValue } from '../conditions/types.js';

/**
 * 数据中心的 IF 语法。
 *
 * 两个用途共用同一套条件表达式（`src/conditions` 的 DSL，不另造语言）：
 * - 写入侧：填表模型可以产出 `IF <条件> THEN <SQL>`，条件不成立就跳过这条写入。
 * - 注入侧：每张表可以配一个注入条件，条件不成立时这张表的行不进提示词。
 *
 * 条件里能读到两部分数据：生成条件上下文（变量、世界书、剧情时间、手机状态，与「规则门控」同源），
 * 以及本模块补上的 `sheets`——数据中心自己的表内容。
 */

/** 条件里可读的表数据来源；`SheetContent` 结构上满足这个形状，因此不需要反向依赖引擎。 */
export interface SheetConditionSource {
  readonly sheet: {
    readonly id: string;
    readonly name: string;
    readonly purpose: string;
    readonly policy: string;
  };
  readonly columns: readonly string[];
  readonly labels: readonly string[];
  readonly rows: readonly { readonly rowId: number; readonly values: readonly string[] }[];
}

export type ConditionalStatement =
  | { readonly kind: 'plain'; readonly sql: string }
  | { readonly kind: 'conditional'; readonly condition: string; readonly sql: string }
  | { readonly kind: 'invalid'; readonly raw: string; readonly reason: string };

export interface SheetConditionOutcome {
  readonly passed: boolean;
  /** 条件语法或求值出错时的说明；`passed` 一律按 false 处理，不静默当成成立。 */
  readonly error?: string;
}

/**
 * 快照里每张表最多带多少行。
 * 与 `DEFAULT_CONDITION_LIMITS.maxArrayLength` 对齐：再多也会被 `createConditionSnapshot` 截掉，
 * 显式截断可以让 `count` 与 `rows.length` 的差异有明确含义。
 */
const CONDITION_ROW_LIMIT = 64;

function isWordBoundary(text: string, start: number, length: number): boolean {
  const before = text[start - 1] ?? ' ';
  const after = text[start + length] ?? ' ';
  return !/[A-Za-z0-9_]/.test(before) && !/[A-Za-z0-9_]/.test(after);
}

/** 在引号外查找关键字：条件表达式里的字符串字面量可能包含 `THEN` 字样。 */
function findKeywordOutsideQuotes(text: string, keyword: string, from: number): number {
  let quote: string | null = null;
  for (let index = from; index < text.length; index += 1) {
    const char = text[index] ?? '';
    if (quote) {
      if (char === '\\') {
        index += 1;
        continue;
      }
      if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'') {
      quote = char;
      continue;
    }
    if (text.slice(index, index + keyword.length).toUpperCase() === keyword
      && isWordBoundary(text, index, keyword.length)) {
      return index;
    }
  }
  return -1;
}

/**
 * 解析一条可能带 IF 前缀的语句。
 * 不做 SQL 合法性判断，也不做条件求值——那分别是 `sql-guard` 与 `evaluateSheetCondition` 的职责。
 */
export function parseConditionalStatement(raw: string): ConditionalStatement {
  const text = raw.trim();
  if (!text) return { kind: 'invalid', raw, reason: '语句为空' };
  if (!/^IF\b/i.test(text)) return { kind: 'plain', sql: text };
  const thenIndex = findKeywordOutsideQuotes(text, 'THEN', 2);
  if (thenIndex < 0) return { kind: 'invalid', raw: text, reason: 'IF 语句缺少 THEN' };
  const condition = text.slice(2, thenIndex).trim();
  const sql = text.slice(thenIndex + 4).trim();
  if (!condition) return { kind: 'invalid', raw: text, reason: 'IF 与 THEN 之间没有条件' };
  if (!sql) return { kind: 'invalid', raw: text, reason: 'THEN 后面没有 SQL' };
  return { kind: 'conditional', condition, sql };
}

/** 建表/改表时的早失败校验：条件语法错就别写进注册表，免得每轮注入时静默跳过。 */
export function validateSheetCondition(condition: string): string | null {
  const source = condition.trim();
  if (!source) return null;
  const { error } = tryParseCondition(source);
  return error ? error.message : null;
}

function rowRecord(source: SheetConditionSource, row: SheetConditionSource['rows'][number]): ConditionValue {
  const record: Record<string, ConditionValue> = { rowId: row.rowId };
  source.columns.forEach((column, index) => {
    record[column] = row.values[index] ?? '';
    const label = source.labels[index];
    // 中文标签也当作可读键：条件里写 `sheets.角色位置.first.当前地点` 比记英文列名顺手。
    if (label && label !== column && !(label in record)) record[label] = row.values[index] ?? '';
  });
  return record;
}

/**
 * 把表内容变成条件可读的数据：`sheets.<表名>` 下挂 count / columns / rows / first / last。
 * `rows` 只带前 `CONDITION_ROW_LIMIT` 行，`count` 始终是真实行数。
 */
export function buildSheetConditionData(sources: readonly SheetConditionSource[]): ConditionValue {
  const sheets: Record<string, ConditionValue> = {};
  for (const source of sources) {
    const rows = source.rows.slice(0, CONDITION_ROW_LIMIT).map((row) => rowRecord(source, row));
    const firstRow = source.rows[0];
    const lastRow = source.rows[source.rows.length - 1];
    sheets[source.sheet.name] = {
      id: source.sheet.id,
      name: source.sheet.name,
      purpose: source.sheet.purpose,
      policy: source.sheet.policy,
      count: source.rows.length,
      columns: [...source.columns],
      labels: [...source.labels],
      rows,
      first: firstRow ? rowRecord(source, firstRow) : null,
      last: lastRow ? rowRecord(source, lastRow) : null,
    };
  }
  return { sheets, sheetCount: sources.length };
}

/**
 * 把表数据合并进已有条件快照。基础快照来自生成上下文，因此变量、世界书、剧情时间等路径保持可用。
 * 这里不重新 sanitize：调用方拿到的 data 会交给 `createConditionSnapshot` 统一收口。
 */
export function mergeSheetConditionData(
  base: ConditionValue,
  sources: readonly SheetConditionSource[],
): ConditionValue {
  const sheetData = buildSheetConditionData(sources);
  if (!isConditionRecord(base) || !isConditionRecord(sheetData)) return sheetData;
  return { ...base, ...sheetData };
}

/** 统一求值口子：语法错、求值超限、路径缺失一律按「条件不成立」处理并带回原因。 */
export function evaluateSheetCondition(
  condition: string,
  snapshot: ConditionSnapshot,
): SheetConditionOutcome {
  const source = condition.trim();
  if (!source) return { passed: true };
  const result = evaluateConditionBoolean(source, snapshot);
  if (!result.ok) return { passed: false, error: result.error?.message ?? '条件求值失败' };
  return { passed: result.value === true };
}