import type { PhoneEvent } from '../domain/events.js';
import type { AppId } from '../domain/model.js';
import { phoneLogger } from './logger.js';

interface PhoneEventLog {
  readonly message: string;
  readonly detail?: Readonly<Record<string, unknown>>;
}

const APP_LABELS: Readonly<Record<AppId, string>> = {
  wechat: '微信',
  forum: '论坛',
  anonymous: '匿名交友',
  twitter: 'X 动态',
};

function appLabel(appId: AppId): string {
  return APP_LABELS[appId];
}

export function describePhoneEvent(event: PhoneEvent): PhoneEventLog {
  switch (event.type) {
    case 'profile.upserted':
      return {
        message: event.payload.profile.id === 'profile:self' ? '个人资料已保存' : '联系人资料已保存',
        detail: { eventType: event.type, profileId: event.payload.profile.id },
      };
    case 'profile.deleted':
      return { message: '联系人已删除', detail: { eventType: event.type, profileId: event.payload.profileId } };
    case 'conversation.upserted':
      return {
        message: `${appLabel(event.payload.conversation.appId)}会话已保存`,
        detail: { eventType: event.type, conversationId: event.payload.conversation.id },
      };
    case 'conversation.deleted':
      return { message: '微信会话已删除', detail: { eventType: event.type, conversationId: event.payload.conversationId } };
    case 'conversation.read':
      return { message: '会话已标记为已读', detail: { eventType: event.type, conversationId: event.payload.conversationId } };
    case 'message.queued':
      return {
        message: `${appLabel(event.payload.message.appId)}消息已加入回复队列`,
        detail: { eventType: event.type, messageId: event.payload.message.id, kind: event.payload.message.kind ?? 'text' },
      };
    case 'message.received':
      return {
        message: `${appLabel(event.payload.message.appId)}收到新消息`,
        detail: { eventType: event.type, messageId: event.payload.message.id, kind: event.payload.message.kind ?? 'text' },
      };
    case 'message.claimed':
      return {
        message: event.payload.claimStatus === 'claimed' ? '消息互动已领取' : '消息互动已拒绝',
        detail: { eventType: event.type, messageId: event.payload.messageId },
      };
    case 'message.deleted':
      return { message: '待处理消息已删除', detail: { eventType: event.type, messageId: event.payload.messageId } };
    case 'post.queued':
      return {
        message: `${appLabel(event.payload.post.appId)}动态已加入回复队列`,
        detail: { eventType: event.type, postId: event.payload.post.id, kind: event.payload.post.kind },
      };
    case 'post.created':
      return {
        message: `${appLabel(event.payload.post.appId)}新增动态`,
        detail: { eventType: event.type, postId: event.payload.post.id, kind: event.payload.post.kind },
      };
    case 'post.deleted':
      return { message: '未回复帖子已删除', detail: { eventType: event.type, postId: event.payload.postId } };
    case 'forum.board.created':
      return { message: '论坛板块已创建', detail: { eventType: event.type, boardId: event.payload.board.id } };
    case 'forum.board.updated':
      return { message: '论坛板块已更新', detail: { eventType: event.type, boardId: event.payload.board.id } };
    case 'forum.board.deleted':
      return { message: '论坛板块已删除', detail: { eventType: event.type, boardId: event.payload.boardId } };
    case 'forum.board.renamed':
      return {
        message: event.payload.name ? '论坛板块归属已迁移' : '论坛板块已并回默认板块',
        detail: { eventType: event.type, previousName: event.payload.previousName, name: event.payload.name },
      };
    case 'forum.item.deleted':
      return { message: '论坛内容已删除', detail: { eventType: event.type, itemId: event.payload.itemId } };
    case 'interaction.created':
      return {
        message: `${appLabel(event.payload.interaction.appId)}互动已记录`,
        detail: { eventType: event.type, interactionId: event.payload.interaction.id, kind: event.payload.interaction.type },
      };
    case 'interaction.deleted':
      return {
        message: '互动已取消',
        detail: { eventType: event.type, interactionId: event.payload.interactionId },
      };
    case 'batch.started':
      return {
        message: '内容生成批次已开始',
        detail: { eventType: event.type, batchId: event.payload.batch.id, outboxCount: event.payload.batch.outboxIds.length },
      };
    case 'batch.completed':
      return {
        message: '内容生成批次已完成',
        detail: {
          eventType: event.type,
          batchId: event.payload.batchId,
          completed: event.payload.completedOutboxIds.length,
          queued: event.payload.queuedOutboxIds.length,
        },
      };
    case 'batch.failed':
      return {
        message: '内容生成批次失败',
        detail: { eventType: event.type, batchId: event.payload.batchId, error: event.payload.error },
      };
    case 'clock.advanced':
      return {
        message: '剧情时间已更新',
        detail: { eventType: event.type, source: event.payload.clock.source, reason: event.payload.clock.reason },
      };
    case 'summary.recorded':
      return {
        message: '手机内容总结已保存',
        detail: { eventType: event.type, summaryId: event.payload.summary.id, sourceCount: event.payload.summary.sourceCount },
      };
    case 'pxx.products.added':
      return { message: 'PXX 商品已添加', detail: { eventType: event.type, count: event.payload.products.length } };
    case 'calendar.festival.upserted':
      return { message: '日历节日已保存', detail: { eventType: event.type, date: event.payload.festival.date } };
    case 'calendar.festival.removed':
      return { message: '日历节日已删除', detail: { eventType: event.type, date: event.payload.date } };
    case 'diary.baseline.set':
      return { message: '日记记录基线已更新', detail: { eventType: event.type } };
    case 'diary.entry.recorded':
      return { message: '新日记已保存', detail: { eventType: event.type, entryId: event.payload.entry.id } };
    case 'diary.entry.removed':
      return { message: '日记已删除', detail: { eventType: event.type, entryId: event.payload.entryId } };
    case 'memory.baseline.set':
      return { message: '记忆整理基线已更新', detail: { eventType: event.type, floor: event.payload.floor } };
    case 'memory.floors.invalidated':
      return {
        message: '记忆楼层范围已失效',
        detail: { eventType: event.type, fromFloor: event.payload.fromFloor, resumeAfterFloor: event.payload.resumeAfterFloor },
      };
    case 'memory.item.recorded':
      return {
        message: '记忆条目已保存',
        detail: { eventType: event.type, memoryId: event.payload.item.id, kind: event.payload.item.kind },
      };
    case 'memory.item.updated':
      return { message: '记忆条目已更新', detail: { eventType: event.type, memoryId: event.payload.item.id } };
    case 'memory.item.removed':
      return { message: '记忆条目已删除', detail: { eventType: event.type, memoryId: event.payload.itemId } };
    case 'timeline.events.recorded':
      return { message: '剧情时间线已更新', detail: { eventType: event.type, count: event.payload.events.length } };
    case 'timeline.event.removed':
      return { message: '剧情时间线事件已删除', detail: { eventType: event.type, eventId: event.payload.eventId } };
    case 'dynamic-worldbook.baseline.set':
      return { message: '动态世界书基线已建立', detail: { eventType: event.type, floor: event.payload.floor, count: event.payload.entries.length } };
    case 'dynamic-worldbook.optimized':
      return { message: '动态世界书已更新', detail: { eventType: event.type, floor: event.payload.floor, count: event.payload.updates.length } };
    case 'dynamic-worldbook.invalidated':
      return { message: '动态世界书已回退', detail: { eventType: event.type, fromFloor: event.payload.fromFloor } };
    case 'dynamic-worldbook.entry.edited':
      return { message: '动态世界书条目已手动编辑', detail: { eventType: event.type, key: event.payload.entry.key } };
    case 'dynamic-worldbook.cleared':
      return { message: '动态世界书已清除', detail: { eventType: event.type } };
    case 'fanfic.narrative.advanced':
      return { message: '同人剧情状态已推进', detail: { eventType: event.type, floor: event.payload.floor } };
    case 'fanfic.narrative.invalidated':
      return { message: '同人剧情状态已回滚', detail: { eventType: event.type, fromFloor: event.payload.fromFloor } };
    case 'fanfic.narrative.replaced':
      return { message: '同人剧情状态已手动修正', detail: { eventType: event.type, floor: event.payload.narrative.lastFloor } };
    case 'fanfic.narrative.cleared':
      return { message: '同人剧情状态已清除', detail: { eventType: event.type } };
  }
}

export function logPhoneEvents(events: readonly PhoneEvent[]): void {
  for (const event of events) {
    const log = describePhoneEvent(event);
    phoneLogger.info(log.message, log.detail);
  }
}