import type { CalendarFestival } from '../domain/model.js';
import type { StoryFloorSnapshot } from '../integration/sillytavern-bridge.js';

const DAY_MS = 86_400_000;

/** 剧情时间戳所在日的 00:00（本地时区）。 */
export function startOfStoryDay(timestamp: number): number {
  const date = new Date(timestamp);
  return new Date(date.getFullYear(), date.getMonth(), date.getDate()).getTime();
}

/** 剧情时间戳 → 日期键（YYYY-MM-DD）。 */
export function storyDateKey(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${date.getFullYear()}-${pad(date.getMonth() + 1)}-${pad(date.getDate())}`;
}

export interface DiaryTriggerDecision {
  /** 是否到达写日记的时间跨度。 */
  readonly due: boolean;
  /** 建议覆盖的范围起点（= 上次覆盖点）。 */
  readonly from: number;
  /** 建议覆盖的范围终点（当前剧情日的 00:00，只写已完整结束的日子）。 */
  readonly to: number;
}

/**
 * 判断是否应该写日记：
 * 距上次覆盖点已经过去了 intervalDays 个完整的剧情日（正在进行中的当天不算）。
 */
export function evaluateDiaryTrigger(
  coveredUntil: number,
  storyNow: number,
  intervalDays: number,
): DiaryTriggerDecision {
  const to = startOfStoryDay(storyNow);
  const from = coveredUntil;
  if (from <= 0) return { due: false, from, to };
  const interval = Math.max(1, Math.round(intervalDays)) * DAY_MS;
  return { due: to - from >= interval, from, to };
}

/** 日记覆盖范围的人类可读标签：单日「8月12日」，跨天「8月10日 ~ 8月12日」。 */
export function describeDiaryRange(coveredFrom: number, coveredUntil: number): string {
  const label = (timestamp: number) => {
    const date = new Date(timestamp);
    return `${date.getMonth() + 1}月${date.getDate()}日`;
  };
  const first = label(coveredFrom);
  // 覆盖终点是次日 00:00，往回拨 1 分钟取最后一天。
  const last = label(Math.max(coveredFrom, coveredUntil - 60_000));
  return first === last ? first : `${first} ~ ${last}`;
}

export interface DiaryPromptInput {
  /** 日记作者（用户）的名字。 */
  readonly userName: string;
  /** 覆盖范围标签（如「8月12日」）。 */
  readonly rangeLabel: string;
  /** 覆盖范围内的手机记录摘要（无记录时为 null）。 */
  readonly digestText: string | null;
  /** 正文最新楼层，作为这段日子的剧情素材。 */
  readonly recentStory: readonly StoryFloorSnapshot[];
  /** 覆盖范围内的节日/事件。 */
  readonly festivals: readonly CalendarFestival[];
  /** 当前实际启用的世界书摘要。 */
  readonly worldBookExcerpt?: string | null;
}

export interface DiaryPrompt {
  readonly system: string;
  readonly user: string;
}

/** 构建日记生成提示词：第一人称、按时间顺序详述这段日子发生了什么。 */
export function buildDiaryPrompt(input: DiaryPromptInput): DiaryPrompt {
  const system = [
    `你是「${input.userName}」本人，正在睡前写自己的日记。`,
    ...(input.worldBookExcerpt?.trim()
      ? ['日记必须遵循当前世界书摘要中的时代、身份、世界观事实、内容边界和表达要求；世界书与通用日记习惯冲突时，以世界书为准。']
      : ['没有提供世界书摘要时，不要擅自假设未给出的时代、身份或生活方式。']),
    '- 用第一人称「我」回顾这段时间发生的事，按时间顺序自然叙述；时间段和叙述结构以世界书及素材允许的方式为准。',
    '- 以提供的手机聊天记录、社交动态与正文剧情为事实依据；材料没提到的空档只能在不违背世界书的前提下简略带过，不得用固定的日常活动模板填充，也不得虚构重大事件。',
    '- 提到别人时直接用名字；写出当时的心情和一两个具体细节，像真人日记，不要写成流水账汇报或工作总结。',
    '- 只输出日记正文纯文本：不要标题、不要日期抬头、不要 Markdown、不要任何解释；篇幅 150~450 字。',
  ].join('\n');

  const festivalLines = input.festivals.length > 0
    ? `这段时间的节日/事件：${input.festivals.map((festival) => `${festival.name}（${festival.description || '无备注'}）`).join('；')}\n`
    : '';
  const storyLines = input.recentStory.length > 0
    ? input.recentStory.map((floor) => `${floor.name}：${floor.text}`).join('\n')
    : '（无）';
  const user = [
    `日记覆盖的日子：${input.rangeLabel}`,
    festivalLines,
    '【这段时间的手机记录】',
    input.digestText ?? '（这段时间手机上没有留下记录；只依据正文剧情和世界书中的已知事实书写，不要补造空档活动）',
    '',
    '【正文剧情片段（最近楼层，供参考）】',
    storyLines,
    ...(input.worldBookExcerpt?.trim() ? ['', '【当前启用世界书摘要】', input.worldBookExcerpt.trim()] : []),
  ].join('\n');

  return { system, user };
}
