/**
 * 原著库与导入资料的本地存储（IndexedDB）。
 * 原著全文体量可能很大，不进入手机状态，也不写入酒馆聊天元数据；
 * 每个聊天作用域保存一份已建立的原著库，以及可重建它的原始导入文档。
 */

import type { CanonLibrary } from '../fanfic/model.js';

const DB_NAME = 'narrative_phone_canon';
const DB_VERSION = 1;
const LIBRARY_STORE = 'libraries';
const IMPORT_STORE = 'imports';

export interface CanonImportDocument {
  readonly id: string;
  readonly scopeId: string;
  readonly name: string;
  readonly text: string;
  readonly updatedAt: number;
}

interface StoredLibraryRecord {
  readonly scopeId: string;
  readonly library: CanonLibrary;
  readonly savedAt: number;
}

let dbPromise: Promise<IDBDatabase> | null = null;

function openDatabase(): Promise<IDBDatabase> {
  if (dbPromise) return dbPromise;
  dbPromise = new Promise((resolve, reject) => {
    const request = indexedDB.open(DB_NAME, DB_VERSION);
    request.onupgradeneeded = () => {
      const db = request.result;
      if (!db.objectStoreNames.contains(LIBRARY_STORE)) {
        db.createObjectStore(LIBRARY_STORE, { keyPath: 'scopeId' });
      }
      if (!db.objectStoreNames.contains(IMPORT_STORE)) {
        const store = db.createObjectStore(IMPORT_STORE, { keyPath: 'id' });
        store.createIndex('scopeId', 'scopeId');
      }
    };
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => {
      dbPromise = null;
      reject(request.error ?? new Error('无法打开原著库存储。'));
    };
  });
  return dbPromise;
}

function requestAsPromise<T>(request: IDBRequest<T>): Promise<T> {
  return new Promise((resolve, reject) => {
    request.onsuccess = () => resolve(request.result);
    request.onerror = () => reject(request.error ?? new Error('原著库存储操作失败。'));
  });
}

function transactionSettled(transaction: IDBTransaction): Promise<void> {
  return new Promise((resolve, reject) => {
    transaction.oncomplete = () => resolve();
    transaction.onerror = () => reject(transaction.error ?? new Error('原著库事务失败。'));
    transaction.onabort = () => reject(transaction.error ?? new Error('原著库事务已取消。'));
  });
}

export async function loadCanonLibrary(scopeId: string): Promise<CanonLibrary | null> {
  try {
    const db = await openDatabase();
    const tx = db.transaction(LIBRARY_STORE, 'readonly');
    const record = await requestAsPromise<StoredLibraryRecord | undefined>(
      tx.objectStore(LIBRARY_STORE).get(scopeId) as IDBRequest<StoredLibraryRecord | undefined>,
    );
    return record?.library ?? null;
  } catch {
    return null;
  }
}

export async function saveCanonLibrary(scopeId: string, library: CanonLibrary): Promise<void> {
  const db = await openDatabase();
  const tx = db.transaction(LIBRARY_STORE, 'readwrite');
  tx.objectStore(LIBRARY_STORE).put({ scopeId, library, savedAt: Date.now() } satisfies StoredLibraryRecord);
  await transactionSettled(tx);
}

export async function clearCanonLibrary(scopeId: string): Promise<void> {
  try {
    const db = await openDatabase();
    const tx = db.transaction(LIBRARY_STORE, 'readwrite');
    tx.objectStore(LIBRARY_STORE).delete(scopeId);
    await transactionSettled(tx);
  } catch {
    // 库不存在时无需处理。
  }
}

export async function listCanonImports(scopeId: string): Promise<readonly CanonImportDocument[]> {
  try {
    const db = await openDatabase();
    const tx = db.transaction(IMPORT_STORE, 'readonly');
    const records = await requestAsPromise<CanonImportDocument[]>(
      tx.objectStore(IMPORT_STORE).index('scopeId').getAll(scopeId) as IDBRequest<CanonImportDocument[]>,
    );
    return records.slice().sort((left, right) => left.updatedAt - right.updatedAt);
  } catch {
    return [];
  }
}

/**
 * 保存一份导入资料。
 * 原著全文不再按字数截断：长篇小说整本导入也会完整保留，
 * 只有浏览器存储真的写不下时才失败，并把原因照实告诉用户。
 */
export async function saveCanonImport(
  scopeId: string,
  name: string,
  text: string,
): Promise<CanonImportDocument> {
  const normalized = text.replace(/\0/g, '');
  if (!normalized.trim()) throw new Error('导入文件内容为空。');
  const document: CanonImportDocument = {
    id: `${scopeId}|${name}`,
    scopeId,
    name: name.trim() || '未命名资料',
    text: normalized,
    updatedAt: Date.now(),
  };
  const db = await openDatabase();
  const tx = db.transaction(IMPORT_STORE, 'readwrite');
  tx.objectStore(IMPORT_STORE).put(document);
  try {
    await transactionSettled(tx);
  } catch (error) {
    throw describeWriteFailure(error, normalized.length);
  }
  return document;
}

/** 写入失败大多是浏览器存储配额不足：给出可执行的提示而不是原始报错。 */
function describeWriteFailure(error: unknown, charCount: number): Error {
  const name = error instanceof DOMException ? error.name : '';
  const message = error instanceof Error ? error.message : String(error ?? '未知错误');
  if (name === 'QuotaExceededError' || /quota|storage/i.test(message)) {
    return new Error(
      `浏览器存储空间不足，${charCount} 字的资料没能写入。可以先清理旧的导入资料，或把原著拆成几份分别导入。`,
    );
  }
  return new Error(`保存导入资料失败：${message}`);
}

export async function removeCanonImport(documentId: string): Promise<void> {
  const db = await openDatabase();
  const tx = db.transaction(IMPORT_STORE, 'readwrite');
  tx.objectStore(IMPORT_STORE).delete(documentId);
  await transactionSettled(tx);
}

export async function clearCanonImports(scopeId: string): Promise<void> {
  const documents = await listCanonImports(scopeId);
  if (documents.length === 0) return;
  const db = await openDatabase();
  const tx = db.transaction(IMPORT_STORE, 'readwrite');
  for (const document of documents) tx.objectStore(IMPORT_STORE).delete(document.id);
  await transactionSettled(tx);
}