/**
 * MVU 映射的规范化与查询。
 *
 * 映射是「变量路径 ↔ 表格坐标」的唯一真值来源：
 * 正向投影（表 → `stat_data`）与反向翻译（旧脚本 `_.set` → SQL）都查它，
 * 因此值的类型也存在映射里，投影时按类型还原，不靠猜。
 */

import type { MvuMapping, MvuMappingEntry, MvuValueType } from './types.js';
import type { MvuScalar } from './mvu-tuple.js';

const LIST_SEPARATOR = '、';
const MAPPING_LIMIT = 4_000;

function text(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

function valueType(value: unknown): MvuValueType {
  return value === 'number' || value === 'boolean' || value === 'list' || value === 'json' ? value : 'string';
}

/** 规范化持久化的映射；结构不对就返回 undefined，让调用方按「没有映射」处理。 */
export function normalizeMvuMapping(value: unknown): MvuMapping | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const raw = (value as Record<string, unknown>).entries;
  if (!Array.isArray(raw)) return undefined;
  const seen = new Set<string>();
  const entries: MvuMappingEntry[] = [];
  for (const item of raw) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) continue;
    const record = item as Record<string, unknown>;
    const path = text(record.path).trim();
    const sheet = text(record.sheet).trim();
    const column = text(record.column).trim();
    if (!path || !sheet || !column || seen.has(path)) continue;
    seen.add(path);
    entries.push({
      path,
      sheet,
      column,
      keyColumn: text(record.keyColumn).trim(),
      keyValue: text(record.keyValue),
      desc: text(record.desc),
      valueType: valueType(record.valueType),
      readOnly: record.readOnly === true,
      ...(typeof record.defaultValue === 'string' ? { defaultValue: record.defaultValue } : {}),
      ...(record.nullable === true ? { nullable: true } : {}),
      ...(record.optional === true ? { optional: true } : {}),
      ...(record.constraints && typeof record.constraints === 'object' ? { constraints: record.constraints as MvuMappingEntry['constraints'] } : {}),
      ...(record.dynamic && typeof record.dynamic === 'object'
        && Array.isArray((record.dynamic as Record<string, unknown>).prefix)
        && Array.isArray((record.dynamic as Record<string, unknown>).field)
        ? { dynamic: { prefix: ((record.dynamic as Record<string, unknown>).prefix as unknown[]).map(text), field: ((record.dynamic as Record<string, unknown>).field as unknown[]).map(text) } } : {}),
    });
    if (entries.length >= MAPPING_LIMIT) break;
  }
  return entries.length > 0 ? { version: 1, entries } : undefined;
}

export function isEmptyMapping(mapping: MvuMapping | undefined): boolean {
  return !mapping || mapping.entries.length === 0;
}

/** 合并两份映射：按变量路径去重，后者覆盖前者；两边都空时返回 undefined。 */
export function mergeMvuMappings(
  current: MvuMapping | undefined,
  incoming: MvuMapping | undefined,
): MvuMapping | undefined {
  if (isEmptyMapping(current)) return isEmptyMapping(incoming) ? undefined : incoming;
  if (isEmptyMapping(incoming)) return current;
  const merged = new Map<string, MvuMappingEntry>();
  for (const entry of current!.entries) merged.set(entry.path, entry);
  for (const entry of incoming!.entries) merged.set(entry.path, entry);
  return { version: 1, entries: [...merged.values()] };
}

/** 按变量路径查映射；路径大小写与空格敏感，与 MVU 的 `_.set` 写法一致。 */
export function findMappingEntry(mapping: MvuMapping, path: string): MvuMappingEntry | null {
  const target = path.trim();
  return mapping.entries.find((entry) => entry.path === target) ?? null;
}

/** 按表名分组，投影时一次读一张表。 */
export function groupMappingBySheet(mapping: MvuMapping): ReadonlyMap<string, readonly MvuMappingEntry[]> {
  const grouped = new Map<string, MvuMappingEntry[]>();
  for (const entry of mapping.entries) {
    const bucket = grouped.get(entry.sheet);
    if (bucket) bucket.push(entry);
    else grouped.set(entry.sheet, [entry]);
  }
  return grouped;
}

/**
 * 单元格文本 → 变量值：按映射里记下的类型还原，避免把 `"123"` 猜成数字。
 * `json` 是结构值（对象数组这类）的存法，原样解析回去；解析不了就当普通文本，不丢数据。
 */
export function parseCellValue(cell: string, type: MvuValueType, nullable = false): unknown {
  if (nullable && cell === 'null') return null;
  if (type === 'json') {
    try {
      return JSON.parse(cell.trim() || 'null') as unknown;
    } catch {
      return cell;
    }
  }
  if (type === 'list') {
    if (cell.trim().startsWith('[')) {
      try { const value: unknown = JSON.parse(cell); if (Array.isArray(value)) return value; } catch { /* 兼容旧的顿号列表。 */ }
    }
    const items = cell.split(LIST_SEPARATOR).map((item) => item.trim()).filter(Boolean);
    return items;
  }
  if (type === 'number') {
    const parsed = Number(cell.trim());
    return Number.isFinite(parsed) ? parsed : cell;
  }
  if (type === 'boolean') {
    const normalized = cell.trim().toLowerCase();
    if (['true', '1', '是', 'yes'].includes(normalized)) return true;
    if (['false', '0', '否', 'no', ''].includes(normalized)) return false;
    return cell;
  }
  return cell;
}

/** 变量值 → 单元格文本；列表用中文顿号连接，与转换时的写法保持一致。 */
export function formatCellValue(value: unknown, type?: MvuValueType): string {
  if (type === 'json') {
    if (typeof value === 'string') {
      try { JSON.parse(value); return value; } catch { return JSON.stringify(value); }
    }
    return JSON.stringify(value ?? null);
  }
  if (value === null || value === undefined) return '';
  if (Array.isArray(value)) {
    if (value.some((item) => typeof item !== 'string' || item.includes(LIST_SEPARATOR))) return JSON.stringify(value);
    return value.map((item) => (item === null || item === undefined ? '' : String(item))).join(LIST_SEPARATOR);
  }
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value as MvuScalar);
}

/** 把路径写进嵌套对象，供投影拼装 `stat_data`。 */
export function assignByPath(target: Record<string, unknown>, path: string, value: unknown): void {
  assignBySegments(target, splitMvuPath(path), value);
}

/** 兼容旧映射；新映射直接携带 prefix / field，成员名与变量路径分开存储。 */
export function mappingDynamic(entry: MvuMappingEntry): MvuMappingEntry['dynamic'] {
  if (entry.dynamic) return entry.dynamic;
  if (!entry.keyColumn || !entry.keyValue) return undefined;
  const path = splitMvuPath(entry.path);
  const positions = path.flatMap((key, index) => key === entry.keyValue ? [index] : []);
  const at = positions.length === 1 ? positions[0] : undefined;
  return at === undefined ? undefined : { prefix: path.slice(0, at), field: path.slice(at + 1) };
}

export interface MvuMappingTarget {
  readonly entry: MvuMappingEntry;
  readonly keyValue: string;
  readonly jsonPath?: readonly string[];
}

export function resolveVariableTarget(mapping: MvuMapping, path: string): MvuMappingTarget | null {
  const segments = splitMvuPath(path);
  if (!segments.length) return null;
  const direct = findMappingEntry(mapping, path);
  if (direct && !direct.dynamic) return { entry: direct, keyValue: direct.keyValue };
  let json: MvuMappingTarget | null = null;
  for (const entry of mapping.entries) {
    const dynamic = mappingDynamic(entry);
    const keyValue = dynamic ? segments[dynamic.prefix.length] : entry.keyValue;
    const known = dynamic ? [...dynamic.prefix, keyValue ?? '', ...dynamic.field] : splitMvuPath(entry.path);
    if (!known.length || !keyValue && dynamic || !known.every((key, i) => key === segments[i])) continue;
    if (known.length === segments.length) return { entry, keyValue: keyValue ?? '' };
    if ((entry.valueType === 'json' || entry.valueType === 'list') && known.length < segments.length) {
      const jsonPath = segments.slice(known.length);
      if (!json || jsonPath.length < (json.jsonPath?.length ?? Infinity)) json = { entry, keyValue: keyValue ?? '', jsonPath };
    }
  }
  return json;
}

const UNSAFE_KEYS = new Set(['__proto__', 'prototype', 'constructor']);

/** 点路径和带引号的括号路径；成员名中的小数点保留为一个键。 */
export function splitMvuPath(path: string): readonly string[] {
  const segments: string[] = [];
  const pattern = /(?:^|\.)([^.\[\]]+)|\[\s*("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])*'|\d+)\s*\]/g;
  let consumed = 0;
  for (const match of path.matchAll(pattern)) {
    if (match.index !== consumed) return [];
    consumed += match[0].length;
    const token = match[1] ?? match[2] ?? '';
    let key = token.trim();
    if (match[2]?.startsWith('"')) { try { key = JSON.parse(match[2]) as string; } catch { return []; } }
    else if (match[2]?.startsWith("'")) key = match[2].slice(1, -1).replace(/\\(['\\])/g, '$1');
    if (UNSAFE_KEYS.has(key)) return [];
    if (key) segments.push(key);
  }
  return consumed === path.length ? segments : [];
}

export function joinMvuPath(segments: readonly string[]): string {
  return segments.map((key, index) => /[.\[\]"']/.test(key) ? `[${JSON.stringify(key)}]` : `${index ? '.' : ''}${key}`).join('');
}

export function assignBySegments(target: Record<string, unknown>, segments: readonly string[], value: unknown): void {
  if (segments.length === 0) return;
  if (segments.some((key) => UNSAFE_KEYS.has(key))) return;
  let current = target;
  for (let index = 0; index < segments.length - 1; index += 1) {
    const key = segments[index]!;
    const next = current[key];
    if (!next || typeof next !== 'object' || Array.isArray(next)) {
      const created: Record<string, unknown> = {};
      current[key] = created;
      current = created;
    } else {
      current = next as Record<string, unknown>;
    }
  }
  current[segments[segments.length - 1]!] = value;
}

/** 读取嵌套对象上的路径值。 */
export function readByPath(source: Record<string, unknown>, path: string): unknown {
  const segments = splitMvuPath(path);
  let current: unknown = source;
  for (const segment of segments) {
    if (!current || typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[segment];
  }
  return current;
}

/**
 * 把嵌套对象摊平成「路径 → 叶子值」。数组当成叶子（列表单元格），不再往下拆。
 * 用于 `replaceMvuData` 这类整体替换：对比前后差异才知道该写哪几格。
 */
export function flattenLeafPaths(
  value: unknown,
  prefix = '',
  depth = 0,
): ReadonlyMap<string, unknown> {
  const flat = new Map<string, unknown>();
  if (depth > 12 || !value || typeof value !== 'object' || Array.isArray(value)) {
    if (prefix) flat.set(prefix, value);
    return flat;
  }
  for (const [key, child] of Object.entries(value as Record<string, unknown>)) {
    if (UNSAFE_KEYS.has(key)) continue;
    const path = joinMvuPath([...splitMvuPath(prefix), key]);
    if (child && typeof child === 'object' && !Array.isArray(child)) {
      const nested = flattenLeafPaths(child, path, depth + 1);
      if (nested.size === 0) flat.set(path, {});
      else for (const [nestedPath, nestedValue] of nested) flat.set(nestedPath, nestedValue);
    } else {
      flat.set(path, child);
    }
  }
  return flat;
}
