/** MVU Zod 结构的公共入口；结构、默认值与约束由有界 AST 解析器读取。 */
import { readStaticMvuSchema } from './zod-static.js';
import type { MvuTree } from './types.js';

export interface MvuSchemaParseResult {
  readonly tree: MvuTree;
  readonly issues: readonly string[];
}

export function looksLikeMvuSchemaScript(content: string): boolean {
  if (/registerMvuSchema\s*\(/.test(content)) return true;
  return /\bz\s*\.\s*object\s*\(\s*\{/.test(content) && /\.(?:prefault|default)\s*\(/.test(content);
}

/** 保留供旧调用方使用的注释清理工具。 */
export function stripScriptComments(script: string): string {
  let output = '';
  let quote: '"' | '\'' | '`' | null = null;
  for (let index = 0; index < script.length; index += 1) {
    const char = script[index] ?? '';
    if (quote) {
      output += char;
      if (char === '\\') {
        output += script[index + 1] ?? '';
        index += 1;
        continue;
      }
      if (char === quote) quote = null;
      continue;
    }
    if (char === '"' || char === '\'' || char === '`') {
      quote = char;
      output += char;
      continue;
    }
    if (char === '/' && script[index + 1] === '/') {
      while (index < script.length && script[index] !== '\n') index += 1;
      output += '\n';
      continue;
    }
    if (char === '/' && script[index + 1] === '*') {
      const close = script.indexOf('*/', index + 2);
      index = close < 0 ? script.length : close + 1;
      continue;
    }
    output += char;
  }
  return output;
}

export function parseMvuSchemaScript(script: string): MvuSchemaParseResult {
  return readStaticMvuSchema(script);
}
