import { EXTENSION_MODULE_MAX_DATA_BYTES, type ExtensionModuleStorage } from './module-contract.js';

const MODULE_DATA_KEY = 'moduleData';

export interface ModuleStorageSettingsContext {
  readonly extensionSettings?: Record<string, unknown>;
  readonly saveSettingsDebounced?: () => void;
}

export type ModuleStorageContext = ModuleStorageSettingsContext | (() => ModuleStorageSettingsContext);

export class ExtensionModuleStorageService {
  readonly #context: ModuleStorageContext;
  readonly #moduleId: string;
  readonly #scopeId: string;

  constructor(context: ModuleStorageContext, moduleId: string, scopeId: string) {
    this.#context = context;
    this.#moduleId = moduleId;
    this.#scopeId = scopeId;
  }

  create(): ExtensionModuleStorage {
    return {
      get: async <T>(key: string) => this.#read<T>(key),
      set: async (key, value) => this.#write(key, value),
      remove: async (key) => this.#remove(key),
      clear: async () => this.#clear(),
    };
  }

  snapshot(): Readonly<Record<string, unknown>> {
    const value = this.#root(false)?.[this.#moduleId]?.[this.#scopeId];
    if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
    return structuredClone(value) as Readonly<Record<string, unknown>>;
  }

  async clearModule(): Promise<void> {
    const root = this.#root(false);
    if (!root) return;
    delete root[this.#moduleId];
    this.#settingsContext.saveSettingsDebounced?.();
  }

  #read<T>(key: string): T | undefined {
    validateKey(key);
    const value = this.#root(false)?.[this.#moduleId]?.[this.#scopeId]?.[key];
    return value === undefined ? undefined : structuredClone(value) as T;
  }

  #write(key: string, value: unknown): void {
    validateKey(key);
    const serialized = JSON.stringify(value);
    if (serialized === undefined || serialized.length > EXTENSION_MODULE_MAX_DATA_BYTES) {
      throw new Error(`模块数据不能超过 ${EXTENSION_MODULE_MAX_DATA_BYTES} 字节。`);
    }
    const root = this.#root(true) as Record<string, Record<string, Record<string, unknown>>>;
    const module = root[this.#moduleId] ?? (root[this.#moduleId] = {});
    const scope = module[this.#scopeId] ?? (module[this.#scopeId] = {});
    scope[key] = structuredClone(value);
    this.#settingsContext.saveSettingsDebounced?.();
  }

  #remove(key: string): void {
    validateKey(key);
    const scope = this.#root(false)?.[this.#moduleId]?.[this.#scopeId];
    if (!scope) return;
    delete scope[key];
    this.#settingsContext.saveSettingsDebounced?.();
  }

  #clear(): void {
    const module = this.#root(false)?.[this.#moduleId];
    if (!module) return;
    delete module[this.#scopeId];
    this.#settingsContext.saveSettingsDebounced?.();
  }

  get #settingsContext(): ModuleStorageSettingsContext {
    return typeof this.#context === 'function' ? this.#context() : this.#context;
  }

  #root(create: boolean): Record<string, Record<string, Record<string, Record<string, unknown>>>> | null {
    const settings = this.#settingsContext.extensionSettings;
    if (!settings) return null;
    const existing = settings[MODULE_DATA_KEY];
    if (existing && typeof existing === 'object' && !Array.isArray(existing)) {
      return existing as Record<string, Record<string, Record<string, Record<string, unknown>>>>;
    }
    if (!create) return null;
    const root: Record<string, Record<string, Record<string, Record<string, unknown>>>> = {};
    settings[MODULE_DATA_KEY] = root;
    return root;
  }
}

function validateKey(key: string): void {
  if (!/^[a-zA-Z0-9._-]{1,80}$/.test(key)) throw new Error('模块存储键只能使用字母、数字、点、下划线和短横线。');
}