import { SELF_PROFILE_ID } from '../domain/commands.js';
import { appLabelOf, type AppId, type PhoneState } from '../domain/model.js';
import { replaceImageMarkers } from '../generation/image-client.js';

/** 总结输入中把生图标记替换为占位，避免提示词混入总结。 */
const stripImageMarkers = replaceImageMarkers;

export interface PhoneContentDigest {
  /** 供总结模型阅读的纯文本记录。 */
  readonly text: string;
  /** 条目数量。 */
  readonly count: number;
  /** 最新条目的剧情时间戳（作为总结覆盖点）。 */
  readonly latestTimestamp: number;
}

export interface PhoneContentDigestOptions {
  /** 只统计到该剧情时间点（含）为止；日记等按时间段取材的场景使用。 */
  readonly until?: number;
  /** 个性化里停用的应用不参与总结。 */
  readonly disabledAppIds?: readonly string[];
  /** 个性化里的自定义应用名称；缺省回落到出厂名称。 */
  readonly appLabels?: Readonly<Record<string, string>>;
}

/**
 * 汇总 sinceTimestamp 之后产生的全部手机内容（消息 / 动态 / 互动），供 AI 总结。
 */
export function buildPhoneContentDigest(
  state: PhoneState,
  sinceTimestamp: number,
  options: PhoneContentDigestOptions = {},
): PhoneContentDigest | null {
  const untilTimestamp = options.until ?? Number.POSITIVE_INFINITY;
  const disabledApps = new Set(options.disabledAppIds ?? []);
  const describeApp = (appId: AppId): string => appLabelOf(appId, options.appLabels ?? {});
  const nameOf = (profileId: string): string => state.profiles[profileId]?.displayName
    ?? (profileId === SELF_PROFILE_ID ? '用户' : '未知');

  interface DigestLine {
    readonly timestamp: number;
    readonly section: string;
    readonly text: string;
  }
  const lines: DigestLine[] = [];

  const pendingPostIds = new Set(
    Object.values(state.outbox)
      .filter((item) => item.entityType === 'post' && item.status !== 'completed')
      .map((item) => item.entityId),
  );

  for (const message of Object.values(state.messages)) {
    if (message.createdAt <= sinceTimestamp || message.createdAt > untilTimestamp || disabledApps.has(message.appId)) continue;
    if (message.status === 'queued' || message.status === 'processing') continue;
    // 强行介入是给模型的幕后指令，不属于剧情内容，不写进正文摘要。
    if (message.kind === 'directive') continue;
    const conversation = state.conversations[message.conversationId];
    if (!conversation) continue;
    lines.push({
      timestamp: message.createdAt,
      section: `${describeApp(conversation.appId)}·${conversation.title}`,
      text: `${nameOf(message.profileId)}：${stripImageMarkers(message.content)}`,
    });
  }

  for (const post of Object.values(state.posts)) {
    if (post.createdAt <= sinceTimestamp || post.createdAt > untilTimestamp || pendingPostIds.has(post.id)
      || disabledApps.has(post.appId)) continue;
    const verb = post.kind.includes('reply') ? '回复' : post.kind.includes('repost') ? '转发' : '发布';
    lines.push({
      timestamp: post.createdAt,
      section: `${describeApp(post.appId)}·动态`,
      text: `${nameOf(post.profileId)}${verb}：${stripImageMarkers(post.content)}`,
    });
  }

  for (const interaction of Object.values(state.interactions)) {
    if (interaction.createdAt <= sinceTimestamp || interaction.createdAt > untilTimestamp
      || disabledApps.has(interaction.appId)) continue;
    const target = state.posts[interaction.targetId];
    const verb = interaction.type === 'like' ? '点赞' : '评论';
    const detail = interaction.type === 'like'
      ? `了「${truncate(target?.content ?? '', 20)}」`
      : `：${interaction.content ?? ''}`;
    lines.push({
      timestamp: interaction.createdAt,
      section: `${describeApp(interaction.appId)}·动态`,
      text: `${nameOf(interaction.actorProfileId)}${verb}${detail}`,
    });
  }

  if (lines.length === 0) return null;
  lines.sort((left, right) => left.timestamp - right.timestamp);
  const latestLine = lines[lines.length - 1];
  if (!latestLine) return null;

  const grouped = new Map<string, string[]>();
  for (const line of lines) {
    const list = grouped.get(line.section) ?? [];
    list.push(`[${formatTime(line.timestamp)}] ${line.text}`);
    grouped.set(line.section, list);
  }
  const sections = [...grouped.entries()].map(
    ([section, entries]) => `【${section}】\n${entries.join('\n')}`,
  );

  return {
    text: sections.join('\n\n'),
    count: lines.length,
    latestTimestamp: latestLine.timestamp,
  };
}

function truncate(text: string, limit: number): string {
  return text.length > limit ? `${text.slice(0, limit)}…` : text;
}

function formatTime(timestamp: number): string {
  const date = new Date(timestamp);
  const pad = (value: number) => String(value).padStart(2, '0');
  return `${pad(date.getMonth() + 1)}-${pad(date.getDate())} ${pad(date.getHours())}:${pad(date.getMinutes())}`;
}
