/**
 * 转换编排：MVU 资产 → 可入库的表格预设 + 变量映射 + 填表规则。
 *
 * 纯函数：输入是已经读好的世界书资产，输出是数据，落库与写卡都由调用方负责。
 * 这样面板可以先跑一遍拿预览，用户确认后再执行真正的写入。
 */

import { expandRecordMembers, listMvuLeafPaths, mergeMvuTrees, parseInitVarTree } from './init-var.js';
import { parseMvuSchemaScript } from './zod-schema.js';
import { planSheetsFromTree, type MvuSheetShape } from './tree-to-sheets.js';
import { applyFillGuides, buildAssetFillGuides } from './rules-to-prompt.js';
import { mvuMappingCoverage } from './coverage.js';
import { selectAssets } from './card-source.js';
import type { MvuAsset, MvuCardSource, MvuMapping, MvuTree } from './types.js';
import type { SheetPresetEntry } from '../db/sheet-preset.js';

export interface MvuSheetPreview {
  readonly name: string;
  readonly shape: MvuSheetShape;
  readonly columns: number;
  readonly rows: number;
  readonly policy: SheetPresetEntry['policy'];
  readonly hasGuide: boolean;
}

/** 变量结构的来源：Zod 脚本、InitVar 条目，或两者合并。 */
export type MvuStructureSource = 'zod' | 'json' | 'yaml' | 'zod+json' | 'zod+yaml';

export interface MvuConversionOutcome {
  readonly ruleSources: readonly MvuAsset[];
  readonly coverage: ReturnType<typeof mvuMappingCoverage>;
  readonly sheets: readonly SheetPresetEntry[];
  readonly mapping: MvuMapping;
  readonly sharedGuide: string;
  readonly issues: readonly string[];
  readonly format: MvuStructureSource;
  /** 变量叶子总数，与映射条数对比可以看出有多少变量没进表。 */
  readonly leafCount: number;
  readonly preview: readonly MvuSheetPreview[];
  /** 实际参与建表的资产名，面板上要让用户看清用的是哪一份。 */
  readonly usedAssets: readonly string[];
}

interface PickedTree {
  readonly tree: MvuTree;
  readonly format: MvuStructureSource;
  readonly issues: readonly string[];
  readonly usedAssets: readonly string[];
}

interface ParsedCandidate {
  readonly asset: MvuAsset;
  readonly tree: MvuTree;
  readonly leafCount: number;
  readonly issues: readonly string[];
  readonly format: 'json' | 'yaml';
}

function describeFailure(asset: MvuAsset, error: unknown): string {
  return `条目「${asset.name}」解析失败：${error instanceof Error ? error.message : String(error)}`;
}

/** 解析全部 InitVar 候选；标题命中的排在前面，同组内叶子多的优先。 */
function parseInitVarCandidates(source: MvuCardSource): {
  readonly candidates: readonly ParsedCandidate[];
  readonly failures: readonly string[];
} {
  const failures: string[] = [];
  const candidates: ParsedCandidate[] = [];
  for (const asset of selectAssets(source, 'initVar')) {
    try {
      const parsed = parseInitVarTree(asset.content);
      candidates.push({
        asset,
        tree: parsed.tree,
        leafCount: listMvuLeafPaths(parsed.tree).length,
        issues: parsed.issues,
        format: parsed.format,
      });
    } catch (error) {
      failures.push(describeFailure(asset, error));
    }
  }
  const rank = (candidate: ParsedCandidate): number => (candidate.asset.detectedBy === 'name' ? 0 : 1);
  return {
    candidates: [...candidates].sort((left, right) => rank(left) - rank(right) || right.leafCount - left.leafCount),
    failures,
  };
}

/** 解析全部 Zod 变量结构脚本，取字段最多的那份。 */
function parseSchemaTree(source: MvuCardSource): {
  readonly picked: { readonly asset: MvuAsset; readonly tree: MvuTree; readonly issues: readonly string[] } | null;
  readonly failures: readonly string[];
} {
  const failures: string[] = [];
  let picked: { asset: MvuAsset; tree: MvuTree; issues: readonly string[]; leafCount: number } | null = null;
  for (const asset of selectAssets(source, 'schema')) {
    try {
      const parsed = parseMvuSchemaScript(asset.content);
      const leafCount = listMvuLeafPaths(parsed.tree).length;
      if (!picked || leafCount > picked.leafCount) picked = { asset, tree: parsed.tree, issues: parsed.issues, leafCount };
    } catch (error) {
      failures.push(`脚本「${asset.name}」解析失败：${error instanceof Error ? error.message : String(error)}`);
    }
  }
  return { picked: picked ? { asset: picked.asset, tree: picked.tree, issues: picked.issues } : null, failures };
}

/**
 * 定出最终变量树。
 *
 * Zod 脚本提供结构（字段、类型、`_`/`$` 修饰、`z.record` 动态字典），InitVar 提供数据（实例与初值）。
 * 两者都在时合并：只取脚本会缺角色实例，只取 InitVar 会缺被作者关掉的字段与类型信息。
 */
function pickTree(source: MvuCardSource): PickedTree {
  const schema = parseSchemaTree(source);
  const initVar = parseInitVarCandidates(source);
  const main = initVar.candidates[0] ?? null;
  const extras = initVar.candidates.slice(1);
  const issues = [
    ...schema.failures,
    ...initVar.failures,
    ...(schema.picked?.issues ?? []),
    ...(main?.issues ?? []),
  ];
  if (extras.length > 0) {
    issues.push(`另有 ${extras.length} 份 InitVar 条目未参与建表：${extras.map((item) => item.asset.name).slice(0, 4).join('、')}。`);
  }

  if (schema.picked && main) {
    return {
      tree: expandRecordMembers(mergeMvuTrees(schema.picked.tree, main.tree)),
      format: main.format === 'yaml' ? 'zod+yaml' : 'zod+json',
      issues,
      usedAssets: [schema.picked.asset.name, main.asset.name],
    };
  }
  if (schema.picked) {
    return {
      tree: expandRecordMembers(schema.picked.tree),
      format: 'zod',
      issues,
      usedAssets: [schema.picked.asset.name],
    };
  }
  if (main) {
    return {
      tree: expandRecordMembers(main.tree),
      format: main.format,
      issues,
      usedAssets: [main.asset.name],
    };
  }
  const detail = [...initVar.failures, ...schema.failures].join('；');
  throw new Error(detail
    ? `这张卡里的变量结构都无法解析。${detail}`
    : '这张卡里没有找到 InitVar 变量条目，也没有 Zod 变量结构脚本，无法生成表结构。');
}

/** 执行转换。抛错只有一种情况：没有任何可用的变量结构来源。 */
export function convertMvuCard(source: MvuCardSource): MvuConversionOutcome {
  const picked = pickTree(source);
  const plan = planSheetsFromTree(picked.tree);
  const ruleSources = selectAssets(source, 'updateRules');
  const guides = buildAssetFillGuides(ruleSources, plan);
  const planned = applyFillGuides(plan, guides);
  const coverage = mvuMappingCoverage(picked.tree, planned.mapping);

  return {
    ruleSources,
    coverage,
    sheets: planned.entries.map((entry) => entry.sheet),
    mapping: planned.mapping,
    sharedGuide: guides.sharedGuide,
    issues: [...source.issues, ...picked.issues, ...planned.issues,
      ...(coverage.missing.length ? [`尚未映射的源路径：${coverage.missing.join('、')}`] : [])],
    format: picked.format,
    leafCount: listMvuLeafPaths(picked.tree).length,
    preview: planned.entries.map((entry) => ({
      name: entry.sheet.name,
      shape: entry.shape,
      columns: entry.sheet.columns.length,
      rows: entry.sheet.rows.length,
      policy: entry.sheet.policy,
      hasGuide: entry.sheet.fillGuide.trim().length > 0,
    })),
    usedAssets: picked.usedAssets,
  };
}

const SOURCE_LABELS: Readonly<Record<MvuStructureSource, string>> = Object.freeze({
  zod: 'Zod 变量结构脚本',
  json: 'InitVar JSON',
  yaml: 'InitVar YAML',
  'zod+json': 'Zod 结构 + InitVar JSON',
  'zod+yaml': 'Zod 结构 + InitVar YAML',
});

/** 转换结果的一句话摘要，给面板与通知用。 */
export function describeConversion(outcome: MvuConversionOutcome): string {
  const guided = outcome.preview.filter((item) => item.hasGuide).length;
  return `${outcome.sheets.length} 张表、${outcome.coverage.covered}/${outcome.coverage.declared} 个源路径已覆盖（含 JSON 子路径与动态模板）`
    + `，${guided} 张表带填表规则（来源：${SOURCE_LABELS[outcome.format]}）。`;
}

export interface MvuAssetSummary {
  readonly kind: string;
  readonly name: string;
  readonly book: string;
  readonly enabled: boolean;
  readonly chars: number;
  /** `shape` 说明这条是按正文形状兜底认出来的，面板上要标出来。 */
  readonly detectedBy?: 'name' | 'shape';
}

/** 扫描结果：面板拿它渲染预览，不含任何写入动作。 */
export interface MvuScanReport {
  readonly available: boolean;
  readonly cardName: string;
  readonly books: readonly string[];
  readonly assets: readonly MvuAssetSummary[];
  readonly issues: readonly string[];
  /** 试转换的预览；InitVar 解析不了时为 null，原因写在 error 里。 */
  readonly outcome: MvuConversionOutcome | null;
  readonly error: string;
}

export interface MvuConvertOptions {
  /** true = 合并进当前预设包；false = 新建「<卡名>（墨韵数据）」独立预设包。 */
  readonly mergeIntoActive: boolean;
  /** 是否写出带（墨韵数据）后缀的新卡与新世界书。 */
  readonly writeCard: boolean;
  /** 是否顺手打开数据桥接管（状态栏/EJS 改从数据中心读）。 */
  readonly enableBridge: boolean;
  /** 卡内填表协议是否允许正文模型直接输出 ```sql（含 IF 语法）。 */
  readonly allowStorySql: boolean;
}

export interface MvuConvertReport {
  readonly ok: boolean;
  readonly message: string;
  readonly presetName: string;
  readonly sheets: number;
  readonly createdSheets: number;
  readonly insertedRows: number;
  readonly mappedPaths: number;
  readonly cardName: string;
  readonly bookNames: readonly string[];
  readonly issues: readonly string[];
}

export const DEFAULT_MVU_CONVERT_OPTIONS: MvuConvertOptions = Object.freeze({
  mergeIntoActive: false,
  writeCard: true,
  enableBridge: true,
  allowStorySql: false,
});
