import type { PhoneEvent } from './events.js';
import { memorySourceOf, normalizeTimelineEvents } from './model.js';
import { applyNarrativePatch } from '../fanfic/patch-apply.js';
import { createEmptyFanficNarrative, normalizeFanficNarrative, rollbackFanficNarrative } from '../fanfic/narrative.js';
import type {
  Conversation,
  DeliveryStatus,
  DynamicWorldBookEntryState,
  OutboxItem,
  OutboxStatus,
  PhoneMessage,
  PhonePost,
  PhoneState,
} from './model.js';

const ACTION_HISTORY_LIMIT = 2_000;

function upsert<T>(source: Readonly<Record<string, T>>, id: string, value: T): Readonly<Record<string, T>> {
  return { ...source, [id]: value };
}

function appendUnique(source: readonly string[], id: string): readonly string[] {
  return source.includes(id) ? source : [...source, id];
}

function recordAction(state: PhoneState, actionId?: string): readonly string[] {
  if (!actionId || state.appliedActionIds.includes(actionId)) return state.appliedActionIds;
  return [...state.appliedActionIds, actionId].slice(-ACTION_HISTORY_LIMIT);
}

function updateOutboxItems(
  source: Readonly<Record<string, OutboxItem>>,
  ids: ReadonlySet<string>,
  status: OutboxStatus,
  batchId?: string,
  lastError?: string,
): Readonly<Record<string, OutboxItem>> {
  let changed = false;
  const next = { ...source };
  for (const id of ids) {
    const item = source[id];
    if (!item) continue;
    changed = true;
    // 清除错误时必须删掉键而不是写入 undefined：
    // IndexedDB 结构化克隆会保留 undefined 键，JSON 序列化会丢弃，两边状态会比对不一致。
    const { lastError: _cleared, ...rest } = item;
    next[id] = {
      ...rest,
      status,
      ...(batchId ? { batchId } : {}),
      ...(lastError ? { lastError } : {}),
    };
  }
  return changed ? next : source;
}

function updateMessageStatusesFromOutbox(
  messages: Readonly<Record<string, PhoneMessage>>,
  outbox: Readonly<Record<string, OutboxItem>>,
  outboxIds: ReadonlySet<string>,
  status: DeliveryStatus,
  batchId?: string,
): Readonly<Record<string, PhoneMessage>> {
  let changed = false;
  const next = { ...messages };
  for (const outboxId of outboxIds) {
    const item = outbox[outboxId];
    if (!item || item.entityType !== 'message') continue;
    const message = messages[item.entityId];
    if (!message) continue;
    changed = true;
    next[item.entityId] = {
      ...message,
      status,
      ...(batchId ? { batchId } : {}),
    };
  }
  return changed ? next : messages;
}

function markConversationUnread(
  conversations: Readonly<Record<string, Conversation>>,
  conversationId: string,
  occurredAt: number,
): Readonly<Record<string, Conversation>> {
  const conversation = conversations[conversationId];
  if (!conversation) return conversations;
  return upsert(conversations, conversationId, {
    ...conversation,
    unreadCount: conversation.unreadCount + 1,
    updatedAt: Math.max(conversation.updatedAt, occurredAt),
  });
}

function touchConversation(
  conversations: Readonly<Record<string, Conversation>>,
  conversationId: string,
  occurredAt: number,
): Readonly<Record<string, Conversation>> {
  const conversation = conversations[conversationId];
  if (!conversation) return conversations;
  return upsert(conversations, conversationId, {
    ...conversation,
    updatedAt: Math.max(conversation.updatedAt, occurredAt),
  });
}

/**
 * 收集一条公开内容连带的全部后代：楼层/回复贴、楼中楼、点赞与评论互动。
 * 根可以是帖子，也可以是评论互动；遍历只在同一个应用内进行，避免跨应用误删。
 */
function collectSocialItemTree(
  state: PhoneState,
  rootId: string,
): { readonly postIds: ReadonlySet<string>; readonly interactionIds: ReadonlySet<string> } | null {
  const rootPost = state.posts[rootId];
  const rootInteraction = state.interactions[rootId];
  const appId = rootPost?.appId
    ?? (rootInteraction?.type === 'comment' ? rootInteraction.appId : undefined);
  if (!appId) return null;

  const postIds = new Set<string>();
  const interactionIds = new Set<string>();
  const queue = [rootId];
  if (rootPost) postIds.add(rootId);
  else interactionIds.add(rootId);

  for (let index = 0; index < queue.length; index += 1) {
    const parentId = queue[index];
    if (!parentId) continue;
    for (const post of Object.values(state.posts)) {
      if (post.appId !== appId || postIds.has(post.id)) continue;
      if (post.parentId !== parentId && post.targetId !== parentId) continue;
      postIds.add(post.id);
      queue.push(post.id);
    }
    for (const interaction of Object.values(state.interactions)) {
      if (interaction.appId !== appId || interactionIds.has(interaction.id)) continue;
      if (interaction.targetId !== parentId) continue;
      interactionIds.add(interaction.id);
      if (interaction.type === 'comment') queue.push(interaction.id);
    }
  }
  return { postIds, interactionIds };
}

function deleteSocialItems(
  state: PhoneState,
  rootId: string,
): Pick<PhoneState, 'posts' | 'postOrder' | 'outbox' | 'interactions' | 'batches'> | null {
  const deleted = collectSocialItemTree(state, rootId);
  if (!deleted) return null;
  const deletedOutboxIds = new Set(
    Object.values(state.outbox)
      .filter((item) => item.entityType === 'post' && deleted.postIds.has(item.entityId))
      .map((item) => item.id),
  );
  return {
    posts: Object.fromEntries(
      Object.entries(state.posts).filter(([id]) => !deleted.postIds.has(id)),
    ),
    postOrder: state.postOrder.filter((id) => !deleted.postIds.has(id)),
    outbox: Object.fromEntries(
      Object.entries(state.outbox).filter(([id]) => !deletedOutboxIds.has(id)),
    ),
    interactions: Object.fromEntries(
      Object.entries(state.interactions).filter(([id, interaction]) => (
        !deleted.interactionIds.has(id) && !deleted.postIds.has(interaction.targetId)
      )),
    ),
    batches: Object.fromEntries(
      Object.entries(state.batches).map(([id, batch]) => {
        const outboxIds = batch.outboxIds.filter((outboxId) => !deletedOutboxIds.has(outboxId));
        return [id, outboxIds.length === batch.outboxIds.length ? batch : { ...batch, outboxIds }];
      }),
    ),
  };
}

function forumItemExists(state: PhoneState, itemId: string): boolean {
  const post = state.posts[itemId];
  if (post?.appId === 'forum') return true;
  const interaction = state.interactions[itemId];
  return interaction?.appId === 'forum' && interaction.type === 'comment';
}

function forumPostParentExists(state: PhoneState, post: PhonePost): boolean {
  if (post.appId !== 'forum' || post.kind !== 'forum-reply') return true;
  const parentId = post.parentId ?? post.targetId;
  return Boolean(parentId && forumItemExists(state, parentId));
}

function renameForumBoard(posts: PhoneState['posts'], previousName: string, nextName: string): PhoneState['posts'] {
  const previousKey = previousName.trim().toLocaleLowerCase('zh-CN');
  let changed = false;
  const result: Record<string, PhonePost> = {};
  for (const [id, post] of Object.entries(posts)) {
    if (post.appId !== 'forum' || post.board?.trim().toLocaleLowerCase('zh-CN') !== previousKey) {
      result[id] = post;
      continue;
    }
    changed = true;
    if (nextName) {
      result[id] = { ...post, board: nextName };
    } else {
      const { board: _removed, ...withoutBoard } = post;
      result[id] = withoutBoard;
    }
  }
  return changed ? result : posts;
}

function assertEventScope(state: PhoneState, event: PhoneEvent): void {
  if (state.scopeId !== event.scopeId) {
    throw new Error(`Phone event scope mismatch: ${event.scopeId} !== ${state.scopeId}`);
  }
}

export function reducePhoneEvent(state: PhoneState, event: PhoneEvent): PhoneState {
  assertEventScope(state, event);
  if (event.actionId && state.appliedActionIds.includes(event.actionId)) return state;

  const base = {
    ...state,
    revision: state.revision + 1,
    appliedActionIds: recordAction(state, event.actionId),
  };

  switch (event.type) {
    case 'profile.upserted':
      return {
        ...base,
        profiles: upsert(state.profiles, event.payload.profile.id, event.payload.profile),
      };

    case 'profile.deleted': {
      if (!state.profiles[event.payload.profileId]) return base;
      const profiles = { ...state.profiles };
      delete profiles[event.payload.profileId];
      return { ...base, profiles };
    }

    case 'conversation.upserted':
      return {
        ...base,
        conversations: upsert(
          state.conversations,
          event.payload.conversation.id,
          event.payload.conversation,
        ),
      };

    case 'conversation.deleted': {
      const conversation = state.conversations[event.payload.conversationId];
      if (!conversation) return base;
      const conversations = { ...state.conversations };
      delete conversations[conversation.id];
      const deletedMessageIds = new Set(
        Object.values(state.messages)
          .filter((message) => message.conversationId === conversation.id)
          .map((message) => message.id),
      );
      const messages = Object.fromEntries(
        Object.entries(state.messages).filter(([id]) => !deletedMessageIds.has(id)),
      );
      const outbox = Object.fromEntries(
        Object.entries(state.outbox).filter(([id, item]) => {
          if (item.conversationId === conversation.id) return false;
          return item.entityType !== 'message' || !deletedMessageIds.has(item.entityId);
        }),
      );
      const interactions = Object.fromEntries(
        Object.entries(state.interactions).filter(([, interaction]) => interaction.targetId !== conversation.id),
      );
      return {
        ...base,
        conversations,
        messages,
        messageOrder: state.messageOrder.filter((id) => !deletedMessageIds.has(id)),
        outbox,
        interactions,
      };
    }

    case 'conversation.read': {
      const conversation = state.conversations[event.payload.conversationId];
      if (!conversation || conversation.unreadCount === 0) return base;
      return {
        ...base,
        conversations: upsert(state.conversations, conversation.id, {
          ...conversation,
          unreadCount: 0,
        }),
      };
    }

    case 'message.queued':
      return {
        ...base,
        messages: upsert(state.messages, event.payload.message.id, event.payload.message),
        messageOrder: appendUnique(state.messageOrder, event.payload.message.id),
        outbox: upsert(state.outbox, event.payload.outboxItem.id, event.payload.outboxItem),
      };

    case 'message.received':
      return {
        ...base,
        messages: upsert(state.messages, event.payload.message.id, event.payload.message),
        messageOrder: appendUnique(state.messageOrder, event.payload.message.id),
        conversations: event.payload.message.direction === 'incoming'
          ? markConversationUnread(
              state.conversations,
              event.payload.message.conversationId,
              event.occurredAt,
            )
          : touchConversation(
              state.conversations,
              event.payload.message.conversationId,
              event.occurredAt,
            ),
      };

    case 'message.claimed': {
      const message = state.messages[event.payload.messageId];
      if (!message) return base;
      return {
        ...base,
        messages: upsert(state.messages, message.id, {
          ...message,
          claimStatus: event.payload.claimStatus,
          ...(event.payload.content ? { content: event.payload.content } : {}),
        }),
      };
    }

    case 'message.deleted': {
      const message = state.messages[event.payload.messageId];
      if (!message) return base;
      const messages = { ...state.messages };
      delete messages[message.id];
      // 同步移除关联的待生成队列条目。
      const outbox = { ...state.outbox };
      for (const [outboxId, item] of Object.entries(state.outbox)) {
        if (item.entityType === 'message' && item.entityId === message.id) delete outbox[outboxId];
      }
      return {
        ...base,
        messages,
        messageOrder: state.messageOrder.filter((id) => id !== message.id),
        outbox,
      };
    }

    case 'post.queued':
      if (!forumPostParentExists(state, event.payload.post)) return base;
      return {
        ...base,
        posts: upsert(state.posts, event.payload.post.id, event.payload.post),
        postOrder: appendUnique(state.postOrder, event.payload.post.id),
        outbox: upsert(state.outbox, event.payload.outboxItem.id, event.payload.outboxItem),
      };

    case 'post.created':
      if (!forumPostParentExists(state, event.payload.post)) return base;
      return {
        ...base,
        posts: upsert(state.posts, event.payload.post.id, event.payload.post),
        postOrder: appendUnique(state.postOrder, event.payload.post.id),
      };

    case 'post.deleted': {
      const deleted = deleteSocialItems(state, event.payload.postId);
      return deleted ? { ...base, ...deleted } : base;
    }

    case 'forum.board.created':
      return {
        ...base,
        forumBoards: upsert(state.forumBoards, event.payload.board.id, event.payload.board),
      };

    case 'forum.board.updated': {
      if (!state.forumBoards[event.payload.board.id]) return base;
      return {
        ...base,
        forumBoards: upsert(state.forumBoards, event.payload.board.id, event.payload.board),
        posts: renameForumBoard(state.posts, event.payload.previousName, event.payload.board.name),
      };
    }

    case 'forum.board.deleted': {
      const board = state.forumBoards[event.payload.boardId];
      if (!board) return base;
      const forumBoards = { ...state.forumBoards };
      delete forumBoards[board.id];
      return {
        ...base,
        forumBoards,
        posts: renameForumBoard(state.posts, board.name, ''),
      };
    }

    case 'forum.board.renamed':
      return { ...base, posts: renameForumBoard(state.posts, event.payload.previousName, event.payload.name) };

    case 'forum.item.deleted': {
      const deleted = deleteSocialItems(state, event.payload.itemId);
      return deleted ? { ...base, ...deleted } : base;
    }

    case 'interaction.created':
      if (event.payload.interaction.appId === 'forum'
        && !forumItemExists(state, event.payload.interaction.targetId)) return base;
      return {
        ...base,
        interactions: upsert(
          state.interactions,
          event.payload.interaction.id,
          event.payload.interaction,
        ),
      };

    case 'interaction.deleted': {
      if (!state.interactions[event.payload.interactionId]) return base;
      const interactions = { ...state.interactions };
      delete interactions[event.payload.interactionId];
      return { ...base, interactions };
    }

    case 'batch.started': {
      const ids = new Set(event.payload.batch.outboxIds);
      return {
        ...base,
        batches: upsert(state.batches, event.payload.batch.id, event.payload.batch),
        outbox: updateOutboxItems(state.outbox, ids, 'processing', event.payload.batch.id),
        messages: updateMessageStatusesFromOutbox(
          state.messages,
          state.outbox,
          ids,
          'processing',
          event.payload.batch.id,
        ),
      };
    }

    case 'batch.completed': {
      const completed = new Set(event.payload.completedOutboxIds);
      const queued = new Set(event.payload.queuedOutboxIds);
      const batch = state.batches[event.payload.batchId];
      const afterCompleted = updateOutboxItems(state.outbox, completed, 'completed', event.payload.batchId);
      const nextOutbox = updateOutboxItems(
        afterCompleted,
        queued,
        'queued',
        event.payload.batchId,
        event.payload.error,
      );
      const sentMessages = updateMessageStatusesFromOutbox(
        state.messages,
        state.outbox,
        completed,
        'sent',
        event.payload.batchId,
      );
      const nextMessages = updateMessageStatusesFromOutbox(
        sentMessages,
        state.outbox,
        queued,
        'queued',
        event.payload.batchId,
      );
      return {
        ...base,
        outbox: nextOutbox,
        messages: nextMessages,
        batches: batch
          ? upsert(state.batches, batch.id, {
              ...batch,
              status: queued.size > 0 ? 'partial' : 'completed',
              completedAt: event.payload.completedAt,
              ...(event.payload.error ? { error: event.payload.error } : {}),
            })
          : state.batches,
      };
    }

    case 'batch.failed': {
      const batch = state.batches[event.payload.batchId];
      if (!batch) return base;
      const ids = new Set(batch.outboxIds);
      return {
        ...base,
        outbox: updateOutboxItems(state.outbox, ids, 'queued', batch.id, event.payload.error),
        messages: updateMessageStatusesFromOutbox(state.messages, state.outbox, ids, 'queued', batch.id),
        batches: upsert(state.batches, batch.id, {
          ...batch,
          status: 'failed',
          completedAt: event.payload.failedAt,
          error: event.payload.error,
        }),
      };
    }

    case 'clock.advanced': {
      // 用户手动设置或变量同步允许把剧情时间调早；其余来源只允许前进。
      const exactSet = event.payload.clock.source === 'user' || event.payload.clock.source === 'variables';
      return {
        ...base,
        worldClock: {
          ...event.payload.clock,
          now: exactSet
            ? event.payload.clock.now
            : Math.max(state.worldClock.now, event.payload.clock.now),
        },
      };
    }

    case 'summary.recorded':
      return {
        ...base,
        summaries: [...(state.summaries ?? []), event.payload.summary],
      };

    case 'pxx.products.added': {
      const existing = state.pxxProducts ?? [];
      const knownNames = new Set(existing.map((product) => product.name.trim().toLowerCase()));
      const additions = event.payload.products.filter((product) => {
        const key = product.name.trim().toLowerCase();
        if (!key || knownNames.has(key)) return false;
        knownNames.add(key);
        return true;
      });
      if (additions.length === 0) return base;
      return {
        ...base,
        pxxProducts: [...existing, ...additions],
      };
    }

    case 'calendar.festival.upserted':
      return {
        ...base,
        calendarFestivals: upsert(
          state.calendarFestivals ?? {},
          event.payload.festival.date,
          event.payload.festival,
        ),
      };

    case 'calendar.festival.removed': {
      const festivals = state.calendarFestivals ?? {};
      if (!festivals[event.payload.date]) return base;
      const next = { ...festivals };
      delete next[event.payload.date];
      return {
        ...base,
        calendarFestivals: next,
      };
    }

    case 'diary.baseline.set':
      return {
        ...base,
        diaryCoveredUntil: Math.max(state.diaryCoveredUntil ?? 0, event.payload.coveredUntil),
      };

    case 'diary.entry.recorded': {
      const entry = event.payload.entry;
      // 同一天补写视为重写：替换该日期的旧条目。
      const entries = [...(state.diaryEntries ?? []).filter((item) => item.date !== entry.date), entry]
        .sort((left, right) => left.date.localeCompare(right.date) || left.createdAt - right.createdAt);
      return {
        ...base,
        diaryEntries: entries,
        diaryCoveredUntil: Math.max(state.diaryCoveredUntil ?? 0, entry.coveredUntil),
      };
    }

    case 'diary.entry.removed': {
      const entries = state.diaryEntries ?? [];
      const next = entries.filter((item) => item.id !== event.payload.entryId);
      if (next.length === entries.length) return base;
      return {
        ...base,
        diaryEntries: next,
      };
    }

    case 'memory.baseline.set':
      return {
        ...base,
        memoryLastFloor: Math.max(state.memoryLastFloor ?? -1, event.payload.floor),
      };

    case 'memory.floors.invalidated': {
      const fromFloor = Math.max(0, Math.floor(event.payload.fromFloor));
      // 手机总结覆盖手机记录而不是正文楼层，正文删除不应清掉它们。
      const retainedItems = (state.memoryItems ?? []).filter(
        (item) => memorySourceOf(item) === 'phone' || item.floorTo < fromFloor,
      );
      const archivedByRetainedConsolidations = new Set(
        retainedItems
          .filter((item) => memorySourceOf(item) === 'summary')
          .flatMap((item) => item.sourceSeqs ?? []),
      );
      return {
        ...base,
        memoryItems: retainedItems.map((item) => (
          memorySourceOf(item) === 'memory'
            ? { ...item, archived: archivedByRetainedConsolidations.has(item.seq) }
            : item
        )),
        timelineEvents: (state.timelineEvents ?? []).filter((entry) => entry.floor < fromFloor),
        memoryLastFloor: Math.min(
          state.memoryLastFloor ?? -1,
          Math.max(-1, Math.floor(event.payload.resumeAfterFloor)),
        ),
      };
    }

    case 'memory.item.recorded': {
      const item = event.payload.item;
      const archiveSeqs = new Set(event.payload.archiveSeqs ?? []);
      const existing = (state.memoryItems ?? []).map((memory) => (
        archiveSeqs.has(memory.seq) && !memory.archived ? { ...memory, archived: true } : memory
      ));
      return {
        ...base,
        memoryItems: [...existing, item].sort((left, right) => left.seq - right.seq),
        memorySeq: Math.max(state.memorySeq ?? 0, item.seq),
        // 只有正文楼层摘要代表整理进度；总结与手机总结不推进楼层游标。
        memoryLastFloor: memorySourceOf(item) === 'memory'
          ? Math.max(state.memoryLastFloor ?? -1, item.floorTo)
          : (state.memoryLastFloor ?? -1),
      };
    }

    case 'memory.item.updated': {
      const items = state.memoryItems ?? [];
      const index = items.findIndex((item) => item.id === event.payload.item.id);
      if (index < 0) return base;
      const next = [...items];
      next[index] = event.payload.item;
      return {
        ...base,
        memoryItems: next,
      };
    }

    case 'memory.item.removed': {
      const items = state.memoryItems ?? [];
      const next = items.filter((item) => item.id !== event.payload.itemId);
      if (next.length === items.length) return base;
      return {
        ...base,
        memoryItems: next,
      };
    }

    case 'timeline.events.recorded': {
      if (event.payload.events.length === 0) return base;
      const maxSeq = Math.max(...event.payload.events.map((entry) => entry.seq));
      return {
        ...base,
        timelineEvents: normalizeTimelineEvents([...(state.timelineEvents ?? []), ...event.payload.events]),
        timelineSeq: Math.max(state.timelineSeq ?? 0, maxSeq),
      };
    }

    case 'timeline.event.removed': {
      const events = state.timelineEvents ?? [];
      const next = events.filter((entry) => entry.id !== event.payload.eventId);
      if (next.length === events.length) return base;
      return {
        ...base,
        timelineEvents: next,
      };
    }

    case 'dynamic-worldbook.baseline.set':
      return {
        ...base,
        dynamicWorldBook: {
          lastFloor: Math.max(state.dynamicWorldBook?.lastFloor ?? -1, event.payload.floor),
          entries: event.payload.entries,
          revision: (state.dynamicWorldBook?.revision ?? 0) + 1,
        },
      };

    case 'dynamic-worldbook.optimized': {
      const existing = state.dynamicWorldBook ?? { lastFloor: -1, entries: [], revision: 0 };
      const updatesByKey = new Map(event.payload.updates.map((entry) => [entry.key, entry]));
      const entries = existing.entries.map((entry) => updatesByKey.get(entry.key) ?? entry);
      const known = new Set(entries.map((entry) => entry.key));
      entries.push(...event.payload.updates.filter((entry) => !known.has(entry.key)));
      return {
        ...base,
        dynamicWorldBook: {
          lastFloor: Math.max(existing.lastFloor, event.payload.floor),
          entries,
          revision: existing.revision + 1,
        },
      };
    }

    case 'dynamic-worldbook.invalidated': {
      const fromFloor = Math.max(0, Math.floor(event.payload.fromFloor));
      const current = state.dynamicWorldBook ?? { lastFloor: -1, entries: [], revision: 0 };
      return {
        ...base,
        dynamicWorldBook: {
          lastFloor: Math.min(current.lastFloor, fromFloor - 1),
          entries: current.entries
            .map((entry) => restoreDynamicEntryBeforeFloor(entry, fromFloor))
            .filter((entry) => entry !== null),
          revision: current.revision + 1,
        },
      };
    }

    case 'dynamic-worldbook.entry.edited': {
      const current = state.dynamicWorldBook ?? { lastFloor: -1, entries: [], revision: 0 };
      const entries = current.entries.filter((entry) => entry.key !== event.payload.entry.key);
      return {
        ...base,
        dynamicWorldBook: {
          ...current,
          entries: [...entries, event.payload.entry],
          revision: current.revision + 1,
        },
      };
    }

    case 'dynamic-worldbook.cleared':
      return {
        ...base,
        dynamicWorldBook: { lastFloor: -1, entries: [], revision: (state.dynamicWorldBook?.revision ?? 0) + 1 },
      };

    case 'fanfic.narrative.advanced':
      return {
        ...base,
        fanficNarrative: applyNarrativePatch(
          normalizeFanficNarrative(state.fanficNarrative),
          event.payload.patch,
          event.payload.floor,
        ),
      };

    case 'fanfic.narrative.invalidated':
      return {
        ...base,
        fanficNarrative: rollbackFanficNarrative(
          normalizeFanficNarrative(state.fanficNarrative),
          event.payload.fromFloor,
        ),
      };

    case 'fanfic.narrative.replaced':
      return {
        ...base,
        fanficNarrative: normalizeFanficNarrative(event.payload.narrative),
      };

    case 'fanfic.narrative.cleared':
      return {
        ...base,
        fanficNarrative: createEmptyFanficNarrative(),
      };
  }
}

function restoreDynamicEntryBeforeFloor(
  entry: DynamicWorldBookEntryState,
  fromFloor: number,
): DynamicWorldBookEntryState | null {
  if (entry.manualEdited) return entry;
  const retained = entry.evolutionLog.flatMap((raw) => {
    try {
      const record = JSON.parse(raw) as { floor?: unknown; content?: unknown };
      const floor = Number(record.floor);
      return Number.isFinite(floor) && typeof record.content === 'string' && floor < fromFloor
        ? [{ raw, floor: Math.floor(floor), content: record.content }]
        : [];
    } catch {
      return [];
    }
  });
  const latest = retained.at(-1);
  return {
    ...entry,
    currentState: latest?.content ?? entry.baselineContent,
    evolutionLog: retained.map((record) => record.raw),
    updatedAtFloor: latest?.floor ?? Math.min(entry.updatedAtFloor, Math.max(0, fromFloor - 1)),
  };
}

export function reducePhoneEvents(state: PhoneState, events: readonly PhoneEvent[]): PhoneState {
  return events.reduce(reducePhoneEvent, state);
}