import { PHONE_DATA_BUCKETS, summarizePhoneData, type PhoneDataBucketId } from '../domain/data-purge.js';
import type { PhoneState } from '../domain/model.js';
import { button, element } from './dom.js';

export interface DataPurgeViewContext {
  readonly state: PhoneState;
  readonly onPurgeData: (
    bucketIds: readonly PhoneDataBucketId[],
  ) => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 重绘「数据与备份」页（展开/收起清除面板时使用）。 */
  readonly refresh: () => void;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

const ALL_BUCKET_IDS: readonly PhoneDataBucketId[] = PHONE_DATA_BUCKETS.map((bucket) => bucket.id);

/** 面板是否展开，以及当前勾选集合；设置页因其他原因重绘时不丢勾选。 */
let opened = false;
let selection = new Set<PhoneDataBucketId>(ALL_BUCKET_IDS);

function countLabel(count: number): string {
  return count < 0 ? '浏览器缓存' : `${count} 条`;
}

/**
 * 清除数据面板：默认全选，可取消全选后只勾某个应用或功能。
 * 勾选状态是一次性操作意图，不写入设置；关闭面板即回到默认全选。
 */
export function renderDataPurgeSection(context: DataPurgeViewContext): HTMLElement {
  const section = element('div', { className: 'phone-data-purge' });
  if (!opened) {
    section.append(
      element('p', {
        className: 'phone-settings-hint',
        text: '需要重来一遍时，可以只清掉某个应用或某项功能的数据，不必整份备份覆盖。',
      }),
      button('清除数据…', 'phone-button phone-button-danger-ghost', () => {
        selection = new Set(ALL_BUCKET_IDS);
        opened = true;
        context.refresh();
      }),
    );
    return section;
  }

  const summaries = summarizePhoneData(context.state);
  const counter = element('small', { className: 'phone-settings-inline-count' });
  const inputs = new Map<PhoneDataBucketId, HTMLInputElement>();
  const syncCounter = (): void => {
    counter.textContent = `已选 ${selection.size}/${summaries.length}`;
  };
  const applyAll = (checked: boolean): void => {
    selection = new Set(checked ? ALL_BUCKET_IDS : []);
    for (const input of inputs.values()) input.checked = checked;
    syncCounter();
  };

  const toolbar = element('div', { className: 'phone-settings-inline-actions' });
  toolbar.append(
    counter,
    button('全选', 'phone-button phone-button-secondary phone-button-compact', () => applyAll(true)),
    button('全不选', 'phone-button phone-button-secondary phone-button-compact', () => applyAll(false)),
  );

  const list = element('div', { className: 'phone-purge-list' });
  for (const summary of summaries) {
    const row = element('label', { className: 'phone-checkbox-control' });
    const input = element('input', { attributes: { type: 'checkbox' } });
    input.checked = selection.has(summary.id);
    input.addEventListener('change', () => {
      if (input.checked) selection.add(summary.id);
      else selection.delete(summary.id);
      syncCounter();
    });
    inputs.set(summary.id, input);
    const copy = element('span');
    copy.append(
      element('strong', { text: `${summary.label} · ${countLabel(summary.count)}` }),
      element('small', { text: summary.hint }),
    );
    row.append(input, copy);
    list.append(row);
  }
  syncCounter();

  const actions = element('div', { className: 'phone-settings-actions' });
  const purge = button('清除所选数据', 'phone-button phone-button-danger', async () => {
    const chosen = summaries.filter((summary) => selection.has(summary.id));
    if (chosen.length === 0) {
      context.showNotice('请先勾选要清除的数据。', 'info');
      return;
    }
    const confirmText = [
      '将永久删除当前聊天的以下数据：',
      ...chosen.map((summary) => `· ${summary.label}（${countLabel(summary.count)}）`),
      '',
      '此操作不可撤销，建议先导出备份。确定继续吗？',
    ].join('\n');
    if (!window.confirm(confirmText)) return;
    purge.disabled = true;
    purge.textContent = '清除中…';
    try {
      const result = await context.onPurgeData([...selection]);
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) {
        opened = false;
        selection = new Set(ALL_BUCKET_IDS);
        context.refresh();
      }
    } finally {
      purge.disabled = false;
      purge.textContent = '清除所选数据';
    }
  });
  actions.append(
    purge,
    button('取消', 'phone-button phone-button-secondary', () => {
      opened = false;
      selection = new Set(ALL_BUCKET_IDS);
      context.refresh();
    }),
  );

  section.append(
    element('p', {
      className: 'phone-settings-hint',
      text: '默认勾选全部；取消全选后只清你勾中的部分。联系人资料、记忆库这类跨应用数据是独立条目，'
        + '清掉某个应用不会连带删除它们。剧情时间、扩展设置与角色卡世界书都不在清除范围内。',
    }),
    toolbar,
    list,
    actions,
  );
  return section;
}
