import type { VectorSettings } from './sillytavern-bridge.js';

/**
 * 向量召回跑不起来的具体原因；`null` 表示可用。
 *
 * 判定同时被记忆库设置页（选择时立即提醒）和运行时召回（生成前跳过并提示）使用，
 * 因此必须集中在这里：两处各写一份判定会出现「界面说可用、生成时静默跳过」的偏差。
 */
export type VectorRecallGap = 'app-disabled' | 'vector-disabled' | 'embedding-model-missing';

/** 判定输入：向量库自身配置，加上向量库应用是否被个性化停用。 */
export interface VectorRecallEnvironment {
  readonly vector: Pick<VectorSettings, 'enabled' | 'embedding'>;
  readonly vectorAppDisabled: boolean;
}

/** 缺口原因短语，用于日志字段与提示句拼装。 */
export const VECTOR_RECALL_GAP_REASON: Record<VectorRecallGap, string> = {
  'app-disabled': '向量库应用已在个性化里停用',
  'vector-disabled': '向量库尚未启用',
  'embedding-model-missing': '向量库尚未选择向量化模型',
};

/** 按「应用可见 → 开关打开 → 配了向量化模型」的顺序找出第一个缺口。 */
export function findVectorRecallGap(env: VectorRecallEnvironment): VectorRecallGap | null {
  if (env.vectorAppDisabled) return 'app-disabled';
  if (!env.vector.enabled) return 'vector-disabled';
  if (env.vector.embedding.model.trim().length === 0) return 'embedding-model-missing';
  return null;
}

/** 面向用户的完整提示句：说明缺什么、后果是什么、有哪两条出路。 */
export function describeVectorRecallGap(gap: VectorRecallGap): string {
  return `${VECTOR_RECALL_GAP_REASON[gap]}，向量召回本轮不会注入任何记忆；请到向量库完成配置，或把召回方式切回记忆召回。`;
}