/**
 * 生图响应解码：把各家站点的返回负载统一成 `<img src>` 可用的地址。
 *
 * 站点实现差异极大：官网返回 ZIP 包裹的 PNG，公益站可能返回裸 PNG / WebP / JPEG、
 * JSON 包 base64、JSON 包直链，甚至纯文本裸 base64；而 Content-Type 往往不可信
 * （网关会写成 octet-stream，出错页写成 text/html）。因此这里统一按
 * 「一次读完字节 → 按内容嗅探 → 再按文本解析」判断，不依赖响应头。
 */
import { describeError, excerpt } from '../core/diagnostics.js';

const TEXT_SNIFF_LIMIT = 256;
const TEXT_EXCERPT_LIMIT = 400;
const HEAD_HEX_BYTES = 16;
const MAX_JSON_DEPTH = 8;
const MAX_ZIP_ENTRIES = 8;
/** 无法嗅探出类型时，仍按图片处理的最小 base64 长度。 */
const BLIND_BASE64_MIN_LENGTH = 512;

/** 解码失败：区分「正文传输中断」（可重试）与「格式无法识别」（重试无意义）。 */
export class ImagePayloadError extends Error {
  readonly retryable: boolean;
  readonly diagnostics: Readonly<Record<string, unknown>>;

  constructor(
    message: string,
    options: { readonly retryable: boolean; readonly diagnostics?: Readonly<Record<string, unknown>> },
  ) {
    super(message);
    this.name = 'ImagePayloadError';
    this.retryable = options.retryable;
    this.diagnostics = options.diagnostics ?? {};
  }
}

export function isRetryableImagePayloadError(error: unknown): boolean {
  return error instanceof ImagePayloadError && error.retryable;
}

/** 解码失败时可直接写进日志的响应侧证据（Content-Type、字节长度、开头字节、正文片段）。 */
export function imagePayloadDiagnostics(error: unknown): Readonly<Record<string, unknown>> {
  return error instanceof ImagePayloadError ? error.diagnostics : {};
}

interface ImageSignature {
  readonly mime: string;
  /** 需要同时命中的字节片段，按 [偏移, 字节序列] 声明。 */
  readonly parts: readonly (readonly [number, readonly number[]])[];
  /** 签名足够长、可用于在整段字节里扫描定位。 */
  readonly scannable?: boolean;
}

const FTYP = [0x66, 0x74, 0x79, 0x70] as const;

/** 图片魔数表：按内容判定 MIME，不相信 Content-Type。 */
const IMAGE_SIGNATURES: readonly ImageSignature[] = [
  { mime: 'image/png', parts: [[0, [0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]]], scannable: true },
  { mime: 'image/jpeg', parts: [[0, [0xff, 0xd8, 0xff]]], scannable: true },
  { mime: 'image/webp', parts: [[0, [0x52, 0x49, 0x46, 0x46]], [8, [0x57, 0x45, 0x42, 0x50]]], scannable: true },
  { mime: 'image/gif', parts: [[0, [0x47, 0x49, 0x46, 0x38]]], scannable: true },
  { mime: 'image/avif', parts: [[4, FTYP], [8, [0x61, 0x76, 0x69, 0x66]]], scannable: true },
  { mime: 'image/avif', parts: [[4, FTYP], [8, [0x61, 0x76, 0x69, 0x73]]], scannable: true },
  { mime: 'image/heic', parts: [[4, FTYP], [8, [0x68, 0x65, 0x69, 0x63]]], scannable: true },
  { mime: 'image/heic', parts: [[4, FTYP], [8, [0x6d, 0x69, 0x66, 0x31]]], scannable: true },
  { mime: 'image/jxl', parts: [[0, [0x00, 0x00, 0x00, 0x0c, 0x4a, 0x58, 0x4c, 0x20]]], scannable: true },
  { mime: 'image/jxl', parts: [[0, [0xff, 0x0a]]] },
  { mime: 'image/tiff', parts: [[0, [0x49, 0x49, 0x2a, 0x00]]] },
  { mime: 'image/tiff', parts: [[0, [0x4d, 0x4d, 0x00, 0x2a]]] },
  { mime: 'image/bmp', parts: [[0, [0x42, 0x4d]]] },
  { mime: 'image/x-icon', parts: [[0, [0x00, 0x00, 0x01, 0x00]]] },
];

const ZIP_LOCAL_HEADER = [0x50, 0x4b, 0x03, 0x04] as const;
/** 本地文件头、中央目录、数据描述符、目录尾：用于反推缺失的压缩长度。 */
const ZIP_BLOCK_HEADERS: readonly (readonly number[])[] = [
  ZIP_LOCAL_HEADER,
  [0x50, 0x4b, 0x01, 0x02],
  [0x50, 0x4b, 0x07, 0x08],
  [0x50, 0x4b, 0x05, 0x06],
];

/** 按魔数判定图片类型；无法识别时返回 null。 */
export function sniffImageMime(bytes: Uint8Array): string | null {
  const matched = IMAGE_SIGNATURES.find((signature) => signature.parts.every(
    ([offset, pattern]) => matchesBytes(bytes, offset, pattern),
  ));
  if (matched) return matched.mime;
  return looksLikeSvg(bytes) ? 'image/svg+xml' : null;
}

export function isZipArchive(bytes: Uint8Array): boolean {
  return matchesBytes(bytes, 0, ZIP_LOCAL_HEADER);
}

interface ZipEntry {
  readonly name: string;
  readonly method: number;
  readonly start: number;
  readonly end: number;
}

/**
 * 顺序读取 ZIP 本地文件头。
 * 压缩长度为 0（流式写出时长度记在数据描述符里）或 ZIP64 占位值时，
 * 用下一个区块签名反推数据边界，避免把整包尾部当成压缩数据。
 */
export function readZipEntries(bytes: Uint8Array): readonly ZipEntry[] {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const entries: ZipEntry[] = [];
  let offset = findBytes(bytes, ZIP_LOCAL_HEADER, 0);
  while (offset >= 0 && offset + 30 <= bytes.length && entries.length < MAX_ZIP_ENTRIES) {
    const nameLength = view.getUint16(offset + 26, true);
    const start = offset + 30 + nameLength + view.getUint16(offset + 28, true);
    if (start > bytes.length) break;
    const compressedSize = view.getUint32(offset + 18, true);
    const sized = compressedSize > 0
      && compressedSize !== 0xffffffff
      && start + compressedSize <= bytes.length;
    const end = sized ? start + compressedSize : nextZipBlockOffset(bytes, start);
    entries.push({
      name: decodeText(bytes.subarray(offset + 30, offset + 30 + nameLength)),
      method: view.getUint16(offset + 8, true),
      start,
      end,
    });
    if (!sized) break;
    offset = findBytes(bytes, ZIP_LOCAL_HEADER, end);
  }
  return entries;
}

/** 取出 ZIP 中第一个能识别为图片的条目；条目全部失败时退回整包签名扫描。 */
export async function extractImageFromArchive(bytes: Uint8Array): Promise<Uint8Array> {
  const failures: string[] = [];
  for (const entry of readZipEntries(bytes)) {
    try {
      const content = await readZipEntry(bytes, entry);
      if (sniffImageMime(content)) return content;
      failures.push(`${entry.name || '未命名条目'}：解出的内容不是可识别的图片`);
    } catch (error) {
      failures.push(`${entry.name || '未命名条目'}：${describeError(error)}`);
    }
  }
  const embedded = findEmbeddedImage(bytes);
  if (embedded) return embedded;
  throw new Error(`压缩包内没有可识别的图片${failures.length > 0 ? `（${failures.join('；')}）` : ''}`);
}

async function readZipEntry(bytes: Uint8Array, entry: ZipEntry): Promise<Uint8Array> {
  const slice = bytes.subarray(entry.start, entry.end);
  if (slice.length === 0) throw new Error('条目数据为空');
  if (entry.method === 0) return slice;
  if (entry.method !== 8) throw new Error(`不支持的压缩方式（${entry.method}）`);
  const raw = await inflate(slice, 'deflate-raw');
  return raw.length > 0 ? raw : inflate(slice, 'deflate');
}

/**
 * 解压时容忍尾部附加字节：流式 ZIP 会在压缩数据后紧跟数据描述符与中央目录，
 * 严格解压会以「junk after end of stream」失败，而图片本体此时已经完整读出。
 * 这里逐块读取并保留已解出的内容，也避免用 `new Response(stream)` 把
 * 解压错误伪装成 `TypeError: Failed to fetch`。
 */
async function inflate(data: Uint8Array, format: 'deflate-raw' | 'deflate'): Promise<Uint8Array> {
  const reader = new Blob([data as BlobPart]).stream()
    .pipeThrough(new DecompressionStream(format))
    .getReader();
  const chunks: Uint8Array[] = [];
  let total = 0;
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      if (value) {
        chunks.push(value);
        total += value.length;
      }
    }
  } catch (error) {
    if (total === 0) throw error;
  }
  return concatBytes(chunks, total);
}

/** 兜底：在整段字节里搜索图片签名，应对 multipart 包裹、ZIP64 与异常前缀。 */
export function findEmbeddedImage(bytes: Uint8Array): Uint8Array | null {
  let best = -1;
  for (const signature of IMAGE_SIGNATURES) {
    const head = signature.scannable ? signature.parts[0] : undefined;
    if (!head) continue;
    const [offset, pattern] = head;
    const found = findBytes(bytes, pattern, offset + 1);
    const start = found - offset;
    if (found < 0 || start < 1 || (best >= 0 && start >= best)) continue;
    if (sniffImageMime(bytes.subarray(start))) best = start;
  }
  return best >= 0 ? bytes.subarray(best) : null;
}

const BASE64_PATTERN = /^[A-Za-z0-9+/_-]+={0,2}$/;
const IMAGE_PATH_PATTERN = /\.(?:png|jpe?g|webp|gif|bmp|avif|heic|heif|svg|jxl|tiff?|ico)(?:[?#]|$)/i;

/**
 * 把单个候选字符串归一成可用地址：
 * data: URL、blob: URL、http(s) 直链、协议相对地址、站内相对路径、裸 base64（含 base64url）。
 * 无法判定为图片时返回 null，交由上层继续尝试其他解析路径。
 */
export function normalizeImageCandidate(raw: string, baseUrl?: string): string | null {
  const text = raw.trim().replace(/^["']+|["']+$/g, '').trim();
  if (!text) return null;
  if (/^data:image\//i.test(text)) return text;
  if (/^blob:/i.test(text)) return text;
  const mislabeled = /^data:[^;,]*;base64,/i.exec(text);
  if (mislabeled) {
    // 少数站点把 MIME 写成 octet-stream / text-plain，按内容重新判定。
    const payload = text.slice(mislabeled[0].length);
    return dataUrlFromBase64(payload) ?? `data:image/png;base64,${payload.replace(/\s+/g, '')}`;
  }
  if (/^https?:\/\//i.test(text)) return text;
  if (/^\/\/[^/]/.test(text)) return `https:${text}`;
  if (baseUrl && !/\s/.test(text) && IMAGE_PATH_PATTERN.test(text)) {
    try {
      return new URL(text, baseUrl).toString();
    } catch {
      // 相对路径拼接失败时继续按 base64 处理。
    }
  }
  return dataUrlFromBase64(text);
}

/** 裸 base64 → data URL：按解码后的字节判定真实类型（PNG / WebP / JPEG…）。 */
function dataUrlFromBase64(text: string): string | null {
  const compact = text.replace(/\s+/g, '');
  if (!BASE64_PATTERN.test(compact)) return null;
  const standard = compact.replace(/-/g, '+').replace(/_/g, '/');
  const padded = standard.padEnd(standard.length + ((4 - (standard.length % 4)) % 4), '=');
  if (padded.length < 16) return null;
  const bytes = decodeBase64(padded);
  if (!bytes || bytes.length === 0) return null;
  const mime = sniffImageMime(bytes);
  if (mime) return `data:${mime};base64,${padded}`;
  // 长负载即使嗅探不出类型也按图片处理（部分站点会二次编码或裁掉文件头）。
  return padded.length >= BLIND_BASE64_MIN_LENGTH ? `data:image/png;base64,${padded}` : null;
}

/** 字段名优先级：越靠前越可能是图片本体。 */
const JSON_KEY_RANKS: readonly (readonly [RegExp, number])[] = [
  [/^(?:b64_json|base64|image_base64|imagebase64|b64)$/i, 0],
  [/^(?:image|images|img|imgs|artifact|artifacts|output|outputs|thumbnail)$/i, 1],
  [/^(?:image_url|imageurl|url|uri|src|link|href|file|filename|filepath|path|photo|picture)$/i, 2],
  [/^(?:data|result|results|response|payload|content|attachment|attachments|items|list)$/i, 3],
];
/** 明确不是图片的字段：避免把报错文案里的链接当成图片。 */
const IGNORED_JSON_KEY = /^(?:error|errors|message|msg|detail|details|reason|status|state|code|model|prompt|input|negative_prompt|documentation_url|docs|help|type|id|seed|log|logs|version)$/i;

/** 在任意形状的 JSON 里挑出最可能的图片字段（递归，按字段名与层级排序）。 */
export function pickImageFromJson(payload: unknown, baseUrl?: string): string | null {
  const matches: { readonly value: string; readonly rank: number; readonly depth: number }[] = [];
  const visit = (node: unknown, key: string, depth: number): void => {
    if (depth > MAX_JSON_DEPTH) return;
    if (typeof node === 'string') {
      if (IGNORED_JSON_KEY.test(key)) return;
      const value = normalizeImageCandidate(node, baseUrl);
      if (value) matches.push({ value, rank: rankJsonKey(key), depth });
      return;
    }
    // 数组沿用父级字段名，`images: [...]` 才能保持原有优先级。
    if (Array.isArray(node)) {
      for (const item of node) visit(item, key, depth + 1);
      return;
    }
    if (node && typeof node === 'object') {
      for (const [childKey, value] of Object.entries(node)) visit(value, childKey, depth + 1);
    }
  };
  visit(payload, '', 0);
  return [...matches].sort((left, right) => left.rank - right.rank || left.depth - right.depth)[0]?.value ?? null;
}

function rankJsonKey(key: string): number {
  return JSON_KEY_RANKS.find(([pattern]) => pattern.test(key))?.[1] ?? JSON_KEY_RANKS.length;
}

export interface DecodeImageOptions {
  /** 相对路径直链的解析基准，通常是请求地址。 */
  readonly baseUrl?: string;
  /** 二进制结果的落地方式；默认优先 blob 地址，无 URL.createObjectURL 时回退 data URL。 */
  readonly toImageUrl?: (bytes: Uint8Array, mime: string) => string;
}

/**
 * 生图响应 → `<img src>` 地址的唯一入口。
 * 判定顺序：二进制图片 → ZIP 包裹 → JSON 字段 → 纯文本（直链 / 裸 base64）→ 整段签名扫描。
 */
export async function decodeImageResponse(
  response: Response,
  options: DecodeImageOptions = {},
): Promise<string> {
  const contentType = (response.headers.get('content-type') ?? '').toLowerCase();
  const bytes = await readResponseBytes(response, contentType);
  const toImageUrl = options.toImageUrl ?? createImageUrl;

  const mime = sniffImageMime(bytes);
  if (mime) return toImageUrl(bytes, mime);

  if (isZipArchive(bytes)) {
    try {
      const content = await extractImageFromArchive(bytes);
      return toImageUrl(content, sniffImageMime(content) ?? 'image/png');
    } catch (error) {
      throw new ImagePayloadError(`站点返回的压缩包无法解出图片：${describeError(error)}。`, {
        retryable: false,
        diagnostics: payloadDiagnostics(contentType, bytes),
      });
    }
  }

  const text = decodeText(bytes).trim();
  const fromJson = /^[[{]/.test(text) ? pickImageFromJsonText(text, options.baseUrl) : null;
  if (fromJson) return fromJson;
  const fromText = normalizeImageCandidate(text, options.baseUrl);
  if (fromText) return fromText;
  const embedded = findEmbeddedImage(bytes);
  if (embedded) return toImageUrl(embedded, sniffImageMime(embedded) ?? 'image/png');

  throw new ImagePayloadError(unknownPayloadMessage(contentType, bytes, text), {
    retryable: false,
    diagnostics: payloadDiagnostics(contentType, bytes),
  });
}

function pickImageFromJsonText(text: string, baseUrl?: string): string | null {
  try {
    return pickImageFromJson(JSON.parse(text) as unknown, baseUrl);
  } catch {
    return null;
  }
}

/**
 * 读取正文字节。响应头已经到达却在读正文时失败，属于连接中断
 * （网关断流、代理超时、跨域读取被拦截）；浏览器同样报 `TypeError: Failed to fetch`，
 * 但它和「格式不对」是两件事，必须按可重试上报。
 */
async function readResponseBytes(response: Response, contentType: string): Promise<Uint8Array> {
  let bytes: Uint8Array;
  try {
    bytes = new Uint8Array(await response.arrayBuffer());
  } catch (error) {
    throw new ImagePayloadError(
      `站点已经返回了响应头，但图片正文在传输中被中断：${describeError(error)}。`
      + '这是连接中断（网关断流、代理超时或跨域读取被拦截），不是图片格式问题；请重试或更换站点。',
      { retryable: true, diagnostics: { contentType: contentType || '未提供', phase: '读取正文' } },
    );
  }
  if (bytes.length === 0) {
    throw new ImagePayloadError(
      `站点返回了空的图片正文（Content-Type=${contentType || '未提供'}）。`,
      { retryable: true, diagnostics: { contentType: contentType || '未提供', byteLength: 0 } },
    );
  }
  return bytes;
}

function createImageUrl(bytes: Uint8Array, mime: string): string {
  if (typeof URL !== 'undefined' && typeof URL.createObjectURL === 'function' && typeof Blob === 'function') {
    return URL.createObjectURL(new Blob([bytes as BlobPart], { type: mime }));
  }
  return `data:${mime};base64,${encodeBase64(bytes)}`;
}

function unknownPayloadMessage(contentType: string, bytes: Uint8Array, text: string): string {
  const shape = /^</.test(text)
    ? '站点返回的是网页内容（多为登录页、验证页或网关错误页）'
    : '站点返回的内容既不是图片，也不是含图片字段的 JSON 或 base64';
  return `${shape}；Content-Type=${contentType || '未提供'}，长度 ${bytes.length} 字节，`
    + `开头字节 ${headHex(bytes)}，正文片段：${excerpt(text, TEXT_EXCERPT_LIMIT)}`;
}

function payloadDiagnostics(contentType: string, bytes: Uint8Array): Readonly<Record<string, unknown>> {
  return {
    contentType: contentType || '未提供',
    byteLength: bytes.length,
    headHex: headHex(bytes),
    bodyExcerpt: excerpt(decodeText(bytes.subarray(0, TEXT_EXCERPT_LIMIT)), TEXT_EXCERPT_LIMIT),
  };
}

function matchesBytes(bytes: Uint8Array, offset: number, pattern: readonly number[]): boolean {
  if (bytes.length < offset + pattern.length) return false;
  return pattern.every((value, index) => bytes[offset + index] === value);
}

function findBytes(bytes: Uint8Array, pattern: readonly number[], from: number): number {
  const first = pattern[0];
  if (first === undefined) return -1;
  for (let index = Math.max(0, from); index <= bytes.length - pattern.length; index += 1) {
    if (bytes[index] === first && matchesBytes(bytes, index, pattern)) return index;
  }
  return -1;
}

function nextZipBlockOffset(bytes: Uint8Array, from: number): number {
  return ZIP_BLOCK_HEADERS.reduce((end, header) => {
    const found = findBytes(bytes, header, from);
    return found >= 0 && found < end ? found : end;
  }, bytes.length);
}

function concatBytes(chunks: readonly Uint8Array[], total: number): Uint8Array {
  if (chunks.length === 1 && chunks[0]?.length === total) return chunks[0];
  const merged = new Uint8Array(total);
  let offset = 0;
  for (const chunk of chunks) {
    merged.set(chunk, offset);
    offset += chunk.length;
  }
  return merged;
}

function decodeText(bytes: Uint8Array): string {
  return new TextDecoder().decode(bytes);
}

function looksLikeSvg(bytes: Uint8Array): boolean {
  return /^\s*(?:<\?xml[^>]*\?>\s*)?(?:<!--[\s\S]*?-->\s*)?(?:<!DOCTYPE\s+svg[^>]*>\s*)?<svg[\s>]/i
    .test(decodeText(bytes.subarray(0, TEXT_SNIFF_LIMIT)));
}

function decodeBase64(padded: string): Uint8Array | null {
  if (typeof atob !== 'function') return null;
  try {
    const binary = atob(padded);
    const bytes = new Uint8Array(binary.length);
    for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index);
    return bytes;
  } catch {
    return null;
  }
}

function encodeBase64(bytes: Uint8Array): string {
  if (typeof btoa !== 'function') return '';
  const chunkSize = 0x8000;
  let binary = '';
  for (let index = 0; index < bytes.length; index += chunkSize) {
    binary += String.fromCharCode(...bytes.subarray(index, index + chunkSize));
  }
  return btoa(binary);
}

function headHex(bytes: Uint8Array): string {
  return [...bytes.subarray(0, HEAD_HEX_BYTES)]
    .map((byte) => byte.toString(16).padStart(2, '0'))
    .join(' ');
}