import type {
  AmbientPostDraft,
  AmbientTwitterCommentDraft,
  AmbientTwitterRepostDraft,
  AmbientTwitterTarget,
} from '../domain/commands.js';
import type { PhonePost, PhoneState } from '../domain/model.js';
import type { ImageProviderKind } from '../integration/sillytavern-bridge.js';
import { replaceImageMarkers } from './content-safety.js';
import { formatWorldTime } from '../time/world-clock.js';

export type AmbientPostPlatform = 'forum' | 'twitter';

/** 提示词里列出的历史动态编号表；解析转发/评论目标时用它还原真实帖子 id。 */
export interface AmbientTimelineRef {
  /** 给模型看的短编号，例如 p1。 */
  readonly ref: string;
  readonly postId: string;
}

export interface AmbientPostPrompt {
  readonly system: string;
  readonly user: string;
  readonly timeline: readonly AmbientTimelineRef[];
}

/** 一次推特刷新解析结果：独立动态 + 转发 + 评论。 */
export interface AmbientTwitterBatch {
  readonly posts: readonly AmbientPostDraft[];
  readonly reposts: readonly AmbientTwitterRepostDraft[];
  readonly comments: readonly AmbientTwitterCommentDraft[];
}

export interface AmbientPostPromptOptions {
  readonly platform: AmbientPostPlatform;
  readonly state: PhoneState;
  readonly selfProfileId: string;
  readonly count?: number;
  readonly worldBookExcerpt?: string | null;
  /** 当前实际启用的世界书条目名称，用于让模型区分本轮设定来源。 */
  readonly worldBookNames?: readonly string[];
  readonly imageProvider?: ImageProviderKind | null;
  /** 需要附带图片提示词的帖子序号（0-based），由调用方随机决定。 */
  readonly imagePostIndexes?: readonly number[];
}

function boundedRandom(random: () => number): number {
  const raw = random();
  return Number.isFinite(raw) ? Math.min(0.999_999, Math.max(0, raw)) : 0;
}

function selectRandomPostIndexes(
  count: number,
  selectedCount: number,
  random: () => number,
): readonly number[] {
  const candidates = Array.from({ length: count }, (_, index) => index);
  for (let index = candidates.length - 1; index > 0; index -= 1) {
    const swapIndex = Math.floor(boundedRandom(random) * (index + 1));
    [candidates[index], candidates[swapIndex]] = [candidates[swapIndex]!, candidates[index]!];
  }
  return candidates.slice(0, selectedCount).sort((left, right) => left - right);
}

/** 在本批次中随机选出要附带图片提示词的帖子；至少一条，最多三条。 */
export function selectAmbientImagePostIndexes(
  count: number,
  random: () => number = Math.random,
): readonly number[] {
  const normalizedCount = normalizeCount(count);
  const maximumImageCount = Math.min(3, normalizedCount);
  const imageCount = 1 + Math.floor(boundedRandom(random) * maximumImageCount);
  return selectRandomPostIndexes(normalizedCount, imageCount, random);
}

export function buildAmbientPostPrompt(options: AmbientPostPromptOptions): AmbientPostPrompt {
  const count = normalizeCount(options.count);
  const platformLabel = options.platform === 'twitter' ? 'X（推特）' : '论坛';
  const preferenceSignals = collectPreferenceSignals(options.state, options.selfProfileId, options.platform);
  const timeline = selectTimelineEntries(options.state, options.platform, options.selfProfileId);
  const recentAuthorNames = [...new Set(timeline.map((entry) => entry.authorName))];
  const imagePostIndexes = normalizeImagePostIndexes(options.imagePostIndexes, count, options.imageProvider);
  const imageRules = buildAmbientImageRules(
    options.imageProvider ?? null,
    imagePostIndexes,
  );
  const platformRules = options.platform === 'twitter'
    ? buildTwitterFeedRules(timeline.map((entry) => entry.ref), count)
    : [
        '世界书没有规定论坛主题范围时，才把兴趣信号作为选题参考；世界书规定了专属功能、主题或内容范围时，只生成规定范围内的内容。',
        '世界书没有规定发帖人时，作者名才使用自然且彼此不同的论坛昵称；若规定了固定、唯一或受限发帖人，每条 authorName 必须严格使用该身份，禁止创建其他作者。',
        '世界书没有规定帖子结构时，论坛内容才使用 title 和 content 字段；若规定了栏目、面板或字段，则按世界书要求完整体现。',
      ];
  const postShape = options.platform === 'forum'
    ? { authorName: '昵称', title: '标题', content: '正文' } as Record<string, string>
    : { authorName: '昵称', content: '正文' } as Record<string, string>;
  if (imagePostIndexes.length > 0) postShape.imagePrompt = '仅指定序号必须提供';
  const returnShape: Record<string, unknown> = { posts: [postShape] };
  if (options.platform === 'twitter') {
    returnShape.reposts = [{ authorName: '昵称', target: 'p1 或 n1', comment: '转发附言，可省略' }];
    returnShape.comments = [{ authorName: '昵称', target: 'p1 或 n1', content: '评论正文' }];
  }
  const system = [
    `你是${platformLabel}内容生成器，只输出严格 JSON，不输出 markdown、解释或其他文字。`,
    '世界书设定是本次生成的最高优先级硬约束：先完整阅读 settingExcerpt，再决定平台的存在形式、发帖人资格、可讨论范围、内容格式、时代背景和语言风格。世界书没有允许的内容不要自行补充；如果世界书把平台限制为单一发帖人或特殊用途，必须严格遵守，不得退回通用公共论坛或其他通用公共平台。',
    `世界书没有写${platformLabel}这类平台时不要拒绝生成、也不要返回空批次：改为依据世界书给出的世界观、时代、地域、人群与正在发生的事，推断这个世界里该平台的形态、参与者和话题；世界书完全没有可推断线索时才使用与平台相符的中性内容。`,
    '本次只使用当前请求附带的世界书条目；不要使用上一次刷新、其他平台或角色卡中未附带条目的设定。',
    `当前启用世界书条目：${options.worldBookNames?.length ? options.worldBookNames.join('、') : '未提供条目名称'}。`,
    '兴趣信号和历史平台内容只能作为参考，不能覆盖世界书，也不能把其中的主题或作者类型变成默认要求。',
    'timeline 只用于两件事：避免重复已经出现过的选题，以及给转发或评论指定目标。禁止把它当成对话上文。',
    '不得围绕用户，不得称呼、提及、影射或描写用户，也不得回应用户发过的内容；不得使用私聊、通讯录、真实姓名映射或用户经历。',
    ...platformRules,
    ...imageRules,
    `返回格式：${JSON.stringify(returnShape)}`,
  ].join('\n');
  const user = JSON.stringify({
    platform: options.platform,
    count,
    currentTime: formatWorldTime(options.state.worldClock.now),
    preferenceSignals,
    timeline: timeline.map((entry) => ({ ref: entry.ref, authorName: entry.authorName, digest: entry.digest })),
    recentAuthorNames,
    ...(imagePostIndexes.length > 0
      ? {
          imageGeneration: {
            provider: options.imageProvider,
            postIndexes: imagePostIndexes,
            postNumbers: imagePostIndexes.map((index) => index + 1),
          },
        }
      : {}),
    ...(options.worldBookExcerpt?.trim()
      ? {
          settingExcerpt: options.worldBookExcerpt.trim(),
          settingEntryNames: options.worldBookNames ?? [],
        }
      : {}),
  }, null, 2);
  return { system, user, timeline: timeline.map(({ ref, postId }) => ({ ref, postId })) };
}

interface AmbientTimelineEntry extends AmbientTimelineRef {
  readonly authorName: string;
  readonly digest: string;
}

/**
 * 历史动态只以「作者 + 短摘要」进入提示词：
 * 完整正文会把信息流变成对话上文，模型会顺着往下接，生成出隔空回应式的推文。
 * 用户自己的动态与评论层内容都排除在外，转发/评论只能指向别人的主贴。
 */
function selectTimelineEntries(
  state: PhoneState,
  platform: AmbientPostPlatform,
  selfProfileId: string,
): readonly AmbientTimelineEntry[] {
  return selectPlatformPosts(state, platform)
    .filter((post) => post.profileId !== selfProfileId && post.kind !== 'twitter-reply' && post.kind !== 'forum-reply')
    .slice(-12)
    .map((post, index) => ({
      ref: `p${index + 1}`,
      postId: post.id,
      authorName: authorNameOf(state, post, platform),
      digest: digestOf(post),
    }));
}

function authorNameOf(state: PhoneState, post: PhonePost, platform: AmbientPostPlatform): string {
  const profile = state.profiles[post.profileId];
  if (!profile) return '未知账号';
  const platformName = platform === 'twitter' ? profile.twitterName : profile.forumName;
  return (platformName?.trim() || profile.displayName).slice(0, 40);
}

function digestOf(post: PhonePost): string {
  const body = replaceImageMarkers(post.content, '').replace(/\s+/g, ' ').trim();
  return `${post.title ? `${post.title}｜` : ''}${body}`.slice(0, 60);
}

function normalizePostIndexes(
  indexes: readonly number[] | undefined,
  count: number,
): readonly number[] {
  if (!indexes) return [];
  return [...new Set(indexes
    .filter((index) => Number.isInteger(index) && index >= 0 && index < count))]
    .sort((left, right) => left - right);
}

function normalizeImagePostIndexes(
  indexes: readonly number[] | undefined,
  count: number,
  provider: ImageProviderKind | null | undefined,
): readonly number[] {
  return provider ? normalizePostIndexes(indexes, count) : [];
}

function buildTwitterFeedRules(timelineRefs: readonly string[], count: number): readonly string[] {
  const newRefs = Array.from({ length: count }, (_, index) => `n${index + 1}`).join('、');
  const targetHint = timelineRefs.length > 0
    ? `target 只能填 timeline 里的 ${timelineRefs.join('、')}，或本批次新动态的 ${newRefs}`
    : `timeline 为空，target 只能填本批次新动态的 ${newRefs}`;
  return [
    '模拟当前世界书规定的 X 信息流；如果世界书没有规定平台表现，再使用短文本、不同作者和自然的网络表达作为中性格式兜底。',
    'contentRating 仅在世界书明确要求分级或平台数据结构需要时提供；世界书未要求时省略该字段。',
    '不要因为平台名称、历史帖子或插件默认值，自行加入成人向、露骨、争议、游戏、动漫、热点、城市观察或其他固定主题。',
    '每条 content 的长度、语言、标点、表情符号、话题标签和作者身份均服从世界书；未规定时才使用 5-280 字的短文本。',
    'posts 里的每条动态都是各自独立发布的公开内容：禁止 @、点名、引用、承接、附和或反驳 timeline 中的任何内容，'
      + '也禁止本批次两条动态互相搭话，禁止写成一问一答、隔空对话或连载式回应。每条都必须能被单独看懂。',
    `账号之间需要互动时，只能用 reposts（转发）与 comments（评论区留言）表达，不要写进 posts 正文。${targetHint}。`,
    '只有世界书要求账号之间互相转发、评论、引用、声援或围观时才输出 reposts 与 comments；世界书没有这类要求时，两个数组都留空。'
      + '同一个 authorName 不得转发或评论自己的动态。',
    '除非世界书把发帖人限定为固定、唯一或受限账号，本批次的 authorName 必须互不相同，'
      + '并优先启用 recentAuthorNames 里还没出现过的世界书角色、组织或群体身份，让世界观里更多角色轮换到台前，不要总是同两三个账号。',
  ];
}

function buildAmbientImageRules(
  provider: ImageProviderKind | null,
  imagePostIndexes: readonly number[],
): readonly string[] {
  if (!provider || imagePostIndexes.length === 0) {
    return ['本批次不生成图片提示词；所有帖子都必须省略 imagePrompt。'];
  }
  const postNumbers = imagePostIndexes.map((index) => index + 1);
  const common = `仅第 ${postNumbers.join('、')} 条帖子必须提供 imagePrompt，其他帖子必须省略该字段；`
    + `本批次恰好 ${imagePostIndexes.length} 条带图，不得擅自给其余帖子补图。`
    + 'imagePrompt 描述对应内容中实际出现的照片、插画或图片，必须与对应 content 直接一致，不得描写、影射或包含用户及用户联系人。'
    + 'imagePrompt 只放提示词，不要自行写 image### 标记、Markdown 图片、URL、解释、负面提示词或中文说明。';
  if (provider === 'novelai') {
    return [
      common,
      '当前供应商是 NovelAI。imagePrompt 必须使用 NAI 多角色结构化英文 Danbooru 格式，段落用英文分号分隔，并以 Scene Composition: 开头。'
        + '纯风景、食物、宠物或物品照片只写 Scene Composition；有人物时再按人数添加 Character N Prompt，可附 |centers:c3，最多 4 人。'
        + '成人向图片必须在 Scene Composition 紧跟冒号后写 nsfw，并使用 18+、18-year-old、adult、adult female、adult male、mature 等成年表达；不要禁止 girl、boy、young、school uniform 等单独标签。'
        + '普通示例：Scene Composition:night market,food stall,warm lighting,close-up,no humans;'
        + ' 或 Scene Composition:1woman,adult female,bookstore interior,afternoon,upper body;Character 1 Prompt:adult woman,short brown hair,casual coat,holding book,smile|centers:c3;',
    ];
  }
  if (provider === 'openai') {
    return [
      common,
      '当前供应商是 OpenAI 兼容生图。imagePrompt 使用完整自然的英文摄影描述，写清主体、环境、时间、光线、镜头和构图，不要使用 Danbooru 字段名。',
    ];
  }
  return [
    common,
    `当前供应商是 ${provider === 'sdwebui' ? 'SD WebUI' : 'ComfyUI'}。imagePrompt 使用英文逗号分隔的 Danbooru/Stable Diffusion 正面标签，按主体、外观、动作、场景、光线、镜头、构图排列。`,
  ];
}

export function parseAmbientPosts(
  raw: string,
  platform: AmbientPostPlatform,
  existingContents: readonly string[] = [],
  requestedCount = 3,
  imageOptions: {
    readonly provider: ImageProviderKind | null;
    readonly postIndexes: readonly number[];
  } = { provider: null, postIndexes: [] },
): readonly AmbientPostDraft[] {
  const parsed = parseJsonObject(raw);
  return parsePostDrafts(parsed, platform, existingContents, requestedCount, imageOptions);
}

/**
 * 解析一次推特刷新的完整产出。转发与评论只有在世界书要求时才会出现，
 * 因此这里对它们宽容处理：目标解析不出来就丢弃，不影响独立动态入库。
 */
export function parseAmbientTwitterBatch(
  raw: string,
  options: {
    readonly timeline: readonly AmbientTimelineRef[];
    readonly existingContents?: readonly string[];
    readonly count?: number;
    readonly image?: {
      readonly provider: ImageProviderKind | null;
      readonly postIndexes: readonly number[];
    };
  },
): AmbientTwitterBatch {
  const parsed = parseJsonObject(raw);
  const posts = parsePostDrafts(
    parsed,
    'twitter',
    options.existingContents ?? [],
    options.count ?? 3,
    options.image ?? { provider: null, postIndexes: [] },
  );
  const timeline = options.timeline;
  const reposts = toRecordArray(parsed.reposts).flatMap((record) => {
    const authorName = cleanText(record.authorName, 24);
    const target = resolveAmbientTarget(record.target, timeline, posts.length);
    if (!authorName || !target) return [];
    const comment = cleanText(record.comment, 280, false, true);
    return [{ authorName, target, ...(comment ? { comment } : {}) } satisfies AmbientTwitterRepostDraft];
  }).slice(0, 4);
  const comments = toRecordArray(parsed.comments).flatMap((record) => {
    const authorName = cleanText(record.authorName, 24);
    const content = cleanText(record.content, 300, false, true);
    const target = resolveAmbientTarget(record.target, timeline, posts.length);
    if (!authorName || !content || !target) return [];
    return [{ authorName, target, content } satisfies AmbientTwitterCommentDraft];
  }).slice(0, 8);
  return { posts, reposts, comments };
}

function toRecordArray(value: unknown): readonly Record<string, unknown>[] {
  if (!Array.isArray(value)) return [];
  return value.flatMap((item) => (
    item && typeof item === 'object' && !Array.isArray(item) ? [item as Record<string, unknown>] : []
  ));
}

/** `p1` 指向 timeline 里的历史动态，`n1` 指向本批次第 1 条新动态。 */
function resolveAmbientTarget(
  value: unknown,
  timeline: readonly AmbientTimelineRef[],
  postCount: number,
): AmbientTwitterTarget | null {
  const raw = typeof value === 'string'
    ? value.trim().toLowerCase()
    : typeof value === 'number' && Number.isInteger(value)
      ? `p${value}`
      : '';
  if (!raw) return null;
  const batch = /^n(\d+)$/.exec(raw);
  if (batch) {
    const index = Number(batch[1]) - 1;
    return index >= 0 && index < postCount ? { kind: 'batchPost', index } : null;
  }
  const entry = timeline.find((item) => item.ref.toLowerCase() === raw);
  return entry ? { kind: 'existing', postId: entry.postId } : null;
}

function parsePostDrafts(
  parsed: Record<string, unknown>,
  platform: AmbientPostPlatform,
  existingContents: readonly string[],
  requestedCount: number,
  imageOptions: {
    readonly provider: ImageProviderKind | null;
    readonly postIndexes: readonly number[];
  },
): readonly AmbientPostDraft[] {
  const values = Array.isArray(parsed.posts) ? parsed.posts : [];
  const limit = normalizeCount(requestedCount);
  if (values.length !== limit) {
    throw new Error(`AI 必须返回恰好 ${limit} 条帖子，实际返回 ${values.length} 条`);
  }
  const knownContents = new Set(existingContents
    .map((content) => normalizeForComparison(replaceImageMarkers(content, '')))
    .filter(Boolean));
  const drafts: AmbientPostDraft[] = [];
  const imagePostIndexes = new Set(normalizeImagePostIndexes(imageOptions.postIndexes, limit, imageOptions.provider));
  const acceptedImageIndexes = new Set<number>();

  for (const [index, value] of values.entries()) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) continue;
    const record = value as Record<string, unknown>;
    const authorName = cleanText(record.authorName, 24);
    const sourceContent = typeof record.content === 'string' ? record.content : '';
    if (/(?:image###|\[\[生图[:：])/i.test(sourceContent)) {
      throw new Error(`AI 返回的第 ${index + 1} 条帖子含有非法图片标记`);
    }
    const rawContent = replaceImageMarkers(sourceContent, '');
    const cleaned = cleanText(rawContent, platform === 'twitter' ? 500 : 1_200, true, platform === 'twitter');
    const content = platform === 'twitter' ? stripAirReplyAddressing(cleaned) : cleaned;
    const title = platform === 'forum' ? cleanText(record.title, 80) : '';
    const contentKey = normalizeForComparison(content);
    if (!authorName || !content || !contentKey || knownContents.has(contentKey)) continue;
    if (platform === 'forum' && !title) continue;
    const requiresImage = imagePostIndexes.has(index);
    const imagePrompt = requiresImage
      ? cleanImagePrompt(record.imagePrompt, imageOptions.provider)
      : '';
    if (requiresImage && !imagePrompt) {
      throw new Error(`AI 返回的第 ${index + 1} 条帖子缺少有效图片提示词`);
    }
    const richContent = imagePrompt ? `${content}\n\nimage###${imagePrompt}###` : content;
    if (requiresImage) acceptedImageIndexes.add(index);
    knownContents.add(contentKey);
    drafts.push({ authorName, content: richContent, ...(title ? { title } : {}) });
    if (drafts.length >= limit) break;
  }

  if (drafts.length !== limit) {
    throw new Error(`AI 必须返回 ${limit} 条可用的新帖子，实际只有 ${drafts.length} 条`);
  }
  if ([...imagePostIndexes].some((index) => !acceptedImageIndexes.has(index))) {
    throw new Error('AI 返回的带图帖子不完整，请重试刷新');
  }
  return drafts;
}

/**
 * 去掉 X 回复体裁的开头称呼（@某人、回复@某人：）。
 * 独立动态一旦以称呼开头，读起来就是在跟另一条推文对话，即隔空回应。
 */
function stripAirReplyAddressing(content: string): string {
  return content
    .replace(/^\s*(?:回复|回覆|@?回应)?\s*(?:@[^\s@：:，,]{1,24}[\s，,：:]*)+/u, '')
    .trim();
}

function cleanImagePrompt(
  value: unknown,
  provider: ImageProviderKind | null,
): string {
  if (typeof value !== 'string' || !provider) return '';
  let prompt = value.replace(/\u0000/g, '').trim().slice(0, 2_000);
  if (!prompt || /(?:###|\[\[生图|https?:\/\/|```|负面提示词|negative prompt)/i.test(prompt)) return '';
  if (/\p{Script=Han}/u.test(prompt)) return '';
  if (/(?:\b(?:underage|minor|child|children|loli|shota)\b|未成年|未满|儿童|小孩|幼女|幼男|萝莉|正太)/i.test(prompt)) return '';
  if (provider === 'novelai' && !/^scene\s+composition\s*:/i.test(prompt)) return '';
  if (provider === 'openai' && /\b(?:scene\s+composition|character\s+\d+\s+prompt)\s*:/i.test(prompt)) return '';
  if ((provider === 'sdwebui' || provider === 'comfyui') && !prompt.includes(',')) return '';
  return prompt;
}

function collectPreferenceSignals(
  state: PhoneState,
  selfProfileId: string,
  platform: AmbientPostPlatform,
): Record<string, unknown> {
  const posts = selectPlatformPosts(state, platform);
  const postsById = new Map(posts.map((post) => [post.id, post]));
  const likedPostIds = new Set(
    Object.values(state.interactions)
      .filter((interaction) => interaction.appId === platform
        && interaction.type === 'like'
        && interaction.actorProfileId === selfProfileId)
      .map((interaction) => interaction.targetId),
  );
  const commentedPostIds = new Set(
    Object.values(state.interactions)
      .filter((interaction) => interaction.appId === platform
        && interaction.type === 'comment'
        && interaction.actorProfileId === selfProfileId)
      .map((interaction) => interaction.targetId),
  );
  const followedProfileIds = platform === 'twitter'
    ? new Set(Object.values(state.interactions)
      .filter((interaction) => interaction.appId === 'twitter'
        && interaction.type === 'follow'
        && interaction.actorProfileId === selfProfileId)
      .map((interaction) => interaction.targetId))
    : new Set<string>();
  const formatSignalPost = (post: PhonePost) => ({
    ...(post.title ? { title: post.title } : {}),
    content: replaceImageMarkers(post.content, ''),
  });
  const selfProfile = state.profiles[selfProfileId];
  return {
    declaredInterests: [selfProfile?.bio, selfProfile?.twitterBio]
      .filter((value): value is string => Boolean(value?.trim()))
      .map((value) => value.trim()),
    likedTopics: [...likedPostIds].flatMap((id) => {
      const post = postsById.get(id);
      return post ? [formatSignalPost(post)] : [];
    }).slice(-8),
    discussedTopics: [...commentedPostIds].flatMap((id) => {
      const post = postsById.get(id);
      return post ? [formatSignalPost(post)] : [];
    }).slice(-6),
    followedTopics: posts
      .filter((post) => followedProfileIds.has(post.profileId))
      .slice(-8)
      .map(formatSignalPost),
  };
}

function selectPlatformPosts(state: PhoneState, platform: AmbientPostPlatform): readonly PhonePost[] {
  return state.postOrder.flatMap((id) => {
    const post = state.posts[id];
    return post?.appId === platform ? [post] : [];
  });
}

function parseJsonObject(raw: string): Record<string, unknown> {
  const trimmed = String(raw ?? '').trim();
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/i.exec(trimmed);
  const candidate = fenced?.[1] ?? trimmed;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('AI 返回的帖子格式无效');
  try {
    const value = JSON.parse(candidate.slice(start, end + 1)) as unknown;
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error();
    return value as Record<string, unknown>;
  } catch {
    throw new Error('AI 返回的帖子不是有效 JSON');
  }
}

const EMOJI_PATTERN = /[\p{Extended_Pictographic}\u{FE0F}\u{200D}\u{1F3FB}-\u{1F3FF}\u{1F1E6}-\u{1F1FF}\u{20E3}]/gu;

function cleanText(
  value: unknown,
  maxLength: number,
  preserveLineBreaks = false,
  preserveEmoji = false,
): string {
  if (typeof value !== 'string') return '';
  const withoutEmoji = preserveEmoji ? value.replace(/\u0000/g, '') : value.replace(/\u0000/g, '').replace(EMOJI_PATTERN, '');
  const normalized = preserveLineBreaks
    ? withoutEmoji.replace(/[\t ]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim()
    : withoutEmoji.replace(/\s+/g, ' ').trim();
  return normalized.slice(0, maxLength);
}

function normalizeForComparison(value: string): string {
  return value.toLocaleLowerCase('zh-CN').replace(/[^\p{L}\p{N}]+/gu, '').slice(0, 600);
}

function normalizeCount(value: number | undefined): number {
  return Math.min(6, Math.max(1, Math.round(value ?? 3)));
}