/**
 * 重绘后的滚动位置保持。
 *
 * 手机界面每次重绘都会清空内容区再重新构建整棵树，所有滚动容器的位置都会归零：
 * 在设置里勾一个世界书条目，列表就被弹回顶部，下一次勾选还得重新滑回去。
 *
 * 新旧节点没有引用关系，所以用「结构路径」当键：从根节点往下逐层拼
 * 标签名.class#同级序号。同一个页面重绘出来的结构一致，键就能对上；
 * 结构真的变了（换页面、条目数量变化）就对不上，退化成不还原，
 * 不会把位置错放到别的容器上。
 */

export type ScrollPositions = ReadonlyMap<string, { readonly top: number; readonly left: number }>;

function childKey(parentPath: string, child: Element, index: number): string {
  // is-scrolling 由滚动条显隐逻辑临时添加，不能影响重绘前后的容器身份。
  const stableClasses = (child.getAttribute('class') ?? '')
    .split(/\s+/u)
    .filter((className) => className && className !== 'is-scrolling')
    .join(' ');
  return `${parentPath}/${child.tagName}.${stableClasses}#${index}`;
}

/** 记录 root 子树里所有已经滚动过的容器位置；没滚动过的不记，省得白跑一趟。 */
export function captureScrollPositions(root: Element): ScrollPositions {
  const positions = new Map<string, { readonly top: number; readonly left: number }>();
  const visit = (node: Element, path: string): void => {
    let index = 0;
    for (const child of node.children) {
      const key = childKey(path, child, index);
      index += 1;
      if (child.scrollTop > 0 || child.scrollLeft > 0) {
        positions.set(key, { top: child.scrollTop, left: child.scrollLeft });
      }
      visit(child, key);
    }
  };
  visit(root, '');
  return positions;
}

/** 把记录下来的位置放回重建后的容器；没有记录的容器保持在顶部。 */
export function restoreScrollPositions(root: Element, positions: ScrollPositions | null): void {
  if (!positions || positions.size === 0) return;
  const visit = (node: Element, path: string): void => {
    let index = 0;
    for (const child of node.children) {
      const key = childKey(path, child, index);
      index += 1;
      const saved = positions.get(key);
      if (saved) {
        child.scrollTop = saved.top;
        child.scrollLeft = saved.left;
      }
      visit(child, key);
    }
  };
  visit(root, '');
}
