import { getCurrentCharacterData, getSillyTavernContext, getSillyTavernRequestHeaders, type SillyTavernContextShape } from './sillytavern-bridge.js';

export const STORY_SQL_REGEX_PREFIX = 'moyun-story-sql-display-';
const record = (value: unknown): Record<string, unknown> => value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
const pending = new Map<string, Promise<boolean>>();

/** 仅作用于助手回复的 Markdown；完整和流式未闭合围栏都隐藏，原始消息保持可执行。 */
export function storySqlDisplayRegexes(): readonly Record<string, unknown>[] {
  return ['`', '~'].map((marker, index) => ({
    id: `${STORY_SQL_REGEX_PREFIX}${index + 1}`,
    scriptName: `墨韵数据：隐藏正文 SQL${index ? '（波浪围栏）' : ''}`,
    findRegex: `/(^|\\r?\\n)[ \\t]*(${marker}{3,})[ \\t]*(?:sql|sqlite|sqlite3)[ \\t]*(?:\\r?\\n|$)[\\s\\S]*?(?:\\r?\\n[ \\t]*\\2${marker}*[ \\t]*(?=\\r?\\n|$)|(?![\\s\\S]))/gi`,
    replaceString: '$1', trimStrings: [], placement: [2], disabled: false,
    markdownOnly: true, promptOnly: false, runOnEdit: true, substituteRegex: 0, minDepth: null, maxDepth: null,
  }));
}

export function withStorySqlDisplayRegexes(existing: unknown): readonly unknown[] {
  const kept = Array.isArray(existing) ? existing.filter((item) => !String(record(item).id ?? '').startsWith(STORY_SQL_REGEX_PREFIX)) : [];
  return [...kept, ...storySqlDisplayRegexes()];
}

/** 当前角色的局部正则，重复核对不会重复保存。 */
export function ensureStorySqlDisplay(context: SillyTavernContextShape = getSillyTavernContext()): Promise<boolean> {
  const key = String(record(getCurrentCharacterData(context)).avatar ?? '');
  const current = pending.get(key);
  if (current) return current;
  const run = installStorySqlDisplay(context).finally(() => { if (pending.get(key) === run) pending.delete(key); });
  pending.set(key, run);
  return run;
}

async function installStorySqlDisplay(context: SillyTavernContextShape): Promise<boolean> {
  const character = record(getCurrentCharacterData(context));
  const avatar = character.avatar;
  if (typeof avatar !== 'string' || !avatar || context.characterId === undefined) return false;
  const data = record(character.data);
  const extensions = record(data.extensions);
  const next = withStorySqlDisplayRegexes(extensions.regex_scripts);
  const changed = JSON.stringify(next) !== JSON.stringify(extensions.regex_scripts);
  if (changed) {
    const response = await fetch('/api/characters/merge-attributes', {
      method: 'POST', headers: getSillyTavernRequestHeaders(context), credentials: 'include',
      body: JSON.stringify({ avatar, data: { extensions: { regex_scripts: next } } }),
    });
    if (!response.ok) throw new Error(`保存角色 SQL 隐藏正则失败：HTTP ${response.status}`);
    extensions.regex_scripts = next;
    data.extensions = extensions;
    character.data = data;
    if (typeof character.json_data === 'string') {
      try {
        const json = record(JSON.parse(character.json_data));
        const jsonData = record(json.data);
        jsonData.extensions = { ...record(jsonData.extensions), regex_scripts: next };
        json.data = jsonData;
        character.json_data = JSON.stringify(json);
      } catch { /* 其他字段交给宿主保存，本次只更新局部正则。 */ }
    }
  }
  const settings = context.extensionSettings;
  const allowed = settings && Array.isArray(settings.character_allowed_regex) ? settings.character_allowed_regex : [];
  const enabled = allowed.includes(avatar);
  if (settings && !enabled) {
    settings.character_allowed_regex = [...allowed, avatar];
    context.saveSettingsDebounced?.();
  }
  if ((changed || !enabled) && getCurrentCharacterData() === character) {
    const editor = typeof document === 'undefined' ? null : document.querySelector<HTMLInputElement>('#character_json_data');
    if (editor && typeof character.json_data === 'string') editor.value = character.json_data;
    for (const [id, message] of (context.chat ?? []).entries()) context.updateMessageBlock?.(id, message, { rerenderMessage: true });
  }
  return changed || !enabled;
}
