export class DataCenterInactiveError extends Error {
  constructor() {
    super('数据中心未启用或本次操作已失效，请启用数据中心后重新操作。');
    this.name = 'DataCenterInactiveError';
  }
}

/** 关闭或切换聊天会永久作废旧任务；随后重新启用也不会让旧结果恢复写入资格。 */
export class DataCenterAccess {
  #epoch = 0;

  constructor(
    readonly isEnabled: () => boolean,
    private readonly scope: () => string = () => '',
  ) {}

  invalidate(): void {
    this.#epoch += 1;
  }

  capture(): () => boolean {
    const epoch = this.#epoch;
    const scope = this.scope();
    return () => this.isEnabled() && epoch === this.#epoch && scope === this.scope();
  }

  require(): () => void {
    const isCurrent = this.capture();
    const assertCurrent = (): void => {
      if (!isCurrent()) throw new DataCenterInactiveError();
    };
    assertCurrent();
    return assertCurrent;
  }
}
