export type Unsubscribe = () => void;

export class EventBus<TEvents extends object> {
  readonly #listeners = new Map<keyof TEvents, Set<(payload: unknown) => void>>();

  on<TKey extends keyof TEvents>(key: TKey, listener: (payload: TEvents[TKey]) => void): Unsubscribe {
    const listeners = this.#listeners.get(key) ?? new Set();
    listeners.add(listener as (payload: unknown) => void);
    this.#listeners.set(key, listeners);
    return () => {
      listeners.delete(listener as (payload: unknown) => void);
      if (listeners.size === 0) this.#listeners.delete(key);
    };
  }

  emit<TKey extends keyof TEvents>(key: TKey, payload: TEvents[TKey]): void {
    for (const listener of [...(this.#listeners.get(key) ?? [])]) {
      listener(payload);
    }
  }

  clear(): void {
    this.#listeners.clear();
  }
}

export class CleanupStack {
  readonly #cleanups: Array<() => void> = [];
  #disposed = false;

  add(cleanup: (() => void) | null | undefined): void {
    if (!cleanup) return;
    if (this.#disposed) {
      cleanup();
      return;
    }
    this.#cleanups.push(cleanup);
  }

  dispose(): void {
    if (this.#disposed) return;
    this.#disposed = true;
    for (const cleanup of this.#cleanups.splice(0).reverse()) {
      try {
        cleanup();
      } catch (error) {
        console.warn('[墨韵手机] 清理资源失败', error);
      }
    }
  }
}