/**
 * 变量树 → 数据中心表格（混合映射）。
 *
 * 四种形态，按「能不能一眼看懂」排优先级：
 * - 同构兄弟组（≥2 个字段集高度重合的兄弟对象）→ 一张多行实体表，首列 `entity` 区分对象；
 * - `z.record(...)` 动态字典 → 同样是实体表，成员为零也先按模板把列建出来；
 * - 单个分组（含嵌套）→ 一张单行宽表，嵌套路径展平成列（`身心状态·着装·上装`）；
 * - 列数超限或结构无法归一 → 该分组降级成「路径/值/说明」键值表，降级点写进 issues。
 *
 * 嵌套展平是刻意的：真实卡的角色状态普遍有两三层（`角色.某人.身心状态.着装`），
 * 一律降级键值表会得到几十上百行的长表，模型既读不懂也改不准。
 *
 * 副产物 `MvuMapping` 是接管方案的真值来源：正向投影与反向 `_.set` 翻译都查它。
 */

import { buildRowTemplate, type SheetPresetEntry } from '../db/sheet-preset.js';
import { hashText, isUsableColumnName, type SheetPolicy } from '../db/sheet-dsl.js';
import { keyFlagsOf, makeLeaf, mvuNodeValue } from './init-var.js';
import { joinMvuPath, splitMvuPath } from './mapping.js';
import type {
  MvuGroupNode,
  MvuLeafNode,
  MvuMapping,
  MvuMappingEntry,
  MvuNode,
  MvuTree,
  MvuTreeEntry,
} from './types.js';

export type MvuSheetShape = 'wide' | 'entity' | 'keyValue' | 'global';

export interface MvuSheetPlanEntry {
  readonly sheet: SheetPresetEntry;
  /** 这张表覆盖的 MVU 顶层键；更新规则按它归属到表。 */
  readonly origins: readonly string[];
  readonly shape: MvuSheetShape;
  /** `_` 前缀的只读列标签；填表规则里要明确禁止写入。 */
  readonly readOnlyLabels: readonly string[];
  /** `$` 前缀的内部标记列标签；对 AI 不可见，不该主动改。 */
  readonly hiddenLabels: readonly string[];
}

export interface MvuSheetPlan {
  readonly entries: readonly MvuSheetPlanEntry[];
  readonly mapping: MvuMapping;
  readonly issues: readonly string[];
}

export const MVU_GLOBAL_SHEET_NAME = '全局标记';
export const MVU_ENTITY_COLUMN = 'entity';
const MVU_ENTITY_LABEL = '对象';
/** `z.record(z.string(), z.string())` 这种「名字 → 标量」字典，值单独占一列。 */
const MVU_RECORD_VALUE_LABEL = '值';
const KEY_VALUE_COLUMNS = ['path', 'value', 'note'] as const;
const KEY_VALUE_LABELS = ['路径', '值', '说明'] as const;
const LIST_SEPARATOR = '、';
const LABEL_SEPARATOR = '·';
const MAX_COLUMNS = 60;
/** 字段集重合度阈值：低于它就不当成同构兄弟，各自成表。 */
const FAMILY_OVERLAP = 0.6;
const CHARACTER_HINTS = ['好感度', '信任度', '心理', '着装', '姓名', '年龄', '性格', '服从', '堕落', '羞耻'];

/** 展平后的一个字段：路径相对所在分组，标签用 `·` 连接嵌套键。 */
interface FlatField {
  readonly path: string;
  readonly label: string;
  readonly leaf: MvuLeafNode;
}

function isGroup(node: MvuNode): node is MvuGroupNode {
  return node.kind === 'group';
}

/** 展平分组下的全部叶子（含嵌套），保持声明顺序。 */
function flattenFields(group: MvuGroupNode, pathPrefix = '', labelPrefix = ''): readonly FlatField[] {
  return group.entries.flatMap((entry): readonly FlatField[] => {
    const path = joinMvuPath([...splitMvuPath(pathPrefix), entry.key]);
    const label = labelPrefix ? `${labelPrefix}${LABEL_SEPARATOR}${entry.key}` : entry.key;
    if (entry.node.kind === 'leaf') return [{ path, label, leaf: entry.node }];
    if (entry.node.record || entry.node.entries.length === 0) return [{ path, label,
      leaf: makeLeaf(JSON.stringify(mvuNodeValue(entry.node)), entry.node.desc ?? '', keyFlagsOf(entry.key), 'json'),
    }];
    return flattenFields(entry.node, path, label);
  });
}

/** 分组的字段指纹：展平路径集合，用来判断兄弟对象是不是同构。 */
function fieldSignature(group: MvuGroupNode): readonly string[] {
  return flattenFields(group).map((field) => field.path);
}

function overlap(left: readonly string[], right: readonly string[]): number {
  if (left.length === 0 || right.length === 0) return 0;
  const rightSet = new Set(right);
  const shared = left.filter((key) => rightSet.has(key)).length;
  return shared / Math.max(left.length, right.length);
}

/** 成员分组：直接子节点全是分组，且彼此字段高度重合。`record` 分组无条件算。 */
function isEntityGroup(node: MvuGroupNode): boolean {
  if (node.record) return true;
  if (node.entries.length < 2 || !node.entries.every((entry) => isGroup(entry.node))) return false;
  const signatures = node.entries.map((entry) => fieldSignature(entry.node as MvuGroupNode));
  const head = signatures[0] ?? [];
  return signatures.every((signature) => overlap(signature, head) >= FAMILY_OVERLAP);
}

/**
 * 单元格文本：列表用中文顿号连接，null 写空串。
 *
 * MVU 卡常把状态栏的渲染模板塞进 stat_data，值实际是 `<%= _cos %>`、
 * `<%_ if (_preg) _%>` 这类源码，依赖展示层运行时才注入的局部变量。
 * 这种值不是数据快照：写进表只会污染注入内容，还会让宿主渲染提示词时抛
 * `not defined` 并中断整轮生成，因此整值作废。
 */
export function cellTextOfLeaf(leaf: MvuLeafNode): string {
  if (leaf.value === null && leaf.nullable) return 'null';
  const raw = Array.isArray(leaf.value)
    ? leaf.value.some((item) => typeof item !== 'string' || item.includes(LIST_SEPARATOR)) ? JSON.stringify(leaf.value)
      : leaf.value.join(LIST_SEPARATOR)
    : (leaf.value === null ? '' : String(leaf.value));
  return raw.includes('<%') ? '' : raw;
}

/**
 * 中文键 → 可直接进 DDL 的 ASCII 列名。
 * 拿不到 ASCII 词根时退化成稳定哈希：列名只是载体，语义由中文标签承担。
 * 刻意不给纯中文键套 `_col` 之类的空壳名——那样第一列会莫名叫 `_col`，读日志的人只会更困惑。
 */
export function toColumnName(key: string, taken: readonly string[]): string {
  const ascii = key.normalize('NFKD').toLowerCase().replace(/[^a-z0-9_]+/g, '_').replace(/^_+|_+$/g, '').slice(0, 40);
  const hashed = `c_${hashText(key).slice(0, 6)}`;
  const candidates = ascii ? [ascii, `${ascii}_col`, hashed] : [hashed];
  for (const candidate of candidates) {
    if (!candidate || !isUsableColumnName(candidate) || taken.includes(candidate)) continue;
    return candidate;
  }
  for (let index = 2; index < 100; index += 1) {
    const candidate = `c_${hashText(key).slice(0, 6)}_${index}`;
    if (isUsableColumnName(candidate) && !taken.includes(candidate)) return candidate;
  }
  return `c_${hashText(`${key}|${taken.length}`)}`;
}

function uniqueSheetName(base: string, taken: readonly string[]): string {
  const trimmed = base.trim().slice(0, 50) || '未命名分组';
  if (!taken.includes(trimmed)) return trimmed;
  for (let index = 2; index < 100; index += 1) {
    const candidate = `${trimmed}${index}`;
    if (!taken.includes(candidate)) return candidate;
  }
  return `${trimmed}${hashText(trimmed).slice(0, 4)}`;
}

interface SheetDraft {
  readonly name: string;
  readonly purpose: string;
  readonly columns: readonly string[];
  readonly labels: readonly string[];
  readonly policy: SheetPolicy;
  readonly rows: readonly (readonly string[])[];
  readonly origins: readonly string[];
  readonly shape: MvuSheetShape;
  readonly readOnlyLabels: readonly string[];
  readonly hiddenLabels: readonly string[];
}

function toPresetEntry(draft: SheetDraft, orderNo: number): SheetPresetEntry {
  return {
    name: draft.name,
    purpose: draft.purpose,
    columns: draft.columns,
    labels: draft.labels,
    policy: draft.policy,
    rowTemplate: buildRowTemplate(draft.columns, draft.labels),
    tokenBudget: draft.policy === 'always' ? 512 : 256,
    orderNo,
    injectCondition: '',
    fillGuide: '',
    rows: draft.rows,
  };
}

interface BuildContext {
  readonly drafts: SheetDraft[];
  readonly mapping: MvuMappingEntry[];
  readonly issues: string[];
  readonly names: string[];
}

function pushWideSheet(
  context: BuildContext,
  groupKey: string,
  fields: readonly FlatField[],
  shape: 'wide' | 'global',
  absent = false,
): void {
  const name = uniqueSheetName(shape === 'global' ? MVU_GLOBAL_SHEET_NAME : groupKey, context.names);
  context.names.push(name);
  const columns: string[] = [];
  const labels: string[] = [];
  const row: string[] = [];
  for (const field of fields) {
    const column = toColumnName(field.label, columns);
    columns.push(column);
    labels.push(field.label);
    row.push(cellTextOfLeaf(field.leaf));
    context.mapping.push({
      path: joinMvuPath([...(groupKey ? [groupKey] : []), ...splitMvuPath(field.path)]),
      sheet: name,
      column,
      keyColumn: '',
      keyValue: '',
      desc: field.leaf.desc,
      valueType: field.leaf.valueType,
      readOnly: field.leaf.readOnly,
      defaultValue: cellTextOfLeaf(field.leaf),
      ...(field.leaf.constraints ? { constraints: field.leaf.constraints } : {}),
      ...(field.leaf.nullable ? { nullable: true } : {}),
      ...(absent || field.leaf.optional ? { optional: true } : {}),
    });
  }
  context.drafts.push({
    name,
    purpose: shape === 'global'
      ? '散落在变量树顶层的全局标记，例如剧情阶段与版本号；整表只有一行，变化时覆盖这一行。'
      : `${groupKey} 的当前状态；整表只有一行，字段变化时覆盖这一行，不要新增行。`,
    columns,
    labels,
    policy: 'always',
    rows: absent ? [] : [row],
    // 全局标记表没有分组名，规则按叶子键写（例如 `$剧情阶段:`），所以拿叶子键当归属键。
    origins: groupKey ? [groupKey] : labels,
    shape,
    readOnlyLabels: fields.filter((field) => field.leaf.readOnly).map((field) => field.label),
    hiddenLabels: fields.filter((field) => field.leaf.hidden).map((field) => field.label),
  });
}

interface EntityInput {
  readonly sheetName: string;
  readonly members: readonly MvuTreeEntry[];
  /** 成员路径前缀；顶层同构兄弟组为空串。 */
  readonly pathPrefix: string;
  readonly origins: readonly string[];
  /** `z.record(...)` 的成员模板：成员为零时靠它把列建出来。 */
  readonly template?: MvuNode | undefined;
}

function pushEntitySheet(context: BuildContext, input: EntityInput): void {
  const name = uniqueSheetName(input.sheetName, context.names);
  context.names.push(name);
  const columns: string[] = [MVU_ENTITY_COLUMN];
  const labels: string[] = [MVU_ENTITY_LABEL];
  const columnByPath = new Map<string, string>();
  const fieldByPath = new Map<string, FlatField>();
  const memberFields = input.members.map((member) => ({
    key: member.key,
    // 成员是标量时（`名字 → 值` 字典）给它一个匿名字段，路径就是成员本身。
    fields: isGroup(member.node)
      ? flattenFields(member.node)
      : [{ path: '', label: MVU_RECORD_VALUE_LABEL, leaf: member.node }],
  }));
  const declared = [
    ...(input.template ? input.template.kind === 'group' ? flattenFields(input.template)
      : [{ path: '', label: MVU_RECORD_VALUE_LABEL, leaf: input.template }] : []),
    ...memberFields.flatMap((member) => member.fields),
  ];
  for (const field of declared) {
    if (columnByPath.has(field.path)) continue;
    const column = toColumnName(field.label, columns);
    columnByPath.set(field.path, column);
    fieldByPath.set(field.path, field);
    columns.push(column);
    labels.push(field.label);
  }
  const rows = memberFields.map((member) => {
    const byPath = new Map(member.fields.map((field) => [field.path, field]));
    return [member.key, ...[...columnByPath.keys()].map((path) => {
      const field = byPath.get(path);
      return field ? cellTextOfLeaf(field.leaf) : cellTextOfLeaf(fieldByPath.get(path)!.leaf);
    })];
  });
  for (const member of memberFields) {
    for (const field of member.fields) {
      const column = columnByPath.get(field.path);
      if (!column) continue;
      context.mapping.push({
        path: joinMvuPath([...splitMvuPath(input.pathPrefix), member.key, ...splitMvuPath(field.path)]),
        sheet: name,
        column,
        keyColumn: MVU_ENTITY_COLUMN,
        keyValue: member.key,
        desc: field.leaf.desc,
        valueType: field.leaf.valueType,
        readOnly: field.leaf.readOnly,
        defaultValue: cellTextOfLeaf(field.leaf),
        ...(field.leaf.nullable ? { nullable: true } : {}),
        ...(field.leaf.optional ? { optional: true } : {}),
        ...(field.leaf.constraints ? { constraints: field.leaf.constraints } : {}),
      });
    }
  }
  // 成员无关的模板同时驱动正向投影和反向写入，空字典也具备新增成员的坐标。
  for (const [fieldPath, column] of columnByPath) {
    const field = fieldByPath.get(fieldPath)!;
    const prefix = splitMvuPath(input.pathPrefix);
    const suffix = splitMvuPath(fieldPath);
    context.mapping.push({
      path: joinMvuPath([...prefix, '*', ...suffix]), sheet: name, column, keyColumn: MVU_ENTITY_COLUMN, keyValue: '*',
      dynamic: { prefix, field: suffix }, desc: field.leaf.desc, valueType: field.leaf.valueType,
      readOnly: field.leaf.readOnly, defaultValue: cellTextOfLeaf(field.leaf),
      ...(field.leaf.nullable ? { nullable: true } : {}),
      ...(field.leaf.optional ? { optional: true } : {}),
      ...(field.leaf.constraints ? { constraints: field.leaf.constraints } : {}),
    });
  }
  const shown = input.members.map((member) => member.key).slice(0, 4).join('、');
  const fields = [...fieldByPath.values()];
  context.drafts.push({
    name,
    purpose: input.members.length > 0
      ? `${shown}${input.members.length > 4 ? '等' : ''}的状态；每个对象固定一行，用 UPDATE 改这一行，不要为同一对象新增行。`
      : `${input.sheetName} 的成员列表；出现新对象时 INSERT 一行，已有对象用 UPDATE 改这一行。`,
    columns,
    labels,
    policy: 'always',
    rows,
    origins: input.origins,
    shape: 'entity',
    readOnlyLabels: fields.filter((field) => field.leaf.readOnly).map((field) => field.label),
    hiddenLabels: fields.filter((field) => field.leaf.hidden).map((field) => field.label),
  });
}

function pushKeyValueSheet(context: BuildContext, groupKey: string, group: MvuGroupNode, reason: string): void {
  const name = uniqueSheetName(`${groupKey}（键值）`, context.names);
  context.names.push(name);
  const fields = flattenFields(group);
  const kept = fields;
  const rows = kept.map((field) => [field.path, cellTextOfLeaf(field.leaf), field.leaf.desc]);
  for (const field of kept) {
    context.mapping.push({
      path: joinMvuPath([groupKey, ...splitMvuPath(field.path)]),
      sheet: name,
      column: 'value',
      keyColumn: 'path',
      keyValue: field.path,
      desc: field.leaf.desc,
      valueType: field.leaf.valueType,
      readOnly: field.leaf.readOnly,
      defaultValue: cellTextOfLeaf(field.leaf),
      ...(field.leaf.constraints ? { constraints: field.leaf.constraints } : {}),
    });
  }
  context.issues.push(`${groupKey}：${reason}，已降级成「路径/值/说明」键值表。`);
  context.drafts.push({
    name,
    purpose: `${groupKey} 的层级数据，一行一个变量路径；改值请按 path 定位后 UPDATE value。`,
    columns: [...KEY_VALUE_COLUMNS],
    labels: [...KEY_VALUE_LABELS],
    policy: kept.length > 40 ? 'recall' : 'always',
    rows,
    origins: [groupKey],
    shape: 'keyValue',
    readOnlyLabels: kept.filter((field) => field.leaf.readOnly).map((field) => field.path),
    hiddenLabels: kept.filter((field) => field.leaf.hidden).map((field) => field.path),
  });
}

/** 顶层同构兄弟组的家族名：认得出角色字段就叫「角色状态」，否则用中性名。 */
function familyName(signature: readonly string[]): string {
  return signature.some((key) => CHARACTER_HINTS.some((hint) => key.includes(hint))) ? '角色状态' : '实体状态';
}

/** 顶层的兄弟分组按字段指纹归族：同族合成一张实体表，独苗各自成表。 */
function groupFamilies(records: readonly MvuTreeEntry[]): readonly (readonly MvuTreeEntry[])[] {
  const families: MvuTreeEntry[][] = [];
  for (const record of records) {
    const signature = fieldSignature(record.node as MvuGroupNode);
    if (signature.length < 2) {
      families.push([record]);
      continue;
    }
    const family = families.find((candidate) => {
      const head = candidate[0];
      if (!head) return false;
      const headSignature = fieldSignature(head.node as MvuGroupNode);
      return headSignature.length >= 2 && overlap(signature, headSignature) >= FAMILY_OVERLAP;
    });
    if (family) family.push(record);
    else families.push([record]);
  }
  return families;
}

/** 实体表的列并集大小（含 entity 列）：判断要不要降级键值表。 */
function entityColumnCount(group: MvuGroupNode): number {
  const paths = new Set<string>(group.template ? group.template.kind === 'group' ? fieldSignature(group.template) : [''] : []);
  for (const member of group.entries) {
    if (!isGroup(member.node)) {
      paths.add('');
      continue;
    }
    for (const path of fieldSignature(member.node)) paths.add(path);
  }
  return paths.size + 1;
}

/** 变量树 → 表结构 + 映射。纯函数：同一棵树永远得到同一批表名与列名。 */
export function planSheetsFromTree(tree: MvuTree): MvuSheetPlan {
  const context: BuildContext = { drafts: [], mapping: [], issues: [], names: [] };
  const topLeaves = tree.entries.filter((entry) => entry.node.kind === 'leaf');
  const topGroups = tree.entries.filter((entry) => isGroup(entry.node));
  const entityGroups = topGroups.filter((entry) => isEntityGroup(entry.node as MvuGroupNode));
  const plainGroups = topGroups.filter((entry) => !isEntityGroup(entry.node as MvuGroupNode));

  for (const entry of entityGroups) {
    const group = entry.node as MvuGroupNode;
    if (entityColumnCount(group) > MAX_COLUMNS) {
      const asJson = (node: MvuNode): MvuLeafNode => makeLeaf(JSON.stringify(mvuNodeValue(node)), '', keyFlagsOf(entry.key), 'json');
      pushEntitySheet(context, { sheetName: entry.key, pathPrefix: joinMvuPath([entry.key]), origins: [entry.key],
        members: group.entries.map((member) => ({ key: member.key, node: asJson(member.node) })),
        template: group.template ? asJson(group.template) : makeLeaf('{}', '', keyFlagsOf(entry.key), 'json'),
      });
      context.issues.push(`${entry.key}：成员字段超过 ${MAX_COLUMNS} 列，按「对象 / JSON 数据」保存完整结构。`);
      continue;
    }
    pushEntitySheet(context, {
      sheetName: entry.key,
      members: group.entries,
      pathPrefix: joinMvuPath([entry.key]),
      // 归属键连成员名一起收：规则常写 `络络:` 而不是 `角色:`。
      origins: [entry.key, ...group.entries.map((member) => member.key)],
      template: group.template,
    });
  }

  for (const family of groupFamilies(plainGroups)) {
    const head = family[0];
    if (!head) continue;
    const group = head.node as MvuGroupNode;
    if (family.length > 1) {
      const signature = fieldSignature(group);
      if (signature.length + 1 > MAX_COLUMNS) {
        for (const member of family) pushKeyValueSheet(context, member.key, member.node as MvuGroupNode, `字段数 ${signature.length} 超过 ${MAX_COLUMNS} 列上限`);
        continue;
      }
      pushEntitySheet(context, {
        sheetName: familyName(signature),
        members: family,
        pathPrefix: '',
        origins: family.map((member) => member.key),
      });
      continue;
    }
    const fields = flattenFields(group);
    if (fields.length === 0) {
      pushWideSheet(context, head.key, [{ path: '', label: '内容', leaf: makeLeaf('{}', '', keyFlagsOf(head.key), 'json') }], 'wide', group.optional && !group.present);
      continue;
    }
    if (fields.length > MAX_COLUMNS) {
      pushKeyValueSheet(context, head.key, group, `字段数 ${fields.length} 超过 ${MAX_COLUMNS} 列上限`);
      continue;
    }
    pushWideSheet(context, head.key, fields, 'wide', group.optional && !group.present);
  }

  if (topLeaves.length > 0) {
    pushWideSheet(context, '', flattenFields({ kind: 'group', entries: topLeaves }), 'global');
  }

  return {
    entries: context.drafts.map((draft, index) => ({
      sheet: toPresetEntry(draft, index),
      origins: draft.origins,
      shape: draft.shape,
      readOnlyLabels: draft.readOnlyLabels,
      hiddenLabels: draft.hiddenLabels,
    })),
    mapping: { version: 1, entries: context.mapping },
    issues: context.issues,
  };
}
