export type PhoneLogLevel = 'info' | 'warn' | 'error';

export interface PhoneLogEntry {
  readonly id: number;
  readonly timestamp: number;
  readonly level: PhoneLogLevel;
  readonly message: string;
  readonly detail?: string;
}

const CAPACITY = 800;
const DETAIL_LIMIT = 12_000;

let nextId = 1;
let paused = false;
const entries: PhoneLogEntry[] = [];
const listeners = new Set<() => void>();

function describeDetail(detail: unknown): string | undefined {
  if (detail === undefined || detail === null) return undefined;
  if (typeof detail === 'string') return detail.slice(0, DETAIL_LIMIT);
  if (detail instanceof Error) {
    return `${detail.message}${detail.stack ? `\n${detail.stack}` : ''}`.slice(0, DETAIL_LIMIT);
  }
  try {
    return JSON.stringify(detail).slice(0, DETAIL_LIMIT);
  } catch {
    return String(detail).slice(0, DETAIL_LIMIT);
  }
}

function record(level: PhoneLogLevel, message: string, detail?: unknown): void {
  // 同步镜像到控制台，方便配合浏览器 DevTools 排查。
  const consoleMethod = level === 'error' ? console.error : level === 'warn' ? console.warn : console.info;
  if (detail !== undefined) consoleMethod(`[墨韵手机] ${message}`, detail);
  else consoleMethod(`[墨韵手机] ${message}`);

  if (paused) return;
  const entry: PhoneLogEntry = {
    id: nextId++,
    timestamp: Date.now(),
    level,
    message: message.slice(0, 500),
    ...(describeDetail(detail) !== undefined ? { detail: describeDetail(detail) } : {}),
  };
  entries.push(entry);
  if (entries.length > CAPACITY) entries.splice(0, entries.length - CAPACITY);
  for (const listener of listeners) listener();
}

export const phoneLogger = {
  info(message: string, detail?: unknown): void {
    record('info', message, detail);
  },
  warn(message: string, detail?: unknown): void {
    record('warn', message, detail);
  },
  error(message: string, detail?: unknown): void {
    record('error', message, detail);
  },
  entries(): readonly PhoneLogEntry[] {
    return entries;
  },
  clear(): void {
    entries.length = 0;
    for (const listener of listeners) listener();
  },
  setPaused(value: boolean): void {
    paused = value;
    for (const listener of listeners) listener();
  },
  isPaused(): boolean {
    return paused;
  },
  subscribe(listener: () => void): () => void {
    listeners.add(listener);
    return () => listeners.delete(listener);
  },
  /** 导出为纯文本（一行一条）。 */
  exportText(): string {
    return entries
      .map((entry) => {
        const time = new Date(entry.timestamp).toLocaleString();
        const detail = entry.detail ? `\n    ${entry.detail.replace(/\n/g, '\n    ')}` : '';
        return `[${time}] [${entry.level.toUpperCase()}] ${entry.message}${detail}`;
      })
      .join('\n');
  },
};
