/**
 * MVU 数据桥：把「数据中心表格」摆到 MVU 的位置上。
 *
 * 两个方向：
 * - 正向投影：表内容 → 最新楼层的 `stat_data`。前端状态栏、EJS 模板、`{{getvar}}` 都是从变量读的，
 *   投影之后它们不用改一行代码就能读到数据中心的内容。
 * - 反向接管：装一个 `window.Mvu` 门面，旧脚本的 `getMvuData` 读投影快照，
 *   `replaceMvuData` / `parseMessage` / `setMvuVariable` 的写入翻译成表格写入。
 *
 * 安装时机很关键：酒馆助手的消息 iframe 只在创建那一刻从父窗口取 `Mvu`
 * （见 JS-Slash-Runner 的 `iframe/predefine.js`），所以门面必须在运行时启动早期就装好。
 */

import { phoneLogger } from '../core/logger.js';
import { getSillyTavernContext, getSillyTavernEventChannel } from './sillytavern-bridge.js';
import { getLastMessageIdSafe, readVariables, writeVariableByPath } from './variables-bridge.js';
import { parseMvuCommands } from '../mvu/commands.js';
import { isEmptyMapping, joinMvuPath, readByPath } from '../mvu/mapping.js';
import { planCommandWrites, projectStatData, type MvuSheetView, type MvuSheetWrite } from '../mvu/projection.js';
import type { MvuMapping } from '../mvu/types.js';

/** 数据桥依赖的数据中心能力；由运行时适配到 SQLite 引擎，便于单测替换。 */
export interface MvuBridgePort {
  readonly contextKey?: () => string;
  /** 当前是否应该接管（设置开关 + 当前预设带映射）。 */
  readonly isActive: () => boolean;
  readonly mapping: () => MvuMapping | null;
  readonly readViews: () => Promise<readonly MvuSheetView[]>;
  readonly applyWrites: (writes: readonly MvuSheetWrite[]) => Promise<number>;
  readonly captureAccess?: () => () => boolean;
}

export interface MvuBridgeStatus {
  readonly installed: boolean;
  /** 安装前是否已经存在真的 MVU（我们会把它存起来，卸载时还原）。 */
  readonly replacedForeignMvu: boolean;
  readonly mappedPaths: number;
  readonly missingPaths: number;
  readonly lastProjectedAt: number | null;
  readonly lastSkipped: readonly { readonly path: string; readonly reason: string }[];
}

export interface MvuProjectionOutcome {
  readonly ok: boolean;
  readonly message: string;
  readonly projectedPaths: number;
}

const MVU_EVENTS = Object.freeze({
  VARIABLE_INITIALIZED: 'mag_variable_initiailized',
  VARIABLE_UPDATE_STARTED: 'mag_variable_update_started',
  COMMAND_PARSED: 'mag_command_parsed',
  VARIABLE_UPDATE_ENDED: 'mag_variable_update_ended',
  BEFORE_MESSAGE_UPDATE: 'mag_before_message_update',
});

const FOREIGN_MVU_KEY = '__NARRATIVE_PHONE_ORIGINAL_MVU__';

interface MvuDataShape {
  readonly initialized_lorebooks: Record<string, unknown[]>;
  readonly stat_data: Record<string, unknown>;
  readonly display_data: Record<string, unknown>;
  readonly delta_data: Record<string, unknown>;
}

function getHostRecord(): Record<string, unknown> {
  try {
    const parent = globalThis.window?.parent as unknown as Record<string, unknown> | undefined;
    if (parent && (parent.SillyTavern || parent.TavernHelper)) return parent;
  } catch {
    // 受限 iframe 下回退当前窗口。
  }
  return globalThis as unknown as Record<string, unknown>;
}

function emptyData(): MvuDataShape {
  return { initialized_lorebooks: {}, stat_data: {}, display_data: {}, delta_data: {} };
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

/**
 * 同步读最新楼层的 `stat_data`。
 * `getMvuData` 必须同步返回，而页面刷新后到第一次投影之间快照是空的；
 * 楼层变量与投影同源，用它兜底，状态栏就不会在刷新后读到空对象。
 */
function readStatDataFromLatestFloor(): Record<string, unknown> | null {
  try {
    const context = getSillyTavernContext();
    const chat = Array.isArray(context.chat) ? context.chat : [];
    const message = chat[chat.length - 1] as Record<string, unknown> | undefined;
    if (!message) return null;
    const swipeId = Number(message.swipe_id ?? 0);
    const index = Number.isInteger(swipeId) && swipeId >= 0 ? swipeId : 0;
    const variables = message.variables;
    const bucket = Array.isArray(variables)
      ? asRecord(variables[index]) ?? asRecord(variables[0])
      : asRecord(asRecord(variables)?.[String(index)]) ?? asRecord(variables);
    return asRecord(bucket?.stat_data);
  } catch {
    return null;
  }
}

export function createMvuDataBridge(port: MvuBridgePort): {
  readonly install: () => void;
  readonly uninstall: () => void;
  readonly project: () => Promise<MvuProjectionOutcome>;
  readonly status: () => MvuBridgeStatus;
} {
  let snapshot: MvuDataShape = emptyData();
  let hasProjection = false;
  let allowFallback = true;
  let identity = '';
  let lifetime = 0;
  let chain: Promise<unknown> = Promise.resolve();
  let installed = false;
  let replacedForeignMvu = false;
  let lastProjectedAt: number | null = null;
  let mappedPaths = 0;
  let missingPaths = 0;
  let lastSkipped: readonly { readonly path: string; readonly reason: string }[] = [];

  const currentIdentity = (): string => JSON.stringify([port.contextKey?.() ?? '', port.mapping()]);
  const syncIdentity = (): void => {
    const next = currentIdentity();
    if (identity === next) return;
    allowFallback = !identity;
    identity = next;
    hasProjection = false;
    snapshot = emptyData();
    lastProjectedAt = null;
    mappedPaths = 0;
    missingPaths = 0;
    lastSkipped = [];
  };
  const serial = <T>(task: (isCurrent: () => boolean) => Promise<T>): Promise<T> => {
    syncIdentity();
    const key = identity, epoch = lifetime;
    const hasAccess = port.captureAccess?.() ?? port.isActive;
    const isCurrent = (): boolean => hasAccess() && port.isActive() && epoch === lifetime && key === currentIdentity();
    const run = chain.then(() => task(isCurrent));
    chain = run.catch(() => undefined);
    return run;
  };

  /**
   * 门面读到的数据。必须同步返回：MVU 的 `getMvuData` 是同步 API，
   * 前端状态栏在渲染路径上直接调用它，因此这里只读投影快照，不做 IO；
   * 还没投影过时退回楼层变量，避免刷新后那一小段时间读到空对象。
   */
  const readSnapshot = (): MvuDataShape => {
    syncIdentity();
    if (hasProjection || !allowFallback) return snapshot;
    const fallback = readStatDataFromLatestFloor();
    return fallback ? { ...emptyData(), stat_data: fallback, display_data: fallback } : snapshot;
  };

  const writeCommands = async (text: string, isCurrent: () => boolean): Promise<number> => {
    const mapping = port.mapping();
    if (!isCurrent() || !port.isActive() || !mapping || isEmptyMapping(mapping)) return 0;
    const commands = parseMvuCommands(text);
    if (commands.length === 0) return 0;
    const views = await port.readViews();
    if (!isCurrent() || !port.isActive()) return 0;
    const plan = planCommandWrites(mapping, views, commands);
    lastSkipped = plan.skipped;
    if (plan.skipped.length > 0) {
      phoneLogger.warn('MVU 数据桥有未翻译的写入', { skipped: plan.skipped.slice(0, 8) });
    }
    if (plan.writes.length === 0) return 0;
    return port.applyWrites(plan.writes);
  };

  /** 整体替换：与当前快照逐路径比对，只把变化的格写回表。 */
  const writeWholeData = async (next: unknown, isCurrent: () => boolean): Promise<number> => {
    const record = asRecord(next);
    const nextStat = asRecord(record?.stat_data) ?? asRecord(next) ?? {};
    const mapping = port.mapping();
    if (!isCurrent() || !mapping) return 0;
    const views = await port.readViews();
    if (!isCurrent()) return 0;
    const before = projectStatData(mapping, views).statData;
    const commands = Object.entries(nextStat)
      .filter(([key, value]) => JSON.stringify(before[key]) !== JSON.stringify(value))
      .map(([key, value]) => `_.set(${JSON.stringify(joinMvuPath([key]))}, ${JSON.stringify(value)});`);
    for (const key of Object.keys(before)) {
      if (!Object.hasOwn(nextStat, key)) commands.push(`_.delete(${JSON.stringify(joinMvuPath([key]))});`);
    }
    if (commands.length === 0) return 0;
    return writeCommands(commands.join('\n'), isCurrent);
  };

  const project = async (isCurrent: () => boolean): Promise<MvuProjectionOutcome> => {
    const mapping = port.mapping();
    if (!isCurrent() || !mapping || isEmptyMapping(mapping)) {
      return { ok: false, message: '当前没有启用 MVU 数据桥或没有变量映射。', projectedPaths: 0 };
    }
    try {
      const views = await port.readViews();
      if (!isCurrent() || !port.isActive()) return { ok: false, message: '数据桥操作已停止。', projectedPaths: 0 };
      const { statData, missing, projectedPaths } = projectStatData(mapping, views);
      mappedPaths = projectedPaths ?? mapping.entries.length - missing.length;
      missingPaths = missing.length;
      snapshot = { ...emptyData(), stat_data: statData, display_data: statData };
      hasProjection = true;
      const messageId = getLastMessageIdSafe();
      if (messageId !== null) {
        const result = await writeVariableByPath('message', messageId, ['stat_data'], statData, undefined, () => {
          if (!isCurrent() || !port.isActive()) throw new Error('数据桥操作已停止。');
        });
        if (!result.ok) return { ok: false, message: result.message, projectedPaths: mappedPaths };
      }
      if (!isCurrent()) return { ok: false, message: '数据桥操作已停止。', projectedPaths: 0 };
      lastProjectedAt = Date.now();
      return {
        ok: true,
        message: missing.length > 0
          ? `已投影 ${mappedPaths} 个变量到第 ${messageId ?? 0} 楼；${missing.length} 个路径在表里读不到。`
          : `已投影 ${mappedPaths} 个变量到第 ${messageId ?? 0} 楼。`,
        projectedPaths: mappedPaths,
      };
    } catch (error) {
      const detail = error instanceof Error ? error.message : String(error);
      phoneLogger.warn('MVU 投影失败', error);
      return { ok: false, message: `投影失败：${detail}`, projectedPaths: 0 };
    }
  };

  const facade = {
    __narrativePhoneBridge: true as const,
    events: MVU_EVENTS,
    getMvuData: (): MvuDataShape => structuredClone(readSnapshot()),
    getMvuVariable: (data: unknown, path: string, options?: { default_value?: unknown }): unknown => {
      const source = asRecord(asRecord(data)?.stat_data) ?? readSnapshot().stat_data;
      const value = readByPath(source, path);
      return value === undefined ? options?.default_value : value;
    },
    setMvuVariable: (_data: unknown, path: string, value: unknown): Promise<boolean> => serial(async (isCurrent) => {
      const written = await writeCommands(`_.set(${JSON.stringify(path)}, ${JSON.stringify(value ?? null)});`, isCurrent);
      if (written > 0) await project(isCurrent);
      return written > 0;
    }),
    replaceMvuData: (data: unknown): Promise<void> => serial(async (isCurrent) => {
      const written = await writeWholeData(data, isCurrent);
      if (written > 0) await project(isCurrent);
    }),
    parseMessage: (message: string, oldData: unknown): Promise<MvuDataShape> => serial(async (isCurrent) => {
      const written = await writeCommands(message, isCurrent);
      if (written > 0) await project(isCurrent);
      return hasProjection || !allowFallback
        ? structuredClone(snapshot)
        : { ...emptyData(), ...(asRecord(oldData) as Partial<MvuDataShape> ?? {}) };
    }),
    isDuringExtraAnalysis: (): boolean => false,
  };

  /**
   * 装门面。
   *
   * MVU 变量框架常以「酒馆助手脚本库脚本」形式存在，加载时机可能晚于扩展启动，
   * 而它是直接 `_.set(window, 'Mvu', ...)` 覆盖全局的。所以这里用访问器占位：
   * 后来者被收进备份而不是顶掉门面，否则接管会在页面加载竞速里静默失效（面板还显示"已接管"）。
   */
  const install = (): void => {
    syncIdentity();
    const host = getHostRecord();
    if (installed && host.Mvu === facade) return;
    const existing = host.Mvu as (Record<string, unknown> | undefined);
    if (existing && existing.__narrativePhoneBridge !== true) {
      host[FOREIGN_MVU_KEY] = existing;
      replacedForeignMvu = true;
      phoneLogger.info('MVU 数据桥接管了已安装的 MVU 变量框架', {});
    }
    try {
      Object.defineProperty(host, 'Mvu', {
        configurable: true,
        get: () => facade,
        set: (value: unknown) => {
          if (!value || (value as Record<string, unknown>).__narrativePhoneBridge === true) return;
          host[FOREIGN_MVU_KEY] = value;
          replacedForeignMvu = true;
          phoneLogger.info('MVU 变量框架在数据桥之后加载，已收进备份并保持接管', {});
        },
      });
    } catch (error) {
      host.Mvu = facade;
      phoneLogger.warn('以访问器方式接管 window.Mvu 失败，已退回普通赋值（可能被后加载的 MVU 覆盖）', error);
    }
    installed = true;
    // 酒馆助手的脚本用 waitGlobalInitialized('Mvu') 等这个事件，不发就会一直等下去。
    try {
      getSillyTavernEventChannel()?.emit('global_Mvu_initialized');
    } catch (error) {
      phoneLogger.warn('发送 global_Mvu_initialized 事件失败', error);
    }
  };

  const uninstall = (): void => {
    lifetime += 1;
    snapshot = emptyData();
    hasProjection = false;
    allowFallback = false;
    if (!installed) return;
    const host = getHostRecord();
    const original = host[FOREIGN_MVU_KEY];
    try {
      delete host.Mvu;
    } catch (error) {
      phoneLogger.warn('移除 window.Mvu 门面失败', error);
    }
    if (original) {
      host.Mvu = original;
      delete host[FOREIGN_MVU_KEY];
    }
    installed = false;
    replacedForeignMvu = false;
  };

  return {
    install,
    uninstall,
    project: () => serial(project),
    status: (): MvuBridgeStatus => ({
      // 以宿主上的实际对象为准：退回普通赋值时仍可能被后加载的脚本顶掉，面板不能报假的"已接管"。
      installed: installed && getHostRecord().Mvu === facade,
      replacedForeignMvu,
      mappedPaths,
      missingPaths,
      lastProjectedAt,
      lastSkipped,
    }),
  };
}

/** 供面板显示：读一次当前楼层的 `stat_data`，确认投影确实落到了变量里。 */
export async function readProjectedStatData(): Promise<Record<string, unknown> | null> {
  const snapshot = await readVariables('message', null);
  const statData = asRecord((snapshot.data as Record<string, unknown>).stat_data);
  return statData;
}
