import type { PhoneEvent } from '../domain/events.js';
import { createInitialPhoneState, type PhoneState } from '../domain/model.js';
import { reducePhoneEvents } from '../domain/reducer.js';
import { phoneLogger } from '../core/logger.js';
import {
  StorageConflictError,
  type StorageBackend,
  type StorageListener,
  type UnsubscribeStorage,
} from './storage-port.js';
import { resolveScopeId as scopeIdFromContext } from '../integration/scope-id.js';
export { resolveScopeId as scopeIdFromContext } from '../integration/scope-id.js';

export const TAVERN_PHONE_STATE_KEY = 'narrative_phone_state';
const PAYLOAD_VERSION = 1;

/**
 * 提交后写入酒馆聊天文件的合并窗口（毫秒）。
 *
 * 宿主的 saveMetadata 会把整个聊天（全部楼层 + 元数据）POST 回服务端，长聊天里一次要一两秒。
 * 元数据在内存里是立即更新的，所以把落盘合并到一个短窗口：连发消息、一轮生成里的多次提交
 * 只触发一次写盘，界面也不用再等服务端往返。
 */
const SAVE_COALESCE_MS = 400;

export interface TavernStorageContext {
  readonly chatId?: string;
  readonly characterId?: string | number;
  readonly chat?: object;
  readonly chatMetadata?: Readonly<Record<string, unknown>>;
  readonly getRequestHeaders?: () => Readonly<Record<string, string>>;
  readonly saveMetadata?: () => void | Promise<void>;
  readonly saveChat?: () => void | Promise<void>;
}

export type TavernStorageContextProvider = () => TavernStorageContext;

interface TavernStateEnvelope {
  readonly version: number;
  readonly scopeId: string;
  readonly revision: number;
  readonly updatedAt: number;
  readonly state: PhoneState;
}

interface SillyTavernHost {
  readonly SillyTavern?: {
    readonly getContext?: () => TavernStorageContext;
  };
}

/**
 * 手机业务状态的持久事实源。
 *
 * 每个聊天的完整状态写入 SillyTavern 聊天元数据，数据因此跟随服务端聊天文件，
 * 而不是绑定某个浏览器或数据库兼容插件。
 *
 * 写入分两步：元数据在内存里同步更新（提交立刻生效），聊天文件落盘按短窗口合并。
 * 迁移与删除等冷路径仍然直接等待落盘完成。
 */
export class TavernStorage implements StorageBackend {
  readonly kind = 'tavern' as const;
  readonly #contextProvider: TavernStorageContextProvider;
  readonly #listeners = new Map<string, Set<StorageListener>>();
  #writeQueue: Promise<void> = Promise.resolve();
  #pendingSaveContext: TavernStorageContext | null = null;
  #saveTimer: ReturnType<typeof setTimeout> | null = null;
  #saveInFlight: Promise<void> | null = null;
  #saveFailureLogged = false;

  constructor(contextProvider: TavernStorageContextProvider = getTavernStorageContext) {
    this.#contextProvider = contextProvider;
  }

  async isAvailable(): Promise<boolean> {
    try {
      const context = this.#contextProvider();
      return Boolean(
        context.chatMetadata
        && (typeof context.saveMetadata === 'function' || typeof context.saveChat === 'function'),
      );
    } catch {
      return false;
    }
  }

  async load(scopeId: string): Promise<PhoneState | null> {
    const context = this.#contextForScope(scopeId);
    return readState(context.chatMetadata, scopeId);
  }

  commit(
    scopeId: string,
    expectedRevision: number,
    events: readonly PhoneEvent[],
  ): Promise<PhoneState> {
    return this.#enqueueWrite(async () => {
      const context = this.#contextForScope(scopeId);
      const current = readState(context.chatMetadata, scopeId);
      if (!current && events.length === 0) return createInitialPhoneState(scopeId);
      const baseline = current ?? createInitialPhoneState(scopeId, events[0]?.occurredAt ?? Date.now());
      if (baseline.revision !== expectedRevision) {
        throw new StorageConflictError(scopeId, expectedRevision, baseline.revision);
      }
      const next = reducePhoneEvents(baseline, events);
      // 热路径：元数据同步更新，落盘合并到窗口内；next 本身就是新对象，无需再拷一份。
      await this.#write(context, scopeId, next, { deferSave: true });
      return next;
    });
  }

  replace(scopeId: string, state: PhoneState): Promise<void> {
    return this.#enqueueWrite(async () => {
      if (state.scopeId !== scopeId) throw new Error('Cannot replace a different phone scope');
      const context = this.#contextForScope(scopeId);
      await this.#write(context, scopeId, state);
    });
  }

  async listScopes(): Promise<readonly string[]> {
    const context = this.#contextProvider();
    const scopeId = scopeIdFromContext(context);
    if (!scopeId || !readState(context.chatMetadata, scopeId)) return [];
    return [scopeId];
  }

  deleteScope(scopeId: string): Promise<void> {
    return this.#enqueueWrite(async () => {
      const context = this.#contextForScope(scopeId);
      const metadata = context.chatMetadata as Record<string, unknown>;
      const previous = metadata[TAVERN_PHONE_STATE_KEY];
      delete metadata[TAVERN_PHONE_STATE_KEY];
      try {
        await saveTavernStorageContext(context);
      } catch (error) {
        if (previous !== undefined) metadata[TAVERN_PHONE_STATE_KEY] = previous;
        throw error;
      }
      this.#listeners.delete(scopeId);
    });
  }

  subscribe(scopeId: string, listener: StorageListener): UnsubscribeStorage {
    const listeners = this.#listeners.get(scopeId) ?? new Set<StorageListener>();
    listeners.add(listener);
    this.#listeners.set(scopeId, listeners);
    return () => {
      listeners.delete(listener);
      if (listeners.size === 0) this.#listeners.delete(scopeId);
    };
  }

  /** 等待挂起的聊天文件写盘完成（切换聊天、迁移、卸载前调用）。 */
  async flush(): Promise<void> {
    if (this.#saveTimer !== null) {
      clearTimeout(this.#saveTimer);
      this.#saveTimer = null;
    }
    await this.#drainSave();
  }

  dispose(): void {
    void this.flush();
    this.#listeners.clear();
  }

  async #write(
    context: TavernStorageContext,
    scopeId: string,
    state: PhoneState,
    options: { readonly deferSave?: boolean } = {},
  ): Promise<void> {
    const metadata = context.chatMetadata as Record<string, unknown>;
    const previous = metadata[TAVERN_PHONE_STATE_KEY];
    const persistedState = jsonClone(state);
    metadata[TAVERN_PHONE_STATE_KEY] = {
      version: PAYLOAD_VERSION,
      scopeId,
      revision: persistedState.revision,
      updatedAt: Date.now(),
      state: persistedState,
    } satisfies TavernStateEnvelope;

    if (options.deferSave) {
      this.#deferSave(context);
    } else {
      try {
        await saveTavernStorageContext(context);
      } catch (error) {
        if (previous === undefined) delete metadata[TAVERN_PHONE_STATE_KEY];
        else metadata[TAVERN_PHONE_STATE_KEY] = previous;
        throw new Error(`酒馆聊天数据保存失败：${formatError(error)}`);
      }
    }

    for (const listener of this.#listeners.get(scopeId) ?? []) {
      listener(state);
    }
  }

  #deferSave(context: TavernStorageContext): void {
    this.#pendingSaveContext = context;
    if (this.#saveTimer !== null) return;
    this.#saveTimer = setTimeout(() => {
      this.#saveTimer = null;
      void this.#drainSave();
    }, SAVE_COALESCE_MS);
  }

  /**
   * 落盘挂起的元数据。
   *
   * 失败不回滚内存元数据：此时更新的状态已经被后续提交继续推进，回滚只会造成状态倒退。
   * 内存元数据保持最新，宿主下一次保存聊天会把它带上；浏览器恢复缓存里也已经有同一份状态，
   * 下次打开时 AdaptiveStorage 会用较新的修订号回写酒馆。
   */
  #drainSave(): Promise<void> {
    const context = this.#pendingSaveContext;
    this.#pendingSaveContext = null;
    if (!context) return this.#saveInFlight ?? Promise.resolve();
    const previous = this.#saveInFlight ?? Promise.resolve();
    const save = previous.catch(() => undefined).then(() => this.#saveNow(context));
    this.#saveInFlight = save;
    void save.then(() => {
      if (this.#saveInFlight === save) this.#saveInFlight = null;
    });
    return save;
  }

  async #saveNow(context: TavernStorageContext): Promise<void> {
    try {
      await saveTavernStorageContext(context);
      this.#saveFailureLogged = false;
    } catch (error) {
      if (!this.#saveFailureLogged) {
        this.#saveFailureLogged = true;
        phoneLogger.warn('保存酒馆聊天数据失败，手机状态仍保留在浏览器恢复缓存中', error);
      }
    }
  }

  #contextForScope(scopeId: string): TavernStorageContext & {
    readonly chatMetadata: Readonly<Record<string, unknown>>;
  } {
    const context = this.#contextProvider();
    if (!context.chatMetadata) throw new Error('当前聊天没有可用的酒馆元数据存储');
    const activeScopeId = scopeIdFromContext(context);
    if (activeScopeId !== scopeId) {
      throw new Error(`酒馆聊天作用域已变化：期望 ${scopeId}，当前 ${activeScopeId ?? '无'}`);
    }
    if (typeof context.saveMetadata !== 'function' && typeof context.saveChat !== 'function') {
      throw new Error('当前酒馆版本没有提供聊天元数据保存接口');
    }
    return context as TavernStorageContext & {
      readonly chatMetadata: Readonly<Record<string, unknown>>;
    };
  }

  #enqueueWrite<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.#writeQueue.then(operation, operation);
    this.#writeQueue = result.then(
      () => undefined,
      () => undefined,
    );
    return result;
  }
}

export function getTavernStorageContext(): TavernStorageContext {
  let parentContext: TavernStorageContext | undefined;
  try {
    const parentHost = window.parent as unknown as SillyTavernHost | undefined;
    parentContext = parentHost?.SillyTavern?.getContext?.();
  } catch {
    // 受限 iframe 下回退当前窗口。
  }
  const selfHost = window as unknown as SillyTavernHost;
  return parentContext ?? selfHost.SillyTavern?.getContext?.() ?? {};
}

function readState(
  metadata: Readonly<Record<string, unknown>> | undefined,
  scopeId: string,
): PhoneState | null {
  const raw = metadata?.[TAVERN_PHONE_STATE_KEY];
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return null;
  const record = raw as Record<string, unknown>;
  const candidate = record.state ?? raw;
  if (!isPhoneState(candidate)) throw new Error('酒馆聊天元数据中的手机状态无法解析');
  if (candidate.scopeId !== scopeId) {
    throw new Error(`酒馆手机状态作用域不匹配：${candidate.scopeId} !== ${scopeId}`);
  }
  return jsonClone(candidate);
}

function isPhoneState(value: unknown): value is PhoneState {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const state = value as Partial<PhoneState>;
  return typeof state.scopeId === 'string'
    && Number.isInteger(state.schemaVersion)
    && Number.isInteger(state.revision)
    && Boolean(state.profiles && typeof state.profiles === 'object')
    && Boolean(state.worldClock && typeof state.worldClock === 'object');
}

export async function saveTavernStorageContext(context: TavernStorageContext): Promise<void> {
  const save = context.saveMetadata ?? context.saveChat;
  if (!save) throw new Error('酒馆聊天保存接口不可用');
  await Promise.resolve(save.call(context));
}

function jsonClone<T>(value: T): T {
  return JSON.parse(JSON.stringify(value)) as T;
}

function formatError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}