function describeRuntimeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? '未知错误');
}

/** 物化指纹：作用域 + 选中的预设 + 表名集合，任一变化都要重新建表。 */
function dataCenterPresetKey(
  scopeId: string,
  activePresetId: string,
  sheets: readonly SheetPresetEntry[],
): string {
  return `${scopeId}:${activePresetId}:${hashText(JSON.stringify(sheets))}`;
}

function hasPhoneFallbackSignal(text: string): boolean {
  if (!text.trim()) return false;
  return /(?:微信|朋友圈|推特|Twitter|X平台|论坛|贴吧|Discord|QQ|短信|私信|群聊|聊天软件|手机).{0,80}(?:发送|发了|回复|发布|私信|消息|动态|帖子|评论|转发|点赞)|(?:发送|回复|发布|私信|消息|动态|帖子|评论|转发|点赞).{0,80}(?:微信|朋友圈|推特|Twitter|X平台|论坛|贴吧|Discord|QQ|短信|私信|群聊|聊天软件|手机)/isu.test(text);
}

/** 当前聊天里最后一条 User 楼层下标；没有则为 -1。 */
function latestUserFloorIndex(): number {
  const chat = getSillyTavernContext().chat;
  const messages = Array.isArray(chat) ? chat : [];
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if ((messages[index] as { is_user?: unknown } | undefined)?.is_user === true) return index;
  }
  return -1;
}

function memoryApiLabel(settings: PhoneExtensionSettings): string {
  const api = settings.memory.recallApi;
  return api.profileName?.trim() || api.model.trim() || '未配置 API';
}

function reportGenerationRetry(label: string, progress: ApiRetryProgress): void {
  beginPhoneTask(label).retry({
    attempt: progress.attempt,
    retryCount: progress.retryCount,
    error: progress.error,
  });
}

/**
 * 给一次 API 生成阶段套上任务提示：进入即「进行中」，重试转警告，成功/失败落终态。
 * 阶段名直接当操作名用，标题统一渲染为「墨韵手机 {阶段名}」。
 */
async function withStageTask<T>(
  label: string,
  operation: (task: PhoneTaskHandle) => Promise<T>,
): Promise<T> {
  const task = beginPhoneTask(label);
  try {
    const result = await operation(task);
    task.succeed();
    return result;
  } catch (error) {
    task.fail(error);
    throw error;
  }
}

/**
 * 后台管线的提示适配器：把 reportTask / reportTaskResult 这种「一条字符串」的
 * 回调绑定到固定操作 id 的任务卡片上，管线自身不需要知道通知长什么样。
 *
 * 传入 cancel 时，「进行中」卡片会带上终止入口。
 */
function pipelineReporter(id: RuntimeOperationId, cancel?: () => void): {
  readonly reportTask: (message: string | null) => void;
  readonly reportTaskResult: (message: string, kind: 'error' | 'success' | 'cancelled') => void;
} {
  let task: PhoneTaskHandle | null = null;
  const detailOf = (message: string): string => message.trim().replace(/^墨韵手机\s*[：:]\s*/u, '').trim();
  const options = cancel ? { action: { label: '终止', run: cancel } } : {};
  return {
    reportTask: (message) => {
      if (message) {
        task ??= beginPhoneTask(id, options);
        task.progress(detailOf(message));
        return;
      }
      task?.dismiss();
      task = null;
    },
    reportTaskResult: (message, kind) => {
      const handle = task ?? beginPhoneTask(id, options);
      const detail = detailOf(message);
      if (kind === 'cancelled') handle.cancel(detail);
      else handle.settle({ ok: kind === 'success', message: detail });
      task = null;
    },
  };
}

