  #autoParse: AutoParseService | null = null;
  #shell: PhoneShell | null = null;
  #toggle: HTMLButtonElement | null = null;
  #started = false;
  #visible = false;
  #settings: PhoneExtensionSettings | null = null;
  #runtimeInfo: PhoneRuntimeInfo | null = null;
  #memoryPipeline: MemoryPipeline | null = null;
  /** 向量阶段（向量化 / 重排序）的进行中卡片：同一阶段复用一张，阶段结束即收起。 */
  readonly #vectorStageTasks = new Map<VectorStageReport['kind'], PhoneTaskHandle>();
  /** 后台补索引的单飞标记：避免设置连改几次时并发向量化同一批记忆。 */
  #vectorIndexRunning = false;
  /** 本轮向量召回结果缓存：同一轮里提示词会同步两次，避免重复向量化与重排序。 */
  #vectorRecallCache: { readonly key: string; readonly result: VectorRecallResult | null } | null = null;
  #suppressedVectorScope: string | null = null;
