  async #autoMatchContact(request: {
    readonly platform: ContactMatchPlatform;
    readonly targetName?: string;
  }): Promise<ContactAutoMatchResult> {
    const generation = this.#generation;
    if (!generation) throw new Error('生成服务未就绪');
    await this.#refreshWorldBookForGeneration();
    const entries = this.#worldBook.activeEntries
      .filter((entry) => entry.enabled && entry.content.trim())
      .map((entry) => ({ name: entry.name, content: entry.content }));
    if (entries.length === 0) throw new Error('当前绑定的世界书没有可用于匹配的启用条目。');
    const recentStory = (() => {
      try {
        return getRecentStoryFloors(8).map((floor) => `${floor.name}：${floor.text}`);
      } catch {
        return [] as const;
      }
    })();
    const existingProfiles = Object.values(this.#store.state.profiles)
      .filter((profile) => profile.id !== SELF_PROFILE_ID);
    const limit = request.targetName ? 1 : CONTACT_MATCH_BATCH_LIMIT;
    const prompt = buildContactMatchPrompt({
      platform: request.platform,
      targetName: request.targetName,
      worldBookEntries: entries,
      existingProfiles,
      recentStory,
      limit,
    });
    const raw = await withStageTask('联系人自动匹配', (task) => generation.generateFreeform(
      `contact-match:${request.platform}`,
      prompt.system,
      prompt.user,
      limit > 1 ? 8_192 : 2_400,
      undefined,
      0.35,
      (progress) => task.retry(progress),
    ));
    const drafts = parseContactMatchResponses(requireUsableGeneratedText(raw, '联系人匹配'), request.platform);
    // 已存在的角色一律跳过：模型不听话时也不会把上一轮的人再匹配一遍。
    const taken = request.targetName
      ? new Set<string>()
      : new Set(existingProfiles.flatMap((profile) => identityNamesOf(profile)));
    const contacts: ContactAutoMatchContact[] = [];
    const skipped: string[] = [];
    for (const draft of drafts.slice(0, limit)) {
      if (taken.has(normalizeIdentityName(draft.boundCharacter))) {
        skipped.push(`${draft.boundCharacter}（已匹配过）`);
        continue;
      }
      try {
        const result = await this.#commands.upsertMatchedContact({
          platform: draft.platform,
          displayName: draft.displayName,
          boundCharacter: draft.boundCharacter,
          wechatAlias: draft.wechatAlias,
          twitterName: draft.twitterName,
          twitterHandle: draft.twitterHandle,
          bio: draft.bio,
          personality: draft.personality,
          twitterBio: draft.bio,
          appearancePrompt: draft.appearancePrompt,
          avatarPrompt: draft.avatarPrompt,
        });
        contacts.push({
          conversationId: result.conversation.id,
          profileId: result.profile.id,
          displayName: result.profile.displayName,
          boundCharacter: result.profile.boundCharacter ?? draft.boundCharacter,
        });
        for (const name of identityNamesOf(result.profile)) taken.add(name);
      } catch (error) {
        skipped.push(`${draft.boundCharacter}（${describeRuntimeError(error)}）`);
      }
    }
    return { contacts, skipped, hasMore: !request.targetName && contacts.length >= limit };
  }

  /** 按用户在公开平台留下的兴趣信号，刷新一批不围绕用户本人的公共帖子。 */
  async #generateAmbientPosts(
    platform: 'forum' | 'twitter',
    options?: { readonly board?: string },
  ): Promise<number> {
    return platform === 'forum'
      ? this.#forumRefresh.run((signal) => this.#generateAmbientPostsOnce(platform, signal, options?.board))
      : this.#generateAmbientPostsOnce(platform);
  }

  async #generateAmbientPostsOnce(
    platform: 'forum' | 'twitter',
    signal?: AbortSignal,
    board?: string,
  ): Promise<number> {
    await this.#scopeSwitch;
    const generationScopeId = this.#store.scopeId;
    const settings = this.#settings ?? loadPhoneSettings();
    if (settings.personalization.disabledAppIds.includes(platform)) {
      throw new Error(`${platform === 'twitter' ? '推特' : '论坛'}应用已停用。`);
    }
    if (!this.#generation) throw new Error('生成服务未就绪');
    const generation = this.#generation;

    // 酒馆世界书条目可能在同一张角色卡内被临时切换；刷新必须读取当前状态，不能复用启动时快照。
    await this.#refreshWorldBookForGeneration(settings);
    const worldBookContext = this.#worldBookForGeneration();
    if (platform === 'forum') {
      const scopedBoard = board?.trim() ?? '';
      const prompt = buildForumDiscussionPrompt({
        state: this.#store.state,
        settings: settings.forum,
        selfProfileId: SELF_PROFILE_ID,
        worldBookExcerpt: worldBookContext?.excerpt ?? null,
        worldBookNames: worldBookContext?.names ?? [],
        ...(scopedBoard ? { board: scopedBoard } : {}),
      });
      const maxTokens = settings.forum.generationMaxTokens;
      const raw = await withStageTask(
        scopedBoard ? `板块自转 · ${scopedBoard}` : '论坛自转',
        (task) => generation.generateFreeform(
          'forum-discussions',
          prompt.system,
          prompt.user,
          maxTokens,
          signal,
          undefined,
          (progress) => task.retry(progress),
        ),
      );
      if (signal?.aborted || this.#store.scopeId !== generationScopeId) {
        throw new Error('聊天已切换，本轮论坛刷新结果已丢弃。');
      }
      const drafts = parseForumDiscussionBatch(raw, settings.forum, prompt);
      const posts = await this.#commands.createForumDiscussionBatch(drafts);
      if (posts.length === 0) throw new Error('没有写入新的论坛讨论。');
      return posts.length;
    }

    const count = 3;
    const imageProvider = settings.imageGeneration.enabled ? settings.imageGeneration.provider : null;
    const imagePostIndexes = imageProvider ? selectAmbientImagePostIndexes(count) : [];
    const prompt = buildAmbientPostPrompt({
      platform,
      state: this.#store.state,
      selfProfileId: SELF_PROFILE_ID,
      count,
      worldBookExcerpt: worldBookContext?.excerpt ?? null,
      worldBookNames: worldBookContext?.names ?? [],
      imageProvider,
      imagePostIndexes,
    });
    const raw = await withStageTask(
      `${platform === 'twitter' ? '推特' : '论坛'}内容生成`,
      (task) => generation.generateFreeform(
        `ambient-posts:${platform}`,
        prompt.system,
        prompt.user,
        3_200,
        undefined,
        undefined,
        (progress) => task.retry(progress),
      ),
    );
    const existingContents = Object.values(this.#store.state.posts)
      .filter((post) => post.appId === platform)
      .map((post) => post.content);
    const batch = parseAmbientTwitterBatch(raw, {
      timeline: prompt.timeline,
      existingContents,
      count,
      image: { provider: imageProvider, postIndexes: imagePostIndexes },
    });
    const written = await this.#commands.createAmbientTwitterBatch(batch);
    if (written.posts.length === 0) throw new Error('没有写入新的推荐帖子。');
    if (written.reposts.length > 0 || written.comments.length > 0) {
      phoneLogger.info('推特刷新写入了世界书要求的互动', {
        posts: written.posts.length,
        reposts: written.reposts.length,
        comments: written.comments.length,
      });
    }
    return written.posts.length + written.reposts.length;
  }

