import { validateSheetCondition } from './sheet-condition.js';

export type SheetPolicy = 'always' | 'recall' | 'manual';

export interface SheetColumn {
  readonly name: string;
  readonly type: 'TEXT' | 'INTEGER' | 'REAL' | 'BLOB';
  readonly nullable?: boolean;
}

export interface SheetRegistrationInput {
  readonly id: string;
  readonly scopeId: string;
  readonly name: string;
  readonly purpose: string;
  readonly physicalName?: string;
  readonly ddl: string;
  readonly policy: SheetPolicy;
  readonly rowTemplate: string;
  readonly tokenBudget?: number;
  readonly orderNo?: number;
  /** 注入条件（IF 语法的表达式部分）；空串表示无条件每次都参与注入。 */
  readonly injectCondition?: string;
  /** 这张表的填表规则；随表结构进填表提示词。 */
  readonly fillGuide?: string;
}

export interface SheetDefinition {
  readonly id: string;
  readonly scopeId: string;
  readonly name: string;
  readonly purpose: string;
  readonly physicalName: string;
  readonly ddl: string;
  readonly policy: SheetPolicy;
  readonly rowTemplate: string;
  readonly tokenBudget: number;
  readonly orderNo: number;
  readonly updatedAt: number;
  readonly injectCondition: string;
  readonly fillGuide: string;
}

export interface SheetRow {
  readonly key?: string | number;
  readonly values: Readonly<Record<string, unknown>>;
}

export interface RenderedMemoryDocument {
  readonly rowKey: string;
  readonly text: string;
  readonly hash: string;
}

const PHYSICAL_NAME_PATTERN = /^acu_u_[a-z][a-z0-9_]{0,47}$/;
const COLUMN_NAME_PATTERN = /^[A-Za-z_][A-Za-z0-9_]{0,63}$/;
const DDL_PATTERN = /^CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?([A-Za-z_][A-Za-z0-9_]*)\s*\(([^]*)\)$/i;
const SQLITE_KEYWORDS = new Set([
  'ABORT', 'ACTION', 'ADD', 'AFTER', 'ALL', 'ALTER', 'ANALYZE', 'AND', 'AS', 'ASC', 'ATTACH', 'AUTOINCREMENT',
  'BEFORE', 'BEGIN', 'BETWEEN', 'BY', 'CASCADE', 'CASE', 'CAST', 'CHECK', 'COLLATE', 'COLUMN', 'COMMIT', 'CONFLICT',
  'CONSTRAINT', 'CREATE', 'CROSS', 'CURRENT', 'CURRENT_DATE', 'CURRENT_TIME', 'CURRENT_TIMESTAMP', 'DATABASE', 'DEFAULT',
  'DEFERRABLE', 'DEFERRED', 'DELETE', 'DESC', 'DETACH', 'DISTINCT', 'DO', 'DROP', 'EACH', 'ELSE', 'END', 'ESCAPE',
  'EXCEPT', 'EXCLUDE', 'EXCLUSIVE', 'EXISTS', 'EXPLAIN', 'FAIL', 'FILTER', 'FIRST', 'FOLLOWING', 'FOR', 'FOREIGN', 'FROM',
  'FULL', 'GENERATED', 'GLOB', 'GROUP', 'GROUPS', 'HAVING', 'IF', 'IGNORE', 'IMMEDIATE', 'IN', 'INDEX', 'INDEXED', 'INITIALLY',
  'INNER', 'INSERT', 'INSTEAD', 'INTERSECT', 'INTO', 'IS', 'ISNULL', 'JOIN', 'KEY', 'LAST', 'LEFT', 'LIKE', 'LIMIT', 'MATCH',
  'NATURAL', 'NO', 'NOT', 'NOTHING', 'NOTNULL', 'NULL', 'NULLS', 'OF', 'OFFSET', 'ON', 'OR', 'ORDER', 'OTHERS', 'OUTER',
  'OVER', 'PARTITION', 'PLAN', 'PRAGMA', 'PRECEDING', 'PRIMARY', 'QUERY', 'RAISE', 'RANGE', 'RECURSIVE', 'REFERENCES', 'REGEXP',
  'REINDEX', 'RELEASE', 'RENAME', 'REPLACE', 'RESTRICT', 'RIGHT', 'ROLLBACK', 'ROW', 'ROWS', 'SAVEPOINT', 'SELECT', 'SET',
  'TABLE', 'TEMP', 'TEMPORARY', 'THEN', 'TIES', 'TO', 'TRANSACTION', 'TRIGGER', 'UNBOUNDED', 'UNION', 'UNIQUE', 'UPDATE', 'USING',
  'VACUUM', 'VALUES', 'VIEW', 'VIRTUAL', 'WHEN', 'WHERE', 'WINDOW', 'WITH', 'WITHOUT',
]);

/** 稳定的行/正文指纹：用于物理表名后缀与 `mem_doc.hash` 去重。 */
export function hashText(value: string): string {
  let hash = 2166136261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0).toString(16).padStart(8, '0');
}

function stableNameSuffix(value: string): string {
  return hashText(value).slice(0, 8);
}

function normalizeSlug(value: string): string {
  const normalized = value.normalize('NFKD').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '');
  return normalized.slice(0, 40) || 'sheet';
}

export function physicalTableName(name: string, id: string): string {
  const slug = normalizeSlug(name).slice(0, 33);
  return `acu_u_${slug}_${stableNameSuffix(id)}`;
}

export function quoteIdentifier(identifier: string): string {
  if (!PHYSICAL_NAME_PATTERN.test(identifier) && !COLUMN_NAME_PATTERN.test(identifier)) {
    throw new Error(`非法 SQLite 标识符：${identifier}`);
  }
  return `"${identifier}"`;
}

/** 列名能否直接用于未加引号的 DDL：形状合法且不是 SQLite 保留字。 */
export function isUsableColumnName(name: string): boolean {
  return COLUMN_NAME_PATTERN.test(name) && !SQLITE_KEYWORDS.has(name.toUpperCase());
}

function validateColumnName(name: string): void {
  if (!isUsableColumnName(name)) {
    throw new Error(`非法或保留字列名：${name}`);
  }
}

function splitColumnDefinitions(body: string): readonly string[] {
  const parts: string[] = [];
  let start = 0;
  let quote: string | null = null;
  let depth = 0;
  for (let index = 0; index < body.length; index += 1) {
    const char = body[index];
    if (quote) {
      if (char === quote && body[index + 1] === quote) {
        index += 1;
      } else if (char === quote) {
        quote = null;
      }
      continue;
    }
    if (char === '"' || char === '`' || char === '[') {
      quote = char === '[' ? ']' : char;
    } else if (char === '(') {
      depth += 1;
    } else if (char === ')') {
      depth -= 1;
    } else if (char === ',' && depth === 0) {
      parts.push(body.slice(start, index).trim());
      start = index + 1;
    }
  }
  parts.push(body.slice(start).trim());
  return parts.filter(Boolean);
}

export function validateSheetDdl(ddl: string, physicalName: string): string {
  if (!PHYSICAL_NAME_PATTERN.test(physicalName)) throw new Error(`非法物理表名：${physicalName}`);
  const normalized = ddl.trim().replace(/;\s*$/, '');
  if (normalized.includes(';') || /--|\/\*/.test(normalized)) throw new Error('表 DDL 不得包含注释或多语句');
  const match = DDL_PATTERN.exec(normalized);
  const tableName = match?.[1];
  const body = match?.[2];
  if (!match || tableName !== physicalName || body === undefined) throw new Error(`DDL 必须只创建已分配的物理表 ${physicalName}`);
  const definitions = splitColumnDefinitions(body);
  if (definitions.length === 0 || definitions.length > 64) throw new Error('表至少需要一列，且最多支持 64 列');
  for (const definition of definitions) {
    const columnMatch = /^([A-Za-z_][A-Za-z0-9_]*)\s+(TEXT|INTEGER|REAL|BLOB)\b/i.exec(definition);
    if (!columnMatch) {
      if (/^(PRIMARY|UNIQUE|CHECK|FOREIGN)\b/i.test(definition)) continue;
      throw new Error(`列定义只允许显式 TEXT/INTEGER/REAL/BLOB 类型：${definition}`);
    }
    const columnName = columnMatch[1];
    if (!columnName) throw new Error(`列定义缺少列名：${definition}`);
    validateColumnName(columnName);
    if (/\bGENERATED\b|\bREFERENCES\b|\bCOLLATE\b/i.test(definition)) throw new Error('用户表 DDL 不允许生成列、外键或自定义排序规则');
  }
  return normalized;
}

export function createSheetDdl(physicalName: string, columns: readonly SheetColumn[]): string {
  if (!PHYSICAL_NAME_PATTERN.test(physicalName)) throw new Error(`非法物理表名：${physicalName}`);
  if (columns.length === 0 || columns.length > 64) throw new Error('用户表至少需要一列，且最多支持 64 列');
  const definitions = columns.map((column) => {
    validateColumnName(column.name);
    const nullable = column.nullable === false ? ' NOT NULL' : '';
    return `${column.name} ${column.type}${nullable}`;
  });
  return `CREATE TABLE ${physicalName} (${definitions.join(', ')})`;
}

export function prepareSheetRegistration(input: SheetRegistrationInput, now = Date.now()): SheetDefinition {
  if (!input.id.trim() || !input.scopeId.trim() || !input.name.trim()) throw new Error('表注册需要 id、scopeId 和 name');
  if (!input.purpose.trim()) throw new Error('表 purpose 不能为空');
  if (!input.rowTemplate.trim()) throw new Error('表 rowTemplate 不能为空');
  if (!['always', 'recall', 'manual'].includes(input.policy)) throw new Error(`未知表策略：${input.policy}`);
  const physicalName = input.physicalName ?? physicalTableName(input.name, input.id);
  const ddl = validateSheetDdl(input.ddl, physicalName);
  const tokenBudget = Math.trunc(input.tokenBudget ?? 256);
  if (tokenBudget < 16 || tokenBudget > 8192) throw new Error('表 tokenBudget 必须在 16 到 8192 之间');
  const injectCondition = (input.injectCondition ?? '').trim();
  // 建表时就把条件语法错拦下：留到每轮注入时才发现，只会表现成"这张表莫名不注入了"。
  const conditionError = validateSheetCondition(injectCondition);
  if (conditionError) throw new Error(`注入条件无效：${conditionError}`);
  return {
    id: input.id,
    scopeId: input.scopeId,
    name: input.name.trim(),
    purpose: input.purpose.trim(),
    physicalName,
    ddl,
    policy: input.policy,
    rowTemplate: input.rowTemplate.trim(),
    tokenBudget,
    orderNo: Math.trunc(input.orderNo ?? 0),
    updatedAt: now,
    injectCondition,
    fillGuide: (input.fillGuide ?? '').trim(),
  };
}

/**
 * 行 → 召回文本。值为空的片段整段丢掉：
 * 一行 14 列只填了 2 列时，渲染成 `上衣=；下装=；内裤=` 既白烧 token，
 * 也会被模型读成"这些部位是空的"这种字面结论。
 */
export function renderRowAsDocument(sheet: Pick<SheetDefinition, 'rowTemplate'>, row: SheetRow): RenderedMemoryDocument {
  const rowKey = String(row.key ?? row.values.id ?? row.values.key ?? hashText(JSON.stringify(row.values)));
  const filled = templateSegments(sheet.rowTemplate).flatMap((segment) => {
    let hasPlaceholder = false;
    let hasValue = false;
    const rendered = segment.replace(/\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}/g, (_match, key: string) => {
      hasPlaceholder = true;
      const value = row.values[key];
      const text = value === null || value === undefined ? '' : String(value).trim();
      if (text) hasValue = true;
      return text;
    });
    if (hasPlaceholder && !hasValue) return [];
    return rendered.trim() ? [rendered.trim()] : [];
  });
  const text = filled.join(TEMPLATE_SEPARATOR);
  if (!text) throw new Error('行模板渲染结果为空');
  return { rowKey, text, hash: hashText(text) };
}

/**
 * 表结构行：列名后带上中文标签。
 * 只给列名的话，中文键生成的 `c_1a2b3c` 这种物理列名对模型毫无意义，写 SQL 时会对错列。
 */
export function sheetSchemaLine(sheet: Pick<SheetDefinition, 'name' | 'purpose' | 'ddl'> & { readonly rowTemplate?: string }): string {
  const labels = sheetColumnLabels(sheet.rowTemplate ?? '');
  const columns = sheetColumnNames(sheet.ddl)
    .map((column) => {
      const label = labels.get(column);
      return label && label !== column ? `${column}=${label}` : column;
    })
    .join(', ');
  return `${sheet.name}(${columns}) — ${sheet.purpose}`;
}

/** 已注册 DDL 的列顺序：界面网格与行投影都按它对齐。 */
export function sheetColumnNames(ddl: string): readonly string[] {
  const match = DDL_PATTERN.exec(ddl.trim().replace(/;\s*$/, ''));
  const body = match?.[2];
  if (!body) return [];
  return splitColumnDefinitions(body)
    .filter((definition) => !/^(PRIMARY|UNIQUE|CHECK|FOREIGN)\b/i.test(definition))
    .flatMap((definition) => {
      const name = definition.split(/\s+/, 1)[0];
      return name ? [name] : [];
    });
}

/**
 * 行模板里的 `标签={{列}}` 对。物理列名必须是 ASCII，中文语义只存在于行模板里，
 * 因此行模板同时充当界面列标题的来源，不需要额外的 schema 字段。
 */
export function sheetColumnLabels(rowTemplate: string): ReadonlyMap<string, string> {
  const labels = new Map<string, string>();
  for (const match of rowTemplate.matchAll(/([^；;|、,\n]+?)\s*[=:：]\s*\{\{\s*([A-Za-z_][A-Za-z0-9_]*)\s*\}\}/g)) {
    const label = match[1]?.trim();
    const column = match[2];
    // `{{name}}：{{summary}}` 这类没有标签的模板会把前一个占位符当成标签，必须挡掉。
    if (!label || label.includes('{') || label.includes('}')) continue;
    if (column && !labels.has(column)) labels.set(column, label);
  }
  return labels;
}

const TEMPLATE_SEPARATOR = '；';

function templateSegments(rowTemplate: string): readonly string[] {
  return rowTemplate.split(/[；;]/).map((segment) => segment.trim()).filter(Boolean);
}

/** 列改名时同步行模板占位符，避免渲染出空值。 */
export function renameTemplateColumn(rowTemplate: string, from: string, to: string): string {
  const pattern = new RegExp(`\\{\\{\\s*${from}\\s*\\}\\}`, 'g');
  return rowTemplate.replace(pattern, `{{${to}}}`);
}

/** 删列时移除引用该列的整个片段；模板被清空时回退到剩余列的默认拼装。 */
export function removeTemplateColumn(rowTemplate: string, column: string, remaining: readonly string[]): string {
  const pattern = new RegExp(`\\{\\{\\s*${column}\\s*\\}\\}`);
  const kept = templateSegments(rowTemplate).filter((segment) => !pattern.test(segment));
  if (kept.length > 0) return kept.join(TEMPLATE_SEPARATOR);
  return remaining.map((name) => `${name}={{${name}}}`).join(TEMPLATE_SEPARATOR);
}

/** 加列时追加片段，标签缺省时用列名。 */
export function appendTemplateColumn(rowTemplate: string, column: string, label?: string): string {
  const segment = `${label?.trim() || column}={{${column}}}`;
  const segments = templateSegments(rowTemplate);
  if (segments.some((item) => new RegExp(`\\{\\{\\s*${column}\\s*\\}\\}`).test(item))) return rowTemplate;
  return [...segments, segment].join(TEMPLATE_SEPARATOR);
}
