import type { PhoneEvent } from '../domain/events.js';
import type { IdFactory } from '../domain/ids.js';
import { createScopedId } from '../domain/ids.js';
import type { Interaction, PhoneMessage, PhonePost, PhoneState, Profile, WorldClock } from '../domain/model.js';
import { advanceTo, scheduleReply } from '../time/world-clock.js';
import { normalizeTimeAdvanceSettings, type TimeAdvanceSettings } from '../time/time-advance.js';

/** 由 seed 生成 0 ~ range-1 毫秒的确定性抖动（同一动作重放结果一致）。 */
function deterministicJitter(seed: string, range: number): number {
  if (range <= 1) return 0;
  let hash = 2166136261;
  for (const character of seed) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return (hash >>> 0) % range;
}
import type { GenerationPlan } from './batch-planner.js';
import type { ValidatedGenerationAction } from './schema.js';

export interface ActionExecutionResult {
  readonly events: readonly PhoneEvent[];
  readonly completedOutboxIds: readonly string[];
  readonly queuedOutboxIds: readonly string[];
  readonly unansweredOutboxIds: readonly string[];
  readonly finalClock: WorldClock;
}

export interface GenerationCoverage {
  readonly repliedConversationIds: ReadonlySet<string>;
  readonly respondedPostIds: ReadonlySet<string>;
  readonly missingConversationIds: readonly string[];
  readonly missingPostIds: readonly string[];
  readonly unansweredOutboxIds: readonly string[];
}

export function analyzeGenerationCoverage(
  plan: GenerationPlan,
  actions: readonly ValidatedGenerationAction[],
): GenerationCoverage {
  const repliedConversationIds = new Set<string>();
  const respondedPostIds = new Set<string>();
  for (const action of actions) {
    if ((action.type === 'message.reply' || action.type === 'message.claim') && action.conversationId) {
      repliedConversationIds.add(action.conversationId);
    }
    const referencedPostId = action.parentId ?? action.targetId;
    if (referencedPostId && action.type !== 'message.claim') respondedPostIds.add(referencedPostId);
  }
  const missingConversationIds = plan.conversations
    .map(({ conversation }) => conversation.id)
    .filter((id) => !repliedConversationIds.has(id));
  const missingPostIds = plan.queuedPosts
    .map(({ post }) => post.id)
    .filter((id) => !respondedPostIds.has(id));
  const missingConversations = new Set(missingConversationIds);
  const missingPosts = new Set(missingPostIds);
  const unansweredOutboxIds = plan.batch.outboxIds.filter((outboxId) => {
    const conversation = plan.conversations.find(({ outboxItems }) => outboxItems.some((item) => item.id === outboxId));
    if (conversation) return missingConversations.has(conversation.conversation.id);
    const post = plan.queuedPosts.find(({ outboxItem }) => outboxItem.id === outboxId);
    return post ? missingPosts.has(post.post.id) : false;
  });
  return {
    repliedConversationIds,
    respondedPostIds,
    missingConversationIds,
    missingPostIds,
    unansweredOutboxIds,
  };
}

export interface ActionExecutionOptions {
  readonly timeAdvance?: Partial<TimeAdvanceSettings>;
  /** 写入批次记录的问题摘要。 */
  readonly validationError?: string;
  /**
   * 本轮完全没拿到生成结果、必须保持「待生成」的 outbox（例如某个分片模型没返回 JSON）。
   * 这些条目会被重新置为 queued，用户可以再次点击生成；其余条目照常收敛为 completed。
   */
  readonly retryOutboxIds?: ReadonlySet<string>;
}

export function buildActionEvents(
  state: PhoneState,
  plan: GenerationPlan,
  actions: readonly ValidatedGenerationAction[],
  idFactory: IdFactory,
  options: ActionExecutionOptions = {},
): ActionExecutionResult {
  const events: PhoneEvent[] = [];
  const ambientProfiles = new Map<string, Profile>();
  const timeAdvance = normalizeTimeAdvanceSettings(options.timeAdvance);
  let finalTimestamp = state.worldClock.now;
  /**
   * 剧情时间推进规则：
   * 模型等待时间、联系人首条回复、连续回复及整轮上限均来自同一份规则。
   * 关闭时消息保持当前剧情时间；顺序由事件和消息列表保留。
   */
  const batchStart = finalTimestamp;
  const MAX_EXPLICIT_DELAY_MINUTES = timeAdvance.modelDelayMaxMinutes;
  const FIRST_REPLY_MIN_MS = timeAdvance.firstReplyMinSeconds * 1000;
  const FIRST_REPLY_MAX_MS = timeAdvance.firstReplyMaxSeconds * 1000;
  const BURST_BASE_MS = timeAdvance.burstMinSeconds * 1000;
  const BURST_JITTER_MS = (timeAdvance.burstMaxSeconds - timeAdvance.burstMinSeconds) * 1000;
  const MAX_BATCH_ADVANCE_MS = timeAdvance.batchMaxMinutes * 60_000;
  const actorsSeen = new Set<string>();

  /** 路人网友（actorName）按昵称复用本轮/历史创建的路人档案，绝不复用真实联系人档案。 */
  const resolveActor = (action: ValidatedGenerationAction): Profile | null => {
    if (action.actorProfileId) return state.profiles[action.actorProfileId] ?? null;
    const name = action.actorName?.trim();
    if (!name) return null;
    const reusable = ambientProfiles.get(name)
      ?? Object.values(state.profiles).find(
        (profile) => profile.displayName === name && profile.id.startsWith('ambient-profile:'),
      );
    if (reusable) {
      ambientProfiles.set(name, reusable);
      return reusable;
    }
    const profile: Profile = {
      id: createScopedId(state.scopeId, 'ambient-profile', idFactory),
      scopeId: state.scopeId,
      displayName: name,
      aliases: action.appId === 'twitter'
        ? { twitter: `@${slugifyHandle(name)}` }
        : { forum: name },
      replyDelay: { minimumMinutes: 0, maximumMinutes: 20 },
      activeHours: { startHour: 0, endHour: 23 },
      createdAt: state.worldClock.now,
      updatedAt: state.worldClock.now,
    };
    ambientProfiles.set(name, profile);
    events.push({
      id: createScopedId(state.scopeId, 'event', idFactory),
      scopeId: state.scopeId,
      type: 'profile.upserted',
      occurredAt: state.worldClock.now,
      payload: { profile },
    });
    return profile;
  };

  for (const action of actions) {
    const actor = resolveActor(action);
    if (!actor) continue;
    const actorKey = actor.id || `ambient:${action.actorName ?? ''}`;
    const isFirstOfActor = !actorsSeen.has(actorKey);
    actorsSeen.add(actorKey);

    let delayMs: number;
    if (!timeAdvance.enabled) {
      delayMs = 0;
    } else if (timeAdvance.useModelDelay && action.delayMinutes !== undefined && Number.isFinite(action.delayMinutes)) {
      // 模型显式表达了节奏（连发 0~2 / 忙碌 5~30 / 晾着 30+），直接采用。
      delayMs = Math.max(0, Math.min(MAX_EXPLICIT_DELAY_MINUTES, action.delayMinutes)) * 60_000;
    } else if (isFirstOfActor) {
      // 该角色本轮第一条：用回复习惯，但压缩为温和区间（活跃时段平移只保留温和部分）。
      const scheduled = scheduleReply({
        clock: { ...state.worldClock, now: finalTimestamp },
        profile: actor,
        seed: action.actionId,
      });
      const habit = scheduled.at - finalTimestamp;
      delayMs = Math.min(Math.max(habit, FIRST_REPLY_MIN_MS), FIRST_REPLY_MAX_MS);
    } else {
      // 同一角色的连发：几十秒的间隔，保持消息在相邻分钟内。
      delayMs = BURST_BASE_MS + deterministicJitter(action.actionId, BURST_JITTER_MS);
    }

    const createdAt = timeAdvance.enabled ? Math.min(
      finalTimestamp + Math.max(delayMs, 0),
      batchStart + MAX_BATCH_ADVANCE_MS,
    ) : batchStart;
    finalTimestamp = createdAt;

    if (action.type === 'message.claim' && action.targetId && action.claimStatus) {
      events.push({
        id: createScopedId(state.scopeId, 'event', idFactory),
        scopeId: state.scopeId,
        type: 'message.claimed',
        occurredAt: createdAt,
        actionId: action.actionId,
        payload: {
          messageId: action.targetId,
          claimStatus: action.claimStatus,
          ...(action.content ? { content: action.content } : {}),
        },
      });
      continue;
    }

    if (action.type === 'message.reply' && action.conversationId) {
      // 模型把多句话用换行塞进一条消息时，自动拆成连发短消息（更像真人聊天）。
      const segments = action.content
        .split(/\n+/)
        .map((part) => part.trim())
        .filter(Boolean)
        .slice(0, 4);
      const pieces = segments.length > 0 ? segments : [action.content];
      let pieceTimestamp = createdAt;
      pieces.forEach((piece, pieceIndex) => {
        if (pieceIndex > 0 && timeAdvance.enabled) {
          pieceTimestamp = Math.min(
            pieceTimestamp + BURST_BASE_MS + deterministicJitter(`${action.actionId}:${pieceIndex}`, BURST_JITTER_MS),
            batchStart + MAX_BATCH_ADVANCE_MS,
          );
          finalTimestamp = Math.max(finalTimestamp, pieceTimestamp);
        }
        const message: PhoneMessage = {
          id: createScopedId(state.scopeId, 'message', idFactory),
          scopeId: state.scopeId,
          appId: action.appId,
          conversationId: action.conversationId as string,
          profileId: actor.id,
          direction: 'incoming',
          content: piece,
          // 角色内部思考只保留在元数据里，永不渲染、也不进入互动记录（只挂在第一条上）。
          ...(pieceIndex === 0 && action.thought ? { metadata: { thought: action.thought } } : {}),
          status: 'sent',
          createdAt: pieceTimestamp,
          batchId: plan.batch.id,
          actionId: pieceIndex === 0 ? action.actionId : `${action.actionId}#${pieceIndex}`,
        };
        events.push({
          id: createScopedId(state.scopeId, 'event', idFactory),
          scopeId: state.scopeId,
          type: 'message.received',
          occurredAt: pieceTimestamp,
          actionId: pieceIndex === 0 ? action.actionId : `${action.actionId}#${pieceIndex}`,
          payload: { message },
        });
      });
      continue;
    }

    if (action.postKind) {
      const post: PhonePost = {
        id: createScopedId(state.scopeId, 'post', idFactory),
        scopeId: state.scopeId,
        appId: action.appId,
        kind: action.postKind,
        profileId: actor.id,
        ...(action.title ? { title: action.title } : {}),
        content: action.content,
        createdAt,
        actionId: action.actionId,
        ...(action.parentId ? { parentId: action.parentId } : {}),
        ...(action.targetId ? { targetId: action.targetId } : {}),
      };
      events.push({
        id: createScopedId(state.scopeId, 'event', idFactory),
        scopeId: state.scopeId,
        type: 'post.created',
        occurredAt: createdAt,
        actionId: action.actionId,
        payload: { post },
      });
      continue;
    }

    if (action.targetId) {
      const interaction: Interaction = {
        id: createScopedId(state.scopeId, 'interaction', idFactory),
        scopeId: state.scopeId,
        appId: action.appId,
        type: action.type === 'interaction.like' ? 'like' : 'comment',
        actorProfileId: actor.id,
        targetId: action.targetId,
        content: action.content,
        createdAt,
        actionId: action.actionId,
      };
      events.push({
        id: createScopedId(state.scopeId, 'event', idFactory),
        scopeId: state.scopeId,
        type: 'interaction.created',
        occurredAt: createdAt,
        actionId: action.actionId,
        payload: { interaction },
      });
    }
  }

  const coverage = analyzeGenerationCoverage(plan, actions);
  // 模型/API 成功返回后，本批次必须收敛：模型答了却漏掉的目标记为 unanswered，不再重排，
  // 避免下一轮重复提交同一条消息。但整段请求失败（没拿到可解析结果）的目标必须留在 queued 等重试。
  const retryOutboxIds = options.retryOutboxIds ?? new Set<string>();
  const completedOutboxIds = plan.batch.outboxIds.filter((id) => !retryOutboxIds.has(id));
  const queuedOutboxIds = plan.batch.outboxIds.filter((id) => retryOutboxIds.has(id));
  const finalClock = timeAdvance.enabled && finalTimestamp > batchStart
    ? advanceTo(state.worldClock, finalTimestamp, `generation-batch:${plan.batch.id}`) : state.worldClock;
  if (finalClock !== state.worldClock) events.push({
    id: createScopedId(state.scopeId, 'event', idFactory),
    scopeId: state.scopeId,
    type: 'clock.advanced',
    occurredAt: finalClock.now,
    payload: { clock: finalClock },
  });
  events.push({
    id: createScopedId(state.scopeId, 'event', idFactory),
    scopeId: state.scopeId,
    type: 'batch.completed',
    occurredAt: finalClock.now,
    payload: {
      batchId: plan.batch.id,
      completedAt: finalClock.now,
      completedOutboxIds,
      queuedOutboxIds,
      ...(options.validationError ? { error: options.validationError } : {}),
    },
  });

  return {
    events,
    completedOutboxIds,
    queuedOutboxIds,
    // 已重排等待重试的条目不算「没获得回复」，避免同一件事被报告两次。
    unansweredOutboxIds: coverage.unansweredOutboxIds.filter((id) => !retryOutboxIds.has(id)),
    finalClock,
  };
}

function slugifyHandle(value: string): string {
  const slug = value.toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g, '_').replace(/^_+|_+$/g, '');
  return slug || 'user';
}
