export interface SettingsPanelContext {
  readonly state: PhoneState;
  readonly settings: PhoneExtensionSettings;
  readonly capabilities: GenerationCapabilities;
  readonly hostApis: SillyTavernApiSnapshot;
  readonly storage: AdaptiveStorageStatus;
  readonly worldBook: WorldBookSnapshot;
  readonly formatAdapters: readonly FormatAdapter[];
  readonly presetPromptSlots: PresetPromptSlotSnapshot;
  readonly section: SettingsSection;
  readonly navigateSection: (section: SettingsSection) => void;
  readonly openDatabaseApp: () => void;
  readonly onChange: (patch: PhoneSettingsPatch) => void | Promise<void>;
  /** 导出插件专用完整备份。 */
  readonly onExportBackup: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 校验备份文件并返回导入预览。 */
  readonly onPreviewBackup: (raw: string) => Promise<PhoneBackupPreview>;
  /** 原子恢复备份；跨作用域需要显式允许。 */
  readonly onImportBackup: (
    raw: string,
    options: { readonly allowScopeChange: boolean },
  ) => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 按类别清除当前聊天的数据。 */
  readonly onPurgeData: (
    bucketIds: readonly PhoneDataBucketId[],
  ) => Promise<{ readonly ok: boolean; readonly message: string }>;
  readonly onRefresh: () => Promise<void>;
  /** 用任意 API 配置拉取模型列表（配置库编辑器的连接测试）。 */
  readonly onFetchApiModels: (config: OpenAiCompatibleApiConfig) => Promise<readonly ApiModelOption[]>;
  /** 手动触发一次手机内容总结。 */
  readonly onSummarizeNow: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  /** 让 AI 读角色卡与世界书，合成能解析这张卡的格式适配器（只读卡，只写插件设置）。 */
  readonly onForceFormatCompat: () => Promise<{
    readonly ok: boolean;
    readonly message: string;
    readonly accepted: readonly string[];
    readonly rejected: readonly string[];
  }>;
  /** MVU 转换数据：扫描、转换与数据桥状态。 */
  readonly mvu: MvuPanelActions;
  readonly onDynamicWorldBookOptimize: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  readonly onDynamicWorldBookClear: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  readonly onDynamicWorldBookEdit: (entryKey: string, content: string) => Promise<{ readonly ok: boolean; readonly message: string }>;
  readonly onDynamicWorldBookRestore: (entryKey: string) => Promise<{ readonly ok: boolean; readonly message: string }>;
  readonly showModal: (title: string, fields: readonly ModalField[]) => Promise<Record<string, string> | null>;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

function reportSettingsSaveError(error: unknown): void {
  beginPhoneTask('settingsSave').fail(error);
}

function runSettingChange(operation: () => void | Promise<void>): void {
  void Promise.resolve().then(operation).catch(reportSettingsSaveError);
}

export function renderSettingsPanel(context: SettingsPanelContext): HTMLElement {
  if (context.section !== 'timeAdvance') resetTimeAdvanceDraft();
  if (context.section === 'timeAdvance') return wrapSection('时间推进规则', renderTimeAdvancePanel({
    scopeId: context.state.scopeId, settings: context.settings.timeAdvance,
    onSave: (timeAdvance) => context.onChange({ timeAdvance }), onBack: () => context.navigateSection('generation'),
    showNotice: context.showNotice,
  }));
  if (context.section === 'api') return wrapSection('API 配置', renderApiCard(context));
  if (context.section === 'generation') return wrapSection('生成设置', renderGenerationCard(context));
  if (context.section === 'jailbreak') return wrapSection('破限设置', renderJailbreakCard(context));
  if (context.section === 'worldBook') return wrapSection('世界书', renderWorldBookCard(context));
  if (context.section === 'dynamicWorldBook') return wrapSection('动态世界书', renderDynamicWorldBookCard(context));
  if (context.section === 'image') return wrapSection('生图配置', renderImageCard(context));
  if (context.section === 'context') return wrapSection('上下文与总结', renderContextCard(context));
  if (context.section === 'logs') return wrapSection('运行日志', renderLogsCard(context));
  if (context.section === 'promptLog') return wrapSection('酒馆提示词日志', renderTavernPromptLogCard(context));
  if (context.section === 'mvuConvert') return wrapSection('MVU 转换数据', renderMvuConvertCard(context));
  if (context.section === 'data') return wrapSection('数据与备份', renderDataCard(context));
  return renderSettingsHome(context);
}

function wrapSection(title: string, content: HTMLElement): HTMLElement {
  const page = element('div', { className: 'phone-page phone-settings' });
  page.append(
    renderSection(title, '设置', content),
  );
  return page;
}

function renderSettingsHome(context: SettingsPanelContext): HTMLElement {
  // 回到设置首页就丢掉 MVU 面板的一次性状态（扫描结果、勾选项），下次进去重新扫描。
  resetMvuConvertPanel();
  const page = element('div', { className: 'phone-page phone-settings' });
  page.append(renderSection('连接状态', '当前状态', renderConnectionCard(context)));
  const menu = element('div', { className: 'phone-settings-menu' });
  menu.append(
    settingsEntry('API 配置', '模型拉取、温度与输出上限', 'apiSettings', () => context.navigateSection('api')),
    settingsEntry('生成设置', '手机入口、模式与世界书注入', 'generationSettings', () => context.navigateSection('generation')),
    settingsEntry('破限设置', '开关与提示词', 'jailbreakSettings', () => context.navigateSection('jailbreak')),
    settingsEntry('上下文与总结', '正文楼层数量、自动总结阈值', 'contextSummary', () => context.navigateSection('context')),
    settingsEntry('世界书', '角色卡绑定世界书与条目', 'worldBook', () => context.navigateSection('worldBook')),
    settingsEntry('动态世界书', '按剧情维护角色状态与关系', 'dynamicWorldBook', () => context.navigateSection('dynamicWorldBook')),
    settingsEntry('生图配置', 'NovelAI / OpenAI / SD / ComfyUI', 'imageSettings', () => context.navigateSection('image')),
    settingsEntry('日志查看', '运行日志：暂停 / 导出 / 清空', 'logView', () => context.navigateSection('logs')),
    settingsEntry('酒馆提示词日志', '记录并查看酒馆正文请求的完整提示词结构', 'log', () => context.navigateSection('promptLog')),
    settingsEntry('MVU 转换数据', '把 MVU 变量卡转成数据中心表格并接管变量读写', 'variables', () => context.navigateSection('mvuConvert')),
    settingsEntry('数据与备份', '存储、导出与迁移', 'dataSettings', () => context.navigateSection('data')),
  );
  page.append(renderSection('功能入口', '设置', menu));
  const databaseHint = element('p', {
    className: 'phone-settings-hint',
    text: '数据库的表格数据请在手机桌面的「数据库」应用中查看；桌面布局、壁纸与应用图标请使用桌面上的「个性化」应用调整。',
  });
  page.append(databaseHint);
  return page;
}

function settingsEntry(title: string, detail: string, icon: Parameters<typeof renderPhoneIcon>[0], action: () => void): HTMLButtonElement {
  const row = button('', 'phone-settings-entry', action);
  const iconBox = element('span', { className: 'phone-settings-entry-icon' });
  iconBox.append(renderPhoneIcon(icon));
  const copy = element('span', { className: 'phone-settings-entry-copy' });
  copy.append(element('strong', { text: title }), element('small', { text: detail }));
  row.append(iconBox, copy, renderPhoneIcon('chevron'));
  return row;
}

function renderSection(title: string, kicker: string, content: HTMLElement): HTMLElement {
  const section = element('section', { className: 'phone-settings-section' });
  const heading = element('div', { className: 'phone-settings-heading' });
  heading.append(
    element('span', { className: 'phone-kicker', text: kicker }),
    element('h2', { className: 'phone-settings-title', text: title }),
  );
  section.append(heading, content);
  return section;
}

function renderConnectionCard(context: SettingsPanelContext): HTMLElement {
  const card = element('div', { className: 'phone-settings-card phone-status-grid' });
  const apiReady = Boolean(context.settings.primaryApi.enabled && context.settings.primaryApi.model);
  card.append(
    statusRow('酒馆上下文', context.hostApis.contextAvailable ? '已连接' : '未检测到', context.hostApis.contextAvailable),
    statusRow('配置 API', apiReady ? `主 API · ${context.settings.primaryApi.model}` : '未配置/未启用', apiReady),
    statusRow('回复引擎', context.capabilities.selectedLabel, context.capabilities.selectedProvider !== 'unavailable'),
    statusRow(
      '手机数据存储',
      context.storage.selectedKind === 'tavern'
        ? '酒馆聊天持久化'
        : context.storage.selectedKind === 'indexeddb'
          ? '浏览器临时缓存（酒馆保存不可用）'
          : '尚未选择',
      context.storage.selectedKind === 'tavern',
    ),
    statusRow('数据版本', `第 ${context.state.schemaVersion} 版 · 修订 ${context.state.revision}`, true),
  );
  return card;
}

/** 配置库编辑器的草稿（模块级：设置重绘时不丢输入）。 */
interface ApiProfileDraft {
  name: string;
  baseUrl: string;
  apiKey: string;
  model: string;
  temperature: number | null;
  maxTokens: number | null;
  retryCount: number;
  stream: boolean;
}
let apiEditorSelection = '__new__';
let apiEditorDraft: ApiProfileDraft | null = null;
let apiEditorModels: readonly ApiModelOption[] = [];

function draftFromProfile(profile: ApiProfile | null): ApiProfileDraft {
  return {
    name: profile?.name ?? '',
    baseUrl: profile?.baseUrl ?? '',
    apiKey: profile?.apiKey ?? '',
    model: profile?.model ?? '',
    temperature: profile ? profile.temperature : 1,
    maxTokens: profile ? profile.maxTokens : 2_000,
    retryCount: profile?.retryCount ?? 3,
    stream: profile ? profile.stream !== false : true,
  };
}

function renderApiCard(context: SettingsPanelContext): HTMLElement {
  const card = element('div', { className: 'phone-settings-card' });
  card.append(
    element('p', {
      className: 'phone-settings-hint',
      text: '在下方「API 配置库」中填写并保存配置，然后在这里为主/副 API 选择要使用的配置。'
        + '主 API 失败且副 API 已启用时自动切换；两者都未启用时回退酒馆生成通道。日记本与记忆库同样从配置库选择。',
    }),
    renderApiSlotPicker(context, 'primary'),
    renderApiSlotPicker(context, 'secondary'),
    renderApiProfileEditor(context),
  );
  return card;
}

/** 主/副 API 槽位：启用开关 + 从配置库选择。 */
function renderApiSlotPicker(context: SettingsPanelContext, slot: 'primary' | 'secondary'): HTMLElement {
  const isPrimary = slot === 'primary';
  const config = isPrimary ? context.settings.primaryApi : context.settings.secondaryApi;
  const title = isPrimary ? '主 API' : '副 API（备用）';
  const patch = (partial: Partial<OpenAiCompatibleApiConfig>) => context.onChange(
    isPrimary ? { primaryApi: partial } : { secondaryApi: partial },
  );

  const section = element('div', { className: 'phone-api-slot' });
  section.append(
    element('h3', { className: 'phone-subsection-title', text: title }),
    checkboxField(
      `启用${title}`,
      isPrimary ? '使用所选配置的 OpenAI 兼容接口生成手机内容。' : '主 API 请求失败时自动切换到副 API。',
      config.enabled,
      (checked) => patch({ enabled: checked }),
    ),
  );

  const profiles = context.settings.apiProfiles;
  const knownProfile = profiles.find((profile) => profile.name === config.profileName);
  const hasManualConfig = Boolean(config.model || config.baseUrl);
  const options: (readonly [string, string])[] = [
    ['', profiles.length > 0 ? '— 选择已保存的配置 —' : '— 配置库为空，先在下方保存配置 —'],
    ...(!knownProfile && hasManualConfig ? [['__current__', '当前配置（未关联配置库）'] as const] : []),
    ...profiles.map((profile) => [profile.name, `${profile.name}（${profile.model || '未填模型'}）`] as const),
  ];
  section.append(selectField('使用配置', options, knownProfile ? knownProfile.name : (hasManualConfig ? '__current__' : ''), (value) => {
    const profile = profiles.find((item) => item.name === value);
    if (profile) void patch(applyApiProfile(profile));
  }));
  section.append(element('p', {
    className: 'phone-settings-hint',
    text: hasManualConfig
      ? `模型 ${config.model || '未填写'} · ${config.baseUrl || '官方地址'}`
      : '尚未选择配置。',
  }));
  return section;
}

/** API 配置库：单一填写区 + 保存/删除；主副/日记/记忆库共用这里保存的配置。 */
function renderApiProfileEditor(context: SettingsPanelContext): HTMLElement {
  const wrapper = element('div', { className: 'phone-api-slot phone-api-profile-editor' });
  const rebuild = () => {
    wrapper.replaceChildren(...buildEditorChildren());
  };

  const buildEditorChildren = (): HTMLElement[] => {
    const profiles = context.settings.apiProfiles;
    const editingProfile = profiles.find((profile) => profile.name === apiEditorSelection) ?? null;
    if (apiEditorDraft === null) apiEditorDraft = draftFromProfile(editingProfile);
    const draft = apiEditorDraft;
    const children: HTMLElement[] = [];

    children.push(element('h3', { className: 'phone-subsection-title', text: 'API 配置库' }));
    children.push(selectField(
      '编辑目标',
      [['__new__', '＋ 新建配置'], ...profiles.map((profile) => [profile.name, profile.name] as const)],
      apiEditorSelection,
      (value) => {
        apiEditorSelection = value;
        apiEditorDraft = draftFromProfile(profiles.find((profile) => profile.name === value) ?? null);
        apiEditorModels = [];
        rebuild();
      },
    ));

    children.push(textField('配置名称', draft.name, '例如：DeepSeek 官方 / 中转站 A', (value) => {
      draft.name = value;
    }));
    children.push(textField('Base URL', draft.baseUrl, 'https://api.openai.com/v1（留空使用官方地址）', (value) => {
      draft.baseUrl = value;
    }));
    children.push(textField('API Key', draft.apiKey, 'sk-...（部分本地/中转接口可留空）', (value) => {
      draft.apiKey = value;
    }, true));

    // 模型：手填 + 拉取列表测试连接。
    const modelRow = element('div', { className: 'phone-setting-control phone-setting-control-stack' });
    modelRow.append(element('span', { className: 'phone-control-label', text: '模型' }));
    const modelGroup = element('div', { className: 'phone-inline-group' });
    const modelInput = element('input', {
      className: 'phone-input',
      attributes: { type: 'text', placeholder: 'gpt-4o-mini（可手动填写或拉取列表选择）', autocomplete: 'off', spellcheck: 'false' },
    });
    modelInput.value = draft.model;
    modelInput.addEventListener('change', () => {
      draft.model = modelInput.value.trim();
    });
    const fetchButton = button('拉取模型列表', 'phone-button phone-button-secondary phone-button-compact', async () => {
      fetchButton.disabled = true;
      fetchButton.textContent = '拉取中…';
      try {
        apiEditorModels = await context.onFetchApiModels({
          enabled: true,
          baseUrl: draft.baseUrl,
          apiKey: draft.apiKey,
          model: draft.model,
          temperature: draft.temperature,
          maxTokens: draft.maxTokens,
          maxContextTokens: null,
          retryCount: draft.retryCount,
          stream: true,
        });
        context.showNotice(`连接成功，获取到 ${apiEditorModels.length} 个模型。`, 'success');
        rebuild();
      } catch (error) {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
        fetchButton.disabled = false;
        fetchButton.textContent = '拉取模型列表';
      }
    });
    modelGroup.append(modelInput, fetchButton);
    modelRow.append(modelGroup);
    children.push(modelRow);

    if (apiEditorModels.length > 0) {
      children.push(selectField(
        '从列表选择',
        [['', `— 从 ${apiEditorModels.length} 个模型中选择 —`], ...apiEditorModels.map((model) => [model.id, model.label] as const)],
        draft.model,
        (value) => {
          if (!value) return;
          draft.model = value;
          modelInput.value = value;
        },
      ));
    }

    children.push(nullableNumberField(
      '温度',
      draft.temperature,
      0,
      2,
      0.05,
      `留空 = 使用默认温度（${context.settings.generationTemperature}）`,
      (value) => {
        draft.temperature = value;
      },
    ));
    children.push(nullableNumberField(
      '输出上限（tokens）',
      draft.maxTokens,
      16,
      131_072,
      64,
      `留空 = 使用默认输出上限（${context.settings.generationMaxTokens}）`,
      (value) => {
        draft.maxTokens = value;
      },
    ));
    children.push(numberField(
      '失败重试次数',
      draft.retryCount,
      0,
      10,
      1,
      (value) => {
        draft.retryCount = Math.min(10, Math.max(0, Math.round(value)));
      },
    ));
    children.push(checkboxField(
      '启用流式传输',
      '开启后使用流式输出调用模型（SSE）；关闭则等待完整响应。部分代理只支持其中一种。',
      draft.stream,
      (checked) => {
        draft.stream = checked;
      },
    ));

    const actions = element('div', { className: 'phone-settings-actions' });
    if (editingProfile) {
      actions.append(button('删除此配置', 'phone-button phone-button-danger-ghost', async () => {
        if (!window.confirm(`确定删除配置「${editingProfile.name}」吗？正在使用它的功能会保留当前值。`)) return;
        const nextProfiles = profiles.filter((profile) => profile.name !== editingProfile.name);
        // 解除各槽位对该配置的关联（保留已拷贝的值）。
        const vectorPatch = {
          ...(context.settings.vector.embedding.profileName === editingProfile.name ? { embedding: { profileName: '' } } : {}),
          ...(context.settings.vector.rerank.profileName === editingProfile.name ? { rerank: { profileName: '' } } : {}),
        };
        const patch: PhoneSettingsPatch = {
          apiProfiles: nextProfiles,
          ...(Object.keys(vectorPatch).length > 0 ? { vector: vectorPatch } : {}),
          ...(context.settings.primaryApi.profileName === editingProfile.name ? { primaryApi: { profileName: '' } } : {}),
          ...(context.settings.secondaryApi.profileName === editingProfile.name ? { secondaryApi: { profileName: '' } } : {}),
          ...(context.settings.diary.api.profileName === editingProfile.name ? { diary: { api: { profileName: '' } } } : {}),
          ...(context.settings.memory.recallApi.profileName === editingProfile.name
            ? { memory: { recallApi: { profileName: '' } } }
            : {}),
          ...(context.settings.memory.organizeApi.profileName === editingProfile.name
            ? { memory: { organizeApi: { profileName: '' } } }
            : {}),
        };
        await context.onChange(patch);
        apiEditorSelection = '__new__';
        apiEditorDraft = draftFromProfile(null);
        apiEditorModels = [];
        context.showNotice(`配置「${editingProfile.name}」已删除。`, 'info');
      }));
    }
    const save = button('保存 API 配置', 'phone-button phone-button-primary', async () => {
      const name = draft.name.trim().slice(0, 40);
      if (!name) {
        context.showNotice('请先填写配置名称。', 'error');
        return;
      }
      if (name === '__new__' || name === '__current__') {
        context.showNotice('这个名称不可用，请换一个。', 'error');
        return;
      }
      const renamed = editingProfile && editingProfile.name !== name;
      if (profiles.some((profile) => profile.name === name && profile.name !== editingProfile?.name)) {
        if (!window.confirm(`已存在同名配置「${name}」，保存将覆盖它。继续吗？`)) return;
      }
      const saved: ApiProfile = {
        name,
        enabled: false,
        baseUrl: draft.baseUrl.trim(),
        apiKey: draft.apiKey.trim(),
        model: draft.model.trim(),
        temperature: draft.temperature,
        maxTokens: draft.maxTokens,
        maxContextTokens: editingProfile?.maxContextTokens ?? null,
        retryCount: draft.retryCount,
        stream: draft.stream,
        maxTokenField: editingProfile?.maxTokenField ?? 'max_tokens',
        topP: editingProfile?.topP ?? 1,
        frequencyPenalty: editingProfile?.frequencyPenalty ?? 0,
        presencePenalty: editingProfile?.presencePenalty ?? 0,
      };
      const nextProfiles = [
        ...profiles.filter((profile) => profile.name !== name && profile.name !== editingProfile?.name),
        saved,
      ];
      // 同步所有引用该配置的槽位（重命名时按旧名匹配）。
      const referenceName = renamed ? editingProfile.name : name;
      const vectorPatch = {
        ...(context.settings.vector.embedding.profileName === referenceName ? { embedding: { profileName: saved.name, baseUrl: saved.baseUrl, apiKey: saved.apiKey, model: saved.model } } : {}),
        ...(context.settings.vector.rerank.profileName === referenceName ? { rerank: { profileName: saved.name, baseUrl: saved.baseUrl, apiKey: saved.apiKey, model: saved.model } } : {}),
      };
      const patch: PhoneSettingsPatch = {
        apiProfiles: nextProfiles,
        ...(Object.keys(vectorPatch).length > 0 ? { vector: vectorPatch } : {}),
        ...(context.settings.primaryApi.profileName === referenceName ? { primaryApi: applyApiProfile(saved) } : {}),
        ...(context.settings.secondaryApi.profileName === referenceName ? { secondaryApi: applyApiProfile(saved) } : {}),
        ...(context.settings.diary.api.profileName === referenceName ? { diary: { api: applyApiProfile(saved) } } : {}),
        ...(context.settings.memory.recallApi.profileName === referenceName
          ? { memory: { recallApi: applyApiProfile(saved) } }
          : {}),
        ...(context.settings.memory.organizeApi.profileName === referenceName
          ? { memory: { organizeApi: applyApiProfile(saved) } }
          : {}),
      };
      await context.onChange(patch);
      apiEditorSelection = name;
      context.showNotice(`配置「${name}」已保存，可在上方与日记本/记忆库中选择使用。`, 'success');
    });
    actions.append(save);
    children.push(actions);
    return children;
  };

  rebuild();
  return wrapper;
}

