/** 展示当前角色卡和注册表中的格式适配器，并允许逐项停用或添加手动容器。 */
function renderDetectedFormatAdapters(context: SettingsPanelContext): HTMLElement {
  const adapters = context.formatAdapters;
  const section = element('div', { className: 'phone-api-slot' });
  section.append(
    element('h3', { className: 'phone-subsection-title', text: '手机格式适配器' }),
    element('p', {
      className: 'phone-settings-hint',
      text: adapters.length > 0
        ? '确定性解析只使用已启用的适配器。关闭某项只影响解析注册表，不会修改角色卡正文。'
        : '当前没有可显示的适配器；可以手动添加容器标签。',
    }),
  );

  const sourceLabels: Record<FormatAdapter['source'], string> = {
    builtin: '内置',
    card: '角色卡',
    user: '手动',
  };
  const familyLabels: Record<FormatAdapter['family'], string> = {
    tagged: '标签消息',
    bracketed: '方括号字段',
    'chat-app': '聊天行',
    discord: '论坛字段',
    dsl: '调用 DSL',
  };
  const appLabels: Record<FormatAdapter['appId'], string> = {
    wechat: '微信/QQ',
    twitter: '推特/X',
    forum: '论坛',
    anonymous: '匿名交友',
  };
  const list = element('div', { className: 'phone-settings-card' });
  for (const adapter of adapters) {
    const enabled = isFormatAdapterEnabled(adapter, context.settings.formatAdapterOverrides);
    const row = element('div', { className: 'phone-format-adapter-row' });
    row.append(checkboxField(
      `启用 ${adapter.containers.join(' / ')}`,
      `${familyLabels[adapter.family]} · ${appLabels[adapter.appId]} · ${sourceLabels[adapter.source]} · 置信度 ${Math.round(adapter.confidence * 100)}%${enabled ? '' : ' · 已关闭'}`,
      enabled,
      (checked) => {
        const overrides = { ...context.settings.formatAdapterOverrides };
        if (checked) delete overrides[adapter.id];
        else overrides[adapter.id] = false;
        return context.onChange({ formatAdapterOverrides: overrides });
      },
    ));
    if (adapter.source === 'user') {
      row.append(button('删除', 'phone-button phone-button-danger-ghost phone-button-compact', () => {
        return context.onChange({
          manualFormatAdapters: context.settings.manualFormatAdapters.filter((item) => item.id !== adapter.id),
          formatAdapterOverrides: withoutAdapterOverride(context.settings.formatAdapterOverrides, adapter.id),
        });
      }));
    }
    list.append(row);
  }
  section.append(list);

  const add = button('手动添加容器适配器', 'phone-button phone-button-secondary', async () => {
    const values = await context.showModal('添加手机容器适配器', [
      {
        name: 'containers',
        label: '容器标签',
        placeholder: '例如：手机聊天, 私聊框（逗号分隔）',
        required: true,
      },
      {
        name: 'family',
        label: '语法族',
        type: 'select',
        value: 'tagged',
        options: [
          ['tagged', '标签块'],
          ['bracketed', '方括号字段'],
          ['chat-app', '聊天行'],
          ['discord', '论坛字段'],
          ['dsl', '调用 DSL'],
        ],
      },
      {
        name: 'appId',
        label: '目标 App',
        type: 'select',
        value: 'wechat',
        options: [
          ['wechat', '微信/QQ'],
          ['twitter', '推特/X'],
          ['forum', '论坛'],
          ['anonymous', '匿名交友'],
        ],
      },
      {
        name: 'conversationKind',
        label: '会话类型',
        type: 'select',
        value: 'direct',
        options: [
          ['direct', '私聊'],
          ['group', '群聊/论坛'],
          ['anonymous', '匿名聊天'],
        ],
      },
      {
        name: 'postKind',
        label: '帖子类型（可选）',
        type: 'select',
        value: '',
        options: [
          ['', '消息容器'],
          ['moment', '朋友圈动态'],
          ['forum-thread', '论坛主题'],
          ['forum-reply', '论坛回复'],
          ['twitter-post', '推特/X 动态'],
          ['twitter-reply', '推特/X 回复'],
          ['twitter-repost', '推特/X 转发'],
        ],
      },
    ]);
    if (!values) return;
    const input: UserFormatAdapterInput = {
      containers: String(values.containers ?? '').split(/[,，\n]/u).map((value) => value.trim()).filter(Boolean),
      family: String(values.family ?? 'tagged') as UserFormatAdapterInput['family'],
      appId: String(values.appId ?? 'wechat') as UserFormatAdapterInput['appId'],
      conversationKind: String(values.conversationKind ?? 'direct') as UserFormatAdapterInput['conversationKind'],
      ...(values.postKind ? { postKind: values.postKind as UserFormatAdapterInput['postKind'] } : {}),
    };
    try {
      const adapter = createUserFormatAdapter(input);
      const existing = context.settings.manualFormatAdapters.some((item) => item.id === adapter.id);
      if (existing) {
        context.showNotice('相同的手动适配器已经存在。', 'info');
        return;
      }
      await context.onChange({ manualFormatAdapters: [...context.settings.manualFormatAdapters, adapter] });
      context.showNotice(`已添加容器：${adapter.containers.join('、')}。`, 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
  });
  const force = button('给我强兼它！！！', 'phone-button phone-button-primary phone-force-compat-button', async () => {
    force.disabled = true;
    const previousLabel = force.textContent;
    force.textContent = '正在读卡…';
    report.replaceChildren(element('span', { className: 'phone-settings-hint', text: '正在读取角色卡与已激活世界书里的格式说明…' }));
    try {
      const result = await context.onForceFormatCompat();
      report.replaceChildren(renderForceCompatReport(result));
      context.showNotice(result.message, result.ok ? 'success' : 'error');
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      report.replaceChildren(element('span', { className: 'phone-settings-hint', text: `强兼失败：${message}` }));
      context.showNotice(message, 'error');
    } finally {
      force.disabled = false;
      force.textContent = previousLabel ?? '给我强兼它！！！';
    }
  });
  force.title = '调用 AI 读角色卡与世界书的格式说明，自动补齐能解析这张卡的适配器';
  const report = element('div', { className: 'phone-force-compat-report' });
  section.append(
    element('p', {
      className: 'phone-settings-hint',
      text: '自动识别覆盖不到的卡（起止标记、JSON 面板、自定义字段名）可以让 AI 现场合成适配器：全程只读角色卡与世界书，只写插件设置，且必须用卡里的示例正文试跑成功才会保存。',
    }),
    force,
    report,
  );
  section.append(add, element('p', {
    className: 'phone-settings-hint',
    text: '手动配置只保存容器名和目标映射，不执行正则、不评估正文脚本；容器名必须是字母/中文开头的短标签。',
  }));
  return section;
}

/** 强兼结果：接受了哪些容器、丢弃了哪些以及原因，全部摊开给用户看。 */
function renderForceCompatReport(result: {
  readonly ok: boolean;
  readonly message: string;
  readonly accepted: readonly string[];
  readonly rejected: readonly string[];
}): HTMLElement {
  const wrap = element('div', { className: 'phone-force-compat-result' });
  wrap.append(element('strong', { className: result.ok ? 'is-ok' : 'is-failed', text: result.message }));
  if (result.accepted.length > 0) {
    const list = element('ul', { className: 'phone-force-compat-list' });
    for (const item of result.accepted) list.append(element('li', { text: `已启用：${item}` }));
    wrap.append(list);
  }
  if (result.rejected.length > 0) {
    const list = element('ul', { className: 'phone-force-compat-list is-rejected' });
    for (const item of result.rejected.slice(0, 8)) list.append(element('li', { text: `已丢弃：${item}` }));
    wrap.append(list);
  }
  return wrap;
}

function withoutAdapterOverride(
  overrides: Readonly<Record<string, boolean>>,
  adapterId: string,
): Readonly<Record<string, boolean>> {
  const next = { ...overrides };
  delete next[adapterId];
  return next;
}

/** phoneMode=preset 的槽位选择：与「主聊天记忆注入位置」同构，占用与恢复由运行时负责。 */
function renderPhonePresetSlotSettings(context: SettingsPanelContext): HTMLElement {
  const settings = context.settings;
  const snapshot = context.presetPromptSlots;
  const section = element('div', { className: 'phone-api-slot' });
  const selected = snapshot.slots.find((slot) => slot.id === settings.phonePresetPromptId);
  const slotOptions: (readonly [string, string])[] = [
    ['', snapshot.available ? '— 选择当前预设中的普通提示词 —' : '— 预设提示词不可用 —'],
    ...(!selected && settings.phonePresetPromptId
      ? [[settings.phonePresetPromptId, `已失效的槽位 · ${settings.phonePresetPromptId}`] as const]
      : []),
    ...snapshot.slots.map((slot) => {
      const position = slot.position === 'in_chat' ? `聊天内 depth ${slot.depth ?? 0}` : `相对位置 #${slot.index + 1}`;
      const content = slot.contentLength > 0 ? `${slot.contentLength} 字` : '空槽';
      return [slot.id, `${slot.name} · ${slot.role} · ${position} · ${content} · ${slot.enabled ? '启用' : '停用'}`] as const;
    }),
  ];

  section.append(
    element('h3', { className: 'phone-subsection-title', text: '手机互动注入位置' }),
    element('p', {
      className: 'phone-settings-hint',
      text: '本轮互动不再写入楼层，而是在下一次正文生成前临时占用所选预设条目，并在生成结束、停止、切聊天或切预设时恢复原内容。',
    }),
    element('p', {
      className: 'phone-settings-hint',
      text: snapshot.available ? `${snapshot.presetName} · ${snapshot.slots.length} 个可选槽位` : snapshot.reason,
    }),
    selectField('目标提示词槽位', slotOptions, settings.phonePresetPromptId, (value) => context.onChange({
      phonePresetPromptId: value,
    })),
    selectField(
      '注入角色',
      [
        ['', '沿用目标槽位角色'],
        ['system', 'system'],
        ['user', 'user'],
        ['assistant', 'assistant（仅了解预填充语义时使用）'],
      ],
      settings.phonePresetPromptRole,
      (value) => context.onChange({
        phonePresetPromptRole: value === 'system' || value === 'user' || value === 'assistant' ? value : '',
      }),
    ),
  );

  if (selected) {
    section.append(element('p', {
      className: 'phone-settings-hint',
      text: selected.contentLength > 0
        ? `所选条目当前已有 ${selected.contentLength} 字内容；插件会在生成期间临时替换并在结束后完整恢复。异常退出前请避免手动编辑同一条目。`
        : '所选条目当前为空；插件仍会保存并恢复其启用状态、角色、位置和完整内容。',
    }));
  }
  if (settings.memory.injectionMode === 'preset'
    && settings.memory.presetPromptId
    && settings.memory.presetPromptId === settings.phonePresetPromptId) {
    section.append(element('p', {
      className: 'phone-settings-hint',
      text: '该槽位已被「主聊天记忆注入位置」占用，两处注入必须使用不同的条目，否则手机互动会被拒绝写入。',
    }));
  }

  const actions = element('div', { className: 'phone-settings-inline-actions' });
  const refresh = button('刷新预设槽位', 'phone-button phone-button-secondary phone-button-compact', async () => {
    refresh.disabled = true;
    try {
      await context.onRefresh();
      context.showNotice('已重新读取当前预设提示词槽位。', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      refresh.disabled = false;
    }
  });
  actions.append(refresh);
  section.append(actions);
  return section;
}

