/**
 * 自定义绘图提示词与自定义标记标签。
 * 与供应商无关：标签一旦配置，消息里出现该包裹结构就会显示生成图片按钮。
 */
function renderCustomImagePromptSection(
  config: PhoneExtensionSettings['imageGeneration'],
  patch: (partial: Partial<PhoneExtensionSettings['imageGeneration']>) => void | Promise<void>,
): HTMLElement {
  const section = element('div', { className: 'phone-settings-subcard' });
  section.append(
    element('h3', { className: 'phone-subsection-title', text: '自定义绘图提示词' }),
    checkboxField(
      '启用自定义绘图提示词',
      '开启后，下方提示词会追加到生成指令中；同时启用自定义标签识别。',
      config.customPromptEnabled,
      (checked) => patch({ customPromptEnabled: checked }),
    ),
  );
  if (!config.customPromptEnabled) return section;

  section.append(
    textareaField(
      '绘图提示词',
      config.customPrompt,
      '例如：照片统一使用胶片质感、暖色调；人物避免正脸特写。',
      (value) => patch({ customPrompt: value }),
    ),
    element('p', {
      className: 'phone-settings-hint',
      text: '自定义标签：两个都填写后，正文里被这对标签包裹的内容会被当作绘图提示词，自动显示「点击生成图片」按钮；内置的 image###...### 格式始终有效。',
    }),
    textField('开始标签', config.customMarkerStart, '例如 <img>', (value) => {
      void patch({ customMarkerStart: value });
    }),
    textField('结束标签', config.customMarkerEnd, '例如 </img>', (value) => {
      void patch({ customMarkerEnd: value });
    }),
  );

  const start = config.customMarkerStart.trim();
  const end = config.customMarkerEnd.trim();
  if (start || end) {
    const usable = isUsableCustomImageMarker(start, end);
    section.append(element('p', {
      className: 'phone-settings-hint',
      text: usable
        ? `已启用自定义标签识别：${start}提示词${end}`
        : '开始标签与结束标签都填写后才会生效，目前仍只识别内置格式。',
    }));
  }
  return section;
}

/** 运行日志：查看 / 暂停 / 导出 / 清空。 */
function renderLogsCard(context: SettingsPanelContext): HTMLElement {
  const card = element('div', { className: 'phone-settings-card phone-logs-card' });
  const entries = phoneLogger.entries();

  const toolbar = element('div', { className: 'phone-settings-inline-actions phone-logs-toolbar' });
  const pauseButton = button(
    phoneLogger.isPaused() ? '继续记录' : '暂停记录',
    'phone-button phone-button-secondary phone-button-compact',
    () => {
      phoneLogger.setPaused(!phoneLogger.isPaused());
      context.navigateSection('logs');
    },
  );
  const refreshButton = button('刷新', 'phone-button phone-button-secondary phone-button-compact', () => {
    context.navigateSection('logs');
  });
  const exportButton = button('导出', 'phone-button phone-button-secondary phone-button-compact', () => {
    const text = phoneLogger.exportText();
    if (!text) {
      context.showNotice('当前没有日志可导出。', 'info');
      return;
    }
    downloadTextFile(`墨韵手机日志-${new Date().toISOString().slice(0, 19).replace(/[T:]/g, '-')}.txt`, text);
    context.showNotice('日志已导出。', 'success');
  });
  const clearButton = button('清空', 'phone-button phone-button-danger phone-button-compact', () => {
    phoneLogger.clear();
    context.navigateSection('logs');
  });
  toolbar.append(pauseButton, refreshButton, exportButton, clearButton);
  card.append(
    toolbar,
    element('p', {
      className: 'phone-settings-hint',
      text: `共 ${entries.length} 条记录${phoneLogger.isPaused() ? '（已暂停记录新日志）' : ''}；日志同时输出到浏览器控制台。`,
    }),
  );

  const list = element('div', { className: 'phone-logs-list' });
  if (entries.length === 0) {
    list.append(element('p', { className: 'phone-settings-hint', text: '暂无日志。' }));
  }
  for (const entry of [...entries].reverse().slice(0, 200)) {
    const row = element('div', { className: `phone-log-row phone-log-${entry.level}` });
    const time = new Date(entry.timestamp);
    const pad = (value: number) => String(value).padStart(2, '0');
    row.append(
      element('span', {
        className: 'phone-log-time',
        text: `${pad(time.getHours())}:${pad(time.getMinutes())}:${pad(time.getSeconds())}`,
      }),
      element('span', { className: 'phone-log-level', text: entry.level.toUpperCase() }),
      element('span', { className: 'phone-log-message', text: entry.message }),
    );
    if (entry.detail) {
      const detail = element('details', { className: 'phone-log-detail' });
      const summary = element('summary', { text: '详情' });
      detail.append(summary, element('pre', { className: 'phone-log-detail-pre', text: entry.detail }));
      row.append(detail);
    }
    list.append(row);
  }
  card.append(list);
  return card;
}

