/** 提示词预设：保存/应用/删除固定正负面提示词组合。 */
function renderPromptPresetSection(
  context: SettingsPanelContext,
  config: PhoneExtensionSettings['imageGeneration'],
  patch: (partial: Partial<PhoneExtensionSettings['imageGeneration']>) => void | Promise<void>,
): HTMLElement {
  const box = element('div', { className: 'phone-setting-control phone-setting-control-stack' });
  box.append(element('span', { className: 'phone-control-label', text: '提示词预设' }));

  const row = element('div', { className: 'phone-inline-group' });
  const select = element('select', { className: 'phone-select phone-preset-select' });
  select.append(element('option', { text: config.promptPresets.length > 0 ? '— 选择预设以应用 —' : '（还没有保存的预设）', attributes: { value: '' } }));
  for (const preset of config.promptPresets) {
    select.append(element('option', { text: preset.name, attributes: { value: preset.name } }));
  }
  select.addEventListener('change', () => {
    const preset = config.promptPresets.find((item) => item.name === select.value);
    if (!preset) return;
    void Promise.resolve()
      .then(() => patch({ positivePrompt: preset.positive, negativePrompt: preset.negative }))
      .then(() => context.showNotice(`已应用预设「${preset.name}」。`, 'success'))
      .catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });

  const save = button('保存当前', 'phone-button phone-button-secondary phone-button-compact', async () => {
    const host = document.getElementById('narrative-phone-host');
    const shell = host?.shadowRoot?.querySelector<HTMLElement>('.phone-shell');
    if (!shell) return;
    const values = await showModal(shell, '保存提示词预设', [
      { name: 'name', label: '预设名称', required: true, placeholder: '例如：日常插画风' },
    ]);
    const name = values?.name?.trim().slice(0, 40);
    if (!name) return;
    const others = config.promptPresets.filter((item) => item.name !== name);
    await patch({
      promptPresets: [...others, { name, positive: config.positivePrompt, negative: config.negativePrompt }],
    });
    context.showNotice(`预设「${name}」已保存。`, 'success');
  });
  const remove = button('删除所选', 'phone-button phone-button-danger phone-button-compact', async () => {
    const name = select.value;
    if (!name) {
      context.showNotice('请先在下拉框中选择要删除的预设。', 'info');
      return;
    }
    await patch({ promptPresets: config.promptPresets.filter((item) => item.name !== name) });
    context.showNotice(`预设「${name}」已删除。`, 'info');
  });
  row.append(select, save, remove);
  box.append(row, element('small', {
    className: 'phone-settings-hint',
    text: '「保存当前」会把上面的固定正/负面提示词存成一个预设；选择预设即可一键切换。',
  }));
  return box;
}

