/** 导入流程：选文件 → 校验预览 → 跨作用域二次确认 → 覆盖确认 → 原子恢复。 */
async function runBackupImport(context: SettingsPanelContext): Promise<void> {
  const picked = await pickTextFile();
  if (!picked) return;
  let preview: PhoneBackupPreview;
  try {
    preview = await context.onPreviewBackup(picked.text);
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    return;
  }
  const stats = preview.statistics;
  const summaryLine = [
    `文件：${picked.name}`,
    `导出时间：${preview.exportedAt > 0 ? new Date(preview.exportedAt).toLocaleString() : '未知'}`,
    `联系人 ${stats.profiles} · 会话 ${stats.conversations} · 消息 ${stats.messages} · 动态 ${stats.posts}`,
    `记忆 ${stats.memoryItems} · 时间线 ${stats.timelineEvents} · 日记 ${stats.diaryEntries} · 节日 ${stats.calendarFestivals}`,
  ].join('\n');
  if (!preview.checksumValid) {
    if (!window.confirm(`${summaryLine}\n\n备份校验和与内容不一致，文件可能被手工修改过。仍要继续导入吗？`)) return;
  }
  if (preview.requiresScopeConfirmation) {
    const scopeWarning = [
      summaryLine,
      '',
      '⚠ 这份备份来自其他聊天：',
      `备份作用域：${preview.sourceScopeId}`,
      `当前作用域：${preview.targetScopeId}`,
      '',
      '继续会把备份数据重映射到当前聊天，并覆盖当前聊天的全部手机数据。确定继续吗？',
    ].join('\n');
    if (!window.confirm(scopeWarning)) return;
  }
  if (!window.confirm(`${summaryLine}\n\n导入会覆盖当前聊天的全部手机数据，且无法撤销。确定继续吗？`)) return;
  try {
    const result = await context.onImportBackup(picked.text, {
      allowScopeChange: preview.requiresScopeConfirmation,
    });
    context.showNotice(result.message, result.ok ? 'success' : 'error');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

