import type {
  CalendarFestival,
  Conversation,
  DiaryEntry,
  DynamicWorldBookEntryState,
  FanficNarrativeState,
  ForumBoard,
  GenerationBatch,
  Interaction,
  MemoryItem,
  OutboxItem,
  PhoneMessage,
  PhonePost,
  PhoneSummary,
  Profile,
  PxxProduct,
  TimelineEvent,
  WorldClock,
} from './model.js';
import type { NarrativePatch } from '../fanfic/patch-protocol.js';

interface EventEnvelope<TType extends string, TPayload> {
  readonly id: string;
  readonly scopeId: string;
  readonly type: TType;
  readonly occurredAt: number;
  readonly payload: TPayload;
  readonly actionId?: string;
}

export type PhoneEvent =
  | EventEnvelope<'profile.upserted', { readonly profile: Profile }>
  | EventEnvelope<'profile.deleted', { readonly profileId: string }>
  | EventEnvelope<'conversation.upserted', { readonly conversation: Conversation }>
  | EventEnvelope<'conversation.deleted', { readonly conversationId: string }>
  | EventEnvelope<'conversation.read', { readonly conversationId: string }>
  | EventEnvelope<'message.queued', { readonly message: PhoneMessage; readonly outboxItem: OutboxItem }>
  | EventEnvelope<'message.received', { readonly message: PhoneMessage }>
  | EventEnvelope<'message.claimed', { readonly messageId: string; readonly claimStatus: 'claimed' | 'declined'; readonly content?: string }>
  | EventEnvelope<'message.deleted', { readonly messageId: string }>
  | EventEnvelope<'post.queued', { readonly post: PhonePost; readonly outboxItem: OutboxItem }>
  | EventEnvelope<'post.created', { readonly post: PhonePost }>
  | EventEnvelope<'post.deleted', { readonly postId: string }>
  | EventEnvelope<'forum.board.created', { readonly board: ForumBoard }>
  | EventEnvelope<'forum.board.updated', { readonly board: ForumBoard; readonly previousName: string }>
  | EventEnvelope<'forum.board.deleted', { readonly boardId: string }>
  /** 只迁移帖子归属：NPC/世界书写出的内容板块没有登记记录，改名与并回默认板块都靠它。 */
  | EventEnvelope<'forum.board.renamed', { readonly previousName: string; readonly name: string }>
  | EventEnvelope<'forum.item.deleted', { readonly itemId: string }>
  | EventEnvelope<'interaction.created', { readonly interaction: Interaction }>
  | EventEnvelope<'interaction.deleted', { readonly interactionId: string }>
  | EventEnvelope<'batch.started', { readonly batch: GenerationBatch }>
  | EventEnvelope<
      'batch.completed',
      {
        readonly batchId: string;
        readonly completedAt: number;
        readonly completedOutboxIds: readonly string[];
        readonly queuedOutboxIds: readonly string[];
        readonly error?: string;
      }
    >
  | EventEnvelope<
      'batch.failed',
      { readonly batchId: string; readonly failedAt: number; readonly error: string }
    >
  | EventEnvelope<'clock.advanced', { readonly clock: WorldClock }>
  | EventEnvelope<'summary.recorded', { readonly summary: PhoneSummary }>
  | EventEnvelope<'pxx.products.added', { readonly products: readonly PxxProduct[] }>
  | EventEnvelope<'calendar.festival.upserted', { readonly festival: CalendarFestival }>
  | EventEnvelope<'calendar.festival.removed', { readonly date: string }>
  | EventEnvelope<'diary.baseline.set', { readonly coveredUntil: number }>
  | EventEnvelope<'diary.entry.recorded', { readonly entry: DiaryEntry }>
  | EventEnvelope<'diary.entry.removed', { readonly entryId: string }>
  | EventEnvelope<'memory.baseline.set', { readonly floor: number }>
  | EventEnvelope<
      'memory.floors.invalidated',
      { readonly fromFloor: number; readonly resumeAfterFloor: number }
    >
  | EventEnvelope<'memory.item.recorded', { readonly item: MemoryItem; readonly archiveSeqs?: readonly number[] }>
  | EventEnvelope<'memory.item.updated', { readonly item: MemoryItem }>
  | EventEnvelope<'memory.item.removed', { readonly itemId: string }>
  | EventEnvelope<'timeline.events.recorded', { readonly events: readonly TimelineEvent[] }>
  | EventEnvelope<'timeline.event.removed', { readonly eventId: string }>
  | EventEnvelope<'dynamic-worldbook.baseline.set', {
      readonly floor: number;
      readonly entries: readonly DynamicWorldBookEntryState[];
    }>
  | EventEnvelope<'dynamic-worldbook.optimized', {
      readonly floor: number;
      readonly updates: readonly DynamicWorldBookEntryState[];
    }>
  | EventEnvelope<'dynamic-worldbook.invalidated', { readonly fromFloor: number }>
  | EventEnvelope<'dynamic-worldbook.entry.edited', { readonly entry: DynamicWorldBookEntryState }>
  | EventEnvelope<'dynamic-worldbook.cleared', Record<string, never>>
  | EventEnvelope<'fanfic.narrative.advanced', { readonly floor: number; readonly patch: NarrativePatch }>
  | EventEnvelope<'fanfic.narrative.invalidated', { readonly fromFloor: number }>
  | EventEnvelope<'fanfic.narrative.replaced', { readonly narrative: FanficNarrativeState }>
  | EventEnvelope<'fanfic.narrative.cleared', Record<string, never>>;

export type PhoneEventType = PhoneEvent['type'];

export type EventOfType<TType extends PhoneEventType> = Extract<PhoneEvent, { readonly type: TType }>;

export function createPhoneEvent<TType extends PhoneEventType>(
  event: Omit<EventOfType<TType>, 'id'> & { readonly id?: string },
  createId: () => string,
): EventOfType<TType> {
  return {
    ...event,
    id: event.id ?? createId(),
  } as EventOfType<TType>;
}