/**
 * 宿主层通知栈：手机所有操作的「进行中 / 成功 / 失败」提示都渲染到这里。
 *
 * 只负责「怎么显示」——堆叠布局、进出与重排动画、自动消失计时；
 * 不认识任何业务语义，操作名与文案由 phone-operations.ts / phone-task.ts 提供。
 */

import {
  MAX_NOTICE_DEPTH,
  MAX_VISIBLE_NOTICES,
  noticeDepth,
} from './notice-stack-depth.js';

/** 通知语义色：pending 常驻并呼吸，其余为终态。 */
export type NoticeKind = 'pending' | 'success' | 'error' | 'warn' | 'info';

export interface NoticeAction {
  readonly label: string;
  readonly run: () => void;
}

export interface NoticeSpec {
  /** 加粗主标题，例如「墨韵手机 数据库填表」。 */
  readonly title: string;
  /** 副文案，例如「正在填表，请稍候…」。 */
  readonly detail?: string;
  readonly kind: NoticeKind;
  /** 0 或省略表示常驻，直到转为终态或被关闭。 */
  readonly durationMs?: number;
  /** 行内动作按钮，例如「终止」。 */
  readonly action?: NoticeAction | null;
  /** 同 key 的通知会复用同一张卡片，避免同一操作刷屏。 */
  readonly key?: string;
}

export interface NoticeHandle {
  readonly key: string;
  /** 原地更新同一张卡片（进行中 → 成功/失败都走这里，卡片不闪断）。 */
  readonly update: (patch: Partial<NoticeSpec>) => void;
  readonly dismiss: () => void;
  readonly isAlive: () => boolean;
}

const STACK_ID = 'moyun-phone-notice-stack';
const STYLE_ID = 'moyun-phone-notice-stack-style';
/** 卡片间距；容器用等量负 margin 抵掉首条，避免增删时首条规则突变。 */
const GAP_PX = 9;
/** 入场只动卡片自身：滑入 + 淡入，纯合成动画，不触发布局。 */
const ENTER_CARD_MS = 420;
const ENTER_MS = ENTER_CARD_MS;
/** 退场：卡片先淡出，占位高度随后收拢，避免下方卡片被猛地拽上来。 */
const EXIT_CARD_MS = 200;
const EXIT_SLOT_MS = 280;
const EXIT_SLOT_DELAY_MS = 110;
const EXIT_MS = EXIT_SLOT_MS + EXIT_SLOT_DELAY_MS;
/** 文案在同一张卡片上变化时的高度过渡。 */
const RESIZE_MS = 320;

const KIND_ACCENTS: Readonly<Record<NoticeKind, string>> = {
  pending: '#f0a33c',
  success: '#32d074',
  error: '#ff4f45',
  warn: '#ffb020',
  info: '#8b7bff',
};

const STACK_CSS = `
  #${STACK_ID} {
    position: fixed;
    top: max(18px, env(safe-area-inset-top));
    right: max(18px, env(safe-area-inset-right));
    /* 高于 src/styles/index.css 中手机舞台的 2147483000。 */
    z-index: 2147483647 !important;
    display: flex;
    box-sizing: border-box;
    flex-direction: column;
    align-items: flex-end;
    width: min(430px, calc(100vw - 32px));
    /* 抵掉首条卡片的统一间距：所有 slot 用同一条 margin 规则，增删时不会突变。 */
    margin: -${GAP_PX}px 0 0;
    padding: 0;
    pointer-events: none;
    --moyun-notice-offset: 18px;
    --moyun-out: cubic-bezier(0.22, 1, 0.36, 1);
    --moyun-spring: cubic-bezier(0.32, 1.28, 0.58, 1);
    --moyun-in: cubic-bezier(0.4, 0, 0.7, 0.1);
  }
  .moyun-notice-slot {
    display: flex;
    box-sizing: border-box;
    justify-content: flex-end;
    width: 100%;
    margin-top: ${GAP_PX}px;
    transition:
      height ${EXIT_SLOT_MS}ms var(--moyun-in),
      margin-top ${EXIT_SLOT_MS}ms var(--moyun-in);
  }
  /* 调整文案高度时裁剪；进出场保持溢出可见，避免横向滑动被占位槽截断。 */
  .moyun-notice-slot.is-resizing {
    overflow: hidden;
    will-change: height;
  }
  .moyun-notice-slot.is-resizing {
    transition: height ${RESIZE_MS}ms var(--moyun-out);
  }
  .moyun-notice-slot.is-leaving {
    transition:
      height ${EXIT_SLOT_MS}ms var(--moyun-in) ${EXIT_SLOT_DELAY_MS}ms,
      margin-top ${EXIT_SLOT_MS}ms var(--moyun-in) ${EXIT_SLOT_DELAY_MS}ms;
  }
  .moyun-notice-card {
    display: flex;
    box-sizing: border-box;
    align-items: center;
    gap: 9px;
    max-width: 100%;
    padding: 9px 9px 9px 14px;
    border: 0.5px solid color-mix(in srgb, var(--moyun-notice-accent, #8b7bff) 38%, rgba(255, 255, 255, 0.1));
    border-radius: 999px;
    color: #f4f5f9;
    background: rgba(26, 28, 36, 0.9);
    backdrop-filter: blur(18px) saturate(150%);
    -webkit-backdrop-filter: blur(18px) saturate(150%);
    box-shadow: 0 14px 36px rgba(0, 0, 0, 0.36);
    font: 500 12.5px/1.45 system-ui, -apple-system, "Segoe UI", sans-serif;
    opacity: 0;
    pointer-events: auto;
    transform: translate3d(calc(100vw + 100%), 0, 0);
    transition:
      opacity ${Math.round(ENTER_CARD_MS * 0.55)}ms var(--moyun-out),
      transform ${ENTER_CARD_MS}ms var(--moyun-spring),
      background-color 300ms var(--moyun-out),
      border-color 300ms var(--moyun-out);
    will-change: transform, opacity;
  }
  /*
   * 越靠下（越新）的卡片越贴右，越旧的往左后退，形成层次而不互相覆盖。
   * 这一步只能用 transform：早先用的是 margin-right，会把旧卡片的可用宽度真的削掉
   * 18~54px，于是「墨韵手机 楼层摘要 / 正在整理楼层摘要……」这种本可一行的文案
   * 在栈里排第二条时就被挤成两行。transform 不参与布局，宽度保持满格。
   */
  .moyun-notice-slot.is-visible > .moyun-notice-card {
    opacity: 1;
    animation: moyun-notice-enter ${ENTER_CARD_MS}ms var(--moyun-out);
    transform: translate3d(calc(-1 * var(--moyun-notice-depth, 0) * var(--moyun-notice-offset, 18px)), 0, 0) scale(1);
  }
  @keyframes moyun-notice-enter {
    0% { transform: translate3d(100vw, 0, 0); }
    72% { transform: translate3d(calc(-1 * var(--moyun-notice-depth, 0) * var(--moyun-notice-offset, 18px) - 12px), 0, 0); }
    100% { transform: translate3d(calc(-1 * var(--moyun-notice-depth, 0) * var(--moyun-notice-offset, 18px)), 0, 0); }
  }
  .moyun-notice-slot.is-leaving > .moyun-notice-card {
    animation: none;
    opacity: 0;
    transform: translate3d(100vw, 0, 0);
    transition:
      opacity ${Math.round(EXIT_CARD_MS * 0.85)}ms var(--moyun-in),
      transform ${EXIT_CARD_MS}ms var(--moyun-in);
  }
  .moyun-notice-card[data-kind="error"] {
    border-color: rgba(255, 96, 88, 0.44);
    background: rgba(58, 24, 24, 0.92);
  }
  .moyun-notice-card[data-kind="success"] {
    border-color: rgba(52, 214, 122, 0.38);
    background: rgba(20, 46, 32, 0.92);
  }
  .moyun-notice-card[data-kind="warn"] {
    border-color: rgba(255, 176, 32, 0.4);
    background: rgba(56, 41, 16, 0.92);
  }
  .moyun-notice-dot {
    position: relative;
    flex: 0 0 7px;
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: var(--moyun-notice-accent, #8b7bff);
    box-shadow: 0 0 0 3px color-mix(in srgb, var(--moyun-notice-accent, #8b7bff) 20%, transparent);
    transition: background-color 260ms ease, box-shadow 260ms ease;
  }
  .moyun-notice-card[data-kind="pending"] > .moyun-notice-dot {
    animation: moyun-notice-pulse 1.5s ease-in-out infinite;
  }
  @keyframes moyun-notice-pulse {
    0%, 100% { opacity: 1; box-shadow: 0 0 0 2px color-mix(in srgb, var(--moyun-notice-accent) 26%, transparent); }
    50% { opacity: 0.55; box-shadow: 0 0 0 6px color-mix(in srgb, var(--moyun-notice-accent) 6%, transparent); }
  }
  .moyun-notice-body {
    display: flex;
    min-width: 0;
    flex: 1 1 auto;
    align-items: baseline;
    gap: 7px;
    /*
     * 不换行：标题与正文永远在同一行，空间不足时由 detail 在自己内部折行
     * （靠 flex 基准宽度 0 与 overflow-wrap: anywhere）。
     * 用 wrap 的话，宽度差一点点就会把整条 detail 甩到标题下面，白占一行高度。
     */
    flex-wrap: nowrap;
  }
  .moyun-notice-title {
    flex: 0 0 auto;
    /* 标题跟随状态色：一眼能看出这条是进行中、成功还是失败。 */
    color: var(--moyun-notice-accent, #fff);
    font-weight: 700;
    letter-spacing: 0.2px;
    white-space: nowrap;
    transition: color 260ms ease;
  }
  .moyun-notice-detail {
    min-width: 0;
    /*
     * basis 0：detail 的 flex 基准宽度不参与「要不要换行」的判定，
     * 空间够时它照常显示成一行，不够时先在自己内部折行，
     * 而不是把整条 detail 甩到标题下面另起一行。
     */
    flex: 1 1 0%;
    color: rgba(255, 255, 255, 0.82);
    font-weight: 500;
    overflow-wrap: anywhere;
  }
  .moyun-notice-detail:empty { display: none; }
  .moyun-notice-action {
    display: inline-flex;
    flex: 0 0 auto;
    align-items: center;
    gap: 5px;
    margin: 0;
    padding: 3px 10px;
    border: 0.5px solid rgba(255, 255, 255, 0.28);
    border-radius: 999px;
    color: inherit;
    background: rgba(255, 255, 255, 0.08);
    cursor: pointer;
    font: 600 11.5px/1.35 inherit;
    transition: background-color 140ms ease, border-color 140ms ease;
  }
  /* 停止方块：让「终止」在一眼扫过时就能被认出是中断入口。 */
  .moyun-notice-action::before {
    flex: 0 0 7px;
    width: 7px;
    height: 7px;
    border-radius: 2px;
    background: currentColor;
    content: '';
  }
  .moyun-notice-action:hover,
  .moyun-notice-action:focus-visible {
    border-color: rgba(255, 255, 255, 0.5);
    background: rgba(255, 255, 255, 0.18);
  }
  .moyun-notice-action[hidden] { display: none; }
  .moyun-notice-close {
    display: inline-grid;
    flex: 0 0 22px;
    width: 22px;
    height: 22px;
    margin: 0;
    padding: 0;
    border: 0.5px solid rgba(255, 255, 255, 0.22);
    border-radius: 7px;
    color: inherit;
    background: transparent;
    place-items: center;
    cursor: pointer;
    font: 400 15px/1 system-ui, sans-serif;
    opacity: 0.7;
    transition: background-color 140ms ease, opacity 140ms ease;
  }
  .moyun-notice-close:hover,
  .moyun-notice-close:focus-visible {
    background: rgba(255, 255, 255, 0.16);
    opacity: 1;
  }
  .moyun-notice-close:focus-visible,
  .moyun-notice-action:focus-visible {
    outline: 2px solid rgba(255, 255, 255, 0.86);
    outline-offset: 1px;
  }
  .moyun-notice-card[data-kind="pending"]::after {
    position: absolute;
    right: 16px;
    bottom: 2px;
    left: 16px;
    height: 1.5px;
    border-radius: 999px;
    background: linear-gradient(
      90deg,
      transparent,
      var(--moyun-notice-accent) 42%,
      var(--moyun-notice-accent) 58%,
      transparent
    );
    content: '';
    opacity: 0.7;
    animation: moyun-notice-sweep 1.7s linear infinite;
  }
  .moyun-notice-card { position: relative; overflow: hidden; }
  @keyframes moyun-notice-sweep {
    from { transform: translate3d(-70%, 0, 0); }
    to { transform: translate3d(70%, 0, 0); }
  }
  @media (max-width: 600px) {
    #${STACK_ID} {
      top: max(12px, env(safe-area-inset-top));
      right: max(12px, env(safe-area-inset-right));
      width: calc(100vw - 24px);
      /* 窄屏本来就没有富余宽度，阶梯缩进会把旧卡片推出左边缘，这里直接取消。 */
      --moyun-notice-offset: 0px;
    }
    .moyun-notice-card { font-size: 12px; }
  }
  @media (prefers-reduced-motion: reduce) {
    .moyun-notice-slot,
    .moyun-notice-slot.is-resizing,
    .moyun-notice-slot.is-leaving,
    .moyun-notice-card,
    .moyun-notice-slot.is-leaving > .moyun-notice-card {
      transition-duration: 1ms;
      transition-delay: 0ms;
    }
    .moyun-notice-slot.is-visible > .moyun-notice-card { animation: none; }
    .moyun-notice-card[data-kind="pending"] > .moyun-notice-dot,
    .moyun-notice-card[data-kind="pending"]::after { animation: none; }
  }
`;

interface NoticeEntry {
  readonly key: string;
  readonly slot: HTMLDivElement;
  readonly card: HTMLDivElement;
  readonly dot: HTMLSpanElement;
  readonly title: HTMLElement;
  readonly detail: HTMLElement;
  readonly action: HTMLButtonElement;
  readonly close: HTMLButtonElement;
  spec: NoticeSpec;
  hideHandle: number | null;
  removeHandle: number | null;
  settleHandle: number | null;
  leaving: boolean;
}

/** 按插入顺序保存活跃卡片；Map 的迭代顺序即视觉从上到下的顺序。 */
const entries = new Map<string, NoticeEntry>();
let autoKeySeq = 0;

function hostDocument(): Document | null {
  try {
    const parent = window.parent;
    // 当前窗口就是酒馆页面时使用当前文档；嵌入窗口必须使用父文档。
    return parent && parent !== window ? parent.document : document;
  } catch {
    // 父窗口不可访问时不能退回手机 iframe，否则提示会显示在手机内部。
    return null;
  }
}

function ensureStack(doc: Document): HTMLDivElement | null {
  if (!doc.head || !doc.body) return null;
  if (!doc.getElementById(STYLE_ID)) {
    const style = doc.createElement('style');
    style.id = STYLE_ID;
    style.textContent = STACK_CSS;
    doc.head.append(style);
  }
  const existing = doc.getElementById(STACK_ID);
  if (existing instanceof HTMLDivElement) return existing;
  existing?.remove();
  const stack = doc.createElement('div');
  stack.id = STACK_ID;
  stack.setAttribute('role', 'log');
  stack.setAttribute('aria-live', 'polite');
  stack.setAttribute('aria-label', '墨韵手机通知');
  doc.body.append(stack);
  return stack;
}

function clearHandle(handle: number | null): null {
  if (handle !== null) window.clearTimeout(handle);
  return null;
}

function refreshDepths(): void {
  const list = [...entries.values()].filter((entry) => !entry.leaving);
  list.forEach((entry, index) => {
    entry.card.style.setProperty('--moyun-notice-depth', String(noticeDepth(index, list.length)));
  });
}

/**
 * 内容或存在性变化后把 slot 高度过渡到内容高度。
 * 先写死当前高度再切到目标高度，让「进行中 → 成功」这类文案变化也是滑动而不是跳变。
 */
function transitionHeight(entry: NoticeEntry, target: number | 'content'): void {
  const from = entry.slot.getBoundingClientRect().height;
  entry.slot.style.height = `${from}px`;
  // 读取一次布局，确保起点高度已生效再切换到终点。
  void entry.slot.offsetHeight;
  const to = target === 'content' ? entry.card.getBoundingClientRect().height : target;
  entry.slot.style.height = `${to}px`;
}

/** 文案变化引起的高度过渡：用更短的曲线，避免和入场一样"沉"。 */
function resizeHeight(entry: NoticeEntry): void {
  entry.slot.classList.add('is-resizing');
  transitionHeight(entry, 'content');
  releaseHeight(entry, RESIZE_MS, () => entry.slot.classList.remove('is-resizing'));
}

/** 过渡结束后交还高度控制权，卡片文案换行数变化时不会被写死的高度截断。 */
function releaseHeight(entry: NoticeEntry, delay: number, onSettled?: () => void): void {
  entry.settleHandle = clearHandle(entry.settleHandle);
  entry.settleHandle = window.setTimeout(() => {
    entry.settleHandle = null;
    onSettled?.();
    if (entry.leaving) return;
    entry.slot.style.removeProperty('height');
  }, delay);
}

function createEntry(doc: Document, key: string): NoticeEntry {
  const slot = doc.createElement('div');
  slot.className = 'moyun-notice-slot';
  const card = doc.createElement('div');
  card.className = 'moyun-notice-card';
  const dot = doc.createElement('span');
  dot.className = 'moyun-notice-dot';
  dot.setAttribute('aria-hidden', 'true');
  const body = doc.createElement('span');
  body.className = 'moyun-notice-body';
  const title = doc.createElement('strong');
  title.className = 'moyun-notice-title';
  const detail = doc.createElement('span');
  detail.className = 'moyun-notice-detail';
  body.append(title, detail);
  const action = doc.createElement('button');
  action.type = 'button';
  action.className = 'moyun-notice-action';
  action.hidden = true;
  const close = doc.createElement('button');
  close.type = 'button';
  close.className = 'moyun-notice-close';
  close.textContent = '×';
  close.setAttribute('aria-label', '关闭通知');
  close.title = '关闭通知';
  card.append(dot, body, action, close);
  slot.append(card);

  const entry: NoticeEntry = {
    key,
    slot,
    card,
    dot,
    title,
    detail,
    action,
    close,
    spec: { title: '', kind: 'info' },
    hideHandle: null,
    removeHandle: null,
    settleHandle: null,
    leaving: false,
  };
  action.addEventListener('click', () => entry.spec.action?.run());
  close.addEventListener('click', () => leave(entry));
  return entry;
}

function applySpec(entry: NoticeEntry, spec: NoticeSpec): void {
  entry.spec = spec;
  entry.title.textContent = spec.title;
  entry.detail.textContent = spec.detail?.trim() ?? '';
  entry.card.dataset.kind = spec.kind;
  entry.card.style.setProperty('--moyun-notice-accent', KIND_ACCENTS[spec.kind]);
  entry.card.setAttribute('role', spec.kind === 'error' ? 'alert' : 'status');
  const label = spec.action?.label.trim() ?? '';
  entry.action.hidden = label.length === 0;
  entry.action.textContent = label;

  entry.hideHandle = clearHandle(entry.hideHandle);
  const duration = spec.durationMs ?? 0;
  if (duration > 0) {
    entry.hideHandle = window.setTimeout(() => {
      entry.hideHandle = null;
      leave(entry);
    }, duration);
  }
}

function leave(entry: NoticeEntry): void {
  if (entry.leaving) return;
  entry.leaving = true;
  entry.hideHandle = clearHandle(entry.hideHandle);
  entry.settleHandle = clearHandle(entry.settleHandle);
  entry.removeHandle = clearHandle(entry.removeHandle);
  entries.delete(entry.key);
  // 先固定当前高度作为起点，再切到退场时序：卡片淡出在前，空间收拢在后。
  entry.slot.classList.remove('is-visible');
  entry.slot.style.height = `${entry.slot.getBoundingClientRect().height}px`;
  void entry.slot.offsetHeight;
  entry.slot.classList.add('is-leaving');
  entry.slot.style.height = '0px';
  entry.slot.style.marginTop = '0px';
  refreshDepths();
  entry.removeHandle = window.setTimeout(() => {
    entry.removeHandle = null;
    entry.slot.remove();
  }, EXIT_MS);
}

/** 超出上限时先挤掉最旧的终态卡片；全是进行中就挤掉最旧的那条。 */
function trimOverflow(): void {
  while (entries.size > MAX_VISIBLE_NOTICES) {
    const list = [...entries.values()];
    const victim = list.find((entry) => entry.spec.kind !== 'pending') ?? list[0];
    if (!victim) return;
    leave(victim);
  }
}

/**
 * 推入一条通知。带 key 时复用已有卡片（原地更新，不闪断也不重复堆叠），
 * 否则在栈底新增一张卡片。
 */
export function pushStackNotice(spec: NoticeSpec): NoticeHandle {
  const key = spec.key ?? `moyun-notice-${(autoKeySeq += 1)}`;
  const doc = hostDocument();
  const stack = doc ? ensureStack(doc) : null;
  if (!doc || !stack) return deadHandle(key);

  const existing = entries.get(key);
  if (existing && !existing.leaving) {
    applySpec(existing, { ...spec, key });
    resizeHeight(existing);
    return createHandle(existing);
  }

  const entry = createEntry(doc, key);
  applySpec(entry, { ...spec, key });
  stack.append(entry.slot);
  entries.set(key, entry);
  trimOverflow();
  refreshDepths();
  // 入场只切一个类：卡片一开始就按完整高度占位，靠自身位移与淡入进场，
  // 不做高度动画也不裁剪，因此不会先露出一条细缝再展开。
  window.requestAnimationFrame(() => {
    if (!entry.leaving) entry.slot.classList.add('is-visible');
  });
  return createHandle(entry);
}

function createHandle(entry: NoticeEntry): NoticeHandle {
  return {
    key: entry.key,
    update: (patch) => {
      const current = entries.get(entry.key);
      if (!current || current.leaving) {
        pushStackNotice({ ...entry.spec, ...patch, key: entry.key });
        return;
      }
      applySpec(current, { ...current.spec, ...patch, key: entry.key });
      resizeHeight(current);
      refreshDepths();
    },
    dismiss: () => {
      const current = entries.get(entry.key);
      if (current) leave(current);
    },
    isAlive: () => entries.get(entry.key) === entry && !entry.leaving,
  };
}

/** 宿主文档不可用（例如跨域父窗口）时返回的空句柄，保证调用方无需判空。 */
function deadHandle(key: string): NoticeHandle {
  return {
    key,
    update: () => undefined,
    dismiss: () => undefined,
    isAlive: () => false,
  };
}

export function dismissStackNotice(key: string): void {
  const entry = entries.get(key);
  if (entry) leave(entry);
}

export function clearStackNotices(): void {
  for (const entry of [...entries.values()]) leave(entry);
}
