import type { ImageGenerationSettings } from '../integration/sillytavern-bridge.js';
import { logHttpFailure, logOperationFailure } from '../core/diagnostics.js';

const POLL_INTERVAL_MS = 1_000;
const MAX_POLL_RETRIES = 3;

class QueueServiceError extends Error {
  readonly retryable: boolean;

  constructor(message: string, retryable: boolean) {
    super(message);
    this.name = 'QueueServiceError';
    this.retryable = retryable;
  }
}

interface QueueResponse {
  readonly position?: number;
  readonly queue_size?: number;
  readonly lock_token?: string;
  readonly is_my_turn?: boolean;
  readonly current_greeting?: string;
}

interface QueueLease {
  readonly keyHash: string;
  readonly userId: string;
  readonly taskId: string;
  readonly lockToken: string;
}

export async function withNovelAiQueue<T>(
  config: ImageGenerationSettings,
  operation: () => Promise<T>,
): Promise<T> {
  if (!config.novelaiQueueEnabled) return operation();
  const lease = await acquireQueueLease(config);
  let cancelled = false;
  try {
    return await operation();
  } catch (error) {
    cancelled = error instanceof Error && error.name === 'AbortError';
    throw error;
  } finally {
    await releaseQueue(config, lease, cancelled);
  }
}

async function acquireQueueLease(config: ImageGenerationSettings): Promise<QueueLease> {
  const baseUrl = normalizeQueueUrl(config.novelaiQueueUrl);
  if (!baseUrl) throw new Error('已启用 NovelAI 排队功能，请填写排队地址。');
  const key = config.apiKey.trim();
  if (!key) throw new Error('已启用 NovelAI 排队功能，请先填写 API Token。');

  const keyHash = await sha256(key);
  const userId = getQueueUserId();
  const taskId = createTaskId();
  const joined = await requestQueue<QueueResponse>(`${baseUrl}/join-queue`, {
    method: 'POST',
    body: JSON.stringify({ key_hash: keyHash, user_id: userId, task_id: taskId, greeting: null }),
  });
  const directToken = joined.lock_token;
  if (joined.position === 0 && directToken) {
    return { keyHash, userId, taskId, lockToken: directToken };
  }

  let retries = 0;
  while (true) {
    await sleep(POLL_INTERVAL_MS);
    try {
      const status = await requestQueue<QueueResponse>(
        `${baseUrl}/my-turn?key_hash=${encodeURIComponent(keyHash)}&user_id=${encodeURIComponent(userId)}&task_id=${encodeURIComponent(taskId)}`,
      );
      retries = 0;
      if (status.is_my_turn && status.lock_token) {
        return { keyHash, userId, taskId, lockToken: status.lock_token };
      }
    } catch (error) {
      retries += 1;
      if (retries >= MAX_POLL_RETRIES) {
        throw new QueueServiceError(
          `排队服务不可用：${error instanceof Error ? error.message : String(error)}`,
          error instanceof QueueServiceError && error.retryable,
        );
      }
    }
  }
}

async function releaseQueue(
  config: ImageGenerationSettings,
  lease: QueueLease,
  leave: boolean,
): Promise<void> {
  const baseUrl = normalizeQueueUrl(config.novelaiQueueUrl);
  if (!baseUrl) return;
  const endpoint = leave ? 'leave-queue' : 'complete';
  try {
    await requestQueue(`${baseUrl}/${endpoint}`, {
      method: 'POST',
      body: JSON.stringify({
        key_hash: lease.keyHash,
        user_id: lease.userId,
        task_id: lease.taskId,
        lock_token: lease.lockToken,
      }),
    });
  } catch (error) {
    logOperationFailure({
      stage: 'NovelAI 排队服务',
      reason: `释放排队锁（${endpoint}）失败，已保留生成结果`,
      context: { operation: endpoint },
      error,
    });
  }
}

async function requestQueue<T>(url: string, init: RequestInit = {}): Promise<T> {
  let response: Response;
  try {
    response = await fetch(url, {
      ...init,
      ...(init.body === undefined ? {} : { headers: { 'Content-Type': 'application/json' } }),
    });
  } catch (error) {
    logHttpFailure({
      stage: 'NovelAI 排队服务',
      url,
      request: { operation: init.method === 'POST' ? 'queue-write' : 'queue-read' },
      error,
    });
    throw new QueueServiceError(
      `排队服务网络不可达：${error instanceof Error ? error.message : String(error)}`,
      true,
    );
  }
  if (!response.ok) {
    const body = await response.text();
    logHttpFailure({
      stage: 'NovelAI 排队服务',
      url,
      status: response.status,
      statusText: response.statusText,
      body,
      request: { operation: init.method === 'POST' ? 'queue-write' : 'queue-read' },
    });
    throw new QueueServiceError(
      `HTTP ${response.status}：${body}`,
      response.status === 408 || response.status === 429 || response.status >= 500,
    );
  }
  try {
    return await response.json() as T;
  } catch (error) {
    logHttpFailure({
      stage: 'NovelAI 排队服务响应解码',
      url,
      request: { operation: init.method === 'POST' ? 'queue-write' : 'queue-read' },
      error,
    });
    throw new QueueServiceError(
      `排队服务返回格式错误：${error instanceof Error ? error.message : String(error)}`,
      false,
    );
  }
}

function normalizeQueueUrl(value: string): string {
  return value.trim().replace(/\/+$/, '');
}

function getQueueUserId(): string {
  const storageKey = 'sjichajian_novelai_queue_user_id';
  const existing = localStorage.getItem(storageKey)?.trim();
  if (existing) return existing;
  const created = typeof crypto.randomUUID === 'function'
    ? crypto.randomUUID()
    : `${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
  localStorage.setItem(storageKey, created);
  return created;
}

function createTaskId(): string {
  return `sjichajian-${Date.now().toString(36)}-${Math.random().toString(36).slice(2)}`;
}

async function sha256(value: string): Promise<string> {
  const data = new TextEncoder().encode(value);
  const digest = await crypto.subtle.digest('SHA-256', data);
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, '0')).join('');
}

function sleep(milliseconds: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}