import { SELF_PROFILE_ID } from '../../domain/commands.js';
import type { Conversation, Profile, PxxProduct } from '../../domain/model.js';
import { element, button } from '../../ui/dom.js';
import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';

/**
 * PXX 购物应用：
 * 商品由 AI 根据世界书与剧情生成（每轮 10 个、不重复），
 * 点击商品查看描述并可购买送给微信好友（附收货地址）。
 */
export function createPxxApp(): PhoneAppDefinition {
  let detailProductId: string | null = null;
  let generating = false;

  const startGeneration = (context: PhoneViewContext): void => {
    if (generating) return;
    generating = true;
    const existingNames = (context.state.pxxProducts ?? []).map((product) => product.name);
    void (async () => {
      try {
        const drafts = await context.generatePxxProducts(existingNames);
        // 先复位标志再入库：入库会触发重渲染，此时必须已退出加载态。
        generating = false;
        const added = await context.commands.addPxxProducts(drafts);
        context.showNotice(`已上架 ${added.length} 个新商品。`, 'success');
      } catch (error) {
        generating = false;
        context.showNotice(`商品生成失败：${error instanceof Error ? error.message : String(error)}`, 'error');
        context.navigate('pxx');
      }
    })();
  };

  const render = (context: PhoneViewContext): HTMLElement => {
    const page = element('div', { className: 'phone-page phone-pxx' });
    const products = context.state.pxxProducts ?? [];

    const detail = detailProductId ? products.find((product) => product.id === detailProductId) : undefined;
    if (detail) {
      page.append(renderDetail(context, detail, () => {
        detailProductId = null;
        context.navigate('pxx');
      }));
      return page;
    }
    detailProductId = null;

    const header = element('div', { className: 'phone-pxx-header' });
    header.append(
      element('strong', { className: 'phone-pxx-title', text: '为你推荐' }),
      element('small', { className: 'phone-pxx-subtitle', text: '根据剧情与你的喜好挑选' }),
    );
    page.append(header);

    if (generating) {
      page.append(element('p', { className: 'phone-empty phone-pxx-loading', text: '正在根据剧情挑选商品…' }));
    } else if (products.length === 0) {
      // 首次进入不自动调用 AI，由用户点击按钮触发。
      const emptyBox = element('div', { className: 'phone-empty phone-pxx-empty' });
      emptyBox.append(
        element('strong', { text: '货架还是空的' }),
        element('span', { text: '点击下方按钮，AI 会根据世界书与剧情为你挑选 10 个商品。' }),
      );
      const generate = button('立即生成商品信息', 'phone-button phone-button-primary phone-pxx-first-generate', () => {
        startGeneration(context);
        context.navigate('pxx');
      });
      emptyBox.append(generate);
      page.append(emptyBox);
    } else {
      const grid = element('div', { className: 'phone-pxx-grid' });
      for (const product of [...products].reverse()) {
        const card = button('', 'phone-pxx-card', () => {
          detailProductId = product.id;
          context.navigate('pxx');
        });
        card.append(
          element('strong', { className: 'phone-pxx-card-name', text: product.name }),
          element('span', { className: 'phone-pxx-card-desc', text: product.description }),
          buildCardFooter(product),
        );
        grid.append(card);
      }
      page.append(grid);
    }

    if (!generating && products.length > 0) {
      const more = button('继续生成 10 个商品', 'phone-button phone-button-secondary phone-pxx-more', () => {
        startGeneration(context);
        context.navigate('pxx');
      });
      page.append(more);
    }
    return page;
  };

  return {
    id: 'pxx',
    label: 'PXX',
    icon: '🛍',
    navigation: [],
    render,
  };
}

function buildCardFooter(product: PxxProduct): HTMLElement {
  const footer = element('span', { className: 'phone-pxx-card-footer' });
  footer.append(element('strong', { className: 'phone-pxx-price', text: product.price }));
  if (product.category) {
    footer.append(element('span', { className: 'phone-pxx-category', text: product.category }));
  }
  return footer;
}

function renderDetail(context: PhoneViewContext, product: PxxProduct, onBack: () => void): HTMLElement {
  const wrap = element('div', { className: 'phone-pxx-detail' });
  const back = button('← 返回商品列表', 'phone-button phone-button-secondary phone-button-compact phone-pxx-back', onBack);
  wrap.append(back);

  const card = element('div', { className: 'phone-card phone-pxx-detail-card' });
  card.append(
    element('h3', { className: 'phone-pxx-detail-name', text: product.name }),
    buildCardFooter(product),
    element('p', { className: 'phone-pxx-detail-desc', text: product.description }),
  );
  wrap.append(card);

  const buy = button('购买并送给微信好友', 'phone-button phone-button-primary phone-pxx-buy', () => {
    void purchaseProduct(context, product);
  });
  wrap.append(buy);
  return wrap;
}

async function purchaseProduct(context: PhoneViewContext, product: PxxProduct): Promise<void> {
  const friends = Object.values(context.state.profiles)
    .filter((profile) => profile.id !== SELF_PROFILE_ID && isWechatContact(context, profile))
    .sort((a, b) => a.displayName.localeCompare(b.displayName, 'zh-CN'));
  if (friends.length === 0) {
    context.showNotice('还没有微信好友，先去微信添加联系人吧。', 'error');
    return;
  }
  const picked = await context.showContactPicker(
    `把「${product.name}」送给谁？`,
    friends.map((profile) => ({
      id: profile.id,
      name: profile.displayName,
      detail: profile.boundCharacter ? `绑定：${profile.boundCharacter}` : (profile.aliases.wechat ?? '微信联系人'),
    })),
    { min: 1, max: 1 },
  );
  const friendId = picked?.[0];
  if (!friendId) return;
  const friend = context.state.profiles[friendId];
  if (!friend) return;

  const form = await context.showModal('确认订单', [
    {
      name: 'address',
      label: '收货地址',
      value: `${friend.displayName}的常用收货地址`,
      required: true,
    },
    { name: 'note', label: '留言（可选）', placeholder: '想对 TA 说的话' },
  ]);
  if (!form) return;
  const address = (form.address ?? '').trim();
  if (!address) {
    context.showNotice('收货地址不能为空。', 'error');
    return;
  }

  try {
    let conversation = findWechatDirectConversation(context, friend.id);
    conversation ??= await context.commands.createConversation({
      appId: 'wechat',
      kind: 'direct',
      title: friend.displayName,
      participantIds: [friend.id],
    });
    const note = form.note?.trim();
    const content = note
      ? `[礼物] ${product.name}（${product.price}）：${note}`
      : `[礼物] ${product.name}（${product.price}）`;
    await context.commands.queueMessage(conversation.id, content, {
      kind: 'gift',
      metadata: {
        gift: product.name,
        price: product.price,
        address,
        source: 'PXX',
      },
    });
    context.showNotice(`已下单「${product.name}」，寄往：${address}`, 'success');
    context.openConversation(conversation.id);
  } catch (error) {
    context.showNotice(`购买失败：${error instanceof Error ? error.message : String(error)}`, 'error');
  }
}

function findWechatDirectConversation(context: PhoneViewContext, profileId: string): Conversation | undefined {
  return Object.values(context.state.conversations).find(
    (conversation) => conversation.appId === 'wechat'
      && conversation.kind === 'direct'
      && conversation.participantIds.includes(profileId),
  );
}

function isWechatContact(context: PhoneViewContext, profile: Profile): boolean {
  if (profile.aliases.wechat) return true;
  return Object.values(context.state.conversations).some(
    (conversation) => conversation.appId === 'wechat' && conversation.participantIds.includes(profile.id),
  );
}
