import type {
  Conversation,
  GenerationBatch,
  OutboxItem,
  PhoneMessage,
  PhonePost,
  PhoneState,
  Profile,
} from '../domain/model.js';
import type { IdFactory } from '../domain/ids.js';
import { createScopedId } from '../domain/ids.js';

export interface PlannedConversation {
  readonly conversation: Conversation;
  readonly participants: readonly Profile[];
  readonly messages: readonly PhoneMessage[];
  readonly outboxItems: readonly OutboxItem[];
}

export interface PlannedPost {
  readonly post: PhonePost;
  readonly outboxItem: OutboxItem;
}

export interface GenerationPlan {
  readonly batch: GenerationBatch;
  readonly scopeId: string;
  readonly worldTime: number;
  readonly conversations: readonly PlannedConversation[];
  readonly queuedPosts: readonly PlannedPost[];
  readonly availableProfiles: readonly Profile[];
  readonly recentPosts: readonly string[];
  /** 分片生成时只有首片允许自主动态，避免预算被片数放大；未设置视为允许。 */
  readonly allowAutonomous?: boolean;
}

export function createGenerationPlan(
  state: PhoneState,
  idFactory: IdFactory,
  now = Date.now(),
  disabledAppIds: readonly string[] = [],
): GenerationPlan | null {
  const disabledApps = new Set(disabledAppIds);
  const pending = Object.values(state.outbox)
    .filter((item) => item.status === 'queued' && !disabledApps.has(item.appId))
    .sort((a, b) => a.createdAt - b.createdAt);
  if (pending.length === 0) return null;

  const grouped = new Map<string, OutboxItem[]>();
  for (const item of pending) {
    if (item.entityType !== 'message' || !item.conversationId) continue;
    const items = grouped.get(item.conversationId) ?? [];
    items.push(item);
    grouped.set(item.conversationId, items);
  }

  const conversations: PlannedConversation[] = [];
  for (const [conversationId, outboxItems] of grouped) {
    const conversation = state.conversations[conversationId];
    if (!conversation) continue;
    const messages = outboxItems
      .map((item) => state.messages[item.entityId])
      .filter((message): message is PhoneMessage => Boolean(message));
    if (messages.length === 0) continue;
    const participants = conversation.participantIds
      .map((profileId) => state.profiles[profileId])
      .filter((profile): profile is Profile => Boolean(profile));
    conversations.push({ conversation, participants, messages, outboxItems });
  }
  const queuedPosts = pending.flatMap((outboxItem) => {
    if (outboxItem.entityType !== 'post') return [];
    const post = state.posts[outboxItem.entityId];
    return post ? [{ post, outboxItem }] : [];
  });
  if (conversations.length === 0 && queuedPosts.length === 0) return null;

  const outboxIds = planOutboxIds({ conversations, queuedPosts });
  const batch: GenerationBatch = {
    id: createScopedId(state.scopeId, 'batch', idFactory),
    scopeId: state.scopeId,
    outboxIds,
    status: 'running',
    createdAt: now,
  };

  const recentPosts = state.postOrder
    .slice(-12)
    .flatMap((id) => {
      const post = state.posts[id];
      return post && !disabledApps.has(post.appId)
        ? [`${post.appId}/${post.kind}/${post.profileId}: ${post.content}`]
        : [];
    });
  const availableProfiles = Object.values(state.profiles).slice(0, 40);

  return {
    batch,
    scopeId: state.scopeId,
    worldTime: state.worldClock.now,
    conversations,
    queuedPosts,
    availableProfiles,
    recentPosts,
  };
}

/** 该计划（或分片）覆盖的全部 outbox id。 */
export function planOutboxIds(plan: Pick<GenerationPlan, 'conversations' | 'queuedPosts'>): readonly string[] {
  return [
    ...plan.conversations.flatMap(({ outboxItems }) => outboxItems.map((outbox) => outbox.id)),
    ...plan.queuedPosts.map(({ outboxItem }) => outboxItem.id),
  ];
}

/**
 * 把一份计划按会话数切成多个分片，让每次生成只处理少量会话（角色多时避免串味）。
 * 用户动态与自主动态只挂在首片，否则会被重复回应、预算被片数放大。
 */
export function splitGenerationPlan(
  plan: GenerationPlan,
  maxConversations = 4,
): readonly GenerationPlan[] {
  const size = Math.max(1, Math.round(maxConversations));
  if (plan.conversations.length <= size) return [plan];
  const chunks: GenerationPlan[] = [];
  for (let index = 0; index < plan.conversations.length; index += size) {
    const isFirst = index === 0;
    chunks.push({
      ...plan,
      conversations: plan.conversations.slice(index, index + size),
      queuedPosts: isFirst ? plan.queuedPosts : [],
      allowAutonomous: isFirst,
    });
  }
  return chunks;
}