import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import {
  deleteVariableByPath,
  isMvuTupleLeaf,
  readVariables,
  replaceVariablesData,
  writeVariableByPath,
  type VariablesSnapshot,
} from '../../integration/variables-bridge.js';
import { button, clear, element } from '../../ui/dom.js';

export function createVariablesApp(): PhoneAppDefinition {
  return {
    id: 'variables',
    label: '变量管理',
    icon: 'variables',
    navigation: [],
    render: renderVariablesApp,
  };
}

/** 变量管理：只展示楼层变量，卡片式可视化，隐藏 MVU 的解释性描述。 */
function renderVariablesApp(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-variables-page' });

  let requestedMessageId: number | null = null;
  let snapshot: VariablesSnapshot | null = null;

  const floorBar = element('div', { className: 'phone-var-floor-bar' });
  const statusHint = element('p', { className: 'phone-settings-hint phone-var-status' });
  const toolbar = element('div', { className: 'phone-settings-actions phone-var-toolbar' });
  const cardsBox = element('div', { className: 'phone-var-cards' });
  page.append(floorBar, statusHint, toolbar, cardsBox);

  const currentMessageId = (): number | null => snapshot?.messageId ?? requestedMessageId;

  const renderFloorBar = () => {
    clear(floorBar);
    const messageId = currentMessageId();
    const lastId = snapshot?.lastMessageId ?? null;
    const prev = button('‹', 'phone-icon-button phone-var-floor-button', () => {
      if (messageId === null || messageId <= 0) return;
      requestedMessageId = messageId - 1;
      void load();
    });
    prev.setAttribute('aria-label', '上一楼');
    const next = button('›', 'phone-icon-button phone-var-floor-button', () => {
      if (messageId === null || lastId === null || messageId >= lastId) return;
      requestedMessageId = messageId + 1;
      void load();
    });
    next.setAttribute('aria-label', '下一楼');
    prev.disabled = messageId === null || messageId <= 0;
    next.disabled = messageId === null || lastId === null || messageId >= lastId;
    const label = element('span', {
      className: 'phone-var-floor-label',
      text: messageId === null ? '暂无楼层' : `第 ${messageId} 楼${lastId !== null ? ` / 共 ${lastId + 1} 楼` : ''}`,
    });
    const latest = button('最新楼层', 'phone-button phone-button-secondary phone-button-compact', () => {
      requestedMessageId = null;
      void load();
    });
    floorBar.append(prev, label, next, latest);
  };

  const renderToolbar = () => {
    clear(toolbar);
    const refresh = button('刷新', 'phone-button phone-button-secondary phone-button-compact', () => void load(true));
    const addVariable = button('新增变量', 'phone-button phone-button-secondary phone-button-compact', async () => {
      const values = await context.showModal('新增变量', [
        { name: 'path', label: '变量路径（用 . 分隔，例如 stat_data.世界.天气）', required: true },
        { name: 'value', label: '值（可填 JSON 或纯文本）', type: 'textarea' },
      ]);
      if (!values) return;
      const path = (values.path ?? '').split('.').map((part) => part.trim()).filter(Boolean);
      if (path.length === 0) {
        context.showNotice('变量路径无效。', 'error');
        return;
      }
      const result = await writeVariableByPath('message', currentMessageId(), path, parseEditedValue(values.value ?? '', undefined));
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) await load();
    });
    const editJson = button('以 JSON 编辑全部', 'phone-button phone-button-secondary phone-button-compact', async () => {
      if (!snapshot) return;
      const values = await context.showModal('以 JSON 编辑全部变量', [
        {
          name: 'json',
          label: `第 ${currentMessageId()} 楼变量 JSON`,
          type: 'textarea',
          required: true,
          value: JSON.stringify(snapshot.data, null, 2),
        },
      ]);
      if (!values) return;
      let parsed: unknown;
      try {
        parsed = JSON.parse(values.json ?? '');
      } catch (error) {
        context.showNotice(`JSON 解析失败：${error instanceof Error ? error.message : String(error)}`, 'error');
        return;
      }
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        context.showNotice('根节点必须是 JSON 对象。', 'error');
        return;
      }
      const result = await replaceVariablesData('message', currentMessageId(), parsed as Record<string, unknown>);
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) await load();
    });
    toolbar.append(refresh, addVariable, editJson);
  };

  /** 优先展示 stat_data 内的分组；没有 stat_data 时展示根级变量。 */
  const resolveDisplayRoot = (): { readonly basePath: readonly string[]; readonly entries: readonly (readonly [string, unknown])[] } => {
    const data = snapshot?.data ?? {};
    const statData = data.stat_data;
    if (statData && typeof statData === 'object' && !Array.isArray(statData)) {
      return { basePath: ['stat_data'], entries: Object.entries(statData as Record<string, unknown>) };
    }
    return { basePath: [], entries: Object.entries(data) };
  };

  const renderCards = () => {
    clear(cardsBox);
    if (!snapshot) {
      cardsBox.append(element('p', { className: 'phone-settings-hint', text: '正在读取变量…' }));
      return;
    }
    const { basePath, entries } = resolveDisplayRoot();
    if (entries.length === 0) {
      // 具体原因已显示在上方状态行，这里给操作引导，避免重复文案。
      const empty = element('div', { className: 'phone-empty' });
      empty.append(
        element('strong', { text: '此楼层暂无变量' }),
        element('span', { text: '可点击上方「新增变量」创建，或用「以 JSON 编辑全部」批量写入。' }),
      );
      cardsBox.append(empty);
      return;
    }

    // 顶层的简单值合并进「概览」卡片；对象/数组各自成卡。
    const primitiveEntries = entries.filter(([, value]) => isLeafValue(value));
    const groupEntries = entries.filter(([, value]) => !isLeafValue(value));

    if (primitiveEntries.length > 0) {
      const card = element('section', { className: 'phone-var-card' });
      card.append(renderCardHead('概览', [...basePath], false));
      const body = element('div', { className: 'phone-var-card-body' });
      for (const [key, value] of primitiveEntries) {
        body.append(renderLeafRow([...basePath, key], key, value));
      }
      card.append(body);
      cardsBox.append(card);
    }

    for (const [key, value] of groupEntries) {
      const card = element('section', { className: 'phone-var-card' });
      card.append(renderCardHead(key, [...basePath, key], true));
      const body = element('div', { className: 'phone-var-card-body' });
      renderGroup(body, [...basePath, key], value, 0);
      card.append(body);
      cardsBox.append(card);
    }
  };

  const renderCardHead = (title: string, path: readonly string[], deletable: boolean): HTMLElement => {
    const head = element('div', { className: 'phone-var-card-head' });
    head.append(element('strong', { className: 'phone-var-card-title', text: title }));
    const actions = element('span', { className: 'phone-var-actions' });
    if (path.length > 0) {
      actions.append(makeActionButton('编辑', async () => {
        await editNodeAsJson(path, title);
      }));
      if (deletable) {
        actions.append(makeActionButton('删除', async () => {
          if (!window.confirm(`确定删除「${title}」及其全部内容吗？`)) return;
          const result = await deleteVariableByPath('message', currentMessageId(), path);
          context.showNotice(result.message, result.ok ? 'success' : 'error');
          if (result.ok) await load();
        }, true));
      }
    }
    head.append(actions);
    return head;
  };

  const renderGroup = (
    container: HTMLElement,
    path: readonly string[],
    value: unknown,
    depth: number,
  ) => {
    if (Array.isArray(value) && !isMvuTupleLeaf(value)) {
      value.forEach((item, index) => {
        const itemPath = [...path, String(index)];
        if (isLeafValue(item)) {
          container.append(renderLeafRow(itemPath, `#${index + 1}`, item));
        } else {
          container.append(renderSubsection(itemPath, `#${index + 1}`, item, depth));
        }
      });
      if (value.length === 0) {
        container.append(element('p', { className: 'phone-var-empty', text: '（空列表）' }));
      }
      return;
    }
    if (value && typeof value === 'object') {
      const entries = Object.entries(value as Record<string, unknown>);
      if (entries.length === 0) {
        container.append(element('p', { className: 'phone-var-empty', text: '（空对象）' }));
        return;
      }
      for (const [key, child] of entries) {
        const childPath = [...path, key];
        if (isLeafValue(child)) {
          container.append(renderLeafRow(childPath, key, child));
        } else {
          container.append(renderSubsection(childPath, key, child, depth));
        }
      }
    }
  };

  const renderSubsection = (
    path: readonly string[],
    title: string,
    value: unknown,
    depth: number,
  ): HTMLElement => {
    const section = element('div', { className: 'phone-var-subsection' });
    if (depth > 0) section.classList.add('is-nested');
    const head = element('div', { className: 'phone-var-sub-head' });
    head.append(element('span', { className: 'phone-var-sub-title', text: title }));
    const actions = element('span', { className: 'phone-var-actions' });
    actions.append(
      makeActionButton('编辑', () => editNodeAsJson(path, title)),
      makeActionButton('删除', async () => {
        if (!window.confirm(`确定删除「${path.join('.')}」吗？`)) return;
        const result = await deleteVariableByPath('message', currentMessageId(), path);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) await load();
      }, true),
    );
    head.append(actions);
    section.append(head);
    const body = element('div', { className: 'phone-var-sub-body' });
    renderGroup(body, path, value, depth + 1);
    section.append(body);
    return section;
  };

  /** 叶子行：只显示值，MVU 的 [值, 描述] 二元组隐藏描述（悬停可见）。 */
  const renderLeafRow = (path: readonly string[], label: string, value: unknown): HTMLElement => {
    const isTuple = isMvuTupleLeaf(value);
    const displayValue = isTuple ? (value as readonly unknown[])[0] : value;
    const description = isTuple && typeof (value as readonly unknown[])[1] === 'string'
      ? String((value as readonly unknown[])[1])
      : undefined;

    const row = element('div', { className: 'phone-var-row' });
    if (description) row.title = description;
    const labelElement = element('span', { className: 'phone-var-label', text: label });
    const valueElement = element('span', {
      className: `phone-var-value is-${valueTypeOf(displayValue)}`,
      text: formatLeafValue(displayValue),
    });
    const actions = element('span', { className: 'phone-var-actions' });
    actions.append(
      makeActionButton('编辑', async () => {
        const values = await context.showModal(`编辑「${label}」`, [
          {
            name: 'value',
            label: description ? `新值（${description}）` : '新值',
            type: 'textarea',
            value: leafEditValue(displayValue),
          },
        ]);
        if (!values) return;
        const nextValue = parseEditedValue(values.value ?? '', displayValue);
        const result = await writeVariableByPath('message', currentMessageId(), path, nextValue, description);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) await load();
      }),
      makeActionButton('删除', async () => {
        if (!window.confirm(`确定删除变量「${path.join('.')}」吗？`)) return;
        const result = await deleteVariableByPath('message', currentMessageId(), path);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) await load();
      }, true),
    );
    row.append(labelElement, valueElement, actions);
    return row;
  };

  const editNodeAsJson = async (path: readonly string[], title: string) => {
    const current = getValueAtPath(snapshot?.data ?? {}, path);
    const values = await context.showModal(`以 JSON 编辑「${title}」`, [
      { name: 'json', label: 'JSON 内容', type: 'textarea', required: true, value: JSON.stringify(current ?? null, null, 2) },
    ]);
    if (!values) return;
    let parsed: unknown;
    try {
      parsed = JSON.parse(values.json ?? '');
    } catch (error) {
      context.showNotice(`JSON 解析失败：${error instanceof Error ? error.message : String(error)}`, 'error');
      return;
    }
    const result = await writeVariableByPath('message', currentMessageId(), path, parsed);
    context.showNotice(result.message, result.ok ? 'success' : 'error');
    if (result.ok) await load();
  };

  const makeActionButton = (label: string, action: () => void | Promise<void>, danger = false): HTMLButtonElement => {
    const control = button(label, `phone-var-action${danger ? ' is-danger' : ''}`, action);
    return control;
  };

  const load = async (notify = false) => {
    snapshot = null;
    renderCards();
    try {
      snapshot = await readVariables('message', requestedMessageId);
      statusHint.textContent = snapshot.available
        ? `${snapshot.reason}（来源：${describeSource(snapshot.source)}）`
        : snapshot.reason;
      renderFloorBar();
      renderToolbar();
      renderCards();
      if (notify) context.showNotice('变量已刷新。', 'success');
    } catch (error) {
      statusHint.textContent = `读取变量失败：${error instanceof Error ? error.message : String(error)}`;
      renderFloorBar();
      renderToolbar();
      clear(cardsBox);
    }
  };

  renderFloorBar();
  renderToolbar();
  void load();
  return page;
}

function isLeafValue(value: unknown): boolean {
  if (value === null || value === undefined) return true;
  if (typeof value !== 'object') return true;
  return isMvuTupleLeaf(value);
}

function valueTypeOf(value: unknown): string {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'number') return 'number';
  if (typeof value === 'boolean') return 'boolean';
  return 'string';
}

function getValueAtPath(root: Record<string, unknown>, path: readonly string[]): unknown {
  let current: unknown = root;
  for (const key of path) {
    if (!current || typeof current !== 'object') return undefined;
    current = (current as Record<string, unknown>)[key];
  }
  return current;
}

function describeSource(source: VariablesSnapshot['source']): string {
  if (source === 'mvu') return 'MVU 变量框架';
  if (source === 'tavernHelper') return '酒馆助手';
  if (source === 'context') return '酒馆上下文';
  return '未知';
}

function formatLeafValue(value: unknown): string {
  if (value === null) return 'null';
  if (value === undefined) return 'undefined';
  if (typeof value === 'string') return value === '' ? '（空）' : value;
  return String(value);
}

function leafEditValue(value: unknown): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  return String(value);
}

/**
 * 解析用户输入：优先保持原值类型（数字/布尔），
 * 其次尝试 JSON（对象/数组/带引号字符串），否则按纯文本处理。
 */
function parseEditedValue(input: string, originalValue: unknown): unknown {
  const trimmed = input.trim();
  if (typeof originalValue === 'number') {
    const numeric = Number(trimmed);
    if (trimmed !== '' && Number.isFinite(numeric)) return numeric;
  }
  if (typeof originalValue === 'boolean') {
    if (trimmed === 'true') return true;
    if (trimmed === 'false') return false;
  }
  if (typeof originalValue === 'string') return input;
  if (trimmed === '') return '';
  try {
    return JSON.parse(trimmed);
  } catch {
    return input;
  }
}
