import type { VectorEndpointConfig } from '../integration/sillytavern-bridge.js';
import { logHttpFailure, logModelFailure } from '../core/diagnostics.js';
import { normalizeApiBaseUrl } from './api-client.js';

const REQUEST_TIMEOUT_MS = 30_000;

function endpointHeaders(config: VectorEndpointConfig): Record<string, string> {
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  const key = config.apiKey.trim();
  if (key) headers.Authorization = key.startsWith('Bearer ') ? key : `Bearer ${key}`;
  return headers;
}

function endpointUrl(config: VectorEndpointConfig, path: string): string {
  const base = normalizeApiBaseUrl(config.baseUrl);
  if (!base) throw new Error('请先填写 Base URL。');
  return `${base}${path}`;
}

async function readJson(
  response: Response,
  stage: string,
  url: string,
  request?: Readonly<Record<string, unknown>>,
): Promise<Record<string, unknown>> {
  const text = await response.text();
  let payload: Record<string, unknown> = {};
  try {
    payload = text.trim() ? JSON.parse(text) as Record<string, unknown> : {};
  } catch {
    payload = { message: text.slice(0, 400) };
  }
  if (!response.ok || payload.error) {
    const error = payload.error as Record<string, unknown> | string | undefined;
    const message = typeof error === 'string'
      ? error
      : String((error as Record<string, unknown> | undefined)?.message ?? payload.message ?? `HTTP ${response.status}`);
    logHttpFailure({
      stage,
      url,
      status: response.status,
      statusText: response.statusText,
      body: text || payload,
      ...(request ? { request } : {}),
    });
    throw new Error(message);
  }
  return payload;
}

/** OpenAI 兼容 /embeddings：把一批文本转成向量（顺序与输入一致）。 */
export async function embedTexts(
  config: VectorEndpointConfig,
  texts: readonly string[],
): Promise<readonly (readonly number[])[]> {
  if (!config.model.trim()) throw new Error('请先填写向量化模型。');
  if (texts.length === 0) return [];
  const url = endpointUrl(config, '/embeddings');
  const request = { model: config.model.trim(), textCount: texts.length };
  const response = await fetch(url, {
    method: 'POST',
    headers: endpointHeaders(config),
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    body: JSON.stringify({ model: config.model.trim(), input: texts }),
  });
  const payload = await readJson(response, '向量化', url, request);
  const data = Array.isArray(payload.data) ? payload.data : [];
  const vectors = data
    .map((entry) => {
      const record = entry as Record<string, unknown> | null;
      const embedding = record?.embedding;
      return Array.isArray(embedding) ? embedding.map(Number) : null;
    })
    .filter((vector): vector is number[] => Array.isArray(vector) && vector.length > 0);
  if (vectors.length !== texts.length) {
    logModelFailure({
      stage: '向量化',
      reason: `返回数量不匹配（期望 ${texts.length}，实际 ${vectors.length}）`,
      request,
      raw: JSON.stringify(payload),
    });
    throw new Error(`向量化返回数量不匹配（期望 ${texts.length}，实际 ${vectors.length}）。`);
  }
  return vectors;
}

export interface RerankResult {
  readonly index: number;
  readonly score: number;
}

/** 解析 Jina/Cohere 风格的 /rerank 响应。 */
export function parseRerankResults(payload: Record<string, unknown>): readonly RerankResult[] {
  const list = Array.isArray(payload.results)
    ? payload.results
    : Array.isArray(payload.data)
      ? payload.data
      : [];
  return list
    .map((entry) => {
      const record = entry as Record<string, unknown> | null;
      const index = Number(record?.index);
      const score = Number(record?.relevance_score ?? record?.score ?? 0);
      return Number.isInteger(index) && index >= 0 ? { index, score } : null;
    })
    .filter((entry): entry is RerankResult => entry !== null)
    .sort((left, right) => right.score - left.score);
}

/** Jina/Cohere 兼容 /rerank：按与 query 的相关度对文档重排序。 */
export async function rerankDocuments(
  config: VectorEndpointConfig,
  query: string,
  documents: readonly string[],
  topN: number,
): Promise<readonly RerankResult[]> {
  if (!config.model.trim()) throw new Error('请先填写重排序模型。');
  if (documents.length === 0) return [];
  const url = endpointUrl(config, '/rerank');
  const response = await fetch(url, {
    method: 'POST',
    headers: endpointHeaders(config),
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
    body: JSON.stringify({
      model: config.model.trim(),
      query,
      documents,
      top_n: Math.min(topN, documents.length),
    }),
  });
  return parseRerankResults(await readJson(response, '重排序', url, {
    model: config.model.trim(),
    documentCount: documents.length,
    topN,
  }));
}

/** 余弦相似度（向量长度不一致时返回 -1）。 */
export function cosineSimilarity(left: readonly number[], right: readonly number[]): number {
  if (left.length === 0 || left.length !== right.length) return -1;
  let dot = 0;
  let normLeft = 0;
  let normRight = 0;
  for (let index = 0; index < left.length; index += 1) {
    const a = left[index]!;
    const b = right[index]!;
    dot += a * b;
    normLeft += a * a;
    normRight += b * b;
  }
  const denominator = Math.sqrt(normLeft) * Math.sqrt(normRight);
  return denominator === 0 ? -1 : dot / denominator;
}
