import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import { SELF_PROFILE_ID } from '../../domain/commands.js';
import { APP_ID_LABELS, type Conversation, type PhoneMessage } from '../../domain/model.js';
import { replaceImageMarkers } from '../../generation/image-client.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import { appendMessageBody, formatTime, latestMessagesByConversation, renderAvatar, renderMessageRollback, renderQueuedMessageDelete, renderRichContent, richContextOf, scrollToLatestMessage, selectRecentMessages } from '../shared-view.js';

export function createAnonymousApp(): PhoneAppDefinition {
  return {
    id: 'anonymous',
    label: APP_ID_LABELS.anonymous,
    icon: '匿',
    navigation: [],
    render(context) {
      if (context.selectedConversationId) {
        const conversation = context.state.conversations[context.selectedConversationId];
        if (conversation?.appId === 'anonymous') return renderAnonymousChat(context, conversation);
      }
      return renderMatchList(context);
    },
  };
}

function renderMatchList(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page' });
  const toolbar = element('div', { className: 'phone-toolbar' });
  toolbar.append(
    element('h2', { className: 'phone-section-title', text: '匿名匹配' }),
    button('开始匹配', 'phone-button phone-button-primary', async () => {
      const result = await context.showModal('开始匿名匹配', [{
        name: 'alias',
        label: '临时昵称',
        placeholder: `夜航员${String(Date.now()).slice(-3)}`,
      }]);
      if (!result) return;
      const { conversation } = await context.commands.createAnonymousMatch(result.alias);
      context.openConversation(conversation.id);
    }),
  );
  page.append(toolbar);
  const conversations = Object.values(context.state.conversations)
    .filter((conversation) => conversation.appId === 'anonymous')
    .sort((a, b) => b.updatedAt - a.updatedAt);
  if (conversations.length === 0) {
    page.append(element('div', { className: 'phone-empty', text: '匹配只使用临时身份。除非发生显式身份揭示事件，不会显示联系人真实身份。' }));
    return page;
  }
  const list = element('div', { className: 'phone-list' });
  const latestByConversation = latestMessagesByConversation(context.state);
  for (const conversation of conversations) {
    const peerId = conversation.participantIds.find((id) => id !== SELF_PROFILE_ID);
    const closed = isClosed(context, conversation.id);
    const item = button('', 'phone-list-item', () => context.openConversation(conversation.id));
    const main = element('span', { className: 'phone-list-main' });
    main.append(
      element('span', { className: 'phone-list-title', text: conversation.title }),
      element('span', {
        className: 'phone-list-preview',
        text: closed
          ? '匹配已结束'
          : replaceImageMarkers(latestByConversation.get(conversation.id)?.content ?? '可以开始聊天'),
      }),
    );
    item.append(renderAvatar(context.state.profiles[peerId ?? '']), main);
    list.append(item);
  }
  page.append(list);
  return page;
}

function renderAnonymousChat(context: PhoneViewContext, conversation: Conversation): HTMLElement {
  // 打开会话即视为已读，同步消除首页与通知中心的未读角标。
  if (conversation.unreadCount > 0) void context.commands.markConversationRead(conversation.id);
  const closed = isClosed(context, conversation.id);
  const page = element('div', { className: 'phone-chat has-header' });
  const heading = element('div', { className: 'phone-chat-heading' });
  const controls = element('div', { className: 'phone-toolbar' });
  controls.append(
    element('h2', { text: conversation.title }),
    button('解除', 'phone-button phone-button-secondary', async () => {
      await context.commands.closeAnonymousMatch(conversation.id, 'unmatch');
      context.showNotice('已解除匿名匹配', 'success');
    }),
    button('屏蔽', 'phone-button phone-button-danger', async () => {
      await context.commands.closeAnonymousMatch(conversation.id, 'block');
      context.showNotice('已屏蔽该匿名身份', 'success');
    }),
  );
  heading.append(controls, element('p', { className: 'phone-muted', text: closed ? '此会话已经结束' : '临时身份 · 不显示真实联系人映射' }));

  const messages = selectRecentMessages(context.state, conversation.id, 100);
  const list = element('div', { className: 'phone-message-list' });
  for (const message of messages) list.append(renderMessage(context, message));
  if (messages.length === 0) list.append(element('div', { className: 'phone-empty', text: '发送第一条匿名消息，稍后与其他联系人一起生成。' }));

  const composer = element('form', { className: 'phone-composer' });
  const input = element('input', {
    className: 'phone-input',
    attributes: { type: 'text', placeholder: closed ? '匹配已结束' : '发送匿名消息', maxlength: '1200', autocomplete: 'off' },
  });
  input.disabled = closed;
  const send = button('', 'phone-twitter-send-button');
  send.setAttribute('aria-label', '发送匿名消息');
  send.title = '发送';
  send.append(renderPhoneIcon('send', 'phone-svg-icon phone-twitter-send-icon'));
  send.disabled = closed;
  composer.addEventListener('submit', (event) => {
    event.preventDefault();
    void sendMessage(context, conversation.id, input, send);
  });
  send.addEventListener('click', () => void sendMessage(context, conversation.id, input, send));
  composer.append(input, send);
  page.append(heading, list, composer);
  scrollToLatestMessage(list);
  return page;
}

async function sendMessage(
  context: PhoneViewContext,
  conversationId: string,
  input: HTMLInputElement,
  send: HTMLButtonElement,
): Promise<void> {
  const content = input.value.trim();
  if (!content) return;
  input.disabled = true;
  send.disabled = true;
  try {
    await context.commands.queueMessage(conversationId, content);
    input.value = '';
    context.showNotice('匿名消息已加入本轮队列', 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  } finally {
    input.disabled = false;
    send.disabled = false;
  }
}

function isClosed(context: PhoneViewContext, conversationId: string): boolean {
  return Object.values(context.state.interactions).some(
    (interaction) => interaction.targetId === conversationId && (interaction.type === 'unmatch' || interaction.type === 'block'),
  );
}

function renderMessage(context: PhoneViewContext, message: PhoneMessage): HTMLElement {
  const outgoing = message.direction === 'outgoing';
  const row = element('div', { className: `phone-message-row ${outgoing ? 'is-outgoing' : 'is-incoming'}` });
  const control = renderQueuedMessageDelete(context, message) ?? renderMessageRollback(context, message);
  if (!outgoing) row.append(renderAvatar(context.state.profiles[message.profileId]));
  else if (control) row.append(control);
  const stack = element('div', { className: 'phone-message-stack' });
  appendMessageBody(stack, renderRichContent(message.content, richContextOf(context)));
  stack.append(
    element('span', {
      className: 'phone-message-meta',
      text: `${formatTime(message.createdAt)} · ${message.status === 'queued' ? '待生成' : '已发送'}`,
    }),
  );
  row.append(stack);
  if (!outgoing && control) row.append(control);
  return row;
}