export type ForumActivityLevel = 'quiet' | 'balanced' | 'lively' | 'bustling';

export interface ForumSettings {
  /** NPC 是否可以彼此发帖、回复和延续旧讨论。 */
  readonly autonomousMode: boolean;
  /** 控制讨论节奏与提示词中的活跃程度。 */
  readonly activityLevel: ForumActivityLevel;
  /** 每次手动刷新生成的新主题数。 */
  readonly refreshThreadCount: number;
  /** 每个新主题期望生成的 NPC 回复数。 */
  readonly repliesPerThread: number;
  /** 每次刷新最多继续讨论的旧主题数。 */
  readonly continuationThreadCount: number;
  /** NPC 回复允许的最大嵌套深度。 */
  readonly maxReplyDepth: number;
  /** 新主题正文的目标字数。 */
  readonly threadTargetLength: number;
  /** 回复正文的目标字数。 */
  readonly replyTargetLength: number;
  /** 论坛刷新专用输出 token 上限。 */
  readonly generationMaxTokens: number;
  /** 提供给刷新生成器的最近主题数量。 */
  readonly contextThreadCount: number;
  /** 用户发主题时允许保存的标签数量。 */
  readonly maxTagsPerThread: number;
}

export type ForumSettingsPatch = Partial<ForumSettings>;

export const DEFAULT_FORUM_SETTINGS: ForumSettings = Object.freeze({
  autonomousMode: true,
  activityLevel: 'balanced',
  refreshThreadCount: 3,
  repliesPerThread: 2,
  continuationThreadCount: 2,
  maxReplyDepth: 3,
  threadTargetLength: 300,
  replyTargetLength: 120,
  generationMaxTokens: 3_200,
  contextThreadCount: 12,
  maxTagsPerThread: 5,
});

export function normalizeForumSettings(
  value: unknown,
  fallback: ForumSettings = DEFAULT_FORUM_SETTINGS,
): ForumSettings {
  const source = isRecord(value) ? value : {};
  return {
    autonomousMode: source.autonomousMode !== false,
    activityLevel: normalizeActivityLevel(source.activityLevel, fallback.activityLevel),
    refreshThreadCount: clampInteger(source.refreshThreadCount, 1, 6, fallback.refreshThreadCount),
    repliesPerThread: clampInteger(source.repliesPerThread, 0, 6, fallback.repliesPerThread),
    continuationThreadCount: clampInteger(
      source.continuationThreadCount,
      0,
      8,
      fallback.continuationThreadCount,
    ),
    maxReplyDepth: clampInteger(source.maxReplyDepth, 1, 6, fallback.maxReplyDepth),
    threadTargetLength: clampInteger(source.threadTargetLength, 80, 1_200, fallback.threadTargetLength),
    replyTargetLength: clampInteger(source.replyTargetLength, 20, 1_200, fallback.replyTargetLength),
    generationMaxTokens: clampInteger(source.generationMaxTokens, 800, 8_192, fallback.generationMaxTokens),
    contextThreadCount: clampInteger(source.contextThreadCount, 0, 40, fallback.contextThreadCount),
    maxTagsPerThread: clampInteger(source.maxTagsPerThread, 1, 8, fallback.maxTagsPerThread),
  };
}

export function mergeForumSettings(
  current: ForumSettings,
  patch: ForumSettingsPatch | undefined,
): ForumSettings {
  return normalizeForumSettings(patch ? { ...current, ...patch } : current, current);
}

function normalizeActivityLevel(value: unknown, fallback: ForumActivityLevel): ForumActivityLevel {
  return value === 'quiet' || value === 'balanced' || value === 'lively' || value === 'bustling'
    ? value
    : fallback;
}

function clampInteger(value: unknown, minimum: number, maximum: number, fallback: number): number {
  const parsed = Number(value);
  if (!Number.isFinite(parsed)) return fallback;
  return Math.min(maximum, Math.max(minimum, Math.round(parsed)));
}

function isRecord(value: unknown): value is Readonly<Record<string, unknown>> {
  return Boolean(value && typeof value === 'object' && !Array.isArray(value));
}