/**
 * 生图标记语法的单一数据源。
 *
 * 内置格式：image###英文提示词###，兼容旧格式 [[生图:英文提示词]]。
 * 用户可在设置里追加一对自定义开始/结束标签，注册后所有识别入口（消息渲染、
 * 会话预览、正文清洗、提示词编译）都会同步识别，无需逐个调用点传参。
 */

const BUILTIN_MARKER_SOURCE = '(?:image###([\\s\\S]{1,2000}?)###|\\[\\[生图[:：]([\\s\\S]{1,2000}?)\\]\\])';

export interface CustomImageMarkerTags {
  readonly start: string;
  readonly end: string;
}

let customMarker: CustomImageMarkerTags | null = null;
let customPrompt = '';
/** 智绘姬模式下正文必须保留 image###...### 原文，它才会渲染自己的生图按钮。 */
let preserveMarkersInChat = false;

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** 一对标签只有都非空时才能形成可识别的包裹结构。 */
export function isUsableCustomImageMarker(start: string, end: string): boolean {
  const normalizedStart = start.trim();
  const normalizedEnd = end.trim();
  return normalizedStart.length > 0
    && normalizedEnd.length > 0
    && normalizedStart !== normalizedEnd;
}

/**
 * 同步设置到标记注册表。
 * 自定义提示词与自定义标签相互独立：只填提示词时仍按内置标记识别，
 * 只填标签时按标签识别但不追加额外指令。
 */
export function applyImageMarkerSettings(settings: {
  readonly enabled: boolean;
  readonly customPromptEnabled: boolean;
  readonly customPrompt: string;
  readonly customMarkerStart: string;
  readonly customMarkerEnd: string;
  /** 生图供应商；zhihuiji 时把标记原样留在正文里交给智绘姬。 */
  readonly provider?: string;
}): void {
  const active = settings.enabled && settings.customPromptEnabled;
  preserveMarkersInChat = settings.enabled && settings.provider === 'zhihuiji';
  customPrompt = active ? settings.customPrompt.trim() : '';
  customMarker = active && isUsableCustomImageMarker(settings.customMarkerStart, settings.customMarkerEnd)
    ? { start: settings.customMarkerStart.trim(), end: settings.customMarkerEnd.trim() }
    : null;
}

/** 注入正文时是否保留生图标记（智绘姬需要看到原始标记）。 */
export function shouldPreserveImageMarkers(): boolean {
  return preserveMarkersInChat;
}

export function getCustomImageMarker(): CustomImageMarkerTags | null {
  return customMarker;
}

export function getCustomImagePrompt(): string {
  return customPrompt;
}

/**
 * 每次调用返回新的正则实例，避免共享 lastIndex 造成跨调用状态污染。
 */
export function createImageMarkerPattern(): RegExp {
  const sources = [BUILTIN_MARKER_SOURCE];
  if (customMarker) {
    sources.push(`(?:${escapeRegExp(customMarker.start)}([\\s\\S]{1,2000}?)${escapeRegExp(customMarker.end)})`);
  }
  return new RegExp(sources.join('|'), 'gi');
}

/** 标记内的提示词可能落在任意一个分支的捕获组里。 */
function extractPrompt(match: readonly (string | undefined)[]): string {
  for (let index = 1; index < match.length; index += 1) {
    const value = match[index];
    if (typeof value === 'string') return value.trim();
  }
  return '';
}

export interface ContentSegment {
  readonly kind: 'text' | 'image';
  readonly value: string;
}

/** 把消息内容切分为文本片段与生图提示词片段。 */
export function splitContentWithImageMarkers(content: string): readonly ContentSegment[] {
  const segments: ContentSegment[] = [];
  let lastIndex = 0;
  for (const match of content.matchAll(createImageMarkerPattern())) {
    const index = match.index ?? 0;
    if (index > lastIndex) segments.push({ kind: 'text', value: content.slice(lastIndex, index) });
    const prompt = extractPrompt(match);
    if (prompt) segments.push({ kind: 'image', value: prompt });
    lastIndex = index + match[0].length;
  }
  if (lastIndex < content.length) segments.push({ kind: 'text', value: content.slice(lastIndex) });
  if (segments.length === 0) segments.push({ kind: 'text', value: content });
  return segments;
}

export function contentHasImageMarker(content: string): boolean {
  return createImageMarkerPattern().test(content);
}

/** 把生图标记替换为占位文本，用于会话预览、通知与正文注入。 */
export function replaceImageMarkers(content: string, placeholder = '[图片]'): string {
  return content.replace(createImageMarkerPattern(), placeholder);
}