import { parseSheetArchive, type SheetArchive } from '../db/sheet-archive.js';
import { phoneLogger } from '../core/logger.js';
import {
  getTavernStorageContext,
  saveTavernStorageContext,
  scopeIdFromContext,
  type TavernStorageContext,
  type TavernStorageContextProvider,
} from './tavern-storage.js';

/**
 * 数据中心表格归档的持久化通道：SillyTavern 聊天元数据。
 *
 * 为什么另开一个 key 而不塞进 `narrative_phone_state`：
 * `PhoneState` 每条消息都要 commit，`TavernStorage.#write` 里会对整个 state 做一次深拷贝。
 * 表格行是几十 KB 的冷数据，写入频率比消息低两个数量级，混进热路径只会让每条消息都变慢。
 * 两者都落在同一个聊天文件里，跨浏览器、跨设备、导出导入聊天的语义完全一致。
 */
export const TAVERN_SHEET_ARCHIVE_KEY = 'narrative_phone_sheets';

/**
 * 落盘合并窗口（毫秒）。
 * 宿主的 saveMetadata 会把整个聊天 POST 回服务端，逐行编辑时连发多次写入只应触发一次写盘。
 */
const SAVE_COALESCE_MS = 600;

interface ArchiveEnvelope {
  readonly key: typeof TAVERN_SHEET_ARCHIVE_KEY;
  readonly archive: SheetArchive;
}

function formatError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * 归档读写：内存元数据同步更新（写入立刻对本次会话生效），聊天文件落盘按窗口合并。
 * 作用域不匹配一律拒绝写入，避免把上一个聊天的表格写进刚切换过去的聊天。
 */
export class SheetArchiveStore {
  readonly #contextProvider: TavernStorageContextProvider;
  readonly #canWrite: () => boolean;
  #pendingSaveContext: TavernStorageContext | null = null;
  #saveTimer: ReturnType<typeof setTimeout> | null = null;
  #saveInFlight: Promise<void> | null = null;
  #saveFailureLogged = false;

  constructor(contextProvider: TavernStorageContextProvider = getTavernStorageContext, canWrite: () => boolean = () => true) {
    this.#contextProvider = contextProvider;
    this.#canWrite = canWrite;
  }

  isAvailable(): boolean {
    try {
      const context = this.#contextProvider();
      return Boolean(
        context.chatMetadata
        && (typeof context.saveMetadata === 'function' || typeof context.saveChat === 'function'),
      );
    } catch {
      return false;
    }
  }

  /** 读取当前聊天里属于该 scope 的归档；没有、解析不出或作用域不符时返回 null。 */
  read(scopeId: string): SheetArchive | null {
    let context: TavernStorageContext;
    try {
      context = this.#contextProvider();
    } catch {
      return null;
    }
    const raw = context.chatMetadata?.[TAVERN_SHEET_ARCHIVE_KEY];
    if (raw === undefined) return null;
    const envelope = raw as Partial<ArchiveEnvelope> & Record<string, unknown>;
    const candidate = envelope.archive ?? raw;
    const archive = parseSheetArchive(candidate);
    if (!archive) {
      phoneLogger.warn('聊天元数据里的表格归档无法解析，已忽略', { scopeId });
      return null;
    }
    return archive.scopeId === scopeId ? archive : null;
  }

  /**
   * 写入归档。元数据同步更新，落盘合并到窗口内。
   * 返回 false 表示当前聊天不接受写入（没有元数据接口，或作用域已经切换），调用方不应更新已归档指纹。
   */
  write(archive: SheetArchive): boolean {
    if (!this.#canWrite()) return false;
    let context: TavernStorageContext;
    try {
      context = this.#contextProvider();
    } catch {
      return false;
    }
    const metadata = context.chatMetadata as Record<string, unknown> | undefined;
    if (!metadata) return false;
    if (typeof context.saveMetadata !== 'function' && typeof context.saveChat !== 'function') return false;
    const activeScopeId = scopeIdFromContext(context);
    if (activeScopeId !== archive.scopeId) return false;

    metadata[TAVERN_SHEET_ARCHIVE_KEY] = {
      key: TAVERN_SHEET_ARCHIVE_KEY,
      archive,
    } satisfies ArchiveEnvelope;
    this.#deferSave(context);
    return true;
  }

  /** 清除当前聊天的归档（表格全被删除时调用，避免留下空壳继续在新设备上恢复）。 */
  clear(scopeId: string): boolean {
    if (!this.#canWrite()) return false;
    let context: TavernStorageContext;
    try {
      context = this.#contextProvider();
    } catch {
      return false;
    }
    const metadata = context.chatMetadata as Record<string, unknown> | undefined;
    if (!metadata || scopeIdFromContext(context) !== scopeId) return false;
    if (metadata[TAVERN_SHEET_ARCHIVE_KEY] === undefined) return true;
    delete metadata[TAVERN_SHEET_ARCHIVE_KEY];
    this.#deferSave(context);
    return true;
  }

  /** 等待挂起的写盘完成（切换聊天、卸载前调用）。 */
  async flush(): Promise<void> {
    if (this.#saveTimer !== null) {
      clearTimeout(this.#saveTimer);
      this.#saveTimer = null;
    }
    await this.#drainSave();
  }

  #deferSave(context: TavernStorageContext): void {
    this.#pendingSaveContext = context;
    if (this.#saveTimer !== null) return;
    this.#saveTimer = setTimeout(() => {
      this.#saveTimer = null;
      void this.#drainSave();
    }, SAVE_COALESCE_MS);
  }

  #drainSave(): Promise<void> {
    if (!this.#canWrite()) return this.#saveInFlight ?? Promise.resolve();
    const context = this.#pendingSaveContext;
    this.#pendingSaveContext = null;
    if (!context) return this.#saveInFlight ?? Promise.resolve();
    const previous = this.#saveInFlight ?? Promise.resolve();
    const save = previous.catch(() => undefined).then(() => this.#saveNow(context));
    this.#saveInFlight = save;
    void save.then(() => {
      if (this.#saveInFlight === save) this.#saveInFlight = null;
    });
    return save;
  }

  /**
   * 落盘失败不回滚内存元数据：本次会话的表格数据已经在 SQLite 里，元数据保持最新，
   * 宿主下一次保存聊天会把它带上；回滚只会让新设备恢复到更旧的状态。
   */
  async #saveNow(context: TavernStorageContext): Promise<void> {
    if (!this.#canWrite()) {
      this.#pendingSaveContext ??= context;
      return;
    }
    try {
      await saveTavernStorageContext(context);
      this.#saveFailureLogged = false;
    } catch (error) {
      if (!this.#saveFailureLogged) {
        this.#saveFailureLogged = true;
        phoneLogger.warn('保存表格归档到聊天文件失败，本地 SQLite 数据不受影响', formatError(error));
      }
    }
  }
}
