import type { PostKind } from '../domain/model.js';
import type { AdapterFieldRole, FormatAdapter } from './adapter.js';
import {
  extractJsonBody,
  parseColonFields,
  parseDslCalls,
  parsePipeFields,
  scanPhoneBlocks,
  splitSpeakerLines,
  stripNonPhoneBlocks,
} from './grammar.js';
import {
  isSelfSpeaker,
  normalizeParsedContent,
  parseInlineAttachments,
  type ParsedPhoneItem,
  type ParsedPhoneMetrics,
} from './normalize.js';

/**
 * 语义字段的内置写法表。适配器给了 `fieldAliases` 就用卡里的写法，
 * 否则回落到这里，行为与原来硬编码的字段名一致。
 */
const DEFAULT_FIELD_ALIASES: Readonly<Record<AdapterFieldRole, readonly string[]>> = {
  author: ['作者', '发布者', '用户名', '昵称', '楼主', '发送者', '博主', 'author', 'username', 'nickname'],
  account: ['账号', 'handle', '推特号', 'account'],
  title: ['标题', '题目', '帖子标题', '主题', 'title', 'subject'],
  content: ['推文', '正文', '内容', '简介', '动态', '帖子内容', '发言', 'content', 'text', 'body'],
  board: ['频道', '板块', '会话', '分区', '版块', '栏目', 'category', 'channel', 'board', 'section'],
  time: ['时间', '发布时间', '时间戳', 'timestamp', 'time', 'date'],
  tags: ['标签', '话题', 'tags', 'topics'],
  id: ['编号', '帖子id', 'id', 'postid'],
  parentId: ['回复对象', '父级', '父id', 'parentid', 'replyto', 'parent'],
  pinned: ['置顶', 'ispinned', 'pinned', 'sticky'],
  hot: ['热门', '加精', 'ishot', 'hot'],
  views: ['浏览', '浏览数', '阅读', '阅读量', 'viewcount', 'views'],
  likes: ['点赞', '喜欢', '赞', 'likecount', 'likes'],
  comments: ['评论', '评论数', '回复数', 'replycount', 'commentcount', 'comments'],
  reposts: ['转发', '转发数', '引用', 'repostcount', 'reposts', 'shares'],
  favorites: ['收藏', '收藏数', 'favoritecount', 'favorites'],
};

/** 卡里常见的「人气：1.2万浏览 · 300喜欢」这类聚合字段。 */
const POPULARITY_KEYS = ['人气', '数据', '统计', '互动'] as const;


export interface PhoneTextParseResult {
  readonly items: readonly ParsedPhoneItem[];
  readonly consumedRanges: readonly { readonly start: number; readonly end: number }[];
  readonly issues: readonly string[];
}

export function parsePhoneText(
  text: string,
  adapters: readonly FormatAdapter[],
  userNames: readonly string[] = [],
): PhoneTextParseResult {
  const items: ParsedPhoneItem[] = [];
  const issues: string[] = [];
  const consumedRanges: { start: number; end: number }[] = [];
  const blocks = scanPhoneBlocks(text, adapters);
  for (const block of blocks) {
    const parsed = parseBlock(block.adapter, block.body, block.start, userNames);
    items.push(...parsed.items);
    issues.push(...parsed.issues);
    if (parsed.items.length > 0) consumedRanges.push({ start: block.start, end: block.end });
  }
  return {
    items,
    consumedRanges,
    issues,
  };
}

export function removeConsumedRanges(
  text: string,
  ranges: readonly { readonly start: number; readonly end: number }[],
): string {
  if (ranges.length === 0) return text;
  const merged = [...ranges]
    .sort((left, right) => left.start - right.start)
    .reduce<{ start: number; end: number }[]>((result, range) => {
      const previous = result.at(-1);
      if (previous && range.start <= previous.end) previous.end = Math.max(previous.end, range.end);
      else result.push({ start: Math.max(0, range.start), end: Math.min(text.length, range.end) });
      return result;
    }, []);
  let cursor = 0;
  const parts: string[] = [];
  for (const range of merged) {
    parts.push(text.slice(cursor, range.start));
    cursor = range.end;
  }
  parts.push(text.slice(cursor));
  return stripNonPhoneBlocks(parts.join('\n')).replace(/\n{3,}/g, '\n\n').trim();
}

function parseBlock(
  adapter: FormatAdapter,
  body: string,
  offset: number,
  userNames: readonly string[],
): PhoneTextParseResult {
  if (adapter.body === 'json') return parseJsonBlock(adapter, body, offset, userNames);
  if (adapter.family === 'dsl') return parseDslBlock(adapter, body, offset, userNames);
  if (adapter.family === 'discord') return parseDiscordBlock(adapter, body, offset, userNames);
  if (adapter.family === 'bracketed') return parseBracketedBlock(adapter, body, offset, userNames);
  return parseMessageBlock(adapter, body, offset, userNames);
}

/** 语义字段查找：先用适配器声明的卡内写法，再回落到内置写法。 */
function fieldOf(
  adapter: FormatAdapter,
  fields: Readonly<Record<string, string>>,
  role: AdapterFieldRole,
): string {
  return firstField(fields, adapter.fieldAliases?.[role] ?? DEFAULT_FIELD_ALIASES[role]);
}

/** 发言人别名：把 `tuser`、`t诗诗` 这类卡内标签换回规范名，避免建出重复角色。 */
function applySpeakerAlias(adapter: FormatAdapter, speaker: string): string {
  const aliases = adapter.speakerAliases;
  if (!aliases) return speaker;
  const target = speaker.trim();
  if (aliases[target]) return aliases[target];
  const normalized = normalizeAliasKey(target);
  const matched = Object.entries(aliases).find(([key]) => normalizeAliasKey(key) === normalized);
  return matched?.[1] ?? speaker;
}

function normalizeAliasKey(value: string): string {
  return value.trim().toLocaleLowerCase('zh-CN').replace(/^[@<]+|[>]+$/g, '');
}

function parseMessageBlock(
  adapter: FormatAdapter,
  body: string,
  offset: number,
  userNames: readonly string[],
): PhoneTextParseResult {
  const lines = splitSpeakerLines(body);
  const issues: string[] = [];
  const items = lines.flatMap((line, index) => {
    const content = parseInlineAttachments(line.content);
    if (!content.content && content.attachments.length === 0) return [];
    const speaker = normalizeSpeaker(applySpeakerAlias(adapter, line.speaker));
    const item: ParsedPhoneItem = {
      appId: adapter.appId,
      itemKind: 'message',
      conversationKind: adapter.conversationKind,
      conversationKey: `${adapter.appId}:${adapter.containers[0]}`,
      speakerRole: speakerRoleOf(speaker, userNames),
      speakerName: speaker,
      content: content.content || line.content.trim(),
      ...(content.messageKind ? { messageKind: content.messageKind } : {}),
      ...(content.attachments.length > 0 ? { attachments: content.attachments } : {}),
      sourceAdapterId: adapter.id,
      sourceStart: offset + index,
      sourceEnd: offset + body.length,
    };
    return [item];
  });
  if (items.length === 0) issues.push(`${adapter.id}: 未识别到消息发言行`);
  return { items, consumedRanges: [], issues };
}

function parseBracketedBlock(
  adapter: FormatAdapter,
  body: string,
  offset: number,
  userNames: readonly string[],
): PhoneTextParseResult {
  const fields = parseColonFields(body);
  const contentKeys = adapter.fieldAliases?.content ?? DEFAULT_FIELD_ALIASES.content;
  const rawContent = fieldOf(adapter, fields, 'content') || extractAfterLabel(body, contentKeys);
  const title = fieldOf(adapter, fields, 'title');
  const defaultContainer = adapter.containers[0] ?? adapter.id;
  const explicitAuthor = fieldOf(adapter, fields, 'author') || extractAuthorBeforeField(body, contentKeys);
  const inlineAuthor = extractInlinePostAuthor(rawContent);
  const author = explicitAuthor || inlineAuthor.author || defaultContainer;
  const accountName = fieldOf(adapter, fields, 'account') || inlineAuthor.accountName;
  const content = inlineAuthor.content || rawContent;
  const board = fieldOf(adapter, fields, 'board');
  const conversationKey = board || defaultContainer;
  if (!content) return { items: [], consumedRanges: [], issues: [`${adapter.id}: 动态没有可用正文`] };
  const parsed = parseInlineAttachments(content);
  const externalId = fieldOf(adapter, fields, 'id');
  const timeLabel = fieldOf(adapter, fields, 'time');
  const tags = parseTagList(fieldOf(adapter, fields, 'tags'));
  const item: ParsedPhoneItem = {
    appId: adapter.appId,
    itemKind: 'post',
    conversationKind: adapter.conversationKind,
    conversationKey: `${adapter.appId}:${conversationKey}`,
    speakerRole: speakerRoleOf(applySpeakerAlias(adapter, author), userNames),
    speakerName: normalizeSpeaker(applySpeakerAlias(adapter, author)),
    ...(accountName ? { accountName } : {}),
    content: parsed.content || content.trim(),
    ...(title ? { title } : {}),
    ...(adapter.postKind ? { postKind: adapter.postKind } : { postKind: 'twitter-post' }),
    ...(parsed.attachments.length > 0 ? { attachments: parsed.attachments } : {}),
    ...(board ? { board } : {}),
    ...(tags.length > 0 ? { tags } : {}),
    ...(externalId ? { sourceEntityId: externalId } : {}),
    ...(timeLabel ? { timeLabel } : {}),
    ...(isTruthyFlag(fieldOf(adapter, fields, 'pinned')) ? { pinned: true } : {}),
    ...(isTruthyFlag(fieldOf(adapter, fields, 'hot')) ? { hot: true } : {}),
    metrics: parseMetrics(adapter, fields),
    sourceAdapterId: adapter.id,
    sourceStart: offset,
    sourceEnd: offset + body.length,
  };
  // 卡里的评论区常写成 `[热门评论] @昵称: 内容`，它们是对本条动态的评论而不是新动态。
  const comments = parseInlineComments(adapter, body, offset, userNames, externalId, item.conversationKey);
  return { items: [item, ...comments], consumedRanges: [], issues: [] };
}

const INLINE_COMMENT_PATTERN = /^\s*\[(?:热门评论|评论|回复|楼中楼)\]\s*(.+)$/gmu;

/** `[热门评论] @昵称: 内容` → 对当前动态的评论条目。 */
function parseInlineComments(
  adapter: FormatAdapter,
  body: string,
  offset: number,
  userNames: readonly string[],
  targetEntityId: string,
  conversationKey: string,
): readonly ParsedPhoneItem[] {
  const items: ParsedPhoneItem[] = [];
  for (const match of body.matchAll(INLINE_COMMENT_PATTERN)) {
    const line = (match[1] ?? '').trim();
    if (!line) continue;
    const separated = /^([^:：]{1,40})\s*[:：]\s*([\s\S]+)$/u.exec(line);
    const speaker = applySpeakerAlias(adapter, separated?.[1] ?? '路人');
    const content = normalizeParsedContent(separated?.[2] ?? line);
    if (!content) continue;
    items.push({
      appId: adapter.appId,
      itemKind: 'interaction',
      conversationKind: adapter.conversationKind,
      conversationKey,
      speakerRole: speakerRoleOf(speaker, userNames),
      speakerName: normalizeSpeaker(speaker),
      content,
      ...(targetEntityId ? { targetEntityId } : {}),
      sourceAdapterId: adapter.id,
      sourceStart: offset + (match.index ?? 0),
      sourceEnd: offset + (match.index ?? 0) + match[0].length,
    });
  }
  return items;
}

function parseDiscordBlock(
  adapter: FormatAdapter,
  body: string,
  offset: number,
  userNames: readonly string[],
): PhoneTextParseResult {
  const items: ParsedPhoneItem[] = [];
  const tokenPattern = /<channel\b[^>]*>([\s\S]*?)<\/channel\s*>|<(post|message)\b[^>]*>([\s\S]*?)<\/\2\s*>/gi;
  let channel = '#未命名';
  for (const match of body.matchAll(tokenPattern)) {
    if (match[1] !== undefined) {
      channel = match[1].trim() || channel;
      continue;
    }
    const itemType = match[2]?.toLocaleLowerCase('zh-CN');
    const fields = parsePipeFields(match[3] ?? '')[0]?.fields ?? {};
    const author = fields[itemType === 'post' ? '作者' : '发送者'] || fieldOf(adapter, fields, 'author') || '论坛用户';
    const content = fields[itemType === 'post' ? '简介' : '内容'] || fieldOf(adapter, fields, 'content') || '';
    if (!content.trim()) continue;
    items.push(createForumItem(
      adapter,
      channel,
      author,
      content,
      fields,
      offset + (match.index ?? 0),
      userNames,
      itemType === 'post' ? 'forum-thread' : 'forum-reply',
    ));
  }
  return { items, consumedRanges: [], issues: items.length ? [] : [`${adapter.id}: 未识别到论坛 message/post`] };
}

function createForumItem(
  adapter: FormatAdapter,
  channel: string,
  author: string,
  rawContent: string,
  fields: Readonly<Record<string, string>>,
  offset: number,
  userNames: readonly string[],
  postKind: 'forum-thread' | 'forum-reply',
): ParsedPhoneItem {
  const parsed = parseInlineAttachments(rawContent);
  const speaker = applySpeakerAlias(adapter, author);
  const title = fieldOf(adapter, fields, 'title');
  const timeLabel = fieldOf(adapter, fields, 'time');
  const externalId = fieldOf(adapter, fields, 'id');
  const parentId = fieldOf(adapter, fields, 'parentId');
  const tags = parseTagList(fieldOf(adapter, fields, 'tags'));
  const board = fieldOf(adapter, fields, 'board') || channel;
  return {
    appId: 'forum',
    itemKind: 'post',
    conversationKind: 'group',
    conversationKey: `forum:${channel}`,
    speakerRole: speakerRoleOf(speaker, userNames),
    speakerName: normalizeSpeaker(speaker),
    content: parsed.content || rawContent.trim(),
    ...(title ? { title } : {}),
    postKind,
    ...(board ? { board } : {}),
    ...(tags.length > 0 ? { tags } : {}),
    ...(externalId ? { sourceEntityId: externalId } : {}),
    ...(parentId ? { parentEntityId: parentId } : {}),
    ...(isTruthyFlag(fieldOf(adapter, fields, 'pinned')) ? { pinned: true } : {}),
    ...(isTruthyFlag(fieldOf(adapter, fields, 'hot')) ? { hot: true } : {}),
    ...(timeLabel ? { timeLabel } : {}),
    ...(parsed.attachments.length > 0 ? { attachments: parsed.attachments } : {}),
    metrics: parseMetrics(adapter, fields),
    sourceAdapterId: adapter.id,
    sourceStart: offset,
    sourceEnd: offset + rawContent.length,
  };
}

function parseDslBlock(
  adapter: FormatAdapter,
  body: string,
  offset: number,
  userNames: readonly string[],
): PhoneTextParseResult {
  const items: ParsedPhoneItem[] = [];
  const issues: string[] = [];
  for (const call of parseDslCalls(body)) {
    const args = call.args;
    if (call.name === 'QQ.Private' && args.length >= 4) {
      items.push(createDslMessage(adapter, 'direct', arg(args, 0), arg(args, 1), arg(args, 2), arg(args, 3), offset, userNames));
    } else if (call.name === 'QQ.Group' && args.length >= 4) {
      items.push(createDslMessage(adapter, 'group', arg(args, 0), arg(args, 1), arg(args, 2), arg(args, 3), offset, userNames));
    } else if (call.name === 'QQ.Post' && args.length >= 6) {
      const parsed = parseInlineAttachments(arg(args, 2));
      items.push({
        appId: 'wechat',
        itemKind: 'post',
        conversationKind: 'direct',
        conversationKey: `qq-space:${arg(args, 0)}`,
        speakerRole: speakerRoleOf(arg(args, 1), userNames),
        speakerName: normalizeSpeaker(arg(args, 1)),
        content: parsed.content || arg(args, 2),
        postKind: 'moment',
        timeLabel: arg(args, 3),
        sourceEntityId: arg(args, 0),
        ...(parsed.attachments.length > 0 ? { attachments: parsed.attachments } : {}),
        metrics: { views: parseNumber(arg(args, 4)), likes: parseNumber(arg(args, 5)) },
        sourceAdapterId: adapter.id,
        sourceStart: offset + call.start,
        sourceEnd: offset + call.end,
      });
    } else if (call.name === 'QQ.Comment' && args.length >= 3) {
      items.push({
        appId: 'wechat',
        itemKind: 'interaction',
        conversationKind: 'direct',
        conversationKey: `qq-space:${arg(args, 0)}`,
        speakerRole: speakerRoleOf(arg(args, 1), userNames),
        speakerName: normalizeSpeaker(arg(args, 1)),
        content: normalizeParsedContent(arg(args, 2)),
        targetEntityId: arg(args, 0),
        sourceAdapterId: adapter.id,
        sourceStart: offset + call.start,
        sourceEnd: offset + call.end,
      });
    }
  }
  if (items.length === 0) issues.push(`${adapter.id}: 未识别到安全的 QQ DSL 调用`);
  return { items, consumedRanges: [], issues };
}

function createDslMessage(
  adapter: FormatAdapter,
  conversationKind: 'direct' | 'group',
  conversationKey: string,
  speaker: string,
  rawContent: string,
  timeLabel: string,
  offset: number,
  userNames: readonly string[],
): ParsedPhoneItem {
  const parsed = parseInlineAttachments(rawContent);
  return {
    appId: 'wechat',
    itemKind: 'message',
    conversationKind,
    conversationKey: `qq:${conversationKind}:${conversationKey}`,
    speakerRole: speakerRoleOf(speaker, userNames),
    speakerName: normalizeSpeaker(speaker),
    content: parsed.content || rawContent,
    timeLabel,
    ...(parsed.messageKind ? { messageKind: parsed.messageKind } : {}),
    ...(parsed.attachments.length > 0 ? { attachments: parsed.attachments } : {}),
    sourceAdapterId: adapter.id,
    sourceStart: offset,
    sourceEnd: offset,
  };
}

function arg(values: readonly string[], index: number): string {
  return values[index] ?? '';
}

function speakerRoleOf(speaker: string, userNames: readonly string[]): 'self' | 'other' {
  return isSelfSpeaker(speaker, userNames) ? 'self' : 'other';
}

function normalizeSpeaker(value: string): string {
  return value.trim().replace(/^<|>$/g, '').replace(/^@+/, '@').slice(0, 80) || '未知角色';
}

function extractAfterLabel(text: string, labels: readonly string[]): string {
  for (const label of labels) {
    const match = new RegExp(`${escapeRegExp(label)}\\s*[:：]\\s*([\\s\\S]*?)(?=\\n\\s*(?:标签|人气|评论区|作者|发布者|时间)\\s*[:：]|$)`).exec(text);
    if (match?.[1]?.trim()) return match[1].trim();
  }
  return '';
}

function extractAuthorBeforeField(text: string, labels: readonly string[]): string {
  const lines = text.split('\n');
  const fieldIndex = lines.findIndex((line) => labels.some((label) => new RegExp(`^\\s*${escapeRegExp(label)}\\s*[:：]`).test(line)));
  if (fieldIndex <= 0) return '';
  for (let index = fieldIndex - 1; index >= 0; index -= 1) {
    const candidate = lines[index]?.trim() ?? '';
    if (!candidate || /^\[\/?附加内容\]$/i.test(candidate)) continue;
    if (/^[^:：]{1,30}[:：]/.test(candidate)) return '';
    return candidate.slice(0, 80);
  }
  return '';
}

function extractInlinePostAuthor(value: string): {
  readonly author: string;
  readonly accountName: string;
  readonly content: string;
} {
  const match = /^\s*@([^\s:：]+)\s*[:：]?\s*([\s\S]*)$/u.exec(value);
  if (!match?.[1]) return { author: '', accountName: '', content: value };
  const accountName = `@${match[1].replace(/^@+/, '')}`;
  return { author: accountName, accountName, content: match[2]?.trim() ?? '' };
}

/** 字段名先按原样匹配，再按「小写去分隔符」匹配，这样 `viewCount` 也能命中 `viewcount` 别名。 */
function firstField(fields: Readonly<Record<string, string>>, keys: readonly string[]): string {
  for (const key of keys) {
    const value = fields[key];
    if (value) return value;
  }
  const normalized = new Map(Object.entries(fields).map(([key, value]) => [normalizeFieldKey(key), value]));
  for (const key of keys) {
    const value = normalized.get(normalizeFieldKey(key));
    if (value) return value;
  }
  return '';
}

function normalizeFieldKey(value: string): string {
  return value.trim().toLocaleLowerCase('zh-CN').replace(/[\s_-]+/g, '');
}

/** 标签写法很杂：`#a #b`、`a、b`、`a, b`，统一切成数组。 */
function parseTagList(value: string): readonly string[] {
  if (!value.trim()) return [];
  return [...new Set(value
    .split(/[\s,，、;；|]+/u)
    .map((tag) => tag.replace(/^#+/, '').trim())
    .filter(Boolean)
    .map((tag) => `#${tag}`))].slice(0, 8);
}

const FALSE_FLAGS = new Set(['0', 'false', '否', '无', '不', 'no', 'none', '空']);

/** 置顶/加精这类布尔字段：卡里可能写 `true`、`是`、`置顶`，也可能写 `否`。 */
function isTruthyFlag(value: string | boolean | undefined): boolean {
  if (typeof value === 'boolean') return value;
  const text = String(value ?? '').trim().toLocaleLowerCase('zh-CN');
  return text.length > 0 && !FALSE_FLAGS.has(text);
}

function parseMetrics(adapter: FormatAdapter, fields: Readonly<Record<string, string>>): ParsedPhoneMetrics {
  const result: { likes?: number; comments?: number; reposts?: number; views?: number; favorites?: number } = {};
  const popularity = firstField(fields, POPULARITY_KEYS);
  const likes = parseMetric(fieldOf(adapter, fields, 'likes')) ?? parseLabeledMetric(popularity, DEFAULT_FIELD_ALIASES.likes);
  const comments = parseMetric(fieldOf(adapter, fields, 'comments')) ?? parseLabeledMetric(popularity, DEFAULT_FIELD_ALIASES.comments);
  const reposts = parseMetric(fieldOf(adapter, fields, 'reposts')) ?? parseLabeledMetric(popularity, DEFAULT_FIELD_ALIASES.reposts);
  const views = parseMetric(fieldOf(adapter, fields, 'views')) ?? parseLabeledMetric(popularity, DEFAULT_FIELD_ALIASES.views);
  const favorites = parseMetric(fieldOf(adapter, fields, 'favorites')) ?? parseLabeledMetric(popularity, DEFAULT_FIELD_ALIASES.favorites);
  if (likes !== undefined) result.likes = likes;
  if (comments !== undefined) result.comments = comments;
  if (reposts !== undefined) result.reposts = reposts;
  if (views !== undefined) result.views = views;
  if (favorites !== undefined) result.favorites = favorites;
  return result;
}

function parseLabeledMetric(value: string, labels: readonly string[]): number | undefined {
  if (!value) return undefined;
  for (const label of labels) {
    const match = new RegExp(`([\\d,.]+)\\s*${escapeRegExp(label)}`).exec(value);
    if (match?.[1]) return parseMetric(match[1]);
  }
  return undefined;
}

function parseMetric(value: string): number | undefined {
  if (!value) return undefined;
  const wan = /([\d.]+)\s*万/.exec(value);
  if (wan?.[1]) {
    const number = Number(wan[1]) * 10_000;
    return Number.isFinite(number) ? number : undefined;
  }
  const match = /[\d,.]+/.exec(value);
  if (!match) return undefined;
  const number = Number(match[0].replace(/,/g, ''));
  return Number.isFinite(number) ? number : undefined;
}

function parseNumber(value: string): number | undefined {
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** 单个 JSON 面板里最多认多少条帖子与评论，避免异常正文撑爆导入。 */
const MAX_JSON_POSTS = 40;
const MAX_JSON_COMMENTS = 60;

/**
 * 整块 JSON 的面板（卡里常见的「起止标记 + JSON」写法）。
 * 帖子与评论都按语义字段别名取值；卡内 `id` / `parentId` 直接用来搭楼层树。
 */
function parseJsonBlock(
  adapter: FormatAdapter,
  body: string,
  offset: number,
  userNames: readonly string[],
): PhoneTextParseResult {
  const payload = extractJsonBody(body);
  if (!payload || typeof payload !== 'object') {
    return { items: [], consumedRanges: [], issues: [`${adapter.id}: 容器里没有可解析的 JSON`] };
  }
  const entries = readJsonArray(payload, adapter.json?.posts ?? 'posts');
  if (entries.length === 0) {
    return { items: [], consumedRanges: [], issues: [`${adapter.id}: JSON 里没有找到帖子数组`] };
  }
  const threadKind = adapter.postKind ?? (adapter.appId === 'forum' ? 'forum-thread' : 'twitter-post');
  const replyKind = threadKind === 'forum-thread' ? 'forum-reply' : 'twitter-reply';
  const items: ParsedPhoneItem[] = [];
  const issues: string[] = [];
  for (const entry of entries.slice(0, MAX_JSON_POSTS)) {
    const record = asRecord(entry);
    if (!record) continue;
    const fields = jsonFields(record);
    const content = fieldOf(adapter, fields, 'content');
    if (!content.trim()) continue;
    const board = fieldOf(adapter, fields, 'board');
    const conversationKey = `${adapter.appId}:${board || adapter.containers[0] || adapter.id}`;
    const threadExternalId = fieldOf(adapter, fields, 'id');
    items.push(buildJsonItem(adapter, {
      fields,
      content,
      conversationKey,
      postKind: threadKind,
      userNames,
      offset,
      ...(board ? { board } : {}),
    }));
    for (const comment of orderJsonComments(
      readJsonArray(record, adapter.json?.comments ?? 'comments').slice(0, MAX_JSON_COMMENTS),
      adapter,
      threadExternalId,
    )) {
      const commentFields = jsonFields(comment);
      const commentContent = fieldOf(adapter, commentFields, 'content');
      if (!commentContent.trim()) continue;
      const parentExternalId = fieldOf(adapter, commentFields, 'parentId') || threadExternalId;
      items.push(buildJsonItem(adapter, {
        fields: commentFields,
        content: commentContent,
        conversationKey,
        postKind: replyKind,
        userNames,
        offset,
        ...(board ? { board } : {}),
        ...(parentExternalId ? { parentExternalId } : {}),
      }));
    }
  }
  if (items.length === 0) issues.push(`${adapter.id}: JSON 帖子里没有可用正文`);
  return { items, consumedRanges: [], issues };
}

interface JsonItemInput {
  readonly fields: Readonly<Record<string, string>>;
  readonly content: string;
  readonly conversationKey: string;
  readonly postKind: PostKind;
  readonly userNames: readonly string[];
  readonly offset: number;
  readonly board?: string;
  readonly parentExternalId?: string;
}

function buildJsonItem(adapter: FormatAdapter, input: JsonItemInput): ParsedPhoneItem {
  const { fields } = input;
  const parsed = parseInlineAttachments(input.content);
  const speaker = applySpeakerAlias(adapter, fieldOf(adapter, fields, 'author') || adapter.containers[0] || '路人');
  const title = fieldOf(adapter, fields, 'title');
  const externalId = fieldOf(adapter, fields, 'id');
  const timeLabel = fieldOf(adapter, fields, 'time');
  const accountName = fieldOf(adapter, fields, 'account');
  const tags = parseTagList(fieldOf(adapter, fields, 'tags'));
  return {
    appId: adapter.appId,
    itemKind: 'post',
    conversationKind: adapter.conversationKind,
    conversationKey: input.conversationKey,
    speakerRole: speakerRoleOf(speaker, input.userNames),
    speakerName: normalizeSpeaker(speaker),
    ...(accountName ? { accountName } : {}),
    content: parsed.content || input.content.trim(),
    ...(title ? { title } : {}),
    postKind: input.postKind,
    ...(input.board ? { board: input.board } : {}),
    ...(tags.length > 0 ? { tags } : {}),
    ...(externalId ? { sourceEntityId: externalId } : {}),
    ...(input.parentExternalId ? { parentEntityId: input.parentExternalId, targetEntityId: input.parentExternalId } : {}),
    ...(isTruthyFlag(fieldOf(adapter, fields, 'pinned')) ? { pinned: true } : {}),
    ...(isTruthyFlag(fieldOf(adapter, fields, 'hot')) ? { hot: true } : {}),
    ...(timeLabel ? { timeLabel } : {}),
    ...(parsed.attachments.length > 0 ? { attachments: parsed.attachments } : {}),
    metrics: parseMetrics(adapter, fields),
    sourceAdapterId: adapter.id,
    sourceStart: input.offset,
    sourceEnd: input.offset + input.content.length,
  };
}

/** 楼中楼必须先父后子导入，否则子楼找不到挂载目标；顺序异常的条目按原序补在最后。 */
function orderJsonComments(
  comments: readonly unknown[],
  adapter: FormatAdapter,
  threadExternalId: string,
): readonly Record<string, unknown>[] {
  const records = comments.flatMap((comment) => {
    const record = asRecord(comment);
    return record ? [record] : [];
  });
  const parentOf = (record: Record<string, unknown>): string => fieldOf(adapter, jsonFields(record), 'parentId');
  const idOf = (record: Record<string, unknown>): string => fieldOf(adapter, jsonFields(record), 'id');
  const ordered: Record<string, unknown>[] = [];
  const emitted = new Set<string>([threadExternalId].filter(Boolean));
  const pending = [...records];
  let progressed = true;
  while (pending.length > 0 && progressed) {
    progressed = false;
    for (let index = pending.length - 1; index >= 0; index -= 1) {
      const record = pending[index];
      if (!record) continue;
      const parent = parentOf(record);
      if (parent && !emitted.has(parent)) continue;
      ordered.push(record);
      const id = idOf(record);
      if (id) emitted.add(id);
      pending.splice(index, 1);
      progressed = true;
    }
  }
  return [...ordered, ...pending];
}

function readJsonArray(source: unknown, path: string): readonly unknown[] {
  if (Array.isArray(source)) return source;
  let cursor: unknown = source;
  for (const key of path.split('.')) {
    const record = asRecord(cursor);
    if (!record) return [];
    cursor = record[key];
  }
  return Array.isArray(cursor) ? cursor : [];
}

/** JSON 对象拍平成字段表，让文本与 JSON 两条路径共用同一套别名查找。 */
function jsonFields(record: Record<string, unknown>): Readonly<Record<string, string>> {
  const fields: Record<string, string> = {};
  for (const [key, value] of Object.entries(record)) {
    if (value === null || value === undefined) continue;
    if (Array.isArray(value)) {
      const flat = value.filter((item) => typeof item === 'string' || typeof item === 'number').join(' ');
      if (flat) fields[key] = flat;
      continue;
    }
    if (typeof value === 'object') continue;
    fields[key] = String(value);
  }
  return fields;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
}