import { evaluateConditionGate } from '../conditions/generation.js';
import type {
  ExtensionModuleFloorContext,
  ExtensionModuleFloorTrigger,
} from './module-contract.js';
interface FloorTriggerRegistration {
  readonly moduleId: string;
  readonly options: Required<Omit<ExtensionModuleFloorTrigger, 'runOnRegister' | 'condition'>>;
  readonly listener: (context: ExtensionModuleFloorContext) => void | Promise<void>;
  readonly condition?: import('../conditions/types.js').ConditionSource;
  lastObservedFloor: number;
  matchingFloorCount: number;
  lastTriggeredFloor: number;
}

export class ExtensionModuleFloorTriggers {
  readonly #registrations = new Set<FloorTriggerRegistration>();
  readonly #conditionContextProvider: (() => import('../conditions/generation.js').GenerationConditionContext | null) | null;

  constructor(conditionContextProvider?: () => import('../conditions/generation.js').GenerationConditionContext | null) {
    this.#conditionContextProvider = conditionContextProvider ?? null;
  }

  register(
    moduleId: string,
    options: ExtensionModuleFloorTrigger,
    listener: (context: ExtensionModuleFloorContext) => void | Promise<void>,
    current?: ExtensionModuleFloorContext | null,
  ): () => void {
    if (typeof listener !== 'function') throw new Error('楼层触发器必须提供回调函数。');
    const registration: FloorTriggerRegistration = {
      moduleId,
      options: normalizeOptions(options),
      listener,
      ...(options.condition !== undefined ? { condition: options.condition } : {}),
      lastObservedFloor: -1,
      matchingFloorCount: 0,
      lastTriggeredFloor: -1,
    };
    this.#registrations.add(registration);
    if (options.runOnRegister && current) void this.#invokeIfDue(registration, current);
    return () => this.#registrations.delete(registration);
  }

  emit(context: ExtensionModuleFloorContext): void {
    for (const registration of this.#registrations) void this.#invokeIfDue(registration, context);
  }

  clearModule(moduleId: string): void {
    for (const registration of this.#registrations) {
      if (registration.moduleId === moduleId) this.#registrations.delete(registration);
    }
  }

  clear(): void {
    this.#registrations.clear();
  }

  async #invokeIfDue(registration: FloorTriggerRegistration, context: ExtensionModuleFloorContext): Promise<void> {
    const { afterFloor, every, role } = registration.options;
    if (context.floor <= registration.lastObservedFloor || context.floor < afterFloor) return;
    registration.lastObservedFloor = context.floor;
    if (registration.condition !== undefined) {
      const conditionContext = this.#conditionContextProvider?.();
      if (!conditionContext || !evaluateConditionGate(registration.condition, conditionContext)) return;
    }
    if (role !== 'any' && context.role !== role) return;
    registration.matchingFloorCount += 1;
    if (registration.matchingFloorCount % every !== 0) return;
    if (context.floor <= registration.lastTriggeredFloor) return;
    registration.lastTriggeredFloor = context.floor;
    try {
      await registration.listener(context);
    } catch (error) {
      console.warn(`[墨韵手机] 模块 ${registration.moduleId} 楼层触发器执行失败`, error);
    }
  }
}

function normalizeOptions(
  options: ExtensionModuleFloorTrigger,
): Required<Omit<ExtensionModuleFloorTrigger, 'runOnRegister' | 'condition'>> {
  const afterFloor = Number.isFinite(options.afterFloor) ? Math.max(0, Math.floor(options.afterFloor ?? 0)) : 0;
  const every = Number.isFinite(options.every) ? Math.min(1000, Math.max(1, Math.floor(options.every ?? 1))) : 1;
  const role = options.role === 'user' || options.role === 'any' ? options.role : 'assistant';
  return { afterFloor, every, role };
}