import { evaluateConditionBoolean } from './evaluator.js';
import type {
  ConditionEvaluation,
  ConditionRule,
  ConditionSnapshot,
  ConditionSource,
  ConditionValue,
} from './types.js';

export interface ConditionalPromptSection {
  readonly id: string;
  readonly text: string;
  readonly condition: ConditionSource;
  readonly onError?: 'deny' | 'allow';
}

export interface ConditionalActionRule {
  readonly actionType: string;
  readonly condition: ConditionSource;
  readonly onError?: 'deny' | 'allow';
}

export interface ConditionalAppGate {
  readonly appId: string;
  readonly condition: ConditionSource;
  readonly onError?: 'deny' | 'allow';
}

export interface ConditionGate {
  readonly condition: ConditionSource;
  readonly onError?: 'deny' | 'allow';
}

export interface GenerationConditionContext {
  readonly snapshot: ConditionSnapshot;
  readonly promptSections?: readonly ConditionalPromptSection[];
  readonly actionRules?: readonly ConditionalActionRule[];
  readonly appGates?: readonly ConditionalAppGate[];
  readonly injectionGate?: ConditionGate;
}

export interface ConditionalPromptResult {
  readonly included: readonly ConditionalPromptSection[];
  readonly excluded: readonly string[];
  readonly errors: readonly ConditionEvaluation[];
}

export function evaluateConditionGate(
  rule: ConditionSource | ConditionRule | ConditionGate,
  context: GenerationConditionContext | ConditionSnapshot,
): boolean {
  const normalized = normalizeRule(rule);
  const result = evaluateConditionBoolean(normalized.condition, getSnapshot(context));
  return result.ok ? result.value === true : normalized.onError === 'allow';
}

export function evaluateInjectionGate(
  context: GenerationConditionContext | ConditionSnapshot,
  gate?: ConditionSource | ConditionGate,
): boolean {
  if (!gate) return true;
  return evaluateConditionGate(gate, context);
}

export function evaluatePromptSections(context: GenerationConditionContext): ConditionalPromptResult {
  const included: ConditionalPromptSection[] = [];
  const excluded: string[] = [];
  const errors: ConditionEvaluation[] = [];
  for (const section of context.promptSections ?? []) {
    const result = evaluateConditionBoolean(section.condition, context.snapshot);
    if (!result.ok) {
      errors.push(result);
      if (section.onError === 'allow') included.push(section);
      else excluded.push(section.id);
      continue;
    }
    if (result.value === true) included.push(section);
    else excluded.push(section.id);
  }
  return { included, excluded, errors };
}

export function isActionAllowed(
  actionType: string,
  context: GenerationConditionContext,
): boolean {
  const rules = context.actionRules?.filter((rule) => rule.actionType === '*' || rule.actionType === actionType) ?? [];
  return rules.every((rule) => evaluateConditionGate(rule, context));
}

export function isAppAllowed(appId: string, context: GenerationConditionContext): boolean {
  const rules = context.appGates?.filter((rule) => rule.appId === '*' || rule.appId === appId) ?? [];
  return rules.every((rule) => evaluateConditionGate(rule, context));
}

export function conditionData(context: GenerationConditionContext): ConditionValue {
  return context.snapshot.data;
}

function normalizeRule(rule: ConditionSource | ConditionRule | ConditionGate): ConditionRule {
  if (typeof rule === 'string' || isConditionNodeLike(rule)) return { id: 'anonymous', condition: rule };
  return { id: 'anonymous', condition: rule.condition, onError: rule.onError };
}

function getSnapshot(context: GenerationConditionContext | ConditionSnapshot): ConditionSnapshot {
  return 'snapshot' in context ? context.snapshot : context;
}

function isConditionNodeLike(value: unknown): value is Exclude<ConditionSource, string> {
  return typeof value === 'object' && value !== null && 'kind' in value;
}