/**
 * 视口舞台守卫。
 *
 * 手机浮层的几何全部挂在舞台元素（`#narrative-phone-host`）上，机身只在舞台内部做绝对定位。
 * 但宿主页面可以把 `position: fixed` 的包含块从视口劫持走：
 * - SillyTavern 的 `style.css` 给 `<html>` 加了 `-webkit-transform: translateZ(0)` 与 `-webkit-perspective`；
 * - `browser-fixes.js` 在移动端每次 `resize` / `orientationchange` 都会把 `<html>` 临时设为 `position: fixed`，
 *   使其收缩成 fit-content。
 *
 * 包含块一旦收缩，靠 inset 撑开尺寸的浮层就会算出 0 尺寸：DOM 里挂着、点击也生效，但什么都看不见。
 * CSS 侧已改成只用视口单位定尺寸，这里再加一层运行时校正——
 * 只有实测几何偏离视口时才用行内样式钉回去，健康状态下保持 CSS 方案生效。
 */

export interface ViewportStageOptions {
  /** 需要与视口保持一致的舞台元素。 */
  readonly stage: HTMLElement;
  /** 容差像素：视口单位与实际视口之间的舍入差异不必纠正。 */
  readonly tolerancePx?: number;
  /** 视口变化后的校正延迟：宿主可能在同一帧临时改动 `<html>`，等它恢复再测量。 */
  readonly settleDelayMs?: number;
  /** 校正生效时的回调，便于上层记录宿主兼容问题。 */
  readonly onCorrected?: (detail: ViewportStageDrift) => void;
}

export interface ViewportStageDrift {
  readonly left: number;
  readonly top: number;
  readonly width: number;
  readonly height: number;
  readonly viewportWidth: number;
  readonly viewportHeight: number;
}

const DEFAULT_TOLERANCE_PX = 2;
const DEFAULT_SETTLE_DELAY_MS = 200;

/** 持续校正舞台几何，直到调用返回的清理函数。 */
export function keepStageAlignedToViewport(options: ViewportStageOptions): () => void {
  const { stage } = options;
  const tolerance = options.tolerancePx ?? DEFAULT_TOLERANCE_PX;
  const settleDelay = options.settleDelayMs ?? DEFAULT_SETTLE_DELAY_MS;

  const clearOverrides = (): void => {
    stage.style.removeProperty('left');
    stage.style.removeProperty('top');
    stage.style.removeProperty('width');
    stage.style.removeProperty('height');
  };

  const align = (): void => {
    clearOverrides();
    const rect = stage.getBoundingClientRect();
    const drift: ViewportStageDrift = {
      left: rect.left,
      top: rect.top,
      width: rect.width,
      height: rect.height,
      viewportWidth: window.innerWidth,
      viewportHeight: window.innerHeight,
    };
    const aligned = Math.abs(drift.left) <= tolerance
      && Math.abs(drift.top) <= tolerance
      && Math.abs(drift.width - drift.viewportWidth) <= tolerance
      && Math.abs(drift.height - drift.viewportHeight) <= tolerance;
    if (aligned) return;

    stage.style.left = '0px';
    stage.style.top = '0px';
    stage.style.width = `${drift.viewportWidth}px`;
    stage.style.height = `${drift.viewportHeight}px`;
    // 归零后的 rect 偏移就是包含块原点相对视口的位移，取反即可抵消。
    const pinned = stage.getBoundingClientRect();
    if (Math.abs(pinned.left) > tolerance) stage.style.left = `${-Math.round(pinned.left)}px`;
    if (Math.abs(pinned.top) > tolerance) stage.style.top = `${-Math.round(pinned.top)}px`;
    options.onCorrected?.(drift);
  };

  let settleTimer = 0;
  const scheduleAlign = (): void => {
    window.clearTimeout(settleTimer);
    settleTimer = window.setTimeout(align, settleDelay);
  };

  align();
  window.requestAnimationFrame(align);
  window.addEventListener('resize', scheduleAlign);
  window.addEventListener('orientationchange', scheduleAlign);
  window.visualViewport?.addEventListener('resize', scheduleAlign);

  return () => {
    window.clearTimeout(settleTimer);
    window.removeEventListener('resize', scheduleAlign);
    window.removeEventListener('orientationchange', scheduleAlign);
    window.visualViewport?.removeEventListener('resize', scheduleAlign);
    clearOverrides();
  };
}