import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import { renderFanficCharacters } from './characters-view.js';
import { renderFanficNarrative } from './narrative-view.js';
import { renderFanficSettings } from './settings-view.js';
import { renderFanficSources } from './sources-view.js';

type FanficTab = 'sources' | 'characters' | 'story' | 'settings';

const TABS: readonly (readonly [FanficTab, string])[] = [
  ['sources', '来源'],
  ['characters', '人物'],
  ['story', '剧情'],
  ['settings', '设置'],
];

let activeTab: FanficTab = 'sources';

/**
 * 同人剧情：把角色卡与原著资料整理成人物锁，跟踪本作已发生的事实，
 * 让正文与手机共用同一份约束——剧情可以改命运，人物不能被写崩。
 */
export function createFanficApp(): PhoneAppDefinition {
  return {
    id: 'fanfic',
    label: '同人剧情',
    icon: '同',
    navigation: [],
    render(context) {
      const page = element('div', { className: 'phone-page phone-fanfic' });
      page.append(element('h2', { className: 'phone-section-title', text: context.appTitle('同人剧情') }));
      if (!context.fanfic.settings.enabled) {
        page.append(renderIntro(context));
        return page;
      }
      page.append(renderTabs(context), renderActiveTab(context));
      return page;
    },
  };
}

function renderIntro(context: PhoneViewContext): HTMLElement {
  const intro = element('div', { className: 'phone-feature-intro' });
  intro.append(
    renderPhoneIcon('worldBook'),
    element('strong', { text: '启用同人剧情模式' }),
    element('p', {
      text: '启用后，插件会把当前角色卡、世界书与你导入的原著资料整理成「人物锁」：核心人格、价值观底线、认知边界与说话方式。'
        + '同时跟踪本作已经发生的事实（场景、人物状态、关系变化、秘密、约定、与原著的分歧），正文与手机共用同一份上下文。',
    }),
    element('p', {
      className: 'phone-feature-intro-note',
      text: '冲突策略：本作剧情与关系可以自由发展并覆盖原著同位事件；人物核心人格与语感保持原著一致，偏离必须在剧情里有可指认的原因。'
        + '角色只知道自己该知道的事，秘密按知情名单过滤。',
    }),
    element('p', {
      className: 'phone-feature-intro-note',
      text: '解析原著与跟踪状态会调用 API：可使用同人专用配置，未配置时复用记忆库的「记忆整理 API」。全部动作由你手动触发或按设定频率执行。',
    }),
  );
  const actions = element('div', { className: 'phone-feature-settings-actions' });
  const enable = button('启用同人剧情', 'phone-button phone-button-primary', async () => {
    enable.disabled = true;
    try {
      await context.fanfic.updateSettings({ enabled: true });
      activeTab = 'sources';
      context.navigate('fanfic');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      enable.disabled = false;
    }
  });
  actions.append(enable);
  intro.append(actions);
  return intro;
}

function renderTabs(context: PhoneViewContext): HTMLElement {
  const row = element('div', { className: 'phone-fanfic-tabs', attributes: { role: 'tablist' } });
  for (const [tab, label] of TABS) {
    const chip = button(label, 'phone-memory-filter-chip', () => {
      activeTab = tab;
      context.navigate('fanfic');
    });
    chip.classList.toggle('is-active', activeTab === tab);
    chip.setAttribute('role', 'tab');
    chip.setAttribute('aria-selected', String(activeTab === tab));
    row.append(chip);
  }
  const disable = button('停用', 'phone-button phone-button-danger-ghost phone-button-compact', async () => {
    const approved = await context.showConfirm({
      title: '停用同人剧情模式？',
      message: '停用后不再注入人物锁与剧情状态，也不会再调用 API；已建立的原著库与状态会保留。',
      confirmLabel: '停用',
    });
    if (!approved) return;
    await context.fanfic.updateSettings({ enabled: false });
    context.navigate('fanfic');
  });
  disable.title = '停用后保留已有数据';
  row.append(disable);
  return row;
}

function renderActiveTab(context: PhoneViewContext): HTMLElement {
  if (activeTab === 'characters') return renderFanficCharacters(context);
  if (activeTab === 'story') return renderFanficNarrative(context);
  if (activeTab === 'settings') return renderFanficSettings(context);
  return renderFanficSources(context);
}