export const AUTO_PARSE_PROTOCOL_VERSION = 1;
export const AUTO_PARSE_MAX_ACTIONS = 80;
export const AUTO_PARSE_MAX_EXTENSION_ACTIONS = 80;
export const AUTO_PARSE_RECENT_CONTENT_LIMIT = 40;
export const AUTO_PARSE_MAX_NAME_LENGTH = 80;
export const AUTO_PARSE_MAX_CONTENT_LENGTH = 1_200;

export const AUTO_PARSE_ACTION_KINDS = [
  'wechat.message',
  'wechat.moment',
  'twitter.message',
  'twitter.post',
  'forum.thread',
  'anonymous.message',
] as const;

export type AutoParseActionKind = typeof AUTO_PARSE_ACTION_KINDS[number];

export const AUTO_PARSE_RESPONSE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['version', 'actions'],
  properties: {
    version: { const: AUTO_PARSE_PROTOCOL_VERSION },
    actions: {
      type: 'array',
      maxItems: AUTO_PARSE_MAX_ACTIONS,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['kind', 'actorName', 'content'],
        properties: {
          kind: { enum: AUTO_PARSE_ACTION_KINDS },
          actorName: { type: 'string', minLength: 1, maxLength: 80 },
          accountName: { type: 'string', minLength: 1, maxLength: 80 },
          boundCharacter: { type: 'string', minLength: 1, maxLength: 80 },
          recipient: {
            type: 'string',
            minLength: 1,
            maxLength: AUTO_PARSE_MAX_NAME_LENGTH,
            description: '私信收信人；发给用户本人时填写 user，公开内容省略。',
          },
          content: { type: 'string', minLength: 1, maxLength: AUTO_PARSE_MAX_CONTENT_LENGTH },
        },
      },
    },
    extensionActions: {
      type: 'array',
      maxItems: AUTO_PARSE_MAX_EXTENSION_ACTIONS,
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['moduleId', 'data'],
        properties: {
          moduleId: { type: 'string', minLength: 2, maxLength: 64 },
          data: {
            description: '必须符合对应启用模块 autoParse.schema 的值。',
          },
        },
      },
    },
  },
} as const;

export function buildAutoParseResponseSchema(
  extensionSchemas: readonly {
    readonly moduleId: string;
    readonly schema: Readonly<Record<string, unknown>>;
  }[] = [],
): Readonly<Record<string, unknown>> {
  if (extensionSchemas.length === 0) return structuredClone(AUTO_PARSE_RESPONSE_SCHEMA);
  const extensionActions = {
    type: 'array',
    maxItems: AUTO_PARSE_MAX_EXTENSION_ACTIONS,
    items: {
      oneOf: extensionSchemas.map(({ moduleId, schema }) => ({
        type: 'object',
        additionalProperties: false,
        required: ['moduleId', 'data'],
        properties: {
          moduleId: { const: moduleId },
          data: structuredClone(schema),
        },
      })),
    },
  };
  return {
    ...structuredClone(AUTO_PARSE_RESPONSE_SCHEMA),
    properties: {
      ...structuredClone(AUTO_PARSE_RESPONSE_SCHEMA.properties),
      extensionActions,
    },
  };
}