import type { DbParams, DbStatement } from './protocol.js';

const MAX_SQL_LENGTH = 16_384;
const MAX_BATCH_SIZE = 32;
const USER_TABLE_PATTERN = /^acu_u_[a-z][a-z0-9_]{0,47}$/;
const IDENTIFIER_SHAPE = /^[A-Za-z_][A-Za-z0-9_]*$/;
/** 掩码填充字符：非单词字符，不会拼出关键字，也不含 `;`、`-` 等被检查的符号。 */
const MASK_CHAR = '#';

export interface SqlGuardTable {
  readonly physicalName: string;
}

export interface SqlGuardOptions {
  readonly maxSqlLength?: number;
  readonly maxBatchSize?: number;
}

export class SqlGuardError extends Error {
  readonly reason:
    | 'empty'
    | 'too-large'
    | 'comments'
    | 'multiple-statements'
    | 'operation'
    | 'table'
    | 'dangerous';

  constructor(reason: SqlGuardError['reason'], message: string) {
    super(message);
    this.name = 'SqlGuardError';
    this.reason = reason;
  }
}

/** 单条语句被拒的原因；批量分拣时上报给调用方，便于告知用户"哪几条没写进去"。 */
export interface SqlBatchRejection {
  readonly sql: string;
  readonly reason: SqlGuardError['reason'];
  readonly message: string;
}

export interface SqlBatchPartition {
  readonly accepted: readonly DbStatement[];
  readonly rejected: readonly SqlBatchRejection[];
}

interface MaskResult {
  readonly masked: string;
  /** 存在未闭合的引号或方括号：这种 SQL 本身就不合法，且会让掩码吞掉后面的真实分号。 */
  readonly unterminated: boolean;
}

function maskLiterals(sql: string): MaskResult {
  const out: string[] = [];
  let unterminated = false;
  for (let index = 0; index < sql.length; index += 1) {
    const char = sql[index] ?? '';
    if (char === '\'') {
      out.push(char);
      index += 1;
      while (index < sql.length) {
        if (sql[index] === '\'' && sql[index + 1] === '\'') {
          out.push(MASK_CHAR, MASK_CHAR);
          index += 2;
          continue;
        }
        if (sql[index] === '\'') break;
        out.push(MASK_CHAR);
        index += 1;
      }
      if (index < sql.length) out.push('\'');
      else unterminated = true;
      continue;
    }
    if (char === '"' || char === '`' || char === '[') {
      const closer = char === '[' ? ']' : char;
      const end = sql.indexOf(closer, index + 1);
      if (end < 0) {
        out.push(char, MASK_CHAR.repeat(sql.length - index - 1));
        unterminated = true;
        break;
      }
      const inner = sql.slice(index + 1, end);
      // 形状合法就按标识符处理：引号换成空格，内容原样保留，供表名匹配识别。
      out.push(' ', IDENTIFIER_SHAPE.test(inner) ? inner : MASK_CHAR.repeat(inner.length), ' ');
      index = end;
      continue;
    }
    out.push(char);
  }
  return { masked: out.join(''), unterminated };
}

/**
 * 掩掉字符串字面量后返回等长文本，供后续检查使用（执行仍用原始 SQL）。
 *
 * 必须先掩码再检查：填表模型写的是内联字面量，正文里出现 `;`、`--` 或 `WITH`/`DROP`
 * 这类词时，直接在原文上做检查会把一条完全正常的 INSERT 判成攻击。
 * 掩码同时把带引号的标识符（`"acu_u_x"`、`` `acu_u_x` ``、`[acu_u_x]`）的引号换成空格，
 * 否则模型给表名加引号就会被判成"没有引用任何已注册表"。
 * 等长是刻意的：掩码串的下标与原文一一对应，可以用它的判定结果去切原文。
 */
export function maskSqlLiterals(sql: string): string {
  return maskLiterals(sql).masked;
}

function identifiersAfter(sql: string, keyword: string): readonly string[] {
  const values: string[] = [];
  const pattern = new RegExp(`\\b${keyword}\\s+(?:IF\\s+NOT\\s+EXISTS\\s+)?([A-Za-z_][A-Za-z0-9_]*)`, 'gi');
  for (const match of sql.matchAll(pattern)) {
    const identifier = match[1];
    // UPSERT 的 DO UPDATE SET 是同一个 INSERT 的冲突分支，SET 不是第二张表。
    if (keyword === 'UPDATE' && identifier?.toUpperCase() === 'SET' && /\bDO\s*$/i.test(sql.slice(0, match.index))) continue;
    if (identifier) values.push(identifier);
  }
  return values;
}

function referencedTables(sql: string): readonly string[] {
  return [
    ...identifiersAfter(sql, 'FROM'),
    ...identifiersAfter(sql, 'JOIN'),
    ...identifiersAfter(sql, 'UPDATE'),
    ...identifiersAfter(sql, 'INTO'),
  ];
}

/** 检查用的掩码文本与执行用的原始文本；两者下标对齐，尾随分号在同一位置切掉。 */
function prepareStatement(sql: string, options: SqlGuardOptions): { readonly body: string; readonly masked: string } {
  const normalized = sql.trim();
  if (!normalized) throw new SqlGuardError('empty', 'SQL 不能为空');
  if (normalized.length > (options.maxSqlLength ?? MAX_SQL_LENGTH)) throw new SqlGuardError('too-large', 'SQL 超过长度限制');
  if (normalized.includes('\0')) throw new SqlGuardError('dangerous', 'SQL 包含 NUL 字符');
  const { masked, unterminated } = maskLiterals(normalized);
  // 未闭合的引号既是语法错误，也会让掩码把后面真实的分号一并吞掉，必须直接拒绝。
  if (unterminated) throw new SqlGuardError('dangerous', 'SQL 含未闭合的引号或方括号');
  const maskWithoutTail = masked.replace(/\s+$/, '');
  const cut = maskWithoutTail.endsWith(';') ? maskWithoutTail.length - 1 : maskWithoutTail.length;
  return { body: normalized.slice(0, cut).trim(), masked: masked.slice(0, cut) };
}

function assertSafeSql(sql: string, options: SqlGuardOptions): { readonly body: string; readonly masked: string } {
  const { body, masked } = prepareStatement(sql, options);
  if (!body) throw new SqlGuardError('empty', 'SQL 不能为空');
  if (/--|\/\*|\*\//.test(masked)) throw new SqlGuardError('comments', 'SQL 不允许注释，避免绕过审查');
  if (masked.includes(';')) throw new SqlGuardError('multiple-statements', 'SQL 只允许单条语句');
  if (/\b(?:ATTACH|DETACH|PRAGMA|VACUUM|REINDEX|EXPLAIN|CREATE|ALTER|DROP|TRIGGER|VIEW|WITH|BEGIN|COMMIT|ROLLBACK|SAVEPOINT|RELEASE)\b/i.test(masked)) {
    throw new SqlGuardError('dangerous', 'SQL 包含不允许的数据库控制操作');
  }
  if (/\b(?:load_extension|readfile|writefile|fts5_source_id)\s*\(/i.test(masked)) {
    throw new SqlGuardError('dangerous', 'SQL 包含不允许的扩展或文件访问函数');
  }
  if (/^(?:UPDATE|DELETE)\b/i.test(masked) && !/\bWHERE\b/i.test(masked)) {
    throw new SqlGuardError('dangerous', 'UPDATE 和 DELETE 必须包含 WHERE 条件');
  }
  if (!/^(SELECT|INSERT|UPDATE|DELETE)\b/i.test(masked)) throw new SqlGuardError('operation', '只允许 SELECT、INSERT、UPDATE、DELETE');
  return { body, masked };
}

export function validateUserSql(
  statement: DbStatement,
  tables: readonly SqlGuardTable[],
  options: SqlGuardOptions = {},
): DbStatement {
  const { body, masked } = assertSafeSql(statement.sql, options);
  const registered = new Set(tables.map((table) => table.physicalName));
  if (registered.size === 0) throw new SqlGuardError('table', '没有已注册的用户表可以访问');
  const tablesInSql = referencedTables(masked);
  if (tablesInSql.length === 0 || tablesInSql.some((table) => !USER_TABLE_PATTERN.test(table) || !registered.has(table))) {
    throw new SqlGuardError('table', 'SQL 只能访问已注册的 acu_u_ 用户表');
  }
  return { sql: body, ...(statement.params === undefined ? {} : { params: statement.params }) };
}

function assertBatchShape(statements: readonly DbStatement[], options: SqlGuardOptions): void {
  const maxBatchSize = options.maxBatchSize ?? MAX_BATCH_SIZE;
  if (statements.length === 0) throw new SqlGuardError('empty', 'SQL 批次不能为空');
  if (statements.length > maxBatchSize) throw new SqlGuardError('too-large', `SQL 批次最多 ${maxBatchSize} 条`);
}

/** 严格批次：任一条不合法整批拒绝。控制台与需要"全成功或全不做"的调用方用它。 */
export function validateUserSqlBatch(
  statements: readonly DbStatement[],
  tables: readonly SqlGuardTable[],
  options: SqlGuardOptions = {},
): readonly DbStatement[] {
  assertBatchShape(statements, options);
  return statements.map((statement) => validateUserSql(statement, tables, options));
}

/**
 * 宽容批次：逐条过闸，不合法的单条跳过并记下原因。
 *
 * 自动记录走这条路径：模型一次产出十几条语句，其中一条踩到闸门就整批丢弃时，
 * 游标不前进 + 冷却重试会让同一批楼层反复重问模型，既丢数据又烧额度。
 */
export function partitionUserSqlBatch(
  statements: readonly DbStatement[],
  tables: readonly SqlGuardTable[],
  options: SqlGuardOptions = {},
): SqlBatchPartition {
  assertBatchShape(statements, options);
  const accepted: DbStatement[] = [];
  const rejected: SqlBatchRejection[] = [];
  for (const statement of statements) {
    try {
      accepted.push(validateUserSql(statement, tables, options));
    } catch (error) {
      if (!(error instanceof SqlGuardError)) throw error;
      rejected.push({ sql: statement.sql, reason: error.reason, message: error.message });
    }
  }
  return { accepted, rejected };
}

export function encodeAuditParams(params: DbParams | undefined): string {
  return JSON.stringify(params ?? null, (_key, value: unknown) => {
    if (value instanceof Uint8Array || value instanceof Int8Array) return Array.from(value);
    if (value instanceof ArrayBuffer) return Array.from(new Uint8Array(value));
    if (typeof value === 'bigint') return `${value}n`;
    return value;
  });
}

export function assertExpectedRevision(actual: number, expected: number | undefined): void {
  if (expected !== undefined && actual !== expected) {
    throw new Error(`数据库修订冲突：expected=${expected}, actual=${actual}`);
  }
}
