import { phoneLogger } from '../core/logger.js';
import { generateWithApiProxy } from '../generation/api-client.js';
import { CancellableRun, isCancelledError } from '../generation/cancellable-run.js';
import type {
  CharacterCardSnapshot,
  FanficSettings,
  OpenAiCompatibleApiConfig,
} from '../integration/sillytavern-bridge.js';
import {
  clearCanonImports,
  clearCanonLibrary,
  listCanonImports,
  loadCanonLibrary,
  removeCanonImport,
  saveCanonImport,
  saveCanonLibrary,
  type CanonImportDocument,
} from '../storage/canon-library-storage.js';
import {
  buildCanonExtractionPrompt,
  fallbackCharacterLock,
  parseCanonExtraction,
  type CanonExtraction,
} from './canon-extractor.js';
import {
  batchChunks,
  canonLibraryStats,
  createEmptyCanonLibrary,
  mergeCanonExtractions,
  pendingChunks,
} from './canon-merge.js';
import { mergeCharacterLocks } from './identity.js';
import type { CanonChunk, CanonLibrary, CharacterLock } from './model.js';
import { normalizeCanonSources, type CanonRawDocument } from './source-normalizer.js';
import { structuredTemperature, structuredTokenBudget } from './structured-request.js';

export interface CanonPipelineDeps {
  readonly scopeId: () => string;
  readonly settings: () => {
    readonly fanfic: FanficSettings;
    /** 同人专用 API 未配置模型时回退使用的配置（记忆整理 API）。 */
    readonly fallbackApi: OpenAiCompatibleApiConfig;
  };
  readonly cardSnapshot: () => CharacterCardSnapshot;
  readonly worldBookEntries: () => readonly { readonly name: string; readonly content: string }[];
  readonly reportTask?: (message: string | null) => void;
  readonly reportTaskResult?: (message: string, kind: 'error' | 'success' | 'cancelled') => void;
}

export interface CanonPipelineResult {
  readonly ok: boolean;
  readonly message: string;
}

/** 单次请求携带的原著字符数：过大容易触发上下文上限，过小会浪费请求次数。 */
const CHARS_PER_BATCH = 5_000;
/** 单次解析动作最多发起的请求数；长篇原著需要多次「继续解析」。 */
const MAX_BATCHES_PER_RUN = 24;
/**
 * 结构化抽取的输出预算下限。
 * 抽取结果是 JSON，预算太小会在写到一半时被截断，表现为「返回格式无效」，
 * 因此这里对用户配置的 maxTokens 只取更大的一侧。
 */
const MIN_EXTRACTION_TOKENS = 6_000;
const MAX_EXTRACTION_TOKENS = 32_000;
/** 批次解析失败后的二分重试深度：整批失败常见于单块过长，拆小后往往能成功。 */
const BATCH_SPLIT_DEPTH = 1;

interface BatchOutcome {
  readonly extractions: readonly CanonExtraction[];
  readonly analyzed: readonly string[];
  readonly failed: number;
}

/**
 * 原著库管线：把角色卡、世界书与导入资料整理成可长期复用的人物锁与原著事实。
 * 所有 API 调用都由用户显式触发，不在后台自动消耗额度。
 */
export class CanonLibraryPipeline {
  readonly #deps: CanonPipelineDeps;
  readonly #run = new CancellableRun();
  #library: CanonLibrary | null = null;
  #imports: readonly CanonImportDocument[] = [];
  #running = false;

  constructor(deps: CanonPipelineDeps) {
    this.#deps = deps;
  }

  /** 用户在提示卡片上点「终止」时调用。 */
  cancel(): boolean {
    return this.#run.cancel();
  }

  get library(): CanonLibrary | null {
    return this.#library;
  }

  get imports(): readonly CanonImportDocument[] {
    return this.#imports;
  }

  get isRunning(): boolean {
    return this.#running;
  }

  get stats(): ReturnType<typeof canonLibraryStats> {
    return canonLibraryStats(this.#library);
  }

  /** 切换聊天或启动时读取已保存的原著库与导入资料。 */
  async load(): Promise<void> {
    const scopeId = this.#deps.scopeId();
    this.#library = await loadCanonLibrary(scopeId);
    this.#imports = await listCanonImports(scopeId);
  }

  async importDocument(name: string, text: string): Promise<CanonPipelineResult> {
    try {
      const document = await saveCanonImport(this.#deps.scopeId(), name, text);
      this.#imports = await listCanonImports(this.#deps.scopeId());
      return { ok: true, message: `已导入《${document.name}》（${document.text.length} 字），点击「解析原著」开始建立人物锁。` };
    } catch (error) {
      return { ok: false, message: `导入失败：${describeError(error)}` };
    }
  }

  async removeDocument(documentId: string): Promise<CanonPipelineResult> {
    try {
      await removeCanonImport(documentId);
      this.#imports = await listCanonImports(this.#deps.scopeId());
      return { ok: true, message: '已移除该份资料；下次解析会重新计算来源。' };
    } catch (error) {
      return { ok: false, message: `移除失败：${describeError(error)}` };
    }
  }

  async clear(): Promise<CanonPipelineResult> {
    const scopeId = this.#deps.scopeId();
    await clearCanonLibrary(scopeId);
    await clearCanonImports(scopeId);
    this.#library = null;
    this.#imports = [];
    return { ok: true, message: '已清除本聊天的原著库与导入资料。' };
  }

  /** 用户手工修正人物锁：标记为 manual，后续自动解析不再覆盖。 */
  async updateCharacter(character: CharacterLock): Promise<CanonPipelineResult> {
    const library = this.#library;
    if (!library) return { ok: false, message: '还没有建立原著库。' };
    const manual: CharacterLock = { ...character, manual: true, updatedAt: Date.now() };
    const next: CanonLibrary = {
      ...library,
      characters: mergeCharacterLocks(
        library.characters.filter((entry) => entry.id !== manual.id),
        [manual],
      ),
    };
    await this.#persist(next);
    return { ok: true, message: `${manual.name} 的人物锁已保存，自动解析不会再覆盖它。` };
  }

  /**
   * 解析原著资料。reset=true 重建（保留手工修正的人物锁），否则继续解析尚未处理的分块。
   * 未配置可用 API 时退化为「只用角色卡建立基础人物锁」，仍然可用且可手工编辑。
   */
  async analyze(options: { readonly reset?: boolean } = {}): Promise<CanonPipelineResult> {
    if (this.#running) return { ok: false, message: '原著解析正在进行中，请稍候。' };
    const { fanfic } = this.#deps.settings();
    const sources = this.#buildSources();
    if (sources.length === 0) {
      return { ok: false, message: '没有可解析的来源：请确认已加载角色卡，或先导入原著资料。' };
    }
    const bundle = normalizeCanonSources(sources, fanfic.title);
    const base = this.#baseLibrary(bundle, options.reset === true);
    const api = this.#resolveApi();
    if (!api.model.trim()) {
      const fallback = this.#fallbackLibrary(base);
      await this.#persist(fallback);
      return {
        ok: true,
        message: '同人/记忆整理 API 尚未配置模型，已仅用角色卡建立基础人物锁；配置 API 后可再次解析补全原著细节。',
      };
    }

    const pending = pendingChunks(base);
    if (pending.length === 0) {
      await this.#persist(base);
      return { ok: true, message: '当前资料已全部解析完成。' };
    }

    this.#running = true;
    this.#deps.reportTask?.('墨韵手机：正在解析原著资料中.....');
    const signal = this.#run.begin();
    try {
      const batches = batchChunks(pending, CHARS_PER_BATCH, MAX_BATCHES_PER_RUN);
      const extractions: CanonExtraction[] = [];
      const analyzed: string[] = [];
      let failed = 0;
      for (const [index, batch] of batches.entries()) {
        this.#deps.reportTask?.(`墨韵手机：正在解析原著资料 ${index + 1}/${batches.length}.....`);
        const outcome = await this.#analyzeBatchTree(api, base, batch, BATCH_SPLIT_DEPTH, signal);
        extractions.push(...outcome.extractions);
        analyzed.push(...outcome.analyzed);
        failed += outcome.failed;
      }
      const merged = mergeCanonExtractions(base, extractions, analyzed, Date.now());
      await this.#persist(merged);
      const remaining = pendingChunks(merged).length;
      const stats = canonLibraryStats(merged);
      const suffix = remaining > 0 ? `，还有 ${remaining} 段未解析（可再次点击继续解析）` : '';
      const failure = failed > 0 ? `；${failed} 个批次解析失败已跳过` : '';
      const message = `已解析 ${analyzed.length} 段资料：${stats.characters} 个人物锁、${stats.facts} 条原著事实、${stats.worldRules} 条世界规则${suffix}${failure}`;
      this.#deps.reportTaskResult?.(`墨韵手机：${message}`, 'success');
      return { ok: true, message };
    } catch (error) {
      if (isCancelledError(error)) {
        this.#deps.reportTaskResult?.('墨韵手机：原著解析已终止。', 'cancelled');
        return { ok: false, message: '原著解析已终止。' };
      }
      const message = `原著解析失败：${describeError(error)}`;
      this.#deps.reportTaskResult?.(`墨韵手机：${message}`, 'error');
      return { ok: false, message };
    } finally {
      this.#running = false;
      this.#run.end();
    }
  }

  /**
   * 批次解析：整批失败时二分拆小重试，
   * 让「某一块内容过长或过于难解析」不至于连带拖掉同批的其他片段。
   */
  async #analyzeBatchTree(
    api: OpenAiCompatibleApiConfig,
    library: CanonLibrary,
    batch: readonly CanonChunk[],
    depthLeft: number,
    signal: AbortSignal,
  ): Promise<BatchOutcome> {
    const extraction = await this.#analyzeBatch(api, library, batch, signal);
    if (extraction) {
      return { extractions: [extraction], analyzed: batch.map((chunk) => chunk.id), failed: 0 };
    }
    if (depthLeft <= 0 || batch.length < 2) return { extractions: [], analyzed: [], failed: 1 };
    const middle = Math.ceil(batch.length / 2);
    const left = await this.#analyzeBatchTree(api, library, batch.slice(0, middle), depthLeft - 1, signal);
    const right = await this.#analyzeBatchTree(api, library, batch.slice(middle), depthLeft - 1, signal);
    return {
      extractions: [...left.extractions, ...right.extractions],
      analyzed: [...left.analyzed, ...right.analyzed],
      failed: left.failed + right.failed,
    };
  }

  /** 单批解析：解析失败只跳过该批，不中断整轮，也不把该批标记为已解析。 */
  async #analyzeBatch(
    api: OpenAiCompatibleApiConfig,
    library: CanonLibrary,
    batch: readonly CanonChunk[],
    signal: AbortSignal,
  ): Promise<CanonExtraction | null> {
    const prompt = buildCanonExtractionPrompt(batch, library.characters.map((character) => character.name));
    try {
      const raw = await generateWithApiProxy(api, {
        system: prompt.system,
        user: prompt.user,
        temperature: structuredTemperature(api),
        maxTokens: extractionTokenBudget(api),
        signal,
        validateResponse: (response) => parseCanonExtraction(response, batch, Date.now()) !== null,
        invalidResponseMessage: '原著解析返回的格式无效。',
        onRetry: ({ attempt, retryCount, error }) => {
          this.#deps.reportTaskResult?.(
            `墨韵手机：原著解析失败，正在重试 ${attempt}/${retryCount}：${describeError(error)}`,
            'error',
          );
        },
      });
      return parseCanonExtraction(raw, batch, Date.now());
    } catch (error) {
      // 主动终止必须向上冒泡，否则剩余批次会继续消耗额度。
      if (isCancelledError(error)) throw error;
      phoneLogger.warn('原著资料批次解析失败（已跳过该批）', {
        chunkIds: batch.map((chunk) => chunk.id),
        error: describeError(error),
      });
      return null;
    }
  }

  /**
   * 本次解析的基线库：来源指纹变化（新增/删除资料）时重建分块，
   * 只保留手工修正过的人物锁与世界规则，避免旧事实指向已经不存在的片段。
   */
  #baseLibrary(bundle: ReturnType<typeof normalizeCanonSources>, reset: boolean): CanonLibrary {
    const current = this.#library;
    const empty = createEmptyCanonLibrary(bundle, Date.now());
    if (!current || reset || current.fingerprint !== bundle.fingerprint) {
      return {
        ...empty,
        characters: (current?.characters ?? []).filter((character) => character.manual),
        worldRules: reset ? [] : current?.worldRules ?? [],
      };
    }
    return { ...current, title: bundle.title, documents: bundle.documents, chunks: bundle.chunks };
  }

  /** 无可用 API 时的确定性兜底：角色卡本体成为可编辑的基础人物锁。 */
  #fallbackLibrary(base: CanonLibrary): CanonLibrary {
    const card = this.#deps.cardSnapshot();
    const description = card.fields.map((field) => `${field.label}：${field.text}`).join('\n');
    const fallback = fallbackCharacterLock(
      card.name,
      description,
      base.chunks.filter((chunk) => chunk.documentId.startsWith('card:')).map((chunk) => chunk.id),
      Date.now(),
    );
    return fallback
      ? { ...base, characters: mergeCharacterLocks(base.characters, [fallback]) }
      : base;
  }

  #buildSources(): readonly CanonRawDocument[] {
    const card = this.#deps.cardSnapshot();
    const cardText = card.fields.map((field) => `【${field.label}】\n${field.text}`).join('\n\n');
    return [
      ...(cardText ? [{ kind: 'card' as const, name: card.name || '当前角色卡', text: cardText }] : []),
      ...this.#deps.worldBookEntries()
        .filter((entry) => entry.content.trim())
        .map((entry) => ({ kind: 'worldbook' as const, name: entry.name || '世界书条目', text: entry.content })),
      ...this.#imports.map((document) => ({
        kind: 'import' as const,
        name: document.name,
        text: document.text,
        updatedAt: document.updatedAt,
      })),
    ];
  }

  #resolveApi(): OpenAiCompatibleApiConfig {
    const { fanfic, fallbackApi } = this.#deps.settings();
    return fanfic.api.model.trim() ? fanfic.api : fallbackApi;
  }

  async #persist(library: CanonLibrary): Promise<void> {
    this.#library = library;
    await saveCanonLibrary(this.#deps.scopeId(), library);
  }
}

function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

/**
 * 原著抽取的输出预算：用户配置更大就沿用，否则抬到下限。
 * JSON 被截断只会得到「格式无效」，白花一次请求，所以宁可给足输出空间。
 */
export function extractionTokenBudget(api: { readonly maxTokens: number | null }): number {
  return structuredTokenBudget(api, { min: MIN_EXTRACTION_TOKENS, max: MAX_EXTRACTION_TOKENS });
}