import { sheetColumnLabels, sheetColumnNames } from './sheet-dsl.js';
import type { SheetRecord } from './memory-store.js';
import type { DbStatement } from './protocol.js';

const quote = (name: string): string => `"${name.replace(/"/g, '""')}"`;
const literal = (value: string): string => `'${value.replace(/'/g, "''")}'`;

/** 仅识别衣着与覆盖描述的明确矛盾；不从身体描述反推衣着事实。 */
export function buildClothingConsistencyStatements(sheets: readonly SheetRecord[]): readonly DbStatement[] {
  return sheets.flatMap((sheet) => {
    const labels = sheetColumnLabels(sheet.rowTemplate);
    const columns = sheetColumnNames(sheet.ddl);
    const find = (names: readonly string[]): string | undefined => columns.find((column) => names.includes(labels.get(column) ?? column));
    const rules = [
      { source: find(['内衣', '胸衣']), target: find(['胸部状态', '胸部']), garments: ['抹胸', '胸罩', '文胸', '胸衣', '内衣'] },
      { source: find(['内裤']), target: find(['小穴状态', '阴部状态', '私处状态']), garments: ['内裤', '三角裤', '丁字裤', '底裤'] },
    ];
    return rules.flatMap(({ source, target, garments }): DbStatement[] => {
      if (!source || !target) return [];
      const s = `COALESCE(${quote(source)}, '')`;
      const t = `COALESCE(${quote(target)}, '')`;
      const removed = `(TRIM(${s}) IN ('无', '全裸', '未穿', '没穿', '不穿', '裸露') OR ${s} LIKE '%已%脱下%' OR ${s} LIKE '%已%脱掉%' OR ${s} LIKE '%已%褪下%')`;
      const covering = `(${garments.map((garment) => `${t} LIKE ${literal(`%${garment}%`)}`).join(' OR ')}) AND (${['覆盖', '紧贴', '包裹', '遮住', '遮盖'].map((verb) => `${t} LIKE ${literal(`%${verb}%`)}`).join(' OR ')})`;
      const notNegated = ['未', '没有', '不再', '已脱', '无', '不被'].map((word) => `${t} NOT LIKE ${literal(`%${word}%`)}`).join(' AND ');
      return [{ sql: `UPDATE ${quote(sheet.physicalName)} SET ${quote(target)} = '不确定' WHERE ${removed} AND ${covering} AND ${notNegated}` }];
    });
  });
}