/**
 * MVU 叶子约定：`[值, 描述]` 二元组。
 *
 * 世界书 InitVar 条目里的叶子带描述，运行时 `stat_data` 只留纯值。
 * 转换层与数据桥两侧都要用这套判定，因此单独成模块；
 * `variables-bridge` 改为从这里 re-export，避免两份实现各自漂移。
 */

export type MvuScalar = string | number | boolean | null;

/** 叶子值：标量，或标量数组（MVU 里用 `[[...], '描述']` 表达）。 */
export type MvuLeafValue = MvuScalar | readonly MvuScalar[];

export interface MvuLeafRead {
  readonly value: MvuLeafValue;
  readonly desc: string;
}

export function isMvuScalar(value: unknown): value is MvuScalar {
  return value === null || ['string', 'number', 'boolean'].includes(typeof value);
}

/**
 * 严格二元组：`[标量]` 或 `[标量, 描述]`。
 * 这是运行时变量读写沿用的判定，语义不能放宽，否则会把普通字符串数组当成叶子。
 */
export function isMvuTupleLeaf(value: unknown): value is readonly [unknown, string?] {
  return Array.isArray(value)
    && value.length >= 1
    && value.length <= 2
    && (value.length === 1 || typeof value[1] === 'string')
    && isMvuScalar(value[0]);
}

/** 递归把 MVU 的 [值, 描述] 二元组折叠为纯值，便于放进提示词。 */
export function flattenMvuTuples(value: unknown): unknown {
  if (isMvuTupleLeaf(value)) return value[0];
  if (Array.isArray(value)) return value.map((item) => flattenMvuTuples(item));
  if (value && typeof value === 'object') {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>).map(([key, child]) => [key, flattenMvuTuples(child)]),
    );
  }
  return value;
}

/**
 * 叶子方言。同一个 `['林知意', '苏曼']` 在两代 MVU 里含义相反，单看一个叶子分不出来：
 * - `tuple`：老 MVU 的 InitVar 写法，叶子一律是 `[值, 描述]`，上例读成「值 林知意，描述 苏曼」；
 * - `plain`：MVU Zod 卡的写法，默认值直接是裸标量或真列表，上例是一个两项名单。
 * 因此方言必须按整份文档判定一次，再传给每个叶子。
 */
export type MvuLeafDialect = 'tuple' | 'plain';

/** 二元组票数达到这个比例才算 tuple 方言：老卡里几乎每个叶子都是二元组。 */
const TUPLE_MAJORITY = 0.6;
const TUPLE_MIN_VOTES = 3;

interface DialectVotes {
  tuple: number;
  plain: number;
}

function countDialectVotes(value: unknown, votes: DialectVotes, depth: number): void {
  if (depth > 10) return;
  if (isMvuScalar(value)) {
    votes.plain += 1;
    return;
  }
  if (Array.isArray(value)) {
    if (isMvuTupleLeaf(value) && value.length === 2) votes.tuple += 1;
    else votes.plain += 1;
    return;
  }
  if (!value || typeof value !== 'object') return;
  for (const child of Object.values(value as Record<string, unknown>)) {
    countDialectVotes(child, votes, depth + 1);
  }
}

/**
 * 判定整份 InitVar 用哪种叶子方言。
 * 只有「二元组占多数且票数够」才判 tuple；卡里只是偶尔出现一个两项列表的，一律按 plain 读，
 * 因为把真列表读成「值 + 描述」会直接丢掉一半数据。
 */
export function detectLeafDialect(value: unknown): MvuLeafDialect {
  const votes: DialectVotes = { tuple: 0, plain: 0 };
  countDialectVotes(value, votes, 0);
  const total = votes.tuple + votes.plain;
  if (total === 0 || votes.tuple < TUPLE_MIN_VOTES) return 'plain';
  return votes.tuple / total >= TUPLE_MAJORITY ? 'tuple' : 'plain';
}

/**
 * InitVar 解析用的叶子读取。
 *
 * `tuple` 方言下接受 `[值, 描述]` 与 `[[列表], 描述]`；`plain` 方言下数组一律是列表叶子。
 * 空数组两种方言都读成空列表：Zod 的 `z.array(...).prefault([])` 就长这样，丢掉等于丢字段。
 * 返回 null 表示这不是叶子，调用方应继续往下当成分组遍历。
 */
export function readMvuLeaf(value: unknown, dialect: MvuLeafDialect = 'tuple'): MvuLeafRead | null {
  if (isMvuScalar(value)) return { value, desc: '' };
  if (!Array.isArray(value)) return null;
  if (value.length === 0) return { value: [], desc: '' };
  if (dialect === 'plain') {
    return isMvuScalarList(value) ? { value: value as readonly MvuScalar[], desc: '' } : null;
  }
  // 三项以上的纯标量数组不可能是二元组，按无描述的列表叶子读。
  if (value.length > 2) {
    return isMvuScalarList(value) ? { value: value as readonly MvuScalar[], desc: '' } : null;
  }
  const desc = value.length === 2 ? value[1] : '';
  if (value.length === 2 && typeof desc !== 'string') {
    return isMvuScalarList(value) ? { value: value as readonly MvuScalar[], desc: '' } : null;
  }
  const head = value[0];
  if (isMvuScalar(head)) return { value: head, desc: typeof desc === 'string' ? desc : '' };
  if (Array.isArray(head) && head.every((item) => isMvuScalar(item))) {
    return { value: head as readonly MvuScalar[], desc: typeof desc === 'string' ? desc : '' };
  }
  return null;
}

/** 纯标量数组：`['a', 'b', 'c']` 这类没有描述位的列表叶子。 */
export function isMvuScalarList(value: unknown): value is readonly MvuScalar[] {
  return Array.isArray(value) && value.length > 0 && value.every((item) => isMvuScalar(item));
}