import { evaluateConditionBoolean } from './evaluator.js';
import type {
  ConditionalActionRule,
  ConditionalAppGate,
  ConditionalPromptSection,
  ConditionGate,
  GenerationConditionContext,
} from './generation.js';
import type { ConditionSnapshot } from './types.js';

/** 规则作用目标：提示词片段、生成动作、应用范围、整体注入。 */
export type ConditionRuleTarget = 'prompt' | 'action' | 'app' | 'injection';

export const CONDITION_RULE_TARGETS: readonly ConditionRuleTarget[] = ['prompt', 'action', 'app', 'injection'];

export interface ConditionRule {
  readonly id: string;
  readonly name: string;
  readonly target: ConditionRuleTarget;
  /** action 目标为动作类型，app 目标为应用 id；'*' 表示全部，injection 与 prompt 忽略。 */
  readonly selector: string;
  /** prompt 目标条件成立时追加到系统提示词的文本。 */
  readonly text: string;
  readonly condition: string;
  /** 条件无法求值时的行为；默认拒绝。 */
  readonly onError: 'deny' | 'allow';
  readonly enabled: boolean;
}

export interface ConditionRulesSettings {
  /** 总开关：关闭时不产生任何门控，等同于没有配置条件。 */
  readonly enabled: boolean;
  readonly rules: readonly ConditionRule[];
}

export const CONDITION_RULE_LIMITS = Object.freeze({
  maxRules: 64,
  maxNameLength: 60,
  maxSelectorLength: 80,
  maxTextLength: 2_000,
  maxConditionLength: 500,
});

export const DEFAULT_CONDITION_RULES_SETTINGS: ConditionRulesSettings = Object.freeze({
  enabled: false,
  rules: Object.freeze([]) as readonly ConditionRule[],
});

export interface ConditionRuleStatus {
  readonly state: 'pass' | 'deny' | 'error';
  readonly detail: string;
}

export function normalizeConditionRulesSettings(value: unknown): ConditionRulesSettings {
  if (!isRecord(value)) return DEFAULT_CONDITION_RULES_SETTINGS;
  const source = Array.isArray(value.rules) ? value.rules : [];
  const seen = new Set<string>();
  const rules: ConditionRule[] = [];
  for (const [index, entry] of source.entries()) {
    if (rules.length >= CONDITION_RULE_LIMITS.maxRules) break;
    const rule = normalizeConditionRule(entry, `rule-${index + 1}`);
    if (!rule || seen.has(rule.id)) continue;
    seen.add(rule.id);
    rules.push(rule);
  }
  return { enabled: value.enabled === true, rules };
}

/** 单条规则归一化：条件为空、目标非法或 prompt 缺少文本都视为无效配置并丢弃。 */
export function normalizeConditionRule(value: unknown, fallbackId: string): ConditionRule | null {
  if (!isRecord(value)) return null;
  const target = CONDITION_RULE_TARGETS.find((item) => item === value.target);
  if (!target) return null;
  const condition = text(value.condition, CONDITION_RULE_LIMITS.maxConditionLength);
  if (!condition) return null;
  const body = text(value.text, CONDITION_RULE_LIMITS.maxTextLength);
  if (target === 'prompt' && !body) return null;
  const selector = text(value.selector, CONDITION_RULE_LIMITS.maxSelectorLength);
  return {
    id: text(value.id, 64) || fallbackId,
    name: text(value.name, CONDITION_RULE_LIMITS.maxNameLength) || fallbackId,
    target,
    selector: target === 'action' || target === 'app' ? selector || '*' : '',
    text: target === 'prompt' ? body : '',
    condition,
    onError: value.onError === 'allow' ? 'allow' : 'deny',
    enabled: value.enabled !== false,
  };
}

/**
 * 把已保存规则编译成生成链路使用的条件上下文。
 * 总开关关闭或没有启用规则时只返回快照，各接入点按“无规则即放行”处理。
 */
export function buildRuleConditionContext(
  snapshot: ConditionSnapshot,
  settings: ConditionRulesSettings,
): GenerationConditionContext {
  if (!settings.enabled) return { snapshot };
  const active = settings.rules.filter((rule) => rule.enabled);
  const promptSections = active.filter((rule) => rule.target === 'prompt').map(toPromptSection);
  const actionRules = active.filter((rule) => rule.target === 'action').map(toActionRule);
  const appGates = active.filter((rule) => rule.target === 'app').map(toAppGate);
  const injectionGate = toInjectionGate(active.filter((rule) => rule.target === 'injection'));
  return {
    snapshot,
    ...(promptSections.length > 0 ? { promptSections } : {}),
    ...(actionRules.length > 0 ? { actionRules } : {}),
    ...(appGates.length > 0 ? { appGates } : {}),
    ...(injectionGate ? { injectionGate } : {}),
  };
}

/** 单条规则在当前快照下的求值结果，供界面展示通过/拒绝/失败。 */
export function evaluateConditionRule(rule: ConditionRule, snapshot: ConditionSnapshot): ConditionRuleStatus {
  const result = evaluateConditionBoolean(rule.condition, snapshot);
  if (!result.ok) {
    const code = result.error?.code ?? 'invalid-value';
    const fallbackAllows = rule.onError === 'allow';
    return { state: 'error', detail: `${code}：${result.error?.message ?? '条件求值失败'}（${fallbackAllows ? '出错放行' : '出错拒绝'}）` };
  }
  return {
    state: result.value === true ? 'pass' : 'deny',
    detail: `求值步数 ${result.steps}`,
  };
}

function toPromptSection(rule: ConditionRule): ConditionalPromptSection {
  return { id: rule.id, text: rule.text, condition: rule.condition, onError: rule.onError };
}

function toActionRule(rule: ConditionRule): ConditionalActionRule {
  return { actionType: rule.selector || '*', condition: rule.condition, onError: rule.onError };
}

function toAppGate(rule: ConditionRule): ConditionalAppGate {
  return { appId: rule.selector || '*', condition: rule.condition, onError: rule.onError };
}

/** 多条注入规则合并成一个门：全部成立才注入，任一规则要求出错拒绝就整体拒绝。 */
function toInjectionGate(rules: readonly ConditionRule[]): ConditionGate | null {
  if (rules.length === 0) return null;
  return {
    condition: rules.map((rule) => `(${rule.condition})`).join(' and '),
    onError: rules.every((rule) => rule.onError === 'allow') ? 'allow' : 'deny',
  };
}

function text(value: unknown, maxLength: number): string {
  return typeof value === 'string' ? value.trim().slice(0, maxLength) : '';
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}