import { logHttpFailure } from '../core/diagnostics.js';
import {
  getSillyTavernContext,
  getSillyTavernRequestHeaders,
  loadWorldBookSnapshot,
  type SillyTavernContextShape,
  type WorldBookEntrySnapshot,
} from './sillytavern-bridge.js';
import { renderDynamicOverlayContent, type DynamicWorldBookTarget } from '../generation/dynamic-worldbook-service.js';

export const DYNAMIC_WORLD_BOOK_OVERLAY_PREFIX = '【动态设定·';
export const DYNAMIC_WORLD_BOOK_OVERLAY_BOOK_PREFIX = 'Dynamic World Book - ';

interface TavernHelperApi {
  getWorldbook?: (name: string) => Promise<readonly TavernWorldbookEntry[]>;
  updateWorldbookWith?: (
    name: string,
    updater: (entries: TavernWorldbookEntry[]) => readonly Partial<TavernWorldbookEntry>[] | Promise<readonly Partial<TavernWorldbookEntry>[]>,
    options?: { render?: 'debounced' | 'immediate' },
  ) => Promise<readonly TavernWorldbookEntry[]>;
  replaceWorldbook?: (name: string, entries: readonly Partial<TavernWorldbookEntry>[], options?: { render?: 'debounced' | 'immediate' }) => Promise<void>;
  createWorldbook?: (name: string, entries?: readonly Partial<TavernWorldbookEntry>[]) => Promise<boolean>;
  getWorldbookNames?: () => readonly string[];
  getCharWorldbookNames?: (name: 'current') => { primary: string | null; additional: readonly string[] };
  getChatWorldbookName?: (name: 'current') => string | null;
  getOrCreateChatWorldbook?: (name: 'current', bookName?: string) => Promise<string>;
}

interface TavernWorldbookEntry {
  readonly uid: number;
  readonly name: string;
  readonly enabled: boolean;
  readonly strategy: {
    readonly type: string;
    readonly keys: readonly (string | RegExp)[];
    readonly keys_secondary?: unknown;
    readonly scan_depth?: 'same_as_global' | number;
  };
  readonly position: {
    readonly type: string;
    readonly role: 'system' | 'assistant' | 'user';
    readonly depth: number;
    readonly order: number;
  };
  readonly content: string;
  readonly probability: number;
  readonly recursion: {
    readonly prevent_incoming: boolean;
    readonly prevent_outgoing: boolean;
    readonly delay_until: number | null;
  };
  readonly effect: {
    readonly sticky: number | null;
    readonly cooldown: number | null;
    readonly delay: number | null;
  };
  readonly [key: string]: unknown;
}

export interface DynamicWorldBookOverlayEntry {
  readonly entryId: string;
  readonly targetName: string;
  readonly content: string;
  readonly floor: number;
  readonly depth?: number;
  readonly sourceUid?: number;
}

export interface WorldBookWriter {
  readonly readBaselineEntries: (bookNames?: readonly string[]) => Promise<readonly WorldBookEntrySnapshot[]>;
  readonly currentChatBookName: () => string | null;
  readonly ensureOverlayBook: (scopeId: string) => Promise<string>;
  readonly projectOverlay: (bookName: string, entries: readonly DynamicWorldBookOverlayEntry[]) => Promise<void>;
  readonly clearOverlay: (bookName: string) => Promise<void>;
  readonly listOrphanOverlayBooks: () => readonly string[];
}

export function createWorldBookWriter(
  contextProvider: () => SillyTavernContextShape = getSillyTavernContext,
): WorldBookWriter {
  const getHelper = (): TavernHelperApi | null => {
    const host = getHostRecord();
    const helper = host.TavernHelper;
    return helper && typeof helper === 'object' ? helper as TavernHelperApi : null;
  };

  const readBaselineEntries = async (bookNames?: readonly string[]) => {
    const snapshot = await loadWorldBookSnapshot(contextProvider(), {
      sourceMode: bookNames ? 'selected' : 'bound',
      selectedBooks: bookNames ?? [],
    });
    return snapshot.activeEntries;
  };

  const currentChatBookName = () => getHelper()?.getChatWorldbookName?.('current') ?? null;

  const ensureOverlayBook = async (scopeId: string): Promise<string> => {
    const helper = getHelper();
    const existing = currentChatBookName();
    if (existing) return existing;
    if (!helper?.getOrCreateChatWorldbook) {
      throw new Error('当前 SillyTavern 没有可用的聊天世界书创建 API，已停止动态世界书写入。');
    }
    const suffix = scopeId.replace(/[^a-zA-Z0-9_-]+/g, '_').slice(-48) || 'current-chat';
    return helper.getOrCreateChatWorldbook('current', `${DYNAMIC_WORLD_BOOK_OVERLAY_BOOK_PREFIX}${suffix}`);
  };

  const projectOverlay = async (bookName: string, entries: readonly DynamicWorldBookOverlayEntry[]) => {
    if (!bookName.trim()) throw new Error('动态世界书投影缺少聊天世界书名称。');
    const helper = getHelper();
    const project = (current: readonly TavernWorldbookEntry[]) => {
      const managedNames = new Set(entries.map((entry) => overlayEntryName(entry.targetName)));
      const retained = current.filter((entry) => !isManagedOverlayEntry(entry, managedNames));
      return [...retained, ...entries.map(toTavernOverlayEntry)];
    };
    if (helper?.updateWorldbookWith) {
      await helper.updateWorldbookWith(bookName, project, { render: 'immediate' });
      return;
    }
    if (helper?.getWorldbook && helper.replaceWorldbook) {
      await helper.replaceWorldbook(bookName, project(await helper.getWorldbook(bookName)), { render: 'immediate' });
      return;
    }
    await updateWorldBookViaEndpoint(bookName, entries, contextProvider());
  };

  const clearOverlay = async (bookName: string) => {
    const helper = getHelper();
    const clear = (current: readonly TavernWorldbookEntry[]) => current.filter((entry) => !isManagedOverlayEntry(entry));
    if (helper?.updateWorldbookWith) {
      await helper.updateWorldbookWith(bookName, clear, { render: 'immediate' });
      return;
    }
    if (helper?.getWorldbook && helper.replaceWorldbook) {
      await helper.replaceWorldbook(bookName, clear(await helper.getWorldbook(bookName)), { render: 'immediate' });
      return;
    }
    await updateWorldBookViaEndpoint(bookName, [], contextProvider());
  };

  const listOrphanOverlayBooks = () => {
    const helper = getHelper();
    const names = helper?.getWorldbookNames?.() ?? [];
    const current = helper?.getChatWorldbookName?.('current') ?? null;
    return names.filter((name) => name.startsWith(DYNAMIC_WORLD_BOOK_OVERLAY_BOOK_PREFIX) && name !== current);
  };

  return { readBaselineEntries, currentChatBookName, ensureOverlayBook, projectOverlay, clearOverlay, listOrphanOverlayBooks };
}

export const worldBookWriter = createWorldBookWriter();

function overlayEntryName(targetName: string): string {
  return `${DYNAMIC_WORLD_BOOK_OVERLAY_PREFIX}${targetName}】`;
}

function isManagedOverlayEntry(
  entry: Pick<TavernWorldbookEntry, 'name' | 'content'>,
  expectedNames?: ReadonlySet<string>,
): boolean {
  if (expectedNames?.has(entry.name)) return true;
  return entry.name.startsWith(DYNAMIC_WORLD_BOOK_OVERLAY_PREFIX)
    || entry.content.includes('这是当前剧情状态的最新覆盖信息');
}

function toTavernOverlayEntry(entry: DynamicWorldBookOverlayEntry): Partial<TavernWorldbookEntry> {
  return {
    uid: stableOverlayUid(entry.entryId),
    name: overlayEntryName(entry.targetName),
    enabled: true,
    strategy: {
      type: 'constant',
      keys: [],
      keys_secondary: { logic: 'and_any', keys: [] },
      scan_depth: 'same_as_global',
    },
    position: { type: 'at_depth', role: 'system', depth: clampOverlayDepth(entry.depth), order: 9999 },
    content: renderDynamicOverlayContent({ name: entry.targetName }, entry.content, entry.floor),
    probability: 100,
    recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
    effect: { sticky: null, cooldown: null, delay: null },
    addMemo: true,
    matchPersonaDescription: false,
    matchCharacterDescription: false,
    matchCharacterPersonality: false,
    matchCharacterDepthPrompt: false,
    matchScenario: false,
    matchCreatorNotes: false,
    group: '',
    groupOverride: false,
    groupWeight: 100,
    caseSensitive: false,
    matchWholeWords: false,
    useGroupScoring: false,
    automationId: '',
  };
}

function clampOverlayDepth(value: number | undefined): number {
  if (!Number.isFinite(value)) return 4;
  return Math.min(20, Math.max(0, Math.floor(value!)));
}

function stableOverlayUid(entryId: string): number {
  let hash = 2_147_483_647;
  for (const char of entryId) hash = (hash * 31 + char.codePointAt(0)!) | 0;
  return Math.abs(hash) % 1_000_000_000;
}

async function updateWorldBookViaEndpoint(
  bookName: string,
  entries: readonly DynamicWorldBookOverlayEntry[],
  context: SillyTavernContextShape,
): Promise<void> {
  const getResponse = await fetch('/api/worldinfo/get', {
    method: 'POST',
    headers: getSillyTavernRequestHeaders(context),
    credentials: 'include',
    body: JSON.stringify({ name: bookName }),
  });
  if (!getResponse.ok) {
    logHttpFailure({
      stage: '聊天世界书读取',
      url: '/api/worldinfo/get',
      status: getResponse.status,
      statusText: getResponse.statusText,
      body: await getResponse.text().catch(() => ''),
      request: { bookName },
    });
    throw new Error(`读取聊天世界书失败：HTTP ${getResponse.status}`);
  }
  const payload = await getResponse.json() as { entries?: Record<string, Record<string, unknown>> };
  const current = Object.values(payload.entries ?? {});
  const retained = current.filter((entry) => !isManagedOverlayEntry({
    name: String(entry.comment ?? entry.name ?? ''),
    content: String(entry.content ?? ''),
  }));
  const next = [...retained, ...entries.map((entry) => ({
    ...toTavernOverlayEntry(entry),
    comment: overlayEntryName(entry.targetName),
  }))];
  const data = { entries: Object.fromEntries(next.map((entry, index) => [String(entry.uid ?? index), entry])) };
  const response = await fetch('/api/worldinfo/edit', {
    method: 'POST',
    headers: getSillyTavernRequestHeaders(context),
    credentials: 'include',
    body: JSON.stringify({ name: bookName, data }),
  });
  if (!response.ok) {
    logHttpFailure({
      stage: '聊天世界书写入',
      url: '/api/worldinfo/edit',
      status: response.status,
      statusText: response.statusText,
      body: await response.text().catch(() => ''),
      request: { bookName, entryCount: next.length, overlayCount: entries.length },
    });
    throw new Error(`写入聊天世界书失败：HTTP ${response.status}`);
  }
}

function getHostRecord(): Record<string, unknown> {
  try {
    const parent = globalThis.window?.parent as unknown as Record<string, unknown> | undefined;
    if (parent && (parent.SillyTavern || parent.TavernHelper)) return parent;
  } catch {
    // 受限 iframe 下回退当前窗口。
  }
  return globalThis as unknown as Record<string, unknown>;
}