/**
 * 从世界书条目与角色脚本里认出 MVU 资产。
 *
 * 真实卡的条目命名极不统一（`MVU初始化变量`、`[initvar]变量初始化`、`[InitVar] 初始变量`、
 * `[mvu_update]变量更新规则`、`变量更新逻辑`、`【SAM】变量更新规则` 都出现过），
 * 因此走「标题正则 + 正文形状」双路：标题认不出来时看正文长什么样。
 *
 * 但正文形状只能当补充，不能当依据：`parseYamlLite` 对任何带冒号的散文都能读出映射，
 * 只靠它会把人设、生图规范、表情包清单全当成变量条目。所以这里记住每条资产是
 * 「靠标题」还是「靠形状」认出来的，一张卡里连一条标题命中的 MVU 资产都没有时，
 * 整张卡按「不是 MVU 卡」处理。
 *
 * 这里全是纯函数：条目从哪来（酒馆助手 / 角色卡 / 接口）由调用方决定。
 */

import { looksLikeMvuVariableTree, parseInitVarPayload } from './init-var.js';
import { looksLikeMvuSchemaScript } from './zod-schema.js';
import type { MvuAsset, MvuAssetKind, MvuCardSource } from './types.js';
import { hashText } from '../db/sheet-dsl.js';
import type { RuleActivation } from './rule-activation.js';

/** 条目的最小形状：与 `WorldBookEntrySnapshot` 结构兼容，但不依赖它。 */
export interface MvuSourceEntry {
  readonly activation?: RuleActivation;
  readonly id: string;
  readonly name: string;
  readonly content: string;
  readonly enabled: boolean;
  readonly book?: string;
}

/** 角色脚本（酒馆助手的 `tavern_helper.scripts`）：MVU Zod 卡的变量结构就在里面。 */
export interface MvuSourceScript {
  readonly name: string;
  readonly content: string;
  readonly enabled: boolean;
}

/** 只认高置信度的固定写法：`输出协议` 这类泛词会把剧情条目一起卷进来。 */
const OUTPUT_FORMAT_PATTERN = /变量(输出|更新)(格式|规范|协议)|(输出|更新)变量(格式|规范|协议)|output_?format|update_?variable/i;
const UPDATE_RULES_PATTERN = /mvu_?update|更新规则|变量更新|更新逻辑|更新法则|变量处理规则/i;
const INIT_VAR_PATTERN = /init_?var|初始变量|变量初始化|初始化变量|变量初始/i;
const VARIABLE_LIST_PATTERN = /mvu_?variable|变量列表|变量展示|当前变量|变量一览/i;
const SCHEMA_NAME_PATTERN = /变量结构|schema|zod/i;

export type MvuDetectedBy = 'name' | 'shape';

export interface MvuClassification {
  readonly kind: MvuAssetKind;
  readonly by: MvuDetectedBy;
}

/** 正文是不是 InitVar：能解析成对象、结构像变量树，且不带更新规则/命令的特征。 */
export function looksLikeInitVarContent(content: string): boolean {
  if (hasMvuCommandMarkers(content) || /(^|\n)\s*check\s*:/i.test(content)) return false;
  const payload = parseInitVarPayload(content);
  return payload ? looksLikeMvuVariableTree(payload.value) : false;
}

/** 老协议：`_.set('路径', 旧, 新)` 系列命令。 */
function looksLikeLegacyCommands(content: string): boolean {
  return /_\.set\s*\(|_\.insert\s*\(|_\.add\s*\(|_\.delete\s*\(/.test(content);
}

/** 新协议：`<JSONPatch>` 块，或 RFC 6902 风格的 `{"op": "replace", "path": "/a/b"}`。 */
export function looksLikeJsonPatchProtocol(content: string): boolean {
  if (/<\s*\/?\s*JSONPatch\s*>/i.test(content)) return true;
  return /"op"\s*:\s*"(?:replace|delta|insert|remove|add|move|copy)"/i.test(content)
    && /"path"\s*:\s*"\//.test(content);
}

function looksLikeOutputProtocol(content: string): boolean {
  return /<\s*\/?\s*UpdateVariable\s*>/i.test(content) || looksLikeJsonPatchProtocol(content);
}

/** 标题是不是 MVU 资产的命名。删条目这类破坏性操作只认标题与命令特征，不靠正文形状猜。 */
export function matchesMvuEntryName(name: string): boolean {
  const trimmed = name.trim();
  if (!trimmed) return false;
  return OUTPUT_FORMAT_PATTERN.test(trimmed)
    || INIT_VAR_PATTERN.test(trimmed)
    || UPDATE_RULES_PATTERN.test(trimmed)
    || VARIABLE_LIST_PATTERN.test(trimmed);
}

/** 正文里是否带 MVU 的更新命令或输出协议标签（两代协议都算）。 */
export function hasMvuCommandMarkers(content: string): boolean {
  return looksLikeLegacyCommands(content) || looksLikeOutputProtocol(content);
}

function classifyByName(name: string): MvuAssetKind | null {
  // 顺序有讲究：`[mvu_update]变量输出格式` 同时命中「变量输出格式」和「mvu_update」，
  // 必须先判输出格式，否则会被当成更新规则。
  if (OUTPUT_FORMAT_PATTERN.test(name)) return 'outputFormat';
  // 标题写着 initvar 就按 InitVar 收下，即使正文解析不了：
  // 静默丢掉只会让用户看到「没识别到变量」，收下才能报出具体的解析错误。
  if (INIT_VAR_PATTERN.test(name)) return 'initVar';
  if (UPDATE_RULES_PATTERN.test(name)) return 'updateRules';
  if (VARIABLE_LIST_PATTERN.test(name)) return 'variableList';
  return null;
}

/** 判定单个条目属于哪类 MVU 资产，并记下是靠标题还是靠正文形状认出来的。 */
export function classifyMvuEntryDetailed(
  entry: Pick<MvuSourceEntry, 'name' | 'content'>,
): MvuClassification | null {
  const name = entry.name.trim();
  const content = entry.content.trim();
  if (!content) return null;

  const byName = classifyByName(name);
  if (byName) return { kind: byName, by: 'name' };

  if (looksLikeOutputProtocol(content)) return { kind: 'outputFormat', by: 'shape' };
  if (looksLikeLegacyCommands(content)) return { kind: 'updateRules', by: 'shape' };
  if (looksLikeInitVarContent(content)) return { kind: 'initVar', by: 'shape' };
  return null;
}

/** 判定单个条目属于哪类 MVU 资产；认不出来返回 null。 */
export function classifyMvuEntry(entry: Pick<MvuSourceEntry, 'name' | 'content'>): MvuAssetKind | null {
  return classifyMvuEntryDetailed(entry)?.kind ?? null;
}

const ASSET_ORDER: Readonly<Record<MvuAssetKind, number>> = Object.freeze({
  schema: 0,
  initVar: 1,
  updateRules: 2,
  outputFormat: 3,
  variableList: 4,
});

function toSchemaAsset(script: MvuSourceScript, index: number): MvuAsset | null {
  const content = script.content.trim();
  if (!content) return null;
  const name = script.name.trim();
  if (!looksLikeMvuSchemaScript(content)) return null;
  return {
    kind: 'schema',
    entryId: `script-${index}`,
    name: name || '未命名角色脚本',
    book: '角色脚本',
    content,
    enabled: script.enabled,
    detectedBy: SCHEMA_NAME_PATTERN.test(name) ? 'name' : 'shape',
  };
}

/**
 * 收集一张卡上的 MVU 资产。
 * InitVar 条目在卡里通常是关闭状态，因此**必须**传入全部条目（含 disabled），不能只传生效条目。
 */
export function collectMvuAssets(input: {
  readonly cardName: string;
  readonly books: readonly string[];
  readonly entries: readonly MvuSourceEntry[];
  readonly scripts?: readonly MvuSourceScript[];
}): MvuCardSource {
  const issues: string[] = [];
  const seen = new Set<string>();
  const assets: MvuAsset[] = [];

  for (const [index, script] of (input.scripts ?? []).entries()) {
    const asset = toSchemaAsset(script, index);
    if (asset) assets.push(asset);
  }

  for (const entry of input.entries) {
    const classification = classifyMvuEntryDetailed(entry);
    if (!classification) continue;
    const book = entry.book ?? '';
    const fingerprint = `${book}|${entry.name.trim()}|${hashText(entry.content)}`;
    if (seen.has(fingerprint)) continue;
    seen.add(fingerprint);
    assets.push({
      kind: classification.kind,
      entryId: entry.id,
      name: entry.name.trim() || '未命名条目',
      book,
      content: entry.content.trim(),
      enabled: entry.enabled,
      detectedBy: classification.by,
      ...(entry.activation ? { activation: entry.activation } : {}),
    });
  }

  assets.sort((left, right) => ASSET_ORDER[left.kind] - ASSET_ORDER[right.kind]
    || right.content.length - left.content.length);

  // 一条标题命中的资产都没有，说明这张卡只是「正文里有几段带冒号的设定」，不是 MVU 卡。
  // 这一闸不设的话，人设与生图规范会被当成变量条目，还会按「叶子最多」挤掉真正的变量表。
  const confirmed = assets.some((asset) => asset.detectedBy === 'name');
  if (!confirmed) {
    return {
      available: false,
      cardName: input.cardName.trim(),
      books: input.books.filter((book) => book.trim()),
      assets: [],
      issues: assets.length > 0
        ? ['卡里没有 MVU 命名的变量条目（InitVar / 变量更新规则 / 变量输出格式），只有几段形状相似的设定文本，已按「非 MVU 卡」处理。']
        : [],
    };
  }

  const initVars = assets.filter((asset) => asset.kind === 'initVar');
  const hasSchema = assets.some((asset) => asset.kind === 'schema');
  if (initVars.length === 0 && !hasSchema) {
    issues.push('没有找到可解析的 InitVar 变量条目，也没有 Zod 变量结构脚本，无法生成表结构。');
  }
  if (initVars.length === 0 && hasSchema) {
    issues.push('卡里没有 InitVar 条目，表结构与初值来自角色脚本里的 Zod 变量结构。');
  }
  if (initVars.length > 1) {
    issues.push('发现多份 InitVar 条目，将使用命名最正式、变量最全的那一份，其余忽略。');
  }

  return {
    available: true,
    cardName: input.cardName.trim(),
    books: input.books.filter((book) => book.trim()),
    assets,
    issues,
  };
}

/** 取某类资产里正文最长的一条（收集时已按此排序）。 */
export function selectAsset(source: MvuCardSource, kind: MvuAssetKind): MvuAsset | null {
  return source.assets.find((asset) => asset.kind === kind) ?? null;
}

/** 取某类资产的全部条目，按正文长度降序。 */
export function selectAssets(source: MvuCardSource, kind: MvuAssetKind): readonly MvuAsset[] {
  return source.assets.filter((asset) => asset.kind === kind);
}

/** 面板上用一句话说明扫描结果。 */
export function describeMvuCardSource(source: MvuCardSource): string {
  if (!source.available) return '当前角色卡与绑定世界书里没有识别到 MVU 变量资产。';
  const parts = [
    `变量结构脚本 ${selectAssets(source, 'schema').length} 份`,
    `InitVar ${selectAssets(source, 'initVar').length} 条`,
    `更新规则 ${selectAssets(source, 'updateRules').length} 条`,
    `输出格式 ${selectAssets(source, 'outputFormat').length} 条`,
    `变量列表 ${selectAssets(source, 'variableList').length} 条`,
  ];
  return `识别到：${parts.join('、')}。`;
}
