import type { PhoneState, Profile } from '../domain/model.js';

/**
 * 身份层：把「谁是谁」从提示词拼装中独立出来。
 * 私域（私聊/群聊，含推特私信）使用备注名与绑定角色；公开平台（论坛/推特动态）只暴露平台昵称。
 */

export interface SpeakerRef {
  readonly id: string;
  readonly name: string;
  readonly boundCharacter?: string;
}

export interface RosterEntry {
  readonly id: string;
  readonly displayName: string;
  readonly boundCharacter?: string;
  readonly publicNames: { readonly twitter: string; readonly forum: string };
  readonly isUser?: true;
  readonly bio: string;
  readonly personality: string;
  readonly activeHours: Profile['activeHours'];
  readonly replyDelay: Profile['replyDelay'];
}

/** 名册来源：GenerationPlan 结构上满足该形状，身份层因此不依赖生成计划模块。 */
export interface RosterSource {
  readonly conversations: readonly { readonly conversation: { readonly participantIds: readonly string[] } }[];
  readonly queuedPosts: readonly { readonly post: { readonly profileId: string } }[];
  readonly availableProfiles: readonly Profile[];
}

export interface IdentityConflict {
  readonly source: 'thought' | 'content';
  readonly claimedName: string;
  readonly expectedName: string;
}

export interface IdentityConflictInput {
  readonly actor: Profile;
  readonly profiles: Readonly<Record<string, Profile>>;
  readonly content: string;
  readonly thought?: string;
}

export function publicNameFor(profile: Profile, appId: 'forum' | 'twitter'): string {
  if (appId === 'twitter') {
    return profile.twitterName?.trim() || profile.aliases.twitter?.trim() || profile.displayName;
  }
  return profile.forumName?.trim() || profile.aliases.forum?.trim() || profile.displayName;
}

/** 会话成员的完整身份：名字、绑定角色、平台昵称与行为习惯一次给全，避免模型靠 id 猜人。 */
export function describeParticipant(profile: Profile, selfProfileId: string): Record<string, unknown> {
  return {
    id: profile.id,
    name: profile.displayName,
    ...(profile.id === selfProfileId ? { isUser: true } : {}),
    ...(profile.boundCharacter ? { boundCharacter: profile.boundCharacter } : {}),
    ...(profile.twitterName?.trim() ? { twitterName: profile.twitterName.trim() } : {}),
    aliases: profile.aliases,
    bio: profile.bio ?? '',
    personality: profile.personality ?? '',
    activeHours: profile.activeHours,
    replyDelay: profile.replyDelay,
  };
}

/** 会话内允许发言的角色白名单（用户本人除外）。 */
export function speakersOf(participants: readonly Profile[], selfProfileId: string): readonly SpeakerRef[] {
  return participants
    .filter((profile) => profile.id !== selfProfileId)
    .map((profile) => ({
      id: profile.id,
      name: profile.displayName,
      ...(profile.boundCharacter ? { boundCharacter: profile.boundCharacter } : {}),
    }));
}

/** 消息发言人显示名：历史里每条消息都要能直接看出是谁说的。 */
export function speakerNameOf(state: PhoneState, profileId: string): string {
  return state.profiles[profileId]?.displayName ?? '未知联系人';
}

/**
 * 唯一的 id → 身份表：本轮相关角色（会话成员、待处理动态作者、近期动态作者）排在前面，
 * 其余档案补齐到上限。同一个 id 只出现一次，且私域名与公开昵称同时给出，消除双重命名。
 */
export function buildIdentityRoster(
  state: PhoneState,
  source: RosterSource,
  selfProfileId: string,
  limit = 40,
): readonly RosterEntry[] {
  const relevantIds = new Set<string>();
  for (const { conversation } of source.conversations) {
    for (const id of conversation.participantIds) relevantIds.add(id);
  }
  for (const { post } of source.queuedPosts) relevantIds.add(post.profileId);
  for (const postId of state.postOrder.slice(-12)) {
    const post = state.posts[postId];
    if (post) relevantIds.add(post.profileId);
  }

  const relevant = [...relevantIds].flatMap((id) => {
    const profile = state.profiles[id];
    return profile ? [profile] : [];
  });
  const pool = source.availableProfiles.length > 0 ? source.availableProfiles : Object.values(state.profiles);
  const others = pool.filter((profile) => !relevantIds.has(profile.id));
  return [...relevant, ...others]
    .slice(0, Math.max(1, limit))
    .map((profile) => rosterEntryOf(profile, selfProfileId));
}

function rosterEntryOf(profile: Profile, selfProfileId: string): RosterEntry {
  return {
    id: profile.id,
    displayName: profile.displayName,
    ...(profile.boundCharacter ? { boundCharacter: profile.boundCharacter } : {}),
    publicNames: { twitter: publicNameFor(profile, 'twitter'), forum: publicNameFor(profile, 'forum') },
    ...(profile.id === selfProfileId ? { isUser: true as const } : {}),
    bio: profile.bio ?? '',
    personality: profile.personality ?? '',
    activeHours: profile.activeHours,
    replyDelay: profile.replyDelay,
  };
}

/** 该档案的全部可识别名字（备注名、绑定角色、推特昵称与各平台别名）。 */
export function identityNamesOf(profile: Profile): readonly string[] {
  return [profile.displayName, profile.boundCharacter, profile.forumName, profile.twitterName, ...Object.values(profile.aliases)]
    .map((value) => normalizeIdentityName(value ?? ''))
    .filter((value) => value.length > 0);
}

const SELF_CLAIM_MARKERS = ['我是', '我就是', '我叫', '本人是', '这里是'] as const;
const SIGNATURE_MARKERS = ['——', '—', '--'] as const;
/**
 * 自称边界：名字后面必须是句末或标点/语气词，才算「我就是这个人」。
 * 这样「我是乙姐，刚到」会被判定为冒名，而「我是乙姐的邻居」「我是老板派来的」不会误伤。
 */
const CLAIM_BOUNDARY = /^$|^[，。！？；：、…·~～!?,.:;)）】」』"']|^[啊呀哦喔噢啦了呢吧嘛哈]/u;

/**
 * 身份错乱检测：只在角色明确自称/署名为「别人的名字」时判定，避免误伤正常提及他人。
 */
export function findIdentityConflict(input: IdentityConflictInput): IdentityConflict | null {
  const ownNames = new Set(identityNamesOf(input.actor));
  const candidates = new Map<string, string>();
  for (const profile of Object.values(input.profiles)) {
    if (profile.id === input.actor.id) continue;
    for (const name of identityNamesOf(profile)) {
      if (name.length < 2 || ownNames.has(name) || candidates.has(name)) continue;
      candidates.set(name, profile.displayName);
    }
  }
  if (candidates.size === 0) return null;
  const ordered = [...candidates.entries()].sort(([left], [right]) => right.length - left.length);

  const sources: readonly (readonly ['thought' | 'content', string])[] = [
    ['thought', input.thought ?? ''],
    ['content', input.content],
  ];
  for (const [source, text] of sources) {
    const claimed = findClaimedName(text, ordered);
    if (claimed) {
      return { source, claimedName: claimed, expectedName: input.actor.displayName };
    }
  }
  return null;
}

function findClaimedName(text: string, candidates: readonly (readonly [string, string])[]): string | null {
  if (!text) return null;
  const normalized = normalizeIdentityName(text);
  for (const marker of SELF_CLAIM_MARKERS) {
    let from = 0;
    for (;;) {
      const index = normalized.indexOf(marker, from);
      if (index < 0) break;
      const rest = normalized.slice(index + marker.length);
      const hit = candidates.find(
        ([name]) => rest.startsWith(name) && CLAIM_BOUNDARY.test(rest.slice(name.length)),
      );
      if (hit) return hit[1];
      from = index + marker.length;
    }
  }
  for (const marker of SIGNATURE_MARKERS) {
    const index = normalized.lastIndexOf(marker);
    if (index < 0) continue;
    const tail = normalized.slice(index + marker.length);
    const hit = candidates.find(([name]) => tail === name);
    if (hit) return hit[1];
  }
  return null;
}

/** 身份名归一化：去掉 @ 前缀与空白后小写比较。 */
export function normalizeIdentityName(value: string): string {
  return value.replace(/^@+/, '').replace(/\s+/g, '').toLocaleLowerCase('zh-CN');
}