import { describeError, logModelFailure } from '../core/diagnostics.js';
import {
  ADAPTER_FIELD_ROLES,
  createUserFormatAdapter,
  normalizeContainer,
  type AdapterBodyFormat,
  type AdapterFieldAliases,
  type AdapterJsonShape,
  type FormatAdapter,
  type UserFormatAdapterInput,
} from '../parsing/adapter.js';
import { cardFormatSourcesFromCharacter } from '../parsing/discovery.js';
import { parsePhoneText } from '../parsing/parser.js';

/** 一段可能写着格式约定的正文（世界书条目或角色卡字段）。 */
export interface FormatCompatSnippet {
  readonly label: string;
  readonly text: string;
}

export interface FormatCompatRequest {
  /** 当前角色卡原始数据（v2/v3 均可）。 */
  readonly character: unknown;
  readonly worldBookEntries: readonly { readonly name: string; readonly content: string }[];
  /** 已经生效的适配器，用来告诉模型哪些容器不用再提。 */
  readonly existingAdapters: readonly FormatAdapter[];
  readonly disabledAppIds: readonly string[];
  readonly userNames: readonly string[];
}

export interface FormatCompatResult {
  readonly ok: boolean;
  readonly message: string;
  /** 通过校验与干跑、可以写入设置的适配器。 */
  readonly adapters: readonly FormatAdapter[];
  readonly accepted: readonly string[];
  readonly rejected: readonly string[];
}

/** 单次最多送多少段格式片段给模型，避免把整本世界书塞进请求。 */
const MAX_SNIPPETS = 8;
const MAX_SNIPPET_LENGTH = 2_400;
const MAX_TOTAL_LENGTH = 12_000;
const MAX_PROPOSED_ADAPTERS = 12;
/** 判断一段正文是否在讲「输出格式」。 */
const FORMAT_SIGNAL = /(格式|输出要求|示例|模板|format|template|_始|_开始|\[\/|<\/)/i;
/** 容器标记信号：没有任何标记的纯说明文字对适配器合成没有价值。 */
const CONTAINER_SIGNAL = /(<[A-Za-z_\u4e00-\u9fa5][^>]{0,31}>|\[[A-Za-z_\u4e00-\u9fa5][^\]]{0,31}\]|【[^】]{1,31}】)/;

const SYSTEM_PROMPT = `你是「墨韵手机格式适配器合成器」。你的唯一任务：读角色卡与世界书里关于手机内容输出格式的说明，产出让插件能解析这张卡的适配器声明，并只返回严格 JSON。

插件的解析模型（必须映射到这套语义，不要发明新字段）：
- 一个适配器 = 一个容器。容器要么是成对标签（<容器>…</容器> 或 [容器]…[/容器]），要么是一对起止标记（open/close，如 [X_始] 与 [X_末]）。
- appId 只能是 wechat（微信/QQ 私聊群聊）、twitter（推特/X 动态与私信）、forum（论坛/贴吧/Discord 式版块）、anonymous（匿名聊天）。
- family 描述容器正文的语法：tagged=每行用 <发言人>内容</发言人>；chat-app=每行「发言人: 内容」；bracketed=「字段名：值」逐行；discord=<channel>/<post>/<message> + [字段|值]；dsl=QQ.Private(...) 这类调用。
- body 描述正文形态：fields（字段行）、lines（发言行）、json（容器内是一整段 JSON）。只有确实是 JSON 才填 json。
- conversationKind：direct（私聊）、group（群聊/论坛版块）、anonymous（匿名会话）。
- postKind 只在容器产出帖子/动态时填：moment、forum-thread、forum-reply、twitter-post、twitter-reply、twitter-repost。
- fieldAliases 把插件语义字段映射到卡里真实写的字段名，键只能取：author、account、title、content、board、time、tags、id、parentId、pinned、hot、views、likes、comments、reposts、favorites。值是字符串数组，写卡里出现的原文（JSON 键名也照抄）。
- speakerAliases 把卡里的发言人写法映射成规范名，例如 {"tuser":"user","t诗诗":"诗诗"}；用户本人一律映射成 user。
- json 只在 body=json 时填：{"posts":"帖子数组的点分路径","comments":"每个帖子里评论数组的路径"}。

规则：
1. 只描述卡里真实写明的格式，不要编造容器名、字段名或路径；没有把握就不要输出那一条。
2. 不要重复 existingContainers 里已经支持的容器。
3. 不要把 UpdateVariable、Analysis、JSONPatch、think、summary、options、正文、剧情 之类的非手机容器当成手机容器。
4. 每个容器只输出一条适配器；最多 12 条。
5. 只返回 JSON，不要 Markdown，不要解释。

输出格式：
{"version":1,"adapters":[{"containers":["容器名"],"open":"可选起始标记","close":"可选结束标记","family":"tagged|bracketed|chat-app|discord|dsl","appId":"wechat|twitter|forum|anonymous","conversationKind":"direct|group|anonymous","postKind":"可选","body":"fields|lines|json","fieldAliases":{"author":["作者"]},"speakerAliases":{"tuser":"user"},"json":{"posts":"posts","comments":"comments"},"note":"一句话说明依据"}]}`;

/**
 * 「给我强兼它」：让模型把角色卡里的手机格式翻译成插件的解析适配器。
 * 全程只读角色卡与世界书；产出的适配器必须先通过本地校验，再用卡里的示例正文干跑成功才允许落库。
 */
export async function synthesizeFormatAdapters(
  request: FormatCompatRequest,
  options: { readonly generate: (system: string, user: string) => Promise<string> },
): Promise<FormatCompatResult> {
  const snippets = collectFormatSnippets(request);
  if (snippets.length === 0) {
    return {
      ok: false,
      message: '角色卡与已激活的世界书里没有找到任何格式说明或示例，先确认卡里写了手机内容的输出格式。',
      adapters: [],
      accepted: [],
      rejected: [],
    };
  }

  const existingContainers = [...new Set(request.existingAdapters.flatMap((adapter) => adapter.containers))];
  const user = JSON.stringify({
    task: '阅读 formatSnippets，输出插件可用的容器适配器声明。',
    existingContainers,
    disabledApps: request.disabledAppIds,
    formatSnippets: snippets,
  }, null, 2);

  let raw = '';
  try {
    raw = await options.generate(SYSTEM_PROMPT, user);
  } catch (error) {
    return {
      ok: false,
      message: `调用模型失败：${describeError(error)}`,
      adapters: [],
      accepted: [],
      rejected: [],
    };
  }

  const parsed = parseAdapterPlan(raw);
  if (parsed.issues.length > 0 || parsed.proposals.length === 0) {
    logModelFailure({
      stage: '格式强兼容',
      reason: parsed.issues[0] ?? '模型没有提出任何适配器',
      raw,
      issues: parsed.issues,
      request: { snippetLabels: snippets.map((snippet) => snippet.label), existingContainers },
    });
  }
  if (parsed.proposals.length === 0) {
    return {
      ok: false,
      message: `模型没有给出可用的适配器方案${parsed.issues[0] ? `（${parsed.issues[0]}）` : ''}。`,
      adapters: [],
      accepted: [],
      rejected: parsed.issues,
    };
  }

  const disabled = new Set(request.disabledAppIds);
  const known = new Set(existingContainers.map(normalizeContainer));
  const adapters: FormatAdapter[] = [];
  const accepted: string[] = [];
  const rejected: string[] = [...parsed.issues];
  for (const proposal of parsed.proposals.slice(0, MAX_PROPOSED_ADAPTERS)) {
    const label = proposal.containers.join(' / ') || '未命名容器';
    if (disabled.has(proposal.appId)) {
      rejected.push(`${label}：目标应用已停用`);
      continue;
    }
    if (proposal.containers.every((container) => known.has(normalizeContainer(container)))) {
      rejected.push(`${label}：已经被现有适配器覆盖`);
      continue;
    }
    let adapter: FormatAdapter;
    try {
      adapter = createUserFormatAdapter(proposal);
    } catch (error) {
      rejected.push(`${label}：${describeError(error)}`);
      continue;
    }
    const matched = dryRun(adapter, snippets, request.userNames);
    if (matched === 0) {
      rejected.push(`${label}：用卡里的示例正文试跑没有解析出任何内容，已丢弃`);
      continue;
    }
    adapters.push(adapter);
    accepted.push(`${label}（${proposal.appId} · 试跑命中 ${matched} 条）`);
  }

  return {
    ok: adapters.length > 0,
    message: adapters.length > 0
      ? `已生成 ${adapters.length} 个适配器：${accepted.join('；')}`
      : `没有适配器通过校验${rejected[0] ? `（${rejected[0]}）` : ''}。`,
    adapters,
    accepted,
    rejected,
  };
}

/** 用卡里的示例正文验证适配器真的能解析出东西。 */
function dryRun(
  adapter: FormatAdapter,
  snippets: readonly FormatCompatSnippet[],
  userNames: readonly string[],
): number {
  let matched = 0;
  for (const snippet of snippets) {
    try {
      matched += parsePhoneText(snippet.text, [adapter], userNames).items.length;
    } catch {
      // 单个片段解析异常不影响其他片段。
    }
  }
  return matched;
}

/** 从角色卡与世界书里挑出真正在讲格式的片段。 */
export function collectFormatSnippets(request: FormatCompatRequest): readonly FormatCompatSnippet[] {
  const sources = cardFormatSourcesFromCharacter(request.character);
  const candidates: FormatCompatSnippet[] = [
    ...request.worldBookEntries.map((entry) => ({ label: `世界书 · ${entry.name || '未命名条目'}`, text: entry.content })),
    ...sources.instructionTexts.map((text, index) => ({ label: `角色卡片段 ${index + 1}`, text })),
    ...sources.regexScripts.map((script) => ({ label: `角色卡正则 · ${script.name}`, text: script.findRegex })),
  ];
  const snippets: FormatCompatSnippet[] = [];
  let total = 0;
  for (const candidate of candidates) {
    const text = String(candidate.text ?? '').trim();
    if (!text || !FORMAT_SIGNAL.test(text) || !CONTAINER_SIGNAL.test(text)) continue;
    const clipped = text.length > MAX_SNIPPET_LENGTH ? `${text.slice(0, MAX_SNIPPET_LENGTH)}…` : text;
    if (total + clipped.length > MAX_TOTAL_LENGTH) break;
    total += clipped.length;
    snippets.push({ label: candidate.label, text: clipped });
    if (snippets.length >= MAX_SNIPPETS) break;
  }
  return snippets;
}

interface AdapterPlan {
  readonly proposals: readonly UserFormatAdapterInput[];
  readonly issues: readonly string[];
}

/** 严格解析模型返回的适配器方案；任何形状不对的条目都记为 issue 而不是猜。 */
export function parseAdapterPlan(raw: string): AdapterPlan {
  const payload = parseJsonObject(raw);
  if (!payload) return { proposals: [], issues: ['模型没有返回 JSON 对象'] };
  if (payload.version !== 1) return { proposals: [], issues: ['适配器方案版本不匹配'] };
  if (!Array.isArray(payload.adapters)) return { proposals: [], issues: ['adapters 必须是数组'] };

  const proposals: UserFormatAdapterInput[] = [];
  const issues: string[] = [];
  for (const [index, value] of payload.adapters.entries()) {
    const record = value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
    if (!record) {
      issues.push(`第 ${index + 1} 条：不是对象`);
      continue;
    }
    const containers = Array.isArray(record.containers)
      ? record.containers.map((item) => String(item ?? '').trim()).filter(Boolean)
      : [String(record.container ?? '').trim()].filter(Boolean);
    if (containers.length === 0) {
      issues.push(`第 ${index + 1} 条：没有容器名`);
      continue;
    }
    const fieldAliases = readFieldAliases(record.fieldAliases);
    const speakerAliases = readSpeakerAliases(record.speakerAliases);
    const json = readJsonShape(record.json);
    proposals.push({
      containers,
      family: String(record.family ?? '') as UserFormatAdapterInput['family'],
      appId: String(record.appId ?? '') as UserFormatAdapterInput['appId'],
      conversationKind: String(record.conversationKind ?? 'direct') as UserFormatAdapterInput['conversationKind'],
      ...(record.postKind ? { postKind: String(record.postKind) as UserFormatAdapterInput['postKind'] } : {}),
      ...(record.body ? { body: String(record.body) as AdapterBodyFormat } : {}),
      ...(typeof record.open === 'string' && record.open.trim() ? { open: record.open.trim() } : {}),
      ...(typeof record.close === 'string' && record.close.trim() ? { close: record.close.trim() } : {}),
      ...(fieldAliases ? { fieldAliases } : {}),
      ...(speakerAliases ? { speakerAliases } : {}),
      ...(json ? { json } : {}),
    });
  }
  return { proposals, issues };
}

function readFieldAliases(value: unknown): AdapterFieldAliases | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const source = value as Record<string, unknown>;
  const result: Record<string, readonly string[]> = {};
  for (const role of ADAPTER_FIELD_ROLES) {
    const names = source[role];
    if (!Array.isArray(names)) continue;
    const cleaned = names.map((name) => String(name ?? '').trim()).filter(Boolean);
    if (cleaned.length > 0) result[role] = cleaned;
  }
  return Object.keys(result).length > 0 ? result as AdapterFieldAliases : null;
}

function readSpeakerAliases(value: unknown): Readonly<Record<string, string>> | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const result: Record<string, string> = {};
  for (const [key, name] of Object.entries(value as Record<string, unknown>)) {
    const alias = String(key ?? '').trim();
    const canonical = String(name ?? '').trim();
    if (alias && canonical) result[alias] = canonical;
  }
  return Object.keys(result).length > 0 ? result : null;
}

function readJsonShape(value: unknown): AdapterJsonShape | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const source = value as Record<string, unknown>;
  const posts = String(source.posts ?? '').trim();
  const comments = String(source.comments ?? '').trim();
  if (!posts && !comments) return null;
  return {
    ...(posts ? { posts } : {}),
    ...(comments ? { comments } : {}),
  };
}

function parseJsonObject(raw: string): Record<string, unknown> | null {
  const trimmed = String(raw ?? '').trim();
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/i.exec(trimmed);
  const candidate = fenced?.[1] ?? trimmed;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    const value = JSON.parse(candidate.slice(start, end + 1)) as unknown;
    return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
  } catch {
    return null;
  }
}