import './styles/index.css';
import { PhoneRuntime } from './core/runtime.js';
import { beginPhoneTask } from './ui/phone-task.js';

const EXTENSION_VERSION = '1.0.0';
const INSTANCE_KEY = '__NARRATIVE_PHONE_INSTANCE__';
const OWNER_TOKEN = `narrative-phone:${Date.now()}:${Math.random().toString(36).slice(2)}`;

interface PhoneInstanceRecord {
  readonly ownerToken: string;
  readonly version: string;
  readonly runtime: PhoneRuntime;
  status: 'starting' | 'ready' | 'failed' | 'destroyed';
  error?: string;
}

declare global {
  interface Window {
    __NARRATIVE_PHONE_INSTANCE__?: PhoneInstanceRecord;
  }
}

let activation: Promise<void> | null = null;

function getHost(): Window {
  return window.parent && window.parent !== window ? window.parent : window;
}

function getOwnedRecord(): PhoneInstanceRecord | null {
  const record = getHost()[INSTANCE_KEY];
  return record?.ownerToken === OWNER_TOKEN ? record : null;
}

async function activate(): Promise<void> {
  const host = getHost();
  const existing = host[INSTANCE_KEY];
  if (existing && existing.ownerToken !== OWNER_TOKEN && existing.status !== 'destroyed') {
    console.warn('[墨韵手机] 已存在活动实例，跳过重复加载');
    return;
  }
  if (activation) return activation;

  const runtime = existing?.ownerToken === OWNER_TOKEN ? existing.runtime : new PhoneRuntime();
  const record: PhoneInstanceRecord = {
    ownerToken: OWNER_TOKEN,
    version: EXTENSION_VERSION,
    runtime,
    status: 'starting',
  };
  host[INSTANCE_KEY] = record;
  activation = runtime.start().then(
    () => {
      record.status = 'ready';
      delete record.error;
    },
    (error: unknown) => {
      record.status = 'failed';
      record.error = error instanceof Error ? error.message : String(error);
      activation = null;
      throw error;
    },
  );
  return activation;
}

function deactivate(): void {
  const host = getHost();
  const record = getOwnedRecord();
  record?.runtime.destroy();
  if (record) record.status = 'destroyed';
  if (host[INSTANCE_KEY]?.ownerToken === OWNER_TOKEN) delete host[INSTANCE_KEY];
  activation = null;
}

export async function onInstall(): Promise<void> {
  await activate();
}

export async function onUpdate(): Promise<void> {
  await activate();
}

export async function onActivate(): Promise<void> {
  await activate();
}

export async function onEnable(): Promise<void> {
  await activate();
}

export function onDisable(): void {
  deactivate();
}

export function onDelete(): void {
  deactivate();
}

queueMicrotask(() => {
  void activate().catch((error: unknown) => {
    beginPhoneTask('bootstrap').fail(error);
    console.error('[墨韵手机] 扩展启动失败', error);
  });
});