const SHELL_POSITION_STORAGE_KEY = 'narrative-phone:shell-position';

/** 移动端全屏布局下禁用窗口拖拽。 */
function canFloatShell(): boolean {
  try {
    return !window.matchMedia('(max-width: 600px), (pointer: coarse) and (max-width: 820px)').matches;
  } catch {
    return true;
  }
}

