export class PhoneShell {
  readonly #options: PhoneShellOptions;
  readonly #apps: ReadonlyMap<string, PhoneAppDefinition>;
  readonly #host: HTMLDivElement;
  readonly #shadow: ShadowRoot;
  readonly #shellElement: HTMLElement;
  readonly #content: HTMLElement;
  readonly #generationBar: HTMLDivElement;
  readonly #bottomNav: HTMLElement;
  readonly #notice: HTMLDivElement;
  readonly #noticeTimer = createNoticeTimer({
    setTimeout: (callback: () => void, delay: number) => window.setTimeout(callback, delay),
    clearTimeout: (handle: number) => window.clearTimeout(handle),
  }, 3_600);
  readonly #timeLabel: HTMLSpanElement;
  readonly #queuedChip: HTMLSpanElement;
  readonly #contextLabel: HTMLSpanElement;
  readonly #notifyButton: HTMLButtonElement;
  readonly #drawer: HTMLDivElement;
  #drawerOpen = false;
  #drawerCloseListener: ((event: Event) => void) | null = null;
  #outsideClickHandler: ((event: PointerEvent) => void) | null = null;
  /** 舞台几何守卫的清理函数：只在挂载期间生效。 */
  #stageGuardDispose: (() => void) | null = null;
  #state: PhoneState;
  #runtimeInfo: PhoneRuntimeInfo;
  #extensionModules: readonly ExtensionModuleRecord[];
  #route: PhoneRoute = 'home';
  #extensionModuleId: string | null = null;
  #selectedConversationId: string | null = null;
  #progress: GenerationProgress = { phase: 'idle', message: '等待回复' };
  #mounted = false;
  /** 待执行的整机重绘句柄：一帧内的多次状态变化合并成一次重绘。 */
  #renderHandle: number | null = null;
  /** 上一次重绘的页面标识：同一个页面才还原滚动位置，换页面仍然从顶部开始。 */
  #lastViewKey = '';

  constructor(options: PhoneShellOptions) {
    // 所有登记过的功能入口在这里统一套上「墨韵手机 {操作名}」三态提示。
    this.#options = withOperationNotices(options);
    this.#apps = new Map(options.apps.map((app) => [app.id, app]));
    this.#state = options.initialState;
    this.#runtimeInfo = options.runtimeInfo;
    this.#extensionModules = options.extensionModules;
    this.#host = element('div', { className: 'narrative-phone-host' });
    this.#host.id = 'narrative-phone-host';
    this.#shadow = this.#host.attachShadow({ mode: 'open' });

    const style = element('style', { text: `${PHONE_SHADOW_CSS}\n${PHONE_THEME_POLISH_CSS}` });
    this.#shadow.append(style);
    const shell = element('section', { className: 'phone-shell', attributes: { 'aria-label': '墨韵手机' } });
    const topBar = element('header', { className: 'phone-topbar' });
    const backButton = button('', 'phone-icon-button phone-back-button', () => this.#goBack());
    backButton.append(renderPhoneIcon('back'));
    backButton.setAttribute('aria-label', '返回上一层');
    const statusArea = element('div', { className: 'phone-topbar-status' });
    const time = element('span', { className: 'phone-time' });
    const queuedChip = element('span', { className: 'phone-topbar-chip' });
    const contextLabel = element('span', { className: 'phone-topbar-context' });
    const notifyButton = button('', 'phone-topbar-notify', () => this.#toggleNotificationDrawer());
    notifyButton.setAttribute('aria-label', '查看新消息通知');
    queuedChip.hidden = true;
    contextLabel.hidden = true;
    statusArea.append(time, notifyButton, queuedChip, contextLabel);
    const indicators = element('div', { className: 'phone-topbar-indicators' });
    indicators.append(
      renderPhoneIcon('signal', 'phone-indicator-icon'),
      renderPhoneIcon('battery', 'phone-indicator-icon phone-indicator-battery'),
    );
    const closeButton = button('', 'phone-icon-button phone-close-button', () => this.#options.onClose());
    closeButton.append(renderPhoneIcon('close'));
    closeButton.title = '关闭手机';
    closeButton.setAttribute('aria-label', '关闭手机界面');
    topBar.append(backButton, statusArea, indicators, closeButton);

    const content = element('main', { className: 'phone-content' });
    const generationBar = element('div', { className: 'phone-generation-bar' });
    const notice = element('div', { className: 'phone-notice', attributes: { role: 'status' } });
    const bottomBar = element('nav', { className: 'phone-bottom-nav', attributes: { 'aria-label': '应用导航' } });
    const drawer = element('div', { className: 'phone-notify-drawer' });
    drawer.hidden = true;
    generationBar.hidden = true;
    bottomBar.hidden = true;
    shell.append(topBar, drawer, content, generationBar, notice, bottomBar);
    this.#shadow.append(shell);
    this.#shellElement = shell;
    this.#content = content;
    this.#generationBar = generationBar;
    this.#bottomNav = bottomBar;
    this.#notice = notice;
    this.#timeLabel = time;
    this.#queuedChip = queuedChip;
    this.#contextLabel = contextLabel;
    this.#notifyButton = notifyButton;
    this.#drawer = drawer;

    // 顶栏可拖拽移动整个手机窗口（移动端全屏时禁用），位置会被记住。
    // 状态区（时间/通知）不参与窗口拖拽，避免与下拉通知手势冲突。
    makeDraggable({
      handle: topBar,
      target: shell,
      storageKey: SHELL_POSITION_STORAGE_KEY,
      ignoreSelector: 'button, .phone-topbar-status',
      enabled: canFloatShell,
    });
    // 跨过移动/桌面断点时切换定位模式：移动端居中布局不能残留拖拽坐标。
    try {
      const layoutMedia = window.matchMedia('(max-width: 600px), (pointer: coarse) and (max-width: 820px)');
      layoutMedia.addEventListener('change', () => this.#applyShellLayout());
    } catch {
      // matchMedia 不可用时忽略（极老环境）。
    }
    this.#bindNotificationPullGesture(statusArea);
    this.#bindEdgeSwipeBack(content);
    this.#bindScrollbarAutoHide(shell);
    this.#applyTheme(options.runtimeInfo.settings.uiTheme);
    this.#applyPersonalization();
  }

  /** 滚动条显隐：滚动时显示，停止滚动 1 秒后自动隐藏。 */
  #bindScrollbarAutoHide(shell: HTMLElement): void {
    const timers = new WeakMap<HTMLElement, number>();
    shell.addEventListener(
      'scroll',
      (event) => {
        const target = event.target;
        if (!(target instanceof HTMLElement)) return;
        target.classList.add('is-scrolling');
        const existing = timers.get(target);
        if (existing) window.clearTimeout(existing);
        timers.set(target, window.setTimeout(() => {
          target.classList.remove('is-scrolling');
        }, 1_000));
      },
      { capture: true, passive: true },
    );
  }

  /** 应用个性化设置：网格列数、窗口尺寸、字号缩放、字体、壁纸、主题配色。 */
  #applyPersonalization(): void {
    const config = this.#runtimeInfo.settings.personalization;
    this.#host.style.setProperty('--phone-app-cols', String(config.appColumns));
    // min() 钳制：自定义尺寸不允许超出当前视口（移动端小屏也能完整显示）。
    this.#shellElement.style.width = config.shellWidth > 0 ? `min(${config.shellWidth}px, calc(100vw - 20px))` : '';
    this.#shellElement.style.height = config.shellHeight > 0 ? `min(${config.shellHeight}px, calc(100dvh - 32px))` : '';
    this.#shellElement.style.fontFamily = config.fontFamily || '';
    // zoom 在主流 Chromium/Firefox 中可缩放内容区文字与组件。
    (this.#content.style as CSSStyleDeclaration & { zoom?: string }).zoom = config.fontScale !== 100
      ? String(config.fontScale / 100)
      : '';
    if (config.wallpaper) {
      this.#host.style.setProperty('--phone-wallpaper', `url("${config.wallpaper}")`);
      this.#host.setAttribute('data-has-wallpaper', '');
    } else {
      this.#host.style.removeProperty('--phone-wallpaper');
      this.#host.removeAttribute('data-has-wallpaper');
    }
    const theme = this.#runtimeInfo.settings.uiTheme;
    const colors = theme === 'dark'
      ? config.themeColorsDark
      : theme === 'glass'
        ? config.themeColorsGlass
        : config.themeColorsLight;
    this.#applyThemeColors(colors, theme);
  }

  /**
   * 自定义主题配色：以内联 CSS 变量覆盖语义色板（内联优先级高于所有 :host 规则），
   * 未设置的槽位清除内联值回落主题默认；部分次级色从主槽位用 color-mix 自动衍生。
   */
  #applyThemeColors(colors: ThemeColorOverrides, theme: PhoneTheme): void {
    const style = this.#host.style;
    const assign = (names: readonly string[], value: string) => {
      for (const name of names) {
        if (value) style.setProperty(name, value);
        else style.removeProperty(name);
      }
    };
    const isGlass = theme === 'glass';
    assign(['--phone-accent'], colors.accent);
    // 副色未设置时从主色衍生：白天加深，深色与玻璃主题提亮。
    const accentDark = colors.accentDark
      || (colors.accent
        ? (theme === 'light'
          ? `color-mix(in srgb, ${colors.accent} 76%, #000)`
          : `color-mix(in srgb, ${colors.accent} 68%, #fff)`)
        : '');
    assign(['--phone-accent-dark'], accentDark);
    assign(['--phone-canvas'], isGlass && colors.canvas
      ? `color-mix(in srgb, ${colors.canvas} 82%, transparent)`
      : colors.canvas);
    assign(['--phone-topbar-bg'], colors.canvas ? `color-mix(in srgb, ${colors.canvas} 88%, transparent)` : '');
    this.#host.toggleAttribute('data-custom-canvas', Boolean(colors.canvas));
    const surface = colors.surface;
    const surfaceBase = isGlass && surface ? `color-mix(in srgb, ${surface} 18%, transparent)` : surface;
    const surfaceSolid = isGlass && surface
      ? `color-mix(in srgb, ${surface} 48%, var(--phone-canvas))`
      : surface;
    assign(['--phone-surface-1', '--phone-card'], surfaceBase);
    assign(['--phone-card-solid'], surfaceSolid);
    assign(['--phone-surface-2'], surface
      ? (isGlass ? `color-mix(in srgb, ${surface} 13%, transparent)` : `color-mix(in srgb, ${surface} 62%, var(--phone-canvas))`)
      : '');
    assign(['--phone-surface-3', '--phone-fill'], surface
      ? (isGlass ? `color-mix(in srgb, ${surface} 19%, transparent)` : `color-mix(in srgb, ${surface} 36%, var(--phone-canvas))`)
      : '');
    assign(['--phone-fill-strong'], surface
      ? (isGlass ? `color-mix(in srgb, ${surface} 26%, transparent)` : `color-mix(in srgb, ${surface} 24%, var(--phone-canvas))`)
      : '');
    assign(['--phone-glass'], surface
      ? (isGlass ? `color-mix(in srgb, ${surface} 16%, transparent)` : `color-mix(in srgb, ${surface} 88%, transparent)`)
      : '');
    assign(['--phone-glass-strong'], surface
      ? (isGlass ? `color-mix(in srgb, ${surface} 24%, transparent)` : `color-mix(in srgb, ${surface} 96%, transparent)`)
      : '');
    assign(['--phone-text-primary', '--phone-ink'], colors.textPrimary);
    assign(['--phone-text-secondary', '--phone-muted'], colors.textSecondary);
    assign(
      ['--phone-text-tertiary'],
      colors.textSecondary ? `color-mix(in srgb, ${colors.textSecondary} 72%, var(--phone-canvas))` : '',
    );
    assign(
      ['--phone-placeholder'],
      colors.textSecondary ? `color-mix(in srgb, ${colors.textSecondary} 55%, var(--phone-canvas))` : '',
    );
  }

  /** 状态区下拉手势：向下拖动超过阈值展开通知列表；轻点也可切换。 */
  #bindNotificationPullGesture(statusArea: HTMLElement): void {
    let startX = 0;
    let startY = 0;
    let pointerId: number | null = null;
    let triggered = false;
    statusArea.style.touchAction = 'none';
    statusArea.addEventListener('pointerdown', (event) => {
      pointerId = event.pointerId;
      startX = event.clientX;
      startY = event.clientY;
      triggered = false;
    });
    statusArea.addEventListener('pointermove', (event) => {
      if (pointerId !== event.pointerId || triggered) return;
      const deltaX = event.clientX - startX;
      const deltaY = event.clientY - startY;
      if (deltaY > 26 && Math.abs(deltaY) > Math.abs(deltaX)) {
        triggered = true;
        this.#toggleNotificationDrawer(true);
      }
    });
    statusArea.addEventListener('pointerup', (event) => {
      if (pointerId !== event.pointerId) return;
      const moved = Math.hypot(event.clientX - startX, event.clientY - startY);
      // 轻点状态区（非按钮）也切换通知列表。
      if (!triggered && moved < 5 && !(event.target instanceof Element && event.target.closest('button'))) {
        this.#toggleNotificationDrawer();
      }
      pointerId = null;
    });
    statusArea.addEventListener('pointercancel', () => { pointerId = null; });
  }

  /** 从窗口左缘向右滑动返回上一页。 */
  #bindEdgeSwipeBack(content: HTMLElement): void {
    let startX = 0;
    let startY = 0;
    let pointerId: number | null = null;
    let tracking = false;
    let triggered = false;
    content.addEventListener('pointerdown', (event) => {
      const shellRect = this.#shellElement.getBoundingClientRect();
      tracking = event.clientX - shellRect.left <= 30;
      if (!tracking) return;
      pointerId = event.pointerId;
      startX = event.clientX;
      startY = event.clientY;
      triggered = false;
    });
    content.addEventListener('pointermove', (event) => {
      if (!tracking || pointerId !== event.pointerId || triggered) return;
      const deltaX = event.clientX - startX;
      const deltaY = event.clientY - startY;
      if (deltaX > 56 && Math.abs(deltaX) > Math.abs(deltaY) * 1.4) {
        triggered = true;
        this.#goBack();
      }
    });
    const stop = () => {
      tracking = false;
      pointerId = null;
    };
    content.addEventListener('pointerup', stop);
    content.addEventListener('pointercancel', stop);
  }

  #applyTheme(theme: PhoneTheme): void {
    this.#host.dataset.theme = theme;
  }

  get host(): HTMLDivElement {
    return this.#host;
  }

  get route(): PhoneRoute {
    return this.#route;
  }

  get selectedConversationId(): string | null {
    return this.#selectedConversationId;
  }

  /** 按当前断点决定机身是浮窗（恢复拖拽坐标）还是全屏（清掉行内坐标）。 */
  #applyShellLayout(): void {
    if (canFloatShell()) {
      restoreDraggedPosition(this.#shellElement, SHELL_POSITION_STORAGE_KEY, canFloatShell);
    } else {
      clearInlinePosition(this.#shellElement);
    }
  }

  mount(): void {
    if (this.#mounted) return;
    document.body.append(this.#host);
    this.#mounted = true;
    // 舞台必须先对齐视口，机身的绝对定位才有正确的参照系。
    const disposeStageGuard = keepStageAlignedToViewport({
      stage: this.#host,
      onCorrected: (drift) => {
        console.warn('[墨韵手机] 宿主页面劫持了浮层包含块，已按视口校正舞台几何', drift);
      },
    });
    this.#applyShellLayout();
    // 视口变小后旧的拖拽坐标会把机身推到屏幕外，重新按当前视口钳制一次。
    let reflowTimer = 0;
    const scheduleReflow = (): void => {
      window.clearTimeout(reflowTimer);
      reflowTimer = window.setTimeout(() => {
        if (this.#mounted) this.#applyShellLayout();
      }, 220);
    };
    window.addEventListener('resize', scheduleReflow);
    window.addEventListener('orientationchange', scheduleReflow);
    this.#stageGuardDispose = () => {
      window.clearTimeout(reflowTimer);
      window.removeEventListener('resize', scheduleReflow);
      window.removeEventListener('orientationchange', scheduleReflow);
      disposeStageGuard();
    };
    // 点击手机外部区域自动关闭（悬浮按钮除外，避免连点造成先关后开）。
    this.#outsideClickHandler = (event: PointerEvent) => {
      // 智绘姬等宿主扩展会由手机桥接层向正文按钮派发 pointerdown。
      // 非可信事件不是用户点击，不能把这种跨 DOM 的内部调用误判成点击手机外部。
      if (!event.isTrusted) return;
      const target = event.target as Node | null;
      if (!target) return;
      if (this.#host.contains(target)) return;
      if (target instanceof Element && target.closest('#narrative-phone-toggle')) return;
      this.#options.onClose();
    };
    window.setTimeout(() => {
      if (this.#mounted && this.#outsideClickHandler) {
        document.addEventListener('pointerdown', this.#outsideClickHandler, true);
      }
    }, 0);
    this.#render();
  }

  unmount(): void {
    closeImagePreview(this.#shellElement);
    if (!this.#mounted) return;
    this.#stageGuardDispose?.();
    this.#stageGuardDispose = null;
    if (this.#outsideClickHandler) {
      document.removeEventListener('pointerdown', this.#outsideClickHandler, true);
      this.#outsideClickHandler = null;
    }
    if (this.#drawerCloseListener) {
      this.#shadow.removeEventListener('pointerdown', this.#drawerCloseListener, true);
      this.#drawerCloseListener = null;
    }
    hideAutoDismissNotice(this.#notice, this.#noticeTimer);
    this.#drawerOpen = false;
    this.#drawer.hidden = true;
    this.#host.remove();
    this.#mounted = false;
    this.#cancelScheduledRender();
  }

  updateState(state: PhoneState): void {
    if (state.scopeId !== this.#state.scopeId) closeImagePreview(this.#shellElement);
    this.#state = state;
    if (this.#selectedConversationId && !state.conversations[this.#selectedConversationId]) {
      this.#selectedConversationId = null;
    }
    // 注入正文、自动解析、时间同步会在很短时间内连续改状态；合并成一帧重绘，避免界面反复闪。
    this.#scheduleRender();
  }

  updateRuntimeInfo(runtimeInfo: PhoneRuntimeInfo): void {
    this.#runtimeInfo = runtimeInfo;
    this.#applyTheme(runtimeInfo.settings.uiTheme);
    this.#applyPersonalization();
    if (this.#mounted && (this.#route.startsWith('settings') || this.#route === 'personalize' || this.#route === 'extensions'
      || this.#route === 'extensionApp' || this.#route === 'database' || this.#route === 'dataCenter'
      || this.#route === 'diary' || this.#route === 'memory' || this.#route === 'vector' || this.#route === 'conditions'
      || this.#route === 'forum' || this.#route === 'forumBoard' || this.#route === 'forumHot' || this.#route === 'forumMe')) this.#render();
  }

  updateExtensionModules(modules: readonly ExtensionModuleRecord[]): void {
    this.#extensionModules = modules;
    if (this.#mounted && (this.#route === 'home' || this.#route === 'extensions' || this.#route === 'extensionApp')) this.#render();
  }

  updateProgress(progress: GenerationProgress): void {
    this.#progress = progress;
    if (this.#mounted) this.#renderGenerationBar();
  }

  /**
   * 外部数据源（本地 SQLite 等）变化后重绘当前视图。
   * 这类写入不改变 `PhoneState`，因此不会触发 store 订阅，必须显式刷新。
   */
  refreshView(appId?: PhoneAppId): void {
    if (!this.#mounted) return;
    if (appId && this.#appIdForRoute(this.#route) !== appId) return;
    this.#scheduleRender();
  }

  navigate(route: PhoneRoute): void {
    this.#route = route;
    this.#extensionModuleId = null;
    this.#selectedConversationId = null;
    if (this.#mounted) this.#render();
  }

  openExtensionModule(moduleId: string): void {
    const record = this.#extensionModules.find((item) => item.manifest.id === moduleId && item.enabled);
    if (!record || !this.#options.getExtensionModule(moduleId)) return;
    this.#extensionModuleId = moduleId;
    this.#selectedConversationId = null;
    this.#route = 'extensionApp';
    if (this.#mounted) this.#render();
  }

  openConversation(conversationId: string): void {
    const conversation = this.#state.conversations[conversationId];
    if (!conversation || !this.#isAppEnabled(conversation.appId)) return;
    this.#selectedConversationId = conversationId;
    this.#route = conversation.appId === 'anonymous'
      ? 'anonymous'
      : conversation.appId === 'twitter'
        ? 'twitterDm'
        : conversation.appId === 'wechat'
          ? 'wechat'
          : 'forum';
    if (this.#mounted) this.#render();
  }

  #isAppEnabled(appId: string): boolean {
    return isPhoneAppEnabled(this.#runtimeInfo.settings.personalization.disabledAppIds, appId);
  }

  /**
   * 应用级显示名称：只用于桌面图标、通知与应用页面标题。
   * 应用内导航项使用自身 label，避免改名后所有导航项被换成同一个名字。
   */
  #appLabel(appId: string, fallback: string): string {
    return resolveAppLabel(this.#runtimeInfo.settings.personalization.appLabels, appId, fallback);
  }

  #goBack(): void {
    if (this.#selectedConversationId) {
      const conversation = this.#state.conversations[this.#selectedConversationId];
      this.#selectedConversationId = null;
      this.#route = conversation?.appId === 'twitter'
        ? 'twitterDm'
        : conversation?.appId === 'wechat'
          ? 'wechat'
          : conversation?.appId === 'anonymous'
            ? 'anonymous'
            : 'forum';
      if (this.#mounted) this.#render();
      return;
    }
    // 应用自定义的子页面返回目标（如推文详情返回打开它的列表页）。
    const appBackRoute = this.#apps.get(this.#appIdForRoute(this.#route))?.backRoute?.(this.#route);
    if (appBackRoute) {
      this.navigate(appBackRoute);
      return;
    }
    if (this.#route === 'wechatMoments') {
      this.navigate('wechatDiscover');
      return;
    }
    if (this.#route === 'settingsTimeAdvance') {
      this.navigate('settingsGeneration');
      return;
    }
    if (this.#route.startsWith('settings') && this.#route !== 'settings') {
      this.navigate('settings');
      return;
    }
    if (this.#route === 'extensionDocs') {
      this.navigate('extensions');
      return;
    }
    if (this.#route === 'extensions' || this.#route === 'extensionApp') {
      this.navigate('home');
      return;
    }
    if (this.#route !== 'home') this.navigate('home');
  }

  showNotice(message: string, kind: 'info' | 'error' | 'success' = 'info'): void {
    if (kind === 'error') {
      // 错误只显示在酒馆宿主页面右上角，避免与手机底部提示重复且不被手机层级遮挡。
      hideAutoDismissNotice(this.#notice, this.#noticeTimer);
      showHostTaskResultNotice(`墨韵手机：${message}`, 'error', 8_000);
      return;
    }
    showAutoDismissNotice(this.#notice, this.#noticeTimer, message, kind);
  }

  /** 把重绘推到下一帧，合并同一批状态变化；已排队时直接复用。 */
  #scheduleRender(): void {
    if (!this.#mounted || this.#renderHandle !== null) return;
    this.#renderHandle = requestAnimationFrame(() => {
      this.#renderHandle = null;
      if (this.#mounted) this.#render();
    });
  }

  #cancelScheduledRender(): void {
    if (this.#renderHandle === null) return;
    cancelAnimationFrame(this.#renderHandle);
    this.#renderHandle = null;
  }

  #render(): void {
    // 立即重绘（导航、挂载）时丢弃已排队的那一帧，避免同一次交互画两遍。
    this.#cancelScheduledRender();
    if ((this.#route === 'extensions' || this.#route === 'extensionDocs' || this.#route === 'extensionApp') && !this.#isAppEnabled('extensions')) {
      this.#route = 'home';
      this.#extensionModuleId = null;
    } else if (this.#route !== 'home' && this.#route !== 'personalize' && this.#route !== 'extensions'
      && this.#route !== 'extensionDocs'
      && this.#route !== 'extensionApp' && !this.#route.startsWith('settings')) {
      const routeAppId = this.#appIdForRoute(this.#route);
      if (!this.#isAppEnabled(routeAppId)) {
        this.#route = 'home';
        this.#selectedConversationId = null;
      }
    }
    this.#host.dataset.route = this.#route;
    // home 与 settings 需要区分：首页壁纸/状态栏黑膜只在 data-app="home" 时生效。
    this.#host.dataset.app = this.#route === 'home'
      ? 'home'
      : this.#route === 'personalize'
        ? 'personalize'
        : this.#route === 'extensions' || this.#route === 'extensionDocs' || this.#route === 'extensionApp'
        ? 'extensions'
        : this.#route.startsWith('settings')
          ? 'settings'
          : this.#appIdForRoute(this.#route);
    this.#renderHeader();
    // 勾选世界书条目这类操作会触发整机重绘，重建界面树会把所有滚动位置清零。
    // 同一个页面重绘前先记下滚动位置，画完再原样放回去，避免每次勾选都被弹回顶部。
    const viewKey = `${this.#route}|${this.#selectedConversationId ?? ''}|${this.#extensionModuleId ?? ''}`;
    const samePage = viewKey === this.#lastViewKey;
    const scrollPositions = samePage ? captureScrollPositions(this.#content) : null;
    const contentScrollTop = samePage ? this.#content.scrollTop : 0;
    this.#lastViewKey = viewKey;
    clear(this.#content);
    const context = this.#context();
    if (this.#route === 'home') {
      this.#content.append(this.#renderHome());
    } else if (this.#route === 'extensions') {
      this.#content.append(renderExtensionModulesPanel({
        modules: this.#extensionModules,
        onImport: this.#options.onImportExtensionModule,
        onToggle: this.#options.onToggleExtensionModule,
        onRemove: this.#options.onRemoveExtensionModule,
        openDeveloperGuide: () => this.navigate('extensionDocs'),
        showNotice: (message, kind) => this.showNotice(message, kind),
      }));
    } else if (this.#route === 'extensionDocs') {
      this.#content.append(renderExtensionDeveloperPanel({
        showNotice: (message, kind) => this.showNotice(message, kind),
      }));
    } else if (this.#route === 'extensionApp') {
      this.#content.append(this.#renderExtensionApp());
    } else if (this.#route === 'personalize') {
      this.#content.append(renderPersonalizePanel({
        settings: this.#runtimeInfo.settings,
        apps: this.#personalizeAppEntries(),
        disabledAppIds: this.#runtimeInfo.settings.personalization.disabledAppIds,
        onChange: this.#options.onSettingsChange,
        showNotice: (message, kind) => this.showNotice(message, kind),
        showModal: (title, fields) => showModal(this.#shadow.querySelector('.phone-shell') as HTMLElement, title, fields),
      }));
    } else if (this.#route.startsWith('settings')) {
      const section = this.#route === 'settingsApi' ? 'api'
        : this.#route === 'settingsGeneration' ? 'generation'
        : this.#route === 'settingsTimeAdvance' ? 'timeAdvance'
        : this.#route === 'settingsJailbreak' ? 'jailbreak'
        : this.#route === 'settingsWorldBook' ? 'worldBook'
        : this.#route === 'settingsDynamicWorldBook' ? 'dynamicWorldBook'
        : this.#route === 'settingsImage' ? 'image'
        : this.#route === 'settingsContext' ? 'context'
        : this.#route === 'settingsLogs' ? 'logs'
        : this.#route === 'settingsPromptLog' ? 'promptLog'
        : this.#route === 'settingsMvu' ? 'mvuConvert'
        : this.#route === 'settingsData' ? 'data'
        : 'home';
      this.#content.append(renderSettingsPanel({
        state: this.#state,
        settings: this.#runtimeInfo.settings,
        capabilities: this.#runtimeInfo.capabilities,
        hostApis: this.#runtimeInfo.hostApis,
        storage: this.#runtimeInfo.storage,
        worldBook: this.#runtimeInfo.worldBook,
        formatAdapters: this.#runtimeInfo.formatAdapters,
        presetPromptSlots: this.#runtimeInfo.presetPromptSlots,
        section,
        navigateSection: (next) => {
          const routeMap = {
            home: 'settings',
            api: 'settingsApi',
            generation: 'settingsGeneration',
            timeAdvance: 'settingsTimeAdvance',
            jailbreak: 'settingsJailbreak',
            worldBook: 'settingsWorldBook',
            dynamicWorldBook: 'settingsDynamicWorldBook',
            image: 'settingsImage',
            context: 'settingsContext',
            logs: 'settingsLogs',
            promptLog: 'settingsPromptLog',
            mvuConvert: 'settingsMvu',
            data: 'settingsData',
          } as const;
          this.navigate(routeMap[next]);
        },
        openDatabaseApp: () => this.navigate('database'),
        onChange: this.#options.onSettingsChange,
        onExportBackup: this.#options.onExportBackup,
        onPreviewBackup: this.#options.onPreviewBackup,
        onImportBackup: this.#options.onImportBackup,
        onPurgeData: this.#options.onPurgeData,
        onRefresh: this.#options.onRefreshRuntimeInfo,
        onFetchApiModels: this.#options.onFetchApiModels,
        onSummarizeNow: this.#options.onSummarizeNow,
        onForceFormatCompat: this.#options.onForceFormatCompat,
        mvu: this.#options.mvu,
        onDynamicWorldBookOptimize: this.#options.onDynamicWorldBookOptimize,
        onDynamicWorldBookClear: this.#options.onDynamicWorldBookClear,
        onDynamicWorldBookEdit: this.#options.onDynamicWorldBookEdit,
        onDynamicWorldBookRestore: this.#options.onDynamicWorldBookRestore,
        showModal: (title, fields) => showModal(this.#shadow.querySelector('.phone-shell') as HTMLElement, title, fields),
        showNotice: (message, kind) => this.showNotice(message, kind),
      }));
    } else {
      const app = this.#apps.get(this.#appIdForRoute(this.#route));
      if (app) this.#content.append(app.render(context));
    }
    this.#renderGenerationBar();
    this.#renderBottomNav();
    if (contentScrollTop > 0) this.#content.scrollTop = contentScrollTop;
    restoreScrollPositions(this.#content, scrollPositions);
  }

  #renderHeader(): void {
    // 顶部状态栏：剧情时间、未读消息应用图标、待处理数量与当前会话名。
    this.#timeLabel.textContent = formatShortTime(this.#state.worldClock.now);
    const queued = Object.values(this.#state.outbox)
      .filter((item) => item.status === 'queued' && this.#isAppEnabled(item.appId)).length;
    this.#queuedChip.hidden = queued === 0;
    this.#queuedChip.textContent = `${queued} 待处理`;
    const conversation = this.#selectedConversationId
      ? this.#state.conversations[this.#selectedConversationId]
      : undefined;
    this.#contextLabel.hidden = !conversation;
    this.#contextLabel.textContent = conversation?.title ?? '';
    const backButton = this.#shadow.querySelector<HTMLButtonElement>('.phone-back-button');
    if (backButton) backButton.hidden = this.#route === 'home';
    this.#renderNotifyIndicator();
    this.#renderNotificationDrawer();
  }

  /** 收集有未读消息的会话（按最近更新排序）。 */
  #unreadConversations() {
    return Object.values(this.#state.conversations)
      .filter((conversation) => conversation.unreadCount > 0 && this.#isAppEnabled(conversation.appId))
      .sort((left, right) => right.updatedAt - left.updatedAt);
  }

  /** 通知区应用图标：优先使用个性化设置里的自定义图标。 */
  #notifyAppIcon(appId: PhoneAppId): HTMLElement {
    const iconBox = element('span', { className: `phone-notify-app phone-notify-app-${appId}` });
    const custom = this.#runtimeInfo.settings.personalization.appIcons[appId];
    if (custom) {
      iconBox.classList.add('has-custom-icon');
      iconBox.append(element('img', { className: 'phone-app-icon-img', attributes: { alt: '', src: custom } }));
    } else {
      iconBox.append(renderPhoneIcon(appIconName(appId), 'phone-notify-app-icon'));
    }
    return iconBox;
  }

  /** 灵动岛：无消息时显示镜头点，有未读时展开为通知胶囊。 */
  #renderNotifyIndicator(): void {
    const unread = this.#unreadConversations();
    clear(this.#notifyButton);
    if (unread.length === 0) {
      this.#notifyButton.append(element('span', { className: 'phone-island-lens' }));
      this.#notifyButton.title = '通知中心';
      return;
    }
    const appIds = [...new Set(unread.map((conversation) => conversation.appId))].slice(0, 4);
    for (const appId of appIds) {
      this.#notifyButton.append(this.#notifyAppIcon(appId));
    }
    const total = unread.reduce((sum, conversation) => sum + conversation.unreadCount, 0);
    this.#notifyButton.append(element('span', { className: 'phone-notify-count', text: String(Math.min(99, total)) }));
    this.#notifyButton.title = '点击展开消息通知';
  }

  #toggleNotificationDrawer(force?: boolean): void {
    const next = force ?? !this.#drawerOpen;
    if (next === this.#drawerOpen) {
      if (next) this.#renderNotificationDrawer();
      return;
    }
    this.#drawerOpen = next;
    this.#drawer.hidden = !next;
    if (next) {
      this.#renderNotificationDrawer();
      const close = (event: Event) => {
        const target = event.target as Node | null;
        if (!target || this.#drawer.contains(target)) return;
        if (target instanceof Element && target.closest('.phone-topbar-status')) return;
        this.#toggleNotificationDrawer(false);
      };
      this.#drawerCloseListener = close;
      window.setTimeout(() => {
        if (this.#drawerOpen && this.#drawerCloseListener === close) {
          this.#shadow.addEventListener('pointerdown', close, true);
        }
      }, 0);
    } else if (this.#drawerCloseListener) {
      this.#shadow.removeEventListener('pointerdown', this.#drawerCloseListener, true);
      this.#drawerCloseListener = null;
    }
  }

  /** 下拉通知列表：每个未读会话一行预览，点击跳转到对应应用的会话。 */
  #renderNotificationDrawer(): void {
    if (!this.#drawerOpen) return;
    clear(this.#drawer);
    const unread = this.#unreadConversations();
    if (unread.length === 0) {
      this.#drawer.append(element('p', { className: 'phone-notify-empty', text: '没有新消息。' }));
      return;
    }
    const appLabels: Record<PhoneAppId, string> = {
      album: this.#appLabel('album', '相册'),
      wechat: this.#appLabel('wechat', '微信'),
      twitter: this.#appLabel('twitter', '推特'),
      forum: this.#appLabel('forum', '论坛'),
      anonymous: this.#appLabel('anonymous', '匿名交友'),
      database: this.#appLabel('database', '数据库'),
      dataCenter: this.#appLabel('dataCenter', '数据中心'),
      variables: this.#appLabel('variables', '变量管理'),
      conditions: this.#appLabel('conditions', '条件'),
      pxx: this.#appLabel('pxx', 'PXX'),
      calendar: this.#appLabel('calendar', '日历'),
      diary: this.#appLabel('diary', '日记本'),
      memory: this.#appLabel('memory', '记忆库'),
      vector: this.#appLabel('vector', '向量库'),
      fanfic: this.#appLabel('fanfic', '同人剧情'),
    };
    for (const conversation of unread.slice(0, 12)) {
      const latest = [...this.#state.messageOrder]
        .reverse()
        .map((id) => this.#state.messages[id])
        .find((message) => message?.conversationId === conversation.id);
      const row = button('', 'phone-notify-row', () => {
        this.#toggleNotificationDrawer(false);
        void this.#options.commands.markConversationRead(conversation.id);
        this.openConversation(conversation.id);
      });
      const iconBox = this.#notifyAppIcon(conversation.appId);
      const copy = element('span', { className: 'phone-notify-copy' });
      const head = element('span', { className: 'phone-notify-head' });
      head.append(
        element('strong', { text: conversation.title }),
        element('small', { text: `${appLabels[conversation.appId]} · ${formatShortTime(conversation.updatedAt)}` }),
      );
      copy.append(
        head,
        element('span', { className: 'phone-notify-preview', text: latest ? replaceImageMarkers(latest.content) : '有新消息' }),
      );
      row.append(iconBox, copy, element('span', { className: 'phone-badge', text: String(conversation.unreadCount) }));
      this.#drawer.append(row);
    }
  }

  #renderHome(): HTMLElement {
    const page = element('div', { className: 'phone-page phone-home' });
    if (this.#runtimeInfo.settings.personalization.wallpaper) page.classList.add('has-wallpaper');

    // 顶部时钟：居中大字时间 + 年月日星期；双击可配置剧情时间。
    const clock = element('div', { className: 'phone-home-clock' });
    const now = new Date(this.#state.worldClock.now);
    clock.append(
      element('strong', { className: 'phone-home-clock-time', text: formatShortTime(this.#state.worldClock.now) }),
      element('span', {
        className: 'phone-home-clock-date',
        text: `${now.getFullYear()}年${now.getMonth() + 1}月${now.getDate()}日 ${describeStoryWeekday(this.#state.worldClock.now, this.#state.scopeId)}`,
      }),
      element('span', { className: 'phone-home-clock-hint', text: '双击配置剧情时间' }),
    );
    clock.title = '双击配置剧情时间（手动输入或绑定变量）';
    clock.addEventListener('dblclick', () => {
      void this.#openClockConfig();
    });
    page.append(clock);

    const grid = element('div', { className: 'phone-app-grid' });
    const appIcons = this.#runtimeInfo.settings.personalization.appIcons;
    // 每个应用的未读总数：会话未读相加，用于图标右上角红点角标。
    const unreadByApp = new Map<PhoneAppId, number>();
    for (const conversation of Object.values(this.#state.conversations)) {
      if (conversation.unreadCount <= 0 || !this.#isAppEnabled(conversation.appId)) continue;
      unreadByApp.set(conversation.appId, (unreadByApp.get(conversation.appId) ?? 0) + conversation.unreadCount);
    }
    const appendTile = (
      id: string,
      label: string,
      icon: Parameters<typeof renderPhoneIcon>[0],
      onOpen: () => void,
      unread = 0,
      customIcon = '',
    ) => {
      const tile = button('', `phone-app-tile phone-app-tile-${id}`, onOpen);
      tile.setAttribute('aria-label', unread > 0 ? `打开${label}（${unread} 条未读）` : `打开${label}`);
      const custom = customIcon || appIcons[id];
      const iconWrap = element('span', { className: 'phone-app-icon-wrap' });
      const iconBox = element('span', { className: `phone-app-icon-box${custom ? ' has-custom-icon' : ''}` });
      if (custom) {
        iconBox.append(element('img', { className: 'phone-app-icon-img', attributes: { alt: '', src: custom } }));
      } else {
        iconBox.append(renderPhoneIcon(icon, 'phone-app-icon-svg'));
      }
      iconWrap.append(iconBox);
      if (unread > 0) {
        iconWrap.append(element('span', {
          className: 'phone-badge phone-app-badge',
          text: unread > 99 ? '99+' : String(unread),
        }));
      }
      tile.append(
        iconWrap,
        element('span', { className: 'phone-app-label', text: label }),
      );
      grid.append(tile);
    };
    for (const app of this.#apps.values()) {
      if (!this.#isAppEnabled(app.id)) continue;
      appendTile(
        app.id,
        this.#appLabel(app.id, app.label),
        appIconName(app.id),
        () => this.navigate(this.#homeRouteForApp(app.id)),
        unreadByApp.get(app.id) ?? 0,
      );
    }
    if (this.#isAppEnabled('extensions')) {
      appendTile('extensions', this.#appLabel('extensions', '拓展应用'), 'extensions', () => this.navigate('extensions'));
      for (const record of this.#extensionModules) {
        if (!record.enabled || !this.#options.getExtensionModule(record.manifest.id)) continue;
        appendTile(
          `extension-${record.manifest.id}`,
          record.manifest.name,
          'extensions',
          () => this.openExtensionModule(record.manifest.id),
          0,
          record.manifest.icon ?? '',
        );
      }
    }
    appendTile('personalize', this.#appLabel('personalize', '个性化'), 'palette', () => this.navigate('personalize'));
    appendTile('settings', this.#appLabel('settings', '设置'), 'settings', () => this.navigate('settings'));
    page.append(grid);

    // 底部操作栏：撤销最近一轮 AI 生成的全部内容。
    const hasRevertibleBatch = Object.values(this.#state.batches)
      .some((batch) => batch.status === 'completed' || batch.status === 'partial');
    const actionBar = element('div', { className: 'phone-home-actions' });
    const revert = button('完整回退本轮', 'phone-button phone-button-danger-ghost', async () => {
      if (!window.confirm('确定完整回退最近一轮手机内容吗？\n本轮用户发送的消息/帖子和 AI 生成的回复、动态、互动都会删除；因此变空的匿名匹配也会一并清理。')) return;
      revert.disabled = true;
      try {
        const result = await this.#options.onRevertLastBatch();
        this.showNotice(result.message, result.ok ? 'success' : 'error');
      } catch (error) {
        this.showNotice(error instanceof Error ? error.message : String(error), 'error');
      } finally {
        revert.disabled = false;
      }
    });
    revert.disabled = !hasRevertibleBatch;
    actionBar.append(revert);
    if (!hasRevertibleBatch) {
      actionBar.append(element('span', { className: 'phone-home-actions-hint', text: '暂无可删除的生成记录' }));
    }
    page.append(actionBar);
    return page;
  }

  #renderExtensionApp(): HTMLElement {
    const page = element('div', { className: 'phone-page phone-extension-app' });
    const moduleId = this.#extensionModuleId;
    const record = this.#extensionModules.find((item) => item.manifest.id === moduleId);
    const definition = moduleId ? this.#options.getExtensionModule(moduleId) : null;
    if (!record || !definition) {
      page.append(element('p', { className: 'phone-settings-hint', text: '模块不存在或已停用。' }));
      return page;
    }
    const heading = element('header', { className: 'phone-extension-app-heading' });
    heading.append(
      element('span', { className: 'phone-kicker', text: 'MODULE' }),
      element('h2', { className: 'phone-section-title', text: record.manifest.name }),
    );
    if (record.manifest.description) heading.append(element('p', { className: 'phone-settings-hint', text: record.manifest.description }));
    page.append(heading);
    try {
      page.append(definition.render(this.#options.getExtensionModuleHostApi(moduleId!)));
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      page.append(
        element('div', { className: 'phone-empty phone-extension-error' }),
        element('strong', { text: '模块运行失败' }),
        element('span', { text: message.slice(0, 300) }),
      );
      this.showNotice(`模块「${record.manifest.name}」运行失败。`, 'error');
    }
    return page;
  }

  /** 双击时钟：手动输入日期/时间/星期，或绑定楼层变量作为时间来源。 */
  async #openClockConfig(): Promise<void> {
    let config: ClockConfigData;
    try {
      config = await this.#options.onLoadClockConfig();
    } catch (error) {
      this.showNotice(error instanceof Error ? error.message : String(error), 'error');
      return;
    }
    const variableOptions: (readonly [string, string])[] = [
      ['', '不绑定（手动管理）'],
      ...config.variables.map((leaf) => [leaf.path, `${leaf.path}（${leaf.preview}）`] as const),
    ];
    const weekdayOptions: (readonly [string, string])[] = [
      ['', '跟随日期自动计算'],
      ...WEEKDAY_LABELS.map((label, index) => [String(index), label] as const),
    ];
    const shell = this.#shadow.querySelector('.phone-shell') as HTMLElement;
    const result = await showModal(shell, '配置剧情时间', [
      { name: 'date', label: '日期（如 2026-08-13 或 2026年8月13日）', value: config.date, required: true },
      { name: 'time', label: '时间（如 14:30 或 下午2点30分）', value: config.time, required: true },
      {
        name: 'weekday',
        label: '星期显示',
        type: 'select',
        options: weekdayOptions,
        value: config.weekdayOverride === null ? '' : String(config.weekdayOverride),
      },
      {
        name: 'dateVariable',
        label: '绑定日期变量（每轮生成后自动同步）',
        type: 'select',
        options: variableOptions,
        value: config.dateVariable,
      },
      {
        name: 'timeVariable',
        label: '绑定时间变量',
        type: 'select',
        options: variableOptions,
        value: config.timeVariable,
      },
    ]);
    if (!result) return;
    try {
      const outcome = await this.#options.onApplyClockConfig({
        date: (result.date ?? '').trim(),
        time: (result.time ?? '').trim(),
        weekdayOverride: result.weekday ? Number(result.weekday) : null,
        dateVariable: result.dateVariable ?? '',
        timeVariable: result.timeVariable ?? '',
      });
      this.showNotice(outcome.message, outcome.ok ? 'success' : 'error');
      if (this.#mounted) this.#render();
    } catch (error) {
      this.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
  }

  #renderGenerationBar(): void {
    const queued = Object.values(this.#state.outbox)
      .filter((item) => item.status === 'queued' && this.#isAppEnabled(item.appId)).length;
    const generating = this.#progress.phase === 'generating' || this.#progress.phase === 'committing';
    const hidden = this.#route === 'home' || this.#route === 'personalize' || this.#route.startsWith('settings') || (!generating && queued === 0);
    this.#generationBar.hidden = hidden;
    if (hidden) {
      clear(this.#generationBar);
      return;
    }
    clear(this.#generationBar);
    const label = generating
      ? this.#progress.message
      : `${queued} 条消息等待回复`;
    this.#generationBar.append(element('span', { className: 'phone-generation-label', text: label }));
    if (generating) {
      this.#generationBar.append(button('停止生成', 'phone-button phone-button-danger', this.#options.onCancelGeneration));
      return;
    }
    const generate = button('生成回复', 'phone-button phone-button-primary', async () => {
      try {
        await this.#options.onGenerate();
      } catch (error) {
        this.showNotice(error instanceof Error ? error.message : String(error), 'error');
      }
    });
    generate.disabled = queued === 0;
    this.#generationBar.append(generate);
  }

  #renderBottomNav(): void {
    clear(this.#bottomNav);
    const app = this.#apps.get(this.#appIdForRoute(this.#route));
    const visible = Boolean(
      app
      && this.#route !== 'home'
      && this.#route !== 'personalize'
      && !this.#route.startsWith('settings')
      && this.#route !== 'wechatMoments'
      && !this.#selectedConversationId
      && app.navigation.length > 0,
    );
    this.#bottomNav.hidden = !visible;
    if (!visible || !app) return;
    this.#bottomNav.setAttribute('aria-label', `${this.#appLabel(app.id, app.label)}导航`);
    const activeRoute = this.#route === 'twitter' ? 'twitterFeed' : this.#route;
    for (const itemDefinition of app.navigation) {
      const item = button('', 'phone-nav-item', () => this.navigate(itemDefinition.route));
      item.dataset.route = itemDefinition.route;
      item.classList.toggle('is-active', itemDefinition.route === activeRoute);
      item.setAttribute('aria-label', itemDefinition.label);
      item.append(
        renderPhoneIcon(itemDefinition.icon as Parameters<typeof renderPhoneIcon>[0]),
        element('small', { text: itemDefinition.label }),
      );
      this.#bottomNav.append(item);
    }
  }

  #context(): PhoneViewContext {
    return {
      state: this.#state,
      commands: this.#options.commands,
      generation: this.#options.generation,
      diary: {
        settings: this.#runtimeInfo.settings.diary,
        apiProfiles: this.#runtimeInfo.settings.apiProfiles,
        updateSettings: (patch) => Promise.resolve(this.#options.onSettingsChange({ diary: patch })),
        generateNow: () => this.#options.onDiaryGenerateNow(),
      },
      memoryBank: {
        settings: this.#runtimeInfo.settings.memory,
        apiProfiles: this.#runtimeInfo.settings.apiProfiles,
        presetPromptSlots: this.#runtimeInfo.presetPromptSlots,
        refreshPresetPromptSlots: this.#options.onRefreshRuntimeInfo,
        updateSettings: (patch) => Promise.resolve(this.#options.onSettingsChange({ memory: patch })),
        memorizeNow: () => this.#options.onMemorizeNow(),
        updateItemContent: (itemId, content) => this.#options.onMemoryItemUpdate(itemId, content),
        regenerateItem: (itemId) => this.#options.onMemoryItemRegenerate(itemId),
        consolidateNow: () => this.#options.onConsolidateNow(),
      },
      vector: {
        settings: this.#runtimeInfo.settings.vector,
        appDisabled: !this.#isAppEnabled('vector'),
        apiProfiles: this.#runtimeInfo.settings.apiProfiles,
        updateSettings: (patch) => Promise.resolve(this.#options.onSettingsChange({ vector: patch })),
        test: (query) => this.#options.onVectorTest(query),
        rebuildIndex: () => this.#options.onVectorRebuild(),
        ensureIndex: () => this.#options.onVectorEnsureIndex(),
        indexStatus: () => this.#options.onVectorStatus(),
      },
      conditions: {
        settings: this.#runtimeInfo.settings.conditions,
        worldBook: this.#runtimeInfo.worldBook,
        disabledAppIds: this.#runtimeInfo.settings.personalization.disabledAppIds,
        updateSettings: (patch) => Promise.resolve(this.#options.onSettingsChange({ conditions: patch })),
      },
      forum: {
        settings: this.#runtimeInfo.settings.forum,
        updateSettings: (patch) => Promise.resolve(this.#options.onSettingsChange({ forum: patch })),
      },
      fanfic: {
        ...this.#options.fanfic.snapshot(),
        settings: this.#runtimeInfo.settings.fanfic,
        apiProfiles: this.#runtimeInfo.settings.apiProfiles,
        narrative: this.#state.fanficNarrative,
        updateSettings: (patch) => Promise.resolve(this.#options.onSettingsChange({ fanfic: patch })),
        importText: (name, text) => this.#options.fanfic.importText(name, text),
        removeDocument: (documentId) => this.#options.fanfic.removeDocument(documentId),
        analyze: (reset) => this.#options.fanfic.analyze(reset),
        clearLibrary: () => this.#options.fanfic.clearLibrary(),
        updateCharacter: (character) => this.#options.fanfic.updateCharacter(character),
        trackNow: () => this.#options.fanfic.trackNow(),
        clearNarrative: () => this.#options.fanfic.clearNarrative(),
      },
      database: {
        storage: this.#runtimeInfo.storage,
        inspect: this.#options.onInspectDatabase,
        snapshotTables: this.#options.onSnapshotDatabaseTables,
        refresh: this.#options.onRefreshRuntimeInfo,
      },
      dataCenter: {
        ...this.#options.dataCenter,
        settings: this.#runtimeInfo.settings.dataCenter,
        apiProfiles: this.#runtimeInfo.settings.apiProfiles,
        updateSettings: (patch) => Promise.resolve(this.#options.onSettingsChange({ dataCenter: patch })),
      },
      route: this.#route,
      selectedConversationId: this.#selectedConversationId,
      appTitle: (defaultLabel) => this.#appLabel(this.#appIdForRoute(this.#route), defaultLabel),
      navigate: (route) => this.navigate(route),
      openConversation: (id) => this.openConversation(id),
      generateImage: (prompt) => this.#options.onGenerateImage(prompt),
      generateAvatarPrompt: (request) => this.#options.onGenerateAvatarPrompt(request),
      autoMatchContact: (request) => this.#options.onAutoMatchContact(request),
      generatePxxProducts: (existingNames) => this.#options.onGeneratePxxProducts(existingNames),
      generateAmbientPosts: (platform, options) => this.#options.onGenerateAmbientPosts(platform, options),
      showNotice: (message, kind) => this.showNotice(message, kind),
      showModal: (title, fields) => showModal(this.#shadow.querySelector('.phone-shell') as HTMLElement, title, fields),
      showConfirm: (request) => showConfirm(this.#shadow.querySelector('.phone-shell') as HTMLElement, request),
      showContactPicker: (title, contacts, options) => showContactPicker(
        this.#shadow.querySelector('.phone-shell') as HTMLElement,
        title,
        contacts,
        options,
      ),
      getProgress: () => this.#progress,
    };
  }

  #appIdForRoute(route: PhoneRoute): PhoneAppId {
    if (route === 'album') return 'album';
    if (route === 'database') return 'database';
    if (route === 'dataCenter') return 'dataCenter';
    if (route === 'variables') return 'variables';
    if (route === 'conditions') return 'conditions';
    if (route === 'pxx') return 'pxx';
    if (route === 'calendar') return 'calendar';
    if (route === 'diary') return 'diary';
    if (route === 'memory') return 'memory';
    if (route === 'vector') return 'vector';
    if (route === 'fanfic') return 'fanfic';
    if (route === 'wechat' || route === 'wechatContacts' || route === 'wechatDiscover' || route === 'wechatMoments' || route === 'wechatMe') return 'wechat';
    if (route === 'twitter' || route === 'twitterFeed' || route === 'twitterSearch' || route === 'twitterNotifications' || route === 'twitterDm' || route === 'twitterMe' || route === 'twitterPost') return 'twitter';
    if (route === 'forum' || route === 'forumBoard' || route === 'forumHot' || route === 'forumMe' || route === 'forumPost') return 'forum';
    return 'anonymous';
  }

  #homeRouteForApp(appId: PhoneAppId): PhoneRoute {
    if (appId === 'wechat') return 'wechat';
    if (appId === 'twitter') return 'twitterFeed';
    return appId;
  }

  /** 应用管理列表：注册应用 + 首页上的管理入口与设置。 */
  #personalizeAppEntries(): readonly PersonalizeAppEntry[] {
    return [
      ...[...this.#apps.values()].map((app) => ({ id: app.id, label: app.label, icon: appIconName(app.id) })),
      { id: 'extensions', label: '拓展应用', icon: 'extensions' as const },
      { id: 'personalize', label: '个性化', icon: 'palette' as const, canDisable: false },
      { id: 'settings', label: '设置', icon: 'settings' as const, canDisable: false },
    ];
  }
}

function appIconName(appId: PhoneAppId): Parameters<typeof renderPhoneIcon>[0] {
  if (appId === 'database') return 'database';
  // 数据中心复用「数据与配置」图标：同样表示本机数据管理，避免引入新的图标资源。
  if (appId === 'dataCenter') return 'dataSettings';
  if (appId === 'variables') return 'variables';
  if (appId === 'conditions') return 'conditions';
  if (appId === 'pxx') return 'pxx';
  if (appId === 'calendar') return 'calendar';
  if (appId === 'diary') return 'diary';
  if (appId === 'memory') return 'memory';
  if (appId === 'vector') return 'vector';
  // 同人剧情复用世界书图标：它同样表示"作品设定来源"，避免引入新的图标资源。
  if (appId === 'fanfic') return 'worldBook';
  if (appId === 'wechat') return 'wechat';
  if (appId === 'twitter') return 'twitter';
  if (appId === 'forum') return 'forum';
  return 'anonymous';
}

function formatShortTime(timestamp: number): string {
  const date = new Date(timestamp);
  return `${String(date.getHours()).padStart(2, '0')}:${String(date.getMinutes()).padStart(2, '0')}`;
}
