import {
  BUILTIN_FORMAT_ADAPTERS,
  isFormatAdapterEnabled,
  mergeFormatAdapters,
  type FormatAdapter,
} from './adapter.js';

export function createFormatRegistrySnapshot(
  discovered: readonly FormatAdapter[] = [],
  user: readonly FormatAdapter[] = [],
): readonly FormatAdapter[] {
  return mergeFormatAdapters(discovered, user);
}

export function createFormatRegistry(
  discovered: readonly FormatAdapter[] = [],
  user: readonly FormatAdapter[] = [],
  overrides: Readonly<Record<string, boolean>> = {},
): readonly FormatAdapter[] {
  return createFormatRegistrySnapshot(discovered, user).filter((adapter) => isFormatAdapterEnabled(adapter, overrides));
}

export function builtinFormatRegistry(): readonly FormatAdapter[] {
  return BUILTIN_FORMAT_ADAPTERS;
}

export function adaptersForText(
  adapters: readonly FormatAdapter[],
  text: string,
): readonly FormatAdapter[] {
  const normalized = text.toLocaleLowerCase('zh-CN');
  return adapters.filter((adapter) => {
    if (adapter.open && normalized.includes(adapter.open.toLocaleLowerCase('zh-CN'))) return true;
    return adapter.containers.some((container) => {
      const name = container.toLocaleLowerCase('zh-CN');
      return normalized.includes(`<${name}`) || normalized.includes(`[${name}]`);
    });
  });
}