import { tryParseCondition } from './parser.js';
import type {
  ConditionBinaryOperator,
  ConditionNode,
  ConditionPathNode,
} from './types.js';

export type VisualConditionOperator = Exclude<ConditionBinaryOperator, 'and' | 'or'>
  | 'exists'
  | 'empty';

export type VisualConditionValueKind = 'string' | 'number' | 'boolean' | 'list' | 'path';

export interface VisualConditionClause {
  readonly kind: 'clause';
  readonly path: string;
  readonly operator: VisualConditionOperator;
  readonly value: string;
  readonly valueKind: VisualConditionValueKind;
}

export interface VisualConditionGroup {
  readonly kind: 'group';
  readonly join: 'and' | 'or';
  readonly items: readonly VisualConditionNode[];
}

export interface VisualConditionNot {
  readonly kind: 'not';
  readonly item: VisualConditionNode;
}

export type VisualConditionNode = VisualConditionClause | VisualConditionGroup | VisualConditionNot;

export interface AdvancedConditionSource {
  readonly mode: 'advanced';
  readonly source: string;
  readonly reason: string;
}

export interface VisualConditionSource {
  readonly mode: 'visual';
  readonly node: VisualConditionNode;
}

export type ConditionEditorSource = VisualConditionSource | AdvancedConditionSource;

const COMPARISON_OPERATORS = new Set<VisualConditionOperator>([
  'eq', 'ne', 'gt', 'gte', 'lt', 'lte', 'contains', 'in',
]);

export function compileVisualCondition(node: VisualConditionNode): string {
  return compileNode(node);
}

export function createVisualConditionClause(
  path = 'variables.',
  operator: VisualConditionOperator = 'eq',
): VisualConditionClause {
  return {
    kind: 'clause',
    path,
    operator,
    value: '',
    valueKind: operator === 'in' ? 'list' : 'string',
  };
}

export function readConditionEditorSource(source: string): ConditionEditorSource {
  const trimmed = source.trim();
  if (!trimmed) {
    return { mode: 'visual', node: createVisualConditionClause() };
  }
  const parsed = tryParseCondition(trimmed);
  if (!parsed.node) return { mode: 'advanced', source: trimmed, reason: parsed.error?.message ?? '表达式无法解析' };
  const node = toVisualNode(parsed.node);
  return node
    ? { mode: 'visual', node }
    : { mode: 'advanced', source: trimmed, reason: '表达式包含高级语法，已保留原文' };
}

export function isVisualConditionComplete(node: VisualConditionNode): boolean {
  try {
    const source = compileVisualCondition(node);
    return Boolean(source);
  } catch {
    return false;
  }
}

function compileNode(node: VisualConditionNode): string {
  if (node.kind === 'clause') return compileClause(node);
  if (node.kind === 'not') return `not (${compileNode(node.item)})`;
  const parts = node.items.map(compileNode).filter(Boolean);
  if (parts.length === 0) return '';
  if (parts.length === 1) return parts[0]!;
  return `(${parts.join(` ${node.join} `)})`;
}

function compileClause(clause: VisualConditionClause): string {
  const path = normalizePath(clause.path);
  if (!path) throw new Error('条件路径不能为空或格式无效');
  if (clause.operator === 'exists' || clause.operator === 'empty') {
    return `${clause.operator}(${path})`;
  }
  const right = serializeValue(clause.value, clause.valueKind, clause.operator);
  if (!right) throw new Error('条件值不能为空');
  const operator = {
    eq: '==',
    ne: '!=',
    gt: '>',
    gte: '>=',
    lt: '<',
    lte: '<=',
    contains: 'contains',
    in: 'in',
  }[clause.operator];
  return `${path} ${operator} ${right}`;
}

function serializeValue(value: string, kind: VisualConditionValueKind, operator: VisualConditionOperator): string {
  const trimmed = value.trim();
  if (!trimmed) return '';
  if (kind === 'path') return normalizePath(trimmed);
  if (kind === 'number') {
    const number = Number(trimmed);
    if (!Number.isFinite(number)) throw new Error('条件值必须是有效数字');
    return String(number);
  }
  if (kind === 'boolean') {
    if (trimmed !== 'true' && trimmed !== 'false') throw new Error('布尔值只能是 true 或 false');
    return trimmed;
  }
  if (kind === 'list' || operator === 'in') {
    const values = trimmed.split(',').map((item) => item.trim()).filter(Boolean);
    if (values.length === 0) return '';
    return `[${values.map((item) => JSON.stringify(item)).join(', ')}]`;
  }
  return JSON.stringify(trimmed);
}

function normalizePath(source: string): string {
  const trimmed = source.trim();
  if (!trimmed) return '';
  const parsed = tryParseCondition(trimmed);
  return parsed.node?.kind === 'path' ? trimmed : '';
}

function toVisualNode(node: ConditionNode): VisualConditionNode | null {
  if (node.kind === 'unary' && node.operator === 'not') {
    const item = toVisualNode(node.operand);
    return item ? { kind: 'not', item } : null;
  }
  if (node.kind === 'binary' && (node.operator === 'and' || node.operator === 'or')) {
    const left = toVisualNode(node.left);
    const right = toVisualNode(node.right);
    if (!left || !right) return null;
    return { kind: 'group', join: node.operator, items: [left, right] };
  }
  if (node.kind === 'binary') {
    const operator = node.operator;
    if (!isVisualOperator(operator)) return null;
    if (node.left.kind !== 'path') return null;
    const value = readNodeValue(node.right, operator);
    if (!value) return null;
    return {
      kind: 'clause',
      path: pathToSource(node.left),
      operator,
      value: value.value,
      valueKind: value.kind,
    };
  }
  if (node.kind === 'call' && (node.name === 'exists' || node.name === 'empty') && node.arguments.length === 1) {
    const argument = node.arguments[0];
    if (!argument || argument.kind !== 'path') return null;
    return { kind: 'clause', path: pathToSource(argument), operator: node.name, value: '', valueKind: 'string' };
  }
  return null;
}

function isVisualOperator(value: ConditionBinaryOperator): value is Exclude<VisualConditionOperator, 'exists' | 'empty'> {
  return COMPARISON_OPERATORS.has(value as VisualConditionOperator);
}

function readNodeValue(
  node: ConditionNode,
  operator: VisualConditionOperator,
): { readonly value: string; readonly kind: VisualConditionValueKind } | null {
  if (operator === 'in') {
    if (node.kind !== 'array' || node.items.some((item) => item.kind !== 'literal')) return null;
    return {
      value: node.items.map((item) => {
        const literal = (item as Extract<ConditionNode, { kind: 'literal' }>).value;
        return typeof literal === 'string' ? literal : String(literal);
      }).join(', '),
      kind: 'list',
    };
  }
  if (node.kind === 'path') return { value: pathToSource(node), kind: 'path' };
  if (node.kind !== 'literal') return null;
  if (typeof node.value === 'number') return { value: String(node.value), kind: 'number' };
  if (typeof node.value === 'boolean') return { value: String(node.value), kind: 'boolean' };
  if (typeof node.value === 'string') return { value: node.value, kind: 'string' };
  return null;
}

function pathToSource(node: ConditionPathNode): string {
  return node.segments.reduce<string>((source, segment, index) => {
    if (typeof segment === 'number') return `${source}[${segment}]`;
    if (index === 0) return segment;
    return `${source}.${segment}`;
  }, '');
}