import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import type { SheetContent, SheetSummary } from '../../db/memory-engine.js';
import type { SheetPolicy } from '../../db/sheet-dsl.js';
import { composeSheetRuleFields, parseSheetRuleFields, SHEET_RULE_SECTIONS } from '../../db/sheet-rules.js';
import { formatRows, truncate } from '../cell-format.js';
import { availablePresetBundles } from '../../db/builtin-sheet-preset.js';
import { button, clear, element, pickTextFile } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';

/** 新建表的默认注入预算：预算是内部装配细节，不再暴露成用户配置项。 */
const DEFAULT_SHEET_TOKEN_BUDGET = 256;

const POLICY_LABELS: Readonly<Record<SheetPolicy, string>> = Object.freeze({
  always: '每轮注入',
  recall: '按需召回',
  manual: '仅手动',
});

function normalizePolicy(value: string): SheetPolicy {
  return value === 'always' || value === 'manual' ? value : 'recall';
}

/**
 * IF 条件语法说明，写表单提示与控制台占位都用它，避免两处措辞漂移。
 * 条件表达式与「规则门控」是同一套 DSL，数据中心只是额外把表内容挂到了 `sheets` 下。
 */
const CONDITION_SYNTAX_HINT = '条件语法：== != > >= < <= and or not ( )，还有 contains、in、exists()、empty()、length()。'
  + '可读 sheets.<表名>.count / .first.<列名或标签> / .last / .rows[0]，以及 variables.<变量名>、time.hour、time.weekday。';

/** 设置是独立页面；当前选中表与列表状态在重渲染之间保留。 */
let panelMode: 'browser' | 'settings' | 'schema' = 'browser';
let editingSheetId: string | null = null;
let activeSheetId: string | null = null;
let browserView: { readonly mode: 'list' } | { readonly mode: 'detail'; readonly rowId: number } | { readonly mode: 'add' } = { mode: 'list' };
let keyword = '';
let reversed = false;
/** SQL 控制台的输入与最近一次结果：写入后整页会重绘，不提升到模块级就会在下一帧被清空。 */
const SQL_RESULT_PLACEHOLDER = '执行结果会显示在这里。';
let sqlDraft = '';
let sqlOutcome = SQL_RESULT_PLACEHOLDER;

/**
 * 数据中心：手机插件自有的本地 SQLite 记忆库。
 * 主界面是表格浏览器（与数据库应用一致的交互），齿轮展开的是数据中心自己的设置。
 */
export function createDataCenterApp(): PhoneAppDefinition {
  return {
    id: 'dataCenter',
    label: '数据中心',
    icon: 'dataSettings',
    navigation: [],
    render: renderDataCenterApp,
  };
}

function renderDataCenterApp(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-database-page phone-data-center-page' });
  const render = (): void => {
    clear(page);
    if (!context.dataCenter.settings.enabled) {
      page.append(
        renderSettingsSection(context),
        element('p', { className: 'phone-settings-hint', text: '启用数据中心后可建表、编辑、导入和执行 SQL。关闭期间停止写入，现有数据保留。' }),
      );
      return;
    }
    if (panelMode === 'schema' && editingSheetId) {
      page.append(
        backBar('表格编辑', () => {
          panelMode = 'settings';
          render();
        }),
        renderSchemaEditor(context, editingSheetId, () => {
          panelMode = 'settings';
          editingSheetId = null;
          render();
        }),
      );
      return;
    }
    if (panelMode === 'settings') {
      page.append(
        backBar('数据中心设置', () => {
          panelMode = 'browser';
          render();
        }),
        renderSettingsSection(context),
        renderPresetSection(context),
        renderEngineSection(context),
        renderSchemaListSection(context, (sheetId) => {
          editingSheetId = sheetId;
          panelMode = 'schema';
          render();
        }),
        renderSqlConsole(context),
      );
      return;
    }
    page.append(renderSheetBrowser(context, () => {
      panelMode = 'settings';
      render();
    }));
  };
  render();
  return page;
}

/** 表格浏览器：左右箭头切表，记录卡片列表，点击进入详情可改可删。 */
function renderSheetBrowser(context: PhoneViewContext, onToggleSettings: () => void): HTMLElement {
  const section = element('section', { className: 'phone-db-browser' });
  const switcher = element('div', { className: 'phone-db-switcher' });
  const prevButton = button('', 'phone-icon-button phone-db-switch-button', () => switchSheet(-1));
  prevButton.textContent = '‹';
  prevButton.setAttribute('aria-label', '上一张表');
  const nextButton = button('', 'phone-icon-button phone-db-switch-button', () => switchSheet(1));
  nextButton.textContent = '›';
  nextButton.setAttribute('aria-label', '下一张表');
  const sheetTitle = element('span', { className: 'phone-db-switch-title', text: '加载中…' });
  const settingsButton = button('', 'phone-icon-button phone-db-switch-button phone-db-settings-button', onToggleSettings);
  settingsButton.append(renderPhoneIcon('settings', 'phone-db-settings-icon'));
  settingsButton.title = '数据中心设置';
  settingsButton.setAttribute('aria-label', '数据中心设置');
  switcher.append(prevButton, sheetTitle, nextButton, settingsButton);

  const body = element('div', { className: 'phone-db-body' });
  body.append(element('p', { className: 'phone-settings-hint', text: '正在读取数据中心…' }));
  section.append(switcher, body);

  let sheets: readonly SheetSummary[] = [];
  let content: SheetContent | null = null;

  const switchSheet = (offset: number): void => {
    if (sheets.length === 0) return;
    const currentIndex = Math.max(0, sheets.findIndex((sheet) => sheet.id === activeSheetId));
    activeSheetId = sheets[(currentIndex + offset + sheets.length) % sheets.length]?.id ?? null;
    keyword = '';
    browserView = { mode: 'list' };
    void load();
  };

  const load = async (notify = false): Promise<void> => {
    const status = await context.dataCenter.inspect();
    sheets = status.sheets;
    if (!sheets.some((sheet) => sheet.id === activeSheetId)) {
      activeSheetId = sheets[0]?.id ?? null;
      browserView = { mode: 'list' };
    }
    content = activeSheetId ? await context.dataCenter.readSheet(activeSheetId) : null;
    const view = browserView;
    if (view.mode === 'detail' && !content?.rows.some((row) => row.rowId === view.rowId)) {
      browserView = { mode: 'list' };
    }
    renderBody(status.description);
    if (notify) context.showNotice(status.description, 'info');
  };

  const renderBody = (description: string): void => {
    clear(body);
    if (!context.dataCenter.settings.enabled) {
      sheetTitle.textContent = '未启用';
      body.append(element('p', {
        className: 'phone-settings-hint',
        text: '数据中心尚未启用。点击右上角设置打开开关后，才会启动本地数据库、记录表格与注入召回内容。',
      }));
      return;
    }
    if (!content) {
      sheetTitle.textContent = sheets.length === 0 ? '暂无表格' : '读取失败';
      body.append(element('p', {
        className: 'phone-settings-hint',
        text: sheets.length === 0
          ? '还没有表格。在设置里选择「内置默认表格」或导入表格预设（支持 SP 模板），也可以手动新建记忆表。'
          : `无法读取表内容：${description}`,
      }));
      return;
    }
    const position = `${sheets.findIndex((sheet) => sheet.id === content?.sheet.id) + 1}/${sheets.length}`;
    sheetTitle.textContent = `${content.sheet.name} · ${position}`;
    if (browserView.mode === 'detail') renderDetail(content, browserView.rowId);
    else if (browserView.mode === 'add') renderAdd(content);
    else renderList(content);
  };

  const renderList = (sheet: SheetContent): void => {
    const toolbar = element('div', { className: 'phone-db-search-row' });
    const searchInput = element('input', {
      className: 'phone-input phone-db-search-input',
      attributes: { type: 'search', placeholder: '搜索任意字段…' },
    });
    searchInput.value = keyword;
    searchInput.addEventListener('input', () => {
      keyword = searchInput.value.trim();
      renderCards();
    });
    const reverseButton = button(reversed ? '正序' : '倒序', 'phone-button phone-button-secondary phone-button-compact', () => {
      reversed = !reversed;
      renderBody('');
    });
    toolbar.append(searchInput, reverseButton);

    const summary = element('p', { className: 'phone-db-count-hint' });
    const cards = element('div', { className: 'phone-db-cards' });
    const renderCards = (): void => {
      const lowered = keyword.toLowerCase();
      const matched = sheet.rows.filter((row) => !keyword || row.values.some((value) => value.toLowerCase().includes(lowered)));
      const ordered = reversed ? [...matched].reverse() : matched;
      summary.textContent = keyword
        ? `匹配 ${ordered.length}/${sheet.rows.length} 行 · ${sheet.sheet.purpose}`
        : `共 ${sheet.rows.length} 行 · ${POLICY_LABELS[sheet.sheet.policy]}`;
      clear(cards);
      if (ordered.length === 0) {
        cards.append(element('p', {
          className: 'phone-settings-hint',
          text: keyword ? '没有匹配的行。' : '这张表还没有数据。可点击下方「新增记录」，或让填表模型自动写入。',
        }));
        return;
      }
      for (const row of ordered) {
        const card = button('', 'phone-db-record-card', () => {
          browserView = { mode: 'detail', rowId: row.rowId };
          renderBody('');
        });
        const head = element('div', { className: 'phone-db-record-head' });
        head.append(
          element('span', { className: 'phone-db-record-index', text: `#${row.rowId}` }),
          element('strong', { className: 'phone-db-record-title', text: truncate(row.values.find((value) => value.trim()) ?? '（空行）', 24) }),
          element('span', { className: 'phone-db-record-badge', text: `${row.values.filter((value) => value.trim()).length} 项` }),
        );
        const preview = sheet.labels
          .map((label, index) => (row.values[index]?.trim() ? `${label}：${row.values[index]}` : ''))
          .filter(Boolean)
          .slice(1)
          .join(' · ');
        card.append(head, element('p', { className: 'phone-db-record-preview', text: truncate(preview, 76) || '（无更多字段）' }));
        cards.append(card);
      }
    };

    const actions = element('div', { className: 'phone-db-bottom-actions' });
    actions.append(
      button('新增记录', 'phone-button phone-button-primary', () => {
        browserView = { mode: 'add' };
        renderBody('');
      }),
      button('刷新', 'phone-button phone-button-secondary', () => load(true)),
    );
    body.append(toolbar, summary, cards, actions);
    renderCards();
  };

  const renderEditor = (
    sheet: SheetContent,
    initial: readonly string[],
  ): { readonly form: HTMLElement; readonly read: () => Record<string, string> } => {
    const form = element('div', { className: 'phone-db-form' });
    const editors = new Map<string, HTMLTextAreaElement>();
    sheet.columns.forEach((column, index) => {
      const field = element('label', { className: 'phone-db-field' });
      field.append(element('span', { className: 'phone-control-label', text: `${sheet.labels[index] ?? column}（${column}）` }));
      const editor = element('textarea', { className: 'phone-textarea phone-db-field-input' });
      editor.value = initial[index] ?? '';
      editor.rows = estimateRows(editor.value);
      editor.addEventListener('input', () => {
        editor.rows = estimateRows(editor.value);
      });
      editors.set(column, editor);
      field.append(editor);
      form.append(field);
    });
    return { form, read: () => Object.fromEntries([...editors].map(([column, editor]) => [column, editor.value])) };
  };

  const renderDetail = (sheet: SheetContent, rowId: number): void => {
    const row = sheet.rows.find((item) => item.rowId === rowId);
    if (!row) {
      browserView = { mode: 'list' };
      renderBody('');
      return;
    }
    body.append(backBar(`${sheet.sheet.name} · 行 #${rowId}`, () => {
      browserView = { mode: 'list' };
      renderBody('');
    }));
    const editor = renderEditor(sheet, row.values);
    body.append(editor.form);

    const actions = element('div', { className: 'phone-db-bottom-actions' });
    const save = button('保存修改', 'phone-button phone-button-primary', async () => {
      const values = editor.read();
      const changed = Object.fromEntries(
        sheet.columns.flatMap((column, index) => (values[column] === (row.values[index] ?? '') ? [] : [[column, values[column] ?? '']])),
      );
      if (Object.keys(changed).length === 0) {
        context.showNotice('没有需要保存的修改。', 'info');
        return;
      }
      save.disabled = true;
      try {
        const result = await context.dataCenter.updateRow(sheet.sheet.id, rowId, changed);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) {
          browserView = { mode: 'list' };
          await load();
        }
      } finally {
        save.disabled = false;
      }
    });
    const remove = button('删除本行', 'phone-button phone-button-danger', async () => {
      const confirmed = await context.showConfirm({
        title: '删除这一行？',
        message: `将从「${sheet.sheet.name}」删除行 #${rowId}，同时移除它的召回投影。此操作不可撤销。`,
        confirmLabel: '删除',
      });
      if (!confirmed) return;
      remove.disabled = true;
      try {
        const result = await context.dataCenter.deleteRow(sheet.sheet.id, rowId);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) {
          browserView = { mode: 'list' };
          await load();
        }
      } finally {
        remove.disabled = false;
      }
    });
    actions.append(save, remove);
    body.append(actions);
  };

  const renderAdd = (sheet: SheetContent): void => {
    body.append(backBar(`新增记录 · ${sheet.sheet.name}`, () => {
      browserView = { mode: 'list' };
      renderBody('');
    }));
    const editor = renderEditor(sheet, []);
    body.append(editor.form);
    const insert = button('插入新行', 'phone-button phone-button-primary', async () => {
      const values = Object.fromEntries(Object.entries(editor.read()).filter(([, value]) => value.trim()));
      if (Object.keys(values).length === 0) {
        context.showNotice('请至少填写一个字段。', 'info');
        return;
      }
      insert.disabled = true;
      try {
        const result = await context.dataCenter.insertRow(sheet.sheet.id, values);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) {
          browserView = { mode: 'list' };
          await load();
        }
      } finally {
        insert.disabled = false;
      }
    });
    const actions = element('div', { className: 'phone-db-bottom-actions' });
    actions.append(insert);
    body.append(actions);
  };

  void load();
  return section;
}

function backBar(title: string, onBack: () => void): HTMLElement {
  const bar = element('div', { className: 'phone-db-back-bar' });
  bar.append(
    button('← 返回', 'phone-button phone-button-secondary phone-button-compact', onBack),
    element('strong', { className: 'phone-db-back-title', text: title }),
  );
  return bar;
}

function toggleRow(label: string, hint: string, checked: boolean, onChange: (next: boolean) => void): HTMLElement {
  const row = element('label', { className: 'phone-checkbox-control' });
  const control = element('input', { attributes: { type: 'checkbox' } });
  control.checked = checked;
  control.addEventListener('change', () => onChange(control.checked));
  const copy = element('span');
  copy.append(element('strong', { text: label }), element('small', { text: hint }));
  row.append(control, copy);
  return row;
}

function numberRow(
  label: string,
  hint: string,
  value: number,
  range: { readonly min: number; readonly max: number },
  onCommit: (next: number) => void,
): HTMLElement {
  const wrapper = element('div', { className: 'phone-setting-block' });
  const row = element('label', { className: 'phone-setting-control' });
  row.append(element('span', { className: 'phone-control-label', text: label }));
  const control = element('input', {
    className: 'phone-number-input',
    attributes: { type: 'number', min: String(range.min), max: String(range.max), step: '1', inputmode: 'numeric' },
  });
  control.value = String(value);
  control.addEventListener('change', () => {
    const next = Number(control.value);
    if (Number.isFinite(next)) onCommit(Math.trunc(next));
  });
  row.append(control);
  wrapper.append(row, element('p', { className: 'phone-settings-hint', text: hint }));
  return wrapper;
}

/** 数据中心设置：启用开关、填表模型、记录节奏。 */
function renderSettingsSection(context: PhoneViewContext): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  const { settings, apiProfiles } = context.dataCenter;
  const update = async (patch: Parameters<typeof context.dataCenter.updateSettings>[0]): Promise<void> => {
    await context.dataCenter.updateSettings(patch);
  };

  const modelRow = element('label', { className: 'phone-db-field' });
  modelRow.append(element('span', { className: 'phone-control-label', text: '数据模型（填表用）' }));
  const modelSelect = element('select', { className: 'phone-input' });
  modelSelect.append(element('option', { text: apiProfiles.length > 0 ? '— 选择已保存的 API 配置 —' : '（请先在设置→API 配置里保存配置）' }));
  for (const profile of apiProfiles) {
    const option = element('option', { text: `${profile.name}（${profile.model || '未填模型'}）` });
    option.value = profile.name;
    if (settings.api.profileName === profile.name) option.selected = true;
    modelSelect.append(option);
  }
  modelSelect.addEventListener('change', () => {
    const profile = apiProfiles.find((item) => item.name === modelSelect.value);
    if (!profile) return;
    void update({
      api: {
        profileName: profile.name,
        baseUrl: profile.baseUrl,
        apiKey: profile.apiKey,
        model: profile.model,
        enabled: true,
      },
    });
  });
  modelRow.append(modelSelect, element('small', {
    className: 'phone-settings-hint',
    text: settings.api.model.trim()
      ? `当前模型：${settings.api.model}${settings.api.profileName ? `（${settings.api.profileName}）` : ''}`
      : '未选择模型时不会自动记录，但手动编辑表格仍可用。',
  }));

  const recordNow = button('立即记录一次', 'phone-button phone-button-primary', async () => {
    recordNow.disabled = true;
    try {
      const result = await context.dataCenter.recordNow();
      context.showNotice(result.message, result.ok ? 'success' : 'error');
    } finally {
      recordNow.disabled = false;
    }
  });
  const actions = element('div', { className: 'phone-settings-actions' });
  recordNow.disabled = !settings.enabled;
  actions.append(recordNow);

  section.append(
    element('h3', { className: 'phone-subsection-title', text: '数据中心设置' }),
    toggleRow('启用数据中心', '关闭时不会启动本地数据库、不记录表格、不注入召回内容。', settings.enabled, (enabled) => void update({ enabled })),
    modelRow,
    numberRow('每多少条 AI 回复记录一次', '达到该数量的新增 AI 楼层后调用填表模型。', settings.everyAiMessages, { min: 1, max: 100 }, (everyAiMessages) => void update({ everyAiMessages })),
    numberRow(
      '正文截断值（字）',
      '攒够楼层数后还要正文达到该字数才会调用填表模型；不足时这批楼层不消耗额度，会累积到下一轮一起记录。0 = 不限制；「立即记录一次」不受此限制。',
      settings.minContentChars,
      { min: 0, max: 20_000 },
      (minContentChars) => void update({ minContentChars }),
    ),
    toggleRow('本层不记录数据', '保留最新 AI 楼层，等下一层生成完成后再记录，避免重生成浪费额度。', settings.deferCurrentFloor, (deferCurrentFloor) => void update({ deferCurrentFloor })),
    numberRow('单轮 SQL 语句上限', '超出的语句会被丢弃；每条语句仍需通过安全闸门，未过闸的单条会被跳过并写进运行日志。', settings.maxStatements, { min: 1, max: 32 }, (maxStatements) => void update({ maxStatements })),
    actions,
  );
  return section;
}

/** 表格预设：选择当前使用哪一份（含内置默认表格）、导入新预设、移除已导入的预设。 */
function renderPresetSection(context: PhoneViewContext): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  const { settings } = context.dataCenter;
  const bundles = availablePresetBundles(settings.presetLibrary);
  const active = bundles.find((bundle) => bundle.id === settings.activePresetId) ?? null;
  const removable = settings.presetLibrary.some((bundle) => bundle.id === settings.activePresetId);

  const picker = element('label', { className: 'phone-db-field' });
  picker.append(element('span', { className: 'phone-control-label', text: '使用的表格预设' }));
  const select = element('select', { className: 'phone-select' });
  const options: (readonly [string, string])[] = [
    ['', '— 不使用预设（只用手动新建的表）—'],
    ...bundles.map((bundle) => [bundle.id, `${bundle.name}（${bundle.sheets.length} 张表）`] as const),
  ];
  for (const [value, label] of options) {
    const option = element('option', { text: label, attributes: { value } });
    option.selected = value === settings.activePresetId;
    select.append(option);
  }
  select.addEventListener('change', () => {
    activeSheetId = null;
    editingSheetId = null;
    browserView = { mode: 'list' };
    void context.dataCenter.updateSettings({ activePresetId: select.value });
  });
  picker.append(select);

  const actions = element('div', { className: 'phone-settings-actions' });
  actions.append(
    button('导入预设 / SQ 角色卡', 'phone-button phone-button-primary', async () => {
      const picked = await pickTextFile('application/json,.json');
      if (!picked) return;
      const result = await context.dataCenter.importPreset(picked.text, presetNameFromFile(picked.name));
      context.showNotice(result.message, result.ok ? 'success' : 'error');
    }),
  );
  if (context.dataCenter.importCurrentSqCard) actions.append(button('读取当前 SQ 角色卡', 'phone-button phone-button-secondary', async () => {
    const result = await context.dataCenter.importCurrentSqCard!();
    context.showNotice(result.message, result.ok ? 'success' : 'error');
  }));
  if (removable) {
    actions.append(button('移除所选预设', 'phone-button phone-button-danger-ghost', async () => {
      const confirmed = await context.showConfirm({
        title: `移除预设「${active?.name ?? ''}」？`,
        message: '只从预设库里移除这份预设，已经建好的表和其中的数据都会保留。',
        confirmLabel: '移除',
      });
      if (!confirmed) return;
      const result = await context.dataCenter.deletePreset(settings.activePresetId);
      context.showNotice(result.message, result.ok ? 'success' : 'error');
    }));
  }

  section.append(
    element('h3', { className: 'phone-subsection-title', text: '表格预设' }),
    element('p', {
      className: 'phone-settings-hint',
      text: '预设决定「自动建哪些表」。内置默认表格覆盖角色位置、剧情时间、时间跨度、角色任务与角色穿着；'
        + '也可以导入 SQ / ACU 角色卡、表格模板或本扩展预设。SQ 卡启用后，开局界面的数据接口会连接到数据中心。预设是全局的，各聊天的数据独立保存。',
    }),
    picker,
    element('p', {
      className: 'phone-settings-hint',
      text: active
        ? `当前使用：${active.name} · ${active.sheets.map((sheet) => sheet.name).join('、')}`
        : '当前不使用预设：不会自动建表，只保留你手动新建的表。',
    }),
    element('p', {
      className: 'phone-settings-hint',
      text: '每份预设保留独立的表格与剧情进度，切回即可继续使用。只有当前预设和手动建表参与填表与召回；删除的预设表不会自动重建。',
    }),
    actions,
  );
  return section;
}

/** 用文件名当预设包名称：同名文件重复导入会更新同一份预设，而不是不停新增。 */
function presetNameFromFile(fileName: string): string {
  return fileName.replace(/\.[^.]+$/, '').trim().slice(0, 60) || '导入的表格预设';
}

/** 引擎状态与表管理。 */
function renderEngineSection(context: PhoneViewContext): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  const statusLine = element('p', { className: 'phone-settings-hint', text: '正在检测本地记忆库…' });
  const sheetLines = element('div', { className: 'phone-db-cards' });
  let selectedSheet: SheetSummary | undefined;
  let refreshing = 0;

  const refresh = async (): Promise<void> => {
    const request = ++refreshing;
    const status = await context.dataCenter.inspect();
    if (request !== refreshing) return;
    selectedSheet = status.sheets.find((sheet) => sheet.id === activeSheetId) ?? status.sheets[0];
    activeSheetId = selectedSheet?.id ?? null;
    statusLine.textContent = `${status.description} · 召回单元 ${status.documentCount} 条（记忆库条目 ${status.memoryItemCount} 条）`;
    clear(sheetLines);
    for (const sheet of status.sheets) {
      const line = button('', 'phone-detail-line phone-db-record-card', () => {
        activeSheetId = sheet.id;
        selectedSheet = sheet;
        void refresh();
      });
      line.setAttribute('aria-pressed', String(sheet.id === selectedSheet?.id));
      line.append(
        element('span', { text: `${sheet.id === selectedSheet?.id ? '✓ ' : ''}${sheet.name}（${POLICY_LABELS[sheet.policy]}）` }),
        element('strong', { text: `${sheet.rowCount} 行 / 召回 ${sheet.documentCount}` }),
      );
      sheetLines.append(line);
    }
    if (status.sheets.length === 0) {
      sheetLines.append(element('p', { className: 'phone-settings-hint', text: '尚无表格。' }));
    }
  };

  const createSheet = async (): Promise<void> => {
    const values = await context.showModal('新建记忆表', [
      { name: 'name', label: '表名（中文可）', required: true, placeholder: '例如 人物关系' },
      { name: 'purpose', label: '用途说明（写给模型看）', required: true, placeholder: '记录角色之间的关系与好感度' },
      { name: 'columns', label: '列名（英文或拼音，逗号分隔）', required: true, placeholder: 'name,relation,summary' },
      {
        name: 'policy',
        label: '注入策略',
        type: 'select',
        value: 'recall',
        options: [
          ['recall', '按相关度召回（默认）'],
          ['always', '每轮整表注入（状态表）'],
          ['manual', '仅手动查询，不自动注入'],
        ],
      },
      { name: 'rowTemplate', label: '行模板（留空自动生成）', placeholder: '姓名={{name}}；关系={{relation}}' },
      {
        name: 'injectCondition',
        label: '注入条件（留空 = 每次都注入）',
        placeholder: 'sheets.剧情时间.first.时段 == \'夜晚\'',
      },
      {
        name: 'fillGuide',
        label: '填表规则（写给填表模型看，留空则没有额外规则）',
        placeholder: '好感度取值 0-100；姓名只读，不要写入。',
      },
    ]);
    if (!values) return;
    const columns = (values.columns ?? '').split(/[,，\s]+/).filter(Boolean);
    const result = await context.dataCenter.createSheet({
      name: values.name ?? '',
      purpose: values.purpose ?? '',
      columns,
      policy: normalizePolicy(values.policy ?? ''),
      rowTemplate: (values.rowTemplate ?? '').trim() || columns.map((column) => `${column}={{${column}}}`).join('；'),
      tokenBudget: DEFAULT_SHEET_TOKEN_BUDGET,
      injectCondition: (values.injectCondition ?? '').trim(),
      fillGuide: (values.fillGuide ?? '').trim(),
    });
    context.showNotice(result.message, result.ok ? 'success' : 'error');
    await refresh();
  };

  const actions = element('div', { className: 'phone-settings-actions' });
  actions.append(
    button('新建记忆表', 'phone-button phone-button-secondary', createSheet),
    button('删除当前表', 'phone-button phone-button-danger', async () => {
      const target = selectedSheet;
      if (!target) {
        context.showNotice('请先在上方选中一张表。', 'info');
        return;
      }
      const confirmed = await context.showConfirm({
        title: `删除「${target.name}」？`,
        message: '将删除这张表及其数据，并记录删除状态。刷新或重新选择预设后也不会自动重建。',
        confirmLabel: '删除',
      });
      if (!confirmed) return;
      const result = await context.dataCenter.dropSheet(target.id);
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) {
        activeSheetId = null;
        selectedSheet = undefined;
        if (editingSheetId === target.id) editingSheetId = null;
        browserView = { mode: 'list' };
      }
      await refresh();
    }),
    button('重建召回投影', 'phone-button phone-button-secondary', async () => {
      const result = await context.dataCenter.refreshProjections();
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      await refresh();
    }),
    button('导出 .sqlite3', 'phone-button phone-button-secondary', async () => {
      const result = await context.dataCenter.exportDatabase();
      context.showNotice(result.message, result.ok ? 'success' : 'error');
    }),
  );

  section.append(
    element('h3', { className: 'phone-subsection-title', text: '本地记忆库（SQLite）' }),
    statusLine,
    sheetLines,
    actions,
  );
  void refresh();
  return section;
}

/** 表格编辑入口：列出所有表，点击进入结构编辑。 */
function renderSchemaListSection(context: PhoneViewContext, onOpen: (sheetId: string) => void): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  const list = element('div', { className: 'phone-db-cards' });
  const refresh = async (): Promise<void> => {
    const status = await context.dataCenter.inspect();
    clear(list);
    if (status.sheets.length === 0) {
      list.append(element('p', { className: 'phone-settings-hint', text: '还没有表。先选择或导入表格预设，或手动新建记忆表。' }));
      return;
    }
    for (const sheet of status.sheets) {
      const card = button('', 'phone-db-record-card', () => onOpen(sheet.id));
      const head = element('div', { className: 'phone-db-record-head' });
      head.append(
        element('strong', { className: 'phone-db-record-title', text: sheet.name }),
        element('span', { className: 'phone-db-record-badge', text: POLICY_LABELS[sheet.policy] }),
        element('span', { className: 'phone-db-record-badge', text: `${sheet.rowCount} 行` }),
      );
      if (sheet.injectCondition.trim()) {
        head.append(element('span', { className: 'phone-db-record-badge', text: 'IF 条件' }));
      }
      card.append(head, element('p', {
        className: 'phone-db-record-preview',
        text: sheet.injectCondition.trim()
          ? `注入条件：${truncate(sheet.injectCondition, 60)}`
          : `${sheet.purpose} · 点击编辑表名、列、填表规则与注入策略`,
      }));
      list.append(card);
    }
  };
  section.append(
    element('h3', { className: 'phone-subsection-title', text: '表格编辑' }),
    element('p', {
      className: 'phone-settings-hint',
      text: '修改表结构会同步更新召回投影：改行模板会改变模型看到的文本，改策略会改变是否每轮注入，'
        + '配了「注入条件」的表则在条件不成立时整张缺席本轮注入。',
    }),
    list,
  );
  void refresh();
  return section;
}

/** 表结构编辑：元数据、填表操作规则、列的增删改与删除整表。 */
function renderSchemaEditor(context: PhoneViewContext, sheetId: string, onDeleted: () => void): HTMLElement {
  const section = element('section', { className: 'phone-database-browser' });
  const title = element('p', { className: 'phone-settings-hint', text: '正在读取表结构…' });
  const body = element('div', { className: 'phone-db-form' });
  section.append(title, body);

  const load = async (): Promise<void> => {
    const content = await context.dataCenter.readSheet(sheetId);
    clear(body);
    if (!content) {
      title.textContent = '这张表已不存在或本地记忆库不可用。';
      return;
    }
    const { sheet, columns, labels } = content;
    title.textContent = `${sheet.name} · ${columns.length} 列 · ${content.rows.length} 行 · 物理表 ${sheet.physicalName}`;

    const nameInput = textField('表名（中文可）', sheet.name);
    const purposeInput = textArea('用途说明（写给模型看）', sheet.purpose);
    const policySelect = element('select', { className: 'phone-select' });
    for (const [value, label] of [['recall', '按相关度召回'], ['always', '每轮整表注入'], ['manual', '仅手动查询']] as const) {
      const option = element('option', { text: label, attributes: { value } });
      option.selected = sheet.policy === value;
      policySelect.append(option);
    }
    const policyRow = element('label', { className: 'phone-setting-control' });
    policyRow.append(element('span', { className: 'phone-control-label', text: '注入策略' }), policySelect);
    const templateInput = textArea('行模板（`标签={{列名}}`，分号分隔）', sheet.rowTemplate);
    const conditionInput = textArea('注入条件（留空 = 每次都注入）', sheet.injectCondition);
    conditionInput.field.append(element('small', { className: 'phone-settings-hint', text: CONDITION_SYNTAX_HINT }));
    const rules = parseSheetRuleFields(sheet.fillGuide);
    const guideInput = textArea('通用填表规则', rules.general);
    guideInput.field.append(element('small', {
      className: 'phone-settings-hint',
      text: '填写适用于所有操作的要求。下面可分别编辑初始化、新增、更新和删除规则，保存后共同用于填表。',
    }));
    const operationInputs = SHEET_RULE_SECTIONS.map(({ key, label, hint }) => {
      const input = textArea(label, rules[key]);
      input.field.append(element('small', { className: 'phone-settings-hint', text: hint }));
      return { key, ...input };
    });

    const save = button('保存表设置', 'phone-button phone-button-primary', async () => {
      save.disabled = true;
      try {
        const result = await context.dataCenter.updateSheet(sheetId, {
          name: nameInput.control.value,
          purpose: purposeInput.control.value,
          policy: normalizePolicy(policySelect.value),
          rowTemplate: templateInput.control.value,
          tokenBudget: sheet.tokenBudget,
          injectCondition: conditionInput.control.value,
          fillGuide: composeSheetRuleFields({ ...rules, general: guideInput.control.value,
            ...Object.fromEntries(operationInputs.map((input) => [input.key, input.control.value])),
          }),
        });
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) await load();
      } finally {
        save.disabled = false;
      }
    });

    const columnList = element('div', { className: 'phone-db-cards' });
    columns.forEach((column, index) => {
      const row = element('div', { className: 'phone-db-record-card' });
      const editor = element('input', { className: 'phone-input', attributes: { type: 'text' } });
      editor.value = column;
      const actions = element('div', { className: 'phone-settings-actions' });
      actions.append(
        button('改名', 'phone-button phone-button-secondary phone-button-compact', async () => {
          const next = editor.value.trim();
          if (!next || next === column) {
            context.showNotice('请输入新的列名。', 'info');
            return;
          }
          const result = await context.dataCenter.renameColumn(sheetId, column, next);
          context.showNotice(result.message, result.ok ? 'success' : 'error');
          await load();
        }),
        button('删除', 'phone-button phone-button-danger phone-button-compact', async () => {
          const confirmed = await context.showConfirm({
            title: `删除列「${labels[index] ?? column}」？`,
            message: '该列的数据会随之消失，行模板里引用它的片段也会被移除。此操作不可撤销。',
            confirmLabel: '删除',
          });
          if (!confirmed) return;
          const result = await context.dataCenter.dropColumn(sheetId, column);
          context.showNotice(result.message, result.ok ? 'success' : 'error');
          await load();
        }),
      );
      row.append(
        element('div', { className: 'phone-db-record-head', text: `${labels[index] ?? column}（${column}）` }),
        editor,
        actions,
      );
      columnList.append(row);
    });

    const addName = textField('新增列名（英文或拼音）', '');
    const addLabel = textField('新增列的中文标签（可空）', '');
    const addColumn = button('新增列', 'phone-button phone-button-primary', async () => {
      const column = addName.control.value.trim();
      if (!column) {
        context.showNotice('请输入列名。', 'info');
        return;
      }
      const label = addLabel.control.value.trim();
      const result = await context.dataCenter.addColumn(sheetId, column, label || undefined);
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) await load();
    });

    const dangerActions = element('div', { className: 'phone-db-bottom-actions' });
    dangerActions.append(button('删除整张表', 'phone-button phone-button-danger', async () => {
      const confirmed = await context.showConfirm({
        title: `删除表「${sheet.name}」？`,
        message: '物理表、注册信息与召回投影都会被删除，此操作不可撤销。',
        confirmLabel: '删除',
      });
      if (!confirmed) return;
      const result = await context.dataCenter.dropSheet(sheetId);
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) onDeleted();
    }));

    const saveActions = element('div', { className: 'phone-settings-actions' });
    saveActions.append(save);
    const addActions = element('div', { className: 'phone-settings-actions' });
    addActions.append(addColumn);
    body.append(
      nameInput.field,
      purposeInput.field,
      policyRow,
      templateInput.field,
      conditionInput.field,
      element('h3', { className: 'phone-subsection-title', text: '填表规则' }),
      guideInput.field,
      ...operationInputs.map((input) => input.field),
      saveActions,
      element('h3', { className: 'phone-subsection-title', text: '列' }),
      columnList,
      addName.field,
      addLabel.field,
      addActions,
      dangerActions,
    );
  };

  void load();
  return section;
}

function textField(label: string, value: string, type = 'text'): {
  readonly field: HTMLElement;
  readonly control: HTMLInputElement;
} {
  const field = element('label', { className: 'phone-db-field' });
  field.append(element('span', { className: 'phone-control-label', text: label }));
  const control = element('input', { className: 'phone-input', attributes: { type } });
  control.value = value;
  field.append(control);
  return { field, control };
}

function textArea(label: string, value: string): {
  readonly field: HTMLElement;
  readonly control: HTMLTextAreaElement;
} {
  const field = element('label', { className: 'phone-db-field' });
  field.append(element('span', { className: 'phone-control-label', text: label }));
  const control = element('textarea', { className: 'phone-textarea phone-db-field-input' });
  control.value = value;
  control.rows = estimateRows(value);
  control.addEventListener('input', () => {
    control.rows = estimateRows(control.value);
  });
  field.append(control);
  return { field, control };
}

/**
 * 按内容长度撑开输入框：整页滚动已经承担长内容，
 * 输入框再自己滚动就会出现「小窗里翻内容、页面底部大片空白」。
 */
function estimateRows(value: string): number {
  const lines = value
    .split('\n')
    .reduce((total, line) => total + Math.max(1, Math.ceil(line.length / 26)), 0);
  return Math.min(20, Math.max(1, lines));
}

/** 过闸 SQL 控制台：单条语句，只允许命中已注册的 acu_u_ 表，支持 IF 前缀。 */
function renderSqlConsole(context: PhoneViewContext): HTMLElement {
  const section = element('section', { className: 'phone-database-browser' });
  const sqlResult = element('pre', { className: 'phone-database-pre', text: sqlOutcome });
  const sqlInput = element('textarea', {
    className: 'phone-textarea',
    attributes: {
      placeholder: '只能命中已注册的 acu_u_ 表，且只允许单条 SELECT/INSERT/UPDATE/DELETE；可写成 IF 条件 THEN 语句',
      maxlength: '2000',
    },
  });
  sqlInput.value = sqlDraft;
  sqlInput.addEventListener('input', () => {
    sqlDraft = sqlInput.value;
  });
  const runSql = button('执行', 'phone-button phone-button-primary', async () => {
    const sql = sqlInput.value.trim();
    if (!sql) return;
    runSql.disabled = true;
    try {
      const outcome = await context.dataCenter.runSql(sql);
      sqlOutcome = outcome.ok
        ? [outcome.message, formatRows(outcome.columns, outcome.rows)].filter(Boolean).join('\n\n')
        : `被拒绝或执行失败：${outcome.message}`;
      sqlResult.textContent = sqlOutcome;
      if (!outcome.ok) context.showNotice(outcome.message, 'error');
    } finally {
      runSql.disabled = false;
    }
  });
  const actions = element('div', { className: 'phone-settings-actions' });
  actions.append(runSql);
  section.append(
    element('h3', { className: 'phone-subsection-title', text: '过闸 SQL 控制台' }),
    element('p', { className: 'phone-settings-hint', text: `支持 IF 条件 THEN 语句：条件不成立时不执行。${CONDITION_SYNTAX_HINT}` }),
    sqlInput,
    actions,
    sqlResult,
  );
  return section;
}
