/** 聊天中的预设实例归属；保留未激活的数据，删除标记随聊天归档携带。 */
export interface PresetScopeState {
  readonly activeId?: string;
  readonly owners: Readonly<Record<string, string>>;
  readonly keys: Readonly<Record<string, string>>;
  readonly definitions: Readonly<Record<string, string>>;
  /** 各预设已经处理完的正文楼层；包括模型判断无需写入的批次。 */
  readonly recordFloors?: Readonly<Record<string, number>>;
  readonly deleted: Readonly<Record<string, readonly string[]>>;
  readonly hidden: readonly string[];
  readonly updatedAt: number;
}

export const LEGACY_PRESET_ID = 'builtin-preserved-tables';
export const EMPTY_PRESET_SCOPE: PresetScopeState = Object.freeze({ owners: {}, keys: {}, definitions: {}, deleted: {}, hidden: [], updatedAt: 0 });
export const presetScopeKey = (scopeId: string): string => `sheet_preset_scope:${scopeId}`;
export const sheetBackupPrefix = (scopeId: string): string => `sheet_schema_backup:${encodeURIComponent(scopeId)}:`;

function record(value: unknown): Record<string, unknown> {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : {};
}

function strings(value: unknown): Record<string, string> {
  return Object.fromEntries(Object.entries(record(value)).filter((entry): entry is [string, string] => typeof entry[1] === 'string'));
}

export function normalizePresetScopeState(value: unknown): PresetScopeState {
  const source = record(value);
  const recordFloors = Object.fromEntries(Object.entries(record(source.recordFloors))
    .filter((entry): entry is [string, number] => Number.isSafeInteger(entry[1]) && Number(entry[1]) >= -1));
  return {
    ...(typeof source.activeId === 'string' ? { activeId: source.activeId } : {}),
    owners: strings(source.owners), keys: strings(source.keys), definitions: strings(source.definitions),
    ...(Object.keys(recordFloors).length ? { recordFloors } : {}),
    deleted: Object.fromEntries(Object.entries(record(source.deleted)).map(([key, items]) => [key,
      Array.isArray(items) ? [...new Set(items.filter((item): item is string => typeof item === 'string'))] : [],
    ])),
    hidden: Array.isArray(source.hidden) ? source.hidden.filter((item): item is string => typeof item === 'string') : [],
    updatedAt: Number.isFinite(source.updatedAt) ? Number(source.updatedAt) : 0,
  };
}

export function presetScopeFingerprint(state: PresetScopeState): string {
  const sorted = <T>(value: Readonly<Record<string, T>>): readonly (readonly [string, T])[] => Object.entries(value).sort(([a], [b]) => a.localeCompare(b));
  return JSON.stringify([state.activeId, sorted(state.owners), sorted(state.keys), sorted(state.definitions),
    sorted(Object.fromEntries(Object.entries(state.deleted).map(([key, items]) => [key, [...items].sort()]))), [...state.hidden].sort(),
    ...(Object.keys(state.recordFloors ?? {}).length ? [sorted(state.recordFloors!)] : [])]);
}

export function sheetIsActive(id: string, state: PresetScopeState): boolean {
  return !state.hidden.includes(id) && (state.activeId === undefined || !Object.hasOwn(state.owners, id) || state.owners[id] === state.activeId);
}
