import { resolveStorySqlTableName } from '../db/story-sql.js';
import type { SqCompatibility } from './template.js';

/** 只改标识符；SQL 字符串中的表名、row_id 和 desc 原样保留。最终仍通过同一个 SQL 闸门。 */
export function resolveSqSql(sql: string, metadata: SqCompatibility | undefined, sheets: readonly { name: string; physicalName: string }[]): string {
  if (!metadata) return resolveStorySqlTableName(sql, sheets);
  const aliases = metadata.tables.flatMap((table) => {
    const sheet = sheets.find((sheet) => sheet.name === table.name);
    return sheet ? [...new Set([table.key, table.uid, table.name, table.sqlName])].map((name) => ({ name, physicalName: sheet.physicalName })) : [];
  });
  const resolved = resolveStorySqlTableName(sql, [...sheets, ...aliases.filter((alias) => !sheets.some((sheet) => sheet.name === alias.name))]);
  const target = /^(?:\s*(?:INSERT\s+(?:OR\s+\w+\s+)?INTO|UPDATE(?:\s+OR\s+\w+)?|DELETE\s+FROM)\s+)([A-Za-z_][A-Za-z0-9_]*)/i.exec(resolved)?.[1];
  const sheet = sheets.find((sheet) => sheet.physicalName === target);
  const table = metadata.tables.find((table) => table.name === sheet?.name);
  if (!table) return resolved;
  const columns = new Map(table.columns.map((column) => [column.sourceName.toLowerCase(), column.column]));
  columns.set('row_id', 'rowid');
  return resolved.replace(/'(?:''|[^'])*'|"(?:""|[^"])*"|`(?:``|[^`])*`|\[[^\]]*\]|[A-Za-z_][A-Za-z0-9_]*/g, (token, offset: number) => {
    if (token.startsWith("'")) return token;
    const quoted = /^["`\[]/.test(token);
    const name = quoted ? token.slice(1, -1) : token;
    const replacement = columns.get(name.toLowerCase());
    if (!replacement || replacement === name) return token;
    // ORDER BY x DESC 中的 DESC 是排序关键字，不能当成同名列。
    if (!quoted && name.toLowerCase() === 'desc') {
      const before = resolved.slice(0, offset).trimEnd();
      const previous = /([A-Za-z_][A-Za-z0-9_]*)$/.exec(before)?.[1]?.toUpperCase();
      if (previous && !['SET', 'WHERE', 'AND', 'OR', 'WHEN', 'BY', 'SELECT', 'THEN', 'ELSE', 'AS'].includes(previous)) return token;
    }
    return replacement;
  });
}
