import type { AppId, ConversationKind, PostKind } from '../domain/model.js';

export type AdapterFamily = 'tagged' | 'bracketed' | 'chat-app' | 'discord' | 'dsl';
export type AdapterSource = 'builtin' | 'card' | 'user';
/** 容器正文的组织方式：字段行、发言行、或整块 JSON。 */
export type AdapterBodyFormat = 'fields' | 'lines' | 'json';

/** 语义字段 → 卡内实际写法；解析时按顺序取第一个命中的键，缺省时回落到内置默认列表。 */
export interface AdapterFieldAliases {
  readonly author?: readonly string[];
  readonly account?: readonly string[];
  readonly title?: readonly string[];
  readonly content?: readonly string[];
  readonly board?: readonly string[];
  readonly time?: readonly string[];
  readonly tags?: readonly string[];
  readonly id?: readonly string[];
  readonly parentId?: readonly string[];
  readonly pinned?: readonly string[];
  readonly hot?: readonly string[];
  readonly views?: readonly string[];
  readonly likes?: readonly string[];
  readonly comments?: readonly string[];
  readonly reposts?: readonly string[];
  readonly favorites?: readonly string[];
}

export const ADAPTER_FIELD_ROLES = [
  'author', 'account', 'title', 'content', 'board', 'time', 'tags', 'id', 'parentId',
  'pinned', 'hot', 'views', 'likes', 'comments', 'reposts', 'favorites',
] as const;

export type AdapterFieldRole = typeof ADAPTER_FIELD_ROLES[number];

/** JSON 正文里帖子与评论数组的位置（点分路径），只在 body 为 json 时使用。 */
export interface AdapterJsonShape {
  readonly posts?: string;
  readonly comments?: string;
}

export interface FormatAdapter {
  readonly id: string;
  readonly family: AdapterFamily;
  readonly source: AdapterSource;
  readonly appId: AppId;
  readonly containers: readonly string[];
  readonly confidence: number;
  readonly conversationKind: ConversationKind;
  readonly postKind?: PostKind;
  /** 起止标记不成对时使用（如 `[论坛_始]` / `[论坛_末]`）；缺省时按 containers 的成对标签匹配。 */
  readonly open?: string;
  readonly close?: string;
  readonly body?: AdapterBodyFormat;
  readonly fieldAliases?: AdapterFieldAliases;
  /** 卡内发言人写法 → 规范名（`tuser` → `user`、`t诗诗` → `诗诗`）。 */
  readonly speakerAliases?: Readonly<Record<string, string>>;
  readonly json?: AdapterJsonShape;
}

export interface UserFormatAdapterInput {
  readonly family: AdapterFamily;
  readonly appId: AppId;
  readonly containers: readonly string[];
  readonly conversationKind: ConversationKind;
  readonly postKind?: PostKind;
  readonly open?: string;
  readonly close?: string;
  readonly body?: AdapterBodyFormat;
  readonly fieldAliases?: AdapterFieldAliases;
  readonly speakerAliases?: Readonly<Record<string, string>>;
  readonly json?: AdapterJsonShape;
}

const ADAPTER_FAMILIES = new Set<AdapterFamily>(['tagged', 'bracketed', 'chat-app', 'discord', 'dsl']);
const ADAPTER_BODY_FORMATS = new Set<AdapterBodyFormat>(['fields', 'lines', 'json']);
const ADAPTER_APP_IDS = new Set<AppId>(['wechat', 'forum', 'anonymous', 'twitter']);
const CONVERSATION_KINDS = new Set<ConversationKind>(['direct', 'group', 'anonymous']);
const POST_KINDS = new Set<PostKind>([
  'moment', 'forum-thread', 'forum-reply', 'twitter-post', 'twitter-reply', 'twitter-repost',
]);
const CONTAINER_PATTERN = /^[A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5-]{0,31}$/u;
/** 起止标记允许中英文、数字与常见包裹符号，长度受限以免把整段正文当标记。 */
const MARKER_PATTERN = /^[^\s\n\r]{2,48}$/u;
const MAX_ALIASES_PER_ROLE = 8;
const MAX_ALIAS_LENGTH = 40;
const MAX_SPEAKER_ALIASES = 24;
const MAX_JSON_PATH_LENGTH = 64;

export function createUserFormatAdapter(input: UserFormatAdapterInput): FormatAdapter {
  const containers = normalizeContainers(input.containers);
  if (containers.length === 0) throw new Error('手动适配器至少需要一个合法容器名。');
  const semantics = normalizeUserAdapterSemantics(input);
  const markers = normalizeMarkers(input.open, input.close);
  const fieldAliases = normalizeFieldAliases(input.fieldAliases);
  const speakerAliases = normalizeSpeakerAliases(input.speakerAliases);
  const json = normalizeJsonShape(input.json);
  const signature = [
    semantics.family,
    semantics.appId,
    semantics.conversationKind,
    semantics.postKind ?? '',
    semantics.body ?? '',
    markers.open ?? '',
    markers.close ?? '',
    JSON.stringify(fieldAliases ?? {}),
    JSON.stringify(speakerAliases ?? {}),
    JSON.stringify(json ?? {}),
    ...containers.map(normalizeContainer).sort(),
  ].join('|');
  return {
    id: `user.${semantics.appId}.${semantics.family}.${stableHash(signature)}`,
    family: semantics.family,
    source: 'user',
    appId: semantics.appId,
    containers,
    confidence: 1,
    conversationKind: semantics.conversationKind,
    ...(semantics.postKind ? { postKind: semantics.postKind } : {}),
    ...(markers.open ? { open: markers.open } : {}),
    ...(markers.close ? { close: markers.close } : {}),
    ...(semantics.body ? { body: semantics.body } : {}),
    ...(fieldAliases ? { fieldAliases } : {}),
    ...(speakerAliases ? { speakerAliases } : {}),
    ...(json ? { json } : {}),
  };
}

export function normalizeUserFormatAdapters(value: unknown): readonly FormatAdapter[] {
  if (!Array.isArray(value)) return [];
  const adapters = new Map<string, FormatAdapter>();
  for (const entry of value) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) continue;
    const record = entry as Record<string, unknown>;
    const family = String(record.family ?? '') as AdapterFamily;
    const appId = String(record.appId ?? '') as AppId;
    const conversationKind = String(record.conversationKind ?? '') as ConversationKind;
    const postKind = String(record.postKind ?? '') as PostKind;
    const body = String(record.body ?? '') as AdapterBodyFormat;
    if (!ADAPTER_FAMILIES.has(family) || !ADAPTER_APP_IDS.has(appId) || !CONVERSATION_KINDS.has(conversationKind)) continue;
    const containers = Array.isArray(record.containers)
      ? record.containers.map(String)
      : [String(record.container ?? '')];
    try {
      const adapter = createUserFormatAdapter({
        family,
        appId,
        conversationKind,
        containers,
        ...(POST_KINDS.has(postKind) ? { postKind } : {}),
        ...(ADAPTER_BODY_FORMATS.has(body) ? { body } : {}),
        ...(typeof record.open === 'string' ? { open: record.open } : {}),
        ...(typeof record.close === 'string' ? { close: record.close } : {}),
        ...(record.fieldAliases ? { fieldAliases: record.fieldAliases as AdapterFieldAliases } : {}),
        ...(record.speakerAliases ? { speakerAliases: record.speakerAliases as Readonly<Record<string, string>> } : {}),
        ...(record.json ? { json: record.json as AdapterJsonShape } : {}),
      });
      adapters.set(adapter.id, adapter);
      if (adapters.size >= 30) break;
    } catch {
      // 忽略损坏或不受支持的用户容器配置。
    }
  }
  return [...adapters.values()];
}

export function isFormatAdapterEnabled(
  adapter: FormatAdapter,
  overrides: Readonly<Record<string, boolean>> = {},
): boolean {
  return overrides[adapter.id] !== false;
}

function normalizeUserAdapterSemantics(input: UserFormatAdapterInput): UserFormatAdapterInput {
  if (!ADAPTER_FAMILIES.has(input.family) || !ADAPTER_APP_IDS.has(input.appId) || !CONVERSATION_KINDS.has(input.conversationKind)) {
    throw new Error('手动适配器的语法族、目标 App 或会话类型无效。');
  }
  if (input.postKind !== undefined && !POST_KINDS.has(input.postKind)) {
    throw new Error('手动适配器的帖子类型无效。');
  }
  if (input.body !== undefined && !ADAPTER_BODY_FORMATS.has(input.body)) {
    throw new Error('手动适配器的正文组织方式无效。');
  }
  return input;
}

/** 起止标记必须成对出现，否则无法界定容器范围。 */
function normalizeMarkers(
  open: string | undefined,
  close: string | undefined,
): { readonly open?: string; readonly close?: string } {
  const openMarker = String(open ?? '').trim();
  const closeMarker = String(close ?? '').trim();
  if (!openMarker && !closeMarker) return {};
  if (!MARKER_PATTERN.test(openMarker) || !MARKER_PATTERN.test(closeMarker)) {
    throw new Error('起止标记必须成对提供，且不能包含空白或超过 48 字。');
  }
  if (normalizeContainer(openMarker) === normalizeContainer(closeMarker)) {
    throw new Error('起始标记与结束标记不能相同。');
  }
  return { open: openMarker, close: closeMarker };
}

function normalizeFieldAliases(value: AdapterFieldAliases | undefined): AdapterFieldAliases | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const source = value as Record<string, unknown>;
  const result: Record<string, readonly string[]> = {};
  for (const role of ADAPTER_FIELD_ROLES) {
    const raw = source[role];
    if (!Array.isArray(raw)) continue;
    const names = [...new Set(raw
      .map((name) => String(name ?? '').trim())
      .filter((name) => name.length > 0 && name.length <= MAX_ALIAS_LENGTH))]
      .slice(0, MAX_ALIASES_PER_ROLE);
    if (names.length > 0) result[role] = names;
  }
  return Object.keys(result).length > 0 ? result as AdapterFieldAliases : undefined;
}

function normalizeSpeakerAliases(
  value: Readonly<Record<string, string>> | undefined,
): Readonly<Record<string, string>> | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const result: Record<string, string> = {};
  for (const [key, name] of Object.entries(value)) {
    const alias = String(key ?? '').trim();
    const canonical = String(name ?? '').trim();
    if (!alias || !canonical || alias.length > MAX_ALIAS_LENGTH || canonical.length > MAX_ALIAS_LENGTH) continue;
    result[alias] = canonical;
    if (Object.keys(result).length >= MAX_SPEAKER_ALIASES) break;
  }
  return Object.keys(result).length > 0 ? result : undefined;
}

function normalizeJsonShape(value: AdapterJsonShape | undefined): AdapterJsonShape | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const source = value as Record<string, unknown>;
  const posts = normalizeJsonPath(source.posts);
  const comments = normalizeJsonPath(source.comments);
  if (!posts && !comments) return undefined;
  return {
    ...(posts ? { posts } : {}),
    ...(comments ? { comments } : {}),
  };
}

function normalizeJsonPath(value: unknown): string {
  const path = String(value ?? '').trim();
  if (!path || path.length > MAX_JSON_PATH_LENGTH) return '';
  return /^[A-Za-z_$][\w$]*(?:\.[A-Za-z_$][\w$]*)*$/.test(path) ? path : '';
}

function normalizeContainers(values: readonly string[]): readonly string[] {
  const result = new Map<string, string>();
  for (const value of values) {
    const container = String(value ?? '').trim();
    if (!CONTAINER_PATTERN.test(container)) continue;
    result.set(normalizeContainer(container), container);
  }
  return [...result.values()];
}

function stableHash(value: string): string {
  let hash = 2_166_136_261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16_777_619);
  }
  return (hash >>> 0).toString(36);
}

