export function adapterForContainer(
  adapters: readonly FormatAdapter[],
  container: string,
): FormatAdapter | null {
  const normalized = normalizeContainer(container);
  return adapters.find((adapter) => adapter.containers.some((name) => normalizeContainer(name) === normalized)) ?? null;
}

export function normalizeContainer(value: string): string {
  return value.trim().toLocaleLowerCase('zh-CN').replace(/[\s_-]+/g, '');
}

export function mergeFormatAdapters(
  discovered: readonly FormatAdapter[] = [],
  user: readonly FormatAdapter[] = [],
): readonly FormatAdapter[] {
  const result = new Map<string, FormatAdapter>();
  for (const adapter of [...BUILTIN_FORMAT_ADAPTERS, ...discovered, ...user]) {
    result.set(adapter.id, adapter);
  }
  return [...result.values()].sort((left, right) => right.confidence - left.confidence);
}