import type {
  DbRow,
  DbStatement,
  EngineStatus,
  ExecuteResult,
  ExportResult,
  SearchResult,
  SearchRow,
  SqliteGateway,
} from './protocol.js';
import { buildClothingConsistencyStatements } from './state-consistency.js';
import { SqliteClient } from './client.js';
import { encodeAuditParams } from './sql-guard.js';
import { quoteIdentifier, sheetColumnNames, type SheetDefinition, type SheetPolicy } from './sheet-dsl.js';
import { normalizePresetScopeState, presetScopeKey, sheetIsActive, type PresetScopeState } from './preset-state.js';
import { writeSheetMetaStatement } from './sheet-transaction.js';

export interface SqliteMemoryDocumentInput {
  readonly scopeId: string;
  readonly kind: string;
  readonly sheetId?: string;
  readonly rowKey?: string;
  readonly text: string;
  readonly importance?: number;
  readonly pinned?: boolean;
  readonly validFrom?: number;
  readonly validTo?: number;
  readonly tokens?: number;
  readonly hash: string;
  readonly updatedAt?: number;
}

/** `sheet` 注册表中的一行；界面与召回都只读取这些字段。 */
export interface SheetRecord {
  readonly id: string;
  readonly scopeId: string;
  readonly name: string;
  readonly purpose: string;
  readonly physicalName: string;
  readonly ddl: string;
  readonly policy: SheetPolicy;
  readonly rowTemplate: string;
  readonly tokenBudget: number;
  readonly orderNo: number;
  readonly updatedAt: number;
  /** 注入条件（IF 语法的表达式部分）；空串表示无条件。 */
  readonly injectCondition: string;
  /** 这张表的填表规则；随表结构一起进填表提示词。空串表示没有额外规则。 */
  readonly fillGuide: string;
}

/** 已落库的召回单元；`mem_doc` 的读取投影。 */
export interface MemoryDocumentRecord {
  readonly id: number;
  readonly sheetId: string | null;
  readonly rowKey: string | null;
  readonly text: string;
  readonly tokens: number;
  readonly importance: number;
  readonly pinned: boolean;
  readonly updatedAt: number;
}

/** 投影同步输入：事实源（`PhoneState` 或用户物理表）渲染后的召回单元。 */
export interface MemoryDocumentProjection {
  readonly text: string;
  readonly hash: string;
  readonly sheetId?: string;
  readonly rowKey?: string;
  readonly importance?: number;
  readonly pinned?: boolean;
  readonly tokens?: number;
  readonly validFrom?: number;
  readonly validTo?: number;
  readonly updatedAt?: number;
}

export interface ProjectionSyncReport {
  readonly kind: string;
  readonly added: number;
  readonly removed: number;
  readonly kept: number;
}

/** 按作用域前缀清理后的统计：删掉的注册表数、召回单元数与审计条目数。 */
export interface ScopePurgeReport {
  readonly sheets: number;
  readonly documents: number;
  readonly auditEntries: number;
}

function escapeLikePattern(value: string): string {
  return value.replaceAll('\\', '\\\\').replaceAll('%', '\\%').replaceAll('_', '\\_');
}

/** 快照里的单元格：用户表列一律 TEXT，加上 rowid 的数字，可安全 JSON 化。 */
export type SnapshotCell = string | number | null;
export type SnapshotRow = Readonly<Record<string, SnapshotCell>>;

/** 表级前像：物理表名 → 全量行（含 rowid），楼层回撤时按它覆盖回去。 */
export type SheetSnapshot = Readonly<Record<string, readonly SnapshotRow[]>>;

function snapshotCell(value: unknown): SnapshotCell {
  if (value === null || value === undefined) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (typeof value === 'string') return value;
  if (typeof value === 'bigint' || typeof value === 'boolean') return String(value);
  return null;
}

function parseSnapshot(raw: string): SheetSnapshot {
  if (!raw.trim()) return {};
  try {
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null || Array.isArray(parsed)) return {};
    const snapshot: Record<string, readonly SnapshotRow[]> = {};
    for (const [table, rows] of Object.entries(parsed as Record<string, unknown>)) {
      if (!Array.isArray(rows)) continue;
      snapshot[table] = rows.flatMap((row): readonly SnapshotRow[] => {
        if (typeof row !== 'object' || row === null || Array.isArray(row)) return [];
        return [Object.fromEntries(
          Object.entries(row as Record<string, unknown>).map(([column, value]) => [column, snapshotCell(value)]),
        )];
      });
    }
    return snapshot;
  } catch {
    return {};
  }
}

export interface SqliteMemoryStoreOptions {
  readonly gateway?: SqliteGateway;
}

/** 注册表可更新字段；`ddl` 只在结构变更时由引擎重新生成后写入。 */
export interface SheetRegistryPatch {
  readonly name?: string;
  readonly purpose?: string;
  readonly policy?: SheetPolicy;
  readonly rowTemplate?: string;
  readonly tokenBudget?: number;
  readonly ddl?: string;
  readonly injectCondition?: string;
  readonly fillGuide?: string;
}

function text(value: unknown): string {
  return typeof value === 'string' ? value : '';
}

function integer(value: unknown): number {
  return typeof value === 'number' && Number.isFinite(value) ? value : Number(value ?? 0) || 0;
}

function nullableText(value: unknown): string | null {
  return typeof value === 'string' ? value : null;
}

function sheetPolicy(value: unknown): SheetPolicy {
  return value === 'always' || value === 'manual' ? value : 'recall';
}

function toSheetRecord(row: DbRow): SheetRecord {
  return {
    id: text(row.id),
    scopeId: text(row.scope_id),
    name: text(row.name),
    purpose: text(row.purpose),
    physicalName: text(row.physical_name),
    ddl: text(row.ddl),
    policy: sheetPolicy(row.policy),
    rowTemplate: text(row.row_template),
    tokenBudget: integer(row.token_budget),
    orderNo: integer(row.order_no),
    updatedAt: integer(row.updated_at),
    injectCondition: text(row.inject_condition),
    fillGuide: text(row.fill_guide),
  };
}

function toDocumentRecord(row: DbRow): MemoryDocumentRecord {
  return {
    id: integer(row.id),
    sheetId: nullableText(row.sheet_id),
    rowKey: nullableText(row.row_key),
    text: text(row.text),
    tokens: integer(row.tokens),
    importance: integer(row.importance),
    pinned: integer(row.pinned) === 1,
    updatedAt: integer(row.updated_at),
  };
}

/** 行级编辑需要隐式 rowid 定位；用固定别名避免与用户列重名。 */
export const ROW_ID_ALIAS = '__rowid';

/** 单个作用域保留的审计条目上限；超出的旧记录连同其前像一起清理。 */
const AUDIT_LOG_RETENTION = 500;

const INSERT_DOCUMENT_SQL = `
  INSERT INTO mem_doc(
    scope_id, kind, sheet_id, row_key, text, importance, pinned, valid_from, valid_to, tokens, hash, updated_at
  ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
`;

function documentInsertParams(
  scopeId: string,
  kind: string,
  document: MemoryDocumentProjection,
  fallbackUpdatedAt: number,
): readonly (string | number | null)[] {
  return [
    scopeId,
    kind,
    document.sheetId ?? null,
    document.rowKey ?? null,
    document.text,
    document.importance ?? 0,
    document.pinned === true ? 1 : 0,
    document.validFrom ?? null,
    document.validTo ?? null,
    document.tokens ?? 0,
    document.hash,
    document.updatedAt ?? fallbackUpdatedAt,
  ];
}

/**
 * SQLite 记忆子系统的数据访问层：只做 SQL 与行投影，不做策略决策与预算装配。
 * 所有方法都要求调用方已经通过 `open()` 确认引擎可用。
 */
export class SqliteMemoryStore {
  readonly #gateway: SqliteGateway;
  #assertAccess: () => void = () => undefined;
  #closed = false;
  #closing: Promise<void> | null = null;

  constructor(options: SqliteMemoryStoreOptions = {}) {
    const assertAccess = (): void => {
      this.#assertAccess();
      if (this.#closed) throw new Error('数据中心连接已关闭，本次操作已中止。');
    };
    const gateway = options.gateway ?? new SqliteClient({ assertAccess });
    const guarded = async <T>(run: () => Promise<T>): Promise<T> => {
      assertAccess();
      return run();
    };
    this.#gateway = {
      open: () => guarded(() => gateway.open()),
      status: () => guarded(() => gateway.status()),
      execute: (statement) => guarded(() => gateway.execute(statement)),
      transaction: (statements) => guarded(() => gateway.transaction(statements)),
      search: (scopeId, query, limit) => guarded(() => gateway.search(scopeId, query, limit)),
      exportDatabase: () => guarded(() => gateway.exportDatabase()),
      close: () => gateway.close(),
    };
  }

  /** 引擎创建连接时绑定访问期；连接内每次 SQL 调用都复查，不会被重新启用激活。 */
  setAccessGuard(assertAccess: () => void): void {
    this.#assertAccess = assertAccess;
  }

  /** 仅接受引擎校验后的 SELECT；查询不写审计、不刷新投影。 */
  async query(statement: DbStatement): Promise<ExecuteResult> {
    return this.#gateway.execute(statement);
  }

  async open(): Promise<EngineStatus> {
    return this.#gateway.open();
  }

  async status(): Promise<EngineStatus> {
    return this.#gateway.status();
  }

  async registerSheet(sheet: SheetDefinition): Promise<void> {
    await this.#gateway.transaction([
      { sql: sheet.ddl },
      {
        sql: `
          INSERT INTO sheet(
            id, scope_id, name, purpose, physical_name, ddl, policy, row_template, token_budget, order_no, updated_at,
            inject_condition, fill_guide
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
          ON CONFLICT(id) DO UPDATE SET
            scope_id = excluded.scope_id,
            name = excluded.name,
            purpose = excluded.purpose,
            physical_name = excluded.physical_name,
            ddl = excluded.ddl,
            policy = excluded.policy,
            row_template = excluded.row_template,
            token_budget = excluded.token_budget,
            order_no = excluded.order_no,
            updated_at = excluded.updated_at,
            inject_condition = excluded.inject_condition,
            fill_guide = excluded.fill_guide
        `,
        params: [
          sheet.id,
          sheet.scopeId,
          sheet.name,
          sheet.purpose,
          sheet.physicalName,
          sheet.ddl,
          sheet.policy,
          sheet.rowTemplate,
          sheet.tokenBudget,
          sheet.orderNo,
          sheet.updatedAt,
          sheet.injectCondition,
          sheet.fillGuide,
        ],
      },
    ]);
  }

  async listSheets(scopeId: string, includeInactive = false): Promise<readonly SheetRecord[]> {
    const result = await this.#gateway.execute({
      sql: 'SELECT * FROM sheet WHERE scope_id = ? ORDER BY order_no, name',
      params: [scopeId],
    });
    const sheets = result.rows.map(toSheetRecord);
    if (includeInactive) return sheets;
    const state = await this.readPresetState(scopeId);
    return sheets.filter((sheet) => sheetIsActive(sheet.id, state));
  }

  async readPresetState(scopeId: string): Promise<PresetScopeState> {
    const raw = await this.readMeta(presetScopeKey(scopeId));
    return normalizePresetScopeState(raw ? JSON.parse(raw) : null);
  }

  /** 内部迁移计划；调用方先完成所有校验，再一次提交。 */
  async commitSheetPlan(statements: readonly DbStatement[]): Promise<void> {
    if (statements.length) await this.#gateway.transaction(statements);
  }

  async readMetaPrefix(prefix: string): Promise<Readonly<Record<string, string>>> {
    const result = await this.#gateway.execute({
      sql: "SELECT key, value FROM sys_meta WHERE key LIKE ? ESCAPE '\\' ORDER BY key",
      params: [`${escapeLikePattern(prefix)}%`],
    });
    return Object.fromEntries(result.rows.map((row) => [text(row.key), text(row.value)]));
  }

  /** `sys_meta` 是引擎自用的键值位；跨设备归档指纹存在这里，随库一起持久化。 */
  async readMeta(key: string): Promise<string | null> {
    const result = await this.#gateway.execute({
      sql: 'SELECT value FROM sys_meta WHERE key = ?',
      params: [key],
    });
    return nullableText(result.rows[0]?.value);
  }

  async writeMeta(key: string, value: string): Promise<void> {
    await this.#gateway.execute({
      sql: 'INSERT INTO sys_meta(key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value',
      params: [key, value],
    });
  }

  async upsertDocument(input: SqliteMemoryDocumentInput): Promise<void> {
    if (!input.scopeId.trim() || !input.kind.trim() || !input.text.trim() || !input.hash.trim()) {
      throw new Error('SQLite 记忆文档需要 scopeId、kind、text 和 hash');
    }
    const params = documentInsertParams(
      input.scopeId,
      input.kind,
      { ...input, text: input.text.trim() },
      Date.now(),
    );
    if (input.sheetId !== undefined && input.rowKey !== undefined) {
      await this.#gateway.execute({
        sql: `
          ${INSERT_DOCUMENT_SQL}
          ON CONFLICT(scope_id, sheet_id, row_key) WHERE sheet_id IS NOT NULL AND row_key IS NOT NULL DO UPDATE SET
            kind = excluded.kind,
            text = excluded.text,
            importance = excluded.importance,
            pinned = excluded.pinned,
            valid_from = excluded.valid_from,
            valid_to = excluded.valid_to,
            tokens = excluded.tokens,
            hash = excluded.hash,
            updated_at = excluded.updated_at
        `,
        params,
      });
      return;
    }
    await this.#gateway.execute({ sql: INSERT_DOCUMENT_SQL, params });
  }

  /**
   * 按 `kind` 把一组文档同步成该 scope 的完整投影：缺失的插入、已消失的删除、同 hash 重复的收敛为一行。
   * 事实源在别处（`PhoneState` 或用户物理表），所以以 hash 差集为准，可以反复执行。
   */
  async syncDocuments(
    scopeId: string,
    kind: string,
    documents: readonly MemoryDocumentProjection[],
  ): Promise<ProjectionSyncReport> {
    if (!scopeId.trim() || !kind.trim()) throw new Error('SQLite 投影同步需要 scopeId 和 kind');
    const existing = await this.#gateway.execute({
      sql: 'SELECT id, hash FROM mem_doc WHERE scope_id = ? AND kind = ? ORDER BY id',
      params: [scopeId, kind],
    });
    const existingIds = new Map<string, number[]>();
    for (const row of existing.rows) {
      const hash = text(row.hash);
      if (!hash) continue;
      const ids = existingIds.get(hash);
      if (ids) ids.push(integer(row.id));
      else existingIds.set(hash, [integer(row.id)]);
    }

    const wanted = new Map<string, MemoryDocumentProjection>();
    for (const document of documents) {
      const body = document.text.trim();
      if (!body || !document.hash.trim() || wanted.has(document.hash)) continue;
      wanted.set(document.hash, { ...document, text: body });
    }

    const now = Date.now();
    const statements: DbStatement[] = [];
    const staleIds: number[] = [];
    for (const [hash, ids] of existingIds) {
      if (wanted.has(hash)) staleIds.push(...ids.slice(1));
      else staleIds.push(...ids);
    }
    // 先删后插：行内容变化时 row_key 不变，唯一索引要求旧行先离开。
    if (staleIds.length > 0) {
      statements.push({
        sql: `DELETE FROM mem_doc WHERE id IN (${staleIds.map(() => '?').join(', ')})`,
        params: staleIds,
      });
    }
    for (const [hash, document] of wanted) {
      if (existingIds.has(hash)) continue;
      statements.push({ sql: INSERT_DOCUMENT_SQL, params: documentInsertParams(scopeId, kind, document, now) });
    }
    if (statements.length > 0) await this.#gateway.transaction(statements);

    const added = wanted.size - [...wanted.keys()].filter((hash) => existingIds.has(hash)).length;
    return { kind, added, removed: staleIds.length, kept: wanted.size - added };
  }

  /** `policy='always'` 的表行：整表注入的候选，按表顺序返回。 */
  async listAlwaysDocuments(scopeId: string, limit = 200): Promise<readonly MemoryDocumentRecord[]> {
    const result = await this.#gateway.execute({
      sql: `
        SELECT d.id, d.sheet_id, d.row_key, d.text, d.tokens, d.importance, d.pinned, d.updated_at
        FROM mem_doc AS d
        JOIN sheet AS s ON s.id = d.sheet_id
        WHERE d.scope_id = ? AND s.policy = 'always'
        ORDER BY s.order_no, s.name, d.row_key, d.id
        LIMIT ?
      `,
      params: [scopeId, Math.max(1, Math.min(1_000, Math.trunc(limit)))],
    });
    return result.rows.map(toDocumentRecord);
  }

  /** 用户物理表的行数；表名先过标识符校验。 */
  async countSheetRows(sheet: SheetRecord): Promise<number> {
    const result = await this.#gateway.execute({
      sql: `SELECT COUNT(*) AS count FROM ${quoteIdentifier(sheet.physicalName)}`,
    });
    return integer(result.rows[0]?.count);
  }

  /** 某 scope（可选限定 kind）下的召回单元数量。 */
  async countDocuments(scopeId: string, kind?: string): Promise<number> {
    const result = await this.#gateway.execute({
      sql: kind === undefined
        ? 'SELECT COUNT(*) AS count FROM mem_doc WHERE scope_id = ?'
        : 'SELECT COUNT(*) AS count FROM mem_doc WHERE scope_id = ? AND kind = ?',
      params: kind === undefined ? [scopeId] : [scopeId, kind],
    });
    return integer(result.rows[0]?.count);
  }

  async search(scopeId: string, query: string, limit = 20): Promise<SearchResult> {
    return this.#gateway.search(scopeId, query, limit);
  }

  /** 批量写入用户表行（预设导入路径）：列名过标识符校验，值全部参数化。 */
  async insertSheetRows(
    sheet: Pick<SheetRecord, 'physicalName'> & Partial<Pick<SheetRecord, 'ddl' | 'rowTemplate'>>,
    columns: readonly string[],
    rows: readonly (readonly string[])[],
  ): Promise<number> {
    if (columns.length === 0 || rows.length === 0) return 0;
    const sql = `INSERT INTO ${quoteIdentifier(sheet.physicalName)}(${columns.map(quoteIdentifier).join(', ')}) VALUES (${columns.map(() => '?').join(', ')})`;
    await this.#gateway.transaction([...rows.map((row) => ({
      sql,
      params: columns.map((_, index) => row[index] ?? ''),
    })), ...(sheet.ddl && sheet.rowTemplate ? buildClothingConsistencyStatements([sheet as SheetRecord]) : [])]);
    return rows.length;
  }

  /** 读取某张用户物理表的全部行（带隐式 rowid，供行级编辑定位）；表名先过标识符校验。 */
  async readSheetRows(sheet: SheetRecord, limit = 2_000): Promise<readonly DbRow[]> {
    const result = await this.#gateway.execute({
      sql: `SELECT rowid AS ${ROW_ID_ALIAS}, * FROM ${quoteIdentifier(sheet.physicalName)} ORDER BY rowid LIMIT ?`,
      params: [Math.max(1, Math.min(10_000, Math.trunc(limit)))],
    });
    return result.rows;
  }

  /** 迁移、归档与投影读取全量行；界面分页上限不适用于事实数据。 */
  async readAllSheetRows(sheet: SheetRecord): Promise<readonly DbRow[]> {
    return (await this.#gateway.execute({
      sql: `SELECT rowid AS ${ROW_ID_ALIAS}, * FROM ${quoteIdentifier(sheet.physicalName)} ORDER BY rowid`,
    })).rows;
  }

  /** 按 rowid 更新一行的部分列；列名过标识符校验，值全部参数化。 */
  async updateSheetRow(
    sheet: Pick<SheetRecord, 'physicalName'> & Partial<Pick<SheetRecord, 'ddl' | 'rowTemplate'>>,
    rowId: number,
    values: Readonly<Record<string, string>>,
  ): Promise<number> {
    const columns = Object.keys(values);
    if (columns.length === 0) return 0;
    const assignments = columns.map((column) => `${quoteIdentifier(column)} = ?`).join(', ');
    const results = await this.#gateway.transaction([{
      sql: `UPDATE ${quoteIdentifier(sheet.physicalName)} SET ${assignments} WHERE rowid = ?`,
      params: [...columns.map((column) => values[column] ?? ''), rowId],
    }, ...(sheet.ddl && sheet.rowTemplate ? buildClothingConsistencyStatements([sheet as SheetRecord]) : [])]);
    return results[0]?.changes ?? 0;
  }

  async deleteSheetRow(sheet: Pick<SheetRecord, 'physicalName'>, rowId: number): Promise<number> {
    const result = await this.#gateway.execute({
      sql: `DELETE FROM ${quoteIdentifier(sheet.physicalName)} WHERE rowid = ?`,
      params: [rowId],
    });
    return result.changes;
  }

  /** 某个作用域前缀下的全部注册表（跨 scope 维护用，例如清理瞬态作用域）。 */
  async listSheetsByScopePrefix(prefix: string): Promise<readonly SheetRecord[]> {
    if (!prefix.trim()) throw new Error('作用域前缀不能为空');
    const result = await this.#gateway.execute({
      sql: "SELECT * FROM sheet WHERE scope_id LIKE ? ESCAPE '\\' ORDER BY scope_id, order_no, name",
      params: [`${escapeLikePattern(prefix)}%`],
    });
    return result.rows.map(toSheetRecord);
  }

  /**
   * 清理某个作用域前缀下的一切：物理表、注册行、召回投影与审计日志，单事务提交。
   * 只用于永远不会再被访问的瞬态作用域；真实聊天的表必须走 `dropSheet` 逐张确认。
   */
  async purgeScopePrefix(prefix: string): Promise<ScopePurgeReport> {
    const sheets = await this.listSheetsByScopePrefix(prefix);
    const pattern = `${escapeLikePattern(prefix)}%`;
    const statements: DbStatement[] = sheets.map((sheet) => ({ sql: `DROP TABLE IF EXISTS ${quoteIdentifier(sheet.physicalName)}` }));
    statements.push(
      { sql: "DELETE FROM mem_doc WHERE scope_id LIKE ? ESCAPE '\\'", params: [pattern] },
      { sql: "DELETE FROM op_log WHERE scope_id LIKE ? ESCAPE '\\'", params: [pattern] },
      { sql: "DELETE FROM sheet WHERE scope_id LIKE ? ESCAPE '\\'", params: [pattern] },
    );
    const results = await this.#gateway.transaction(statements);
    const tail = results.slice(sheets.length);
    return {
      sheets: integer(tail[2]?.changes),
      documents: integer(tail[0]?.changes),
      auditEntries: integer(tail[1]?.changes),
    };
  }

  /** 删除一张表：物理表、注册行与该表的召回投影同批消失。 */
  async dropSheet(sheet: SheetRecord): Promise<void> {
    await this.#gateway.transaction([
      { sql: `DROP TABLE IF EXISTS ${quoteIdentifier(sheet.physicalName)}` },
      { sql: 'DELETE FROM mem_doc WHERE scope_id = ? AND sheet_id = ?', params: [sheet.scopeId, sheet.id] },
      { sql: 'DELETE FROM sheet WHERE id = ?', params: [sheet.id] },
    ]);
  }

  /** 更新注册表元数据（表名、用途、策略、行模板、预算、DDL 文本），不触碰物理表结构。 */
  async updateSheetRegistration(sheetId: string, patch: SheetRegistryPatch): Promise<number> {
    const mapping: readonly (readonly [keyof SheetRegistryPatch, string])[] = [
      ['name', 'name'],
      ['purpose', 'purpose'],
      ['policy', 'policy'],
      ['rowTemplate', 'row_template'],
      ['tokenBudget', 'token_budget'],
      ['ddl', 'ddl'],
      ['injectCondition', 'inject_condition'],
      ['fillGuide', 'fill_guide'],
    ];
    const assignments: string[] = [];
    const params: (string | number)[] = [];
    for (const [key, column] of mapping) {
      const value = patch[key];
      if (value === undefined) continue;
      assignments.push(`${column} = ?`);
      params.push(value);
    }
    if (assignments.length === 0) return 0;
    assignments.push('updated_at = ?');
    params.push(Date.now());
    const result = await this.#gateway.execute({
      sql: `UPDATE sheet SET ${assignments.join(', ')} WHERE id = ?`,
      params: [...params, sheetId],
    });
    return result.changes;
  }

  /**
   * 结构变更：物理表 `ALTER TABLE` 与注册表里的 DDL/行模板同批提交。
   * 这条路径只由界面触发，列名与表名都已过 `sheet-dsl` 校验，不经模型 SQL 闸门。
   */
  async alterSheetColumn(
    sheet: SheetRecord,
    alter: 'add' | 'rename' | 'drop',
    columns: { readonly from?: string; readonly to?: string },
    next: { readonly ddl: string; readonly rowTemplate: string },
  ): Promise<void> {
    const table = quoteIdentifier(sheet.physicalName);
    const statement = alter === 'add'
      ? `ALTER TABLE ${table} ADD COLUMN ${quoteIdentifier(columns.to ?? '')} TEXT`
      : alter === 'rename'
        ? `ALTER TABLE ${table} RENAME COLUMN ${quoteIdentifier(columns.from ?? '')} TO ${quoteIdentifier(columns.to ?? '')}`
        : `ALTER TABLE ${table} DROP COLUMN ${quoteIdentifier(columns.from ?? '')}`;
    const nextColumns = sheetColumnNames(next.ddl);
    const history = await this.planSnapshotColumns(sheet, nextColumns, nextColumns.map((column) => alter === 'rename' && column === columns.to ? columns.from : column));
    await this.#gateway.transaction([
      ...history,
      { sql: statement },
      {
        sql: 'UPDATE sheet SET ddl = ?, row_template = ?, updated_at = ? WHERE id = ?',
        params: [next.ddl, next.rowTemplate, Date.now(), sheet.id],
      },
    ]);
  }

  /**
   * 在单个事务里执行已过闸的语句，并为每条语句写入 `op_log`。
   * 审计与数据同批提交：回滚时不会留下"执行过但没记录"或"记录了但没执行"的中间态。
   *
   * 表级前像整批只存一份（挂在第一条语句上）：回撤需要的是"这批写入之前"的状态，
   * 每条语句各存一份会让 `op_log` 按语句数成倍膨胀，长聊天里快照体积会压垮整库快照落盘。
   * 同时按 `AUDIT_LOG_RETENTION` 修剪该 scope 的审计，避免无上限增长；
   * 代价是超出保留窗口的历史楼层不再可回撤。
   */
  async runAuditedStatements(
    scopeId: string,
    statements: readonly DbStatement[],
    audit: {
      readonly actor: string;
      readonly revision: number;
      readonly floor?: number;
      readonly snapshot?: SheetSnapshot;
    },
  ): Promise<readonly ExecuteResult[]> {
    if (statements.length === 0) return [];
    const at = Date.now();
    const floor = audit.floor ?? -1;
    const snapshot = audit.snapshot === undefined ? null : JSON.stringify(audit.snapshot);
    const batch: DbStatement[] = [];
    statements.forEach((statement, index) => {
      batch.push(statement);
      batch.push({
        sql: 'INSERT INTO op_log(scope_id, at, actor, sql, params, revision, floor, snapshot) VALUES (?, ?, ?, ?, ?, ?, ?, ?)',
        params: [
          scopeId,
          at,
          audit.actor,
          statement.sql,
          encodeAuditParams(statement.params),
          audit.revision,
          floor,
          index === 0 ? snapshot : null,
        ],
      });
    });
    const executed = batch.length;
    if (floor >= 0) {
      const state = await this.readPresetState(scopeId);
      batch.push(...await this.planPresetRecordedFloor(scopeId, state.activeId ?? '', floor, state));
    }
    batch.push({
      sql: `
        DELETE FROM op_log
        WHERE scope_id = ?
          AND id NOT IN (SELECT id FROM op_log WHERE scope_id = ? ORDER BY id DESC LIMIT ?)
      `,
      params: [scopeId, scopeId, AUDIT_LOG_RETENTION],
    });
    const results = await this.#gateway.transaction(batch);
    return results.slice(0, executed).filter((_, index) => index % 2 === 0);
  }

  /** 拍下这些表的完整前像（含 rowid）；只在需要支持回撤的写入前调用。 */
  async captureSheetSnapshot(sheets: readonly SheetRecord[]): Promise<SheetSnapshot> {
    const snapshot: Record<string, readonly SnapshotRow[]> = {};
    for (const sheet of sheets) {
      const rows = await this.readAllSheetRows(sheet);
      snapshot[sheet.physicalName] = rows.map((row) => Object.fromEntries(
        Object.entries(row).map(([column, value]) => [column, snapshotCell(value)]),
      ));
    }
    return snapshot;
  }

  /** 结构变化时同步迁移楼层前像，回撤不会再引用被删掉或改名的旧列。 */
  async planSnapshotColumns(sheet: SheetRecord, columns: readonly string[], from: readonly (string | undefined)[], defaults: readonly string[] = []): Promise<readonly DbStatement[]> {
    const records = await this.#gateway.execute({ sql: 'SELECT id, snapshot FROM op_log WHERE scope_id = ? AND snapshot IS NOT NULL', params: [sheet.scopeId] });
    const statements: DbStatement[] = [];
    for (const row of records.rows) {
      const snapshot = parseSnapshot(text(row.snapshot));
      const source = snapshot[sheet.physicalName];
      if (!source) continue;
      const migrated = source.map((old) => Object.fromEntries([[ROW_ID_ALIAS, old[ROW_ID_ALIAS] ?? null],
        ...columns.map((column, index) => [column, from[index] && Object.hasOwn(old, from[index]!) ? old[from[index]!] ?? null : defaults[index] ?? ''])]));
      statements.push({ sql: 'UPDATE op_log SET snapshot = ? WHERE id = ? AND scope_id = ?',
        params: [JSON.stringify({ ...snapshot, [sheet.physicalName]: migrated }), row.id ?? null, sheet.scopeId] });
    }
    return statements;
  }

  /**
   * 该聊天最后一次写入数据表的楼层；从未记录过时返回 -1。
   * 数据中心的记录游标靠它在刷新页面后恢复，避免把「尚未记录的楼层」当成已处理。
   */
  async readLastRecordedFloor(scopeId: string): Promise<number> {
    const result = await this.#gateway.execute({
      sql: 'SELECT MAX(floor) AS last_floor FROM op_log WHERE scope_id = ?',
      params: [scopeId],
    });
    const raw = result.rows[0]?.last_floor;
    const parsed = typeof raw === 'number' ? raw : Number(raw ?? Number.NaN);
    return Number.isFinite(parsed) ? Math.trunc(parsed) : -1;
  }

  /** 预设各自恢复进度；老归档按该预设表的审计前像读取，避免借用另一份预设的楼层。 */
  async readPresetRecordedFloor(scopeId: string, presetId: string): Promise<number | null> {
    const state = await this.readPresetState(scopeId);
    if (Object.hasOwn(state.recordFloors ?? {}, presetId)) return state.recordFloors![presetId]!;
    const sheets = (await this.listSheets(scopeId, true)).filter((sheet) =>
      state.owners[sheet.id] === presetId || (!presetId && !Object.hasOwn(state.owners, sheet.id)));
    const tables = new Set(sheets.map((sheet) => sheet.physicalName));
    if (!tables.size) return null;
    const result = await this.#gateway.execute({
      sql: 'SELECT floor, snapshot FROM op_log WHERE scope_id = ? AND floor >= 0 AND snapshot IS NOT NULL ORDER BY floor DESC',
      params: [scopeId],
    });
    const row = result.rows.find((entry) => Object.keys(parseSnapshot(text(entry.snapshot))).some((table) => tables.has(table)));
    return row ? Number(row.floor) : null;
  }

  async planPresetRecordedFloor(scopeId: string, presetId: string, floor: number, previous?: PresetScopeState): Promise<readonly DbStatement[]> {
    if (!Number.isSafeInteger(floor) || floor < -1) throw new Error('记录楼层必须是大于或等于 -1 的整数。');
    const state = previous ?? await this.readPresetState(scopeId);
    const next = Math.max(state.recordFloors?.[presetId] ?? -1, floor);
    if (state.recordFloors?.[presetId] === next) return [];
    return [writeSheetMetaStatement(presetScopeKey(scopeId), {
      ...state, recordFloors: { ...state.recordFloors, [presetId]: next }, updatedAt: Date.now(),
    })];
  }

  /**
   * 读取楼层 ≥ `floor` 的审计前像，并合并成"这些楼层被写入之前"的状态。
   * 同一张表只保留最早出现的前像，后续写入的前像已经包含前一次的结果。
   */
  async readRevertSnapshot(
    scopeId: string,
    floor: number,
  ): Promise<{ readonly snapshot: SheetSnapshot; readonly entries: number }> {
    const result = await this.#gateway.execute({
      sql: 'SELECT snapshot FROM op_log WHERE scope_id = ? AND floor >= ? AND snapshot IS NOT NULL ORDER BY id',
      params: [scopeId, Math.max(0, Math.trunc(floor))],
    });
    const merged: Record<string, readonly SnapshotRow[]> = {};
    for (const row of result.rows) {
      for (const [table, rows] of Object.entries(parseSnapshot(text(row.snapshot)))) {
        if (!(table in merged)) merged[table] = rows;
      }
    }
    return { snapshot: merged, entries: result.rows.length };
  }

  /** 用前像覆盖这些表，并清掉已回撤楼层的审计记录（同一事务）。 */
  async restoreSheetSnapshot(
    scopeId: string,
    floor: number,
    snapshot: SheetSnapshot,
    sheets: readonly SheetRecord[],
  ): Promise<number> {
    const statements: DbStatement[] = [];
    let restoredTables = 0;
    for (const sheet of sheets) {
      const rows = snapshot[sheet.physicalName];
      if (!rows) continue;
      restoredTables += 1;
      statements.push({ sql: `DELETE FROM ${quoteIdentifier(sheet.physicalName)}` });
      for (const row of rows) {
        const columns = Object.keys(row).filter((column) => column !== ROW_ID_ALIAS);
        const placeholders = ['?', ...columns.map(() => '?')].join(', ');
        statements.push({
          sql: `INSERT INTO ${quoteIdentifier(sheet.physicalName)}(rowid, ${columns.map(quoteIdentifier).join(', ')}) VALUES (${placeholders})`,
          params: [row[ROW_ID_ALIAS] ?? null, ...columns.map((column) => row[column] ?? null)],
        });
      }
    }
    statements.push({
      sql: 'DELETE FROM op_log WHERE scope_id = ? AND floor >= ?',
      params: [scopeId, Math.max(0, Math.trunc(floor))],
    });
    const state = await this.readPresetState(scopeId);
    const cutoff = Math.max(0, Math.trunc(floor)) - 1;
    if (Object.values(state.recordFloors ?? {}).some((recorded) => recorded > cutoff)) statements.push(
      writeSheetMetaStatement(presetScopeKey(scopeId), { ...state, updatedAt: Date.now(),
        recordFloors: Object.fromEntries(Object.entries(state.recordFloors ?? {}).map(([id, recorded]) => [id, Math.min(recorded, cutoff)])),
      }),
    );
    await this.#gateway.transaction(statements);
    return restoredTables;
  }

  async exportDatabase(): Promise<ExportResult> {
    return this.#gateway.exportDatabase();
  }

  close(): Promise<void> {
    if (this.#closing) return this.#closing;
    this.#closed = true;
    this.#closing = this.#gateway.close();
    return this.#closing;
  }
}

export function searchRowToMemoryContext(row: SearchRow): {
  readonly id: string;
  readonly source: 'memory';
  readonly content: string;
} {
  return {
    id: `sqlite:${row.id}`,
    source: 'memory',
    content: row.text,
  };
}
