import type { PhoneState } from '../domain/model.js';
import { readVariables } from '../integration/variables-bridge.js';
import { createConditionContext, type ConditionWorldBookSource } from './context.js';
import type { GenerationConditionContext } from './generation.js';
import { buildRuleConditionContext, type ConditionRulesSettings } from './rules.js';

export interface ConditionSourceDeps {
  readonly state: () => PhoneState | null;
  readonly rules: () => ConditionRulesSettings;
  readonly worldBook: () => ConditionWorldBookSource | null;
  readonly appAccess: () => Readonly<Record<string, boolean>> | null;
}

export interface ConditionSource {
  /** 同步取用：使用最近一次读到的变量快照编译规则，供生成、注入与楼层触发等同步门控。 */
  readonly context: () => GenerationConditionContext;
  /** 重新读取楼层变量后再编译；读取失败时保留上一次的变量快照，条件仍可基于状态与时间求值。 */
  readonly refresh: () => Promise<GenerationConditionContext>;
}

/**
 * 把「已保存的条件规则」与「当前只读快照」组合成各接入点使用的条件上下文。
 * 变量读取是异步的，这里缓存最近一次结果，让同步门控也能拿到一致的快照。
 */
export function createConditionSource(deps: ConditionSourceDeps): ConditionSource {
  let variables: Readonly<Record<string, unknown>> = {};

  const compile = (): GenerationConditionContext => {
    const base = createConditionContext({
      state: deps.state(),
      variables,
      worldBook: deps.worldBook(),
      appAccess: deps.appAccess(),
    });
    return buildRuleConditionContext(base.snapshot, deps.rules());
  };

  return {
    context: compile,
    refresh: async () => {
      try {
        const snapshot = await readVariables('message', null);
        if (snapshot.available) variables = snapshot.data;
      } catch {
        // 变量接口不可用时保留上一次快照：条件门控不因读取失败而改变判定依据。
      }
      return compile();
    },
  };
}