import type { AppId, ConversationKind, PostKind } from '../domain/model.js';
import type { AdapterBodyFormat, AdapterFamily, FormatAdapter } from './adapter.js';
import { BUILTIN_FORMAT_ADAPTERS, normalizeContainer } from './adapter.js';
import { extractJsonBody } from './grammar.js';

export interface CardRegexScriptHint {
  readonly name: string;
  readonly findRegex: string;
  readonly markdownOnly: boolean;
  readonly promptOnly: boolean;
  readonly disabled: boolean;
}

export interface CardFormatSources {
  readonly regexScripts: readonly CardRegexScriptHint[];
  readonly instructionTexts: readonly string[];
}

export function cardFormatSourcesFromCharacter(character: unknown, extraTexts: readonly string[] = []): CardFormatSources {
  const root = asRecord(character);
  const data = asRecord(root?.data) ?? root;
  const extensions = asRecord(data?.extensions);
  const scripts = Array.isArray(extensions?.regex_scripts) ? extensions.regex_scripts : [];
  const regexScripts = scripts.flatMap((value): CardRegexScriptHint[] => {
    const script = asRecord(value);
    if (!script) return [];
    return [{
      name: String(script.scriptName ?? script.name ?? '角色卡正则'),
      findRegex: String(script.findRegex ?? ''),
      markdownOnly: script.markdownOnly === true,
      promptOnly: script.promptOnly === true,
      disabled: script.disabled === true,
    }];
  });
  const instructionTexts = [
    ...['description', 'system_prompt', 'post_history_instructions', 'first_mes', 'mes_example']
      .map((key) => data?.[key])
      .filter((value): value is string => typeof value === 'string'),
    ...(Array.isArray(data?.alternate_greetings) ? data.alternate_greetings.filter((value): value is string => typeof value === 'string') : []),
    ...readCharacterBookContents(data?.character_book),
    ...extraTexts,
  ];
  return { regexScripts, instructionTexts };
}

function readCharacterBookContents(value: unknown): readonly string[] {
  const book = asRecord(value);
  const entries = Array.isArray(book?.entries) ? book.entries : [];
  return entries.flatMap((entry) => {
    const content = asRecord(entry)?.content;
    return typeof content === 'string' ? [content] : [];
  });
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

const BLOCKED_CONTAINERS = new Set([
  'updatevariable', 'analysis', 'phoneanalysis', 'jsonpatch', 'initvar', 'summary', 'options',
  'content', 'story', '正文', '剧情', 'think', 'thinking', 'reasoning', 'image', 'img', '附加内容',
]);

export function discoverFormatAdapters(sources: CardFormatSources): readonly FormatAdapter[] {
  const candidates = new Map<string, FormatAdapter>();
  for (const script of sources.regexScripts) {
    if (script.disabled || !script.markdownOnly || script.promptOnly) continue;
    if (!isSafeRegexHint(script.findRegex)) continue;
    for (const container of extractRegexContainers(script.findRegex)) {
      const adapter = inferAdapter(container, `${script.name}\n${script.findRegex}`, 'card', 0.96);
      if (adapter) mergeDiscoveredAdapter(candidates, adapter);
    }
  }
  for (const text of sources.instructionTexts) {
    for (const sample of extractStructuredSamples(text)) {
      const adapter = inferAdapter(sample.container, sample.body, 'card', sample.confidence);
      if (adapter) mergeDiscoveredAdapter(candidates, adapter);
    }
    for (const sample of extractMarkedSamples(text)) {
      const adapter = inferAdapter(sample.container, sample.body, 'card', sample.confidence, {
        open: sample.open,
        close: sample.close,
        ...(sample.json ? { body: 'json' as const } : {}),
      });
      if (adapter) mergeDiscoveredAdapter(candidates, adapter);
    }
  }
  return [...candidates.values()].sort((left, right) => right.confidence - left.confidence);
}

function mergeDiscoveredAdapter(candidates: Map<string, FormatAdapter>, adapter: FormatAdapter): void {
  const existing = candidates.get(adapter.id);
  if (!existing) {
    candidates.set(adapter.id, adapter);
    return;
  }
  candidates.set(adapter.id, {
    ...existing,
    containers: [...new Set([...existing.containers, ...adapter.containers])],
    confidence: Math.max(existing.confidence, adapter.confidence),
    ...(existing.open ?? adapter.open ? { open: existing.open ?? adapter.open } : {}),
    ...(existing.close ?? adapter.close ? { close: existing.close ?? adapter.close } : {}),
    ...(existing.body ?? adapter.body ? { body: existing.body ?? adapter.body } : {}),
  });
}

export function isSafeRegexHint(value: string): boolean {
  const source = value.trim();
  if (!source || source.length > 2_000) return false;
  if (/\(\?<([=!])/.test(source)) return false;
  if (/\((?:[^()\\]|\\.)*[*+](?:[^()\\]|\\.)*\)\s*(?:[*+]|\{\d*,?\d*\})/.test(source)) return false;
  if (/(?:\[[^\]]*\]|\\[sSwWdD])(?:\*|\+|\{\d*,?\d*\})(?:\s*)(?:\*|\+|\{)/.test(source)) return false;
  return true;
}

export function extractRegexContainers(value: string): readonly string[] {
  const source = stripRegexLiteral(value);
  const names = new Set<string>();
  for (const match of source.matchAll(/(?:<|\\<)([A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5-]{1,31})(?:\\?>|>)/g)) {
    const name = match[1];
    if (name) names.add(name);
  }
  for (const match of source.matchAll(/(?:\\\[|\[)([A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5-]{1,31})(?:\\\]|\])/g)) {
    const name = match[1] ?? '';
    if (!name || /^(?:s|S|w|W|d|D)$/.test(name)) continue;
    names.add(name);
  }
  return [...names].filter((name) => !BLOCKED_CONTAINERS.has(normalizeContainer(name)));
}

function extractStructuredSamples(text: string): readonly { readonly container: string; readonly body: string; readonly confidence: number }[] {
  const source = text.slice(0, 60_000);
  return [
    ...scanStructuredSamples(source, /<([A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5-]{1,31})\b[^>]*>/g, (name) => new RegExp(`<\\/${escapeRegExp(name)}\\s*>`, 'i')),
    ...scanStructuredSamples(source, /\[([A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5-]{1,31})\]/g, (name) => new RegExp(`\\[\\/${escapeRegExp(name)}\\]`, 'i')),
  ];
}

interface MarkedSample {
  readonly container: string;
  readonly open: string;
  readonly close: string;
  readonly body: string;
  readonly confidence: number;
  readonly json: boolean;
}

const MARKER_WRAPPERS: Readonly<Record<string, string>> = { '[': ']', '【': '】', '<': '>' };
/** 起止后缀按长的优先匹配，避免 `_开始` 被 `始` 抢先命中。 */
const MARKER_SUFFIXES: readonly (readonly [string, string])[] = [
  ['_开始', '_结束'],
  ['_始', '_末'],
  ['_start', '_end'],
  ['开始', '结束'],
  ['始', '末'],
];

/**
 * 起止标记不成对的容器（`[宝可梦论坛_始] … [宝可梦论坛_末]`）。
 * 这类写法用成对标签的正则永远匹配不到，必须按「开始标记 + 对应结束标记」字面量扫描。
 */
export function extractMarkedSamples(text: string): readonly MarkedSample[] {
  const source = text.slice(0, 60_000);
  const samples: MarkedSample[] = [];
  const pattern = /([[【<])\s*([A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5-]{0,31})\s*([\]】>])/g;
  for (const match of source.matchAll(pattern)) {
    const openWrapper = match[1] ?? '';
    const name = match[2] ?? '';
    const closeWrapper = match[3] ?? '';
    if (MARKER_WRAPPERS[openWrapper] !== closeWrapper) continue;
    const suffix = MARKER_SUFFIXES.find(([opening]) => name.toLocaleLowerCase('zh-CN').endsWith(opening.toLocaleLowerCase('zh-CN')));
    if (!suffix) continue;
    const container = name.slice(0, name.length - suffix[0].length);
    if (!container || BLOCKED_CONTAINERS.has(normalizeContainer(container))) continue;
    const open = match[0];
    const close = `${openWrapper}${container}${suffix[1]}${closeWrapper}`;
    const bodyStart = (match.index ?? 0) + open.length;
    const closeIndex = source.indexOf(close, bodyStart);
    if (closeIndex < 0) continue;
    const body = source.slice(bodyStart, closeIndex);
    const json = looksLikeJsonBody(body);
    if (!body.trim() || (!json && !looksLikePhoneBody(body, container))) continue;
    samples.push({ container, open, close, body, confidence: json ? 0.95 : 0.9, json });
  }
  return samples;
}

function looksLikeJsonBody(body: string): boolean {
  const trimmed = body.trim();
  if (!/^[[{]/.test(trimmed)) return false;
  return extractJsonBody(trimmed) !== null;
}

function scanStructuredSamples(
  source: string,
  openingPattern: RegExp,
  closingPattern: (name: string) => RegExp,
): readonly { readonly container: string; readonly body: string; readonly confidence: number }[] {
  const samples: { container: string; body: string; confidence: number }[] = [];
  for (const match of source.matchAll(openingPattern)) {
    const container = match[1] ?? '';
    const normalized = normalizeContainer(container);
    if (!container || BLOCKED_CONTAINERS.has(normalized)) continue;
    const bodyStart = (match.index ?? 0) + match[0].length;
    const remainder = source.slice(bodyStart, bodyStart + 8_000);
    const close = closingPattern(container).exec(remainder);
    if (!close) continue;
    const body = remainder.slice(0, close.index);
    if (!looksLikePhoneBody(body, container)) continue;
    const prefix = source.slice(Math.max(0, (match.index ?? 0) - 300), match.index);
    samples.push({
      container,
      body,
      confidence: /Format|格式|FORMAT_RULE/.test(prefix) ? 0.93 : 0.84,
    });
  }
  return samples;
}

function looksLikePhoneBody(body: string, container: string): boolean {
  return /(微信|推特|twitter|discord|forum|论坛|私信|chat|message|post|推文|发送者|作者|QQ\.(?:Private|Group|Post))|(?:^|\n)\s*[^:：\n]{1,20}[:：]\s*\S/i.test(`${container}\n${body}`);
}

function inferAdapter(
  container: string,
  evidence: string,
  source: FormatAdapter['source'],
  confidence: number,
  extra: { readonly open?: string; readonly close?: string; readonly body?: AdapterBodyFormat } = {},
): FormatAdapter | null {
  const capabilities = {
    ...(extra.open && extra.close ? { open: extra.open, close: extra.close } : {}),
    ...(extra.body ? { body: extra.body } : {}),
  };
  const normalized = normalizeContainer(container);
  const builtin = BUILTIN_FORMAT_ADAPTERS.find((adapter) => adapter.containers.some((name) => normalizeContainer(name) === normalized));
  if (builtin) {
    return {
      ...builtin,
      id: `card.${normalized}.${builtin.family}`,
      source,
      containers: [container],
      confidence: Math.max(confidence, builtin.confidence),
      ...capabilities,
    };
  }
  if (BLOCKED_CONTAINERS.has(normalized)) return null;

  const haystack = `${container}\n${evidence}`;
  let family: AdapterFamily | null = null;
  let appId: AppId | null = null;
  let conversationKind: ConversationKind = 'direct';
  let postKind: PostKind | undefined;

  if (/QQ\.(?:Private|Group|Post|Comment)/.test(haystack)) {
    family = 'dsl'; appId = 'wechat';
  } else if (/论坛|forum|贴吧|bbs/i.test(container)) {
    // 容器名直接点明是论坛：JSON 正文按帖子面板解析，纯文本按字段块解析。
    family = extra.body === 'json' || /<post|<message|\[发送者\|/i.test(evidence) ? 'discord' : 'bracketed';
    appId = 'forum'; conversationKind = 'group'; postKind = 'forum-thread';
  } else if (/<channel>|\[发送者\||\[标题\||<message>|<post>/i.test(haystack)) {
    family = 'discord'; appId = 'forum'; conversationKind = 'group'; postKind = 'forum-thread';
  } else if (/推特私信|twitter[_ -]?(?:dm|message)|私信/i.test(haystack)) {
    family = /<[^>]+>[\s\S]*<\//.test(evidence) ? 'tagged' : 'chat-app'; appId = 'twitter';
  } else if (/推特|twitter|tweet|推文|评论区/i.test(haystack)) {
    family = /推文\s*[:：]/.test(evidence) ? 'bracketed' : 'tagged'; appId = 'twitter'; postKind = 'twitter-post';
  } else if (/微信|wechat/i.test(haystack)) {
    family = 'tagged'; appId = 'wechat';
  } else if (/匿名|chat[_ -]?app|对方\s*[:：]/i.test(haystack)) {
    family = 'chat-app'; appId = 'anonymous'; conversationKind = 'anonymous';
  } else if (/帖子|楼主|板块|版块/.test(haystack)) {
    family = extra.body === 'json' ? 'discord' : 'bracketed';
    appId = 'forum'; conversationKind = 'group'; postKind = 'forum-thread';
  }
  if (!family || !appId) return null;
  return {
    id: `card.${normalized}.${family}`,
    family,
    source,
    appId,
    containers: [container],
    confidence,
    conversationKind,
    ...(postKind ? { postKind } : {}),
    ...capabilities,
  };
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function stripRegexLiteral(value: string): string {
  const trimmed = value.trim();
  const match = /^\/([\s\S]*)\/[dgimsuvy]*$/.exec(trimmed);
  return match?.[1] ?? trimmed;
}