import type { PhoneAppDefinition, PhoneRoute, PhoneViewContext } from '../app-types.js';
import { SELF_PROFILE_ID } from '../../domain/commands.js';
import { APP_ID_LABELS, type Conversation, type PhoneMessage, type PhonePost, type Profile } from '../../domain/model.js';
import { replaceImageMarkers } from '../../generation/image-client.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import {
  appendMessageBody,
  createChatExtPanel,
  describeContactMatchResult,
  describeMessagePreview,
  formatTime,
  latestMessagesByConversation,
  pickImageAsDataUrl,
  renderAvatar,
  renderDirectiveCard,
  renderMediaMessageCard,
  renderMessageRollback,
  renderQueuedMessageDelete,
  renderRichContent,
  richContextOf,
  scrollToLatestMessage,
  selectRecentMessages,
  sendDirectiveMessage,
  sendMediaMessage,
} from '../shared-view.js';
import { createProfileAvatarGenerator } from '../profile-avatar-generator.js';

type TwitterTimelineTab = 'recommended' | 'following';
let twitterTimelineTab: TwitterTimelineTab = 'recommended';
/** 当前打开的推文详情（评论区）与打开它的来源页，用于返回。 */
let twitterDetailPostId: string | null = null;
let twitterDetailReturnRoute: PhoneRoute = 'twitterFeed';
/** 私信列表的多选删除状态。 */
let twitterDmSelectMode = false;
const twitterDmSelection = new Set<string>();

export function createTwitterApp(): PhoneAppDefinition {
  return {
    id: 'twitter',
    label: APP_ID_LABELS.twitter,
    icon: '推',
    navigation: [
      { route: 'twitterFeed', label: '主页', icon: 'home' },
      { route: 'twitterSearch', label: '搜索', icon: 'search' },
      { route: 'twitterNotifications', label: '通知', icon: 'bell' },
      { route: 'twitterDm', label: '私信', icon: 'message' },
      { route: 'twitterMe', label: '我', icon: 'me' },
    ],
    backRoute: (route) => (route === 'twitterPost' ? twitterDetailReturnRoute : null),
    render(context) {
      if (context.selectedConversationId) {
        const conversation = context.state.conversations[context.selectedConversationId];
        if (conversation?.appId === 'twitter') return renderDirectMessage(context, conversation);
      }
      if (context.route === 'twitterPost') {
        const post = twitterDetailPostId ? context.state.posts[twitterDetailPostId] : undefined;
        if (post && post.appId === 'twitter') return renderTweetDetail(context, post);
        return renderFeedPage(context);
      }
      if (context.route === 'twitterSearch') return renderSearchPage(context);
      if (context.route === 'twitterNotifications') return renderNotificationsPage(context);
      if (context.route === 'twitterDm') return renderDirectMessageList(context);
      if (context.route === 'twitterMe') return renderMePage(context);
      return renderFeedPage(context);
    },
  };
}

/** 打开推文详情（评论区），并记录来源页以便返回。 */
function openTweetDetail(context: PhoneViewContext, post: PhonePost): void {
  twitterDetailPostId = post.id;
  if (context.route !== 'twitterPost') {
    twitterDetailReturnRoute = context.route.startsWith('twitter') ? context.route : 'twitterFeed';
  }
  context.navigate('twitterPost');
}

/** 推特语境下的显示身份：优先推特昵称/头像，回退通用档案。 */
function twitterIdentity(profile: Profile | undefined): {
  readonly name: string;
  readonly handle: string;
  readonly avatarProfile: Profile | undefined;
} {
  if (!profile) return { name: '未知用户', handle: '@unknown', avatarProfile: undefined };
  const name = profile.twitterName?.trim() || profile.displayName;
  const handle = profile.aliases.twitter ?? `@${profile.displayName}`;
  const avatarProfile: Profile = profile.twitterAvatarUrl
    ? { ...profile, displayName: name, avatarUrl: profile.twitterAvatarUrl }
    : { ...profile, displayName: name };
  return { name, handle, avatarProfile };
}

function twitterAvatar(profile: Profile | undefined, className = 'phone-avatar phone-twitter-avatar'): HTMLElement {
  return renderAvatar(twitterIdentity(profile).avatarProfile, className);
}

function renderFeedPage(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-twitter-page phone-twitter-feed' });
  const header = element('div', { className: 'phone-twitter-brandbar' });
  header.append(renderPhoneIcon('twitter', 'phone-twitter-mark'));
  // 用户改过应用名时在品牌栏展示自定义名称；未改名时保持原有纯图标设计。
  const title = context.appTitle('推特');
  if (title !== '推特') header.append(element('strong', { className: 'phone-twitter-brandbar-title', text: title }));
  const tabs = renderTimelineTabs(context);
  page.append(header, tabs, renderTrendStrip(context), renderTimeline(context, twitterTimelineTab));
  return page;
}

function renderTimelineTabs(context: PhoneViewContext): HTMLElement {
  const tabs = element('div', { className: 'phone-twitter-tabs' });
  const recommended = button('为你推荐', 'phone-twitter-tab');
  const following = button('正在关注', 'phone-twitter-tab');
  recommended.classList.toggle('is-active', twitterTimelineTab === 'recommended');
  following.classList.toggle('is-active', twitterTimelineTab === 'following');
  recommended.addEventListener('click', () => {
    twitterTimelineTab = 'recommended';
    context.navigate('twitterFeed');
  });
  following.addEventListener('click', () => {
    twitterTimelineTab = 'following';
    context.navigate('twitterFeed');
  });
  tabs.append(recommended, following);
  return tabs;
}

/** 发布动态弹窗（从「我」页的 + 号触发）。 */
async function composeTweet(context: PhoneViewContext): Promise<void> {
  const values = await context.showModal('发布动态', [
    { name: 'content', label: '有什么新鲜事？', type: 'textarea', required: true, placeholder: '所有人可见，最多 500 字' },
  ]);
  const content = values?.content?.trim();
  if (!content) return;
  try {
    await context.commands.createUserPost('twitter', 'twitter-post', content.slice(0, 500));
    context.showNotice('动态已进入本轮回复队列', 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

function renderTrendStrip(context: PhoneViewContext): HTMLElement {
  const trend = element('section', { className: 'phone-twitter-trend-strip' });
  const copy = button('', 'phone-twitter-trend-copy', () => context.navigate('twitterSearch'));
  copy.append(
    element('span', { className: 'phone-twitter-trend-label', text: '正在发生' }),
    element('strong', { text: topTrend(context) }),
  );
  const refresh = button('', 'phone-icon-button phone-twitter-refresh-button');
  refresh.append(renderPhoneIcon('refresh'));
  refresh.title = '根据你的兴趣刷新推荐动态';
  refresh.setAttribute('aria-label', '根据你的兴趣刷新推荐动态');
  refresh.addEventListener('click', (event) => {
    event.stopPropagation();
    void refreshAmbientPosts(context, refresh, 'twitter');
  });
  trend.append(copy, refresh);
  return trend;
}

async function refreshAmbientPosts(
  context: PhoneViewContext,
  trigger: HTMLButtonElement,
  platform: 'forum' | 'twitter',
): Promise<void> {
  trigger.disabled = true;
  trigger.classList.add('is-loading');
  try {
    const count = await context.generateAmbientPosts(platform);
    context.showNotice(`已刷新 ${count} 条${platform === 'twitter' ? 'X' : '论坛'}推荐动态`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  } finally {
    trigger.disabled = false;
    trigger.classList.remove('is-loading');
  }
}

function renderTimeline(context: PhoneViewContext, tab: TwitterTimelineTab): HTMLElement {
  const feed = element('div', { className: 'phone-twitter-timeline' });
  const posts = selectTwitterFeedPosts(context, tab);
  if (posts.length === 0) {
    const emptyMessage = tab === 'following'
      ? ['关注的人还没有动态', '关注更多联系人后，他们的动态会显示在这里。']
      : ['时间线还没有动态', '发布一条动态，等待角色加入讨论。'];
    feed.append(renderTwitterEmpty(emptyMessage[0] ?? '', emptyMessage[1] ?? ''));
    return feed;
  }
  for (const post of posts) feed.append(renderTweet(context, post));
  return feed;
}

function renderSearchPage(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-twitter-page phone-twitter-search-page' });
  const search = element('label', { className: 'phone-twitter-search' });
  const input = element('input', {
    className: 'phone-twitter-search-input',
    attributes: { type: 'search', placeholder: '搜索推特', autocomplete: 'off' },
  });
  search.append(renderPhoneIcon('search'), input);
  const results = element('div', { className: 'phone-twitter-search-results' });
  const posts = selectTwitterPosts(context);
  const trends = renderTrendList(context);
  for (const post of posts) {
    const tweet = renderTweet(context, post);
    results.append(tweet);
  }
  input.addEventListener('input', () => {
    const keyword = input.value.trim().toLocaleLowerCase('zh-CN');
    trends.hidden = Boolean(keyword);
    for (const tweet of results.querySelectorAll<HTMLElement>('.phone-tweet-card')) {
      tweet.hidden = Boolean(keyword) && !tweet.textContent?.toLocaleLowerCase('zh-CN').includes(keyword);
    }
  });
  page.append(search, trends, results);
  if (posts.length === 0) results.append(renderTwitterEmpty('还没有搜索结果', '世界中出现新的公开动态后会显示在这里。'));
  return page;
}

function renderTrendList(context: PhoneViewContext): HTMLElement {
  const section = element('section', { className: 'phone-twitter-trends' });
  section.append(element('h2', { text: '热门趋势' }));
  const trends = collectTrends(context);
  if (trends.length === 0) {
    section.append(element('p', { className: 'phone-twitter-empty-line', text: '暂时没有趋势标签' }));
    return section;
  }
  for (const [index, [tag, count]] of trends.slice(0, 8).entries()) {
    const row = element('div', { className: 'phone-twitter-trend-row' });
    row.append(
      element('span', { className: 'phone-twitter-trend-rank', text: String(index + 1) }),
      element('span', { className: 'phone-list-main' }),
    );
    const copy = row.querySelector<HTMLElement>('.phone-list-main');
    copy?.append(element('strong', { text: tag }), element('small', { text: `${count} 条动态` }));
    section.append(row);
  }
  return section;
}

/** 通知页只显示针对「用户自己的动态」的互动与回复，角色之间的互动不属于用户通知。 */
function renderNotificationsPage(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-twitter-page phone-twitter-notifications' });
  const list = element('div', { className: 'phone-twitter-notification-list' });

  const isUserPost = (postId: string): boolean =>
    context.state.posts[postId]?.profileId === SELF_PROFILE_ID;

  interface NotificationEntry {
    readonly createdAt: number;
    readonly actorProfileId: string;
    readonly action: string;
    readonly icon: 'heart' | 'reply' | 'repost';
    readonly quote: string;
  }
  const entries: NotificationEntry[] = [];

  for (const interaction of Object.values(context.state.interactions)) {
    if (interaction.appId !== 'twitter' || !isUserPost(interaction.targetId)) continue;
    if (interaction.actorProfileId === SELF_PROFILE_ID) continue;
    const target = context.state.posts[interaction.targetId];
    entries.push({
      createdAt: interaction.createdAt,
      actorProfileId: interaction.actorProfileId,
      action: interaction.type === 'like' ? '喜欢了你的动态' : `评论了你的动态：${interaction.content ?? ''}`,
      icon: interaction.type === 'like' ? 'heart' : 'reply',
      quote: target?.content ?? '',
    });
  }
  for (const post of Object.values(context.state.posts)) {
    if (post.appId !== 'twitter' || post.profileId === SELF_PROFILE_ID) continue;
    const referencedId = post.parentId ?? post.targetId;
    if (!referencedId || !isUserPost(referencedId)) continue;
    const referenced = context.state.posts[referencedId];
    entries.push({
      createdAt: post.createdAt,
      actorProfileId: post.profileId,
      action: post.kind === 'twitter-repost' ? '转发了你的动态' : `回复了你的动态：${post.content}`,
      icon: post.kind === 'twitter-repost' ? 'repost' : 'reply',
      quote: referenced?.content ?? '',
    });
  }
  entries.sort((a, b) => b.createdAt - a.createdAt);

  for (const entry of entries) {
    const actor = context.state.profiles[entry.actorProfileId];
    const identity = twitterIdentity(actor);
    const row = element('article', { className: 'phone-twitter-notification' });
    row.append(
      renderPhoneIcon(entry.icon, 'phone-twitter-notification-icon'),
      twitterAvatar(actor),
    );
    const copy = element('div', { className: 'phone-twitter-notification-copy' });
    copy.append(
      element('p', { text: `${identity.name} ${entry.action}` }),
      element('small', { text: formatTime(entry.createdAt) }),
      element('span', { className: 'phone-twitter-notification-quote', text: entry.quote }),
    );
    row.append(copy);
    list.append(row);
  }
  if (entries.length === 0) list.append(renderTwitterEmpty('暂无通知', '有人与你的动态互动后，通知会显示在这里。'));
  page.append(list);
  return page;
}

/** 「我」页：配置用户在推特的昵称、推特号、简介与头像；下方是自己的动态。 */
function renderMePage(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-twitter-page phone-twitter-me' });
  const self = context.state.profiles[SELF_PROFILE_ID];
  const identity = twitterIdentity(self);

  const cover = element('div', { className: 'phone-twitter-me-cover' });
  const card = element('section', { className: 'phone-twitter-me-card' });
  const avatarButton = button('', 'phone-twitter-me-avatar-button', () => {
    if (self) openTwitterProfileEditor(context, self.id, true);
  });
  avatarButton.append(twitterAvatar(self, 'phone-avatar phone-twitter-avatar phone-twitter-me-avatar'));
  avatarButton.title = '编辑推特资料';

  const headRow = element('div', { className: 'phone-twitter-me-head' });
  const edit = button('编辑资料', 'phone-button phone-button-secondary phone-button-compact', () => {
    if (self) openTwitterProfileEditor(context, self.id, true);
  });
  headRow.append(avatarButton, edit);

  const myPosts = selectTwitterPosts(context).filter((post) => post.profileId === SELF_PROFILE_ID);
  const followingCount = Object.values(context.state.interactions).filter(
    (interaction) => interaction.appId === 'twitter'
      && interaction.type === 'follow'
      && interaction.actorProfileId === SELF_PROFILE_ID,
  ).length;
  const likesReceived = Object.values(context.state.interactions).filter(
    (interaction) => interaction.appId === 'twitter'
      && interaction.type === 'like'
      && interaction.actorProfileId !== SELF_PROFILE_ID
      && context.state.posts[interaction.targetId]?.profileId === SELF_PROFILE_ID,
  ).length;

  card.append(
    headRow,
    element('strong', { className: 'phone-twitter-me-name', text: identity.name }),
    element('span', { className: 'phone-twitter-me-handle', text: identity.handle }),
    ...(self?.twitterBio ? [element('p', { className: 'phone-twitter-me-bio', text: self.twitterBio })] : []),
  );
  const stats = element('div', { className: 'phone-twitter-me-stats' });
  stats.append(
    statItem(String(myPosts.length), '动态'),
    statItem(String(followingCount), '正在关注'),
    statItem(String(likesReceived), '获赞'),
  );
  card.append(stats);
  page.append(cover, card);

  const timeline = element('div', { className: 'phone-twitter-timeline' });
  if (myPosts.length === 0) {
    timeline.append(renderTwitterEmpty('还没有动态', '点击右上角 + 号发布第一条动态吧。'));
  } else {
    for (const post of myPosts) timeline.append(renderTweet(context, post));
  }
  const sectionBar = element('div', { className: 'phone-twitter-me-section' });
  const composeButton = button('', 'phone-icon-button phone-twitter-compose-button', () => void composeTweet(context));
  composeButton.append(renderPhoneIcon('add', 'phone-twitter-compose-icon'));
  composeButton.title = '发布动态';
  composeButton.setAttribute('aria-label', '发布动态');
  sectionBar.append(element('h3', { className: 'phone-twitter-me-section-title', text: '我的动态' }), composeButton);
  page.append(sectionBar, timeline);
  return page;
}

function statItem(value: string, label: string): HTMLElement {
  const item = element('span', { className: 'phone-twitter-me-stat' });
  item.append(element('strong', { text: value }), element('small', { text: label }));
  return item;
}

/**
 * 推特资料编辑器。
 * isSelf=true：编辑自己的推特昵称/推特号/简介/头像；
 * isSelf=false：编辑私信对象，可额外配置实际绑定角色。
 */
function openTwitterProfileEditor(context: PhoneViewContext, profileId: string, isSelf: boolean): void {
  const profile = context.state.profiles[profileId];
  if (!profile) return;
  const host = document.getElementById('narrative-phone-host');
  const shellRoot = host?.shadowRoot?.querySelector<HTMLElement>('.phone-shell');
  if (!shellRoot) return;

  const identity = twitterIdentity(profile);
  let avatarUrl = profile.twitterAvatarUrl ?? profile.avatarUrl ?? '';

  const backdrop = element('div', { className: 'phone-modal-backdrop' });
  const dialog = element('div', { className: 'phone-modal phone-profile-editor', attributes: { role: 'dialog', 'aria-modal': 'true' } });
  dialog.append(element('h2', { className: 'phone-modal-title', text: isSelf ? '我的推特资料' : '私信对象资料' }));

  const avatarRow = element('div', { className: 'phone-profile-avatar-row' });
  const avatarPreview = element('button', { className: 'phone-profile-avatar', attributes: { type: 'button', title: '点击更换头像' } });
  const refreshAvatarPreview = () => {
    avatarPreview.replaceChildren();
    if (avatarUrl) {
      avatarPreview.append(element('img', { attributes: { src: avatarUrl, alt: '头像' } }));
    } else {
      avatarPreview.append(element('span', { text: identity.name.slice(0, 1).toUpperCase() }));
    }
  };
  refreshAvatarPreview();
  avatarPreview.addEventListener('click', () => {
    void pickImageAsDataUrl(256).then((dataUrl) => {
      if (!dataUrl) return;
      avatarUrl = dataUrl;
      refreshAvatarPreview();
    });
  });
  avatarRow.append(avatarPreview);
  if (isSelf) avatarRow.append(element('span', { className: 'phone-settings-hint', text: '点击头像上传新图片（仅推特内显示）' }));
  dialog.append(avatarRow);

  const nameField = element('label', { className: 'phone-modal-field' });
  nameField.append(element('span', { text: '推特昵称' }));
  const nameInput = element('input', { className: 'phone-modal-input', attributes: { maxlength: '40' } });
  nameInput.value = profile.twitterName ?? profile.displayName;
  nameField.append(nameInput);
  dialog.append(nameField);

  const handleField = element('label', { className: 'phone-modal-field' });
  handleField.append(element('span', { text: '推特号' }));
  const handleInput = element('input', { className: 'phone-modal-input', attributes: { maxlength: '30', placeholder: '@handle' } });
  handleInput.value = profile.aliases.twitter ?? '';
  handleField.append(handleInput);
  dialog.append(handleField);

  const bioField = element('label', { className: 'phone-modal-field' });
  bioField.append(element('span', { text: '简介（可选）' }));
  const bioInput = element('textarea', { className: 'phone-modal-input', attributes: { maxlength: '200', rows: '2' } });
  bioInput.value = profile.twitterBio ?? '';
  bioField.append(bioInput);
  dialog.append(bioField);

  let boundInput: HTMLInputElement | null = null;
  let appearanceInput: HTMLTextAreaElement | null = null;
  let avatarPromptInput: HTMLTextAreaElement | null = null;
  if (!isSelf) {
    const boundField = element('label', { className: 'phone-modal-field' });
    boundField.append(element('span', { text: '实际绑定角色（世界书/角色卡中的正式名字）' }));
    boundInput = element('input', { className: 'phone-modal-input', attributes: { maxlength: '80', placeholder: '留空表示与昵称相同' } });
    boundInput.value = profile.boundCharacter ?? '';
    boundField.append(boundInput);
    dialog.append(boundField);

    const appearanceField = element('label', { className: 'phone-modal-field' });
    appearanceField.append(element('span', { text: '生图素体提示词（固定外貌 tag，英文逗号分隔）' }));
    appearanceInput = element('textarea', {
      className: 'phone-modal-input phone-modal-textarea',
      attributes: { rows: '3', maxlength: '1000', placeholder: '例如：long silver hair, blue eyes, slender' },
    });
    appearanceInput.value = profile.appearancePrompt ?? '';
    appearanceField.append(appearanceInput);
    dialog.append(appearanceField);

    const avatarGenerator = createProfileAvatarGenerator({
      context,
      profile,
      avatarField: 'twitterAvatarUrl',
      appearanceInput,
      getDraft: () => ({
        twitterName: nameInput.value,
        boundCharacter: boundInput?.value,
        twitterBio: bioInput.value,
        appearancePrompt: appearanceInput?.value,
      }),
      onAvatarApplied: (url) => {
        avatarUrl = url;
        refreshAvatarPreview();
      },
    });
    avatarPromptInput = avatarGenerator.promptInput;
    avatarRow.append(avatarGenerator.control);
  }

  const actions = element('div', { className: 'phone-modal-actions' });
  const cancel = button('取消', 'phone-button phone-button-secondary', () => backdrop.remove());
  const save = button('保存', 'phone-button phone-button-primary', async () => {
    save.disabled = true;
    try {
      await context.commands.updateProfile(profile.id, {
        twitterName: nameInput.value,
        twitterHandle: handleInput.value,
        twitterBio: bioInput.value,
        twitterAvatarUrl: avatarUrl,
        ...(boundInput ? { boundCharacter: boundInput.value } : {}),
        ...(appearanceInput ? { appearancePrompt: appearanceInput.value } : {}),
        ...(avatarPromptInput ? { avatarPrompt: avatarPromptInput.value } : {}),
      });
      backdrop.remove();
      context.showNotice('推特资料已保存。', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      save.disabled = false;
    }
  });
  actions.append(cancel, save);
  dialog.append(actions);
  backdrop.append(dialog);
  backdrop.addEventListener('pointerdown', (event) => {
    if (event.target === backdrop) backdrop.remove();
  });
  shellRoot.append(backdrop);
}

function renderTweet(context: PhoneViewContext, post: PhonePost): HTMLElement {
  const profile = context.state.profiles[post.profileId];
  const identity = twitterIdentity(profile);
  const card = element('article', { className: 'phone-tweet-card phone-tweet-card-clickable' });
  card.dataset.profileId = post.profileId;
  const quoted = post.kind === 'twitter-repost' && post.targetId ? context.state.posts[post.targetId] : undefined;
  if (post.kind === 'twitter-reply') {
    card.append(contextLine(card, '回复了一条动态'));
  } else if (post.kind === 'twitter-repost') {
    const quotedHandle = quoted ? twitterIdentity(context.state.profiles[quoted.profileId]).handle : '';
    card.append(contextLine(card, quotedHandle ? `转发了 ${quotedHandle} 的动态` : '转发了一条动态'));
  }
  const head = element('header', { className: 'phone-tweet-head' });
  const identityBox = element('div', { className: 'phone-list-main' });
  const nameLine = element('div', { className: 'phone-tweet-name-line' });
  nameLine.append(
    element('strong', { text: identity.name }),
    element('span', { text: identity.handle }),
    element('span', { className: 'phone-tweet-dot', text: '·' }),
    element('time', { className: 'phone-tweet-time', text: formatTime(post.createdAt) }),
  );
  identityBox.append(nameLine);
  head.append(twitterAvatar(profile), identityBox);
  const follow = renderFollowButton(context, post.profileId);
  if (follow) head.append(follow);
  card.append(head, renderRichContent(post.content, richContextOf(context), { className: 'phone-tweet-content', block: true }));
  if (quoted) card.append(renderQuotedTweet(context, quoted));

  const { replyCount, likeCount } = tweetEngagement(context, post);
  const actions = element('div', { className: 'phone-tweet-actions' });
  actions.append(
    tweetAction(replyCount > 0 ? String(replyCount) : '', 'reply', () => openTweetDetail(context, post)),
    tweetAction('', 'repost', () => context.showNotice('转发功能将在后续版本开放', 'info')),
    tweetAction(likeCount > 0 ? String(likeCount) : '', 'heart', () => interactWithPost(context, post, 'like')),
    tweetAction('', 'share', () => context.showNotice('已复制到剪贴板（模拟）', 'info')),
    renderTwitterDelete(context, post.id, postLabelOf(post), post.content, () => context.navigate(context.route)),
  );
  card.append(actions);
  // 点击卡片正文打开评论区；按钮、链接与图片保持原有交互。
  card.addEventListener('click', (event) => {
    const target = event.target instanceof Element ? event.target : null;
    if (target?.closest('button, a, img')) return;
    openTweetDetail(context, post);
  });
  return card;
}

function postLabelOf(post: PhonePost): TwitterItemLabel {
  if (post.kind === 'twitter-repost') return '转发';
  return post.kind === 'twitter-reply' ? '回复' : '动态';
}

/** 转发卡片里的原动态引用块：让转发在信息流里能被单独看懂。 */
function renderQuotedTweet(context: PhoneViewContext, quoted: PhonePost): HTMLElement {
  const profile = context.state.profiles[quoted.profileId];
  const identity = twitterIdentity(profile);
  const box = element('blockquote', { className: 'phone-tweet-quote' });
  const head = element('div', { className: 'phone-tweet-quote-head' });
  head.append(
    twitterAvatar(profile, 'phone-avatar phone-twitter-avatar phone-tweet-quote-avatar'),
    element('strong', { text: identity.name }),
    element('span', { text: identity.handle }),
  );
  box.append(
    head,
    renderRichContent(quoted.content, richContextOf(context), { className: 'phone-tweet-quote-content', block: true }),
  );
  return box;
}

type TwitterItemLabel = '动态' | '转发' | '回复' | '评论';

/**
 * 推特内容删除：动态、转发、回复贴与评论互动都能删，包含路人网友的内容。
 * 删主贴会连带清理它下面的回复、转发、点赞与评论，因此二次确认里写明影响范围。
 */
function renderTwitterDelete(
  context: PhoneViewContext,
  itemId: string,
  label: TwitterItemLabel,
  content: string,
  onDeleted: () => void,
): HTMLButtonElement {
  const cascades = label === '动态' || label === '转发';
  const remove = button('', 'phone-tweet-action phone-tweet-delete', async () => {
    const confirmed = await context.showConfirm({
      title: `删除这条${label}？`,
      message: cascades
        ? '这条内容以及挂在它下面的回复、转发、点赞和评论都会一并删除，且不可撤销。'
        : `这条${label}会被删除，且不可撤销。`,
      detail: content.replace(/\s+/g, ' ').trim().slice(0, 180),
      confirmLabel: `删除${label}`,
      danger: true,
    });
    if (!confirmed) return;
    remove.disabled = true;
    try {
      await context.commands.deleteTwitterItem(itemId);
      context.showNotice(`${label}已删除`, 'success');
      onDeleted();
    } catch (error) {
      remove.disabled = false;
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
  });
  remove.append(renderPhoneIcon('trash'));
  remove.title = `删除${label}`;
  remove.setAttribute('aria-label', remove.title);
  return remove;
}

function isFollowing(context: PhoneViewContext, profileId: string): boolean {
  return Object.values(context.state.interactions).some(
    (interaction) => interaction.appId === 'twitter'
      && interaction.type === 'follow'
      && interaction.actorProfileId === SELF_PROFILE_ID
      && interaction.targetId === profileId,
  );
}

function renderFollowButton(context: PhoneViewContext, profileId: string): HTMLButtonElement | null {
  if (profileId === SELF_PROFILE_ID || !context.state.profiles[profileId]) return null;
  const followed = isFollowing(context, profileId);
  const control = button(
    followed ? '已关注' : '关注',
    `phone-twitter-follow${followed ? ' is-following' : ''}`,
    async () => {
      control.disabled = true;
      try {
        await context.commands.setTwitterFollow(profileId, !followed);
        context.showNotice(followed ? '已取消关注' : '已关注该账号', 'success');
      } catch (error) {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
        control.disabled = false;
      }
    },
  );
  control.setAttribute('aria-label', followed ? '取消关注该账号' : '关注该账号');
  return control;
}

/** 推文互动统计：回复数 = 回复贴 + 评论互动，与详情页评论区口径一致。 */
function tweetEngagement(context: PhoneViewContext, post: PhonePost): { readonly replyCount: number; readonly likeCount: number } {
  const interactions = Object.values(context.state.interactions).filter((item) => item.targetId === post.id);
  const likeCount = interactions.filter((item) => item.type === 'like').length;
  const commentCount = interactions.filter((item) => item.type === 'comment').length;
  const replyPosts = Object.values(context.state.posts).filter(
    (item) => item.appId === 'twitter' && (item.parentId === post.id || item.targetId === post.id),
  ).length;
  return { replyCount: replyPosts + commentCount, likeCount };
}

function contextLine(_card: HTMLElement, text: string): HTMLElement {
  const line = element('div', { className: 'phone-tweet-context' });
  line.append(renderPhoneIcon('repost', 'phone-tweet-context-icon'), element('span', { text }));
  return line;
}

function tweetAction(count: string, icon: 'reply' | 'repost' | 'heart' | 'share', action: () => void | Promise<void>): HTMLButtonElement {
  const control = button('', 'phone-tweet-action', action);
  control.append(renderPhoneIcon(icon));
  if (count) control.append(element('span', { text: count }));
  return control;
}

/** 评论区条目：回复贴（可继续回复）或评论互动（纯展示），统一按时间排序。 */
interface TweetComment {
  readonly key: string;
  readonly profileId: string;
  readonly content: string;
  readonly createdAt: number;
  readonly post?: PhonePost;
  /** 上级不是主推文时，标注「回复 @某人」。 */
  readonly replyToProfileId?: string;
}

/** 收集一条推文的全部评论：所有层级的回复贴 + 针对它们的评论互动。 */
function collectTweetComments(context: PhoneViewContext, root: PhonePost): readonly TweetComment[] {
  const comments: TweetComment[] = [];
  const threadIds = new Set<string>([root.id]);
  const posts = Object.values(context.state.posts).filter((post) => post.appId === 'twitter');
  // 回复可能引用更深层的回复，反复扫描直到没有新增（手机数据量小，无性能压力）。
  let added = true;
  while (added) {
    added = false;
    for (const post of posts) {
      if (threadIds.has(post.id)) continue;
      const parentId = post.parentId ?? post.targetId;
      if (!parentId || !threadIds.has(parentId)) continue;
      threadIds.add(post.id);
      added = true;
      const parent = parentId === root.id ? undefined : context.state.posts[parentId];
      comments.push({
        key: post.id,
        profileId: post.profileId,
        content: post.content,
        createdAt: post.createdAt,
        post,
        ...(parent ? { replyToProfileId: parent.profileId } : {}),
      });
    }
  }
  for (const interaction of Object.values(context.state.interactions)) {
    if (interaction.appId !== 'twitter' || interaction.type !== 'comment') continue;
    if (!threadIds.has(interaction.targetId)) continue;
    const target = interaction.targetId === root.id ? undefined : context.state.posts[interaction.targetId];
    comments.push({
      key: interaction.id,
      profileId: interaction.actorProfileId,
      content: interaction.content ?? '',
      createdAt: interaction.createdAt,
      ...(target ? { replyToProfileId: target.profileId } : {}),
    });
  }
  return comments.sort((a, b) => a.createdAt - b.createdAt);
}

/** 推文详情页：主推文 + 评论区 + 底部回复输入框。 */
function renderTweetDetail(context: PhoneViewContext, post: PhonePost): HTMLElement {
  const page = element('div', { className: 'phone-chat phone-twitter-page phone-twitter-detail has-header' });
  const header = element('div', { className: 'phone-twitter-subheader' });
  header.append(element('span', { className: 'phone-twitter-subheader-label', text: '帖子' }));

  // 底部回复框先创建，主推文的「回复」按钮可以聚焦到它。
  const composer = element('form', { className: 'phone-composer phone-twitter-composer-bar' });
  const input = element('input', {
    className: 'phone-input',
    attributes: { type: 'text', placeholder: '发布你的回复', maxlength: '1200', autocomplete: 'off' },
  });
  const send = button('', 'phone-twitter-send-button');
  send.setAttribute('aria-label', '发布回复');
  send.title = '回复';
  send.append(renderPhoneIcon('send', 'phone-svg-icon phone-twitter-send-icon'));
  const submit = async () => {
    const content = input.value.trim();
    if (!content) return;
    input.disabled = true;
    send.disabled = true;
    try {
      await context.commands.createUserPost('twitter', 'twitter-reply', content, { parentId: post.id });
      input.value = '';
      context.showNotice('回复已发布，角色回应将在下轮生成', 'success');
    } finally {
      input.disabled = false;
      send.disabled = false;
    }
  };
  composer.addEventListener('submit', (event) => {
    event.preventDefault();
    void submit().catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });
  send.addEventListener('click', () => {
    void submit().catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });
  composer.append(input, send);

  const scroll = element('div', { className: 'phone-twitter-detail-scroll' });

  // 主推文：大字正文 + 完整时间 + 操作行。
  const profile = context.state.profiles[post.profileId];
  const identity = twitterIdentity(profile);
  const main = element('article', { className: 'phone-tweet-card phone-tweet-detail-card' });
  if (post.kind === 'twitter-reply') main.append(contextLine(main, '回复了一条动态'));
  const head = element('header', { className: 'phone-tweet-head' });
  const identityBox = element('div', { className: 'phone-list-main' });
  const nameLine = element('div', { className: 'phone-tweet-name-line' });
  nameLine.append(
    element('strong', { text: identity.name }),
    element('span', { text: identity.handle }),
  );
  identityBox.append(nameLine);
  head.append(twitterAvatar(profile), identityBox);
  const follow = renderFollowButton(context, post.profileId);
  if (follow) head.append(follow);
  main.append(
    head,
    renderRichContent(post.content, richContextOf(context), { className: 'phone-tweet-content phone-tweet-detail-content', block: true }),
  );
  const quoted = post.kind === 'twitter-repost' && post.targetId ? context.state.posts[post.targetId] : undefined;
  if (quoted) main.append(renderQuotedTweet(context, quoted));
  main.append(element('time', { className: 'phone-tweet-detail-time', text: formatTime(post.createdAt) }));
  const { replyCount, likeCount } = tweetEngagement(context, post);
  const actions = element('div', { className: 'phone-tweet-actions phone-tweet-detail-actions' });
  actions.append(
    tweetAction(replyCount > 0 ? String(replyCount) : '', 'reply', () => input.focus()),
    tweetAction('', 'repost', () => context.showNotice('转发功能将在后续版本开放', 'info')),
    tweetAction(likeCount > 0 ? String(likeCount) : '', 'heart', () => interactWithPost(context, post, 'like')),
    tweetAction('', 'share', () => context.showNotice('已复制到剪贴板（模拟）', 'info')),
    renderTwitterDelete(context, post.id, postLabelOf(post), post.content, () => {
      twitterDetailPostId = null;
      context.navigate(twitterDetailReturnRoute);
    }),
  );
  main.append(actions);
  scroll.append(main);

  // 评论区。
  const comments = collectTweetComments(context, post);
  scroll.append(element('div', {
    className: 'phone-twitter-comment-head',
    text: comments.length > 0 ? `评论 · ${comments.length}` : '评论',
  }));
  if (comments.length === 0) {
    scroll.append(renderTwitterEmpty('还没有评论', '发布第一条回复，或等待角色在下轮生成中加入讨论。'));
  } else {
    for (const comment of comments) scroll.append(renderTweetComment(context, comment));
  }

  page.append(header, scroll, composer);
  return page;
}

function renderTweetComment(context: PhoneViewContext, comment: TweetComment): HTMLElement {
  const profile = context.state.profiles[comment.profileId];
  const identity = twitterIdentity(profile);
  const row = element('article', { className: 'phone-twitter-comment' });
  row.append(twitterAvatar(profile, 'phone-avatar phone-twitter-avatar phone-twitter-comment-avatar'));
  const copy = element('div', { className: 'phone-twitter-comment-copy' });
  const nameLine = element('div', { className: 'phone-tweet-name-line' });
  nameLine.append(
    element('strong', { text: identity.name }),
    element('span', { text: identity.handle }),
    element('span', { className: 'phone-tweet-dot', text: '·' }),
    element('time', { className: 'phone-tweet-time', text: formatTime(comment.createdAt) }),
  );
  copy.append(nameLine);
  if (comment.replyToProfileId) {
    copy.append(element('span', {
      className: 'phone-twitter-comment-replyto',
      text: `回复 ${twitterIdentity(context.state.profiles[comment.replyToProfileId]).handle}`,
    }));
  }
  copy.append(renderRichContent(comment.content, richContextOf(context), { className: 'phone-twitter-comment-content', block: true }));
  const replyTarget = comment.post;
  const controls = element('div', { className: 'phone-twitter-comment-controls' });
  if (replyTarget) {
    controls.append(button('回复', 'phone-twitter-comment-reply', () => void replyToPost(context, replyTarget)));
  }
  controls.append(renderTwitterDelete(
    context,
    replyTarget?.id ?? comment.key,
    replyTarget ? '回复' : '评论',
    comment.content,
    () => context.navigate('twitterPost'),
  ));
  copy.append(controls);
  row.append(copy);
  return row;
}

function renderDirectMessageList(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-twitter-page phone-twitter-dm-page' });
  const conversations = Object.values(context.state.conversations)
    .filter((conversation) => conversation.appId === 'twitter')
    .sort((a, b) => b.updatedAt - a.updatedAt);
  const selectable = conversations.filter((conversation) => conversation.kind === 'direct');
  // 会话被删除或切换聊天后清理残留选择，避免删除到已不存在的对象。
  const knownIds = new Set(selectable.map((conversation) => conversation.id));
  for (const id of [...twitterDmSelection]) if (!knownIds.has(id)) twitterDmSelection.delete(id);
  if (twitterDmSelectMode && selectable.length === 0) twitterDmSelectMode = false;

  const header = element('div', { className: 'phone-twitter-subheader' });
  const autoMatch = button('自动匹配', 'phone-button phone-button-secondary phone-button-compact', async () => {
    autoMatch.disabled = true;
    context.showNotice('正在从当前世界书批量匹配私信对象…', 'info');
    try {
      const result = await context.autoMatchContact({ platform: 'twitter' });
      context.showNotice(
        describeContactMatchResult(result, '私信对象'),
        result.contacts.length > 0 ? 'success' : 'info',
      );
      const single = result.contacts.length === 1 ? result.contacts[0] : undefined;
      if (single) context.openConversation(single.conversationId);
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      autoMatch.disabled = false;
    }
  });
  header.append(
    element('span', { className: 'phone-twitter-subheader-label', text: '私信' }),
    autoMatch,
    button('新消息', 'phone-button phone-button-primary phone-button-compact', () => void createDirectMessage(context)),
  );

  const list = element('div', { className: 'phone-twitter-dm-list' });
  const latestByConversation = latestMessagesByConversation(context.state);
  const toolbar = renderDmSelectionToolbar(context, selectable);
  for (const conversation of conversations) {
    const peerId = conversation.participantIds.find((id) => id !== SELF_PROFILE_ID);
    const peer = context.state.profiles[peerId ?? ''];
    const identity = twitterIdentity(peer);
    const latest = latestByConversation.get(conversation.id);
    const selectableItem = conversation.kind === 'direct';
    const item = button('', 'phone-twitter-dm-item', () => {
      if (twitterDmSelectMode && selectableItem) {
        toggleDmSelection(conversation.id, item, mark);
        toolbar.refresh();
        return;
      }
      context.openConversation(conversation.id);
      if (conversation.unreadCount > 0) void context.commands.markConversationRead(conversation.id);
    });
    const mark = element('span', { className: 'phone-list-select-check', attributes: { 'aria-hidden': 'true' } });
    if (twitterDmSelectMode && selectableItem) item.append(mark);
    item.append(
      twitterAvatar(peer),
      element('span', { className: 'phone-list-main' }),
    );
    const copy = item.querySelector<HTMLElement>('.phone-list-main');
    const titleLine = element('span', { className: 'phone-twitter-dm-title-line' });
    titleLine.append(
      element('strong', { text: identity.name }),
      element('small', { text: identity.handle }),
      element('time', { text: formatTime(conversation.updatedAt) }),
    );
    copy?.append(
      titleLine,
      element('span', {
        className: 'phone-twitter-dm-preview',
        text: latest ? replaceImageMarkers(describeMessagePreview(latest, '开始一段私信')) : '开始一段私信',
      }),
    );
    if (conversation.unreadCount > 0) item.append(element('span', { className: 'phone-badge', text: String(conversation.unreadCount) }));
    if (twitterDmSelectMode && selectableItem) {
      const selected = twitterDmSelection.has(conversation.id);
      item.classList.toggle('is-selected', selected);
      item.setAttribute('aria-pressed', String(selected));
      mark.textContent = selected ? '✓' : '';
    }
    list.append(item);
  }
  if (conversations.length === 0) list.append(renderTwitterEmpty('还没有私信', '点击右上角“新消息”联系一位联系人。'));
  page.append(header, ...(selectable.length > 0 ? [toolbar.element] : []), list);
  return page;
}

function toggleDmSelection(conversationId: string, item: HTMLElement, mark: HTMLElement): void {
  if (twitterDmSelection.has(conversationId)) twitterDmSelection.delete(conversationId);
  else twitterDmSelection.add(conversationId);
  const selected = twitterDmSelection.has(conversationId);
  item.classList.toggle('is-selected', selected);
  item.setAttribute('aria-pressed', String(selected));
  mark.textContent = selected ? '✓' : '';
}

/** 私信多选工具条：进入多选、全选/取消、显示已选数量并执行对象删除。 */
function renderDmSelectionToolbar(
  context: PhoneViewContext,
  selectable: readonly Conversation[],
): { readonly element: HTMLElement; readonly refresh: () => void } {
  const toolbar = element('div', { className: 'phone-list-select-toolbar' });
  const count = element('span', { className: 'phone-list-select-count' });
  const remove = button('', 'phone-list-select-action', async () => {
    if (!twitterDmSelectMode) {
      twitterDmSelectMode = true;
      twitterDmSelection.clear();
      context.navigate('twitterDm');
      return;
    }
    const targets = selectable.filter((conversation) => twitterDmSelection.has(conversation.id));
    if (targets.length === 0) {
      context.showNotice('请先选择要删除的私信对象', 'info');
      return;
    }
    const names = targets
      .map((conversation) => twitterIdentity(
        context.state.profiles[conversation.participantIds.find((id) => id !== SELF_PROFILE_ID) ?? ''],
      ).name)
      .join('、');
    const messageCount = Object.values(context.state.messages)
      .filter((message) => targets.some((conversation) => conversation.id === message.conversationId)).length;
    const confirmed = await context.showConfirm({
      title: '删除私信对象',
      message: `将删除 ${targets.length} 位私信对象、${targets.length} 个会话和全部 ${messageCount} 条私信，`
        + '包括还在等待生成的消息。删除后无法恢复；重新添加同一推特号会得到全新的空会话。',
      detail: names,
      confirmLabel: '删除',
      danger: true,
    });
    if (!confirmed) return;
    remove.disabled = true;
    try {
      const report = await context.commands.deleteTwitterContacts(targets.map((conversation) => conversation.id));
      twitterDmSelectMode = false;
      twitterDmSelection.clear();
      context.showNotice(
        `已删除 ${report.deletedConversationCount} 位私信对象与 ${report.deletedMessageCount} 条私信`,
        'success',
      );
      context.navigate('twitterDm');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      remove.disabled = false;
    }
  });
  remove.append(renderPhoneIcon('trash', 'phone-svg-icon'), element('span', { text: '删除私信对象' }), count);
  const refresh = () => {
    count.textContent = twitterDmSelection.size > 0 ? `已选 ${twitterDmSelection.size}` : '';
    remove.classList.toggle('has-selection', twitterDmSelection.size > 0);
  };
  refresh();
  if (!twitterDmSelectMode) {
    toolbar.append(remove);
    return { element: toolbar, refresh };
  }
  const allSelected = selectable.length > 0 && selectable.every((conversation) => twitterDmSelection.has(conversation.id));
  const toggleAll = button(allSelected ? '取消全选' : '全选', 'phone-button phone-button-secondary phone-button-compact', () => {
    if (allSelected) twitterDmSelection.clear();
    else for (const conversation of selectable) twitterDmSelection.add(conversation.id);
    context.navigate('twitterDm');
  });
  const cancel = button('取消', 'phone-button phone-button-secondary phone-button-compact', () => {
    twitterDmSelectMode = false;
    twitterDmSelection.clear();
    context.navigate('twitterDm');
  });
  toolbar.append(
    element('span', { className: 'phone-list-select-hint', text: '点击私信条目进行多选' }),
    toggleAll,
    cancel,
    remove,
  );
  return { element: toolbar, refresh };
}

/**
 * 新私信：直接输入对方推特号即可创建会话。
 * 推特与微信互相独立，不需要先在微信通讯录中添加。
 */
async function createDirectMessage(context: PhoneViewContext): Promise<void> {
  const values = await context.showModal('新私信', [
    { name: 'handle', label: '对方推特号（例如 @night_owl）', required: true, placeholder: '@handle' },
    { name: 'name', label: '显示昵称（可选，默认使用推特号）', placeholder: '昵称' },
  ]);
  if (!values?.handle?.trim()) return;
  const handle = `@${values.handle.trim().replace(/^@+/, '')}`;

  // 已有相同推特号的档案时直接复用，不重复创建。
  const existingProfile = Object.values(context.state.profiles).find(
    (item) => item.id !== SELF_PROFILE_ID && item.aliases.twitter === handle,
  );
  if (existingProfile) {
    const existingConversation = Object.values(context.state.conversations).find(
      (conversation) => conversation.appId === 'twitter'
        && conversation.kind === 'direct'
        && conversation.participantIds.includes(existingProfile.id),
    );
    if (existingConversation) {
      context.openConversation(existingConversation.id);
      return;
    }
    try {
      const conversation = await context.commands.createConversation({
        appId: 'twitter',
        kind: 'direct',
        title: `${existingProfile.displayName} ${handle}`,
        participantIds: [SELF_PROFILE_ID, existingProfile.id],
      });
      context.openConversation(conversation.id);
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
    return;
  }

  try {
    const { conversation } = await context.commands.addTwitterContact(handle, values.name ?? '');
    context.openConversation(conversation.id);
    context.showNotice(`已创建与 ${handle} 的私信`, 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

function renderDirectMessage(context: PhoneViewContext, conversation: Conversation): HTMLElement {
  if (conversation.unreadCount > 0) void context.commands.markConversationRead(conversation.id);
  const page = element('div', { className: 'phone-chat phone-twitter-chat' });

  // 对话顶部的对方资料条：点击头像可配置绑定角色。
  const peerId = conversation.participantIds.find((id) => id !== SELF_PROFILE_ID);
  const peer = context.state.profiles[peerId ?? ''];
  if (peer) {
    page.classList.add('has-header');
    const identity = twitterIdentity(peer);
    const strip = element('div', { className: 'phone-twitter-dm-peer' });
    const avatarButton = button('', 'phone-twitter-dm-peer-avatar', () => openTwitterProfileEditor(context, peer.id, false));
    avatarButton.append(twitterAvatar(peer));
    avatarButton.title = '点击配置资料与绑定角色';
    const copy = element('span', { className: 'phone-twitter-dm-peer-copy' });
    copy.append(
      element('strong', { text: identity.name }),
      element('small', {
        text: peer.boundCharacter ? `${identity.handle} · 绑定：${peer.boundCharacter}` : `${identity.handle} · 点头像绑定角色`,
      }),
    );
    strip.append(avatarButton, copy);
    page.append(strip);
  }

  const list = element('div', { className: 'phone-message-list phone-twitter-message-list' });
  const messages = selectRecentMessages(context.state, conversation.id, 120);
  if (messages.length === 0) {
    list.append(renderTwitterEmpty('还没有私信', '发送第一条消息，稍后统一生成回复。'));
  } else {
    for (const message of messages) list.append(renderMessage(context, message));
  }
  const composer = element('form', { className: 'phone-composer phone-twitter-composer-bar' });
  const input = element('input', {
    className: 'phone-input',
    attributes: { type: 'text', placeholder: '发送私信', maxlength: '1200', autocomplete: 'off' },
  });
  const send = button('', 'phone-twitter-send-button');
  send.setAttribute('aria-label', '发送私信');
  send.title = '发送';
  send.append(renderPhoneIcon('send', 'phone-svg-icon phone-twitter-send-icon'));
  const { panel, toggle } = createChatExtPanel(context, [
    { label: '图片', handler: () => sendMediaMessage(context, conversation.id, 'image') },
    { label: '视频', handler: () => sendMediaMessage(context, conversation.id, 'video') },
    { label: '强行介入', handler: () => sendDirectiveMessage(context, conversation.id) },
  ]);
  const submit = async () => {
    const content = input.value.trim();
    if (!content) return;
    input.disabled = true;
    send.disabled = true;
    try {
      await context.commands.queueMessage(conversation.id, content);
      input.value = '';
      context.showNotice('私信已发送，等待统一生成回复', 'success');
    } finally {
      input.disabled = false;
      send.disabled = false;
      input.focus();
    }
  };
  composer.addEventListener('submit', (event) => {
    event.preventDefault();
    void submit().catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });
  send.addEventListener('click', () => {
    void submit().catch((error: unknown) => context.showNotice(error instanceof Error ? error.message : String(error), 'error'));
  });
  composer.append(input, toggle, send);
  const composerWrap = element('div', { className: 'phone-chat-composer-wrap' });
  composerWrap.append(composer, panel);
  page.append(list, composerWrap);
  scrollToLatestMessage(list);
  return page;
}

function renderMessage(context: PhoneViewContext, message: PhoneMessage): HTMLElement {
  const outgoing = message.direction === 'outgoing';
  const row = element('div', { className: `phone-message-row ${outgoing ? 'is-outgoing' : 'is-incoming'}` });
  const stack = element('div', { className: 'phone-message-stack' });
  appendMessageBody(stack, renderDirectMessageBody(context, message));
  stack.append(
    element('span', {
      className: 'phone-message-meta',
      text: `${formatTime(message.createdAt)} · ${message.status === 'queued' ? '等待回复' : '已送达'}`,
    }),
  );
  const control = renderQueuedMessageDelete(context, message) ?? renderMessageRollback(context, message);
  if (!outgoing) {
    const profile = context.state.profiles[message.profileId];
    const avatar = twitterAvatar(profile, 'phone-avatar phone-twitter-avatar phone-avatar-clickable');
    if (profile) {
      avatar.title = '点击配置资料与绑定角色';
      avatar.addEventListener('click', (event) => {
        event.stopPropagation();
        openTwitterProfileEditor(context, profile.id, false);
      });
    }
    row.append(avatar, stack);
    if (control) row.append(control);
    return row;
  }
  if (control) row.append(control);
  row.append(stack);
  return row;
}

function renderDirectMessageBody(context: PhoneViewContext, message: PhoneMessage): HTMLElement {
  const kind = message.kind ?? 'text';
  if (kind === 'image' || kind === 'video') return renderMediaMessageCard(message, kind);
  if (kind === 'directive') return renderDirectiveCard(message);
  return renderRichContent(message.content, richContextOf(context));
}

function renderTwitterEmpty(title: string, detail: string): HTMLElement {
  const empty = element('div', { className: 'phone-empty phone-twitter-empty' });
  empty.append(renderPhoneIcon('twitter'), element('strong', { text: title }), element('span', { text: detail }));
  return empty;
}

async function interactWithPost(
  context: PhoneViewContext,
  post: PhonePost,
  type: 'like' | 'comment',
  content = '',
): Promise<void> {
  try {
    await context.commands.createUserInteraction('twitter', type, post.id, content);
    context.showNotice(type === 'like' ? '已喜欢' : '回复已发布', 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

async function replyToPost(context: PhoneViewContext, post: PhonePost): Promise<void> {
  const content = (await context.showModal('回复动态', [{ name: 'content', label: '回复内容', type: 'textarea', required: true }]))?.content;
  if (!content?.trim()) return;
  try {
    await context.commands.createUserPost('twitter', 'twitter-reply', content, { parentId: post.id });
    context.showNotice('回复已进入本轮队列', 'success');
  } catch (error) {
    context.showNotice(error instanceof Error ? error.message : String(error), 'error');
  }
}

/**
 * 主时间线只展示能独立阅读的内容：主贴与转发。
 * 回复贴留在推文详情的评论区，避免信息流被拆成一句一条的隔空对话。
 */
function selectTwitterFeedPosts(
  context: PhoneViewContext,
  tab: TwitterTimelineTab = 'recommended',
): readonly PhonePost[] {
  return selectTwitterPosts(context, tab).filter((post) => post.kind !== 'twitter-reply');
}

function selectTwitterPosts(context: PhoneViewContext, tab: TwitterTimelineTab = 'recommended'): readonly PhonePost[] {
  const all = [...context.state.postOrder].reverse().flatMap((id) => {
    const post = context.state.posts[id];
    return post?.appId === 'twitter' ? [post] : [];
  });
  if (tab === 'recommended') return all;
  const followedIds = new Set(
    Object.values(context.state.interactions)
      .filter((interaction) => interaction.appId === 'twitter'
        && interaction.type === 'follow'
        && interaction.actorProfileId === SELF_PROFILE_ID)
      .map((interaction) => interaction.targetId),
  );
  return all.filter((post) => followedIds.has(post.profileId));
}

function topTrend(context: PhoneViewContext): string {
  return collectTrends(context)[0]?.[0] ?? '#精彩时刻';
}

function collectTrends(context: PhoneViewContext): readonly (readonly [string, number])[] {
  const counts = new Map<string, number>();
  for (const post of selectTwitterPosts(context)) {
    for (const match of post.content.matchAll(/#[^\s#]{1,24}/g)) {
      const tag = match[0];
      counts.set(tag, (counts.get(tag) ?? 0) + 1);
    }
  }
  return [...counts.entries()].sort((a, b) => b[1] - a[1]);
}
