import type { PhoneAppDefinition, PhoneViewContext } from './app-types.js';
import { listAlbumImages, deleteAlbumImage } from '../storage/image-store.js';
import { button, element } from '../ui/dom.js';
import { renderPhoneIcon } from '../ui/phone-icon.js';
import { showImagePreview } from '../ui/image-preview.js';

function formatSavedAt(timestamp: number): string {
  return new Intl.DateTimeFormat('zh-CN', {
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  }).format(timestamp);
}

function fileTypeLabel(blob: Blob): string {
  const subtype = blob.type.split('/')[1]?.toUpperCase();
  return subtype || '图片';
}

function renderAlbum(context: PhoneViewContext): HTMLElement {
  const root = element('section', { className: 'phone-page phone-album' });
  const header = element('header', { className: 'phone-album-header' });
  const headingCopy = element('div', { className: 'phone-album-heading-copy' });
  headingCopy.append(
    element('span', { className: 'phone-album-eyebrow', text: '视觉记忆' }),
    element('h1', { className: 'phone-section-title', text: context.appTitle('相册') }),
    element('p', { className: 'phone-album-description', text: '保存聊天中生成的每一个灵感瞬间。' }),
  );
  const headerIcon = element('div', { className: 'phone-album-header-icon' });
  headerIcon.append(renderPhoneIcon('camera', 'phone-album-camera-icon'));
  header.append(headingCopy, headerIcon);

  const summary = element('div', { className: 'phone-album-summary' });
  const status = element('p', { className: 'phone-album-status', attributes: { role: 'status', 'aria-live': 'polite' } });
  summary.append(renderPhoneIcon('camera', 'phone-album-status-icon'), status);

  const grid = element('div', { className: 'phone-album-grid' });
  const empty = element('div', { className: 'phone-album-empty' });
  empty.hidden = true;
  const emptyIcon = element('div', { className: 'phone-album-empty-icon' });
  emptyIcon.append(renderPhoneIcon('camera'));
  empty.append(
    emptyIcon,
    element('strong', { text: '这里还没有图片' }),
    element('p', { text: '在聊天中使用生图功能后，生成的图片会自动收纳到这里。' }),
    element('span', { className: 'phone-album-empty-hint', text: '图片只保存在当前聊天空间中' }),
  );

  const skeletons = Array.from({ length: 4 }, () => element('div', { className: 'phone-album-skeleton' }));
  grid.append(...skeletons);
  status.textContent = '正在整理图片…';
  root.append(header, summary, grid, empty);

  const scope = context.state.scopeId;
  const updateEmptyState = (hasImages: boolean): void => {
    grid.hidden = !hasImages;
    empty.hidden = hasImages;
  };
  const updateStatus = (count: number): void => {
    status.textContent = count > 0 ? `${count} 张图片` : '暂无图片';
  };

  void listAlbumImages(scope).then((images) => {
    grid.replaceChildren();
    updateStatus(images.length);
    updateEmptyState(images.length > 0);

    for (const record of images) {
      const card = element('article', { className: 'phone-album-card' });
      const media = button('', 'phone-album-preview');
      media.setAttribute('aria-label', `预览 ${formatSavedAt(record.savedAt)} 保存的图片`);
      const image = element('img', { attributes: { alt: '生成的图片', loading: 'lazy' } });
      media.append(image);
      const reader = new FileReader();
      reader.onload = () => { image.src = String(reader.result ?? ''); };
      reader.readAsDataURL(record.blob);
      media.addEventListener('click', () => {
        if (image.src) showImagePreview(image, image.src);
      });

      const footer = element('div', { className: 'phone-album-card-footer' });
      const metadata = element('div', { className: 'phone-album-card-meta' });
      metadata.append(
        element('strong', { text: formatSavedAt(record.savedAt) }),
        element('span', { text: fileTypeLabel(record.blob) }),
      );
      const actions = element('div', { className: 'phone-album-card-actions' });
      const download = button('下载', 'phone-button phone-button-secondary phone-album-action');
      download.setAttribute('aria-label', `下载 ${formatSavedAt(record.savedAt)} 保存的图片`);
      download.addEventListener('click', () => {
        const url = URL.createObjectURL(record.blob);
        const link = element('a', {
          attributes: {
            href: url,
            download: `图片-${record.savedAt}.${record.blob.type.split('/')[1]?.replace('jpeg', 'jpg') || 'png'}`,
          },
        });
        root.append(link);
        link.click();
        link.remove();
        window.setTimeout(() => URL.revokeObjectURL(url), 1000);
      });
      const remove = button('删除', 'phone-button phone-button-ghost phone-album-action phone-album-delete');
      remove.setAttribute('aria-label', `删除 ${formatSavedAt(record.savedAt)} 保存的图片`);
      remove.addEventListener('click', async () => {
        remove.disabled = true;
        try {
          await deleteAlbumImage(scope, record.key);
          card.remove();
          const remaining = grid.querySelectorAll('.phone-album-card').length;
          updateStatus(remaining);
          updateEmptyState(remaining > 0);
        } catch {
          context.showNotice('删除图片失败，请重试。', 'error');
        } finally {
          remove.disabled = false;
        }
      });
      actions.append(download, remove);
      footer.append(metadata, actions);
      card.append(media, footer);
      grid.append(card);
    }
  }).catch(() => {
    grid.replaceChildren();
    grid.hidden = true;
    empty.hidden = false;
    empty.querySelector('strong')!.textContent = '相册暂时无法打开';
    empty.querySelector('p')!.textContent = '图片存储读取失败，请关闭后重新打开相册。';
    empty.querySelector('.phone-album-empty-hint')!.textContent = '如果问题持续，请检查浏览器的本地存储权限';
    status.textContent = '读取失败';
  });
  return root;
}

export function createAlbumApp(): PhoneAppDefinition {
  return { id: 'album', label: '相册', icon: '相机', navigation: [], render: renderAlbum };
}