import { CANON_LIBRARY_VERSION, type CanonChunk, type CanonDocument, type CanonSourceKind } from './model.js';

/** 标准化前的原始资料：宿主字段差异在调用方消化，这里只接受纯文本。 */
export interface CanonRawDocument {
  readonly kind: CanonSourceKind;
  readonly name: string;
  readonly text: string;
  readonly updatedAt?: number;
}

export interface CanonSourceBundle {
  readonly title: string;
  readonly fingerprint: string;
  readonly documents: readonly CanonDocument[];
  readonly chunks: readonly CanonChunk[];
}

/** 单块目标长度：足够容纳一段完整设定，又不至于让单块挤掉其他召回结果。 */
const CHUNK_TARGET_CHARS = 1_100;
const CHUNK_HARD_LIMIT = 1_800;
/**
 * 单份资料的分块上限：只用于兜住异常输入（例如整份都是一行的二进制文本），
 * 按目标块长换算约两千万字，整本长篇小说不会被截掉。
 */
const MAX_CHUNKS_PER_DOCUMENT = 20_000;
const HEADING_PATTERN = /^(?:#{1,6}\s+|第[零一二三四五六七八九十百千0-9]+[章节回]|【[^】]{1,40}】|=+\s*[^=]{1,40}\s*=+)/;

export function normalizeCanonSources(
  raws: readonly CanonRawDocument[],
  title = '',
): CanonSourceBundle {
  const documents: CanonDocument[] = [];
  const chunks: CanonChunk[] = [];
  for (const raw of raws) {
    const text = cleanText(raw.text);
    if (!text) continue;
    const documentId = documentIdOf(raw.kind, raw.name, documents.length);
    documents.push({
      id: documentId,
      kind: raw.kind,
      name: raw.name.trim() || `${raw.kind}-${documents.length + 1}`,
      charCount: text.length,
      updatedAt: Number.isFinite(raw.updatedAt) ? Number(raw.updatedAt) : 0,
    });
    chunks.push(...chunkDocument(documentId, text));
  }
  return {
    title: title.trim() || documents.find((document) => document.kind === 'card')?.name || '未命名作品',
    fingerprint: fingerprintOf(documents, chunks),
    documents,
    chunks,
  };
}

/** 按标题与段落切块：优先在标题处断开，其次在空行，最后才硬切。 */
export function chunkDocument(documentId: string, text: string): readonly CanonChunk[] {
  const blocks = text.split(/\n{2,}/).map((block) => block.trim()).filter(Boolean);
  const chunks: CanonChunk[] = [];
  let heading = '';
  let buffer: string[] = [];
  let bufferLength = 0;

  const flush = (): void => {
    if (buffer.length === 0 || chunks.length >= MAX_CHUNKS_PER_DOCUMENT) {
      buffer = [];
      bufferLength = 0;
      return;
    }
    const index = chunks.length;
    chunks.push({
      id: `${documentId}#${index}`,
      documentId,
      index,
      heading,
      text: buffer.join('\n\n'),
    });
    buffer = [];
    bufferLength = 0;
  };

  for (const block of blocks) {
    // 标题常与正文同处一个段落块：先摘出首行标题，剩余部分仍按正文处理，避免正文被当成标题丢掉。
    const { heading: blockHeading, body } = splitHeading(block);
    if (blockHeading) {
      flush();
      heading = blockHeading;
    }
    if (!body) continue;
    for (const piece of splitLongBlock(body)) {
      if (bufferLength > 0 && bufferLength + piece.length > CHUNK_TARGET_CHARS) flush();
      buffer.push(piece);
      bufferLength += piece.length;
    }
  }
  flush();
  return chunks;
}

function splitHeading(block: string): { readonly heading: string; readonly body: string } {
  const [firstLine = '', ...rest] = block.split('\n');
  const line = firstLine.trim();
  if (!HEADING_PATTERN.test(line) || line.length > 80) return { heading: '', body: block };
  return {
    heading: line.replace(/^#+\s*/, '').replace(/^=+\s*|\s*=+$/g, '').slice(0, 80),
    body: rest.join('\n').trim(),
  };
}

function splitLongBlock(block: string): readonly string[] {
  if (block.length <= CHUNK_HARD_LIMIT) return [block];
  const sentences = block.split(/(?<=[。！？!?…】”』」\n])/);
  const pieces: string[] = [];
  let current = '';
  for (const sentence of sentences) {
    if (current.length + sentence.length > CHUNK_HARD_LIMIT && current) {
      pieces.push(current);
      current = '';
    }
    current += sentence;
    if (current.length >= CHUNK_HARD_LIMIT) {
      pieces.push(current);
      current = '';
    }
  }
  if (current.trim()) pieces.push(current);
  return pieces.map((piece) => piece.trim()).filter(Boolean);
}

/** 清理 HTML 标签、零宽字符与多余空行，保留段落结构。 */
export function cleanText(value: string): string {
  return value
    .replace(/\0/g, '')
    .replace(/\r\n?/g, '\n')
    .replace(/<\/?(?:script|style)[^>]*>/gi, ' ')
    .replace(/<[^>\n]{1,200}>/g, ' ')
    .replace(/[\u200B-\u200D\uFEFF]/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function documentIdOf(kind: CanonSourceKind, name: string, index: number): string {
  return `${kind}:${index}:${hashText(name.trim())}`;
}

/** 来源指纹：资料未变化时可直接复用已建立的原著库，避免重复消耗 API。 */
export function fingerprintOf(
  documents: readonly CanonDocument[],
  chunks: readonly CanonChunk[],
): string {
  const signature = [
    `v${CANON_LIBRARY_VERSION}`,
    ...documents.map((document) => `${document.kind}|${document.name}|${document.charCount}`),
    `chunks:${chunks.length}`,
    `body:${hashText(chunks.map((chunk) => chunk.text).join('\u0001'))}`,
  ].join('\n');
  return hashText(signature);
}

export function hashText(value: string): string {
  let hash = 2_166_136_261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16_777_619);
  }
  return (hash >>> 0).toString(36);
}