import {
  memoryLabelOf,
  memorySourceOf,
  type MemoryItem,
  type MemorySource,
} from '../domain/model.js';
import { extractStoryContext, type StoryAnalysis } from './story-context.js';
import { neutralizeHostTemplates } from './content-safety.js';
import { FANFIC_PROMPT_OPEN_TAG } from '../fanfic/context-render.js';

export const STORY_MEMORY_INJECTION_ITEM_LIMIT = 10;
export const STORY_MEMORY_PROMPT_OPEN_TAG = '<retrieved_story_memories>';
export const STORY_MEMORY_PROMPT_CLOSE_TAG = '</retrieved_story_memories>';
export const SQLITE_RECALL_PROMPT_OPEN_TAG = '<phone_memory_tables>';
export const SQLITE_RECALL_PROMPT_CLOSE_TAG = '</phone_memory_tables>';
/** 走同一条临时提示词通道注入的区块标记；用于在最终请求里判断是否已经带上。 */
export const INJECTED_PROMPT_MARKERS: readonly string[] = Object.freeze([
  STORY_MEMORY_PROMPT_OPEN_TAG,
  SQLITE_RECALL_PROMPT_OPEN_TAG,
  FANFIC_PROMPT_OPEN_TAG,
]);

/** 把预算化 recall pack 包成可注入区块；空 pack 返回空串（表示本轮不注入）。 */
export function renderSqliteRecallPrompt(packText: string): string {
  // 表里可能残留 MVU 卡的 EJS 模板源码，注入前必须中和，否则宿主渲染时会抛 not defined。
  const body = neutralizeHostTemplates(packText).trim();
  if (!body) return '';
  return [
    SQLITE_RECALL_PROMPT_OPEN_TAG,
    '以下是本聊天的结构化记忆表与按相关度召回的记忆行。表结构段说明存在哪些表，可据此判断能查到什么；固定记忆段是长期状态，召回记忆段是与当前输入相关的历史事实。',
    '这些内容是已记录的信息；标为“不确定”、相互矛盾或已被当前正文明确更新的状态，不得当作不可否定的事实。未列出的细节不要凭空编造。回复中不要暴露表名、标签名或检索过程。',
    body,
    SQLITE_RECALL_PROMPT_CLOSE_TAG,
  ].join('\n\n');
}

/** 记忆正文与同人剧情上下文合并成一条系统提示词，避免占用两个注入位置。 */
export function composeInjectedPrompt(memoryPrompt: string, extraPrompt: string): string {
  return [memoryPrompt.trim(), extraPrompt.trim()].filter(Boolean).join('\n\n');
}

/** 编号引用：正文编号只匹配正文记忆，总结编号同时匹配合并总结与手机总结。 */
interface RequestedMemoryReference {
  readonly seq: number;
  readonly sources: readonly MemorySource[];
}

const MEMORY_TYPE_LABELS: Readonly<Record<MemorySource, string>> = Object.freeze({
  memory: '记忆摘要',
  summary: '合并总结',
  phone: '手机内容总结',
});

export interface StoryMemoryInjectionResult {
  readonly prompt: string;
  readonly requestedIds: readonly number[];
  readonly resolvedIds: readonly number[];
  readonly filteredCount: number;
}

export interface StoryMemoryPromptSyncInput {
  readonly generationType: unknown;
  readonly dryRun: unknown;
  readonly enabled: boolean;
  readonly currentScopeId: string;
  readonly storeScopeId: string;
  readonly latestUserMessage: string;
  readonly memoryItems: readonly MemoryItem[];
  /**
   * 记忆召回之外的编号来源（向量召回）。与楼层里的 `<story_context>` 编号合并后一起装配，
   * 因此两种召回方式可以单开、也可以同时开。
   */
  readonly extraIds?: {
    readonly memoryIds?: readonly number[];
    readonly summaryIds?: readonly number[];
  };
  /** 与记忆正文共用同一条临时提示词的附加区块（同人剧情上下文）。 */
  readonly extraPrompt?: string;
  readonly updatePrompt: (content: string) => boolean | Promise<boolean>;
}

export interface StoryMemoryPromptSyncResult extends StoryMemoryInjectionResult {
  readonly status: 'injected' | 'cleared' | 'unavailable';
}

export interface ChatCompletionMemoryMessage {
  role?: unknown;
  content?: unknown;
  [key: string]: unknown;
}

export interface StoryMemoryFinalizationResult {
  readonly status: 'present' | 'repaired' | 'skipped' | 'unavailable';
  readonly messageIndex: number;
  readonly promptLength: number;
  readonly messageCount: number;
}

/** 判定本轮是否不该注入记忆正文的四个条件来源。 */
export interface StoryMemoryGateInput {
  readonly generationType: unknown;
  readonly dryRun: unknown;
  readonly currentScopeId: string;
  readonly storeScopeId: string;
}

/**
 * 本轮是否应该清空而不是注入记忆正文。
 *
 * 静默生成（手机内容自己就是 quiet 生成）、扮演补全、算 token 的 dryRun 与跨作用域请求
 * 都不参与注入。调用方在做召回之前先问一次，避免为这些请求白跑一次向量化/重排序。
 */
export function shouldClearStoryMemoryPrompt(input: StoryMemoryGateInput): boolean {
  const generationType = String(input.generationType ?? '').toLowerCase();
  return input.dryRun === true
    || generationType === 'quiet'
    || generationType === 'impersonate'
    || !input.currentScopeId
    || input.currentScopeId !== input.storeScopeId;
}

/** 每次宿主原生生成前重新读取最新用户楼层；重试和滑动无需依赖新的 MESSAGE_SENT。 */
export async function syncStoryMemoryPrompt(
  input: StoryMemoryPromptSyncInput,
): Promise<StoryMemoryPromptSyncResult> {
  // 静默生成、扮演补全与跨作用域的请求不注入任何内容，包括同人上下文。
  if (shouldClearStoryMemoryPrompt(input)) {
    const updated = await input.updatePrompt('');
    return { ...emptyInjectionResult(), status: updated ? 'cleared' : 'unavailable' };
  }

  const analysis = input.enabled ? extractStoryContext(input.latestUserMessage) : null;
  const requested = input.enabled ? mergeRequestedIds(analysis, input.extraIds) : null;
  const injection = requested
    ? buildStoryMemoryInjection(requested, input.memoryItems, input.currentScopeId)
    : emptyInjectionResult();
  const prompt = composeInjectedPrompt(injection.prompt, input.extraPrompt ?? '');
  const updated = await input.updatePrompt(prompt);
  return {
    ...injection,
    prompt,
    status: updated ? (prompt ? 'injected' : 'cleared') : 'unavailable',
  };
}

export function ensureStoryMemoryInChatCompletion(
  chat: unknown,
  prompt: string,
  dryRun: unknown,
): StoryMemoryFinalizationResult {
  const messages = Array.isArray(chat) ? chat as ChatCompletionMemoryMessage[] : null;
  const promptLength = prompt.length;
  if (!messages) {
    return { status: 'unavailable', messageIndex: -1, promptLength, messageCount: 0 };
  }
  if (dryRun === true || !prompt.trim()) {
    return { status: 'skipped', messageIndex: -1, promptLength, messageCount: messages.length };
  }

  const existingIndex = messages.findIndex((message) => contentContainsStoryMemory(message.content));
  if (existingIndex >= 0) {
    return {
      status: 'present',
      messageIndex: existingIndex,
      promptLength,
      messageCount: messages.length,
    };
  }

  const latestUserIndex = findLatestMessageIndex(messages, 'user');
  const insertIndex = latestUserIndex >= 0 ? latestUserIndex : messages.length;
  messages.splice(insertIndex, 0, {
    role: 'system',
    content: prompt,
  });
  return {
    status: 'repaired',
    messageIndex: insertIndex,
    promptLength,
    messageCount: messages.length,
  };
}

/**
 * 将剧情分析器选择的编号解析为当前聊天作用域内的真实记忆正文。
 * 此函数不读取宿主状态，也不修改聊天消息，可安全用于每次原生生成前重建临时提示词。
 */
export function buildStoryMemoryInjection(
  analysis: Pick<StoryAnalysis, 'memoryIds' | 'summaryIds'> | null,
  memoryItems: readonly MemoryItem[],
  scopeId: string,
): StoryMemoryInjectionResult {
  const rawReferences: readonly RequestedMemoryReference[] = analysis
    ? [
        ...analysis.memoryIds.map((seq) => ({ seq, sources: ['memory'] as const })),
        ...analysis.summaryIds.map((seq) => ({ seq, sources: ['summary', 'phone'] as const })),
      ]
    : [];
  const requestedIds = uniqueValidIds(rawReferences.map((reference) => reference.seq));
  const references = deduplicateReferences(rawReferences);
  const available = indexAvailableMemories(memoryItems, scopeId);
  const resolved: MemoryItem[] = [];

  for (const reference of references) {
    const item = reference.sources
      .map((source) => available.get(memoryKey(source, reference.seq)))
      .find((candidate) => candidate !== undefined);
    if (!item) continue;
    resolved.push(item);
    if (resolved.length >= STORY_MEMORY_INJECTION_ITEM_LIMIT) break;
  }

  const formatted = formatResolvedMemories(resolved);
  return {
    prompt: formatted.prompt,
    requestedIds,
    resolvedIds: formatted.items.map((item) => item.seq),
    filteredCount: Math.max(0, rawReferences.length - formatted.items.length),
  };
}

function contentContainsStoryMemory(content: unknown): boolean {
  const includesMarker = (text: string): boolean => INJECTED_PROMPT_MARKERS.some((marker) => text.includes(marker));
  if (typeof content === 'string') return includesMarker(content);
  if (!Array.isArray(content)) return false;
  return content.some((part) => {
    if (!part || typeof part !== 'object' || Array.isArray(part)) return false;
    const text = (part as Record<string, unknown>).text;
    return typeof text === 'string' && includesMarker(text);
  });
}

function findLatestMessageIndex(
  messages: readonly ChatCompletionMemoryMessage[],
  role: string,
): number {
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    if (messages[index]?.role === role) return index;
  }
  return -1;
}

function emptyInjectionResult(): StoryMemoryInjectionResult {
  return { prompt: '', requestedIds: [], resolvedIds: [], filteredCount: 0 };
}

/**
 * 合并两路召回给出的编号：记忆召回来自楼层里的 `<story_context>`，向量召回来自相似度打分。
 * 两者都没有结果时返回 null，调用方据此判定「本轮没有要注入的记忆」。
 */
function mergeRequestedIds(
  analysis: Pick<StoryAnalysis, 'memoryIds' | 'summaryIds'> | null,
  extraIds: StoryMemoryPromptSyncInput['extraIds'],
): Pick<StoryAnalysis, 'memoryIds' | 'summaryIds'> | null {
  const memoryIds = [...(analysis?.memoryIds ?? []), ...(extraIds?.memoryIds ?? [])];
  const summaryIds = [...(analysis?.summaryIds ?? []), ...(extraIds?.summaryIds ?? [])];
  if (memoryIds.length === 0 && summaryIds.length === 0) return analysis;
  return { memoryIds, summaryIds };
}

function deduplicateReferences(
  references: readonly RequestedMemoryReference[],
): readonly RequestedMemoryReference[] {
  const seen = new Set<string>();
  const unique: RequestedMemoryReference[] = [];
  for (const reference of references) {
    const key = `${reference.sources.join('|')}:${reference.seq}`;
    if (!isValidSequence(reference.seq) || seen.has(key)) continue;
    seen.add(key);
    unique.push(reference);
  }
  return unique;
}

function uniqueValidIds(ids: readonly number[]): readonly number[] {
  const seen = new Set<number>();
  const unique: number[] = [];
  for (const id of ids) {
    if (!isValidSequence(id) || seen.has(id)) continue;
    seen.add(id);
    unique.push(id);
  }
  return unique;
}

function indexAvailableMemories(
  memoryItems: readonly MemoryItem[],
  scopeId: string,
): ReadonlyMap<string, MemoryItem> {
  const available = new Map<string, MemoryItem>();
  for (const item of memoryItems) {
    if (
      item.scopeId !== scopeId
      || item.archived
      || !isMemoryKind(item.kind)
      || !isValidSequence(item.seq)
      || !item.content.trim()
    ) continue;
    const key = memoryKey(memorySourceOf(item), item.seq);
    if (!available.has(key)) available.set(key, item);
  }
  return available;
}

function formatResolvedMemories(
  memories: readonly MemoryItem[],
): { readonly prompt: string; readonly items: readonly MemoryItem[] } {
  const sections: string[] = [];
  const included: MemoryItem[] = [];
  for (const item of memories) {
    const content = normalizeMemoryContent(item.content);
    if (!content) continue;
    const source = memorySourceOf(item);
    included.push(item);
    sections.push([
      memoryLabelOf(item),
      `类型：${MEMORY_TYPE_LABELS[source]}`,
      source === 'phone' ? '来源：手机内容' : `来源楼层：${item.floorFrom}-${item.floorTo}`,
      '正文：',
      content,
    ].join('\n'));
  }
  if (sections.length === 0) return { prompt: '', items: [] };
  const recallTargets = included.map(memoryLabelOf).join('、');
  return {
    items: included,
    prompt: [
      STORY_MEMORY_PROMPT_OPEN_TAG,
      '【强制回忆规则】在思考/分析本轮回复时，第一步必须逐条回忆下列内容：先明确写出对应的记忆/总结编号，再复述该编号“正文”中的关键事实，然后说明这些事实对当前剧情的约束。全部核对完成后，才能继续分析当前场景并生成回复。禁止跳过任何一条，禁止只写“已参考记忆”，禁止未读取正文就直接作答。',
      `本轮必须首先回忆：${recallTargets}`,
      '编号核对只用于内部思考/分析；最终给用户的回复不得暴露标签名或检索过程，也不要机械复述编号，但必须体现这些正文事实并保持剧情连续性。',
      ...sections,
      STORY_MEMORY_PROMPT_CLOSE_TAG,
    ].join('\n\n'),
  };
}

function memoryKey(source: MemorySource, seq: number): string {
  return `${source}:${seq}`;
}

function normalizeMemoryContent(content: string): string {
  return content
    .replace(/\0/g, '')
    .replace(/<\/?retrieved_story_memories\b[^>]*>/gi, '')
    .replace(/\r\n?/g, '\n')
    .trim();
}

function isMemoryKind(kind: unknown): kind is MemoryItem['kind'] {
  return kind === 'summary' || kind === 'consolidation';
}

function isValidSequence(value: unknown): value is number {
  return Number.isInteger(value) && Number(value) >= 0 && Number(value) <= 2_000_000_000;
}