import type { Profile } from '../domain/model.js';

const AVATAR_REQUIRED_FIELDS = [
  'subject',
  'age',
  'hairColor',
  'hairStyle',
  'eyeColor',
  'skin',
  'face',
  'expression',
  'build',
  'clothing',
] as const;

export type AvatarPromptField = typeof AVATAR_REQUIRED_FIELDS[number];

export interface AvatarPromptDraft {
  readonly displayName?: string;
  readonly boundCharacter?: string;
  readonly twitterName?: string;
  readonly bio?: string;
  readonly twitterBio?: string;
  readonly personality?: string;
  readonly appearancePrompt?: string;
}

export interface AvatarPromptContext {
  readonly profile: Profile;
  readonly draft?: AvatarPromptDraft;
  readonly worldBookExcerpt?: string | null;
  readonly recentStory?: readonly string[];
}

export interface AvatarPromptRequest {
  readonly profileId: string;
  readonly draft?: AvatarPromptDraft;
}

export interface AvatarPromptResult {
  /** 完整头像生图提示词。 */
  readonly prompt: string;
  /** 可复用于其他场景的固定外貌提示词。 */
  readonly appearancePrompt: string;
}

interface AvatarPromptPayload extends Record<AvatarPromptField, string> {
  readonly extraTags?: readonly string[];
}

const cleanTag = (value: string): string => value
  .replace(/[\r\n;；]+/g, ', ')
  .replace(/^[,，\s]+|[,，\s]+$/g, '')
  .trim();

const splitTags = (value: string): readonly string[] => value
  .split(/[,，]/)
  .map(cleanTag)
  .filter(Boolean);

const withNoun = (value: string, noun: 'hair' | 'eyes' | 'skin' | 'face'): string => {
  const cleaned = cleanTag(value);
  return new RegExp(`\\b${noun}\\b`, 'i').test(cleaned) ? cleaned : `${cleaned} ${noun}`;
};

const uniqueTags = (tags: readonly string[]): readonly string[] => {
  const seen = new Set<string>();
  return tags.filter((tag) => {
    const key = tag.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
};

export function buildAvatarPromptMessages(context: AvatarPromptContext): { readonly system: string; readonly user: string } {
  const profile = context.profile;
  const draft = context.draft ?? {};
  const displayName = draft.displayName?.trim() || draft.twitterName?.trim() || profile.twitterName || profile.displayName;
  const boundCharacter = draft.boundCharacter?.trim() || profile.boundCharacter || displayName;
  const appearancePrompt = draft.appearancePrompt?.trim() || profile.appearancePrompt || '';
  const bio = draft.twitterBio?.trim() || draft.bio?.trim() || profile.twitterBio || profile.bio || '';
  const personality = draft.personality?.trim() || profile.personality || '';

  return {
    system: [
      '你是角色立绘提示词设计器。根据角色资料生成一份单人头像生图提示词。',
      '只能输出一个 JSON 对象，不要 Markdown、解释或代码围栏。',
      '所有字段值必须是简短、明确的英文逗号标签，不得使用中文，不得省略字段。',
      'worldBookExcerpt 与已有素体提示词是外貌事实的最高优先级来源；不要用常见头像风格覆盖角色的时代、服装、物种、年龄表达或外貌设定。',
      '未知细节只能在生成结构所必需时做保守且协调的推断，不要输出 unknown、unspecified、N/A，也不要扩写与头像无关的背景。',
      'subject 必须使用 1girl、1boy、1woman、1man 或 1person 之一。',
      '输出结构：{"subject":"...","age":"...","hairColor":"...","hairStyle":"...","eyeColor":"...","skin":"...","face":"...","expression":"...","build":"...","clothing":"...","extraTags":["..."]}',
      'extraTags 只放角色辨识度细节；不要放构图、背景、画质、艺术家名或露骨内容。',
    ].join('\n'),
    user: JSON.stringify({
      task: '为此角色生成头像提示词标签。优先服从已有素体提示词与明确设定，禁止擅自改变已知外貌。',
      character: {
        displayName,
        boundCharacter,
        bio,
        personality,
        existingAppearancePrompt: appearancePrompt,
      },
      worldBookExcerpt: context.worldBookExcerpt ?? '',
      recentStory: (context.recentStory ?? []).slice(-8),
    }),
  };
}

function extractJsonObject(raw: string): string {
  const unfenced = raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
  const start = unfenced.indexOf('{');
  const end = unfenced.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('模型没有返回头像提示词 JSON。');
  return unfenced.slice(start, end + 1);
}

function parsePayload(raw: string): AvatarPromptPayload {
  let value: unknown;
  try {
    value = JSON.parse(extractJsonObject(raw));
  } catch (error) {
    if (error instanceof Error && error.message.includes('头像提示词 JSON')) throw error;
    throw new Error('头像提示词不是有效 JSON。');
  }
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('头像提示词 JSON 必须是对象。');
  const record = value as Record<string, unknown>;
  const missing = AVATAR_REQUIRED_FIELDS.filter((field) => typeof record[field] !== 'string' || !cleanTag(record[field] as string));
  if (missing.length > 0) throw new Error(`头像提示词标签不完整：缺少 ${missing.join(', ')}。`);
  return {
    subject: cleanTag(record.subject as string),
    age: cleanTag(record.age as string),
    hairColor: withNoun(record.hairColor as string, 'hair'),
    hairStyle: withNoun(record.hairStyle as string, 'hair'),
    eyeColor: withNoun(record.eyeColor as string, 'eyes'),
    skin: withNoun(record.skin as string, 'skin'),
    face: withNoun(record.face as string, 'face'),
    expression: cleanTag(record.expression as string),
    build: cleanTag(record.build as string),
    clothing: cleanTag(record.clothing as string),
    extraTags: Array.isArray(record.extraTags)
      ? record.extraTags.filter((item): item is string => typeof item === 'string').flatMap(splitTags)
      : [],
  };
}

export function parseAvatarPromptResponse(raw: string): AvatarPromptResult {
  const payload = parsePayload(raw);
  const appearancePrompt = uniqueTags([
    ...splitTags(payload.subject),
    ...splitTags(payload.age),
    ...splitTags(payload.hairColor),
    ...splitTags(payload.hairStyle),
    ...splitTags(payload.eyeColor),
    ...splitTags(payload.skin),
    ...splitTags(payload.face),
    ...splitTags(payload.build),
    ...(payload.extraTags ?? []),
  ]).join(', ');
  const prompt = uniqueTags([
    ...splitTags(appearancePrompt),
    ...splitTags(payload.expression),
    ...splitTags(payload.clothing),
    'solo',
    'headshot portrait',
    'looking at viewer',
    'centered composition',
    'simple background',
    'soft lighting',
  ]).join(', ');
  if (!isAvatarPromptComplete(prompt)) throw new Error('头像提示词标签不完整，请重新生成。');
  return { prompt, appearancePrompt };
}

/** 检测已保存的头像提示词是否具备生成所需的角色与构图标签。 */
export function isAvatarPromptComplete(prompt: string | undefined): boolean {
  if (!prompt) return false;
  const normalized = prompt.toLowerCase();
  const tags = splitTags(normalized);
  if (tags.length < 12) return false;
  return [
    /\b1(?:girl|boy|woman|man|person)\b/,
    /\bhair\b/,
    /\beyes?\b/,
    /\b(?:portrait|headshot|upper body|bust)\b/,
    /\bbackground\b/,
    /\b(?:light|lighting)\b/,
  ].every((pattern) => pattern.test(normalized));
}