export interface DraggableOptions {
  /** 响应拖拽起始的元素（如窗口标题栏或按钮本身）。 */
  readonly handle: HTMLElement;
  /** 实际被移动的元素。 */
  readonly target: HTMLElement;
  /** localStorage 键，用于记忆位置。 */
  readonly storageKey: string;
  /** 命中该选择器的子元素不触发拖拽（例如标题栏上的按钮）。 */
  readonly ignoreSelector?: string;
  /** 返回 false 时暂时禁用拖拽（例如移动端全屏布局）。 */
  readonly enabled?: () => boolean;
  /** 拖拽结束后是否拦截随后的 click（用于本身可点击的悬浮按钮）。 */
  readonly suppressClickAfterDrag?: boolean;
}

interface StoredPosition {
  readonly left: number;
  readonly top: number;
}

const DRAG_THRESHOLD_PX = 5;
const MIN_VISIBLE_PX = 44;

/** 让元素可拖拽并记忆位置；返回清理函数。 */
export function makeDraggable(options: DraggableOptions): () => void {
  const { handle, target } = options;
  let pointerId: number | null = null;
  let dragging = false;
  let startX = 0;
  let startY = 0;
  let startRect: DOMRect | null = null;

  const previousTouchAction = handle.style.touchAction;
  const previousUserSelect = handle.style.userSelect;
  const previousWebkitUserSelect = handle.style.webkitUserSelect;

  const onPointerDown = (event: PointerEvent) => {
    if (event.button !== 0 && event.pointerType === 'mouse') return;
    if (options.enabled && !options.enabled()) return;
    if (options.ignoreSelector && event.target instanceof Element && event.target.closest(options.ignoreSelector)) return;
    pointerId = event.pointerId;
    dragging = false;
    startX = event.clientX;
    startY = event.clientY;
    startRect = target.getBoundingClientRect();
    try {
      handle.setPointerCapture(event.pointerId);
    } catch {
      // 某些环境不支持指针捕获时仍可依赖 move 事件。
    }
  };

  const onPointerMove = (event: PointerEvent) => {
    if (pointerId === null || event.pointerId !== pointerId || !startRect) return;
    const deltaX = event.clientX - startX;
    const deltaY = event.clientY - startY;
    if (!dragging && Math.hypot(deltaX, deltaY) < DRAG_THRESHOLD_PX) return;
    if (!dragging) {
      dragging = true;
      document.getSelection()?.removeAllRanges();
    }
    event.preventDefault();
    applyPosition(target, {
      left: startRect.left + deltaX,
      top: startRect.top + deltaY,
    });
  };

  const finishDrag = (event: PointerEvent) => {
    if (pointerId === null || event.pointerId !== pointerId) return;
    pointerId = null;
    try {
      handle.releasePointerCapture(event.pointerId);
    } catch {
      // 忽略重复释放。
    }
    if (!dragging) return;
    dragging = false;
    const rect = target.getBoundingClientRect();
    savePosition(options.storageKey, { left: rect.left, top: rect.top });
    if (options.suppressClickAfterDrag) {
      const suppress = (clickEvent: Event) => {
        clickEvent.stopPropagation();
        clickEvent.preventDefault();
      };
      handle.addEventListener('click', suppress, { capture: true, once: true });
      window.setTimeout(() => handle.removeEventListener('click', suppress, { capture: true }), 0);
    }
  };

  handle.addEventListener('pointerdown', onPointerDown);
  handle.addEventListener('pointermove', onPointerMove);
  handle.addEventListener('pointerup', finishDrag);
  handle.addEventListener('pointercancel', finishDrag);
  handle.style.touchAction = 'none';
  handle.style.userSelect = 'none';
  handle.style.webkitUserSelect = 'none';

  return () => {
    handle.removeEventListener('pointerdown', onPointerDown);
    handle.removeEventListener('pointermove', onPointerMove);
    handle.removeEventListener('pointerup', finishDrag);
    handle.removeEventListener('pointercancel', finishDrag);
    handle.style.touchAction = previousTouchAction;
    handle.style.userSelect = previousUserSelect;
    handle.style.webkitUserSelect = previousWebkitUserSelect;
  };
}

/** 恢复记忆的位置（若存在且当前允许自定义定位）。 */
export function restoreDraggedPosition(
  target: HTMLElement,
  storageKey: string,
  enabled?: () => boolean,
): void {
  if (enabled && !enabled()) {
    clearInlinePosition(target);
    return;
  }
  const stored = loadPosition(storageKey);
  if (!stored) return;
  applyPosition(target, stored);
}

export function clearInlinePosition(target: HTMLElement): void {
  target.style.left = '';
  target.style.top = '';
  target.style.right = '';
  target.style.bottom = '';
}

/**
 * 确保元素在可视区域内：完全或部分跑出视口时，
 * 恢复存储位置（重新钳制）或回退到给定的默认位置。
 * 用于移动端转屏、视口尺寸变化、以及宿主页面劫持 fixed 包含块的场景。
 */
export function ensureVisiblePosition(
  target: HTMLElement,
  storageKey: string,
  fallback: () => StoredPosition,
): void {
  const rect = target.getBoundingClientRect();
  const inView = rect.width > 0
    && rect.top >= 0
    && rect.left >= 0
    && rect.bottom <= window.innerHeight
    && rect.right <= window.innerWidth;
  if (inView) return;
  const stored = loadPosition(storageKey);
  applyPosition(target, stored ?? fallback());
}

function applyPosition(target: HTMLElement, position: StoredPosition): void {
  const width = target.offsetWidth || 48;
  const height = target.offsetHeight || 48;
  const maxLeft = Math.max(0, window.innerWidth - Math.min(width, MIN_VISIBLE_PX * 2));
  const maxTop = Math.max(0, window.innerHeight - Math.min(height, MIN_VISIBLE_PX));
  const left = Math.min(Math.max(position.left, MIN_VISIBLE_PX - width), maxLeft);
  const top = Math.min(Math.max(position.top, 0), maxTop);
  target.style.left = `${Math.round(left)}px`;
  target.style.top = `${Math.round(top)}px`;
  target.style.right = 'auto';
  target.style.bottom = 'auto';
}

function savePosition(storageKey: string, position: StoredPosition): void {
  try {
    localStorage.setItem(storageKey, JSON.stringify({ left: Math.round(position.left), top: Math.round(position.top) }));
  } catch {
    // localStorage 不可用时仅本次会话生效。
  }
}

function loadPosition(storageKey: string): StoredPosition | null {
  try {
    const raw = localStorage.getItem(storageKey);
    if (!raw) return null;
    const parsed = JSON.parse(raw) as { left?: unknown; top?: unknown };
    const left = Number(parsed.left);
    const top = Number(parsed.top);
    return Number.isFinite(left) && Number.isFinite(top) ? { left, top } : null;
  } catch {
    return null;
  }
}
