/**
 * 内置默认表格预设。
 *
 * 数据中心开箱可用的一份基础结构：角色位置、剧情时间、时间跨度、角色任务与角色穿着。
 * 这份预设不写进设置（不占用户的预设库配额），只在选择列表里与导入的预设并列出现；
 * 被选中时和导入的预设走完全相同的物化路径。
 */

import { buildRowTemplate, selectPresetBundle, type SheetPresetBundle, type SheetPresetEntry } from './sheet-preset.js';
import type { SheetPolicy } from './sheet-dsl.js';

export const BUILTIN_SHEET_PRESET_ID = 'builtin-default';

interface BuiltinSheetSpec {
  readonly name: string;
  readonly purpose: string;
  readonly policy: SheetPolicy;
  /** [列名, 中文标签]；列名保持 ASCII，语义由标签承担。 */
  readonly columns: readonly (readonly [string, string])[];
}

const BUILTIN_SHEETS: readonly BuiltinSheetSpec[] = Object.freeze([
  {
    name: '角色位置',
    purpose: '每个角色当前在哪：地点、所处区域、同行者，以及这条位置对应的剧情时刻。',
    policy: 'always',
    columns: [
      ['name', '角色'],
      ['place', '当前地点'],
      ['area', '所处区域'],
      ['company', '同行者'],
      ['at_time', '记录时刻'],
      ['note', '备注'],
    ],
  },
  {
    name: '剧情时间',
    purpose: '当前剧情走到哪个时间点：日期、时刻、时段、星期与天气季节，供后续推算时间线。',
    policy: 'always',
    columns: [
      ['date', '剧情日期'],
      ['clock', '具体时刻'],
      ['phase', '时段'],
      ['weekday', '星期'],
      ['weather', '天气'],
      ['season', '季节'],
      ['note', '备注'],
    ],
  },
  {
    name: '时间跨度',
    purpose: '事件从什么时候持续到什么时候：开始、结束与持续时长，用于回答“过了多久”。',
    policy: 'recall',
    columns: [
      ['event', '事件'],
      ['start_time', '开始时间'],
      ['end_time', '结束时间'],
      ['duration', '持续时长'],
      ['note', '说明'],
    ],
  },
  {
    name: '角色任务',
    purpose: '每个角色手上的目标与进度：任务内容、当前状态、完成度与期限。',
    policy: 'always',
    columns: [
      ['name', '角色'],
      ['task', '任务目标'],
      ['status', '状态'],
      ['progress', '进度'],
      ['deadline', '期限'],
      ['note', '备注'],
    ],
  },
  {
    name: '角色穿着',
    purpose: '每个角色当前的穿着：场合、上下装、鞋履与配饰，保证换装与描写前后一致。',
    policy: 'always',
    columns: [
      ['name', '角色'],
      ['occasion', '场合'],
      ['top', '上身'],
      ['bottom', '下身'],
      ['shoes', '鞋履'],
      ['accessory', '配饰'],
      ['underwear', '贴身衣物'],
      ['note', '备注'],
    ],
  },
]);

function toPresetEntry(spec: BuiltinSheetSpec, orderNo: number): SheetPresetEntry {
  const columns = spec.columns.map(([column]) => column);
  const labels = spec.columns.map(([, label]) => label);
  return {
    name: spec.name,
    purpose: spec.purpose,
    columns,
    labels,
    policy: spec.policy,
    rowTemplate: buildRowTemplate(columns, labels),
    tokenBudget: spec.policy === 'always' ? 512 : 256,
    orderNo,
    injectCondition: '',
    fillGuide: '',
    rows: [],
  };
}

export const BUILTIN_SHEET_PRESET: SheetPresetBundle = Object.freeze({
  id: BUILTIN_SHEET_PRESET_ID,
  name: '内置默认表格',
  sheets: Object.freeze(BUILTIN_SHEETS.map(toPresetEntry)) as readonly SheetPresetEntry[],
});

/** 可供选择的全部预设：内置默认表格永远排在最前，后面是用户导入的预设包。 */
export function availablePresetBundles(
  library: readonly SheetPresetBundle[],
): readonly SheetPresetBundle[] {
  return [BUILTIN_SHEET_PRESET, { id: 'builtin-preserved-tables', name: '历史保留表', sheets: [] },
    ...library.filter((bundle) => bundle.id !== BUILTIN_SHEET_PRESET_ID && bundle.id !== 'builtin-preserved-tables')];
}

/** 当前生效的预设包；未选择任何预设时返回 null。 */
export function resolveActivePresetBundle(
  library: readonly SheetPresetBundle[],
  activeId: string,
): SheetPresetBundle | null {
  if (!activeId) return null;
  return selectPresetBundle(availablePresetBundles(library), activeId);
}

/** 当前生效的表结构；未选择任何预设时返回空数组（此时不会自动建表）。 */
export function resolveActivePresetSheets(
  library: readonly SheetPresetBundle[],
  activeId: string,
): readonly SheetPresetEntry[] {
  if (!activeId) return [];
  return selectPresetBundle(availablePresetBundles(library), activeId)?.sheets ?? [];
}
