import type { PhoneViewContext } from '../app-types.js';
import { button, element, pickTextFile } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import { fanficActionButton, fanficStatRow } from './shared.js';

/** 原著来源：角色卡与世界书状态、导入资料管理、解析进度。 */
export function renderFanficSources(context: PhoneViewContext): HTMLElement {
  const fanfic = context.fanfic;
  const view = element('div', { className: 'phone-fanfic-section' });
  const analyzedRatio = fanfic.stats.chunks > 0
    ? `${fanfic.stats.analyzed}/${fanfic.stats.chunks} 段`
    : '暂无可解析内容';

  view.append(
    element('p', {
      className: 'phone-settings-hint',
      text: '原著来源包含当前角色卡、已启用的世界书条目，以及你导入的原著资料。解析结果保存在本聊天，不与其他聊天混用。',
    }),
    fanficStatRow('角色卡', fanfic.card.available ? `${fanfic.card.name || '未命名'} · ${fanfic.card.fieldCount} 个字段 · ${fanfic.card.charCount} 字` : '未读取到角色卡', fanfic.card.available),
    fanficStatRow('导入资料', fanfic.imports.length > 0 ? `${fanfic.imports.length} 份` : '未导入', fanfic.imports.length > 0),
    fanficStatRow('解析进度', analyzedRatio, fanfic.stats.analyzed > 0),
    fanficStatRow('人物锁', `${fanfic.stats.characters} 个`, fanfic.stats.characters > 0),
    fanficStatRow('原著事实', `${fanfic.stats.facts} 条`, fanfic.stats.facts > 0),
    fanficStatRow('世界规则', `${fanfic.stats.worldRules} 条`, fanfic.stats.worldRules > 0),
  );

  if (fanfic.imports.length > 0) {
    const list = element('div', { className: 'phone-fanfic-list' });
    for (const document of fanfic.imports) {
      const row = element('div', { className: 'phone-fanfic-row' });
      const info = element('span', { className: 'phone-fanfic-row-main' });
      info.append(
        element('strong', { text: document.name }),
        element('small', { text: `${document.charCount} 字` }),
      );
      const remove = button('', 'phone-icon-button phone-fanfic-row-action', async () => {
        const approved = await context.showConfirm({
          title: `移除《${document.name}》？`,
          message: '移除后需要重新解析才会更新人物锁；已建立的人物锁不会自动删除。',
          confirmLabel: '移除',
        });
        if (!approved) return;
        const result = await fanfic.removeDocument(document.id);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) context.navigate('fanfic');
      });
      remove.append(renderPhoneIcon('trash', 'phone-svg-icon'));
      remove.setAttribute('aria-label', `移除${document.name}`);
      row.append(info, remove);
      list.append(row);
    }
    view.append(list);
  }

  const actions = element('div', { className: 'phone-fanfic-actions' });
  const importButton = button('导入原著资料', 'phone-button phone-button-primary phone-button-compact', async () => {
    importButton.disabled = true;
    try {
      const picked = await pickTextFile('.txt,.md,.json,text/plain,text/markdown,application/json');
      if (!picked) return;
      const result = await fanfic.importText(picked.name, picked.text);
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) context.navigate('fanfic');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      importButton.disabled = false;
    }
  });
  importButton.title = '支持 txt / md / json 纯文本资料';
  actions.append(
    importButton,
    fanficActionButton(context, {
      label: fanfic.stats.analyzed > 0 ? '继续解析' : '解析原著',
      title: '按批次解析尚未处理的资料片段；长篇原著可以多次继续',
      className: 'phone-button phone-button-primary phone-button-compact',
      disabled: fanfic.busy,
      run: () => fanfic.analyze(false),
    }),
    fanficActionButton(context, {
      label: '重建人物锁',
      title: '丢弃自动解析结果重新开始（手工修正过的人物锁会保留）',
      disabled: fanfic.busy,
      run: () => fanfic.analyze(true),
    }),
  );
  view.append(actions);

  const danger = element('div', { className: 'phone-fanfic-actions' });
  danger.append(button('清除原著库与资料', 'phone-button phone-button-danger-ghost phone-button-compact', async () => {
    const approved = await context.showConfirm({
      title: '清除本聊天的原著库？',
      message: '会同时删除已建立的人物锁、原著事实与导入的资料文件，此操作不可恢复。剧情状态不会被清除。',
      confirmLabel: '清除',
    });
    if (!approved) return;
    const result = await fanfic.clearLibrary();
    context.showNotice(result.message, result.ok ? 'success' : 'error');
    if (result.ok) context.navigate('fanfic');
  }));
  view.append(danger);

  if (fanfic.stats.chunks === 0) {
    view.append(element('p', {
      className: 'phone-settings-hint',
      text: '当前没有可解析内容：请确认已加载角色卡或世界书，或导入一份原著资料。',
    }));
  }
  return view;
}