import type { SheetContent } from './memory-engine.js';
import { parseConditionalStatement, type ConditionalStatement } from './sheet-condition.js';

export interface RecordFloorInput {
  readonly floor: number;
  readonly name: string;
  readonly role: 'user' | 'ai';
  readonly text: string;
}

export interface SheetRecordPromptInput {
  readonly userName: string;
  readonly floors: readonly RecordFloorInput[];
  readonly sheets: readonly SheetContent[];
  readonly maxStatements: number;
  /** 现有行注入上限，避免整表塞进提示词。 */
  readonly rowLimit?: number;
  /** 跨表共享的填表规则（MVU 转换时那些没法归属到单张表的通用法则）。 */
  readonly sharedGuide?: string;
}

const DEFAULT_ROW_LIMIT = 40;
function indentGuide(guide: string): string {
  return guide.trim().split(/\r?\n/).map((line) => `    ${line.trim()}`).filter((line) => line.trim()).join('\n');
}

function describeSheet(content: SheetContent, rowLimit: number): string {
  const header = content.columns
    .map((column, index) => `${column}（${content.labels[index] ?? column}）`)
    .join('、');
  const rows = content.rows.slice(-rowLimit).map((row) => {
    const cells = content.columns
      .map((column, index) => `${column}=${row.values[index] ?? ''}`)
      .join('；');
    return `  rowid=${row.rowId}：${cells}`;
  });
  const guide = indentGuide(content.sheet.fillGuide);
  return [
    `表 ${content.sheet.name} → 物理表 ${content.sheet.physicalName}`,
    `  用途：${content.sheet.purpose}`,
    `  列：${header}`,
    `  条件路径：sheets.${content.sheet.name}（.count 行数、.first / .last 首尾行、.rows[n] 指定行，行下再接列名或中文标签）`,
    guide ? `  填表规则：\n${guide}` : '',
    rows.length > 0 ? `  现有行（最多 ${rowLimit} 行）：\n${rows.join('\n')}` : '  现有行：无',
  ].filter(Boolean).join('\n');
}

/**
 * 构造填表提示词：模型只被允许产出针对已列出物理表的 SQL。
 * 越权、DDL、多语句夹带一律由 `sql-guard` 在执行前拦下，这里只负责把约束说清楚。
 */
export function buildSheetRecordPrompt(input: SheetRecordPromptInput): {
  readonly system: string;
  readonly user: string;
} {
  const rowLimit = input.rowLimit ?? DEFAULT_ROW_LIMIT;
  const system = [
    '你是剧情数据记录器。读取新增正文楼层，把其中的事实写进给定的 SQLite 数据表。',
    '输出规则（必须严格遵守）：',
    `1. 只输出一个 \`\`\`sql 代码块，块内最多 ${input.maxStatements} 条语句，每条以分号结尾。`,
    '2. 只允许 INSERT / UPDATE / DELETE，且表名必须是下面列出的物理表名，不得使用其他表。',
    '3. UPDATE 与 DELETE 必须带 WHERE，优先用 rowid 定位已有行。',
    '4. 禁止 CREATE/ALTER/DROP/PRAGMA/ATTACH、禁止 SQL 注释、禁止事务语句。',
    '5. 字符串用单引号，内部单引号写成两个连续单引号。',
    '6. 表名直接写物理表名，不要加双引号、反引号或方括号。',
    '7. 值里不要出现半角分号 `;` 与连续两个减号 `--`，需要断句请用中文标点。',
    '8. 已经记录过的事实不要重复插入；状态变化用 UPDATE 覆盖旧行。',
    '9. 正文里没有明确发生的内容不要编造；确实无需记录时输出空代码块。',
    '条件写入（可选，需要按表里现有数据判断时才用）：',
    '- 写成 `IF <条件> THEN <SQL>`，一条语句只能有一个 IF，没有 ELSE；条件不成立时这条写入会被跳过。',
    '- 条件运算符：== != > >= < <= and or not ( )，还有 contains、in，以及 exists(路径)、empty(路径)、length(路径)。',
    '- 条件里读表用 `sheets.<表名>`：`.count` 是行数，`.first` / `.last` 是首尾行，`.rows[0]` 是指定行，行下面接列名或中文标签。',
    '- 也可以读 `variables.<变量名>` 与 `time.hour`、`time.weekday`。',
    '- 例：`IF sheets.剧情时间.count == 0 THEN INSERT INTO acu_u_story_time_x(phase) VALUES (\'傍晚\')`。',
    '- 例：`IF sheets.角色位置.first.当前地点 != \'卧室\' THEN UPDATE acu_u_role_place_x SET place = \'卧室\' WHERE rowid = 1`。',
    '- 条件写不出来就不要写 IF，直接给普通语句；写坏的 IF 会被整条丢弃。',
    '不要输出任何解释文字。',
  ].join('\n');
  const user = [
    `用户名：${input.userName}`,
    input.sharedGuide?.trim() ? `通用填表规则（适用于下面所有表）：\n${input.sharedGuide.trim()}` : '',
    '可写入的数据表：',
    input.sheets.map((sheet) => describeSheet(sheet, rowLimit)).join('\n\n'),
    '待记录的新增正文楼层：',
    input.floors.map((floor) => `第${floor.floor}楼（${floor.name}·${floor.role === 'ai' ? 'AI' : '用户'}）：\n${floor.text}`).join('\n\n'),
  ].filter(Boolean).join('\n\n');
  return { system, user };
}

/**
 * 从模型输出里提取待执行语句，支持 `IF <条件> THEN <SQL>`。
 * 只做切分、去噪与 IF 拆解，不做安全判断与条件求值——那分别是 `sql-guard` 与调用方的职责，
 * 重复实现会造成多套规则漂移。
 */
export function extractRecordStatements(raw: string, limit: number): readonly ConditionalStatement[] {
  const fenced = [...raw.matchAll(/```(?:sql)?\s*([\s\S]*?)```/gi)].map((match) => match[1] ?? '');
  return parseRecordStatementBody(fenced.length > 0 ? fenced.join('\n') : raw, limit);
}

/** 已提取的 SQL 块直接切分，避免再次把字符串中的 Markdown 当成围栏。 */
export function parseRecordStatementBody(raw: string, limit: number): readonly ConditionalStatement[] {
  const body = raw.replace(/\r\n?/g, '\n');
  const statements: string[] = [];
  let current = '';
  let quote: '\'' | '"' | null = null;
  for (let index = 0; index < body.length; index += 1) {
    const char = body[index] ?? '';
    if (quote) {
      current += char;
      if (char === quote) quote = body[index + 1] === quote ? (current += body[++index], quote) : null;
      continue;
    }
    if (char === '\'' || char === '"') {
      quote = char;
      current += char;
      continue;
    }
    if (char === ';') {
      statements.push(current);
      current = '';
      continue;
    }
    current += char;
  }
  statements.push(current);
  return statements
    .map(trimToStatement)
    .filter(Boolean)
    .map(parseConditionalStatement)
    .filter(isUsableRecordStatement)
    .slice(0, Math.max(1, Math.trunc(limit)));
}

/**
 * 写坏的 IF 也要留下来上报，但只在它确实想写数据时——
 * 模型的说明文字偶尔以 “If …” 开头，那种片段直接当噪声丢掉。
 */
function isUsableRecordStatement(statement: ConditionalStatement): boolean {
  if (statement.kind === 'invalid') return /\b(?:INSERT|UPDATE|DELETE)\b/i.test(statement.raw);
  return /^(?:INSERT|UPDATE|DELETE)\b/i.test(statement.sql);
}

/**
 * 去掉语句前面夹带的解说文字：模型常在同一段里先写说明再写 SQL，
 * 按分号切分后这些说明会留在语句头部，直接丢弃整段会静默漏掉这条写入。
 */
function trimToStatement(fragment: string): string {
  const lines = fragment.split('\n');
  const start = lines.findIndex((line) => /^\s*(?:INSERT|UPDATE|DELETE|IF)\b/i.test(line));
  return start < 0 ? '' : lines.slice(start).join('\n').trim();
}
