import type { DbStatement } from './protocol.js';
import { quoteIdentifier, type SheetDefinition } from './sheet-dsl.js';

/** 所有结构、元数据和初始行先组成计划，再交给同一个 SQLite 事务提交。 */
export function registerSheetStatements(sheet: SheetDefinition): readonly DbStatement[] {
  return [{ sql: sheet.ddl }, {
    sql: `INSERT INTO sheet(id, scope_id, name, purpose, physical_name, ddl, policy, row_template, token_budget,
      order_no, updated_at, inject_condition, fill_guide) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
      ON CONFLICT(id) DO UPDATE SET scope_id=excluded.scope_id, name=excluded.name, purpose=excluded.purpose,
      physical_name=excluded.physical_name, ddl=excluded.ddl, policy=excluded.policy, row_template=excluded.row_template,
      token_budget=excluded.token_budget, order_no=excluded.order_no, updated_at=excluded.updated_at,
      inject_condition=excluded.inject_condition, fill_guide=excluded.fill_guide`,
    params: [sheet.id, sheet.scopeId, sheet.name, sheet.purpose, sheet.physicalName, sheet.ddl, sheet.policy,
      sheet.rowTemplate, sheet.tokenBudget, sheet.orderNo, sheet.updatedAt, sheet.injectCondition, sheet.fillGuide],
  }];
}

export function dropSheetStatements(sheet: Pick<SheetDefinition, 'physicalName' | 'scopeId' | 'id'>): readonly DbStatement[] {
  return [
    { sql: `DROP TABLE IF EXISTS ${quoteIdentifier(sheet.physicalName)}` },
    { sql: 'DELETE FROM mem_doc WHERE scope_id = ? AND sheet_id = ?', params: [sheet.scopeId, sheet.id] },
    { sql: 'DELETE FROM sheet WHERE id = ?', params: [sheet.id] },
  ];
}

export function insertSheetRowsStatements(
  sheet: Pick<SheetDefinition, 'physicalName'>,
  columns: readonly string[],
  rows: readonly (readonly string[])[],
  rowIds?: readonly number[],
): readonly DbStatement[] {
  if (!columns.length) return [];
  return rows.map((row, index) => {
    const rowId = rowIds?.[index];
    const keepId = Number.isSafeInteger(rowId) && Number(rowId) > 0;
    const names = [...(keepId ? ['rowid'] : []), ...columns];
    return {
      sql: `INSERT INTO ${quoteIdentifier(sheet.physicalName)}(${names.map(quoteIdentifier).join(', ')}) VALUES (${names.map(() => '?').join(', ')})`,
      params: [...(keepId ? [Number(rowId)] : []), ...columns.map((_, i) => row[i] ?? '')],
    };
  });
}

export function writeSheetMetaStatement(key: string, value: unknown): DbStatement {
  return { sql: 'INSERT INTO sys_meta(key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value=excluded.value', params: [key, JSON.stringify(value)] };
}
