import type { GenerationConditionContext } from '../conditions/generation.js';
import { isActionAllowed, isAppAllowed } from '../conditions/generation.js';
import type { AppId, PhoneState, PostKind, Profile } from '../domain/model.js';
import { findFanficViolation } from '../fanfic/consistency.js';
import type { CharacterLock, FanficSecret } from '../fanfic/model.js';
import { findIdentityConflict } from './identity.js';
import { findRoboticVoice, findRoleBreakout, findUnsupportedRupture } from './reply-guard.js';
import {
  GENERATION_ACTION_TYPES,
  GENERATION_LONG_CONTENT_ACTION_TYPES,
  GENERATION_MAX_ACTOR_NAME_LENGTH,
  GENERATION_MAX_COMMON_CONTENT_LENGTH,
  GENERATION_MAX_DELAY_MINUTES,
  GENERATION_MAX_LONG_CONTENT_LENGTH,
  GENERATION_MAX_THOUGHT_LENGTH,
  GENERATION_MAX_VARIABLE_PATH_LENGTH,
  GENERATION_MAX_ACTIONS,
  GENERATION_MAX_VARIABLE_UPDATES,
  GENERATION_PROTOCOL_VERSION,
  type GenerationActionType,
  type ValidationIssue,
  type ValidationResult,
  type ValidatedGenerationAction,
  type ValidatedVariableUpdate,
} from './schema.js';

const ACTION_TYPES = new Set<GenerationActionType>(GENERATION_ACTION_TYPES);

/** 允许虚构路人网友（actorName）执行的动作：仅推特公开动态的轻量互动。 */
const AMBIENT_ACTION_TYPES = new Set<GenerationActionType>([
  'forum.ambient.create',
  'twitter.ambient.create',
  'forum.reply.create',
  'twitter.reply.create',
  'twitter.repost.create',
  'interaction.like',
  'interaction.comment',
]);

interface ValidationContext {
  readonly batchId: string;
  readonly state: PhoneState;
  readonly selfProfileId: string;
  readonly allowedConversationIds: ReadonlySet<string>;
  readonly maxActions?: number;
  /**
   * 允许自主发布动态/互动的应用集合（由用户的应用开关与世界自转开关决定）。
   * 会话回复与针对用户内容的回应不受此限制；未提供时不做门控。
   */
  readonly allowedAutonomousApps?: ReadonlySet<AppId>;
  /** 完全停用的应用：该应用的会话回复、动态和互动一律拒绝。 */
  readonly disabledAppIds?: ReadonlySet<string>;
  readonly actionIndexOffset?: number;
  /** 纯条件快照；未提供时不启用条件规则，避免破坏旧调用方。 */
  readonly conditionContext?: GenerationConditionContext;
  /** 同人一致性检查：解析说话人的人物锁与当前秘密；未提供时跳过检查。 */
  readonly fanficGuard?: {
    readonly resolveCharacter: (name: string) => CharacterLock | null;
    readonly secrets: readonly FanficSecret[];
  };
}

export function validateGenerationResponse(raw: string, context: ValidationContext): ValidationResult {
  const issues: ValidationIssue[] = [];
  const strict = parseResponse(raw);
  // 输出被截断（例如 max_tokens 不够）时，尽力从残缺文本里捞回已经写完的动作，避免整轮白跑。
  const salvaged = strict && typeof strict === 'object' && !Array.isArray(strict)
    ? null
    : salvageResponse(raw, context.batchId);
  if (salvaged) {
    issues.push({ index: -1, reason: `模型输出不是完整 JSON，已恢复 ${salvaged.actions.length} 个动作` });
  }
  const parsed = salvaged ?? strict;
  if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
    return { actions: [], issues: [{ index: -1, reason: '模型没有返回 JSON 对象' }], variableUpdates: [] };
  }

  const record = parsed as Record<string, unknown>;
  if (record.version !== GENERATION_PROTOCOL_VERSION) {
    issues.push({ index: -1, reason: '生成协议版本不匹配' });
  }
  if (record.batchId !== context.batchId) {
    issues.push({ index: -1, reason: 'batchId 不匹配' });
  }
  if (!Array.isArray(record.actions)) {
    return { actions: [], issues: [...issues, { index: -1, reason: 'actions 必须是数组' }], variableUpdates: [] };
  }

  const maxActions = Math.min(GENERATION_MAX_ACTIONS, Math.max(1, context.maxActions ?? GENERATION_MAX_ACTIONS));
  const actions: ValidatedGenerationAction[] = [];
  const actorCounts = new Map<string, number>();

  for (const [index, value] of record.actions.slice(0, maxActions).entries()) {
    const actionIndex = index + (context.actionIndexOffset ?? 0);
    const result = validateAction(value, actionIndex, context, actorCounts);
    if ('reason' in result) {
      issues.push({ index: actionIndex, reason: result.reason });
      continue;
    }
    actions.push(result.action);
  }

  if (record.actions.length > maxActions) {
    issues.push({ index: maxActions, reason: `动作超过上限 ${maxActions}，其余已忽略` });
  }

  return { actions, issues, variableUpdates: validateVariableUpdates(record.variableUpdates, issues) };
}

function validateVariableUpdates(
  value: unknown,
  issues: ValidationIssue[],
): readonly ValidatedVariableUpdate[] {
  if (value === undefined || value === null) return [];
  if (!Array.isArray(value)) {
    issues.push({ index: -1, reason: 'variableUpdates 必须是数组，已忽略' });
    return [];
  }
  const updates: ValidatedVariableUpdate[] = [];
  for (const [index, item] of value.slice(0, GENERATION_MAX_VARIABLE_UPDATES).entries()) {
    const record = item && typeof item === 'object' && !Array.isArray(item)
      ? item as Record<string, unknown>
      : null;
    const path = String(record?.path ?? '').trim();
    const updateValue = record?.value;
    const validValue = updateValue === null
      || typeof updateValue === 'string'
      || typeof updateValue === 'number'
      || typeof updateValue === 'boolean';
    if (!record || !path || path.length > GENERATION_MAX_VARIABLE_PATH_LENGTH || !validValue) {
      issues.push({ index, reason: `variableUpdates[${index}] 无效，已忽略` });
      continue;
    }
    updates.push({ path, value: updateValue as string | number | boolean | null });
  }
  if (value.length > GENERATION_MAX_VARIABLE_UPDATES) {
    issues.push({
      index: GENERATION_MAX_VARIABLE_UPDATES,
      reason: `变量更新超过 ${GENERATION_MAX_VARIABLE_UPDATES} 条，其余已忽略`,
    });
  }
  return updates;
}

function validateAction(
  value: unknown,
  index: number,
  context: ValidationContext,
  actorCounts: Map<string, number>,
): { action: ValidatedGenerationAction } | { reason: string } {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return { reason: '动作必须是对象' };
  const source = value as Record<string, unknown>;
  const type = source.type;
  if (typeof type !== 'string' || !ACTION_TYPES.has(type as GenerationActionType)) {
    return { reason: '动作类型不在白名单中' };
  }
  if (context.conditionContext && !isActionAllowed(type, context.conditionContext)) {
    return { reason: '动作未通过条件门控' };
  }
  const actorProfileId = cleanIdentifier(source.actorProfileId);
  const actorName = cleanDisplayName(source.actorName);
  const isAmbientActor = !actorProfileId && Boolean(actorName);
  let actorProfile: Profile | undefined;

  if (isAmbientActor) {
    // 推特/论坛路人网友只允许在公开平台活动，且不能参与私聊。
    if (!AMBIENT_ACTION_TYPES.has(type as GenerationActionType)) {
      return { reason: '路人网友（actorName）只能创建论坛/推特独立动态，或回复/转发/点赞/评论公开内容' };
    }
  } else {
    if (type === 'forum.ambient.create' || type === 'twitter.ambient.create') {
      return { reason: '独立路人动态必须使用 actorName，不得绑定真实角色档案' };
    }
    const actor = actorProfileId ? context.state.profiles[actorProfileId] : undefined;
    if (!actor || actor.scopeId !== context.state.scopeId) return { reason: '动作角色不存在或不属于当前聊天' };
    if (actorProfileId === context.selfProfileId) {
      return { reason: '模型不能使用用户身份创建手机动作' };
    }
    actorProfile = actor;
  }
  // 私聊与公开发布各自计额：话多的角色连发几条消息后，不该把自己的动态挤出本轮。
  const actorScope = type === 'message.reply' || type === 'message.claim' ? 'chat' : 'public';
  const actorKey = `${actorScope}|${isAmbientActor ? `ambient:${actorName}` : actorProfileId}`;
  const actorCount = (actorCounts.get(actorKey) ?? 0) + 1;
  if (actorCount > 6) return { reason: '单个角色动作数量超限' };
  actorCounts.set(actorKey, actorCount);

  const contentLimit = GENERATION_LONG_CONTENT_ACTION_TYPES.includes(
    type as typeof GENERATION_LONG_CONTENT_ACTION_TYPES[number],
  )
    ? GENERATION_MAX_LONG_CONTENT_LENGTH
    : GENERATION_MAX_COMMON_CONTENT_LENGTH;
  const targetId = cleanIdentifier(source.targetId);
  const conversationId = cleanIdentifier(source.conversationId);
  const parentId = cleanIdentifier(source.parentId);

  if (type === 'message.claim') {
    if (!targetId) return { reason: '领取目标消息缺失' };
    const message = context.state.messages[targetId];
    if (!message) return { reason: '目标消息不存在' };
    const claimable = message.kind === 'red_packet' || message.kind === 'gift' || message.kind === 'transfer';
    if (!claimable) return { reason: '该消息不可领取' };
    const conversation = context.state.conversations[message.conversationId];
    if (!conversation || context.disabledAppIds?.has(conversation.appId)) {
      return { reason: '目标应用已停用' };
    }
    if (context.conditionContext && !isAppAllowed(conversation.appId, context.conditionContext)) {
      return { reason: '领取目标应用未通过条件门控' };
    }
    if (!conversation.participantIds.includes(actorProfileId)) {
      return { reason: '领取角色不是该会话成员' };
    }
    const claimStatus = source.claimStatus === 'declined'
      ? 'declined'
      : source.claimStatus === 'claimed'
        ? 'claimed'
        : null;
    if (!claimStatus) return { reason: 'claimStatus 必须是 claimed 或 declined' };
    const content = typeof source.content === 'string' ? cleanContent(source.content, contentLimit) : '';
    const actionId = buildActionId(
      context.batchId,
      index,
      type,
      actorProfileId,
      `${targetId}|${claimStatus}|${content}`,
    );
    return {
      action: {
        actionId,
        type: 'message.claim',
        appId: message.appId,
        actorProfileId,
        content: content || (claimStatus === 'claimed' ? '已领取' : '已婉拒'),
        targetId,
        conversationId: message.conversationId,
        claimStatus,
      },
    };
  }

  const content = cleanContent(source.content, contentLimit);
  if (!content) return { reason: '动作内容为空或过长' };

  const delayMinutes = normalizeDelay(source.delayMinutes);
  if (source.delayMinutes !== undefined && delayMinutes === null) return { reason: 'delayMinutes 超出允许范围' };

  const thought = typeof source.thought === 'string'
    ? source.thought.replace(/\u0000/g, '').trim().slice(0, GENERATION_MAX_THOUGHT_LENGTH)
    : '';

  // 身份错乱兜底：actorProfileId 正确但内容自称/署名成了别人时，这条回复不可信。
  if (actorProfile) {
    const conflict = findIdentityConflict({
      actor: actorProfile,
      profiles: context.state.profiles,
      content,
      thought,
    });
    if (conflict) {
      return {
        reason: `身份错乱：${conflict.source === 'thought' ? 'thought' : '内容'}自称「${conflict.claimedName}」，`
          + `实际是「${conflict.expectedName}」`,
      };
    }
  }

  // 出戏兜底：模型把自己的合规顾虑写成了角色台词。
  const breakout = findRoleBreakout({ content, thought });
  if (breakout) return { reason: `内容出戏：${breakout.reason}` };

  const title = type === 'forum.thread.create' || type === 'forum.ambient.create'
    ? cleanForumTitle(source.title) || deriveForumTitle(content)
    : '';
  const actionId = buildActionId(context.batchId, index, type, isAmbientActor ? `name:${actorName}` : actorProfileId, `${title}|${content}`);
  const base = {
    actionId,
    type: type as GenerationActionType,
    actorProfileId,
    ...(isAmbientActor ? { actorName } : {}),
    ...(thought ? { thought } : {}),
    content,
    ...(delayMinutes === null ? {} : { delayMinutes }),
  };

  if (type === 'message.reply') {
    if (!conversationId || !context.allowedConversationIds.has(conversationId)) {
      return { reason: '回复目标不属于本批次' };
    }
    const conversation = context.state.conversations[conversationId];
    if (!conversation || context.disabledAppIds?.has(conversation.appId)) {
      return { reason: '回复目标应用已停用' };
    }
    if (context.conditionContext && !isAppAllowed(conversation.appId, context.conditionContext)) {
      return { reason: '回复目标应用未通过条件门控' };
    }
    if (!conversation.participantIds.includes(actorProfileId)) {
      return { reason: '回复角色不是该会话成员' };
    }
    if (matchesPendingUserContent(context, content, { conversationId })) {
      return { reason: '回复内容重复了待处理的用户消息' };
    }
    // 无故断联兜底：上下文一片正常却突然拉黑/绝交，通常是被模型的安全倾向带偏了。
    const robotic = findRoboticVoice({ content });
    if (robotic) return { reason: `机器人腔：${robotic.reason}` };
    const rupture = findUnsupportedRupture({
      content,
      historyTexts: conversationHistoryTexts(context.state, conversationId),
    });
    if (rupture) return { reason: `关系突变：${rupture.reason}` };
    // 同人模式：拦下写崩人物语感与泄露角色不知情信息的回复。
    const fanficViolation = findFanficMessageViolation(context, actorProfile, actorName, content);
    if (fanficViolation) return { reason: `同人一致性：${fanficViolation}` };
    return { action: { ...base, appId: conversation.appId, conversationId } };
  }

  const postMapping = mapPostType(type as GenerationActionType);
  if (postMapping) {
    if (context.disabledAppIds?.has(postMapping.appId)) return { reason: '目标应用已停用' };
    if (context.conditionContext && !isAppAllowed(postMapping.appId, context.conditionContext)) {
      return { reason: '目标应用未通过条件门控' };
    }
    /*
     * 独立动态（动态/朋友圈/主题）本来就不需要引用目标。模型顺手带上一个不存在的
     * targetId/parentId 时只剔除该字段，不能连整条动态一起丢掉——否则角色在聊天里
     * 说「我发了条动态」，动态却从未出现在时间线上。回复与转发仍要求目标真实存在。
     */
    const knownPostId = (id: string): string => (id && context.state.posts[id] ? id : '');
    const parentPostId = knownPostId(parentId);
    const targetPostId = knownPostId(targetId);
    const referencedId = parentPostId || targetPostId;
    if (postMapping.requiresParent && !referencedId) {
      return { reason: parentId || targetId ? '回复或转发的目标不存在' : '回复或转发缺少目标' };
    }
    if (isAmbientActor && postMapping.appId !== 'twitter' && postMapping.appId !== 'forum') {
      return { reason: '路人网友只能参与论坛或推特公开内容' };
    }
    if (referencedId && matchesPendingUserContent(context, content, { postId: referencedId })) {
      return { reason: '回复内容重复了待处理的用户帖子' };
    }
    const respondsToUser = referencedId
      ? context.state.posts[referencedId]?.profileId === context.selfProfileId
      : false;
    if (!respondsToUser && !isAutonomousAppAllowed(context, postMapping.appId)) {
      return { reason: `${describeApp(postMapping.appId)}已停用，已丢弃该自主动作` };
    }
    return {
      action: {
        ...base,
        appId: postMapping.appId,
        postKind: postMapping.kind,
        ...(title ? { title } : {}),
        ...(targetPostId ? { targetId: targetPostId } : {}),
        ...(parentPostId ? { parentId: parentPostId } : {}),
      },
    };
  }

  if (!targetId || !context.state.posts[targetId]) return { reason: '互动目标不存在' };
  const targetPost = context.state.posts[targetId];
  if (context.disabledAppIds?.has(targetPost.appId)) return { reason: '目标应用已停用' };
  if (context.conditionContext && !isAppAllowed(targetPost.appId, context.conditionContext)) {
    return { reason: '互动目标应用未通过条件门控' };
  }
  if (isAmbientActor && targetPost.appId !== 'twitter') {
    return { reason: '路人网友只能互动推特动态' };
  }
  const interactsWithUser = targetPost.profileId === context.selfProfileId;
  if (!interactsWithUser && !isAutonomousAppAllowed(context, targetPost.appId)) {
    return { reason: `${describeApp(targetPost.appId)}已停用，已丢弃该互动` };
  }
  if (matchesPendingUserContent(context, content, { postId: targetId })) {
    return { reason: '互动内容重复了待处理的用户帖子' };
  }
  return {
    action: {
      ...base,
      appId: targetPost.appId,
      targetId,
    },
  };
}

/**
 * 同人一致性：说话人先按绑定角色、再按显示名解析人物锁。
 * 解析不到人物锁时不做判定，避免对没有原著依据的联系人误报。
 */
function findFanficMessageViolation(
  context: ValidationContext,
  actorProfile: Profile | undefined,
  actorName: string,
  content: string,
): string | null {
  const guard = context.fanficGuard;
  if (!guard) return null;
  const speakerName = actorProfile?.boundCharacter?.trim() || actorProfile?.displayName?.trim() || actorName;
  if (!speakerName) return null;
  const violation = findFanficViolation({
    speakerName,
    content,
    character: guard.resolveCharacter(speakerName),
    secrets: guard.secrets,
  });
  return violation?.reason ?? null;
}

/** 该会话最近的消息文本（新到旧），用于判断关系转折是否有上下文支撑。 */
function conversationHistoryTexts(state: PhoneState, conversationId: string, limit = 14): readonly string[] {
  const texts: string[] = [];
  for (let index = state.messageOrder.length - 1; index >= 0 && texts.length < limit; index -= 1) {
    const messageId = state.messageOrder[index];
    const message = messageId ? state.messages[messageId] : undefined;
    if (!message || message.conversationId !== conversationId) continue;
    texts.push(message.content);
  }
  return texts;
}

function matchesPendingUserContent(
  context: ValidationContext,
  responseContent: string,
  target: { readonly conversationId?: string; readonly postId?: string },
): boolean {
  const normalizedResponse = normalizeEchoContent(responseContent);
  if (normalizedResponse.length < 4) return false;
  return Object.values(context.state.outbox).some((item) => {
    if (item.status === 'completed') return false;
    if (item.batchId && item.batchId !== context.batchId) return false;
    if (target.conversationId) {
      if (item.entityType !== 'message' || item.conversationId !== target.conversationId) return false;
      const message = context.state.messages[item.entityId];
      return message?.profileId === context.selfProfileId
        && normalizeEchoContent(message.content) === normalizedResponse;
    }
    if (target.postId) {
      if (item.entityType !== 'post' || item.entityId !== target.postId) return false;
      const post = context.state.posts[item.entityId];
      return post?.profileId === context.selfProfileId
        && normalizeEchoContent(post.content) === normalizedResponse;
    }
    return false;
  });
}

function normalizeEchoContent(value: string): string {
  return value.toLocaleLowerCase('zh-CN').replace(/[^\p{L}\p{N}]+/gu, '');
}

function isAutonomousAppAllowed(context: ValidationContext, appId: AppId): boolean {
  if (!context.allowedAutonomousApps) return true;
  return context.allowedAutonomousApps.has(appId);
}

function describeApp(appId: AppId): string {
  if (appId === 'forum') return '论坛';
  if (appId === 'twitter') return '推特';
  if (appId === 'anonymous') return '匿名交友';
  return '微信';
}

function parseResponse(raw: string): unknown {
  const trimmed = String(raw ?? '').trim();
  const fenced = /^```(?:json)?\s*([\s\S]*?)\s*```$/i.exec(trimmed);
  const candidate = fenced?.[1] ?? trimmed;
  const start = candidate.indexOf('{');
  const end = candidate.lastIndexOf('}');
  if (start < 0 || end <= start) return null;
  try {
    return JSON.parse(candidate.slice(start, end + 1));
  } catch {
    return null;
  }
}

interface SalvagedResponse {
  readonly version: number;
  readonly batchId: string;
  readonly actions: readonly Record<string, unknown>[];
}

/**
 * 从不完整的输出里恢复动作：扫描所有闭合的花括号对象，保留动作白名单内的那些。
 * 用于 max_tokens 不足导致 JSON 被截断的情况——已经写完的回复不该被整轮丢弃。
 */
function salvageResponse(raw: string, batchId: string): SalvagedResponse | null {
  const actions = scanBalancedObjects(String(raw ?? '')).filter((value) => {
    const type = value.type;
    return typeof type === 'string' && ACTION_TYPES.has(type as GenerationActionType);
  });
  if (actions.length === 0) return null;
  return { version: GENERATION_PROTOCOL_VERSION, batchId, actions };
}

function scanBalancedObjects(text: string): readonly Record<string, unknown>[] {
  const found: Record<string, unknown>[] = [];
  const starts: number[] = [];
  let inString = false;
  let escaped = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') inString = false;
      continue;
    }
    if (character === '"') inString = true;
    else if (character === '{') starts.push(index);
    else if (character === '}') {
      const start = starts.pop();
      if (start === undefined) continue;
      try {
        const value: unknown = JSON.parse(text.slice(start, index + 1));
        if (value && typeof value === 'object' && !Array.isArray(value)) found.push(value as Record<string, unknown>);
      } catch {
        // 残缺对象直接跳过。
      }
    }
  }
  return found;
}

function cleanIdentifier(value: unknown): string {
  return typeof value === 'string' && /^[a-zA-Z0-9:_-]{1,160}$/.test(value.trim()) ? value.trim() : '';
}

function cleanDisplayName(value: unknown): string {
  if (typeof value !== 'string') return '';
  const name = stripEmoji(value.replace(/\u0000/g, '')).trim();
  return name.length >= 1 && name.length <= 24 ? name : '';
}

/**
 * emoji 剥离（提示词已禁止，这里兜底）：
 * 覆盖 Extended_Pictographic、变体选择符、肤色修饰符、ZWJ 组合与区域旗帜。
 * 颜文字（QAQ、= = 等纯文本）不受影响。
 */
const EMOJI_PATTERN = /[\p{Extended_Pictographic}\u{FE0F}\u{200D}\u{1F3FB}-\u{1F3FF}\u{1F1E6}-\u{1F1FF}\u{20E3}]/gu;

function stripEmoji(value: string): string {
  return value.replace(EMOJI_PATTERN, '').replace(/ {2,}/g, ' ');
}

function cleanContent(value: unknown, limit: number): string {
  if (typeof value !== 'string') return '';
  const content = stripEmoji(value.replace(/\u0000/g, '')).trim();
  return content.length > 0 && content.length <= limit ? content : '';
}

function cleanForumTitle(value: unknown): string {
  return typeof value === 'string' ? stripEmoji(value.replace(/\u0000/g, '')).trim().slice(0, 80) : '';
}

function deriveForumTitle(content: string): string {
  const firstLine = content.split(/\r?\n/, 1)[0]?.trim() ?? '';
  const compact = firstLine.replace(/^[#【\[]+|[】\]]+$/g, '').trim();
  return (compact || '未命名主题').slice(0, 40);
}

function normalizeDelay(value: unknown): number | null {
  if (value === undefined) return null;
  const number = Number(value);
  return number >= 0 && number <= GENERATION_MAX_DELAY_MINUTES ? Math.round(number) : null;
}

function buildActionId(
  batchId: string,
  index: number,
  type: string,
  actorProfileId: string,
  content: string,
): string {
  let hash = 2166136261;
  for (const character of `${type}|${actorProfileId}|${content}`) {
    hash ^= character.charCodeAt(0);
    hash = Math.imul(hash, 16777619);
  }
  return `action:${batchId}:${index}:${(hash >>> 0).toString(36)}`;
}

function mapPostType(type: GenerationActionType):
  | { readonly appId: 'wechat' | 'forum' | 'twitter'; readonly kind: PostKind; readonly requiresParent: boolean }
  | null {
  switch (type) {
    case 'moment.create':
      return { appId: 'wechat', kind: 'moment', requiresParent: false };
    case 'forum.thread.create':
      return { appId: 'forum', kind: 'forum-thread', requiresParent: false };
    case 'forum.ambient.create':
      return { appId: 'forum', kind: 'forum-thread', requiresParent: false };
    case 'forum.reply.create':
      return { appId: 'forum', kind: 'forum-reply', requiresParent: true };
    case 'twitter.post.create':
      return { appId: 'twitter', kind: 'twitter-post', requiresParent: false };
    case 'twitter.ambient.create':
      return { appId: 'twitter', kind: 'twitter-post', requiresParent: false };
    case 'twitter.reply.create':
      return { appId: 'twitter', kind: 'twitter-reply', requiresParent: true };
    case 'twitter.repost.create':
      return { appId: 'twitter', kind: 'twitter-repost', requiresParent: true };
    default:
      return null;
  }
}