/** 已保存的 API 配置（配置库条目）：主/副/日记/记忆库统一从这里选用。 */
export interface ApiProfile extends OpenAiCompatibleApiConfig {
  /** 配置名称（唯一）。 */
  readonly name: string;
}

/** 把已保存配置套用到某个 API 槽位的补丁（不改动槽位的启用状态）。 */
export function applyApiProfile(profile: ApiProfile): Partial<OpenAiCompatibleApiConfig> {
  const { name, enabled: _enabled, profileName: _profileName, ...config } = profile;
  return { ...config, profileName: name };
}

/** 向量端点只复用配置库的连接信息，不继承温度、Token、流式等生成参数。 */
export function applyVectorProfile(profile: ApiProfile): VectorEndpointConfig {
  return {
    profileName: profile.name,
    baseUrl: profile.baseUrl,
    apiKey: profile.apiKey,
    model: profile.model,
  };
}

