  readonly maxStatements: number;
  /** 全局表格预设库：跟随扩展设置保存，被选中的那一份会在每个聊天里物化成自己的表。 */
  readonly presetLibrary: readonly SheetPresetBundle[];
  /** 当前使用的预设 id（'' = 不使用预设；'builtin-default' = 内置默认表格）。 */
  readonly activePresetId: string;
