/** 填表模型的默认输出上限：API 配置里 maxTokens 留空（跟随生成设置）时用它。 */
export const DATA_CENTER_DEFAULT_MAX_TOKENS = 1_600;

/**
 * 每轮注入表格内容的 token 预算。
 *
 * 刻意不再单独配置：注入给填表模型的表格量与它一轮能写多少 SQL 是同一个量级问题，
 * 两个旋钮只会互相打架，因此统一取该 API 配置的输出上限。
 * 表结构段最多占其中 35%，其余给「每轮注入」的整表内容与按需召回的行。
 */
export function resolveDataCenterInjectBudget(api: OpenAiCompatibleApiConfig): number {
  const raw = api.maxTokens ?? DATA_CENTER_DEFAULT_MAX_TOKENS;
  return Math.min(8_192, Math.max(256, Math.trunc(raw)));
}

