export function getSillyTavernRequestHeaders(
  context = getSillyTavernContext(),
): Record<string, string> {
  try {
    return { 'Content-Type': 'application/json', ...(context.getRequestHeaders?.() ?? {}) };
  } catch {
    return { 'Content-Type': 'application/json' };
  }
}

export function getSillyTavernContext(): SillyTavernContextShape {
  const currentWindow = typeof window === 'undefined' ? null : window;
  let parentContext: SillyTavernContextShape | undefined;
  try {
    const parentHost = currentWindow?.parent as unknown as SillyTavernHost | undefined;
    parentContext = parentHost?.SillyTavern?.getContext?.() as SillyTavernContextShape | undefined;
  } catch {
    // 跨域 parent 或受限环境下忽略，回退当前窗口。
  }
  const selfHost = currentWindow as unknown as SillyTavernHost | null;
  const selfContext = selfHost?.SillyTavern?.getContext?.() as SillyTavernContextShape | undefined;
  return parentContext ?? selfContext ?? {};
}

/**
 * 解析可用于扩展间通信的事件通道。
 * 优先使用酒馆 context.eventSource；若宿主只暴露前端助手全局事件函数，则使用其同一组 API。
 */
export function getSillyTavernEventChannel(): SillyTavernEventChannel | null {
  for (const host of getAccessibleSillyTavernHosts()) {
    const eventSource = readHostEventSource(host);
    if (eventSource) {
      const remove = eventSource.removeListener ?? eventSource.off;
      if (typeof eventSource.on === 'function'
        && typeof eventSource.emit === 'function'
        && typeof remove === 'function') {
        return {
          source: 'eventSource',
          on: eventSource.on.bind(eventSource),
          emit: eventSource.emit.bind(eventSource),
          removeListener: remove.bind(eventSource),
        };
      }
    }
    if (typeof host.eventOn === 'function'
      && typeof host.eventEmit === 'function'
      && typeof host.eventRemoveListener === 'function') {
      return {
        source: 'frontendHelper',
        on: host.eventOn.bind(host),
        emit: host.eventEmit.bind(host),
        removeListener: host.eventRemoveListener.bind(host),
      };
    }
  }
  return null;
}

function getAccessibleSillyTavernHosts(): readonly SillyTavernHost[] {
  const currentWindow = typeof window === 'undefined' ? null : window;
  if (!currentWindow) return [];
  const hosts: SillyTavernHost[] = [];
  try {
    const parentHost = currentWindow.parent as unknown as SillyTavernHost | undefined;
    if (parentHost && parentHost !== currentWindow) hosts.push(parentHost);
  } catch {
    // 跨域 parent 不可访问时只检查当前窗口。
  }
  const selfHost = currentWindow as unknown as SillyTavernHost;
  if (!hosts.includes(selfHost)) hosts.push(selfHost);
  return hosts;
}

function readHostEventSource(host: SillyTavernHost): SillyTavernEventSource | undefined {
  try {
    return host.SillyTavern?.getContext?.().eventSource ?? host.eventSource;
  } catch {
    return host.eventSource;
  }
}

export function getCurrentCharacterData(context = getSillyTavernContext()): unknown {
  const characterIndex = Number(context.characterId);
  if (Array.isArray(context.characters) && Number.isInteger(characterIndex)) {
    return context.characters[characterIndex] ?? context.character ?? null;
  }
  return context.character ?? null;
}

