export function getCurrentUserName(context = getSillyTavernContext()): string {
  return getCurrentUserPersona(context).displayName;
}

export function getCurrentUserPersona(context = getSillyTavernContext()): UserPersonaSnapshot {
  const host = getHostRecord();

  const managerCandidates = [
    asRecord(host.UserPersona),
    asRecord(host.userPersona),
    asRecord(host.UserPersonas),
    asRecord(host.userPersonas),
  ];
  for (const manager of managerCandidates) {
    const snapshot = resolvePersonaManagerSnapshot(manager);
    if (snapshot) return snapshot;
  }

  const powerUser = asRecord(host.power_user)
    ?? asRecord(asRecord(context.extensionSettings)?.power_user);
  const powerUserSnapshot = resolvePowerUserPersonaSnapshot(powerUser);
  if (powerUserSnapshot) return powerUserSnapshot;

  const extensionPersona = resolveExtensionSettingsPersonaSnapshot(context.extensionSettings);
  if (extensionPersona) return extensionPersona;

  const avatarSnapshot = resolveUserAvatarSnapshot(context);
  if (avatarSnapshot) return avatarSnapshot;

  const name = String(context.name1 ?? '').trim();
  const character = asRecord(context.character);
  const description = character
    ? pickString(character, ['description', 'bio', 'persona', 'personality', 'scenario'])
    : '';
  return {
    displayName: name || '用户',
    description,
    source: name
      ? (description ? 'context.name1+character' : 'context.name1')
      : 'default',
  };
}

export function maskApiKey(key: string): string {
  const trimmed = key.trim();
  if (!trimmed) return '';
  if (trimmed.length <= 8) return '****';
  return `${trimmed.slice(0, 4)}...${trimmed.slice(-4)}`;
}

export function getLatestChatTimestamp(context = getSillyTavernContext()): number | null {
  const messages = Array.isArray(context.chat) ? context.chat : [];
  for (let index = messages.length - 1; index >= 0; index -= 1) {
    const message = messages[index];
    const candidates = [message?.send_date, message?.sendDate, message?.timestamp];
    for (const candidate of candidates) {
      const normalized = normalizeTimestamp(candidate);
      if (normalized) return normalized;
    }
  }
  return null;
}

export function loadPhoneSettings(context = getSillyTavernContext()): PhoneExtensionSettings {
  const root = context.extensionSettings;
  const value = root?.[SETTINGS_KEY];
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const legacyProvider = source.preferTavernHelper === true ? 'tavernHelper' : DEFAULT_SETTINGS.generationProvider;
  const legacySelectedWorldBooks = normalizeWorldBookSelection(source.selectedWorldBooks);
  const settings: PhoneExtensionSettings = {
    enabled: source.enabled !== false,
    generationProvider: normalizeGenerationProvider(source.generationProvider, legacyProvider),
    allowTavernFallback: source.allowTavernFallback === true,
    jailbreakEnabled: source.jailbreakEnabled === true,
    jailbreakPrompt: String(source.jailbreakPrompt ?? ''),
    primaryApi: normalizeOpenAiCompatibleApiConfig(source.primaryApi, DEFAULT_SETTINGS.primaryApi),
    secondaryApi: normalizeOpenAiCompatibleApiConfig(source.secondaryApi, DEFAULT_SETTINGS.secondaryApi),
    apiProfiles: normalizeApiProfiles(source.apiProfiles),
    extensionModules: normalizeExtensionModules(source.extensionModules),
    diary: normalizeDiarySettings(source.diary),
    memory: normalizeMemorySettings(source.memory),
    dynamicWorldBook: normalizeDynamicWorldBookSettings(source.dynamicWorldBook),
    dataCenter: normalizeDataCenterSettings(source.dataCenter),
    fanfic: normalizeFanficSettings(source.fanfic),
    timeline: DEFAULT_TIMELINE_SETTINGS,
    vector: normalizeVectorSettings(source.vector),
    forum: normalizeForumSettings(source.forum),
    conditions: normalizeConditionRulesSettings(source.conditions),
    worldRotationEnabled: source.worldRotationEnabled !== false,
    autoParseEnabled: source.autoParseEnabled === true,
    autoParseDeferCurrentFloor: source.autoParseDeferCurrentFloor === true,
    autoParseEveryAiMessages: clampInteger(
      source.autoParseEveryAiMessages,
      1,
      100,
      DEFAULT_SETTINGS.autoParseEveryAiMessages,
    ),
    autoParseMode: normalizeAutoParseMode(source.autoParseMode),
    manualFormatAdapters: normalizeUserFormatAdapters(source.manualFormatAdapters),
    formatAdapterOverrides: normalizeFormatAdapterOverrides(source.formatAdapterOverrides),
    autonomousPostBudget: clampInteger(source.autonomousPostBudget, 0, 8, DEFAULT_SETTINGS.autonomousPostBudget),
    conversationShardSize: clampInteger(
      source.conversationShardSize,
      0,
      12,
      DEFAULT_SETTINGS.conversationShardSize,
    ),
    generationTemperature: clampNumber(source.generationTemperature, 0, 2, DEFAULT_SETTINGS.generationTemperature),
    generationMaxTokens: clampInteger(source.generationMaxTokens, 128, 8192, DEFAULT_SETTINGS.generationMaxTokens),
    storagePreference: normalizeStoragePreference(source.storagePreference),
    includeWorldBook: source.includeWorldBook !== false,
    worldBookSourceMode: normalizeWorldBookSourceMode(
      source.worldBookSourceMode,
      legacySelectedWorldBooks.length > 0 ? 'selected' : 'bound',
    ),
    selectedWorldBooks: legacySelectedWorldBooks,
    worldBookEntrySelections: normalizeWorldBookEntrySelections(source.worldBookEntrySelections),
    phoneMode: normalizePhoneMode(source.phoneMode, 'auto'),
    customInsertionAnchor: source.phoneMode === 'enhanced'
      ? (source.enhancedInsertionAnchor === 'user' ? 'user' : 'ai')
      : (source.customInsertionAnchor === 'user' ? 'user' : 'ai'),
    phonePresetPromptId: String(source.phonePresetPromptId ?? '').trim().slice(0, 200),
    phonePresetPromptRole: normalizeStoryMemoryPresetRole(source.phonePresetPromptRole),
    uiTheme: source.uiTheme === 'dark' || source.uiTheme === 'glass' ? source.uiTheme : 'light',
    contextFloorCount: clampInteger(source.contextFloorCount, 0, 100, DEFAULT_SETTINGS.contextFloorCount),
    memoryInjectCount: clampInteger(source.memoryInjectCount, 0, 20, DEFAULT_SETTINGS.memoryInjectCount),
    phoneSummaryEnabled: source.phoneSummaryEnabled === true,
    summaryThreshold: normalizeSummaryThreshold(source.summaryThreshold, DEFAULT_SETTINGS.summaryThreshold),
    summaryLength: clampInteger(source.summaryLength, 100, 2_000, DEFAULT_SETTINGS.summaryLength),
    summaryInjectCount: clampInteger(source.summaryInjectCount, 1, 10, DEFAULT_SETTINGS.summaryInjectCount),
    clockDateVariable: String(source.clockDateVariable ?? '').trim().slice(0, 200),
    clockTimeVariable: String(source.clockTimeVariable ?? '').trim().slice(0, 200),
    timeAdvance: normalizeTimeAdvanceSettings(source.timeAdvance),
    tavernPromptLogEnabled: source.tavernPromptLogEnabled === true,
    personalization: normalizePersonalizationSettings(source.personalization),
    imageGeneration: normalizeImageGenerationSettings(source.imageGeneration),
  };
  if (root && (value === undefined || source.phoneMode === 'enhanced')) {
    root[SETTINGS_KEY] = { ...settings };
    context.saveSettingsDebounced?.();
  }
  return settings;
}

export function savePhoneSettings(
  patch: PhoneSettingsPatch,
  context = getSillyTavernContext(),
): PhoneExtensionSettings {
  const current = loadPhoneSettings(context);
  const next: PhoneExtensionSettings = {
    enabled: patch.enabled ?? current.enabled,
    generationProvider: normalizeGenerationProvider(patch.generationProvider, current.generationProvider),
    allowTavernFallback: patch.allowTavernFallback ?? current.allowTavernFallback,
    jailbreakEnabled: patch.jailbreakEnabled ?? current.jailbreakEnabled,
    jailbreakPrompt: String(patch.jailbreakPrompt ?? current.jailbreakPrompt),
    primaryApi: normalizeOpenAiCompatibleApiConfig(
      patch.primaryApi ? { ...current.primaryApi, ...patch.primaryApi } : current.primaryApi,
      current.primaryApi,
    ),
    secondaryApi: normalizeOpenAiCompatibleApiConfig(
      patch.secondaryApi ? { ...current.secondaryApi, ...patch.secondaryApi } : current.secondaryApi,
      current.secondaryApi,
    ),
    apiProfiles: patch.apiProfiles !== undefined ? normalizeApiProfiles(patch.apiProfiles) : current.apiProfiles,
    extensionModules: patch.extensionModules !== undefined
      ? normalizeExtensionModules(patch.extensionModules)
      : current.extensionModules,
    diary: normalizeDiarySettings(
      patch.diary
        ? {
            ...current.diary,
            ...patch.diary,
            api: patch.diary.api ? { ...current.diary.api, ...patch.diary.api } : current.diary.api,
          }
        : current.diary,
    ),
    memory: normalizeMemorySettings(
      patch.memory
        ? {
            ...current.memory,
            ...patch.memory,
            recallApi: patch.memory.recallApi
              ? { ...current.memory.recallApi, ...patch.memory.recallApi }
              : current.memory.recallApi,
            organizeApi: patch.memory.organizeApi
              ? { ...current.memory.organizeApi, ...patch.memory.organizeApi }
              : current.memory.organizeApi,
          }
        : current.memory,
    ),
    dynamicWorldBook: normalizeDynamicWorldBookSettings(
      patch.dynamicWorldBook
        ? {
            ...current.dynamicWorldBook,
            ...patch.dynamicWorldBook,
            api: patch.dynamicWorldBook.api
              ? { ...current.dynamicWorldBook.api, ...patch.dynamicWorldBook.api }
              : current.dynamicWorldBook.api,
          }
        : current.dynamicWorldBook,
    ),
    dataCenter: normalizeDataCenterSettings(
      patch.dataCenter
        ? {
            ...current.dataCenter,
            ...patch.dataCenter,
            api: patch.dataCenter.api ? { ...current.dataCenter.api, ...patch.dataCenter.api } : current.dataCenter.api,
            mvuBridge: patch.dataCenter.mvuBridge
              ? { ...current.dataCenter.mvuBridge, ...patch.dataCenter.mvuBridge }
              : current.dataCenter.mvuBridge,
          }
        : current.dataCenter,
    ),
    fanfic: normalizeFanficSettings(
      patch.fanfic
        ? {
            ...current.fanfic,
            ...patch.fanfic,
            api: patch.fanfic.api ? { ...current.fanfic.api, ...patch.fanfic.api } : current.fanfic.api,
          }
        : current.fanfic,
    ),
    timeline: DEFAULT_TIMELINE_SETTINGS,
    vector: normalizeVectorSettings(
      patch.vector
        ? {
            ...current.vector,
            ...patch.vector,
            embedding: patch.vector.embedding ? { ...current.vector.embedding, ...patch.vector.embedding } : current.vector.embedding,
            rerank: patch.vector.rerank ? { ...current.vector.rerank, ...patch.vector.rerank } : current.vector.rerank,
          }
        : current.vector,
    ),
    forum: mergeForumSettings(current.forum, patch.forum),
    conditions: normalizeConditionRulesSettings(
      patch.conditions ? { ...current.conditions, ...patch.conditions } : current.conditions,
    ),
    worldRotationEnabled: patch.worldRotationEnabled ?? current.worldRotationEnabled,
    autoParseEnabled: patch.autoParseEnabled ?? current.autoParseEnabled,
    autoParseDeferCurrentFloor: patch.autoParseDeferCurrentFloor ?? current.autoParseDeferCurrentFloor,
    autoParseEveryAiMessages: clampInteger(
      patch.autoParseEveryAiMessages ?? current.autoParseEveryAiMessages,
      1,
      100,
      current.autoParseEveryAiMessages,
    ),
    autoParseMode: normalizeAutoParseMode(patch.autoParseMode ?? current.autoParseMode),
    manualFormatAdapters: patch.manualFormatAdapters !== undefined
      ? normalizeUserFormatAdapters(patch.manualFormatAdapters)
      : current.manualFormatAdapters,
    formatAdapterOverrides: patch.formatAdapterOverrides !== undefined
      ? normalizeFormatAdapterOverrides(patch.formatAdapterOverrides)
      : current.formatAdapterOverrides,
    autonomousPostBudget: clampInteger(
      patch.autonomousPostBudget ?? current.autonomousPostBudget,
      0,
      8,
      current.autonomousPostBudget,
    ),
    conversationShardSize: clampInteger(
      patch.conversationShardSize ?? current.conversationShardSize,
      0,
      12,
      current.conversationShardSize,
    ),
    generationTemperature: clampNumber(
      patch.generationTemperature ?? current.generationTemperature,
      0,
      2,
      current.generationTemperature,
    ),
    generationMaxTokens: clampInteger(
      patch.generationMaxTokens ?? current.generationMaxTokens,
      128,
      8192,
      current.generationMaxTokens,
    ),
    storagePreference: normalizeStoragePreference(patch.storagePreference, current.storagePreference),
    includeWorldBook: patch.includeWorldBook ?? current.includeWorldBook,
    worldBookSourceMode: normalizeWorldBookSourceMode(patch.worldBookSourceMode, current.worldBookSourceMode),
    selectedWorldBooks: patch.selectedWorldBooks !== undefined
      ? normalizeWorldBookSelection(patch.selectedWorldBooks)
      : current.selectedWorldBooks,
    worldBookEntrySelections: patch.worldBookEntrySelections !== undefined
      ? normalizeWorldBookEntrySelections(patch.worldBookEntrySelections)
      : current.worldBookEntrySelections,
    phoneMode: normalizePhoneMode(patch.phoneMode, current.phoneMode),
    customInsertionAnchor: patch.customInsertionAnchor === 'user' || patch.customInsertionAnchor === 'ai'
      ? patch.customInsertionAnchor
      : current.customInsertionAnchor,
    phonePresetPromptId: String(patch.phonePresetPromptId ?? current.phonePresetPromptId).trim().slice(0, 200),
    phonePresetPromptRole: patch.phonePresetPromptRole !== undefined
      ? normalizeStoryMemoryPresetRole(patch.phonePresetPromptRole)
      : current.phonePresetPromptRole,
    uiTheme: patch.uiTheme === 'dark' || patch.uiTheme === 'light' || patch.uiTheme === 'glass' ? patch.uiTheme : current.uiTheme,
    contextFloorCount: clampInteger(patch.contextFloorCount ?? current.contextFloorCount, 0, 100, current.contextFloorCount),
    memoryInjectCount: clampInteger(patch.memoryInjectCount ?? current.memoryInjectCount, 0, 20, current.memoryInjectCount),
    phoneSummaryEnabled: patch.phoneSummaryEnabled ?? current.phoneSummaryEnabled,
    summaryThreshold: normalizeSummaryThreshold(patch.summaryThreshold ?? current.summaryThreshold, current.summaryThreshold),
    summaryLength: clampInteger(patch.summaryLength ?? current.summaryLength, 100, 2_000, current.summaryLength),
    summaryInjectCount: clampInteger(patch.summaryInjectCount ?? current.summaryInjectCount, 1, 10, current.summaryInjectCount),
    clockDateVariable: String(patch.clockDateVariable ?? current.clockDateVariable).trim().slice(0, 200),
    clockTimeVariable: String(patch.clockTimeVariable ?? current.clockTimeVariable).trim().slice(0, 200),
    timeAdvance: normalizeTimeAdvanceSettings({ ...current.timeAdvance, ...patch.timeAdvance }),
    tavernPromptLogEnabled: patch.tavernPromptLogEnabled ?? current.tavernPromptLogEnabled,
    personalization: normalizePersonalizationSettings(
      patch.personalization ? { ...current.personalization, ...patch.personalization } : current.personalization,
    ),
    imageGeneration: normalizeImageGenerationSettings(
      patch.imageGeneration ? { ...current.imageGeneration, ...patch.imageGeneration } : current.imageGeneration,
    ),
  };
  if (next.memory.presetPromptId && next.memory.presetPromptId === next.phonePresetPromptId) {
    throw new Error('故事记忆槽与手机互动槽不能使用同一 ID，请修改槽位后再保存。');
  }
  if (context.extensionSettings) {
    context.extensionSettings[SETTINGS_KEY] = { ...next };
    context.saveSettingsDebounced?.();
  }
  return next;
}

function normalizeAutoParseMode(value: unknown): PhoneExtensionSettings['autoParseMode'] {
  return value === 'deterministic' || value === 'llm' || value === 'hybrid' ? value : 'hybrid';
}

function normalizeFormatAdapterOverrides(value: unknown): Readonly<Record<string, boolean>> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const overrides: Record<string, boolean> = {};
  for (const [rawId, enabled] of Object.entries(value as Record<string, unknown>)) {
    const id = rawId.trim().slice(0, 160);
    if (!id || enabled !== false) continue;
    overrides[id] = false;
    if (Object.keys(overrides).length >= 100) break;
  }
  return overrides;
}

function normalizePhoneMode(
  value: unknown,
  fallback: PhoneExtensionSettings['phoneMode'],
): PhoneExtensionSettings['phoneMode'] {
  // 'enhanced' 是历史模式名，语义等价于当前的自定义插入位置。
  if (value === 'enhanced') return 'custom';
  return value === 'offline' || value === 'hidden' || value === 'auto' || value === 'custom' || value === 'preset'
    ? value
    : fallback;
}

function normalizeWorldBookSourceMode(value: unknown, fallback: WorldBookSourceMode = 'bound'): WorldBookSourceMode {
  return value === 'selected' || value === 'bound' ? value : fallback;
}

function normalizeWorldBookSelection(value: unknown): readonly string[] {
  if (!Array.isArray(value)) return [];
  return [...new Set(value
    .map((item) => String(item ?? '').trim())
    .filter(Boolean))];
}

function normalizeWorldBookEntrySelections(value: unknown): Readonly<Record<string, WorldBookEntrySelection>> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const selections: Record<string, WorldBookEntrySelection> = {};
  for (const [rawBook, rawSelection] of Object.entries(value as Record<string, unknown>)) {
    const book = rawBook.trim();
    if (!book || !rawSelection || typeof rawSelection !== 'object' || Array.isArray(rawSelection)) continue;
    const selection = rawSelection as Record<string, unknown>;
    const entryIds = Array.isArray(selection.entryIds)
      ? [...new Set(selection.entryIds
        .map((item) => String(item ?? '').trim())
        .filter(Boolean))]
      : [];
    selections[book] = selection.mode === 'manual'
      ? { mode: 'manual', entryIds }
      : { mode: 'enabled', entryIds: [] };
  }
  return selections;
}

function normalizeExtensionModules(value: unknown): readonly ExtensionModuleRecord[] {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  const records: ExtensionModuleRecord[] = [];
  for (const item of value) {
    if (!item || typeof item !== 'object' || Array.isArray(item)) continue;
    const raw = item as Record<string, unknown>;
    try {
      const manifest = validateExtensionModuleManifest(raw.manifest);
      if (seen.has(manifest.id)) continue;
      const source = String(raw.source ?? '');
      if (!source || new TextEncoder().encode(source).byteLength > 1_500_000) continue;
      seen.add(manifest.id);
      records.push({
        manifest,
        source,
        importedAt: Number.isFinite(Number(raw.importedAt)) ? Number(raw.importedAt) : Date.now(),
        enabled: raw.enabled !== false,
        settings: raw.settings && typeof raw.settings === 'object' && !Array.isArray(raw.settings)
          ? raw.settings as Readonly<Record<string, unknown>>
          : {},
      });
    } catch {
      // 设置加载必须容忍已损坏的第三方模块，避免拖垮整个手机插件。
    }
  }
  return records.slice(0, 30);
}

/** 规范化配置库：名称唯一（1-40 字），最多 30 条；条目内不携带 profileName。 */
function normalizeApiProfiles(value: unknown): readonly ApiProfile[] {
  if (!Array.isArray(value)) return [];
  const seen = new Set<string>();
  const profiles: ApiProfile[] = [];
  for (const entry of value) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry)) continue;
    const record = entry as Record<string, unknown>;
    const name = String(record.name ?? '').trim().slice(0, 40);
    if (!name || seen.has(name)) continue;
    seen.add(name);
    const { profileName: _profileName, ...config } = normalizeOpenAiCompatibleApiConfig(
      record,
      DEFAULT_API_PROFILE_CONFIG,
    );
    profiles.push({ name, ...config });
    if (profiles.length >= 30) break;
  }
  return profiles;
}

/** 自定义提示词模板：只保存纯文本并限制长度，'' 表示使用内置提示词。 */
function normalizePromptTemplate(value: unknown): string {
  return typeof value === 'string' ? value.replace(/\u0000/g, '').trim().slice(0, 4_000) : '';
}

function normalizeStoryMemoryPresetRole(value: unknown): StoryMemoryPresetRole {
  return value === 'system' || value === 'user' || value === 'assistant' ? value : '';
}

/**
 * 召回方式归一化。缺少 `recallMode` 的旧配置按双开关时代的语义迁移：
 * 只有「关掉记忆召回且开着向量召回」才落到向量模式，其余一律回到记忆召回（历史默认行为）。
 */
function normalizeStoryRecallMode(source: Record<string, unknown>): StoryRecallMode {
  if (source.recallMode === 'vector' || source.recallMode === 'memory') return source.recallMode;
  return source.vectorRecallEnabled === true && source.recallEnabled === false ? 'vector' : 'memory';
}

function normalizeMemorySettings(value: unknown): MemorySettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const legacyApi = source.api;
  const recallSource = source.recallApi ?? legacyApi;
  const organizeSource = source.organizeApi ?? legacyApi;
  return {
    enabled: source.enabled === true,
    injectionMode: source.injectionMode === 'preset' ? 'preset' : 'extension',
    presetPromptId: String(source.presetPromptId ?? '').trim().slice(0, 200),
    presetPromptRole: normalizeStoryMemoryPresetRole(source.presetPromptRole),
    everyAiMessages: clampInteger(source.everyAiMessages, 1, 20, DEFAULT_MEMORY_SETTINGS.everyAiMessages),
    minContentChars: clampInteger(source.minContentChars, 0, 20_000, DEFAULT_MEMORY_SETTINGS.minContentChars),
    deferCurrentFloor: source.deferCurrentFloor === true,
    consolidateEvery: clampInteger(source.consolidateEvery, 0, 50, DEFAULT_MEMORY_SETTINGS.consolidateEvery),
    recallMode: normalizeStoryRecallMode(source),
    memoryPrompt: normalizePromptTemplate(source.memoryPrompt),
    summaryPrompt: normalizePromptTemplate(source.summaryPrompt),
    recallApi: normalizeOpenAiCompatibleApiConfig(recallSource, DEFAULT_MEMORY_SETTINGS.recallApi),
    organizeApi: normalizeOpenAiCompatibleApiConfig(organizeSource, DEFAULT_MEMORY_SETTINGS.organizeApi),
  };
}

/** 同人剧情设置归一化：预算与条数都有硬上限，避免注入撑爆上下文。 */
function normalizeFanficSettings(value: unknown): FanficSettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  return {
    enabled: source.enabled === true,
    autoTrack: source.autoTrack !== false,
    trackEveryAiMessages: clampInteger(source.trackEveryAiMessages, 1, 20, DEFAULT_FANFIC_SETTINGS.trackEveryAiMessages),
    characterLimit: clampInteger(source.characterLimit, 1, 16, DEFAULT_FANFIC_SETTINGS.characterLimit),
    factLimit: clampInteger(source.factLimit, 0, 40, DEFAULT_FANFIC_SETTINGS.factLimit),
    excerptLimit: clampInteger(source.excerptLimit, 0, 6, DEFAULT_FANFIC_SETTINGS.excerptLimit),
    charBudget: clampInteger(source.charBudget, 1_000, 30_000, DEFAULT_FANFIC_SETTINGS.charBudget),
    title: String(source.title ?? '').trim().slice(0, 80),
    api: normalizeOpenAiCompatibleApiConfig(source.api, DEFAULT_FANFIC_SETTINGS.api),
  };
}

function normalizeDynamicWorldBookSettings(value: unknown): DynamicWorldBookSettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const managedEntryIds = Array.isArray(source.managedEntryIds)
    ? [...new Set(source.managedEntryIds.map(String).map((id) => id.trim()).filter(Boolean))].slice(0, 200)
    : [...DEFAULT_DYNAMIC_WORLD_BOOK_SETTINGS.managedEntryIds];
  return {
    enabled: source.enabled === true,
    everyAiMessages: clampInteger(source.everyAiMessages, 1, 100, DEFAULT_DYNAMIC_WORLD_BOOK_SETTINGS.everyAiMessages),
    deferCurrentFloor: source.deferCurrentFloor !== false,
    overlayDepth: clampInteger(source.overlayDepth, 0, 100, DEFAULT_DYNAMIC_WORLD_BOOK_SETTINGS.overlayDepth),
    managedEntryIds,
    api: normalizeOpenAiCompatibleApiConfig(source.api, DEFAULT_DYNAMIC_WORLD_BOOK_SETTINGS.api),
  };
}

function normalizeDataCenterSettings(value: unknown): DataCenterSettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const library = normalizeSheetPresetBundles(source.presetLibrary);
  // 旧版本把所有导入的表混在一个 `presets` 数组里；升级时整体收成一份可选择的预设包。
  const legacySheets = library.length === 0 ? normalizeSheetPresetEntries(source.presets) : [];
  const migrated = legacySheets.length > 0
    ? [{ id: presetBundleId('已导入预设'), name: '已导入预设', sheets: legacySheets }]
    : library;
  const requestedId = String(source.activePresetId ?? '').trim().slice(0, 80);
  return {
    enabled: source.enabled === true,
    everyAiMessages: clampInteger(source.everyAiMessages, 1, 100, DEFAULT_DATA_CENTER_SETTINGS.everyAiMessages),
    minContentChars: clampInteger(source.minContentChars, 0, 20_000, DEFAULT_DATA_CENTER_SETTINGS.minContentChars),
    deferCurrentFloor: source.deferCurrentFloor !== false,
    maxStatements: clampInteger(source.maxStatements, 1, 32, DEFAULT_DATA_CENTER_SETTINGS.maxStatements),
    presetLibrary: migrated,
    activePresetId: requestedId || (legacySheets.length > 0 ? migrated[0]?.id ?? '' : ''),
    mvuBridge: normalizeMvuBridgeSettings(source.mvuBridge),
    api: normalizeOpenAiCompatibleApiConfig(source.api, DEFAULT_DATA_CENTER_SETTINGS.api),
  };
}

function normalizeMvuBridgeSettings(value: unknown): MvuBridgeSettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const mode = source.mode === 'takeover' || source.mode === 'off' ? source.mode : 'auto';
  return {
    mode,
    projectToVariables: source.projectToVariables !== false,
    acceptStoryTableSql: source.acceptStoryTableSql === true,
  };
}

function normalizeVectorEndpoint(value: unknown): VectorEndpointConfig {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const profileName = String(source.profileName ?? '').trim().slice(0, 40);
  return {
    ...(profileName ? { profileName } : {}),
    baseUrl: String(source.baseUrl ?? '').trim().slice(0, 400),
    apiKey: String(source.apiKey ?? '').trim().slice(0, 400),
    model: String(source.model ?? '').trim().slice(0, 200),
  };
}

function normalizeVectorSettings(value: unknown): VectorSettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  return {
    enabled: source.enabled === true,
    topK: clampInteger(source.topK, 1, 10, DEFAULT_VECTOR_SETTINGS.topK),
    candidateLimit: clampInteger(source.candidateLimit, 1, 200, DEFAULT_VECTOR_SETTINGS.candidateLimit),
    minScore: clampNumber(source.minScore, 0, 1, DEFAULT_VECTOR_SETTINGS.minScore),
    embedBatchSize: clampInteger(source.embedBatchSize, 1, 256, DEFAULT_VECTOR_SETTINGS.embedBatchSize),
    queryChars: clampInteger(source.queryChars, 200, 20_000, DEFAULT_VECTOR_SETTINGS.queryChars),
    documentChars: clampInteger(source.documentChars, 200, 20_000, DEFAULT_VECTOR_SETTINGS.documentChars),
    autoIndex: source.autoIndex !== false,
    rerankEnabled: source.rerankEnabled !== false,
    rerankTopN: clampInteger(source.rerankTopN, 0, 50, DEFAULT_VECTOR_SETTINGS.rerankTopN),
    rerankMinScore: clampNumber(source.rerankMinScore, 0, 1, DEFAULT_VECTOR_SETTINGS.rerankMinScore),
    embedding: normalizeVectorEndpoint(source.embedding),
    rerank: normalizeVectorEndpoint(source.rerank),
  };
}

function normalizeDiarySettings(value: unknown): DiarySettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  return {
    enabled: source.enabled === true,
    intervalDays: clampInteger(source.intervalDays, 1, 30, DEFAULT_DIARY_SETTINGS.intervalDays),
    api: normalizeOpenAiCompatibleApiConfig(source.api, DEFAULT_DIARY_SETTINGS.api),
  };
}

function normalizeImageGenerationSettings(value: unknown): ImageGenerationSettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const provider = source.provider === 'novelai' || source.provider === 'sdwebui'
    || source.provider === 'comfyui' || source.provider === 'zhihuiji'
    ? source.provider
    : 'openai';
  return {
    enabled: source.enabled === true,
    provider,
    novelaiSite: source.novelaiSite === 'community' || source.novelaiSite === 'custom' ? source.novelaiSite : 'official',
    novelaiQueueEnabled: source.novelaiQueueEnabled === true,
    novelaiQueueUrl: String(source.novelaiQueueUrl ?? '').trim().replace(/\/+$/, '').slice(0, 500),
    baseUrl: String(source.baseUrl ?? '').trim().replace(/\/+$/, '').slice(0, 500),
    apiKey: String(source.apiKey ?? '').trim().slice(0, 500),
    model: String(source.model ?? '').trim().slice(0, 200),
    width: clampInteger(source.width, 64, 2048, DEFAULT_IMAGE_SETTINGS.width),
    height: clampInteger(source.height, 64, 2048, DEFAULT_IMAGE_SETTINGS.height),
    steps: clampInteger(source.steps, 1, 150, DEFAULT_IMAGE_SETTINGS.steps),
    cfgScale: clampNumber(source.cfgScale, 1, 30, DEFAULT_IMAGE_SETTINGS.cfgScale),
    sampler: String(source.sampler ?? '').trim().slice(0, 80),
    scheduler: String(source.scheduler ?? '').trim().slice(0, 80),
    quality: source.quality === 'standard' || source.quality === 'hd' ? source.quality : '',
    sdAuth: String(source.sdAuth ?? '').trim().slice(0, 200),
    positivePrompt: String(source.positivePrompt ?? '').slice(0, 2000),
    negativePrompt: String(source.negativePrompt ?? '').slice(0, 2000),
    customPromptEnabled: source.customPromptEnabled === true,
    customPrompt: String(source.customPrompt ?? '').slice(0, 4000),
    customMarkerStart: String(source.customMarkerStart ?? '').trim().slice(0, 60),
    customMarkerEnd: String(source.customMarkerEnd ?? '').trim().slice(0, 60),
    promptPresets: normalizeImagePromptPresets(source.promptPresets),
  };
}

function normalizeImagePromptPresets(value: unknown): readonly ImagePromptPreset[] {
  if (!Array.isArray(value)) return [];
  const presets: ImagePromptPreset[] = [];
  for (const item of value.slice(0, 20)) {
    if (!item || typeof item !== 'object') continue;
    const record = item as Record<string, unknown>;
    const name = String(record.name ?? '').trim().slice(0, 40);
    if (!name) continue;
    presets.push({
      name,
      positive: String(record.positive ?? '').slice(0, 2000),
      negative: String(record.negative ?? '').slice(0, 2000),
    });
  }
  return presets;
}

export function getWorldBookSnapshot(context = getSillyTavernContext()): WorldBookSnapshot {
  const metadata = context.chatMetadata ?? {};
  const candidates = [
    context.worldBook,
    context.worldbook,
    context.worldInfo,
    metadata.worldBook,
    metadata.worldbook,
    metadata.world_info,
  ];
  for (const candidate of candidates) {
    const rawEntries = collectWorldBookEntries(candidate);
    if (rawEntries.length === 0) continue;
    const entries: WorldBookEntrySnapshot[] = rawEntries.map((entry, index) => {
      const id = resolveWorldBookEntryId(entry, index);
      return {
        id,
        legacyIds: resolveWorldBookEntryAliases(entry, index, 'context', id),
        ...(readRuleActivation(entry) ? { activation: readRuleActivation(entry) } : {}),
        name: cleanWorldBookName(entry, index),
        content: cleanWorldBookContent(entry),
        enabled: entry.enabled !== false && entry.disable !== true,
      };
    });
    return buildWorldBookSnapshot('context', [], entries);
  }
  return emptyWorldBookSnapshot();
}

export function emptyWorldBookSnapshot(): WorldBookSnapshot {
  return {
    available: false,
    source: 'none',
    catalog: [],
    books: [],
    activeEntryCount: 0,
    entryCount: 0,
    activeEntries: [],
    names: [],
    entries: [],
    excerpt: '',
  };
}

/**
 * 读取当前角色卡/聊天绑定或用户指定的世界书及其条目。
 * 依次尝试：酒馆助手 API → 角色卡数据 + /api/worldinfo/get → 上下文旧式探测。
 */
export async function loadWorldBookSnapshot(
  context = getSillyTavernContext(),
  options: {
    readonly sourceMode?: WorldBookSourceMode;
    readonly selectedBooks?: readonly string[];
    readonly entrySelections?: Readonly<Record<string, WorldBookEntrySelection>>;
  } = {},
): Promise<WorldBookSnapshot> {
  const sourceMode = options.sourceMode ?? 'bound';
  const readBoundBooks = sourceMode === 'bound';
  const selectedBooks = options.selectedBooks ?? [];
  const entrySelections = options.entrySelections ?? {};
  const viaHelper = await loadWorldBookViaTavernHelper(selectedBooks, entrySelections, readBoundBooks);
  if (viaHelper) return viaHelper;
  const viaCharacter = await loadWorldBookViaCharacterData(context, selectedBooks, entrySelections, readBoundBooks);
  if (viaCharacter) return viaCharacter;
  return sourceMode === 'selected' ? emptyWorldBookSnapshot() : getWorldBookSnapshot(context);
}

async function loadWorldBookViaTavernHelper(
  selectedBooks: readonly string[],
  entrySelections: Readonly<Record<string, WorldBookEntrySelection>>,
  readBoundBooks: boolean,
): Promise<WorldBookSnapshot | null> {
  const host = getHostRecord();
  const helper = asRecord(host.TavernHelper);
  if (!helper) return null;

  const bookNames: string[] = [];
  const addBook = (value: unknown) => {
    const name = String(value ?? '').trim();
    if (name && !bookNames.includes(name)) bookNames.push(name);
  };
  const catalog = resolveHelperBookNames(helper);


  const charBooks = asRecord(
    callHelperMethod(helper, 'getCharWorldbookNames', ['current'])
      ?? callHelperMethod(helper, 'getCharLorebooks', [{ name: 'current' }]),
  );
  if (charBooks) {
    addBook(charBooks.primary);
    for (const additional of Array.isArray(charBooks.additional) ? charBooks.additional : []) addBook(additional);
  }
  addBook(callHelperMethod(helper, 'getChatWorldbookName', ['current'])
    ?? callHelperMethod(helper, 'getChatLorebook', []));

  const boundBookNames = [...bookNames];
  bookNames.length = 0;
  for (const selected of readBoundBooks ? boundBookNames : selectedBooks) addBook(selected);
  if (bookNames.length === 0) return catalog.length > 0 ? buildWorldBookSnapshot('tavernHelper', [], [], catalog) : null;

  const entries: WorldBookEntrySnapshot[] = [];
  for (const bookName of bookNames) {
    const rawEntries = await resolveHelperEntries(helper, bookName);
    for (const raw of rawEntries) {
      const entry = asRecord(raw);
      if (!entry) continue;
      const id = resolveWorldBookEntryId(entry, entries.length, bookName);
      entries.push({
        id,
        legacyIds: resolveWorldBookEntryAliases(entry, entries.length, bookName, id),
        ...(readRuleActivation(entry) ? { activation: readRuleActivation(entry) } : {}),
        book: bookName,
        name: String(entry.name ?? entry.comment ?? '').trim() || `条目 ${entries.length + 1}`,
        content: String(entry.content ?? '').trim(),
        enabled: entry.enabled !== false && entry.disable !== true,
      });
    }
  }
  return buildWorldBookSnapshot('tavernHelper', bookNames, entries, catalog, entrySelections);
}

function resolveHelperBookNames(helper: Record<string, unknown>): readonly string[] {
  for (const methodName of ['getWorldbookNames', 'getLorebookNames', 'getWorldbooks', 'getLorebooks']) {
    const result = callHelperMethod(helper, methodName, []);
    const values = Array.isArray(result)
      ? result
      : result && typeof result === 'object'
        ? Object.keys(result as Record<string, unknown>)
        : [];
    const names = values.map((value) => {
      if (typeof value === 'string') return value.trim();
      const record = asRecord(value);
      return String(record?.name ?? record?.bookName ?? record?.id ?? '').trim();
    }).filter(Boolean);
    if (names.length > 0) return [...new Set(names)];
  }
  return [];
}

async function resolveHelperEntries(
  helper: Record<string, unknown>,
  bookName: string,
): Promise<readonly unknown[]> {
  for (const methodName of ['getWorldbook', 'getLorebookEntries']) {
    const method = helper[methodName];
    if (typeof method !== 'function') continue;
    try {
      const result = await Promise.resolve((method as (name: string) => unknown).call(helper, bookName));
      if (Array.isArray(result)) return result;
    } catch {
      // 尝试下一个方法名。
    }
  }
  return [];
}

async function loadWorldBookViaCharacterData(
  context: SillyTavernContextShape,
  selectedBooks: readonly string[] = [],
  entrySelections: Readonly<Record<string, WorldBookEntrySelection>> = {},
  readBoundBooks = true,
): Promise<WorldBookSnapshot | null> {
  const contextRecord = context as unknown as Record<string, unknown>;
  const characters = contextRecord.characters;
  const characterIndex = Number(context.characterId);
  const character = Array.isArray(characters) && Number.isInteger(characterIndex)
    ? asRecord(characters[characterIndex])
    : null;
  const data = asRecord(character?.data) ?? character;
  if (!data) return null;

  const boundBookNames: string[] = [];
  const primary = String(asRecord(data.extensions)?.world ?? '').trim();
  if (primary) boundBookNames.push(primary);

  const bookNames = readBoundBooks ? boundBookNames : [...new Set(selectedBooks)];
  const entries: WorldBookEntrySnapshot[] = [];
  const characterBook = asRecord(data.character_book);
  if (readBoundBooks && characterBook && Array.isArray(characterBook.entries)) {
    for (const raw of characterBook.entries) {
      const entry = asRecord(raw);
      if (!entry) continue;
      const book = primary || '角色卡内嵌条目';
      const id = resolveWorldBookEntryId(entry, entries.length, book);
      entries.push({
        id,
        legacyIds: resolveWorldBookEntryAliases(entry, entries.length, book, id),
        ...(readRuleActivation(entry) ? { activation: readRuleActivation(entry) } : {}),
        book,
        name: String(entry.comment ?? entry.name ?? '').trim() || `内嵌条目 ${entries.length + 1}`,
        content: String(entry.content ?? '').trim(),
        enabled: entry.enabled !== false && entry.disable !== true,
      });
    }
  }
  for (const bookName of bookNames) {
    entries.push(...await fetchWorldInfoEntries(bookName, context));
  }
  if (bookNames.length === 0 && entries.length === 0) return null;
  return buildWorldBookSnapshot('character', bookNames, entries, bookNames, entrySelections);
}

async function fetchWorldInfoEntries(
  name: string,
  context: SillyTavernContextShape,
): Promise<readonly WorldBookEntrySnapshot[]> {
  try {
    const response = await fetch('/api/worldinfo/get', {
      method: 'POST',
      headers: getSillyTavernRequestHeaders(context),
      credentials: 'include',
      body: JSON.stringify({ name }),
    });
    if (!response.ok) return [];
    const payload = asRecord(await response.json());
    const entriesRecord = asRecord(payload?.entries);
    if (!entriesRecord) return [];
    return Object.values(entriesRecord).flatMap((raw, index) => {
      const entry = asRecord(raw);
      if (!entry) return [];
      const keys = Array.isArray(entry.key) ? entry.key.map(String).join('、') : '';
      const id = resolveWorldBookEntryId(entry, index, name);
      return [{
        id,
        legacyIds: resolveWorldBookEntryAliases(entry, index, name, id),
        ...(readRuleActivation(entry) ? { activation: readRuleActivation(entry) } : {}),
        book: name,
        name: String(entry.comment ?? '').trim() || keys || `条目 ${entry.uid ?? ''}`.trim(),
        content: String(entry.content ?? '').trim(),
        enabled: entry.disable !== true,
      }];
    });
  } catch {
    return [];
  }
}

function buildWorldBookSnapshot(
  source: WorldBookSnapshot['source'],
  books: readonly string[],
  entries: readonly WorldBookEntrySnapshot[],
  catalog: readonly string[] = books,
  entrySelections: Readonly<Record<string, WorldBookEntrySelection>> = {},
): WorldBookSnapshot {
  const visibleEntries = [...entries];
  const activeEntries = selectWorldBookEntries(visibleEntries, entrySelections);
  const excerpt = activeEntries
    .filter((entry) => entry.content)
    .map((entry) => entry.content)
    .join('\n\n');
  return {
    available: visibleEntries.length > 0,
    source,
    catalog: [...new Set(catalog)],
    books: [...new Set(books)],
    activeEntryCount: activeEntries.length,
    entryCount: visibleEntries.length,
    activeEntries,
    names: activeEntries.map((entry) => entry.name).filter(Boolean),
    entries: visibleEntries,
    excerpt,
  };
}

export function selectWorldBookEntries(
  entries: readonly WorldBookEntrySnapshot[],
  selections: Readonly<Record<string, WorldBookEntrySelection>> = {},
): readonly WorldBookEntrySnapshot[] {
  return entries.filter((entry) => isWorldBookEntrySelected(entry, selections));
}

function isWorldBookEntrySelected(
  entry: WorldBookEntrySnapshot,
  selections: Readonly<Record<string, WorldBookEntrySelection>>,
): boolean {
  const selection = entry.book ? selections[entry.book] : undefined;
  if (!selection || selection.mode === 'enabled') return entry.enabled;
  const selectedIds = new Set(selection.entryIds.map(normalizeWorldBookEntryId));
  return [entry.id, ...(entry.legacyIds ?? [])]
    .map(normalizeWorldBookEntryId)
    .some((id) => selectedIds.has(id));
}

function resolveWorldBookEntryId(entry: Record<string, unknown>, index: number, book = 'context'): string {
  const candidate = entry.uid ?? entry.id ?? entry.key;
  const normalized = normalizeWorldBookEntryCandidate(candidate);
  const bookKey = book.trim() || 'context';
  return `entry:${bookKey}:${normalized || `index:${index}`}`;
}

function resolveWorldBookEntryAliases(
  entry: Record<string, unknown>,
  index: number,
  book: string,
  canonicalId: string,
): readonly string[] {
  const bookKey = book.trim() || 'context';
  const candidates = [entry.uid, entry.id, entry.key]
    .map(normalizeWorldBookEntryCandidate)
    .filter(Boolean);
  const aliases = new Set<string>();
  for (const candidate of candidates) {
    aliases.add(`entry:${bookKey}:${candidate}`);
    aliases.add(`entry:context:${candidate}`);
  }
  aliases.add(`entry:${bookKey}:index:${index}`);
  aliases.delete(canonicalId);
  return [...aliases];
}

function normalizeWorldBookEntryCandidate(value: unknown): string {
  return Array.isArray(value)
    ? value.map(String).join('|').trim()
    : String(value ?? '').trim();
}

function normalizeWorldBookEntryId(value: string): string {
  return value.trim();
}

function callHelperMethod(
  helper: Record<string, unknown>,
  methodName: string,
  args: readonly unknown[],
): unknown {
  const method = helper[methodName];
  if (typeof method !== 'function') return null;
  try {
    return (method as (...params: readonly unknown[]) => unknown).apply(helper, args as unknown[]);
  } catch {
    return null;
  }
}

const HOST_STORY_MEMORY_PROMPT_ID = 'narrative-phone-story-memory';

export async function setHostStoryMemoryPrompt(content: string): Promise<boolean> {
  const context = getSillyTavernContext();
  const host = getHostRecord();
  const setter = context.setExtensionPrompt
    ?? (typeof host.setExtensionPrompt === 'function' ? host.setExtensionPrompt as SillyTavernContextShape['setExtensionPrompt'] : undefined);
  if (setter) {
    try {
      await Promise.resolve(setter(
        HOST_STORY_MEMORY_PROMPT_ID,
        content,
        0,
        0,
        false,
        0,
        null,
      ));
      return true;
    } catch (error) {
      console.warn('[墨韵手机] 主聊天记忆提示词注入失败', error);
    }
  }

  const prompts = context.extensionPrompts
    ?? (host.extension_prompts as Record<string, unknown> | undefined)
    ?? (host.extensionPrompts as Record<string, unknown> | undefined);
  if (!prompts) return false;
  try {
    if (!content) {
      delete prompts[HOST_STORY_MEMORY_PROMPT_ID];
      return true;
    }
    prompts[HOST_STORY_MEMORY_PROMPT_ID] = {
      value: content,
      position: 0,
      depth: 0,
      scan: false,
      role: 0,
      filter: null,
    };
    return true;
  } catch (error) {
    console.warn('[墨韵手机] 主聊天记忆提示词槽不可写', error);
    return false;
  }
}

export async function clearHostStoryMemoryPrompt(): Promise<void> {
  await setHostStoryMemoryPrompt('');
}

/** 中止酒馆当前原生生成；用于发送前门控失败，防止继续产生 AI 楼层。 */
export function stopHostGeneration(): boolean {
  try {
    return getSillyTavernContext().stopGeneration?.() === true;
  } catch {
    return false;
  }
}

export function bindSillyTavernLifecycle(
  cleanup: CleanupStack,
  handlers: {
    readonly onChatChanged: (...args: unknown[]) => void | Promise<void>;
    readonly onMessageChanged?: (...args: unknown[]) => void | Promise<void>;
    readonly onMessageReceived?: (...args: unknown[]) => void | Promise<void>;
    readonly onMessageEdited?: (...args: unknown[]) => void | Promise<void>;
    readonly onMessageDeleted?: (...args: unknown[]) => void | Promise<void>;
    readonly onMessageSwiped?: (...args: unknown[]) => void | Promise<void>;
    readonly onUserMessageSent?: (...args: unknown[]) => void | Promise<void>;
    readonly onGenerationAfterCommands?: (...args: unknown[]) => void | Promise<void>;
    readonly onChatCompletionPromptReady?: (...args: unknown[]) => void | Promise<void>;
    readonly onGenerateAfterCombinePrompts?: (...args: unknown[]) => void | Promise<void>;
    readonly onGenerationEnded?: (...args: unknown[]) => void | Promise<void>;
    readonly onGenerationStopped?: (...args: unknown[]) => void | Promise<void>;
    readonly onPresetChanging?: (...args: unknown[]) => void | Promise<void>;
    readonly onPresetChanged?: (...args: unknown[]) => void | Promise<void>;
  },
): void {
  const context = getSillyTavernContext();
  const source = context.eventSource;
  const eventTypes = context.event_types;
  if (!source || !eventTypes) return;

  const subscriptions: Array<[string, (...args: unknown[]) => void | Promise<void>]> = [];
  const subscribe = (
    eventName: string | undefined,
    handler: (...args: unknown[]) => void | Promise<void>,
  ) => {
    if (!eventName) return;
    const listener = (...args: unknown[]) => Promise.resolve()
      .then(() => handler(...args))
      .catch((error: unknown) => {
        beginPhoneTask('hostEvent').fail(error);
        console.error(`[墨韵手机] SillyTavern 事件处理失败：${eventName}`, error);
      });
    source.on(eventName, listener);
    subscriptions.push([eventName, listener]);
  };

  subscribe(eventTypes.CHAT_CHANGED, handlers.onChatChanged);
  const messageReceivedHandler = handlers.onMessageReceived ?? handlers.onMessageChanged;
  const messageEditedHandler = handlers.onMessageEdited ?? handlers.onMessageChanged;
  if (messageReceivedHandler) subscribe(eventTypes.MESSAGE_RECEIVED, messageReceivedHandler);
  if (messageEditedHandler) subscribe(eventTypes.MESSAGE_EDITED, messageEditedHandler);
  if (handlers.onMessageDeleted && eventTypes.MESSAGE_DELETED) {
    subscribe(eventTypes.MESSAGE_DELETED, handlers.onMessageDeleted);
  }
  if (handlers.onMessageSwiped && eventTypes.MESSAGE_SWIPED) {
    subscribe(eventTypes.MESSAGE_SWIPED, handlers.onMessageSwiped);
  }
  if (handlers.onUserMessageSent && eventTypes.MESSAGE_SENT) {
    subscribe(eventTypes.MESSAGE_SENT, handlers.onUserMessageSent);
  }
  if (handlers.onGenerationAfterCommands && eventTypes.GENERATION_AFTER_COMMANDS) {
    subscribe(eventTypes.GENERATION_AFTER_COMMANDS, handlers.onGenerationAfterCommands);
  }
  if (handlers.onChatCompletionPromptReady && eventTypes.CHAT_COMPLETION_PROMPT_READY) {
    subscribe(eventTypes.CHAT_COMPLETION_PROMPT_READY, handlers.onChatCompletionPromptReady);
  }
  if (handlers.onGenerateAfterCombinePrompts && eventTypes.GENERATE_AFTER_COMBINE_PROMPTS) {
    subscribe(eventTypes.GENERATE_AFTER_COMBINE_PROMPTS, handlers.onGenerateAfterCombinePrompts);
  }
  if (handlers.onGenerationEnded && eventTypes.GENERATION_ENDED) {
    subscribe(eventTypes.GENERATION_ENDED, handlers.onGenerationEnded);
  }
  if (handlers.onGenerationStopped && eventTypes.GENERATION_STOPPED) {
    subscribe(eventTypes.GENERATION_STOPPED, handlers.onGenerationStopped);
  }
  if (handlers.onPresetChanging && eventTypes.OAI_PRESET_CHANGED_BEFORE) {
    subscribe(eventTypes.OAI_PRESET_CHANGED_BEFORE, handlers.onPresetChanging);
  }
  if (handlers.onPresetChanged && eventTypes.OAI_PRESET_CHANGED_AFTER) {
    subscribe(eventTypes.OAI_PRESET_CHANGED_AFTER, handlers.onPresetChanged);
  }

  cleanup.add(() => {
    for (const [eventName, listener] of subscriptions) {
      if (source.removeListener) source.removeListener(eventName, listener);
      else source.off?.(eventName, listener);
    }
  });
}

function getHostRecord(): Record<string, unknown> {
  try {
    const parent = window.parent as unknown as Record<string, unknown>;
    if (parent && (parent.SillyTavern || parent.TavernHelper || parent.AutoCardUpdaterAPI)) return parent;
  } catch {
    // Cross-origin parents are ignored; the extension can still use the current frame.
  }
  return window as unknown as Record<string, unknown>;
}

function asRecord(value: unknown): Record<string, unknown> | null {
  return value && typeof value === 'object' && !Array.isArray(value) ? value as Record<string, unknown> : null;
}

function normalizeTimestamp(value: unknown): number | null {
  if (value instanceof Date) return value.getTime();
  if (typeof value === 'number' && Number.isFinite(value)) return value < 1e12 ? value * 1000 : value;
  if (typeof value === 'string' && value.trim()) {
    const numeric = Number(value);
    if (Number.isFinite(numeric)) return numeric < 1e12 ? numeric * 1000 : numeric;
    const parsed = Date.parse(value.replace(' at ', ' '));
    return Number.isFinite(parsed) ? parsed : null;
  }
  return null;
}

function clampInteger(value: unknown, min: number, max: number, fallback: number): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.min(max, Math.max(min, Math.round(numeric))) : fallback;
}

function clampNumber(value: unknown, min: number, max: number, fallback: number): number {
  const numeric = Number(value);
  return Number.isFinite(numeric)
    ? Math.round(Math.min(max, Math.max(min, numeric)) * 100) / 100
    : fallback;
}

function normalizeGenerationProvider(
  value: unknown,
  fallback: PhoneExtensionSettings['generationProvider'] = DEFAULT_SETTINGS.generationProvider,
): PhoneExtensionSettings['generationProvider'] {
  return value === 'auto' || value === 'quietPrompt' || value === 'tavernHelper' ? value : fallback;
}

function normalizeStoragePreference(
  value: unknown,
  fallback: PhoneExtensionSettings['storagePreference'] = DEFAULT_SETTINGS.storagePreference,
): PhoneExtensionSettings['storagePreference'] {
  if (value === 'acu') return 'auto';
  return value === 'auto' || value === 'tavern' || value === 'indexeddb' ? value : fallback;
}

function normalizeOpenAiCompatibleApiConfig(
  value: unknown,
  fallback: OpenAiCompatibleApiConfig = DEFAULT_API_CONFIG,
): OpenAiCompatibleApiConfig {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  const profileName = String(
    ('profileName' in source ? source.profileName : fallback.profileName) ?? '',
  ).trim().slice(0, 40);
  return {
    enabled: source.enabled === true,
    ...(profileName ? { profileName } : {}),
    baseUrl: String(source.baseUrl ?? fallback.baseUrl).trim().replace(/\/+$/, '').slice(0, 500),
    apiKey: String(source.apiKey ?? fallback.apiKey).trim().slice(0, 500),
    model: String(source.model ?? fallback.model).trim().slice(0, 200),
    temperature: clampNumberOrNull(
      'temperature' in source ? source.temperature : fallback.temperature,
      0,
      2,
    ),
    maxTokens: clampIntegerOrNull(
      'maxTokens' in source ? source.maxTokens : fallback.maxTokens,
      16,
      131_072,
    ),
    maxContextTokens: clampIntegerOrNull(
      'maxContextTokens' in source ? source.maxContextTokens : fallback.maxContextTokens,
      1_024,
      4_000_000,
    ),
    retryCount: clampInteger(source.retryCount, 0, 10, fallback.retryCount ?? 3),
    stream: 'stream' in source ? source.stream !== false : fallback.stream !== false,
    maxTokenField: source.maxTokenField === 'max_completion_tokens' ? 'max_completion_tokens' : 'max_tokens',
    topP: clampNumber(source.topP, 0, 1, fallback.topP ?? 1),
    frequencyPenalty: clampNumber(source.frequencyPenalty, -2, 2, fallback.frequencyPenalty ?? 0),
    presencePenalty: clampNumber(source.presencePenalty, -2, 2, fallback.presencePenalty ?? 0),
  };
}

function normalizePersonalizationSettings(value: unknown): PersonalizationSettings {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  return {
    appColumns: clampInteger(source.appColumns, 3, 6, DEFAULT_PERSONALIZATION.appColumns),
    shellWidth: normalizeShellDimension(source.shellWidth, 280, 900),
    shellHeight: normalizeShellDimension(source.shellHeight, 460, 1_200),
    fontScale: clampInteger(source.fontScale, 80, 140, DEFAULT_PERSONALIZATION.fontScale),
    fontFamily: String(source.fontFamily ?? '').trim().slice(0, 200),
    // 截断 dataURL 会损坏图片，超限时直接丢弃。
    wallpaper: typeof source.wallpaper === 'string'
      && source.wallpaper.startsWith('data:image/')
      && source.wallpaper.length <= 2_000_000
      ? source.wallpaper
      : '',
    appIcons: normalizeAppIcons(source.appIcons),
    appLabels: normalizeAppLabels(source.appLabels),
    disabledAppIds: normalizeDisabledAppIds(source.disabledAppIds),
    themeColorsLight: normalizeThemeColorOverrides(source.themeColorsLight),
    themeColorsDark: normalizeThemeColorOverrides(source.themeColorsDark),
    themeColorsGlass: normalizeThemeColorOverrides(source.themeColorsGlass),
    themePresets: normalizeThemePresets(source.themePresets),
  };
}

/** 单个颜色槽位：仅接受 #rrggbb，其余一律回落 ''（跟随主题默认）。 */
function normalizeThemeColor(value: unknown): string {
  if (typeof value !== 'string') return '';
  const trimmed = value.trim().toLowerCase();
  return /^#[0-9a-f]{6}$/.test(trimmed) ? trimmed : '';
}

function normalizeThemeColorOverrides(value: unknown): ThemeColorOverrides {
  const source = value && typeof value === 'object' && !Array.isArray(value)
    ? value as Record<string, unknown>
    : {};
  return {
    accent: normalizeThemeColor(source.accent),
    accentDark: normalizeThemeColor(source.accentDark),
    canvas: normalizeThemeColor(source.canvas),
    surface: normalizeThemeColor(source.surface),
    textPrimary: normalizeThemeColor(source.textPrimary),
    textSecondary: normalizeThemeColor(source.textSecondary),
  };
}

function normalizeThemePresets(value: unknown): readonly ThemeColorPreset[] {
  if (!Array.isArray(value)) return [];
  const presets: ThemeColorPreset[] = [];
  for (const item of value.slice(0, 12)) {
    if (!item || typeof item !== 'object') continue;
    const record = item as Record<string, unknown>;
    const name = String(record.name ?? '').trim().slice(0, 30);
    if (!name || presets.some((preset) => preset.name === name)) continue;
    presets.push({
      name,
      light: normalizeThemeColorOverrides(record.light),
      dark: normalizeThemeColorOverrides(record.dark),
      glass: normalizeThemeColorOverrides(record.glass),
    });
  }
  return presets;
}

function normalizeAppLabels(value: unknown): Readonly<Record<string, string>> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const labels: Record<string, string> = {};
  for (const [key, label] of Object.entries(value as Record<string, unknown>)) {
    if (!/^[a-z][a-z0-9-]{0,31}$/i.test(key) || typeof label !== 'string') continue;
    const normalized = label.trim().slice(0, 40);
    if (normalized) labels[key] = normalized;
    if (Object.keys(labels).length >= 64) break;
  }
  return labels;
}

/** 自定义应用图标表：仅保留合法 dataURL，控制单图体积与条目数量。 */
function normalizeAppIcons(value: unknown): Readonly<Record<string, string>> {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return {};
  const icons: Record<string, string> = {};
  let count = 0;
  for (const [key, icon] of Object.entries(value as Record<string, unknown>)) {
    if (count >= 24) break;
    if (!/^[a-z][a-z0-9-]{0,31}$/i.test(key)) continue;
    if (typeof icon !== 'string' || !icon.startsWith('data:image/') || icon.length > 400_000) continue;
    icons[key] = icon;
    count += 1;
  }
  return icons;
}

function normalizeDisabledAppIds(value: unknown): readonly string[] {
  if (!Array.isArray(value)) return [];
  return [...new Set(value
    .map((item) => String(item ?? '').trim().slice(0, 64))
    .filter((item) => /^[a-z][a-z0-9-]{0,63}$/i.test(item)))].slice(0, 64);
}

/** 尺寸：0 = 使用默认；非 0 时夹在合理范围内。 */
function normalizeShellDimension(value: unknown, min: number, max: number): number {
  const numeric = Number(value);
  if (!Number.isFinite(numeric) || numeric <= 0) return 0;
  return Math.min(max, Math.max(min, Math.round(numeric)));
}

function normalizeSummaryThreshold(value: unknown, fallback: number): number {
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return fallback;
  if (numeric <= 0) return 0;
  return Math.min(100_000, Math.max(500, Math.round(numeric)));
}

export interface StoryFloorSnapshot {
  readonly floor: number;
  readonly name: string;
  readonly role: 'user' | 'ai';
  readonly text: string;
  /** 楼层内由手机注入的互动记录；与正文分开，避免正文清洗时丢失。 */
  readonly phoneText?: string;
}

/** 一批楼层的正文字数（含楼层内的手机互动记录）；截断值判定统一走这里。 */
export function measureFloorChars(floors: readonly StoryFloorSnapshot[]): number {
  return floors.reduce(
    (total, floor) => total + floor.text.trim().length + (floor.phoneText?.trim().length ?? 0),
    0,
  );
}

/** 从楼层原文中提取手机互动记录；详情块本身不是剧情正文。 */
function extractPhoneInteractionText(raw: string): string {
  const pattern = /<details\b[^>]*class\s*=\s*["'][^"']*narrative-phone-log[^"']*["'][^>]*>[\s\S]*?<\/details\s*>/gi;
  const sections: string[] = [];
  for (const match of raw.matchAll(pattern)) {
    const block = match[0]
      .replace(/<summary\b[^>]*>[\s\S]*?<\/summary\s*>/gi, ' ')
      .replace(/^\s*<details\b[^>]*>|<\/details\s*>\s*$/gi, ' ');
    const text = sanitizeStoryText(block);
    if (text) sections.push(text);
  }
  return [...new Set(sections)].join('\n\n');
}

function buildFloorSnapshot(
  index: number,
  message: Record<string, unknown>,
  text: string,
  raw: string,
): StoryFloorSnapshot {
  const phoneText = extractPhoneInteractionText(raw);
  return {
    floor: index,
    name: String(message.name ?? (message.is_user === true ? '用户' : '角色')),
    role: message.is_user === true ? 'user' : 'ai',
    text,
    ...(phoneText ? { phoneText } : {}),
  };
}

/** 读取正文最新 N 条楼层（去除本插件注入的互动记录块与 HTML 标签，不截断单层正文）。 */
export function getRecentStoryFloors(
  count: number,
  context = getSillyTavernContext(),
): readonly StoryFloorSnapshot[] {
  if (count <= 0) return [];
  const chat = Array.isArray(context.chat) ? context.chat : [];
  const floors: StoryFloorSnapshot[] = [];
  for (let index = chat.length - 1; index >= 0 && floors.length < count; index -= 1) {
    const message = chat[index] as Record<string, unknown> | undefined;
    if (!message || message.is_system === true) continue;
    const raw = String(message.mes ?? '');
    const text = sanitizeStoryText(raw);
    if (!text && !extractPhoneInteractionText(raw)) continue;
    floors.push(buildFloorSnapshot(index, message, text, raw));
  }
  return floors.reverse();
}

/**
 * 读取楼层号大于 afterFloor 的正文楼层（含用户与 AI），供记忆库整理摘要。
 * 默认不限制单层字数；调用方需要控制体积时自行传入 charLimit。
 */
export function getStoryFloorsSince(
  afterFloor: number,
  options: { readonly maxCount?: number; readonly charLimit?: number; readonly raw?: boolean } = {},
  context = getSillyTavernContext(),
): readonly StoryFloorSnapshot[] {
  const maxCount = options.maxCount ?? 40;
  const charLimit = options.charLimit ?? Number.POSITIVE_INFINITY;
  const chat = Array.isArray(context.chat) ? context.chat : [];
  const floors: StoryFloorSnapshot[] = [];
  for (let index = Math.max(0, afterFloor + 1); index < chat.length && floors.length < maxCount; index += 1) {
    const message = chat[index] as Record<string, unknown> | undefined;
    if (!message || message.is_system === true) continue;
    const raw = String(message.mes ?? '');
    const text = options.raw ? normalizeRawStoryText(raw, charLimit) : sanitizeStoryText(raw, charLimit);
    if (!text && !extractPhoneInteractionText(raw)) continue;
    floors.push(buildFloorSnapshot(index, message, text, raw));
  }
  return floors;
}

function normalizeRawStoryText(raw: string, charLimit: number): string {
  const text = raw.replace(/\r\n?/g, '\n').replace(/\u0000/g, '').trim();
  return Number.isFinite(charLimit) ? text.slice(0, Math.max(0, charLimit)) : text;
}

export function getLatestFloorIndex(context = getSillyTavernContext()): number {
  const chat = Array.isArray(context.chat) ? context.chat : [];
  return chat.length - 1;
}

/** 替换主聊天用户楼层内容；事件处理期间调用时可在原生生成前完成持久化。 */
export async function replaceStoryFloorText(
  floor: number,
  text: string,
  context = getSillyTavernContext(),
): Promise<boolean> {
  const chat = Array.isArray(context.chat) ? context.chat : [];
  const message = chat[floor] as Record<string, unknown> | undefined;
  if (!message || message.is_user !== true) return false;
  message.mes = text;
  try {
    context.updateMessageBlock?.(floor, message, { rerenderMessage: true });
  } catch {
    // 部分宿主版本只提供聊天存储，不提供即时消息重绘能力。
  }
  const save = getHostRecord().saveChatConditional;
  if (typeof save === 'function') {
    await Promise.resolve((save as () => void | Promise<void>)());
  }
  return true;
}

function clampNumberOrNull(value: unknown, min: number, max: number): number | null {
  if (value === null || value === undefined || value === '') return null;
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return null;
  return Math.round(Math.min(max, Math.max(min, numeric)) * 100) / 100;
}

function clampIntegerOrNull(value: unknown, min: number, max: number): number | null {
  if (value === null || value === undefined || value === '') return null;
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return null;
  return Math.min(max, Math.max(min, Math.round(numeric)));
}

function resolvePersonaManagerSnapshot(manager: Record<string, unknown> | null): UserPersonaSnapshot | null {
  if (!manager) return null;
  const active = pickPersonaRecord([
    callPersonaGetter(manager, ['getCurrent', 'getActive', 'getSelected', 'getActivePersona']),
    asRecord(manager.current),
    asRecord(manager.active),
    asRecord(manager.selected),
  ]);
  if (active) {
    return buildPersonaSnapshot(active, 'UserPersona manager');
  }
  const list = collectPersonaRecords(manager.personas ?? manager.items ?? manager.list);
  const activeId = pickString(manager, ['activePersonaId', 'active_persona', 'selectedPersonaId', 'currentPersonaId']);
  if (activeId) {
    const matched = list.find((item) => pickString(item, ['id', 'uid', 'name']) === activeId);
    if (matched) return buildPersonaSnapshot(matched, 'UserPersona manager.activePersonaId');
  }
  if (list.length === 1) {
    const only = list[0];
    if (only) return buildPersonaSnapshot(only, 'UserPersona manager.personas[0]');
  }
  return null;
}

function resolvePowerUserPersonaSnapshot(powerUser: Record<string, unknown> | null): UserPersonaSnapshot | null {
  if (!powerUser) return null;
  const personas = collectPersonaRecords(powerUser.personas ?? powerUser.persona_descriptions);
  if (personas.length === 0) return null;
  const activeIndex = clampInteger(
    powerUser.active_persona ?? powerUser.activePersona ?? powerUser.persona,
    0,
    Math.max(0, personas.length - 1),
    0,
  );
  const active = personas[activeIndex] ?? personas[0];
  if (!active) return null;
  return buildPersonaSnapshot(active, 'power_user.personas');
}

function resolveExtensionSettingsPersonaSnapshot(
  extensionSettings: Record<string, unknown> | undefined,
): UserPersonaSnapshot | null {
  if (!extensionSettings) return null;
  const personaSettings = asRecord(extensionSettings.persona)
    ?? asRecord(extensionSettings.personas)
    ?? asRecord(extensionSettings.user_persona);
  if (!personaSettings) return null;
  const active = pickPersonaRecord([
    asRecord(personaSettings.current),
    asRecord(personaSettings.active),
    callPersonaGetter(personaSettings, ['getCurrent', 'getActive']),
  ]);
  if (active) return buildPersonaSnapshot(active, 'extensionSettings.persona');
  const list = collectPersonaRecords(personaSettings.list ?? personaSettings.items ?? personaSettings.personas);
  const first = list[0];
  if (first) return buildPersonaSnapshot(first, 'extensionSettings.personas[0]');
  return buildPersonaSnapshot(personaSettings, 'extensionSettings.persona');
}

function resolveUserAvatarSnapshot(context: SillyTavernContextShape): UserPersonaSnapshot | null {
  const metadata = context.chatMetadata ?? {};
  const contextRecord = context as Record<string, unknown>;
  const candidates = [
    asRecord(contextRecord.user_avatar),
    asRecord(contextRecord.userAvatar),
    asRecord(metadata.user_avatar),
    asRecord(metadata.userAvatar),
  ];
  for (const candidate of candidates) {
    if (!candidate) continue;
    const snapshot = buildPersonaSnapshot(candidate, 'user_avatar');
    if (snapshot.description || snapshot.displayName !== '用户') return snapshot;
  }
  return null;
}

function buildPersonaSnapshot(record: Record<string, unknown>, source: string): UserPersonaSnapshot {
  const displayName = pickString(record, [
    'name',
    'displayName',
    'display_name',
    'title',
    'persona_name',
    'personaName',
    'avatar',
  ]);
  const description = pickString(record, [
    'description',
    'bio',
    'persona',
    'personality',
    'character_description',
    'characterDescription',
    'content',
    'text',
    'prompt',
  ]);
  return {
    displayName: displayName || '用户',
    description,
    source,
  };
}

function pickPersonaRecord(candidates: readonly unknown[]): Record<string, unknown> | null {
  for (const candidate of candidates) {
    const record = asRecord(candidate);
    if (record) return record;
  }
  return null;
}

function collectPersonaRecords(value: unknown): readonly Record<string, unknown>[] {
  if (Array.isArray(value)) {
    return value.filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === 'object' && !Array.isArray(item));
  }
  const record = asRecord(value);
  if (!record) return [];
  return Object.values(record).filter(
    (item): item is Record<string, unknown> => Boolean(item) && typeof item === 'object' && !Array.isArray(item),
  );
}

function callPersonaGetter(
  record: Record<string, unknown>,
  methodNames: readonly string[],
): Record<string, unknown> | null {
  for (const methodName of methodNames) {
    const method = record[methodName];
    if (typeof method !== 'function') continue;
    try {
      const result = (method as () => unknown).call(record);
      const resolved = asRecord(result);
      if (resolved) return resolved;
    } catch {
      // Ignore persona manager probe failures and continue with other sources.
    }
  }
  return null;
}

function pickString(record: Record<string, unknown>, keys: readonly string[]): string {
  for (const key of keys) {
    const value = String(record[key] ?? '').trim();
    if (value) return value;
  }
  return '';
}

function collectWorldBookEntries(value: unknown): readonly Record<string, unknown>[] {
  if (typeof value === 'string' && value.trim()) return [{ name: '世界书', content: value }];
  if (Array.isArray(value)) {
    return value.filter((item): item is Record<string, unknown> => Boolean(item) && typeof item === 'object' && !Array.isArray(item));
  }
  if (!value || typeof value !== 'object') return [];
  const record = value as Record<string, unknown>;
  for (const key of ['entries', 'data', 'worldInfo', 'world_info', 'worldBook', 'worldbook']) {
    const nested = collectWorldBookEntries(record[key]);
    if (nested.length > 0) return nested;
  }
  const values = Object.values(record).filter(
    (item): item is Record<string, unknown> => Boolean(item) && typeof item === 'object' && !Array.isArray(item),
  );
  return values.some((item) => cleanWorldBookContent(item)) ? values : [];
}

function cleanWorldBookName(entry: Record<string, unknown>, index: number): string {
  for (const value of [entry.comment, entry.name, entry.title, entry.key, entry.uid]) {
    const name = String(value ?? '').trim();
    if (name) return name.slice(0, 80);
  }
  return `条目 ${index + 1}`;
}

function cleanWorldBookContent(entry: Record<string, unknown>): string {
  for (const value of [entry.content, entry.text, entry.description, entry.value]) {
    const content = String(value ?? '').replace(/\u0000/g, '').trim();
    if (content) return content;
  }
  return '';
}
