import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import { formatError, truncate } from '../cell-format.js';
import type { DatabaseTableSnapshot } from '../../storage/database-api.js';
import { button, clear, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';

/** 设置是独立页面（点击右上角齿轮进入），列表状态在重渲染之间保留。 */
let databaseSettingsVisible = false;

type BrowserView =
  | { readonly mode: 'list' }
  | { readonly mode: 'detail'; readonly rowIndex: number };

export function createDatabaseApp(): PhoneAppDefinition {
  return {
    id: 'database',
    label: '数据库',
    icon: 'database',
    navigation: [],
    render: renderDatabaseApp,
  };
}

function renderDatabaseApp(context: PhoneViewContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-database-page' });
  const render = (): void => {
    clear(page);
    const inspection = context.database.inspect();
    if (databaseSettingsVisible) {
      page.append(backBar('数据库设置', () => {
        databaseSettingsVisible = false;
        render();
      }));
      page.append(renderStatusSection(context, inspection.reason));
      return;
    }
    page.append(renderTableBrowser(context, () => {
      databaseSettingsVisible = true;
      render();
    }));
  };
  render();
  return page;
}

/**
 * 表格浏览器：顶部左右箭头切换表，下方以记录卡片列表展示行数据，
 * 支持搜索、倒序、查看详情与刷新；外部表格只读。
 */
function renderTableBrowser(context: PhoneViewContext, onToggleSettings: () => void): HTMLElement {
  const section = element('section', { className: 'phone-db-browser' });

  const switcher = element('div', { className: 'phone-db-switcher' });
  const prevButton = button('', 'phone-icon-button phone-db-switch-button', () => switchTable(-1));
  prevButton.textContent = '‹';
  prevButton.setAttribute('aria-label', '上一张表');
  const nextButton = button('', 'phone-icon-button phone-db-switch-button', () => switchTable(1));
  nextButton.textContent = '›';
  nextButton.setAttribute('aria-label', '下一张表');
  const tableTitle = element('span', { className: 'phone-db-switch-title', text: '加载中…' });
  const settingsButton = button('', 'phone-icon-button phone-db-switch-button phone-db-settings-button', () => {
    settingsButton.classList.toggle('is-active');
    onToggleSettings();
  });
  settingsButton.append(renderPhoneIcon('settings', 'phone-db-settings-icon'));
  settingsButton.title = '只读连接状态';
  settingsButton.setAttribute('aria-label', '只读连接状态');
  if (databaseSettingsVisible) settingsButton.classList.add('is-active');
  switcher.append(prevButton, tableTitle, nextButton, settingsButton);

  const body = element('div', { className: 'phone-db-body' });
  body.append(element('p', { className: 'phone-settings-hint', text: '正在读取表格数据…' }));
  section.append(switcher, body);

  let tables: readonly DatabaseTableSnapshot[] = [];
  let activeSheetKey: string | null = null;
  let keyword = '';
  let reversed = false;
  let view: BrowserView = { mode: 'list' };

  const activeTable = (): DatabaseTableSnapshot | null =>
    tables.find((table) => table.sheetKey === activeSheetKey) ?? tables[0] ?? null;

  const switchTable = (offset: number) => {
    if (tables.length === 0) return;
    const currentIndex = Math.max(0, tables.findIndex((table) => table.sheetKey === activeSheetKey));
    const nextIndex = (currentIndex + offset + tables.length) % tables.length;
    activeSheetKey = tables[nextIndex]?.sheetKey ?? null;
    keyword = '';
    view = { mode: 'list' };
    renderBody();
  };

  const renderBody = () => {
    clear(body);
    const table = activeTable();
    if (!table) {
      tableTitle.textContent = '暂无表格';
      body.append(element('p', { className: 'phone-settings-hint', text: '当前聊天没有可显示的表格数据。' }));
      return;
    }
    activeSheetKey = table.sheetKey;
    const position = `${tables.findIndex((item) => item.sheetKey === table.sheetKey) + 1}/${tables.length}`;
    tableTitle.textContent = `${table.name} · ${position}`;
    if (view.mode === 'detail') renderDetail(table, view.rowIndex);
    else renderList(table);
  };

  const renderList = (table: DatabaseTableSnapshot) => {
    const toolbar = element('div', { className: 'phone-db-search-row' });
    const searchInput = element('input', {
      className: 'phone-input phone-db-search-input',
      attributes: { type: 'search', placeholder: '搜索标题、字段内容…' },
    });
    searchInput.value = keyword;
    searchInput.addEventListener('input', () => {
      keyword = searchInput.value.trim();
      renderCards();
    });
    const reverseButton = button(reversed ? '正序' : '倒序', 'phone-button phone-button-secondary phone-button-compact', () => {
      reversed = !reversed;
      renderBody();
    });
    toolbar.append(searchInput, reverseButton);

    const summary = element('p', { className: 'phone-db-count-hint' });
    const cardsBox = element('div', { className: 'phone-db-cards' });

    const renderCards = () => {
      const matched = matchRows(table, keyword);
      const ordered = reversed ? [...matched].reverse() : matched;
      summary.textContent = keyword
        ? `匹配 ${ordered.length}/${table.rows.length} 条记录 · 点击条目进入详情`
        : `共 ${table.rows.length} 条记录 · 点击条目查看详情（只读）`;
      clear(cardsBox);
      if (ordered.length === 0) {
        cardsBox.append(element('p', { className: 'phone-settings-hint', text: keyword ? '没有匹配的记录。' : '该表暂无数据。' }));
        return;
      }
      for (const rowIndex of ordered) {
        cardsBox.append(renderRowCard(table, rowIndex));
      }
    };

    const renderRowCard = (source: DatabaseTableSnapshot, rowIndex: number): HTMLElement => {
      const row = source.rows[rowIndex] ?? [];
      const nonEmpty = row.filter((cell) => cell.trim() !== '');
      const card = button('', 'phone-db-record-card', () => {
        view = { mode: 'detail', rowIndex };
        renderBody();
      });
      const head = element('div', { className: 'phone-db-record-head' });
      head.append(
        element('span', { className: 'phone-db-record-index', text: `#${rowIndex + 1}` }),
        element('strong', { className: 'phone-db-record-title', text: recordTitle(source.headers, row) }),
        element('span', { className: 'phone-db-record-badge', text: `${nonEmpty.length} 项` }),
      );
      const preview = element('p', { className: 'phone-db-record-preview', text: recordPreview(source.headers, row) });
      card.append(head, preview);
      return card;
    };

    const actions = element('div', { className: 'phone-db-bottom-actions' });
    actions.append(element('p', { className: 'phone-settings-hint', text: '仅查看外部数据库当前内容。表格写入请使用数据中心。' }));
    const refreshButton = button('刷新', 'phone-button phone-button-secondary', () => void load(true));
    actions.append(refreshButton);

    body.append(toolbar, summary, cardsBox, actions);
    renderCards();
  };

  const renderDetail = (table: DatabaseTableSnapshot, rowIndex: number) => {
    const row = table.rows[rowIndex];
    if (!row) {
      view = { mode: 'list' };
      renderBody();
      return;
    }
    body.append(backBar(`${table.name} · 第 ${rowIndex + 1} 条`, () => {
      view = { mode: 'list' };
      renderBody();
    }));

    const form = element('div', { className: 'phone-db-form' });
    table.headers.forEach((header, columnIndex) => {
      const value = row[columnIndex] ?? '';
      const field = element('label', { className: 'phone-db-field' });
      field.append(element('span', { className: 'phone-control-label', text: header || `列 ${columnIndex + 1}` }));
      const editor = element('textarea', { className: 'phone-textarea phone-db-field-input' });
      editor.value = value;
      editor.rows = value.length > 48 ? 3 : 1;
      editor.readOnly = true;
      editor.classList.add('is-readonly');
      field.append(editor);
      form.append(field);
    });
    body.append(form);
  };

  const load = async (notify = false) => {
    try {
      const snapshot = await context.database.snapshotTables();
      if (!snapshot.available) {
        tables = [];
        clear(body);
        tableTitle.textContent = '数据库';
        body.append(element('p', { className: 'phone-settings-hint', text: snapshot.reason }));
        return;
      }
      tables = snapshot.tables;
      if (!tables.some((table) => table.sheetKey === activeSheetKey)) {
        activeSheetKey = tables[0]?.sheetKey ?? null;
        view = { mode: 'list' };
      }
      if (view.mode === 'detail' && !(activeTable()?.rows[view.rowIndex])) {
        view = { mode: 'list' };
      }
      renderBody();
      if (notify) context.showNotice(snapshot.reason, 'success');
    } catch (error) {
      clear(body);
      body.append(element('p', { className: 'phone-settings-hint', text: `读取表格失败：${formatError(error)}` }));
    }
  };

  void load();
  return section;
}

function matchRows(table: DatabaseTableSnapshot, keyword: string): readonly number[] {
  const indexes = table.rows.map((_, index) => index);
  if (!keyword) return indexes;
  const lowered = keyword.toLowerCase();
  return indexes.filter((index) => {
    const row = table.rows[index] ?? [];
    return row.some((cell) => cell.toLowerCase().includes(lowered));
  });
}

/** row_id 是数据库内部序号列，不作为标题或预览内容。 */
function isRowIdColumn(header: string): boolean {
  return /^row_?id$/i.test(header.trim());
}

/** 标题取第一个非 row_id 的非空字段（例如角色名）。 */
function recordTitle(headers: readonly string[], row: readonly string[]): string {
  for (let index = 0; index < row.length; index += 1) {
    if (isRowIdColumn(headers[index] ?? '')) continue;
    const cell = (row[index] ?? '').trim();
    if (cell) return truncate(cell, 24);
  }
  return '（空记录）';
}

function recordPreview(headers: readonly string[], row: readonly string[]): string {
  const parts: string[] = [];
  let skippedTitle = false;
  for (let index = 0; index < row.length; index += 1) {
    if (isRowIdColumn(headers[index] ?? '')) continue;
    const cell = (row[index] ?? '').trim();
    if (!cell) continue;
    if (!skippedTitle) {
      skippedTitle = true;
      continue;
    }
    parts.push(cell);
    if (parts.join(' · ').length > 72) break;
  }
  return truncate(parts.join(' · '), 76) || '（无更多字段）';
}

function backBar(title: string, onBack: () => void): HTMLElement {
  const bar = element('div', { className: 'phone-db-back-bar' });
  bar.append(
    button('← 返回', 'phone-button phone-button-secondary phone-button-compact', onBack),
    element('strong', { className: 'phone-db-back-title', text: title }),
  );
  return bar;
}

function renderStatusSection(context: PhoneViewContext, reason: string): HTMLElement {
  const section = element('section', { className: 'phone-database-status' });
  section.append(
    element('h3', { className: 'phone-subsection-title', text: '连接状态' }),
    statusLine('外部数据库', reason),
    element('p', {
      className: 'phone-settings-hint',
      text: '此应用仅显示外部数据库的当前内容。表格编辑、脚本读写和正文 SQL 由插件内的数据中心处理，启用后生效。',
    }),
    button('打开数据中心', 'phone-button phone-button-primary', () => context.navigate('dataCenter')),
  );
  return section;
}

function statusLine(label: string, value: string): HTMLElement {
  const row = element('div', { className: 'phone-detail-line' });
  row.append(element('span', { text: label }), element('strong', { text: value }));
  return row;
}
