import type { PhoneViewContext } from '../app-types.js';
import { applyApiProfile } from '../../integration/sillytavern-bridge.js';
import { element } from '../../ui/dom.js';
import { settingsApiProfileRows, settingsSelectRow, settingsToggleRow } from '../shared-settings.js';

const TRACK_FREQUENCY_OPTIONS: readonly (readonly [string, string])[] = [
  ['1', '每条 AI 回复更新一次'],
  ['2', '每 2 条 AI 回复更新一次'],
  ['3', '每 3 条 AI 回复更新一次'],
  ['5', '每 5 条 AI 回复更新一次'],
];

const CHARACTER_LIMIT_OPTIONS: readonly (readonly [string, string])[] = [
  ['3', '最多 3 个人物锁'],
  ['4', '最多 4 个人物锁'],
  ['6', '最多 6 个人物锁'],
  ['8', '最多 8 个人物锁'],
  ['12', '最多 12 个人物锁'],
];

const FACT_LIMIT_OPTIONS: readonly (readonly [string, string])[] = [
  ['0', '不注入原著事实'],
  ['6', '最多 6 条'],
  ['12', '最多 12 条'],
  ['20', '最多 20 条'],
  ['30', '最多 30 条'],
];

const EXCERPT_LIMIT_OPTIONS: readonly (readonly [string, string])[] = [
  ['0', '不注入原文片段'],
  ['1', '最多 1 段'],
  ['2', '最多 2 段'],
  ['4', '最多 4 段'],
];

const BUDGET_OPTIONS: readonly (readonly [string, string])[] = [
  ['3000', '约 3000 字'],
  ['6000', '约 6000 字（默认）'],
  ['10000', '约 10000 字'],
  ['16000', '约 16000 字'],
];

/** 同人剧情设置：跟踪频率、注入预算与专用 API。 */
export function renderFanficSettings(context: PhoneViewContext): HTMLElement {
  const fanfic = context.fanfic;
  const settings = fanfic.settings;
  const view = element('div', { className: 'phone-fanfic-section' });
  const patch = (partial: Parameters<typeof fanfic.updateSettings>[0]) => {
    void fanfic.updateSettings(partial).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
  };

  view.append(
    settingsToggleRow(
      '自动跟踪剧情状态',
      '关闭后只能在「剧情」页手动更新；关闭不会影响已经记录的状态。',
      settings.autoTrack,
      (checked) => patch({ autoTrack: checked }),
    ),
    settingsSelectRow('跟踪频率', TRACK_FREQUENCY_OPTIONS, String(settings.trackEveryAiMessages), (value) => (
      patch({ trackEveryAiMessages: Number(value) || 1 })
    )),
    element('h3', { className: 'phone-feature-subtitle', text: '注入预算' }),
    element('p', {
      className: 'phone-settings-hint',
      text: '人物锁与本作剧情状态是强约束，始终注入；原著事实与原文片段按下面的预算裁剪，避免挤占上下文。',
    }),
    settingsSelectRow('人物锁数量', CHARACTER_LIMIT_OPTIONS, String(settings.characterLimit), (value) => (
      patch({ characterLimit: Number(value) || 6 })
    )),
    settingsSelectRow('原著事实条数', FACT_LIMIT_OPTIONS, String(settings.factLimit), (value) => (
      patch({ factLimit: Number(value) })
    )),
    settingsSelectRow('原文片段条数', EXCERPT_LIMIT_OPTIONS, String(settings.excerptLimit), (value) => (
      patch({ excerptLimit: Number(value) })
    )),
    settingsSelectRow('原著部分字符预算', BUDGET_OPTIONS, String(settings.charBudget), (value) => (
      patch({ charBudget: Number(value) || 6_000 })
    )),
    element('h3', { className: 'phone-feature-subtitle', text: '同人专用 API' }),
    element('p', {
      className: 'phone-settings-hint',
      text: '用于解析原著资料与跟踪剧情状态。留空时复用记忆库的「记忆整理 API」，不需要重复配置。',
    }),
  );

  for (const row of settingsApiProfileRows(fanfic.apiProfiles, settings.api, (profile) => {
    patch({ api: applyApiProfile(profile) });
  })) {
    view.append(row);
  }
  return view;
}