import type { PhoneState } from '../domain/model.js';

/**
 * 判断两份手机状态在“持久化语义”上是否一致。
 * 状态最终都会 JSON 序列化保存，因此值为 undefined 的键视同不存在：
 * IndexedDB（结构化克隆）会保留这类键，而 JSON 往返会丢弃它们，
 * 忽略这一差异才能让「本地状态 vs 数据库回读状态」的校验不误报。
 */
export function phoneStatesEqual(left: PhoneState, right: PhoneState): boolean {
  return deeplyEqual(left, right);
}

function definedKeys(record: Record<string, unknown>): string[] {
  return Object.keys(record).filter((key) => record[key] !== undefined).sort();
}

function deeplyEqual(left: unknown, right: unknown): boolean {
  if (Object.is(left, right)) return true;
  if (!left || !right || typeof left !== 'object' || typeof right !== 'object') return false;
  if (Array.isArray(left) || Array.isArray(right)) {
    return Array.isArray(left)
      && Array.isArray(right)
      && left.length === right.length
      && left.every((value, index) => deeplyEqual(value, right[index]));
  }

  const leftKeys = definedKeys(left as Record<string, unknown>);
  const rightKeys = definedKeys(right as Record<string, unknown>);
  return leftKeys.length === rightKeys.length
    && leftKeys.every((key, index) => key === rightKeys[index]
      && deeplyEqual((left as Record<string, unknown>)[key], (right as Record<string, unknown>)[key]));
}