import type { FanficTurnContext } from './context-compiler.js';
import type { CharacterLock, FanficNarrativeState } from './model.js';
import { hasFanficNarrativeContent } from './narrative.js';

export const FANFIC_PROMPT_OPEN_TAG = '<fanfic_context>';
export const FANFIC_PROMPT_CLOSE_TAG = '</fanfic_context>';

/** 同人剧情的冲突优先级：AU 剧情可以改命运，人物本身不能被写崩。 */
export const FANFIC_PRIORITY_RULES: readonly string[] = Object.freeze([
  '1. 最新正文楼层决定当前所在地点、时间与每个人此刻的动作，任何设定都不能推翻它。',
  '2. 【本作已发生】里的事件、关系与命运变化是本作既定事实，与原著冲突时以本作为准，禁止把角色写回原著旧状态。',
  '3. 【人物锁】里的核心人格、价值观底线与说话指纹保持原著一致；只有当本作剧情中存在可指认的渐进原因时才允许偏离，且必须写出这个过程。',
  '4. 每个角色只知道自己该知道的事：不在场、没人告知、不在知情名单里的信息一律不知道，禁止全知发言与跨场景泄密。',
  '5. 【原著事实】用于补足细节与语感，不得覆盖前四条；与本作既定事实冲突时直接放弃该条原著事实。',
  '6. 以上信息只用于内部思考：正文与消息里不得出现编号、标签名、字段名或“设定/记忆库/上下文”这类系统概念。',
]);

/** 注入正文链路的纯文本形式。 */
export function renderFanficContextPrompt(context: FanficTurnContext): string {
  const sections = [
    context.title ? `【作品】${context.title}` : '',
    renderCharacterSection(context.characters),
    renderNarrativeSection(context.narrative),
    renderFactSection(context),
    renderExcerptSection(context),
  ].filter((section) => section.trim().length > 0);
  if (sections.length === 0) return '';
  return [
    FANFIC_PROMPT_OPEN_TAG,
    '【同人剧情优先级】',
    ...FANFIC_PRIORITY_RULES,
    ...sections,
    FANFIC_PROMPT_CLOSE_TAG,
  ].join('\n\n');
}

function renderCharacterSection(characters: readonly CharacterLock[]): string {
  if (characters.length === 0) return '';
  const blocks = characters.map((character) => [
    `· ${character.name}${character.aliases.length > 0 ? `（又称：${character.aliases.join('、')}）` : ''}`,
    line('核心人格', character.core),
    line('价值观与底线', character.values),
    line('认知边界', character.knowledge),
    character.voice.register ? `  语体：${character.voice.register}` : '',
    line('说话习惯', character.voice.habits),
    line('绝不会说', character.voice.forbidden),
    line('关系基线', character.relationships.map((relationship) => `${relationship.targetName}：${relationship.summary}`)),
    line('原著台词参考', character.signatureLines),
  ].filter(Boolean).join('\n'));
  return ['【人物锁】', ...blocks].join('\n');
}

function renderNarrativeSection(narrative: FanficNarrativeState): string {
  if (!hasFanficNarrativeContent(narrative)) return '';
  const scene = narrative.scene;
  const rows = [
    scene.place || scene.time || scene.situation
      ? `  场景：${[scene.place, scene.time, scene.situation].filter(Boolean).join(' / ')}`
      : '',
    line('人物当前状态', narrative.presence.map(describePresence)),
    line('关系变化', narrative.relationshipShifts.map((shift) => shift.summary)),
    line('秘密与知情人', narrative.secrets.map((secret) => (
      `${secret.text}（知情：${secret.knownBy.length > 0 ? secret.knownBy.join('、') : '无人'}）`
    ))),
    line('未完成的约定', narrative.threads.filter((thread) => thread.kind === 'promise' && !thread.resolved).map((thread) => thread.text)),
    line('待解决的伏笔', narrative.threads.filter((thread) => thread.kind === 'open' && !thread.resolved).map((thread) => thread.text)),
    line('与原著的分歧', narrative.divergences.map((divergence) => (
      `原著「${divergence.canonText}」→ 本作「${divergence.storyText}」`
    ))),
  ].filter(Boolean);
  return rows.length > 0 ? ['【本作已发生】', ...rows].join('\n') : '';
}

function describePresence(presence: FanficNarrativeState['presence'][number]): string {
  const details = [presence.posture, presence.holding, presence.mood].filter(Boolean).join('，');
  const prefix = presence.present ? presence.name : `${presence.name}（不在场）`;
  return details ? `${prefix}：${details}` : prefix;
}

function renderFactSection(context: FanficTurnContext): string {
  if (context.facts.length === 0) return '';
  const rows = context.facts.map((fact) => (
    `  · ${fact.text}${fact.confidence === 'low' ? '（原著未明写，仅供参考）' : ''}`
  ));
  return ['【原著事实】', ...rows].join('\n');
}

function renderExcerptSection(context: FanficTurnContext): string {
  if (context.excerpts.length === 0) return '';
  const rows = context.excerpts.map((chunk) => (
    `  · ${chunk.heading ? `${chunk.heading}：` : ''}${chunk.text}`
  ));
  return ['【原著片段】', ...rows].join('\n');
}

/** 手机生成使用的结构化载荷：与正文注入同源，字段名保持稳定。 */
export function toFanficPromptPayload(context: FanficTurnContext): Readonly<Record<string, unknown>> {
  const narrative = context.narrative;
  return {
    title: context.title,
    priority: FANFIC_PRIORITY_RULES,
    characters: context.characters.map((character) => ({
      name: character.name,
      aliases: character.aliases,
      core: character.core,
      values: character.values,
      knowledge: character.knowledge,
      voice: character.voice,
      relationships: character.relationships.map((relationship) => ({
        target: relationship.targetName,
        summary: relationship.summary,
      })),
      signatureLines: character.signatureLines,
    })),
    story: {
      scene: narrative.scene,
      presence: narrative.presence,
      relationshipShifts: narrative.relationshipShifts.map((shift) => shift.summary),
      secrets: narrative.secrets.map((secret) => ({ text: secret.text, knownBy: secret.knownBy })),
      promises: narrative.threads.filter((thread) => thread.kind === 'promise' && !thread.resolved).map((thread) => thread.text),
      openThreads: narrative.threads.filter((thread) => thread.kind === 'open' && !thread.resolved).map((thread) => thread.text),
      divergences: narrative.divergences.map((divergence) => ({
        canon: divergence.canonText,
        story: divergence.storyText,
      })),
    },
    canonFacts: context.facts.map((fact) => ({ kind: fact.kind, text: fact.text, confidence: fact.confidence })),
  };
}

function line(label: string, values: readonly string[]): string {
  const usable = values.map((value) => value.trim()).filter(Boolean);
  return usable.length > 0 ? `  ${label}：${usable.join('；')}` : '';
}

export function removeFanficContext(content: string): string {
  return content
    .replace(new RegExp(`${FANFIC_PROMPT_OPEN_TAG}[\\s\\S]*?${FANFIC_PROMPT_CLOSE_TAG}`, 'gi'), '')
    .trimEnd();
}