import type { StoryFloorSnapshot } from './sillytavern-bridge.js';

export interface PhoneMemoryAttachment {
  readonly batchId: string;
  readonly targetFloor: number;
  readonly text: string;
}

/**
 * 把没有写回聊天楼层的预设槽位互动挂到实际服务的 User 楼层。
 * 楼层中已有同批次文本时不再追加，避免切换注入模式后重复整理。
 */
export function attachPresetPhoneInteractions(
  floors: readonly StoryFloorSnapshot[],
  attachments: readonly PhoneMemoryAttachment[],
): readonly StoryFloorSnapshot[] {
  if (floors.length === 0 || attachments.length === 0) return floors;
  const byFloor = new Map<number, string[]>();
  for (const attachment of attachments) {
    const text = normalizePhoneMemoryText(attachment.text);
    if (!text) continue;
    const current = byFloor.get(attachment.targetFloor) ?? [];
    if (!current.includes(text)) byFloor.set(attachment.targetFloor, [...current, text]);
  }
  if (byFloor.size === 0) return floors;
  return floors.map((floor) => {
    const existing = normalizePhoneMemoryText(floor.phoneText ?? '');
    const additions = (byFloor.get(floor.floor) ?? [])
      .filter((addition) => !phoneMemoryContains(existing, addition));
    if (additions.length === 0) return floor;
    const merged = [...new Set([existing, ...additions].filter(Boolean))].join('\n\n');
    return merged === existing ? floor : { ...floor, phoneText: merged };
  });
}

function phoneMemoryContains(existing: string, addition: string): boolean {
  if (!existing || existing.includes(addition)) return Boolean(existing);
  const existingLines = new Set(existing.split('\n').map((line) => line.trim()).filter(Boolean));
  const additionLines = addition.split('\n').map((line) => line.trim()).filter(Boolean);
  return additionLines.length > 0 && additionLines.every((line) => existingLines.has(line));
}

/** 去掉预设槽位的承载标签与模块说明，只保留可供记忆模型阅读的互动事实。 */
export function normalizePhoneMemoryText(raw: string): string {
  return raw
    .replace(/<\/?手机互动消息>/g, ' ')
    .replace(/^\s*手机互动模块\s*$/gim, ' ')
    .replace(/^\s*下方内容为正文外[^\n]*$/gim, ' ')
    .replace(/^\s*---\s*$/gm, ' ')
    .replace(/^\s*内容：\s*/i, '')
    .replace(/\r\n?/g, '\n')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}