import type { PhoneRoute } from '../app-types.js';
import type { ForumSort } from './projection.js';

/**
 * 论坛界面的临时状态：只影响这一次浏览，不进入领域数据。
 * 草稿与回复目标按主题 id 保存，整页重渲染（生成完成、状态刷新）后不会丢。
 */
interface ForumViewState {
  detailPostId: string | null;
  /** 详情页返回目标，记住是从首页、板块还是热榜点进来的。 */
  returnRoute: PhoneRoute;
  /** 当前板块筛选；null 表示全部话题。 */
  board: string | null;
  sort: ForumSort;
  readonly drafts: Map<string, string>;
  readonly replyTargets: Map<string, string>;
}

export const forumView: ForumViewState = {
  detailPostId: null,
  returnRoute: 'forum',
  board: null,
  sort: 'latest',
  drafts: new Map(),
  replyTargets: new Map(),
};

export function setForumDraft(threadId: string, content: string): void {
  if (content.trim()) forumView.drafts.set(threadId, content);
  else forumView.drafts.delete(threadId);
}

export function forumDraft(threadId: string): string {
  return forumView.drafts.get(threadId) ?? '';
}

export function setForumReplyTarget(threadId: string, targetId: string | null): void {
  if (targetId) forumView.replyTargets.set(threadId, targetId);
  else forumView.replyTargets.delete(threadId);
}

export function forumReplyTarget(threadId: string): string | null {
  return forumView.replyTargets.get(threadId) ?? null;
}