import { EXTENSION_MODULE_TEMPLATES, type ExtensionModuleTemplate } from '../extensions/module-templates.js';
import {
  EXTENSION_API_CATALOG,
  EXTENSION_HOST_API_VERSION,
  EXTENSION_OUTPUT_CONVENTIONS,
  EXTENSION_PROTOCOLS,
  type ExtensionApiCatalogEntry,
} from '../extensions/public-api.js';
import { button, element } from './dom.js';

export interface ExtensionDeveloperPanelContext {
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

const CONVENTION_LABELS: Readonly<Record<keyof typeof EXTENSION_OUTPUT_CONVENTIONS, string>> = {
  snapshots: '查询返回',
  writes: '写入返回',
  errors: '错误处理',
  timestamps: '时间戳',
  images: '图片与头像',
  scope: '作用域隔离',
  sensitiveData: '敏感数据',
};

const COMMON_ERRORS: readonly string[] = [
  '导入失败：文件必须是 .js/.mjs，manifest.entry 填 self，并默认导出工厂函数（或导出 createModule）。',
  '调用被拒绝：实体 ID 必须属于当前聊天作用域；写操作要 await 并捕获 Error。',
  '头像不生效：只接受 https 地址或 data:image/*；传空字符串或 null 表示清空。',
  '自动解析没写入：确认模块已启用、data 符合 autoParse.schema，且 apply 没有抛错。',
  '模块存储没进模型上下文：在 manifest.generationContext.includeStorage 里显式开启。',
];

export function renderExtensionDeveloperPanel(context: ExtensionDeveloperPanelContext): HTMLElement {
  const page = element('div', { className: 'phone-page phone-extension-guide' });
  const header = element('header', { className: 'phone-extension-guide-header' });
  header.append(
    element('span', { className: 'phone-kicker', text: 'DEVELOPER' }),
    element('h2', { className: 'phone-section-title', text: '插件开发者指南' }),
    element('p', {
      className: 'phone-settings-hint',
      text: `Host API v${EXTENSION_HOST_API_VERSION} · ${EXTENSION_API_CATALOG.length} 个公开方法。所有启用的模块默认获得完整能力，无需声明权限。`,
    }),
  );
  page.append(
    header,
    renderQuickStart(),
    renderTemplates(context),
    renderCatalog(),
    renderProtocols(),
    renderConventions(),
    renderCommonErrors(),
  );
  return page;
}

function guideBlock(title: string, open = false): HTMLDetailsElement {
  const block = element('details', {
    className: 'phone-extension-guide-block',
    ...(open ? { attributes: { open: '' } } : {}),
  });
  block.append(element('summary', { text: title }));
  return block;
}

function renderQuickStart(): HTMLElement {
  const block = guideBlock('5 分钟入门', true);
  const steps = element('ol', { className: 'phone-extension-guide-steps' });
  steps.append(
    element('li', { text: '下载下面任意模板，保存成 .js 文件。' }),
    element('li', { text: '回到「拓展应用」点击导入模块，选择该文件。' }),
    element('li', { text: '改掉 manifest 里的 id、name、author，id 只能用小写字母、数字、点、下划线和短横线。' }),
    element('li', { text: '在工厂函数里用传入的 api 读写手机数据，render 返回一个 HTMLElement。' }),
    element('li', { text: '需要清理定时器或订阅时实现 dispose；需要解析正文时实现 autoParse。' }),
  );
  block.append(
    element('p', { text: '模块是一个单文件 ES Module：导出 manifest，并默认导出接收 api 的工厂函数。' }),
    steps,
    element('p', {
      className: 'phone-extension-guide-note',
      text: '常用起点：api.state.snapshot() 读全量状态，api.wechat.getAvatar(profileId) 读微信头像，api.wechat.send(conversationId, content) 发消息，api.generation.reply({ messages }) 生成回复。',
    }),
  );
  return block;
}

function renderTemplates(context: ExtensionDeveloperPanelContext): HTMLElement {
  const block = guideBlock('可导入模板', true);
  for (const template of EXTENSION_MODULE_TEMPLATES) block.append(renderTemplateCard(context, template));
  return block;
}

function renderTemplateCard(context: ExtensionDeveloperPanelContext, template: ExtensionModuleTemplate): HTMLElement {
  const card = element('article', { className: 'phone-extension-template-card' });
  const copy = element('div', { className: 'phone-extension-template-copy' });
  copy.append(
    element('strong', { text: template.title }),
    element('small', { text: template.summary }),
  );
  const download = button('下载', 'phone-button phone-button-secondary phone-button-compact', () => {
    downloadTextFile(template.filename, template.source);
    context.showNotice(`已下载「${template.title}」模板。`, 'success');
  });
  const source = element('details', { className: 'phone-extension-template-source' });
  source.append(element('summary', { text: '查看源码' }), element('pre', { text: template.source }));
  card.append(copy, download, source);
  return card;
}

function renderCatalog(): HTMLElement {
  const block = guideBlock(`接口目录（${EXTENSION_API_CATALOG.length}）`, true);
  const search = element('input', {
    className: 'phone-input phone-extension-catalog-search',
    attributes: { type: 'search', placeholder: '搜索方法名、分组或用途，例如「头像」', 'aria-label': '搜索 Host API 接口' },
  });
  const list = element('div', { className: 'phone-extension-catalog-list' });
  const draw = (query: string): void => {
    const normalized = query.trim().toLocaleLowerCase('zh-CN');
    const entries = EXTENSION_API_CATALOG.filter((item) => matchesEntry(item, normalized));
    list.replaceChildren();
    if (entries.length === 0) {
      list.append(element('p', { className: 'phone-extension-guide-note', text: '没有匹配的接口。' }));
      return;
    }
    for (const [group, groupEntries] of groupEntriesByGroup(entries)) {
      const groupBlock = element('section', { className: 'phone-extension-catalog-group' });
      groupBlock.append(element('h3', { text: `${group}（${groupEntries.length}）` }));
      for (const item of groupEntries) groupBlock.append(renderCatalogEntry(item));
      list.append(groupBlock);
    }
  };
  search.addEventListener('input', () => draw(search.value));
  block.append(search, list);
  draw('');
  return block;
}

function groupEntriesByGroup(
  entries: readonly ExtensionApiCatalogEntry[],
): ReadonlyMap<string, readonly ExtensionApiCatalogEntry[]> {
  const groups = new Map<string, ExtensionApiCatalogEntry[]>();
  for (const item of entries) {
    const bucket = groups.get(item.group) ?? [];
    bucket.push(item);
    groups.set(item.group, bucket);
  }
  return groups;
}

function matchesEntry(item: ExtensionApiCatalogEntry, query: string): boolean {
  if (!query) return true;
  return [item.path, item.group, item.summary, item.parameters, item.returns, item.throws ?? '', item.example ?? '']
    .some((value) => value.toLocaleLowerCase('zh-CN').includes(query));
}

function renderCatalogEntry(item: ExtensionApiCatalogEntry): HTMLElement {
  const entry = element('article', { className: 'phone-extension-catalog-entry' });
  entry.append(
    element('code', { className: 'phone-extension-catalog-path', text: `api.${item.path}` }),
    element('p', { text: item.summary }),
    element('small', { text: `参数：${item.parameters}` }),
    element('small', { text: `返回：${item.returns}` }),
  );
  if (item.throws) entry.append(element('small', { className: 'phone-extension-catalog-throws', text: `抛错：${item.throws}` }));
  if (item.example) entry.append(element('code', { className: 'phone-extension-catalog-example', text: item.example }));
  return entry;
}

function renderProtocols(): HTMLElement {
  const block = guideBlock('模型输出协议');
  for (const protocol of EXTENSION_PROTOCOLS) {
    const card = element('article', { className: 'phone-extension-protocol-card' });
    card.append(
      element('strong', { text: `${protocol.id} · v${protocol.version}` }),
      element('p', { text: protocol.summary }),
      element('small', { text: `动作：${protocol.actionTypes.join('、')}` }),
      element('small', {
        text: `限制：${Object.entries(protocol.limits).map(([key, value]) => `${key}=${value}`).join('、')}`,
      }),
    );
    const flow = element('ul', { className: 'phone-extension-protocol-flow' });
    for (const step of [...protocol.processing, ...protocol.failureBehavior]) flow.append(element('li', { text: step }));
    card.append(flow);
    if (protocol.actions) {
      const actions = element('details', { className: 'phone-extension-protocol-actions' });
      actions.append(element('summary', { text: '逐动作字段' }));
      for (const action of protocol.actions) {
        actions.append(element('p', {
          text: `${action.type}｜必填 ${action.required.join('、')}｜可选 ${action.optional.length > 0 ? action.optional.join('、') : '无'}｜${action.constraints}`,
        }));
      }
      card.append(actions);
    }
    const schema = element('details', { className: 'phone-extension-protocol-schema' });
    schema.append(element('summary', { text: '完整 JSON Schema' }), element('pre', { text: JSON.stringify(protocol.schema, null, 2) }));
    card.append(schema);
    block.append(card);
  }
  return block;
}

function renderConventions(): HTMLElement {
  const block = guideBlock('输出规范');
  const list = element('ul', { className: 'phone-extension-conventions' });
  for (const [key, label] of Object.entries(CONVENTION_LABELS)) {
    const item = element('li');
    item.append(
      element('strong', { text: `${label}：` }),
      element('span', { text: EXTENSION_OUTPUT_CONVENTIONS[key as keyof typeof EXTENSION_OUTPUT_CONVENTIONS] }),
    );
    list.append(item);
  }
  block.append(list);
  return block;
}

function renderCommonErrors(): HTMLElement {
  const block = guideBlock('常见错误');
  const list = element('ul', { className: 'phone-extension-error-list' });
  for (const text of COMMON_ERRORS) list.append(element('li', { text }));
  block.append(list);
  return block;
}

function downloadTextFile(filename: string, text: string): void {
  const blob = new Blob([text], { type: 'text/javascript;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}
