import { showHostErrorNotice } from './host-notice.js';
import { beginPhoneTask } from './phone-task.js';
import { phoneLogger } from '../core/logger.js';

export function element<K extends keyof HTMLElementTagNameMap>(
  tag: K,
  options: {
    readonly className?: string;
    readonly text?: string;
    readonly attributes?: Readonly<Record<string, string>>;
  } = {},
): HTMLElementTagNameMap[K] {
  const node = document.createElement(tag);
  if (options.className) node.className = options.className;
  if (options.text !== undefined) node.textContent = options.text;
  for (const [name, value] of Object.entries(options.attributes ?? {})) {
    node.setAttribute(name, value);
  }
  return node;
}

export function button(
  label: string,
  className = 'phone-button',
  onClick?: () => void | Promise<void>,
): HTMLButtonElement {
  const node = element('button', { className, text: label, attributes: { type: 'button' } });
  if (onClick) {
    node.addEventListener('click', () => {
      void Promise.resolve()
        .then(onClick)
        .catch((error: unknown) => {
          // 未被具体界面处理的按钮错误也必须通知用户，并保留日志供排查。
          const message = error instanceof Error ? error.message : String(error ?? '未知错误');
          showHostErrorNotice(`墨韵手机：${message}`);
          phoneLogger.error(`按钮操作失败：${label || className}`, error);
        });
    });
  }
  return node;
}

export function clear(node: HTMLElement): void {
  node.replaceChildren();
}

/** 以 JSON 文件形式下载数据（备份导出与日志导出共用）。 */
export function downloadJsonFile(filename: string, value: unknown): void {
  const blob = new Blob([JSON.stringify(value, null, 2)], { type: 'application/json' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** 以纯文本文件形式下载内容（运行日志与提示词日志共用）。 */
export function downloadTextFile(filename: string, text: string): void {
  const blob = new Blob([text], { type: 'text/plain;charset=utf-8' });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** 以二进制文件形式下载数据（SQLite 数据库导出）。 */
export function downloadBinaryFile(filename: string, data: Uint8Array, mimeType: string): void {
  const buffer = new ArrayBuffer(data.byteLength);
  new Uint8Array(buffer).set(data);
  const url = URL.createObjectURL(new Blob([buffer], { type: mimeType }));
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = filename;
  anchor.click();
  window.setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** 让用户选择一个本地文件并读回文本内容；取消选择时返回 null。 */
export function pickTextFile(accept = 'application/json,.json'): Promise<{ readonly name: string; readonly text: string } | null> {
  return new Promise((resolve) => {
    const input = element('input', { attributes: { type: 'file', accept } });
    input.style.display = 'none';
    let settled = false;
    const finish = (value: { readonly name: string; readonly text: string } | null) => {
      if (settled) return;
      settled = true;
      input.remove();
      resolve(value);
    };
    input.addEventListener('change', () => {
      const file = input.files?.[0];
      if (!file) {
        finish(null);
        return;
      }
      void file.text().then((text) => finish({ name: file.name, text })).catch((error: unknown) => {
        beginPhoneTask('fileRead').fail(error);
        phoneLogger.error('读取备份文件失败', error);
        finish(null);
      });
    });
    // 用户直接关闭系统文件框时不会触发 change；焦点回到页面后收尾避免 Promise 永挂。
    window.addEventListener('focus', () => {
      window.setTimeout(() => {
        if (!input.files || input.files.length === 0) finish(null);
      }, 500);
    }, { once: true });
    document.body.append(input);
    input.click();
  });
}

export interface ModalField {
  readonly name: string;
  readonly label: string;
  readonly placeholder?: string;
  readonly type?: 'text' | 'number' | 'textarea' | 'select' | 'image';
  /** type = 'select' 时的选项列表：[值, 显示文本]。 */
  readonly options?: readonly (readonly [string, string])[];
  readonly required?: boolean;
  readonly value?: string;
  /** 根据当前表单值控制字段显示，例如只在选择“上传”时显示图片字段。 */
  readonly visibleWhen?: (values: Readonly<Record<string, string>>) => boolean;
  /** type = 'image' 时的预览、默认内容和选图回调。 */
  readonly imagePreview?: {
    readonly alt?: string;
    readonly hint?: string;
    readonly renderFallback?: () => Element;
    readonly onPick: () => Promise<string | null>;
  };
}

export function showModal(root: HTMLElement, title: string, fields: readonly ModalField[]): Promise<Record<string, string> | null> {
  return new Promise((resolve) => {
    const backdrop = element('div', { className: 'phone-modal-backdrop' });
    const dialog = element('form', { className: 'phone-modal', attributes: { role: 'dialog', 'aria-modal': 'true' } });
    dialog.append(element('h2', { className: 'phone-modal-title', text: title }));
    const controls = new Map<string, HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>();
    const imageValues = new Map<string, string>();
    const fieldRows = new Map<string, HTMLElement>();
    const readValues = (): Record<string, string> => {
      const values: Record<string, string> = {};
      for (const [name, control] of controls) values[name] = control.value.trim();
      for (const [name, value] of imageValues) values[name] = value;
      return values;
    };
    const updateVisibility = (): void => {
      const values = readValues();
      for (const field of fields) {
        const row = fieldRows.get(field.name);
        if (row && field.visibleWhen) row.hidden = !field.visibleWhen(values);
      }
    };
    for (const field of fields) {
      const label = element('label', { className: 'phone-modal-field' });
      label.append(element('span', { text: field.label }));
      fieldRows.set(field.name, label);

      if (field.type === 'image') {
        const previewButton = button('', 'phone-modal-image-picker');
        previewButton.setAttribute('aria-label', field.imagePreview?.alt ?? field.label);
        const preview = element('span', { className: 'phone-modal-image-preview' });
        const hint = element('small', { className: 'phone-modal-image-hint', text: field.imagePreview?.hint ?? '点击图标上传图片' });
        imageValues.set(field.name, field.value ?? '');
        const renderPreview = (source: string): void => {
          preview.replaceChildren();
          if (source) {
            preview.append(element('img', {
              className: 'phone-modal-image',
              attributes: { alt: field.imagePreview?.alt ?? field.label, src: source },
            }));
          } else if (field.imagePreview?.renderFallback) {
            preview.append(field.imagePreview.renderFallback());
          }
        };
        renderPreview(field.value ?? '');
        previewButton.append(preview, hint);
        previewButton.addEventListener('click', async (event) => {
          event.preventDefault();
          previewButton.disabled = true;
          try {
            const source = await field.imagePreview?.onPick();
            if (source) {
              imageValues.set(field.name, source);
              renderPreview(source);
            }
          } catch (error) {
            beginPhoneTask('imagePick').fail(error);
            phoneLogger.error('选择图片失败', error);
          } finally {
            previewButton.disabled = false;
          }
        });
        label.append(previewButton);
        dialog.append(label);
        continue;
      }

      let control: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement;
      if (field.type === 'select') {
        const select = element('select');
        for (const [optionValue, optionLabel] of field.options ?? []) {
          const option = element('option', { text: optionLabel, attributes: { value: optionValue } });
          option.selected = optionValue === field.value;
          select.append(option);
        }
        control = select;
      } else {
        control = field.type === 'textarea' ? element('textarea') : element('input');
        if (field.type && field.type !== 'textarea' && control instanceof HTMLInputElement) control.type = field.type;
        control.placeholder = field.placeholder ?? '';
        if (field.value !== undefined) control.value = field.value;
      }
      control.className = 'phone-modal-input';
      if (field.required && !(control instanceof HTMLSelectElement)) control.required = true;
      controls.set(field.name, control);
      label.append(control);
      control.addEventListener('change', updateVisibility);
      dialog.append(label);
    }
    updateVisibility();
    const actions = element('div', { className: 'phone-modal-actions' });
    const cancel = button('取消', 'phone-button phone-button-secondary');
    const submit = button('确定', 'phone-button phone-button-primary');
    actions.append(cancel, submit);
    dialog.append(actions);
    backdrop.append(dialog);
    root.append(backdrop);
    const finish = (value: Record<string, string> | null) => { backdrop.remove(); resolve(value); };
    dialog.addEventListener('submit', (event) => {
      event.preventDefault();
      finish(readValues());
    });
    cancel.addEventListener('click', (event) => { event.preventDefault(); finish(null); });
    submit.addEventListener('click', () => dialog.requestSubmit());
    window.setTimeout(() => controls.values().next().value?.focus(), 0);
  });
}

export interface ConfirmRequest {
  readonly title: string;
  /** 说明这次操作会做什么、是否可撤销。 */
  readonly message: string;
  /** 需要复核的具体内容（例如被删消息的正文），以引用块展示。 */
  readonly detail?: string;
  readonly confirmLabel?: string;
  readonly cancelLabel?: string;
  /** 破坏性操作用红色确认按钮。 */
  readonly danger?: boolean;
}

/** 不可逆操作前的确认弹窗：确认返回 true，取消或点击遮罩返回 false。 */
export function showConfirm(root: HTMLElement, request: ConfirmRequest): Promise<boolean> {
  return new Promise((resolve) => {
    const backdrop = element('div', { className: 'phone-modal-backdrop' });
    const dialog = element('div', {
      className: 'phone-modal phone-modal-confirm',
      attributes: { role: 'alertdialog', 'aria-modal': 'true' },
    });
    dialog.append(
      element('h2', { className: 'phone-modal-title', text: request.title }),
      element('p', { className: 'phone-modal-confirm-message', text: request.message }),
    );
    if (request.detail) {
      dialog.append(element('p', { className: 'phone-modal-confirm-detail', text: request.detail }));
    }
    const actions = element('div', { className: 'phone-modal-actions' });
    const cancel = button(request.cancelLabel ?? '取消', 'phone-button phone-button-secondary');
    const confirm = button(
      request.confirmLabel ?? '确认',
      `phone-button ${request.danger === false ? 'phone-button-primary' : 'phone-button-danger'}`,
    );
    actions.append(cancel, confirm);
    dialog.append(actions);
    backdrop.append(dialog);
    root.append(backdrop);

    let settled = false;
    const finish = (value: boolean): void => {
      if (settled) return;
      settled = true;
      backdrop.remove();
      resolve(value);
    };
    cancel.addEventListener('click', () => finish(false));
    confirm.addEventListener('click', () => finish(true));
    backdrop.addEventListener('pointerdown', (event) => {
      if (event.target === backdrop) finish(false);
    });
    dialog.addEventListener('keydown', (event) => {
      if (event.key === 'Escape') finish(false);
    });
    window.setTimeout(() => cancel.focus(), 0);
  });
}

export interface ContactOption {
  readonly id: string;
  readonly name: string;
  readonly detail?: string;
}

export function showContactPicker(
  root: HTMLElement,
  title: string,
  contacts: readonly ContactOption[],
  options: { readonly min?: number; readonly max?: number } = {},
): Promise<readonly string[] | null> {
  return new Promise((resolve) => {
    const min = options.min ?? 1;
    const max = options.max ?? Number.POSITIVE_INFINITY;
    const selected = new Set<string>();
    const backdrop = element('div', { className: 'phone-modal-backdrop' });
    const dialog = element('div', { className: 'phone-modal phone-contact-picker', attributes: { role: 'dialog', 'aria-modal': 'true' } });
    dialog.append(element('h2', { className: 'phone-modal-title', text: title }));
    const list = element('div', { className: 'phone-contact-picker-list' });
    const confirm = button('确定', 'phone-button phone-button-primary');
    confirm.disabled = true;
    const update = () => { confirm.disabled = selected.size < min; };
    for (const contact of contacts) {
      const row = button('', 'phone-contact-picker-item');
      const mark = element('span', { className: 'phone-contact-picker-check', text: '' });
      const copy = element('span', { className: 'phone-contact-picker-copy' });
      copy.append(element('strong', { text: contact.name }));
      if (contact.detail) copy.append(element('small', { text: contact.detail }));
      row.append(mark, copy);
      row.addEventListener('click', () => {
        if (selected.has(contact.id)) selected.delete(contact.id);
        else {
          if (selected.size >= max) return;
          selected.add(contact.id);
        }
        row.classList.toggle('is-selected', selected.has(contact.id));
        mark.textContent = selected.has(contact.id) ? '✓' : '';
        update();
      });
      list.append(row);
    }
    if (contacts.length === 0) {
      list.append(element('p', { className: 'phone-settings-hint', text: '通讯录为空，请先添加联系人。' }));
    }
    const actions = element('div', { className: 'phone-modal-actions' });
    const cancel = button('取消', 'phone-button phone-button-secondary');
    actions.append(cancel, confirm);
    dialog.append(list, actions);
    backdrop.append(dialog);
    root.append(backdrop);
    const finish = (value: readonly string[] | null) => { backdrop.remove(); resolve(value); };
    cancel.addEventListener('click', () => finish(null));
    confirm.addEventListener('click', () => finish([...selected]));
  });
}
