import {
  MEMORY_SOURCE_LABELS,
  memoryCoveredUntil,
  memoryLabelOf,
  memorySourceOf,
  type MemoryItem,
  type MemorySource,
} from '../../domain/model.js';
import { applyApiProfile } from '../../integration/sillytavern-bridge.js';
import type { StoryRecallMode } from '../../integration/sillytavern-bridge.js';
import {
  describeVectorRecallGap,
  findVectorRecallGap,
  type VectorRecallGap,
} from '../../integration/vector-recall-readiness.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import {
  settingsApiProfileRows,
  settingsNumberRow,
  settingsSegmentedRow,
  settingsSelectRow,
  settingsToggleRow,
} from '../shared-settings.js';

let memoryShowSettings = false;

type MemoryScopeFilter = 'all' | MemorySource;
/** 记忆库列表的来源筛选：全部 / 手机 / 记忆 / 总结。 */
let memoryScopeFilter: MemoryScopeFilter = 'all';

const MEMORY_FILTER_OPTIONS: readonly (readonly [MemoryScopeFilter, string])[] = [
  ['all', '全部'],
  ['phone', MEMORY_SOURCE_LABELS.phone],
  ['memory', MEMORY_SOURCE_LABELS.memory],
  ['summary', MEMORY_SOURCE_LABELS.summary],
];

/** 记忆库：把正文楼层整理成不丢细节的摘要，攒多后自动合并成总结；独立 API，不依赖数据库脚本。 */
export function createMemoryApp(): PhoneAppDefinition {
  return {
    id: 'memory',
    label: '记忆库',
    icon: '忆',
    navigation: [],
    render(context) {
      const page = element('div', { className: 'phone-page phone-memory' });
      const enabled = context.memoryBank.settings.enabled;
      page.append(renderHeader(context, enabled));
      if (!enabled || memoryShowSettings) page.append(renderSettings(context));
      else page.append(renderList(context));
      return page;
    },
  };
}

function renderHeader(context: PhoneViewContext, enabled: boolean): HTMLElement {
  const header = element('div', { className: 'phone-memory-header' });
  header.append(element('h2', { className: 'phone-section-title', text: context.appTitle('记忆库') }));
  const actions = element('div', { className: 'phone-memory-header-actions' });
  if (enabled) {
    actions.append(asyncActionButton(context, '整理楼层', '把还没有记忆的楼层立即整理', () => context.memoryBank.memorizeNow()));
    actions.append(asyncActionButton(context, '立即总结', '把未归档的记忆合并成一份总结', () => context.memoryBank.consolidateNow()));
    const gear = button('', 'phone-icon-button phone-memory-gear', () => {
      memoryShowSettings = !memoryShowSettings;
      context.navigate('memory');
    });
    gear.append(renderPhoneIcon('settings'));
    gear.setAttribute('aria-label', '记忆库设置');
    gear.classList.toggle('is-active', memoryShowSettings);
    actions.append(gear);
  }
  header.append(actions);
  return header;
}

function asyncActionButton(
  context: PhoneViewContext,
  label: string,
  title: string,
  action: () => Promise<{ readonly ok: boolean; readonly message: string }>,
): HTMLButtonElement {
  const trigger = button(label, 'phone-button phone-button-secondary phone-button-compact', async () => {
    trigger.disabled = true;
    trigger.textContent = '处理中…';
    try {
      const result = await action();
      context.showNotice(result.message, result.ok ? 'success' : 'error');
      if (result.ok) {
        memoryShowSettings = false;
        context.navigate('memory');
      }
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      trigger.disabled = false;
      trigger.textContent = label;
    }
  });
  trigger.title = title;
  return trigger;
}

/* ===== 记忆列表 ===== */

function renderList(context: PhoneViewContext): HTMLElement {
  const wrap = element('div', { className: 'phone-memory-list-wrap' });
  const items = context.state.memoryItems ?? [];
  const grouped = {
    memory: items.filter((item) => memorySourceOf(item) === 'memory'),
    summary: items.filter((item) => memorySourceOf(item) === 'summary'),
    phone: items.filter((item) => memorySourceOf(item) === 'phone'),
  };
  const active = grouped.memory.filter((item) => !item.archived);
  const lastFloor = context.state.memoryLastFloor ?? -1;

  const stats = element('p', { className: 'phone-memory-stats' });
  stats.textContent = lastFloor >= 0
    ? `已整理到第 ${lastFloor} 楼 · ${grouped.memory.length} 份记忆（${active.length} 份未归档）`
      + ` · ${grouped.summary.length} 份总结 · ${grouped.phone.length} 份手机总结`
    : '尚未建立整理基线（启用后从下一条 AI 回复开始记录）。';
  wrap.append(stats, renderScopeFilter(context, grouped));

  const visible = memoryScopeFilter === 'all' ? items : grouped[memoryScopeFilter];
  if (visible.length === 0) {
    wrap.append(renderEmptyState(context, items.length > 0));
    return wrap;
  }

  const list = element('div', { className: 'phone-memory-list' });
  for (const item of [...visible].reverse()) list.append(renderItem(context, item));
  wrap.append(list);
  return wrap;
}

function renderScopeFilter(
  context: PhoneViewContext,
  grouped: Readonly<Record<MemorySource, readonly MemoryItem[]>>,
): HTMLElement {
  const row = element('div', { className: 'phone-memory-filter', attributes: { role: 'tablist' } });
  for (const [value, label] of MEMORY_FILTER_OPTIONS) {
    const count = value === 'all'
      ? grouped.memory.length + grouped.summary.length + grouped.phone.length
      : grouped[value].length;
    const chip = button(`${label}${count > 0 ? ` ${count}` : ''}`, 'phone-memory-filter-chip', () => {
      memoryScopeFilter = value;
      context.navigate('memory');
    });
    chip.classList.toggle('is-active', memoryScopeFilter === value);
    chip.setAttribute('role', 'tab');
    chip.setAttribute('aria-selected', String(memoryScopeFilter === value));
    row.append(chip);
  }
  return row;
}

function renderEmptyState(context: PhoneViewContext, hasOtherItems: boolean): HTMLElement {
  const empty = element('div', { className: 'phone-empty phone-memory-empty' });
  if (hasOtherItems) {
    const label = MEMORY_FILTER_OPTIONS.find(([value]) => value === memoryScopeFilter)?.[1] ?? '该分类';
    empty.append(
      renderPhoneIcon('memory'),
      element('strong', { text: `没有${label}记录` }),
      element('span', { text: '切换到「全部」可以查看其他分类的记录。' }),
    );
    return empty;
  }
  empty.append(
    renderPhoneIcon('memory'),
    element('strong', { text: '记忆库还是空的' }),
    element('span', { text: `每 ${context.memoryBank.settings.everyAiMessages} 条 AI 回复会自动整理一份记忆；也可以点「整理楼层」手动整理已有正文。` }),
  );
  return empty;
}

function renderItem(context: PhoneViewContext, item: MemoryItem): HTMLElement {
  const source = memorySourceOf(item);
  const label = memoryLabelOf(item);
  const card = element('article', { className: `phone-memory-item is-${source}${item.archived ? ' is-archived' : ''}` });
  const head = element('div', { className: 'phone-memory-item-head' });
  head.append(
    element('span', { className: 'phone-memory-item-seq', text: label }),
    element('span', { className: 'phone-memory-item-kind', text: MEMORY_SOURCE_LABELS[source] }),
    element('span', {
      className: 'phone-memory-item-floors',
      text: source === 'phone'
        ? `手机内容 · 覆盖到 ${new Date(memoryCoveredUntil(item)).toLocaleString()}`
        : `楼层 ${item.floorFrom}-${item.floorTo}`,
    }),
  );
  if (item.archived) head.append(element('span', { className: 'phone-memory-item-archived', text: '已并入总结' }));
  if (source === 'summary' && item.sourceSeqs && item.sourceSeqs.length > 0) {
    head.append(element('span', {
      className: 'phone-memory-item-sources',
      text: `并入 #${item.sourceSeqs[0]}~#${item.sourceSeqs[item.sourceSeqs.length - 1]}`,
    }));
  }
  const itemActions = element('span', { className: 'phone-memory-item-actions' });
  if (source === 'memory') {
    const regenerate = button('', 'phone-icon-button phone-memory-item-action phone-memory-item-regenerate', async () => {
      if (!window.confirm(`确定按楼层 ${item.floorFrom}-${item.floorTo} 重新生成 ${label} 吗？`)) return;
      regenerate.disabled = true;
      try {
        const result = await context.memoryBank.regenerateItem(item.id);
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) context.navigate('memory');
      } finally {
        regenerate.disabled = false;
      }
    });
    regenerate.append(renderPhoneIcon('refresh', 'phone-svg-icon'));
    regenerate.setAttribute('aria-label', `重新生成${label}`);
    regenerate.title = '按原楼层重新生成记忆';
    itemActions.append(regenerate);
  }
  const edit = button('', 'phone-icon-button phone-memory-item-action phone-memory-item-edit', async () => {
    const values = await context.showModal(`编辑${label}`, [{
      name: 'content',
      label: `${MEMORY_SOURCE_LABELS[source]}内容`,
      type: 'textarea',
      required: true,
      value: item.content,
    }]);
    const content = values?.content?.trim();
    if (!content) return;
    const result = await context.memoryBank.updateItemContent(item.id, content);
    context.showNotice(result.message, result.ok ? 'success' : 'error');
    if (result.ok) context.navigate('memory');
  });
  edit.append(renderPhoneIcon('edit', 'phone-svg-icon'));
  edit.setAttribute('aria-label', `编辑${label}`);
  edit.title = '编辑记录内容';
  const remove = button('', 'phone-icon-button phone-memory-item-action phone-memory-item-delete', async () => {
    if (!window.confirm(`确定删除 ${label} 吗？`)) return;
    try {
      await context.commands.removeMemoryItem(item.id);
      context.showNotice(`${label} 已删除。`, 'info');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
  });
  remove.append(renderPhoneIcon('trash', 'phone-svg-icon'));
  remove.setAttribute('aria-label', `删除${label}`);
  itemActions.append(edit, remove);
  head.append(itemActions);
  card.append(head);

  const details = element('details', { className: 'phone-memory-item-body' });
  const preview = item.content.replace(/\s+/g, ' ').slice(0, 46);
  details.append(
    element('summary', { text: `${preview}${item.content.length > 46 ? '…' : ''}` }),
    element('p', { className: 'phone-memory-item-content', text: item.content }),
  );
  card.append(details);
  return card;
}

/* ===== 设置视图 ===== */

function renderSettings(context: PhoneViewContext): HTMLElement {
  const settings = context.memoryBank.settings;
  const panel = element('div', { className: 'phone-memory-settings' });

  if (!settings.enabled) {
    const intro = element('div', { className: 'phone-feature-intro' });
    intro.append(
      renderPhoneIcon('memory'),
      element('strong', { text: '启用记忆库' }),
      element('p', { text: '启用后，每当 AI 回复正文，系统会用下方的专用 API 把该楼层梳理成一份可读且不丢细节的记忆；记忆攒多后自动整理成总结。长对话中记忆不再随上下文丢失，也可以随时手动整理或总结。' }),
      element('p', { className: 'phone-feature-intro-note', text: '记忆库按来源分为三类：正文楼层「记忆#N」、多条记忆合并的「总结#N」、手机内容的「手机#N」，可在列表顶部切换查看。数据保存在本扩展内，不与数据库脚本同步。' }),
    );
    panel.append(intro);
  }

  panel.append(settingsToggleRow(
    '启用记忆库',
    'AI 回复后自动整理楼层记忆；关闭后已有记忆仍保留。',
    settings.enabled,
    (checked) => {
      if (checked) memoryShowSettings = true;
      void context.memoryBank.updateSettings({ enabled: checked }).catch((error: unknown) => {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      });
    },
  ));

  // 召回方式紧跟启用开关：先决定「本轮怎么选记忆」，再往下调整整理节奏。
  panel.append(renderRecallModeRow(context));

  panel.append(settingsSelectRow(
    '记忆频率',
    [['1', '每条 AI 回复一份'], ['2', '每 2 条 AI 回复一份'], ['3', '每 3 条 AI 回复一份'], ['5', '每 5 条 AI 回复一份'], ['10', '每 10 条 AI 回复一份']],
    String(settings.everyAiMessages),
    (value) => void context.memoryBank.updateSettings({ everyAiMessages: Number(value) || 1 }),
  ));
  panel.append(settingsNumberRow(
    '正文截断值（字）',
    settings.minContentChars,
    0,
    20_000,
    50,
    (value) => void context.memoryBank.updateSettings({ minContentChars: value ?? 0 }),
  ));
  panel.append(element('p', {
    className: 'phone-settings-hint',
    text: `攒够记忆频率后还要正文达到该字数才会调用整理模型；不足时这批楼层不消耗额度，会累积到下一轮一起整理。0 = 不限制，当前 ${settings.minContentChars} 字。手动点「整理楼层」不受此限制。`,
  }));
  panel.append(settingsToggleRow(
    '本层不整理记忆',
    '启用后，最新 AI 楼层会等到下一条 AI 回复出现后再整理，方便重生成当前楼层时节省 API 额度。',
    settings.deferCurrentFloor,
    (checked) => void context.memoryBank.updateSettings({ deferCurrentFloor: checked }),
  ));
  panel.append(settingsSelectRow(
    '自动总结阈值',
    [['0', '关闭自动总结'], ['5', '攒满 5 份记忆'], ['10', '攒满 10 份记忆'], ['15', '攒满 15 份记忆'], ['20', '攒满 20 份记忆'], ['30', '攒满 30 份记忆']],
    String(settings.consolidateEvery),
    (value) => void context.memoryBank.updateSettings({ consolidateEvery: Number(value) || 0 }),
  ));

  panel.append(renderStoryMemoryInjectionSettings(context));

  panel.append(element('h3', { className: 'phone-feature-subtitle', text: '记忆库专用 API' }));
  panel.append(element('p', {
    className: 'phone-settings-hint',
    text: '记忆召回负责生成前分析剧情并选择记忆；记忆整理负责生成楼层摘要与合并总结，两者可分别使用不同配置。',
  }));
  panel.append(element('h4', { className: 'phone-subsection-title', text: '记忆召回 API' }));
  for (const row of settingsApiProfileRows(context.memoryBank.apiProfiles, settings.recallApi, (profile) => {
    void context.memoryBank.updateSettings({ recallApi: applyApiProfile(profile) }).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
  })) {
    panel.append(row);
  }
  panel.append(element('h4', { className: 'phone-subsection-title', text: '记忆整理 API' }));
  for (const row of settingsApiProfileRows(context.memoryBank.apiProfiles, settings.organizeApi, (profile) => {
    void context.memoryBank.updateSettings({ organizeApi: applyApiProfile(profile) }).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
  })) {
    panel.append(row);
  }

  if (settings.enabled) {
    const back = button('查看记忆', 'phone-button phone-button-primary', () => {
      memoryShowSettings = false;
      context.navigate('memory');
    });
    const actionRow = element('div', { className: 'phone-feature-settings-actions' });
    actionRow.append(back);
    panel.append(actionRow);
  }
  return panel;
}

/* ===== 召回方式 ===== */

/** 向量召回缺什么（null = 可用）；判定与运行时召回共用同一份规则。 */
function vectorRecallGapOf(context: PhoneViewContext): VectorRecallGap | null {
  return findVectorRecallGap({
    vector: context.vector.settings,
    vectorAppDisabled: context.vector.appDisabled,
  });
}

/** 当前召回方式的效果说明。 */
function describeRecallMode(context: PhoneViewContext): string {
  const vector = context.vector.settings;
  if (context.memoryBank.settings.recallMode === 'memory') {
    return '记忆召回：每轮生成前调用「记忆召回 API」读最近剧情，由模型挑出要注入的记忆编号。';
  }
  const rerank = vector.rerankEnabled && vector.rerank.model.trim()
    ? `先用「${vector.rerank.model}」精排再取前 ${vector.topK} 条`
    : `按相似度取前 ${vector.topK} 条`;
  return `向量召回：把记忆 / 总结 / 手机总结向量化建索引，每轮生成前${rerank}注入，不消耗召回模型额度。`;
}

/**
 * 召回方式：滑动在「记忆召回」与「向量召回」之间二选一。
 *
 * 两条路径产出的都是「注入哪些记忆编号」，最终共用同一套注入装配与预算，
 * 因此这里只需要一个互斥选择，不做多选叠加。
 */
function renderRecallModeRow(context: PhoneViewContext): HTMLElement {
  const section = element('div', { className: 'phone-memory-recall' });
  const gap = vectorRecallGapOf(context);
  section.append(settingsSegmentedRow<StoryRecallMode>(
    '本轮召回方式',
    [
      { value: 'memory', label: '记忆召回' },
      { value: 'vector', label: '向量召回' },
    ],
    context.memoryBank.settings.recallMode,
    (recallMode) => {
      // 未就绪也照用户意图保存选择，但立刻说明缺什么，避免生成时静默不注入。
      if (recallMode === 'vector' && gap) context.showNotice(describeVectorRecallGap(gap), 'error');
      void context.memoryBank.updateSettings({ recallMode }).catch((error: unknown) => {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      });
    },
  ));
  section.append(context.memoryBank.settings.recallMode === 'vector' && gap
    ? element('p', { className: 'phone-memory-recall-warning', text: describeVectorRecallGap(gap) })
    : element('p', { className: 'phone-settings-hint', text: describeRecallMode(context) }));
  return section;
}

function renderStoryMemoryInjectionSettings(context: PhoneViewContext): HTMLElement {
  const memory = context.memoryBank.settings;
  const snapshot = context.memoryBank.presetPromptSlots;
  const section = element('div', { className: 'phone-api-slot' });
  section.append(
    element('h3', { className: 'phone-subsection-title', text: '主聊天记忆注入位置' }),
    element('p', {
      className: 'phone-settings-hint',
      text: '默认方式保持现有兼容注入；指定预设槽位会在每轮生成前临时占用所选条目，并在生成结束、停止、切聊天或切预设时恢复原内容。',
    }),
    settingsSelectRow(
      '注入方式',
      [
        ['extension', '兼容注入（现有方式，推荐默认）'],
        ['preset', '指定当前预设提示词槽位（实验）'],
      ],
      memory.injectionMode,
      (value) => void context.memoryBank.updateSettings({
        injectionMode: value === 'preset' ? 'preset' : 'extension',
      }),
    ),
  );

  if (memory.injectionMode !== 'preset') return section;

  const selected = snapshot.slots.find((slot) => slot.id === memory.presetPromptId);
  const slotOptions: (readonly [string, string])[] = [
    ['', snapshot.available ? '— 选择当前预设中的普通提示词 —' : '— 预设提示词不可用 —'],
    ...(!selected && memory.presetPromptId
      ? [[memory.presetPromptId, `已失效的槽位 · ${memory.presetPromptId}`] as const]
      : []),
    ...snapshot.slots.map((slot) => {
      const position = slot.position === 'in_chat' ? `聊天内 depth ${slot.depth ?? 0}` : `相对位置 #${slot.index + 1}`;
      const content = slot.contentLength > 0 ? `${slot.contentLength} 字` : '空槽';
      const state = slot.enabled ? '启用' : '停用';
      return [slot.id, `${slot.name} · ${slot.role} · ${position} · ${content} · ${state}`] as const;
    }),
  ];
  section.append(
    element('p', {
      className: 'phone-settings-hint',
      text: snapshot.available ? `${snapshot.presetName} · ${snapshot.slots.length} 个可选槽位` : snapshot.reason,
    }),
    settingsSelectRow('目标提示词槽位', slotOptions, memory.presetPromptId, (value) => void context.memoryBank.updateSettings({
      presetPromptId: value,
    })),
    settingsSelectRow(
      '注入角色',
      [
        ['', '沿用目标槽位角色'],
        ['system', 'system'],
        ['user', 'user'],
        ['assistant', 'assistant（仅了解预填充语义时使用）'],
      ],
      memory.presetPromptRole,
      (value) => void context.memoryBank.updateSettings({
        presetPromptRole: value as typeof memory.presetPromptRole,
      }),
    ),
  );

  if (selected) {
    section.append(element('p', {
      className: 'phone-settings-hint',
      text: selected.contentLength > 0
        ? `所选条目当前已有 ${selected.contentLength} 字内容；插件会在生成期间临时替换并在结束后完整恢复。异常退出前请避免手动编辑同一条目。`
        : '所选条目当前为空；插件仍会保存并恢复其启用状态、角色、位置和完整内容。',
    }));
  }

  const actions = element('div', { className: 'phone-settings-inline-actions' });
  const refresh = button('刷新预设槽位', 'phone-button phone-button-secondary phone-button-compact', async () => {
    refresh.disabled = true;
    try {
      await context.memoryBank.refreshPresetPromptSlots();
      context.showNotice('已重新读取当前预设提示词槽位。', 'success');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    } finally {
      refresh.disabled = false;
    }
  });
  actions.append(refresh);
  section.append(actions);
  return section;
}
