import {
  ensurePhoneStateShape,
  PHONE_BACKUP_PROTOCOL_VERSION,
  PHONE_SCHEMA_VERSION,
  type PhoneBackupDocument,
  type PhoneBackupImportPreview,
  type PhoneBackupSettingsSnapshot,
  type PhoneBackupStatistics,
  type PhoneState,
} from '../domain/model.js';

/** 备份解析失败：文案直接展示给用户，不泄漏原始对象。 */
export class PhoneBackupFormatError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'PhoneBackupFormatError';
  }
}

export interface PhoneBackupPreview extends PhoneBackupImportPreview {
  /** 校验和与内容不一致：文件可能被手工编辑过，仍允许用户确认后导入。 */
  readonly checksumValid: boolean;
}

export interface PhoneBackupParseResult {
  readonly document: PhoneBackupDocument;
  readonly preview: PhoneBackupPreview;
}

const BACKUP_FORMAT = 'sjichajian.phone-backup';
/** 备份里不保留的派生缓存字段：向量索引与图片二进制由本地重建。 */
const SENSITIVE_KEY_PATTERN = /^(apiKey|token|secret|password)$/i;

export function createPhoneBackup(input: {
  readonly state: PhoneState;
  readonly settings: Readonly<Record<string, unknown>>;
  readonly includeApiKeys?: boolean;
  readonly exportedAt?: number;
}): PhoneBackupDocument {
  const state = ensurePhoneStateShape(input.state);
  const includesApiKeys = input.includeApiKeys === true;
  const settings = sanitizeSettings(input.settings, includesApiKeys);
  const statistics = collectStatistics(state);
  return {
    format: BACKUP_FORMAT,
    protocolVersion: PHONE_BACKUP_PROTOCOL_VERSION,
    schemaVersion: state.schemaVersion,
    sourceScopeId: state.scopeId,
    exportedAt: input.exportedAt ?? Date.now(),
    includesApiKeys,
    settings,
    state,
    statistics,
    checksum: checksumOf(state, settings),
  };
}

/**
 * 解析并校验备份 JSON。
 * 结构非法直接抛错；旧协议版本走迁移；作用域不一致由调用方二次确认，不静默改写。
 */
export function parsePhoneBackup(raw: unknown, targetScopeId: string): PhoneBackupParseResult {
  const source = typeof raw === 'string' ? parseJson(raw) : raw;
  if (!isPlainObject(source)) throw new PhoneBackupFormatError('备份文件不是有效的 JSON 对象。');
  if (source.format !== BACKUP_FORMAT) {
    throw new PhoneBackupFormatError('这不是墨韵手机的备份文件（缺少 sjichajian.phone-backup 标记）。');
  }
  const protocolVersion = asInteger(source.protocolVersion);
  if (protocolVersion === null || protocolVersion < 1) {
    throw new PhoneBackupFormatError('备份文件缺少可识别的协议版本。');
  }
  if (protocolVersion > PHONE_BACKUP_PROTOCOL_VERSION) {
    throw new PhoneBackupFormatError(
      `备份来自更高版本（协议 v${protocolVersion}），当前扩展只支持到 v${PHONE_BACKUP_PROTOCOL_VERSION}，请先升级扩展。`,
    );
  }
  if (!isPlainObject(source.state)) throw new PhoneBackupFormatError('备份文件缺少手机状态数据。');

  const state = normalizeBackupState(source.state);
  const sourceScopeId = typeof source.sourceScopeId === 'string' && source.sourceScopeId.trim()
    ? source.sourceScopeId.trim()
    : state.scopeId;
  const settings = isPlainObject(source.settings) ? sanitizeSettings(source.settings, true) : {};
  const statistics = collectStatistics(state);
  const includesApiKeys = source.includesApiKeys === true;
  const exportedAt = asInteger(source.exportedAt) ?? 0;
  const checksum = typeof source.checksum === 'string' ? source.checksum : '';
  const document: PhoneBackupDocument = {
    format: BACKUP_FORMAT,
    protocolVersion,
    schemaVersion: state.schemaVersion,
    sourceScopeId,
    exportedAt,
    includesApiKeys,
    settings,
    state,
    statistics,
    checksum,
  };
  return {
    document,
    preview: {
      sourceScopeId,
      targetScopeId,
      requiresScopeConfirmation: sourceScopeId !== targetScopeId,
      includesApiKeys,
      exportedAt,
      statistics,
      checksumValid: checksum.length === 0 || checksum === checksumOf(state, settings),
    },
  };
}

/** 把备份状态重映射到当前聊天作用域：所有实体的 scopeId 必须与目标一致才能被检索到。 */
export function remapBackupScope(state: PhoneState, targetScopeId: string): PhoneState {
  if (state.scopeId === targetScopeId) return state;
  const remapRecord = <T extends { readonly scopeId: string }>(
    source: Readonly<Record<string, T>>,
  ): Readonly<Record<string, T>> => Object.fromEntries(
    Object.entries(source).map(([key, value]) => [key, { ...value, scopeId: targetScopeId }]),
  );
  const remapList = <T extends { readonly scopeId: string }>(source: readonly T[]): readonly T[] =>
    source.map((value) => ({ ...value, scopeId: targetScopeId }));
  return {
    ...state,
    scopeId: targetScopeId,
    profiles: remapRecord(state.profiles),
    conversations: remapRecord(state.conversations),
    messages: remapRecord(state.messages),
    posts: remapRecord(state.posts),
    interactions: remapRecord(state.interactions),
    outbox: remapRecord(state.outbox),
    batches: remapRecord(state.batches),
    calendarFestivals: remapRecord(state.calendarFestivals),
    summaries: remapList(state.summaries),
    pxxProducts: remapList(state.pxxProducts),
    diaryEntries: remapList(state.diaryEntries),
    memoryItems: remapList(state.memoryItems),
    timelineEvents: remapList(state.timelineEvents),
    worldClock: { ...state.worldClock, scopeId: targetScopeId },
  };
}

/**
 * 从备份设置快照生成设置补丁：空的密钥字段不覆盖当前配置，
 * 未识别的键直接丢弃，避免把任意 JSON 写进宿主设置。
 */
export function buildSettingsRestorePatch(
  snapshot: PhoneBackupSettingsSnapshot,
  allowedKeys: readonly string[],
): Readonly<Record<string, unknown>> {
  const allowed = new Set(allowedKeys);
  const patch: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(snapshot)) {
    if (!allowed.has(key) || value === undefined) continue;
    patch[key] = dropEmptySecrets(value);
  }
  return patch;
}

function normalizeBackupState(raw: Record<string, unknown>): PhoneState {
  const scopeId = typeof raw.scopeId === 'string' && raw.scopeId.trim() ? raw.scopeId.trim() : '';
  if (!scopeId) throw new PhoneBackupFormatError('备份状态缺少聊天作用域标识。');
  const schemaVersion = asInteger(raw.schemaVersion) ?? 1;
  if (schemaVersion > PHONE_SCHEMA_VERSION) {
    throw new PhoneBackupFormatError(
      `备份状态版本（v${schemaVersion}）高于当前扩展支持的 v${PHONE_SCHEMA_VERSION}，请先升级扩展。`,
    );
  }
  const shaped: PhoneState = {
    ...(raw as unknown as PhoneState),
    schemaVersion,
    scopeId,
    revision: Math.max(0, asInteger(raw.revision) ?? 0),
    profiles: recordOf(raw.profiles),
    conversations: recordOf(raw.conversations),
    messages: recordOf(raw.messages),
    messageOrder: stringsOf(raw.messageOrder),
    posts: recordOf(raw.posts),
    postOrder: stringsOf(raw.postOrder),
    interactions: recordOf(raw.interactions),
    outbox: recordOf(raw.outbox),
    batches: recordOf(raw.batches),
    appliedActionIds: stringsOf(raw.appliedActionIds),
    calendarFestivals: recordOf(raw.calendarFestivals),
    summaries: arrayOf(raw.summaries),
    pxxProducts: arrayOf(raw.pxxProducts),
    diaryEntries: arrayOf(raw.diaryEntries),
    memoryItems: arrayOf(raw.memoryItems),
    timelineEvents: arrayOf(raw.timelineEvents),
    dynamicWorldBook: normalizeDynamicWorldBook(raw.dynamicWorldBook),
    worldClock: normalizeWorldClock(raw.worldClock, scopeId),
  };
  return ensurePhoneStateShape(shaped);
}

function normalizeDynamicWorldBook(raw: unknown): PhoneState['dynamicWorldBook'] {
  const source = isPlainObject(raw) ? raw : {};
  return {
    lastFloor: asInteger(source.lastFloor) ?? -1,
    entries: arrayOf(source.entries),
    revision: Math.max(0, asInteger(source.revision) ?? 0),
  };
}

const WORLD_CLOCK_SOURCES: readonly PhoneState['worldClock']['source'][] = [
  'database', 'chat', 'system', 'user', 'generation', 'variables',
];

function normalizeWorldClock(raw: unknown, scopeId: string): PhoneState['worldClock'] {
  const source = isPlainObject(raw) ? raw : {};
  const now = asInteger(source.now);
  const kind = WORLD_CLOCK_SOURCES.find((candidate) => candidate === source.source) ?? 'system';
  return {
    scopeId,
    now: now !== null && now > 0 ? now : Date.now(),
    source: kind,
    reason: typeof source.reason === 'string' ? source.reason.slice(0, 200) : 'backup-restore',
  };
}

function collectStatistics(state: PhoneState): PhoneBackupStatistics {
  return {
    profiles: Object.keys(state.profiles).length,
    conversations: Object.keys(state.conversations).length,
    messages: Object.keys(state.messages).length,
    posts: Object.keys(state.posts).length,
    interactions: Object.keys(state.interactions).length,
    outbox: Object.keys(state.outbox).length,
    batches: Object.keys(state.batches).length,
    summaries: state.summaries.length,
    memoryItems: state.memoryItems.length,
    timelineEvents: state.timelineEvents.length,
    diaryEntries: state.diaryEntries.length,
    calendarFestivals: Object.keys(state.calendarFestivals).length,
    dynamicWorldBookEntries: state.dynamicWorldBook.entries.length,
  };
}

function sanitizeSettings(
  source: Readonly<Record<string, unknown>>,
  includeSecrets: boolean,
): PhoneBackupSettingsSnapshot {
  return sanitizeValue(source, includeSecrets) as PhoneBackupSettingsSnapshot;
}

function sanitizeValue(value: unknown, includeSecrets: boolean): unknown {
  if (Array.isArray(value)) return value.map((entry) => sanitizeValue(entry, includeSecrets));
  if (!isPlainObject(value)) return value;
  const result: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (entry === undefined || typeof entry === 'function') continue;
    if (!includeSecrets && SENSITIVE_KEY_PATTERN.test(key)) {
      result[key] = '';
      continue;
    }
    result[key] = sanitizeValue(entry, includeSecrets);
  }
  return result;
}

function dropEmptySecrets(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(dropEmptySecrets);
  if (!isPlainObject(value)) return value;
  const result: Record<string, unknown> = {};
  for (const [key, entry] of Object.entries(value)) {
    if (SENSITIVE_KEY_PATTERN.test(key) && (entry === '' || entry === null)) continue;
    result[key] = dropEmptySecrets(entry);
  }
  return result;
}

/** FNV-1a：轻量、无依赖，只用于发现文件被截断或手工改写。键顺序无关。 */
function checksumOf(state: PhoneState, settings: PhoneBackupSettingsSnapshot): string {
  const payload = JSON.stringify(canonicalize({ state, settings }));
  let hash = 0x811c9dc5;
  for (let index = 0; index < payload.length; index += 1) {
    hash ^= payload.charCodeAt(index);
    hash = Math.imul(hash, 0x01000193) >>> 0;
  }
  return `fnv1a-${hash.toString(16).padStart(8, '0')}`;
}

function canonicalize(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(canonicalize);
  if (!isPlainObject(value)) return value === undefined ? null : value;
  return Object.fromEntries(
    Object.keys(value).sort().map((key) => [key, canonicalize(value[key])]),
  );
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    throw new PhoneBackupFormatError('备份文件不是合法的 JSON 文本。');
  }
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
}

function asInteger(value: unknown): number | null {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? Math.floor(parsed) : null;
}

function recordOf<T>(value: unknown): Readonly<Record<string, T>> {
  if (!isPlainObject(value)) return {};
  return Object.fromEntries(
    Object.entries(value).filter(([, entry]) => isPlainObject(entry)),
  ) as Readonly<Record<string, T>>;
}

function arrayOf<T>(value: unknown): readonly T[] {
  return Array.isArray(value) ? value.filter((entry) => isPlainObject(entry)) as T[] : [];
}

function stringsOf(value: unknown): readonly string[] {
  return Array.isArray(value) ? value.filter((entry): entry is string => typeof entry === 'string') : [];
}