import { DEFAULT_TIME_ADVANCE, TIME_ADVANCE_LIMITS, type TimeAdvanceNumberKey, type TimeAdvanceSettings } from '../time/time-advance.js';
import { button, element } from './dom.js';

interface TimeAdvancePanelContext {
  readonly scopeId: string;
  readonly settings: TimeAdvanceSettings;
  readonly onSave: (settings: Partial<TimeAdvanceSettings>) => void | Promise<void>;
  readonly onBack: () => void;
  readonly showNotice: (message: string, kind?: 'info' | 'error' | 'success') => void;
}

const GROUPS: readonly { title: string; hint: string; fields: readonly (readonly [TimeAdvanceNumberKey, string])[] }[] = [
  { title: '发送消息与发布动态', hint: '每次耗时 = 基础时间 + 按字数计算的时间；不足一档按一档计，最后受单次上限约束。', fields: [
    ['sendBaseMinutes', '每次基础耗时（分钟）'], ['sendCharsPerMinute', '每增加一分钟所需字数'],
    ['sendAttachmentMinutes', '图片或视频额外耗时（分钟）'], ['sendMaxMinutes', '单次发送上限（分钟）'],
  ] },
  { title: '生成回复', hint: '首条回复参考联系人回复习惯，并限制在设定范围内；同一联系人继续回复或拆分短句时使用连续回复间隔。', fields: [
    ['firstReplyMinSeconds', '首条回复最短等待（秒）'], ['firstReplyMaxSeconds', '首条回复最长等待（秒）'],
    ['burstMinSeconds', '连续回复最短间隔（秒）'], ['burstMaxSeconds', '连续回复最长间隔（秒）'],
    ['modelDelayMaxMinutes', '模型等待时间上限（分钟）'], ['batchMaxMinutes', '整轮生成推进上限（分钟）'],
  ] },
];

interface TimeAdvanceDraft {
  readonly key: string;
  readonly values: Record<TimeAdvanceNumberKey, string>;
  useModelDelay: boolean;
}
let pendingDraft: TimeAdvanceDraft | null = null;
export function resetTimeAdvanceDraft(): void { pendingDraft = null; }

export function renderTimeAdvancePanel(context: TimeAdvancePanelContext): HTMLElement {
  const key = JSON.stringify([context.scopeId, context.settings]);
  if (pendingDraft?.key !== key) pendingDraft = { key, useModelDelay: context.settings.useModelDelay,
    values: Object.fromEntries(Object.keys(TIME_ADVANCE_LIMITS).map((key) => [key, String(context.settings[key as TimeAdvanceNumberKey])])) as Record<TimeAdvanceNumberKey, string>,
  };
  const draft = pendingDraft;
  const card = element('div', { className: 'phone-settings-card' });
  card.append(element('p', { className: 'phone-settings-hint', text: context.settings.enabled
    ? '自动时间推进已开启。修改后点击保存，后续发送和生成将使用这些规则。'
    : '自动时间推进已关闭。规则可以预先编辑，重新开启后生效；手动设置时钟仍可使用。' }));
  const inputs = new Map<TimeAdvanceNumberKey, HTMLInputElement>();
  const modelDelay = element('input', { attributes: { type: 'checkbox' } });
  modelDelay.checked = draft.useModelDelay;
  modelDelay.addEventListener('change', () => { draft.useModelDelay = modelDelay.checked; });
  for (const group of GROUPS) {
    card.append(element('h3', { className: 'phone-subsection-title', text: group.title }),
      element('p', { className: 'phone-settings-hint', text: group.hint }));
    if (group.title === '生成回复') {
      const row = element('label', { className: 'phone-checkbox-control' });
      const copy = element('span');
      copy.append(element('strong', { text: '采用模型给出的等待时间' }),
        element('small', { text: '模型明确给出等待时间时优先采用，但仍受模型等待上限和整轮上限约束。' }));
      row.append(modelDelay, copy);
      card.append(row);
    }
    for (const [key, label] of group.fields) {
      const [min, max] = TIME_ADVANCE_LIMITS[key];
      const row = element('label', { className: 'phone-setting-control' });
      const input = element('input', { className: 'phone-number-input', attributes: {
        type: 'number', min: String(min), max: String(max), step: key === 'sendCharsPerMinute' ? '1' : 'any', inputmode: 'decimal',
      } });
      input.value = draft.values[key];
      input.addEventListener('input', () => { draft.values[key] = input.value; });
      inputs.set(key, input);
      row.append(element('span', { className: 'phone-control-label', text: label }), input);
      card.append(row);
    }
  }
  const actions = element('div', { className: 'phone-settings-actions' });
  const save = button('保存时间推进规则', 'phone-button phone-button-primary', async () => {
    const values = {} as Record<TimeAdvanceNumberKey, number>;
    for (const group of GROUPS) for (const [key, label] of group.fields) {
      const input = inputs.get(key)!;
      const value = Number(input.value), [min, max] = TIME_ADVANCE_LIMITS[key];
      if (!input.value.trim() || !Number.isFinite(value) || value < min || value > max || (key === 'sendCharsPerMinute' && !Number.isInteger(value))) {
        context.showNotice(`请为「${label}」填写 ${min}～${max} 范围内的${key === 'sendCharsPerMinute' ? '整数' : '数值'}。`, 'error');
        input.focus();
        return;
      }
      values[key] = value;
    }
    if (values.firstReplyMinSeconds > values.firstReplyMaxSeconds || values.burstMinSeconds > values.burstMaxSeconds) {
      context.showNotice('最短等待或间隔应小于或等于对应的最长值。', 'error');
      return;
    }
    save.disabled = true;
    try {
      await context.onSave({ ...values, useModelDelay: modelDelay.checked });
      resetTimeAdvanceDraft();
      context.showNotice('时间推进规则已保存。', 'success');
      context.onBack();
    } finally { save.disabled = false; }
  });
  const reset = button('恢复默认', 'phone-button phone-button-secondary', () => {
    for (const [key, input] of inputs) { input.value = String(DEFAULT_TIME_ADVANCE[key]); draft.values[key] = input.value; }
    modelDelay.checked = DEFAULT_TIME_ADVANCE.useModelDelay;
    draft.useModelDelay = modelDelay.checked;
    context.showNotice('已填入默认规则，保存后生效。', 'info');
  });
  actions.append(reset, save);
  card.append(actions);
  return card;
}
