import type { DiaryEntry } from '../../domain/model.js';
import { describeDiaryRange } from '../../generation/diary-service.js';
import { applyApiProfile } from '../../integration/sillytavern-bridge.js';
import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import { settingsApiProfileRows } from '../shared-settings.js';

const DAY_MS = 86_400_000;
const WEEKDAYS = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'] as const;

/** 当前查看的页码；null = 最新一页。 */
let diaryPageIndex: number | null = null;
/** 是否停留在设置视图。 */
let diaryShowSettings = false;
/** 本次渲染要播放的翻页动画方向。 */
let diaryFlipDirection: 'next' | 'prev' | null = null;

/** 日记本：独立 API 定期把「这一天发生了什么」写成第一人称日记，翻页查看。 */
export function createDiaryApp(): PhoneAppDefinition {
  return {
    id: 'diary',
    label: '日记本',
    icon: '记',
    navigation: [],
    render(context) {
      const page = element('div', { className: 'phone-page phone-diary' });
      const enabled = context.diary.settings.enabled;
      page.append(renderHeader(context, enabled));
      if (!enabled || diaryShowSettings) {
        page.append(renderSettings(context));
      } else {
        page.append(renderBook(context));
      }
      return page;
    },
  };
}

function renderHeader(context: PhoneViewContext, enabled: boolean): HTMLElement {
  const header = element('div', { className: 'phone-diary-header' });
  header.append(element('h2', { className: 'phone-section-title', text: '日记本' }));
  const actions = element('div', { className: 'phone-diary-header-actions' });
  if (enabled) {
    const writeNow = button('补写日记', 'phone-button phone-button-secondary phone-button-compact', async () => {
      writeNow.disabled = true;
      writeNow.textContent = '正在写…';
      try {
        const result = await context.diary.generateNow();
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        if (result.ok) {
          diaryShowSettings = false;
          diaryPageIndex = null;
          context.navigate('diary');
        }
      } catch (error) {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      } finally {
        writeNow.disabled = false;
        writeNow.textContent = '补写日记';
      }
    });
    writeNow.title = '把上次记录点到现在的剧情立即写成日记';
    actions.append(writeNow);
    const gear = button('', 'phone-icon-button phone-diary-gear', () => {
      diaryShowSettings = !diaryShowSettings;
      context.navigate('diary');
    });
    gear.append(renderPhoneIcon('settings'));
    gear.setAttribute('aria-label', '日记设置');
    gear.classList.toggle('is-active', diaryShowSettings);
    actions.append(gear);
  }
  header.append(actions);
  return header;
}

/* ===== 书本视图 ===== */

function renderBook(context: PhoneViewContext): HTMLElement {
  const wrap = element('div', { className: 'phone-diary-book-wrap' });
  const entries = context.state.diaryEntries ?? [];
  if (entries.length === 0) {
    const empty = element('div', { className: 'phone-empty phone-diary-empty' });
    empty.append(
      renderPhoneIcon('diary'),
      element('strong', { text: '日记本还是空的' }),
      element('span', { text: `剧情时间每过 ${context.diary.settings.intervalDays} 天会自动写下一篇；也可以点右上角「补写日记」立即记录。` }),
    );
    wrap.append(empty, renderNextDueHint(context));
    return wrap;
  }

  const pageCount = entries.length;
  const index = diaryPageIndex === null
    ? pageCount - 1
    : Math.min(Math.max(diaryPageIndex, 0), pageCount - 1);
  const entry = entries[index]!;

  const book = element('div', { className: 'phone-diary-book' });
  const paper = element('article', { className: 'phone-diary-page-paper' });
  if (diaryFlipDirection) {
    paper.classList.add(diaryFlipDirection === 'next' ? 'is-flip-next' : 'is-flip-prev');
    diaryFlipDirection = null;
  }
  paper.append(renderPaper(context, entry));
  book.append(paper);
  wrap.append(book);

  // 翻页控制：‹ 第 N 页 / 共 M 页 ›
  const nav = element('div', { className: 'phone-diary-nav' });
  const prev = button('', 'phone-icon-button phone-diary-flip', () => {
    diaryFlipDirection = 'prev';
    diaryPageIndex = index - 1;
    context.navigate('diary');
  });
  prev.append(renderPhoneIcon('back'));
  prev.disabled = index <= 0;
  prev.setAttribute('aria-label', '上一页');
  const next = button('', 'phone-icon-button phone-diary-flip', () => {
    diaryFlipDirection = 'next';
    diaryPageIndex = index + 1;
    context.navigate('diary');
  });
  next.append(renderPhoneIcon('chevron'));
  next.disabled = index >= pageCount - 1;
  next.setAttribute('aria-label', '下一页');
  nav.append(
    prev,
    element('span', { className: 'phone-diary-nav-count', text: `第 ${index + 1} 页 / 共 ${pageCount} 页` }),
    next,
  );
  wrap.append(nav, renderNextDueHint(context));
  return wrap;
}

function renderPaper(context: PhoneViewContext, entry: DiaryEntry): HTMLElement {
  const inner = element('div', { className: 'phone-diary-paper-inner' });
  const [year, month, day] = entry.date.split('-').map(Number);
  const weekday = WEEKDAYS[new Date(year ?? 2000, (month ?? 1) - 1, day ?? 1).getDay()] ?? '';
  const head = element('header', { className: 'phone-diary-page-head' });
  head.append(
    element('strong', { text: `${year}年${month}月${day}日` }),
    element('span', { text: weekday }),
  );
  // 跨天补写的篇目标注覆盖范围。
  if (entry.coveredUntil - entry.coveredFrom > DAY_MS + 60_000) {
    head.append(element('small', { text: `记 ${describeDiaryRange(entry.coveredFrom, entry.coveredUntil)}` }));
  }
  const body = element('div', { className: 'phone-diary-page-body', text: entry.content });
  const foot = element('footer', { className: 'phone-diary-page-foot' });
  const tear = button('撕掉这页', 'phone-diary-tear', async () => {
    if (!window.confirm(`确定撕掉 ${entry.date} 这页日记吗？`)) return;
    try {
      await context.commands.removeDiaryEntry(entry.id);
      diaryPageIndex = null;
      context.showNotice('这页日记已被撕掉。', 'info');
    } catch (error) {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    }
  });
  foot.append(tear);
  inner.append(head, body, foot);
  return inner;
}

function renderNextDueHint(context: PhoneViewContext): HTMLElement {
  const settings = context.diary.settings;
  const covered = context.state.diaryCoveredUntil ?? 0;
  const hint = element('p', { className: 'phone-diary-due-hint' });
  if (covered > 0) {
    const due = new Date(covered + settings.intervalDays * DAY_MS);
    hint.textContent = `已记录到 ${formatDay(covered)}；剧情时间到 ${due.getMonth() + 1}月${due.getDate()}日 后自动写下一篇。`;
  } else {
    hint.textContent = '日记将从当前剧情日开始记录。';
  }
  return hint;
}

function formatDay(timestamp: number): string {
  const date = new Date(Math.max(0, timestamp - 60_000));
  return `${date.getMonth() + 1}月${date.getDate()}日`;
}

/* ===== 设置视图 ===== */

function renderSettings(context: PhoneViewContext): HTMLElement {
  const settings = context.diary.settings;
  const panel = element('div', { className: 'phone-diary-settings' });

  if (!settings.enabled) {
    const intro = element('div', { className: 'phone-diary-intro' });
    intro.append(
      renderPhoneIcon('diary'),
      element('strong', { text: '启用日记本' }),
      element('p', {
        text: '启用后，剧情时间每跨过设定的天数，手机会用下方的专用 API 自动把这段日子发生的事写成一篇第一人称日记（早上做了什么、中午和谁吃饭、晚上去了哪…），翻页即可回顾。',
      }),
      element('p', { className: 'phone-diary-intro-note', text: '日记使用独立 API，与聊天回复 API 互不影响。' }),
    );
    panel.append(intro);
  }

  // 启用开关。
  const toggleRow = element('label', { className: 'phone-checkbox-control' });
  const toggle = element('input', { attributes: { type: 'checkbox' } });
  toggle.checked = settings.enabled;
  toggle.addEventListener('change', () => {
    void context.diary.updateSettings({ enabled: toggle.checked }).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
    if (toggle.checked) diaryShowSettings = true;
  });
  const toggleCopy = element('span');
  toggleCopy.append(
    element('strong', { text: '启用日记本' }),
    element('small', { text: '按剧情时间跨度自动生成日记；关闭后已写的日记仍保留。' }),
  );
  toggleRow.append(toggle, toggleCopy);
  panel.append(toggleRow);

  // 记录间隔。
  const intervalOptions: (readonly [string, string])[] = [
    ['1', '每天一篇'], ['2', '每两天一篇'], ['3', '三天一篇'], ['5', '五天一篇'],
    ['7', '每周一篇'], ['14', '两周一篇'], ['30', '每月一篇'],
  ];
  if (!intervalOptions.some(([value]) => value === String(settings.intervalDays))) {
    intervalOptions.push([String(settings.intervalDays), `每 ${settings.intervalDays} 天一篇`]);
  }
  panel.append(selectRow('记录间隔（剧情时间）', intervalOptions, String(settings.intervalDays), (value) => {
    void context.diary.updateSettings({ intervalDays: Number(value) || 1 });
  }));

  // 专用 API：从配置库选择（在 设置 → API 配置 中保存）。
  panel.append(element('h3', { className: 'phone-diary-settings-subtitle', text: '日记专用 API（从配置库选择，独立于回复 API）' }));
  for (const row of settingsApiProfileRows(context.diary.apiProfiles, settings.api, (profile) => {
    void context.diary.updateSettings({ api: applyApiProfile(profile) }).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
  })) {
    panel.append(row);
  }

  if (settings.enabled) {
    const back = button('查看日记', 'phone-button phone-button-primary', () => {
      diaryShowSettings = false;
      context.navigate('diary');
    });
    const actionRow = element('div', { className: 'phone-diary-settings-actions' });
    actionRow.append(back);
    panel.append(actionRow);
  }
  return panel;
}

function selectRow(
  label: string,
  options: readonly (readonly [string, string])[],
  value: string,
  onChange: (value: string) => void,
): HTMLElement {
  const row = element('label', { className: 'phone-setting-control' });
  row.append(element('span', { className: 'phone-control-label', text: label }));
  const select = element('select', { className: 'phone-select' });
  for (const [optionValue, optionLabel] of options) {
    const option = element('option', { text: optionLabel, attributes: { value: optionValue } });
    option.selected = optionValue === value;
    select.append(option);
  }
  select.addEventListener('change', () => onChange(select.value));
  row.append(select);
  return row;
}
