import type { ConditionSnapshot, ConditionValue } from './types.js';

export type ConditionSnapshotNodeKind = 'group' | 'object' | 'array' | 'value';

export interface ConditionSnapshotNode {
  readonly path: string;
  readonly key: string;
  readonly kind: ConditionSnapshotNodeKind;
  readonly preview: string;
  readonly count: number;
  readonly expandable: boolean;
  readonly children: readonly ConditionSnapshotNode[];
}

export interface ConditionSnapshotTree {
  readonly revision: string;
  readonly scopeId: string;
  readonly totalNodes: number;
  readonly totalValues: number;
  readonly children: readonly ConditionSnapshotNode[];
}

export interface SnapshotTreeOptions {
  readonly maxDepth?: number;
  readonly maxChildren?: number;
  readonly previewLength?: number;
}

const DEFAULT_OPTIONS: Required<SnapshotTreeOptions> = {
  maxDepth: 3,
  maxChildren: 24,
  previewLength: 96,
};

const ROOT_GROUPS = ['state', 'variables', 'time', 'apps', 'worldBook', 'modules'] as const;

export function createConditionSnapshotTree(
  snapshot: ConditionSnapshot,
  options: SnapshotTreeOptions = {},
): ConditionSnapshotTree {
  const config = { ...DEFAULT_OPTIONS, ...options };
  const counters = { nodes: 0, values: 0 };
  const source = isRecord(snapshot.data) ? snapshot.data : {};
  const children = ROOT_GROUPS
    .filter((key) => key in source)
    .map((key) => buildNode(key, key, source[key]!, 0, config, counters, true));
  const known = new Set(ROOT_GROUPS);
  for (const [key, value] of Object.entries(source)) {
    if (!known.has(key as typeof ROOT_GROUPS[number])) {
      children.push(buildNode(key, key, value, 0, config, counters, true));
    }
  }
  return {
    revision: snapshot.revision,
    scopeId: snapshot.scopeId,
    totalNodes: counters.nodes,
    totalValues: counters.values,
    children,
  };
}

export function filterConditionSnapshotTree(
  tree: ConditionSnapshotTree,
  query: string,
): ConditionSnapshotTree {
  const keyword = query.trim().toLocaleLowerCase('zh-CN');
  if (!keyword) return tree;
  const children = tree.children
    .map((node) => filterNode(node, keyword))
    .filter((node): node is ConditionSnapshotNode => node !== null);
  return { ...tree, children };
}

export function summarizeConditionValue(value: ConditionValue, maxLength = DEFAULT_OPTIONS.previewLength): string {
  if (value === null) return '空值';
  if (typeof value === 'string') return quotePreview(value, maxLength);
  if (typeof value === 'number' || typeof value === 'boolean') return String(value);
  if (Array.isArray(value)) return `数组 · ${value.length} 项`;
  return `对象 · ${Object.keys(value).length} 个字段`;
}

function buildNode(
  key: string,
  path: string,
  value: ConditionValue,
  depth: number,
  config: Required<SnapshotTreeOptions>,
  counters: { nodes: number; values: number },
  isGroup = false,
): ConditionSnapshotNode {
  counters.nodes += 1;
  if (!isRecord(value) && !Array.isArray(value)) counters.values += 1;
  const isArray = Array.isArray(value);
  const isObject = isRecord(value);
  if (!isArray && !isObject) {
    return { key, path, kind: isGroup ? 'group' : 'value', preview: summarizeConditionValue(value, config.previewLength), count: 0, expandable: false, children: [] };
  }
  const entries = isArray
    ? value.map((item, index) => [String(index), item] as const)
    : Object.entries(value);
  const expandable = entries.length > 0;
  const children = depth >= config.maxDepth
    ? []
    : entries.slice(0, config.maxChildren).map(([childKey, childValue]) => buildNode(
      childKey,
      isArray ? `${path}[${childKey}]` : `${path}.${childKey}`,
      childValue,
      depth + 1,
      config,
      counters,
    ));
  const omitted = Math.max(0, entries.length - children.length);
  const preview = `${isArray ? '数组' : '对象'} · ${entries.length} ${isArray ? '项' : '个字段'}${omitted ? ` · 另有 ${omitted} 项` : ''}`;
  return {
    key,
    path,
    kind: isGroup ? 'group' : isArray ? 'array' : 'object',
    preview,
    count: entries.length,
    expandable,
    children,
  };
}

function filterNode(node: ConditionSnapshotNode, keyword: string): ConditionSnapshotNode | null {
  const selfMatches = `${node.path} ${node.key} ${node.preview}`.toLocaleLowerCase('zh-CN').includes(keyword);
  const children = node.children
    .map((child) => filterNode(child, keyword))
    .filter((child): child is ConditionSnapshotNode => child !== null);
  if (!selfMatches && children.length === 0) return null;
  return { ...node, children, expandable: node.expandable || children.length > 0 };
}

function quotePreview(value: string, maxLength: number): string {
  const compact = value.replace(/\s+/gu, ' ').trim();
  const clipped = compact.length > maxLength ? `${compact.slice(0, Math.max(0, maxLength - 1))}…` : compact;
  return `“${clipped}”`;
}

function isRecord(value: ConditionValue): value is { readonly [key: string]: ConditionValue } {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}