import { evaluateConditionGate } from '../conditions/generation.js';
import type { GenerationConditionContext } from '../conditions/generation.js';
import type { ConditionSource } from '../conditions/types.js';
import { phoneLogger } from '../core/logger.js';
import type { PhoneCommands } from '../domain/commands.js';
import type { DynamicWorldBookEntryState } from '../domain/model.js';
import type {
  DynamicWorldBookSettings,
  StoryFloorSnapshot,
  WorldBookEntrySnapshot,
} from '../integration/sillytavern-bridge.js';
import type { PhoneStore } from '../storage/phone-store.js';
import type { WorldBookWriter } from '../integration/worldbook-writer.js';
import { generateWithApiProxy } from './api-client.js';
import { CancellableRun, isCancelledError } from './cancellable-run.js';
import {
  buildDynamicWorldBookPrompt,
  DYNAMIC_WORLD_BOOK_PROTECTED_PATTERN,
  parseDynamicWorldBookResponse,
  type DynamicWorldBookTarget,
} from './dynamic-worldbook-service.js';

export interface DynamicWorldBookPipelineDeps {
  readonly store: PhoneStore;
  readonly commands: PhoneCommands;
  readonly settings: () => DynamicWorldBookSettings;
  readonly baselineEntries: () => readonly WorldBookEntrySnapshot[];
  readonly readFloorsSince: (afterFloor: number) => readonly StoryFloorSnapshot[];
  readonly latestFloorIndex: () => number;
  readonly userName: () => string;
  readonly writer: WorldBookWriter;
  readonly reportTask?: (message: string | null) => void;
  readonly reportTaskResult?: (message: string, kind: 'error' | 'success' | 'cancelled') => void;
  /** 可选纯条件门控；条件失败时不读取/写入动态世界书投影。 */
  readonly condition?: ConditionSource;
  readonly conditionContextProvider?: () => GenerationConditionContext | null;
}

export interface DynamicWorldBookPipelineResult {
  readonly ok: boolean;
  readonly message: string;
  readonly changed?: number;
}

interface EvolutionRecord {
  readonly floor: number;
  readonly content: string;
  readonly rationale: string;
}

const FAILURE_COOLDOWN_MS = 60_000;
const DEFAULT_MAX_TOKENS = 8_000;

class DynamicWorldBookFloorsChangedError extends Error {}
class DynamicWorldBookScopeChangedError extends Error {}

export class DynamicWorldBookPipeline {
  readonly #deps: DynamicWorldBookPipelineDeps;
  readonly #run = new CancellableRun();
  #running = false;
  #floorRevision = 0;
  #cooldownUntil = 0;
  #overlayBookName: string | null = null;

  constructor(deps: DynamicWorldBookPipelineDeps) {
    this.#deps = deps;
  }

  get isRunning(): boolean {
    return this.#running;
  }

  /** 用户在提示卡片上点「终止」时调用。 */
  cancel(): boolean {
    return this.#run.cancel();
  }

  async maybeOptimize(): Promise<void> {
    const settings = this.#deps.settings();
    if (!isConditionAllowed(this.#deps)) return;
    if (!settings.enabled || this.#running || Date.now() < this.#cooldownUntil) return;
    try {
      const state = this.#deps.store.state.dynamicWorldBook;
      if (state.lastFloor < 0) {
        if (selectTargets(this.#deps.baselineEntries(), settings.managedEntryIds).length === 0) return;
        const baseline = await this.#establishBaseline();
        if (!baseline.ok) {
          phoneLogger.warn('自动建立动态世界书基线未完成', { message: baseline.message });
        }
        return;
      }
      if (!settings.api.model.trim() || settings.managedEntryIds.length === 0) return;
      const floors = this.#eligibleFloors(state.lastFloor, settings.deferCurrentFloor);
      const aiCount = floors.filter((floor) => floor.role === 'ai').length;
      if (aiCount < settings.everyAiMessages) return;
      const result = await this.#optimize(floors);
      if (!result.ok) {
        // 提示已由 #optimize 内部落终态，这里只留排查用日志。
        phoneLogger.warn('自动优化动态世界书未完成', { message: result.message });
      }
    } catch (error) {
      this.#deps.reportTaskResult?.(`墨韵手机：自动动态世界书失败：${describeError(error)}`, 'error');
      phoneLogger.warn('自动动态世界书失败', error);
    }
  }

  async optimizeNow(): Promise<DynamicWorldBookPipelineResult> {
    const settings = this.#deps.settings();
    if (!isConditionAllowed(this.#deps)) return { ok: false, message: '动态世界书未通过条件门控。' };
    if (!settings.enabled) return { ok: false, message: '请先启用动态世界书。' };
    if (settings.managedEntryIds.length === 0) return { ok: false, message: '请先勾选允许动态维护的世界书条目。' };
    if (!settings.api.model.trim()) return { ok: false, message: '请先为动态世界书选择专用 API 配置。' };
    if (this.#running) return { ok: false, message: '动态世界书正在优化中，请稍候。' };
    if (this.#deps.store.state.dynamicWorldBook.lastFloor < 0) {
      const established = await this.#establishBaseline();
      if (!established.ok) return established;
      return { ok: true, message: `${established.message} 后续新增剧情可立即优化。`, changed: 0 };
    }
    const lastFloor = this.#deps.store.state.dynamicWorldBook.lastFloor;
    return this.#optimize(this.#eligibleFloors(lastFloor, false));
  }

  async invalidateFromFloor(fromFloor: number): Promise<void> {
    this.#floorRevision += 1;
    this.#cooldownUntil = 0;
    await this.#deps.commands.invalidateDynamicWorldBook(fromFloor);
    await this.syncProjection();
  }

  async switchScope(): Promise<void> {
    this.#floorRevision += 1;
    this.#cooldownUntil = 0;
    this.#overlayBookName = null;
    await this.syncProjection();
  }

  async syncProjection(): Promise<void> {
    const settings = this.#deps.settings();
    const managed = new Set(settings.managedEntryIds);
    const entries = settings.enabled
      ? this.#deps.store.state.dynamicWorldBook.entries
        .filter((entry) => managed.has(entry.key)
          && entry.currentState.trim()
          && entry.currentState.trim() !== entry.baselineContent.trim())
        .map((entry) => ({
          entryId: entry.key,
          targetName: entry.name,
          content: entry.currentState,
          floor: entry.updatedAtFloor,
          depth: settings.overlayDepth,
        }))
      : [];
    if (entries.length === 0) {
      const bookName = this.#overlayBookName ?? this.#deps.writer.currentChatBookName();
      if (bookName) await this.#deps.writer.clearOverlay(bookName);
      this.#overlayBookName = bookName;
      return;
    }
    const bookName = this.#overlayBookName ?? await this.#deps.writer.ensureOverlayBook(this.#deps.store.scopeId);
    this.#overlayBookName = bookName;
    await this.#deps.writer.projectOverlay(bookName, entries);
  }

  async clear(): Promise<DynamicWorldBookPipelineResult> {
    if (this.#running) return { ok: false, message: '动态世界书正在优化中，请稍候。' };
    try {
      if (this.#overlayBookName) await this.#deps.writer.clearOverlay(this.#overlayBookName);
      await this.#deps.commands.clearDynamicWorldBook();
      this.#cooldownUntil = 0;
      return { ok: true, message: '已清除本聊天的动态世界书状态与叠加条目。' };
    } catch (error) {
      return { ok: false, message: `清除失败：${describeError(error)}` };
    }
  }

  async editEntry(entryKey: string, content: string): Promise<DynamicWorldBookPipelineResult> {
    if (this.#running) return { ok: false, message: '动态世界书正在优化中，请稍候。' };
    const entry = this.#deps.store.state.dynamicWorldBook.entries.find((item) => item.key === entryKey);
    const normalized = content.replace(/\0/g, '').replace(/\r\n?/g, '\n').trim();
    if (!entry) return { ok: false, message: '动态条目不存在。' };
    if (!normalized) return { ok: false, message: '动态条目正文不能为空。' };
    if (DYNAMIC_WORLD_BOOK_PROTECTED_PATTERN.test(normalized)) return { ok: false, message: '正文命中受保护的机制或格式内容。' };
    try {
      await this.#deps.commands.editDynamicWorldBookEntry({
        ...entry,
        currentState: normalized,
        updatedAtFloor: Math.max(entry.updatedAtFloor, this.#deps.latestFloorIndex()),
        manualEdited: true,
      });
      await this.syncProjection();
      return { ok: true, message: `动态条目「${entry.name}」已更新。`, changed: 1 };
    } catch (error) {
      return { ok: false, message: `更新失败：${describeError(error)}` };
    }
  }

  async restoreEntry(entryKey: string): Promise<DynamicWorldBookPipelineResult> {
    const entry = this.#deps.store.state.dynamicWorldBook.entries.find((item) => item.key === entryKey);
    if (!entry) return { ok: false, message: '动态条目不存在。' };
    await this.#deps.commands.editDynamicWorldBookEntry({
      ...entry,
      currentState: entry.baselineContent,
      evolutionLog: [],
      manualEdited: false,
    });
    await this.syncProjection();
    return { ok: true, message: `「${entry.name}」已恢复静态基线。`, changed: 1 };
  }

  listOrphanOverlayBooks(): readonly string[] {
    return this.#deps.writer.listOrphanOverlayBooks();
  }

  async #establishBaseline(): Promise<DynamicWorldBookPipelineResult> {
    const settings = this.#deps.settings();
    const targets = selectTargets(this.#deps.baselineEntries(), settings.managedEntryIds);
    if (targets.length === 0) return { ok: false, message: '没有找到可维护的已勾选条目，受保护条目不会加入动态世界书。' };
    const floor = Math.max(0, this.#deps.latestFloorIndex());
    const entries = targets.map((target) => baselineState(target, floor));
    await this.#deps.commands.setDynamicWorldBookBaseline(floor, entries);
    return { ok: true, message: `已在第 ${floor} 层建立 ${entries.length} 个动态条目基线。`, changed: 0 };
  }

  async #optimize(floors: readonly StoryFloorSnapshot[]): Promise<DynamicWorldBookPipelineResult> {
    if (floors.length === 0 || !floors.some((floor) => floor.role === 'ai')) {
      return { ok: false, message: '基线之后没有可优化的新 AI 剧情楼层。' };
    }
    const settings = this.#deps.settings();
    const targets = selectTargets(this.#deps.baselineEntries(), settings.managedEntryIds);
    if (targets.length === 0) return { ok: false, message: '没有找到安全且已勾选的世界书条目。' };
    const stateAtStart = this.#deps.store.state;
    const scopeId = this.#deps.store.scopeId;
    const revision = this.#floorRevision;
    const floor = floors.at(-1)!.floor;
    const currentByKey = new Map(stateAtStart.dynamicWorldBook.entries.map((entry) => [entry.key, entry]));
    const currentStates = Object.fromEntries(targets.flatMap((target) => {
      const entry = currentByKey.get(target.id);
      const evolution = entry?.evolutionLog.map(parseEvolutionRecord).filter(isEvolutionRecord) ?? [];
      if (evolution.length === 0) return [];
      return [[target.id, evolution.map((item) => `第 ${item.floor} 层：${item.rationale || item.content}`).join('\n')]];
    }));
    const prompt = buildDynamicWorldBookPrompt({
      targets,
      floors,
      currentStates,
      userName: this.#deps.userName(),
      floor,
    });

    this.#running = true;
    this.#deps.reportTask?.(`墨韵手机：正在优化动态世界书（截至第 ${floor} 层）…`);
    try {
      const raw = await generateWithApiProxy(settings.api, {
        system: prompt.system,
        user: prompt.user,
        temperature: settings.api.temperature ?? 0.2,
        maxTokens: settings.api.maxTokens ?? DEFAULT_MAX_TOKENS,
        signal: this.#run.begin(),
        validateResponse: (response) => parseDynamicWorldBookResponse(response, targets).status !== 'invalid',
        invalidResponseMessage: '动态世界书响应未通过 JSON、格式或安全校验。',
        onRetry: ({ attempt, retryCount, error }) => {
          this.#deps.reportTaskResult?.(
            `墨韵手机：动态世界书优化失败，正在重试 ${attempt}/${retryCount}：${describeError(error)}`,
            'error',
          );
        },
      });
      this.#assertCurrent(scopeId, revision);
      const parsed = parseDynamicWorldBookResponse(raw, targets);
      if (parsed.status === 'invalid') throw new Error(parsed.reason);
      if (parsed.status === 'unchanged') {
        await this.#deps.commands.optimizeDynamicWorldBook(floor, []);
        this.#cooldownUntil = 0;
        const message = `截至第 ${floor} 层没有确认到需要更新的设定。`;
        this.#deps.reportTaskResult?.(`墨韵手机：${message}`, 'success');
        return { ok: true, message, changed: 0 };
      }
      const targetMap = new Map(targets.map((target) => [target.id, target]));
      const updates: DynamicWorldBookEntryState[] = parsed.response.updates.map((update) => {
        const target = targetMap.get(update.entryId)!;
        const previous = currentByKey.get(update.entryId) ?? baselineState(target, stateAtStart.dynamicWorldBook.lastFloor);
        const evolution: EvolutionRecord = {
          floor,
          content: update.content,
          rationale: update.rationale ?? '',
        };
        return {
          ...previous,
          currentState: update.content,
          evolutionLog: [...previous.evolutionLog, JSON.stringify(evolution)],
          updatedAtFloor: floor,
          manualEdited: false,
        };
      });
      await this.#deps.commands.optimizeDynamicWorldBook(floor, updates);
      this.#assertCurrent(scopeId, revision);
      await this.syncProjection();
      this.#cooldownUntil = 0;
      const message = `已更新 ${updates.length} 个动态世界书条目（截至第 ${floor} 层）。`;
      this.#deps.reportTaskResult?.(`墨韵手机：${message}`, 'success');
      return { ok: true, message, changed: updates.length };
    } catch (error) {
      if (isCancelledError(error)) {
        this.#deps.reportTaskResult?.('墨韵手机：动态世界书优化已终止。', 'cancelled');
        return { ok: false, message: '动态世界书优化已终止。' };
      }
      if (!(error instanceof DynamicWorldBookFloorsChangedError) && !(error instanceof DynamicWorldBookScopeChangedError)) {
        this.#cooldownUntil = Date.now() + FAILURE_COOLDOWN_MS;
      }
      const message = `动态世界书优化失败：${describeError(error)}`;
      this.#deps.reportTaskResult?.(`墨韵手机：${message}`, 'error');
      return { ok: false, message };
    } finally {
      this.#running = false;
      this.#run.end();
    }
  }

  #eligibleFloors(lastFloor: number, deferCurrentFloor: boolean): readonly StoryFloorSnapshot[] {
    const floors = this.#deps.readFloorsSince(lastFloor).filter((floor) => floor.floor > lastFloor);
    if (!deferCurrentFloor) return floors;
    const latestAiFloor = [...floors].reverse().find((floor) => floor.role === 'ai')?.floor;
    return latestAiFloor === undefined ? floors : floors.filter((floor) => floor.floor < latestAiFloor);
  }

  #assertCurrent(scopeId: string, revision: number): void {
    if (this.#deps.store.scopeId !== scopeId) throw new DynamicWorldBookScopeChangedError('聊天已切换，已丢弃旧聊天的优化结果。');
    if (this.#floorRevision !== revision) throw new DynamicWorldBookFloorsChangedError('剧情楼层已变化，已丢弃过期优化结果。');
  }
}

function selectTargets(
  entries: readonly WorldBookEntrySnapshot[],
  managedEntryIds: readonly string[],
): readonly DynamicWorldBookTarget[] {
  const selected = new Set(managedEntryIds.map(normalizeEntryId));
  return entries.flatMap((entry) => {
    const content = entry.content.trim();
    const entryIds = [entry.id, ...(entry.legacyIds ?? [])].map(normalizeEntryId);
    if (!entryIds.some((id) => selected.has(id)) || !content || DYNAMIC_WORLD_BOOK_PROTECTED_PATTERN.test(`${entry.name}\n${content}`)) return [];
    return [{ id: entry.id, name: entry.name, content, ...(entry.book ? { book: entry.book } : {}) }];
  });
}

function normalizeEntryId(value: string): string {
  return value.trim();
}

function baselineState(target: DynamicWorldBookTarget, floor: number): DynamicWorldBookEntryState {
  return {
    key: target.id,
    book: target.book ?? '',
    name: target.name,
    baselineHash: hashText(target.content),
    baselineContent: target.content,
    currentState: target.content,
    evolutionLog: [],
    updatedAtFloor: Math.max(0, Math.floor(floor)),
    manualEdited: false,
  };
}

function parseEvolutionRecord(value: string): EvolutionRecord | null {
  try {
    const parsed = JSON.parse(value) as Partial<EvolutionRecord>;
    return Number.isFinite(parsed.floor) && typeof parsed.content === 'string' && typeof parsed.rationale === 'string'
      ? { floor: Math.floor(parsed.floor!), content: parsed.content, rationale: parsed.rationale }
      : null;
  } catch {
    return null;
  }
}

function isEvolutionRecord(value: EvolutionRecord | null): value is EvolutionRecord {
  return value !== null;
}

function hashText(value: string): string {
  let hash = 2_166_136_261;
  for (let index = 0; index < value.length; index += 1) {
    hash ^= value.charCodeAt(index);
    hash = Math.imul(hash, 16_777_619);
  }
  return (hash >>> 0).toString(36);
}

function isConditionAllowed(deps: DynamicWorldBookPipelineDeps): boolean {
  if (deps.condition === undefined) return true;
  const context = deps.conditionContextProvider?.();
  return context ? evaluateConditionGate(deps.condition, context) : false;
}

function describeError(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? '未知错误');
}