export const SELF_PROFILE_ID = 'profile:self';

export function canDeleteUnansweredUserPost(state: PhoneState, postId: string): boolean {
  const post = state.posts[postId];
  if (!post || post.profileId !== SELF_PROFILE_ID || (post.appId !== 'forum' && post.appId !== 'twitter')) {
    return false;
  }
  const isProcessing = Object.values(state.outbox).some(
    (item) => item.entityType === 'post' && item.entityId === postId && item.status === 'processing',
  );
  if (isProcessing) return false;
  const hasReplyPost = Object.values(state.posts).some(
    (candidate) => candidate.id !== postId
      && (candidate.parentId === postId || candidate.targetId === postId),
  );
  const hasComment = Object.values(state.interactions).some(
    (interaction) => interaction.targetId === postId && interaction.type === 'comment',
  );
  return !hasReplyPost && !hasComment;
}

export interface MessageRollbackPlan {
  readonly conversationId: string;
  /** 会被删除的消息 id（按聊天顺序）。 */
  readonly removedMessageIds: readonly string[];
  /** 删除后重新回到「待生成」的用户消息 id；没有可等待回复的用户消息时为 null。 */
  readonly requeueMessageId: string | null;
}

/**
 * 计算「从这条消息回滚」的效果：
 * - 目标是用户消息：删掉它后面的全部消息，它自己回到待生成，方便重新 roll；
 * - 目标是角色消息：连它一起删掉，若上方紧邻的用户消息因此没有回复，也回到待生成。
 * 纯函数，UI 用它决定按钮是否显示与提示文案。
 */
export function planMessageRollback(state: PhoneState, messageId: string): MessageRollbackPlan | null {
  const target = state.messages[messageId];
  if (!target) return null;
  const ordered = state.messageOrder.flatMap((id) => {
    const message = state.messages[id];
    return message && message.conversationId === target.conversationId ? [message] : [];
  });
  const targetIndex = ordered.findIndex((message) => message.id === messageId);
  if (targetIndex < 0) return null;
  const fromUser = isUserMessage(target);
  const removedMessageIds = ordered.slice(fromUser ? targetIndex + 1 : targetIndex).map((message) => message.id);
  const removed = new Set(removedMessageIds);
  const last = ordered.filter((message) => !removed.has(message.id)).at(-1);
  const requeueMessageId = last && isUserMessage(last) && last.status !== 'queued' ? last.id : null;
  return { conversationId: target.conversationId, removedMessageIds, requeueMessageId };
}

/** 是否有内容可回滚（没有可删内容也无法重排时不显示按钮）。 */
export function canRollbackMessage(state: PhoneState, messageId: string): boolean {
  const plan = planMessageRollback(state, messageId);
  return Boolean(plan && (plan.removedMessageIds.length > 0 || plan.requeueMessageId));
}

function isUserMessage(message: PhoneMessage): boolean {
  return message.profileId === SELF_PROFILE_ID || message.direction === 'outgoing';
}

