  /**
   * 正文楼层被删除或改写后，使覆盖该楼层及其后续楼层的记忆/总结/时间线失效，
   * 并把整理游标回退到最早受影响摘要之前，供新 AI 回复完成后重新整理。
   */
  async invalidateMemoryFromFloor(fromFloor: number): Promise<{
    readonly removedMemoryCount: number;
    readonly removedTimelineCount: number;
    readonly resumeAfterFloor: number;
  }> {
    if (!Number.isFinite(fromFloor) || fromFloor < 0) {
      return { removedMemoryCount: 0, removedTimelineCount: 0, resumeAfterFloor: -1 };
    }
    const floor = Math.floor(fromFloor);
    const state = this.#store.state;
    const affectedSummaries = (state.memoryItems ?? []).filter((item) => (
      item.kind === 'summary' && item.floorTo >= floor
    ));
    const resumeAfterFloor = Math.max(
      -1,
      Math.min(floor, ...affectedSummaries.map((item) => item.floorFrom)) - 1,
    );
    const removedMemoryCount = (state.memoryItems ?? []).filter((item) => item.floorTo >= floor).length;
    const removedTimelineCount = (state.timelineEvents ?? []).filter((entry) => entry.floor >= floor).length;
    const needsCursorRollback = (state.memoryLastFloor ?? -1) > resumeAfterFloor;
    if (removedMemoryCount === 0 && removedTimelineCount === 0 && !needsCursorRollback) {
      return { removedMemoryCount, removedTimelineCount, resumeAfterFloor };
    }
    await this.#store.dispatch([
      createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'memory.floors.invalidated',
          occurredAt: state.worldClock.now,
          payload: { fromFloor: floor, resumeAfterFloor },
        },
        this.#idFactory,
      ),
    ]);
    return { removedMemoryCount, removedTimelineCount, resumeAfterFloor };
  }

  /** 记录一条记忆（正文摘要、合并总结或手机总结），自动分配记忆编号；总结可同时归档并入的摘要。 */
  async recordMemoryItem(input: {
    readonly kind: 'summary' | 'consolidation';
    readonly content: string;
    readonly floorFrom: number;
    readonly floorTo: number;
    readonly archiveSeqs?: readonly number[];
    /** 来源语义；缺省时按 kind 推导（summary → 正文记忆，consolidation → 合并总结）。 */
    readonly source?: MemorySource;
    /** 手机总结覆盖到的剧情时刻。 */
    readonly coveredUntil?: number;
    /** 手机总结覆盖的手机记录条数。 */
    readonly sourceCount?: number;
  }): Promise<MemoryItem> {
    const content = input.content.replace(/\u0000/g, '').trim();
    if (!content) throw new Error('记忆内容为空');
    const state = this.#store.state;
    const source = input.source ?? (input.kind === 'consolidation' ? 'summary' : 'memory');
    const item: MemoryItem = {
      id: createScopedId(state.scopeId, 'memory', this.#idFactory),
      scopeId: state.scopeId,
      seq: (state.memorySeq ?? 0) + 1,
      kind: input.kind,
      source,
      displayType: source,
      content,
      floorFrom: input.floorFrom,
      floorTo: input.floorTo,
      archived: false,
      ...(input.archiveSeqs && input.archiveSeqs.length > 0 ? { sourceSeqs: input.archiveSeqs } : {}),
      ...(typeof input.coveredUntil === 'number' && Number.isFinite(input.coveredUntil)
        ? { coveredUntil: input.coveredUntil }
        : {}),
      ...(typeof input.sourceCount === 'number' && Number.isFinite(input.sourceCount)
        ? { sourceCount: Math.max(0, Math.floor(input.sourceCount)) }
        : {}),
      createdAt: state.worldClock.now,
    };
    await this.#store.dispatch([
      createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'memory.item.recorded',
          occurredAt: state.worldClock.now,
          payload: {
            item,
            ...(input.archiveSeqs && input.archiveSeqs.length > 0 ? { archiveSeqs: input.archiveSeqs } : {}),
          },
        },
        this.#idFactory,
      ),
    ]);
    return item;
  }

