  async setTwitterFollow(profileId: string, followed: boolean): Promise<boolean> {
    const state = this.#store.state;
    const profile = state.profiles[profileId];
    if (!profile || profile.id === SELF_PROFILE_ID) throw new Error('无法关注该账号');
    const existing = Object.values(state.interactions).filter(
      (interaction) => interaction.appId === 'twitter'
        && interaction.type === 'follow'
        && interaction.actorProfileId === SELF_PROFILE_ID
        && interaction.targetId === profileId,
    );
    if (followed) {
      if (existing.length > 0) return true;
      const interaction: Interaction = {
        id: createScopedId(state.scopeId, 'interaction', this.#idFactory),
        scopeId: state.scopeId,
        appId: 'twitter',
        type: 'follow',
        actorProfileId: SELF_PROFILE_ID,
        targetId: profileId,
        createdAt: state.worldClock.now,
      };
      await this.#store.dispatch([
        createPhoneEvent(
          {
            scopeId: state.scopeId,
            type: 'interaction.created',
            occurredAt: interaction.createdAt,
            payload: { interaction },
          },
          this.#idFactory,
        ),
      ]);
      return true;
    }
    if (existing.length === 0) return false;
    await this.#store.dispatch(existing.map((interaction) => createPhoneEvent(
      {
        scopeId: state.scopeId,
        type: 'interaction.deleted',
        occurredAt: state.worldClock.now,
        payload: { interactionId: interaction.id },
      },
      this.#idFactory,
    )));
    return false;
  }

