  async createForumBoard(
    rawName: string,
    rawDescription = '',
    maximumBoards = 24,
  ): Promise<ForumBoard> {
    const state = this.#store.state;
    const name = cleanAmbientText(rawName, 40);
    const description = rawDescription.replace(/\u0000/g, '').trim().slice(0, 160);
    if (!name) throw new Error('板块名称不能为空');
    const limit = Math.min(50, Math.max(1, Math.floor(maximumBoards)));
    if (Object.keys(state.forumBoards).length >= limit) throw new Error(`自定义板块最多 ${limit} 个`);
    if (findForumBoardByName(state, name) || forumBoardNameExistsInPosts(state, name)) {
      throw new Error('已存在同名板块');
    }
    const board: ForumBoard = {
      id: createScopedId(state.scopeId, 'forum-board', this.#idFactory),
      scopeId: state.scopeId,
      name,
      description,
      createdAt: state.worldClock.now,
      updatedAt: state.worldClock.now,
    };
    await this.#store.dispatch([
      createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'forum.board.created',
          occurredAt: state.worldClock.now,
          payload: { board },
        },
        this.#idFactory,
      ),
    ]);
    return board;
  }

  async updateForumBoard(
    boardId: string,
    patch: { readonly name?: string; readonly description?: string },
  ): Promise<ForumBoard> {
    const state = this.#store.state;
    const existing = state.forumBoards[boardId];
    if (!existing) throw new Error('自定义板块不存在');
    const name = patch.name === undefined ? existing.name : cleanAmbientText(patch.name, 40);
    if (!name) throw new Error('板块名称不能为空');
    const duplicate = findForumBoardByName(state, name);
    if (duplicate && duplicate.id !== existing.id) throw new Error('已存在同名自定义板块');
    if (name !== existing.name && forumBoardNameExistsInPosts(state, name)) throw new Error('已存在同名内容板块');
    const board: ForumBoard = {
      ...existing,
      name,
      description: patch.description === undefined
        ? existing.description
        : patch.description.replace(/\u0000/g, '').trim().slice(0, 160),
      updatedAt: state.worldClock.now,
    };
    await this.#store.dispatch([
      createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'forum.board.updated',
          occurredAt: state.worldClock.now,
          payload: { board, previousName: existing.name },
        },
        this.#idFactory,
      ),
    ]);
    return board;
  }

