  /**
   * 按名称改写板块。界面上的板块只有名字，登记过的自定义板块走 id 更新；
   * NPC/世界书写出的内容板块没有记录，这里首次编辑时登记为可管理板块并迁移历史主题。
   */
  async updateForumBoardByName(
    currentName: string,
    patch: { readonly name?: string; readonly description?: string },
  ): Promise<ForumBoard> {
    const state = this.#store.state;
    const previousName = currentName.replace(/\u0000/g, '').trim();
    const registered = previousName ? findForumBoardByName(state, previousName) : undefined;
    if (registered) return this.updateForumBoard(registered.id, patch);
    if (!previousName || !forumBoardNameExistsInPosts(state, previousName)) throw new Error('板块不存在');
    const name = patch.name === undefined ? previousName : cleanAmbientText(patch.name, 40);
    if (!name) throw new Error('板块名称不能为空');
    if (findForumBoardByName(state, name)) throw new Error('已存在同名自定义板块');
    const renamed = !sameForumBoardName(name, previousName);
    if (renamed && forumBoardNameExistsInPosts(state, name)) throw new Error('已存在同名内容板块');
    const board: ForumBoard = {
      id: createScopedId(state.scopeId, 'forum-board', this.#idFactory),
      scopeId: state.scopeId,
      name,
      description: (patch.description ?? '').replace(/\u0000/g, '').trim().slice(0, 160),
      createdAt: state.worldClock.now,
      updatedAt: state.worldClock.now,
    };
    const events: PhoneEvent[] = [
      createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'forum.board.created',
          occurredAt: state.worldClock.now,
          payload: { board },
        },
        this.#idFactory,
      ),
    ];
    if (renamed) {
      events.push(createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'forum.board.renamed',
          occurredAt: state.worldClock.now,
          payload: { previousName, name },
        },
        this.#idFactory,
      ));
    }
    await this.#store.dispatch(events);
    return board;
  }

  /** 按名称删除板块：登记过的删记录，内容板块把历史主题并回默认板块。两种情况都不删帖。 */
  async deleteForumBoardByName(name: string): Promise<void> {
    const state = this.#store.state;
    const previousName = name.replace(/\u0000/g, '').trim();
    const registered = previousName ? findForumBoardByName(state, previousName) : undefined;
    if (registered) return this.deleteForumBoard(registered.id);
    if (!previousName || !forumBoardNameExistsInPosts(state, previousName)) throw new Error('板块不存在');
    await this.#store.dispatch([
      createPhoneEvent(
        {
          scopeId: state.scopeId,
          type: 'forum.board.renamed',
          occurredAt: state.worldClock.now,
          payload: { previousName, name: '' },
        },
        this.#idFactory,
      ),
    ]);
  }

