interface ImageRequestDiagnostic {
  readonly stage: string;
  readonly url: string;
  readonly request?: Readonly<Record<string, unknown>>;
  readonly sameOrigin?: boolean;
}

class ImageNetworkError extends Error {
  readonly originalError: unknown;

  constructor(message: string, originalError: unknown) {
    super(message);
    this.name = 'ImageNetworkError';
    this.originalError = originalError;
  }
}

class NovelAiRequestError extends Error {
  readonly retryable: boolean;

  constructor(message: string, retryable: boolean) {
    super(message);
    this.name = 'NovelAiRequestError';
    this.retryable = retryable;
  }
}

/** 只处理 fetch 直接拒绝；HTTP 响应由调用方按供应商协议分类。 */
async function fetchImageResponse(
  diagnostic: ImageRequestDiagnostic,
  init?: RequestInit,
): Promise<Response> {
  try {
    return await fetch(diagnostic.url, init);
  } catch (error) {
    logHttpFailure({
      stage: diagnostic.stage,
      url: diagnostic.url,
      request: diagnostic.request,
      error,
    });
    const locationHint = diagnostic.sameOrigin
      ? 'SillyTavern 同源接口不可达；请检查酒馆服务是否仍在运行，并查看服务端控制台。'
      : '浏览器没有收到 HTTP 响应；请检查站点地址、手机网络、DNS/证书，以及目标站点是否允许浏览器跨域访问（CORS）。';
    throw new ImageNetworkError(
      `${diagnostic.stage}网络连接失败：${locationHint}原始错误：${describeError(error)}`,
      error,
    );
  }
}

function imageRequestSummary(
  config: ImageGenerationSettings,
  extra: Readonly<Record<string, unknown>> = {},
): Readonly<Record<string, unknown>> {
  return {
    provider: config.provider,
    model: config.model,
    width: config.width,
    height: config.height,
    steps: config.steps,
    ...extra,
  };
}

/**
 * 统一解码各供应商的成功响应：二进制图片、ZIP 包裹、JSON 字段、裸 base64、直链都走同一条路径。
 * 失败时把响应侧证据（Content-Type、字节长度、开头字节、正文片段）写进日志，
 * 并保留「正文传输中断可重试」与「格式不可识别不重试」的区分。
 */
async function decodeImagePayload(
  response: Response,
  diagnostic: ImageRequestDiagnostic,
): Promise<string> {
  try {
    return await decodeImageResponse(response, { baseUrl: diagnostic.url });
  } catch (error) {
    logOperationFailure({
      stage: `${diagnostic.stage}响应解码`,
      reason: error instanceof Error ? error.message : String(error),
      context: {
        url: diagnostic.url,
        status: response.status,
        ...(diagnostic.request ?? {}),
        ...imagePayloadDiagnostics(error),
      },
    });
    throw error;
  }
}

/** 拼接固定正面提示词：AI 提示词在前，质量/画风词在后。 */
function mergePositivePrompt(config: ImageGenerationSettings, prompt: string): string {
  const fixed = config.positivePrompt.trim().replace(/^[,，]+|[,，]+$/g, '');
  if (!fixed) return prompt;
  return `${prompt.replace(/[,，]\s*$/, '')}, ${fixed}`;
}

export interface GenerateImageOptions {
  /** 角色参考图（NAI v4 系 Character Reference；其他供应商忽略）。 */
  readonly characterReferences?: readonly CharacterReferenceInput[];
}

/** 调用配置的供应商生成图片，返回可直接用于 <img src> 的地址。 */
export async function generateImageWithConfig(
  config: ImageGenerationSettings,
  prompt: string,
  options: GenerateImageOptions = {},
): Promise<string> {
  if (!config.enabled) throw new Error('生图功能未启用；请在设置的「生图配置」中开启。');
  const cleanPrompt = prompt.trim();
  if (!cleanPrompt) throw new Error('生图提示词为空。');
  if (config.provider === 'zhihuiji') {
    // 智绘姬主动生图通过宿主事件总线发送带唯一 ID 的请求；参数由智绘姬自身设置决定。
    return requestZhihuijiImage(cleanPrompt);
  }
  if (config.provider === 'novelai') {
    // NovelAI 分支自行处理结构化提示词与固定正面词的拼接位置。
    return generateWithNovelAi(config, cleanPrompt, options.characterReferences ?? []);
  }
  // 其他供应商不支持结构化格式：若 AI 输出了结构化提示词则拍平成单串。
  const structured = parseNovelAiStructuredPrompt(cleanPrompt);
  const flatPrompt = mergePositivePrompt(config, structured ? flattenNovelAiStructuredPrompt(structured) : cleanPrompt);
  if (!flatPrompt) throw new Error('生图提示词为空。');
  switch (config.provider) {
    case 'sdwebui':
      return generateWithSdWebUi(config, flatPrompt);
    case 'comfyui':
      return generateWithComfyUi(config, flatPrompt);
    default:
      return generateWithOpenAi(config, flatPrompt);
  }
}

async function generateWithOpenAi(config: ImageGenerationSettings, prompt: string): Promise<string> {
  const baseUrl = config.baseUrl || OPENAI_DEFAULT_BASE_URL;
  if (!config.apiKey) throw new Error('OpenAI 兼容生图需要填写 API Key。');
  const endpoint = `${baseUrl}/images/generations`;
  const request = imageRequestSummary(config, { route: 'images/generations' });
  const response = await fetchImageResponse({
    stage: 'OpenAI 兼容生图',
    url: endpoint,
    request,
    sameOrigin: false,
  }, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: config.apiKey.startsWith('Bearer ') ? config.apiKey : `Bearer ${config.apiKey}`,
    },
    body: JSON.stringify({
      model: config.model || 'dall-e-3',
      prompt,
      n: 1,
      size: `${config.width}x${config.height}`,
      response_format: 'b64_json',
      ...(config.quality ? { quality: config.quality } : {}),
    }),
  });
  if (!response.ok) {
    const detail = await readErrorText(response);
    logHttpFailure({
      stage: 'OpenAI 兼容生图',
      url: endpoint,
      status: response.status,
      statusText: response.statusText,
      body: detail,
      request,
    });
    throw new Error(`生图请求失败 (HTTP ${response.status})：${detail}`);
  }
  return decodeImagePayload(response, {
    stage: 'OpenAI 兼容生图',
    url: endpoint,
    request,
  });
}

async function generateWithSdWebUi(config: ImageGenerationSettings, prompt: string): Promise<string> {
  if (!config.baseUrl) throw new Error('请填写本地 SD WebUI 地址（例如 http://127.0.0.1:7860）。');
  const endpoint = `${config.baseUrl}/sdapi/v1/txt2img`;
  const request = imageRequestSummary(config, { route: 'sdapi/v1/txt2img' });
  const headers: Record<string, string> = { 'Content-Type': 'application/json' };
  if (config.sdAuth) headers.Authorization = `Basic ${btoa(config.sdAuth)}`;
  const response = await fetchImageResponse({
    stage: 'SD WebUI 生图',
    url: endpoint,
    request,
    sameOrigin: false,
  }, {
    method: 'POST',
    headers,
    body: JSON.stringify({
      prompt,
      negative_prompt: config.negativePrompt,
      width: config.width,
      height: config.height,
      steps: config.steps,
      cfg_scale: config.cfgScale,
      ...(config.sampler ? { sampler_name: config.sampler } : {}),
      ...(config.scheduler ? { scheduler: config.scheduler } : {}),
      ...(config.model ? { override_settings: { sd_model_checkpoint: config.model } } : {}),
    }),
  });
  if (!response.ok) {
    const detail = await readErrorText(response);
    logHttpFailure({
      stage: 'SD WebUI 生图',
      url: endpoint,
      status: response.status,
      statusText: response.statusText,
      body: detail,
      request,
    });
    throw new Error(`SD WebUI 请求失败 (HTTP ${response.status})：${detail}。请确认 WebUI 以 --api --cors-allow-origins=* 启动。`);
  }
  return decodeImagePayload(response, {
    stage: 'SD WebUI 生图',
    url: endpoint,
    request,
  });
}

