function isNovelAiV4Model(model: string): boolean {
  // v4、v4.5、v5 及更高版本都使用相同的结构化API格式（base_caption、char_captions等）
  // v3 使用旧版简单格式（input、negative_prompt）
  return model.startsWith('nai-diffusion-4') || model.startsWith('nai-diffusion-5');
}

/** NAI v4 多角色结构化提示词中的单个角色。 */
export interface NovelAiCharacterPrompt {
  readonly prompt: string;
  readonly uc: string;
  /** 九宫格中心位置（NAI PositionMap：0.1/0.3/0.5/0.7/0.9）；未指定时为 null。 */
  readonly center: { readonly x: number; readonly y: number } | null;
}

export interface NovelAiStructuredPrompt {
  /** 场景构图（Scene Composition），作为 base_caption。 */
  readonly scene: string;
  readonly characters: readonly NovelAiCharacterPrompt[];
}

const POSITION_STEPS = [0.1, 0.3, 0.5, 0.7, 0.9] as const;

/** 把 a~e 列 + 1~5 行的九宫格代号（如 c3）转为 NAI 坐标。 */
function centerFromCode(column: string, row: string): { x: number; y: number } | null {
  const x = POSITION_STEPS[column.toLowerCase().charCodeAt(0) - 97];
  const y = POSITION_STEPS[Number(row) - 1];
  if (x === undefined || y === undefined) return null;
  return { x, y };
}

/**
 * 解析 NAI 多角色结构化提示词（参考油猴 NAI4 世界书的格式）：
 * Scene Composition:场景tag;Character 1 Prompt:角色tag|centers:c3;Character 1 UC:负面tag;Character 2 Prompt:...;
 * 段落用分号分隔、顺序不限；没有识别到结构化段落时返回 null（按普通单串提示词处理）。
 */
export function parseNovelAiStructuredPrompt(prompt: string): NovelAiStructuredPrompt | null {
  const segments = prompt.split(/;/).map((part) => part.trim()).filter(Boolean);
  let scene = '';
  const characterMap = new Map<number, { prompt: string; uc: string; center: { x: number; y: number } | null }>();
  let structured = false;

  for (const segment of segments) {
    const sceneMatch = /^scene\s*composition\s*[:：]([\s\S]*)$/i.exec(segment);
    if (sceneMatch) {
      scene = (sceneMatch[1] ?? '').trim();
      structured = true;
      continue;
    }
    const promptMatch = /^character\s*(\d)\s*prompt\s*[:：]([\s\S]*)$/i.exec(segment);
    if (promptMatch) {
      const index = Number(promptMatch[1]);
      let body = (promptMatch[2] ?? '').trim();
      let center: { x: number; y: number } | null = null;
      const centerMatch = /\|\s*centers?\s*[:：]\s*([a-e])\s*([1-5])\s*$/i.exec(body);
      if (centerMatch) {
        center = centerFromCode(centerMatch[1] ?? '', centerMatch[2] ?? '');
        body = body.slice(0, centerMatch.index).trim().replace(/[,，]\s*$/, '');
      }
      const existing = characterMap.get(index) ?? { prompt: '', uc: '', center: null };
      characterMap.set(index, { ...existing, prompt: body, center: center ?? existing.center });
      structured = true;
      continue;
    }
    const ucMatch = /^character\s*(\d)\s*uc\s*[:：]([\s\S]*)$/i.exec(segment);
    if (ucMatch) {
      const index = Number(ucMatch[1]);
      const existing = characterMap.get(index) ?? { prompt: '', uc: '', center: null };
      characterMap.set(index, { ...existing, uc: (ucMatch[2] ?? '').trim() });
      structured = true;
      continue;
    }
    // 不认识的段落：若尚未识别出场景描述，则并入场景，避免丢内容。
    if (structured && !scene) scene = segment;
  }

  if (!structured) return null;
  const characters = [...characterMap.entries()]
    .sort(([a], [b]) => a - b)
    .map(([, value]) => value)
    .filter((item) => item.prompt.length > 0);
  return { scene, characters };
}

/** 把结构化提示词拍平为单串（v3 模型或非 NAI 供应商使用）。 */
export function flattenNovelAiStructuredPrompt(structured: NovelAiStructuredPrompt): string {
  return [structured.scene, ...structured.characters.map((item) => item.prompt)]
    .filter(Boolean)
    .join(', ');
}

/** 角色一致性解析所需的最小档案信息。 */
export interface ConsistencyProfile {
  readonly displayName: string;
  readonly twitterName?: string;
  readonly boundCharacter?: string;
  readonly appearancePrompt?: string;
  readonly imageRefUrl?: string;
  readonly imageRefStrength?: number;
}

/** 角色参考图（已解析强度；dataUrl 在发送前再缩放编码）。 */
export interface CharacterReferenceInput {
  readonly dataUrl: string;
  readonly strength: number;
}

export interface ConsistencyResolution {
  readonly prompt: string;
  readonly references: readonly CharacterReferenceInput[];
}

const CHARACTER_MENTION_PATTERN = /@([^,，;；|#()\s][^,，;；|#]{0,39})/g;
const DEFAULT_REFERENCE_STRENGTH = 0.75;
const MAX_CHARACTER_REFERENCES = 4;

/**
 * 角色生图一致性：把提示词中的 @角色名 引用替换为该角色的素体提示词
 * （固定外貌 tag），并收集配置了参考图的角色，供 NAI Character Reference 使用。
 * 匹配备注名 / 推特昵称 / 绑定角色名（不区分大小写）；
 * 未匹配到档案或素体为空时移除 @名字，避免非英文名字混入生图提示词。
 */
export function resolveCharacterConsistency(
  prompt: string,
  profiles: readonly ConsistencyProfile[],
): ConsistencyResolution {
  const lookup = new Map<string, ConsistencyProfile>();
  for (const profile of profiles) {
    for (const name of [profile.displayName, profile.twitterName, profile.boundCharacter]) {
      const key = name?.trim().toLowerCase();
      if (key && !lookup.has(key)) lookup.set(key, profile);
    }
  }
  const references: CharacterReferenceInput[] = [];
  const seenRefs = new Set<ConsistencyProfile>();
  const collectReference = (profile: ConsistencyProfile): void => {
    if (!profile.imageRefUrl || seenRefs.has(profile) || references.length >= MAX_CHARACTER_REFERENCES) return;
    seenRefs.add(profile);
    references.push({
      dataUrl: profile.imageRefUrl,
      strength: profile.imageRefStrength ?? DEFAULT_REFERENCE_STRENGTH,
    });
  };
  CHARACTER_MENTION_PATTERN.lastIndex = 0;
  const resolved = prompt.replace(CHARACTER_MENTION_PATTERN, (_whole, rawName: string) => {
    // 名字可能后跟空格分隔的额外 tag（如 @小雪 selfie），从整段开始递减匹配。
    const raw = rawName.trim();
    let candidate = raw;
    let rest = '';
    while (candidate) {
      const profile = lookup.get(candidate.toLowerCase());
      if (profile) {
        collectReference(profile);
        const appearance = profile.appearancePrompt?.trim() ?? '';
        const suffix = rest.trim();
        if (appearance && suffix) return `${appearance}, ${suffix}`;
        return appearance || suffix;
      }
      const spaceIndex = candidate.lastIndexOf(' ');
      if (spaceIndex < 0) break;
      rest = candidate.slice(spaceIndex) + rest;
      candidate = candidate.slice(0, spaceIndex).trimEnd();
    }
    // 未匹配到档案：丢弃名字（第一个词），保留其后的 tag。
    return raw.split(/\s+/).slice(1).join(' ');
  })
    // 清理替换后遗留的空标签（连续逗号、段首/段尾逗号）。
    .replace(/,\s*(?:,\s*)+/g, ', ')
    .replace(/([:;])\s*,\s*/g, '$1')
    .replace(/,\s*([;#])/g, '$1')
    .replace(/^\s*,\s*/, '')
    .trim();
  return { prompt: resolved, references };
}

/**
 * 解析 NovelAI 请求地址。
 * - 官网：使用 SillyTavern 同源代理 /api/novelai/generate-image，避免浏览器跨域预检失败。
 * - 公益站 / 自定义：使用用户填写的地址；若地址中已包含 generate-image 则原样使用，
 *   否则自动拼接 /ai/generate-image（与 st-chatu8 的站点兼容策略一致）。
 */
export function resolveNovelAiEndpoint(config: ImageGenerationSettings): string {
  const site = config.novelaiSite || 'official';
  if (site === 'official') return NOVELAI_TAVERN_ENDPOINT;
  const base = config.baseUrl.trim().replace(/\/+$/, '');
  if (!base) {
    throw new Error(site === 'community'
      ? '公益站模式需要填写站点地址（例如 https://xxx.example.com）。'
      : '自定义站点模式需要填写接口地址。');
  }
  return /generate-image/i.test(base) ? base : `${base}/ai/generate-image`;
}

/** 已编码好的角色参考图（裸 base64）。 */
export interface EncodedCharacterReference {
  readonly data: string;
  readonly strength: number;
}

/**
 * 参考图预处理：缩放到 NAI Character Reference 支持的三档尺寸
 * （1024×1536 / 1472×1472 / 1536×1024，按宽高比选最接近的），输出裸 base64。
 */
async function encodeReferenceImage(dataUrl: string): Promise<string> {
  const image = await new Promise<HTMLImageElement>((resolve, reject) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => reject(new Error('角色参考图加载失败。'));
    img.src = dataUrl;
  });
  const targets = [
    { width: 1024, height: 1536 },
    { width: 1472, height: 1472 },
    { width: 1536, height: 1024 },
  ];
  const ratio = image.width / image.height;
  let selected = targets[0]!;
  let minDiff = Math.abs(ratio - selected.width / selected.height);
  for (const target of targets.slice(1)) {
    const diff = Math.abs(ratio - target.width / target.height);
    if (diff < minDiff) {
      minDiff = diff;
      selected = target;
    }
  }
  const canvas = document.createElement('canvas');
  canvas.width = selected.width;
  canvas.height = selected.height;
  const context = canvas.getContext('2d');
  if (!context) throw new Error('无法创建画布处理参考图。');
  context.imageSmoothingEnabled = true;
  context.imageSmoothingQuality = 'high';
  context.drawImage(image, 0, 0, selected.width, selected.height);
  return canvas.toDataURL('image/png').replace(/^data:image\/png;base64,/, '');
}

/** 构造 NAI 请求的 input / parameters（导出供测试）。 */
export function buildNovelAiRequestBody(
  config: ImageGenerationSettings,
  prompt: string,
  seed = Math.floor(Math.random() * 4294967295),
  references: readonly EncodedCharacterReference[] = [],
): { readonly input: string; readonly model: string; readonly parameters: Record<string, unknown> } {
  const model = config.model || 'nai-diffusion-4-5-full';
  const negative = config.negativePrompt;
  const structured = parseNovelAiStructuredPrompt(prompt);

  if (!isNovelAiV4Model(model)) {
    // v3：结构化提示词拍平为单串，角色 UC 合并进负面。
    const flat = mergePositivePrompt(config, structured ? flattenNovelAiStructuredPrompt(structured) : prompt);
    const mergedNegative = structured
      ? [negative, ...structured.characters.map((item) => item.uc)].filter(Boolean).join(', ')
      : negative;
    return {
      input: flat,
      model,
      parameters: {
        width: config.width,
        height: config.height,
        steps: config.steps,
        scale: config.cfgScale,
        sampler: config.sampler || 'k_euler_ancestral',
        ...(config.scheduler ? { noise_schedule: config.scheduler } : {}),
        n_samples: 1,
        negative_prompt: mergedNegative,
        qualityToggle: true,
        stream: 'msgpack',
        seed,
      },
    };
  }

  // v4/v4.5：base_caption 使用场景构图，角色进 char_captions（多角色 + 九宫格位置）。
  const baseCaption = mergePositivePrompt(config, structured ? structured.scene : prompt);
  const characters = structured?.characters ?? [];
  const hasExplicitCenter = characters.some((item) => item.center !== null);
  const DEFAULT_CENTER = { x: 0.5, y: 0.5 };
  const charCaptions = characters.map((item) => ({
    char_caption: item.prompt,
    centers: [item.center ?? DEFAULT_CENTER],
  }));
  const charNegativeCaptions = characters.map((item) => ({
    char_caption: item.uc,
    centers: [item.center ?? DEFAULT_CENTER],
  }));
  const characterPrompts = characters.map((item) => ({
    prompt: item.prompt,
    uc: item.uc,
    center: item.center ?? DEFAULT_CENTER,
    enabled: true,
  }));
  // 角色参考图（Character Reference）：director_reference_* 五个数组一一对应。
  const referenceFields = references.length > 0
    ? {
        director_reference_images_cached: references.map((item) => ({
          cache_secret_key: randomUuid(),
          data: item.data,
        })),
        director_reference_descriptions: references.map(() => ({
          caption: { base_caption: 'character', char_captions: [] },
          legacy_uc: false,
        })),
        director_reference_information_extracted: references.map(() => 1),
        director_reference_strength_values: references.map((item) => item.strength),
        director_reference_secondary_strength_values: references.map((item) => 1 - item.strength),
      }
    : {};
  return {
    input: baseCaption,
    model,
    parameters: {
      params_version: 3,
      width: config.width,
      height: config.height,
      steps: config.steps,
      scale: config.cfgScale,
      sampler: config.sampler || 'k_euler_ancestral',
      noise_schedule: config.scheduler || 'karras',
      n_samples: 1,
      seed,
      ucPreset: 0,
      qualityToggle: true,
      dynamic_thresholding: false,
      legacy: false,
      use_coords: hasExplicitCenter,
      legacy_uc: false,
      negative_prompt: negative,
      stream: 'msgpack',
      characterPrompts,
      v4_prompt: {
        caption: { base_caption: baseCaption, char_captions: charCaptions },
        use_coords: hasExplicitCenter,
        use_order: true,
      },
      v4_negative_prompt: {
        caption: { base_caption: negative, char_captions: charNegativeCaptions },
        legacy_uc: false,
      },
      ...referenceFields,
    },
  };
}

function randomUuid(): string {
  if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
  return `${Date.now().toString(16)}-${Math.random().toString(16).slice(2)}`;
}

let syncedNovelAiToken = '';

function normalizeNovelAiToken(value: string): string {
  return value.trim().replace(/^Bearer\s+/i, '');
}

async function syncNovelAiTokenToTavern(rawToken: string): Promise<void> {
  const token = normalizeNovelAiToken(rawToken);
  if (!token) throw new NovelAiRequestError('NovelAI 官网生图需要填写 API Token（pst-...）。', false);
  if (token === syncedNovelAiToken) return;
  let response: Response;
  try {
    response = await fetchImageResponse({
      stage: 'NovelAI Token 同步',
      url: NOVELAI_SECRET_ENDPOINT,
      request: { provider: 'novelai', operation: 'sync-token' },
      sameOrigin: true,
    }, {
      method: 'POST',
      headers: getSillyTavernRequestHeaders(),
      body: JSON.stringify({
        key: NOVELAI_SECRET_KEY,
        value: token,
        label: '墨韵手机 NovelAI Token',
      }),
    });
  } catch (error) {
    throw new NovelAiRequestError(error instanceof Error ? error.message : String(error), true);
  }
  if (!response.ok) {
    const detail = await readErrorText(response);
    logHttpFailure({
      stage: 'NovelAI Token 同步',
      url: NOVELAI_SECRET_ENDPOINT,
      status: response.status,
      statusText: response.statusText,
      body: detail,
      request: { provider: 'novelai', operation: 'sync-token' },
    });
    throw new NovelAiRequestError(
      `无法将 NovelAI Token 写入 SillyTavern 密钥库 (HTTP ${response.status})：${detail}`,
      isRetryableNovelAiStatus(response.status),
    );
  }
  syncedNovelAiToken = token;
}

function buildNovelAiTavernRequestBody(
  config: ImageGenerationSettings,
  prompt: string,
  body: ReturnType<typeof buildNovelAiRequestBody>,
): Record<string, unknown> {
  const parameters = body.parameters;
  const structured = parseNovelAiStructuredPrompt(prompt);
  const v4 = isNovelAiV4Model(body.model);
  const proxyPrompt = v4 && structured
    ? mergePositivePrompt(config, flattenNovelAiStructuredPrompt(structured))
    : body.input;
  const parameterNegative = String(parameters.negative_prompt ?? config.negativePrompt);
  const proxyNegative = v4 && structured
    ? [parameterNegative, ...structured.characters.map((character) => character.uc)].filter(Boolean).join(', ')
    : parameterNegative;
  return {
    prompt: proxyPrompt,
    model: body.model,
    sampler: parameters.sampler ?? (config.sampler || 'k_euler_ancestral'),
    scheduler: parameters.noise_schedule ?? (config.scheduler || 'karras'),
    steps: parameters.steps ?? config.steps,
    scale: parameters.scale ?? config.cfgScale,
    width: parameters.width ?? config.width,
    height: parameters.height ?? config.height,
    negative_prompt: proxyNegative,
    decrisper: parameters.dynamic_thresholding ?? false,
    variety_boost: parameters.skip_cfg_above_sigma ?? false,
    sm: parameters.sm ?? false,
    sm_dyn: parameters.sm_dyn ?? false,
    seed: parameters.seed ?? Math.floor(Math.random() * 4294967295),
  };
}

async function generateWithNovelAi(
  config: ImageGenerationSettings,
  prompt: string,
  characterReferences: readonly CharacterReferenceInput[] = [],
): Promise<string> {
  // 本地串行在最外层；每次重试重新获取并释放共享排队名额，避免网络失败时长期占锁。
  return runNovelAiExclusive(() => withNovelAiRetry(async () => {
    try {
      return await withNovelAiQueue(
        config,
        () => attemptNovelAiGeneration(config, prompt, characterReferences),
      );
    } catch (error) {
      return {
        ok: false,
        retryable: error instanceof Error
          && (error as Error & { readonly retryable?: boolean }).retryable === true,
        message: error instanceof Error ? error.message : String(error),
      };
    }
  }));
}

async function attemptNovelAiGeneration(
  config: ImageGenerationSettings,
  prompt: string,
  characterReferences: readonly CharacterReferenceInput[] = [],
): Promise<NovelAiAttempt<string>> {
  const site = config.novelaiSite || 'official';
  if (site === 'official' && !config.apiKey) {
    return { ok: false, retryable: false, message: 'NovelAI 官网生图需要填写 API Token（pst-...）。' };
  }
  let endpoint: string;
  try {
    endpoint = resolveNovelAiEndpoint(config);
  } catch (error) {
    return { ok: false, retryable: false, message: error instanceof Error ? error.message : String(error) };
  }
  const encodedReferences: EncodedCharacterReference[] = [];
  if (site !== 'official'
    && characterReferences.length > 0
    && isNovelAiV4Model(config.model || 'nai-diffusion-4-5-full')) {
    for (const [index, reference] of characterReferences.entries()) {
      try {
        encodedReferences.push({ data: await encodeReferenceImage(reference.dataUrl), strength: reference.strength });
      } catch (error) {
        logOperationFailure({
          stage: 'NovelAI 角色参考图',
          reason: `第 ${index + 1} 张参考图无法编码，已跳过`,
          context: imageRequestSummary(config, { site }),
          error,
        });
      }
    }
  } else if (characterReferences.length > 0) {
    logOperationFailure({
      stage: 'NovelAI 角色参考图',
      reason: site === 'official' ? '官网酒馆代理不接收角色参考图数组，已跳过' : '当前模型不支持角色参考图，已跳过',
      context: imageRequestSummary(config, { site }),
    });
  }
  const body = buildNovelAiRequestBody(config, prompt, undefined, encodedReferences);

  try {
    if (site === 'official') {
      await syncNovelAiTokenToTavern(config.apiKey);
      const response = await fetchImageResponse({
        stage: 'NovelAI 官网生图（酒馆代理）',
        url: endpoint,
        request: imageRequestSummary(config, { site, route: 'sillytavern-proxy' }),
        sameOrigin: true,
      }, {
        method: 'POST',
        headers: getSillyTavernRequestHeaders(),
        body: JSON.stringify(buildNovelAiTavernRequestBody(config, prompt, body)),
      });
      if (!response.ok) {
        const detail = await readErrorText(response);
        logHttpFailure({
          stage: 'NovelAI 官网生图（酒馆代理）',
          url: endpoint,
          status: response.status,
          statusText: response.statusText,
          body: detail,
          request: imageRequestSummary(config, { site, route: 'sillytavern-proxy' }),
        });
        if (response.status === 400) {
          syncedNovelAiToken = '';
          return {
            ok: false,
            retryable: true,
            retryAfterMs: 0,
            message: `NovelAI 官网请求失败 (HTTP 400)：酒馆服务端未读取到 Token，请重试或检查 SillyTavern 密钥库。${detail}`,
          };
        }
        const retryable = isRetryableNovelAiStatus(response.status);
        return {
          ok: false,
          retryable,
          message: `NovelAI 官网请求失败 (HTTP ${response.status})：${detail}。${retryable
            ? 'NovelAI 同一时刻只允许一张图在生成，自动重试后仍失败；请稍等几秒再点，并检查 SillyTavern 服务端控制台中的 NovelAI 错误。'
            : '请同时检查 SillyTavern 服务端控制台中的 NovelAI 错误。'}`,
        };
      }
      try {
        return {
          ok: true,
          value: await decodeImagePayload(response, {
            stage: 'NovelAI 官网生图（酒馆代理）',
            url: endpoint,
            request: imageRequestSummary(config, { site, route: 'sillytavern-proxy' }),
          }),
        };
      } catch (error) {
        return {
          ok: false,
          retryable: isRetryableImagePayloadError(error),
          message: error instanceof Error ? error.message : `NovelAI 官网返回格式错误：${describeError(error)}`,
        };
      }
    }

    const headers: Record<string, string> = { 'Content-Type': 'application/json' };
    if (config.apiKey) {
      headers.Authorization = config.apiKey.startsWith('Bearer ') ? config.apiKey : `Bearer ${config.apiKey}`;
    }
    const response = await fetchImageResponse({
      stage: 'NovelAI 站点生图',
      url: endpoint,
      request: imageRequestSummary(config, { site, route: 'direct' }),
      sameOrigin: false,
    }, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        input: body.input,
        model: body.model,
        action: 'generate',
        parameters: body.parameters,
      }),
    });
    if (!response.ok) {
      const detail = await readErrorText(response);
      logHttpFailure({
        stage: 'NovelAI 站点生图',
        url: endpoint,
        status: response.status,
        statusText: response.statusText,
        body: detail,
        request: imageRequestSummary(config, { site, route: 'direct' }),
      });
      if (response.status === 404) {
        return {
          ok: false,
          retryable: false,
          message: `NovelAI 请求失败 (HTTP 404)：${detail}。接口路径不存在——请检查站点类型与地址：官网无需填地址；公益站/自定义填站点根地址（自动拼接 /ai/generate-image），如果站点路径特殊，请直接填完整的 generate-image 地址。`,
        };
      }
      if (response.status === 401) {
        return { ok: false, retryable: false, message: 'NovelAI 请求失败 (HTTP 401)：API Token 无效或已过期，请检查 Token。' };
      }
      if (response.status === 402) {
        return { ok: false, retryable: false, message: 'NovelAI 请求失败 (HTTP 402)：当前订阅等级无法使用该模型或尺寸。' };
      }
      const retryable = isRetryableNovelAiStatus(response.status);
      return {
        ok: false,
        retryable,
        message: `NovelAI 请求失败 (HTTP ${response.status})：${detail}${retryable
          ? '。这是可恢复的限流或服务端/网关错误；有限重试后仍失败，请稍后再试。'
          : ''}`,
      };
    }
    try {
      return {
        ok: true,
        value: await decodeImagePayload(response, {
          stage: 'NovelAI 站点生图',
          url: endpoint,
          request: imageRequestSummary(config, { site, route: 'direct' }),
        }),
      };
    } catch (error) {
      return {
        ok: false,
        retryable: isRetryableImagePayloadError(error),
        message: error instanceof Error ? error.message : `NovelAI 站点返回格式错误：${describeError(error)}`,
      };
    }
  } catch (error) {
    if (error instanceof NovelAiRequestError) {
      return { ok: false, retryable: error.retryable, message: error.message };
    }
    if (error instanceof ImageNetworkError) {
      return { ok: false, retryable: true, message: error.message };
    }
    logHttpFailure({
      stage: site === 'official' ? 'NovelAI 官网生图' : 'NovelAI 站点生图',
      url: endpoint,
      request: imageRequestSummary(config, { site }),
      error,
    });
    return { ok: false, retryable: false, message: `NovelAI 生图失败：${describeError(error)}` };
  }
}

async function generateWithComfyUi(config: ImageGenerationSettings, prompt: string): Promise<string> {
  if (!config.baseUrl) throw new Error('请填写 ComfyUI 地址（例如 http://127.0.0.1:8188）。');
  if (!config.model) throw new Error('ComfyUI 需要填写 checkpoint 文件名（例如 sd_xl_base_1.0.safetensors）。');
  const clientId = `narrative-phone-${Math.random().toString(36).slice(2)}`;
  const workflow = buildComfyWorkflow(config, prompt);
  const submitUrl = `${config.baseUrl}/prompt`;
  const request = imageRequestSummary(config, { route: 'prompt' });
  const submit = await fetchImageResponse({
    stage: 'ComfyUI 提交',
    url: submitUrl,
    request,
    sameOrigin: false,
  }, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ prompt: workflow, client_id: clientId }),
  });
  if (!submit.ok) {
    const detail = await readErrorText(submit);
    logHttpFailure({
      stage: 'ComfyUI 提交',
      url: submitUrl,
      status: submit.status,
      statusText: submit.statusText,
      body: detail,
      request,
    });
    throw new Error(`ComfyUI 提交失败 (HTTP ${submit.status})：${detail}。请确认 ComfyUI 以 --enable-cors-header 启动。`);
  }
  let promptId: string | undefined;
  try {
    const submitted = await submit.json() as { readonly prompt_id?: string };
    promptId = submitted.prompt_id;
    if (!promptId) throw new Error('ComfyUI 未返回任务 ID。');
  } catch (error) {
    logHttpFailure({ stage: 'ComfyUI 提交响应解码', url: submitUrl, request, error });
    throw error;
  }

  const deadline = Date.now() + COMFYUI_TIMEOUT_MS;
  const historyUrl = `${config.baseUrl}/history/${promptId}`;
  while (Date.now() < deadline) {
    await sleep(COMFYUI_POLL_INTERVAL_MS);
    const historyResponse = await fetchImageResponse({
      stage: 'ComfyUI 任务轮询',
      url: historyUrl,
      request: imageRequestSummary(config, { route: 'history', promptId }),
      sameOrigin: false,
    });
    if (!historyResponse.ok) {
      const detail = await readErrorText(historyResponse);
      logHttpFailure({
        stage: 'ComfyUI 任务轮询',
        url: historyUrl,
        status: historyResponse.status,
        statusText: historyResponse.statusText,
        body: detail,
        request: imageRequestSummary(config, { route: 'history', promptId }),
      });
      continue;
    }
    let history: Record<string, {
      readonly outputs?: Record<string, { readonly images?: readonly { filename: string; subfolder: string; type: string }[] }>;
    }>;
    try {
      history = await historyResponse.json() as typeof history;
    } catch (error) {
      logHttpFailure({
        stage: 'ComfyUI 任务响应解码',
        url: historyUrl,
        request: imageRequestSummary(config, { route: 'history', promptId }),
        error,
      });
      throw error;
    }
    const outputs = history[promptId]?.outputs;
    if (!outputs) continue;
    for (const node of Object.values(outputs)) {
      const image = node.images?.[0];
      if (image) {
        const params = new URLSearchParams({
          filename: image.filename,
          subfolder: image.subfolder ?? '',
          type: image.type ?? 'output',
        });
        return `${config.baseUrl}/view?${params.toString()}`;
      }
    }
  }
  logOperationFailure({
    stage: 'ComfyUI 生图',
    reason: '等待任务 180 秒仍未返回图片',
    context: imageRequestSummary(config, { promptId }),
  });
  throw new Error('ComfyUI 生成超时（180 秒）。');
}

function buildComfyWorkflow(config: ImageGenerationSettings, prompt: string): Record<string, unknown> {
  return {
    '3': {
      class_type: 'KSampler',
      inputs: {
        cfg: config.cfgScale,
        denoise: 1,
        latent_image: ['5', 0],
        model: ['4', 0],
        negative: ['7', 0],
        positive: ['6', 0],
        sampler_name: config.sampler || 'euler',
        scheduler: config.scheduler || 'normal',
        seed: Math.floor(Math.random() * 1e15),
        steps: config.steps,
      },
    },
    '4': { class_type: 'CheckpointLoaderSimple', inputs: { ckpt_name: config.model } },
    '5': { class_type: 'EmptyLatentImage', inputs: { batch_size: 1, height: config.height, width: config.width } },
    '6': { class_type: 'CLIPTextEncode', inputs: { clip: ['4', 1], text: prompt } },
    '7': { class_type: 'CLIPTextEncode', inputs: { clip: ['4', 1], text: config.negativePrompt } },
    '8': { class_type: 'VAEDecode', inputs: { samples: ['3', 0], vae: ['4', 2] } },
    '9': { class_type: 'SaveImage', inputs: { filename_prefix: 'narrative-phone', images: ['8', 0] } },
  };
}

async function readErrorText(response: Response): Promise<string> {
  try {
    const text = await response.text();
    try {
      const parsed = JSON.parse(text) as { error?: { message?: string } | string; message?: string };
      const message = typeof parsed.error === 'string'
        ? parsed.error
        : parsed.error?.message ?? parsed.message;
      if (message) return String(message).slice(0, 300);
    } catch {
      // 保留纯文本错误。
    }
    return text.replace(/\s+/g, ' ').slice(0, 300) || '无错误详情';
  } catch {
    return '无法读取错误详情';
  }
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}
