/** 有界的语法树分析：只读取 schema 和字面量表达式，绝不加载或运行角色脚本。 */
import { parse, type AnyNode, type Expression, type Function as AstFunction } from 'acorn';
import { keyFlagsOf, makeLeaf, OPEN_KEY_FLAGS, type MvuKeyFlags } from './init-var.js';
import { isMvuScalar, type MvuLeafValue } from './mvu-tuple.js';
import type { MvuGroupNode, MvuNode, MvuTree, MvuValueConstraints } from './types.js';

const UNKNOWN = Symbol('unresolved-literal');
type Binding = { node: AnyNode; env: Env } | { value: unknown };
type Env = Map<string, Binding>;
const blockedKeys = new Set(['__proto__', 'prototype', 'constructor']);
const isObject = (value: unknown): value is Record<string, unknown> => !!value && typeof value === 'object' && !Array.isArray(value);
function walk(node: AnyNode, visit: (node: AnyNode) => void): void {
  visit(node);
  for (const value of Object.values(node)) {
    if (Array.isArray(value)) { for (const item of value) if (isObject(item) && typeof item.type === 'string') walk(item as unknown as AnyNode, visit); }
    else if (isObject(value) && typeof value.type === 'string') walk(value as unknown as AnyNode, visit);
  }
}
function methodName(node: AnyNode | undefined): string {
  if (node?.type !== 'MemberExpression') return '';
  return !node.computed && node.property.type === 'Identifier' ? node.property.name
    : node.property.type === 'Literal' && typeof node.property.value === 'string' ? node.property.value : '';
}
function functionNode(node: AnyNode | undefined): node is (AnyNode & AstFunction) {
  return !!node && ['ArrowFunctionExpression', 'FunctionExpression', 'FunctionDeclaration'].includes(node.type);
}
function returned(fn: AstFunction): AnyNode | undefined {
  if (fn.body.type !== 'BlockStatement') return fn.body;
  const statement = [...fn.body.body].reverse().find((item) => item.type === 'ReturnStatement');
  return statement?.type === 'ReturnStatement' ? statement.argument ?? undefined : undefined;
}

class SchemaReader {
  readonly env: Env = new Map();
  readonly issues = new Set<string>();
  #remaining = 100_000;
  constructor(readonly source: string) {}

  #tick(depth: number): void {
    if (depth > 100 || --this.#remaining <= 0) throw new Error('变量结构超过静态分析预算，请拆分循环引用或过深结构。');
  }

  /** 只计算白名单内的纯字面量操作，未知调用返回 UNKNOWN。 */
  literal(node: AnyNode | undefined, env = this.env, depth = 0): unknown {
    this.#tick(depth);
    if (!node) return undefined;
    const read = (child: AnyNode | undefined): unknown => this.literal(child, env, depth + 1);
    if (node.type === 'Literal') return node.regex || node.bigint ? UNKNOWN : node.value;
    if (node.type === 'Identifier') {
      if (node.name === 'undefined') return undefined;
      if (node.name === 'Infinity') return Infinity;
      if (node.name === 'NaN') return NaN;
      const binding = env.get(node.name);
      return binding ? 'value' in binding ? binding.value : this.literal(binding.node, binding.env, depth + 1) : UNKNOWN;
    }
    if (node.type === 'TemplateLiteral') {
      const values = node.expressions.map(read);
      return values.includes(UNKNOWN) ? UNKNOWN : node.quasis.map((part, i) => (part.value.cooked ?? part.value.raw) + (i < values.length ? String(values[i]) : '')).join('');
    }
    if (node.type === 'ArrayExpression') {
      const result: unknown[] = [];
      for (const item of node.elements) {
        if (!item) { result.push(null); continue; }
        const value = read(item.type === 'SpreadElement' ? item.argument : item);
        if (value === UNKNOWN || (item.type === 'SpreadElement' && !Array.isArray(value))) return UNKNOWN;
        if (item.type === 'SpreadElement') result.push(...value as unknown[]); else result.push(value);
      }
      return result;
    }
    if (node.type === 'ObjectExpression') {
      const result: Record<string, unknown> = Object.create(null) as Record<string, unknown>;
      for (const prop of node.properties) {
        if (prop.type === 'SpreadElement') {
          const value = read(prop.argument);
          if (!isObject(value)) return UNKNOWN;
          for (const [key, entry] of Object.entries(value)) if (!blockedKeys.has(key)) result[key] = entry;
          continue;
        }
        if (prop.kind !== 'init' || prop.method) return UNKNOWN;
        const key = !prop.computed && prop.key.type === 'Identifier' ? prop.key.name : read(prop.key);
        const value = read(prop.value);
        if (key === UNKNOWN || value === UNKNOWN || typeof key !== 'string' && typeof key !== 'number') return UNKNOWN;
        if (!blockedKeys.has(String(key))) result[String(key)] = value;
      }
      return result;
    }
    if (node.type === 'MemberExpression') {
      const key = !node.computed && node.property.type === 'Identifier' ? node.property.name : read(node.property);
      if (typeof key !== 'string' && typeof key !== 'number' || blockedKeys.has(String(key))) return UNKNOWN;
      if (node.object.type === 'Identifier' && node.object.name === 'Number' && key === 'MAX_SAFE_INTEGER') return Number.MAX_SAFE_INTEGER;
      const object = read(node.object);
      return (isObject(object) || Array.isArray(object)) && Object.hasOwn(object, key) ? (object as Record<string | number, unknown>)[key]
        : object !== UNKNOWN && (object === undefined || object === null || isObject(object)) ? undefined : UNKNOWN;
    }
    if (node.type === 'UnaryExpression') {
      const value = read(node.argument);
      if (value === UNKNOWN) return UNKNOWN;
      if (node.operator === '-') return -Number(value);
      if (node.operator === '+') return Number(value);
      if (node.operator === '!') return !value;
      if (node.operator === 'typeof') return typeof value;
      if (node.operator === 'void') return undefined;
      return UNKNOWN;
    }
    if (node.type === 'ConditionalExpression') {
      const test = read(node.test);
      return test === UNKNOWN ? UNKNOWN : read(test ? node.consequent : node.alternate);
    }
    if (node.type === 'LogicalExpression') {
      const left = read(node.left);
      if (left === UNKNOWN) return UNKNOWN;
      return node.operator === '??' ? left ?? read(node.right) : node.operator === '||' ? left || read(node.right) : left && read(node.right);
    }
    if (node.type === 'BinaryExpression') {
      const left = read(node.left), right = read(node.right);
      if (left === UNKNOWN || right === UNKNOWN) return UNKNOWN;
      switch (node.operator) {
        case '==': return left == right;
        case '!=': return left != right;
        case '===': return left === right;
        case '!==': return left !== right;
        case '+': return typeof left === 'string' || typeof right === 'string' ? String(left) + String(right) : Number(left) + Number(right);
        case '-': return Number(left) - Number(right);
        case '*': return Number(left) * Number(right);
        case '/': return Number(left) / Number(right);
        case '>': return Number(left) > Number(right);
        case '<': return Number(left) < Number(right);
        case '>=': return Number(left) >= Number(right);
        case '<=': return Number(left) <= Number(right);
        default: return UNKNOWN;
      }
    }
    if (node.type === 'CallExpression') {
      const args = node.arguments.map(read);
      if (args.includes(UNKNOWN)) return UNKNOWN;
      const name = methodName(node.callee);
      const owner = node.callee.type === 'MemberExpression' && node.callee.object.type === 'Identifier' ? node.callee.object.name : '';
      if (owner === 'Object' && name === 'freeze') return args[0];
      if (owner === 'Array' && name === 'isArray') return Array.isArray(args[0]);
      if (owner === 'Number' && name === 'isNaN') return Number.isNaN(args[0]);
      if (node.callee.type === 'Identifier' && ['String', 'Number', 'Boolean'].includes(node.callee.name)) {
        return node.callee.name === 'String' ? String(args[0]) : node.callee.name === 'Number' ? Number(args[0]) : Boolean(args[0]);
      }
      if (name === 'includes' && node.callee.type === 'MemberExpression') {
        const object = read(node.callee.object);
        if (Array.isArray(object)) return object.includes(args[0]);
      }
    }
    return UNKNOWN;
  }

  bind(fn: AstFunction, args: readonly AnyNode[], env: Env, lexical = env): Env {
    const local = new Map(lexical);
    fn.params.forEach((param, index) => {
      const target = param.type === 'AssignmentPattern' ? param.left : param;
      if (target.type !== 'Identifier') return;
      const argument = args[index];
      const defaultNode = param.type === 'AssignmentPattern' ? param.right : undefined;
      const binding: Binding = argument ? { node: argument, env } : defaultNode ? { node: defaultNode, env: local } : { value: undefined };
      local.set(target.name, binding);
    });
    if (fn.body.type === 'BlockStatement') for (const statement of fn.body.body) {
      if (statement.type === 'VariableDeclaration') for (const decl of statement.declarations) {
        if (decl.id.type === 'Identifier' && decl.init) local.set(decl.id.name, { node: decl.init, env: local });
      }
    }
    return local;
  }

  defaultValue(schema: MvuNode, value: unknown): MvuNode {
    if (value === UNKNOWN || value === undefined) return schema;
    if (schema.kind === 'leaf') {
      const cell: MvuLeafValue = schema.valueType === 'json' ? JSON.stringify(value)
        : Array.isArray(value) ? value.filter(isMvuScalar) : isMvuScalar(value) ? value : schema.value;
      return { ...schema, value: cell };
    }
    if (!isObject(value)) return schema;
    if (schema.record && schema.template) return { ...schema, present: true, entries: Object.entries(value).map(([key, child]) => ({ key, node: this.defaultValue(schema.template!, child) })) };
    return { ...schema, present: true, entries: schema.entries.map((entry) => ({ key: entry.key,
      node: Object.hasOwn(value, entry.key) ? this.defaultValue(entry.node, value[entry.key]) : entry.node,
    })) };
  }

  describe(schema: MvuNode, desc: string): MvuNode { return { ...schema, desc }; }

  schema(node: AnyNode | undefined, env = this.env, path = '', flags: MvuKeyFlags = OPEN_KEY_FLAGS, depth = 0): MvuNode | null {
    this.#tick(depth);
    if (!node) return null;
    const read = (child: AnyNode | undefined): MvuNode | null => this.schema(child, env, path, flags, depth + 1);
    if (node.type === 'Identifier') {
      const binding = env.get(node.name);
      if (binding && 'node' in binding) return this.schema(binding.node, binding.env, path, flags, depth + 1);
      return this.unresolved(node, path, flags);
    }
    if (node.type !== 'CallExpression') return this.unresolved(node, path, flags);
    if (node.callee.type === 'Identifier') {
      const binding = env.get(node.callee.name);
      if (binding && 'node' in binding && functionNode(binding.node)) {
        const fn = binding.node;
        return this.schema(returned(fn), this.bind(fn, node.arguments, env, binding.env), path, flags, depth + 1);
      }
      return this.unresolved(node, path, flags);
    }
    if (node.callee.type !== 'MemberExpression') return this.unresolved(node, path, flags);
    const method = methodName(node.callee);
    const owner = node.callee.object;
    const zodRoot = owner.type === 'Identifier' && owner.name === 'z'
      || owner.type === 'MemberExpression' && owner.object.type === 'Identifier' && owner.object.name === 'z' && methodName(owner) === 'coerce';
    const args = node.arguments;
    if (zodRoot) {
      if (method === 'preprocess') {
        let result = read(args[1]);
        const fn = args[0];
        if (result && functionNode(fn)) {
          const local = this.bind(fn, [], env);
          const inferred = this.literal(returned(fn), local);
          result = this.defaultValue(result, inferred);
          if (inferred === UNKNOWN) this.issues.add(`${path || '根结构'}：自定义预处理逻辑保留为来源说明，转换未运行该函数。`);
        } else if (result && fn) this.issues.add(`${path || '根结构'}：预处理 ${this.source.slice(fn.start, fn.end)} 未执行，请使用规范字段写入。`);
        return result;
      }
      if (method === 'object' || method === 'strictObject' || method === 'looseObject') return this.object(args[0], env, path, flags, depth + 1);
      if (method === 'record' || method === 'map') {
        const template = read(args.at(-1));
        return { kind: 'group', entries: [], record: true, ...(template ? { template } : {}) };
      }
      if (method === 'array' || method === 'set') {
        const child = read(args[0]);
        const scalarList = child?.kind === 'leaf' && child.valueType !== 'json' && child.valueType !== 'list';
        return makeLeaf(scalarList ? [] : '[]', '', flags, scalarList ? 'list' : 'json');
      }
      if (method === 'union' || method === 'discriminatedUnion') {
        const variants = args.at(-1);
        if (variants?.type === 'ArrayExpression') {
          const nodes = variants.elements.filter((item): item is Expression => !!item && item.type !== 'SpreadElement').map(read).filter((item): item is MvuNode => !!item);
          const first = nodes[0];
          if (first?.kind === 'leaf' && nodes.every((item) => item.kind === 'leaf' && item.valueType === first.valueType)) {
            const enums = nodes.flatMap((item) => item.kind === 'leaf' ? item.constraints?.enumValues ?? [] : []);
            const allEnums = nodes.every((item) => item.kind === 'leaf' && item.constraints?.enumValues?.length);
            return { ...first, constraints: allEnums ? { enumValues: [...new Set(enums)] } : undefined };
          }
          // 可变形状保存在一个 JSON 单元格，避免选中第一分支而丢弃其他形状。
          this.issues.add(`${path}：联合类型按 JSON 保存；各分支的运行时校验需由写入方遵守。`);
          return makeLeaf('null', '', flags, 'json');
        }
      }
      if (method === 'intersection') {
        const left = read(args[0]), right = read(args[1]);
        if (left?.kind === 'group' && right?.kind === 'group') return this.merge(left, right);
      }
      if (method === 'lazy' && functionNode(args[0])) return read(returned(args[0]));
      if (method === 'enum' || method === 'nativeEnum' || method === 'literal') {
        const raw = this.literal(args[0], env);
        const values = (Array.isArray(raw) ? raw : isObject(raw) ? Object.values(raw) : [raw]).filter(isMvuScalar);
        const value = values[0] ?? '';
        const leaf = makeLeaf(value, '', flags);
        return { ...leaf, constraints: { enumValues: values } };
      }
      if (['string', 'number', 'boolean', 'bigint', 'date', 'null', 'any', 'unknown'].includes(method)) {
        return makeLeaf(method === 'number' || method === 'bigint' ? 0 : method === 'boolean' ? false : method === 'null' ? null : ['any', 'unknown'].includes(method) ? 'null' : '', '', flags,
          method === 'number' || method === 'bigint' ? 'number' : method === 'boolean' ? 'boolean' : ['any', 'unknown'].includes(method) ? 'json' : 'string');
      }
      return this.unresolved(node, path, flags);
    }
    let base = read(owner);
    if (!base) return null;
    if (method === 'extend' || method === 'safeExtend') {
      const extension = this.object(args[0], env, path, flags, depth + 1);
      return base.kind === 'group' && extension ? this.merge(base, extension) : base;
    }
    if (method === 'merge' || method === 'and') {
      const right = read(args[0]);
      return base.kind === 'group' && right?.kind === 'group' ? this.merge(base, right) : base;
    }
    if (method === 'describe') return this.describe(base, String(this.literal(args[0], env) ?? ''));
    if (['prefault', 'default', 'catch'].includes(method)) {
      const arg = args[0];
      return this.defaultValue(base, this.literal(functionNode(arg) ? returned(arg) : arg, env));
    }
    if (method === 'optional' || method === 'nullish') base = { ...base, optional: true };
    if ((method === 'nullable' || method === 'nullish') && base.kind === 'leaf') base = { ...base, nullable: true };
    if (method === 'array') return makeLeaf(base.kind === 'leaf' && base.valueType !== 'json' ? [] : '[]', '', flags, base.kind === 'leaf' && base.valueType !== 'json' ? 'list' : 'json');
    if (['pick', 'omit'].includes(method) && base.kind === 'group') {
      const keys = this.literal(args[0], env);
      if (isObject(keys)) base = { ...base, entries: base.entries.filter((entry) => method === 'pick' ? !!keys[entry.key] : !keys[entry.key]) };
    }
    if (base.kind === 'leaf') {
      const constraints: { minimum?: number; maximum?: number; integer?: boolean; enumValues?: MvuValueConstraints['enumValues'] } = { ...base.constraints };
      const value = this.literal(args[0], env);
      if (['min', 'gte'].includes(method) && typeof value === 'number') constraints.minimum = value;
      if (['max', 'lte'].includes(method) && typeof value === 'number') constraints.maximum = value;
      if (['nonnegative', 'positive'].includes(method)) constraints.minimum = 0;
      if (method === 'int') constraints.integer = true;
      if (method === 'transform' && functionNode(args[0])) {
        let known = false;
        walk(args[0], (part) => {
          if (part.type !== 'CallExpression') return;
          const name = methodName(part.callee);
          if (name === 'clamp') {
            const min = this.literal(part.arguments[1], env), max = this.literal(part.arguments[2], env);
            if (typeof min === 'number' && Number.isFinite(min)) constraints.minimum = min;
            if (typeof max === 'number' && Number.isFinite(max)) constraints.maximum = max;
            known = true;
          }
          if (name === 'round' || name === 'trunc') { constraints.integer = true; known = true; }
        });
        if (!known) this.issues.add(`${path}：自定义 transform 未执行，已保留基础类型。`);
      }
      if (Object.keys(constraints).length) base = { ...base, constraints };
    } else if (method === 'transform' || method === 'refine' || method === 'superRefine') this.issues.add(`${path || '根结构'}：自定义 ${method} 未执行，已保留声明的对象结构。`);
    return base;
  }

  object(node: AnyNode | undefined, env: Env, path: string, flags: MvuKeyFlags, depth: number): MvuGroupNode | null {
    if (node?.type === 'MemberExpression' && methodName(node) === 'shape') {
      const schema = this.schema(node.object, env, path, flags, depth + 1);
      return schema?.kind === 'group' ? schema : null;
    }
    if (node?.type === 'Identifier') {
      const binding = env.get(node.name);
      return binding && 'node' in binding ? this.object(binding.node, binding.env, path, flags, depth + 1) : null;
    }
    if (node?.type !== 'ObjectExpression') return null;
    let group: MvuGroupNode = { kind: 'group', entries: [] };
    for (const prop of node.properties) {
      if (prop.type === 'SpreadElement') {
        const other = this.object(prop.argument, env, path, flags, depth + 1);
        if (other) group = this.merge(group, other); else this.issues.add(`${path}：对象展开的结构尚未解析。`);
        continue;
      }
      const key = !prop.computed && prop.key.type === 'Identifier' ? prop.key.name : this.literal(prop.key, env);
      if (typeof key !== 'string' || blockedKeys.has(key)) { this.issues.add(`${path}：未解析的动态字段名。`); continue; }
      const node = this.schema(prop.value, env, path ? `${path}.${key}` : key, keyFlagsOf(key, flags), depth + 1);
      if (node) group = this.merge(group, { kind: 'group', entries: [{ key, node }] });
    }
    return group;
  }

  merge(left: MvuGroupNode, right: MvuGroupNode): MvuGroupNode {
    const entries = new Map(left.entries.map((entry) => [entry.key, entry]));
    for (const entry of right.entries) entries.set(entry.key, entry);
    return { ...left, entries: [...entries.values()] };
  }
  unresolved(node: AnyNode, path: string, flags: MvuKeyFlags): MvuNode {
    this.issues.add(`${path || '根结构'}：未解析的 schema「${this.source.slice(node.start, node.end).slice(0, 120)}」，已保留 JSON 存储位置。`);
    return makeLeaf('null', '', flags, 'json');
  }
}

export function readStaticMvuSchema(source: string): { readonly tree: MvuTree; readonly issues: readonly string[] } {
  const program = parse(source, { ecmaVersion: 'latest', sourceType: 'module', allowAwaitOutsideFunction: true });
  const reader = new SchemaReader(source);
  const roots: { node: AnyNode; env: Env }[] = [], named: { node: AnyNode; env: Env }[] = [], objects: { node: AnyNode; env: Env }[] = [];
  const visit = (node: AnyNode, parent: Env): void => {
    let env = parent;
    if (node.type === 'Program' || node.type === 'BlockStatement') {
      env = new Map(parent);
      for (const item of node.body) {
        const statement = item.type === 'ExportNamedDeclaration' ? item.declaration : item;
        if (statement?.type === 'VariableDeclaration') for (const decl of statement.declarations) {
          if (decl.id.type === 'Identifier' && decl.init) env.set(decl.id.name, { node: decl.init, env });
        }
        if (statement?.type === 'FunctionDeclaration' && statement.id) env.set(statement.id.name, { node: statement, env });
      }
      for (const key of ['Schema', 'schema', 'MvuSchema']) { const binding = env.get(key); if (binding && 'node' in binding) named.push({ node: binding.node, env: binding.env }); }
    }
    if (functionNode(node)) {
      env = new Map(env);
      for (const param of node.params) {
        const target = param.type === 'AssignmentPattern' ? param.left : param;
        if (target.type === 'Identifier') env.set(target.name, { value: undefined });
      }
    }
    if (node.type === 'CallExpression') {
      if (node.callee.type === 'Identifier' && node.callee.name === 'registerMvuSchema' && node.arguments[0]) roots.push({ node: node.arguments[0], env });
      if (methodName(node.callee) === 'object') objects.push({ node, env });
    }
    for (const value of Object.values(node)) {
      if (Array.isArray(value)) { for (const item of value) if (isObject(item) && typeof item.type === 'string') visit(item as unknown as AnyNode, env); }
      else if (isObject(value) && typeof value.type === 'string') visit(value as unknown as AnyNode, env);
    }
  };
  visit(program, reader.env);
  const root = roots[0] ?? named[0] ?? objects[0];
  const tree = root ? reader.schema(root.node, root.env) : null;
  if (!tree || tree.kind !== 'group' || !tree.entries.length) throw new Error('这份脚本里没有找到可解析的 z.object 变量根结构。');
  return { tree, issues: [...reader.issues] };
}
