import type { SqSheetView } from '../integration/sq-data-bridge.js';
import { getSillyTavernContext } from '../integration/sillytavern-bridge.js';
import { neutralizeHostTemplates } from '../generation/content-safety.js';
import { hashText } from '../db/sheet-dsl.js';
import { sqRecord, type SqCompatibility } from './template.js';

export interface SqInjection { readonly id: string; readonly content: string; readonly position: number; readonly depth: number; readonly role: number; readonly order: number }
const strings = (value: unknown): string[] => Array.isArray(value) ? value.map(String) : String(value ?? '').split(/[,，\n]/).map((part) => part.trim()).filter(Boolean);
const wrap = (template: unknown, content: string): string => typeof template === 'string' && template.trim() ? template.replaceAll('$1', content) : content;

/** SQ 的显示开关、关键词正文和常驻索引分开处理，关闭导出的表不会进入模型上下文。 */
export function buildSqInjections(metadata: SqCompatibility, views: readonly SqSheetView[], query: string): readonly SqInjection[] {
  const injections: SqInjection[] = [];
  const push = (key: string, content: string, placement: unknown): void => {
    if (!content.trim()) return;
    const config = sqRecord(placement), position = String(config.position ?? 'before_character_definition');
    const order = Number(config.order) || 0;
    injections.push({ id: `moyun-sq-${String(Math.max(0, order)).padStart(8, '0')}-${hashText(key)}`, content: neutralizeHostTemplates(content),
      position: position.startsWith('at_depth') ? 1 : position.startsWith('before') ? 2 : 0,
      depth: Math.max(0, Math.min(10000, Number(config.depth) || 0)),
      role: position.endsWith('_user') ? 1 : position.endsWith('_assistant') ? 2 : 0, order });
  };
  for (const table of metadata.tables) {
    const view = views.find((view) => view.name === table.name), config = table.exportConfig;
    if (!view || view.policy === 'manual' || config.enabled === false || !view.rows.length) continue;
    const modes = sqRecord(config.extraIndexColumnModes);
    const describe = (row: SqSheetView['rows'][number], columns = table.columns) => columns.map((column) => `${column.label}=${row.values[view.columns.indexOf(column.column)] ?? ''}`).join('；');
    const terms = strings(config.keywords);
    const matches = (row: SqSheetView['rows'][number]): boolean => terms.some((term) => {
      const column = table.columns.find((column) => [column.label, column.sourceName, column.column].includes(term));
      const keyword = column ? row.values[view.columns.indexOf(column.column)] ?? '' : term;
      return !!keyword && query.toLocaleLowerCase().includes(keyword.toLocaleLowerCase());
    });
    let rows = config.entryType === 'constant' ? view.rows : view.rows.filter(matches);
    if (config.splitByRow === false && rows.length) rows = view.rows;
    const bodyColumns = table.columns.filter((column) => modes[column.label] !== 'index_only' && modes[column.sourceName] !== 'index_only');
    if (rows.length) push(`${table.key}:body`, wrap(config.injectionTemplate, rows.map((row) => describe(row, bodyColumns)).join('\n')), config.entryPlacement);
    if (config.extraIndexEnabled === true) {
      const wanted = strings(config.extraIndexColumns);
      const columns = table.columns.filter((column) => wanted.includes(column.label) || wanted.includes(column.sourceName) || wanted.includes(column.column));
      if (columns.length) push(`${table.key}:index`, wrap(config.extraIndexInjectionTemplate, view.rows.map((row) => describe(row, columns)).join('\n')), config.extraIndexPlacement);
    }
  }
  return injections.sort((left, right) => left.order - right.order);
}

/** 专用临时槽保留深度和角色；停用、切聊天和本轮未命中时清掉旧槽。 */
export function createSqPromptController() {
  let ids: string[] = [];
  let chain: Promise<unknown> = Promise.resolve();
  return {
    sync(entries: readonly SqInjection[], isCurrent: () => boolean = () => true): Promise<string> {
      const context = getSillyTavernContext();
      const task = chain.then(async () => {
        const setter = context.setExtensionPrompt;
        if (!setter) return isCurrent() ? entries.map((entry) => entry.content).join('\n\n') : '';
        for (const id of ids) await setter(id, '', 0, 0, false, 0, null);
        ids = [];
        for (const entry of entries) {
          if (!isCurrent()) break;
          await setter(entry.id, entry.content, entry.position, entry.depth, false, entry.role, isCurrent);
          ids.push(entry.id);
        }
        return '';
      });
      chain = task.catch(() => undefined);
      return task;
    },
  };
}
