import type { FormatAdapter } from './adapter.js';

export interface ParsedBlock {
  readonly adapter: FormatAdapter;
  readonly container: string;
  readonly body: string;
  readonly start: number;
  readonly end: number;
}

export interface ParsedFieldRecord {
  readonly fields: Readonly<Record<string, string>>;
  readonly start: number;
  readonly end: number;
}

const IGNORED_BLOCKS = [
  'UpdateVariable', 'Analysis', 'PhoneAnalysis', 'JSONPatch', 'VariableEdit', 'VariableInsert',
  'VariableDelete', 'initvar', 'StatusPlaceHolderImpl', 'image', 'imgthink', 'WorldEvent',
  'summary', 'options', 'think', 'thinking', 'reasoning', 'reflection', 'scratchpad', '附加内容',
] as const;

export function stripNonPhoneBlocks(text: string, keepMarkers: readonly string[] = []): string {
  let result = text.replace(/\r\n?/g, '\n').replace(/\u0000/g, '');
  for (let pass = 0; pass < 3; pass += 1) {
    const before = result;
    for (const tag of IGNORED_BLOCKS) {
      const escaped = escapeRegExp(tag);
      result = result.replace(new RegExp(`<${escaped}\\b[^>]*>[\\s\\S]*?<\\/${escaped}\\s*>`, 'gi'), (block) => ' '.repeat(block.length));
      result = result.replace(new RegExp(`\\[${escaped}\\][\\s\\S]*?\\[\\/${escaped}\\]`, 'gi'), (block) => ' '.repeat(block.length));
    }
    result = result.replace(/```(?:json|html|javascript|js)?[\s\S]*?```/gi, (block) => (
      /<(?:wechat|twitter|discord_ui|phone|chat_app)/i.test(block)
        || keepMarkers.some((marker) => marker.length > 0 && block.includes(marker))
        ? block
        : ' '.repeat(block.length)
    ));
    if (before === result) break;
  }
  return result;
}

/** 同一段正文最多认多少个显式标记块，避免异常正文把解析拖死。 */
const MAX_MARKED_BLOCKS = 24;

export function scanPhoneBlocks(text: string, adapters: readonly FormatAdapter[]): readonly ParsedBlock[] {
  const sorted = [...adapters].sort((left, right) => right.confidence - left.confidence);
  // 卡里的容器可能写在代码围栏里，先把这些标记登记为「不要清掉」。
  const source = stripNonPhoneBlocks(text, sorted.flatMap((adapter) => [
    ...(adapter.open ? [adapter.open] : []),
    ...adapter.containers,
  ]));
  const blocks = [...scanPairedBlocks(source, sorted), ...scanMarkedBlocks(source, sorted)]
    .sort((left, right) => left.start - right.start);
  const seen = new Set<string>();
  const unique = blocks.filter((block) => {
    const key = `${block.start}:${block.end}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  return removeNestedDuplicates(unique);
}

/** `<容器>…</容器>` 与 `[容器]…[/容器]` 两种成对写法。 */
function scanPairedBlocks(source: string, adapters: readonly FormatAdapter[]): readonly ParsedBlock[] {
  const blocks: ParsedBlock[] = [];
  const patterns = adapters.flatMap((adapter) => adapter.containers.map((container) => ({ adapter, container })));
  const re = /<([A-Za-z_\u4e00-\u9fa5][\w\u4e00-\u9fa5-]*)(?=[\s>])[^>]*>([\s\S]*?)<\/\1\s*>|\[([^\]\r\n]{1,32})\]([\s\S]*?)\[\/\3\]/gi;
  for (const match of source.matchAll(re)) {
    const container = (match[1] ?? match[3] ?? '').trim();
    const body = match[2] ?? match[4] ?? '';
    const definition = patterns.find(({ container: known }) => normalizeName(known) === normalizeName(container));
    if (!definition) continue;
    const start = match.index ?? 0;
    blocks.push({ adapter: definition.adapter, container, body, start, end: start + match[0].length });
  }
  return blocks;
}

/** `[容器_始]…[容器_末]` 这类起止标记不成对的写法：按字面量查找，不走正则。 */
function scanMarkedBlocks(source: string, adapters: readonly FormatAdapter[]): readonly ParsedBlock[] {
  const blocks: ParsedBlock[] = [];
  for (const adapter of adapters) {
    const { open, close } = adapter;
    if (!open || !close) continue;
    let cursor = 0;
    while (blocks.length < MAX_MARKED_BLOCKS) {
      const start = source.indexOf(open, cursor);
      if (start < 0) break;
      const bodyStart = start + open.length;
      const closeIndex = source.indexOf(close, bodyStart);
      if (closeIndex < 0) break;
      blocks.push({
        adapter,
        container: adapter.containers[0] ?? open,
        body: source.slice(bodyStart, closeIndex),
        start,
        end: closeIndex + close.length,
      });
      cursor = closeIndex + close.length;
    }
  }
  return blocks;
}

/**
 * 从容器正文里取出第一个完整的 JSON 对象或数组。
 * 卡里常在 JSON 前后写说明文字，因此按括号配对扫描而不是直接 `JSON.parse` 整段。
 */
export function extractJsonBody(body: string): unknown {
  const start = body.search(/[[{]/);
  if (start < 0) return null;
  const opening = body[start];
  const closing = opening === '{' ? '}' : ']';
  let depth = 0;
  let quote = false;
  let escaped = false;
  for (let index = start; index < body.length; index += 1) {
    const character = body[index];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (quote) {
      if (character === '\\') escaped = true;
      else if (character === '"') quote = false;
      continue;
    }
    if (character === '"') quote = true;
    else if (character === opening) depth += 1;
    else if (character === closing) {
      depth -= 1;
      if (depth === 0) {
        try {
          return JSON.parse(body.slice(start, index + 1)) as unknown;
        } catch {
          return null;
        }
      }
    }
  }
  return null;
}

export function parsePipeFields(text: string): readonly ParsedFieldRecord[] {
  const records: ParsedFieldRecord[] = [];
  const fieldPattern = /\[([^\]|]{1,40})\|([\s\S]*?)(?=\]\s*\[\s*[^\]|]{1,40}\||\]\s*$)/g;
  const matches = [...text.matchAll(fieldPattern)];
  if (matches.length === 0) return records;
  const fields: Record<string, string> = {};
  let start = matches[0]?.index ?? 0;
  let end = start;
  for (const match of matches) {
    const key = match[1]?.trim();
    if (!key) continue;
    fields[key] = match[2]?.trim() ?? '';
    end = (match.index ?? end) + match[0].length;
  }
  records.push({ fields, start, end });
  return records;
}

export function parseColonFields(text: string): Readonly<Record<string, string>> {
  const fields: Record<string, string> = {};
  for (const line of text.split('\n')) {
    const match = /^\s*([^:：\[\]【】]{1,30})\s*[:：]\s*(.*?)\s*$/.exec(line);
    if (!match) continue;
    fields[match[1]?.trim() ?? ''] = match[2]?.trim() ?? '';
  }
  return fields;
}

export function splitSpeakerLines(text: string): readonly { readonly speaker: string; readonly content: string }[] {
  const tagged = [...text.matchAll(/<([^<>\r\n]{1,80})>([\s\S]*?)<\/\1\s*>/g)]
    .filter((match) => Boolean(match[1]) && !/^(?:img|image|附加内容|content|message|post|channel)$/i.test((match[1] ?? '').trim()))
    .map((match) => ({ speaker: (match[1] ?? '').trim(), content: (match[2] ?? '').trim() }))
    .filter((entry) => entry.content);
  if (tagged.length > 0) return tagged;

  const lines: { speaker: string; content: string }[] = [];
  let current: { speaker: string; content: string } | null = null;
  const flush = () => {
    if (current && current.content.trim()) lines.push({ speaker: current.speaker, content: current.content.trim() });
    current = null;
  };
  for (const line of text.split('\n')) {
    const prefix = /^\s*([^:：<>\r\n]{1,80})\s*[:：]\s*(.*)$/.exec(line);
    if (prefix) {
      flush();
      current = { speaker: prefix[1]?.trim() ?? '', content: prefix[2]?.trim() ?? '' };
    } else if (current && line.trim()) {
      current.content += `\n${line}`;
    }
  }
  flush();
  return lines;
}

export function parseDslCalls(text: string): readonly { readonly name: string; readonly args: readonly string[]; readonly start: number; readonly end: number }[] {
  const calls: { name: string; args: string[]; start: number; end: number }[] = [];
  const callPattern = /\b(QQ\.(?:Private|Group|SetGroupName|Post|Comment))\s*\(/g;
  for (const match of text.matchAll(callPattern)) {
    const start = match.index ?? 0;
    const open = start + match[0].lastIndexOf('(');
    const close = findClosingParen(text, open);
    if (close < 0) continue;
    const args = splitDslArguments(text.slice(open + 1, close));
    const name = match[1];
    if (!name) continue;
    calls.push({ name, args: [...args], start, end: close + 1 });
  }
  return calls;
}

function findClosingParen(text: string, open: number): number {
  let quote = '';
  let escaped = false;
  for (let index = open + 1; index < text.length; index += 1) {
    const character = text[index];
    if (escaped) { escaped = false; continue; }
    if (character === '\\' && quote) { escaped = true; continue; }
    if (quote) { if (character === quote) quote = ''; continue; }
    if (character === "'" || character === '"') { quote = character; continue; }
    if (character === ')') return index;
  }
  return -1;
}

function splitDslArguments(value: string): readonly string[] {
  const args: string[] = [];
  let start = 0;
  let quote = '';
  let escaped = false;
  for (let index = 0; index < value.length; index += 1) {
    const character = value[index];
    if (escaped) { escaped = false; continue; }
    if (character === '\\' && quote) { escaped = true; continue; }
    if (quote) { if (character === quote) quote = ''; continue; }
    if (character === "'" || character === '"') { quote = character; continue; }
    if (character === ',') { args.push(unquote(value.slice(start, index))); start = index + 1; }
  }
  args.push(unquote(value.slice(start)));
  return args;
}

function unquote(value: string): string {
  const text = value.trim();
  return text.length >= 2 && ((text.startsWith("'") && text.endsWith("'")) || (text.startsWith('"') && text.endsWith('"')))
    ? text.slice(1, -1).replace(/\\([\\'"nrt])/g, (_match, character: string) => ({ '\\': '\\', "'": "'", '"': '"', n: '\n', r: '\r', t: '\t' }[character] ?? character))
    : text;
}

function normalizeName(value: string): string {
  return value.trim().toLocaleLowerCase('zh-CN').replace(/[\s_-]+/g, '');
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function removeNestedDuplicates(blocks: readonly ParsedBlock[]): readonly ParsedBlock[] {
  return blocks.filter((block, index) => !blocks.some((other, otherIndex) => otherIndex !== index && other.start <= block.start && other.end >= block.end && (other.end > block.end || other.start < block.start)));
}