import {
  createRequest,
  isDbResponse,
  type DbErrorCode,
  type DbParams,
  type DbRequestKind,
  type DbRequestPayloadMap,
  type DbResponse,
  type DbResponseKind,
  type DbResponsePayloadMap,
  type DbStatement,
  type EngineStatus,
  type ExportResult,
  type ExecuteResult,
  type SearchResult,
} from './protocol.js';
import { validateUserSqlBatch, type SqlGuardTable, type SqlGuardOptions } from './sql-guard.js';

interface WorkerLike {
  postMessage(message: unknown): void;
  terminate(): void;
  addEventListener(type: 'message' | 'error', listener: EventListener): void;
  removeEventListener(type: 'message' | 'error', listener: EventListener): void;
}

export class DbClientError extends Error {
  readonly code: DbErrorCode;
  readonly sqliteCode?: number;

  constructor(code: DbErrorCode, message: string, sqliteCode?: number) {
    super(message);
    this.name = 'DbClientError';
    this.code = code;
    this.sqliteCode = sqliteCode;
  }
}

export interface DbClientOptions {
  readonly worker?: WorkerLike;
  readonly workerUrl?: URL;
  readonly requestTimeoutMs?: number;
  /** 在实际向 Worker 派发请求时再检查，覆盖 await open() 期间被关闭的情形。 */
  readonly assertAccess?: () => void;
}

/**
 * 分级请求超时。
 *
 * 整库快照落盘、全表前像与批量事务都挂在 `transaction`/`export` 上，用统一 15s 会在长聊天里
 * 把"其实已经提交成功"的写入误判成失败——超时只是客户端不再等待，worker 侧的事务照常 COMMIT，
 * 于是下一轮又会重复记录同一批楼层。`open` 要覆盖 WASM 冷启动，同样不能用 15s。
 */
const REQUEST_TIMEOUT_MS: Readonly<Record<DbRequestKind, number>> = Object.freeze({
  open: 60_000,
  status: 15_000,
  execute: 30_000,
  transaction: 120_000,
  search: 30_000,
  export: 120_000,
  close: 30_000,
});

interface PendingRequest {
  readonly kind: DbResponseKind;
  readonly resolve: (payload: unknown) => void;
  readonly reject: (error: DbClientError) => void;
  readonly timer: ReturnType<typeof setTimeout>;
}

function messageOf(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function createWorker(url: URL): WorkerLike {
  if (typeof Worker === 'undefined') throw new DbClientError('engine-unavailable', '当前环境不支持 Web Worker');
  return new Worker(url, { type: 'module', name: 'narrative-phone-sqlite' });
}

function responsePayload(response: DbResponse, expectedKind: DbResponseKind): unknown {
  if (!response.ok) {
    throw new DbClientError(response.error.code, response.error.message, response.error.sqliteCode);
  }
  if (response.kind !== expectedKind) {
    throw new DbClientError('protocol-error', `数据库响应类型不匹配：expected=${expectedKind}, actual=${response.kind}`);
  }
  return response.payload;
}

export class SqliteClient {
  readonly #options: DbClientOptions;
  readonly #pending = new Map<string, PendingRequest>();
  readonly #worker: WorkerLike;
  #openPromise: Promise<EngineStatus> | null = null;
  #closed = false;
  #closing = false;
  #sequence = 0;

  constructor(options: DbClientOptions = {}) {
    this.#options = options;
    this.#worker = options.worker ?? createWorker(options.workerUrl ?? new URL('./db-worker.js', import.meta.url));
    this.#worker.addEventListener('message', this.#onMessage);
    this.#worker.addEventListener('error', this.#onError);
  }

  open(): Promise<EngineStatus> {
    if (this.#closed || this.#closing) return Promise.reject(new DbClientError('closed', '数据库客户端已关闭'));
    if (this.#openPromise) return this.#openPromise;
    const promise = this.#request('open', {}, 'open').catch((error: unknown) => {
      this.#openPromise = null;
      throw error;
    });
    this.#openPromise = promise;
    return promise;
  }

  async status(): Promise<EngineStatus> {
    await this.open();
    return this.#request('status', {}, 'status');
  }

  async execute(statement: DbStatement): Promise<ExecuteResult> {
    await this.open();
    return this.#request('execute', statement, 'execute');
  }

  async transaction(statements: readonly DbStatement[]): Promise<readonly ExecuteResult[]> {
    await this.open();
    return this.#request('transaction', { statements }, 'transaction');
  }

  async executeGuardedBatch(
    statements: readonly DbStatement[],
    tables: readonly SqlGuardTable[],
    options?: SqlGuardOptions,
  ): Promise<readonly ExecuteResult[]> {
    const safeStatements = validateUserSqlBatch(statements, tables, options);
    return this.transaction(safeStatements);
  }

  async search(scopeId: string, query: string, limit?: number): Promise<SearchResult> {
    await this.open();
    return this.#request('search', { scopeId, query, ...(limit === undefined ? {} : { limit }) }, 'search');
  }

  async exportDatabase(): Promise<ExportResult> {
    await this.open();
    return this.#request('export', {}, 'export');
  }

  async close(): Promise<void> {
    if (this.#closed || this.#closing) return;
    this.#closing = true;
    try {
      if (this.#openPromise) await this.#request('close', {}, 'close');
    } catch {
      // A failed close must not keep the worker alive or retain pending requests.
    } finally {
      this.#closed = true;
      this.#closing = false;
      this.#rejectPending(new DbClientError('closed', '数据库客户端已关闭'));
      this.#worker.removeEventListener('message', this.#onMessage);
      this.#worker.removeEventListener('error', this.#onError);
      this.#worker.terminate();
    }
  }

  #request<K extends DbRequestKind, R extends DbResponseKind>(
    kind: K,
    payload: DbRequestPayloadMap[K],
    responseKind: R,
  ): Promise<DbResponsePayloadMap[R]> {
    if (this.#closed || (this.#closing && kind !== 'close')) {
      return Promise.reject(new DbClientError('closed', '数据库客户端已关闭'));
    }
    if (kind !== 'close') {
      try {
        this.#options.assertAccess?.();
      } catch (error) {
        return Promise.reject(error);
      }
    }
    const id = `${Date.now().toString(36)}-${(this.#sequence += 1).toString(36)}`;
    const request = createRequest(id, kind, payload);
    const timeout = this.#options.requestTimeoutMs ?? REQUEST_TIMEOUT_MS[kind];
    return new Promise<DbResponsePayloadMap[R]>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.#pending.delete(id);
        reject(new DbClientError('timeout', `数据库操作超时：${kind}`));
      }, timeout);
      this.#pending.set(id, {
        kind: responseKind,
        resolve: (value: unknown) => resolve(value as DbResponsePayloadMap[R]),
        reject,
        timer,
      });
      try {
        this.#worker.postMessage(request);
      } catch (error) {
        clearTimeout(timer);
        this.#pending.delete(id);
        reject(new DbClientError('engine-unavailable', `无法发送数据库请求：${messageOf(error)}`));
      }
    });
  }

  #onMessage = (event: Event): void => {
    const messageEvent = event as MessageEvent<unknown>;
    if (!isDbResponse(messageEvent.data)) return;
    const response = messageEvent.data;
    const pending = this.#pending.get(response.id);
    if (!pending) return;
    this.#pending.delete(response.id);
    clearTimeout(pending.timer);
    try {
      pending.resolve(responsePayload(response, pending.kind));
    } catch (error) {
      pending.reject(error instanceof DbClientError ? error : new DbClientError('protocol-error', messageOf(error)));
    }
  };

  #onError = (event: Event): void => {
    const errorEvent = event as ErrorEvent;
    this.#rejectPending(new DbClientError('engine-unavailable', errorEvent.message || '数据库 Worker 发生未捕获错误'));
  };

  #rejectPending(error: DbClientError): void {
    for (const [id, pending] of this.#pending) {
      clearTimeout(pending.timer);
      pending.reject(error);
      this.#pending.delete(id);
    }
  }
}

export function createSqliteClient(options: DbClientOptions = {}): SqliteClient {
  return new SqliteClient(options);
}

export type { DbParams };
