/** 表元数据的可编辑字段；列结构由专门的加列/改名/删列接口负责。 */
export interface SheetMetaPatch {
  readonly name?: string;
  readonly purpose?: string;
  readonly policy?: SheetPolicy;
  readonly rowTemplate?: string;
  readonly tokenBudget?: number;
  /** 注入条件（IF 语法的表达式部分）；空串表示无条件。 */
  readonly injectCondition?: string;
  /** 这张表的填表规则；空串表示没有额外规则。 */
  readonly fillGuide?: string;
}

export type SqliteAvailability =
  | { readonly kind: 'idle' }
  | { readonly kind: 'ready'; readonly status: EngineStatus }
  | { readonly kind: 'unavailable'; readonly reason: string };

/** 记忆库条目投影使用的 `mem_doc.kind`；事实源仍是 `PhoneState`。 */
export const SQLITE_MEMORY_ITEM_KIND = 'memory-item';

/** 打开失败后允许重试的间隔。 */
const REOPEN_RETRY_DELAY_MS = 30_000;

/** 用户表行投影使用的 `mem_doc.kind`；事实源是对应的 `acu_u_*` 物理表。 */
export function sheetDocumentKind(sheetId: string): string {
  return `sheet:${sheetId}`;
}

export interface UserSqlRequest {
  readonly assertCurrent?: () => void;
  /** 内部参数化批次（变量桥）可提高语句数；普通模型 SQL 继续使用默认上限。 */
  readonly maxBatchSize?: number;
  readonly scopeId: string;
  readonly statements: readonly DbStatement[];
  /** 审计归属；默认按模型产出记录。 */
  readonly actor?: string;
  readonly revision?: number;
  /**
   * 该批写入覆盖到的最后一个正文楼层。给定后会保存表级前像，支持按楼层回撤。
   * 必须是"最后一层"而不是首层：回撤查询按 `floor >= 目标层` 命中，
   * 记首层会让"改动批次中间某一层"完全命中不到前像，回撤静默失效。
   */
  readonly floor?: number;
  /** 逐条过闸：不合法的单条跳过并在结果里上报，而不是整批拒绝。自动记录用它。 */
  readonly skipRejected?: boolean;
}

export interface UserSqlResult {
  readonly results: readonly ExecuteResult[];
  readonly projections: readonly ProjectionSyncReport[];
  /** 被闸门拒掉的语句；`skipRejected` 为真时才可能非空。 */
  readonly rejected: readonly SqlBatchRejection[];
}

export interface FloorRevertReport {
  /** 被回撤的审计条目数。 */
  readonly entries: number;
  readonly tables: number;
  readonly projections: readonly ProjectionSyncReport[];
}

/** 界面用的表摘要：注册信息 + 物理表行数 + 已投影的召回单元数。 */
export interface SheetSummary extends SheetRecord {
  readonly rowCount: number;
  readonly documentCount: number;
}

/** 数据库面板快照：引擎能力如实呈现，不可用时列表为空但仍带原因。 */
export interface SqlitePanelStatus {
  readonly availability: SqliteAvailability;
  readonly description: string;
  readonly sheets: readonly SheetSummary[];
  readonly documentCount: number;
  readonly memoryItemCount: number;
}

export interface SheetPresetImportReport {
  readonly changed?: boolean;
  readonly updated?: readonly string[];
  readonly format: SheetPresetFormat;
  readonly createdSheets: number;
  readonly insertedRows: number;
  /** 结构一致、因此保留既有数据没有重建的表。 */
  readonly skipped: readonly string[];
  /** 列结构变了、按新预设重建过的表（旧行会随之丢弃）。 */
  readonly rebuilt: readonly string[];
  /** 不属于本次预设、被一并清掉的旧预设表。 */
  readonly pruned: readonly string[];
  readonly issues: readonly string[];
}

export interface SheetPresetImportOptions extends PresetMaterializeOptions {
  /**
   * 把当前 scope 里「由预设物化、但不属于本次预设」的表一并删掉。
   * 用于「不合并进当前预设」的显式替换：不删的话上一份预设的表会留在库里继续
   * 参与填表与注入，用户看到的就是两套表混在一起。界面手工建的表（`sheet-` 前缀）不受影响。
   */
  readonly prunePresetSheets?: boolean;
}

/** 归档回灌结果；`dropped` 是归档里已不存在、因此在本地一并删除的表。 */
export interface SheetArchiveApplyReport {
  readonly restoredSheets: number;
  readonly restoredRows: number;
  readonly dropped: number;
  readonly projections: readonly ProjectionSyncReport[];
}

/** 一张表的可视化内容：列名保持 ASCII，标题用行模板里的中文标签。 */
export interface SheetRowContent {
  /** SQLite 隐式 rowid，行级编辑与删除的定位键。 */
  readonly rowId: number;
  readonly values: readonly string[];
}

export interface SheetContent {
  readonly sheet: SheetRecord;
  readonly columns: readonly string[];
  readonly labels: readonly string[];
  readonly rows: readonly SheetRowContent[];
}

function cellText(value: DbValue | undefined): string {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string') return value;
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') return String(value);
  return '[二进制]';
}

function archiveFingerprintKey(scopeId: string): string {
  return `sheet_archive_fingerprint:${scopeId}`;
}

export interface SqliteMemoryEngineOptions {
  /** 延迟创建：浏览器不支持 Worker 或 OPFS 时构造过程本身就会失败。 */
  readonly createStore?: () => SqliteMemoryStore;
  readonly tokenCounter?: (text: string) => number;
  readonly onDiagnostic?: (message: string, detail?: unknown) => void;
  readonly isEnabled?: () => boolean;
}

export interface SqliteRecallRequest {
  readonly scopeId: string;
  readonly query: string;
  /** 召回段（按相关度取的历史行）的 token 预算。 */
  readonly totalTokenBudget: number;
  /**
   * 表结构 + 固定记忆的上限。省略表示不限量：这两段是模型当前必须看见的状态，
   * 被预算截掉会让表在库里有数据、模型却读不到。只有调用方明确要限量时才传。
   */
  readonly fixedTokenBudget?: number;
  readonly candidateLimit?: number;
  readonly alwaysLimit?: number;
  readonly now?: number;
  /**
   * 表级注入门控。返回 false 的表不参与本轮注入：表结构不列、固定记忆与召回记忆都不取它的行。
   * 判定逻辑（IF 条件求值）由调用方提供，引擎只负责按结果过滤，不认识条件语言。
   */
  readonly sheetGate?: (sheet: SheetRecord) => boolean;
}

export interface SqliteRecallResult extends RecallPack {
  /** 实际使用的检索路径；trigram 需要 ≥3 字符，否则显式退化为 LIKE。 */
  readonly searchMode: SearchMode;
  readonly sheetCount: number;
}

export interface SqliteDocumentDraft extends Omit<SqliteMemoryDocumentInput, 'hash'> {
  readonly hash?: string;
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error ?? '未知错误');
}

function documentToCandidate(document: MemoryDocumentRecord): RecallCandidate {
  return {
    id: document.id,
    text: document.text,
    ...(document.tokens > 0 ? { tokens: document.tokens } : {}),
    ...(document.sheetId ? { sheetId: document.sheetId } : {}),
    importance: document.importance,
    pinned: document.pinned,
    updatedAt: document.updatedAt,
  };
}

function searchRowToCandidate(row: SearchRow, rank: number, mode: SearchMode): RecallCandidate {
  return {
    id: row.id,
    text: row.text,
    ...(row.tokens > 0 ? { tokens: row.tokens } : {}),
    ...(row.sheet_id ? { sheetId: row.sheet_id } : {}),
    importance: row.importance,
    pinned: row.pinned === 1,
    updatedAt: row.updated_at,
    ...(mode === 'fts5' ? { ftsRank: rank, ftsScore: row.fts_score } : {}),
  };
}

/** 面向界面与日志的引擎状态描述；内存模式绝不描述为已持久化。 */
export function describeSqliteAvailability(availability: SqliteAvailability): string {
  if (availability.kind === 'idle') return 'SQLite 记忆引擎尚未初始化。';
  if (availability.kind === 'unavailable') return `SQLite 记忆引擎不可用：${availability.reason}`;
  const { status } = availability;
  const persistence = status.mode === 'opfs-sahpool'
    ? 'OPFS 持久化（仅存在于当前浏览器）'
    : status.mode === 'indexeddb-snapshot'
      ? '内存库 + IndexedDB 快照（仅存在于当前浏览器，换浏览器或清理站点数据即丢失）'
      : '仅内存库（刷新后数据丢失）';
  const search = status.fts5 ? 'FTS5 trigram 可用' : 'FTS5 不可用，仅 LIKE 检索';
  return `SQLite ${status.sqliteVersion} · ${persistence} · ${search}${status.warning ? ` · ${status.warning}` : ''}`;
}

/**
 * SQLite 记忆子系统的组合层：负责单飞初始化、能力降级与召回装配。
 * 读取路径在引擎不可用时返回 null（功能降级），写入路径必须抛错（不静默丢写）。
 */
export class SqliteMemoryEngine {
  readonly #options: SqliteMemoryEngineOptions;
  readonly #access: DataCenterAccess;
  #store: SqliteMemoryStore | null = null;
  #opening: Promise<SqliteMemoryStore | null> | null = null;
  #openingStore: SqliteMemoryStore | null = null;
  #closing: Promise<void> | null = null;
  #availability: SqliteAvailability = { kind: 'idle' };
  #unavailableAt = 0;
  #writeChain: Promise<unknown> = Promise.resolve();

  #serializeWrites<T>(work: () => Promise<T>): Promise<T> {
    const wasEnabled = this.#access.isEnabled();
    const isCurrent = this.#access.capture();
    const run = this.#writeChain.then(() => {
      if (wasEnabled && !isCurrent()) throw new DataCenterInactiveError();
      return work();
    });
    this.#writeChain = run.catch(() => undefined);
    return run;
  }

  constructor(options: SqliteMemoryEngineOptions = {}) {
    this.#options = options;
    this.#access = new DataCenterAccess(options.isEnabled ?? (() => true));
  }

  get availability(): SqliteAvailability {
    return this.#availability;
  }

  /** 单飞打开；任何失败都记录原因并返回 null，不抛出。 */
  async ensureOpen(): Promise<EngineStatus | null> {
    const store = await this.#openStore();
    return store && this.#availability.kind === 'ready' ? this.#availability.status : null;
  }

  /** 面板快照：读取路径，引擎不可用时返回原因与空列表，不抛错。 */
  async inspect(scopeId: string): Promise<SqlitePanelStatus> {
    const store = await this.#openStore();
    if (!store) {
      return {
        availability: this.#availability,
        description: describeSqliteAvailability(this.#availability),
        sheets: [],
        documentCount: 0,
        memoryItemCount: 0,
      };
    }
    try {
      const sheets = await store.listSheets(scopeId);
      const summaries: SheetSummary[] = [];
      for (const sheet of sheets) {
        summaries.push({
          ...sheet,
          rowCount: await store.countSheetRows(sheet),
          documentCount: await store.countDocuments(scopeId, sheetDocumentKind(sheet.id)),
        });
      }
      return {
        availability: this.#availability,
        description: describeSqliteAvailability(this.#availability),
        sheets: summaries,
        documentCount: await store.countDocuments(scopeId),
        memoryItemCount: await store.countDocuments(scopeId, SQLITE_MEMORY_ITEM_KIND),
      };
    } catch (error) {
      this.#report('读取 SQLite 面板状态失败', error);
      return {
        availability: this.#availability,
        description: `${describeSqliteAvailability(this.#availability)} · 状态读取失败：${errorMessage(error)}`,
        sheets: [],
        documentCount: 0,
        memoryItemCount: 0,
      };
    }
  }

  async registerSheet(input: SheetRegistrationInput, now?: number): Promise<SheetDefinition> {
    return this.#serializeWrites(async () => {
      const sheet = prepareSheetRegistration(input, now);
      const store = await this.#requireStore();
      await store.registerSheet(sheet);
      return sheet;
    });
  }

  async listSheets(scopeId: string): Promise<readonly SheetRecord[]> {
    const store = await this.#openStore();
    if (!store) return [];
    try {
      return await store.listSheets(scopeId);
    } catch (error) {
      this.#report('读取 SQLite 表注册表失败', error);
      return [];
    }
  }

  async recordDocument(draft: SqliteDocumentDraft): Promise<void> {
    const store = await this.#requireStore();
    await store.upsertDocument({ ...draft, hash: draft.hash ?? hashText(draft.text) });
  }

  /**
   * 把事实源渲染结果同步成该 scope 下某一类的完整投影。
   * 引擎不可用时抛错：投影可重建，但调用方必须知道这一轮没有同步成功。
   */
  async syncProjection(
    scopeId: string,
    kind: string,
    documents: readonly MemoryDocumentProjection[],
  ): Promise<ProjectionSyncReport> {
    const store = await this.#requireStore();
    return store.syncDocuments(scopeId, kind, documents);
  }

  /**
   * 执行模型或界面产出的 SQL：先按 `sheet` 注册表过闸，再事务化执行并写 `op_log`，
   * 最后把该 scope 的用户表行重新投影成召回单元。任一步失败都整批回滚并抛出原始错误。
   * `skipRejected` 为真时改为逐条过闸，被拒的语句进 `rejected`，合法部分照常写入。
   */
  async runUserSql(request: UserSqlRequest): Promise<UserSqlResult> {
    return this.#serializeWrites(async () => {
      request.assertCurrent?.();
      const store = await this.#requireStore();
      const sheets = await store.listSheets(request.scopeId);
      const { accepted, rejected } = request.skipRejected
        ? partitionUserSqlBatch(request.statements, sheets, { maxBatchSize: request.maxBatchSize })
        : { accepted: validateUserSqlBatch(request.statements, sheets, { maxBatchSize: request.maxBatchSize }), rejected: [] as readonly SqlBatchRejection[] };
      // 一条都没通过时不开事务、不留审计：调用方据此判定"这批产出全部不合法"，不必按写入失败重试。
      if (accepted.length === 0) return { results: [], projections: [], rejected };
      const snapshot = request.floor === undefined ? undefined : await store.captureSheetSnapshot(sheets);
      request.assertCurrent?.();
      const results = await store.runAuditedStatements(request.scopeId, [...accepted, ...buildClothingConsistencyStatements(sheets)], {
        actor: request.actor ?? 'model',
        revision: request.revision ?? 0,
        ...(request.floor === undefined ? {} : { floor: request.floor }),
        ...(snapshot === undefined ? {} : { snapshot }),
      });
      const projections = await this.#projectAfterWrite(store, request.scopeId, sheets);
      return { results, projections, rejected };
    });
  }

  /** 脚本只读查询，限定当前聊天的注册表；不触发审计或数据投影写入。 */
  async queryUserSql(scopeId: string, sql: string, limit = 100): Promise<ExecuteResult> {
    const store = await this.#requireStore();
    if (!/^SELECT\b/i.test(sql.trim())) throw new Error('数据中心查询只接受单条 SELECT 语句。');
    const sheets = await store.listSheets(scopeId);
    const statement = validateUserSql({ sql }, sheets);
    const rowLimit = Number.isFinite(limit) ? Math.max(1, Math.min(1_000, Math.trunc(limit))) : 100;
    return store.query({ sql: `SELECT * FROM (${statement.sql}) LIMIT ?`, params: [rowLimit] });
  }

  /**
   * 数据中心记录游标的恢复依据：该聊天最后一次写入数据表的楼层。
   * 引擎不可用或从未记录过时返回 -1，调用方按「没有历史进度」处理。
   */
  async lastRecordedFloor(scopeId: string): Promise<number> {
    const store = await this.#openStore();
    if (!store) return -1;
    try {
      return await store.readLastRecordedFloor(scopeId);
    } catch (error) {
      this.#report('读取数据中心记录游标失败', error);
      return -1;
    }
  }

  async presetRecordedFloor(scopeId: string, presetId: string): Promise<number | null> {
    const store = await this.#openStore();
    return store ? store.readPresetRecordedFloor(scopeId, presetId) : null;
  }

  /** 无 SQL 的记录批次也保存进度，并随预设归档携带。 */
  async markPresetRecordedFloor(scopeId: string, presetId: string, floor: number, assertCurrent?: () => void): Promise<void> {
    return this.#serializeWrites(async () => {
      assertCurrent?.();
      const store = await this.#requireStore();
      const statements = await store.planPresetRecordedFloor(scopeId, presetId, floor);
      assertCurrent?.();
      if (statements.length) await store.commitSheetPlan(statements);
    });
  }

  /**
   * 楼层回撤：把楼层 ≥ `floor` 的记录写入恢复成写入前的状态，并清掉对应审计。
   * 用户删除/重生成/滑动楼层后调用，避免表里留下已经不存在的剧情事实。
   * 读取路径语义：引擎不可用时返回空报告而不抛错，调用方按"未回撤"处理。
   */
  async revertFromFloor(scopeId: string, floor: number): Promise<FloorRevertReport> {
    return this.#serializeWrites(async () => {
      const store = await this.#openStore();
      if (!store) return { entries: 0, tables: 0, projections: [] };
      try {
        const { snapshot, entries } = await store.readRevertSnapshot(scopeId, floor);
        const sheets = await store.listSheets(scopeId, true);
        const tables = await store.restoreSheetSnapshot(scopeId, floor, snapshot, sheets);
        const projections = tables ? await this.#projectSheets(store, scopeId, await store.listSheets(scopeId)) : [];
        return { entries, tables, projections };
      } catch (error) {
        this.#report(`回撤楼层 ${floor} 起的数据中心写入失败`, error);
        return { entries: 0, tables: 0, projections: [] };
      }
    });
  }

  /** 用户表行 → 召回单元投影；表结构或行内容在别处被改动后重新调用即可收敛。 */
  async refreshSheetProjections(scopeId: string): Promise<readonly ProjectionSyncReport[]> {
    return this.#serializeWrites(async () => {
      const store = await this.#requireStore();
      return this.#projectSheets(store, scopeId, await store.listSheets(scopeId));
    });
  }

  /**
   * 导入表格预设（自有格式或 SP 的 chatSheets 模板）。
   *
   * 同名表按稳定 id 判定：列结构一致就跳过，保住用户已经积累的行；
   * 列结构变了必须重建——旧表的列名与新映射对不上，留着它会让投影与写入
   * 全都定位不到列，表面上「表还在」，实际上那一组变量彻底失联。
   */
  async importSheetPreset(
    scopeId: string,
    preset: SheetPresetImport,
    options: SheetPresetImportOptions = {},
  ): Promise<SheetPresetImportReport> {
    return this.#serializeWrites(async () => {
      const store = await this.#requireStore();
      const report = await materializePreset(store, scopeId, preset, options);
      await this.#projectAfterWrite(store, scopeId, await store.listSheets(scopeId));
      return report;
    });
  }

  /**
   * 导出该 scope 的表格归档（表定义 + 行文本），供调用方写进跨设备持久化通道。
   * 读取路径：引擎不可用或读取失败时返回 null，调用方按「本轮没有可归档内容」处理，不能当成空归档写出去。
   */
  async exportSheetArchive(scopeId: string): Promise<SheetArchive | null> {
    return this.#serializeWrites(async () => {
      const store = await this.#openStore();
      if (!store) return null;
      try {
        const sheets = await store.listSheets(scopeId, true);
        const sources: SheetArchiveSource[] = [];
        for (const sheet of sheets) {
          const columns = sheetColumnNames(sheet.ddl);
          const rows = await store.readAllSheetRows(sheet);
          sources.push({
            sheet: {
              id: sheet.id,
              name: sheet.name,
              purpose: sheet.purpose,
              physicalName: sheet.physicalName,
              policy: sheet.policy,
              rowTemplate: sheet.rowTemplate,
              tokenBudget: sheet.tokenBudget,
              orderNo: sheet.orderNo,
              updatedAt: sheet.updatedAt,
              injectCondition: sheet.injectCondition,
              fillGuide: sheet.fillGuide,
            },
            columns,
            rows: rows.map((row) => columns.map((column) => cellText(row[column]))),
            rowIds: rows.map((row) => Number(row[ROW_ID_ALIAS])),
          });
        }
        const state = await store.readMeta(presetScopeKey(scopeId));
        const prefix = sheetBackupPrefix(scopeId);
        const backups = await store.readMetaPrefix(prefix);
        return captureSheetArchive(scopeId, sources, Date.now(), {
          ...(state ? { presetState: await store.readPresetState(scopeId) } : {}),
          ...(Object.keys(backups).length ? { migrationBackups: Object.fromEntries(Object.entries(backups).map(([key, value]) => [key.slice(prefix.length), value])) } : {}),
        });
      } catch (error) {
        this.#report('导出数据中心表格归档失败', error);
        return null;
      }
    });
  }

  /**
   * 用归档覆盖该 scope 的本地表格：归档是事实源，因此归档里没有的表在本地一并删除，
   * 存在的表整表重建（列可能被增删改名，逐行比对无法收敛结构差异），最后重建召回投影。
   * 写入路径：失败必须抛出，调用方要知道这一轮没有恢复成功，绝不能静默留着旧数据。
   */
  async applySheetArchive(scopeId: string, archive: SheetArchive): Promise<SheetArchiveApplyReport> {
    return this.#serializeWrites(async () => {
      const store = await this.#requireStore();
      const existing = await store.listSheets(scopeId, true);
      const rebased = new Map<string, string>();
      const incoming = [];
      for (const entry of archive.sheets) {
        const collision = await store.query({ sql: 'SELECT id FROM sheet WHERE scope_id <> ? AND (id = ? OR physical_name = ?)', params: [scopeId, entry.id, entry.physicalName] });
        if (!collision.rows.length) { incoming.push(entry); continue; }
        const id = `sheet-clone-${hashText(`${scopeId}|${entry.id}`)}`;
        rebased.set(entry.id, id);
        incoming.push({ ...entry, id, physicalName: physicalTableName(entry.name, id) });
      }
      const wanted = new Map(incoming.map((entry) => [entry.id, entry]));
      const dropped = existing.filter((sheet) => !wanted.has(sheet.id)).length;
      const statements: DbStatement[] = existing.flatMap(dropSheetStatements);
      let restoredSheets = 0;
      let restoredRows = 0;
      for (const entry of wanted.values()) {
        const collision = await store.query({ sql: 'SELECT id FROM sheet WHERE scope_id <> ? AND (id = ? OR physical_name = ?)', params: [scopeId, entry.id, entry.physicalName] });
        if (collision.rows.length) throw new Error(`归档中的表「${entry.name}」与其他聊天的实例冲突，恢复已中止。`);
        const sheet = prepareSheetRegistration(
          archiveEntryToRegistration(scopeId, entry),
          entry.updatedAt > 0 ? entry.updatedAt : undefined,
        );
        statements.push(...registerSheetStatements(sheet), ...insertSheetRowsStatements(sheet, entry.columns, entry.rows, entry.rowIds));
        restoredSheets += 1;
        restoredRows += entry.rows.length;
      }
      const remap = (record: Readonly<Record<string, string>>) => Object.fromEntries(Object.entries(record).map(([id, value]) => [rebased.get(id) ?? id, value]));
      const presetState = archive.presetState && { ...archive.presetState, owners: remap(archive.presetState.owners), keys: remap(archive.presetState.keys),
        definitions: remap(archive.presetState.definitions), hidden: archive.presetState.hidden.map((id) => rebased.get(id) ?? id) };
      statements.push(presetState ? writeSheetMetaStatement(presetScopeKey(scopeId), presetState)
        : { sql: 'DELETE FROM sys_meta WHERE key = ?', params: [presetScopeKey(scopeId)] });
      for (const key of Object.keys(await store.readMetaPrefix(sheetBackupPrefix(scopeId)))) statements.push({ sql: 'DELETE FROM sys_meta WHERE key = ?', params: [key] });
      for (const [key, value] of Object.entries(archive.migrationBackups ?? {})) statements.push({ sql: 'INSERT INTO sys_meta(key, value) VALUES (?, ?)', params: [`${sheetBackupPrefix(scopeId)}${key}`, value] });
      statements.push({ sql: 'DELETE FROM op_log WHERE scope_id = ?', params: [scopeId] });
      await store.commitSheetPlan(statements);
      const projections = await this.#projectAfterWrite(store, scopeId, await store.listSheets(scopeId));
      return { restoredSheets, restoredRows, dropped, projections };
    });
  }

  /**
   * 上次成功归档时的内容指纹，存在库自己的 `sys_meta` 里。
   * 它是「本地有没有未上传改动」的唯一判据：本地指纹与它一致说明本地改动都已归档，
   * 此时可以安全地采用远端归档；不一致说明本地领先，应该反过来覆盖远端。
   */
  async readArchiveFingerprint(scopeId: string): Promise<string | null> {
    const store = await this.#openStore();
    if (!store) return null;
    try {
      return await store.readMeta(archiveFingerprintKey(scopeId));
    } catch (error) {
      this.#report('读取表格归档指纹失败', error);
      return null;
    }
  }

  async writeArchiveFingerprint(scopeId: string, fingerprint: string): Promise<void> {
    const store = await this.#requireStore();
    await store.writeMeta(archiveFingerprintKey(scopeId), fingerprint);
  }

  /** 读取一张表的完整内容用于界面网格；引擎不可用或表不存在时返回 null。 */
  async readSheet(scopeId: string, sheetId: string, limit: number | null = 2_000): Promise<SheetContent | null> {
    const store = await this.#openStore();
    if (!store) return null;
    try {
      const sheet = (await store.listSheets(scopeId)).find((item) => item.id === sheetId);
      if (!sheet) return null;
      const columns = sheetColumnNames(sheet.ddl);
      const labels = sheetColumnLabels(sheet.rowTemplate);
      const rows = limit === null ? await store.readAllSheetRows(sheet) : await store.readSheetRows(sheet, limit);
      return {
        sheet,
        columns,
        labels: columns.map((column) => labels.get(column) ?? column),
        rows: rows.map((row) => ({
          rowId: Number(row[ROW_ID_ALIAS] ?? 0),
          values: columns.map((column) => cellText(row[column])),
        })),
      };
    } catch (error) {
      this.#report(`读取表「${sheetId}」内容失败`, error);
      return null;
    }
  }

  /** 行级写入：界面编辑走这里，写完立即重投影该表，保证召回与表内容一致。 */
  async insertSheetRow(
    scopeId: string,
    sheetId: string,
    values: Readonly<Record<string, string>>,
  ): Promise<number> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      const columns = sheetColumnNames(sheet.ddl).filter((column) => values[column] !== undefined);
      if (columns.length === 0) throw new Error('没有可写入的列。');
      const inserted = await store.insertSheetRows(sheet, columns, [columns.map((column) => values[column] ?? '')]);
      await this.#projectAfterWrite(store, scopeId, [sheet]);
      return inserted;
    });
  }

  async updateSheetRow(
    scopeId: string,
    sheetId: string,
    rowId: number,
    values: Readonly<Record<string, string>>,
  ): Promise<number> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      const allowed = new Set(sheetColumnNames(sheet.ddl));
      const patch = Object.fromEntries(Object.entries(values).filter(([column]) => allowed.has(column)));
      if (Object.keys(patch).length === 0) throw new Error('没有可更新的列。');
      const changes = await store.updateSheetRow(sheet, rowId, patch);
      await this.#projectAfterWrite(store, scopeId, [sheet]);
      return changes;
    });
  }

  async deleteSheetRow(scopeId: string, sheetId: string, rowId: number): Promise<number> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      const changes = await store.deleteSheetRow(sheet, rowId);
      await this.#projectAfterWrite(store, scopeId, [sheet]);
      return changes;
    });
  }

  /** 删除整张表：物理表、注册行与投影同批消失。 */
  async dropSheet(scopeId: string, sheetId: string): Promise<void> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      await deletePresetSheet(store, sheet);
    });
  }

  /**
   * 清理瞬态作用域（如 `chat:anonymous-*`）遗留的表、投影与审计：
   * 这些 scope 每次页面加载都重新编号，里面的数据永远不会再被读到。
   * 维护写入：引擎不可用时抛错，由调用方决定是否忽略。
   */
  async purgeScopePrefix(prefix: string): Promise<ScopePurgeReport> {
    return this.#serializeWrites(async () => {
      const store = await this.#requireStore();
      return store.purgeScopePrefix(prefix);
    });
  }

  /** 修改表的元数据：表名、用途说明、注入策略、行模板、token 预算、注入条件、填表规则。 */
  async updateSheetMeta(scopeId: string, sheetId: string, patch: SheetMetaPatch): Promise<SheetRecord> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      const name = (patch.name ?? sheet.name).trim();
      const purpose = (patch.purpose ?? sheet.purpose).trim();
      const rowTemplate = (patch.rowTemplate ?? sheet.rowTemplate).trim();
      const policy = patch.policy ?? sheet.policy;
      const tokenBudget = Math.trunc(patch.tokenBudget ?? sheet.tokenBudget);
      const injectCondition = (patch.injectCondition ?? sheet.injectCondition).trim();
      const fillGuide = (patch.fillGuide ?? sheet.fillGuide).trim();
      if (!name) throw new Error('表名不能为空。');
      if (!purpose) throw new Error('用途说明不能为空，它是模型判断这张表能查什么的唯一依据。');
      if (!rowTemplate) throw new Error('行模板不能为空。');
      if (!['always', 'recall', 'manual'].includes(policy)) throw new Error(`未知注入策略：${policy}`);
      if (tokenBudget < 16 || tokenBudget > 8_192) throw new Error('token 预算必须在 16 到 8192 之间。');
      const conditionError = validateSheetCondition(injectCondition);
      if (conditionError) throw new Error(`注入条件无效：${conditionError}`);
      await store.updateSheetRegistration(sheetId, {
        name,
        purpose,
        policy,
        rowTemplate,
        tokenBudget,
        injectCondition,
        fillGuide,
      });
      const next: SheetRecord = { ...sheet, name, purpose, policy, rowTemplate, tokenBudget, injectCondition, fillGuide };
      await this.#projectAfterWrite(store, scopeId, [next]);
      return next;
    });
  }

  /** 新增一列（一律 TEXT）；行模板同步追加片段，已有行该列为空。 */
  async addSheetColumn(scopeId: string, sheetId: string, column: string, label?: string): Promise<readonly string[]> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      const name = column.trim();
      if (!isUsableColumnName(name)) throw new Error(`列名「${name}」非法或与 SQLite 保留字冲突，请用英文或拼音。`);
      const columns = sheetColumnNames(sheet.ddl);
      if (columns.includes(name)) throw new Error(`列「${name}」已存在。`);
      if (columns.length >= 64) throw new Error('单表最多 64 列。');
      const nextColumns = [...columns, name];
      const ddl = createSheetDdl(sheet.physicalName, nextColumns.map((item) => ({ name: item, type: 'TEXT' as const })));
      const rowTemplate = appendTemplateColumn(sheet.rowTemplate, name, label);
      await store.alterSheetColumn(sheet, 'add', { to: name }, { ddl, rowTemplate });
      await this.#projectAfterWrite(store, scopeId, [{ ...sheet, ddl, rowTemplate }]);
      return nextColumns;
    });
  }

  /** 改列名：物理列、DDL 与行模板占位符一起改，行数据原样保留。 */
  async renameSheetColumn(
    scopeId: string,
    sheetId: string,
    from: string,
    to: string,
  ): Promise<readonly string[]> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      const target = to.trim();
      if (!isUsableColumnName(target)) throw new Error(`列名「${target}」非法或与 SQLite 保留字冲突，请用英文或拼音。`);
      const columns = sheetColumnNames(sheet.ddl);
      if (!columns.includes(from)) throw new Error(`列「${from}」不存在。`);
      if (columns.includes(target)) throw new Error(`列「${target}」已存在。`);
      const nextColumns = columns.map((item) => (item === from ? target : item));
      const ddl = createSheetDdl(sheet.physicalName, nextColumns.map((item) => ({ name: item, type: 'TEXT' as const })));
      const rowTemplate = renameTemplateColumn(sheet.rowTemplate, from, target);
      await store.alterSheetColumn(sheet, 'rename', { from, to: target }, { ddl, rowTemplate });
      await this.#projectAfterWrite(store, scopeId, [{ ...sheet, ddl, rowTemplate }]);
      return nextColumns;
    });
  }

  /** 删列：连同行模板里引用它的片段一起去掉；最后一列不允许删除。 */
  async dropSheetColumn(scopeId: string, sheetId: string, column: string): Promise<readonly string[]> {
    return this.#serializeWrites(async () => {
      const { store, sheet } = await this.#requireSheet(scopeId, sheetId);
      const columns = sheetColumnNames(sheet.ddl);
      if (!columns.includes(column)) throw new Error(`列「${column}」不存在。`);
      if (columns.length <= 1) throw new Error('表至少需要保留一列，如需清理请直接删除整张表。');
      const nextColumns = columns.filter((item) => item !== column);
      const ddl = createSheetDdl(sheet.physicalName, nextColumns.map((item) => ({ name: item, type: 'TEXT' as const })));
      const rowTemplate = removeTemplateColumn(sheet.rowTemplate, column, nextColumns);
      await store.alterSheetColumn(sheet, 'drop', { from: column }, { ddl, rowTemplate });
      await this.#projectAfterWrite(store, scopeId, [{ ...sheet, ddl, rowTemplate }]);
      return nextColumns;
    });
  }

  async #requireSheet(
    scopeId: string,
    sheetId: string,
  ): Promise<{ readonly store: SqliteMemoryStore; readonly sheet: SheetRecord }> {
    const store = await this.#requireStore();
    const sheet = (await store.listSheets(scopeId)).find((item) => item.id === sheetId);
    if (!sheet) throw new Error('表不存在或已被删除。');
    return { store, sheet };
  }

  /**
   * 装配预算化 recall pack；无数据或引擎不可用时返回 null，调用方按“无注入”处理。
   * 表结构段只列会自动注入的表：`manual` 表的行永远不进提示词，列出来只会让模型以为能查到；
   * 被 `sheetGate` 拒掉的表（IF 注入条件不成立）同样整张缺席。
   */
  async recall(request: SqliteRecallRequest): Promise<SqliteRecallResult | null> {
    const store = await this.#openStore();
    if (!store) return null;
    try {
      const gate = request.sheetGate;
      const injectable = (await store.listSheets(request.scopeId))
        .filter((sheet) => sheet.policy !== 'manual' && (!gate || gate(sheet)));
      const allowedIds = new Set(injectable.map((sheet) => sheet.id));
      const keep = (sheetId: string | null): boolean => sheetId !== null && allowedIds.has(sheetId);
      const always = (await store.listAlwaysDocuments(request.scopeId, request.alwaysLimit ?? 200))
        .filter((document) => keep(document.sheetId));
      const search = await store.search(request.scopeId, request.query, request.candidateLimit ?? 20);
      const recallRows = search.rows.filter((row) => keep(row.sheet_id));
      if (injectable.length === 0 && always.length === 0 && recallRows.length === 0) return null;
      const pack = buildRecallPack({
        schema: injectable,
        always: always.map(documentToCandidate),
        recall: recallRows.map((row, index) => searchRowToCandidate(row, index, search.mode)),
        totalTokenBudget: request.totalTokenBudget,
        ...(request.fixedTokenBudget === undefined ? {} : { fixedTokenBudget: request.fixedTokenBudget }),
        ...(request.now === undefined ? {} : { now: request.now }),
        ...(this.#options.tokenCounter ? { tokenCounter: this.#options.tokenCounter } : {}),
      });
      if (!pack.text) return null;
      return { ...pack, searchMode: search.mode, sheetCount: injectable.length };
    } catch (error) {
      this.#report('SQLite 记忆召回失败（本轮跳过注入）', error);
      return null;
    }
  }

  async exportDatabase(): Promise<ExportResult> {
    const store = await this.#requireStore();
    return store.exportDatabase();
  }

  close(): Promise<void> {
    this.#access.invalidate();
    const store = this.#store ?? this.#openingStore;
    const opening = this.#opening;
    const previousClose = this.#closing;
    this.#store = null;
    this.#opening = null;
    this.#openingStore = null;
    this.#availability = { kind: 'idle' };
    this.#unavailableAt = 0;
    const closing = (async () => {
      await previousClose;
      try {
        await store?.close();
        await opening;
      } catch (error) {
        this.#report('关闭 SQLite 记忆引擎失败', error);
      }
    })().finally(() => {
      if (this.#closing === closing) this.#closing = null;
    });
    this.#closing = closing;
    return closing;
  }

  #openStore(): Promise<SqliteMemoryStore | null> {
    if (!this.#access.isEnabled()) return Promise.resolve(null);
    const isCurrent = this.#access.capture();
    if (this.#closing) return this.#closing.then(() => isCurrent() ? this.#openStore() : null);
    if (this.#store) return Promise.resolve(this.#store);
    // 打开失败后短时间内不重复尝试，但也不永久放弃：一次 WASM 冷启动超时或 Worker 抖动
    // 不应该让数据中心整场会话都不可用，用户只能靠关开开关恢复。
    if (this.#availability.kind === 'unavailable' && Date.now() - this.#unavailableAt < REOPEN_RETRY_DELAY_MS) {
      return Promise.resolve(null);
    }
    if (this.#opening) return this.#opening;
    const opening = this.#open(isCurrent).finally(() => {
      if (this.#opening === opening) this.#opening = null;
    });
    this.#opening = opening;
    return opening;
  }

  async #open(isCurrent: () => boolean): Promise<SqliteMemoryStore | null> {
    let store: SqliteMemoryStore | null = null;
    try {
      store = (this.#options.createStore ?? (() => new SqliteMemoryStore()))();
      this.#openingStore = store;
      store.setAccessGuard(() => {
        if (!isCurrent()) throw new DataCenterInactiveError();
      });
      const status = await store.open();
      if (!isCurrent()) {
        await store.close();
        return null;
      }
      this.#store = store;
      this.#availability = { kind: 'ready', status };
      if (status.warning) this.#report(`SQLite 引擎已降级：${status.warning}`);
      return store;
    } catch (error) {
      if (isCurrent()) {
        const reason = errorMessage(error);
        this.#availability = { kind: 'unavailable', reason };
        this.#unavailableAt = Date.now();
        this.#report('SQLite 记忆引擎初始化失败', error);
      }
      if (store) await store.close().catch(() => undefined);
      return null;
    } finally {
      if (this.#openingStore === store) this.#openingStore = null;
    }
  }

  async #requireStore(): Promise<SqliteMemoryStore> {
    const assertCurrent = this.#access.require();
    const store = await this.#openStore();
    assertCurrent();
    if (!store) {
      const reason = this.#availability.kind === 'unavailable' ? this.#availability.reason : '引擎未初始化';
      throw new Error(`SQLite 记忆引擎不可用，写入已中止：${reason}`);
    }
    return store;
  }

  async #projectSheets(
    store: SqliteMemoryStore,
    scopeId: string,
    sheets: readonly SheetRecord[],
  ): Promise<readonly ProjectionSyncReport[]> {
    const reports: ProjectionSyncReport[] = [];
    for (const sheet of sheets) {
      const rows = await store.readAllSheetRows(sheet);
      const documents = rows.flatMap((row): readonly MemoryDocumentProjection[] => {
        try {
          // rowid 当作稳定 row_key：行内容被编辑后 hash 变化，投影按差集收敛而不会重复堆积。
          const rendered = renderRowAsDocument(sheet, { key: Number(row[ROW_ID_ALIAS] ?? 0), values: row });
          return [{
            text: rendered.text,
            hash: rendered.hash,
            sheetId: sheet.id,
            rowKey: rendered.rowKey,
            updatedAt: sheet.updatedAt,
          }];
        } catch (error) {
          this.#report(`表「${sheet.name}」有一行无法渲染成召回文本，已跳过该行`, error);
          return [];
        }
      });
      reports.push(await store.syncDocuments(scopeId, sheetDocumentKind(sheet.id), documents));
    }
    return reports;
  }

  #report(message: string, detail?: unknown): void {
    this.#options.onDiagnostic?.(message, detail);
  }

  /** 写入已提交后，派生投影失败只记诊断；避免调用方重试并重复 INSERT。 */
  async #projectAfterWrite(store: SqliteMemoryStore, scopeId: string, sheets: readonly SheetRecord[]): Promise<readonly ProjectionSyncReport[]> {
    try { return await this.#projectSheets(store, scopeId, sheets); }
    catch (error) { this.#report('表格已保存，召回投影待重建', error); return []; }
  }
}
