import type { PxxProductDraft } from '../domain/commands.js';
import type { StoryFloorSnapshot } from '../integration/sillytavern-bridge.js';

export interface PxxPromptInput {
  readonly userName: string;
  readonly worldBookExcerpt: string | null;
  readonly recentStory: readonly StoryFloorSnapshot[];
  readonly phoneSummaries: readonly string[];
  readonly existingNames: readonly string[];
  readonly count: number;
}

/** 构建 PXX 商品生成提示词：商品必须扎根于世界书与剧情，而不是凭空罗列。 */
export function buildPxxProductPrompt(input: PxxPromptInput): { readonly system: string; readonly user: string } {
  const system = [
    '你是购物平台“PXX”的选品策划，为一位置身于特定故事世界中的用户挑选商品。',
    '商品必须从给定的世界书设定与最近剧情中推导：符合世界观（时代、科技水平、文化），呼应用户的喜好、需求和剧情正在发生的事件。',
    '世界书是商品主题、商品形态、可用技术、货币、文化和表达方式的最高优先级来源；世界书没有允许或支持的商品不要自行补充。',
    '例如剧情提到用户爱吃水果就上架对应的水果，提到角色手机坏了就上架手机；也可以有少量贴合世界观的日常商品，但只能在世界书没有更具体限制时作为兜底。',
    '禁止出现与世界观冲突的商品（如古代世界出现电子产品）。',
    '只输出一个 JSON 数组，不要任何解释、Markdown 代码块或额外文本。',
  ].join('\n');

  const user = JSON.stringify(
    {
      task: `为用户「${input.userName}」生成 ${input.count} 个新商品。`,
      requirements: [
        '每个商品：{"name":"商品名","price":"¥123","description":"80-160字的商品描述，可以带一点购物平台的推销语气，描述中自然体现它与剧情或用户喜好的关联","category":"分类"}',
        '价格用人民币或世界观内合理的货币表示，写成字符串。',
        `不得与已有商品重名或高度雷同：${input.existingNames.length > 0 ? input.existingNames.join('、') : '（当前没有已有商品）'}`,
        '商品之间只需彼此不同且符合世界书；不要为了覆盖多个方向而强行加入世界书没有支持的类别。',
      ],
      ...(input.worldBookExcerpt ? { worldBook: input.worldBookExcerpt } : {}),
      ...(input.recentStory.length > 0
        ? {
            recentStory: input.recentStory.map((floor) => ({
              name: floor.name,
              role: floor.role,
              text: floor.text,
            })),
          }
        : {}),
      ...(input.phoneSummaries.length > 0 ? { phoneSummary: input.phoneSummaries } : {}),
    },
    null,
    2,
  );

  return { system, user };
}

/** 解析模型返回的商品数组；按名称去重（含与已有商品比较）。 */
export function parsePxxProducts(
  raw: string,
  existingNames: readonly string[],
  limit = 12,
): PxxProductDraft[] {
  const jsonText = extractJsonArray(raw);
  if (!jsonText) throw new Error('模型未返回商品 JSON 数组');
  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonText);
  } catch {
    throw new Error('商品 JSON 解析失败');
  }
  if (!Array.isArray(parsed)) throw new Error('商品数据不是数组');

  const known = new Set(existingNames.map((name) => name.trim().toLowerCase()));
  const drafts: PxxProductDraft[] = [];
  for (const item of parsed) {
    if (drafts.length >= limit) break;
    if (!item || typeof item !== 'object') continue;
    const record = item as Record<string, unknown>;
    const name = String(record.name ?? '').trim().slice(0, 60);
    const key = name.toLowerCase();
    if (!name || known.has(key)) continue;
    const priceRaw = record.price;
    const price = typeof priceRaw === 'number'
      ? `¥${priceRaw}`
      : String(priceRaw ?? '').trim().slice(0, 30) || '¥??';
    const description = String(record.description ?? '').trim().slice(0, 1_000) || '暂无描述';
    const category = String(record.category ?? '').trim().slice(0, 20);
    known.add(key);
    drafts.push({ name, price, description, ...(category ? { category } : {}) });
  }
  if (drafts.length === 0) throw new Error('没有解析到有效的新商品');
  return drafts;
}

function extractJsonArray(raw: string): string | null {
  const cleaned = raw.replace(/```(?:json)?/gi, '').trim();
  const start = cleaned.indexOf('[');
  if (start < 0) return null;
  let depth = 0;
  let inString = false;
  let escaped = false;
  for (let index = start; index < cleaned.length; index += 1) {
    const char = cleaned[index];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (char === '\\') {
      if (inString) escaped = true;
      continue;
    }
    if (char === '"') {
      inString = !inString;
      continue;
    }
    if (inString) continue;
    if (char === '[') depth += 1;
    else if (char === ']') {
      depth -= 1;
      if (depth === 0) return cleaned.slice(start, index + 1);
    }
  }
  return null;
}
