import { createConditionContext } from '../conditions/context.js';
import { evaluateConditionBoolean, readConditionPath } from '../conditions/evaluator.js';
import { evaluateConditionGate } from '../conditions/generation.js';
import type { GenerationConditionContext } from '../conditions/generation.js';
import type { ConditionSource } from '../conditions/types.js';
import { SELF_PROFILE_ID } from '../domain/commands.js';
import type { PhoneCommands, MatchedContactInput, PxxProductDraft } from '../domain/commands.js';
import { projectPhoneSummaries } from '../domain/model.js';
import type { AppId, MessageKind, PhoneState, PostKind, Profile } from '../domain/model.js';
import type { GenerationService } from '../generation/generation-service.js';
import type { DynamicWorldBookPipeline } from '../generation/dynamic-worldbook-pipeline.js';
import type { MemoryPipeline } from '../generation/memory-pipeline.js';
import type { OpenAiCompatibleApiConfig, PhoneExtensionSettings } from '../integration/sillytavern-bridge.js';
import {
  compactVariablesForPrompt,
  deleteVariableByPath,
  readVariables,
  replaceVariablesData,
  writeVariableByPath,
} from '../integration/variables-bridge.js';
import type { PhoneStore } from '../storage/phone-store.js';
import type { ModalField } from '../ui/dom.js';
import type {
  ExtensionModuleApiBinding,
  ExtensionModuleFloorContext,
  ExtensionModuleFloorTrigger,
  ExtensionModuleRecord,
} from './module-contract.js';
import { ExtensionModuleStorageService, type ModuleStorageContext } from './module-storage.js';
import {
  EXTENSION_API_CATALOG,
  EXTENSION_HOST_API_VERSION,
  EXTENSION_OUTPUT_CONVENTIONS,
  EXTENSION_PROTOCOLS,
  type ExtensionMessageOptions,
  type ExtensionModuleHostApi,
  type ExtensionModuleReplyRequest,
  type ExtensionPlatformAvatar,
} from './public-api.js';

export interface ExtensionHostApiFactoryOptions {
  readonly record: ExtensionModuleRecord;
  readonly store: PhoneStore;
  readonly commands: PhoneCommands;
  readonly storageContext: ModuleStorageContext;
  readonly getSettings: () => PhoneExtensionSettings;
  readonly conditionContextProvider?: () => GenerationConditionContext | null;
  readonly getApiBinding: () => ExtensionModuleApiBinding;
  readonly updateModuleSettings: (patch: Readonly<Record<string, unknown>>) => Promise<void>;
  readonly generate: (request: {
    readonly system: string;
    readonly user: string;
    readonly temperature?: number;
    readonly maxTokens?: number;
    readonly signal?: AbortSignal;
  }) => Promise<string>;
  readonly buildReplySystemPrompt: (moduleSystem: string) => string;
  readonly generatePxxProducts: (existingNames: readonly string[], count: number) => Promise<readonly PxxProductDraft[]>;
  readonly generateImage: (prompt: string) => Promise<string>;
  readonly worldBookSnapshot: () => Readonly<{ available: boolean; books: readonly string[]; names: readonly string[]; excerpt: string }>;
  readonly memoryPipeline: () => MemoryPipeline | null;
  readonly dynamicWorldBookPipeline: () => DynamicWorldBookPipeline | null;
  readonly dynamicWorldBookOptimize: () => Promise<Awaited<ReturnType<DynamicWorldBookPipeline['optimizeNow']>>>;
  readonly generationService: () => GenerationService | null;
  readonly runQueuedGeneration: () => Promise<Awaited<ReturnType<GenerationService['run']>>>;
  readonly diaryGenerate: () => Promise<{ readonly ok: boolean; readonly message: string }>;
  readonly database: ExtensionModuleHostApi['database'];
  readonly floorLatest: () => number;
  readonly floorRecent: (count?: number) => readonly ExtensionModuleFloorContext[];
  readonly floorTrigger: (
    moduleId: string,
    options: ExtensionModuleFloorTrigger,
    listener: (context: ExtensionModuleFloorContext) => void | Promise<void>,
  ) => () => void;
  readonly notify: (message: string, kind?: 'info' | 'error' | 'success') => void;
  readonly modal: (title: string, fields: readonly ModalField[]) => Promise<Record<string, string> | null>;
}

export function createExtensionModuleHostApi(options: ExtensionHostApiFactoryOptions): ExtensionModuleHostApi {
  const { record, store, commands } = options;
  const storage = new ExtensionModuleStorageService(options.storageContext, record.manifest.id, store.scopeId).create();
  const publicManifest = record.manifest.api?.mode === 'custom'
    ? { ...record.manifest, api: { mode: 'custom' as const } }
    : structuredClone(record.manifest);
  const state = (): PhoneState => store.state;
  const conditionContext = (): GenerationConditionContext =>
    options.conditionContextProvider?.() ?? createConditionContext({ state: state() });
  const conditions = {
    snapshot: () => structuredClone(conditionContext().snapshot),
    evaluate: (condition: ConditionSource): boolean => {
      const result = evaluateConditionBoolean(condition, conditionContext().snapshot);
      return result.ok && result.value === true;
    },
    read: (path: readonly (string | number)[]) => readConditionPath(conditionContext().snapshot, path),
  };
  const snapshot = <T>(value: T): T => structuredClone(value);
  const boundedLimit = (limit: number | undefined, fallback = 100): number => (
    Math.min(500, Math.max(1, Math.floor(limit ?? fallback)))
  );
  const profile = (profileId: string): Profile | null => state().profiles[profileId] ?? null;
  const getAvatar = (profileId: string, platform: ExtensionPlatformAvatar = 'wechat'): string | null => {
    const item = profile(profileId);
    if (!item) return null;
    return platform === 'twitter' ? item.twitterAvatarUrl ?? item.avatarUrl ?? null : item.avatarUrl ?? null;
  };
  const setAvatar = async (
    profileId: string,
    url: string | null,
    platform: ExtensionPlatformAvatar = 'wechat',
  ): Promise<Profile> => {
    const value = normalizeImageUrl(url, '头像');
    return commands.updateProfile(profileId, platform === 'twitter' ? { twitterAvatarUrl: value } : { avatarUrl: value });
  };
  const setBackground = (profileId: string, url: string | null): Promise<Profile> =>
    commands.updateProfile(profileId, { chatBackgroundUrl: normalizeImageUrl(url, '聊天背景') });
  const followedProfileIds = (): readonly string[] => Object.values(state().interactions)
    .filter((item) => item.appId === 'twitter' && item.type === 'follow' && item.actorProfileId === SELF_PROFILE_ID)
    .map((item) => item.targetId);
  const conversations = (appId?: AppId) => Object.values(state().conversations)
    .filter((item) => !appId || item.appId === appId)
    .sort((left, right) => right.updatedAt - left.updatedAt);
  const messages = (filter: { readonly conversationId?: string; readonly appId?: AppId; readonly limit?: number } = {}) => Object.values(state().messages)
    .filter((item) => !filter.conversationId || item.conversationId === filter.conversationId)
    .filter((item) => !filter.appId || item.appId === filter.appId)
    .sort((left, right) => left.createdAt - right.createdAt)
    .slice(-boundedLimit(filter.limit));
  const posts = (filter: { readonly appId?: AppId; readonly kind?: PostKind; readonly parentId?: string; readonly limit?: number } = {}) => Object.values(state().posts)
    .filter((item) => !filter.appId || item.appId === filter.appId)
    .filter((item) => !filter.kind || item.kind === filter.kind)
    .filter((item) => !filter.parentId || item.parentId === filter.parentId || item.targetId === filter.parentId)
    .sort((left, right) => left.createdAt - right.createdAt)
    .slice(-boundedLimit(filter.limit));
  const requireConversation = (conversationId: string, appId: AppId) => {
    const item = state().conversations[conversationId];
    if (!item || item.appId !== appId) throw new Error(`${appLabel(appId)}会话不存在。`);
    return item;
  };
  const listAppProfiles = (appId: AppId): Profile[] => {
    const ids = new Set(conversations(appId).flatMap((item) => item.participantIds));
    for (const item of posts({ appId, limit: 500 })) ids.add(item.profileId);
    return [...ids]
      .map((id) => state().profiles[id])
      .filter((item): item is Profile => item !== undefined)
      .sort((left, right) => left.displayName.localeCompare(right.displayName, 'zh-CN'));
  };
  const createPost = (
    appId: 'wechat' | 'forum' | 'twitter',
    kind: PostKind,
    content: string,
    postOptions: { readonly parentId?: string; readonly targetId?: string; readonly title?: string } = {},
  ) => {
    assertPostKind(appId, kind);
    return commands.createUserPost(appId, kind, content, postOptions);
  };
  const generate = options.generate;

  return {
    meta: {
      apiVersion: EXTENSION_HOST_API_VERSION,
      trusted: true,
      catalog: () => snapshot(EXTENSION_API_CATALOG),
      protocols: () => snapshot(EXTENSION_PROTOCOLS),
      outputConventions: () => snapshot(EXTENSION_OUTPUT_CONVENTIONS),
    },
    module: {
      id: record.manifest.id,
      manifest: publicManifest,
      settings: snapshot(record.settings),
      updateSettings: options.updateModuleSettings,
    },
    state: { scopeId: store.scopeId, snapshot: () => snapshot(state()) },
    conditions,
    time: {
      now: () => state().worldClock.now,
      date: () => new Date(state().worldClock.now),
      format: (formatOptions, locale = 'zh-CN') => new Intl.DateTimeFormat(
        locale,
        formatOptions ?? { dateStyle: 'medium', timeStyle: 'short' },
      ).format(state().worldClock.now),
      set: (timestamp, reason = 'extension-module') => commands.setWorldTime(timestamp, 'user', reason),
    },
    generation: {
      generate,
      reply: async (request: ExtensionModuleReplyRequest) => {
        const normalized = normalizeModuleReplyMessages(request);
        const system = normalized
          .filter((message) => message.role === 'system')
          .map((message) => message.content)
          .join('\n\n') || '请根据对话上下文生成自然、连贯的下一条回复。';
        const user = normalized
          .filter((message) => message.role !== 'system')
          .map((message) => `${message.role === 'assistant' ? 'Assistant' : 'User'}：${message.content}`)
          .join('\n');
        return generate({
          system: options.buildReplySystemPrompt(system),
          user: `以下是按时间排序的最近 ${normalized.length} 条消息。请只输出下一条回复正文。\n\n${user}`,
          ...(request.temperature !== undefined ? { temperature: request.temperature } : {}),
          ...(request.maxTokens !== undefined ? { maxTokens: request.maxTokens } : {}),
          ...(request.signal ? { signal: request.signal } : {}),
        });
      },
      generateJson: async <T>(request: {
        readonly system: string;
        readonly user: string;
        readonly validate?: (value: unknown) => value is T;
        readonly temperature?: number;
        readonly maxTokens?: number;
        readonly signal?: AbortSignal;
      }) => {
        const raw = await generate(request);
        let parsed: unknown;
        try {
          parsed = JSON.parse(raw.replace(/^```json\s*|\s*```$/g, '').trim());
        } catch {
          throw new Error('模块生成结果不是有效 JSON。');
        }
        if (request.validate && !request.validate(parsed)) throw new Error('模块生成结果未通过校验。');
        return parsed as T;
      },
      runQueued: () => options.runQueuedGeneration(),
      cancel: () => options.generationService()?.cancel(),
      isRunning: () => options.generationService()?.isRunning ?? false,
      subscribe: (listener) => options.generationService()?.subscribe(listener) ?? (() => undefined),
    },
    apps: {
      list: () => ['wechat', 'forum', 'anonymous', 'twitter'],
      snapshot: (appId) => {
        const selectedConversations = conversations(appId);
        const selectedMessages = messages({ appId, limit: 500 });
        const selectedPosts = posts({ appId, limit: 500 });
        const ids = new Set(selectedConversations.flatMap((item) => item.participantIds));
        selectedMessages.forEach((item) => ids.add(item.profileId));
        selectedPosts.forEach((item) => ids.add(item.profileId));
        const selectedProfiles = [...ids]
          .map((id) => state().profiles[id])
          .filter((item): item is Profile => item !== undefined);
        return snapshot({
          appId,
          profiles: selectedProfiles,
          conversations: selectedConversations,
          messages: selectedMessages,
          posts: selectedPosts,
        });
      },
    },
    profiles: {
      list: () => snapshot(Object.values(state().profiles).sort((left, right) => left.displayName.localeCompare(right.displayName, 'zh-CN'))),
      get: (profileId) => snapshot(profile(profileId)),
      update: async (profileId, patch) => snapshot(await commands.updateProfile(profileId, patch)),
      getAvatar,
      setAvatar,
      selfId: SELF_PROFILE_ID,
      self: () => snapshot(profile(SELF_PROFILE_ID)),
      ensureSelf: async (displayName, bio) => snapshot(await commands.ensureSelfProfile(displayName, bio)),
      upsertMatched: async (input: MatchedContactInput) => snapshot(await commands.upsertMatchedContact(input)),
      images: (profileId) => {
        const item = profile(profileId);
        if (!item) return null;
        return {
          avatarUrl: item.avatarUrl ?? null,
          twitterAvatarUrl: item.twitterAvatarUrl ?? null,
          chatBackgroundUrl: item.chatBackgroundUrl ?? null,
          imageRefUrl: item.imageRefUrl ?? null,
          imageRefStrength: item.imageRefStrength ?? null,
          avatarPrompt: item.avatarPrompt ?? null,
          appearancePrompt: item.appearancePrompt ?? null,
        };
      },
      setBackground: async (profileId, url) => snapshot(await setBackground(profileId, url)),
      getAlias: (profileId, appId) => profile(profileId)?.aliases[appId] ?? null,
    },
    conversations: {
      list: (listOptions = {}) => snapshot(conversations(listOptions.appId)),
      get: (conversationId) => snapshot(state().conversations[conversationId] ?? null),
      create: async (input) => snapshot(await commands.createConversation(input)),
      addParticipants: async (conversationId, profileIds) => snapshot(await commands.addConversationParticipants(conversationId, profileIds)),
      delete: (conversationId) => commands.deleteConversation(conversationId),
      markRead: (conversationId) => commands.markConversationRead(conversationId),
      unread: () => snapshot(conversations().filter((item) => item.unreadCount > 0)),
    },
    queue: {
      list: () => snapshot(Object.values(state().outbox).sort((left, right) => left.createdAt - right.createdAt)),
      pending: (filter = {}) => snapshot(Object.values(state().outbox)
        .filter((item) => item.status !== 'completed')
        .filter((item) => !filter.appId || item.appId === filter.appId)
        .sort((left, right) => left.createdAt - right.createdAt)),
      batches: () => snapshot(Object.values(state().batches).sort((left, right) => left.createdAt - right.createdAt)),
    },
    messages: {
      list: (filter = {}) => snapshot(messages(filter)),
      get: (messageId) => snapshot(state().messages[messageId] ?? null),
      send: async (conversationId, content, messageOptions) => snapshot(await commands.queueMessage(conversationId, content, messageOptions)),
      deleteQueued: (messageId) => commands.deleteQueuedMessage(messageId),
      rollback: (messageId) => commands.rollbackMessage(messageId),
    },
    posts: {
      list: (filter = {}) => snapshot(posts(filter)),
      get: (postId) => snapshot(state().posts[postId] ?? null),
      create: async (appId, kind, content, postOptions) => snapshot(await createPost(appId, kind, content, postOptions)),
      delete: (postId) => commands.deleteUnansweredUserPost(postId),
    },
    interactions: {
      list: (filter = {}) => snapshot(Object.values(state().interactions)
        .filter((item) => !filter.appId || item.appId === filter.appId)
        .filter((item) => !filter.targetId || item.targetId === filter.targetId)
        .filter((item) => !filter.type || item.type === filter.type)
        .sort((left, right) => left.createdAt - right.createdAt)),
      like: async (appId, targetId) => snapshot(await commands.createUserInteraction(appId, 'like', targetId)),
      comment: async (appId, targetId, content) => snapshot(await commands.createUserInteraction(appId, 'comment', targetId, content)),
    },
    wechat: {
      getProfile: (profileId) => snapshot(profile(profileId)),
      getAvatar: (profileId) => getAvatar(profileId, 'wechat'),
      setAvatar: (profileId, url) => setAvatar(profileId, url, 'wechat'),
      updateContact: async (profileId, patch) => snapshot(await commands.updateProfile(profileId, patch)),
      addContact: async (input) => snapshot(await commands.addContact(input)),
      deleteContacts: (profileIds) => commands.deleteWechatContacts(profileIds),
      profiles: () => snapshot(listAppProfiles('wechat')),
      conversations: () => snapshot(conversations('wechat')),
      messages: (conversationId, limit) => {
        requireConversation(conversationId, 'wechat');
        return snapshot(messages({ conversationId, limit }));
      },
      send: async (conversationId, content, messageOptions) => {
        requireConversation(conversationId, 'wechat');
        return snapshot(await commands.queueMessage(conversationId, content, messageOptions));
      },
      moments: (limit) => snapshot(posts({ appId: 'wechat', kind: 'moment', limit })),
      share: async (request) => {
        if (request.conversationId) {
          requireConversation(request.conversationId, 'wechat');
          return snapshot(await commands.queueMessage(request.conversationId, request.content, {
            ...(request.kind ? { kind: request.kind } : {}),
            ...(request.metadata ? { metadata: request.metadata } : {}),
          }));
        }
        return snapshot(await createPost('wechat', 'moment', request.content));
      },
      like: async (postId) => snapshot(await commands.createUserInteraction('wechat', 'like', postId)),
      comment: async (postId, content) => snapshot(await commands.createUserInteraction('wechat', 'comment', postId, content)),
      getNickname: (profileId) => {
        const item = profile(profileId);
        return item ? item.aliases.wechat ?? item.displayName : null;
      },
      setRemark: async (profileId, remark) => snapshot(await commands.updateProfile(profileId, { displayName: remark })),
      getBackground: (profileId) => profile(profileId)?.chatBackgroundUrl ?? null,
      setBackground: async (profileId, url) => snapshot(await setBackground(profileId, url)),
      markRead: (conversationId) => {
        requireConversation(conversationId, 'wechat');
        return commands.markConversationRead(conversationId);
      },
      createGroup: async (title, profileIds) => snapshot(await commands.createConversation({
        appId: 'wechat',
        kind: 'group',
        title,
        participantIds: profileIds,
      })),
      sendMedia: async (conversationId, kind, content, metadata) => {
        requireConversation(conversationId, 'wechat');
        return snapshot(await commands.queueMessage(conversationId, content, {
          kind,
          ...(metadata ? { metadata } : {}),
        }));
      },
    },
    twitter: {
      getProfile: (profileId) => snapshot(profile(profileId)),
      getAvatar: (profileId) => getAvatar(profileId, 'twitter'),
      setAvatar: (profileId, url) => setAvatar(profileId, url, 'twitter'),
      updateContact: async (profileId, patch) => snapshot(await commands.updateProfile(profileId, patch)),
      addContact: async (handle, displayName = '') => snapshot(await commands.addTwitterContact(handle, displayName)),
      conversations: () => snapshot(conversations('twitter')),
      messages: (conversationId, limit) => {
        requireConversation(conversationId, 'twitter');
        return snapshot(messages({ conversationId, limit }));
      },
      send: async (conversationId, content, messageOptions) => {
        requireConversation(conversationId, 'twitter');
        return snapshot(await commands.queueMessage(conversationId, content, messageOptions));
      },
      posts: (limit) => snapshot(posts({ appId: 'twitter', limit })),
      createPost: async (content) => snapshot(await createPost('twitter', 'twitter-post', content)),
      reply: async (targetId, content) => snapshot(await createPost('twitter', 'twitter-reply', content, { parentId: targetId })),
      repost: async (targetId, content = '转发') => snapshot(await createPost('twitter', 'twitter-repost', content || '转发', { targetId })),
      follow: (profileId, followed) => commands.setTwitterFollow(profileId, followed),
      like: async (postId) => snapshot(await commands.createUserInteraction('twitter', 'like', postId)),
      comment: async (postId, content) => snapshot(await commands.createUserInteraction('twitter', 'comment', postId, content)),
      createAmbient: async (drafts) => snapshot(await commands.createAmbientPosts('twitter', drafts)),
      getName: (profileId) => {
        const item = profile(profileId);
        return item ? item.twitterName ?? item.displayName : null;
      },
      setName: async (profileId, name) => snapshot(await commands.updateProfile(profileId, { twitterName: name })),
      getHandle: (profileId) => profile(profileId)?.aliases.twitter ?? null,
      setHandle: async (profileId, handle) => snapshot(await commands.updateProfile(profileId, { twitterHandle: handle })),
      getBio: (profileId) => profile(profileId)?.twitterBio ?? null,
      setBio: async (profileId, bio) => snapshot(await commands.updateProfile(profileId, { twitterBio: bio })),
      following: () => {
        const ids = new Set(followedProfileIds());
        return snapshot(Object.values(state().profiles)
          .filter((item) => ids.has(item.id))
          .sort((left, right) => left.displayName.localeCompare(right.displayName, 'zh-CN')));
      },
    },
    forum: {
      threads: (limit) => snapshot(posts({ appId: 'forum', kind: 'forum-thread', limit })),
      replies: (threadId, limit) => snapshot(posts({ appId: 'forum', kind: 'forum-reply', parentId: threadId, limit })),
      createThread: async (title, content) => snapshot(await createPost('forum', 'forum-thread', content, { title })),
      reply: async (threadId, content) => snapshot(await createPost('forum', 'forum-reply', content, { parentId: threadId })),
      like: async (postId) => snapshot(await commands.createUserInteraction('forum', 'like', postId)),
      comment: async (postId, content) => snapshot(await commands.createUserInteraction('forum', 'comment', postId, content)),
      createAmbient: async (drafts) => snapshot(await commands.createAmbientPosts('forum', drafts)),
    },
    anonymous: {
      conversations: () => snapshot(conversations('anonymous')),
      profiles: () => snapshot(listAppProfiles('anonymous')),
      messages: (conversationId, limit) => {
        requireConversation(conversationId, 'anonymous');
        return snapshot(messages({ conversationId, limit }));
      },
      createMatch: async (alias) => snapshot(await commands.createAnonymousMatch(alias)),
      send: async (conversationId, content) => {
        requireConversation(conversationId, 'anonymous');
        return snapshot(await commands.queueMessage(conversationId, content));
      },
      close: (conversationId, type) => commands.closeAnonymousMatch(conversationId, type),
    },
    calendar: {
      list: () => snapshot(Object.values(state().calendarFestivals ?? {}).sort((left, right) => left.date.localeCompare(right.date))),
      get: (date) => snapshot((state().calendarFestivals ?? {})[date] ?? null),
      upsert: async (date, name, description = '') => snapshot(await commands.upsertCalendarFestival(date, name, description)),
      remove: (date) => commands.removeCalendarFestival(date),
    },
    diary: {
      list: () => snapshot([...(state().diaryEntries ?? [])].sort((left, right) => left.date.localeCompare(right.date))),
      get: (entryId) => snapshot((state().diaryEntries ?? []).find((item) => item.id === entryId) ?? null),
      generate: options.diaryGenerate,
      remove: (entryId) => commands.removeDiaryEntry(entryId),
      record: async (input) => snapshot(await commands.recordDiaryEntry(input)),
      setBaseline: (coveredUntil) => commands.setDiaryBaseline(coveredUntil),
    },
    pxx: {
      list: () => snapshot(state().pxxProducts ?? []),
      add: async (drafts) => snapshot(await commands.addPxxProducts(drafts)),
      generate: async (generateOptions = {}) => {
        const existingNames = (state().pxxProducts ?? []).map((item) => item.name);
        const count = Math.min(20, Math.max(1, Math.floor(generateOptions.count ?? 10)));
        return snapshot(await options.generatePxxProducts(existingNames, count));
      },
    },
    image: { generate: options.generateImage },
    worldBook: { snapshot: () => snapshot(options.worldBookSnapshot()) },
    dynamicWorldBook: {
      snapshot: () => snapshot(state().dynamicWorldBook),
      optimize: options.dynamicWorldBookOptimize,
      edit: (entryKey, content) => options.dynamicWorldBookPipeline()?.editEntry(entryKey, content)
        ?? Promise.resolve({ ok: false, message: '动态世界书管线未就绪。' }),
      restore: (entryKey) => options.dynamicWorldBookPipeline()?.restoreEntry(entryKey)
        ?? Promise.resolve({ ok: false, message: '动态世界书管线未就绪。' }),
      clear: () => options.dynamicWorldBookPipeline()?.clear()
        ?? Promise.resolve({ ok: false, message: '动态世界书管线未就绪。' }),
      invalidateFromFloor: (fromFloor) => commands.invalidateDynamicWorldBook(fromFloor),
    },
    summaries: {
      // 手机总结现在统一存放在记忆库；这里按创建时间投影成旧 PhoneSummary 形状保持兼容。
      list: () => snapshot([...projectPhoneSummaries(state())].sort((left, right) => left.createdAt - right.createdAt)),
      record: async (content, coveredUntil, sourceCount) => snapshot(await commands.recordSummary(content, coveredUntil, sourceCount)),
    },
    timeline: {
      list: () => snapshot([...state().timelineEvents].sort((left, right) => left.seq - right.seq)),
      record: async (drafts) => snapshot(await commands.recordTimelineEvents(drafts)),
      remove: (eventId) => commands.removeTimelineEvent(eventId),
    },
    memory: {
      list: (filter = {}) => snapshot((state().memoryItems ?? [])
        .filter((item) => filter.includeArchived || !item.archived)
        .filter((item) => !filter.kind || item.kind === filter.kind)
        .slice(-boundedLimit(filter.limit))),
      get: (idOrSeq) => snapshot((state().memoryItems ?? []).find((item) => (
        typeof idOrSeq === 'number' ? item.seq === idOrSeq : item.id === idOrSeq
      )) ?? null),
      search: async (query) => snapshot(await (options.memoryPipeline()?.testSearch(query) ?? Promise.resolve([]))),
      memorize: () => options.memoryPipeline()?.memorize(true) ?? Promise.resolve({ ok: false, message: '记忆管线未就绪。' }),
      consolidate: () => options.memoryPipeline()?.consolidateNow() ?? Promise.resolve({ ok: false, message: '记忆管线未就绪。' }),
      update: (itemId, content) => options.memoryPipeline()?.updateItemContent(itemId, content) ?? Promise.resolve({ ok: false, message: '记忆管线未就绪。' }),
      regenerate: (itemId) => options.memoryPipeline()?.regenerateItem(itemId) ?? Promise.resolve({ ok: false, message: '记忆管线未就绪。' }),
      invalidateFromFloor: (fromFloor) => options.memoryPipeline()?.invalidateFromFloor(fromFloor)
        ?? Promise.resolve({ removedMemoryCount: 0, removedTimelineCount: 0, resumeAfterFloor: -1 }),
      record: async (input) => snapshot(await commands.recordMemoryItem(input)),
      remove: (itemId) => commands.removeMemoryItem(itemId),
      removeMany: (itemIds) => commands.removeMemoryItems(itemIds),
      setContent: async (itemId, content) => snapshot(await commands.updateMemoryItemContent(itemId, content)),
      setBaseline: (floor) => commands.setMemoryBaseline(floor),
    },
    vector: {
      search: async (query) => snapshot(await (options.memoryPipeline()?.testSearch(query) ?? Promise.resolve([]))),
      rebuild: () => options.memoryPipeline()?.rebuildIndex() ?? Promise.resolve({ ok: false, message: '向量管线未就绪。' }),
      status: () => options.memoryPipeline()?.indexStatus() ?? Promise.resolve({ indexed: 0, total: 0 }),
    },
    variables: {
      read: async (readOptions = {}) => {
        const variableSnapshot = await readVariables(readOptions.scope ?? 'message', readOptions.messageId ?? null);
        const result = !readOptions.compact || !variableSnapshot.available
          ? variableSnapshot
          : { ...variableSnapshot, data: compactVariablesForPrompt(variableSnapshot.data) ?? {} };
        return snapshot(result);
      },
      update: async (path, value, variableOptions = {}) => {
        const scope = variableOptions.scope ?? 'message';
        const variableSnapshot = await readVariables(scope, variableOptions.messageId ?? null);
        return writeVariableByPath(scope, variableSnapshot.messageId, variablePath(path), value);
      },
      remove: async (path, variableOptions = {}) => {
        const scope = variableOptions.scope ?? 'message';
        const variableSnapshot = await readVariables(scope, variableOptions.messageId ?? null);
        return deleteVariableByPath(scope, variableSnapshot.messageId, variablePath(path));
      },
      replace: async (data, variableOptions = {}) => {
        const scope = variableOptions.scope ?? 'message';
        const variableSnapshot = await readVariables(scope, variableOptions.messageId ?? null);
        return replaceVariablesData(scope, variableSnapshot.messageId, structuredClone(data));
      },
    },
    database: options.database,
    floors: {
      latest: options.floorLatest,
      recent: (count) => snapshot(options.floorRecent(count)),
      onTrigger: (triggerOptions, listener) => options.floorTrigger(record.manifest.id, triggerOptions, listener),
    },
    notify: options.notify,
    modal: options.modal,
    storage,
    api: {
      get binding() {
        return snapshot(options.getApiBinding());
      },
      get profiles() {
        return options.getSettings().apiProfiles.map(({ name, model, baseUrl }) => ({ name, model, baseUrl }));
      },
    },
  };
}

function normalizeImageUrl(value: string | null, label: string): string {
  const url = String(value ?? '').trim();
  if (!url) return '';
  if (url.startsWith('data:image/') || /^https:\/\/[^\s]+$/i.test(url)) return url;
  throw new Error(`${label}必须是 https 地址或 data:image/*。`);
}

function variablePath(path: string): readonly string[] {
  const segments = path.split('.').map((item) => item.trim()).filter(Boolean);
  if (segments.length === 0) throw new Error('变量路径为空。');
  return segments;
}

function assertPostKind(appId: 'wechat' | 'forum' | 'twitter', kind: PostKind): void {
  const allowed: Readonly<Record<typeof appId, readonly PostKind[]>> = {
    wechat: ['moment'],
    forum: ['forum-thread', 'forum-reply'],
    twitter: ['twitter-post', 'twitter-reply', 'twitter-repost'],
  };
  if (!allowed[appId].includes(kind)) throw new Error(`${appLabel(appId)}不支持帖子类型 ${kind}。`);
}

function appLabel(appId: AppId): string {
  if (appId === 'wechat') return '微信';
  if (appId === 'twitter') return 'Twitter';
  if (appId === 'forum') return '论坛';
  return '匿名交友';
}

function normalizeModuleReplyMessages(request: ExtensionModuleReplyRequest): ExtensionModuleReplyRequest['messages'] {
  if (!Array.isArray(request.messages) || request.messages.length === 0) throw new Error('reply.messages 不能为空。');
  const waitFor = Math.min(40, Math.max(1, Math.floor(request.waitFor ?? 20)));
  return request.messages
    .map((message) => ({ role: message.role, content: String(message.content ?? '').trim() }))
    .filter((message) => message.content && ['system', 'user', 'assistant'].includes(message.role))
    .slice(-waitFor);
}

export type ExtensionGenerationBridge = Pick<GenerationService, 'generateFreeform'>;
export type ExtensionApiConfig = OpenAiCompatibleApiConfig;
export type ExtensionMessageInput = ExtensionMessageOptions;
