/**
 * 模型输出的 JSON 提取与字段读取：同人引擎的解析层共用，绝不 eval，也不抛出解析细节。
 *
 * 真实模型的返回极少是标准 JSON，这里统一吸收以下破损：
 * - Markdown 代码围栏、JSON 前后的解说文字；
 * - 字符串里的裸换行与控制字符、`//` 行注释与块注释、对象/数组的尾随逗号；
 * - 输出被 token 上限截断：丢掉末尾没写完的条目后补齐括号，保住已经写完的部分；
 * - 字段形态摇摆：该给数组时给了字符串、该给数组时给了以名字为键的对象。
 */

/** 截断修复的最大回退次数：每次退到上一个安全分隔点重新扫描。 */
const MAX_REPAIR_ATTEMPTS = 16;
/** 候选起点数量：推理模型常在正文里先写一段带括号的思路，再给出真正的 JSON。 */
const MAX_OBJECT_STARTS = 12;

interface JsonScan {
  /** 从起点开始的候选文本：闭合完整时只到闭合括号，否则为剩余全文。 */
  readonly text: string;
  readonly complete: boolean;
  /** 仍未闭合的 `{` / `[` 栈。 */
  readonly open: readonly string[];
  /** 未闭合字符串的起始下标；-1 表示没有。 */
  readonly unterminatedStringAt: number;
  /** 最后一个字符串外逗号的下标；-1 表示没有。 */
  readonly lastSeparator: number;
}

/** 提取第一个闭合完整的 JSON 对象文本；截断内容返回 null（不做修复）。 */
export function extractJsonObject(raw: string): string | null {
  const text = stripModelWrappers(raw);
  for (const start of valueStarts(text, '{')) {
    const scan = scanJson(sanitizeJson(text.slice(start)));
    if (scan.complete && isRecord(parseJsonText(scan.text))) return scan.text;
  }
  return null;
}

/** 解析模型返回的 JSON 对象；先按完整 JSON 解析，失败后启用截断修复。 */
export function parseJsonObject(raw: string): Record<string, unknown> | null {
  const value = parseJsonValue(raw);
  return isRecord(value) ? value : null;
}

/**
 * 解析模型返回的 JSON 值：对象优先，找不到对象时接受顶层数组。
 * 模型经常省掉外层对象，直接给出人物数组或规则数组，由调用方决定怎么归类。
 */
export function parseJsonValue(raw: string): Record<string, unknown> | readonly unknown[] | null {
  const text = stripModelWrappers(raw);
  // 顶层第一个字符就是 `[`：模型省掉了外层对象，整份结果就是一个数组。
  if (text.startsWith('[')) {
    const root = parseFromStart(text, 0);
    if (isUsableArray(root)) return root;
  }
  for (const start of valueStarts(text, '{')) {
    const value = parseFromStart(text, start);
    if (isRecord(value)) return value;
  }
  // 兜底：解说文字之后才给出数组，且全文没有任何可用对象。
  for (const start of valueStarts(text, '[')) {
    const value = parseFromStart(text, start);
    if (isUsableArray(value)) return value;
  }
  return null;
}

/** 从某个起点解析：优先完整 JSON，其次截断修复；两者都拿不到可用值时返回 undefined。 */
function parseFromStart(text: string, start: number): unknown {
  const body = sanitizeJson(text.slice(start));
  const scan = scanJson(body);
  if (scan.complete) {
    const exact = parseJsonText(scan.text);
    if (isRecord(exact) || isUsableArray(exact)) return exact;
  }
  const repaired = parseRepairedJson(body);
  if (isRecord(repaired) && Object.keys(repaired).length > 0) return repaired;
  return isUsableArray(repaired) ? repaired : undefined;
}

/** 可用数组：至少含一个对象或一条非空字符串，避免把正文里的 `[1]` 当成结果。 */
function isUsableArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value)
    && value.some((item) => isRecord(item) || (typeof item === 'string' && item.trim() !== ''));
}

/**
 * 有些模型会把结果再包一层（result / data / 单键包装）。
 * 只要顶层没有任何预期字段，就向下钻一层找出真正的载荷。
 */
export function unwrapJsonPayload(
  value: Record<string, unknown>,
  expectedKeys: readonly string[],
): Record<string, unknown> {
  if (expectedKeys.some((key) => key in value)) return value;
  for (const key of ['result', 'data', 'output', 'json', 'response', 'payload', 'content']) {
    const nested = value[key];
    if (isRecord(nested)) return nested;
  }
  const entries = Object.entries(value);
  const only = entries.length === 1 ? entries[0] : undefined;
  return only && isRecord(only[1]) ? only[1] : value;
}

/** 按候选键名依次取值：模型可能用英文、下划线或中文键名。 */
export function pickValue(record: Record<string, unknown>, keys: readonly string[]): unknown {
  for (const key of keys) {
    const value = record[key];
    if (value !== undefined && value !== null && value !== '') return value;
  }
  return undefined;
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

export function readText(value: unknown, limit = 400): string {
  const raw = typeof value === 'string'
    ? value
    : typeof value === 'number' || typeof value === 'boolean'
      ? String(value)
      : '';
  return raw
    .replace(/<[^>]{1,500}>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, limit);
}

export function readTextList(value: unknown, limit = 12, charLimit = 200): readonly string[] {
  if (!Array.isArray(value)) return [];
  return dedupeTexts(value.map((item) => readText(item, charLimit)), limit);
}

/**
 * 读取可能被写成字符串、对象或嵌套数组的文本列表。
 * 字符串按换行、分号与列表符号拆条；超过单条上限的长句再按句末标点切分，避免直接截掉后半段。
 */
export function readFlexibleTextList(value: unknown, limit = 12, charLimit = 200): readonly string[] {
  const flattened = flattenTexts(value, 0);
  const pieces: string[] = [];
  for (const piece of flattened) {
    if (pieces.length >= limit * 4) break;
    pieces.push(...packSentences(piece, charLimit));
  }
  return dedupeTexts(pieces.map((piece) => readText(piece, charLimit)), limit);
}

export function readRecordList(value: unknown, limit = 24): readonly Record<string, unknown>[] {
  if (!Array.isArray(value)) return [];
  return value.filter(isRecord).slice(0, limit);
}

export interface FlexibleRecordOptions {
  /** 数组里出现纯字符串时，把它写进这个字段。 */
  readonly textKey?: string;
  /** 载荷是「名字 → 内容」的字典时，把键写进这个字段。 */
  readonly keyField?: string;
  /** 「名字 → 内容」字典里内容不是对象时，把内容写进这个字段（默认与 textKey 相同）。 */
  readonly keyValueKey?: string;
  /** 判定单个对象而非对象字典的特征键。 */
  readonly itemKeys?: readonly string[];
}

/** 读取可能被写成对象、字典或混合数组的记录列表。 */
export function readFlexibleRecordList(
  value: unknown,
  limit = 24,
  options: FlexibleRecordOptions = {},
): readonly Record<string, unknown>[] {
  const items = Array.isArray(value)
    ? value
    : isRecord(value)
      ? expandRecordDictionary(value, options)
      : [];
  const records: Record<string, unknown>[] = [];
  for (const item of items) {
    if (records.length >= limit) break;
    if (isRecord(item)) {
      records.push(item);
      continue;
    }
    const text = readText(item, 400);
    if (text && options.textKey) records.push({ [options.textKey]: text });
  }
  return records;
}

export function readBoolean(value: unknown): boolean {
  return value === true || value === 'true' || value === 1 || value === '1'
    || value === '是' || value === 'yes' || value === 'Y';
}

export function readFloor(value: unknown, fallback = -1): number {
  const numeric = Number(value);
  return Number.isFinite(numeric) ? Math.floor(numeric) : fallback;
}

function expandRecordDictionary(
  value: Record<string, unknown>,
  options: FlexibleRecordOptions,
): readonly unknown[] {
  const keyField = options.keyField;
  const itemKeys = options.itemKeys ?? [];
  const looksLikeItem = !keyField || itemKeys.some((key) => key in value);
  if (looksLikeItem) return [value];
  const valueKey = options.keyValueKey ?? options.textKey;
  return Object.entries(value).map(([key, nested]) => (
    isRecord(nested)
      ? { [keyField]: key, ...nested }
      : { [keyField]: key, ...(valueKey ? { [valueKey]: nested } : {}) }
  ));
}

const TEXT_KEYS = ['text', 'value', 'summary', 'description', 'content', 'name', 'label', 'title', '内容', '描述'];

function flattenTexts(value: unknown, depth: number): readonly string[] {
  if (value === null || value === undefined) return [];
  if (typeof value === 'string') return splitTextEntries(value);
  if (typeof value === 'number' || typeof value === 'boolean') return [String(value)];
  if (depth >= 4) return [];
  if (Array.isArray(value)) return value.flatMap((item) => flattenTexts(item, depth + 1));
  if (!isRecord(value)) return [];
  const preferred = TEXT_KEYS.map((key) => value[key]).find((entry) => typeof entry === 'string' && entry.trim());
  if (typeof preferred === 'string') return splitTextEntries(preferred);
  const joined = Object.values(value)
    .filter((entry): entry is string | number => typeof entry === 'string' || typeof entry === 'number')
    .map((entry) => String(entry).trim())
    .filter(Boolean)
    .join('：');
  return joined ? [joined] : [];
}

/** 按换行与分号拆条，并去掉「- 」「1. 」「• 」这类列表符号。 */
function splitTextEntries(value: string): readonly string[] {
  return value
    .split(/[\n\r;；]+/)
    .map((line) => line.replace(/^\s*(?:[-*•·—]|\d{1,3}[.、)]|\(\d{1,3}\))\s*/, '').trim())
    .filter(Boolean);
}

/** 把超长文本按句末标点打包成不超过上限的多条，尽量不丢内容。 */
function packSentences(value: string, charLimit: number): readonly string[] {
  const text = value.trim();
  if (text.length <= charLimit) return text ? [text] : [];
  const sentences = text.split(/(?<=[。！？!?…；;])/);
  const packed: string[] = [];
  let current = '';
  for (const sentence of sentences) {
    for (const piece of hardSplit(sentence, charLimit)) {
      if (current && current.length + piece.length > charLimit) {
        packed.push(current);
        current = '';
      }
      current += piece;
    }
  }
  if (current.trim()) packed.push(current);
  return packed.map((piece) => piece.trim()).filter(Boolean);
}

function hardSplit(value: string, charLimit: number): readonly string[] {
  if (value.length <= charLimit) return [value];
  const pieces: string[] = [];
  for (let index = 0; index < value.length; index += charLimit) {
    pieces.push(value.slice(index, index + charLimit));
  }
  return pieces;
}

function dedupeTexts(values: readonly string[], limit: number): readonly string[] {
  const seen = new Set<string>();
  const list: string[] = [];
  for (const value of values) {
    const text = value.trim();
    if (!text || seen.has(text)) continue;
    seen.add(text);
    list.push(text);
    if (list.length >= limit) break;
  }
  return list;
}

/**
 * 去掉 JSON 外面的模型包装：Markdown 代码围栏，以及推理模型的思考块。
 * 思考块里常有花括号，留着会让候选起点全被无效片段占满。
 */
function stripModelWrappers(raw: string): string {
  return raw
    .replace(/<(think|thinking|reasoning|thought)\b[^>]*>[\s\S]*?<\/\1>/gi, ' ')
    .replace(/```[a-zA-Z0-9_-]*/g, ' ')
    .replace(/```/g, ' ')
    .trim();
}

/** 候选起点：按出现顺序返回指定起始符的下标。 */
function valueStarts(text: string, opener: '{' | '[', limit = MAX_OBJECT_STARTS): readonly number[] {
  const starts: number[] = [];
  for (let index = text.indexOf(opener); index >= 0 && starts.length < limit; index = text.indexOf(opener, index + 1)) {
    starts.push(index);
  }
  return starts;
}

function parseJsonText(text: string): unknown {
  if (!text.trim()) return undefined;
  try {
    return JSON.parse(text) as unknown;
  } catch {
    return undefined;
  }
}

/** 截断修复：补齐括号；仍失败则退到上一个逗号分隔点再试，直到拿到可用前缀。 */
function parseRepairedJson(body: string): unknown {
  let candidate = body;
  for (let attempt = 0; attempt < MAX_REPAIR_ATTEMPTS; attempt += 1) {
    const scan = scanJson(candidate);
    const value = parseJsonText(scan.complete ? scan.text : closeOpenStructures(scan));
    if (value !== undefined) return value;
    if (scan.lastSeparator < 0) return undefined;
    candidate = candidate.slice(0, scan.lastSeparator);
  }
  return undefined;
}

function closeOpenStructures(scan: JsonScan): string {
  const cut = scan.unterminatedStringAt >= 0 ? scan.text.slice(0, scan.unterminatedStringAt) : scan.text;
  const trimmed = cut.replace(/[\s,:]+$/, '');
  if (!trimmed) return '';
  const closers = scan.open
    .map((character) => (character === '{' ? '}' : ']'))
    .reverse()
    .join('');
  return trimmed + closers;
}

/** 单次线性扫描：记录闭合状态、未闭合字符串位置与最后一个可回退的逗号。 */
function scanJson(text: string): JsonScan {
  const open: string[] = [];
  let quoted = false;
  let escaped = false;
  let stringStart = -1;
  let lastSeparator = -1;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index]!;
    if (quoted) {
      if (escaped) escaped = false;
      else if (character === '\\') escaped = true;
      else if (character === '"') {
        quoted = false;
        stringStart = -1;
      }
      continue;
    }
    if (character === '"') {
      quoted = true;
      stringStart = index;
      continue;
    }
    if (character === '{' || character === '[') {
      open.push(character);
      continue;
    }
    if (character === '}' || character === ']') {
      open.pop();
      if (open.length === 0) {
        return { text: text.slice(0, index + 1), complete: true, open: [], unterminatedStringAt: -1, lastSeparator };
      }
      continue;
    }
    if (character === ',' && open.length > 0) lastSeparator = index;
  }
  return { text, complete: false, open, unterminatedStringAt: quoted ? stringStart : -1, lastSeparator };
}

/**
 * 预处理：转义字符串里的裸换行与控制字符、去掉注释与尾随逗号。
 * 字符串内部的内容一律保留，注释与逗号判断都只在字符串外生效。
 */
function sanitizeJson(text: string): string {
  let out = '';
  let quoted = false;
  let escaped = false;
  for (let index = 0; index < text.length; index += 1) {
    const character = text[index]!;
    if (quoted) {
      if (escaped) {
        out += character;
        escaped = false;
        continue;
      }
      if (character === '\\') {
        out += character;
        escaped = true;
        continue;
      }
      if (character === '"') {
        out += character;
        quoted = false;
        continue;
      }
      if (character === '\n') {
        out += '\\n';
        continue;
      }
      if (character === '\r') {
        out += '\\r';
        continue;
      }
      if (character === '\t') {
        out += '\\t';
        continue;
      }
      if (character < ' ') continue;
      out += character;
      continue;
    }
    if (character === '"') {
      out += character;
      quoted = true;
      continue;
    }
    if (character === '/' && (text[index + 1] === '/' || text[index + 1] === '*')) {
      index = skipComment(text, index);
      continue;
    }
    if (character === ',') {
      const next = nextMeaningfulCharacter(text, index + 1);
      if (next === '}' || next === ']') continue;
      out += character;
      continue;
    }
    out += character;
  }
  return out;
}

/** 返回注释结束处的下标（供 for 循环自增后跳过）。 */
function skipComment(text: string, index: number): number {
  if (text[index + 1] === '/') {
    const end = text.indexOf('\n', index + 2);
    return end < 0 ? text.length : end - 1;
  }
  const end = text.indexOf('*/', index + 2);
  return end < 0 ? text.length : end + 1;
}

function nextMeaningfulCharacter(text: string, from: number): string {
  let index = from;
  while (index < text.length) {
    const character = text[index]!;
    if (character === '/' && (text[index + 1] === '/' || text[index + 1] === '*')) {
      index = skipComment(text, index) + 1;
      continue;
    }
    if (!/\s/.test(character)) return character;
    index += 1;
  }
  return '';
}
