import { button, element } from '../../ui/dom.js';
import { renderPhoneIcon } from '../../ui/phone-icon.js';
import type { PhoneAppDefinition, PhoneViewContext } from '../app-types.js';
import type { VectorIndexStats } from '../../generation/memory-pipeline.js';
import {
  settingsApiProfileRows,
  settingsNumberRow,
  settingsSelectRow,
  settingsToggleRow,
} from '../shared-settings.js';
import { applyVectorProfile } from '../../integration/sillytavern-bridge.js';

/** 向量库：配置向量化与重排序模型，生成前检索记忆库并把相关记忆注入提示词。 */
export function createVectorApp(): PhoneAppDefinition {
  return {
    id: 'vector',
    label: '向量库',
    icon: '向',
    navigation: [],
    render(context) {
      const page = element('div', { className: 'phone-page phone-vector' });
      const header = element('div', { className: 'phone-vector-header' });
      header.append(element('h2', { className: 'phone-section-title', text: '向量库' }));
      page.append(header);

      const settings = context.vector.settings;
      if (!settings.enabled) {
        const intro = element('div', { className: 'phone-feature-intro' });
        intro.append(
          renderPhoneIcon('vector'),
          element('strong', { text: '启用向量库' }),
          element('p', { text: '与记忆库互通：配置向量化模型（和可选的重排序模型）后，记忆 / 总结 / 手机总结会被向量化建立索引；在记忆库底部打开「向量召回」，每轮生成前就按相似度取出最相关的几条注入给 AI——楼层再高也不会失忆。' }),
          element('p', { className: 'phone-feature-intro-note', text: '向量化端点为 OpenAI 兼容 /embeddings；重排序端点为 Jina/Cohere 兼容 /rerank，留空则只按向量相似度排序。' }),
        );
        page.append(intro);
      }

      page.append(settingsToggleRow(
        '启用向量库',
        '启用后自动补齐向量索引；召回时机由记忆库底部的「向量召回」开关决定。',
        settings.enabled,
        (checked) => {
          void context.vector.updateSettings({ enabled: checked }).catch((error: unknown) => {
            context.showNotice(error instanceof Error ? error.message : String(error), 'error');
          });
        },
      ));

      // 向量化模型：复用设置中的 API 配置库；当前生效的模型统一在下方数据面板呈现。
      page.append(element('h3', { className: 'phone-feature-subtitle', text: '向量化模型（/embeddings）' }));
      for (const row of settingsApiProfileRows(context.vector.apiProfiles, settings.embedding, (profile) => {
        void context.vector.updateSettings({ embedding: applyVectorProfile(profile) }).catch((error: unknown) => {
          context.showNotice(error instanceof Error ? error.message : String(error), 'error');
        });
      }, { showCurrent: false })) {
        page.append(row);
      }

      // 重排序模型：可选，未选择时只按向量相似度排序。
      page.append(element('h3', { className: 'phone-feature-subtitle', text: '重排序模型（/rerank，可选）' }));
      page.append(element('p', { className: 'phone-settings-hint', text: '可复用同一个 API 配置库中的模型；留空则不执行重排序。端点留空时沿用向量化模型的 Base URL。' }));
      for (const row of settingsApiProfileRows(context.vector.apiProfiles, settings.rerank, (profile) => {
        void context.vector.updateSettings({ rerank: applyVectorProfile(profile) }).catch((error: unknown) => {
          context.showNotice(error instanceof Error ? error.message : String(error), 'error');
        });
      }, { showCurrent: false })) {
        page.append(row);
      }

      page.append(renderRecallParams(context));
      page.append(renderRerankParams(context));

      if (settings.enabled) {
        page.append(renderIndexCard(context));
        page.append(renderTestCard(context));
      }
      return page;
    },
  };
}

/** 召回参数：候选数、阈值、截断与批量都直接进入检索流程，没有摆设旋钮。 */
function renderRecallParams(context: PhoneViewContext): HTMLElement {
  const settings = context.vector.settings;
  const update = (patch: Parameters<PhoneViewContext['vector']['updateSettings']>[0]): void => {
    void context.vector.updateSettings(patch).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
  };
  const section = element('section', { className: 'phone-vector-params' });
  section.append(element('h3', { className: 'phone-feature-subtitle', text: '召回参数' }));
  section.append(settingsSelectRow(
    '注入记忆条数',
    [['2', '2 条'], ['3', '3 条'], ['4', '4 条'], ['6', '6 条'], ['8', '8 条'], ['10', '10 条']],
    String(settings.topK),
    (value) => update({ topK: Number(value) || 4 }),
  ));
  section.append(settingsNumberRow(
    '候选数（重排序前）',
    settings.candidateLimit,
    1,
    200,
    1,
    (value) => update({ candidateLimit: value ?? 12 }),
  ));
  section.append(element('p', {
    className: 'phone-settings-hint',
    text: `先按向量相似度取 ${settings.candidateLimit} 条候选，再由重排序模型精排出注入条数；候选越多越准也越慢。`,
  }));
  section.append(settingsNumberRow(
    '相似度下限',
    settings.minScore,
    0,
    1,
    0.05,
    (value) => update({ minScore: value ?? 0 }),
  ));
  section.append(element('p', {
    className: 'phone-settings-hint',
    text: '余弦相似度低于该值的记忆直接丢掉；0 = 不过滤。记忆总量少时建议保持 0，否则可能一条都召不回。',
  }));
  section.append(settingsNumberRow(
    '查询截断（字符）',
    settings.queryChars,
    200,
    20_000,
    100,
    (value) => update({ queryChars: value ?? 2_000 }),
  ));
  section.append(settingsNumberRow(
    '单条记忆截断（字符）',
    settings.documentChars,
    200,
    20_000,
    100,
    (value) => update({ documentChars: value ?? 3_000 }),
  ));
  section.append(element('p', {
    className: 'phone-settings-hint',
    text: '改动截断长度会改变向量内容，已建好的索引需要重建后才与新设置一致。',
  }));
  section.append(settingsNumberRow(
    '单次向量化条数',
    settings.embedBatchSize,
    1,
    256,
    1,
    (value) => update({ embedBatchSize: value ?? 64 }),
  ));
  section.append(settingsToggleRow(
    '自动补齐索引',
    '启用向量库、切换聊天或换向量化模型后，后台自动把未索引的记忆向量化。',
    settings.autoIndex,
    (checked) => update({ autoIndex: checked }),
  ));
  return section;
}

/** 重排序参数：开关、返回条数与分数下限。 */
function renderRerankParams(context: PhoneViewContext): HTMLElement {
  const settings = context.vector.settings;
  const update = (patch: Parameters<PhoneViewContext['vector']['updateSettings']>[0]): void => {
    void context.vector.updateSettings(patch).catch((error: unknown) => {
      context.showNotice(error instanceof Error ? error.message : String(error), 'error');
    });
  };
  const section = element('section', { className: 'phone-vector-params' });
  section.append(element('h3', { className: 'phone-feature-subtitle', text: '重排序参数' }));
  section.append(settingsToggleRow(
    '启用重排序',
    '关闭后即使配了重排序模型也只按向量相似度排序。',
    settings.rerankEnabled,
    (checked) => update({ rerankEnabled: checked }),
  ));
  section.append(settingsNumberRow(
    '重排序返回条数',
    settings.rerankTopN,
    0,
    50,
    1,
    (value) => update({ rerankTopN: value ?? 0 }),
  ));
  section.append(element('p', {
    className: 'phone-settings-hint',
    text: `0 = 跟随注入记忆条数（当前 ${settings.topK} 条）。`,
  }));
  section.append(settingsNumberRow(
    '重排序分数下限',
    settings.rerankMinScore,
    0,
    1,
    0.05,
    (value) => update({ rerankMinScore: value ?? 0 }),
  ));
  section.append(element('p', {
    className: 'phone-settings-hint',
    text: '低于该相关度的重排结果丢掉；若全部被滤掉，本轮回退到向量相似度顺序，不会空注入。',
  }));
  return section;
}

/** 覆盖率条：indexed / total 的可视化。 */
function renderMeter(indexed: number, total: number): HTMLElement {
  const ratio = total > 0 ? Math.min(1, indexed / total) : 0;
  const meter = element('div', {
    className: 'phone-vector-meter',
    attributes: {
      role: 'progressbar',
      'aria-valuemin': '0',
      'aria-valuemax': String(total),
      'aria-valuenow': String(indexed),
    },
  });
  const fill = element('span', { className: 'phone-vector-meter-fill' });
  fill.style.width = `${Math.round(ratio * 100)}%`;
  meter.append(fill);
  return meter;
}

function renderMetric(label: string, value: string): HTMLElement {
  const cell = element('div', { className: 'phone-vector-metric' });
  cell.append(
    element('span', { className: 'phone-vector-metric-label', text: label }),
    element('strong', { className: 'phone-vector-metric-value', text: value }),
  );
  return cell;
}

/** 索引数据面板：总覆盖率 + 按来源分组 + 向量维度与生效模型 + 补齐/重建入口。 */
function renderIndexCard(context: PhoneViewContext): HTMLElement {
  const card = element('section', { className: 'phone-vector-card' });
  const head = element('div', { className: 'phone-vector-card-head' });
  head.append(element('strong', { text: '索引数据' }));
  const actions = element('div', { className: 'phone-vector-card-actions' });
  const body = element('div', { className: 'phone-vector-panel' });

  const renderStats = (stats: VectorIndexStats): void => {
    body.replaceChildren();
    if (!stats.model) {
      body.append(element('p', { className: 'phone-vector-status', text: '尚未配置向量化模型，无法建立索引。' }));
      return;
    }
    if (stats.total === 0) {
      body.append(element('p', { className: 'phone-vector-status', text: '记忆库暂无内容；先到记忆库整理摘要或总结手机内容。' }));
      return;
    }
    const percent = Math.round((stats.indexed / stats.total) * 100);
    body.append(
      element('p', {
        className: 'phone-vector-status',
        text: `已向量化 ${stats.indexed} / ${stats.total} 条（${percent}%）；缺失部分会在召回时按批补齐。`,
      }),
      renderMeter(stats.indexed, stats.total),
    );

    const groups = element('div', { className: 'phone-vector-groups' });
    for (const group of stats.groups) {
      const row = element('div', { className: 'phone-vector-group' });
      row.append(
        element('span', { className: 'phone-vector-group-label', text: group.label }),
        renderMeter(group.indexed, group.total),
        element('small', { className: 'phone-vector-group-count', text: `${group.indexed}/${group.total}` }),
      );
      groups.append(row);
    }
    body.append(groups);

    const metrics = element('div', { className: 'phone-vector-grid' });
    metrics.append(
      renderMetric('向量化模型', stats.model),
      renderMetric('向量维度', stats.dimensions > 0 ? String(stats.dimensions) : '待建立'),
      renderMetric('重排序', stats.rerankActive ? stats.rerankModel : (stats.rerankModel ? '已配置但已关闭' : '未配置')),
      renderMetric('召回条数', `${context.vector.settings.topK} / 候选 ${context.vector.settings.candidateLimit}`),
    );
    body.append(metrics);
  };

  const refreshStatus = async (): Promise<void> => {
    try {
      renderStats(await context.vector.indexStatus());
    } catch (error) {
      body.replaceChildren(element('p', { className: 'phone-vector-status', text: '索引状态读取失败。' }));
      context.showNotice(`索引状态读取失败：${error instanceof Error ? error.message : String(error)}`, 'error');
    }
  };

  const runAction = (
    label: string,
    busyLabel: string,
    action: () => Promise<{ readonly ok: boolean; readonly message: string }>,
  ): HTMLButtonElement => {
    const trigger = button(label, 'phone-button phone-button-secondary phone-button-compact', async () => {
      trigger.disabled = true;
      trigger.textContent = busyLabel;
      try {
        const result = await action();
        context.showNotice(result.message, result.ok ? 'success' : 'error');
        await refreshStatus();
      } catch (error) {
        context.showNotice(error instanceof Error ? error.message : String(error), 'error');
      } finally {
        trigger.disabled = false;
        trigger.textContent = label;
      }
    });
    return trigger;
  };

  actions.append(
    runAction('补齐索引', '向量化中…', () => context.vector.ensureIndex()),
    runAction('重建索引', '重建中…', () => context.vector.rebuildIndex()),
  );
  head.append(actions);
  body.append(element('p', { className: 'phone-vector-status', text: '正在读取索引状态…' }));
  void refreshStatus();
  card.append(head, body);
  return card;
}

/** 检索测试卡片：输入一句话，查看检索与重排结果。 */
function renderTestCard(context: PhoneViewContext): HTMLElement {
  const card = element('section', { className: 'phone-vector-card' });
  card.append(element('strong', { text: '检索测试' }));
  const form = element('form', { className: 'phone-vector-test-form' });
  const input = element('input', {
    className: 'phone-input',
    attributes: { type: 'text', placeholder: '输入下一段剧情的关键词试试…', maxlength: '200' },
  });
  const submit = button('检索', 'phone-button phone-button-primary phone-button-compact');
  form.append(input, submit);
  const results = element('div', { className: 'phone-vector-results' });
  const run = async () => {
    const query = input.value.trim();
    if (!query) return;
    submit.disabled = true;
    submit.textContent = '检索中…';
    results.replaceChildren();
    try {
      const hits = await context.vector.test(query);
      if (hits.length === 0) {
        results.append(element('p', { className: 'phone-vector-status', text: '没有检索到相关记忆。' }));
      }
      for (const hit of hits) {
        const row = element('article', { className: 'phone-vector-hit' });
        const head = element('div', { className: 'phone-vector-hit-head' });
        head.append(
          element('span', { className: 'phone-memory-item-seq', text: `记忆#${hit.seq}` }),
          element('span', { className: 'phone-memory-item-kind', text: hit.kind === 'summary' ? '摘要' : '总结' }),
          element('small', { text: `相关度 ${hit.score.toFixed(3)}` }),
        );
        row.append(head, element('p', { className: 'phone-vector-hit-text', text: hit.content.slice(0, 200) }));
        results.append(row);
      }
    } catch (error) {
      const message = error instanceof Error ? error.message : String(error);
      results.append(element('p', {
        className: 'phone-vector-status',
        text: message,
      }));
      context.showNotice(`向量检索失败：${message}`, 'error');
    } finally {
      submit.disabled = false;
      submit.textContent = '检索';
    }
  };
  form.addEventListener('submit', (event) => {
    event.preventDefault();
    void run();
  });
  submit.addEventListener('click', () => void run());
  card.append(form, results);
  return card;
}