/**
 * 宿主层通知门面：把「一条字符串」式的旧调用桥接到统一通知栈。
 *
 * 新功能请直接使用 phone-task.ts 的任务句柄，以获得「墨韵手机 {操作名}」标题
 * 与进行中/成功/失败三态；这里只服务没有操作上下文的通用提示（例如扩展模块 API）。
 */

import { dismissStackNotice, pushStackNotice, type NoticeKind } from './notice-stack.js';

export type HostNoticeKind = 'info' | 'error' | 'success';

/** 通用提示共用一张卡片，避免同一入口连续提示时堆满屏幕。 */
const NOTICE_KEY = 'phone-notice:general';
/** 旧的「任务提示」通道：常驻显示直到收起或转为终态。 */
const TASK_KEY = 'phone-notice:legacy-task';

const KIND_TITLES: Readonly<Record<HostNoticeKind, string>> = {
  info: '墨韵手机 提示',
  success: '墨韵手机 操作完成',
  error: '墨韵手机 操作失败',
};

/** 旧文案自带「墨韵手机：」前缀，标题已由通知栈统一渲染，这里剥掉避免重复。 */
function stripPrefix(message: string): string {
  return message.trim().replace(/^墨韵手机\s*[：:]\s*/u, '').trim();
}

function emit(key: string, message: string, kind: HostNoticeKind, durationMs: number): void {
  const detail = stripPrefix(message);
  pushStackNotice({
    key,
    title: KIND_TITLES[kind],
    detail,
    kind: kind as NoticeKind,
    durationMs,
  });
}

export function showHostNotice(
  message: string,
  kind: HostNoticeKind = 'info',
  durationMs = 5_000,
): void {
  emit(NOTICE_KEY, message, kind, durationMs);
}

/** 进行中提示：常驻显示，直到 hideHostTaskNotice 或结果提示替换它。 */
export function showHostTaskNotice(message: string): void {
  pushStackNotice({
    key: TASK_KEY,
    title: '墨韵手机 处理中',
    detail: stripPrefix(message),
    kind: 'pending',
    durationMs: 0,
  });
}

/** 结果提示：原地替换同一张进行中卡片，避免闪断成两条。 */
export function showHostTaskResultNotice(
  message: string,
  kind: Extract<HostNoticeKind, 'error' | 'success'>,
  durationMs = 5_000,
): void {
  emit(TASK_KEY, message, kind, durationMs);
}

export function showHostErrorNotice(message: string, durationMs = 8_000): void {
  emit(NOTICE_KEY, message, 'error', durationMs);
}

export function hideHostTaskNotice(): void {
  dismissStackNotice(TASK_KEY);
}

export function hideHostNotice(): void {
  dismissStackNotice(NOTICE_KEY);
}